        private static void RenameOpenHandleRelativeNoReplace(
            SafeFileHandle source,
            SafeFileHandle destinationParent,
            string destinationLeafName,
            string sourceDescription,
            string destinationDescription)
        {
            ValidateLeafName(destinationLeafName, "open_handle_rename_destination");
            char[] destinationName = destinationLeafName.ToCharArray();
            int fileNameLength = checked(destinationName.Length * 2);
            int fileNameOffset = checked((int)Marshal.OffsetOf(
                typeof(FILE_RENAME_INFO_HEADER),
                "FileNameLength") + sizeof(uint));
            int bufferSize = Math.Max(
                Marshal.SizeOf(typeof(FILE_RENAME_INFO_HEADER)),
                checked(fileNameOffset + fileNameLength));
            IntPtr renameBuffer = Marshal.AllocHGlobal(bufferSize);
            bool destinationReferenced = false;
            try
            {
                for (int index = 0; index < bufferSize; index++) Marshal.WriteByte(renameBuffer, index, 0);
                int rootDirectoryOffset = checked((int)Marshal.OffsetOf(
                    typeof(FILE_RENAME_INFO_HEADER),
                    "RootDirectory"));
                int fileNameLengthOffset = checked((int)Marshal.OffsetOf(
                    typeof(FILE_RENAME_INFO_HEADER),
                    "FileNameLength"));
                destinationParent.DangerousAddRef(ref destinationReferenced);
                Marshal.WriteIntPtr(
                    renameBuffer,
                    rootDirectoryOffset,
                    destinationParent.DangerousGetHandle());
                Marshal.WriteInt32(renameBuffer, fileNameLengthOffset, fileNameLength);
                Marshal.Copy(destinationName, 0, IntPtr.Add(renameBuffer, fileNameOffset), destinationName.Length);
                IO_STATUS_BLOCK ioStatus;
                int status = NtSetInformationFile(
                    source,
                    out ioStatus,
                    renameBuffer,
                    (uint)bufferSize,
                    10 /* FileRenameInformation */);
                if (status < 0)
                {
                    int error = unchecked((int)RtlNtStatusToDosError(status));
                    throw new Win32Exception(
                        error,
                        "SYNAPSE_PHYSICAL_OPEN_HANDLE_RENAME_FAILED source=" + sourceDescription +
                        " destination=" + destinationDescription + " replace=false ntstatus=0x" +
                        status.ToString("X8") + " win32=" + error);
                }
            }
            finally
            {
                if (destinationReferenced) destinationParent.DangerousRelease();
                Marshal.FreeHGlobal(renameBuffer);
            }
        }

        public sealed class PhysicalPublicationBridge : IDisposable
        {
            private SafeFileHandle rootHandle;
            private List<IDisposable> held;
            private IntPtr buffer;
            private IntPtr overlapped;
            private IntPtr eventHandle;
            private bool watcherPending;
            private bool detached;
            private string rootFileId128;
            private string currentRootPath;
            private bool watchSubtree;
            private uint watchFilter;

            internal PhysicalPublicationBridge(
                SafeFileHandle openedRoot,
                List<SafeFileHandle> sourcePins,
                string sourcePath,
                string expectedRootFileId128,
                bool subtree,
                uint filter)
            {
                rootHandle = openedRoot;
                rootFileId128 = expectedRootFileId128;
                currentRootPath = NormalizeDirectoryPath(sourcePath);
                watchSubtree = subtree;
                watchFilter = filter;
                held = new List<IDisposable>();
                foreach (SafeFileHandle pin in sourcePins) held.Add(pin);
                held.Add(rootHandle);
                buffer = IntPtr.Zero;
                overlapped = IntPtr.Zero;
                eventHandle = IntPtr.Zero;
                watcherPending = false;
                detached = false;
                ArmWatcher();
                RequireWatcherPending("arm");
            }

            private void ArmWatcher()
            {
                const int bufferLength = 65536;
                buffer = Marshal.AllocHGlobal(bufferLength);
                for (int index = 0; index < bufferLength; index++) Marshal.WriteByte(buffer, index, 0);
                eventHandle = CreateEvent(IntPtr.Zero, true, false, null);
                if (eventHandle == IntPtr.Zero)
                {
                    int error = Marshal.GetLastWin32Error();
                    throw new Win32Exception(
                        error,
                        "SYNAPSE_PROFILE_PUBLICATION_WATCH_EVENT_CREATE_FAILED win32=" + error);
                }
                NATIVE_OVERLAPPED native = new NATIVE_OVERLAPPED
                {
                    Internal = IntPtr.Zero,
                    InternalHigh = IntPtr.Zero,
                    Offset = 0,
                    OffsetHigh = 0,
                    EventHandle = eventHandle
                };
                overlapped = Marshal.AllocHGlobal(Marshal.SizeOf(typeof(NATIVE_OVERLAPPED)));
                Marshal.StructureToPtr(native, overlapped, false);
                if (!ReadDirectoryChangesW(
                    rootHandle,
                    buffer,
                    bufferLength,
                    watchSubtree,
                    watchFilter,
                    IntPtr.Zero,
                    overlapped,
                    IntPtr.Zero))
                {
                    int error = Marshal.GetLastWin32Error();
                    throw new Win32Exception(
                        error,
                        "SYNAPSE_PROFILE_PUBLICATION_WATCH_ARM_FAILED path=" + currentRootPath +
                        " subtree=" + watchSubtree + " filter=0x" + watchFilter.ToString("X") +
                        " win32=" + error);
                }
                watcherPending = true;
            }

            private void RequireWatcherPending(string phase)
            {
                uint bytes;
                bool complete = GetOverlappedResult(rootHandle, overlapped, out bytes, false);
                int error = Marshal.GetLastWin32Error();
                if (complete || error != ERROR_IO_INCOMPLETE)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PROFILE_PUBLICATION_WATCH_DIRTY phase=" + phase +
                        " complete=" + complete + " bytes=" + bytes + " win32=" + error +
                        " overflow=" + (error == ERROR_NOTIFY_ENUM_DIR));
                }
            }

            private void CancelWatcherClean()
            {
                RequireWatcherPending("before_cancel");
                if (!CancelIoEx(rootHandle, overlapped))
                {
                    int cancelError = Marshal.GetLastWin32Error();
                    throw new Win32Exception(
                        cancelError,
                        "SYNAPSE_PROFILE_PUBLICATION_WATCH_CANCEL_FAILED win32=" + cancelError);
                }
                uint bytes;
                bool complete = GetOverlappedResult(rootHandle, overlapped, out bytes, true);
                int error = Marshal.GetLastWin32Error();
                watcherPending = false;
                if (complete || error != ERROR_OPERATION_ABORTED)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PROFILE_PUBLICATION_WATCH_CANCEL_DRAIN_AMBIGUOUS complete=" + complete +
                        " bytes=" + bytes + " win32=" + error);
                }
                FreeWatcherMemory();
            }

            public void RequireCleanCheckpoint(string phase)
            {
                if (String.IsNullOrWhiteSpace(phase)) phase = "external";
                RequireWatcherPending(phase);
            }

            public void CompleteCleanGuard()
            {
                CancelWatcherClean();
            }

            private void FreeWatcherMemory()
            {
                if (overlapped != IntPtr.Zero)
                {
                    Marshal.FreeHGlobal(overlapped);
                    overlapped = IntPtr.Zero;
                }
                if (buffer != IntPtr.Zero)
                {
                    Marshal.FreeHGlobal(buffer);
                    buffer = IntPtr.Zero;
                }
                if (eventHandle != IntPtr.Zero)
                {
                    CloseHandle(eventHandle);
                    eventHandle = IntPtr.Zero;
                }
            }

            public PhysicalGenerationLease PublishAndSeal(
                string destinationParentPath,
                string[] expectedDestinationParentPaths,
                string[] expectedDestinationParentFileIds128,
                string destinationLeafName,
                string[] relativeFilePaths,
                string[] expectedFileIds128,
                string[] expectedSha256,
                long[] expectedLengths)
            {
                if (relativeFilePaths == null || expectedFileIds128 == null ||
                    expectedSha256 == null || expectedLengths == null ||
                    relativeFilePaths.Length != expectedFileIds128.Length ||
                    relativeFilePaths.Length != expectedSha256.Length ||
                    relativeFilePaths.Length != expectedLengths.Length)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PROFILE_PUBLICATION_OWNED_DESCRIPTOR_COUNT_MISMATCH");
                }
                string destinationParentFull = NormalizeDirectoryPath(destinationParentPath);
                string destinationPath = NormalizeDirectoryPath(Path.Combine(
                    destinationParentFull,
                    destinationLeafName));
                List<SafeFileHandle> destinationPins = OpenPinnedPhysicalDirectoryChainV2(
                    destinationParentFull,
                    expectedDestinationParentPaths,
                    expectedDestinationParentFileIds128);
                foreach (SafeFileHandle pin in destinationPins) held.Add(pin);
                RequireWatcherPending("before_root_publish");
                RenameOpenHandleRelativeNoReplace(
                    rootHandle,
                    destinationPins[destinationPins.Count - 1],
                    destinationLeafName,
                    currentRootPath,
                    destinationPath);
                currentRootPath = destinationPath;
                PhysicalDirectoryReadback rootReadback = ReadDirectoryHandle(rootHandle, destinationPath);
                if (!NormalizeDirectoryPath(rootReadback.Path).Equals(destinationPath, StringComparison.OrdinalIgnoreCase) ||
                    !rootReadback.FileId128.Equals(rootFileId128, StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PROFILE_PUBLICATION_ROOT_READBACK_MISMATCH expected_path=" + destinationPath +
                        " actual_path=" + rootReadback.Path + " expected_file_id_128=" + rootFileId128 +
                        " actual_file_id_128=" + rootReadback.FileId128);
                }
                RequireWatcherPending("after_root_publish");

                for (int fileIndex = 0; fileIndex < relativeFilePaths.Length; fileIndex++)
                {
                    string relative = relativeFilePaths[fileIndex].Replace('/', Path.DirectorySeparatorChar);
                    if (Path.IsPathRooted(relative))
                        throw new InvalidOperationException(
                            "SYNAPSE_PROFILE_PUBLICATION_RELATIVE_PATH_ROOTED path=" + relative);
                    string[] segments = relative.Split(Path.DirectorySeparatorChar);
                    SafeFileHandle parent = rootHandle;
                    string currentPath = destinationPath;
                    for (int segmentIndex = 0; segmentIndex < segments.Length - 1; segmentIndex++)
                    {
                        ValidateLeafName(segments[segmentIndex], "publication_seal_directory");
                        currentPath = Path.Combine(currentPath, segments[segmentIndex]);
                        SafeFileHandle directoryHandle = OpenRelativeEntry(
                            parent,
                            segments[segmentIndex],
                            FILE_LIST_DIRECTORY | FILE_READ_ATTRIBUTES,
                            FILE_SHARE_READ | FILE_SHARE_WRITE,
                            NT_FILE_OPEN,
                            true,
                            false);
                        PhysicalDirectoryReadback directoryReadback = ReadDirectoryHandle(
                            directoryHandle,
                            currentPath);
                        if (!NormalizeDirectoryPath(directoryReadback.Path).Equals(
                            NormalizeDirectoryPath(currentPath),
                            StringComparison.OrdinalIgnoreCase))
                        {
                            directoryHandle.Dispose();
                            throw new InvalidOperationException(
                                "SYNAPSE_PROFILE_PUBLICATION_DIRECTORY_READBACK_MISMATCH path=" + currentPath +
                                " actual=" + directoryReadback.Path);
                        }
                        held.Add(directoryHandle);
                        parent = directoryHandle;
                    }
                    string leaf = segments[segments.Length - 1];
                    ValidateLeafName(leaf, "publication_seal_file");
                    string filePath = Path.Combine(currentPath, leaf);
                    SafeFileHandle fileHandle = OpenRelativeEntry(
                        parent,
                        leaf,
                        GENERIC_READ | FILE_READ_ATTRIBUTES,
                        FILE_SHARE_READ,
                        NT_FILE_OPEN,
                        false,
                        false);
                    FILE_ATTRIBUTE_TAG_INFO information = ReadPhysicalAttributes(fileHandle, filePath);
                    BY_HANDLE_FILE_INFORMATION linkInformation;
                    if (!GetFileInformationByHandle(fileHandle, out linkInformation))
                    {
                        int error = Marshal.GetLastWin32Error();
                        fileHandle.Dispose();
                        throw new Win32Exception(
                            error,
                            "SYNAPSE_PROFILE_PUBLICATION_LINK_READ_FAILED path=" + filePath + " win32=" + error);
                    }
                    string finalPath = Path.GetFullPath(ReadFinalPath(fileHandle, filePath));
                    string fileId128 = ReadPhysicalFileId128(fileHandle, filePath);
                    if ((information.FileAttributes & (FILE_ATTRIBUTE_REPARSE_POINT | FILE_ATTRIBUTE_DIRECTORY)) != 0 ||
                        linkInformation.NumberOfLinks != 1 ||
                        !finalPath.Equals(Path.GetFullPath(filePath), StringComparison.OrdinalIgnoreCase) ||
                        !fileId128.Equals(expectedFileIds128[fileIndex], StringComparison.OrdinalIgnoreCase))
                    {
                        fileHandle.Dispose();
                        throw new InvalidOperationException(
                            "SYNAPSE_PROFILE_PUBLICATION_FILE_IDENTITY_MISMATCH path=" + filePath +
                            " final=" + finalPath + " expected_file_id_128=" + expectedFileIds128[fileIndex] +
                            " actual_file_id_128=" + fileId128 + " link_count=" + linkInformation.NumberOfLinks +
                            " attributes=" + information.FileAttributes);
                    }
                    FileStream stream = new FileStream(fileHandle, FileAccess.Read, 65536, false);
                    fileHandle = null;
                    byte[] digest;
                    using (SHA256 sha = SHA256.Create()) digest = sha.ComputeHash(stream);
                    string sha256 = BitConverter.ToString(digest).Replace("-", String.Empty);
                    long length = stream.Length;
                    stream.Position = 0;
                    if (!sha256.Equals(expectedSha256[fileIndex], StringComparison.OrdinalIgnoreCase) ||
                        length != expectedLengths[fileIndex])
                    {
                        stream.Dispose();
                        throw new InvalidOperationException(
                            "SYNAPSE_PROFILE_PUBLICATION_FILE_CONTENT_MISMATCH path=" + filePath +
                            " expected_sha256=" + expectedSha256[fileIndex] + " actual_sha256=" + sha256 +
                            " expected_length=" + expectedLengths[fileIndex] + " actual_length=" + length);
                    }
                    held.Add(stream);
                }

                RequireWatcherPending("after_owned_seal");
                CancelWatcherClean();
                List<IDisposable> leaseHandles = held;
                held = null;
                detached = true;
                return new PhysicalGenerationLease(
                    destinationPath,
                    rootFileId128,
                    relativeFilePaths.Length,
                    leaseHandles);
            }

            public void Dispose()
            {
                if (detached) return;
                if (watcherPending && rootHandle != null && !rootHandle.IsInvalid && overlapped != IntPtr.Zero)
                {
                    try
                    {
                        if (CancelIoEx(rootHandle, overlapped))
                        {
                            uint ignored;
                            GetOverlappedResult(rootHandle, overlapped, out ignored, true);
                        }
                    }
                    catch { }
                    watcherPending = false;
                }
                FreeWatcherMemory();
                if (held != null)
                {
                    for (int index = held.Count - 1; index >= 0; index--) held[index].Dispose();
                    held = null;
                }
                rootHandle = null;
            }
        }

        public sealed class PhysicalFileTransitionLease : IDisposable
        {
            private FileStream stream;
            private List<SafeFileHandle> pins;
            private string currentPath;
            private readonly string fileId128;
            private readonly string sha256;
            private readonly long length;

            internal PhysicalFileTransitionLease(
                FileStream openedStream,
                List<SafeFileHandle> openedPins,
                string openedPath,
                string openedFileId128,
                string openedSha256,
                long openedLength)
            {
                stream = openedStream;
                pins = openedPins;
                currentPath = Path.GetFullPath(openedPath);
                fileId128 = openedFileId128;
                sha256 = openedSha256;
                length = openedLength;
            }

            public string CurrentPath { get { return currentPath; } }
            public string FileId128 { get { return fileId128; } }
            public string Sha256 { get { return sha256; } }
            public long Length { get { return length; } }

            public PhysicalEntryReadback MoveNoReplace(
                string destinationParentPath,
                string[] expectedDestinationParentPaths,
                string[] expectedDestinationParentFileIds128,
                string destinationLeafName)
            {
                if (stream == null) throw new ObjectDisposedException("PhysicalFileTransitionLease");
                string destinationParent = NormalizeDirectoryPath(destinationParentPath);
                string destinationPath = Path.GetFullPath(Path.Combine(destinationParent, destinationLeafName));
                List<SafeFileHandle> destinationPins = OpenPinnedPhysicalDirectoryChainV2(
                    destinationParent,
                    expectedDestinationParentPaths,
                    expectedDestinationParentFileIds128);
                bool retained = false;
                try
                {
                    RequireRegularSingleLinkFile(stream.SafeFileHandle, currentPath, fileId128);
                    RenameOpenHandleRelativeNoReplace(
                        stream.SafeFileHandle,
                        destinationPins[destinationPins.Count - 1],
                        destinationLeafName,
                        currentPath,
                        destinationPath);
                    string actualPath = Path.GetFullPath(ReadFinalPath(stream.SafeFileHandle, destinationPath));
                    string actualId = ReadPhysicalFileId128(stream.SafeFileHandle, destinationPath);
                    RequireRegularSingleLinkFile(stream.SafeFileHandle, destinationPath, fileId128);
                    if (!actualPath.Equals(destinationPath, StringComparison.OrdinalIgnoreCase) ||
                        !actualId.Equals(fileId128, StringComparison.OrdinalIgnoreCase))
                    {
                        throw new InvalidOperationException(
                            "SYNAPSE_PHYSICAL_TRANSITION_MOVE_READBACK_MISMATCH expected_path=" + destinationPath +
                            " actual_path=" + actualPath + " expected_file_id_128=" + fileId128 +
                            " actual_file_id_128=" + actualId);
                    }
                    pins.AddRange(destinationPins);
                    retained = true;
                    currentPath = destinationPath;
                    return new PhysicalEntryReadback
                    {
                        Identity = ReadPhysicalIdentity(stream.SafeFileHandle, destinationPath),
                        FileId128 = actualId,
                        Path = actualPath,
                        IsDirectory = false
                    };
                }
                finally
                {
                    if (!retained) DisposeHandles(destinationPins);
                }
            }

            public void RequireExact(string phase)
            {
                if (stream == null) throw new ObjectDisposedException("PhysicalFileTransitionLease");
                string actualPath = Path.GetFullPath(ReadFinalPath(stream.SafeFileHandle, currentPath));
                string actualId = ReadPhysicalFileId128(stream.SafeFileHandle, currentPath);
                RequireRegularSingleLinkFile(stream.SafeFileHandle, currentPath, fileId128);
                long actualLength;
                string actualSha = ComputeSha256Retained(stream, out actualLength);
                if (!actualPath.Equals(currentPath, StringComparison.OrdinalIgnoreCase) ||
                    !actualId.Equals(fileId128, StringComparison.OrdinalIgnoreCase) ||
                    !actualSha.Equals(sha256, StringComparison.OrdinalIgnoreCase) ||
                    actualLength != length)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_TRANSITION_LEASE_DRIFT phase=" + phase +
                        " expected_path=" + currentPath + " actual_path=" + actualPath +
                        " expected_file_id_128=" + fileId128 + " actual_file_id_128=" + actualId +
                        " expected_sha256=" + sha256 + " actual_sha256=" + actualSha +
                        " expected_length=" + length + " actual_length=" + actualLength);
                }
            }

            public PhysicalTextReadback ReadUtf8(int maximumBytes)
            {
                if (stream == null) throw new ObjectDisposedException("PhysicalFileTransitionLease");
                return ReadUtf8Retained(stream, currentPath, fileId128, maximumBytes);
            }

            public void Dispose()
            {
                FileStream currentStream = stream;
                stream = null;
                if (currentStream != null) currentStream.Dispose();
                List<SafeFileHandle> currentPins = pins;
                pins = null;
                DisposeHandles(currentPins);
            }
        }

        public sealed class PhysicalFileReadLease : IDisposable
        {
            private FileStream stream;
            private List<SafeFileHandle> pins;
            private readonly string path;
            private readonly string fileId128;
            private readonly string sha256;
            private readonly long length;

            internal PhysicalFileReadLease(
                FileStream openedStream,
                List<SafeFileHandle> openedPins,
                string openedPath,
                string openedFileId128,
                string openedSha256,
                long openedLength)
            {
                stream = openedStream;
                pins = openedPins;
                path = Path.GetFullPath(openedPath);
                fileId128 = openedFileId128;
                sha256 = openedSha256;
                length = openedLength;
            }

            public string CurrentPath { get { return path; } }
            public string FileId128 { get { return fileId128; } }
            public string Sha256 { get { return sha256; } }
            public long Length { get { return length; } }

            public void RequireExact(string phase)
            {
                if (stream == null) throw new ObjectDisposedException("PhysicalFileReadLease");
                string actualPath = Path.GetFullPath(ReadFinalPath(stream.SafeFileHandle, path));
                string actualId = ReadPhysicalFileId128(stream.SafeFileHandle, path);
                RequireRegularSingleLinkFile(stream.SafeFileHandle, path, fileId128);
                if (stream.Length != length)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_READ_LEASE_LENGTH_DRIFT phase=" + phase +
                        " path=" + path + " expected_length=" + length +
                        " actual_length=" + stream.Length);
                }
                long actualLength;
                string actualSha = ComputeSha256Retained(stream, out actualLength);
                if (!actualPath.Equals(path, StringComparison.OrdinalIgnoreCase) ||
                    !actualId.Equals(fileId128, StringComparison.OrdinalIgnoreCase) ||
                    !actualSha.Equals(sha256, StringComparison.OrdinalIgnoreCase) ||
                    actualLength != length)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_READ_LEASE_DRIFT phase=" + phase +
                        " expected_path=" + path + " actual_path=" + actualPath +
                        " expected_file_id_128=" + fileId128 + " actual_file_id_128=" + actualId +
                        " expected_sha256=" + sha256 + " actual_sha256=" + actualSha +
                        " expected_length=" + length + " actual_length=" + actualLength);
                }
            }

            public PhysicalTextReadback ReadUtf8(int maximumBytes)
            {
                if (stream == null) throw new ObjectDisposedException("PhysicalFileReadLease");
                return ReadUtf8Retained(stream, path, fileId128, maximumBytes);
            }

            public void Dispose()
            {
                FileStream currentStream = stream;
                stream = null;
                if (currentStream != null) currentStream.Dispose();
                List<SafeFileHandle> currentPins = pins;
                pins = null;
                DisposeHandles(currentPins);
            }
        }

        public sealed class PhysicalAllocatedFile : IDisposable
        {
            private FileStream stream;
            private List<SafeFileHandle> pins;
            private string path;
            private readonly string fileId128;
            private string sealedSha256;
            private long sealedLength;

            internal PhysicalAllocatedFile(
                FileStream openedStream,
                List<SafeFileHandle> openedPins,
                string openedPath,
                string openedFileId128)
            {
                stream = openedStream;
                pins = openedPins;
                path = Path.GetFullPath(openedPath);
                fileId128 = openedFileId128;
                sealedSha256 = String.Empty;
                sealedLength = -1;
            }

            public string PathValue { get { return path; } }
            public string FileId128 { get { return fileId128; } }

            public PhysicalFileReadback FillFromFile(
                string sourcePath,
                string expectedSha256,
                long expectedLength)
            {
                if (stream == null) throw new ObjectDisposedException("PhysicalAllocatedFile");
                if (!String.IsNullOrEmpty(sealedSha256) || sealedLength >= 0 || stream.Length != 0)
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_ALLOCATED_FILE_FILL_NOT_EMPTY path=" + path +
                        " length=" + stream.Length + " already_sealed=" + (!String.IsNullOrEmpty(sealedSha256)));
                RequireRegularSingleLinkFile(stream.SafeFileHandle, path, fileId128);
                using (FileStream source = new FileStream(
                    Path.GetFullPath(sourcePath),
                    FileMode.Open,
                    FileAccess.Read,
                    FileShare.Read,
                    65536,
                    FileOptions.SequentialScan))
                {
                    if (expectedLength < 0 || source.Length != expectedLength)
                        throw new InvalidOperationException(
                            "SYNAPSE_PHYSICAL_ALLOCATED_FILE_SOURCE_PRECOPY_LENGTH_MISMATCH source=" + sourcePath +
                            " destination=" + path + " expected_length=" + expectedLength +
                            " actual_length=" + source.Length);
                    stream.Position = 0;
                    stream.SetLength(0);
                    byte[] buffer = new byte[65536];
                    long copied = 0;
                    while (copied < expectedLength)
                    {
                        int requested = (int)Math.Min((long)buffer.Length, expectedLength - copied);
                        int read = source.Read(buffer, 0, requested);
                        if (read <= 0) throw new EndOfStreamException(
                            "SYNAPSE_PHYSICAL_ALLOCATED_FILE_SOURCE_TRUNCATED source=" + sourcePath +
                            " expected_length=" + expectedLength + " copied=" + copied);
                        stream.Write(buffer, 0, read);
                        copied += read;
                    }
                    if (source.ReadByte() != -1 || source.Length != expectedLength)
                        throw new InvalidOperationException(
                            "SYNAPSE_PHYSICAL_ALLOCATED_FILE_SOURCE_GREW source=" + sourcePath +
                            " expected_length=" + expectedLength + " actual_length=" + source.Length);
                    stream.Flush(true);
                }
                long length;
                string sha = ComputeSha256Retained(stream, out length);
                if (!String.IsNullOrWhiteSpace(expectedSha256) &&
                    !sha.Equals(expectedSha256, StringComparison.OrdinalIgnoreCase))
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_ALLOCATED_FILE_SOURCE_HASH_MISMATCH source=" + sourcePath +
                         " destination=" + path + " expected_sha256=" + expectedSha256 +
                         " actual_sha256=" + sha);
                if (expectedLength < 0 || length != expectedLength)
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_ALLOCATED_FILE_SOURCE_LENGTH_MISMATCH source=" + sourcePath +
                        " destination=" + path + " expected_length=" + expectedLength +
                        " actual_length=" + length);
                sealedSha256 = sha;
                sealedLength = length;
                RequireRegularSingleLinkFile(stream.SafeFileHandle, path, fileId128);
                return new PhysicalFileReadback
                {
                    Length = length,
                    Sha256 = sha,
                    Identity = ReadPhysicalIdentity(stream.SafeFileHandle, path),
                    FileId128 = fileId128
                };
            }

            public PhysicalFileReadback FillUtf8(
                string content,
                string expectedSha256,
                long expectedLength)
            {
                if (stream == null) throw new ObjectDisposedException("PhysicalAllocatedFile");
                if (!String.IsNullOrEmpty(sealedSha256) || sealedLength >= 0 || stream.Length != 0)
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_ALLOCATED_TEXT_FILL_NOT_EMPTY path=" + path +
                        " length=" + stream.Length + " already_sealed=" + (!String.IsNullOrEmpty(sealedSha256)));
                RequireRegularSingleLinkFile(stream.SafeFileHandle, path, fileId128);
                byte[] bytes = new UTF8Encoding(false, true).GetBytes(content);
                stream.Position = 0;
                stream.SetLength(0);
                stream.Write(bytes, 0, bytes.Length);
                stream.Flush(true);
                long length;
                string sha = ComputeSha256Retained(stream, out length);
                if (String.IsNullOrWhiteSpace(expectedSha256) ||
                    !sha.Equals(expectedSha256, StringComparison.OrdinalIgnoreCase) ||
                    expectedLength < 0 || length != expectedLength)
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_ALLOCATED_TEXT_READBACK_MISMATCH path=" + path +
                        " expected_sha256=" + expectedSha256 + " actual_sha256=" + sha +
                        " expected_length=" + expectedLength + " actual_length=" + length);
                sealedSha256 = sha;
                sealedLength = length;
                RequireRegularSingleLinkFile(stream.SafeFileHandle, path, fileId128);
                return new PhysicalFileReadback
                {
                    Length = length,
                    Sha256 = sha,
                    Identity = ReadPhysicalIdentity(stream.SafeFileHandle, path),
                    FileId128 = fileId128
                };
            }

            public PhysicalFileReadback Readback()
            {
                if (stream == null) throw new ObjectDisposedException("PhysicalAllocatedFile");
                RequireRegularSingleLinkFile(stream.SafeFileHandle, path, fileId128);
                long length;
                string sha = ComputeSha256Retained(stream, out length);
                return new PhysicalFileReadback
                {
                    Length = length,
                    Sha256 = sha,
                    Identity = ReadPhysicalIdentity(stream.SafeFileHandle, path),
                    FileId128 = fileId128
                };
            }

            public PhysicalTextReadback ReadUtf8(int maximumBytes)
            {
                if (stream == null) throw new ObjectDisposedException("PhysicalAllocatedFile");
                return ReadUtf8Retained(stream, path, fileId128, maximumBytes);
            }

            public PhysicalEntryReadback MoveNoReplace(
                string destinationParentPath,
                string[] expectedDestinationParentPaths,
                string[] expectedDestinationParentFileIds128,
                string destinationLeafName)
            {
                if (stream == null) throw new ObjectDisposedException("PhysicalAllocatedFile");
                if (String.IsNullOrWhiteSpace(sealedSha256) || sealedLength < 0)
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_ALLOCATED_FILE_NOT_SEALED path=" + path);
                string destinationParent = NormalizeDirectoryPath(destinationParentPath);
                ValidateLeafName(destinationLeafName, "allocated_file_move");
                string destinationPath = Path.GetFullPath(Path.Combine(destinationParent, destinationLeafName));
                List<SafeFileHandle> destinationPins = OpenPinnedPhysicalDirectoryChainV2(
                    destinationParent,
                    expectedDestinationParentPaths,
                    expectedDestinationParentFileIds128);
                bool retained = false;
                try
                {
                    RequireRegularSingleLinkFile(stream.SafeFileHandle, path, fileId128);
                    RenameOpenHandleRelativeNoReplace(
                        stream.SafeFileHandle,
                        destinationPins[destinationPins.Count - 1],
                        destinationLeafName,
                        path,
                        destinationPath);
                    string actualPath = Path.GetFullPath(ReadFinalPath(stream.SafeFileHandle, destinationPath));
                    string actualId = ReadPhysicalFileId128(stream.SafeFileHandle, destinationPath);
                    long actualLength;
                    string actualSha = ComputeSha256Retained(stream, out actualLength);
                    RequireRegularSingleLinkFile(stream.SafeFileHandle, destinationPath, fileId128);
                    if (!actualPath.Equals(destinationPath, StringComparison.OrdinalIgnoreCase) ||
                        !actualId.Equals(fileId128, StringComparison.OrdinalIgnoreCase) ||
                        !actualSha.Equals(sealedSha256, StringComparison.OrdinalIgnoreCase) ||
                        actualLength != sealedLength)
                    {
                        throw new InvalidOperationException(
                            "SYNAPSE_PHYSICAL_ALLOCATED_FILE_MOVE_READBACK_MISMATCH expected_path=" + destinationPath +
                            " actual_path=" + actualPath + " expected_file_id_128=" + fileId128 +
                            " actual_file_id_128=" + actualId + " expected_sha256=" + sealedSha256 +
                            " actual_sha256=" + actualSha + " expected_length=" + sealedLength +
                            " actual_length=" + actualLength);
                    }
                    pins.AddRange(destinationPins);
                    retained = true;
                    path = destinationPath;
                    return new PhysicalEntryReadback
                    {
                        Identity = ReadPhysicalIdentity(stream.SafeFileHandle, destinationPath),
                        FileId128 = actualId,
                        Path = actualPath,
                        IsDirectory = false
                    };
                }
                finally
                {
                    if (!retained) DisposeHandles(destinationPins);
                }
            }

            public void RequireExact(string phase)
            {
                if (stream == null) throw new ObjectDisposedException("PhysicalAllocatedFile");
                if (String.IsNullOrWhiteSpace(sealedSha256) || sealedLength < 0)
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_ALLOCATED_FILE_NOT_SEALED phase=" + phase + " path=" + path);
                string actualPath = Path.GetFullPath(ReadFinalPath(stream.SafeFileHandle, path));
                string actualId = ReadPhysicalFileId128(stream.SafeFileHandle, path);
                RequireRegularSingleLinkFile(stream.SafeFileHandle, path, fileId128);
                long actualLength;
                string actualSha = ComputeSha256Retained(stream, out actualLength);
                if (!actualPath.Equals(path, StringComparison.OrdinalIgnoreCase) ||
                    !actualId.Equals(fileId128, StringComparison.OrdinalIgnoreCase) ||
                    !actualSha.Equals(sealedSha256, StringComparison.OrdinalIgnoreCase) ||
                    actualLength != sealedLength)
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_ALLOCATED_FILE_DRIFT phase=" + phase + " path=" + path +
                        " actual_path=" + actualPath + " expected_file_id_128=" + fileId128 +
                        " actual_file_id_128=" + actualId + " expected_sha256=" + sealedSha256 +
                        " actual_sha256=" + actualSha + " expected_length=" + sealedLength +
                        " actual_length=" + actualLength);
            }

            public void Dispose()
            {
                FileStream currentStream = stream;
                stream = null;
                if (currentStream != null) currentStream.Dispose();
                List<SafeFileHandle> currentPins = pins;
                pins = null;
                DisposeHandles(currentPins);
            }
        }

        public sealed class PhysicalAllocationLog : IDisposable
        {
            private FileStream stream;
            private List<SafeFileHandle> pins;
            private readonly string path;
            private readonly string fileId128;

            internal PhysicalAllocationLog(
                FileStream openedStream,
                List<SafeFileHandle> openedPins,
                string openedPath,
                string openedFileId128)
            {
                stream = openedStream;
                pins = openedPins;
                path = Path.GetFullPath(openedPath);
                fileId128 = openedFileId128;
            }

            public string PathValue { get { return path; } }
            public string FileId128 { get { return fileId128; } }

            public PhysicalFileReadback AppendUtf8Line(string line, long maximumBytes)
            {
                if (stream == null) throw new ObjectDisposedException("PhysicalAllocationLog");
                RequireRegularSingleLinkFile(stream.SafeFileHandle, path, fileId128);
                if (line == null || line.IndexOf('\r') >= 0 || line.IndexOf('\n') >= 0)
                    throw new ArgumentException("SYNAPSE_ALLOCATION_LOG_LINE_INVALID");
                byte[] bytes = new UTF8Encoding(false, true).GetBytes(line + "\n");
                if (maximumBytes < 1 || checked(stream.Length + bytes.Length) > maximumBytes)
                    throw new InvalidOperationException(
                        "SYNAPSE_ALLOCATION_LOG_BOUND_EXCEEDED current=" + stream.Length +
                        " append=" + bytes.Length + " max=" + maximumBytes);
                stream.Position = stream.Length;
                stream.Write(bytes, 0, bytes.Length);
                stream.Flush(true);
                RequireRegularSingleLinkFile(stream.SafeFileHandle, path, fileId128);
                long length;
                string sha = ComputeSha256Retained(stream, out length);
                return new PhysicalFileReadback
                {
                    Length = length,
                    Sha256 = sha,
                    Identity = ReadPhysicalIdentity(stream.SafeFileHandle, path),
                    FileId128 = fileId128
                };
            }

            public PhysicalFileReadback Readback()
            {
                if (stream == null) throw new ObjectDisposedException("PhysicalAllocationLog");
                RequireRegularSingleLinkFile(stream.SafeFileHandle, path, fileId128);
                stream.Flush(true);
                long length;
                string sha = ComputeSha256Retained(stream, out length);
                return new PhysicalFileReadback
                {
                    Length = length,
                    Sha256 = sha,
                    Identity = ReadPhysicalIdentity(stream.SafeFileHandle, path),
                    FileId128 = fileId128
                };
            }

            public PhysicalTextReadback ReadUtf8(int maximumBytes)
            {
                if (stream == null) throw new ObjectDisposedException("PhysicalAllocationLog");
                return ReadUtf8Retained(stream, path, fileId128, maximumBytes);
            }

            public void Dispose()
            {
                FileStream currentStream = stream;
                stream = null;
                if (currentStream != null) currentStream.Dispose();
                List<SafeFileHandle> currentPins = pins;
                pins = null;
                DisposeHandles(currentPins);
            }
        }

        public static void ReplaceWriteThrough(string sourcePath, string destinationPath)
        {
            if (String.IsNullOrWhiteSpace(sourcePath) || String.IsNullOrWhiteSpace(destinationPath))
            {
                throw new ArgumentException(
                    "SYNAPSE_ATOMIC_FILE_PATH_INVALID remediation=provide exact non-empty source and destination paths");
            }
            if (!MoveFileEx(
                sourcePath,
                destinationPath,
                MOVEFILE_REPLACE_EXISTING | MOVEFILE_WRITE_THROUGH))
            {
                int error = Marshal.GetLastWin32Error();
                throw new Win32Exception(
                    error,
                    "SYNAPSE_ATOMIC_FILE_REPLACE_FAILED win32=" + error +
                    " remediation=repair filesystem permissions/durability support; no non-atomic fallback is permitted");
            }
        }

        public static void InstallNewWriteThrough(string sourcePath, string destinationPath)
        {
            if (String.IsNullOrWhiteSpace(sourcePath) || String.IsNullOrWhiteSpace(destinationPath))
            {
                throw new ArgumentException(
                    "SYNAPSE_ATOMIC_FILE_PATH_INVALID remediation=provide exact non-empty source and destination paths");
            }
            if (!MoveFileEx(sourcePath, destinationPath, MOVEFILE_WRITE_THROUGH))
            {
                int error = Marshal.GetLastWin32Error();
                throw new Win32Exception(
                    error,
                    "SYNAPSE_ATOMIC_FILE_INSTALL_NEW_FAILED win32=" + error +
                    " remediation=the content-addressed destination must be absent; no replace/fallback is permitted");
            }
        }

        private static SafeFileHandle OpenPhysicalHandle(string path, uint access)
        {
            return OpenPhysicalHandleWithShare(
                path,
                access,
                FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE);
        }

        private static SafeFileHandle OpenPhysicalHandleWithShare(
            string path,
            uint access,
            uint shareMode)
        {
            SafeFileHandle handle = CreateFile(
                path,
                access,
                shareMode,
                IntPtr.Zero,
                OPEN_EXISTING,
                FILE_FLAG_BACKUP_SEMANTICS | FILE_FLAG_OPEN_REPARSE_POINT,
                IntPtr.Zero);
            if (handle.IsInvalid)
            {
                int error = Marshal.GetLastWin32Error();
                handle.Dispose();
                throw new Win32Exception(
                    error,
                    "SYNAPSE_PHYSICAL_HANDLE_OPEN_FAILED path=" + path + " win32=" + error);
            }
            return handle;
        }

        private static SafeFileHandle OpenPinnedPhysicalDirectory(string path)
        {
            SafeFileHandle handle = CreateFile(
                path,
                FILE_LIST_DIRECTORY | FILE_READ_ATTRIBUTES,
                FILE_SHARE_READ | FILE_SHARE_WRITE,
                IntPtr.Zero,
                OPEN_EXISTING,
                FILE_FLAG_BACKUP_SEMANTICS | FILE_FLAG_OPEN_REPARSE_POINT,
                IntPtr.Zero);
            if (handle.IsInvalid)
            {
                int error = Marshal.GetLastWin32Error();
                handle.Dispose();
                throw new Win32Exception(
                    error,
                    "SYNAPSE_PHYSICAL_DIRECTORY_PIN_FAILED path=" + path + " win32=" + error);
            }
            return handle;
        }

        private static string NormalizeDirectoryPath(string path)
        {
            string full = Path.GetFullPath(path);
            string pathRoot = Path.GetPathRoot(full);
            if (full.Equals(pathRoot, StringComparison.OrdinalIgnoreCase)) return pathRoot;
            return full.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
        }

        private static List<SafeFileHandle> OpenPinnedPhysicalDirectoryChain(
            string directoryPath,
            string expectedDirectoryIdentity)
        {
            string directoryFull = NormalizeDirectoryPath(directoryPath);
            List<string> paths = new List<string>();
            DirectoryInfo cursor = new DirectoryInfo(directoryFull);
            while (cursor != null)
            {
                paths.Add(NormalizeDirectoryPath(cursor.FullName));
                cursor = cursor.Parent;
            }
            paths.Reverse();

            List<SafeFileHandle> handles = new List<SafeFileHandle>();
            try
            {
                for (int index = 0; index < paths.Count; index++)
                {
                    string path = paths[index];
                    SafeFileHandle handle = index == 0
                        ? OpenPinnedPhysicalDirectory(path)
                        : OpenRelativeEntry(
                            handles[index - 1],
                            Path.GetFileName(path),
                            FILE_LIST_DIRECTORY | FILE_READ_ATTRIBUTES,
                            FILE_SHARE_READ | FILE_SHARE_WRITE,
                            NT_FILE_OPEN,
                            true,
                            false);
                    handles.Add(handle);
                    FILE_ATTRIBUTE_TAG_INFO information = ReadPhysicalAttributes(handle, path);
                    if ((information.FileAttributes & FILE_ATTRIBUTE_REPARSE_POINT) != 0 ||
                        (information.FileAttributes & FILE_ATTRIBUTE_DIRECTORY) == 0)
                    {
                        throw new InvalidOperationException(
                            "SYNAPSE_PHYSICAL_DIRECTORY_CHAIN_INVALID path=" + path +
                            " attributes=" + information.FileAttributes);
                    }
                    string finalPath = NormalizeDirectoryPath(ReadFinalPath(handle, path));
                    if (!finalPath.Equals(path, StringComparison.OrdinalIgnoreCase))
                    {
                        throw new InvalidOperationException(
                            "SYNAPSE_PHYSICAL_DIRECTORY_CHAIN_FINAL_PATH_MISMATCH path=" + path +
                            " actual_final=" + finalPath);
                    }
                }
                string actualIdentity = ReadIdentityInExpectedProjection(
                    handles[handles.Count - 1],
                    directoryFull,
                    expectedDirectoryIdentity);
                if (String.IsNullOrWhiteSpace(expectedDirectoryIdentity) ||
                    !actualIdentity.Equals(expectedDirectoryIdentity, StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_DIRECTORY_CHAIN_IDENTITY_MISMATCH path=" + directoryFull +
                        " expected_identity=" + expectedDirectoryIdentity +
                        " actual_identity=" + actualIdentity);
                }
                return handles;
            }
            catch
            {
                for (int index = handles.Count - 1; index >= 0; index--) handles[index].Dispose();
                throw;
            }
        }

        private static void DisposeHandles(List<SafeFileHandle> handles)
        {
            if (handles == null) return;
            for (int index = handles.Count - 1; index >= 0; index--) handles[index].Dispose();
        }

        private static FILE_ATTRIBUTE_TAG_INFO ReadPhysicalAttributes(SafeFileHandle handle, string path)
        {
            FILE_ATTRIBUTE_TAG_INFO information;
            if (!GetFileInformationByHandleEx(
                handle,
                FILE_ATTRIBUTE_TAG_INFO_CLASS,
                out information,
                (uint)Marshal.SizeOf(typeof(FILE_ATTRIBUTE_TAG_INFO))))
            {
                int error = Marshal.GetLastWin32Error();
                throw new Win32Exception(
                    error,
                    "SYNAPSE_PHYSICAL_HANDLE_ATTRIBUTE_READ_FAILED path=" + path + " win32=" + error);
            }
            return information;
        }

        private static void RequireNoNamedDataStreams(SafeFileHandle handle, string path)
        {
            const int headerSize = 24;
            int size = 4096;
            while (size <= 1048576)
            {
                IntPtr buffer = Marshal.AllocHGlobal(size);
                try
                {
                    for (int index = 0; index < size; index++) Marshal.WriteByte(buffer, index, 0);
                    if (!GetDirectoryInformationByHandleEx(
                        handle,
                        FILE_STREAM_INFO_CLASS,
                        buffer,
                        (uint)size))
                    {
                        int error = Marshal.GetLastWin32Error();
                        if (error == ERROR_MORE_DATA)
                        {
                            size = checked(size * 2);
                            continue;
                        }
                        if (error == ERROR_HANDLE_EOF) return;
                        throw new Win32Exception(
                            error,
                            "SYNAPSE_PHYSICAL_STREAM_ENUMERATION_FAILED path=" + path +
                            " win32=" + error);
                    }

                    int offset = 0;
                    int count = 0;
                    while (true)
                    {
                        if (offset < 0 || offset > size - headerSize)
                            throw new InvalidOperationException(
                                "SYNAPSE_PHYSICAL_STREAM_ENUMERATION_MALFORMED path=" + path +
                                " offset=" + offset + " size=" + size);
                        uint next = unchecked((uint)Marshal.ReadInt32(buffer, offset));
                        uint nameBytes = unchecked((uint)Marshal.ReadInt32(buffer, offset + 4));
                        if ((nameBytes & 1u) != 0u || nameBytes > (uint)(size - offset - headerSize))
                            throw new InvalidOperationException(
                                "SYNAPSE_PHYSICAL_STREAM_NAME_INVALID path=" + path +
                                " offset=" + offset + " name_bytes=" + nameBytes + " size=" + size);
                        string name = nameBytes == 0u
                            ? String.Empty
                            : Marshal.PtrToStringUni(
                                IntPtr.Add(buffer, checked(offset + headerSize)),
                                checked((int)(nameBytes / 2u)));
                        count++;
                        if (count > 1024)
                            throw new InvalidOperationException(
                                "SYNAPSE_PHYSICAL_STREAM_COUNT_BOUND_EXCEEDED path=" + path +
                                " max=1024");
                        if (!String.Equals(name, "::`$DATA", StringComparison.Ordinal))
                            throw new InvalidOperationException(
                                "SYNAPSE_PHYSICAL_NAMED_STREAM_REFUSED path=" + path +
                                " stream=" + name);
                        if (next == 0u) return;
                        if (next < headerSize || (next & 7u) != 0u || next > (uint)(size - offset))
                            throw new InvalidOperationException(
                                "SYNAPSE_PHYSICAL_STREAM_NEXT_OFFSET_INVALID path=" + path +
                                " offset=" + offset + " next=" + next + " size=" + size);
                        offset = checked(offset + (int)next);
                    }
                }
                finally
                {
                    Marshal.FreeHGlobal(buffer);
                }
            }
            throw new InvalidOperationException(
                "SYNAPSE_PHYSICAL_STREAM_ENUMERATION_BOUND_EXCEEDED path=" + path +
                " max_bytes=1048576");
        }

        private static string ReadFinalPath(SafeFileHandle handle, string path)
        {
            StringBuilder value = new StringBuilder(32768);
            uint length = GetFinalPathNameByHandle(handle, value, (uint)value.Capacity, 0);
            if (length == 0 || length >= value.Capacity)
            {
                int error = Marshal.GetLastWin32Error();
                throw new Win32Exception(
                    error,
                    "SYNAPSE_PHYSICAL_HANDLE_FINAL_PATH_READ_FAILED path=" + path + " win32=" + error);
            }
            string finalPath = value.ToString();
            if (finalPath.StartsWith(@"\\?\UNC\", StringComparison.OrdinalIgnoreCase))
            {
                return @"\\" + finalPath.Substring(8);
            }
            if (finalPath.StartsWith(@"\\?\", StringComparison.OrdinalIgnoreCase))
            {
                return finalPath.Substring(4);
            }
            return finalPath;
        }

        private static string ReadPhysicalIdentity(SafeFileHandle handle, string path)
        {
            BY_HANDLE_FILE_INFORMATION information;
            if (!GetFileInformationByHandle(handle, out information))
            {
                int error = Marshal.GetLastWin32Error();
                throw new Win32Exception(
                    error,
                    "SYNAPSE_PHYSICAL_HANDLE_IDENTITY_READ_FAILED path=" + path + " win32=" + error);
            }
            return information.VolumeSerialNumber.ToString("X8") + ":" +
                information.FileIndexHigh.ToString("X8") + information.FileIndexLow.ToString("X8");
        }

        private static string ReadPhysicalFileId128(SafeFileHandle handle, string path)
        {
            FILE_ID_INFO information;
            if (!GetFileIdInformationByHandleEx(
                handle,
                FILE_ID_INFO_CLASS,
                out information,
                (uint)Marshal.SizeOf(typeof(FILE_ID_INFO))))
            {
                int error = Marshal.GetLastWin32Error();
                throw new Win32Exception(
                    error,
                    "SYNAPSE_PHYSICAL_HANDLE_FILE_ID_INFO_READ_FAILED path=" + path + " win32=" + error);
            }
            if (information.FileId == null || information.FileId.Length != 16)
            {
                throw new InvalidOperationException(
                    "SYNAPSE_PHYSICAL_HANDLE_FILE_ID_INFO_INVALID path=" + path);
            }
            return information.VolumeSerialNumber.ToString("X16") + ":" +
                BitConverter.ToString(information.FileId).Replace("-", String.Empty);
        }

        private static string ReadIdentityInExpectedProjection(
            SafeFileHandle handle,
            string path,
            string expectedIdentity)
        {
            // Current physical descriptors use full FILE_ID_INFO while retained
            // historical descriptors use the BY_HANDLE_FILE_INFORMATION
            // projection. The sealed shape selects one exact representation.
            if (!String.IsNullOrWhiteSpace(expectedIdentity) &&
                System.Text.RegularExpressions.Regex.IsMatch(
                    expectedIdentity,
                    @"^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$",
                    System.Text.RegularExpressions.RegexOptions.CultureInvariant))
            {
                return ReadPhysicalFileId128(handle, path);
            }
            return ReadPhysicalIdentity(handle, path);
        }

        private static BY_HANDLE_FILE_INFORMATION RequireRegularSingleLinkFile(
            SafeFileHandle handle,
            string path,
            string expectedFileId128)
        {
            FILE_ATTRIBUTE_TAG_INFO attributes = ReadPhysicalAttributes(handle, path);
            BY_HANDLE_FILE_INFORMATION information;
            if (!GetFileInformationByHandle(handle, out information))
            {
                int error = Marshal.GetLastWin32Error();
                throw new Win32Exception(error, "SYNAPSE_PHYSICAL_REGULAR_FILE_LINK_READ_FAILED path=" + path);
            }
            string finalPath = Path.GetFullPath(ReadFinalPath(handle, path));
            string fileId128 = ReadPhysicalFileId128(handle, path);
            if ((attributes.FileAttributes & (FILE_ATTRIBUTE_DIRECTORY | FILE_ATTRIBUTE_REPARSE_POINT)) != 0 ||
                information.NumberOfLinks != 1 ||
                !finalPath.Equals(Path.GetFullPath(path), StringComparison.OrdinalIgnoreCase) ||
                (!String.IsNullOrWhiteSpace(expectedFileId128) &&
                    !fileId128.Equals(expectedFileId128, StringComparison.OrdinalIgnoreCase)))
            {
                throw new InvalidOperationException(
                    "SYNAPSE_PHYSICAL_REGULAR_FILE_CONTRACT_INVALID path=" + path +
                    " actual_path=" + finalPath + " expected_file_id_128=" + expectedFileId128 +
                    " actual_file_id_128=" + fileId128 + " links=" + information.NumberOfLinks +
                    " attributes=" + attributes.FileAttributes);
            }
            return information;
        }

        private static void ValidateLeafName(string leafName, string context)
        {
            bool asciiSafe = !String.IsNullOrWhiteSpace(leafName) && leafName.Length <= 128;
            if (asciiSafe)
            {
                for (int index = 0; index < leafName.Length; index++)
                {
                    char value = leafName[index];
                    if (!((value >= 'A' && value <= 'Z') ||
                          (value >= 'a' && value <= 'z') ||
                          (value >= '0' && value <= '9') ||
                          value == '.' || value == '_' || value == '-'))
                    {
                        asciiSafe = false;
                        break;
                    }
                }
            }
            if (!asciiSafe ||
                !Path.GetFileName(leafName).Equals(leafName, StringComparison.Ordinal) ||
                leafName.Equals(".", StringComparison.Ordinal) ||
                leafName.Equals("..", StringComparison.Ordinal) ||
                leafName.EndsWith(".", StringComparison.Ordinal) ||
                leafName.EndsWith(" ", StringComparison.Ordinal) ||
                leafName.IndexOf(Path.DirectorySeparatorChar) >= 0 ||
                leafName.IndexOf(Path.AltDirectorySeparatorChar) >= 0)
            {
                throw new ArgumentException(
                    "SYNAPSE_PHYSICAL_RELATIVE_LEAF_INVALID context=" + context + " leaf=" + leafName);
            }
        }

        private static void ValidateEnumeratedLeafName(string leafName, string context)
        {
            bool safe = !String.IsNullOrWhiteSpace(leafName) && leafName.Length <= 255;
            if (safe &&
                (!Path.GetFileName(leafName).Equals(leafName, StringComparison.Ordinal) ||
                 leafName.Equals(".", StringComparison.Ordinal) ||
                 leafName.Equals("..", StringComparison.Ordinal) ||
                 leafName.EndsWith(".", StringComparison.Ordinal) ||
                 leafName.EndsWith(" ", StringComparison.Ordinal) ||
                 leafName.IndexOf(Path.DirectorySeparatorChar) >= 0 ||
                 leafName.IndexOf(Path.AltDirectorySeparatorChar) >= 0 ||
                 leafName.IndexOf(Path.VolumeSeparatorChar) >= 0 ||
                 leafName.IndexOfAny(Path.GetInvalidFileNameChars()) >= 0))
            {
                safe = false;
            }
            if (!safe)
            {
                throw new ArgumentException(
                    "SYNAPSE_PHYSICAL_ENUMERATED_LEAF_INVALID context=" + context + " leaf=" + leafName);
            }
        }

        private static List<string> GetDirectoryChainPaths(string directoryPath)
        {
            string directoryFull = NormalizeDirectoryPath(directoryPath);
            List<string> paths = new List<string>();
            DirectoryInfo cursor = new DirectoryInfo(directoryFull);
            while (cursor != null)
            {
                paths.Add(NormalizeDirectoryPath(cursor.FullName));
                cursor = cursor.Parent;
            }
            paths.Reverse();
            return paths;
        }

        private static List<SafeFileHandle> OpenPinnedPhysicalDirectoryChainV2(
            string directoryPath,
            string[] expectedPaths,
            string[] expectedFileIds128)
        {
            return OpenPinnedPhysicalDirectoryChainV2Core(
                directoryPath,
                expectedPaths,
                expectedFileIds128,
                false);
        }

        private static List<SafeFileHandle> OpenPinnedPhysicalEnumeratedDirectoryChainV2(
            string directoryPath,
            string[] expectedPaths,
            string[] expectedFileIds128)
        {
            return OpenPinnedPhysicalDirectoryChainV2Core(
                directoryPath,
                expectedPaths,
                expectedFileIds128,
                true);
        }

        private static List<SafeFileHandle> OpenPinnedPhysicalDirectoryChainV2Core(
            string directoryPath,
            string[] expectedPaths,
            string[] expectedFileIds128,
            bool enumeratedLeafNames)
        {
            List<string> paths = GetDirectoryChainPaths(directoryPath);
            if (expectedPaths == null || expectedFileIds128 == null ||
                expectedPaths.Length != paths.Count || expectedFileIds128.Length != paths.Count)
            {
                throw new InvalidOperationException(
                    "SYNAPSE_PHYSICAL_DIRECTORY_CHAIN_DESCRIPTOR_COUNT_MISMATCH path=" + directoryPath +
                    " actual_count=" + paths.Count +
                    " expected_path_count=" + (expectedPaths == null ? -1 : expectedPaths.Length) +
                    " expected_id_count=" + (expectedFileIds128 == null ? -1 : expectedFileIds128.Length));
            }

            List<SafeFileHandle> handles = new List<SafeFileHandle>();
            try
            {
                for (int index = 0; index < paths.Count; index++)
                {
                    string path = paths[index];
                    string expectedPath = NormalizeDirectoryPath(expectedPaths[index]);
                    if (!path.Equals(expectedPath, StringComparison.OrdinalIgnoreCase))
                    {
                        throw new InvalidOperationException(
                            "SYNAPSE_PHYSICAL_DIRECTORY_CHAIN_PATH_MISMATCH index=" + index +
                            " expected=" + expectedPath + " actual=" + path);
                    }
                    SafeFileHandle handle;
                    if (index == 0)
                    {
                        // Share DELETE as well. The live daemon holds the
                        // deployed profiles directory open, so withholding it
                        // failed the pinned chain with
                        // STATUS_SHARING_VIOLATION (0xC0000043) on
                        // leaf=profiles at the end of every otherwise
                        // successful deployment. This costs no TOCTOU
                        // protection: the chain's guarantee comes from
                        // handle-rooted relative opens plus the per-entry
                        // file-id and final-path verification below, not from
                        // denying delete sharing. A concurrent rename cannot
                        // redirect a handle-rooted open, and the final-path
                        // check fails LOUDLY if one happens.
                        handle = OpenPhysicalHandleWithShare(
                            path,
                            FILE_LIST_DIRECTORY | FILE_READ_ATTRIBUTES,
                            FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE);
                    }
                    else
                    {
                        // A fully path/FID-bound physical chain may contain any
                        // valid Windows component. Authored operation leaves
                        // remain strict at their public boundary.
                        handle = OpenEnumeratedRelativeEntry(
                            handles[index - 1],
                            Path.GetFileName(path),
                            FILE_LIST_DIRECTORY | FILE_READ_ATTRIBUTES,
                            FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
                            NT_FILE_OPEN,
                            true,
                            false);
                    }
                    handles.Add(handle);
                    FILE_ATTRIBUTE_TAG_INFO information = ReadPhysicalAttributes(handle, path);
                    if ((information.FileAttributes & FILE_ATTRIBUTE_REPARSE_POINT) != 0 ||
                        (information.FileAttributes & FILE_ATTRIBUTE_DIRECTORY) == 0)
                    {
                        throw new InvalidOperationException(
                            "SYNAPSE_PHYSICAL_DIRECTORY_CHAIN_V2_INVALID path=" + path +
                            " attributes=" + information.FileAttributes);
                    }
                    string finalPath = NormalizeDirectoryPath(ReadFinalPath(handle, path));
                    string fileId128 = ReadPhysicalFileId128(handle, path);
                    if (!finalPath.Equals(path, StringComparison.OrdinalIgnoreCase) ||
                        String.IsNullOrWhiteSpace(expectedFileIds128[index]) ||
                        !fileId128.Equals(expectedFileIds128[index], StringComparison.OrdinalIgnoreCase))
                    {
                        throw new InvalidOperationException(
                            "SYNAPSE_PHYSICAL_DIRECTORY_CHAIN_V2_IDENTITY_MISMATCH index=" + index +
                            " path=" + path + " final=" + finalPath +
                            " expected_file_id_128=" + expectedFileIds128[index] +
                            " actual_file_id_128=" + fileId128);
                    }
                }
                return handles;
            }
            catch
            {
                DisposeHandles(handles);
                throw;
            }
        }

        private static SafeFileHandle OpenRelativeEntry(
            SafeFileHandle parentHandle,
            string leafName,
            uint desiredAccess,
            uint shareAccess,
            uint createDisposition,
            bool directory,
            bool writeThrough,
            bool asynchronous = false)
        {
            return OpenRelativeEntryCore(
                parentHandle,
                leafName,
                desiredAccess,
                shareAccess,
                createDisposition,
                directory,
                writeThrough,
                asynchronous,
                false);
        }

        private static SafeFileHandle OpenEnumeratedRelativeEntry(
            SafeFileHandle parentHandle,
            string leafName,
            uint desiredAccess,
            uint shareAccess,
            uint createDisposition,
            bool directory,
            bool writeThrough,
            bool asynchronous = false)
        {
            return OpenRelativeEntryCore(
                parentHandle,
                leafName,
                desiredAccess,
                shareAccess,
                createDisposition,
                directory,
                writeThrough,
                asynchronous,
                true);
        }

        private static SafeFileHandle OpenRelativeEntryCore(
            SafeFileHandle parentHandle,
            string leafName,
            uint desiredAccess,
            uint shareAccess,
            uint createDisposition,
            bool directory,
            bool writeThrough,
            bool asynchronous,
            bool enumeratedLeaf)
        {
            if (enumeratedLeaf) ValidateEnumeratedLeafName(leafName, "nt_enumerated_relative_open");
            else ValidateLeafName(leafName, "nt_relative_open");
            IntPtr nameBuffer = IntPtr.Zero;
            IntPtr nameStructure = IntPtr.Zero;
            bool parentReferenced = false;
            try
            {
                nameBuffer = Marshal.StringToHGlobalUni(leafName);
                UNICODE_STRING name = new UNICODE_STRING
                {
                    Length = checked((ushort)(leafName.Length * 2)),
                    MaximumLength = checked((ushort)((leafName.Length + 1) * 2)),
                    Buffer = nameBuffer
                };
                nameStructure = Marshal.AllocHGlobal(Marshal.SizeOf(typeof(UNICODE_STRING)));
                Marshal.StructureToPtr(name, nameStructure, false);
                parentHandle.DangerousAddRef(ref parentReferenced);
                OBJECT_ATTRIBUTES attributes = new OBJECT_ATTRIBUTES
                {
                    Length = Marshal.SizeOf(typeof(OBJECT_ATTRIBUTES)),
                    RootDirectory = parentHandle.DangerousGetHandle(),
                    ObjectName = nameStructure,
                    Attributes = OBJ_CASE_INSENSITIVE,
                    SecurityDescriptor = IntPtr.Zero,
                    SecurityQualityOfService = IntPtr.Zero
                };
                IO_STATUS_BLOCK statusBlock;
                SafeFileHandle result;
                uint options = NT_FILE_OPEN_REPARSE_POINT |
                    (asynchronous ? 0u : NT_FILE_SYNCHRONOUS_IO_NONALERT) |
                    (directory ? NT_FILE_DIRECTORY_FILE : NT_FILE_NON_DIRECTORY_FILE) |
                    (writeThrough ? NT_FILE_WRITE_THROUGH : 0);
                int status = NtCreateFile(
                    out result,
                    desiredAccess | (asynchronous ? 0u : SYNCHRONIZE),
                    ref attributes,
                    out statusBlock,
                    IntPtr.Zero,
                    directory ? FILE_ATTRIBUTE_DIRECTORY : FILE_ATTRIBUTE_NORMAL,
                    shareAccess,
                    createDisposition,
                    options,
                    IntPtr.Zero,
                    0);
                if (status < 0 || result == null || result.IsInvalid)
                {
                    uint error = RtlNtStatusToDosError(status);
                    if (result != null) result.Dispose();
                    throw new Win32Exception(
                        unchecked((int)error),
                        "SYNAPSE_PHYSICAL_RELATIVE_OPEN_FAILED leaf=" + leafName +
                        " directory=" + directory + " disposition=" + createDisposition +
                        " ntstatus=0x" + status.ToString("X8") + " win32=" + error);
                }
                return result;
            }
            finally
            {
                if (parentReferenced) parentHandle.DangerousRelease();
                if (nameStructure != IntPtr.Zero) Marshal.FreeHGlobal(nameStructure);
                if (nameBuffer != IntPtr.Zero) Marshal.FreeHGlobal(nameBuffer);
            }
        }

        private static string ComputeSha256(SafeFileHandle handle, out long length)
        {
            using (FileStream stream = new FileStream(handle, FileAccess.Read, 65536, false))
            using (SHA256 sha = SHA256.Create())
            {
                length = stream.Length;
                stream.Position = 0;
                return BitConverter.ToString(sha.ComputeHash(stream)).Replace("-", String.Empty);
            }
        }

        private static string ComputeSha256Retained(FileStream stream, out long length)
        {
            if (stream == null) throw new ArgumentNullException("stream");
            long originalPosition = stream.Position;
            try
            {
                length = stream.Length;
                stream.Position = 0;
                using (SHA256 sha = SHA256.Create())
                {
                    return BitConverter.ToString(sha.ComputeHash(stream)).Replace("-", String.Empty);
                }
            }
            finally
            {
                stream.Position = originalPosition <= stream.Length ? originalPosition : 0;
            }
        }

        private static PhysicalTextReadback ReadUtf8Retained(
            FileStream stream,
            string path,
            string expectedFileId128,
            int maximumBytes)
        {
            if (stream == null) throw new ArgumentNullException("stream");
            if (maximumBytes < 1) throw new ArgumentOutOfRangeException("maximumBytes");
            RequireRegularSingleLinkFile(stream.SafeFileHandle, path, expectedFileId128);
            long length = stream.Length;
            if (length < 0 || length > maximumBytes || length > Int32.MaxValue)
                throw new InvalidOperationException(
                    "SYNAPSE_PHYSICAL_RETAINED_TEXT_LENGTH_INVALID path=" + path +
                    " length=" + length + " max=" + maximumBytes);
            long originalPosition = stream.Position;
            try
            {
                stream.Position = 0;
                byte[] bytes = new byte[(int)length];
                int offset = 0;
                while (offset < bytes.Length)
                {
                    int read = stream.Read(bytes, offset, bytes.Length - offset);
                    if (read <= 0) throw new EndOfStreamException(
                        "SYNAPSE_PHYSICAL_RETAINED_TEXT_TRUNCATED path=" + path +
                        " expected=" + bytes.Length + " actual=" + offset);
                    offset += read;
                }
                string content = new UTF8Encoding(false, true).GetString(bytes);
                byte[] digest;
                using (SHA256 sha = SHA256.Create()) digest = sha.ComputeHash(bytes);
                RequireRegularSingleLinkFile(stream.SafeFileHandle, path, expectedFileId128);
                if (stream.Length != length)
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_RETAINED_TEXT_LENGTH_DRIFT path=" + path +
                        " expected=" + length + " actual=" + stream.Length);
                return new PhysicalTextReadback
                {
                    Content = content,
                    Length = length,
                    Sha256 = BitConverter.ToString(digest).Replace("-", String.Empty),
                    Identity = ReadPhysicalIdentity(stream.SafeFileHandle, path),
                    FileId128 = ReadPhysicalFileId128(stream.SafeFileHandle, path)
                };
            }
            finally
            {
                stream.Position = originalPosition <= stream.Length ? originalPosition : 0;
            }
        }

        private static PhysicalDirectoryReadback ReadDirectoryHandle(
            SafeFileHandle handle,
            string expectedPath)
        {
            FILE_ATTRIBUTE_TAG_INFO information = ReadPhysicalAttributes(handle, expectedPath);
            if ((information.FileAttributes & FILE_ATTRIBUTE_REPARSE_POINT) != 0 ||
                (information.FileAttributes & FILE_ATTRIBUTE_DIRECTORY) == 0)
            {
                throw new InvalidOperationException(
                    "SYNAPSE_PHYSICAL_DIRECTORY_HANDLE_INVALID path=" + expectedPath +
                    " attributes=" + information.FileAttributes);
            }
            string finalPath = NormalizeDirectoryPath(ReadFinalPath(handle, expectedPath));
            return new PhysicalDirectoryReadback
            {
                Path = finalPath,
                Identity = ReadPhysicalIdentity(handle, expectedPath),
                FileId128 = ReadPhysicalFileId128(handle, expectedPath)
            };
        }

        private static SafeFileHandle OpenVerifiedPhysicalEntry(
            string rootPath,
            string expectedRootIdentity,
            string entryPath,
            string expectedEntryIdentity,
            bool expectDirectory,
            uint access,
            bool denyMutation,
            out string actualEntryIdentity)
        {
            string rootFull = Path.GetFullPath(rootPath).TrimEnd(Path.DirectorySeparatorChar);
            string entryFull = Path.GetFullPath(entryPath).TrimEnd(Path.DirectorySeparatorChar);
            string rootPrefix = rootFull + Path.DirectorySeparatorChar;
            if (!entryFull.Equals(rootFull, StringComparison.OrdinalIgnoreCase) &&
                !entryFull.StartsWith(rootPrefix, StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "SYNAPSE_PHYSICAL_HANDLE_SCOPE_ESCAPE root=" + rootFull + " path=" + entryFull);
            }

            SafeFileHandle entry = null;
            List<SafeFileHandle> rootPins = null;
            try
            {
                if (!String.IsNullOrWhiteSpace(expectedRootIdentity))
                {
                    rootPins = OpenPinnedPhysicalDirectoryChain(rootFull, expectedRootIdentity);
                }
                using (SafeFileHandle root = OpenPhysicalHandle(rootFull, FILE_READ_ATTRIBUTES))
                {
                FILE_ATTRIBUTE_TAG_INFO rootInformation = ReadPhysicalAttributes(root, rootFull);
                if ((rootInformation.FileAttributes & FILE_ATTRIBUTE_REPARSE_POINT) != 0 ||
                    (rootInformation.FileAttributes & FILE_ATTRIBUTE_DIRECTORY) == 0)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_HANDLE_ROOT_INVALID root=" + rootFull +
                        " attributes=" + rootInformation.FileAttributes);
                }
                string rootFinal = Path.GetFullPath(ReadFinalPath(root, rootFull)).TrimEnd(Path.DirectorySeparatorChar);
                if (!rootFinal.Equals(rootFull, StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_HANDLE_ROOT_FINAL_PATH_MISMATCH root=" + rootFull +
                        " actual_final=" + rootFinal);
                }
                string rootIdentity = ReadIdentityInExpectedProjection(
                    root,
                    rootFull,
                    expectedRootIdentity);
                if (!String.IsNullOrWhiteSpace(expectedRootIdentity) &&
                    !rootIdentity.Equals(expectedRootIdentity, StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_HANDLE_ROOT_IDENTITY_MISMATCH root=" + rootFull +
                        " expected_identity=" + expectedRootIdentity +
                        " actual_identity=" + rootIdentity);
                }

                entry = OpenPhysicalHandleWithShare(
                    entryFull,
                    access | FILE_READ_ATTRIBUTES,
                    denyMutation ? FILE_SHARE_READ : FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE);
                FILE_ATTRIBUTE_TAG_INFO entryInformation = ReadPhysicalAttributes(entry, entryFull);
                if ((entryInformation.FileAttributes & FILE_ATTRIBUTE_REPARSE_POINT) != 0)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_HANDLE_REPARSE_POINT root=" + rootFull +
                        " path=" + entryFull + " attributes=" + entryInformation.FileAttributes);
                }
                bool isDirectory = (entryInformation.FileAttributes & FILE_ATTRIBUTE_DIRECTORY) != 0;
                if (isDirectory != expectDirectory)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_HANDLE_TYPE_MISMATCH root=" + rootFull +
                        " path=" + entryFull + " expected_directory=" + expectDirectory +
                        " actual_directory=" + isDirectory);
                }
                string relative = entryFull.Equals(rootFull, StringComparison.OrdinalIgnoreCase)
                    ? String.Empty
                    : entryFull.Substring(rootPrefix.Length);
                string expectedFinal = String.IsNullOrEmpty(relative)
                    ? rootFinal
                    : Path.GetFullPath(Path.Combine(rootFinal, relative));
                string entryFinal = Path.GetFullPath(ReadFinalPath(entry, entryFull)).TrimEnd(Path.DirectorySeparatorChar);
                if (!entryFinal.Equals(expectedFinal, StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_HANDLE_FINAL_PATH_MISMATCH root=" + rootFull +
                        " path=" + entryFull + " expected_final=" + expectedFinal +
                        " actual_final=" + entryFinal);
                }
                actualEntryIdentity = ReadIdentityInExpectedProjection(
                    entry,
                    entryFull,
                    expectedEntryIdentity);
                if (!String.IsNullOrWhiteSpace(expectedEntryIdentity) &&
                    !actualEntryIdentity.Equals(expectedEntryIdentity, StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_HANDLE_ENTRY_IDENTITY_MISMATCH root=" + rootFull +
                        " path=" + entryFull + " expected_identity=" + expectedEntryIdentity +
                        " actual_identity=" + actualEntryIdentity);
                }
                    return entry;
                }
            }
            catch
            {
                if (entry != null) entry.Dispose();
                throw;
            }
            finally
            {
                DisposeHandles(rootPins);
            }
        }

        public static string GetPhysicalDirectoryIdentity(string directoryPath)
        {
            string ignored;
            using (SafeFileHandle handle = OpenVerifiedPhysicalEntry(
                directoryPath,
                String.Empty,
                directoryPath,
                String.Empty,
                true,
                FILE_READ_ATTRIBUTES,
                false,
                out ignored))
            {
                return ignored;
            }
        }

        public static string GetPhysicalDirectoryIdentityExpected(
            string directoryPath,
            string expectedIdentity)
        {
            string actualIdentity;
            using (SafeFileHandle handle = OpenVerifiedPhysicalEntry(
                directoryPath,
                expectedIdentity,
                directoryPath,
                expectedIdentity,
                true,
                FILE_READ_ATTRIBUTES,
                false,
                out actualIdentity))
            {
                return actualIdentity;
            }
        }

        // Read-only descriptor capture. It must also share DELETE: the live
        // daemon holds the deployed profiles directory open, and a chain read
        // that withheld FILE_SHARE_DELETE failed the whole run with
        // STATUS_SHARING_VIOLATION (0xC0000043) on leaf=profiles at the very
        // end of an otherwise successful deployment. This is the snapshot used
        // to BUILD a descriptor, not the pinned chain that guards a mutation
        // (OpenPinnedPhysicalDirectoryChainV2Core keeps its stricter share
        // mode); identity here is still proven by the per-entry file-id
        // readback, so tolerating a concurrent holder costs no integrity.
        public static PhysicalDirectoryReadback[] GetPhysicalDirectoryChain(string directoryPath)
        {
            List<string> paths = GetDirectoryChainPaths(directoryPath);
            List<PhysicalDirectoryReadback> result = new List<PhysicalDirectoryReadback>();
            List<SafeFileHandle> handles = new List<SafeFileHandle>();
            try
            {
                for (int index = 0; index < paths.Count; index++)
                {
                    string path = paths[index];
                    SafeFileHandle handle = index == 0
                        ? OpenPhysicalHandleWithShare(
                            path,
                            FILE_LIST_DIRECTORY | FILE_READ_ATTRIBUTES,
                            FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE)
                        : OpenEnumeratedRelativeEntry(
                            handles[index - 1],
                            Path.GetFileName(path),
                            FILE_LIST_DIRECTORY | FILE_READ_ATTRIBUTES,
                            FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
                            NT_FILE_OPEN,
                            true,
                            false);
                    handles.Add(handle);
                    PhysicalDirectoryReadback readback = ReadDirectoryHandle(handle, path);
                    if (!NormalizeDirectoryPath(readback.Path).Equals(path, StringComparison.OrdinalIgnoreCase))
                    {
                        throw new InvalidOperationException(
                            "SYNAPSE_PHYSICAL_DIRECTORY_CHAIN_FINAL_PATH_MISMATCH path=" + path +
                            " actual_final=" + readback.Path);
                    }
                    result.Add(readback);
                }
                return result.ToArray();
            }
            finally
            {
                DisposeHandles(handles);
            }
        }

        public static PhysicalFileTransitionLease OpenPhysicalFileTransitionLease(
            string parentPath,
            string[] expectedParentPaths,
            string[] expectedParentFileIds128,
            string leafName,
            string expectedFileId128,
            string expectedSha256,
            long expectedLength)
        {
            string parent = NormalizeDirectoryPath(parentPath);
            ValidateLeafName(leafName, "transition_lease_open");
            string path = Path.GetFullPath(Path.Combine(parent, leafName));
            List<SafeFileHandle> pins = OpenPinnedPhysicalDirectoryChainV2(
                parent,
                expectedParentPaths,
                expectedParentFileIds128);
            FileStream stream = null;
            try
            {
                SafeFileHandle handle = OpenRelativeEntry(
                    pins[pins.Count - 1],
                    leafName,
                    GENERIC_READ | FILE_READ_ATTRIBUTES | DELETE,
                    FILE_SHARE_READ,
                    NT_FILE_OPEN,
                    false,
                    false);
                FILE_ATTRIBUTE_TAG_INFO attributes = ReadPhysicalAttributes(handle, path);
                BY_HANDLE_FILE_INFORMATION links;
                if (!GetFileInformationByHandle(handle, out links))
                {
                    int error = Marshal.GetLastWin32Error();
                    handle.Dispose();
                    throw new Win32Exception(error, "SYNAPSE_PHYSICAL_TRANSITION_LINK_READ_FAILED path=" + path);
                }
                string finalPath = Path.GetFullPath(ReadFinalPath(handle, path));
                string fileId = ReadPhysicalFileId128(handle, path);
                if ((attributes.FileAttributes & (FILE_ATTRIBUTE_DIRECTORY | FILE_ATTRIBUTE_REPARSE_POINT)) != 0 ||
                    links.NumberOfLinks != 1 ||
                    !finalPath.Equals(path, StringComparison.OrdinalIgnoreCase) ||
                    !fileId.Equals(expectedFileId128, StringComparison.OrdinalIgnoreCase))
                {
                    handle.Dispose();
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_TRANSITION_OPEN_IDENTITY_MISMATCH path=" + path +
                        " final=" + finalPath + " expected_file_id_128=" + expectedFileId128 +
                        " actual_file_id_128=" + fileId + " links=" + links.NumberOfLinks +
                        " attributes=" + attributes.FileAttributes);
                }
                stream = new FileStream(handle, FileAccess.Read, 65536, false);
                long length;
                string sha = ComputeSha256Retained(stream, out length);
                if (!sha.Equals(expectedSha256, StringComparison.OrdinalIgnoreCase) || length != expectedLength)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_TRANSITION_OPEN_CONTENT_MISMATCH path=" + path +
                        " expected_sha256=" + expectedSha256 + " actual_sha256=" + sha +
                        " expected_length=" + expectedLength + " actual_length=" + length);
                }
                PhysicalFileTransitionLease result = new PhysicalFileTransitionLease(
                    stream,
                    pins,
                    path,
                    fileId,
                    sha,
                    length);
                stream = null;
                pins = null;
                return result;
            }
            finally
            {
                if (stream != null) stream.Dispose();
                DisposeHandles(pins);
            }
        }

        public static PhysicalFileReadLease OpenPhysicalFileReadLease(
            string parentPath,
            string[] expectedParentPaths,
            string[] expectedParentFileIds128,
            string leafName,
            string expectedFileId128,
            string expectedSha256,
            long expectedLength)
        {
            string parent = NormalizeDirectoryPath(parentPath);
            ValidateLeafName(leafName, "read_lease_open");
            string path = Path.GetFullPath(Path.Combine(parent, leafName));
            List<SafeFileHandle> pins = OpenPinnedPhysicalDirectoryChainV2(
                parent,
                expectedParentPaths,
                expectedParentFileIds128);
            FileStream stream = null;
            try
            {
                SafeFileHandle handle = OpenRelativeEntry(
                    pins[pins.Count - 1],
                    leafName,
                    GENERIC_READ | FILE_READ_ATTRIBUTES,
                    FILE_SHARE_READ,
                    NT_FILE_OPEN,
                    false,
                    false);
                string fileId = ReadPhysicalFileId128(handle, path);
                RequireRegularSingleLinkFile(handle, path, expectedFileId128);
                stream = new FileStream(handle, FileAccess.Read, 65536, false);
                if (expectedLength < 0 || stream.Length != expectedLength)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_READ_LEASE_LENGTH_MISMATCH path=" + path +
                        " expected_length=" + expectedLength + " actual_length=" + stream.Length);
                }
                long length;
                string sha = ComputeSha256Retained(stream, out length);
                if (!fileId.Equals(expectedFileId128, StringComparison.OrdinalIgnoreCase) ||
                    !sha.Equals(expectedSha256, StringComparison.OrdinalIgnoreCase) ||
                    length != expectedLength)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_READ_LEASE_CONTENT_MISMATCH path=" + path +
                        " expected_file_id_128=" + expectedFileId128 + " actual_file_id_128=" + fileId +
                        " expected_sha256=" + expectedSha256 + " actual_sha256=" + sha +
                        " expected_length=" + expectedLength + " actual_length=" + length);
                }
                PhysicalFileReadLease result = new PhysicalFileReadLease(
                    stream,
                    pins,
                    path,
                    fileId,
                    sha,
                    length);
                stream = null;
                pins = null;
                return result;
            }
            finally
            {
                if (stream != null) stream.Dispose();
                DisposeHandles(pins);
            }
        }

