        public static PhysicalAllocatedFile OpenPhysicalAllocatedFileForFill(
            string parentPath,
            string[] expectedParentPaths,
            string[] expectedParentFileIds128,
            string leafName,
            string expectedFileId128,
            long maximumLength)
        {
            if (maximumLength < 0) throw new ArgumentOutOfRangeException("maximumLength");
            string parent = NormalizeDirectoryPath(parentPath);
            ValidateLeafName(leafName, "allocated_file_fill_open");
            string path = Path.GetFullPath(Path.Combine(parent, leafName));
            List<SafeFileHandle> pins = OpenPinnedPhysicalDirectoryChainV2(
                parent,
                expectedParentPaths,
                expectedParentFileIds128);
            SafeFileHandle handle = null;
            FileStream stream = null;
            try
            {
                handle = OpenRelativeEntry(
                    pins[pins.Count - 1],
                    leafName,
                    GENERIC_READ | GENERIC_WRITE | FILE_READ_ATTRIBUTES | DELETE,
                    FILE_SHARE_READ,
                    NT_FILE_OPEN,
                    false,
                    true);
                FILE_ATTRIBUTE_TAG_INFO attributes = ReadPhysicalAttributes(handle, path);
                BY_HANDLE_FILE_INFORMATION links;
                if (!GetFileInformationByHandle(handle, out links))
                {
                    int error = Marshal.GetLastWin32Error();
                    throw new Win32Exception(error, "SYNAPSE_PHYSICAL_ALLOCATED_FILL_LINK_READ_FAILED path=" + path);
                }
                string finalPath = Path.GetFullPath(ReadFinalPath(handle, path));
                string fileId128 = ReadPhysicalFileId128(handle, path);
                if ((attributes.FileAttributes & (FILE_ATTRIBUTE_DIRECTORY | FILE_ATTRIBUTE_REPARSE_POINT)) != 0 ||
                    links.NumberOfLinks != 1 ||
                    !finalPath.Equals(path, StringComparison.OrdinalIgnoreCase) ||
                    !fileId128.Equals(expectedFileId128, StringComparison.OrdinalIgnoreCase))
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_ALLOCATED_FILL_OPEN_INVALID path=" + path +
                        " actual_path=" + finalPath + " expected_file_id_128=" + expectedFileId128 +
                        " actual_file_id_128=" + fileId128 + " links=" + links.NumberOfLinks +
                        " attributes=" + attributes.FileAttributes);
                stream = new FileStream(handle, FileAccess.ReadWrite, 65536, false);
                handle = null;
                RequireRegularSingleLinkFile(stream.SafeFileHandle, path, fileId128);
                if (stream.Length != 0)
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_ALLOCATED_FILL_NOT_EMPTY path=" + path +
                        " length=" + stream.Length + " max=" + maximumLength);
                PhysicalAllocatedFile result = new PhysicalAllocatedFile(stream, pins, path, fileId128);
                stream = null;
                pins = null;
                return result;
            }
            finally
            {
                if (stream != null) stream.Dispose();
                else if (handle != null) handle.Dispose();
                DisposeHandles(pins);
            }
        }

