        private static PhysicalDirectoryEntryReadback[] EnumeratePhysicalDirectoryBoundedCore(
            string directoryPath,
            string[] expectedDirectoryPaths,
            string[] expectedDirectoryFileIds128,
            int maximumEntries,
            bool enumeratedLeafNames)
        {
            if (maximumEntries < 0 || maximumEntries > 4096)
                throw new ArgumentOutOfRangeException("maximumEntries");
            string directory = NormalizeDirectoryPath(directoryPath);
            List<SafeFileHandle> pins = enumeratedLeafNames
                ? OpenPinnedPhysicalEnumeratedDirectoryChainV2(
                    directory,
                    expectedDirectoryPaths,
                    expectedDirectoryFileIds128)
                : OpenPinnedPhysicalDirectoryChainV2(
                    directory,
                    expectedDirectoryPaths,
                    expectedDirectoryFileIds128);
            IntPtr buffer = IntPtr.Zero;
            try
            {
                SafeFileHandle handle = pins[pins.Count - 1];
                const int bufferLength = 65536;
                buffer = Marshal.AllocHGlobal(bufferLength);
                List<PhysicalDirectoryEntryReadback> entries = new List<PhysicalDirectoryEntryReadback>();
                HashSet<string> names = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                while (true)
                {
                    for (int clear = 0; clear < bufferLength; clear++) Marshal.WriteByte(buffer, clear, 0);
                    if (!GetDirectoryInformationByHandleEx(
                        handle,
                        FILE_ID_BOTH_DIR_INFO_CLASS,
                        buffer,
                        bufferLength))
                    {
                        int error = Marshal.GetLastWin32Error();
                        if (error == ERROR_NO_MORE_FILES) break;
                        throw new Win32Exception(
                            error,
                            "SYNAPSE_PHYSICAL_DIRECTORY_ENUMERATION_FAILED path=" + directory +
                            " win32=" + error);
                    }
                    int offset = 0;
                    while (true)
                    {
                        IntPtr current = IntPtr.Add(buffer, offset);
                        uint next = unchecked((uint)Marshal.ReadInt32(current, 0));
                        uint attributes = unchecked((uint)Marshal.ReadInt32(current, 56));
                        int nameLength = Marshal.ReadInt32(current, 60);
                        if (nameLength < 0 || (nameLength & 1) != 0 ||
                            FILE_ID_BOTH_DIR_INFO_FILE_NAME_OFFSET + nameLength > bufferLength - offset)
                        {
                            throw new InvalidOperationException(
                                "SYNAPSE_PHYSICAL_DIRECTORY_ENUMERATION_RECORD_INVALID path=" + directory +
                                " offset=" + offset + " name_length=" + nameLength + " next=" + next);
                        }
                        string name = Marshal.PtrToStringUni(
                            IntPtr.Add(current, FILE_ID_BOTH_DIR_INFO_FILE_NAME_OFFSET),
                            nameLength / 2);
                        if (name == null)
                            throw new InvalidOperationException(
                                "SYNAPSE_PHYSICAL_DIRECTORY_ENUMERATION_NULL_NAME path=" + directory +
                                " offset=" + offset + " name_length=" + nameLength);
                        if (!name.Equals(".", StringComparison.Ordinal) && !name.Equals("..", StringComparison.Ordinal))
                        {
                            if (String.IsNullOrWhiteSpace(name) || !names.Add(name))
                                throw new InvalidOperationException(
                                    "SYNAPSE_PHYSICAL_DIRECTORY_ENUMERATION_NAME_INVALID path=" + directory +
                                    " name=" + name + " duplicate_case_insensitive=" + names.Contains(name));
                            if (entries.Count >= maximumEntries)
                            {
                                throw new InvalidOperationException(
                                    "SYNAPSE_PHYSICAL_DIRECTORY_ENTRY_BOUND_EXCEEDED path=" + directory +
                                    " max=" + maximumEntries + " observed_at_least=" + (maximumEntries + 1));
                            }
                            bool isDirectory = (attributes & FILE_ATTRIBUTE_DIRECTORY) != 0;
                            SafeFileHandle child = enumeratedLeafNames
                                ? OpenEnumeratedRelativeEntry(
                                    handle,
                                    name,
                                    FILE_READ_ATTRIBUTES,
                                    FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
                                    NT_FILE_OPEN,
                                    isDirectory,
                                    false)
                                : OpenRelativeEntry(
                                    handle,
                                    name,
                                    FILE_READ_ATTRIBUTES,
                                    FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
                                    NT_FILE_OPEN,
                                    isDirectory,
                                    false);
                            try
                            {
                                string childPath = Path.GetFullPath(Path.Combine(directory, name));
                                FILE_ATTRIBUTE_TAG_INFO childAttributes = ReadPhysicalAttributes(child, childPath);
                                BY_HANDLE_FILE_INFORMATION childInformation;
                                if (!GetFileInformationByHandle(child, out childInformation))
                                {
                                    int error = Marshal.GetLastWin32Error();
                                    throw new Win32Exception(error, "SYNAPSE_PHYSICAL_DIRECTORY_CHILD_LINK_READ_FAILED path=" + childPath);
                                }
                                string childFinal = Path.GetFullPath(ReadFinalPath(child, childPath));
                                string childFileId = ReadPhysicalFileId128(child, childPath);
                                bool childIsDirectory = (childAttributes.FileAttributes & FILE_ATTRIBUTE_DIRECTORY) != 0;
                                if (!childFinal.Equals(childPath, StringComparison.OrdinalIgnoreCase) ||
                                    childInformation.NumberOfLinks != 1 || childIsDirectory != isDirectory)
                                    throw new InvalidOperationException(
                                        "SYNAPSE_PHYSICAL_DIRECTORY_CHILD_CONTRACT_INVALID path=" + childPath +
                                        " actual_path=" + childFinal + " file_id_128=" + childFileId +
                                        " links=" + childInformation.NumberOfLinks + " enumerated_directory=" + isDirectory +
                                        " actual_directory=" + childIsDirectory + " attributes=" + childAttributes.FileAttributes);
                                long length = childIsDirectory
                                    ? 0
                                    : checked(((long)childInformation.FileSizeHigh << 32) | childInformation.FileSizeLow);
                                entries.Add(new PhysicalDirectoryEntryReadback
                                {
                                    Name = name,
                                    Path = childPath,
                                    FileId128 = childFileId,
                                    IsDirectory = childIsDirectory,
                                    Attributes = childAttributes.FileAttributes,
                                    Length = length,
                                    Sha256 = String.Empty
                                });
                            }
                            finally
                            {
                                if (child != null) child.Dispose();
                            }
                        }
                        if (next == 0) break;
                        if (next < FILE_ID_BOTH_DIR_INFO_FILE_NAME_OFFSET + nameLength ||
                            next > bufferLength - offset || (next & 7) != 0)
                            throw new InvalidOperationException(
                                "SYNAPSE_PHYSICAL_DIRECTORY_ENUMERATION_NEXT_INVALID path=" + directory +
                                " offset=" + offset + " next=" + next);
                        offset = checked(offset + (int)next);
                    }
                }
                return entries.ToArray();
            }
            finally
            {
                if (buffer != IntPtr.Zero) Marshal.FreeHGlobal(buffer);
                DisposeHandles(pins);
            }
        }

        public static PhysicalVolumeReadback GetStableLocalVolume(string path)
        {
            string full = Path.GetFullPath(path);
            if (full.StartsWith(@"\\", StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "SYNAPSE_PHYSICAL_VOLUME_NETWORK_UNSUPPORTED path=" + full);
            }
            StringBuilder volumePath = new StringBuilder(32768);
            if (!GetVolumePathName(full, volumePath, (uint)volumePath.Capacity))
            {
                int error = Marshal.GetLastWin32Error();
                throw new Win32Exception(
                    error,
                    "SYNAPSE_PHYSICAL_VOLUME_PATH_READ_FAILED path=" + full + " win32=" + error);
            }
            string root = volumePath.ToString();
            StringBuilder volumeName = new StringBuilder(32768);
            StringBuilder fileSystemName = new StringBuilder(256);
            uint serial;
            uint maxComponent;
            uint flags;
            if (!GetVolumeInformation(
                root,
                volumeName,
                (uint)volumeName.Capacity,
                out serial,
                out maxComponent,
                out flags,
                fileSystemName,
                (uint)fileSystemName.Capacity))
            {
                int error = Marshal.GetLastWin32Error();
                throw new Win32Exception(
                    error,
                    "SYNAPSE_PHYSICAL_VOLUME_INFORMATION_FAILED path=" + full + " root=" + root +
                    " win32=" + error);
            }
            uint driveType = GetDriveType(root);
            string fileSystem = fileSystemName.ToString();
            if (driveType != DRIVE_FIXED ||
                (!fileSystem.Equals("NTFS", StringComparison.OrdinalIgnoreCase) &&
                 !fileSystem.Equals("ReFS", StringComparison.OrdinalIgnoreCase)))
            {
                throw new InvalidOperationException(
                    "SYNAPSE_PHYSICAL_VOLUME_STABILITY_UNSUPPORTED path=" + full +
                    " root=" + root + " drive_type=" + driveType + " filesystem=" + fileSystem);
            }
            return new PhysicalVolumeReadback
            {
                RootPath = root,
                FileSystemName = fileSystem,
                VolumeSerialNumber = serial,
                DriveType = driveType
            };
        }

        public static PhysicalPublicationBridge BeginPhysicalPublicationBridge(
            string sourceParentPath,
            string[] expectedSourceParentPaths,
            string[] expectedSourceParentFileIds128,
            string sourceLeafName,
            string expectedRootFileId128)
        {
            ValidateLeafName(sourceLeafName, "publication_bridge_root");
            string sourceParentFull = NormalizeDirectoryPath(sourceParentPath);
            string sourcePath = NormalizeDirectoryPath(Path.Combine(sourceParentFull, sourceLeafName));
            List<SafeFileHandle> sourcePins = OpenPinnedPhysicalDirectoryChainV2(
                sourceParentFull,
                expectedSourceParentPaths,
                expectedSourceParentFileIds128);
            SafeFileHandle root = null;
            try
            {
                root = OpenRelativeEntry(
                    sourcePins[sourcePins.Count - 1],
                    sourceLeafName,
                    FILE_LIST_DIRECTORY | DELETE | FILE_READ_ATTRIBUTES,
                    FILE_SHARE_READ | FILE_SHARE_WRITE,
                    NT_FILE_OPEN,
                    true,
                    true,
                    true);
                PhysicalDirectoryReadback readback = ReadDirectoryHandle(root, sourcePath);
                if (!NormalizeDirectoryPath(readback.Path).Equals(sourcePath, StringComparison.OrdinalIgnoreCase) ||
                    String.IsNullOrWhiteSpace(expectedRootFileId128) ||
                    !readback.FileId128.Equals(expectedRootFileId128, StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PROFILE_PUBLICATION_ROOT_IDENTITY_MISMATCH path=" + sourcePath +
                        " actual_path=" + readback.Path + " expected_file_id_128=" + expectedRootFileId128 +
                        " actual_file_id_128=" + readback.FileId128);
                }
                PhysicalPublicationBridge result = new PhysicalPublicationBridge(
                    root,
                    sourcePins,
                    sourcePath,
                    readback.FileId128,
                    true,
                    PROFILE_CHANGE_FILTER);
                root = null;
                sourcePins = null;
                return result;
            }
            finally
            {
                if (root != null) root.Dispose();
                DisposeHandles(sourcePins);
            }
        }

        public static PhysicalPublicationBridge BeginPhysicalDirectoryChangeGuard(
            string directoryPath,
            string[] expectedDirectoryPaths,
            string[] expectedDirectoryFileIds128,
            string expectedDirectoryFileId128,
            bool watchSubtree)
        {
            string directoryFull = NormalizeDirectoryPath(directoryPath);
            List<SafeFileHandle> pins = OpenPinnedPhysicalDirectoryChainV2(
                directoryFull,
                expectedDirectoryPaths,
                expectedDirectoryFileIds128);
            SafeFileHandle directory = null;
            try
            {
                directory = CreateFile(
                    directoryFull,
                    FILE_LIST_DIRECTORY | FILE_READ_ATTRIBUTES,
                    FILE_SHARE_READ | FILE_SHARE_WRITE,
                    IntPtr.Zero,
                    OPEN_EXISTING,
                    FILE_FLAG_BACKUP_SEMANTICS | FILE_FLAG_OPEN_REPARSE_POINT |
                        FILE_FLAG_OVERLAPPED | FILE_FLAG_WRITE_THROUGH,
                    IntPtr.Zero);
                if (directory.IsInvalid)
                {
                    int error = Marshal.GetLastWin32Error();
                    directory.Dispose();
                    directory = null;
                    throw new Win32Exception(
                        error,
                        "SYNAPSE_PHYSICAL_DIRECTORY_GUARD_OPEN_FAILED path=" + directoryFull +
                        " win32=" + error);
                }
                PhysicalDirectoryReadback readback = ReadDirectoryHandle(directory, directoryFull);
                if (!NormalizeDirectoryPath(readback.Path).Equals(directoryFull, StringComparison.OrdinalIgnoreCase) ||
                    String.IsNullOrWhiteSpace(expectedDirectoryFileId128) ||
                    !readback.FileId128.Equals(expectedDirectoryFileId128, StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_DIRECTORY_GUARD_IDENTITY_MISMATCH path=" + directoryFull +
                        " actual_path=" + readback.Path + " expected_file_id_128=" +
                        expectedDirectoryFileId128 + " actual_file_id_128=" + readback.FileId128);
                }
                PhysicalPublicationBridge result = new PhysicalPublicationBridge(
                    directory,
                    pins,
                    directoryFull,
                    readback.FileId128,
                    watchSubtree,
                    watchSubtree ? PROFILE_CHANGE_FILTER : 0x00000003);
                directory = null;
                pins = null;
                return result;
            }
            finally
            {
                if (directory != null) directory.Dispose();
                DisposeHandles(pins);
            }
        }

