        public static PhysicalFileReadback CreatePhysicalFileFromFileRelative(
            string parentPath,
            string[] expectedParentPaths,
            string[] expectedParentFileIds128,
            string leafName,
            string sourcePath,
            string expectedSha256)
        {
            string parentFull = NormalizeDirectoryPath(parentPath);
            string expectedPath = Path.GetFullPath(Path.Combine(parentFull, leafName));
            List<SafeFileHandle> pins = OpenPinnedPhysicalDirectoryChainV2(
                parentFull,
                expectedParentPaths,
                expectedParentFileIds128);
            SafeFileHandle created = null;
            FileStream destination = null;
            FileStream source = null;
            try
            {
                created = OpenRelativeEntry(
                    pins[pins.Count - 1],
                    leafName,
                    GENERIC_READ | GENERIC_WRITE | FILE_READ_ATTRIBUTES | DELETE,
                    FILE_SHARE_READ,
                    NT_FILE_CREATE,
                    false,
                    true);
                FILE_ATTRIBUTE_TAG_INFO information = ReadPhysicalAttributes(created, expectedPath);
                if ((information.FileAttributes & (FILE_ATTRIBUTE_REPARSE_POINT | FILE_ATTRIBUTE_DIRECTORY)) != 0)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_FILE_CREATE_TYPE_INVALID path=" + expectedPath +
                        " attributes=" + information.FileAttributes);
                }
                string identity = ReadPhysicalIdentity(created, expectedPath);
                string fileId128 = ReadPhysicalFileId128(created, expectedPath);
                source = new FileStream(
                    sourcePath,
                    FileMode.Open,
                    FileAccess.Read,
                    FileShare.Read,
                    65536,
                    FileOptions.SequentialScan);
                destination = new FileStream(created, FileAccess.ReadWrite, 65536, false);
                created = null;
                source.CopyTo(destination);
                destination.Flush(true);
                destination.Position = 0;
                byte[] digest;
                using (SHA256 sha = SHA256.Create()) digest = sha.ComputeHash(destination);
                string actualSha256 = BitConverter.ToString(digest).Replace("-", String.Empty);
                long length = destination.Length;
                if (String.IsNullOrWhiteSpace(expectedSha256) ||
                    !actualSha256.Equals(expectedSha256, StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_FILE_CREATE_HASH_MISMATCH path=" + expectedPath +
                        " source=" + sourcePath + " expected_sha256=" + expectedSha256 +
                        " actual_sha256=" + actualSha256);
                }
                return new PhysicalFileReadback
                {
                    Length = length,
                    Sha256 = actualSha256,
                    Identity = identity,
                    FileId128 = fileId128
                };
            }
            finally
            {
                if (destination != null) destination.Dispose();
                else if (created != null) created.Dispose();
                if (source != null) source.Dispose();
                DisposeHandles(pins);
            }
        }

        public static PhysicalFileReadback CreatePhysicalUtf8TextFileRelative(
            string parentPath,
            string[] expectedParentPaths,
            string[] expectedParentFileIds128,
            string leafName,
            string content)
        {
            string parentFull = NormalizeDirectoryPath(parentPath);
            string expectedPath = Path.GetFullPath(Path.Combine(parentFull, leafName));
            byte[] bytes = new UTF8Encoding(false, true).GetBytes(content ?? String.Empty);
            string expectedSha256;
            using (SHA256 sha = SHA256.Create())
            {
                expectedSha256 = BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-", String.Empty);
            }
            List<SafeFileHandle> pins = OpenPinnedPhysicalDirectoryChainV2(
                parentFull,
                expectedParentPaths,
                expectedParentFileIds128);
            SafeFileHandle created = null;
            FileStream stream = null;
            try
            {
                created = OpenRelativeEntry(
                    pins[pins.Count - 1],
                    leafName,
                    GENERIC_READ | GENERIC_WRITE | FILE_READ_ATTRIBUTES | DELETE,
                    FILE_SHARE_READ,
                    NT_FILE_CREATE,
                    false,
                    true);
                FILE_ATTRIBUTE_TAG_INFO information = ReadPhysicalAttributes(created, expectedPath);
                if ((information.FileAttributes & (FILE_ATTRIBUTE_REPARSE_POINT | FILE_ATTRIBUTE_DIRECTORY)) != 0)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_TEXT_CREATE_TYPE_INVALID path=" + expectedPath +
                        " attributes=" + information.FileAttributes);
                }
                string identity = ReadPhysicalIdentity(created, expectedPath);
                string fileId128 = ReadPhysicalFileId128(created, expectedPath);
                stream = new FileStream(created, FileAccess.ReadWrite, 4096, false);
                created = null;
                stream.Write(bytes, 0, bytes.Length);
                stream.Flush(true);
                stream.Position = 0;
                byte[] digest;
                using (SHA256 sha = SHA256.Create()) digest = sha.ComputeHash(stream);
                string actualSha256 = BitConverter.ToString(digest).Replace("-", String.Empty);
                if (!actualSha256.Equals(expectedSha256, StringComparison.OrdinalIgnoreCase) ||
                    stream.Length != bytes.Length)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_TEXT_CREATE_READBACK_MISMATCH path=" + expectedPath +
                        " expected_length=" + bytes.Length + " actual_length=" + stream.Length +
                        " expected_sha256=" + expectedSha256 + " actual_sha256=" + actualSha256);
                }
                return new PhysicalFileReadback
                {
                    Length = bytes.Length,
                    Sha256 = actualSha256,
                    Identity = identity,
                    FileId128 = fileId128
                };
            }
            finally
            {
                if (stream != null) stream.Dispose();
                else if (created != null) created.Dispose();
                DisposeHandles(pins);
            }
        }

        public static PhysicalPathState GetPhysicalEntryRelativeState(
            string parentPath,
