        private static PhysicalPathState GetPhysicalEntryRelativeStateCore(
            string parentPath,
            string[] expectedParentPaths,
            string[] expectedParentFileIds128,
            string leafName,
            bool directory,
            bool enumeratedLeaf,
            long maximumLength,
            bool exclusiveContentRead)
        {
            if (enumeratedLeaf) ValidateEnumeratedLeafName(leafName, "enumerated_relative_state");
            else ValidateLeafName(leafName, "relative_state");
            string parentFull = NormalizeDirectoryPath(parentPath);
            string expectedPath = Path.GetFullPath(Path.Combine(parentFull, leafName));
            List<SafeFileHandle> pins = enumeratedLeaf
                ? OpenPinnedPhysicalEnumeratedDirectoryChainV2(
                    parentFull,
                    expectedParentPaths,
                    expectedParentFileIds128)
                : OpenPinnedPhysicalDirectoryChainV2(
                    parentFull,
                    expectedParentPaths,
                    expectedParentFileIds128);
            SafeFileHandle handle = null;
            FileStream stream = null;
            try
            {
                try
                {
                    handle = enumeratedLeaf
                        ? OpenEnumeratedRelativeEntry(
                            pins[pins.Count - 1],
                            leafName,
                            FILE_READ_ATTRIBUTES | (directory ? FILE_LIST_DIRECTORY : GENERIC_READ),
                            exclusiveContentRead ? FILE_SHARE_READ : FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
                            NT_FILE_OPEN,
                            directory,
                            false)
                        : OpenRelativeEntry(
                            pins[pins.Count - 1],
                            leafName,
                            FILE_READ_ATTRIBUTES | (directory ? FILE_LIST_DIRECTORY : GENERIC_READ),
                            FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
                            NT_FILE_OPEN,
                            directory,
                            false);
                }
                catch (Win32Exception error)
                {
                    if (error.NativeErrorCode == 2 || error.NativeErrorCode == 3)
                    {
                        return new PhysicalPathState
                        {
                            Exists = false,
                            Path = expectedPath,
                            IsDirectory = directory,
                            LinkCount = 0,
                            Length = 0,
                            Sha256 = String.Empty,
                            Identity = String.Empty,
                            FileId128 = String.Empty
                        };
                    }
                    throw;
                }
                FILE_ATTRIBUTE_TAG_INFO information = ReadPhysicalAttributes(handle, expectedPath);
                BY_HANDLE_FILE_INFORMATION linkInformation;
                if (!GetFileInformationByHandle(handle, out linkInformation))
                {
                    int error = Marshal.GetLastWin32Error();
                    throw new Win32Exception(
                        error,
                        "SYNAPSE_PHYSICAL_RELATIVE_STATE_LINK_READ_FAILED path=" + expectedPath +
                        " win32=" + error);
                }
                bool actualDirectory = (information.FileAttributes & FILE_ATTRIBUTE_DIRECTORY) != 0;
                string finalPath = Path.GetFullPath(ReadFinalPath(handle, expectedPath)).TrimEnd(
                    Path.DirectorySeparatorChar,
                    Path.AltDirectorySeparatorChar);
                if ((information.FileAttributes & FILE_ATTRIBUTE_REPARSE_POINT) != 0 ||
                    actualDirectory != directory ||
                    linkInformation.NumberOfLinks != 1 ||
                    !finalPath.Equals(expectedPath.TrimEnd(Path.DirectorySeparatorChar), StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_RELATIVE_STATE_IDENTITY_MISMATCH path=" + expectedPath +
                        " final=" + finalPath + " expected_directory=" + directory +
                        " actual_directory=" + actualDirectory + " link_count=" +
                        linkInformation.NumberOfLinks + " attributes=" + information.FileAttributes);
                }
                RequireNoNamedDataStreams(handle, expectedPath);
                PhysicalPathState result = new PhysicalPathState
                {
                    Exists = true,
                    Path = finalPath,
                    IsDirectory = actualDirectory,
                    LinkCount = linkInformation.NumberOfLinks,
                    Identity = ReadPhysicalIdentity(handle, expectedPath),
                    FileId128 = ReadPhysicalFileId128(handle, expectedPath),
                    Length = 0,
                    Sha256 = String.Empty
                };
                if (!directory)
                {
                    stream = new FileStream(handle, FileAccess.Read, 65536, false);
                    handle = null;
                    if (maximumLength >= 0 && stream.Length > maximumLength)
                    {
                        throw new InvalidOperationException(
                            "SYNAPSE_PHYSICAL_ENUMERATED_FILE_LENGTH_BOUND_EXCEEDED path=" + expectedPath +
                            " length=" + stream.Length + " maximum_length=" + maximumLength);
                    }
                    byte[] digest;
                    using (SHA256 sha = SHA256.Create()) digest = sha.ComputeHash(stream);
                    result.Length = stream.Length;
                    result.Sha256 = BitConverter.ToString(digest).Replace("-", String.Empty);
                }
                return result;
            }
            finally
            {
                if (stream != null) stream.Dispose();
                else if (handle != null) handle.Dispose();
                DisposeHandles(pins);
            }
        }

        public static PhysicalTextReadback ReadPhysicalUtf8TextFileRelative(
            string parentPath,
            string[] expectedParentPaths,
            string[] expectedParentFileIds128,
            string leafName,
            string expectedFileId128,
            int maxBytes)
        {
            if (maxBytes < 1) throw new ArgumentOutOfRangeException("maxBytes");
            ValidateLeafName(leafName, "relative_text_read");
            string parentFull = NormalizeDirectoryPath(parentPath);
            string expectedPath = Path.GetFullPath(Path.Combine(parentFull, leafName));
            List<SafeFileHandle> pins = OpenPinnedPhysicalDirectoryChainV2(
                parentFull,
                expectedParentPaths,
                expectedParentFileIds128);
            SafeFileHandle handle = null;
            FileStream stream = null;
            try
            {
                // Share WRITE/DELETE as well as READ. These authority files
                // (gate-current.json, roster.json) are read back while the
                // live broker still holds its own write handle open, and a
                // FILE_SHARE_READ-only open then fails the whole deployment
                // with STATUS_SHARING_VIOLATION (0xC0000043) purely on
                // timing. Widening the share mode costs no integrity: the
                // caller pins expected_file_id_128 and the identity/length
                // checks below still fail closed on anything unexpected, and
                // published generations are rename-swapped rather than
                // mutated in place, so a pinned file id is write-once.
                handle = OpenRelativeEntry(
                    pins[pins.Count - 1],
                    leafName,
                    GENERIC_READ | FILE_READ_ATTRIBUTES,
                    FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
                    NT_FILE_OPEN,
                    false,
                    false);
                FILE_ATTRIBUTE_TAG_INFO information = ReadPhysicalAttributes(handle, expectedPath);
                BY_HANDLE_FILE_INFORMATION linkInformation;
                if (!GetFileInformationByHandle(handle, out linkInformation))
                {
                    int error = Marshal.GetLastWin32Error();
                    throw new Win32Exception(
                        error,
                        "SYNAPSE_PHYSICAL_RELATIVE_TEXT_LINK_READ_FAILED path=" + expectedPath +
                        " win32=" + error);
                }
                string finalPath = Path.GetFullPath(ReadFinalPath(handle, expectedPath));
                string fileId128 = ReadPhysicalFileId128(handle, expectedPath);
                if ((information.FileAttributes & (FILE_ATTRIBUTE_REPARSE_POINT | FILE_ATTRIBUTE_DIRECTORY)) != 0 ||
                    linkInformation.NumberOfLinks != 1 ||
                    !finalPath.Equals(expectedPath, StringComparison.OrdinalIgnoreCase) ||
                    String.IsNullOrWhiteSpace(expectedFileId128) ||
                    !fileId128.Equals(expectedFileId128, StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_RELATIVE_TEXT_IDENTITY_MISMATCH path=" + expectedPath +
                        " final=" + finalPath + " expected_file_id_128=" + expectedFileId128 +
                        " actual_file_id_128=" + fileId128 + " link_count=" +
                        linkInformation.NumberOfLinks + " attributes=" + information.FileAttributes);
                }
                stream = new FileStream(handle, FileAccess.Read, 65536, false);
                handle = null;
                if (stream.Length < 0 || stream.Length > maxBytes)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_RELATIVE_TEXT_LENGTH_INVALID path=" + expectedPath +
                        " length=" + stream.Length + " max_bytes=" + maxBytes);
                }
                byte[] bytes = new byte[(int)stream.Length];
                int offset = 0;
                while (offset < bytes.Length)
                {
                    int read = stream.Read(bytes, offset, bytes.Length - offset);
                    if (read == 0) throw new EndOfStreamException(
                        "SYNAPSE_PHYSICAL_RELATIVE_TEXT_SHORT_READ path=" + expectedPath);
                    offset += read;
                }
                byte[] digest;
                using (SHA256 sha = SHA256.Create()) digest = sha.ComputeHash(bytes);
                return new PhysicalTextReadback
                {
                    Length = bytes.Length,
                    Sha256 = BitConverter.ToString(digest).Replace("-", String.Empty),
                    Identity = ReadPhysicalIdentity(stream.SafeFileHandle, expectedPath),
                    FileId128 = fileId128,
                    Content = new UTF8Encoding(false, true).GetString(bytes)
                };
            }
            finally
            {
                if (stream != null) stream.Dispose();
                else if (handle != null) handle.Dispose();
                DisposeHandles(pins);
            }
        }

        public static PhysicalEntryReadback RenamePhysicalEntryRelativeNoReplace(
            string sourceParentPath,
            string[] expectedSourceParentPaths,
            string[] expectedSourceParentFileIds128,
            string sourceLeafName,
            string expectedSourceFileId128,
            string destinationParentPath,
            string[] expectedDestinationParentPaths,
            string[] expectedDestinationParentFileIds128,
            string destinationLeafName,
            bool directory,
            string expectedSha256,
            long expectedLength)
        {
            ValidateLeafName(sourceLeafName, "rename_source");
            ValidateLeafName(destinationLeafName, "rename_destination");
            string sourceParentFull = NormalizeDirectoryPath(sourceParentPath);
            string destinationParentFull = NormalizeDirectoryPath(destinationParentPath);
            string sourcePath = Path.GetFullPath(Path.Combine(sourceParentFull, sourceLeafName));
            string destinationPath = Path.GetFullPath(Path.Combine(destinationParentFull, destinationLeafName));
            List<SafeFileHandle> sourcePins = OpenPinnedPhysicalDirectoryChainV2(
                sourceParentFull,
                expectedSourceParentPaths,
                expectedSourceParentFileIds128);
            List<SafeFileHandle> destinationPins = null;
            SafeFileHandle source = null;
            FileStream sourceStream = null;
            IntPtr renameBuffer = IntPtr.Zero;
            try
            {
                destinationPins = OpenPinnedPhysicalDirectoryChainV2(
                    destinationParentFull,
                    expectedDestinationParentPaths,
                    expectedDestinationParentFileIds128);
                source = OpenRelativeEntry(
                    sourcePins[sourcePins.Count - 1],
                    sourceLeafName,
                    DELETE | FILE_READ_ATTRIBUTES | (directory ? FILE_LIST_DIRECTORY : GENERIC_READ),
                    FILE_SHARE_READ,
                    NT_FILE_OPEN,
                    directory,
                    true);
                FILE_ATTRIBUTE_TAG_INFO sourceInformation = ReadPhysicalAttributes(source, sourcePath);
                BY_HANDLE_FILE_INFORMATION sourceLinkInformation;
                if (!GetFileInformationByHandle(source, out sourceLinkInformation))
                {
                    int error = Marshal.GetLastWin32Error();
                    throw new Win32Exception(
                        error,
                        "SYNAPSE_PHYSICAL_RELATIVE_RENAME_LINK_READ_FAILED source=" + sourcePath +
                        " win32=" + error);
                }
                bool sourceIsDirectory = (sourceInformation.FileAttributes & FILE_ATTRIBUTE_DIRECTORY) != 0;
                string sourceFinal = Path.GetFullPath(ReadFinalPath(source, sourcePath)).TrimEnd(
                    Path.DirectorySeparatorChar,
                    Path.AltDirectorySeparatorChar);
                string sourceFileId128 = ReadPhysicalFileId128(source, sourcePath);
                if ((sourceInformation.FileAttributes & FILE_ATTRIBUTE_REPARSE_POINT) != 0 ||
                    sourceIsDirectory != directory ||
                    sourceLinkInformation.NumberOfLinks != 1 ||
                    !sourceFinal.Equals(sourcePath.TrimEnd(Path.DirectorySeparatorChar), StringComparison.OrdinalIgnoreCase) ||
                    String.IsNullOrWhiteSpace(expectedSourceFileId128) ||
                    !sourceFileId128.Equals(expectedSourceFileId128, StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_RELATIVE_RENAME_SOURCE_MISMATCH source=" + sourcePath +
                        " final=" + sourceFinal + " expected_file_id_128=" + expectedSourceFileId128 +
                        " actual_file_id_128=" + sourceFileId128 + " directory=" + directory +
                        " link_count=" + sourceLinkInformation.NumberOfLinks +
                        " attributes=" + sourceInformation.FileAttributes);
                }

                if (!directory)
                {
                    if (String.IsNullOrWhiteSpace(expectedSha256) || expectedLength < 0)
                    {
                        throw new InvalidOperationException(
                            "SYNAPSE_PHYSICAL_RELATIVE_RENAME_CONTENT_IDENTITY_MISSING source=" + sourcePath);
                    }
                    sourceStream = new FileStream(source, FileAccess.Read, 65536, false);
                    byte[] sourceDigest;
                    using (SHA256 sha = SHA256.Create()) sourceDigest = sha.ComputeHash(sourceStream);
                    string sourceSha256 = BitConverter.ToString(sourceDigest).Replace("-", String.Empty);
                    long sourceLength = sourceStream.Length;
                    sourceStream.Position = 0;
                    if (!sourceSha256.Equals(expectedSha256, StringComparison.OrdinalIgnoreCase) ||
                        sourceLength != expectedLength)
                    {
                        throw new InvalidOperationException(
                            "SYNAPSE_PHYSICAL_RELATIVE_RENAME_CONTENT_MISMATCH source=" + sourcePath +
                            " expected_sha256=" + expectedSha256 + " actual_sha256=" + sourceSha256 +
                            " expected_length=" + expectedLength + " actual_length=" + sourceLength);
                    }
                }

                // SetFileInformationByHandle(FileRenameInfo) requires
                // RootDirectory to be NULL.  Unlike NtSetInformationFile, the
                // Win32 surface does not accept a directory handle as the
                // relative-name root; use the already-normalized full path.
                char[] destinationName = destinationPath.ToCharArray();
                int fileNameLength = checked(destinationName.Length * 2);
                int fileNameOffset = checked((int)Marshal.OffsetOf(
                    typeof(FILE_RENAME_INFO_HEADER),
                    "FileNameLength") + sizeof(uint));
                // Although FileNameLength excludes a terminator, the Win32
                // implementation reads the variable member as a WCHAR string
                // on this supported host.  Keep an explicit zero WCHAR beyond
                // the counted bytes so it cannot consume adjacent heap data.
                int bufferSize = Math.Max(
                    Marshal.SizeOf(typeof(FILE_RENAME_INFO_HEADER)),
                    checked(fileNameOffset + fileNameLength + sizeof(char)));
                renameBuffer = Marshal.AllocHGlobal(bufferSize);
                for (int index = 0; index < bufferSize; index++) Marshal.WriteByte(renameBuffer, index, 0);
                Marshal.WriteInt32(renameBuffer, 0, 0);
                int rootDirectoryOffset = checked((int)Marshal.OffsetOf(
                    typeof(FILE_RENAME_INFO_HEADER),
                    "RootDirectory"));
                int fileNameLengthOffset = checked((int)Marshal.OffsetOf(
                    typeof(FILE_RENAME_INFO_HEADER),
                    "FileNameLength"));
                Marshal.WriteIntPtr(renameBuffer, rootDirectoryOffset, IntPtr.Zero);
                Marshal.WriteInt32(renameBuffer, fileNameLengthOffset, fileNameLength);
                Marshal.Copy(destinationName, 0, IntPtr.Add(renameBuffer, fileNameOffset), destinationName.Length);
                if (!SetFileInformationByHandleBuffer(
                    source,
                    FILE_RENAME_INFO_CLASS,
                    renameBuffer,
                    (uint)bufferSize))
                {
                    int error = Marshal.GetLastWin32Error();
                    throw new Win32Exception(
                        error,
                        "SYNAPSE_PHYSICAL_RELATIVE_RENAME_FAILED source=" + sourcePath +
                        " destination=" + destinationPath + " replace=false win32=" + error);
                }

                string destinationFinal = Path.GetFullPath(ReadFinalPath(source, destinationPath)).TrimEnd(
                    Path.DirectorySeparatorChar,
                    Path.AltDirectorySeparatorChar);
                string destinationFileId128 = ReadPhysicalFileId128(source, destinationPath);
                if (!destinationFinal.Equals(destinationPath.TrimEnd(Path.DirectorySeparatorChar), StringComparison.OrdinalIgnoreCase) ||
                    !destinationFileId128.Equals(sourceFileId128, StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_RELATIVE_RENAME_READBACK_MISMATCH destination=" + destinationPath +
                        " final=" + destinationFinal + " expected_file_id_128=" + sourceFileId128 +
                        " actual_file_id_128=" + destinationFileId128);
                }
                return new PhysicalEntryReadback
                {
                    Path = destinationFinal,
                    Identity = ReadPhysicalIdentity(source, destinationPath),
                    FileId128 = destinationFileId128,
                    IsDirectory = directory
                };
            }
            finally
            {
                if (renameBuffer != IntPtr.Zero) Marshal.FreeHGlobal(renameBuffer);
                if (sourceStream != null) sourceStream.Dispose();
                else if (source != null) source.Dispose();
                DisposeHandles(destinationPins);
                DisposeHandles(sourcePins);
            }
        }

        public static void DeletePhysicalEntryRelative(
            string parentPath,
            string[] expectedParentPaths,
            string[] expectedParentFileIds128,
            string leafName,
            string expectedFileId128,
            bool directory,
            string expectedSha256,
            long expectedLength)
        {
            DeletePhysicalEntryRelativeCore(
                parentPath,
                expectedParentPaths,
                expectedParentFileIds128,
                leafName,
                expectedFileId128,
                directory,
                expectedSha256,
                expectedLength,
                false);
        }

        public static void DeletePhysicalEnumeratedEntryRelative(
            string parentPath,
            string[] expectedParentPaths,
            string[] expectedParentFileIds128,
            string leafName,
            string expectedFileId128,
            bool directory,
            string expectedSha256,
            long expectedLength)
        {
            DeletePhysicalEntryRelativeCore(
                parentPath,
                expectedParentPaths,
                expectedParentFileIds128,
                leafName,
                expectedFileId128,
                directory,
                expectedSha256,
                expectedLength,
                true);
        }

        private static void DeletePhysicalEntryRelativeCore(
            string parentPath,
            string[] expectedParentPaths,
            string[] expectedParentFileIds128,
            string leafName,
            string expectedFileId128,
            bool directory,
            string expectedSha256,
            long expectedLength,
            bool enumeratedLeaf)
        {
            if (enumeratedLeaf) ValidateEnumeratedLeafName(leafName, "delete_enumerated_relative");
            else ValidateLeafName(leafName, "delete_relative");
            string parentFull = NormalizeDirectoryPath(parentPath);
            string path = Path.GetFullPath(Path.Combine(parentFull, leafName));
            List<SafeFileHandle> pins = enumeratedLeaf
                ? OpenPinnedPhysicalEnumeratedDirectoryChainV2(
                    parentFull,
                    expectedParentPaths,
                    expectedParentFileIds128)
                : OpenPinnedPhysicalDirectoryChainV2(
                    parentFull,
                    expectedParentPaths,
                    expectedParentFileIds128);
            SafeFileHandle target = null;
            FileStream targetStream = null;
            try
            {
                target = enumeratedLeaf
                    ? OpenEnumeratedRelativeEntry(
                        pins[pins.Count - 1],
                        leafName,
                        DELETE | FILE_READ_ATTRIBUTES | (directory ? FILE_LIST_DIRECTORY : GENERIC_READ),
                        FILE_SHARE_READ,
                        NT_FILE_OPEN,
                        directory,
                        true)
                    : OpenRelativeEntry(
                        pins[pins.Count - 1],
                        leafName,
                        DELETE | FILE_READ_ATTRIBUTES | (directory ? FILE_LIST_DIRECTORY : GENERIC_READ),
                        FILE_SHARE_READ,
                        NT_FILE_OPEN,
                        directory,
                        true);
                FILE_ATTRIBUTE_TAG_INFO information = ReadPhysicalAttributes(target, path);
                BY_HANDLE_FILE_INFORMATION linkInformation;
                if (!GetFileInformationByHandle(target, out linkInformation))
                {
                    int error = Marshal.GetLastWin32Error();
                    throw new Win32Exception(error, "SYNAPSE_PHYSICAL_RELATIVE_DELETE_LINK_READ_FAILED path=" + path + " win32=" + error);
                }
                bool isDirectory = (information.FileAttributes & FILE_ATTRIBUTE_DIRECTORY) != 0;
                string finalPath = Path.GetFullPath(ReadFinalPath(target, path)).TrimEnd(
                    Path.DirectorySeparatorChar,
                    Path.AltDirectorySeparatorChar);
                string fileId128 = ReadPhysicalFileId128(target, path);
                if ((information.FileAttributes & FILE_ATTRIBUTE_REPARSE_POINT) != 0 ||
                    isDirectory != directory ||
                    linkInformation.NumberOfLinks != 1 ||
                    !finalPath.Equals(path.TrimEnd(Path.DirectorySeparatorChar), StringComparison.OrdinalIgnoreCase) ||
                    !fileId128.Equals(expectedFileId128, StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_RELATIVE_DELETE_MISMATCH path=" + path +
                        " final=" + finalPath + " expected_file_id_128=" + expectedFileId128 +
                        " actual_file_id_128=" + fileId128 + " directory=" + directory +
                        " link_count=" + linkInformation.NumberOfLinks + " attributes=" + information.FileAttributes);
                }
                if (!directory)
                {
                    if (String.IsNullOrWhiteSpace(expectedSha256) || expectedLength < 0)
                        throw new InvalidOperationException("SYNAPSE_PHYSICAL_RELATIVE_DELETE_CONTENT_IDENTITY_MISSING path=" + path);
                    targetStream = new FileStream(target, FileAccess.Read, 65536, false);
                    long actualLength = targetStream.Length;
                    if (actualLength != expectedLength)
                        throw new InvalidOperationException(
                            "SYNAPSE_PHYSICAL_RELATIVE_DELETE_LENGTH_MISMATCH path=" + path +
                            " expected_length=" + expectedLength + " actual_length=" + actualLength);
                    byte[] digest;
                    using (SHA256 sha = SHA256.Create()) digest = sha.ComputeHash(targetStream);
                    string actualSha256 = BitConverter.ToString(digest).Replace("-", String.Empty);
                    targetStream.Position = 0;
                    if (!actualSha256.Equals(expectedSha256, StringComparison.OrdinalIgnoreCase) || actualLength != expectedLength)
                        throw new InvalidOperationException(
                            "SYNAPSE_PHYSICAL_RELATIVE_DELETE_CONTENT_MISMATCH path=" + path +
                            " expected_sha256=" + expectedSha256 + " actual_sha256=" + actualSha256 +
                            " expected_length=" + expectedLength + " actual_length=" + actualLength);
                }
                RequireNoNamedDataStreams(target, path);
                FILE_DISPOSITION_INFO disposition = new FILE_DISPOSITION_INFO { DeleteFile = 1 };
                if (!SetFileInformationByHandle(
                    target,
                    FILE_DISPOSITION_INFO_CLASS,
                    ref disposition,
                    (uint)Marshal.SizeOf(typeof(FILE_DISPOSITION_INFO))))
                {
                    int error = Marshal.GetLastWin32Error();
                    throw new Win32Exception(
                        error,
                        "SYNAPSE_PHYSICAL_RELATIVE_DELETE_FAILED path=" + path + " win32=" + error);
                }
            }
            finally
            {
                if (targetStream != null) targetStream.Dispose();
                else if (target != null) target.Dispose();
                DisposeHandles(pins);
            }
        }

        public static PhysicalGenerationLease AcquirePhysicalGenerationLease(
            string rootPath,
            string[] expectedRootChainPaths,
            string[] expectedRootChainFileIds128,
            string[] relativeFilePaths,
            string[] expectedFileIds128,
            string[] expectedSha256)
        {
            if (relativeFilePaths == null || expectedFileIds128 == null || expectedSha256 == null ||
                relativeFilePaths.Length != expectedFileIds128.Length ||
                relativeFilePaths.Length != expectedSha256.Length)
            {
                throw new InvalidOperationException(
                    "SYNAPSE_PHYSICAL_GENERATION_LEASE_DESCRIPTOR_COUNT_MISMATCH");
            }
            string rootFull = NormalizeDirectoryPath(rootPath);
            List<SafeFileHandle> rootPins = OpenPinnedPhysicalDirectoryChainV2(
                rootFull,
                expectedRootChainPaths,
                expectedRootChainFileIds128);
            List<IDisposable> held = new List<IDisposable>();
            foreach (SafeFileHandle rootPin in rootPins) held.Add(rootPin);
            SafeFileHandle heldRoot = rootPins[rootPins.Count - 1];
            rootPins = null;
            try
            {
                string rootFileId128 = ReadPhysicalFileId128(
                    heldRoot,
                    rootFull);
                for (int fileIndex = 0; fileIndex < relativeFilePaths.Length; fileIndex++)
                {
                    string relative = relativeFilePaths[fileIndex].Replace('/', Path.DirectorySeparatorChar);
                    if (Path.IsPathRooted(relative))
                        throw new InvalidOperationException(
                            "SYNAPSE_PHYSICAL_GENERATION_LEASE_RELATIVE_PATH_ROOTED path=" + relative);
                    string[] segments = relative.Split(Path.DirectorySeparatorChar);
                    if (segments.Length < 1)
                        throw new InvalidOperationException(
                            "SYNAPSE_PHYSICAL_GENERATION_LEASE_RELATIVE_PATH_EMPTY");
                    SafeFileHandle parent = heldRoot;
                    string currentPath = rootFull;
                    for (int segmentIndex = 0; segmentIndex < segments.Length - 1; segmentIndex++)
                    {
                        ValidateLeafName(segments[segmentIndex], "generation_lease_directory");
                        currentPath = Path.Combine(currentPath, segments[segmentIndex]);
                        SafeFileHandle directoryHandle = OpenRelativeEntry(
                            parent,
                            segments[segmentIndex],
                            FILE_LIST_DIRECTORY | FILE_READ_ATTRIBUTES,
                            FILE_SHARE_READ | FILE_SHARE_WRITE,
                            NT_FILE_OPEN,
                            true,
                            false);
                        PhysicalDirectoryReadback directoryReadback = ReadDirectoryHandle(
                            directoryHandle,
                            currentPath);
                        if (!NormalizeDirectoryPath(directoryReadback.Path).Equals(
                            NormalizeDirectoryPath(currentPath),
                            StringComparison.OrdinalIgnoreCase))
                        {
                            directoryHandle.Dispose();
                            throw new InvalidOperationException(
                                "SYNAPSE_PHYSICAL_GENERATION_LEASE_DIRECTORY_FINAL_PATH_MISMATCH path=" +
                                currentPath + " actual=" + directoryReadback.Path);
                        }
                        held.Add(directoryHandle);
                        parent = directoryHandle;
                    }
                    string leaf = segments[segments.Length - 1];
                    ValidateLeafName(leaf, "generation_lease_file");
                    string filePath = Path.Combine(currentPath, leaf);
                    SafeFileHandle fileHandle = OpenRelativeEntry(
                        parent,
                        leaf,
                        GENERIC_READ | FILE_READ_ATTRIBUTES,
                        FILE_SHARE_READ,
                        NT_FILE_OPEN,
                        false,
                        false);
                    FILE_ATTRIBUTE_TAG_INFO fileInformation = ReadPhysicalAttributes(fileHandle, filePath);
                    string finalPath = Path.GetFullPath(ReadFinalPath(fileHandle, filePath));
                    string fileId128 = ReadPhysicalFileId128(fileHandle, filePath);
                    if ((fileInformation.FileAttributes & (FILE_ATTRIBUTE_REPARSE_POINT | FILE_ATTRIBUTE_DIRECTORY)) != 0 ||
                        !finalPath.Equals(Path.GetFullPath(filePath), StringComparison.OrdinalIgnoreCase) ||
                        !fileId128.Equals(expectedFileIds128[fileIndex], StringComparison.OrdinalIgnoreCase))
                    {
                        fileHandle.Dispose();
                        throw new InvalidOperationException(
                            "SYNAPSE_PHYSICAL_GENERATION_LEASE_FILE_IDENTITY_MISMATCH path=" + filePath +
                            " final=" + finalPath + " expected_file_id_128=" + expectedFileIds128[fileIndex] +
                            " actual_file_id_128=" + fileId128 + " attributes=" + fileInformation.FileAttributes);
                    }
                    FileStream stream = new FileStream(fileHandle, FileAccess.Read, 65536, false);
                    fileHandle = null;
                    byte[] digest;
                    using (SHA256 sha = SHA256.Create()) digest = sha.ComputeHash(stream);
                    string sha256 = BitConverter.ToString(digest).Replace("-", String.Empty);
                    stream.Position = 0;
                    if (!sha256.Equals(expectedSha256[fileIndex], StringComparison.OrdinalIgnoreCase))
                    {
                        stream.Dispose();
                        throw new InvalidOperationException(
                            "SYNAPSE_PHYSICAL_GENERATION_LEASE_FILE_HASH_MISMATCH path=" + filePath +
                            " expected_sha256=" + expectedSha256[fileIndex] + " actual_sha256=" + sha256);
                    }
                    held.Add(stream);
                }
                return new PhysicalGenerationLease(
                    rootFull,
                    rootFileId128,
                    relativeFilePaths.Length,
                    held);
            }
            catch
            {
                for (int index = held.Count - 1; index >= 0; index--) held[index].Dispose();
                throw;
            }
        }

        public static PhysicalEntryReadback GetPhysicalEntryIdentityUnderRoot(
            string rootPath,
            string expectedRootIdentity,
            string entryPath,
            string expectedEntryIdentity,
            bool directory)
        {
            string identity;
            using (SafeFileHandle handle = OpenVerifiedPhysicalEntry(
                rootPath,
                expectedRootIdentity,
                entryPath,
                expectedEntryIdentity,
                directory,
                FILE_READ_ATTRIBUTES,
                false,
                out identity))
            {
                return new PhysicalEntryReadback { Identity = identity, IsDirectory = directory };
            }
        }

        public static PhysicalFileReadback Sha256PhysicalFileUnderRoot(
            string rootPath,
            string expectedRootIdentity,
            string filePath,
            string expectedFileIdentity)
        {
            string identity;
            using (SafeFileHandle handle = OpenVerifiedPhysicalEntry(
                rootPath,
                expectedRootIdentity,
                filePath,
                expectedFileIdentity,
                false,
                GENERIC_READ,
                true,
                out identity))
            using (FileStream stream = new FileStream(handle, FileAccess.Read, 4096, false))
            using (SHA256 sha = SHA256.Create())
            {
                long length = stream.Length;
                byte[] digest = sha.ComputeHash(stream);
                return new PhysicalFileReadback
                {
                    Length = length,
                    Sha256 = BitConverter.ToString(digest).Replace("-", String.Empty),
                    Identity = identity,
                    FileId128 = ReadPhysicalFileId128(handle, filePath)
                };
            }
        }

        public static PhysicalTextReadback ReadUtf8TextFileUnderPhysicalRoot(
            string rootPath,
            string expectedRootIdentity,
            string filePath,
            string expectedFileIdentity,
            int maxBytes)
        {
            if (maxBytes < 1)
            {
                throw new ArgumentOutOfRangeException("maxBytes");
            }
            string identity;
            using (SafeFileHandle handle = OpenVerifiedPhysicalEntry(
                rootPath,
                expectedRootIdentity,
                filePath,
                expectedFileIdentity,
                false,
                GENERIC_READ,
                true,
                out identity))
            using (FileStream stream = new FileStream(handle, FileAccess.Read, 4096, false))
            using (SHA256 sha = SHA256.Create())
            {
                if (stream.Length < 0 || stream.Length > maxBytes)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_TEXT_LENGTH_INVALID path=" + filePath +
                        " length=" + stream.Length + " max_bytes=" + maxBytes);
                }
                byte[] bytes = new byte[(int)stream.Length];
                int offset = 0;
                while (offset < bytes.Length)
                {
                    int read = stream.Read(bytes, offset, bytes.Length - offset);
                    if (read == 0)
                    {
                        throw new EndOfStreamException(
                            "SYNAPSE_PHYSICAL_TEXT_SHORT_READ path=" + filePath +
                            " expected=" + bytes.Length + " actual=" + offset);
                    }
                    offset += read;
                }
                byte[] digest = sha.ComputeHash(bytes);
                string content = new UTF8Encoding(false, true).GetString(bytes);
                return new PhysicalTextReadback
                {
                    Length = bytes.Length,
                    Sha256 = BitConverter.ToString(digest).Replace("-", String.Empty),
                    Identity = identity,
                    FileId128 = ReadPhysicalFileId128(handle, filePath),
                    Content = content
                };
            }
        }

        public static PhysicalFileReadback InstallNewUtf8TextUnderPhysicalRoot(
            string rootPath,
            string expectedRootIdentity,
            string leafName,
            string content)
        {
            if (String.IsNullOrWhiteSpace(leafName) ||
                !Path.GetFileName(leafName).Equals(leafName, StringComparison.Ordinal) ||
                leafName.Equals(".", StringComparison.Ordinal) ||
                leafName.Equals("..", StringComparison.Ordinal))
            {
                throw new ArgumentException(
                    "SYNAPSE_PHYSICAL_TEXT_LEAF_INVALID leaf=" + leafName);
            }
            string rootFull = NormalizeDirectoryPath(rootPath);
            string destinationPath = Path.Combine(rootFull, leafName);
            string tempPath = Path.Combine(
                rootFull,
                "." + leafName + ".tmp-" + System.Diagnostics.Process.GetCurrentProcess().Id +
                "-" + Guid.NewGuid().ToString("N"));
            byte[] expectedBytes = new UTF8Encoding(false, true).GetBytes(content ?? String.Empty);
            string expectedSha256;
            using (SHA256 sha = SHA256.Create())
            {
                expectedSha256 = BitConverter.ToString(sha.ComputeHash(expectedBytes)).Replace("-", String.Empty);
            }

            List<SafeFileHandle> directoryPins = null;
            string tempIdentity = null;
            try
            {
                directoryPins = OpenPinnedPhysicalDirectoryChain(rootFull, expectedRootIdentity);
                SafeFileHandle tempHandle = CreateFile(
                    tempPath,
                    GENERIC_READ | GENERIC_WRITE,
                    FILE_SHARE_READ,
                    IntPtr.Zero,
                    CREATE_NEW,
                    FILE_ATTRIBUTE_NORMAL | FILE_FLAG_WRITE_THROUGH | FILE_FLAG_OPEN_REPARSE_POINT,
                    IntPtr.Zero);
                if (tempHandle.IsInvalid)
                {
                    int error = Marshal.GetLastWin32Error();
                    tempHandle.Dispose();
                    throw new Win32Exception(
                        error,
                        "SYNAPSE_PHYSICAL_TEXT_TEMP_CREATE_FAILED path=" + tempPath + " win32=" + error);
                }
                using (FileStream stream = new FileStream(tempHandle, FileAccess.ReadWrite, 4096, false))
                {
                    FILE_ATTRIBUTE_TAG_INFO tempInformation = ReadPhysicalAttributes(tempHandle, tempPath);
                    if ((tempInformation.FileAttributes & FILE_ATTRIBUTE_REPARSE_POINT) != 0 ||
                        (tempInformation.FileAttributes & FILE_ATTRIBUTE_DIRECTORY) != 0)
                    {
                        throw new InvalidOperationException(
                            "SYNAPSE_PHYSICAL_TEXT_TEMP_TYPE_INVALID path=" + tempPath +
                            " attributes=" + tempInformation.FileAttributes);
                    }
                    tempIdentity = ReadPhysicalIdentity(tempHandle, tempPath);
                    stream.Write(expectedBytes, 0, expectedBytes.Length);
                    stream.Flush(true);
                }
                if (!MoveFileEx(tempPath, destinationPath, MOVEFILE_WRITE_THROUGH))
                {
                    int error = Marshal.GetLastWin32Error();
                    throw new Win32Exception(
                        error,
                        "SYNAPSE_PHYSICAL_TEXT_INSTALL_NEW_FAILED source=" + tempPath +
                        " destination=" + destinationPath + " win32=" + error);
                }
                PhysicalFileReadback readback = Sha256PhysicalFileUnderRoot(
                    rootFull,
                    expectedRootIdentity,
                    destinationPath,
                    tempIdentity);
                if (readback.Length != expectedBytes.Length ||
                    !readback.Sha256.Equals(expectedSha256, StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_TEXT_READBACK_MISMATCH path=" + destinationPath +
                        " expected_length=" + expectedBytes.Length +
                        " actual_length=" + readback.Length +
                        " expected_sha256=" + expectedSha256 +
                        " actual_sha256=" + readback.Sha256);
                }
                return readback;
            }
            finally
            {
                if (!String.IsNullOrWhiteSpace(tempIdentity))
                {
                    try
                    {
                        DeletePhysicalEntryUnderRoot(
                            rootFull,
                            expectedRootIdentity,
                            tempPath,
                            tempIdentity,
                            false);
                    }
                    catch { }
                }
                DisposeHandles(directoryPins);
            }
        }

        public static void DeletePhysicalEntryUnderRoot(
            string rootPath,
            string expectedRootIdentity,
            string entryPath,
            string expectedEntryIdentity,
            bool directory)
        {
            DeletePhysicalEntryUnderRootCore(
                rootPath,
                expectedRootIdentity,
                entryPath,
                expectedEntryIdentity,
                String.Empty,
                directory);
        }

        public static void DeletePhysicalFileUnderRoot(
            string rootPath,
            string expectedRootIdentity,
            string entryPath,
            string expectedEntryIdentity,
            string expectedFileId128)
        {
            if (String.IsNullOrWhiteSpace(expectedFileId128))
            {
                throw new ArgumentException(
                    "SYNAPSE_PHYSICAL_HANDLE_DELETE_FILE_ID_MISSING path=" + entryPath);
            }
            DeletePhysicalEntryUnderRootCore(
                rootPath,
                expectedRootIdentity,
                entryPath,
                expectedEntryIdentity,
                expectedFileId128,
                false);
        }

        private static void DeletePhysicalEntryUnderRootCore(
            string rootPath,
            string expectedRootIdentity,
            string entryPath,
            string expectedEntryIdentity,
            string expectedFileId128,
            bool directory)
        {
            string rootFull = NormalizeDirectoryPath(rootPath);
            string entryFull = Path.GetFullPath(entryPath).TrimEnd(
                Path.DirectorySeparatorChar,
                Path.AltDirectorySeparatorChar);
            bool deletesRoot = entryFull.Equals(rootFull, StringComparison.OrdinalIgnoreCase);
            string pinRoot;
            string pinIdentity;
            if (deletesRoot)
            {
                pinRoot = NormalizeDirectoryPath(Path.GetDirectoryName(rootFull));
                pinIdentity = GetPhysicalDirectoryIdentity(pinRoot);
            }
            else
            {
                pinRoot = NormalizeDirectoryPath(Path.GetDirectoryName(entryFull));
                pinIdentity = pinRoot.Equals(rootFull, StringComparison.OrdinalIgnoreCase)
                    ? expectedRootIdentity
                    : GetPhysicalDirectoryIdentity(pinRoot);
            }
            List<SafeFileHandle> rootPins = OpenPinnedPhysicalDirectoryChain(pinRoot, pinIdentity);
            SafeFileHandle handle = null;
            try
            {
                string openedIdentity;
                if (deletesRoot)
                {
                    handle = OpenPhysicalHandleWithShare(
                        entryFull,
                        DELETE | FILE_READ_ATTRIBUTES,
                        FILE_SHARE_READ);
                    FILE_ATTRIBUTE_TAG_INFO information = ReadPhysicalAttributes(handle, entryFull);
                    bool isDirectory = (information.FileAttributes & FILE_ATTRIBUTE_DIRECTORY) != 0;
                    if ((information.FileAttributes & FILE_ATTRIBUTE_REPARSE_POINT) != 0 ||
                        isDirectory != directory)
                    {
                        throw new InvalidOperationException(
                            "SYNAPSE_PHYSICAL_HANDLE_DELETE_ROOT_TYPE_MISMATCH root=" + rootFull +
                            " attributes=" + information.FileAttributes +
                            " expected_directory=" + directory);
                    }
                    openedIdentity = ReadIdentityInExpectedProjection(
                        handle,
                        entryFull,
                        expectedEntryIdentity);
                }
                else
                {
                    handle = OpenVerifiedPhysicalEntry(
                        rootFull,
                        expectedRootIdentity,
                        entryFull,
                        expectedEntryIdentity,
                        directory,
                        DELETE,
                        true,
                        out openedIdentity);
                }
                string finalPath = Path.GetFullPath(ReadFinalPath(handle, entryFull)).TrimEnd(
                    Path.DirectorySeparatorChar,
                    Path.AltDirectorySeparatorChar);
                string finalIdentity = ReadIdentityInExpectedProjection(
                    handle,
                    entryFull,
                    expectedEntryIdentity);
                string finalFileId128 = directory ? String.Empty : ReadPhysicalFileId128(handle, entryFull);
                if (!finalPath.Equals(entryFull, StringComparison.OrdinalIgnoreCase) ||
                    !finalIdentity.Equals(openedIdentity, StringComparison.OrdinalIgnoreCase) ||
                    !finalIdentity.Equals(expectedEntryIdentity, StringComparison.OrdinalIgnoreCase) ||
                    (!String.IsNullOrWhiteSpace(expectedFileId128) &&
                        !finalFileId128.Equals(expectedFileId128, StringComparison.OrdinalIgnoreCase)))
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_PHYSICAL_HANDLE_DELETE_BOUNDARY_MOVED root=" + rootFull +
                        " path=" + entryFull +
                        " actual_final=" + finalPath +
                        " expected_identity=" + expectedEntryIdentity +
                        " opened_identity=" + openedIdentity +
                        " actual_identity=" + finalIdentity +
                        " expected_file_id_128=" + expectedFileId128 +
                        " actual_file_id_128=" + finalFileId128);
                }
                FILE_DISPOSITION_INFO disposition = new FILE_DISPOSITION_INFO { DeleteFile = 1 };
                if (!SetFileInformationByHandle(
                    handle,
                    FILE_DISPOSITION_INFO_CLASS,
                    ref disposition,
                    (uint)Marshal.SizeOf(typeof(FILE_DISPOSITION_INFO))))
                {
                    int error = Marshal.GetLastWin32Error();
                    throw new Win32Exception(
                        error,
                        "SYNAPSE_PHYSICAL_HANDLE_DELETE_FAILED root=" + rootFull +
                        " path=" + entryFull + " directory=" + directory + " win32=" + error);
                }
            }
            finally
            {
                if (handle != null) handle.Dispose();
                DisposeHandles(rootPins);
            }
        }
    }
}
"@
}

function Write-SynapseAtomicUtf8TextFile {
    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][AllowEmptyString()][string]$Content,
        [Parameter(Mandatory=$true)][string]$Purpose
    )

    $resolvedPath = [System.IO.Path]::GetFullPath($Path)
    $parent = Split-Path -Parent $resolvedPath
    $encoding = [System.Text.UTF8Encoding]::new($false, $true)
    $expectedBytes = $encoding.GetBytes($Content)
    $tempPath = Join-Path $parent (".{0}.tmp-{1}-{2}" -f ([System.IO.Path]::GetFileName($resolvedPath)), $PID, ([Guid]::NewGuid().ToString('N')))
    $stream = $null
    try {
        New-Item -ItemType Directory -Force -Path $parent -ErrorAction Stop | Out-Null
        $parentItem = Get-Item -LiteralPath $parent -Force -ErrorAction Stop
        if (-not $parentItem.PSIsContainer -or ($parentItem.Attributes -band [System.IO.FileAttributes]::ReparsePoint)) {
            throw "SYNAPSE_ATOMIC_TEXT_PARENT_INVALID purpose=$Purpose path=$parent attributes=$($parentItem.Attributes) remediation=use a real local setup-owned directory"
        }
        $destinationExisted = Test-Path -LiteralPath $resolvedPath
        if ($destinationExisted) {
            $destinationItem = Get-Item -LiteralPath $resolvedPath -Force -ErrorAction Stop
            if ($destinationItem.PSIsContainer -or ($destinationItem.Attributes -band [System.IO.FileAttributes]::ReparsePoint)) {
                throw "SYNAPSE_ATOMIC_TEXT_DESTINATION_INVALID purpose=$Purpose path=$resolvedPath attributes=$($destinationItem.Attributes) remediation=replace the unexpected directory/reparse point with a regular setup-owned file"
            }
        }
        $stream = [System.IO.FileStream]::new(
            $tempPath,
            [System.IO.FileMode]::CreateNew,
            [System.IO.FileAccess]::Write,
            [System.IO.FileShare]::None,
            4096,
            [System.IO.FileOptions]::WriteThrough)
        $stream.Write($expectedBytes, 0, $expectedBytes.Length)
        $stream.Flush($true)
        $stream.Dispose()
        $stream = $null
        Ensure-SynapseAtomicFileType
        if ($destinationExisted) {
            [SynapseSetup.AtomicFileV2]::ReplaceWriteThrough($tempPath, $resolvedPath)
        } else {
            [SynapseSetup.AtomicFileV2]::InstallNewWriteThrough($tempPath, $resolvedPath)
        }
        if (Test-Path -LiteralPath $tempPath) {
            throw "SYNAPSE_ATOMIC_TEXT_TEMP_RETAINED purpose=$Purpose path=$tempPath remediation=repair atomic rename semantics before retrying"
        }
        $readbackItem = Get-Item -LiteralPath $resolvedPath -Force -ErrorAction Stop
        if ($readbackItem.PSIsContainer -or ($readbackItem.Attributes -band [System.IO.FileAttributes]::ReparsePoint)) {
            throw "SYNAPSE_ATOMIC_TEXT_READBACK_TYPE_INVALID purpose=$Purpose path=$resolvedPath attributes=$($readbackItem.Attributes) remediation=repair concurrent filesystem mutation"
        }
        if ([uint64]$readbackItem.Length -ne [uint64]$expectedBytes.Length) {
            throw "SYNAPSE_ATOMIC_TEXT_READBACK_LENGTH_MISMATCH purpose=$Purpose path=$resolvedPath expected=$($expectedBytes.Length) actual=$($readbackItem.Length) remediation=repair concurrent filesystem mutation or storage durability"
        }
        $sha = [System.Security.Cryptography.SHA256]::Create()
        try {
            $expectedSha256 = ([System.BitConverter]::ToString($sha.ComputeHash($expectedBytes))).Replace('-', '')
        } finally {
            $sha.Dispose()
        }
        $actualSha256 = Get-SynapseFileSha256 -Path $resolvedPath
        if ($actualSha256 -ine $expectedSha256) {
            throw "SYNAPSE_ATOMIC_TEXT_READBACK_BYTES_MISMATCH purpose=$Purpose path=$resolvedPath remediation=repair concurrent filesystem mutation or storage durability"
        }
        return [pscustomobject][ordered]@{
            path = $resolvedPath
            sha256 = $actualSha256
            byte_length = [uint64]$expectedBytes.Length
            encoding = 'utf-8-no-bom'
        }
    } catch {
        if ($null -ne $stream) { $stream.Dispose() }
        try { Remove-Item -LiteralPath $tempPath -Force -ErrorAction SilentlyContinue } catch { }
        throw "SYNAPSE_ATOMIC_TEXT_WRITE_FAILED purpose=$Purpose path=$resolvedPath error=$($_.Exception.Message) remediation=repair setup-owned filesystem permissions/durability; no non-atomic or lossy fallback is permitted"
    }
}

function Write-SynapseAtomicUtf8TextFileUnderPhysicalRoot {
    param(
        [Parameter(Mandatory=$true)][string]$Root,
        [Parameter(Mandatory=$true)][ValidatePattern('^(?:[0-9A-Fa-f]{8}:[0-9A-Fa-f]{16}|[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32})$')][string]$ExpectedRootIdentity,
        [Parameter(Mandatory=$true)][string]$LeafName,
        [Parameter(Mandatory=$true)][AllowEmptyString()][string]$Content,
        [Parameter(Mandatory=$true)][string]$Purpose
    )

    $rootFull = [System.IO.Path]::GetFullPath($Root).TrimEnd('\')
    $resolvedPath = [System.IO.Path]::GetFullPath((Join-Path $rootFull $LeafName))
    try {
        Ensure-SynapseAtomicFileType
        $readback = [SynapseSetup.AtomicFileV2]::InstallNewUtf8TextUnderPhysicalRoot(
            $rootFull,
            $ExpectedRootIdentity,
            $LeafName,
            $Content)
        return [pscustomobject][ordered]@{
            path = $resolvedPath
            sha256 = [string]$readback.Sha256
            byte_length = [uint64]$readback.Length
            file_identity = [string]$readback.Identity
            root_identity = $ExpectedRootIdentity.ToUpperInvariant()
            encoding = 'utf-8-no-bom'
        }
    } catch {
        throw "SYNAPSE_PHYSICAL_ATOMIC_TEXT_WRITE_FAILED purpose=$Purpose root=$rootFull root_identity=$ExpectedRootIdentity path=$resolvedPath error=$($_.Exception.Message) remediation=preserve the exact physical directory and repair setup-owned filesystem permissions/durability; no path-following or non-atomic fallback is permitted"
    }
}

function Read-SynapseUtf8TextFileUnderPhysicalRoot {
    param(
        [Parameter(Mandatory=$true)][string]$Root,
        [Parameter(Mandatory=$true)][ValidatePattern('^(?:[0-9A-Fa-f]{8}:[0-9A-Fa-f]{16}|[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32})$')][string]$ExpectedRootIdentity,
        [Parameter(Mandatory=$true)][string]$Path,
        [AllowEmptyString()][string]$ExpectedFileIdentity = '',
        [ValidateRange(1, 16777216)][int]$MaxBytes = 1048576,
        [Parameter(Mandatory=$true)][string]$Purpose
    )

    $rootFull = [System.IO.Path]::GetFullPath($Root).TrimEnd('\')
    $pathFull = [System.IO.Path]::GetFullPath($Path)
    try {
        Ensure-SynapseAtomicFileType
        $entry = [SynapseSetup.AtomicFileV2]::GetPhysicalEntryIdentityUnderRoot(
            $rootFull,
            $ExpectedRootIdentity,
            $pathFull,
            $ExpectedFileIdentity,
            $false)
        return [SynapseSetup.AtomicFileV2]::ReadUtf8TextFileUnderPhysicalRoot(
            $rootFull,
            $ExpectedRootIdentity,
            $pathFull,
            [string]$entry.Identity,
            $MaxBytes)
    } catch {
        throw "SYNAPSE_PHYSICAL_TEXT_READ_FAILED purpose=$Purpose root=$rootFull root_identity=$ExpectedRootIdentity path=$pathFull expected_file_identity=$ExpectedFileIdentity max_bytes=$MaxBytes error=$($_.Exception.Message) remediation=preserve the physical evidence; setup never follows a reparse/replacement path or accepts unreadable/unbounded text"
    }
}

function Get-SynapseManagedCpuOnlyCalyxConfigIdentity {
    $content = "[calyx]`r`nmath_backend = `"cpu`"`r`nvram_budget_bytes = 0`r`n"
    $contentBytes = [System.Text.UTF8Encoding]::new($false).GetBytes($content)
    if ($contentBytes.Length -gt $SynapseCalyxConfigMaxBytesV1) {
        Die "SYNAPSE_CALYX_CONFIG_TOO_LARGE phase=identity max_bytes=$SynapseCalyxConfigMaxBytesV1 actual_bytes=$($contentBytes.Length) remediation=repair the setup-owned canonical CPU-only config template"
    }
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try {
        $sha256 = ([System.BitConverter]::ToString($sha.ComputeHash($contentBytes))).Replace('-', '')
    } finally {
        $sha.Dispose()
    }
    return [pscustomobject][ordered]@{
        content = $content
        bytes = $contentBytes
        sha256 = $sha256
    }
}

function Write-SynapseManagedCpuOnlyCalyxConfig {
    param([Parameter(Mandatory=$true)][string]$Path)

    $resolvedPath = [System.IO.Path]::GetFullPath($Path)
    $parent = Split-Path -Parent $resolvedPath
    $identity = Get-SynapseManagedCpuOnlyCalyxConfigIdentity
    $content = [string]$identity.content
    $contentBytes = [byte[]]$identity.bytes
    $tempPath = Join-Path $parent (".{0}.tmp-{1}-{2}" -f ([System.IO.Path]::GetFileName($resolvedPath)), $PID, ([Guid]::NewGuid().ToString('N')))
    $writeStream = $null
    try {
        New-Item -ItemType Directory -Force -Path $parent -ErrorAction Stop | Out-Null
        $parentItem = Get-Item -LiteralPath $parent -Force -ErrorAction Stop
        if (-not $parentItem.PSIsContainer -or ($parentItem.Attributes -band [System.IO.FileAttributes]::ReparsePoint)) {
            throw "SYNAPSE_CALYX_CONFIG_PARENT_INVALID path=$parent attributes=$($parentItem.Attributes) remediation=use a real local directory; setup will not write through a reparse point"
        }
        if (Test-Path -LiteralPath $resolvedPath) {
            $existingItem = Get-Item -LiteralPath $resolvedPath -Force -ErrorAction Stop
            if ($existingItem.PSIsContainer -or ($existingItem.Attributes -band [System.IO.FileAttributes]::ReparsePoint)) {
                throw "SYNAPSE_CALYX_CONFIG_DESTINATION_INVALID path=$resolvedPath attributes=$($existingItem.Attributes) remediation=replace the unexpected directory/reparse point with a regular setup-owned file"
            }
        } else {
            $writeStream = [System.IO.FileStream]::new(
                $tempPath,
                [System.IO.FileMode]::CreateNew,
                [System.IO.FileAccess]::Write,
                [System.IO.FileShare]::None,
                4096,
                [System.IO.FileOptions]::WriteThrough)
            $writeStream.Write($contentBytes, 0, $contentBytes.Length)
            $writeStream.Flush($true)
            $writeStream.Dispose()
            $writeStream = $null
            Ensure-SynapseAtomicFileType
            # The filename is the content SHA. Never replace an existing object:
            # a prior generation may still pin it and MoveFileEx(REPLACE) would
            # recreate the same cross-generation TOCTOU under a different name.
            [SynapseSetup.AtomicFileV2]::InstallNewWriteThrough($tempPath, $resolvedPath)
            if (Test-Path -LiteralPath $tempPath) {
                throw "SYNAPSE_CALYX_CONFIG_TEMP_RETAINED path=$tempPath remediation=repair atomic rename semantics; setup refuses ambiguous source/destination ownership"
            }
        }
        $writtenItem = Get-Item -LiteralPath $resolvedPath -Force -ErrorAction Stop
        if ($writtenItem.PSIsContainer -or ($writtenItem.Attributes -band [System.IO.FileAttributes]::ReparsePoint)) {
            throw "SYNAPSE_CALYX_CONFIG_WRITE_READBACK_TYPE_INVALID path=$resolvedPath attributes=$($writtenItem.Attributes) remediation=repair concurrent filesystem mutation; setup requires a regular file after atomic replacement"
        }
    } catch {
        if ($null -ne $writeStream) { $writeStream.Dispose() }
        try { Remove-Item -LiteralPath $tempPath -Force -ErrorAction SilentlyContinue } catch { }
        Die "SYNAPSE_CALYX_CPU_CONFIG_WRITE_FAILED path=$resolvedPath error=$($_.Exception.Message) remediation=repair the setup-owned runtime-bin directory; setup requires a durable explicit math_backend=cpu, vram_budget_bytes=0 config before candidate launch"
    }

    $configStream = $null
    $boundedLength = 0
    $readbackBytes = $null
    try {
        $configStream = [System.IO.File]::Open(
            $resolvedPath,
            [System.IO.FileMode]::Open,
            [System.IO.FileAccess]::Read,
            [System.IO.FileShare]::Read)
        $boundedBuffer = [byte[]]::new($SynapseCalyxConfigMaxBytesV1 + 1)
        $boundedLength = 0
        while ($boundedLength -lt $boundedBuffer.Length) {
            $readCount = $configStream.Read($boundedBuffer, $boundedLength, $boundedBuffer.Length - $boundedLength)
            if ($readCount -eq 0) { break }
            $boundedLength += $readCount
        }
        if ($boundedLength -le $SynapseCalyxConfigMaxBytesV1) {
            $readbackBytes = [byte[]]::new($boundedLength)
            [System.Array]::Copy($boundedBuffer, $readbackBytes, $boundedLength)
            $readback = [System.Text.UTF8Encoding]::new($false, $true).GetString($readbackBytes)
        }
    } catch {
        Die "SYNAPSE_CALYX_CPU_CONFIG_READBACK_FAILED path=$resolvedPath error=$($_.Exception.Message) remediation=repair the setup-owned config file; setup cannot launch from unverified tuning bytes"
    } finally {
        if ($null -ne $configStream) { $configStream.Dispose() }
    }
    if ($boundedLength -gt $SynapseCalyxConfigMaxBytesV1) {
        Die "SYNAPSE_CALYX_CONFIG_TOO_LARGE phase=readback path=$resolvedPath max_bytes=$SynapseCalyxConfigMaxBytesV1 observed_at_least_bytes=$boundedLength remediation=replace the setup-owned tuning document with the canonical bounded CPU-only config"
    }
    if ($readback -cne $content) {
        Die "SYNAPSE_CALYX_CPU_CONFIG_READBACK_MISMATCH path=$resolvedPath expected_chars=$($content.Length) actual_chars=$($readback.Length) remediation=inspect filesystem mutation or encoding drift; setup refuses to launch from bytes that differ from the CPU-only contract"
    }
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try {
        $sha256 = ([System.BitConverter]::ToString($sha.ComputeHash($readbackBytes))).Replace('-', '')
    } finally {
        $sha.Dispose()
    }
    if ($sha256 -ine [string]$identity.sha256) {
        Die "SYNAPSE_CALYX_CPU_CONFIG_CONTENT_ADDRESS_MISMATCH path=$resolvedPath filename_sha256=$($identity.sha256) actual_sha256=$sha256 remediation=refuse to mutate or use an occupied content-addressed path whose bytes do not match its identity"
    }
    Info "Managed Calyx CPU-only content-addressed config readback path=$resolvedPath sha256=$sha256 math_backend=cpu vram_budget_bytes=0 immutable_existing=$([bool](Test-Path -LiteralPath $resolvedPath -PathType Leaf))"
    return [pscustomobject][ordered]@{
        schema = 'synapse_setup_calyx_cpu_config/v1'
        path = $resolvedPath
        sha256 = $sha256
        math_backend = 'cpu'
        vram_budget_bytes = [int64]0
    }
}

function Assert-SynapseChromeBridgeMaintenancePauseBudget {
    param(
        [Parameter(Mandatory=$true)][string]$Reason,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$Phase
    )

    if ($null -eq $script:SynapseChromeBridgeMaintenancePauseUntilUnixMs) {
        return
    }

    $nowMs = Get-SynapseUnixTimeMilliseconds
    $remainingMs = [int64]$script:SynapseChromeBridgeMaintenancePauseUntilUnixMs - [int64]$nowMs
    if ($remainingMs -le [int64]$SynapseChromeBridgeMaintenancePauseGuardMs) {
        Die ("SYNAPSE_CHROME_BRIDGE_MAINTENANCE_PAUSE_EXPIRING reason={0} bind={1} phase={2} pause_until_unix_ms={3} remaining_ms={4} guard_ms={5} remediation=setup refuses to continue daemon bind drain after the Chrome bridge maintenance pause is close to expiry. The Chrome bridge can reconnect and recreate NetworkService peers after this point; rerun setup with a maintenance pause that covers the full drain budget or investigate why Windows still reports stale dead-owner TCP rows." -f `
            $Reason,
            $Bind,
            $Phase,
            $script:SynapseChromeBridgeMaintenancePauseUntilUnixMs,
            $remainingMs,
            $SynapseChromeBridgeMaintenancePauseGuardMs)
    }
}

function Invoke-SynapseChromeBridgeVerifier {
    param(
        [Parameter(Mandatory = $true)]
        [string]$InstallerPath,
        [Parameter(Mandatory = $true)]
        [string]$NativeHostExePath
    )

    if (-not (Test-Path -LiteralPath $InstallerPath -PathType Leaf)) {
        Die "SYNAPSE_CHROME_BRIDGE_INSTALLER_MISSING path=$InstallerPath remediation=setup requires the repo script that verifies the direct localhost Chrome bridge and removes stale nativeMessaging registration"
    }
    $chromeBridgeArgs = @{
        SynapseNativeHostExe = $NativeHostExePath
    }
    $readback = & $InstallerPath @chromeBridgeArgs
    if (-not $readback.ok) {
        Die "SYNAPSE_CHROME_BRIDGE_INSTALLER_FAILED path=$InstallerPath remediation=installer did not return ok=true"
    }
    $extensionDeploy = $readback.extension_deploy
    if (-not $extensionDeploy) {
        Die "SYNAPSE_CHROME_BRIDGE_EXTENSION_DEPLOY_READBACK_MISSING path=$InstallerPath remediation=setup requires the Chrome bridge installer to report deployed service worker hash and register-token injection readback"
    }
    if ($extensionDeploy.bridge_register_token_injected -ne $true -or
        $extensionDeploy.bridge_register_token_matches_expected -ne $true -or
        [int]$extensionDeploy.bridge_register_token_length -ne 64 -or
        [string]$extensionDeploy.bridge_register_token_sha256 -notmatch '^[0-9a-f]{64}$') {
        Die ("SYNAPSE_CHROME_BRIDGE_REGISTER_TOKEN_DEPLOY_READBACK_INVALID path={0} injected={1} matches_expected={2} length={3} sha256={4} remediation=setup must deploy a Chrome service worker with the host-local derived bridge register token before daemon restart; rerun setup after verifying the stable extension directory is writable" -f `
            $InstallerPath,
            $extensionDeploy.bridge_register_token_injected,
            $extensionDeploy.bridge_register_token_matches_expected,
            $extensionDeploy.bridge_register_token_length,
            $extensionDeploy.bridge_register_token_sha256)
    }
    $autoInstall = $readback.synapse_chrome_auto_install
    if (-not $autoInstall) {
        Die "SYNAPSE_CHROME_BRIDGE_AUTOINSTALL_READBACK_MISSING path=$InstallerPath remediation=setup requires the bridge installer to report synapse_chrome_auto_install so skipped or failed active-profile installation cannot pass silently"
    }
    if ([string]$autoInstall.reason -eq 'skip_auto_install_requested') {
        Die "SYNAPSE_CHROME_BRIDGE_AUTOINSTALL_SKIPPED path=$InstallerPath remediation=setup must auto-install the bundled Chrome bridge into the already-open active profile; remove -SkipAutoInstall and rerun from the interactive Windows desktop"
    }
    $profileInstallState = $readback.synapse_chrome_profile_install_state
    if (-not $profileInstallState) {
        Die "SYNAPSE_CHROME_BRIDGE_PROFILE_INSTALL_STATE_MISSING path=$InstallerPath remediation=setup requires active Chrome profile installation readback after bridge verification"
    }
    if ($profileInstallState.active_profile_installed -ne $true) {
        Die ("SYNAPSE_CHROME_BRIDGE_ACTIVE_PROFILE_NOT_INSTALLED active_profile={0} installed_profiles={1} auto_install_attempted={2} auto_install_reason={3} remediation=setup must auto-install the deployed stable Synapse Chrome bridge directory into the already-open active Chrome profile before daemon handoff can continue" -f `
            $profileInstallState.active_profile,
            (@($profileInstallState.installed_profiles) -join ','),
            $autoInstall.attempted,
            $autoInstall.reason)
    }
    return $readback
}

function Format-SynapseChromeBridgeProfileInstallState {
    param($Readback)

    $state = $Readback.synapse_chrome_profile_install_state
    if (-not $state) {
        return 'profile_install_state=missing'
    }
    $autoInstall = $Readback.synapse_chrome_auto_install
    $autoInstallAttempted = if ($autoInstall) { [string]$autoInstall.attempted } else { 'missing' }
    $autoInstallReason = if ($autoInstall) { [string]$autoInstall.reason } else { 'missing' }
    $extensionDir = if ($Readback.extension_dir) { [string]$Readback.extension_dir } else { 'missing' }
    $cleanup = $Readback.stale_bridge_build_cleanup
    $cleanupRemoved = if ($cleanup) { @($cleanup.removed_dirs).Count } else { 'missing' }
    $cleanupPreserved = if ($cleanup) { @($cleanup.preserved_dirs).Count } else { 'missing' }
    $cleanupFailed = if ($cleanup) { @($cleanup.failed_dirs).Count } else { 'missing' }
    return ("profile_install_state=installed:{0},profile_count:{1},installed_profile_count:{2},active_profile:{3},active_profile_installed:{4},reason:{5},auto_install_attempted:{6},auto_install_reason:{7},extension_dir:{8},stale_build_dirs_removed:{9},stale_build_dirs_preserved:{10},stale_build_dirs_failed:{11}" -f `
        $state.installed, `
        $state.profile_count, `
        $state.installed_profile_count, `
        $state.active_profile, `
        $state.active_profile_installed, `
        $state.reason, `
        $autoInstallAttempted, `
        $autoInstallReason, `
        $extensionDir, `
        $cleanupRemoved, `
        $cleanupPreserved, `
        $cleanupFailed)
}

$processTokenAtStart = $env:SYNAPSE_BEARER_TOKEN
$processToolSurfaceHashAtStart = $env:SYNAPSE_TOOL_SURFACE_HASH_AT_CODEX_START
$processToolSurfaceSnapshotAtStart = $env:SYNAPSE_TOOL_SURFACE_SNAPSHOT_AT_CODEX_START
$script:SynapseMcpProtocolVersion = '2025-06-18'
# The setup-time MCP readback runs immediately after daemon replacement, while
# the real Calyx store and Codex reconnect path may still be warming. Keep this
# finite and diagnostic-rich; do not use the short interactive request budget.
$script:SynapseSetupMcpRequestTimeoutSec = 120
# DELETE waits for the daemon's real lifecycle cleanup/readbacks. On the
# operator Calyx vault, cold post-start cleanup can exceed the old 20s budget.
$script:SynapseMcpSessionDeleteTimeoutSec = 120
$script:SynapseSetupMaintenanceLockStream = $null
$script:SynapseSetupMaintenanceLockPath = $null
$script:SynapseBrokerDecommissionMutexStream = $null
$script:SynapseBrokerDecommissionMutexPath = $null
$script:SynapseBrokerDecommissionGlobalTokenBoundaryLease = $null
$script:SynapseSetupMaintenanceLockReason = $null
$script:SynapseSetupMaintenanceLockToken = $null

function Get-ProcessLineage {
    param([int]$StartPid = $PID)
    $lineage = @()
    $seen = @{}
    $current = $StartPid
    $child = $null
    while ($current -and -not $seen.ContainsKey($current)) {
        $seen[$current] = $true
        $p = Get-CimInstance Win32_Process -Filter "ProcessId=$current" -ErrorAction SilentlyContinue
        if (-not $p) { break }
        # Guard against Windows PID reuse: ParentProcessId is a bare number, so
        # once a real parent exits its PID can be recycled by an unrelated, newer
        # process. A genuine parent always starts no later than its child; if the
        # candidate "parent" started after the child it is a recycled PID, not a
        # true ancestor, so stop the walk rather than climb into a phantom chain
        # (e.g. wininit.exe <- cmd.exe, which falsely tripped the cmd-ancestor guard).
        if ($child -and $p.CreationDate -and $child.CreationDate -and $p.CreationDate -gt $child.CreationDate) {
            break
        }
        $lineage += $p
        $child = $p
        $current = [int]$p.ParentProcessId
    }
    return $lineage
}

function Get-SynapseCurrentCodexAncestor {
    $lineage = Get-ProcessLineage
    return ($lineage | Where-Object {
        $_.Name -ieq 'codex.exe' -or $_.CommandLine -match '@openai[\\/]+codex|codex\.js|codex-win32'
    } | Select-Object -First 1)
}

function Test-SynapseCodexProcess {
    param([AllowNull()]$Process)

    if ($null -eq $Process) {
        return $false
    }
    $name = [string]$Process.Name
    $commandLine = [string]$Process.CommandLine
    return (
        $name -ieq 'codex.exe' -or
        $commandLine -match '@openai[\\/]+codex|codex\.js|codex-win32|openai\.chatgpt'
    )
}

function Read-SynapseSetupMaintenanceLockOwner {
    param([Parameter(Mandatory=$true)][string]$Path)
    if (-not (Test-Path -LiteralPath $Path)) {
        return '<missing>'
    }
    try {
        $stream = [System.IO.File]::Open($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
        try {
            $reader = New-Object System.IO.StreamReader($stream, [System.Text.Encoding]::UTF8, $true, 4096, $true)
            try {
                $text = $reader.ReadToEnd().Trim()
                if ([string]::IsNullOrWhiteSpace($text)) { return '<empty>' }
                return ($text -replace '\s+', ' ')
            } finally {
                $reader.Dispose()
            }
        } finally {
            $stream.Dispose()
        }
    } catch {
        return "<unreadable error=$($_.Exception.Message)>"
    }
}

function Acquire-SynapseSetupMaintenanceLock {
    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$Reason
    )

    New-Item -ItemType Directory -Force -Path (Split-Path -Parent $Path) | Out-Null
    try {
        $stream = [System.IO.File]::Open($Path, [System.IO.FileMode]::OpenOrCreate, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::Read)
    } catch [System.IO.IOException] {
        $owner = Read-SynapseSetupMaintenanceLockOwner -Path $Path
        Die "SYNAPSE_SETUP_MAINTENANCE_LOCK_HELD reason=$Reason path=$Path owner=$owner remediation=another setup/remove process owns the maintenance lock; wait for that setup process to exit or inspect the named PID. Do not close terminal windows or broad shell processes to clear this condition."
    } catch {
        Die "SYNAPSE_SETUP_MAINTENANCE_LOCK_OPEN_FAILED reason=$Reason path=$Path error=$($_.Exception.Message) remediation=repair permissions on the synapse local appdata directory"
    }

    $script:SynapseSetupMaintenanceLockStream = $stream
    $script:SynapseSetupMaintenanceLockPath = $Path
    $script:SynapseSetupMaintenanceLockReason = $Reason
    $script:SynapseSetupMaintenanceLockToken = [Guid]::NewGuid().ToString('D')
    $self = Get-CimInstance Win32_Process -Filter "ProcessId=$PID" -ErrorAction SilentlyContinue
    $lineageText = (Get-ProcessLineage | ForEach-Object { "{0}:{1}" -f $_.ProcessId, $_.Name }) -join ' <- '
    $owner = [ordered]@{
        schema = 'synapse_setup_maintenance_lock/v2'
        state = 'held'
        lock_token = $script:SynapseSetupMaintenanceLockToken
        reason = $Reason
        pid = $PID
        parent_pid = $self.ParentProcessId
        process_name = $self.Name
        command_line = $self.CommandLine
        source_dir = $SourceDir
        bind = $Bind
        started_at_utc = (Get-Date).ToUniversalTime().ToString('o')
        lineage = $lineageText
        cleanup_policy = 'never close terminal windows globally; only exact process IDs spawned by this setup operation or verified synapse-mcp targets may be stopped'
    }
    $json = $owner | ConvertTo-Json -Depth 6
    $bytes = [System.Text.Encoding]::UTF8.GetBytes($json + "`n")
    $stream.SetLength(0)
    $stream.Write($bytes, 0, $bytes.Length)
    $stream.Flush($true)
    Info "Maintenance lock acquired reason=$Reason path=$Path pid=$PID"
}

function Acquire-SynapseBrokerDecommissionMutex {
    if($null-ne$script:SynapseBrokerDecommissionMutexStream){return}
    $path=[IO.Path]::GetFullPath((Join-Path $env:LOCALAPPDATA 'synapse\broker-decommission.lock'))
    [IO.Directory]::CreateDirectory((Split-Path -Parent $path))|Out-Null
    try{$stream=[IO.File]::Open($path,[IO.FileMode]::OpenOrCreate,[IO.FileAccess]::ReadWrite,[IO.FileShare]::Read)}catch{Die "SYNAPSE_BROKER_DECOMMISSION_MUTEX_HELD path=$path error=$($_.Exception.Message) remediation=another exact -Remove owns the fixed uninstall mutex; wait for that process rather than changing MaintenanceLockPath"}
    try{$payload=[ordered]@{schema='synapse_broker_decommission_mutex/v1';state='held';pid=$PID;invocation_id=$script:SynapseSetupInvocationId;maintenance_lock_path=[IO.Path]::GetFullPath($MaintenanceLockPath);started_at_utc=[DateTime]::UtcNow.ToString('o')};$bytes=[Text.UTF8Encoding]::new($false,$true).GetBytes((Get-SynapseCanonicalJson -Value $payload)+"`n");$stream.SetLength(0);$stream.Write($bytes,0,$bytes.Length);$stream.Flush($true);$script:SynapseBrokerDecommissionMutexStream=$stream;$script:SynapseBrokerDecommissionMutexPath=$path}catch{try{$stream.Dispose()}catch{};throw}
}

function Release-SynapseBrokerDecommissionGlobalTokenBoundaryLease {
    param([switch]$BestEffort)
    $lease=$script:SynapseBrokerDecommissionGlobalTokenBoundaryLease
    if($null-eq$lease){return}
    $script:SynapseBrokerDecommissionGlobalTokenBoundaryLease=$null
    try{$lease.Dispose()}catch{if(-not$BestEffort){[Environment]::FailFast('SYNAPSE_BROKER_DECOMMISSION_GLOBAL_TOKEN_LEASE_RELEASE_UNPROVEN',$_.Exception)}}
}

function Release-SynapseBrokerDecommissionMutex {
    param([switch]$BestEffort)
    Release-SynapseBrokerDecommissionGlobalTokenBoundaryLease -BestEffort:$BestEffort
    $stream=$script:SynapseBrokerDecommissionMutexStream;if($null-eq$stream){return};$script:SynapseBrokerDecommissionMutexStream=$null;$script:SynapseBrokerDecommissionMutexPath=$null
    try{$stream.Dispose()}catch{if(-not$BestEffort){[Environment]::FailFast('SYNAPSE_BROKER_DECOMMISSION_MUTEX_RELEASE_UNPROVEN',$_.Exception)}}
}

function Release-SynapseSetupMaintenanceLock {
    param(
        [Parameter(Mandatory=$true)][ValidateSet('released','failed','bridge_pending')][string]$State,
        [string]$ErrorMessage,
        [switch]$BestEffort
    )

    if ($null -eq $script:SynapseSetupMaintenanceLockStream) {
        return
    }

    $stream = $script:SynapseSetupMaintenanceLockStream
    $lockPath = $script:SynapseSetupMaintenanceLockPath
    $lockReason = $script:SynapseSetupMaintenanceLockReason
    $lockToken = $script:SynapseSetupMaintenanceLockToken
    $releaseFailure = $null
    try {
        $stream.Seek(0, [System.IO.SeekOrigin]::Begin) | Out-Null
        $reader = New-Object System.IO.StreamReader($stream, [System.Text.Encoding]::UTF8, $true, 4096, $true)
        try {
            $heldText = $reader.ReadToEnd().Trim()
        } finally {
            $reader.Dispose()
        }
        try {
            $held = $heldText | ConvertFrom-Json -ErrorAction Stop
        } catch {
            throw "SYNAPSE_SETUP_MAINTENANCE_LOCK_RELEASE_OWNER_INVALID phase=owner_readback path=$lockPath pid=$PID token=$lockToken detail=$($_.Exception.Message) remediation=preserve the lock record and inspect which setup invocation last wrote it"
        }
        if ([string]$held.state -ne 'held' -or [int]$held.pid -ne $PID -or [string]$held.lock_token -ne $lockToken) {
            throw ("SYNAPSE_SETUP_MAINTENANCE_LOCK_RELEASE_OWNER_MISMATCH phase=owner_validation path={0} expected_pid={1} actual_pid={2} expected_token={3} actual_token={4} actual_state={5} remediation=do not overwrite another setup invocation; inspect the exact record and live process table" -f `
                $lockPath, $PID, $held.pid, $lockToken, $held.lock_token, $held.state)
        }
        $self = Get-CimInstance Win32_Process -Filter "ProcessId=$PID" -ErrorAction SilentlyContinue
        $owner = [ordered]@{
            schema = 'synapse_setup_maintenance_lock/v2'
            state = $State
            lock_token = $lockToken
            reason = $lockReason
            pid = $PID
            parent_pid = if ($self) { $self.ParentProcessId } else { $null }
            process_name = if ($self) { $self.Name } else { $null }
            command_line = if ($self) { $self.CommandLine } else { $null }
            source_dir = $SourceDir
            bind = $Bind
            released_at_utc = (Get-Date).ToUniversalTime().ToString('o')
            cleanup_policy = 'never close terminal windows globally; only exact process IDs spawned by this setup operation or verified synapse-mcp targets may be stopped'
        }
        if (-not [string]::IsNullOrWhiteSpace($ErrorMessage)) {
            $owner.error = ($ErrorMessage -replace '\s+', ' ').Trim()
        }
        $json = $owner | ConvertTo-Json -Depth 6
        $bytes = [System.Text.Encoding]::UTF8.GetBytes($json + "`n")
        $stream.Seek(0, [System.IO.SeekOrigin]::Begin) | Out-Null
        $stream.SetLength(0)
        $stream.Write($bytes, 0, $bytes.Length)
        $stream.Flush($true)

        $stream.Seek(0, [System.IO.SeekOrigin]::Begin) | Out-Null
        $reader = New-Object System.IO.StreamReader($stream, [System.Text.Encoding]::UTF8, $true, 4096, $true)
        try {
            $releasedText = $reader.ReadToEnd().Trim()
        } finally {
            $reader.Dispose()
        }
        try {
            $released = $releasedText | ConvertFrom-Json -ErrorAction Stop
        } catch {
            throw "SYNAPSE_SETUP_MAINTENANCE_LOCK_RELEASE_READBACK_INVALID phase=release_readback path=$lockPath pid=$PID token=$lockToken detail=$($_.Exception.Message) remediation=preserve the record and repair storage before running another setup"
        }
        if ([string]$released.state -ne $State -or [int]$released.pid -ne $PID -or [string]$released.lock_token -ne $lockToken) {
            throw ("SYNAPSE_SETUP_MAINTENANCE_LOCK_RELEASE_READBACK_MISMATCH phase=release_readback path={0} expected_state={1} actual_state={2} expected_pid={3} actual_pid={4} expected_token={5} actual_token={6} remediation=preserve the record and repair storage before running another setup" -f `
                $lockPath, $State, $released.state, $PID, $released.pid, $lockToken, $released.lock_token)
        }
    } catch {
        $releaseFailure = "SYNAPSE_SETUP_MAINTENANCE_LOCK_RELEASE_FAILED phase=release state=$State path=$lockPath pid=$PID token=$lockToken detail=$($_.Exception.Message) remediation=preserve and inspect the exact lock record plus process table; do not start another setup until the OS handle is free and ownership is understood"
    } finally {
        $stream.Dispose()
        $script:SynapseSetupMaintenanceLockStream = $null
        $script:SynapseSetupMaintenanceLockPath = $null
        $script:SynapseSetupMaintenanceLockReason = $null
        $script:SynapseSetupMaintenanceLockToken = $null
    }
    if ($releaseFailure) {
        if ($BestEffort) {
            try { Info "WARN: $releaseFailure" } catch {}
            return
        }
        throw $releaseFailure
    }
    try { Info "Maintenance lock $State path=$lockPath pid=$PID token=$lockToken" } catch {}
}

function Wait-SynapsePostExitParent {
    param(
        [int]$ParentPid,
        [string]$Reason
    )

    if ($ParentPid -le 0) {
        return
    }

    $parent = Get-Process -Id $ParentPid -ErrorAction SilentlyContinue
    if ($null -eq $parent) {
        Info "SYNAPSE_POST_EXIT_PARENT_ALREADY_GONE parent_pid=$ParentPid reason=$Reason"
        return
    }

    Info "SYNAPSE_POST_EXIT_PARENT_WAIT parent_pid=$ParentPid reason=$Reason"
    try {
        Wait-Process -Id $ParentPid -Timeout 180 -ErrorAction Stop
    } catch {
        $stillAlive = [bool](Get-Process -Id $ParentPid -ErrorAction SilentlyContinue)
        if ($stillAlive) {
            Die "SYNAPSE_POST_EXIT_PARENT_STILL_RUNNING parent_pid=$ParentPid reason=$Reason remediation=the setup continuation waits for the parent runner to exit before reacquiring the maintenance lock; inspect the parent process and setup logs, never kill terminal/IDE/WSL hosts globally"
        }
    }
    Start-Sleep -Seconds 1
    Info "SYNAPSE_POST_EXIT_PARENT_GONE parent_pid=$ParentPid reason=$Reason"
}

# ---------------------------------------------------------------------------
# #2092, #2188 -- durable deployment transaction bookkeeping.
#
# PowerShell hoists the top-level trap across this entire scriptblock, but it
# does not make a script-file function callable before execution reaches that
# function's definition. Keep every command the trap can call above the trap,
# including the earliest parameter/contract failures. Broker-era authority is
# recovered only from its durable transaction; no process-local task-name or
# stop-file variable grants rollback authority.
# ---------------------------------------------------------------------------
$script:SynapseDeploymentTransaction = $null
$script:SynapseDeploymentAllocationContext = $null
$script:SynapseDeploymentTransactionPreparingRoot = $null
$script:SynapseDeploymentTransactionPreparingParent = $null
$script:SynapseRuntimeDeploymentPreparingPlan = $null

function Invoke-SynapseDeploymentTransactionRollbackBestEffort {
    param([Parameter(Mandatory=$true)][string]$PrimaryFailure)

    $transaction = $script:SynapseDeploymentTransaction
    if ($null -eq $transaction -or -not [bool]$transaction.Armed) {
        return [pscustomobject]@{ Attempted = $false; Ok = $true; Detail = 'transaction_not_armed' }
    }
    if ([bool]$transaction.Committed) {
        return [pscustomobject]@{ Attempted = $true; Ok = $true; Detail = 'transaction_already_committed_no_rollback' }
    }
    # The append slot is the durable decision boundary. A process-local failure
    # can occur after CreateNew+Flush(true) made commit_decided/rolled_back
    # durable but before the following in-memory assignment ran. Reclassify from
    # the exact journal before touching profiles, runtime files, or task state;
    # an already-decided generation must never be reversed by stale RAM.
    $durableJournal=$null
    if ($null -ne $transaction.PSObject.Properties['RootChain']) {
        try {
            $durableJournal = Read-SynapseDeploymentTransactionJournal `
                -TransactionRoot $transaction.Root `
                -TransactionRootChain $transaction.RootChain
            $durableTerminal = if ([string]$durableJournal.State -eq 'cleanup_ready') {
                [string]$durableJournal.Latest.detail.terminal_state
            } else {
                [string]$durableJournal.State
            }
            if ($durableTerminal -eq 'commit_decided') {
                $transaction.Committed = $true
                if ($null -ne $transaction.RuntimePlan) { Close-SynapseRuntimeTransactionLeases -RuntimePlan $transaction.RuntimePlan }
                if ($null -ne $transaction.ProfileGenerationLease) {
                    $transaction.ProfileGenerationLease.Dispose()
                    $transaction.ProfileGenerationLease = $null
                }
                return [pscustomobject]@{
                    Attempted = $true
                    Ok = $true
                    Detail = "durable_commit_decision_preserved sequence=$($durableJournal.Sequence) slot_sha256=$($durableJournal.LatestRawSha256)"
                }
            }
            if ($durableTerminal -eq 'rolled_back') {
                $transaction.RolledBack = $true
                $transaction.Armed = $false
                if ($null -ne $transaction.RuntimePlan) { Close-SynapseRuntimeTransactionLeases -RuntimePlan $transaction.RuntimePlan }
                if ($null -ne $transaction.ProfileGenerationLease) {
                    $transaction.ProfileGenerationLease.Dispose()
                    $transaction.ProfileGenerationLease = $null
                }
                return [pscustomobject]@{
                    Attempted = $true
                    Ok = $true
                    Detail = "durable_rollback_decision_preserved sequence=$($durableJournal.Sequence) slot_sha256=$($durableJournal.LatestRawSha256)"
                }
            }
            if ($durableTerminal -notin @('armed','candidate_ready')) {
                return [pscustomobject]@{
                    Attempted = $true
                    Ok = $false
                    Detail = "durable_journal_state_refused state=$($durableJournal.State) terminal=$durableTerminal"
                }
            }
        } catch {
            return [pscustomobject]@{
                Attempted = $true
                Ok = $false
                Detail = "durable_journal_reclassification_failed:$($_.Exception.Message)"
            }
        }
    }
    if ([bool]$transaction.RollbackInProgress) {
        return [pscustomobject]@{ Attempted = $true; Ok = $false; Detail = 'rollback_reentry_refused' }
    }
    if ($null -ne $transaction.PSObject.Properties['AuthorityModel'] -and [string]$transaction.AuthorityModel -ceq 'immutable_broker/v1') {
        try {
            $rollback=Invoke-SynapseBrokerApplicationRollback -Transaction $transaction -Authority $transaction.Authority -PrimaryFailure $PrimaryFailure -HealthTimeoutSeconds 420
            return [pscustomobject]@{Attempted=$true;Ok=[bool]$rollback.Ok;Detail=[string]$rollback.Detail}
        } catch {
            return [pscustomobject]@{Attempted=$true;Ok=$false;Detail="broker_v4_rollback_failed:$($_.Exception.Message)"}
        }
    }
    # Shipped v3 depended on mutable fixed-name Scheduler authority. That
    # authority is retired permanently: the trap preserves every non-broker
    # transaction for explicit inspection and performs zero task, runtime, or
    # profile mutations. Frozen v1 recovery is handled by its separate exact
    # no-mutation path and never enters this function.
    return [pscustomobject]@{
        Attempted = $true
        Ok = $false
        Detail = 'legacy_v3_rollback_preserved_no_mutation_authority'
    }
}
trap {
    $errorText = $_ | Out-String
    # Raw PowerShell/.NET failures do not pass through Die(). Record the same
    # phase failure here, but never let this secondary diagnostic replace the
    # primary error which caused the trap (#2209).
    try {
        $trapPhaseLedgerPath = Write-SynapseSetupPhaseLedger `
            -Outcome 'failed' `
            -Message (($errorText -replace '\s+', ' ').Trim())
        if ($trapPhaseLedgerPath) {
            Write-Host "[synapse-setup] phase timing ledger -> $trapPhaseLedgerPath" -ForegroundColor Yellow
        } elseif (-not [string]::IsNullOrWhiteSpace($script:SynapseSetupPhaseLedgerWriteError)) {
            Write-Host "[synapse-setup] WARNING: $script:SynapseSetupPhaseLedgerWriteError" -ForegroundColor Yellow
        }
    } catch {
        try {
            Info "WARN: SYNAPSE_SETUP_PHASE_LEDGER_TRAP_REPORT_FAILED detail=$($_.Exception.Message) remediation=preserve the primary setup error and inspect LogDir manually"
        } catch {}
    }
    # Once armed, deployment rollback owns restart authority and must restore
    # the complete prior generation before any task can be re-enabled. The old
    # revocation-only cleanup is safe only before a deployment transaction was
    # armed; otherwise it could start a mixed generation.
    $transactionRollback = Invoke-SynapseDeploymentTransactionRollbackBestEffort -PrimaryFailure (($errorText -replace '\s+', ' ').Trim())
    if ($transactionRollback.Attempted) {
        Info "SYNAPSE_DEPLOYMENT_TRANSACTION_ROLLBACK attempted=true ok=$($transactionRollback.Ok) detail=$($transactionRollback.Detail)"
        if (-not $transactionRollback.Ok) {
            $errorText = "$errorText`nSYNAPSE_DEPLOYMENT_TRANSACTION_ROLLBACK_FAILED $($transactionRollback.Detail) remediation=restart authority remains absent; inspect the durable transaction backups and restore only the exact snapshotted generation"
        }
    }
    if (-not $transactionRollback.Attempted -and -not [string]::IsNullOrWhiteSpace([string]$script:SynapseDeploymentTransactionPreparingRoot)) {
        try {
            if ($null -ne $script:SynapseRuntimeDeploymentPreparingPlan) {
                Close-SynapseRuntimeTransactionLeases -RuntimePlan $script:SynapseRuntimeDeploymentPreparingPlan
                $script:SynapseRuntimeDeploymentPreparingPlan = $null
            }
            if ($null -ne $script:SynapseDeploymentAllocationContext) {
                Close-SynapseDeploymentAllocationHandles -Context $script:SynapseDeploymentAllocationContext
                $script:SynapseDeploymentAllocationContext = $null
            }
            [void](Remove-SynapseDeploymentTransactionArtifact `
                -Path $script:SynapseDeploymentTransactionPreparingRoot `
                -ExpectedRoot $(if (-not [string]::IsNullOrWhiteSpace([string]$script:SynapseDeploymentTransactionPreparingParent)) { [string]$script:SynapseDeploymentTransactionPreparingParent } else { Join-Path $LogDir 'setup-transactions' }) `
                -ExpectedState 'unarmed' `
                -Reason 'unarmed_deployment_transaction_cleanup')
            $script:SynapseDeploymentTransactionPreparingRoot = $null
            $script:SynapseDeploymentTransactionPreparingParent = $null
        } catch {
            $errorText = "$errorText`nSYNAPSE_UNARMED_DEPLOYMENT_TRANSACTION_CLEANUP_FAILED root=$($script:SynapseDeploymentTransactionPreparingRoot) error=$($_.Exception.Message)"
        }
    }
    if (-not [string]::IsNullOrWhiteSpace([string]$script:SynapseCurrentDaemonStagingDirectory)) {
        try {
            Remove-SynapseCurrentDaemonStagingArtifact
        } catch {
            $cleanupError = "SYNAPSE_DAEMON_STAGING_TRAP_CLEANUP_FAILED error=$($_.Exception.Message) remediation=inspect the exact setup-staging path named by the nested error; do not delete any path whose ownership validation failed"
            Info "FATAL: $cleanupError"
            $errorText = "$errorText`n$cleanupError"
        }
    }
    if ($script:SynapseSetupPartialState -eq 'bridge_pending' -and -not $transactionRollback.Attempted) {
        try {
            Write-SynapseSetupRepairManifestState `
                -State 'bridge_pending' `
                -Message (($errorText -replace '\s+', ' ').Trim()) `
                -ExitCode 1 `
                -Readback $script:SynapseSetupPartialReadback
        } catch {
            Info "WARN: could not write setup repair manifest bridge-pending state path=$script:SynapseSetupRepairManifestPath error=$($_.Exception.Message)"
        }
        Release-SynapseBrokerDecommissionMutex -BestEffort
        Release-SynapseSetupMaintenanceLock -State bridge_pending -ErrorMessage $errorText -BestEffort
        break
    }
    try {
        Write-SynapseSetupRepairManifestState -State 'failed' -Message (($errorText -replace '\s+', ' ').Trim()) -ExitCode 1 -Readback $null -PreserveExistingTerminal
    } catch {
        Info "WARN: could not write setup repair manifest failure state path=$script:SynapseSetupRepairManifestPath error=$($_.Exception.Message)"
    }
    Release-SynapseBrokerDecommissionMutex -BestEffort
    Release-SynapseSetupMaintenanceLock -State failed -ErrorMessage $errorText -BestEffort
    break
}

function Quote-WindowsCommandArgument {
    param([Parameter(Mandatory=$true)][string]$Value)
    if ($Value.Length -eq 0) { return '""' }
    if ($Value -notmatch '[\s"]') { return $Value }
    $escaped = $Value -replace '(\\*)"', '$1$1\"'
    $escaped = $escaped -replace '(\\+)$', '$1$1'
    return '"' + $escaped + '"'
}

function Get-SynapseSupervisorBootstrapTaskArgumentText {
    param(
        [Parameter(Mandatory=$true)][string]$PowerShellPath,
        [Parameter(Mandatory=$true)][string]$SupervisorPath,
        [Parameter(Mandatory=$true)][string]$WorkingDirectory,
        [Parameter(Mandatory=$true)][string]$LogPath,
        [ValidatePattern('^[0-9A-Fa-f]{64}$')][string]$OuterLaunchCapabilitySha256=''
    )

    $arguments=@(
        (Quote-WindowsCommandArgument ([System.IO.Path]::GetFullPath($PowerShellPath))),
        (Quote-WindowsCommandArgument ([System.IO.Path]::GetFullPath($SupervisorPath))),
        (Quote-WindowsCommandArgument ([System.IO.Path]::GetFullPath($WorkingDirectory))),
        (Quote-WindowsCommandArgument ([System.IO.Path]::GetFullPath($LogPath)))
    )
    if(-not [string]::IsNullOrWhiteSpace($OuterLaunchCapabilitySha256)){
        $arguments=@('--outer-launch-capability',$OuterLaunchCapabilitySha256.ToUpperInvariant())+$arguments
    }
    return ($arguments -join ' ')
}

function Quote-VbsString {
    param([Parameter(Mandatory=$true)][string]$Value)
    return '"' + ($Value -replace '"', '""') + '"'
}

function Quote-PowerShellSingleQuotedString {
    param([AllowNull()][string]$Value)
    if ($null -eq $Value) { $Value = '' }
    return "'" + ($Value -replace "'", "''") + "'"
}

function Get-SynapseAuthorityExactReaderPowerShell {
    return @'
if (-not ('SynapseAuthorityRuntime.ExactFile' -as [type])) {
    Add-Type -TypeDefinition @"
using System;
