        [DllImport("kernel32.dll", SetLastError=true, EntryPoint="GetFileInformationByHandleEx")] static extern bool GetAttributeInfo(SafeFileHandle handle,int cls,out FILE_ATTRIBUTE_TAG_INFO info,uint size);
        [DllImport("kernel32.dll", SetLastError=true, EntryPoint="GetFileInformationByHandleEx")] static extern bool GetIdInfo(SafeFileHandle handle,int cls,out FILE_ID_INFO info,uint size);
        [DllImport("kernel32.dll", CharSet=CharSet.Unicode, SetLastError=true)] static extern uint GetFinalPathNameByHandleW(SafeFileHandle handle,StringBuilder path,uint length,uint flags);
        [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern IntPtr FindFirstFileNameW(string fileName,uint flags,ref uint length,StringBuilder linkName);
        [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern bool FindNextFileNameW(IntPtr find,ref uint length,StringBuilder linkName);
        [DllImport("kernel32.dll",SetLastError=true)] static extern bool FindClose(IntPtr find);
