        [DllImport("advapi32.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern bool ConvertSecurityDescriptorToStringSecurityDescriptorW(IntPtr descriptor,uint revision,uint securityInformation,out IntPtr value,out uint length);
        [DllImport("kernel32.dll")] static extern IntPtr LocalFree(IntPtr value);

        FileStream stream;
