        readonly string[] hardLinkPaths;
        ExactFile(FileStream value,IntPtr owned,string p,string id,string hash,long len,uint links,string sddl,string[] names) { stream=value;ownedHandle=owned;path=p;fileId=id;sha=hash;length=len;linkCount=links;securitySddl=sddl;hardLinkPaths=names; }
        public string Path { get { return path; } }
        public string FileId128 { get { return fileId; } }
        public string Sha256 { get { return sha; } }
        public long Length { get { return length; } }
