            IntPtr owner,group,dacl,sacl,descriptor;uint result=GetSecurityInfo(handle,SE_FILE_OBJECT,OWNER_SECURITY_INFORMATION|GROUP_SECURITY_INFORMATION|DACL_SECURITY_INFORMATION,out owner,out group,out dacl,out sacl,out descriptor);if(result!=0)throw new Win32Exception(unchecked((int)result),"SYNAPSE_AUTHORITY_FILE_SECURITY_READ_FAILED context="+context);IntPtr text=IntPtr.Zero;
