        static void CloseOwnedChecked(ref IntPtr handle,string context,Exception primary) {
            if(handle==IntPtr.Zero||handle==new IntPtr(-1)){handle=IntPtr.Zero;return;}IntPtr owned=handle;
            if(!CloseHandle(owned)){Win32Exception closeError=new Win32Exception(Marshal.GetLastWin32Error(),"SYNAPSE_AUTHORITY_EXACT_HANDLE_CLOSE_FAILED context="+context);Environment.FailFast("SYNAPSE_AUTHORITY_EXACT_HANDLE_CLOSE_UNPROVEN context="+context+" primary=["+(primary==null?"none":primary.Message)+"]",closeError);}handle=IntPtr.Zero;
        }
        static ExactFile OpenCore(string input,string expectedId,string expectedSha,long expectedLength,uint shareMode,uint expectedLinkCount,string expectedSecuritySddl,string[] expectedHardLinks) {
            string full=System.IO.Path.GetFullPath(input);
