            if(owned==IntPtr.Zero||owned==new IntPtr(-1)) { int e=Marshal.GetLastWin32Error();throw new Win32Exception(e,"SYNAPSE_AUTHORITY_EXACT_OPEN_FAILED path="+full); }
            SafeFileHandle view=null;FileStream stream=null;Exception primary=null;
            try {
                view=new SafeFileHandle(owned,false);uint links=RequireShape(view,full,expectedLinkCount); string final=FinalPath(view,full); string id=Id(view,full);string sddl=expectedLinkCount==1?String.Empty:ReadSecuritySddl(view,full);string[] names=expectedLinkCount==1?new string[0]:EnumerateHardLinks(full,full);RequireStringSet(names,expectedHardLinks,full);if(!String.IsNullOrWhiteSpace(expectedSecuritySddl)&&!sddl.Equals(expectedSecuritySddl,StringComparison.Ordinal))throw new InvalidOperationException("SYNAPSE_AUTHORITY_FILE_SECURITY_MISMATCH path="+full+" expected="+expectedSecuritySddl+" actual="+sddl);
                if(!final.Equals(full,StringComparison.OrdinalIgnoreCase)) throw new InvalidOperationException("SYNAPSE_AUTHORITY_FINAL_PATH_MISMATCH expected="+full+" actual="+final);
                stream=new FileStream(view,FileAccess.Read,65536,false); view=null;
                long len; string hash=Hash(stream,out len);
                if(!String.IsNullOrWhiteSpace(expectedId) && !id.Equals(expectedId,StringComparison.OrdinalIgnoreCase)) throw new InvalidOperationException("SYNAPSE_AUTHORITY_FILE_ID_MISMATCH path="+full+" expected="+expectedId+" actual="+id);
                if(!String.IsNullOrWhiteSpace(expectedSha) && !hash.Equals(expectedSha,StringComparison.OrdinalIgnoreCase)) throw new InvalidOperationException("SYNAPSE_AUTHORITY_SHA_MISMATCH path="+full+" expected="+expectedSha+" actual="+hash);
                if(expectedLength>=0 && len!=expectedLength) throw new InvalidOperationException("SYNAPSE_AUTHORITY_LENGTH_MISMATCH path="+full+" expected="+expectedLength+" actual="+len);
                ExactFile result=new ExactFile(stream,owned,full,id,hash,len,links,sddl,names);stream=null;owned=IntPtr.Zero;return result;
            } catch(Exception error){primary=error;throw;}
            finally { try{if(stream!=null)stream.Dispose();else if(view!=null)view.Dispose();}catch(Exception closeViewError){if(primary!=null)Environment.FailFast("SYNAPSE_AUTHORITY_EXACT_STREAM_RELEASE_UNPROVEN path="+full+" primary=["+primary.Message+"]",closeViewError);primary=closeViewError;}finally{CloseOwnedChecked(ref owned,"open_failure_"+full,primary);} }
        }
        public static ExactFile Open(string input,string expectedId,string expectedSha,long expectedLength) {
            // Immutable launch/data objects deny write and delete continuously.
            return OpenCore(input,expectedId,expectedSha,expectedLength,FILE_SHARE_READ,1,String.Empty,null);
        }
        public static ExactFile OpenProtectedOs(string input,string expectedId,string expectedSha,long expectedLength,uint expectedLinkCount,string expectedSecuritySddl,string[] expectedHardLinks) {
            if(expectedLinkCount<2||expectedHardLinks==null||expectedHardLinks.Length!=(int)expectedLinkCount||String.IsNullOrWhiteSpace(expectedSecuritySddl))throw new ArgumentException("SYNAPSE_AUTHORITY_PROTECTED_OS_CONTRACT_INVALID path="+input);
            return OpenCore(input,expectedId,expectedSha,expectedLength,FILE_SHARE_READ,expectedLinkCount,expectedSecuritySddl,expectedHardLinks);
        }
        public static ExactFile DiscoverProtectedOs(string input,uint expectedLinkCount) {
            if(expectedLinkCount<2)throw new ArgumentOutOfRangeException("expectedLinkCount");return OpenCore(input,String.Empty,String.Empty,-1,FILE_SHARE_READ,expectedLinkCount,String.Empty,null);
        }
