                int terminal=Marshal.GetLastWin32Error();if(terminal!=18)throw new System.ComponentModel.Win32Exception(terminal,"SYNAPSE_LEGACY_COMPATIBILITY_THREAD_ENUM_NEXT_FAILED context="+context+" pid="+processId);if(suspended<1)throw new InvalidOperationException("SYNAPSE_LEGACY_COMPATIBILITY_THREAD_SET_EMPTY context="+context+" pid="+processId);
            } finally { foreach(IntPtr thread in opened){IntPtr value=thread;CloseChecked(ref value,context+"_thread");}if(snapshot!=IntPtr.Zero&&snapshot!=new IntPtr(-1)){IntPtr value=snapshot;CloseChecked(ref value,context+"_snapshot");} }
        }
        public uint CaptureAndSuspendCompatibilitySupervisorVerified(int timeoutMilliseconds,string expectedPath,string expectedId,string expectedSha,long expectedLength,uint expectedLinkCount,string expectedSecuritySddl,string[] expectedHardLinks) {
            if(disposed||!recoveryKeeper||ownedRecoveryRoot==null||!ownedRecoveryRoot.resumed||recoveryJob==null||remoteRecoveryJobHandle==IntPtr.Zero)throw new InvalidOperationException("SYNAPSE_LEGACY_COMPATIBILITY_CAPTURE_STATE_INVALID keeper_pid="+ProcessId);
            VerifiedChildProcess debugOwner=ownedRecoveryRoot;if(timeoutMilliseconds<1||timeoutMilliseconds>30000||!debugOwner.compatibilityDebugAttached||debugOwner.compatibilityDebugProcessId!=ownedRecoveryRoot.ProcessId)throw new InvalidOperationException("SYNAPSE_LEGACY_COMPATIBILITY_DESCENDANT_DEBUG_OWNER_INVALID root_pid="+ownedRecoveryRoot.ProcessId);System.Diagnostics.Stopwatch clock=System.Diagnostics.Stopwatch.StartNew();
            while(clock.ElapsedMilliseconds<timeoutMilliseconds){DEBUG_EVENT debugEvent;uint remaining=(uint)Math.Max(1,Math.Min(1000,timeoutMilliseconds-clock.ElapsedMilliseconds));if(!WaitForDebugEvent(out debugEvent,remaining)){int error=Marshal.GetLastWin32Error();if(error==121)continue;throw new System.ComponentModel.Win32Exception(error,"SYNAPSE_LEGACY_COMPATIBILITY_DESCENDANT_DEBUG_EVENT_WAIT_FAILED root_pid="+ownedRecoveryRoot.ProcessId);}if(debugEvent.dwDebugEventCode==CREATE_PROCESS_DEBUG_EVENT&&debugEvent.dwProcessId!=ownedRecoveryRoot.ProcessId){uint supervisorPid=debugEvent.dwProcessId;IntPtr imageFile=debugEvent.u.CreateProcessInfo.hFile;try{if(imageFile==IntPtr.Zero)throw new InvalidOperationException("SYNAPSE_LEGACY_COMPATIBILITY_DESCENDANT_IMAGE_HANDLE_MISSING pid="+supervisorPid);recoveryJob.RequireContainsProcess(debugEvent.u.CreateProcessInfo.hProcess,supervisorPid,"compatibility_descendant_debug_event");recoveryJob.RequireExactProcessIds(new ulong[]{ProcessId,ownedRecoveryRoot.ProcessId,supervisorPid},"compatibility_capture_frozen_members");string liveImage=ReadProcessImagePath(debugEvent.u.CreateProcessInfo.hProcess,"compatibility_descendant_image_path");if(!liveImage.Equals(Path.GetFullPath(expectedPath),StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("SYNAPSE_LEGACY_COMPATIBILITY_DESCENDANT_IMAGE_PATH_MISMATCH pid="+supervisorPid+" expected="+expectedPath+" actual="+liveImage);ExactFile.RequireRawHandleIdentityProtectedOs(imageFile,expectedPath,expectedId,expectedSha,expectedLength,expectedLinkCount,expectedSecuritySddl,expectedHardLinks,"compatibility_descendant_debug_image");}catch{if(imageFile!=IntPtr.Zero){IntPtr value=imageFile;CloseChecked(ref value,"compatibility_descendant_rejected_image");}ContinueDebugEvent(debugEvent.dwProcessId,debugEvent.dwThreadId,DBG_CONTINUE);throw;}if(imageFile!=IntPtr.Zero){IntPtr value=imageFile;CloseChecked(ref value,"compatibility_descendant_image");}debugOwner.compatibilityDebugChildProcessId=supervisorPid;debugOwner.compatibilityDebugEventThreadId=debugEvent.dwThreadId;debugOwner.compatibilityDebugEventOutstanding=true;return supervisorPid;}if(!ContinueDebugEvent(debugEvent.dwProcessId,debugEvent.dwThreadId,DBG_CONTINUE))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error(),"SYNAPSE_LEGACY_COMPATIBILITY_DESCENDANT_DEBUG_EVENT_CONTINUE_FAILED pid="+debugEvent.dwProcessId);}
            throw new TimeoutException("SYNAPSE_LEGACY_COMPATIBILITY_SUPERVISOR_CAPTURE_TIMEOUT timeout_ms="+timeoutMilliseconds);
        }
        public void DetachCompatibilitySupervisorDebugVerified() { if(!compatibilityDebugAttached)return;if(compatibilityDebugEventOutstanding){if(!ContinueDebugEvent(compatibilityDebugChildProcessId,compatibilityDebugEventThreadId,DBG_CONTINUE))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error(),"SYNAPSE_LEGACY_COMPATIBILITY_CHILD_DEBUG_CONTINUE_FAILED pid="+compatibilityDebugChildProcessId);compatibilityDebugEventOutstanding=false;}if(compatibilityDebugChildProcessId!=0u&&!DebugActiveProcessStop(compatibilityDebugChildProcessId))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error(),"SYNAPSE_LEGACY_COMPATIBILITY_CHILD_DEBUG_DETACH_FAILED pid="+compatibilityDebugChildProcessId);if(!DebugActiveProcessStop(compatibilityDebugProcessId))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error(),"SYNAPSE_LEGACY_COMPATIBILITY_ROOT_DEBUG_DETACH_FAILED pid="+compatibilityDebugProcessId);compatibilityDebugAttached=false;compatibilityDebugProcessId=0u;compatibilityDebugChildProcessId=0u;compatibilityDebugEventThreadId=0u; }
        public void DetachOwnedCompatibilitySupervisorDebugVerified() { if(ownedRecoveryRoot!=null)ownedRecoveryRoot.DetachCompatibilitySupervisorDebugVerified();else DetachCompatibilitySupervisorDebugVerified(); }
        public bool Wait(int milliseconds) { if(disposed||processHandle==IntPtr.Zero)throw new ObjectDisposedException("VerifiedChildProcess");uint wait=WaitForSingleObject(processHandle,(uint)milliseconds);if(wait==WAIT_OBJECT_0)return true;if(wait==WAIT_TIMEOUT)return false;throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error(),"SYNAPSE_BROKER_CHILD_WAIT_FAILED pid="+ProcessId); }
        public uint ExitCode { get { if(disposed||processHandle==IntPtr.Zero)throw new ObjectDisposedException("VerifiedChildProcess");uint code;if(!GetExitCodeProcess(processHandle,out code))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error(),"SYNAPSE_BROKER_CHILD_EXIT_QUERY_FAILED pid="+ProcessId);if(code==STILL_ACTIVE)throw new InvalidOperationException("SYNAPSE_BROKER_CHILD_EXIT_NOT_READY pid="+ProcessId);return code; } }
        public void TerminateAndWait(int milliseconds,uint exitCode) { if(disposed||processHandle==IntPtr.Zero)return;if(recoveryJob!=null)recoveryJob.TerminateAndProveEmpty(exitCode,milliseconds,"explicit_termination_job");TerminateAndProveHandle(processHandle,exitCode,(uint)milliseconds,"explicit_termination"); }
        public void ReleaseAfterAuthorityTransfer(ulong[] expectedProcessIds) {
            if(disposed||processHandle==IntPtr.Zero||!resumed||!recoveryKeeper||ownedRecoveryRoot==null||!ownedRecoveryRoot.resumed||ownedRecoveryRoot.processHandle==IntPtr.Zero)throw new ObjectDisposedException("VerifiedChildProcess");
            if(recoveryJob==null||!ownsRecoveryJob||remoteRecoveryJobHandle==IntPtr.Zero)throw new InvalidOperationException("SYNAPSE_LEGACY_RECOVERY_JOB_TRANSFER_MISSING pid="+ProcessId);
            if(threadHandle!=IntPtr.Zero||ownedRecoveryRoot.threadHandle!=IntPtr.Zero)throw new InvalidOperationException("SYNAPSE_LEGACY_RESCUE_TRANSFER_THREAD_HANDLE_LIVE pid="+ProcessId+" root_pid="+ownedRecoveryRoot.ProcessId);
            if(expectedProcessIds==null||expectedProcessIds.Length!=4)throw new ArgumentException("SYNAPSE_LEGACY_RECOVERY_JOB_TRANSFER_EXPECTED_CARDINALITY_INVALID");
            ulong[] expected=(ulong[])expectedProcessIds.Clone();Array.Sort(expected);for(int index=0;index<expected.Length;index++){if(expected[index]==0||expected[index]>UInt32.MaxValue)throw new ArgumentException("SYNAPSE_LEGACY_RECOVERY_JOB_TRANSFER_EXPECTED_PID_INVALID pid="+expected[index]);if(index>0&&expected[index-1]==expected[index])throw new ArgumentException("SYNAPSE_LEGACY_RECOVERY_JOB_TRANSFER_EXPECTED_PID_DUPLICATE pid="+expected[index]);}
            if(Array.BinarySearch(expected,(ulong)ProcessId)<0||Array.BinarySearch(expected,(ulong)ownedRecoveryRoot.ProcessId)<0)throw new InvalidOperationException("SYNAPSE_LEGACY_RECOVERY_JOB_TRANSFER_ROOTS_MISSING keeper_pid="+ProcessId+" root_pid="+ownedRecoveryRoot.ProcessId);
            uint keeperCode,rootCode;if(!GetExitCodeProcess(processHandle,out keeperCode)||!GetExitCodeProcess(ownedRecoveryRoot.processHandle,out rootCode))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error(),"SYNAPSE_LEGACY_RESCUE_TRANSFER_EXIT_QUERY_FAILED keeper_pid="+ProcessId+" root_pid="+ownedRecoveryRoot.ProcessId);if(keeperCode!=STILL_ACTIVE||rootCode!=STILL_ACTIVE)throw new InvalidOperationException("SYNAPSE_LEGACY_RESCUE_TRANSFER_PROCESS_EXITED keeper_exit="+keeperCode+" root_exit="+rootCode);
            recoveryJob.RequireContract("transfer");recoveryJob.RequireRemoteHandleExact(processHandle,ProcessId,remoteRecoveryJobHandle,"transfer_remote");recoveryJob.RequireExactProcessIds(expected,"transfer_members");
            string jobName=recoveryJob.JobName,jobSddl=recoveryJob.SecurityDescriptorSddl;LegacyRecoveryJob reopened=null;
            try {
                CloseChecked(ref ownedRecoveryRoot.processHandle,"transfer_root_process");ownedRecoveryRoot.recoveryJob=null;ownedRecoveryRoot.disposed=true;
                recoveryJob.Dispose();recoveryJob=null;ownsRecoveryJob=false;
                reopened=LegacyRecoveryJob.OpenOrNull(jobName,jobSddl);if(reopened==null)throw new InvalidOperationException("SYNAPSE_LEGACY_RECOVERY_JOB_TRANSFER_NAME_DISAPPEARED name="+jobName);
                reopened.RequireRemoteHandleExact(processHandle,ProcessId,remoteRecoveryJobHandle,"transfer_reopened_remote");reopened.RequireExactProcessIds(expected,"transfer_reopened_members");reopened.Dispose();reopened=null;
                if(!GetExitCodeProcess(processHandle,out keeperCode))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error(),"SYNAPSE_LEGACY_RECOVERY_KEEPER_TRANSFER_FINAL_EXIT_QUERY_FAILED pid="+ProcessId);if(keeperCode!=STILL_ACTIVE)throw new InvalidOperationException("SYNAPSE_LEGACY_RECOVERY_KEEPER_TRANSFER_FINAL_EXITED pid="+ProcessId+" exit="+keeperCode);
                CloseChecked(ref processHandle,"transfer_keeper_process");disposed=true;
            } catch(Exception closeError) { if(reopened!=null)try{reopened.Dispose();}catch(Exception finalClose){Environment.FailFast("SYNAPSE_LEGACY_RESCUE_TRANSFER_REOPENED_HANDLE_RELEASE_UNPROVEN pid="+ProcessId,finalClose);}Environment.FailFast("SYNAPSE_LEGACY_RESCUE_TRANSFER_HANDLE_RELEASE_UNPROVEN pid="+ProcessId,closeError); }
        }
        public void Dispose() { if(disposed)return;try{if(recoveryJob!=null)recoveryJob.TerminateAndProveEmpty(127u,30000,"dispose_job");if(ownedRecoveryRoot!=null&&ownedRecoveryRoot.processHandle!=IntPtr.Zero)TerminateAndProveHandle(ownedRecoveryRoot.processHandle,127u,30000u,"dispose_root");if(processHandle!=IntPtr.Zero)TerminateAndProveHandle(processHandle,127u,30000u,"dispose");}catch(Exception cleanupError){Environment.FailFast("SYNAPSE_BROKER_CHILD_DISPOSE_CLEANUP_UNPROVEN pid="+ProcessId,cleanupError);}try{if(ownedRecoveryRoot!=null){CloseChecked(ref ownedRecoveryRoot.threadHandle,"dispose_root_thread");CloseChecked(ref ownedRecoveryRoot.processHandle,"dispose_root_process");CloseChecked(ref ownedRecoveryRoot.standardOutputReadHandle,"dispose_root_stdout");CloseChecked(ref ownedRecoveryRoot.standardErrorReadHandle,"dispose_root_stderr");ownedRecoveryRoot.recoveryJob=null;ownedRecoveryRoot.disposed=true;ownedRecoveryRoot=null;}CloseChecked(ref threadHandle,"dispose_thread");CloseChecked(ref processHandle,"dispose_process");CloseChecked(ref standardOutputReadHandle,"dispose_stdout");CloseChecked(ref standardErrorReadHandle,"dispose_stderr");if(recoveryJob!=null&&ownsRecoveryJob)recoveryJob.Dispose();recoveryJob=null;ownsRecoveryJob=false;disposed=true;}catch(Exception closeError){Environment.FailFast("SYNAPSE_BROKER_CHILD_DISPOSE_HANDLE_RELEASE_UNPROVEN pid="+ProcessId,closeError);} }
    }
}
"@ -Language CSharp
}
'@
}

function Initialize-SynapseAuthorityRuntimeForSetup {
    if(('SynapseAuthorityRuntime.ExactFile' -as [type]) -and
       ('SynapseAuthorityRuntime.MappedProcessLease' -as [type]) -and
       ('SynapseAuthorityRuntime.LegacyRecoveryJob' -as [type]) -and
       ('SynapseAuthorityRuntime.VerifiedChildProcess' -as [type])){return}
    $source=Get-SynapseAuthorityExactReaderPowerShell
    & ([scriptblock]::Create($source))
    if(-not('SynapseAuthorityRuntime.ExactFile' -as [type]) -or
       -not('SynapseAuthorityRuntime.MappedProcessLease' -as [type]) -or
       -not('SynapseAuthorityRuntime.LegacyRecoveryJob' -as [type]) -or
       -not('SynapseAuthorityRuntime.VerifiedChildProcess' -as [type])){
        Die 'SYNAPSE_AUTHORITY_RUNTIME_NATIVE_TYPE_LOAD_FAILED remediation=the exact file, mapped-process lease, recovery Job, and debug-event child bridge must compile before any legacy authority transition'
    }
}

function Normalize-SynapseAllowedPermissionsArgument {
    param([AllowNull()][string]$Value)
    if ([string]::IsNullOrWhiteSpace($Value)) {
        return ''
    }

    $tokens = @($Value -split '[,;\s]+' | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    if ($tokens.Count -eq 0) {
        return ''
    }

    return ($tokens -join ',')
}

$normalizedSetupPermissions = Normalize-SynapseAllowedPermissionsArgument -Value $AllowedPermissions
$setupReadAudioGranted = @($normalizedSetupPermissions -split ',' | Where-Object { $_ -ieq 'READ_AUDIO' }).Count -gt 0
if ([bool]$EnableAudio -ne $setupReadAudioGranted) {
    Die "SYNAPSE_AUDIO_DEPLOYMENT_CONTRACT_INVALID enable_audio=$([bool]$EnableAudio) read_audio_granted=$setupReadAudioGranted allowed_permissions=$normalizedSetupPermissions remediation=enable audio with -EnableAudio and include READ_AUDIO in -AllowedPermissions, or disable both; Synapse refuses a durable launch configuration where capture and authorization disagree"
}

function Vbs-Literal {
    param([Parameter(Mandatory=$true)][string]$Value)
    return '"' + ($Value -replace '"', '""') + '"'
}

function Get-SynapseDaemonArgumentText {
    param(
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$DbPath,
        [Parameter(Mandatory=$true)][string]$ProfilesDir,
        [bool]$EnableAudio,
        [AllowNull()][string]$AllowedPermissions,
        [Parameter(Mandatory=$true)][string]$CalyxConfigPath,
        [Parameter(Mandatory=$true)][ValidatePattern('^[0-9A-Fa-f]{64}$')][string]$ExpectedCalyxConfigSha256,
        [ValidateSet(2,3)][int]$CalyxSstWriteVersion = 3,
        [ValidateSet(2500,10000)][uint32]$ExpectedSupervisorCpuRate = 2500,
        [AllowEmptyString()][string]$ExpectedSupervisorBootstrapPath = ''
    )

    $daemonArguments = @(
        '--mode', 'http',
        '--bind', (Quote-WindowsCommandArgument $Bind),
        '--db', (Quote-WindowsCommandArgument $DbPath),
        '--profile-dir', (Quote-WindowsCommandArgument $ProfilesDir),
        '--log-level', 'info'
    )
    $daemonArguments += @(
        '--calyx-config', (Quote-WindowsCommandArgument $CalyxConfigPath),
        '--calyx-config-sha256', $ExpectedCalyxConfigSha256.ToUpperInvariant(),
        '--calyx-sst-write-version', "v$CalyxSstWriteVersion"
    )
    if ($EnableAudio) {
        $daemonArguments += '--enable-audio'
    }
    $allowedPermissionsArgument = Normalize-SynapseAllowedPermissionsArgument -Value $AllowedPermissions
    if (-not [string]::IsNullOrWhiteSpace($allowedPermissionsArgument)) {
        $daemonArguments += @('--allowed-permissions', (Quote-WindowsCommandArgument $allowedPermissionsArgument))
    }
    return ($daemonArguments -join ' ')
}

# ---------------------------------------------------------------------------
# Legacy supervisor stop-request path. Broker adoption publishes the one
# immutable positive v1 record through its physically pinned adoption
# transition; ordinary setup/operator paths have no generic write or clear API.
# ---------------------------------------------------------------------------
$SynapseDaemonSupervisorStopRequestFileName = 'daemon-supervisor-stop-request.json'

function Get-SynapseDaemonSupervisorStopRequestPath {
    param([Parameter(Mandatory=$true)][string]$RuntimeBinDir)
    return (Join-Path $RuntimeBinDir $SynapseDaemonSupervisorStopRequestFileName)
}

function New-HiddenDaemonLauncher {
    param(
        [Parameter(Mandatory=$true)][string]$OutputPath,
        [Parameter(Mandatory=$true)][string]$ExePath,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$DbPath,
        [Parameter(Mandatory=$true)][string]$ProfilesDir,
        [Parameter(Mandatory=$true)][string]$LogDir,
        [Parameter(Mandatory=$true)][string]$TokenPath,
        [Parameter(Mandatory=$true)][string]$MaintenanceLockPath,
        [bool]$EnableAudio,
        [AllowNull()][string]$AllowedPermissions,
        [Parameter(Mandatory=$true)][string]$CalyxConfigPath,
        [Parameter(Mandatory=$true)][ValidatePattern('^[0-9A-Fa-f]{64}$')][string]$ExpectedCalyxConfigSha256,
        [ValidateSet(2,3)][int]$CalyxSstWriteVersion = 3,
        [ValidateSet('legacy','broker','probe')][string]$AuthorityMode = 'legacy',
        [AllowEmptyString()][string]$AuthorityRosterPath = '',
        [AllowEmptyString()][string]$AuthorityLegacyGatePath = '',
        [AllowEmptyString()][string]$AuthorityLegacyGateFileId128 = '',
        [AllowEmptyString()][string]$AuthorityLegacyGateSha256 = '',
        [long]$AuthorityLegacyGateLength = -1,
        [ValidateRange(0,[long]::MaxValue)][long]$AuthorityEpoch = 0,
        [AllowEmptyString()][string]$AuthorityGenerationId = '',
        [AllowEmptyString()][string]$AuthorityLaunchCapabilitySha256 = '',
        [AllowEmptyString()][string]$AuthorityBrokerTaskName = '',
        [AllowEmptyString()][string]$AuthorityBrokerScriptPath = '',
        [AllowEmptyString()][string]$AuthorityBrokerScriptSha256 = '',
        [AllowEmptyString()][string]$AuthorityBootstrapPath = '',
        [AllowEmptyString()][string]$AuthorityBootstrapSha256 = '',
        [AllowEmptyString()][string]$AuthorityTransactionId = '',
        [AllowEmptyString()][string]$AuthorityShellJobRoot = '',
        [AllowEmptyString()][string]$AuthorityReplacementReservationId = '',
        [ValidateSet(0,2500,10000)][uint32]$ExpectedParentJobCpuRate = 0,
        [bool]$OneShot = $false,
        [switch]$ContentOnly
    )

    if ($ExpectedParentJobCpuRate -eq 0) {
        $ExpectedParentJobCpuRate = if ($AuthorityMode -eq 'broker') { [uint32]10000 } else { [uint32]2500 }
    }
    if (($AuthorityMode -eq 'broker' -and $ExpectedParentJobCpuRate -ne 10000) -or
        ($AuthorityMode -ne 'broker' -and $ExpectedParentJobCpuRate -ne 2500)) {
        Die "SYNAPSE_SUPERVISOR_PARENT_CPU_MODE_INVALID mode=$AuthorityMode expected_parent_cpu_rate=$ExpectedParentJobCpuRate required=$(if($AuthorityMode -eq 'broker'){10000}else{2500})"
    }

    if ($AuthorityMode -eq 'broker') {
        if ([string]::IsNullOrWhiteSpace($AuthorityRosterPath) -or
            [string]::IsNullOrWhiteSpace($AuthorityLegacyGatePath) -or
            $AuthorityLegacyGateFileId128 -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or
            $AuthorityLegacyGateSha256 -notmatch '^[0-9A-Fa-f]{64}$' -or $AuthorityLegacyGateLength -lt 1 -or
            $AuthorityEpoch -lt 1 -or
            [string]::IsNullOrWhiteSpace($AuthorityGenerationId) -or
            $AuthorityLaunchCapabilitySha256 -notmatch '^[0-9A-Fa-f]{64}$' -or
            [string]::IsNullOrWhiteSpace($AuthorityBrokerTaskName) -or
            [string]::IsNullOrWhiteSpace($AuthorityBrokerScriptPath) -or
            $AuthorityBrokerScriptSha256 -notmatch '^[0-9A-Fa-f]{64}$' -or
            [string]::IsNullOrWhiteSpace($AuthorityBootstrapPath) -or
            $AuthorityBootstrapSha256 -notmatch '^[0-9A-Fa-f]{64}$') {
            Die "SYNAPSE_SUPERVISOR_AUTHORITY_GENERATION_INVALID mode=$AuthorityMode epoch=$AuthorityEpoch generation_id=$AuthorityGenerationId roster=$AuthorityRosterPath broker_task=$AuthorityBrokerTaskName broker_script=$AuthorityBrokerScriptPath broker_sha256=$AuthorityBrokerScriptSha256 bootstrap=$AuthorityBootstrapPath bootstrap_sha256=$AuthorityBootstrapSha256"
        }
        $AuthorityRosterPath = [System.IO.Path]::GetFullPath($AuthorityRosterPath)
        $AuthorityLegacyGatePath = [System.IO.Path]::GetFullPath($AuthorityLegacyGatePath)
        $AuthorityLegacyGateFileId128 = $AuthorityLegacyGateFileId128.ToUpperInvariant()
        $AuthorityLegacyGateSha256 = $AuthorityLegacyGateSha256.ToUpperInvariant()
        $AuthorityBrokerScriptPath = [System.IO.Path]::GetFullPath($AuthorityBrokerScriptPath)
        $AuthorityBootstrapPath = [System.IO.Path]::GetFullPath($AuthorityBootstrapPath)
        $AuthorityBrokerScriptSha256 = $AuthorityBrokerScriptSha256.ToUpperInvariant()
        $AuthorityBootstrapSha256 = $AuthorityBootstrapSha256.ToUpperInvariant()
        $AuthorityLaunchCapabilitySha256 = $AuthorityLaunchCapabilitySha256.ToUpperInvariant()
    } elseif ($AuthorityMode -eq 'probe') {
        $requiredTaskPrefix = 'SynapseMcpProbe-'
        if (-not $OneShot -or
            [string]::IsNullOrWhiteSpace($AuthorityTransactionId) -or
            $AuthorityTransactionId.Length -gt 128 -or
            [string]::IsNullOrWhiteSpace($AuthorityBrokerTaskName) -or
            -not $AuthorityBrokerTaskName.StartsWith($requiredTaskPrefix, [System.StringComparison]::Ordinal) -or
            [string]::IsNullOrWhiteSpace($AuthorityBootstrapPath) -or
            $AuthorityBootstrapSha256 -notmatch '^[0-9A-Fa-f]{64}$' -or
            ($AuthorityMode -eq 'probe' -and [string]::IsNullOrWhiteSpace($AuthorityShellJobRoot))) {
            Die "SYNAPSE_SUPERVISOR_ONESHOT_AUTHORITY_INVALID mode=$AuthorityMode transaction_id=$AuthorityTransactionId task=$AuthorityBrokerTaskName bootstrap=$AuthorityBootstrapPath bootstrap_sha256=$AuthorityBootstrapSha256 one_shot=$OneShot"
        }
        $AuthorityBootstrapPath = [System.IO.Path]::GetFullPath($AuthorityBootstrapPath)
        $AuthorityBootstrapSha256 = $AuthorityBootstrapSha256.ToUpperInvariant()
        if (-not [string]::IsNullOrWhiteSpace($AuthorityShellJobRoot)) {
            $AuthorityShellJobRoot = [System.IO.Path]::GetFullPath($AuthorityShellJobRoot)
        }
    }

    $daemonLogDir = $LogDir
    $launcherLog = Join-Path $LogDir 'daemon-launcher.log'
    $supervisorPath = Join-Path (Split-Path -Parent $OutputPath) 'synapse-daemon-supervisor.ps1'
    $supervisorState = Join-Path $LogDir 'daemon-supervisor-current.json'
    $supervisorEvents = Join-Path $LogDir 'daemon-supervisor-events.jsonl'
    # #2083: the operator stop-request (restart-authority revocation) record.
    # It lives beside the supervisor in $RuntimeBinDir, NOT in $LogDir, for the
    # same reason the launcher and supervisor moved out of $LogDir in #1862: a
    # log retention sweep must never be able to change autostart behaviour. A
    # stop-request deleted by a log sweep would silently RESTORE restart
    # authority, which is the fail-open direction.
    $supervisorStopRequestPath = if ($AuthorityMode -eq 'legacy') {
        Get-SynapseDaemonSupervisorStopRequestPath -RuntimeBinDir (Split-Path -Parent $OutputPath)
    } else {
        $AuthorityLegacyGatePath
    }
    if ([string]::IsNullOrWhiteSpace($CalyxConfigPath) -or
        -not (Test-Path -LiteralPath $CalyxConfigPath -PathType Leaf)) {
        Die "SYNAPSE_DAEMON_CPU_CONFIG_MISSING path=$(if ($CalyxConfigPath) { $CalyxConfigPath } else { '<absent>' }) remediation=generate or supply the explicit CPU-only Calyx config before creating the persistent supervisor"
    }
    $expectedCalyxConfigSha256 = $ExpectedCalyxConfigSha256.ToUpperInvariant()
    $actualCalyxConfigSha256 = Get-SynapseFileSha256 -Path $CalyxConfigPath
    if ($actualCalyxConfigSha256 -ine $expectedCalyxConfigSha256) {
        Die "SYNAPSE_DAEMON_CPU_CONFIG_IDENTITY_MISMATCH path=$CalyxConfigPath expected_sha256=$expectedCalyxConfigSha256 actual_sha256=$actualCalyxConfigSha256 remediation=refuse launcher generation; preserve the exact candidate-validated config bytes through handoff"
    }
    $allowedPermissionsArgument = Normalize-SynapseAllowedPermissionsArgument -Value $AllowedPermissions
    $daemonArgumentText = Get-SynapseDaemonArgumentText `
        -Bind $Bind `
        -DbPath $DbPath `
        -ProfilesDir $ProfilesDir `
        -EnableAudio $EnableAudio `
        -AllowedPermissions $AllowedPermissions `
        -CalyxConfigPath $CalyxConfigPath `
        -ExpectedCalyxConfigSha256 $expectedCalyxConfigSha256 `
        -CalyxSstWriteVersion $CalyxSstWriteVersion
    $powerShellExe = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
    if (-not (Test-Path -LiteralPath $powerShellExe -PathType Leaf)) {
        Die "SYNAPSE_HIDDEN_SUPERVISOR_POWERSHELL_MISSING path=$powerShellExe remediation=repair Windows PowerShell before registering the daemon supervisor"
    }

$supervisorScript = @'
param(
    [Parameter(Mandatory=$true)]
    [ValidatePattern('^Local\\SynapseOwned-[A-Za-z0-9-]+$')]
    [string]$ParentJobName
)

# The native bootstrap inherits setup's pwsh environment verbatim. Pin module
# discovery before the first command can auto-load a Core-only PowerShell 7
# module into this Windows PowerShell 5.1 supervisor.
$trustedWinPsModuleRoot = [System.IO.Path]::Combine([string]$PSHOME, 'Modules')
$env:PSModulePath = $trustedWinPsModuleRoot

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

__AUTHORITY_EXACT_READER__

$ExePath = __EXE_PATH__
$Bind = __BIND__
$DbPath = __DB_PATH__
$ProfilesDir = __PROFILES_DIR__
$DaemonLogDir = __DAEMON_LOG_DIR__
$TokenPath = __TOKEN_PATH__
$LauncherLog = __LAUNCHER_LOG__
$SupervisorState = __SUPERVISOR_STATE__
$SupervisorEvents = __SUPERVISOR_EVENTS__
$MaintenanceLockPath = __MAINTENANCE_LOCK_PATH__
$SupervisorStopRequestPath = __SUPERVISOR_STOP_REQUEST_PATH__
$ExpectedCalyxConfigPath = __EXPECTED_CALYX_CONFIG_PATH__
$ExpectedCalyxConfigSha256 = __EXPECTED_CALYX_CONFIG_SHA256__
$DaemonArgumentText = __DAEMON_ARGUMENT_TEXT__
$ExpectedAllowedPermissions = __EXPECTED_ALLOWED_PERMISSIONS__
$ExpectedEnableAudio = __EXPECTED_ENABLE_AUDIO__
$ProcessMemoryLimitBytes = [uint64]__PROCESS_MEMORY_LIMIT_BYTES__
$SupervisorMemoryLimitBytes = [uint64]__SUPERVISOR_MEMORY_LIMIT_BYTES__
$BootstrapPreAssociationReserveBytes = [uint64]__BOOTSTRAP_PREASSOCIATION_RESERVE_BYTES__
$CommittedPrivatePolicyCeilingBytes = [uint64]7000000000
$DaemonCpuRate = [uint32]__DAEMON_CPU_RATE__
$SupervisorCpuRate = [uint32]__SUPERVISOR_CPU_RATE__
$OneShot = [System.Convert]::ToBoolean(__ONE_SHOT__)
$AuthorityMode = __AUTHORITY_MODE__
$AuthorityRosterPath = __AUTHORITY_ROSTER_PATH__
$AuthorityLegacyGateFileId128 = __AUTHORITY_LEGACY_GATE_FILE_ID_128__
$AuthorityLegacyGateSha256 = __AUTHORITY_LEGACY_GATE_SHA256__
$AuthorityLegacyGateLength = [int64]__AUTHORITY_LEGACY_GATE_LENGTH__
$AuthorityEpoch = [int64]__AUTHORITY_EPOCH__
$AuthorityGenerationId = __AUTHORITY_GENERATION_ID__
$AuthorityLaunchCapabilitySha256 = __AUTHORITY_LAUNCH_CAPABILITY_SHA256__
$AuthorityBrokerTaskName = __AUTHORITY_BROKER_TASK_NAME__
$AuthorityBrokerScriptPath = __AUTHORITY_BROKER_SCRIPT_PATH__
$AuthorityBrokerScriptSha256 = __AUTHORITY_BROKER_SCRIPT_SHA256__
$AuthorityBootstrapPath = __AUTHORITY_BOOTSTRAP_PATH__
$AuthorityBootstrapSha256 = __AUTHORITY_BOOTSTRAP_SHA256__
$AuthorityTransactionId = __AUTHORITY_TRANSACTION_ID__
$AuthorityShellJobRoot = __AUTHORITY_SHELL_JOB_ROOT__
$AuthorityReplacementReservationId = __AUTHORITY_REPLACEMENT_RESERVATION_ID__
$script:SynapseAuthorityRosterLease = $null
$script:SynapseAuthorityGateLease = $null
$script:SynapseAuthorityObjectLeases = New-Object 'System.Collections.Generic.List[System.IDisposable]'
$script:SynapseAuthorityValidatedPayload = $null
$script:SynapseAuthorityProfilesLease = $null
$supervisorJobLifetimeOwner = 'native_bootstrap_only'
$supervisorResourceJob = $null
$supervisorJobName = $null

$restartFloorSeconds = 2
$restartCeilingSeconds = 60
$rapidFailureWindowSeconds = 60
$rapidFailureLimit = 5
$deadOwnerBindDrainSeconds = 30
$deadOwnerBindDrainPollMilliseconds = 500
$daemonStartupSeconds = 300
$daemonStartupPollMilliseconds = 250
$generation = 0
$rapidFailures = New-Object 'System.Collections.Generic.Queue[datetime]'

function Write-LogLine {
    param([Parameter(Mandatory=$true)][string]$Message)
    $line = '{0} {1}' -f (Get-Date -Format o), $Message
    Add-Content -LiteralPath $LauncherLog -Value $line -Encoding ascii
}

function Write-SupervisorEvent {
    param(
        [Parameter(Mandatory=$true)][string]$Event,
        [hashtable]$Fields = @{}
    )
    $row = [ordered]@{
        ts_utc = (Get-Date).ToUniversalTime().ToString('o')
        event = $Event
        supervisor_pid = $PID
        bind = $Bind
        db_path = $DbPath
    }
    foreach ($key in $Fields.Keys) {
        $row[$key] = $Fields[$key]
    }
    ($row | ConvertTo-Json -Compress -Depth 8) | Add-Content -LiteralPath $SupervisorEvents -Encoding ascii
}

function Write-SupervisorState {
    param(
        [Parameter(Mandatory=$true)][string]$State,
        [int]$Generation,
        [AllowNull()][object]$ChildPid,
        [AllowNull()][object]$ExitCode,
        [Parameter(Mandatory=$true)][string]$Message,
        [hashtable]$Fields = @{}
    )
    if ($null -ne $supervisorResourceJob) {
        $supervisorResourceJob.RefreshAccounting()
        if ([uint64]$supervisorResourceJob.CurrentJobMemoryUsedBytes -gt $SupervisorMemoryLimitBytes -or
            [uint64]$supervisorResourceJob.PeakJobMemoryUsedBytes -gt $SupervisorMemoryLimitBytes -or
            [uint64]$supervisorResourceJob.PeakProcessMemoryUsedBytes -gt $SupervisorMemoryLimitBytes) {
            throw "SYNAPSE_SUPERVISOR_PARENT_JOB_MEMORY_CONTRACT_VIOLATED job_name=$($supervisorResourceJob.JobName) hard_limit_bytes=$SupervisorMemoryLimitBytes current_job_memory_bytes=$($supervisorResourceJob.CurrentJobMemoryUsedBytes) peak_job_memory_bytes=$($supervisorResourceJob.PeakJobMemoryUsedBytes) peak_process_memory_bytes=$($supervisorResourceJob.PeakProcessMemoryUsedBytes) remediation=identify and optimize the retained owner; the supervisor will not publish an in-budget state"
        }
    }
    $stateObject = [ordered]@{
        updated_utc = (Get-Date).ToUniversalTime().ToString('o')
        state = $State
        generation = $Generation
        supervisor_pid = $PID
        child_pid = $ChildPid
        exit_code = $ExitCode
        bind = $Bind
        db_path = $DbPath
        exe_path = $ExePath
        authority_mode = $AuthorityMode
        authority_epoch = $AuthorityEpoch
        authority_generation_id = $AuthorityGenerationId
        authority_roster_path = $AuthorityRosterPath
        authority_broker_task_name = $AuthorityBrokerTaskName
        authority_broker_script_path = $AuthorityBrokerScriptPath
        authority_broker_script_sha256 = $AuthorityBrokerScriptSha256
        authority_bootstrap_path = $AuthorityBootstrapPath
        authority_bootstrap_sha256 = $AuthorityBootstrapSha256
        calyx_config_path = $ExpectedCalyxConfigPath
        calyx_config_sha256 = $ExpectedCalyxConfigSha256
        math_backend = 'cpu'
        vram_budget_bytes = 0
        detection_backend = 'cpu'
        stt_backend = 'cpu'
        capture_backend = 'gdi_bitblt'
        capture_force_dxgi = $false
        search_open_generation_cache_entries = 6
        job_limit_flags_expected_hex = '0x00002300'
        job_cpu_rate_control_flags_expected_hex = '0x00000005'
        daemon_cpu_rate = $DaemonCpuRate
        working_set_policy = 'measured_only'
        job_security_descriptor_sddl = 'D:P(A;;GA;;;SY)(A;;0x00100004;;;OW)'
        process_memory_limit_bytes = $ProcessMemoryLimitBytes
        job_memory_limit_bytes = $ProcessMemoryLimitBytes
        supervisor_job_limit_flags_expected_hex = '0x00002300'
        supervisor_job_cpu_rate_control_flags_expected_hex = '0x00000005'
        supervisor_process_memory_limit_bytes = $SupervisorMemoryLimitBytes
        supervisor_job_memory_limit_bytes = $SupervisorMemoryLimitBytes
        supervisor_cpu_rate = $SupervisorCpuRate
        owned_combined_memory_limit_bytes = $SupervisorMemoryLimitBytes
        bootstrap_preassociation_reserve_bytes = $BootstrapPreAssociationReserveBytes
        owned_committed_private_ceiling_bytes = $CommittedPrivatePolicyCeilingBytes
        supervisor_job_name = $(if ($null -eq $supervisorResourceJob) { $null } else { $supervisorResourceJob.JobName })
        supervisor_job_lifetime_owner = $supervisorJobLifetimeOwner
        supervisor_job_accounting_source = 'QueryInformationJobObject(NULL/immediate)'
        supervisor_job_limit_flags_hex = $(if ($null -eq $supervisorResourceJob) { $null } else { '0x{0:X8}' -f $supervisorResourceJob.JobLimitFlags })
        supervisor_job_cpu_rate_control_flags_hex = $(if ($null -eq $supervisorResourceJob) { $null } else { '0x{0:X8}' -f $supervisorResourceJob.CpuRateControlFlags })
        supervisor_job_process_memory_limit_bytes = $(if ($null -eq $supervisorResourceJob) { $null } else { $supervisorResourceJob.ProcessMemoryLimitBytes })
        supervisor_job_memory_limit_bytes_actual = $(if ($null -eq $supervisorResourceJob) { $null } else { $supervisorResourceJob.JobMemoryLimitBytes })
        supervisor_job_cpu_rate = $(if ($null -eq $supervisorResourceJob) { $null } else { $supervisorResourceJob.CpuRate })
        supervisor_job_current_memory_used_bytes = $(if ($null -eq $supervisorResourceJob) { $null } else { $supervisorResourceJob.CurrentJobMemoryUsedBytes })
        supervisor_job_memory_headroom_bytes = $(if ($null -eq $supervisorResourceJob) { $null } elseif ($supervisorResourceJob.CurrentJobMemoryUsedBytes -ge $SupervisorMemoryLimitBytes) { [uint64]0 } else { [uint64]($SupervisorMemoryLimitBytes - $supervisorResourceJob.CurrentJobMemoryUsedBytes) })
        supervisor_job_peak_process_memory_used_bytes = $(if ($null -eq $supervisorResourceJob) { $null } else { $supervisorResourceJob.PeakProcessMemoryUsedBytes })
        supervisor_job_peak_memory_used_bytes = $(if ($null -eq $supervisorResourceJob) { $null } else { $supervisorResourceJob.PeakJobMemoryUsedBytes })
        message = $Message
    }
    foreach ($key in $Fields.Keys) {
        $stateObject[$key] = $Fields[$key]
    }
    $stateJson = $stateObject | ConvertTo-Json -Depth 8
    [SynapseDaemonSupervisor.BoundedProcess]::PersistUtf8Atomic($SupervisorState, $stateJson)
}

function Initialize-SynapseDaemonBoundedProcessType {
    if ('SynapseDaemonSupervisor.BoundedProcess' -as [type]) { return }

    try {
        Add-Type -Language CSharp -TypeDefinition @"
using System;
using System.ComponentModel;
using System.IO;
using System.Runtime.InteropServices;
using System.Text;

namespace SynapseDaemonSupervisor
{
    public sealed class BoundedProcess : IDisposable
    {
        private const uint CREATE_SUSPENDED = 0x00000004;
        private const uint CREATE_NO_WINDOW = 0x08000000;
        private const uint EXTENDED_STARTUPINFO_PRESENT = 0x00080000;
        private const uint STARTF_USESHOWWINDOW = 0x00000001;
        private static readonly IntPtr PROC_THREAD_ATTRIBUTE_JOB_LIST =
            new IntPtr(0x0002000D);
        private static readonly IntPtr PROC_THREAD_ATTRIBUTE_HANDLE_LIST =
            new IntPtr(0x00020002);
        private const uint STARTF_USESTDHANDLES = 0x00000100;
        private const ushort SW_HIDE = 0;
        private const uint JOB_OBJECT_LIMIT_PROCESS_MEMORY = 0x00000100;
        private const uint JOB_OBJECT_LIMIT_JOB_MEMORY = 0x00000200;
        private const uint JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE = 0x00002000;
        private const uint JOB_OBJECT_QUERY = 0x00000004;
        private const uint EXPECTED_JOB_LIMIT_FLAGS =
            JOB_OBJECT_LIMIT_PROCESS_MEMORY |
            JOB_OBJECT_LIMIT_JOB_MEMORY |
            JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;
        private const uint EXPECTED_SUPERVISOR_JOB_LIMIT_FLAGS =
            JOB_OBJECT_LIMIT_PROCESS_MEMORY |
            JOB_OBJECT_LIMIT_JOB_MEMORY |
            JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;
        private const int JobObjectExtendedLimitInformation = 9;
        private const int JobObjectCpuRateControlInformation = 15;
        // Raw JOBOBJECTINFOCLASS 28. Microsoft hcsshim uses this exact
        // two-ULONG64 ABI for current and peak aggregate Job commit.
        private const int JobObjectMemoryUsageInformation = 28;
        private const uint JOB_OBJECT_CPU_RATE_CONTROL_ENABLE = 0x00000001;
        private const uint JOB_OBJECT_CPU_RATE_CONTROL_HARD_CAP = 0x00000004;
        private const uint EXPECTED_CPU_RATE_CONTROL_FLAGS =
            JOB_OBJECT_CPU_RATE_CONTROL_ENABLE | JOB_OBJECT_CPU_RATE_CONTROL_HARD_CAP;
        private const uint FILE_APPEND_DATA = 0x00000004;
        private const uint GENERIC_READ = 0x80000000;
        private const uint GENERIC_WRITE = 0x40000000;
        private const uint FILE_SHARE_READ = 0x00000001;
        private const uint FILE_SHARE_WRITE = 0x00000002;
        private const uint FILE_SHARE_DELETE = 0x00000004;
        private const uint OPEN_EXISTING = 3;
        private const uint OPEN_ALWAYS = 4;
        private const uint FILE_ATTRIBUTE_NORMAL = 0x00000080;
        private const uint FILE_ATTRIBUTE_REPARSE_POINT = 0x00000400;
        private const uint MOVEFILE_REPLACE_EXISTING = 0x00000001;
        private const uint MOVEFILE_WRITE_THROUGH = 0x00000008;
        private const uint EXIT_ASSIGN_FAILED = 125;
        private const uint EXIT_RESUME_FAILED = 126;
        private const int ERROR_ALREADY_EXISTS = 183;
        private const int ERROR_INSUFFICIENT_BUFFER = 122;
        private static readonly IntPtr InvalidHandleValue = new IntPtr(-1);

        [StructLayout(LayoutKind.Sequential)]
        private struct IO_COUNTERS
        {
            public ulong ReadOperationCount;
            public ulong WriteOperationCount;
            public ulong OtherOperationCount;
            public ulong ReadTransferCount;
            public ulong WriteTransferCount;
            public ulong OtherTransferCount;
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct JOBOBJECT_BASIC_LIMIT_INFORMATION
        {
            public long PerProcessUserTimeLimit;
            public long PerJobUserTimeLimit;
            public uint LimitFlags;
            public UIntPtr MinimumWorkingSetSize;
            public UIntPtr MaximumWorkingSetSize;
            public uint ActiveProcessLimit;
            public UIntPtr Affinity;
            public uint PriorityClass;
            public uint SchedulingClass;
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct JOBOBJECT_EXTENDED_LIMIT_INFORMATION
        {
            public JOBOBJECT_BASIC_LIMIT_INFORMATION BasicLimitInformation;
            public IO_COUNTERS IoInfo;
            public UIntPtr ProcessMemoryLimit;
            public UIntPtr JobMemoryLimit;
            public UIntPtr PeakProcessMemoryUsed;
            public UIntPtr PeakJobMemoryUsed;
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct JOBOBJECT_CPU_RATE_CONTROL_INFORMATION
        {
            public uint ControlFlags;
            public uint CpuRate;
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct JOBOBJECT_MEMORY_USAGE_INFORMATION
        {
            public ulong JobMemory;
            public ulong PeakJobMemoryUsed;
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct SECURITY_ATTRIBUTES
        {
            public int nLength;
            public IntPtr lpSecurityDescriptor;
            [MarshalAs(UnmanagedType.Bool)]
            public bool bInheritHandle;
        }

        [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
        private struct STARTUPINFO
        {
            public uint cb;
            public string lpReserved;
            public string lpDesktop;
            public string lpTitle;
            public uint dwX;
            public uint dwY;
            public uint dwXSize;
            public uint dwYSize;
            public uint dwXCountChars;
            public uint dwYCountChars;
            public uint dwFillAttribute;
            public uint dwFlags;
            public ushort wShowWindow;
            public ushort cbReserved2;
            public IntPtr lpReserved2;
            public IntPtr hStdInput;
            public IntPtr hStdOutput;
            public IntPtr hStdError;
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct PROCESS_INFORMATION
        {
            public IntPtr hProcess;
            public IntPtr hThread;
            public uint dwProcessId;
            public uint dwThreadId;
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct STARTUPINFOEX
        {
            public STARTUPINFO StartupInfo;
            public IntPtr lpAttributeList;
        }

        [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
        private static extern IntPtr CreateJobObject(IntPtr lpJobAttributes, string lpName);

        [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
        private static extern IntPtr OpenJobObject(
            uint desiredAccess,
            [MarshalAs(UnmanagedType.Bool)] bool inheritHandle,
            string name);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool SetInformationJobObject(
            IntPtr hJob,
            int jobObjectInfoClass,
            IntPtr lpJobObjectInfo,
            uint cbJobObjectInfoLength);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool QueryInformationJobObject(
            IntPtr hJob,
            int jobObjectInfoClass,
            IntPtr lpJobObjectInfo,
            uint cbJobObjectInfoLength,
            out uint lpReturnLength);

        [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
        private static extern IntPtr CreateFile(
            string lpFileName,
            uint dwDesiredAccess,
            uint dwShareMode,
            ref SECURITY_ATTRIBUTES lpSecurityAttributes,
            uint dwCreationDisposition,
            uint dwFlagsAndAttributes,
            IntPtr hTemplateFile);

        [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
        private static extern bool MoveFileEx(
            string existingFileName,
            string newFileName,
            uint flags);

        [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
        private static extern bool CreateProcess(
            string lpApplicationName,
            StringBuilder lpCommandLine,
            IntPtr lpProcessAttributes,
            IntPtr lpThreadAttributes,
            bool bInheritHandles,
            uint dwCreationFlags,
            IntPtr lpEnvironment,
            string lpCurrentDirectory,
            ref STARTUPINFOEX lpStartupInfo,
            out PROCESS_INFORMATION lpProcessInformation);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool InitializeProcThreadAttributeList(
            IntPtr attributeList,
            int attributeCount,
            uint flags,
            ref IntPtr size);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool UpdateProcThreadAttribute(
            IntPtr attributeList,
            uint flags,
            IntPtr attribute,
            IntPtr value,
            IntPtr size,
            IntPtr previousValue,
            IntPtr returnSize);

        [DllImport("kernel32.dll")]
        private static extern void DeleteProcThreadAttributeList(IntPtr attributeList);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool AssignProcessToJobObject(IntPtr hJob, IntPtr hProcess);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool IsProcessInJob(
            IntPtr processHandle,
            IntPtr jobHandle,
            [MarshalAs(UnmanagedType.Bool)] out bool result);

        [DllImport("kernel32.dll")]
        private static extern IntPtr GetCurrentProcess();

        [DllImport("kernel32.dll")]
        private static extern uint GetCurrentProcessId();

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern uint ResumeThread(IntPtr hThread);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool TerminateJobObject(IntPtr hJob, uint uExitCode);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool TerminateProcess(IntPtr hProcess, uint uExitCode);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool CloseHandle(IntPtr hObject);

        [DllImport("advapi32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
        private static extern bool ConvertStringSecurityDescriptorToSecurityDescriptor(
            string stringSecurityDescriptor,
            uint stringSDRevision,
            out IntPtr securityDescriptor,
            out uint securityDescriptorSize);

        [DllImport("kernel32.dll")]
        private static extern IntPtr LocalFree(IntPtr hMem);

        private IntPtr jobHandle;
        private IntPtr processHandle;
        private bool queryImmediateCurrentProcessJob;
        private bool disposed;

        public uint ProcessId { get; private set; }
        public string JobName { get; private set; }
        public uint JobLimitFlags { get; private set; }
        public ulong ProcessMemoryLimitBytes { get; private set; }
        public ulong JobMemoryLimitBytes { get; private set; }
        public ulong PeakProcessMemoryUsedBytes { get; private set; }
        public ulong PeakJobMemoryUsedBytes { get; private set; }
        public ulong CurrentJobMemoryUsedBytes { get; private set; }
        public uint CpuRateControlFlags { get; private set; }
        public uint CpuRate { get; private set; }

        private BoundedProcess()
        {
        }

        public static void PersistUtf8Atomic(string path, string content)
        {
            if (String.IsNullOrWhiteSpace(path) || content == null)
            {
                throw new ArgumentException(
                    "SYNAPSE_SUPERVISOR_STATE_INPUT_INVALID remediation=provide an exact state path and non-null JSON content");
            }
            string destination = Path.GetFullPath(path);
            string parent = Path.GetDirectoryName(destination);
            if (String.IsNullOrWhiteSpace(parent) || !Directory.Exists(parent))
            {
                throw new InvalidOperationException(
                    "SYNAPSE_SUPERVISOR_STATE_PARENT_MISSING path=" + destination +
                    " remediation=repair the setup-owned supervisor state directory before restart");
            }
            if ((File.GetAttributes(parent) & (FileAttributes)FILE_ATTRIBUTE_REPARSE_POINT) != 0 ||
                (File.Exists(destination) &&
                 (File.GetAttributes(destination) & (FileAttributes)FILE_ATTRIBUTE_REPARSE_POINT) != 0))
            {
                throw new InvalidOperationException(
                    "SYNAPSE_SUPERVISOR_STATE_REPARSE_REFUSED path=" + destination +
                    " remediation=replace the reparse point with the exact setup-owned regular path");
            }

            byte[] expected = new UTF8Encoding(false, true).GetBytes(content);
            string temporary = Path.Combine(
                parent,
                "." + Path.GetFileName(destination) + ".synapse-" + Guid.NewGuid().ToString("N") + ".tmp");
            try
            {
                using (FileStream stream = new FileStream(
                    temporary,
                    FileMode.CreateNew,
                    FileAccess.Write,
                    FileShare.None,
                    4096,
                    FileOptions.WriteThrough))
                {
                    stream.Write(expected, 0, expected.Length);
                    stream.Flush(true);
                }
                if (!MoveFileEx(
                    temporary,
                    destination,
                    MOVEFILE_REPLACE_EXISTING | MOVEFILE_WRITE_THROUGH))
                {
                    ThrowLastError("SYNAPSE_SUPERVISOR_STATE_ATOMIC_REPLACE_FAILED");
                }
                byte[] actual = File.ReadAllBytes(destination);
                if (actual.Length != expected.Length)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_SUPERVISOR_STATE_READBACK_LENGTH_MISMATCH expected=" + expected.Length +
                        " actual=" + actual.Length +
                        " remediation=repair filesystem durability before restart");
                }
                for (int index = 0; index < expected.Length; index++)
                {
                    if (actual[index] != expected[index])
                    {
                        throw new InvalidOperationException(
                            "SYNAPSE_SUPERVISOR_STATE_READBACK_BYTES_MISMATCH index=" + index +
                            " remediation=repair filesystem durability before restart");
                    }
                }
            }
            finally
            {
                if (File.Exists(temporary))
                {
                    File.Delete(temporary);
                }
            }
        }

        public static BoundedProcess Launch(
            string applicationName,
            string arguments,
            string workingDirectory,
            string stderrPath,
            string jobName,
            ulong processMemoryLimitBytes,
            uint cpuRate)
        {
            if (String.IsNullOrWhiteSpace(applicationName) ||
                String.IsNullOrWhiteSpace(workingDirectory) ||
                String.IsNullOrWhiteSpace(stderrPath) ||
                String.IsNullOrWhiteSpace(jobName))
            {
                throw new ArgumentException(
                    "SYNAPSE_DAEMON_JOB_INPUT_INVALID application, working directory, stderr path, and unique Job name are required; remediation=regenerate the supervisor from complete setup paths");
            }
            if (processMemoryLimitBytes == 0 || processMemoryLimitBytes >= 7000000000UL ||
                cpuRate == 0 || cpuRate > 10000)
            {
                throw new ArgumentOutOfRangeException(
                    "processMemoryLimitBytes",
                    "SYNAPSE_DAEMON_JOB_LIMIT_INVALID committed-memory limits must be positive and below decimal 7000000000 bytes, and CPU hard rate must be in 1..=10000; remediation=repair the setup-owned constants and regenerate the supervisor");
            }

            BoundedProcess owner = new BoundedProcess();
            PROCESS_INFORMATION processInfo = new PROCESS_INFORMATION();
            IntPtr limitPointer = IntPtr.Zero;
            IntPtr stdinHandle = IntPtr.Zero;
            IntPtr stdoutHandle = IntPtr.Zero;
            IntPtr stderrHandle = IntPtr.Zero;
            IntPtr jobSecurityDescriptor = IntPtr.Zero;
            IntPtr jobAttributesPointer = IntPtr.Zero;
            IntPtr attributeList = IntPtr.Zero;
            IntPtr inheritedHandleList = IntPtr.Zero;
            IntPtr creationJobList = IntPtr.Zero;
            bool attributeListInitialized = false;
            bool processCreated = false;
            bool assigned = false;
            try
            {
                uint jobSecurityDescriptorSize;
                if (!ConvertStringSecurityDescriptorToSecurityDescriptor(
                    "D:P(A;;GA;;;SY)(A;;0x00100004;;;OW)",
                    1,
                    out jobSecurityDescriptor,
                    out jobSecurityDescriptorSize))
                {
                    ThrowLastError("SYNAPSE_DAEMON_JOB_SECURITY_DESCRIPTOR_FAILED");
                }
                SECURITY_ATTRIBUTES jobSecurity = new SECURITY_ATTRIBUTES();
                jobSecurity.nLength = Marshal.SizeOf(typeof(SECURITY_ATTRIBUTES));
                jobSecurity.lpSecurityDescriptor = jobSecurityDescriptor;
                jobSecurity.bInheritHandle = false;
                jobAttributesPointer = Marshal.AllocHGlobal(jobSecurity.nLength);
                Marshal.StructureToPtr(jobSecurity, jobAttributesPointer, false);
                owner.jobHandle = CreateJobObject(jobAttributesPointer, jobName);
                if (owner.jobHandle == IntPtr.Zero)
                {
                    ThrowLastError("SYNAPSE_DAEMON_JOB_CREATE_FAILED");
                }
                int createJobError = Marshal.GetLastWin32Error();
                if (createJobError == ERROR_ALREADY_EXISTS)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_DAEMON_JOB_NAME_COLLISION job_name=" + jobName +
                        " remediation=refuse to attach a new daemon to an existing Job; inspect stale exact supervisor ownership");
                }
                owner.JobName = jobName;

                JOBOBJECT_EXTENDED_LIMIT_INFORMATION limits =
                    new JOBOBJECT_EXTENDED_LIMIT_INFORMATION();
                limits.BasicLimitInformation.LimitFlags = EXPECTED_JOB_LIMIT_FLAGS;
                limits.ProcessMemoryLimit = ToUIntPtr(processMemoryLimitBytes);
                limits.JobMemoryLimit = ToUIntPtr(processMemoryLimitBytes);
                int limitSize = Marshal.SizeOf(typeof(JOBOBJECT_EXTENDED_LIMIT_INFORMATION));
                limitPointer = Marshal.AllocHGlobal(limitSize);
                Marshal.StructureToPtr(limits, limitPointer, false);
                if (!SetInformationJobObject(
                    owner.jobHandle,
                    JobObjectExtendedLimitInformation,
                    limitPointer,
                    (uint)limitSize))
                {
                    ThrowLastError("SYNAPSE_DAEMON_JOB_LIMIT_SET_FAILED");
                }
                Marshal.FreeHGlobal(limitPointer);
                limitPointer = IntPtr.Zero;
                SetCpuHardRate(owner.jobHandle, cpuRate);

                owner.RefreshAccounting();
                if (owner.JobLimitFlags != EXPECTED_JOB_LIMIT_FLAGS ||
                    owner.ProcessMemoryLimitBytes != processMemoryLimitBytes ||
                    owner.JobMemoryLimitBytes != processMemoryLimitBytes ||
                    owner.CpuRateControlFlags != EXPECTED_CPU_RATE_CONTROL_FLAGS ||
                    owner.CpuRate != cpuRate)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_DAEMON_JOB_LIMIT_READBACK_MISMATCH expected_flags=0x" +
                        EXPECTED_JOB_LIMIT_FLAGS.ToString("X8") +
                        " actual_flags=0x" + owner.JobLimitFlags.ToString("X8") +
                        " expected_process_memory=" + processMemoryLimitBytes +
                        " actual_process_memory=" + owner.ProcessMemoryLimitBytes +
                        " expected_job_memory=" + processMemoryLimitBytes +
                        " actual_job_memory=" + owner.JobMemoryLimitBytes +
                        " working_set_policy=measured_only" +
                        " expected_cpu_rate_flags=0x" + EXPECTED_CPU_RATE_CONTROL_FLAGS.ToString("X8") +
                        " actual_cpu_rate_flags=0x" + owner.CpuRateControlFlags.ToString("X8") +
                        " expected_cpu_rate=" + cpuRate +
                        " actual_cpu_rate=" + owner.CpuRate +
                        " remediation=repair Windows Job Object limit support; no daemon was created");
                }

                SECURITY_ATTRIBUTES security = new SECURITY_ATTRIBUTES();
                security.nLength = Marshal.SizeOf(typeof(SECURITY_ATTRIBUTES));
                security.bInheritHandle = true;
                stdinHandle = CreateFile(
                    "NUL",
                    GENERIC_READ,
                    FILE_SHARE_READ | FILE_SHARE_WRITE,
                    ref security,
                    OPEN_EXISTING,
                    FILE_ATTRIBUTE_NORMAL,
                    IntPtr.Zero);
                EnsureHandle(stdinHandle, "SYNAPSE_DAEMON_JOB_STDIN_OPEN_FAILED");
                stdoutHandle = CreateFile(
                    "NUL",
                    GENERIC_WRITE,
                    FILE_SHARE_READ | FILE_SHARE_WRITE,
                    ref security,
                    OPEN_EXISTING,
                    FILE_ATTRIBUTE_NORMAL,
                    IntPtr.Zero);
                EnsureHandle(stdoutHandle, "SYNAPSE_DAEMON_JOB_STDOUT_OPEN_FAILED");
                stderrHandle = CreateFile(
                    stderrPath,
                    FILE_APPEND_DATA,
                    FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
                    ref security,
                    OPEN_ALWAYS,
                    FILE_ATTRIBUTE_NORMAL,
                    IntPtr.Zero);
                EnsureHandle(stderrHandle, "SYNAPSE_DAEMON_JOB_STDERR_OPEN_FAILED");

                IntPtr attributeListSize = IntPtr.Zero;
                bool attributeSizeResult = InitializeProcThreadAttributeList(IntPtr.Zero, 2, 0, ref attributeListSize);
                int attributeSizeError = Marshal.GetLastWin32Error();
                if (attributeSizeResult || attributeSizeError != ERROR_INSUFFICIENT_BUFFER || attributeListSize == IntPtr.Zero)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_DAEMON_JOB_ATTRIBUTE_LIST_SIZE_FAILED expected_win32=" + ERROR_INSUFFICIENT_BUFFER +
                        " actual_win32=" + attributeSizeError +
                        " unexpected_success=" + attributeSizeResult +
                        " size=" + attributeListSize +
                        " remediation=the host must support exact STARTUPINFOEX Job/handle-list sizing before daemon creation");
                }
                attributeList = Marshal.AllocHGlobal(attributeListSize);
                if (!InitializeProcThreadAttributeList(attributeList, 2, 0, ref attributeListSize))
                {
                    ThrowLastError("SYNAPSE_DAEMON_JOB_ATTRIBUTE_LIST_INIT_FAILED");
                }
                attributeListInitialized = true;
                inheritedHandleList = Marshal.AllocHGlobal(IntPtr.Size * 3);
                Marshal.WriteIntPtr(inheritedHandleList, 0, stdinHandle);
                Marshal.WriteIntPtr(inheritedHandleList, IntPtr.Size, stdoutHandle);
                Marshal.WriteIntPtr(inheritedHandleList, IntPtr.Size * 2, stderrHandle);
                if (!UpdateProcThreadAttribute(
                    attributeList,
                    0,
                    PROC_THREAD_ATTRIBUTE_HANDLE_LIST,
                    inheritedHandleList,
                    new IntPtr(IntPtr.Size * 3),
                    IntPtr.Zero,
                    IntPtr.Zero))
                {
                    ThrowLastError("SYNAPSE_DAEMON_JOB_HANDLE_LIST_UPDATE_FAILED");
                }
                creationJobList = Marshal.AllocHGlobal(IntPtr.Size);
                Marshal.WriteIntPtr(creationJobList, owner.jobHandle);
                if (!UpdateProcThreadAttribute(
                    attributeList,
                    0,
                    PROC_THREAD_ATTRIBUTE_JOB_LIST,
                    creationJobList,
                    new IntPtr(IntPtr.Size),
                    IntPtr.Zero,
                    IntPtr.Zero))
                {
                    ThrowLastError("SYNAPSE_DAEMON_JOB_LIST_UPDATE_FAILED");
                }
                STARTUPINFOEX startupInfo = new STARTUPINFOEX();
                startupInfo.StartupInfo.cb = (uint)Marshal.SizeOf(typeof(STARTUPINFOEX));
                startupInfo.StartupInfo.dwFlags = STARTF_USESHOWWINDOW | STARTF_USESTDHANDLES;
                startupInfo.StartupInfo.wShowWindow = SW_HIDE;
                startupInfo.StartupInfo.hStdInput = stdinHandle;
                startupInfo.StartupInfo.hStdOutput = stdoutHandle;
                startupInfo.StartupInfo.hStdError = stderrHandle;
                startupInfo.lpAttributeList = attributeList;
                string commandLineText = "\"" + applicationName + "\"";
                if (!String.IsNullOrWhiteSpace(arguments))
                {
                    commandLineText += " " + arguments;
                }
                StringBuilder commandLine = new StringBuilder(commandLineText);
                if (!CreateProcess(
                    applicationName,
                    commandLine,
                    IntPtr.Zero,
                    IntPtr.Zero,
                    true,
                    CREATE_SUSPENDED | CREATE_NO_WINDOW | EXTENDED_STARTUPINFO_PRESENT,
                    IntPtr.Zero,
                    workingDirectory,
                    ref startupInfo,
                    out processInfo))
                {
                    ThrowLastError("SYNAPSE_DAEMON_JOB_CREATE_PROCESS_FAILED");
                }
                processCreated = true;
                owner.processHandle = processInfo.hProcess;
                owner.ProcessId = processInfo.dwProcessId;

                bool assignedToExactDaemonJob;
                if (!IsProcessInJob(processInfo.hProcess, owner.jobHandle, out assignedToExactDaemonJob))
                {
                    string detail = LastErrorMessage();
                    TerminateJobObject(owner.jobHandle, EXIT_ASSIGN_FAILED);
                    throw new InvalidOperationException(
                        "SYNAPSE_DAEMON_JOB_MEMBERSHIP_READBACK_FAILED error=" + detail +
                        " remediation=the daemon remained suspended and its creation-time Job was terminated because exact kernel membership could not be read back");
                }
                if (!assignedToExactDaemonJob)
                {
                    TerminateJobObject(owner.jobHandle, EXIT_ASSIGN_FAILED);
                    throw new InvalidOperationException(
                        "SYNAPSE_DAEMON_JOB_MEMBERSHIP_MISMATCH job_name=" + owner.JobName +
                        " remediation=the daemon remained suspended and was terminated because PROC_THREAD_ATTRIBUTE_JOB_LIST did not establish exact child Job membership at creation");
                }
                assigned = true;
                if (ResumeThread(processInfo.hThread) == 0xffffffff)
                {
                    string detail = LastErrorMessage();
                    TerminateJobObject(owner.jobHandle, EXIT_RESUME_FAILED);
                    throw new InvalidOperationException(
                        "SYNAPSE_DAEMON_JOB_RESUME_FAILED error=" + detail +
                        " remediation=inspect process-thread rights; the assigned Job was terminated before daemon execution");
                }
                CloseHandle(processInfo.hThread);
                processInfo.hThread = IntPtr.Zero;
                return owner;
            }
            catch
            {
                if (assigned && owner.jobHandle != IntPtr.Zero)
                {
                    TerminateJobObject(owner.jobHandle, 127);
                }
                else if (processCreated && processInfo.hProcess != IntPtr.Zero)
                {
                    TerminateProcess(processInfo.hProcess, 127);
                }
                owner.Dispose();
                throw;
            }
            finally
            {
                if (limitPointer != IntPtr.Zero) Marshal.FreeHGlobal(limitPointer);
                if (jobAttributesPointer != IntPtr.Zero) Marshal.FreeHGlobal(jobAttributesPointer);
                if (jobSecurityDescriptor != IntPtr.Zero) LocalFree(jobSecurityDescriptor);
                if (attributeList != IntPtr.Zero)
                {
                    if (attributeListInitialized) DeleteProcThreadAttributeList(attributeList);
                    Marshal.FreeHGlobal(attributeList);
                }
                if (inheritedHandleList != IntPtr.Zero) Marshal.FreeHGlobal(inheritedHandleList);
                if (creationJobList != IntPtr.Zero) Marshal.FreeHGlobal(creationJobList);
                if (processInfo.hThread != IntPtr.Zero) CloseHandle(processInfo.hThread);
                if (stdinHandle != IntPtr.Zero && stdinHandle != InvalidHandleValue) CloseHandle(stdinHandle);
                if (stdoutHandle != IntPtr.Zero && stdoutHandle != InvalidHandleValue) CloseHandle(stdoutHandle);
                if (stderrHandle != IntPtr.Zero && stderrHandle != InvalidHandleValue) CloseHandle(stderrHandle);
            }
        }

        public static BoundedProcess BindCurrentSupervisor(
            string jobName,
            ulong processMemoryLimitBytes,
            uint cpuRate)
        {
            if (String.IsNullOrWhiteSpace(jobName) ||
                processMemoryLimitBytes == 0 || processMemoryLimitBytes >= 7000000000UL ||
                cpuRate == 0 || cpuRate > 10000)
            {
                throw new ArgumentOutOfRangeException(
                    "processMemoryLimitBytes",
                    "SYNAPSE_SUPERVISOR_JOB_LIMIT_INVALID name and bounded committed-memory/CPU limits are required; remediation=repair setup-owned constants before launching the supervisor");
            }

            BoundedProcess owner = new BoundedProcess();
            try
            {
                owner.jobHandle = OpenJobObject(JOB_OBJECT_QUERY, false, jobName);
                if (owner.jobHandle == IntPtr.Zero)
                {
                    ThrowLastError("SYNAPSE_SUPERVISOR_PARENT_JOB_OPEN_FAILED");
                }
                owner.JobName = jobName;

                owner.ProcessId = GetCurrentProcessId();
                owner.RefreshAccounting();
                if (owner.JobLimitFlags != EXPECTED_SUPERVISOR_JOB_LIMIT_FLAGS ||
                    owner.ProcessMemoryLimitBytes != processMemoryLimitBytes ||
                    owner.JobMemoryLimitBytes != processMemoryLimitBytes ||
                    owner.CpuRateControlFlags != EXPECTED_CPU_RATE_CONTROL_FLAGS ||
                    owner.CpuRate != cpuRate)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_SUPERVISOR_JOB_LIMIT_READBACK_MISMATCH job_name=" + jobName +
                        " actual_flags=0x" + owner.JobLimitFlags.ToString("X8") +
                        " actual_process_memory=" + owner.ProcessMemoryLimitBytes +
                        " actual_job_memory=" + owner.JobMemoryLimitBytes +
                        " working_set_policy=measured_only" +
                        " actual_cpu_rate_flags=0x" + owner.CpuRateControlFlags.ToString("X8") +
                        " actual_cpu_rate=" + owner.CpuRate +
                        " remediation=repair Windows Job Object support; no unbounded supervisor may continue");
                }
                bool currentProcessInJob;
                if (!IsProcessInJob(GetCurrentProcess(), owner.jobHandle, out currentProcessInJob))
                {
                    ThrowLastError("SYNAPSE_SUPERVISOR_JOB_MEMBERSHIP_READBACK_FAILED");
                }
                if (!currentProcessInJob)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_SUPERVISOR_PARENT_JOB_MEMBERSHIP_MISMATCH job_name=" + jobName +
                        " remediation=the native bootstrap or candidate launcher must place PowerShell in the exact parent Job at process creation; post-start assignment is forbidden");
                }
                if (!CloseHandle(owner.jobHandle))
                {
                    ThrowLastError("SYNAPSE_SUPERVISOR_PARENT_JOB_PROOF_HANDLE_CLOSE_FAILED");
                }
                owner.jobHandle = IntPtr.Zero;
                owner.queryImmediateCurrentProcessJob = true;
                // Continuing accounting uses QueryInformationJobObject(NULL),
                // which resolves the current process's immediate Job. Keeping
                // this named query handle open would defeat KILL_ON_CLOSE when
                // the native bootstrap (the sole lifetime owner) exits.
                owner.RefreshAccounting();
                return owner;
            }
            catch
            {
                owner.Dispose();
                throw;
            }
        }

        public void RefreshAccounting()
        {
            if (disposed || (jobHandle == IntPtr.Zero && !queryImmediateCurrentProcessJob))
            {
                throw new ObjectDisposedException(
                    "BoundedProcess",
                    "SYNAPSE_DAEMON_JOB_ACCOUNTING_AFTER_DISPOSE remediation=retain the generation Job owner until after the exact child exits");
            }
            IntPtr accountingJobHandle = queryImmediateCurrentProcessJob ? IntPtr.Zero : jobHandle;
            int size = Marshal.SizeOf(typeof(JOBOBJECT_EXTENDED_LIMIT_INFORMATION));
            IntPtr pointer = Marshal.AllocHGlobal(size);
            try
            {
                uint returned;
                if (!QueryInformationJobObject(
                    accountingJobHandle,
                    JobObjectExtendedLimitInformation,
                    pointer,
                    (uint)size,
                    out returned))
                {
                    ThrowLastError("SYNAPSE_DAEMON_JOB_LIMIT_READBACK_FAILED");
                }
                if (returned != (uint)size)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_DAEMON_JOB_LIMIT_READBACK_SIZE_MISMATCH expected=" + size +
                        " actual=" + returned +
                        " remediation=the host does not expose the expected class-9 Job limit ABI");
                }
                JOBOBJECT_EXTENDED_LIMIT_INFORMATION limits =
                    (JOBOBJECT_EXTENDED_LIMIT_INFORMATION)Marshal.PtrToStructure(
                        pointer,
                        typeof(JOBOBJECT_EXTENDED_LIMIT_INFORMATION));
                JobLimitFlags = limits.BasicLimitInformation.LimitFlags;
                ProcessMemoryLimitBytes = limits.ProcessMemoryLimit.ToUInt64();
                JobMemoryLimitBytes = limits.JobMemoryLimit.ToUInt64();
                PeakProcessMemoryUsedBytes = limits.PeakProcessMemoryUsed.ToUInt64();
                PeakJobMemoryUsedBytes = limits.PeakJobMemoryUsed.ToUInt64();
            }
            finally
            {
                Marshal.FreeHGlobal(pointer);
            }
            int memorySize = Marshal.SizeOf(typeof(JOBOBJECT_MEMORY_USAGE_INFORMATION));
            IntPtr memoryPointer = Marshal.AllocHGlobal(memorySize);
            try
            {
                uint returned;
                if (!QueryInformationJobObject(
                    accountingJobHandle,
                    JobObjectMemoryUsageInformation,
                    memoryPointer,
                    (uint)memorySize,
                    out returned))
                {
                    ThrowLastError("SYNAPSE_DAEMON_JOB_MEMORY_ACCOUNTING_READBACK_FAILED");
                }
                if (returned != (uint)memorySize)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_DAEMON_JOB_MEMORY_ACCOUNTING_SIZE_MISMATCH expected=" + memorySize +
                        " actual=" + returned +
                        " remediation=the host does not expose the expected class-28 Job memory ABI; no unverified accounting is accepted");
                }
                JOBOBJECT_MEMORY_USAGE_INFORMATION memory =
                    (JOBOBJECT_MEMORY_USAGE_INFORMATION)Marshal.PtrToStructure(
                        memoryPointer,
                        typeof(JOBOBJECT_MEMORY_USAGE_INFORMATION));
                if (memory.PeakJobMemoryUsed < PeakJobMemoryUsedBytes)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_DAEMON_JOB_MEMORY_PEAK_REGRESSION extended_peak_earlier=" + PeakJobMemoryUsedBytes +
                        " memory_usage_peak=" + memory.PeakJobMemoryUsed +
                        " remediation=repair Windows Job Object accounting; a later monotone kernel peak cannot regress");
                }
                if (memory.PeakJobMemoryUsed < memory.JobMemory)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_DAEMON_JOB_MEMORY_CURRENT_EXCEEDS_PEAK current=" + memory.JobMemory +
                        " peak=" + memory.PeakJobMemoryUsed +
                        " remediation=repair Windows Job Object accounting; current aggregate commit cannot exceed its monotone peak");
                }
                CurrentJobMemoryUsedBytes = memory.JobMemory;
                PeakJobMemoryUsedBytes = memory.PeakJobMemoryUsed;
            }
            finally
            {
                Marshal.FreeHGlobal(memoryPointer);
            }
            int cpuSize = Marshal.SizeOf(typeof(JOBOBJECT_CPU_RATE_CONTROL_INFORMATION));
            IntPtr cpuPointer = Marshal.AllocHGlobal(cpuSize);
            try
            {
                uint returned;
                if (!QueryInformationJobObject(
                    accountingJobHandle,
                    JobObjectCpuRateControlInformation,
                    cpuPointer,
                    (uint)cpuSize,
                    out returned))
                {
                    ThrowLastError("SYNAPSE_DAEMON_JOB_CPU_RATE_READBACK_FAILED");
                }
                if (returned != (uint)cpuSize)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_DAEMON_JOB_CPU_RATE_READBACK_SIZE_MISMATCH expected=" + cpuSize +
                        " actual=" + returned +
                        " remediation=the host does not expose the expected class-15 Job CPU ABI");
                }
                JOBOBJECT_CPU_RATE_CONTROL_INFORMATION cpu =
                    (JOBOBJECT_CPU_RATE_CONTROL_INFORMATION)Marshal.PtrToStructure(
                        cpuPointer,
                        typeof(JOBOBJECT_CPU_RATE_CONTROL_INFORMATION));
                CpuRateControlFlags = cpu.ControlFlags;
                CpuRate = cpu.CpuRate;
            }
            finally
            {
                Marshal.FreeHGlobal(cpuPointer);
            }
        }

        public void Dispose()
        {
            Dispose(true);
            GC.SuppressFinalize(this);
        }

        ~BoundedProcess()
        {
            Dispose(false);
        }

        private void Dispose(bool disposing)
        {
            if (disposed) return;
            disposed = true;
            if (processHandle != IntPtr.Zero)
            {
                CloseHandle(processHandle);
                processHandle = IntPtr.Zero;
            }
            if (jobHandle != IntPtr.Zero)
            {
                CloseHandle(jobHandle);
                jobHandle = IntPtr.Zero;
            }
        }

        private static UIntPtr ToUIntPtr(ulong value)
        {
            if (UIntPtr.Size == 8) return new UIntPtr(value);
            return new UIntPtr(checked((uint)value));
        }

        private static void SetCpuHardRate(IntPtr jobHandle, uint cpuRate)
        {
            JOBOBJECT_CPU_RATE_CONTROL_INFORMATION cpu =
                new JOBOBJECT_CPU_RATE_CONTROL_INFORMATION();
            cpu.ControlFlags = EXPECTED_CPU_RATE_CONTROL_FLAGS;
            cpu.CpuRate = cpuRate;
            int size = Marshal.SizeOf(typeof(JOBOBJECT_CPU_RATE_CONTROL_INFORMATION));
            IntPtr pointer = Marshal.AllocHGlobal(size);
            try
            {
                Marshal.StructureToPtr(cpu, pointer, false);
                if (!SetInformationJobObject(
                    jobHandle,
                    JobObjectCpuRateControlInformation,
                    pointer,
                    (uint)size))
                {
                    ThrowLastError("SYNAPSE_DAEMON_JOB_CPU_RATE_SET_FAILED");
                }
            }
            finally
            {
                Marshal.FreeHGlobal(pointer);
            }
        }

        private static void EnsureHandle(IntPtr handle, string code)
        {
            if (handle == IntPtr.Zero || handle == InvalidHandleValue)
            {
                ThrowLastError(code);
            }
        }

        private static void ThrowLastError(string code)
        {
            throw new InvalidOperationException(
                code + " error=" + LastErrorMessage() +
                " remediation=inspect Windows Job Object/process rights and the exact named limit; no unbounded daemon is eligible to run");
        }

        private static string LastErrorMessage()
        {
            int error = Marshal.GetLastWin32Error();
            return "win32_error=" + error + " message=" + new Win32Exception(error).Message;
        }
    }
}
"@ | Out-Null
    } catch {
        throw "SYNAPSE_DAEMON_JOB_TYPE_LOAD_FAILED error=$($_.Exception.Message) remediation=repair Windows PowerShell Add-Type and the generated supervisor; no unbounded daemon is eligible to launch"
    }
}

function Get-SynapseDaemonFileSha256 {
    param([Parameter(Mandatory=$true)][string]$Path)

    $stream = $null
    $hasher = $null
    try {
        $stream = [System.IO.File]::Open(
            $Path,
            [System.IO.FileMode]::Open,
            [System.IO.FileAccess]::Read,
            [System.IO.FileShare]::Read
        )
        $hasher = [System.Security.Cryptography.SHA256]::Create()
        $digest = $hasher.ComputeHash($stream)
        return ([System.BitConverter]::ToString($digest)).Replace('-', '').ToUpperInvariant()
    } finally {
        if ($null -ne $hasher) {
            $hasher.Dispose()
        }
        if ($null -ne $stream) {
            $stream.Dispose()
        }
    }
}

function Assert-SynapseDaemonCalyxConfigIdentity {
    if (-not (Test-Path -LiteralPath $ExpectedCalyxConfigPath -PathType Leaf)) {
        throw "SYNAPSE_DAEMON_CALYX_CONFIG_MISSING path=$ExpectedCalyxConfigPath expected_sha256=$ExpectedCalyxConfigSha256 remediation=rerun setup to restore the setup-owned CPU-only Calyx config"
    }
    try {
        $actualSha256 = Get-SynapseDaemonFileSha256 -Path $ExpectedCalyxConfigPath
    } catch {
        throw "SYNAPSE_DAEMON_CALYX_CONFIG_HASH_FAILED path=$ExpectedCalyxConfigPath error=$($_.Exception.Message) remediation=repair access to the pinned config and rerun setup"
    }
    if ($actualSha256 -ne $ExpectedCalyxConfigSha256) {
        throw "SYNAPSE_DAEMON_CALYX_CONFIG_DRIFT path=$ExpectedCalyxConfigPath expected_sha256=$ExpectedCalyxConfigSha256 actual_sha256=$actualSha256 remediation=rerun setup so candidate validation and the persistent supervisor agree on one immutable CPU-only config"
    }
    return $actualSha256
}

function Get-SynapseDaemonMemoryReadback {
    param(
        [Parameter(Mandatory=$true)][System.Diagnostics.Process]$Process,
        [uint64]$PrivateLimitBytes = $ProcessMemoryLimitBytes,
        [string]$Role = 'daemon'
    )
    try {
        $Process.Refresh()
        $privateBytes = [uint64]$Process.PrivateMemorySize64
        $workingSetBytes = [uint64]$Process.WorkingSet64
    } catch {
        throw "SYNAPSE_OWNED_PROCESS_MEMORY_READBACK_FAILED role=$Role pid=$($Process.Id) error=$($_.Exception.Message) remediation=repair the OS process counters; the supervisor will not publish unmeasured owned process state"
    }
    if ($privateBytes -gt $PrivateLimitBytes) {
        throw "SYNAPSE_OWNED_PROCESS_MEMORY_LIMIT_READBACK_EXCEEDED role=$Role pid=$($Process.Id) private_bytes=$privateBytes process_memory_limit_bytes=$PrivateLimitBytes working_set_bytes=$workingSetBytes working_set_policy=measured_only remediation=inspect retained owners and startup allocation; no over-budget process will be published"
    }
    return [pscustomobject]@{
        PrivateBytes = $privateBytes
        WorkingSetBytes = $workingSetBytes
        PrivateHeadroomBytes = [uint64]($PrivateLimitBytes - $privateBytes)
    }
}

function Read-SynapseToken {
    if (-not (Test-Path -LiteralPath $TokenPath -PathType Leaf)) {
        throw "SYNAPSE_DAEMON_TOKEN_MISSING path=$TokenPath"
    }
    $token = (Get-Content -Raw -LiteralPath $TokenPath).Trim()
    if ($token.Length -lt 16) {
        throw "SYNAPSE_DAEMON_TOKEN_INVALID path=$TokenPath length=$($token.Length)"
    }
    return $token
}

function Get-BindParts {
    $lastColon = $Bind.LastIndexOf(':')
    if ($lastColon -lt 1 -or $lastColon -ge ($Bind.Length - 1)) {
        throw "SYNAPSE_DAEMON_BIND_INVALID bind=$Bind"
    }
    return [pscustomobject]@{
        Address = $Bind.Substring(0, $lastColon)
        Port = [int]$Bind.Substring($lastColon + 1)
    }
}

function Get-ProcessInfoForPid {
    param([Parameter(Mandatory=$true)][int]$ProcessId)
    Get-CimInstance Win32_Process -Filter ("ProcessId = {0}" -f $ProcessId) -ErrorAction SilentlyContinue
}

function Test-ExactBindAvailable {
    param(
        [Parameter(Mandatory=$true)][string]$Address,
        [Parameter(Mandatory=$true)][int]$Port
    )

    $probe = $null
    $available = $false
    $errorText = $null
    try {
        $ipAddress = [System.Net.IPAddress]::Parse($Address)
        $probe = [System.Net.Sockets.TcpListener]::new($ipAddress, $Port)
        $probe.ExclusiveAddressUse = $true
        $probe.Start()
        $available = $true
    } catch {
        $errorText = ($_.Exception.Message -replace '\s+', ' ').Trim()
    } finally {
        if ($null -ne $probe) {
            try { $probe.Stop() } catch { }
        }
    }

    return [pscustomobject]@{
        Available = $available
        Error = $errorText
    }
}

function Get-CommandLineArgumentValue {
    param(
        [string]$CommandLine,
        [Parameter(Mandatory=$true)][string]$Name
    )
    if ([string]::IsNullOrWhiteSpace($CommandLine)) { return $null }
    $escapedName = [regex]::Escape($Name)
    $pattern = "(?i)(?:^|\s)$escapedName(?:\s+|=)(?:""(?<quoted>[^""]*)""|(?<bare>\S+))"
    $match = [regex]::Match($CommandLine, $pattern)
    if (-not $match.Success) { return $null }
    if ($match.Groups['quoted'].Success) { return $match.Groups['quoted'].Value }
    return $match.Groups['bare'].Value
}

function Normalize-AllowedPermissionsArgument {
    param([AllowNull()][string]$Value)
    if ([string]::IsNullOrWhiteSpace($Value)) {
        return ''
    }

    $tokens = @($Value -split '[,;\s]+' | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    if ($tokens.Count -eq 0) {
        return ''
    }

    return ($tokens -join ',')
}

function Normalize-PathArgument {
    param([AllowNull()][string]$Value)
    if ([string]::IsNullOrWhiteSpace($Value)) { return '' }
    try { return ([System.IO.Path]::GetFullPath($Value)).TrimEnd([char[]]@([char]92, [char]47)) }
    catch { return $Value.Trim().TrimEnd([char[]]@([char]92, [char]47)) }
}

function Test-ExpectedDaemonProcess {
    param(
        [AllowNull()][object]$ProcessInfo,
        [AllowNull()][object]$ExpectedParentPid = $null
    )
    if ($null -eq $ProcessInfo) {
        return $false
    }
    if (-not [string]::Equals([string]$ProcessInfo.ExecutablePath, $ExePath, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $false
    }
    $commandLine = [string]$ProcessInfo.CommandLine
    $actualMode = Get-CommandLineArgumentValue -CommandLine $commandLine -Name '--mode'
    $actualBind = Get-CommandLineArgumentValue -CommandLine $commandLine -Name '--bind'
    $actualDb = Normalize-PathArgument -Value (Get-CommandLineArgumentValue -CommandLine $commandLine -Name '--db')
    $actualProfiles = Normalize-PathArgument -Value (Get-CommandLineArgumentValue -CommandLine $commandLine -Name '--profile-dir')
    $actualCalyxConfig = Normalize-PathArgument -Value (Get-CommandLineArgumentValue -CommandLine $commandLine -Name '--calyx-config')
    $actualParentPidRaw = Get-CommandLineArgumentValue -CommandLine $commandLine -Name '--parent-pid'
    $actualParentPid = 0
    if (-not [int]::TryParse([string]$actualParentPidRaw, [ref]$actualParentPid) -or $actualParentPid -le 0) {
        return $false
    }
    $actualEnableAudio = $commandLine -match '(?i)(?:^|\s)--enable-audio(?:\s|$)'
    $baseMatches = ($actualMode -ieq 'http') -and
        ($actualBind -ieq $Bind) -and
        ($actualDb -ieq (Normalize-PathArgument -Value $DbPath)) -and
        ($actualProfiles -ieq (Normalize-PathArgument -Value $ProfilesDir)) -and
        ($actualCalyxConfig -ieq (Normalize-PathArgument -Value $ExpectedCalyxConfigPath)) -and
        ($actualEnableAudio -eq [bool]::Parse($ExpectedEnableAudio))
    if (-not $baseMatches) {
        return $false
    }

    $actualAllowedRaw = Get-CommandLineArgumentValue -CommandLine $commandLine -Name '--allowed-permissions'
    $actualAllowed = Normalize-AllowedPermissionsArgument -Value $actualAllowedRaw
    $expectedAllowed = Normalize-AllowedPermissionsArgument -Value $ExpectedAllowedPermissions
    if ($actualAllowed -cne $expectedAllowed) {
        return $false
    }
    if ($null -ne $ExpectedParentPid -and $actualParentPid -ne [int]$ExpectedParentPid) {
        return $false
    }
    return $true
}

function Get-ExactChildIdentityState {
    param(
        [Parameter(Mandatory=$true)][int]$ChildPid,
        [Parameter(Mandatory=$true)][string]$CreationDate
    )
    $current = Get-ProcessInfoForPid -ProcessId $ChildPid
    if ($null -eq $current) {
        return [pscustomobject]@{ Live = $false; Terminal = $true; Reason = 'pid_absent'; ProcessInfo = $null }
    }
    if ([string]$current.CreationDate -cne $CreationDate) {
        return [pscustomobject]@{ Live = $false; Terminal = $true; Reason = 'pid_reused'; ProcessInfo = $current }
    }
    if (-not (Test-ExpectedDaemonProcess -ProcessInfo $current -ExpectedParentPid $PID)) {
        return [pscustomobject]@{ Live = $false; Terminal = $false; Reason = 'identity_mismatch'; ProcessInfo = $current }
    }
    return [pscustomobject]@{ Live = $true; Terminal = $false; Reason = 'exact_child_live'; ProcessInfo = $current }
}

function Test-ExactChildReady {
    param(
        [Parameter(Mandatory=$true)][int]$ChildPid,
        [Parameter(Mandatory=$true)][string]$CreationDate,
        [Parameter(Mandatory=$true)][string]$Token,
        [Parameter(Mandatory=$true)]$BindParts
    )
    $identity = Get-ExactChildIdentityState -ChildPid $ChildPid -CreationDate $CreationDate
    if ($identity.Live -ne $true) {
        return [pscustomobject]@{ Ready = $false; Terminal = $identity.Terminal; Reason = $identity.Reason }
    }
    $listeners = @(Get-NetTCPConnection -LocalAddress $BindParts.Address -LocalPort $BindParts.Port -State Listen -ErrorAction SilentlyContinue)
    $owners = @($listeners | ForEach-Object { [int]$_.OwningProcess } | Sort-Object -Unique)
    if ($owners.Count -ne 1 -or $owners[0] -ne $ChildPid) {
        return [pscustomobject]@{ Ready = $false; Terminal = $false; Reason = "listener_owners_$($owners -join ',')" }
    }
    try {
        $headers = @{ Authorization = "Bearer $Token" }
        $response = Invoke-WebRequest -UseBasicParsing -Uri ("http://{0}/health" -f $Bind) -Headers $headers -TimeoutSec 2
        if ([int]$response.StatusCode -ne 200) {
            return [pscustomobject]@{ Ready = $false; Terminal = $false; Reason = "health_status_$([int]$response.StatusCode)" }
        }
    } catch {
        return [pscustomobject]@{ Ready = $false; Terminal = $false; Reason = "health_failed:$($_.Exception.Message)" }
    }
    $identityAfterHealth = Get-ExactChildIdentityState -ChildPid $ChildPid -CreationDate $CreationDate
    if ($identityAfterHealth.Live -ne $true) {
        return [pscustomobject]@{ Ready = $false; Terminal = $identityAfterHealth.Terminal; Reason = "post_health_$($identityAfterHealth.Reason)" }
    }
    return [pscustomobject]@{ Ready = $true; Terminal = $false; Reason = 'exact_identity_listener_health' }
}

function Test-SetupMaintenanceLockActive {
    if ([string]::IsNullOrWhiteSpace($MaintenanceLockPath) -or -not (Test-Path -LiteralPath $MaintenanceLockPath -PathType Leaf)) {
        return [pscustomobject]@{ Active = $false; Reason = 'missing' }
    }
    try {
        $text = (Get-Content -Raw -LiteralPath $MaintenanceLockPath).Trim()
        if ([string]::IsNullOrWhiteSpace($text)) {
            return [pscustomobject]@{ Active = $false; Reason = 'empty' }
        }
        $lock = $text | ConvertFrom-Json
        if ([string]$lock.schema -ne 'synapse_setup_maintenance_lock/v2') {
            # An authority process may never interpret an unreadable or unknown
            # setup lock as permission to launch.  The setup writer has shipped
            # v2 since the lock gained its nonce and lineage binding.
            return [pscustomobject]@{ Active = $true; Reason = 'schema_mismatch_fail_closed' }
        }
        if ([string]$lock.bind -ne $Bind) {
            return [pscustomobject]@{ Active = $false; Reason = 'bind_mismatch' }
        }
        if ([string]$lock.state -ne 'held') {
            return [pscustomobject]@{ Active = $false; Reason = "state_$($lock.state)" }
        }
        $lockPid = [int]$lock.pid
        $owner = Get-ProcessInfoForPid -ProcessId $lockPid
        if ($null -eq $owner) {
            return [pscustomobject]@{ Active = $false; Reason = "owner_missing_$lockPid" }
        }
        return [pscustomobject]@{ Active = $true; Reason = [string]$lock.reason; Pid = $lockPid }
    } catch {
        return [pscustomobject]@{ Active = $true; Reason = "read_failed_fail_closed:$($_.Exception.Message)" }
    }
}

function Stop-IfSetupMaintenanceActive {
    param(
        [Parameter(Mandatory=$true)][string]$Phase,
        [int]$Generation,
        [AllowNull()][object]$ChildPid,
        [AllowNull()][object]$ExitCode
    )
    $maintenance = Test-SetupMaintenanceLockActive
    if ($maintenance.Active -ne $true) {
        return
    }
    Write-LogLine "SYNAPSE_DAEMON_SUPERVISOR_STOP generation=$Generation reason=setup_maintenance phase=$Phase lock_reason=$($maintenance.Reason) lock_pid=$($maintenance.Pid)"
    Write-SupervisorEvent 'supervisor_stop' @{ generation = $Generation; reason = 'setup_maintenance'; phase = $Phase; lock_reason = $maintenance.Reason; lock_pid = $maintenance.Pid }
    Write-SupervisorState -State 'stopped' -Generation $Generation -ChildPid $ChildPid -ExitCode $ExitCode -Message "Setup maintenance lock is held by pid $($maintenance.Pid); supervisor stopped instead of launching/restarting during $Phase."
    exit 0
}

# #2083: the durable operator stop-request. The setup maintenance lock above is
# a TRANSIENT revocation -- it is only valid while the owning setup process is
# alive, and it is only consulted after a child exit. Neither property is what
# an operator stop needs: `synapse-setup.ps1 -Stop` must leave the daemon down
# after the stopping process itself has exited, and it must park a supervisor
# that is sitting in its restart backoff or that has not launched anything yet.
# This record is that authority, and it is checked at every point where the
# supervisor is about to (re)launch.
function Get-JsonFieldText {
    # Set-StrictMode -Version Latest turns a reference to a missing property into
    # a PropertyNotFoundException, which would replace the coded stop-request
    # diagnostics below with a generic PowerShell message. Read fields through
    # the property bag so a missing field is data, not an exception.
    param(
        [Parameter(Mandatory=$true)][AllowNull()][object]$Object,
        [Parameter(Mandatory=$true)][string]$Name
    )
    if ($null -eq $Object) { return $null }
    $property = $Object.PSObject.Properties[$Name]
    if ($null -eq $property) { return $null }
    if ($null -eq $property.Value) { return $null }
    return [string]$property.Value
}

function Test-OperatorStopRequestActive {
    if ([string]::IsNullOrWhiteSpace($SupervisorStopRequestPath) -or -not (Test-Path -LiteralPath $SupervisorStopRequestPath -PathType Leaf)) {
        if ($AuthorityMode -in @('legacy','broker')) {
            throw "SYNAPSE_DAEMON_SUPERVISOR_PERMANENT_FENCE_MISSING mode=$AuthorityMode path=$SupervisorStopRequestPath remediation=missing setup-owned authority is deny-by-default; only the broker transaction may restore an exact predecision legacy preimage"
        }
        return [pscustomobject]@{ Active = $false; Reason = 'missing' }
    }
    # Deliberately NOT wrapped in a try/catch that degrades to "not active": an
    # unreadable or malformed stop-request is an ambiguous authority state, and
    # the fail-open direction (launch anyway) is exactly the #2083 bug. The trap
    # handler turns this into state=fatal with the exact path and parse error.
    $text = ''
    try {
        $text = (Get-Content -Raw -LiteralPath $SupervisorStopRequestPath).Trim()
    } catch {
        throw "SYNAPSE_DAEMON_SUPERVISOR_STOP_REQUEST_UNREADABLE path=$SupervisorStopRequestPath error=$($_.Exception.Message) remediation=repair or delete this file, or run scripts/synapse-setup.ps1 -Start to clear it; the supervisor refuses to launch while its restart authority is unreadable"
    }
    if ([string]::IsNullOrWhiteSpace($text)) {
        throw "SYNAPSE_DAEMON_SUPERVISOR_STOP_REQUEST_EMPTY path=$SupervisorStopRequestPath remediation=repair or delete this file, or run scripts/synapse-setup.ps1 -Start to clear it; an empty stop-request cannot prove whether restart authority was revoked"
    }
    $request = $null
    try {
        $request = $text | ConvertFrom-Json
    } catch {
        throw "SYNAPSE_DAEMON_SUPERVISOR_STOP_REQUEST_MALFORMED path=$SupervisorStopRequestPath error=$($_.Exception.Message) remediation=repair or delete this file, or run scripts/synapse-setup.ps1 -Start to clear it"
    }
    $requestSchema = Get-JsonFieldText -Object $request -Name 'schema'
    if ($requestSchema -ne 'synapse_daemon_supervisor_stop_request/v1') {
        throw "SYNAPSE_DAEMON_SUPERVISOR_STOP_REQUEST_SCHEMA_MISMATCH path=$SupervisorStopRequestPath actual_schema=$requestSchema expected_schema=synapse_daemon_supervisor_stop_request/v1 remediation=repair or delete this file, or run scripts/synapse-setup.ps1 -Start to clear it"
    }
    $requestBind = Get-JsonFieldText -Object $request -Name 'bind'
    if ($requestBind -ne $Bind) {
        # Scoped exactly like the maintenance lock: a stop-request written for a
        # different bind has no authority over this supervisor, and saying so is
        # a readback, not a degradation.
        return [pscustomobject]@{ Active = $false; Reason = "bind_mismatch_$requestBind" }
    }
    $requestState = Get-JsonFieldText -Object $request -Name 'state'
    if ($requestState -ne 'requested') {
        throw "SYNAPSE_DAEMON_SUPERVISOR_STOP_REQUEST_STATE_INVALID path=$SupervisorStopRequestPath actual_state=$requestState expected_state=requested remediation=repair or delete this file, or run scripts/synapse-setup.ps1 -Start to clear it"
    }
    return [pscustomobject]@{
        Active = $true
        Reason = (Get-JsonFieldText -Object $request -Name 'reason')
        RequestedByPid = (Get-JsonFieldText -Object $request -Name 'requested_by_pid')
        RequestedAtUtc = (Get-JsonFieldText -Object $request -Name 'requested_at_utc')
    }
}

function Get-SynapseDaemonTextSha256 {
    param([AllowEmptyString()][Parameter(Mandatory=$true)][string]$Text)
    $bytes = [System.Text.UTF8Encoding]::new($false, $true).GetBytes($Text)
    $hasher = [System.Security.Cryptography.SHA256]::Create()
    try {
        return ([System.BitConverter]::ToString($hasher.ComputeHash($bytes))).Replace('-', '').ToUpperInvariant()
    } finally {
        $hasher.Dispose()
    }
}

function Read-SynapseBrokerAuthorityRoster {
    if ($AuthorityMode -in @('legacy','probe')) { return $null }
    $rosterIdEntry = Get-Item Env:SYNAPSE_AUTHORITY_ROSTER_FILE_ID_128 -ErrorAction SilentlyContinue
    $rosterShaEntry = Get-Item Env:SYNAPSE_AUTHORITY_ROSTER_SHA256 -ErrorAction SilentlyContinue
    $rosterLengthEntry = Get-Item Env:SYNAPSE_AUTHORITY_ROSTER_LENGTH -ErrorAction SilentlyContinue
    $expectedRosterId = if ($null -eq $rosterIdEntry) { '' } else { [string]$rosterIdEntry.Value }
    $expectedRosterSha = if ($null -eq $rosterShaEntry) { '' } else { [string]$rosterShaEntry.Value }
    $expectedRosterLength = -1L
    if ($expectedRosterId -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or
        $expectedRosterSha -notmatch '^[0-9A-Fa-f]{64}$' -or $null -eq $rosterLengthEntry -or
        -not [int64]::TryParse([string]$rosterLengthEntry.Value, [ref]$expectedRosterLength) -or
        $expectedRosterLength -lt 1 -or $expectedRosterLength -gt 65536) {
        throw "SYNAPSE_BROKER_AUTHORITY_ROSTER_CAPABILITY_IDENTITY_INVALID path=$AuthorityRosterPath file_id_128=$expectedRosterId sha256=$expectedRosterSha length=$(if($rosterLengthEntry){$rosterLengthEntry.Value}else{'<missing>'})"
    }
    if ($null -eq $script:SynapseAuthorityRosterLease) {
        $script:SynapseAuthorityRosterLease = [SynapseAuthorityRuntime.ExactFile]::OpenControl($AuthorityRosterPath,$expectedRosterId,$expectedRosterSha,$expectedRosterLength)
    }
    $script:SynapseAuthorityRosterLease.RequireExact('supervisor_roster_read')
    $raw = $script:SynapseAuthorityRosterLease.ReadUtf8(65536)
    $envelope = $raw | ConvertFrom-Json -ErrorAction Stop
    $envelopeNames = @($envelope.PSObject.Properties.Name)
    $expectedEnvelopeNames = @('schema','payload_utf8_length','payload_sha256','payload_base64','trailer','self_sha256')
    if ($envelopeNames.Count -ne $expectedEnvelopeNames.Count -or
        @($envelopeNames | Where-Object { $expectedEnvelopeNames -cnotcontains $_ }).Count -gt 0 -or
        [string]$envelope.schema -cne 'synapse_daemon_authority_roster_envelope/v1' -or
        [string]$envelope.trailer -cne 'SYNAPSE_DAEMON_AUTHORITY_ROSTER_V1' -or
        [string]$envelope.payload_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or
        [string]$envelope.self_sha256 -notmatch '^[0-9A-Fa-f]{64}$') {
        throw "SYNAPSE_BROKER_AUTHORITY_ROSTER_ENVELOPE_INVALID path=$AuthorityRosterPath"
    }
    $payloadBytes = [Convert]::FromBase64String([string]$envelope.payload_base64)
    if ($payloadBytes.Length -ne [int]$envelope.payload_utf8_length -or $payloadBytes.Length -gt 49152) {
        throw "SYNAPSE_BROKER_AUTHORITY_ROSTER_PAYLOAD_LENGTH_INVALID path=$AuthorityRosterPath declared=$($envelope.payload_utf8_length) actual=$($payloadBytes.Length)"
    }
    $payloadText = [System.Text.UTF8Encoding]::new($false, $true).GetString($payloadBytes)
    $payloadSha256 = Get-SynapseDaemonTextSha256 -Text $payloadText
    $selfInput = '{0}:{1}:{2}:{3}' -f [string]$envelope.schema,$payloadBytes.Length,$payloadSha256,[string]$envelope.trailer
    if ($payloadSha256 -ine [string]$envelope.payload_sha256 -or
        (Get-SynapseDaemonTextSha256 -Text $selfInput) -ine [string]$envelope.self_sha256) {
        throw "SYNAPSE_BROKER_AUTHORITY_ROSTER_HASH_INVALID path=$AuthorityRosterPath"
    }
    $payload = $payloadText | ConvertFrom-Json -ErrorAction Stop
    if ([string]$payload.schema -cne 'synapse_daemon_authority_roster/v1' -or
        [string]$payload.mode -cne 'active' -or
        [string]$payload.role -notin @('prior','candidate') -or
        [int64]$payload.authority_epoch -ne $AuthorityEpoch -or
        [string]$payload.generation_id -cne $AuthorityGenerationId -or
        [string]$payload.generation_launch_capability_sha256 -ine $AuthorityLaunchCapabilitySha256 -or
        [string]$payload.broker_task_capability_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or
        ('SynapseMcpBroker-'+([string]$payload.broker_task_capability_sha256).ToUpperInvariant().Substring(0,40)) -cne $AuthorityBrokerTaskName -or
        [string]$payload.broker_task_name -cne $AuthorityBrokerTaskName -or
        [string]$payload.broker_script_path -ine $AuthorityBrokerScriptPath -or
        [string]$payload.broker_script_sha256 -ine $AuthorityBrokerScriptSha256 -or
        [string]$payload.bootstrap_path -ine $AuthorityBootstrapPath -or
        [string]$payload.bootstrap_sha256 -ine $AuthorityBootstrapSha256 -or
        [string]$payload.generation_supervisor_path -ine $PSCommandPath -or
        [string]$payload.exe_path -ine $ExePath -or
        [string]$payload.bind -cne $Bind -or
        [string]$payload.db_path -ine $DbPath -or
        [string]$payload.profiles_dir -ine $ProfilesDir -or
        [string]$payload.token_path -ine $TokenPath -or
        [string]$payload.daemon_argument_text -cne $DaemonArgumentText) {
        throw "SYNAPSE_BROKER_AUTHORITY_ROSTER_SEMANTIC_MISMATCH path=$AuthorityRosterPath mode=$($payload.mode) role=$($payload.role) epoch=$($payload.authority_epoch) generation=$($payload.generation_id) task=$($payload.broker_task_name)"
    }
    if ($null -eq $script:SynapseAuthorityValidatedPayload) {
    [void]$script:SynapseAuthorityObjectLeases.Add([SynapseAuthorityRuntime.ExactDirectory]::Open([string]$payload.authority_root_path,[string]$payload.authority_root_file_id_128))
    [void]$script:SynapseAuthorityObjectLeases.Add([SynapseAuthorityRuntime.ExactDirectory]::Open([string]$payload.runtime_bin_dir,[string]$payload.runtime_bin_file_id_128))
    $authorityParentKeys = @{}
    foreach ($generationObject in @($payload.generation_objects)) {
        $generationObjectPath = [System.IO.Path]::GetFullPath([string]$generationObject.path)
        $generationObjectParent = [System.IO.Path]::GetFullPath([string]$generationObject.parent_path)
        if ($generationObjectParent -ine [System.IO.Path]::GetFullPath((Split-Path -Parent $generationObjectPath)) -or
            [string]$generationObject.parent_file_id_128 -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$') {
            throw "SYNAPSE_BROKER_AUTHORITY_OBJECT_PARENT_INVALID path=$generationObjectPath parent=$generationObjectParent"
        }
        $authorityParentKey = $generationObjectParent.ToUpperInvariant()
        if (-not $authorityParentKeys.ContainsKey($authorityParentKey)) {
            $parentLease = [SynapseAuthorityRuntime.ExactDirectory]::Open($generationObjectParent,[string]$generationObject.parent_file_id_128)
            [void]$script:SynapseAuthorityObjectLeases.Add($parentLease)
            $authorityParentKeys[$authorityParentKey] = $true
        }
    }
    foreach ($object in @(
        [pscustomobject]@{ Path=$AuthorityBrokerScriptPath; Id=[string]$payload.broker_script_file_id_128; Expected=$AuthorityBrokerScriptSha256; Length=[int64]$payload.broker_script_length; Role='broker_script' },
        [pscustomobject]@{ Path=$AuthorityBootstrapPath; Id=[string]$payload.bootstrap_file_id_128; Expected=$AuthorityBootstrapSha256; Length=[int64]$payload.bootstrap_length; Role='bootstrap' },
        [pscustomobject]@{ Path=$PSCommandPath; Id=[string]$payload.generation_supervisor_file_id_128; Expected=[string]$payload.generation_supervisor_sha256; Length=[int64]$payload.generation_supervisor_length; Role='generation_supervisor' },
        [pscustomobject]@{ Path=$ExePath; Id=[string]$payload.exe_file_id_128; Expected=[string]$payload.exe_sha256; Length=[int64]$payload.exe_length; Role='daemon' },
        [pscustomobject]@{ Path=$ExpectedCalyxConfigPath; Id=[string]$payload.calyx_config_file_id_128; Expected=$ExpectedCalyxConfigSha256; Length=[int64]$payload.calyx_config_length; Role='calyx_config' }
    )) {
        if ([string]$object.Id -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or
            [string]$object.Expected -notmatch '^[0-9A-Fa-f]{64}$' -or [int64]$object.Length -lt 1) {
            throw "SYNAPSE_BROKER_AUTHORITY_OBJECT_MISSING role=$($object.Role) path=$($object.Path) expected_sha256=$($object.Expected)"
        }
        $lease = [SynapseAuthorityRuntime.ExactFile]::Open([string]$object.Path,[string]$object.Id,[string]$object.Expected,[int64]$object.Length)
        [void]$script:SynapseAuthorityObjectLeases.Add($lease)
    }
    $script:SynapseAuthorityValidatedPayload = $payload
    $script:SynapseAuthorityProfilesLease = [SynapseAuthorityRuntime.ExactDirectory]::Open($ProfilesDir,[string]$payload.profiles_root_file_id_128)
    } elseif ([string]$script:SynapseAuthorityValidatedPayload.generation_id -cne [string]$payload.generation_id -or
        [int64]$script:SynapseAuthorityValidatedPayload.revision -ne [int64]$payload.revision) {
        throw "SYNAPSE_BROKER_AUTHORITY_CACHED_GENERATION_DRIFT cached_generation=$($script:SynapseAuthorityValidatedPayload.generation_id) actual_generation=$($payload.generation_id) cached_revision=$($script:SynapseAuthorityValidatedPayload.revision) actual_revision=$($payload.revision)"
    }
    $script:SynapseAuthorityProfilesLease.RequireExact('supervisor_profiles_root')
    $capabilityEpochEntry = Get-Item Env:SYNAPSE_AUTHORITY_EPOCH -ErrorAction SilentlyContinue
    $capabilityGenerationEntry = Get-Item Env:SYNAPSE_AUTHORITY_GENERATION_ID -ErrorAction SilentlyContinue
    $capabilityTaskEntry = Get-Item Env:SYNAPSE_AUTHORITY_BROKER_TASK_NAME -ErrorAction SilentlyContinue
    $launchCapabilityEntry = Get-Item Env:SYNAPSE_LAUNCH_CAPABILITY_SHA256 -ErrorAction SilentlyContinue
    $brokerIdentityEntry = Get-Item Env:SYNAPSE_BROKER_IDENTITY_SHA256 -ErrorAction SilentlyContinue
    $capabilityBrokerPidEntry = Get-Item Env:SYNAPSE_AUTHORITY_BROKER_PID -ErrorAction SilentlyContinue
    $capabilityEpoch = if ($null -eq $capabilityEpochEntry) { '' } else { [string]$capabilityEpochEntry.Value }
    $capabilityGeneration = if ($null -eq $capabilityGenerationEntry) { '' } else { [string]$capabilityGenerationEntry.Value }
    $capabilityTask = if ($null -eq $capabilityTaskEntry) { '' } else { [string]$capabilityTaskEntry.Value }
    $launchCapability = if ($null -eq $launchCapabilityEntry) { '' } else { [string]$launchCapabilityEntry.Value }
    $launchBrokerIdentity = if ($null -eq $brokerIdentityEntry) { '' } else { [string]$brokerIdentityEntry.Value }
    $capabilityBrokerPidText = if ($null -eq $capabilityBrokerPidEntry) { '' } else { [string]$capabilityBrokerPidEntry.Value }
    $capabilityBrokerPid = 0
    if (-not [int]::TryParse($capabilityBrokerPidText, [ref]$capabilityBrokerPid) -or
        $capabilityEpoch -cne ([string]$AuthorityEpoch) -or
        $capabilityGeneration -cne $AuthorityGenerationId -or
        $capabilityTask -cne $AuthorityBrokerTaskName -or
        $launchCapability -ine $AuthorityLaunchCapabilitySha256 -or
        $launchBrokerIdentity -ine [string]$payload.broker_identity_sha256) {
        throw "SYNAPSE_BROKER_AUTHORITY_CAPABILITY_INVALID epoch=$capabilityEpoch generation=$capabilityGeneration task=$capabilityTask broker_pid=$capabilityBrokerPidText"
    }
    $selfProcess = Get-CimInstance Win32_Process -Filter "ProcessId=$PID" -ErrorAction Stop
    $bootstrapProcess = Get-CimInstance Win32_Process -Filter "ProcessId=$([int]$selfProcess.ParentProcessId)" -ErrorAction Stop
    $brokerProcess = Get-CimInstance Win32_Process -Filter "ProcessId=$([int]$bootstrapProcess.ParentProcessId)" -ErrorAction Stop
    if ([int]$brokerProcess.ProcessId -ne $capabilityBrokerPid -or
        [System.IO.Path]::GetFullPath([string]$bootstrapProcess.ExecutablePath) -ine $AuthorityBootstrapPath -or
        [string]$brokerProcess.CommandLine -notlike "*$AuthorityBrokerScriptPath*") {
        throw "SYNAPSE_BROKER_AUTHORITY_LINEAGE_INVALID supervisor_pid=$PID bootstrap_pid=$($bootstrapProcess.ProcessId) bootstrap_path=$($bootstrapProcess.ExecutablePath) broker_pid=$($brokerProcess.ProcessId) expected_broker_pid=$capabilityBrokerPid"
    }
    return $payload
}

function Read-SynapseBrokerLegacyGateExact {
    if ($null -eq $script:SynapseAuthorityGateLease) {
        $script:SynapseAuthorityGateLease = [SynapseAuthorityRuntime.ExactFile]::OpenControl(
            $SupervisorStopRequestPath,
            $AuthorityLegacyGateFileId128,
            $AuthorityLegacyGateSha256,
            $AuthorityLegacyGateLength)
    }
    $script:SynapseAuthorityGateLease.RequireExact('supervisor_legacy_gate')
    $text = $script:SynapseAuthorityGateLease.ReadUtf8(65536).Trim()
    $request = $text | ConvertFrom-Json -ErrorAction Stop
    if ([string]$request.schema -cne 'synapse_daemon_supervisor_stop_request/v1' -or
        [string]$request.state -cne 'requested' -or [string]$request.bind -cne $Bind) {
        throw "SYNAPSE_BROKER_LEGACY_GATE_SEMANTIC_INVALID path=$SupervisorStopRequestPath schema=$($request.schema) state=$($request.state) bind=$($request.bind)"
    }
    return $request
}

function Test-SynapseBrokerAuthorityCapabilityPresent {
    if ($AuthorityMode -eq 'legacy') { return $false }
    $value = Get-Item Env:SYNAPSE_AUTHORITY_GENERATION_ID -ErrorAction SilentlyContinue
    return ($null -ne $value -and -not [string]::IsNullOrWhiteSpace([string]$value.Value))
}

function Stop-IfOperatorStopRequested {
    param(
        [Parameter(Mandatory=$true)][string]$Phase,
        [int]$Generation,
        [AllowNull()][object]$ChildPid,
        [AllowNull()][object]$ExitCode
    )
    if ($AuthorityMode -eq 'probe') {
        if (-not $OneShot -or
            [string]::IsNullOrWhiteSpace($AuthorityTransactionId) -or
            [string]::IsNullOrWhiteSpace($AuthorityBrokerTaskName)) {
            throw "SYNAPSE_ONESHOT_AUTHORITY_LITERAL_INVALID mode=$AuthorityMode phase=$Phase transaction_id=$AuthorityTransactionId task=$AuthorityBrokerTaskName"
        }
        $selfProcess = Get-CimInstance Win32_Process -Filter "ProcessId=$PID" -ErrorAction Stop
        $bootstrapProcess = Get-CimInstance Win32_Process -Filter "ProcessId=$([int]$selfProcess.ParentProcessId)" -ErrorAction Stop
        if ([System.IO.Path]::GetFullPath([string]$bootstrapProcess.ExecutablePath) -ine $AuthorityBootstrapPath -or
            (Get-SynapseDaemonFileSha256 -Path $AuthorityBootstrapPath) -ine $AuthorityBootstrapSha256) {
            throw "SYNAPSE_ONESHOT_AUTHORITY_BOOTSTRAP_LINEAGE_INVALID mode=$AuthorityMode phase=$Phase supervisor_pid=$PID bootstrap_pid=$($bootstrapProcess.ProcessId) expected_path=$AuthorityBootstrapPath actual_path=$($bootstrapProcess.ExecutablePath)"
        }
        return
    }
    $request = Test-OperatorStopRequestActive
    if ($AuthorityMode -ne 'legacy') {
        $exactGate = Read-SynapseBrokerLegacyGateExact
        if (-not (Test-SynapseBrokerAuthorityCapabilityPresent)) {
            Write-LogLine "SYNAPSE_LEGACY_AUTHORITY_DENIED mode=$AuthorityMode generation=$Generation phase=$Phase gate=$SupervisorStopRequestPath reason=broker_capability_absent"
            Write-SupervisorEvent 'legacy_authority_denied' @{ generation=$Generation; phase=$Phase; authority_mode=$AuthorityMode; authority_epoch=$AuthorityEpoch; authority_generation_id=$AuthorityGenerationId }
            Write-SupervisorState -State 'stopped' -Generation $Generation -ChildPid $ChildPid -ExitCode 0 -Message 'Permanent legacy gate is present and no broker capability was supplied; denied before daemon launch.'
            exit 0
        }
        if ($AuthorityMode -eq 'broker') {
            $authority = Read-SynapseBrokerAuthorityRoster
            Write-LogLine "SYNAPSE_BROKER_AUTHORITY_VERIFIED mode=$AuthorityMode generation=$Generation phase=$Phase epoch=$AuthorityEpoch authority_generation_id=$AuthorityGenerationId roster_revision=$($authority.revision) broker_task=$AuthorityBrokerTaskName"
        } else {
            Write-LogLine "SYNAPSE_PROBE_AUTHORITY_VERIFIED mode=$AuthorityMode generation=$Generation phase=$Phase broker_task=$AuthorityBrokerTaskName roster=not_applicable"
        }
        return
    }
    if ($request.Active -ne $true) {
        return
    }
    Write-LogLine "SYNAPSE_DAEMON_SUPERVISOR_STOP generation=$Generation reason=operator_stop_request phase=$Phase request_path=$SupervisorStopRequestPath request_reason=$($request.Reason) requested_by_pid=$($request.RequestedByPid) requested_at_utc=$($request.RequestedAtUtc)"
    Write-SupervisorEvent 'supervisor_stop' @{
        generation = $Generation
        reason = 'operator_stop_request'
        phase = $Phase
        request_path = $SupervisorStopRequestPath
        request_reason = $request.Reason
        requested_by_pid = $request.RequestedByPid
        requested_at_utc = $request.RequestedAtUtc
    }
    Write-SupervisorState -State 'stopped' -Generation $Generation -ChildPid $ChildPid -ExitCode $ExitCode -Message "Operator stop-request $SupervisorStopRequestPath (reason=$($request.Reason), requested_by_pid=$($request.RequestedByPid)) revoked restart authority; supervisor parked at $Phase instead of launching/restarting."
    exit 0
}

function Wait-AdoptedDaemon {
    param(
        [Parameter(Mandatory=$true)][int]$OwnerPid,
        [int]$Generation
    )
    # An unnamed Job's limit handle cannot be recovered from an arbitrary live
    # process. Adopting would therefore turn the hard memory contract into an
    # unverifiable claim. A daemon this supervisor did not create suspended and
    # assign must be drained by setup before this supervisor is started.
    throw "SYNAPSE_DAEMON_ADOPTION_FORBIDDEN generation=$Generation pid=$OwnerPid bind=$Bind remediation=run setup's verified daemon handoff so the existing owner is drained and its successor is created suspended inside the setup-owned bounded Job"
}

function Register-RapidFailure {
    param([Parameter(Mandatory=$true)][datetime]$FailureTime)
    $rapidFailures.Enqueue($FailureTime)
    while ($rapidFailures.Count -gt 0 -and (($FailureTime - $rapidFailures.Peek()).TotalSeconds -gt $rapidFailureWindowSeconds)) {
        [void]$rapidFailures.Dequeue()
    }
    if ($rapidFailures.Count -ge $rapidFailureLimit) {
        throw "SYNAPSE_DAEMON_CRASH_LOOP rapid_failures=$($rapidFailures.Count) window_seconds=$rapidFailureWindowSeconds bind=$Bind"
    }
    $exponent = [Math]::Min($rapidFailures.Count - 1, 5)
    return [int][Math]::Min($restartCeilingSeconds, $restartFloorSeconds * [Math]::Pow(2, $exponent))
}

trap {
    $message = ($_.Exception.Message -replace '\s+', ' ').Trim()
    try {
        Write-LogLine "SYNAPSE_DAEMON_SUPERVISOR_FATAL error=$message"
        Write-SupervisorEvent 'fatal' @{ generation = $generation; error = $message }
        Write-SupervisorState -State 'fatal' -Generation $generation -ChildPid $null -ExitCode 1 -Message $message
    } catch {
    }
    exit 1
}

if (-not [System.IO.Directory]::Exists($trustedWinPsModuleRoot)) {
    throw "SYNAPSE_DAEMON_WINDOWS_POWERSHELL_MODULE_ROOT_MISSING path=$trustedWinPsModuleRoot remediation=repair the OS-shipped Windows PowerShell module root; the supervisor will not load inherited or user modules"
}

New-Item -ItemType Directory -Force -Path $DaemonLogDir | Out-Null
Initialize-SynapseDaemonBoundedProcessType
foreach ($backendVariable in @('SYNAPSE_DETECTION_BACKEND', 'SYNAPSE_STT_BACKEND')) {
    $backendEntry = Get-Item "Env:$backendVariable" -ErrorAction SilentlyContinue
    if ($null -ne $backendEntry -and ([string]$backendEntry.Value).Trim().ToLowerInvariant() -ne 'cpu') {
        throw "SYNAPSE_ZERO_VRAM_BACKEND_ENV_CONTRADICTION scope=supervisor_process name=$backendVariable value=$($backendEntry.Value) remediation=remove the contradictory durable environment value or set it to cpu; the supervisor will not overwrite and hide it"
    }
}
$captureBackendEntry = Get-Item Env:SYNAPSE_CAPTURE_BACKEND -ErrorAction SilentlyContinue
if ($null -ne $captureBackendEntry -and
    ([string]$captureBackendEntry.Value).Trim().ToLowerInvariant() -notin @('cpu', 'gdi', 'gdi_bitblt')) {
    throw "SYNAPSE_NO_EXPLICIT_GPU_CAPTURE_ENV_CONTRADICTION scope=supervisor_process name=SYNAPSE_CAPTURE_BACKEND value=$($captureBackendEntry.Value) remediation=remove the contradictory durable environment value or set it to gdi_bitblt; the supervisor will not overwrite and hide it"
}
$forceDxgiEntry = Get-Item Env:SYNAPSE_CAPTURE_FORCE_DXGI -ErrorAction SilentlyContinue
if ($null -ne $forceDxgiEntry -and
    ([string]$forceDxgiEntry.Value).Trim().ToLowerInvariant() -notin @('0', 'false', 'no')) {
    throw "SYNAPSE_NO_EXPLICIT_GPU_CAPTURE_ENV_CONTRADICTION scope=supervisor_process name=SYNAPSE_CAPTURE_FORCE_DXGI value=$($forceDxgiEntry.Value) remediation=remove the contradictory durable environment value or set it to false; the supervisor will not overwrite and hide it"
}
$env:SYNAPSE_DETECTION_BACKEND = 'cpu'
$env:SYNAPSE_STT_BACKEND = 'cpu'
$env:SYNAPSE_CAPTURE_BACKEND = 'gdi_bitblt'
$env:SYNAPSE_CAPTURE_FORCE_DXGI = 'false'
$env:CALYX_SEARCH_OPEN_GENERATION_CACHE_ENTRIES = '6'
if ($AuthorityMode -eq 'probe') {
    $env:SYNAPSE_SHELL_JOB_ROOT = $AuthorityShellJobRoot
    if ([string]::IsNullOrWhiteSpace($AuthorityReplacementReservationId)) {
        Remove-Item Env:SYNAPSE_CALYX_GPU_REPLACEMENT_RESERVATION_ID -ErrorAction SilentlyContinue
    } else {
        $env:SYNAPSE_CALYX_GPU_REPLACEMENT_RESERVATION_ID = $AuthorityReplacementReservationId
    }
}
$supervisorJobName = $ParentJobName
$supervisorResourceJob = [SynapseDaemonSupervisor.BoundedProcess]::BindCurrentSupervisor(
    $supervisorJobName,
    $SupervisorMemoryLimitBytes,
    $SupervisorCpuRate)
$supervisorProcess = [System.Diagnostics.Process]::GetProcessById($PID)
$supervisorMemory = Get-SynapseDaemonMemoryReadback `
    -Process $supervisorProcess `
    -PrivateLimitBytes $SupervisorMemoryLimitBytes `
    -Role 'supervisor'
$supervisorResourceJob.RefreshAccounting()
$supervisorJobLimitFlagsHex = '0x{0:X8}' -f $supervisorResourceJob.JobLimitFlags
$supervisorCpuRateFlagsHex = '0x{0:X8}' -f $supervisorResourceJob.CpuRateControlFlags
$initialCalyxConfigSha256 = Assert-SynapseDaemonCalyxConfigIdentity
$bindParts = Get-BindParts
Write-LogLine "SYNAPSE_DAEMON_SUPERVISOR_START supervisor_pid=$PID bind=$Bind db=$DbPath exe=$ExePath calyx_config=$ExpectedCalyxConfigPath calyx_config_sha256=$initialCalyxConfigSha256 math_backend=cpu vram_budget_bytes=0 detection_backend=cpu stt_backend=cpu capture_backend=gdi_bitblt capture_force_dxgi=false search_open_generation_cache_entries=6 parent_job_name=$supervisorJobName parent_job_limit_flags=$supervisorJobLimitFlagsHex parent_cpu_rate_flags=$supervisorCpuRateFlagsHex parent_cpu_rate=$($supervisorResourceJob.CpuRate) parent_job_memory_limit_bytes=$SupervisorMemoryLimitBytes supervisor_private_bytes=$($supervisorMemory.PrivateBytes) supervisor_working_set_bytes=$($supervisorMemory.WorkingSetBytes) working_set_policy=measured_only daemon_job_limit_flags=0x00002300 daemon_cpu_rate=$DaemonCpuRate daemon_memory_limit_bytes=$ProcessMemoryLimitBytes owned_combined_memory_limit_bytes=$SupervisorMemoryLimitBytes bootstrap_preassociation_reserve_bytes=$BootstrapPreAssociationReserveBytes owned_committed_private_ceiling_bytes=$CommittedPrivatePolicyCeilingBytes"
Write-SupervisorEvent 'supervisor_start' @{
    generation = $generation
    exe_path = $ExePath
    calyx_config_path = $ExpectedCalyxConfigPath
    calyx_config_sha256 = $initialCalyxConfigSha256
    math_backend = 'cpu'
    vram_budget_bytes = 0
    detection_backend = 'cpu'
    stt_backend = 'cpu'
    capture_backend = 'gdi_bitblt'
    capture_force_dxgi = $false
    search_open_generation_cache_entries = 6
    job_limit_flags_expected_hex = '0x00002300'
    job_cpu_rate_control_flags_expected_hex = '0x00000005'
    daemon_cpu_rate = $DaemonCpuRate
    working_set_policy = 'measured_only'
    job_security_descriptor_sddl = 'D:P(A;;GA;;;SY)(A;;0x00100004;;;OW)'
    process_memory_limit_bytes = $ProcessMemoryLimitBytes
    job_memory_limit_bytes = $ProcessMemoryLimitBytes
    supervisor_job_name = $supervisorJobName
    supervisor_job_lifetime_owner = $supervisorJobLifetimeOwner
    supervisor_job_accounting_source = 'QueryInformationJobObject(NULL/immediate)'
    supervisor_job_limit_flags_hex = $supervisorJobLimitFlagsHex
    supervisor_job_cpu_rate_control_flags_hex = $supervisorCpuRateFlagsHex
    supervisor_process_memory_limit_bytes = $supervisorResourceJob.ProcessMemoryLimitBytes
    supervisor_job_memory_limit_bytes = $supervisorResourceJob.JobMemoryLimitBytes
    supervisor_cpu_rate = $supervisorResourceJob.CpuRate
    supervisor_private_bytes = $supervisorMemory.PrivateBytes
    supervisor_private_headroom_bytes = $supervisorMemory.PrivateHeadroomBytes
    supervisor_working_set_bytes = $supervisorMemory.WorkingSetBytes
    owned_combined_memory_limit_bytes = $SupervisorMemoryLimitBytes
    bootstrap_preassociation_reserve_bytes = $BootstrapPreAssociationReserveBytes
    owned_committed_private_ceiling_bytes = $CommittedPrivatePolicyCeilingBytes
}
Write-SupervisorState -State 'starting' -Generation $generation -ChildPid $null -ExitCode $null -Message 'Supervisor process started.'
# #2083: a supervisor started while restart authority is revoked (stray logon
# trigger, a task re-enabled by hand, a second launcher) must park before it
# touches the bind, not after it has already raced a second daemon into it.
Stop-IfOperatorStopRequested -Phase 'supervisor_start' -Generation $generation -ChildPid $null -ExitCode $null

while ($true) {
    Stop-IfOperatorStopRequested -Phase 'pre_launch' -Generation $generation -ChildPid $null -ExitCode $null
    $listeners = @(Get-NetTCPConnection -LocalAddress $bindParts.Address -LocalPort $bindParts.Port -State Listen -ErrorAction SilentlyContinue |
        Sort-Object OwningProcess, CreationTime)
    if ($listeners.Count -gt 0) {
        $expectedOwnerPid = $null
        $unexpectedOwners = @()
        $deadOwnerRows = @()
        foreach ($listener in $listeners) {
            $ownerPid = [int]$listener.OwningProcess
            $ownerInfo = Get-ProcessInfoForPid -ProcessId $ownerPid
            if ($null -eq $ownerInfo) {
                $deadOwnerRows += $listener
                continue
            }
            if (Test-ExpectedDaemonProcess -ProcessInfo $ownerInfo) {
                if ($null -eq $expectedOwnerPid) {
                    $expectedOwnerPid = $ownerPid
                }
                continue
            }
            $unexpectedOwners += $ownerInfo
        }

        if ($unexpectedOwners.Count -gt 0) {
            $unexpectedSummary = @($unexpectedOwners | ForEach-Object {
                'pid={0} exe={1} command={2}' -f [int]$_.ProcessId, [string]$_.ExecutablePath, (([string]$_.CommandLine -replace '\s+', ' ').Trim())
            }) -join ' | '
            throw "SYNAPSE_DAEMON_BIND_OCCUPIED bind=$Bind live_unexpected_owner_count=$($unexpectedOwners.Count) owners=$unexpectedSummary"
        }

        if ($null -ne $expectedOwnerPid) {
            Wait-AdoptedDaemon -OwnerPid $expectedOwnerPid -Generation $generation
            continue
        }

        $staleOwnerPids = @($deadOwnerRows | ForEach-Object { [int]$_.OwningProcess } | Sort-Object -Unique)
        $staleCreationTimes = @($deadOwnerRows | ForEach-Object { [string]$_.CreationTime })
        $drainStarted = Get-Date
        $drainAttempts = 0
        $lastBindProbeError = $null
        Write-LogLine "SYNAPSE_DAEMON_DEAD_OWNER_BIND_DRAIN_START generation=$generation bind=$Bind stale_owner_pids=$($staleOwnerPids -join ',') listener_count=$($deadOwnerRows.Count) timeout_seconds=$deadOwnerBindDrainSeconds"
        Write-SupervisorEvent 'dead_owner_bind_drain_start' @{
            generation = $generation
            stale_owner_pids = $staleOwnerPids
            listener_count = $deadOwnerRows.Count
            listener_creation_times = $staleCreationTimes
            timeout_seconds = $deadOwnerBindDrainSeconds
        }
        while ($true) {
            $drainAttempts += 1
            $bindProbe = Test-ExactBindAvailable -Address $bindParts.Address -Port $bindParts.Port
            if ($bindProbe.Available -eq $true) {
                break
            }
            $lastBindProbeError = $bindProbe.Error

            $drainListeners = @(Get-NetTCPConnection -LocalAddress $bindParts.Address -LocalPort $bindParts.Port -State Listen -ErrorAction SilentlyContinue |
                Sort-Object OwningProcess, CreationTime)
            $liveDrainOwners = @()
            foreach ($drainListener in $drainListeners) {
                $drainOwner = Get-ProcessInfoForPid -ProcessId ([int]$drainListener.OwningProcess)
                if ($null -ne $drainOwner) {
                    $liveDrainOwners += $drainOwner
                }
            }
            if ($liveDrainOwners.Count -gt 0) {
                $liveDrainSummary = @($liveDrainOwners | ForEach-Object {
                    'pid={0} exe={1} command={2}' -f [int]$_.ProcessId, [string]$_.ExecutablePath, (([string]$_.CommandLine -replace '\s+', ' ').Trim())
                }) -join ' | '
                throw "SYNAPSE_DAEMON_BIND_OCCUPIED_DURING_DEAD_OWNER_DRAIN bind=$Bind owners=$liveDrainSummary bind_probe_error=$lastBindProbeError"
            }

            $drainElapsedMs = [int64]((Get-Date) - $drainStarted).TotalMilliseconds
            if ($drainElapsedMs -ge ($deadOwnerBindDrainSeconds * 1000)) {
                throw "SYNAPSE_DAEMON_DEAD_OWNER_BIND_DRAIN_TIMEOUT bind=$Bind stale_owner_pids=$($staleOwnerPids -join ',') attempts=$drainAttempts elapsed_ms=$drainElapsedMs bind_probe_error=$lastBindProbeError"
            }
            if ($drainAttempts -eq 1 -or ($drainAttempts % 10) -eq 0) {
                Write-LogLine "SYNAPSE_DAEMON_DEAD_OWNER_BIND_DRAIN_PROGRESS generation=$generation bind=$Bind stale_owner_pids=$($staleOwnerPids -join ',') attempts=$drainAttempts elapsed_ms=$drainElapsedMs bind_probe_error=$lastBindProbeError"
                Write-SupervisorEvent 'dead_owner_bind_drain_progress' @{
                    generation = $generation
                    stale_owner_pids = $staleOwnerPids
                    attempts = $drainAttempts
                    elapsed_ms = $drainElapsedMs
                    bind_probe_error = $lastBindProbeError
                }
                Write-SupervisorState -State 'dead_owner_bind_drain' -Generation $generation -ChildPid $null -ExitCode $null -Message "Waiting for the kernel to release dead-owner TCP row(s) for pid(s) $($staleOwnerPids -join ','); attempt=$drainAttempts elapsed_ms=$drainElapsedMs last_bind_error=$lastBindProbeError"
            }
            Start-Sleep -Milliseconds $deadOwnerBindDrainPollMilliseconds
        }

        $drainElapsedMs = [int64]((Get-Date) - $drainStarted).TotalMilliseconds
        Write-LogLine "SYNAPSE_DAEMON_DEAD_OWNER_BIND_DRAINED generation=$generation bind=$Bind stale_owner_pids=$($staleOwnerPids -join ',') listener_count=$($deadOwnerRows.Count) attempts=$drainAttempts elapsed_ms=$drainElapsedMs bind_probe=success"
        Write-SupervisorEvent 'dead_owner_bind_drained' @{
            generation = $generation
            stale_owner_pids = $staleOwnerPids
            listener_count = $deadOwnerRows.Count
            listener_creation_times = $staleCreationTimes
            attempts = $drainAttempts
            elapsed_ms = $drainElapsedMs
            bind_probe_ok = $true
        }
        Write-SupervisorState -State 'dead_owner_bind_drained' -Generation $generation -ChildPid $null -ExitCode $null -Message "Kernel release of $($deadOwnerRows.Count) dead-owner TCP listener row(s) for pid(s) $($staleOwnerPids -join ',') was verified by an exclusive bind probe after ${drainElapsedMs}ms."
    }

    $generation += 1
    $token = Read-SynapseToken
    $generationCalyxConfigSha256 = Assert-SynapseDaemonCalyxConfigIdentity
    $env:SYNAPSE_BEARER_TOKEN = $token
    $env:SYNAPSE_LOG_DIR = $DaemonLogDir

    # Capture child stderr to a per-generation rotating file. Rust writes its
    # crash diagnostics here before __fastfail/abort (e.g. "memory allocation of
    # N bytes failed", "thread '<name>' has overflowed its stack", or a panic
    # message). Without this redirect those lines are lost and a 0xC0000409 exit
    # is unattributable (see issue #1809). Keep the most recent 10 files.
    $stderrLog = Join-Path $DaemonLogDir ('daemon-stderr-gen{0}-{1}.log' -f $generation, (Get-Date -Format 'yyyyMMddHHmmss'))
    try {
        $staleStderr = @(Get-ChildItem -LiteralPath $DaemonLogDir -Filter 'daemon-stderr-gen*.log' -File -ErrorAction SilentlyContinue |
            Sort-Object LastWriteTime -Descending | Select-Object -Skip 9)
        foreach ($old in $staleStderr) { Remove-Item -LiteralPath $old.FullName -Force -ErrorAction SilentlyContinue }
    } catch { }

    $daemonArgumentTextForGeneration = "$DaemonArgumentText --parent-pid $PID"
    $jobName = 'Local\SynapseDaemon-{0}-{1}' -f $PID, $generation
    Write-LogLine "SYNAPSE_DAEMON_LAUNCH_START generation=$generation command=$ExePath $daemonArgumentTextForGeneration calyx_config_sha256=$generationCalyxConfigSha256 job_name=$jobName job_limit_flags=0x00002300 process_memory_limit_bytes=$ProcessMemoryLimitBytes job_memory_limit_bytes=$ProcessMemoryLimitBytes working_set_policy=measured_only"
    Write-SupervisorEvent 'launch_start' @{
        generation = $generation
        exe_path = $ExePath
        arguments = $daemonArgumentTextForGeneration
        stderr_log = $stderrLog
        parent_pid = $PID
        job_name = $jobName
        calyx_config_sha256 = $generationCalyxConfigSha256
        job_limit_flags_expected_hex = '0x00002300'
        job_security_descriptor_sddl = 'D:P(A;;GA;;;SY)(A;;0x00100004;;;OW)'
        process_memory_limit_bytes = $ProcessMemoryLimitBytes
        job_memory_limit_bytes = $ProcessMemoryLimitBytes
        working_set_policy = 'measured_only'
    }
    Write-SupervisorState -State 'launching' -Generation $generation -ChildPid $null -ExitCode $null -Message 'Starting synapse-mcp daemon.'

    if ($AuthorityMode -eq 'broker') {
        [void](Read-SynapseBrokerAuthorityRoster)
        $script:SynapseAuthorityGateLease.RequireExact('supervisor_prelaunch_gate')
        $script:SynapseAuthorityRosterLease.RequireExact('supervisor_prelaunch_roster')
        $script:SynapseAuthorityProfilesLease.RequireExact('supervisor_prelaunch_profiles_root')
        foreach ($authorityObjectLease in $script:SynapseAuthorityObjectLeases) {
            if ($null -eq $authorityObjectLease) { throw 'SYNAPSE_BROKER_AUTHORITY_OBJECT_LEASE_MISSING' }
            $authorityObjectLease.RequireExact('supervisor_prelaunch_object')
        }
    }
    $startTime = Get-Date
    $daemonJob = [SynapseDaemonSupervisor.BoundedProcess]::Launch(
        $ExePath,
        $daemonArgumentTextForGeneration,
        (Split-Path -Parent $ExePath),
        $stderrLog,
        $jobName,
        $ProcessMemoryLimitBytes,
        $DaemonCpuRate)
    try {
        $process = [System.Diagnostics.Process]::GetProcessById([int]$daemonJob.ProcessId)
    } catch {
        throw "SYNAPSE_DAEMON_LAUNCH_PROCESS_LOOKUP_FAILED generation=$generation pid=$($daemonJob.ProcessId) error=$($_.Exception.Message) remediation=inspect daemon stderr; the bounded child exited before its exact process object could be retained"
    }
    # #2090: touching .Handle caches the native process handle in the
    # System.Diagnostics.Process object. Without it, `Start-Process -PassThru`
    # does not keep a handle open, the kernel object is released when the child
    # exits, and `$process.ExitCode` reads back $null for EVERY exit. That made
    # the `$exitCode -eq 0` park below dead code since it was written: a daemon
    # that exited cleanly was indistinguishable from one that crashed, and the
    # supervisor relaunched it. It is load-bearing now, because the #2090
    # OS-shutdown drain exits 0 specifically to tell the supervisor "the machine
    # is going down, do not start another daemon".
    $daemonProcessHandle = $null
    try {
        $daemonProcessHandle = $process.Handle
    } catch {
        throw "SYNAPSE_DAEMON_LAUNCH_HANDLE_CACHE_FAILED generation=$generation pid=$($process.Id) error=$($_.Exception.Message) remediation=repair process-handle access; the supervisor cannot distinguish clean exit from crash without the exact retained handle"
    }
    $childInfo = Get-ProcessInfoForPid -ProcessId $process.Id
    if ($null -eq $childInfo) {
        throw "SYNAPSE_DAEMON_LAUNCH_IDENTITY_MISSING generation=$generation pid=$($process.Id) remediation=inspect the retained process handle and stderr; a child that disappeared before identity capture is not a running generation"
    }
    if (-not (Test-ExpectedDaemonProcess -ProcessInfo $childInfo -ExpectedParentPid $PID)) {
        throw "SYNAPSE_DAEMON_LAUNCH_IDENTITY_MISMATCH generation=$generation pid=$($process.Id) exe=$($childInfo.ExecutablePath) command=$(([string]$childInfo.CommandLine -replace '\s+', ' ').Trim()) remediation=inspect the generated daemon arguments; the supervisor will not monitor an unverified child"
    }
    $childCreationDate = [string]$childInfo.CreationDate
    if ([string]::IsNullOrWhiteSpace($childCreationDate)) {
        throw "SYNAPSE_DAEMON_LAUNCH_CREATION_TIME_MISSING generation=$generation pid=$($process.Id) remediation=repair Win32_Process identity reads; PID alone cannot identify a daemon generation"
    }
    $launchMemory = Get-SynapseDaemonMemoryReadback -Process $process
    $jobLimitFlagsHex = '0x{0:X8}' -f $daemonJob.JobLimitFlags
    $jobCpuRateFlagsHex = '0x{0:X8}' -f $daemonJob.CpuRateControlFlags
    Write-LogLine "SYNAPSE_DAEMON_LAUNCH_OK generation=$generation pid=$($process.Id) creation_date=$childCreationDate parent_pid=$PID stderr_log=$stderrLog exit_code_observable=true job_name=$($daemonJob.JobName) job_limit_flags=$jobLimitFlagsHex job_cpu_rate_control_flags=$jobCpuRateFlagsHex job_cpu_rate=$($daemonJob.CpuRate) process_memory_limit_bytes=$($daemonJob.ProcessMemoryLimitBytes) job_memory_limit_bytes=$($daemonJob.JobMemoryLimitBytes) private_bytes=$($launchMemory.PrivateBytes) private_headroom_bytes=$($launchMemory.PrivateHeadroomBytes) working_set_bytes=$($launchMemory.WorkingSetBytes) working_set_policy=measured_only"
    Write-SupervisorEvent 'launch_ok' @{
        generation = $generation
        child_pid = $process.Id
        child_creation_date = $childCreationDate
        parent_pid = $PID
        stderr_log = $stderrLog
        job_name = $daemonJob.JobName
        job_limit_flags_hex = $jobLimitFlagsHex
        job_cpu_rate_control_flags_hex = $jobCpuRateFlagsHex
        job_cpu_rate = $daemonJob.CpuRate
        process_memory_limit_bytes = $daemonJob.ProcessMemoryLimitBytes
        job_memory_limit_bytes = $daemonJob.JobMemoryLimitBytes
        working_set_policy = 'measured_only'
        private_bytes = $launchMemory.PrivateBytes
        private_headroom_bytes = $launchMemory.PrivateHeadroomBytes
        working_set_bytes = $launchMemory.WorkingSetBytes
    }
    Write-SupervisorState -State 'starting' -Generation $generation -ChildPid $process.Id -ExitCode $null -Message "Daemon exact child identity exists; waiting up to ${daemonStartupSeconds}s for exact listener ownership and authenticated health before publishing running." -Fields @{
        job_name = $daemonJob.JobName
        job_limit_flags_hex = $jobLimitFlagsHex
        job_cpu_rate_control_flags_hex = $jobCpuRateFlagsHex
        job_cpu_rate = $daemonJob.CpuRate
        job_process_memory_limit_bytes = $daemonJob.ProcessMemoryLimitBytes
        job_memory_limit_bytes = $daemonJob.JobMemoryLimitBytes
        working_set_policy = 'measured_only'
        private_bytes = $launchMemory.PrivateBytes
        private_headroom_bytes = $launchMemory.PrivateHeadroomBytes
        working_set_bytes = $launchMemory.WorkingSetBytes
    }

    $startupDeadline = (Get-Date).AddSeconds($daemonStartupSeconds)
    $startupAttempts = 0
    while ($true) {
        $startupAttempts += 1
        $readiness = Test-ExactChildReady -ChildPid $process.Id -CreationDate $childCreationDate -Token $token -BindParts $bindParts
        if ($readiness.Ready -eq $true) {
            break
        }
        if ($readiness.Terminal -eq $true) {
            Write-LogLine "SYNAPSE_DAEMON_STARTING_EXITED generation=$generation pid=$($process.Id) creation_date=$childCreationDate attempts=$startupAttempts reason=$($readiness.Reason)"
            Write-SupervisorEvent 'starting_exited' @{ generation = $generation; child_pid = $process.Id; child_creation_date = $childCreationDate; attempts = $startupAttempts; reason = $readiness.Reason }
            break
        }
        if ((Get-Date) -ge $startupDeadline) {
            throw "SYNAPSE_DAEMON_STARTUP_TIMEOUT generation=$generation pid=$($process.Id) creation_date=$childCreationDate attempts=$startupAttempts timeout_seconds=$daemonStartupSeconds last_readiness=$($readiness.Reason) remediation=inspect daemon stderr, exact listener ownership, authenticated /health, and vault-open progress; no replacement is launched while this exact child remains alive"
        }
        if ($startupAttempts -eq 1 -or ($startupAttempts % 20) -eq 0) {
            $startupElapsedMs = [int64]((Get-Date) - $startTime).TotalMilliseconds
            $startupMemory = Get-SynapseDaemonMemoryReadback -Process $process
            $daemonJob.RefreshAccounting()
            Write-LogLine "SYNAPSE_DAEMON_STARTING generation=$generation pid=$($process.Id) creation_date=$childCreationDate attempts=$startupAttempts readiness=$($readiness.Reason)"
            Write-SupervisorEvent 'starting_progress' @{ generation = $generation; child_pid = $process.Id; child_creation_date = $childCreationDate; attempts = $startupAttempts; elapsed_ms = $startupElapsedMs; readiness = $readiness.Reason }
            Write-SupervisorState -State 'starting' -Generation $generation -ChildPid $process.Id -ExitCode $null -Message "Daemon exact child remains live; readiness=$($readiness.Reason) attempts=$startupAttempts elapsed_ms=$startupElapsedMs. No replacement is eligible." -Fields @{
                job_name = $daemonJob.JobName
                job_limit_flags_hex = $jobLimitFlagsHex
                job_cpu_rate_control_flags_hex = $jobCpuRateFlagsHex
                job_cpu_rate = $daemonJob.CpuRate
                job_process_memory_limit_bytes = $daemonJob.ProcessMemoryLimitBytes
                job_memory_limit_bytes = $daemonJob.JobMemoryLimitBytes
                working_set_policy = 'measured_only'
                private_bytes = $startupMemory.PrivateBytes
                private_headroom_bytes = $startupMemory.PrivateHeadroomBytes
                working_set_bytes = $startupMemory.WorkingSetBytes
                peak_process_memory_used_bytes = $daemonJob.PeakProcessMemoryUsedBytes
                peak_job_memory_used_bytes = $daemonJob.PeakJobMemoryUsedBytes
            }
        }
        Start-Sleep -Milliseconds $daemonStartupPollMilliseconds
    }
    if ($readiness.Ready -eq $true) {
        $readyMemory = Get-SynapseDaemonMemoryReadback -Process $process
        $daemonJob.RefreshAccounting()
        Write-LogLine "SYNAPSE_DAEMON_READY generation=$generation pid=$($process.Id) creation_date=$childCreationDate attempts=$startupAttempts evidence=$($readiness.Reason) private_bytes=$($readyMemory.PrivateBytes) private_headroom_bytes=$($readyMemory.PrivateHeadroomBytes) working_set_bytes=$($readyMemory.WorkingSetBytes) working_set_policy=measured_only peak_process_memory_used_bytes=$($daemonJob.PeakProcessMemoryUsedBytes) peak_job_memory_used_bytes=$($daemonJob.PeakJobMemoryUsedBytes)"
        Write-SupervisorEvent 'ready' @{
            generation = $generation
            child_pid = $process.Id
            child_creation_date = $childCreationDate
            attempts = $startupAttempts
            evidence = $readiness.Reason
            private_bytes = $readyMemory.PrivateBytes
            private_headroom_bytes = $readyMemory.PrivateHeadroomBytes
            working_set_bytes = $readyMemory.WorkingSetBytes
            peak_process_memory_used_bytes = $daemonJob.PeakProcessMemoryUsedBytes
            peak_job_memory_used_bytes = $daemonJob.PeakJobMemoryUsedBytes
        }
        Write-SupervisorState -State 'running' -Generation $generation -ChildPid $process.Id -ExitCode $null -Message 'Daemon exact PID/creation/image/arguments own the listener and authenticated health returned 200.' -Fields @{
            job_name = $daemonJob.JobName
            job_limit_flags_hex = $jobLimitFlagsHex
            job_cpu_rate_control_flags_hex = $jobCpuRateFlagsHex
            job_cpu_rate = $daemonJob.CpuRate
            job_process_memory_limit_bytes = $daemonJob.ProcessMemoryLimitBytes
            job_memory_limit_bytes = $daemonJob.JobMemoryLimitBytes
            working_set_policy = 'measured_only'
            private_bytes = $readyMemory.PrivateBytes
            private_headroom_bytes = $readyMemory.PrivateHeadroomBytes
            working_set_bytes = $readyMemory.WorkingSetBytes
            peak_process_memory_used_bytes = $daemonJob.PeakProcessMemoryUsedBytes
            peak_job_memory_used_bytes = $daemonJob.PeakJobMemoryUsedBytes
        }
    }

    # #2236: after launch identity has been verified, the retained native
    # process handle is the authoritative identity and lifetime SoT. Windows
    # keeps that exact process object alive while the handle is open and
    # signals it at termination. A post-exit Win32_Process row can transiently
    # remain enumerable with already-cleared image/command-line properties;
    # allowing that teardown view to override WaitForExit(true) stranded the
    # daemon with SYNAPSE_DAEMON_CHILD_IDENTITY_DRIFT after a graceful restart.
    # The parameterless wait synchronizes redirected stream completion and
    # makes ExitCode immediately observable from this same exact handle. In a
    # broker generation, poll the immutable roster capability while the exact
    # child is live. A roster revision/generation change disposes the daemon Job
    # first, which drains the exact child tree before this supervisor exits.
    if ($AuthorityMode -ne 'broker') {
        $process.WaitForExit()
    } else {
        while (-not $process.WaitForExit(1000)) {
            try {
                [void](Read-SynapseBrokerAuthorityRoster)
            } catch {
                $authorityDrift = ($_.Exception.Message -replace '\s+', ' ').Trim()
                Write-LogLine "SYNAPSE_BROKER_AUTHORITY_REVOKED generation=$generation pid=$($process.Id) authority_generation_id=$AuthorityGenerationId error=$authorityDrift"
                Write-SupervisorEvent 'broker_authority_revoked' @{ generation=$generation; child_pid=$process.Id; authority_epoch=$AuthorityEpoch; authority_generation_id=$AuthorityGenerationId; error=$authorityDrift }
                $daemonJob.Dispose()
                $process.WaitForExit()
                throw "SYNAPSE_BROKER_AUTHORITY_REVOKED_DURING_CHILD generation=$generation child_pid=$($process.Id) error=$authorityDrift"
            }
        }
        $process.WaitForExit()
    }
    $terminalIdentity = Get-ExactChildIdentityState -ChildPid $process.Id -CreationDate $childCreationDate
    Write-LogLine "SYNAPSE_DAEMON_EXACT_HANDLE_TERMINAL_PROVED generation=$generation pid=$($process.Id) creation_date=$childCreationDate post_exit_identity=$($terminalIdentity.Reason)"
    Write-SupervisorEvent 'exact_handle_terminal_proved' @{ generation = $generation; child_pid = $process.Id; child_creation_date = $childCreationDate; post_exit_identity = $terminalIdentity.Reason }
    $endTime = Get-Date
    $exitCode = $process.ExitCode
    if ($null -eq $exitCode) {
        throw "SYNAPSE_DAEMON_EXIT_CODE_UNOBSERVABLE generation=$generation pid=$($process.Id) creation_date=$childCreationDate handle_cached=$($null -ne $daemonProcessHandle) remediation=inspect the retained process handle; the supervisor cannot choose clean-stop versus restart without the physical exit code"
    }
    $daemonJob.RefreshAccounting()
    $peakProcessMemoryUsedBytes = $daemonJob.PeakProcessMemoryUsedBytes
    $peakJobMemoryUsedBytes = $daemonJob.PeakJobMemoryUsedBytes
    $daemonJob.Dispose()
    $runtimeMs = [int64](($endTime - $startTime).TotalMilliseconds)
    $stderrTail = ''
    try {
        if (Test-Path -LiteralPath $stderrLog -PathType Leaf) {
            $stderrTail = ((Get-Content -LiteralPath $stderrLog -Tail 40 -ErrorAction SilentlyContinue) -join ' | ').Trim()
        }
    } catch { }
    Write-LogLine "SYNAPSE_DAEMON_EXIT generation=$generation pid=$($process.Id) exit_code=$exitCode runtime_ms=$runtimeMs stderr_log=$stderrLog peak_process_memory_used_bytes=$peakProcessMemoryUsedBytes peak_job_memory_used_bytes=$peakJobMemoryUsedBytes"
    if ($exitCode -ne 0 -and -not [string]::IsNullOrWhiteSpace($stderrTail)) {
        Write-LogLine "SYNAPSE_DAEMON_STDERR generation=$generation pid=$($process.Id) exit_code=$exitCode tail=$stderrTail"
    }
    Write-SupervisorEvent 'child_exit' @{ generation = $generation; child_pid = $process.Id; exit_code = $exitCode; runtime_ms = $runtimeMs; stderr_log = $stderrLog; stderr_tail = $stderrTail; peak_process_memory_used_bytes = $peakProcessMemoryUsedBytes; peak_job_memory_used_bytes = $peakJobMemoryUsedBytes }
    Write-SupervisorState -State 'child_exited' -Generation $generation -ChildPid $process.Id -ExitCode $exitCode -Message "Daemon child exited after ${runtimeMs}ms." -Fields @{
        job_name = $daemonJob.JobName
        job_limit_flags_hex = $jobLimitFlagsHex
        job_cpu_rate_control_flags_hex = $jobCpuRateFlagsHex
        job_cpu_rate = $daemonJob.CpuRate
        job_process_memory_limit_bytes = $daemonJob.ProcessMemoryLimitBytes
        job_memory_limit_bytes = $daemonJob.JobMemoryLimitBytes
        working_set_policy = 'measured_only'
        peak_process_memory_used_bytes = $peakProcessMemoryUsedBytes
        peak_job_memory_used_bytes = $peakJobMemoryUsedBytes
    }

    if ($OneShot) {
        Write-LogLine "SYNAPSE_DAEMON_SUPERVISOR_STOP generation=$generation reason=one_shot_child_exit exit_code=$exitCode"
        Write-SupervisorEvent 'supervisor_stop' @{ generation = $generation; reason = 'one_shot_child_exit'; exit_code = $exitCode }
        Write-SupervisorState -State 'stopped' -Generation $generation -ChildPid $process.Id -ExitCode $exitCode -Message 'One-shot candidate generation exited; restart authority was never granted.' -Fields @{
            job_name = $daemonJob.JobName
            job_limit_flags_hex = $jobLimitFlagsHex
            job_cpu_rate_control_flags_hex = $jobCpuRateFlagsHex
            job_cpu_rate = $daemonJob.CpuRate
            job_process_memory_limit_bytes = $daemonJob.ProcessMemoryLimitBytes
            job_memory_limit_bytes = $daemonJob.JobMemoryLimitBytes
            working_set_policy = 'measured_only'
            peak_process_memory_used_bytes = $peakProcessMemoryUsedBytes
            peak_job_memory_used_bytes = $peakJobMemoryUsedBytes
        }
        exit $exitCode
    }

    Stop-IfOperatorStopRequested -Phase 'post_child_exit' -Generation $generation -ChildPid $process.Id -ExitCode $exitCode
    Stop-IfSetupMaintenanceActive -Phase 'post_child_exit' -Generation $generation -ChildPid $process.Id -ExitCode $exitCode

    if ($exitCode -eq 0) {
        Write-LogLine "SYNAPSE_DAEMON_SUPERVISOR_STOP generation=$generation reason=daemon_exit_zero"
        Write-SupervisorEvent 'supervisor_stop' @{ generation = $generation; reason = 'daemon_exit_zero' }
        Write-SupervisorState -State 'stopped' -Generation $generation -ChildPid $process.Id -ExitCode 0 -Message 'Daemon exited cleanly; supervisor stopped.'
        exit 0
    }

    $delaySeconds = Register-RapidFailure -FailureTime $endTime
    Write-LogLine "SYNAPSE_DAEMON_RESTART_SCHEDULED generation=$generation exit_code=$exitCode delay_seconds=$delaySeconds rapid_failures=$($rapidFailures.Count)"
    Write-SupervisorEvent 'restart_scheduled' @{ generation = $generation; exit_code = $exitCode; delay_seconds = $delaySeconds; rapid_failures = $rapidFailures.Count }
    Write-SupervisorState -State 'restart_wait' -Generation $generation -ChildPid $process.Id -ExitCode $exitCode -Message "Restart scheduled in ${delaySeconds}s after non-zero child exit."
    Start-Sleep -Seconds $delaySeconds
    # #2083: authority can be revoked DURING the backoff sleep (up to 60s). Both
    # revocation records are re-read here so a stop that lands mid-backoff parks
    # this supervisor instead of letting it wake up and relaunch.
    Stop-IfOperatorStopRequested -Phase 'post_restart_backoff' -Generation $generation -ChildPid $process.Id -ExitCode $exitCode
    Stop-IfSetupMaintenanceActive -Phase 'post_restart_backoff' -Generation $generation -ChildPid $process.Id -ExitCode $exitCode
}
'@

    $supervisorScript = $supervisorScript.
        Replace('__EXE_PATH__', (Quote-PowerShellSingleQuotedString $ExePath)).
        Replace('__BIND__', (Quote-PowerShellSingleQuotedString $Bind)).
        Replace('__DB_PATH__', (Quote-PowerShellSingleQuotedString $DbPath)).
        Replace('__PROFILES_DIR__', (Quote-PowerShellSingleQuotedString $ProfilesDir)).
        Replace('__DAEMON_LOG_DIR__', (Quote-PowerShellSingleQuotedString $daemonLogDir)).
        Replace('__TOKEN_PATH__', (Quote-PowerShellSingleQuotedString $TokenPath)).
        Replace('__LAUNCHER_LOG__', (Quote-PowerShellSingleQuotedString $launcherLog)).
        Replace('__SUPERVISOR_STATE__', (Quote-PowerShellSingleQuotedString $supervisorState)).
        Replace('__SUPERVISOR_EVENTS__', (Quote-PowerShellSingleQuotedString $supervisorEvents)).
        Replace('__MAINTENANCE_LOCK_PATH__', (Quote-PowerShellSingleQuotedString $MaintenanceLockPath)).
        Replace('__SUPERVISOR_STOP_REQUEST_PATH__', (Quote-PowerShellSingleQuotedString $supervisorStopRequestPath)).
        Replace('__EXPECTED_CALYX_CONFIG_PATH__', (Quote-PowerShellSingleQuotedString $CalyxConfigPath)).
        Replace('__EXPECTED_CALYX_CONFIG_SHA256__', (Quote-PowerShellSingleQuotedString $expectedCalyxConfigSha256)).
        Replace('__DAEMON_ARGUMENT_TEXT__', (Quote-PowerShellSingleQuotedString $daemonArgumentText)).
        Replace('__EXPECTED_ALLOWED_PERMISSIONS__', (Quote-PowerShellSingleQuotedString $allowedPermissionsArgument)).
        Replace('__EXPECTED_ENABLE_AUDIO__', (Quote-PowerShellSingleQuotedString ([string]$EnableAudio))).
        Replace('__PROCESS_MEMORY_LIMIT_BYTES__', ([string]$SynapseDaemonProcessMemoryLimitBytes)).
        Replace('__SUPERVISOR_MEMORY_LIMIT_BYTES__', ([string]$SynapseSupervisorMemoryLimitBytes)).
        Replace('__BOOTSTRAP_PREASSOCIATION_RESERVE_BYTES__', ([string]$SynapseBootstrapPreAssociationReserveBytes)).
        Replace('__DAEMON_CPU_RATE__', ([string]$SynapseDaemonCpuRate)).
        Replace('__SUPERVISOR_CPU_RATE__', ([string]$ExpectedParentJobCpuRate)).
        Replace('__AUTHORITY_MODE__', (Quote-PowerShellSingleQuotedString $AuthorityMode)).
        Replace('__AUTHORITY_ROSTER_PATH__', (Quote-PowerShellSingleQuotedString $AuthorityRosterPath)).
        Replace('__AUTHORITY_LEGACY_GATE_FILE_ID_128__', (Quote-PowerShellSingleQuotedString $AuthorityLegacyGateFileId128)).
        Replace('__AUTHORITY_LEGACY_GATE_SHA256__', (Quote-PowerShellSingleQuotedString $AuthorityLegacyGateSha256)).
        Replace('__AUTHORITY_LEGACY_GATE_LENGTH__', ([string]$AuthorityLegacyGateLength)).
        Replace('__AUTHORITY_EPOCH__', ([string]$AuthorityEpoch)).
        Replace('__AUTHORITY_GENERATION_ID__', (Quote-PowerShellSingleQuotedString $AuthorityGenerationId)).
        Replace('__AUTHORITY_LAUNCH_CAPABILITY_SHA256__', (Quote-PowerShellSingleQuotedString $AuthorityLaunchCapabilitySha256)).
        Replace('__AUTHORITY_BROKER_TASK_NAME__', (Quote-PowerShellSingleQuotedString $AuthorityBrokerTaskName)).
        Replace('__AUTHORITY_BROKER_SCRIPT_PATH__', (Quote-PowerShellSingleQuotedString $AuthorityBrokerScriptPath)).
        Replace('__AUTHORITY_BROKER_SCRIPT_SHA256__', (Quote-PowerShellSingleQuotedString $AuthorityBrokerScriptSha256)).
        Replace('__AUTHORITY_BOOTSTRAP_PATH__', (Quote-PowerShellSingleQuotedString $AuthorityBootstrapPath)).
        Replace('__AUTHORITY_BOOTSTRAP_SHA256__', (Quote-PowerShellSingleQuotedString $AuthorityBootstrapSha256)).
        Replace('__AUTHORITY_TRANSACTION_ID__', (Quote-PowerShellSingleQuotedString $AuthorityTransactionId)).
        Replace('__AUTHORITY_SHELL_JOB_ROOT__', (Quote-PowerShellSingleQuotedString $AuthorityShellJobRoot)).
        Replace('__AUTHORITY_REPLACEMENT_RESERVATION_ID__', (Quote-PowerShellSingleQuotedString $AuthorityReplacementReservationId))
    $supervisorScript = $supervisorScript.Replace('__AUTHORITY_EXACT_READER__', (Get-SynapseAuthorityExactReaderPowerShell))
    $supervisorScript = $supervisorScript.Replace('__ONE_SHOT__', (Quote-PowerShellSingleQuotedString ([string]$OneShot)))

    if ($ContentOnly) {
        $contentBytes = [System.Text.UTF8Encoding]::new($false, $true).GetByteCount($supervisorScript)
        return [pscustomobject][ordered]@{
            SupervisorPath = [System.IO.Path]::GetFullPath($supervisorPath)
            Content = $supervisorScript
            Sha256 = (Get-SynapseSha256Hex -Text $supervisorScript).ToUpperInvariant()
            Length = [int64]$contentBytes
        }
    }

    $supervisorWrite = Write-SynapseAtomicUtf8TextFile `
        -Path $supervisorPath `
        -Content $supervisorScript `
        -Purpose 'daemon_supervisor_generation'
    Info "Daemon supervisor generation atomically persisted path=$($supervisorWrite.path) sha256=$($supervisorWrite.sha256) bytes=$($supervisorWrite.byte_length) encoding=$($supervisorWrite.encoding)"

    # The historical VBS wrapper was a resident process outside the kernel Job
    # accounting tree. The native bootstrap is now the only canonical task
    # action, so retire any exact-path wrapper after the supervisor bytes exist.
    if (Test-Path -LiteralPath $OutputPath) {
        Remove-Item -LiteralPath $OutputPath -Force
        if (Test-Path -LiteralPath $OutputPath) {
            Die "SYNAPSE_LEGACY_VBS_WRAPPER_RETIRE_FAILED path=$OutputPath remediation=the unbounded resident wrapper must be absent before registering the native bootstrap task"
        }
    }
}

function Ensure-SynapseDaemonJobReadbackType {
    if ('SynapseSetup.DaemonJobReadback' -as [type]) { return }

    Add-Type -Language CSharp -TypeDefinition @'
using System;
using System.ComponentModel;
using System.Runtime.InteropServices;

namespace SynapseSetup
{
    public sealed class DaemonJobReadback
    {
        public uint LimitFlags { get; set; }
        public ulong ProcessMemoryLimitBytes { get; set; }
        public ulong JobMemoryLimitBytes { get; set; }
        public ulong CurrentJobMemoryUsedBytes { get; set; }
        public ulong PeakJobMemoryUsedBytes { get; set; }
        public ulong[] ProcessIds { get; set; }
        public uint CpuRateControlFlags { get; set; }
        public uint CpuRate { get; set; }

        private const uint JOB_OBJECT_QUERY = 0x0004;
        private const int JobObjectBasicProcessIdList = 3;
        private const int JobObjectExtendedLimitInformation = 9;
        private const int JobObjectCpuRateControlInformation = 15;
        private const int JobObjectMemoryUsageInformation = 28;

        [StructLayout(LayoutKind.Sequential)]
        private struct IO_COUNTERS
        {
            public ulong ReadOperationCount;
            public ulong WriteOperationCount;
            public ulong OtherOperationCount;
            public ulong ReadTransferCount;
            public ulong WriteTransferCount;
            public ulong OtherTransferCount;
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct JOBOBJECT_BASIC_LIMIT_INFORMATION
        {
            public long PerProcessUserTimeLimit;
            public long PerJobUserTimeLimit;
            public uint LimitFlags;
            public UIntPtr MinimumWorkingSetSize;
            public UIntPtr MaximumWorkingSetSize;
            public uint ActiveProcessLimit;
            public UIntPtr Affinity;
            public uint PriorityClass;
            public uint SchedulingClass;
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct JOBOBJECT_EXTENDED_LIMIT_INFORMATION
        {
            public JOBOBJECT_BASIC_LIMIT_INFORMATION BasicLimitInformation;
            public IO_COUNTERS IoInfo;
            public UIntPtr ProcessMemoryLimit;
            public UIntPtr JobMemoryLimit;
            public UIntPtr PeakProcessMemoryUsed;
            public UIntPtr PeakJobMemoryUsed;
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct JOBOBJECT_MEMORY_USAGE_INFORMATION
        {
            public ulong JobMemory;
            public ulong PeakJobMemoryUsed;
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct JOBOBJECT_CPU_RATE_CONTROL_INFORMATION
        {
            public uint ControlFlags;
            public uint CpuRate;
        }

        [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
        private static extern IntPtr OpenJobObject(uint dwDesiredAccess, bool bInheritHandle, string lpName);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool QueryInformationJobObject(
            IntPtr hJob,
            int jobObjectInfoClass,
            IntPtr lpJobObjectInfo,
            uint cbJobObjectInfoLength,
            out uint lpReturnLength);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool CloseHandle(IntPtr hObject);

        public static DaemonJobReadback Query(string jobName)
        {
            if (String.IsNullOrWhiteSpace(jobName))
            {
                throw new ArgumentException("SYNAPSE_DAEMON_JOB_READBACK_NAME_MISSING");
            }
            IntPtr job = OpenJobObject(JOB_OBJECT_QUERY, false, jobName);
            if (job == IntPtr.Zero)
            {
                throw new Win32Exception(Marshal.GetLastWin32Error(), "SYNAPSE_DAEMON_JOB_OPEN_FAILED job_name=" + jobName);
            }
            try
            {
                DaemonJobReadback result = new DaemonJobReadback();
                ulong extendedPeakJobMemoryUsedBytes = 0;
                int limitSize = Marshal.SizeOf(typeof(JOBOBJECT_EXTENDED_LIMIT_INFORMATION));
                IntPtr limitPointer = Marshal.AllocHGlobal(limitSize);
                try
                {
                    uint returned;
                    if (!QueryInformationJobObject(job, JobObjectExtendedLimitInformation, limitPointer, (uint)limitSize, out returned))
                    {
                        throw new Win32Exception(Marshal.GetLastWin32Error(), "SYNAPSE_DAEMON_JOB_LIMIT_QUERY_FAILED job_name=" + jobName);
                    }
                    if (returned != (uint)limitSize)
                    {
                        throw new InvalidOperationException(
                            "SYNAPSE_DAEMON_JOB_LIMIT_QUERY_SIZE_MISMATCH job_name=" + jobName +
                            " expected=" + limitSize + " actual=" + returned);
                    }
                    JOBOBJECT_EXTENDED_LIMIT_INFORMATION limits =
                        (JOBOBJECT_EXTENDED_LIMIT_INFORMATION)Marshal.PtrToStructure(limitPointer, typeof(JOBOBJECT_EXTENDED_LIMIT_INFORMATION));
                    result.LimitFlags = limits.BasicLimitInformation.LimitFlags;
                    result.ProcessMemoryLimitBytes = limits.ProcessMemoryLimit.ToUInt64();
                    result.JobMemoryLimitBytes = limits.JobMemoryLimit.ToUInt64();
                    extendedPeakJobMemoryUsedBytes = limits.PeakJobMemoryUsed.ToUInt64();
                }
                finally
                {
                    Marshal.FreeHGlobal(limitPointer);
                }

                int usageSize = Marshal.SizeOf(typeof(JOBOBJECT_MEMORY_USAGE_INFORMATION));
                IntPtr usagePointer = Marshal.AllocHGlobal(usageSize);
                try
                {
                    uint returned;
                    if (!QueryInformationJobObject(job, JobObjectMemoryUsageInformation, usagePointer, (uint)usageSize, out returned))
                    {
                        throw new Win32Exception(Marshal.GetLastWin32Error(), "SYNAPSE_DAEMON_JOB_MEMORY_QUERY_FAILED job_name=" + jobName);
                    }
                    if (returned != (uint)usageSize)
                    {
                        throw new InvalidOperationException(
                            "SYNAPSE_DAEMON_JOB_MEMORY_QUERY_SIZE_MISMATCH job_name=" + jobName +
                            " expected=" + usageSize + " actual=" + returned);
                    }
                    JOBOBJECT_MEMORY_USAGE_INFORMATION usage =
                        (JOBOBJECT_MEMORY_USAGE_INFORMATION)Marshal.PtrToStructure(usagePointer, typeof(JOBOBJECT_MEMORY_USAGE_INFORMATION));
                    if (usage.PeakJobMemoryUsed < extendedPeakJobMemoryUsedBytes)
                    {
                        throw new InvalidOperationException(
                            "SYNAPSE_DAEMON_JOB_MEMORY_PEAK_REGRESSION job_name=" + jobName +
                            " extended_peak_earlier=" + extendedPeakJobMemoryUsedBytes +
                            " memory_usage_peak=" + usage.PeakJobMemoryUsed);
                    }
                    if (usage.PeakJobMemoryUsed < usage.JobMemory)
                    {
                        throw new InvalidOperationException(
                            "SYNAPSE_DAEMON_JOB_MEMORY_CURRENT_EXCEEDS_PEAK job_name=" + jobName +
                            " current=" + usage.JobMemory + " peak=" + usage.PeakJobMemoryUsed);
                    }
                    result.CurrentJobMemoryUsedBytes = usage.JobMemory;
                    result.PeakJobMemoryUsedBytes = usage.PeakJobMemoryUsed;
                }
                finally
                {
                    Marshal.FreeHGlobal(usagePointer);
                }

                int cpuSize = Marshal.SizeOf(typeof(JOBOBJECT_CPU_RATE_CONTROL_INFORMATION));
                IntPtr cpuPointer = Marshal.AllocHGlobal(cpuSize);
                try
                {
                    uint returned;
                    if (!QueryInformationJobObject(job, JobObjectCpuRateControlInformation, cpuPointer, (uint)cpuSize, out returned))
                    {
                        throw new Win32Exception(Marshal.GetLastWin32Error(), "SYNAPSE_DAEMON_JOB_CPU_RATE_QUERY_FAILED job_name=" + jobName);
                    }
                    if (returned != (uint)cpuSize)
                    {
                        throw new InvalidOperationException(
                            "SYNAPSE_DAEMON_JOB_CPU_RATE_QUERY_SIZE_MISMATCH job_name=" + jobName +
                            " expected=" + cpuSize + " actual=" + returned);
                    }
                    JOBOBJECT_CPU_RATE_CONTROL_INFORMATION cpu =
                        (JOBOBJECT_CPU_RATE_CONTROL_INFORMATION)Marshal.PtrToStructure(cpuPointer, typeof(JOBOBJECT_CPU_RATE_CONTROL_INFORMATION));
                    result.CpuRateControlFlags = cpu.ControlFlags;
                    result.CpuRate = cpu.CpuRate;
                }
                finally
                {
                    Marshal.FreeHGlobal(cpuPointer);
                }

                const int processBufferSize = 65536;
                IntPtr processPointer = Marshal.AllocHGlobal(processBufferSize);
                try
                {
                    uint returned;
                    if (!QueryInformationJobObject(job, JobObjectBasicProcessIdList, processPointer, processBufferSize, out returned))
                    {
                        throw new Win32Exception(Marshal.GetLastWin32Error(), "SYNAPSE_DAEMON_JOB_PROCESS_QUERY_FAILED job_name=" + jobName);
                    }
                    uint count = unchecked((uint)Marshal.ReadInt32(processPointer, sizeof(uint)));
                    ulong[] processIds = new ulong[checked((int)count)];
                    for (uint index = 0; index < count; index++)
                    {
                        IntPtr entry = IntPtr.Add(processPointer, (2 * sizeof(uint)) + checked((int)index * IntPtr.Size));
                        processIds[index] = IntPtr.Size == 8
                            ? unchecked((ulong)Marshal.ReadInt64(entry))
                            : unchecked((uint)Marshal.ReadInt32(entry));
                    }
                    result.ProcessIds = processIds;
                }
                finally
                {
                    Marshal.FreeHGlobal(processPointer);
                }
                return result;
            }
            finally
            {
                CloseHandle(job);
            }
        }
    }

    public sealed class BrokerDecommissionJobLease : IDisposable
    {
        private const uint JOB_OBJECT_QUERY = 0x0004;
        private const uint SYNCHRONIZE = 0x00100000;
        private const uint OWNER_SECURITY_INFORMATION = 0x00000001;
        private const uint DACL_SECURITY_INFORMATION = 0x00000004;
        private const uint ERROR_FILE_NOT_FOUND = 2;
        private const uint ERROR_MORE_DATA = 234;
        private const int SE_KERNEL_OBJECT = 6;
        private const int JobObjectBasicProcessIdList = 3;
        private const int JobObjectBasicUIRestrictions = 4;
        private const int JobObjectExtendedLimitInformation = 9;
        private const int JobObjectCpuRateControlInformation = 15;
        private const int JobObjectMemoryUsageInformation = 28;
        private const uint EXPECTED_LIMIT_FLAGS = 0x00002300;
        private const uint EXPECTED_CPU_FLAGS = 0x00000005;
        private const uint EXPECTED_CPU_RATE = 2500;
        private const ulong EXPECTED_MEMORY_LIMIT = 6699999232;

        [StructLayout(LayoutKind.Sequential)] private struct IO_COUNTERS { public ulong ReadOperationCount, WriteOperationCount, OtherOperationCount, ReadTransferCount, WriteTransferCount, OtherTransferCount; }
        [StructLayout(LayoutKind.Sequential)] private struct JOBOBJECT_BASIC_LIMIT_INFORMATION { public long PerProcessUserTimeLimit, PerJobUserTimeLimit; public uint LimitFlags; public UIntPtr MinimumWorkingSetSize, MaximumWorkingSetSize; public uint ActiveProcessLimit; public UIntPtr Affinity; public uint PriorityClass, SchedulingClass; }
        [StructLayout(LayoutKind.Sequential)] private struct JOBOBJECT_EXTENDED_LIMIT_INFORMATION { public JOBOBJECT_BASIC_LIMIT_INFORMATION BasicLimitInformation; public IO_COUNTERS IoInfo; public UIntPtr ProcessMemoryLimit, JobMemoryLimit, PeakProcessMemoryUsed, PeakJobMemoryUsed; }
        [StructLayout(LayoutKind.Sequential)] private struct JOBOBJECT_CPU_RATE_CONTROL_INFORMATION { public uint ControlFlags, CpuRate; }
        [StructLayout(LayoutKind.Sequential)] private struct JOBOBJECT_MEMORY_USAGE_INFORMATION { public ulong JobMemory, PeakJobMemoryUsed; }

        [DllImport("kernel32.dll", SetLastError=true, CharSet=CharSet.Unicode)] private static extern IntPtr OpenJobObject(uint access, [MarshalAs(UnmanagedType.Bool)] bool inherit, string name);
        [DllImport("kernel32.dll", SetLastError=true)] private static extern bool QueryInformationJobObject(IntPtr job, int informationClass, IntPtr information, uint size, out uint returned);
        [DllImport("kernel32.dll", SetLastError=true)] private static extern bool TerminateJobObject(IntPtr job, uint exitCode);
        [DllImport("advapi32.dll", SetLastError=true)] private static extern uint GetSecurityInfo(IntPtr handle, int objectType, uint securityInfo, out IntPtr owner, out IntPtr group, out IntPtr dacl, out IntPtr sacl, out IntPtr descriptor);
        [DllImport("advapi32.dll", SetLastError=true, CharSet=CharSet.Unicode)] private static extern bool ConvertSecurityDescriptorToStringSecurityDescriptorW(IntPtr descriptor, uint revision, uint securityInfo, out IntPtr value, out uint length);
        [DllImport("kernel32.dll", SetLastError=true)] private static extern bool CloseHandle(IntPtr handle);
        [DllImport("kernel32.dll")] private static extern IntPtr LocalFree(IntPtr value);

        private IntPtr handle = IntPtr.Zero;
        private bool disposed;
        public string JobName { get; private set; }
        public string SecurityDescriptorSddl { get; private set; }
        private BrokerDecommissionJobLease() { }

        private static void CloseChecked(ref IntPtr value, string context)
        {
            if (value == IntPtr.Zero) return;
            IntPtr owned = value;
            if (!CloseHandle(owned))
            {
                int error = Marshal.GetLastWin32Error();
                value = IntPtr.Zero;
                Environment.FailFast("SYNAPSE_BROKER_DECOMMISSION_JOB_HANDLE_CLOSE_UNPROVEN context=" + context, new Win32Exception(error));
            }
            value = IntPtr.Zero;
        }

        private static string ReadSecuritySddl(IntPtr job, string context)
        {
            IntPtr owner, group, dacl, sacl, descriptor;
            uint result = GetSecurityInfo(job, SE_KERNEL_OBJECT, OWNER_SECURITY_INFORMATION | DACL_SECURITY_INFORMATION, out owner, out group, out dacl, out sacl, out descriptor);
            if (result != 0) throw new Win32Exception(unchecked((int)result), "SYNAPSE_BROKER_DECOMMISSION_JOB_SECURITY_READ_FAILED context=" + context);
            IntPtr text = IntPtr.Zero;
            try
            {
                uint length;
                if (!ConvertSecurityDescriptorToStringSecurityDescriptorW(descriptor, 1, OWNER_SECURITY_INFORMATION | DACL_SECURITY_INFORMATION, out text, out length)) throw new Win32Exception(Marshal.GetLastWin32Error(), "SYNAPSE_BROKER_DECOMMISSION_JOB_SECURITY_RENDER_FAILED context=" + context);
                return Marshal.PtrToStringUni(text);
            }
            finally { if (text != IntPtr.Zero) LocalFree(text); if (descriptor != IntPtr.Zero) LocalFree(descriptor); }
        }

        private void QueryFixed(int cls, IntPtr pointer, uint size, string context)
        {
            uint returned;
            if (!QueryInformationJobObject(handle, cls, pointer, size, out returned)) throw new Win32Exception(Marshal.GetLastWin32Error(), "SYNAPSE_BROKER_DECOMMISSION_JOB_QUERY_FAILED context=" + context + " class=" + cls);
            if (returned != size) throw new InvalidOperationException("SYNAPSE_BROKER_DECOMMISSION_JOB_QUERY_SIZE_MISMATCH context=" + context + " class=" + cls + " expected=" + size + " actual=" + returned);
        }

        private ulong[] ReadProcessIdsOnce(string context)
        {
            const int maximum = 4;
            int size = checked((2 * sizeof(uint)) + (maximum * IntPtr.Size));
            IntPtr buffer = Marshal.AllocHGlobal(size);
            try
            {
                Marshal.Copy(new byte[size], 0, buffer, size);
                uint returned;
                if (!QueryInformationJobObject(handle, JobObjectBasicProcessIdList, buffer, (uint)size, out returned))
                {
                    uint error = unchecked((uint)Marshal.GetLastWin32Error());
                    if (error == ERROR_MORE_DATA) throw new InvalidOperationException("SYNAPSE_BROKER_DECOMMISSION_JOB_PROCESS_BOUND_EXCEEDED context=" + context + " max=" + maximum);
                    throw new Win32Exception(unchecked((int)error), "SYNAPSE_BROKER_DECOMMISSION_JOB_PROCESS_QUERY_FAILED context=" + context);
                }
                uint assigned = unchecked((uint)Marshal.ReadInt32(buffer, 0));
                uint listed = unchecked((uint)Marshal.ReadInt32(buffer, sizeof(uint)));
                uint exact = checked((uint)((2 * sizeof(uint)) + checked((int)listed * IntPtr.Size)));
                if (assigned != listed || listed > maximum || returned != exact) throw new InvalidOperationException("SYNAPSE_BROKER_DECOMMISSION_JOB_PROCESS_CARDINALITY_INVALID context=" + context + " assigned=" + assigned + " listed=" + listed + " returned=" + returned);
                ulong[] ids = new ulong[listed];
                for (uint index = 0; index < listed; index++)
                {
                    long raw = Marshal.ReadIntPtr(buffer, (2 * sizeof(uint)) + checked((int)index * IntPtr.Size)).ToInt64();
                    if (raw <= 0 || unchecked((ulong)raw) > UInt32.MaxValue) throw new InvalidOperationException("SYNAPSE_BROKER_DECOMMISSION_JOB_PROCESS_ID_INVALID context=" + context + " raw=" + raw);
                    ids[index] = unchecked((ulong)raw);
                }
                Array.Sort(ids);
                for (int index = 1; index < ids.Length; index++) if (ids[index] == ids[index - 1]) throw new InvalidOperationException("SYNAPSE_BROKER_DECOMMISSION_JOB_PROCESS_ID_DUPLICATE context=" + context);
                return ids;
            }
            finally { Marshal.FreeHGlobal(buffer); }
        }

        private ulong[] ReadStableProcessIds(string context)
        {
            ulong[] first = ReadProcessIdsOnce(context + "_first");
            System.Threading.Thread.Sleep(25);
            ulong[] second = ReadProcessIdsOnce(context + "_second");
            if (first.Length != second.Length) throw new InvalidOperationException("SYNAPSE_BROKER_DECOMMISSION_JOB_PROCESS_LIST_UNSTABLE context=" + context);
            for (int index = 0; index < first.Length; index++) if (first[index] != second[index]) throw new InvalidOperationException("SYNAPSE_BROKER_DECOMMISSION_JOB_PROCESS_LIST_UNSTABLE context=" + context);
            return second;
        }

        private bool allowHistoricalPeak;

        private void RequireLimits(string context)
        {
            int limitSize = Marshal.SizeOf(typeof(JOBOBJECT_EXTENDED_LIMIT_INFORMATION));
            int cpuSize = Marshal.SizeOf(typeof(JOBOBJECT_CPU_RATE_CONTROL_INFORMATION));
            int memorySize = Marshal.SizeOf(typeof(JOBOBJECT_MEMORY_USAGE_INFORMATION));
            IntPtr limit = Marshal.AllocHGlobal(limitSize), cpu = Marshal.AllocHGlobal(cpuSize), ui = Marshal.AllocHGlobal(sizeof(uint)), memory = Marshal.AllocHGlobal(memorySize);
            try
            {
                QueryFixed(JobObjectExtendedLimitInformation, limit, (uint)limitSize, context + "_limits");
                QueryFixed(JobObjectCpuRateControlInformation, cpu, (uint)cpuSize, context + "_cpu");
                QueryFixed(JobObjectBasicUIRestrictions, ui, sizeof(uint), context + "_ui");
                QueryFixed(JobObjectMemoryUsageInformation, memory, (uint)memorySize, context + "_memory");
                JOBOBJECT_EXTENDED_LIMIT_INFORMATION limits = (JOBOBJECT_EXTENDED_LIMIT_INFORMATION)Marshal.PtrToStructure(limit, typeof(JOBOBJECT_EXTENDED_LIMIT_INFORMATION));
                JOBOBJECT_CPU_RATE_CONTROL_INFORMATION rate = (JOBOBJECT_CPU_RATE_CONTROL_INFORMATION)Marshal.PtrToStructure(cpu, typeof(JOBOBJECT_CPU_RATE_CONTROL_INFORMATION));
                JOBOBJECT_MEMORY_USAGE_INFORMATION usage = (JOBOBJECT_MEMORY_USAGE_INFORMATION)Marshal.PtrToStructure(memory, typeof(JOBOBJECT_MEMORY_USAGE_INFORMATION));
                JOBOBJECT_BASIC_LIMIT_INFORMATION basic = limits.BasicLimitInformation;
                uint uiFlags = unchecked((uint)Marshal.ReadInt32(ui));
                if (basic.LimitFlags != EXPECTED_LIMIT_FLAGS || basic.PerProcessUserTimeLimit != 0 || basic.PerJobUserTimeLimit != 0 || basic.MinimumWorkingSetSize != UIntPtr.Zero || basic.MaximumWorkingSetSize != UIntPtr.Zero || basic.ActiveProcessLimit != 0 || basic.Affinity != UIntPtr.Zero || basic.PriorityClass != 32 || basic.SchedulingClass != 5 || limits.ProcessMemoryLimit.ToUInt64() != EXPECTED_MEMORY_LIMIT || limits.JobMemoryLimit.ToUInt64() != EXPECTED_MEMORY_LIMIT || usage.JobMemory > EXPECTED_MEMORY_LIMIT || (!allowHistoricalPeak && usage.PeakJobMemoryUsed > EXPECTED_MEMORY_LIMIT) || usage.PeakJobMemoryUsed < usage.JobMemory || rate.ControlFlags != EXPECTED_CPU_FLAGS || rate.CpuRate != EXPECTED_CPU_RATE || uiFlags != 0)
                    throw new InvalidOperationException("SYNAPSE_BROKER_DECOMMISSION_JOB_CONTRACT_MISMATCH context=" + context +
                        " limit_flags=0x" + basic.LimitFlags.ToString("X8") +
                        " process_limit=" + limits.ProcessMemoryLimit.ToUInt64() +
                        " job_limit=" + limits.JobMemoryLimit.ToUInt64() +
                        " current_job_memory=" + usage.JobMemory +
                        " peak_job_memory=" + usage.PeakJobMemoryUsed +
                        " allow_historical_peak=" + allowHistoricalPeak +
                        " cpu_flags=0x" + rate.ControlFlags.ToString("X8") +
                        " cpu_rate=" + rate.CpuRate + " ui_flags=0x" + uiFlags.ToString("X8") +
                        " active_process_limit=" + basic.ActiveProcessLimit + " affinity=" + basic.Affinity.ToUInt64() +
                        " priority=" + basic.PriorityClass + " scheduling=" + basic.SchedulingClass);
            }
            finally { Marshal.FreeHGlobal(limit); Marshal.FreeHGlobal(cpu); Marshal.FreeHGlobal(ui); Marshal.FreeHGlobal(memory); }
        }

        private static BrokerDecommissionJobLease OpenCoreOrNull(string name, string expectedCapabilitySha256, uint expectedOuterPid, string expectedSecuritySddl, ulong[] expectedProcessIds, bool requireExact, bool allowHistoricalPeak, string context)
        {
            string capability = (expectedCapabilitySha256 ?? String.Empty).ToUpperInvariant();
            if (capability.Length != 64) throw new ArgumentException("SYNAPSE_BROKER_DECOMMISSION_JOB_CAPABILITY_INVALID context=" + context);
            for (int index = 0; index < capability.Length; index++) { char c = capability[index]; if (!((c >= '0' && c <= '9') || (c >= 'A' && c <= 'F'))) throw new ArgumentException("SYNAPSE_BROKER_DECOMMISSION_JOB_CAPABILITY_INVALID context=" + context); }
            if (expectedOuterPid == 0 || String.IsNullOrWhiteSpace(expectedSecuritySddl) || expectedProcessIds == null) throw new ArgumentException("SYNAPSE_BROKER_DECOMMISSION_JOB_EXPECTATION_INVALID context=" + context);
            string expectedName = @"Local\SynapseOwned-" + capability + "-" + expectedOuterPid;
            if (!String.Equals(name, expectedName, StringComparison.Ordinal)) throw new ArgumentException("SYNAPSE_BROKER_DECOMMISSION_JOB_NAME_INVALID context=" + context + " expected=" + expectedName + " actual=" + name);
            // The frozen bootstrap deliberately grants the owner only QUERY and
            // SYNCHRONIZE on this Job.  Decommission terminates the two exact
            // processes through their separately retained terminate handles,
            // then uses this retained Job handle solely to prove membership
            // drains to empty.  Never request rights the immutable Job DACL did
            // not grant and never fall back to a PID-only kill.
            IntPtr opened = OpenJobObject(JOB_OBJECT_QUERY | SYNCHRONIZE, false, name);
            if (opened == IntPtr.Zero) { uint error = unchecked((uint)Marshal.GetLastWin32Error()); if (error == ERROR_FILE_NOT_FOUND) return null; throw new Win32Exception(unchecked((int)error), "SYNAPSE_BROKER_DECOMMISSION_JOB_OPEN_FAILED context=" + context + " name=" + name); }
            BrokerDecommissionJobLease result = new BrokerDecommissionJobLease(); result.handle = opened; result.JobName = name; result.allowHistoricalPeak = allowHistoricalPeak;
            try
            {
                result.SecurityDescriptorSddl = expectedSecuritySddl;
                if (requireExact) result.RequireExact(expectedProcessIds, context + "_open");
                else result.RequireSubset(expectedProcessIds, context + "_open");
                return result;
            }
            catch (Exception primary) { try { result.Dispose(); } catch (Exception cleanup) { Environment.FailFast("SYNAPSE_BROKER_DECOMMISSION_JOB_OPEN_CLEANUP_UNPROVEN context=" + context + " primary=[" + primary.Message + "]", cleanup); } throw; }
        }

        public static BrokerDecommissionJobLease OpenOrNull(string name, string expectedCapabilitySha256, uint expectedOuterPid, string expectedSecuritySddl, ulong[] expectedProcessIds, bool allowHistoricalPeak, string context)
        {
            return OpenCoreOrNull(name, expectedCapabilitySha256, expectedOuterPid, expectedSecuritySddl, expectedProcessIds, true, allowHistoricalPeak, context);
        }

        public static BrokerDecommissionJobLease OpenSubsetOrNull(string name, string expectedCapabilitySha256, uint expectedOuterPid, string expectedSecuritySddl, ulong[] expectedProcessIds, bool allowHistoricalPeak, string context)
        {
            return OpenCoreOrNull(name, expectedCapabilitySha256, expectedOuterPid, expectedSecuritySddl, expectedProcessIds, false, allowHistoricalPeak, context);
        }

        public void RequireExact(ulong[] expectedProcessIds, string context)
        {
            if (disposed || handle == IntPtr.Zero) throw new ObjectDisposedException("BrokerDecommissionJobLease");
            RequireLimits(context);
            if (expectedProcessIds == null) throw new ArgumentNullException("expectedProcessIds");
            ulong[] wanted = (ulong[])expectedProcessIds.Clone(); Array.Sort(wanted);
            if (wanted.Length < 2 || wanted.Length > 4) throw new ArgumentException("SYNAPSE_BROKER_DECOMMISSION_JOB_EXPECTED_MEMBERS_INVALID context=" + context);
            for (int index = 0; index < wanted.Length; index++) if (wanted[index] == 0 || wanted[index] > UInt32.MaxValue || (index > 0 && wanted[index] == wanted[index - 1])) throw new ArgumentException("SYNAPSE_BROKER_DECOMMISSION_JOB_EXPECTED_MEMBERS_INVALID context=" + context);
            ulong[] actual = ReadStableProcessIds(context + "_members");
            if (actual.Length != wanted.Length) throw new InvalidOperationException("SYNAPSE_BROKER_DECOMMISSION_JOB_MEMBERS_MISMATCH context=" + context + " expected=" + String.Join(",", wanted) + " actual=" + String.Join(",", actual));
            for (int index = 0; index < actual.Length; index++) if (actual[index] != wanted[index]) throw new InvalidOperationException("SYNAPSE_BROKER_DECOMMISSION_JOB_MEMBERS_MISMATCH context=" + context + " expected=" + String.Join(",", wanted) + " actual=" + String.Join(",", actual));
        }

        public void RequireSubset(ulong[] expectedProcessIds, string context)
        {
            if (disposed || handle == IntPtr.Zero) throw new ObjectDisposedException("BrokerDecommissionJobLease");
            if (expectedProcessIds == null) throw new ArgumentNullException("expectedProcessIds");
            ulong[] expected = (ulong[])expectedProcessIds.Clone(); Array.Sort(expected);
            if (expected.Length < 2 || expected.Length > 4) throw new ArgumentException("SYNAPSE_BROKER_DECOMMISSION_JOB_EXPECTED_MEMBERS_INVALID context=" + context);
            for (int index = 0; index < expected.Length; index++) if (expected[index] == 0 || expected[index] > UInt32.MaxValue || (index > 0 && expected[index] == expected[index - 1])) throw new ArgumentException("SYNAPSE_BROKER_DECOMMISSION_JOB_EXPECTED_MEMBERS_INVALID context=" + context);
            RequireLimits(context);
            ulong[] actual = ReadStableProcessIds(context + "_members");
            for (int index = 0; index < actual.Length; index++) if (!Contains(expected, actual[index])) throw new InvalidOperationException("SYNAPSE_BROKER_DECOMMISSION_JOB_REPLACEMENT_MEMBER_REFUSED context=" + context + " pid=" + actual[index]);
        }

        public ulong[] ReadSubset(ulong[] expectedProcessIds, string context)
        {
            if (disposed || handle == IntPtr.Zero) throw new ObjectDisposedException("BrokerDecommissionJobLease");
            if (expectedProcessIds == null) throw new ArgumentNullException("expectedProcessIds");
            ulong[] expected = (ulong[])expectedProcessIds.Clone(); Array.Sort(expected);
            if (expected.Length < 2 || expected.Length > 4) throw new ArgumentException("SYNAPSE_BROKER_DECOMMISSION_JOB_EXPECTED_MEMBERS_INVALID context=" + context);
            for (int index = 0; index < expected.Length; index++) if (expected[index] == 0 || expected[index] > UInt32.MaxValue || (index > 0 && expected[index] == expected[index - 1])) throw new ArgumentException("SYNAPSE_BROKER_DECOMMISSION_JOB_EXPECTED_MEMBERS_INVALID context=" + context);
            RequireLimits(context);
            ulong[] actual = ReadStableProcessIds(context + "_members");
            for (int index = 0; index < actual.Length; index++) if (!Contains(expected, actual[index])) throw new InvalidOperationException("SYNAPSE_BROKER_DECOMMISSION_JOB_REPLACEMENT_MEMBER_REFUSED context=" + context + " pid=" + actual[index]);
            return actual;
        }

        private static bool Contains(ulong[] values, ulong value)
        {
            for (int index = 0; index < values.Length; index++) if (values[index] == value) return true;
            return false;
        }

        public void ProveEmptyAfterProcessTermination(ulong[] expectedProcessIds, int timeoutMilliseconds, string context)
        {
            if (disposed || handle == IntPtr.Zero) throw new ObjectDisposedException("BrokerDecommissionJobLease");
            if (timeoutMilliseconds < 1) throw new ArgumentOutOfRangeException("timeoutMilliseconds");
            if (expectedProcessIds == null) throw new ArgumentNullException("expectedProcessIds");
            ulong[] expected = (ulong[])expectedProcessIds.Clone(); Array.Sort(expected);
            if (expected.Length < 2 || expected.Length > 4) throw new ArgumentException("SYNAPSE_BROKER_DECOMMISSION_JOB_EXPECTED_MEMBERS_INVALID context=" + context);
            for (int index = 0; index < expected.Length; index++) if (expected[index] == 0 || expected[index] > UInt32.MaxValue || (index > 0 && expected[index] == expected[index - 1])) throw new ArgumentException("SYNAPSE_BROKER_DECOMMISSION_JOB_EXPECTED_MEMBERS_INVALID context=" + context);
            System.Diagnostics.Stopwatch clock = System.Diagnostics.Stopwatch.StartNew();
            do
            {
                ulong[] ids = ReadProcessIdsOnce(context + "_drain");
                for (int index = 0; index < ids.Length; index++) if (!Contains(expected, ids[index])) throw new InvalidOperationException("SYNAPSE_BROKER_DECOMMISSION_JOB_REPLACEMENT_MEMBER_REFUSED context=" + context + " pid=" + ids[index]);
                if (ids.Length == 0) { System.Threading.Thread.Sleep(25); if (ReadProcessIdsOnce(context + "_drain_confirm").Length == 0) return; }
                if (clock.ElapsedMilliseconds >= timeoutMilliseconds) break;
                System.Threading.Thread.Sleep(50);
            } while (true);
            throw new TimeoutException("SYNAPSE_BROKER_DECOMMISSION_JOB_DRAIN_TIMEOUT context=" + context + " timeout_ms=" + timeoutMilliseconds);
        }

        public static void RequireNameAbsent(string name, string context)
        {
            if (String.IsNullOrWhiteSpace(name)) throw new ArgumentException("SYNAPSE_BROKER_DECOMMISSION_JOB_NAME_INVALID context=" + context);
            IntPtr opened = OpenJobObject(JOB_OBJECT_QUERY | SYNCHRONIZE, false, name);
            if (opened == IntPtr.Zero)
            {
                uint error = unchecked((uint)Marshal.GetLastWin32Error());
                if (error == ERROR_FILE_NOT_FOUND) return;
                throw new Win32Exception(unchecked((int)error), "SYNAPSE_BROKER_DECOMMISSION_JOB_ABSENCE_QUERY_FAILED context=" + context + " name=" + name);
            }
            try { throw new InvalidOperationException("SYNAPSE_BROKER_DECOMMISSION_JOB_STILL_PRESENT context=" + context + " name=" + name); }
            finally { CloseChecked(ref opened, "absence_" + context); }
        }

        public void Dispose() { if (disposed) return; CloseChecked(ref handle, "dispose_" + JobName); disposed = true; }
    }
}
'@
}

function Get-SynapseDaemonJobKernelReadback {
    param([Parameter(Mandatory=$true)][string]$JobName)

    Ensure-SynapseDaemonJobReadbackType
    try {
        return [SynapseSetup.DaemonJobReadback]::Query($JobName)
    } catch {
        throw "SYNAPSE_DAEMON_JOB_KERNEL_READBACK_FAILED job_name=$JobName error=$($_.Exception.Message) remediation=repair named Windows Job query access; mutable supervisor JSON alone is not accepted as proof of the hard resource boundary"
    }
}

function Ensure-SynapseSetupProcessJobType {
    if ('SynapseSetup.ProcessJob' -as [type]) { return }

    Add-Type -Language CSharp -TypeDefinition @'
using System;
using System.ComponentModel;
using System.Runtime.InteropServices;
using System.Text;

namespace SynapseSetup
{
    public static class ProcessJob
    {
        private const uint CREATE_SUSPENDED = 0x00000004;
        private const uint CREATE_NO_WINDOW = 0x08000000;
        private const uint JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE = 0x00002000;
        private const uint JOB_OBJECT_LIMIT_PROCESS_MEMORY = 0x00000100;
        private const uint JOB_OBJECT_LIMIT_JOB_MEMORY = 0x00000200;
        // Windows rounds Job memory limits down to the host page boundary.
        // Use the exact page-aligned value so Set/QueryInformationJobObject
        // readback is stable and the hard ceiling remains below 1 GB.
        // Shipping is a bounded one-time operation, not part of the daemon's
        // steady-state sub-1-GiB contract. One compiler job still needs enough
        // address-space commit to compile calyx-aster reliably on an 8-GiB PC.
        private const ulong BUILD_MEMORY_LIMIT_BYTES = 12884901888UL;
        private const int JobObjectExtendedLimitInformation = 9;
        private const int JobObjectBasicProcessIdList = 3;
        private const uint WAIT_OBJECT_0 = 0x00000000;
        private const uint WAIT_TIMEOUT = 0x00000102;
        private const uint WAIT_FAILED = 0xffffffff;
        private const uint WAIT_NOT_CALLED = 0xfffffffe;
        private const uint EXIT_TIMEOUT = 124;
        private const uint EXIT_ASSIGN_FAILED = 125;
        private const uint EXIT_RESUME_FAILED = 126;
        private const uint INFINITE = 0xffffffff;

        [StructLayout(LayoutKind.Sequential)]
        private struct IO_COUNTERS
        {
            public ulong ReadOperationCount;
            public ulong WriteOperationCount;
            public ulong OtherOperationCount;
            public ulong ReadTransferCount;
            public ulong WriteTransferCount;
            public ulong OtherTransferCount;
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct JOBOBJECT_BASIC_LIMIT_INFORMATION
        {
            public long PerProcessUserTimeLimit;
            public long PerJobUserTimeLimit;
            public uint LimitFlags;
            public UIntPtr MinimumWorkingSetSize;
            public UIntPtr MaximumWorkingSetSize;
            public uint ActiveProcessLimit;
            public UIntPtr Affinity;
            public uint PriorityClass;
            public uint SchedulingClass;
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct JOBOBJECT_EXTENDED_LIMIT_INFORMATION
        {
            public JOBOBJECT_BASIC_LIMIT_INFORMATION BasicLimitInformation;
            public IO_COUNTERS IoInfo;
            public UIntPtr ProcessMemoryLimit;
            public UIntPtr JobMemoryLimit;
            public UIntPtr PeakProcessMemoryUsed;
            public UIntPtr PeakJobMemoryUsed;
        }

        [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
        private struct STARTUPINFO
        {
            public uint cb;
            public string lpReserved;
            public string lpDesktop;
            public string lpTitle;
            public uint dwX;
            public uint dwY;
            public uint dwXSize;
            public uint dwYSize;
            public uint dwXCountChars;
            public uint dwYCountChars;
            public uint dwFillAttribute;
            public uint dwFlags;
            public ushort wShowWindow;
            public ushort cbReserved2;
            public IntPtr lpReserved2;
            public IntPtr hStdInput;
            public IntPtr hStdOutput;
            public IntPtr hStdError;
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct PROCESS_INFORMATION
        {
            public IntPtr hProcess;
            public IntPtr hThread;
            public uint dwProcessId;
            public uint dwThreadId;
        }

        [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
        private static extern IntPtr CreateJobObject(IntPtr lpJobAttributes, string lpName);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool SetInformationJobObject(
            IntPtr hJob,
            int jobObjectInfoClass,
            IntPtr lpJobObjectInfo,
            uint cbJobObjectInfoLength);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool QueryInformationJobObject(
            IntPtr hJob,
            int jobObjectInfoClass,
            IntPtr lpJobObjectInfo,
            uint cbJobObjectInfoLength,
            out uint lpReturnLength);

        [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
        private static extern bool CreateProcess(
            string lpApplicationName,
            StringBuilder lpCommandLine,
            IntPtr lpProcessAttributes,
            IntPtr lpThreadAttributes,
            bool bInheritHandles,
            uint dwCreationFlags,
            IntPtr lpEnvironment,
            string lpCurrentDirectory,
            ref STARTUPINFO lpStartupInfo,
            out PROCESS_INFORMATION lpProcessInformation);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool AssignProcessToJobObject(IntPtr hJob, IntPtr hProcess);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern uint ResumeThread(IntPtr hThread);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern uint WaitForSingleObject(IntPtr hHandle, uint dwMilliseconds);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool GetExitCodeProcess(IntPtr hProcess, out uint lpExitCode);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool TerminateJobObject(IntPtr hJob, uint uExitCode);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool TerminateProcess(IntPtr hProcess, uint uExitCode);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool CloseHandle(IntPtr hObject);

        public static int Run(
            string applicationName,
            string commandLine,
            string workingDirectory,
            uint timeoutMilliseconds,
            out string failure,
            out string diagnosticsJson)
        {
            failure = "";
            diagnosticsJson = "";
            string completionKind = "not_started";
            string waitKind = "not_waited";
            uint wait = WAIT_NOT_CALLED;
            uint exitCode = 0xffffffff;
            uint cleanupWait = WAIT_NOT_CALLED;
            uint childPid = 0;
            bool jobCreated = false;
            bool processCreated = false;
            bool assignedToJob = false;
            bool resumed = false;
            bool timedOut = false;
            bool terminateJobCalled = false;
            bool terminateJobOk = false;
            string terminateJobError = "";
            IntPtr job = IntPtr.Zero;
            IntPtr limitPointer = IntPtr.Zero;
            PROCESS_INFORMATION processInfo = new PROCESS_INFORMATION();
            uint[] activeJobProcessIds = new uint[0];
            string activeJobProcessQueryError = "";
            try
            {
                job = CreateJobObject(IntPtr.Zero, null);
                if (job == IntPtr.Zero)
                {
                    failure = "PROCESS_JOB_CREATE_FAILED: " + new Win32Exception(Marshal.GetLastWin32Error()).Message;
                    completionKind = "job_create_failed";
                    return 127;
                }
                jobCreated = true;

                JOBOBJECT_EXTENDED_LIMIT_INFORMATION limits = new JOBOBJECT_EXTENDED_LIMIT_INFORMATION();
                limits.BasicLimitInformation.LimitFlags =
                    JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE |
                    JOB_OBJECT_LIMIT_PROCESS_MEMORY |
                    JOB_OBJECT_LIMIT_JOB_MEMORY;
                limits.ProcessMemoryLimit = new UIntPtr(BUILD_MEMORY_LIMIT_BYTES);
                limits.JobMemoryLimit = new UIntPtr(BUILD_MEMORY_LIMIT_BYTES);
                int limitSize = Marshal.SizeOf(typeof(JOBOBJECT_EXTENDED_LIMIT_INFORMATION));
                limitPointer = Marshal.AllocHGlobal(limitSize);
                Marshal.StructureToPtr(limits, limitPointer, false);
                if (!SetInformationJobObject(job, JobObjectExtendedLimitInformation, limitPointer, (uint)limitSize))
                {
                    failure = "PROCESS_JOB_LIMIT_FAILED: " + new Win32Exception(Marshal.GetLastWin32Error()).Message;
                    completionKind = "job_limit_failed";
                    return 127;
                }
                uint limitReadbackBytes;
                if (!QueryInformationJobObject(
                        job,
                        JobObjectExtendedLimitInformation,
                        limitPointer,
                        (uint)limitSize,
                        out limitReadbackBytes) ||
                    limitReadbackBytes != (uint)limitSize)
                {
                    failure = "PROCESS_JOB_LIMIT_READBACK_FAILED: " +
                        new Win32Exception(Marshal.GetLastWin32Error()).Message;
                    completionKind = "job_limit_readback_failed";
                    return 127;
                }
                JOBOBJECT_EXTENDED_LIMIT_INFORMATION limitReadback =
                    (JOBOBJECT_EXTENDED_LIMIT_INFORMATION)Marshal.PtrToStructure(
                        limitPointer,
                        typeof(JOBOBJECT_EXTENDED_LIMIT_INFORMATION));
                if (limitReadback.BasicLimitInformation.LimitFlags != limits.BasicLimitInformation.LimitFlags ||
                    limitReadback.ProcessMemoryLimit.ToUInt64() != BUILD_MEMORY_LIMIT_BYTES ||
                    limitReadback.JobMemoryLimit.ToUInt64() != BUILD_MEMORY_LIMIT_BYTES)
                {
                    failure =
                        "PROCESS_JOB_LIMIT_READBACK_MISMATCH expected_flags=" + limits.BasicLimitInformation.LimitFlags +
                        " actual_flags=" + limitReadback.BasicLimitInformation.LimitFlags +
                        " expected_bytes=" + BUILD_MEMORY_LIMIT_BYTES +
                        " actual_process_bytes=" + limitReadback.ProcessMemoryLimit.ToUInt64() +
                        " actual_job_bytes=" + limitReadback.JobMemoryLimit.ToUInt64();
                    completionKind = "job_limit_readback_mismatch";
                    return 127;
                }

                STARTUPINFO startupInfo = new STARTUPINFO();
                startupInfo.cb = (uint)Marshal.SizeOf(typeof(STARTUPINFO));
                StringBuilder mutableCommandLine = new StringBuilder(commandLine);
                bool created = CreateProcess(
                    applicationName,
                    mutableCommandLine,
                    IntPtr.Zero,
                    IntPtr.Zero,
                    false,
                    CREATE_SUSPENDED | CREATE_NO_WINDOW,
                    IntPtr.Zero,
                    workingDirectory,
                    ref startupInfo,
                    out processInfo);
                if (!created)
                {
                    failure = "PROCESS_JOB_CREATE_PROCESS_FAILED: " + new Win32Exception(Marshal.GetLastWin32Error()).Message;
                    completionKind = "process_create_failed";
                    return 127;
                }
                processCreated = true;
                childPid = processInfo.dwProcessId;

                if (!AssignProcessToJobObject(job, processInfo.hProcess))
                {
                    failure = "PROCESS_JOB_ASSIGN_FAILED: " + new Win32Exception(Marshal.GetLastWin32Error()).Message;
                    completionKind = "job_assign_failed";
                    bool terminated = TerminateProcess(processInfo.hProcess, EXIT_ASSIGN_FAILED);
                    terminateJobCalled = false;
                    terminateJobOk = terminated;
                    if (!terminated)
                    {
                        terminateJobError = new Win32Exception(Marshal.GetLastWin32Error()).Message;
                    }
                    return (int)EXIT_ASSIGN_FAILED;
                }
                assignedToJob = true;

                if (ResumeThread(processInfo.hThread) == 0xffffffff)
                {
                    failure = "PROCESS_JOB_RESUME_FAILED: " + new Win32Exception(Marshal.GetLastWin32Error()).Message;
                    completionKind = "resume_failed";
                    terminateJobCalled = true;
                    terminateJobOk = TerminateJobObject(job, EXIT_RESUME_FAILED);
                    if (!terminateJobOk)
                    {
                        terminateJobError = new Win32Exception(Marshal.GetLastWin32Error()).Message;
                    }
                    return (int)EXIT_RESUME_FAILED;
                }
                resumed = true;

                wait = WaitForSingleObject(
                    processInfo.hProcess,
                    timeoutMilliseconds == 0 ? INFINITE : timeoutMilliseconds);
                waitKind = WaitKind(wait);
                if (wait == WAIT_TIMEOUT)
                {
                    timedOut = true;
                    completionKind = "timeout";
                    terminateJobCalled = true;
                    terminateJobOk = TerminateJobObject(job, EXIT_TIMEOUT);
                    if (!terminateJobOk)
                    {
                        terminateJobError = new Win32Exception(Marshal.GetLastWin32Error()).Message;
                    }
                    cleanupWait = WaitForSingleObject(processInfo.hProcess, 15000);
                    failure = "PROCESS_JOB_TIMEOUT: child process tree exceeded timeout_ms=" + timeoutMilliseconds;
                    return (int)EXIT_TIMEOUT;
                }
                if (wait == WAIT_FAILED)
                {
                    failure = "PROCESS_JOB_WAIT_FAILED: " + new Win32Exception(Marshal.GetLastWin32Error()).Message;
                    completionKind = "wait_failed";
                    terminateJobCalled = true;
                    terminateJobOk = TerminateJobObject(job, 127);
                    if (!terminateJobOk)
                    {
                        terminateJobError = new Win32Exception(Marshal.GetLastWin32Error()).Message;
                    }
                    return 127;
                }
                if (wait != WAIT_OBJECT_0)
                {
                    failure = "PROCESS_JOB_WAIT_UNEXPECTED: wait_result=" + wait;
                    completionKind = "wait_unexpected";
                    terminateJobCalled = true;
                    terminateJobOk = TerminateJobObject(job, 127);
                    if (!terminateJobOk)
                    {
                        terminateJobError = new Win32Exception(Marshal.GetLastWin32Error()).Message;
                    }
                    return 127;
                }

                if (!GetExitCodeProcess(processInfo.hProcess, out exitCode))
                {
                    failure = "PROCESS_JOB_EXIT_CODE_FAILED: " + new Win32Exception(Marshal.GetLastWin32Error()).Message;
                    completionKind = "exit_code_failed";
                    return 127;
                }
                completionKind = "child_exit";
                return unchecked((int)exitCode);
            }
            finally
            {
                if (job != IntPtr.Zero)
                {
                    try
                    {
                        activeJobProcessIds = ActiveProcessIds(job);
                    }
                    catch (Exception error)
                    {
                        activeJobProcessQueryError = error.Message;
                    }
                }
                diagnosticsJson = BuildDiagnosticsJson(
                    applicationName,
                    commandLine,
                    workingDirectory,
                    timeoutMilliseconds,
                    jobCreated,
                    processCreated,
                    childPid,
                    assignedToJob,
                    resumed,
                    wait,
                    waitKind,
                    timedOut,
                    exitCode,
                    completionKind,
                    terminateJobCalled,
                    terminateJobOk,
                    terminateJobError,
                    cleanupWait,
                    activeJobProcessIds,
                    activeJobProcessQueryError,
                    failure);
                if (limitPointer != IntPtr.Zero)
                {
                    Marshal.FreeHGlobal(limitPointer);
                }
                if (processInfo.hThread != IntPtr.Zero)
                {
                    CloseHandle(processInfo.hThread);
                }
                if (processInfo.hProcess != IntPtr.Zero)
                {
                    CloseHandle(processInfo.hProcess);
                }
                if (job != IntPtr.Zero)
                {
                    CloseHandle(job);
                }
            }
        }

        private static string WaitKind(uint wait)
        {
            if (wait == WAIT_NOT_CALLED) return "not_called";
            if (wait == WAIT_OBJECT_0) return "WAIT_OBJECT_0";
            if (wait == WAIT_TIMEOUT) return "WAIT_TIMEOUT";
            if (wait == WAIT_FAILED) return "WAIT_FAILED";
            return "unexpected_" + wait.ToString();
        }

        private static uint[] ActiveProcessIds(IntPtr job)
        {
            const int capacity = 4096;
            int headerBytes = sizeof(uint) * 2;
            int bufferBytes = headerBytes + (IntPtr.Size * capacity);
            IntPtr buffer = Marshal.AllocHGlobal(bufferBytes);
            try
            {
                uint returned;
                if (!QueryInformationJobObject(
                    job,
                    JobObjectBasicProcessIdList,
                    buffer,
                    (uint)bufferBytes,
                    out returned))
                {
                    throw new Win32Exception(Marshal.GetLastWin32Error());
                }
                uint count = unchecked((uint)Marshal.ReadInt32(buffer, sizeof(uint)));
                if (count > capacity)
                {
                    throw new InvalidOperationException("job process list exceeded diagnostic capacity");
                }
                uint[] processIds = new uint[count];
                for (int index = 0; index < count; index++)
                {
                    IntPtr offset = IntPtr.Add(buffer, headerBytes + (index * IntPtr.Size));
                    processIds[index] = unchecked((uint)(IntPtr.Size == 8
                        ? Marshal.ReadInt64(offset)
                        : Marshal.ReadInt32(offset)));
                }
                return processIds;
            }
            finally
            {
                Marshal.FreeHGlobal(buffer);
            }
        }

        private static string JsonEscape(string value)
        {
            if (value == null) return "";
            StringBuilder escaped = new StringBuilder();
            foreach (char c in value)
            {
                switch (c)
                {
                    case '\\': escaped.Append("\\\\"); break;
                    case '"': escaped.Append("\\\""); break;
                    case '\b': escaped.Append("\\b"); break;
                    case '\f': escaped.Append("\\f"); break;
                    case '\n': escaped.Append("\\n"); break;
                    case '\r': escaped.Append("\\r"); break;
                    case '\t': escaped.Append("\\t"); break;
                    default:
                        if (c < 0x20)
                        {
                            escaped.Append("\\u");
                            escaped.Append(((int)c).ToString("x4"));
                        }
                        else
                        {
                            escaped.Append(c);
                        }
                        break;
                }
            }
            return escaped.ToString();
        }

        private static string BuildDiagnosticsJson(
            string applicationName,
            string commandLine,
            string workingDirectory,
            uint timeoutMilliseconds,
            bool jobCreated,
            bool processCreated,
            uint childPid,
            bool assignedToJob,
            bool resumed,
            uint waitResult,
            string waitKind,
            bool timedOut,
            uint exitCode,
            string completionKind,
            bool terminateJobCalled,
            bool terminateJobOk,
            string terminateJobError,
            uint cleanupWait,
            uint[] activeJobProcessIds,
            string activeJobProcessQueryError,
            string failure)
        {
            int signedExitCode = unchecked((int)exitCode);
            StringBuilder json = new StringBuilder();
            json.Append("{");
            json.Append("\"schema\":\"synapse_process_job_result/v2\"");
            json.Append(",\"application_name\":\"").Append(JsonEscape(applicationName)).Append("\"");
            json.Append(",\"command_line\":\"").Append(JsonEscape(commandLine)).Append("\"");
            json.Append(",\"working_directory\":\"").Append(JsonEscape(workingDirectory)).Append("\"");
            json.Append(",\"timeout_ms\":").Append(timeoutMilliseconds);
            json.Append(",\"job_created\":").Append(jobCreated ? "true" : "false");
            json.Append(",\"job_limit_flags\":")
                .Append(JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE |
                        JOB_OBJECT_LIMIT_PROCESS_MEMORY |
                        JOB_OBJECT_LIMIT_JOB_MEMORY);
            json.Append(",\"process_memory_limit_bytes\":").Append(BUILD_MEMORY_LIMIT_BYTES);
            json.Append(",\"job_memory_limit_bytes\":").Append(BUILD_MEMORY_LIMIT_BYTES);
            json.Append(",\"process_created\":").Append(processCreated ? "true" : "false");
            json.Append(",\"child_pid\":").Append(childPid == 0 ? "null" : childPid.ToString());
            json.Append(",\"assigned_to_job\":").Append(assignedToJob ? "true" : "false");
            json.Append(",\"resumed\":").Append(resumed ? "true" : "false");
            json.Append(",\"wait_result\":").Append(waitResult);
            json.Append(",\"wait_kind\":\"").Append(JsonEscape(waitKind)).Append("\"");
            json.Append(",\"timed_out\":").Append(timedOut ? "true" : "false");
            json.Append(",\"exit_code_unsigned\":").Append(exitCode);
            json.Append(",\"exit_code_signed\":").Append(signedExitCode);
            json.Append(",\"exit_code_hex\":\"0x").Append(exitCode.ToString("X8")).Append("\"");
            json.Append(",\"completion_kind\":\"").Append(JsonEscape(completionKind)).Append("\"");
            json.Append(",\"terminate_job_called\":").Append(terminateJobCalled ? "true" : "false");
            json.Append(",\"terminate_job_ok\":").Append(terminateJobOk ? "true" : "false");
            json.Append(",\"terminate_job_error\":\"").Append(JsonEscape(terminateJobError)).Append("\"");
            json.Append(",\"cleanup_wait_result\":").Append(cleanupWait);
            json.Append(",\"cleanup_wait_kind\":\"").Append(JsonEscape(WaitKind(cleanupWait))).Append("\"");
            json.Append(",\"job_active_process_ids_after\":[");
            for (int index = 0; index < activeJobProcessIds.Length; index++)
            {
                if (index != 0) json.Append(",");
                json.Append(activeJobProcessIds[index]);
            }
            json.Append("]");
            json.Append(",\"job_active_process_query_error\":\"")
                .Append(JsonEscape(activeJobProcessQueryError)).Append("\"");
            json.Append(",\"failure\":\"").Append(JsonEscape(failure)).Append("\"");
            json.Append("}");
            return json.ToString();
        }
    }

    public sealed class BoundedSupervisorLaunch : IDisposable
    {
        private const uint CREATE_SUSPENDED = 0x00000004;
        private const uint CREATE_NO_WINDOW = 0x08000000;
        private const uint EXTENDED_STARTUPINFO_PRESENT = 0x00080000;
        private const uint STARTF_USESHOWWINDOW = 0x00000001;
        private static readonly IntPtr PROC_THREAD_ATTRIBUTE_JOB_LIST =
            new IntPtr(0x0002000D);
        private const ushort SW_HIDE = 0;
        private const uint JOB_OBJECT_LIMIT_PROCESS_MEMORY = 0x00000100;
        private const uint JOB_OBJECT_LIMIT_JOB_MEMORY = 0x00000200;
        private const uint JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE = 0x00002000;
        private const uint EXPECTED_LIMIT_FLAGS =
            JOB_OBJECT_LIMIT_PROCESS_MEMORY |
            JOB_OBJECT_LIMIT_JOB_MEMORY |
            JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;
        private const int JobObjectExtendedLimitInformation = 9;
        private const int JobObjectCpuRateControlInformation = 15;
        private const uint EXPECTED_CPU_FLAGS = 0x00000005;
        private const uint EXIT_ASSIGN_FAILED = 125;
        private const uint EXIT_RESUME_FAILED = 126;
        private const int ERROR_ALREADY_EXISTS = 183;
        private const int ERROR_INSUFFICIENT_BUFFER = 122;

        [StructLayout(LayoutKind.Sequential)]
        private struct IO_COUNTERS
        {
            public ulong ReadOperationCount;
            public ulong WriteOperationCount;
            public ulong OtherOperationCount;
            public ulong ReadTransferCount;
            public ulong WriteTransferCount;
            public ulong OtherTransferCount;
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct JOBOBJECT_BASIC_LIMIT_INFORMATION
        {
            public long PerProcessUserTimeLimit;
            public long PerJobUserTimeLimit;
            public uint LimitFlags;
            public UIntPtr MinimumWorkingSetSize;
            public UIntPtr MaximumWorkingSetSize;
            public uint ActiveProcessLimit;
            public UIntPtr Affinity;
            public uint PriorityClass;
            public uint SchedulingClass;
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct JOBOBJECT_EXTENDED_LIMIT_INFORMATION
        {
            public JOBOBJECT_BASIC_LIMIT_INFORMATION BasicLimitInformation;
            public IO_COUNTERS IoInfo;
            public UIntPtr ProcessMemoryLimit;
            public UIntPtr JobMemoryLimit;
            public UIntPtr PeakProcessMemoryUsed;
            public UIntPtr PeakJobMemoryUsed;
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct JOBOBJECT_CPU_RATE_CONTROL_INFORMATION
        {
            public uint ControlFlags;
            public uint CpuRate;
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct SECURITY_ATTRIBUTES
        {
            public int nLength;
            public IntPtr lpSecurityDescriptor;
            [MarshalAs(UnmanagedType.Bool)]
            public bool bInheritHandle;
        }

        [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
        private struct STARTUPINFO
        {
            public uint cb;
            public string lpReserved;
            public string lpDesktop;
            public string lpTitle;
            public uint dwX;
            public uint dwY;
            public uint dwXSize;
            public uint dwYSize;
            public uint dwXCountChars;
            public uint dwYCountChars;
            public uint dwFillAttribute;
            public uint dwFlags;
            public ushort wShowWindow;
            public ushort cbReserved2;
            public IntPtr lpReserved2;
            public IntPtr hStdInput;
            public IntPtr hStdOutput;
            public IntPtr hStdError;
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct PROCESS_INFORMATION
        {
            public IntPtr hProcess;
            public IntPtr hThread;
            public uint dwProcessId;
            public uint dwThreadId;
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct STARTUPINFOEX
        {
            public STARTUPINFO StartupInfo;
            public IntPtr lpAttributeList;
        }

        [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
        private static extern bool CreateProcess(
            string lpApplicationName,
            StringBuilder lpCommandLine,
            IntPtr lpProcessAttributes,
            IntPtr lpThreadAttributes,
            bool bInheritHandles,
            uint dwCreationFlags,
            IntPtr lpEnvironment,
            string lpCurrentDirectory,
            ref STARTUPINFOEX lpStartupInfo,
            out PROCESS_INFORMATION lpProcessInformation);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool InitializeProcThreadAttributeList(
            IntPtr attributeList,
            int attributeCount,
            uint flags,
            ref IntPtr size);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool UpdateProcThreadAttribute(
            IntPtr attributeList,
            uint flags,
            IntPtr attribute,
            IntPtr value,
            IntPtr size,
            IntPtr previousValue,
            IntPtr returnSize);

        [DllImport("kernel32.dll")]
        private static extern void DeleteProcThreadAttributeList(IntPtr attributeList);

        [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
        private static extern IntPtr CreateJobObject(IntPtr lpJobAttributes, string lpName);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool SetInformationJobObject(
            IntPtr hJob,
            int jobObjectInfoClass,
            IntPtr lpJobObjectInfo,
            uint cbJobObjectInfoLength);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool QueryInformationJobObject(
            IntPtr hJob,
            int jobObjectInfoClass,
            IntPtr lpJobObjectInfo,
            uint cbJobObjectInfoLength,
            out uint lpReturnLength);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool AssignProcessToJobObject(IntPtr hJob, IntPtr hProcess);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool IsProcessInJob(
            IntPtr processHandle,
            IntPtr jobHandle,
            [MarshalAs(UnmanagedType.Bool)] out bool result);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern uint ResumeThread(IntPtr hThread);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool TerminateProcess(IntPtr hProcess, uint exitCode);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool TerminateJobObject(IntPtr hJob, uint exitCode);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool CloseHandle(IntPtr handle);

        [DllImport("advapi32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
        private static extern bool ConvertStringSecurityDescriptorToSecurityDescriptor(
            string stringSecurityDescriptor,
            uint stringSDRevision,
            out IntPtr securityDescriptor,
            out uint securityDescriptorSize);

        [DllImport("kernel32.dll")]
        private static extern IntPtr LocalFree(IntPtr memory);

        private IntPtr processHandle;
        private IntPtr jobHandle;
        private bool disposed;

        public uint ProcessId { get; private set; }
        public string JobName { get; private set; }

        private BoundedSupervisorLaunch()
        {
        }

        public static BoundedSupervisorLaunch Launch(
            string applicationName,
            string arguments,
            string workingDirectory,
            string jobName,
            ulong memoryLimitBytes,
            uint cpuRate)
        {
            if (String.IsNullOrWhiteSpace(applicationName) ||
                String.IsNullOrWhiteSpace(workingDirectory) ||
                String.IsNullOrWhiteSpace(jobName) ||
                memoryLimitBytes == 0 || memoryLimitBytes >= 7000000000UL ||
                cpuRate == 0 || cpuRate > 10000)
            {
                throw new ArgumentException(
                    "SYNAPSE_CANDIDATE_SUPERVISOR_JOB_INPUT_INVALID remediation=provide exact paths and a positive sub-one-gigabyte committed-memory limit plus CPU rate 1..10000");
            }

            BoundedSupervisorLaunch owner = new BoundedSupervisorLaunch();
            PROCESS_INFORMATION processInfo = new PROCESS_INFORMATION();
            IntPtr limitPointer = IntPtr.Zero;
            IntPtr cpuPointer = IntPtr.Zero;
            IntPtr descriptor = IntPtr.Zero;
            IntPtr attributesPointer = IntPtr.Zero;
            IntPtr attributeList = IntPtr.Zero;
            IntPtr jobList = IntPtr.Zero;
            bool attributeListInitialized = false;
            bool processCreated = false;
            bool assigned = false;
            try
            {
                owner.JobName = jobName;

                uint descriptorSize;
                if (!ConvertStringSecurityDescriptorToSecurityDescriptor(
                    "D:P(A;;GA;;;SY)(A;;0x00100004;;;OW)",
                    1,
                    out descriptor,
                    out descriptorSize))
                {
                    ThrowLastError("SYNAPSE_CANDIDATE_SUPERVISOR_JOB_SECURITY_DESCRIPTOR_FAILED");
                }
                SECURITY_ATTRIBUTES attributes = new SECURITY_ATTRIBUTES();
                attributes.nLength = Marshal.SizeOf(typeof(SECURITY_ATTRIBUTES));
                attributes.lpSecurityDescriptor = descriptor;
                attributes.bInheritHandle = false;
                attributesPointer = Marshal.AllocHGlobal(attributes.nLength);
                Marshal.StructureToPtr(attributes, attributesPointer, false);
                owner.jobHandle = CreateJobObject(attributesPointer, owner.JobName);
                if (owner.jobHandle == IntPtr.Zero)
                {
                    ThrowLastError("SYNAPSE_CANDIDATE_SUPERVISOR_JOB_CREATE_FAILED");
                }
                if (Marshal.GetLastWin32Error() == ERROR_ALREADY_EXISTS)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_CANDIDATE_SUPERVISOR_JOB_NAME_COLLISION job_name=" + owner.JobName +
                        " remediation=refuse ambiguous PID/Job ownership before candidate execution");
                }

                JOBOBJECT_EXTENDED_LIMIT_INFORMATION limits =
                    new JOBOBJECT_EXTENDED_LIMIT_INFORMATION();
                limits.BasicLimitInformation.LimitFlags = EXPECTED_LIMIT_FLAGS;
                limits.ProcessMemoryLimit = ToUIntPtr(memoryLimitBytes);
                limits.JobMemoryLimit = ToUIntPtr(memoryLimitBytes);
                int limitSize = Marshal.SizeOf(typeof(JOBOBJECT_EXTENDED_LIMIT_INFORMATION));
                limitPointer = Marshal.AllocHGlobal(limitSize);
                Marshal.StructureToPtr(limits, limitPointer, false);
                if (!SetInformationJobObject(
                    owner.jobHandle,
                    JobObjectExtendedLimitInformation,
                    limitPointer,
                    (uint)limitSize))
                {
                    ThrowLastError("SYNAPSE_CANDIDATE_SUPERVISOR_JOB_LIMIT_SET_FAILED");
                }

                JOBOBJECT_CPU_RATE_CONTROL_INFORMATION cpu =
                    new JOBOBJECT_CPU_RATE_CONTROL_INFORMATION();
                cpu.ControlFlags = EXPECTED_CPU_FLAGS;
                cpu.CpuRate = cpuRate;
                int cpuSize = Marshal.SizeOf(typeof(JOBOBJECT_CPU_RATE_CONTROL_INFORMATION));
                cpuPointer = Marshal.AllocHGlobal(cpuSize);
                Marshal.StructureToPtr(cpu, cpuPointer, false);
                if (!SetInformationJobObject(
                    owner.jobHandle,
                    JobObjectCpuRateControlInformation,
                    cpuPointer,
                    (uint)cpuSize))
                {
                    ThrowLastError("SYNAPSE_CANDIDATE_SUPERVISOR_JOB_CPU_RATE_SET_FAILED");
                }

                uint returned;
                if (!QueryInformationJobObject(
                    owner.jobHandle,
                    JobObjectExtendedLimitInformation,
                    limitPointer,
                    (uint)limitSize,
                    out returned))
                {
                    ThrowLastError("SYNAPSE_CANDIDATE_SUPERVISOR_JOB_LIMIT_READBACK_FAILED");
                }
                if (returned != (uint)limitSize)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_CANDIDATE_SUPERVISOR_JOB_LIMIT_READBACK_SIZE_MISMATCH expected=" + limitSize +
                        " actual=" + returned +
                        " remediation=the host does not expose the expected class-9 Job limit ABI");
                }
                JOBOBJECT_EXTENDED_LIMIT_INFORMATION limitReadback =
                    (JOBOBJECT_EXTENDED_LIMIT_INFORMATION)Marshal.PtrToStructure(
                        limitPointer,
                        typeof(JOBOBJECT_EXTENDED_LIMIT_INFORMATION));
                if (!QueryInformationJobObject(
                    owner.jobHandle,
                    JobObjectCpuRateControlInformation,
                    cpuPointer,
                    (uint)cpuSize,
                    out returned))
                {
                    ThrowLastError("SYNAPSE_CANDIDATE_SUPERVISOR_JOB_CPU_RATE_READBACK_FAILED");
                }
                if (returned != (uint)cpuSize)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_CANDIDATE_SUPERVISOR_JOB_CPU_RATE_READBACK_SIZE_MISMATCH expected=" + cpuSize +
                        " actual=" + returned +
                        " remediation=the host does not expose the expected class-15 Job CPU ABI");
                }
                JOBOBJECT_CPU_RATE_CONTROL_INFORMATION cpuReadback =
                    (JOBOBJECT_CPU_RATE_CONTROL_INFORMATION)Marshal.PtrToStructure(
                        cpuPointer,
                        typeof(JOBOBJECT_CPU_RATE_CONTROL_INFORMATION));
                if (limitReadback.BasicLimitInformation.LimitFlags != EXPECTED_LIMIT_FLAGS ||
                    limitReadback.ProcessMemoryLimit.ToUInt64() != memoryLimitBytes ||
                    limitReadback.JobMemoryLimit.ToUInt64() != memoryLimitBytes ||
                    cpuReadback.ControlFlags != EXPECTED_CPU_FLAGS ||
                    cpuReadback.CpuRate != cpuRate)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_CANDIDATE_SUPERVISOR_JOB_READBACK_MISMATCH job_name=" + owner.JobName +
                        " remediation=the kernel did not retain the exact empty parent Job contract before creation-time assignment");
                }

                IntPtr attributeListSize = IntPtr.Zero;
                bool attributeSizeResult = InitializeProcThreadAttributeList(IntPtr.Zero, 1, 0, ref attributeListSize);
                int attributeSizeError = Marshal.GetLastWin32Error();
                if (attributeSizeResult || attributeSizeError != ERROR_INSUFFICIENT_BUFFER || attributeListSize == IntPtr.Zero)
                {
                    throw new InvalidOperationException(
                        "SYNAPSE_CANDIDATE_SUPERVISOR_JOB_LIST_SIZE_FAILED expected_win32=" + ERROR_INSUFFICIENT_BUFFER +
                        " actual_win32=" + attributeSizeError +
                        " unexpected_success=" + attributeSizeResult +
                        " size=" + attributeListSize +
                        " remediation=the host must support exact STARTUPINFOEX Job-list sizing before candidate creation");
                }
                attributeList = Marshal.AllocHGlobal(attributeListSize);
                if (!InitializeProcThreadAttributeList(attributeList, 1, 0, ref attributeListSize))
                {
                    ThrowLastError("SYNAPSE_CANDIDATE_SUPERVISOR_JOB_LIST_INIT_FAILED");
                }
                attributeListInitialized = true;
                jobList = Marshal.AllocHGlobal(IntPtr.Size);
                Marshal.WriteIntPtr(jobList, owner.jobHandle);
                if (!UpdateProcThreadAttribute(
                    attributeList,
                    0,
                    PROC_THREAD_ATTRIBUTE_JOB_LIST,
                    jobList,
                    new IntPtr(IntPtr.Size),
                    IntPtr.Zero,
                    IntPtr.Zero))
                {
                    ThrowLastError("SYNAPSE_CANDIDATE_SUPERVISOR_JOB_LIST_UPDATE_FAILED");
                }
                STARTUPINFOEX startup = new STARTUPINFOEX();
                startup.StartupInfo.cb = (uint)Marshal.SizeOf(typeof(STARTUPINFOEX));
                startup.StartupInfo.dwFlags = STARTF_USESHOWWINDOW;
                startup.StartupInfo.wShowWindow = SW_HIDE;
                startup.lpAttributeList = attributeList;
                string commandText = "\"" + applicationName + "\"";
                if (!String.IsNullOrWhiteSpace(arguments)) commandText += " " + arguments;
                if (!CreateProcess(
                    applicationName,
                    new StringBuilder(commandText),
                    IntPtr.Zero,
                    IntPtr.Zero,
                    false,
                    CREATE_SUSPENDED | CREATE_NO_WINDOW | EXTENDED_STARTUPINFO_PRESENT,
                    IntPtr.Zero,
                    workingDirectory,
                    ref startup,
                    out processInfo))
                {
                    ThrowLastError("SYNAPSE_CANDIDATE_SUPERVISOR_CREATE_PROCESS_IN_JOB_FAILED");
                }
                processCreated = true;
                assigned = true;
                owner.processHandle = processInfo.hProcess;
                owner.ProcessId = processInfo.dwProcessId;
                bool assignedToExactParent;
                if (!IsProcessInJob(processInfo.hProcess, owner.jobHandle, out assignedToExactParent))
                {
                    string detail = LastErrorMessage();
                    TerminateJobObject(owner.jobHandle, EXIT_ASSIGN_FAILED);
                    throw new InvalidOperationException(
                        "SYNAPSE_CANDIDATE_SUPERVISOR_JOB_MEMBERSHIP_READBACK_FAILED error=" + detail +
                        " remediation=the creation-assigned candidate supervisor remained suspended and the bounded tree was terminated because exact kernel Job membership could not be proven");
                }
                if (!assignedToExactParent)
                {
                    TerminateJobObject(owner.jobHandle, EXIT_ASSIGN_FAILED);
                    throw new InvalidOperationException(
                        "SYNAPSE_CANDIDATE_SUPERVISOR_JOB_MEMBERSHIP_MISMATCH job_name=" + owner.JobName +
                        " remediation=the candidate supervisor remained suspended and was terminated because the kernel did not retain exact parent Job membership");
                }
                if (ResumeThread(processInfo.hThread) == 0xffffffff)
                {
                    string detail = LastErrorMessage();
                    TerminateJobObject(owner.jobHandle, EXIT_RESUME_FAILED);
                    throw new InvalidOperationException(
                        "SYNAPSE_CANDIDATE_SUPERVISOR_RESUME_FAILED error=" + detail +
                        " remediation=inspect thread rights; the bounded candidate tree was terminated before supervisor execution");
                }
                CloseHandle(processInfo.hThread);
                processInfo.hThread = IntPtr.Zero;
                return owner;
            }
            catch
            {
                if (assigned && owner.jobHandle != IntPtr.Zero)
                {
                    TerminateJobObject(owner.jobHandle, 127);
                }
                else if (processCreated && processInfo.hProcess != IntPtr.Zero)
                {
                    TerminateProcess(processInfo.hProcess, 127);
                }
                owner.Dispose();
                throw;
            }
            finally
            {
                if (limitPointer != IntPtr.Zero) Marshal.FreeHGlobal(limitPointer);
                if (cpuPointer != IntPtr.Zero) Marshal.FreeHGlobal(cpuPointer);
                if (attributesPointer != IntPtr.Zero) Marshal.FreeHGlobal(attributesPointer);
                if (descriptor != IntPtr.Zero) LocalFree(descriptor);
                if (attributeList != IntPtr.Zero)
                {
                    if (attributeListInitialized) DeleteProcThreadAttributeList(attributeList);
                    Marshal.FreeHGlobal(attributeList);
                }
                if (jobList != IntPtr.Zero) Marshal.FreeHGlobal(jobList);
                if (processInfo.hThread != IntPtr.Zero) CloseHandle(processInfo.hThread);
            }
        }

        public void Dispose()
        {
            if (disposed) return;
            disposed = true;
            if (processHandle != IntPtr.Zero)
            {
                CloseHandle(processHandle);
                processHandle = IntPtr.Zero;
            }
            if (jobHandle != IntPtr.Zero)
            {
                CloseHandle(jobHandle);
                jobHandle = IntPtr.Zero;
            }
        }

        private static UIntPtr ToUIntPtr(ulong value)
        {
            if (UIntPtr.Size == 8) return new UIntPtr(value);
            return new UIntPtr(checked((uint)value));
        }

        private static void ThrowLastError(string code)
        {
            throw new InvalidOperationException(code + " error=" + LastErrorMessage());
        }

        private static string LastErrorMessage()
        {
            int error = Marshal.GetLastWin32Error();
            return "win32=" + error + " detail=" + new Win32Exception(error).Message;
        }
    }
}
'@ | Out-Null
}

function Invoke-SynapseProcessInKillOnCloseJob {
    param(
        [Parameter(Mandatory=$true)][string]$FilePath,
        [string[]]$ArgumentList = @(),
        [Parameter(Mandatory=$true)][string]$WorkingDirectory,
        [Parameter(Mandatory=$true)][int]$TimeoutMinutes,
        [string]$LogPath,
        [System.Management.Automation.PSReference]$Diagnostics
    )

    Ensure-SynapseSetupProcessJobType
    if (-not (Test-Path $FilePath)) { Die "Process job target missing: $FilePath" }
    if (-not (Test-Path $WorkingDirectory)) { Die "Process job working directory missing: $WorkingDirectory" }

    $argumentText = (($ArgumentList | ForEach-Object { Quote-WindowsCommandArgument $_ }) -join ' ').Trim()
    $targetCommand = (Quote-WindowsCommandArgument $FilePath)
    if (-not [string]::IsNullOrWhiteSpace($argumentText)) {
        $targetCommand = "$targetCommand $argumentText"
    }

    $applicationPath = $FilePath
    $commandLine = $targetCommand
    if (-not [string]::IsNullOrWhiteSpace($LogPath)) {
        New-Item -ItemType Directory -Force -Path (Split-Path -Parent $LogPath) | Out-Null
        if (Test-Path $LogPath) { Remove-Item $LogPath -Force }
        $cmdPath = Join-Path $env:SystemRoot 'System32\cmd.exe'
        $redirectCommand = "$targetCommand > $(Quote-WindowsCommandArgument $LogPath) 2>&1"
        $applicationPath = $cmdPath
        $commandLine = "$(Quote-WindowsCommandArgument $cmdPath) /d /s /c `"$redirectCommand`""
    }

    $timeoutMilliseconds = [uint32]([math]::Min([int64]$TimeoutMinutes * 60 * 1000, [uint32]::MaxValue))
    $failure = ''
    $processJobDiagnosticsJson = ''
    $startedAt = (Get-Date).ToUniversalTime().ToString('o')
    $compilerProcessesBefore = @(Get-SynapseBuildToolProcessSnapshot)
    $exitCode = [SynapseSetup.ProcessJob]::Run(
        $applicationPath,
        $commandLine,
        $WorkingDirectory,
        $timeoutMilliseconds,
        [ref]$failure,
        [ref]$processJobDiagnosticsJson)
    $completedAt = (Get-Date).ToUniversalTime().ToString('o')
    $compilerProcessesAfter = @(Get-SynapseBuildToolProcessSnapshot)
    $processJobDiagnostics = $null
    if (-not [string]::IsNullOrWhiteSpace($processJobDiagnosticsJson)) {
        try {
            $processJobDiagnostics = $processJobDiagnosticsJson | ConvertFrom-Json -ErrorAction Stop
        } catch {
            $processJobDiagnostics = [pscustomobject]@{
                schema = 'synapse_process_job_result_parse_failed/v1'
                raw = $processJobDiagnosticsJson
                parse_error = $_.Exception.Message
            }
        }
    }
    $childProcessAfter = $null
    if ($processJobDiagnostics -and $processJobDiagnostics.child_pid) {
        $childPid = [int]$processJobDiagnostics.child_pid
        $childProcessAfter = Get-CimInstance Win32_Process -Filter "ProcessId=$childPid" -ErrorAction SilentlyContinue |
            Select-Object ProcessId, ParentProcessId, Name, ExecutablePath, CommandLine
    }
    $jobActiveProcessIds = if ($processJobDiagnostics -and $processJobDiagnostics.job_active_process_ids_after) {
        @($processJobDiagnostics.job_active_process_ids_after | ForEach-Object { [uint32]$_ })
    } else {
        @()
    }
    $jobOwnedBuildToolsAfter = @($compilerProcessesAfter | Where-Object {
        $jobActiveProcessIds -contains [uint32]$_.ProcessId
    })
    $unrelatedBuildToolsAfter = @($compilerProcessesAfter | Where-Object {
        $jobActiveProcessIds -notcontains [uint32]$_.ProcessId
    })
    $diagnosticObject = [ordered]@{
        schema = 'synapse_setup_process_job_invocation/v2'
        command = $targetCommand
        application_path = $applicationPath
        working_directory = $WorkingDirectory
        timeout_minutes = $TimeoutMinutes
        timeout_ms = $timeoutMilliseconds
        log_path = $LogPath
        started_at_utc = $startedAt
        completed_at_utc = $completedAt
        exit_code = $exitCode
        failure = $failure
        process_job = $processJobDiagnostics
        child_process_after = $childProcessAfter
        global_build_tool_processes_before = $compilerProcessesBefore
        global_build_tool_processes_after = $compilerProcessesAfter
        job_owned_build_tool_processes_after = $jobOwnedBuildToolsAfter
        unrelated_build_tool_processes_after = $unrelatedBuildToolsAfter
        cleanup_result = [ordered]@{
            process_table_after_read = $true
            child_process_alive_after = ($null -ne $childProcessAfter)
            job_owned_build_tool_process_count_after = @($jobOwnedBuildToolsAfter).Count
            unrelated_build_tool_process_count_after = @($unrelatedBuildToolsAfter).Count
        }
    }
    if ($PSBoundParameters.ContainsKey('Diagnostics')) {
        $Diagnostics.Value = [pscustomobject]$diagnosticObject
    }
    return $exitCode
}

function Get-SynapseBuildToolProcessSnapshot {
    @(Get-CimInstance Win32_Process -Filter "Name='cargo.exe' OR Name='rustc.exe'" -ErrorAction SilentlyContinue |
        Sort-Object ProcessId |
        Select-Object ProcessId, ParentProcessId, Name, ExecutablePath, CommandLine)
}

# Windows keeps a running executable image locked for write/delete, so cargo can
# never replace its own link output while a process is running FROM the cargo
# target tree (rust-lang/cargo#12485, #11544). That is an environment/ownership
# fault, not a source defect, and it is fully knowable before a ~20 minute
# release build starts. This enumerates every live process whose image resides
# under the resolved target directory so both the preflight and the failure
# classifier can name the exact PID and image path (#1865).
function Get-SynapseBuildOutputImageHolders {
    param([Parameter(Mandatory=$true)][string]$TargetDir)

    $readback = [ordered]@{
        schema = 'synapse_setup_build_output_image_holders/v1'
        target_dir = $null
        process_table_read = $false
        process_table_error = $null
        holders = @()
        unreadable_path_processes = @()
    }
    try {
        $targetFull = Get-SynapseFullPathForScopeCheck -Path $TargetDir
    } catch {
        $readback.target_dir = $TargetDir
        $readback.process_table_error = "target_dir_unresolvable: $($_.Exception.Message)"
        return [pscustomobject]$readback
    }
    $readback.target_dir = $targetFull
    $prefix = $targetFull + [System.IO.Path]::DirectorySeparatorChar

    $processes = $null
    try {
        $processes = @(Get-CimInstance Win32_Process -ErrorAction Stop |
            Select-Object ProcessId, ParentProcessId, Name, ExecutablePath, CommandLine, CreationDate)
        $readback.process_table_read = $true
    } catch {
        $readback.process_table_error = $_.Exception.Message
        return [pscustomobject]$readback
    }

    $holders = @()
    $unreadable = @()
    foreach ($process in $processes) {
        $exe = [string]$process.ExecutablePath
        if ([string]::IsNullOrWhiteSpace($exe)) {
            # A process whose image path cannot be read is not evidence of
            # absence. Record it so the operator sees the exact gap instead of a
            # silent "no holders" claim.
            $unreadable += [pscustomobject]@{
                pid = [int]$process.ProcessId
                name = [string]$process.Name
            }
            continue
        }
        $exeFull = $null
        try { $exeFull = [System.IO.Path]::GetFullPath($exe) } catch { $exeFull = $exe }
        if (-not $exeFull.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)) { continue }
        $createdUtc = $null
        try {
            if ($process.CreationDate) { $createdUtc = ([datetime]$process.CreationDate).ToUniversalTime().ToString('o') }
        } catch { $createdUtc = $null }
        $holders += [pscustomobject]@{
            pid = [int]$process.ProcessId
            parent_pid = [int]$process.ParentProcessId
            name = [string]$process.Name
            executable_path = $exeFull
            command_line = (([string]$process.CommandLine -replace '\s+', ' ').Trim())
            created_at_utc = $createdUtc
        }
    }
    $readback.holders = @($holders | Sort-Object pid)
    $readback.unreadable_path_processes = @($unreadable | Sort-Object pid)
    return [pscustomobject]$readback
}

function Format-SynapseBuildOutputImageHolders {
    param([Parameter(Mandatory=$true)]$Readback)

    if (@($Readback.holders).Count -eq 0) { return '<none>' }
    return (@($Readback.holders | ForEach-Object {
        'pid={0} image={1} cmd={2}' -f $_.pid, $_.executable_path, $_.command_line
    }) -join ' | ')
}

# Cargo emits its own orchestration failures with the same `error:` prefix rustc
# uses for real diagnostics. Treating every `^error:` line as a compiler
# diagnostic is what made a locked link output report compiler_error=true with a
# remediation pointing at compiler errors that do not exist (#1865). Cargo's
# authoritative discriminator is `--message-format=json` (`reason` =
# `compiler-message`), which the human-readable build log deliberately does not
# use, so classify by shape instead: cargo orchestration failures are always
# `error: failed to <filesystem/network verb>` or `error: could not <verb>`, and
# never carry a rustc error code or a source span.
#
# `error: could not compile <crate>` belongs here too, and its absence is what
# made #1975 misreport a crashed compiler as a source defect. That line is
# ALWAYS cargo's wrapper around a rustc invocation that failed -- it is emitted
# whether rustc printed diagnostics or died of a segfault, and it never carries
# a source span. rustc's own diagnostics are separate `error[E....]:` / `error:`
# lines, so excluding the wrapper can never hide a genuine compile error: a real
# one still contributes its own line.
$script:SynapseCargoOrchestrationErrorPatterns = @(
    '(?i)^error:\s+failed to (remove|write|copy|rename|hardlink|link|create|open|read|move)\b',
    '(?i)^error:\s+could not (remove|create|write|open|read|delete)\b',
    '(?i)^error:\s+could not compile\b',
    '(?i)^error:\s+failed to (get|download|fetch|sync|update|load|select)\b',
    '(?i)^error:\s+the lock file needs to be updated',
    '(?i)^error:\s+no such command'
)

# A build tool that CRASHED is not a build that found errors. Cargo reports a
# crashed child as
#   process didn't exit successfully: `<tool> <args>` (exit code: 0xc0000005, STATUS_ACCESS_VIOLATION)
# where the exit code is an NTSTATUS value rather than a small integer. That is
# a subprocess crash signature, and it is mechanically distinguishable from a
# diagnostic: rustc/lld emitted no error, the operating system killed them.
#
# The distinction is the whole point of #1975. Four archived deploy failures
# reported `compiler_error=true` with the remediation "repair the compiler error
# lines", against a build in which every crate compiled and zero diagnostics were
# emitted -- sending the operator to hunt for source errors that did not exist,
# after an hour-long build, four times.
$script:SynapseToolchainCrashPatterns = @(
    "(?i)process didn't exit successfully:.*\(exit code:\s*0x[0-9a-f]{8}",
    '(?i)\(exit code:\s*0x[0-9a-f]{8},\s*STATUS_[A-Z_]+\s*\)',
    '(?i)\bSTATUS_ACCESS_VIOLATION\b',
    '(?i)\bSTATUS_STACK_OVERFLOW\b',
    '(?i)\bSTATUS_STACK_BUFFER_OVERRUN\b',
    '(?i)\bSTATUS_HEAP_CORRUPTION\b',
    '(?i)\bSTATUS_IN_PAGE_ERROR\b',
    '(?i)\bSTATUS_ILLEGAL_INSTRUCTION\b'
)

# `error: linking with `link.exe` failed` is rustc's wrapper around a separate
# tool's failure. It is never a source diagnostic, so "repair the compiler error
# lines" is the wrong remediation for it; it gets its own classification.
$script:SynapseLinkerFailurePatterns = @(
    '(?i)^error:\s+linking with .* failed',
    '(?i)\bLNK\d{4}\b',
    '(?i)^\s*=?\s*note:\s*rust-lld:\s*error:',
    '(?i)^rust-lld:\s*error:'
)

# A locked build output is always an environment/ownership fault. `os error 5`
# on the link output, MSVC LNK1104, and rust-lld output-write failures are the
# concrete Windows shapes of "something is holding the file we must replace".
$script:SynapseBuildOutputLockedPatterns = @(
    '(?i)^error:\s+failed to (remove|write|copy|rename|hardlink|link) ',
    '(?i)Access is denied\.\s*\(os error 5\)',
    '(?i)\bLNK1104\b',
    '(?i)rust-lld:\s*error:\s*failed to (write|open) output',
    '(?i)\(os error 32\)'
)

function Test-SynapseLogLineMatchesAny {
    param(
        [Parameter(Mandatory=$true)][string]$Line,
        [Parameter(Mandatory=$true)][string[]]$Patterns
    )
    foreach ($pattern in $Patterns) {
        if ($Line -match $pattern) { return $true }
    }
    return $false
}

function Get-SynapseBuildLogSignal {
    param([string]$Path)

    $signal = [ordered]@{
        path = $Path
        exists = $false
        has_compiler_error = $false
        compiler_error_matches = @()
        has_output_locked_error = $false
        output_locked_matches = @()
        output_locked_paths = @()
        cargo_orchestration_error_matches = @()
        has_linker_failure = $false
        linker_failure_matches = @()
        has_toolchain_crash = $false
        toolchain_crash_matches = @()
        toolchain_crash_status = $null
        toolchain_crash_exit_code = $null
        toolchain_crash_tool = $null
        has_memory_exhaustion = $false
        memory_exhaustion_matches = @()
        tail_80 = ''
    }
    if ([string]::IsNullOrWhiteSpace($Path) -or -not (Test-Path -LiteralPath $Path)) {
        return [pscustomobject]$signal
    }
    $signal.exists = $true
    $signal.tail_80 = (Get-Content -LiteralPath $Path -Tail 80 -ErrorAction SilentlyContinue) -join "`n"

    # `process didn't exit successfully` is in the candidate set because the
    # crash signature lives on THAT line, not on the `error:` line above it.
    # Before #1975 it was never scanned at all, so the one fact that identifies a
    # toolchain crash was invisible to this classifier.
    $candidates = @(Select-String -LiteralPath $Path -Pattern "(?i)(^error(\[.*\])?:|fatal error|could not compile|failed to run custom build command|panicked at|memory allocation of [0-9]+ bytes failed|LNK\d{4}|Access is denied\.\s*\(os error 5\)|\(os error 32\)|rust-lld:\s*error:|process didn't exit successfully|STATUS_[A-Z_]{4,})" -ErrorAction SilentlyContinue |
        Select-Object LineNumber, Line)

    $compilerMatches = @()
    $orchestrationMatches = @()
    $lockedMatches = @()
    $linkerMatches = @()
    $crashMatches = @()
    $memoryMatches = @()
    $lockedPaths = @()
    foreach ($candidate in $candidates) {
        $line = [string]$candidate.Line
        $isLocked = Test-SynapseLogLineMatchesAny -Line $line -Patterns $script:SynapseBuildOutputLockedPatterns
        $isOrchestration = Test-SynapseLogLineMatchesAny -Line $line -Patterns $script:SynapseCargoOrchestrationErrorPatterns
        $isLinker = Test-SynapseLogLineMatchesAny -Line $line -Patterns $script:SynapseLinkerFailurePatterns
        $isCrash = Test-SynapseLogLineMatchesAny -Line $line -Patterns $script:SynapseToolchainCrashPatterns
        $isMemoryExhaustion = ($line -match '(?i)memory allocation of [0-9]+ bytes failed')
        if ($isMemoryExhaustion) { $memoryMatches += $candidate }
        if ($isCrash) {
            $crashMatches += $candidate
            # Name the tool that died and the status it died of, so the
            # remediation can be specific instead of generic.
            $statusMatch = [regex]::Match($line, '(?i)\b(STATUS_[A-Z_]+)\b')
            if ($statusMatch.Success -and -not $signal.toolchain_crash_status) {
                $signal.toolchain_crash_status = $statusMatch.Groups[1].Value
            }
            $codeMatch = [regex]::Match($line, '(?i)exit code:\s*(0x[0-9a-f]{8})')
            if ($codeMatch.Success -and -not $signal.toolchain_crash_exit_code) {
                $signal.toolchain_crash_exit_code = $codeMatch.Groups[1].Value
            }
            $toolMatch = [regex]::Match($line, '(?i)`([^`]*?([A-Za-z0-9_.\-]+\.exe))')
            if ($toolMatch.Success -and -not $signal.toolchain_crash_tool) {
                $signal.toolchain_crash_tool = $toolMatch.Groups[2].Value
            }
        }
        if ($isLocked) {
            $lockedMatches += $candidate
            # Tools quote the offending path differently: cargo uses backticks,
            # MSVC LINK uses single quotes, rust-lld uses double quotes.
            foreach ($quotePattern in @('`(?<path>[^`]+)`', "'(?<path>[^']+)'", '"(?<path>[^"]+)"')) {
                $pathMatch = [regex]::Match($line, $quotePattern)
                if ($pathMatch.Success) { $lockedPaths += $pathMatch.Groups['path'].Value; break }
            }
        }
        if ($isLinker) { $linkerMatches += $candidate }
        if ($isOrchestration) { $orchestrationMatches += $candidate }
        # A line only counts as a compiler diagnostic when it is none of the
        # non-source failure shapes above. Anything else reproduces the #1865
        # misdirection where an ownership fault reads as compiler_error=true,
        # and the #1975 one where a crashed compiler did.
        if ($isOrchestration -or $isLocked -or $isLinker -or $isCrash) { continue }
        $compilerMatches += $candidate
    }

    $signal.compiler_error_matches = @($compilerMatches | Select-Object -First 20)
    $signal.has_compiler_error = (@($compilerMatches).Count -gt 0)
    $signal.output_locked_matches = @($lockedMatches | Select-Object -First 20)
    $signal.has_output_locked_error = (@($lockedMatches).Count -gt 0)
    $signal.output_locked_paths = @($lockedPaths | Select-Object -Unique)
    $signal.cargo_orchestration_error_matches = @($orchestrationMatches | Select-Object -First 20)
    $signal.linker_failure_matches = @($linkerMatches | Select-Object -First 20)
    $signal.has_linker_failure = (@($linkerMatches).Count -gt 0)
    $signal.toolchain_crash_matches = @($crashMatches | Select-Object -First 20)
    $signal.has_toolchain_crash = (@($crashMatches).Count -gt 0)
    $signal.memory_exhaustion_matches = @($memoryMatches | Select-Object -First 20)
    $signal.has_memory_exhaustion = (@($memoryMatches).Count -gt 0)
    return [pscustomobject]$signal
}

function Get-SynapseArtifactReadback {
    param([Parameter(Mandatory=$true)][string]$Path)

    $readback = [ordered]@{
        path = $Path
        exists = $false
        length_bytes = $null
        sha256 = $null
        exclusive_open = 'not_checked'
        exclusive_open_error = $null
    }
    if (-not (Test-Path -LiteralPath $Path)) {
        $readback.exclusive_open = 'missing'
        return [pscustomobject]$readback
    }
    $item = Get-Item -LiteralPath $Path -ErrorAction Stop
    $readback.exists = $true
    $readback.length_bytes = $item.Length
    try {
        $readback.sha256 = Get-SynapseFileSha256 -Path $Path
    } catch {
        $readback.sha256 = $null
        $readback.exclusive_open_error = "hash_failed: $($_.Exception.Message)"
    }
    try {
        $stream = [System.IO.File]::Open($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::None)
        try {
            $readback.exclusive_open = 'ok'
        } finally {
            $stream.Dispose()
        }
    } catch {
        $readback.exclusive_open = 'locked_or_unreadable'
        $readback.exclusive_open_error = $_.Exception.Message
    }
    return [pscustomobject]$readback
}

function Test-SynapseStatusAccessViolationExit {
    param([AllowNull()]$Job)

    if (-not $Job) { return $false }
    $hex = [string]$Job.exit_code_hex
    if ($hex -ieq '0xC0000005') { return $true }
    try {
        if ([uint32]$Job.exit_code_unsigned -eq [uint32]3221225477) { return $true }
    } catch {}
    try {
        if ([int32]$Job.exit_code_signed -eq -1073741819) { return $true }
    } catch {}
    return $false
}

function Get-SynapseWerCrashReadback {
    param([AllowNull()][string]$SinceUtc)

    $folder = Join-Path $env:LOCALAPPDATA 'CrashDumps'
    $since = $null
    if (-not [string]::IsNullOrWhiteSpace($SinceUtc)) {
        try {
            $since = ([DateTimeOffset]::Parse($SinceUtc)).UtcDateTime.AddMinutes(-2)
        } catch {
            $since = $null
        }
    }

    $readback = [ordered]@{
        schema = 'synapse_setup_wer_crash_readback/v1'
        folder = $folder
        folder_exists = $false
        since_utc = if ($since) { $since.ToString('o') } else { $null }
        process_names = @('cargo.exe','rustc.exe','rust-lld.exe','lld-link.exe','link.exe')
        localdump_registry_readable = $false
        localdump_registry_error = $null
        localdump_registry = @()
        recent_dump_count = 0
        recent_dumps = @()
    }

    $registryPaths = @(
        'HKLM:\SOFTWARE\Microsoft\Windows\Windows Error Reporting\LocalDumps',
        'HKLM:\SOFTWARE\Wow6432Node\Microsoft\Windows\Windows Error Reporting\LocalDumps'
    )
    $registryRows = @()
    foreach ($registryPath in $registryPaths) {
        try {
            if (Test-Path -LiteralPath $registryPath) {
                $root = Get-ItemProperty -LiteralPath $registryPath -ErrorAction Stop
                $registryRows += [pscustomobject]@{
                    path = $registryPath
                    dump_folder = $root.DumpFolder
                    dump_count = $root.DumpCount
                    dump_type = $root.DumpType
                    custom_dump_flags = $root.CustomDumpFlags
                }
                foreach ($name in $readback.process_names) {
                    $childPath = Join-Path $registryPath $name
                    if (Test-Path -LiteralPath $childPath) {
                        $child = Get-ItemProperty -LiteralPath $childPath -ErrorAction Stop
                        $registryRows += [pscustomobject]@{
                            path = $childPath
                            dump_folder = $child.DumpFolder
                            dump_count = $child.DumpCount
                            dump_type = $child.DumpType
                            custom_dump_flags = $child.CustomDumpFlags
                        }
                    }
                }
            }
            $readback.localdump_registry_readable = $true
        } catch {
            $readback.localdump_registry_error = $_.Exception.Message
        }
    }
    $readback.localdump_registry = @($registryRows)

    if (Test-Path -LiteralPath $folder) {
        $readback.folder_exists = $true
        $names = @($readback.process_names | ForEach-Object { $_.ToLowerInvariant() })
        $dumps = @(Get-ChildItem -LiteralPath $folder -File -ErrorAction SilentlyContinue |
            Where-Object {
                $lowerName = $_.Name.ToLowerInvariant()
                $matchesName = $false
                foreach ($name in $names) {
                    if ($lowerName.StartsWith($name.ToLowerInvariant())) {
                        $matchesName = $true
                        break
                    }
                }
                if (-not $matchesName) {
                    $false
                } elseif ($since) {
                    $_.LastWriteTimeUtc -ge $since
                } else {
                    $true
                }
            } |
            Sort-Object LastWriteTimeUtc -Descending |
            Select-Object -First 20 FullName, Name, Length, @{Name='LastWriteTimeUtc';Expression={$_.LastWriteTimeUtc.ToString('o')}})
        $readback.recent_dump_count = $dumps.Count
        $readback.recent_dumps = @($dumps)
    }

    return [pscustomobject]$readback
}

function Get-SynapseRustToolchainReadback {
    param([Parameter(Mandatory=$true)][string]$CargoPath)

    $commands = @('cargo','rustc','rust-lld','lld-link','link')
    $resolved = @()
    foreach ($command in $commands) {
        $row = [ordered]@{
            command = $command
            source = $null
            version = $null
            error = $null
        }
        try {
            $cmd = Get-Command $command -ErrorAction Stop
            $row.source = $cmd.Source
            if ($command -eq 'cargo') {
                $row.version = (& $CargoPath --version 2>&1 | Select-Object -First 1) -join ''
            } elseif ($command -eq 'rustc') {
                $row.version = (& $cmd.Source -vV 2>&1 | Select-Object -First 8) -join "`n"
            } else {
                $row.version = (& $cmd.Source --version 2>&1 | Select-Object -First 3) -join "`n"
            }
        } catch {
            $row.error = $_.Exception.Message
        }
        $resolved += [pscustomobject]$row
    }

    return [pscustomobject]@{
        schema = 'synapse_setup_rust_toolchain_readback/v1'
        cargo_path = $CargoPath
        commands = @($resolved)
    }
}

function Set-SynapseReleaseBuildCompilerEnvironment {
    # 8 MiB. The former 64 MiB minimum was retained after its crash hypothesis
    # had been falsified, on the assumption that virtual stack reservation had
    # no relevant cost. That assumption is incompatible with the hard sub-1 GB
    # source-build contract: rustc exhausted its Job memory while compiling a
    # dependency and reported a failed 36 KiB allocation. Keep the historical
    # 8 MiB compiler floor, but do not multiply every rustc worker's reservation
    # by another eight without evidence.
    $minimumRustStack = 8 * 1024 * 1024
    $existing = $env:RUST_MIN_STACK
    $effective = $minimumRustStack
    $source = 'synapse_setup_default'
    if (-not [string]::IsNullOrWhiteSpace($existing)) {
        $parsed = 0L
        if ([Int64]::TryParse($existing, [ref]$parsed) -and $parsed -ge $minimumRustStack) {
            $effective = $parsed
            $source = 'preexisting_env'
        } else {
            $source = 'raised_by_synapse_setup'
        }
    }
    $env:RUST_MIN_STACK = [string]$effective
    return [pscustomobject]@{
        schema = 'synapse_setup_release_build_compiler_environment/v1'
        rust_min_stack = $env:RUST_MIN_STACK
        rust_min_stack_source = $source
        rust_min_stack_minimum = $minimumRustStack
    }
}

function Get-SynapseReleaseBuildToolchainCrashRetryBudget {
    # How many EXTRA release-build attempts setup makes after rustc physically
    # crashes (#1975 ask 3).
    #
    # This is not a fallback and it is not a retry-until-green loop. It fires on
    # exactly one classification -- SYNAPSE_RELEASE_BUILD_TOOLCHAIN_CRASHED, a
    # named tool that died on an NTSTATUS having emitted zero source diagnostics
    # -- and on nothing else. A real compiler error, a link failure, a locked
    # output, or a timeout is deterministic and is still fatal on the first
    # attempt, because retrying any of those would be exactly the "cover a break
    # with a rerun" failure this codebase refuses.
    #
    # It is bounded, and every crashed attempt still writes its own immutable
    # diagnostics archive, so a retried deploy accrues MORE evidence than a
    # human-retried one rather than less. If the budget is exhausted the deploy
    # dies with the whole per-attempt history attached.
    #
    # Budget of 2 (3 attempts total). The observed crash rate is ~4 in 7
    # (#1975), so at p(crash) = 0.57 three independent attempts leave a
    # 0.57^3 = 18.6% chance of exhausting the budget -- high enough that the
    # exhaustion path is a real path that must report properly, and low enough
    # that most deploys land unattended. A retry re-runs only the final crate:
    # the measured successful retry took 14m54s against a 1.5-2h cold build.
    $default = 2
    $raw = $env:SYNAPSE_SETUP_TOOLCHAIN_CRASH_RETRIES
    if ([string]::IsNullOrWhiteSpace($raw)) {
        return [pscustomobject]@{ budget = $default; source = 'synapse_setup_default' }
    }
    $parsed = 0
    if (-not [int]::TryParse($raw, [ref]$parsed) -or $parsed -lt 0 -or $parsed -gt 10) {
        Die ("SYNAPSE_SETUP_TOOLCHAIN_CRASH_RETRY_BUDGET_INVALID value={0} remediation=SYNAPSE_SETUP_TOOLCHAIN_CRASH_RETRIES must be an integer in [0,10]; unset it to use the default of {1}" -f `
            $raw, $default)
    }
    return [pscustomobject]@{ budget = $parsed; source = 'env_override' }
}

function Get-SynapseReleaseBuildFailureKind {
    param(
        [Parameter(Mandatory=$true)]$Diagnostics,
        [Parameter(Mandatory=$true)]$LogSignal,
        [Parameter(Mandatory=$true)]$ArtifactReadback,
        [AllowNull()]$OutputImageHolders
    )

    $job = $Diagnostics.process_job
    # Ranked above the compiler-error branch on purpose: a locked link output is
    # an ownership fault whose fix is "stop the process holding the output", and
    # cargo reports it through the same `error:` prefix as a real diagnostic
    # (#1865).
    if ($LogSignal.has_output_locked_error) {
        $lockedPath = if (@($LogSignal.output_locked_paths).Count -gt 0) { @($LogSignal.output_locked_paths)[0] } else { '<unnamed>' }
        $holderText = if ($OutputImageHolders) { Format-SynapseBuildOutputImageHolders -Readback $OutputImageHolders } else { '<not_enumerated>' }
        return [pscustomobject]@{
            code = 'SYNAPSE_RELEASE_BUILD_OUTPUT_LOCKED'
            remediation = ("the build output could not be replaced because it is locked by a live process; locked_path=$lockedPath live_images_under_target_dir=$holderText; stop the exact process holding the build output (a daemon started straight out of target\release locks its own image on Windows) and rerun setup. This is NOT a compiler error; there is nothing to repair in the source.")
        }
    }
    if ($job -and $job.completion_kind -eq 'timeout') {
        return [pscustomobject]@{
            code = 'SYNAPSE_RELEASE_BUILD_TIMEOUT'
            remediation = 'increase BuildTimeoutMinutes only after verifying job_owned_build_tool_processes_after are still making progress, or inspect setup-build.log for a stuck compiler/linker; unrelated_build_tool_processes_after are context only and never cleanup targets'
        }
    }
    if ($job -and -not [string]::IsNullOrWhiteSpace([string]$job.failure) -and $job.completion_kind -ne 'child_exit') {
        return [pscustomobject]@{
            code = 'SYNAPSE_RELEASE_BUILD_PROCESS_JOB_FAILED'
            remediation = 'inspect process_job.failure, wait_kind, terminate_job_ok, and cleanup_wait_kind; repair the Windows process/job-object failure before rerunning setup'
        }
    }
    if ($ArtifactReadback.exclusive_open -eq 'locked_or_unreadable') {
        return [pscustomobject]@{
            code = 'SYNAPSE_RELEASE_BUILD_ARTIFACT_LOCKED'
            remediation = 'inspect the process table for a build or scanner process holding the release artifact; do not close protected terminal/IDE/WSL host processes'
        }
    }
    # A Rust allocator failure under the setup-owned hard Job ceiling is a
    # deterministic resource-admission refusal. Windows rustc subsequently
    # aborts with 0xc0000409, but retrying that abort as a probabilistic
    # toolchain crash only repeats the same over-budget compilation.
    if ($LogSignal.has_memory_exhaustion) {
        $first = @($LogSignal.memory_exhaustion_matches | ForEach-Object { "line $($_.LineNumber): $($_.Line)" } | Select-Object -First 5) -join ' | '
        return [pscustomobject]@{
            code = 'SYNAPSE_RELEASE_BUILD_MEMORY_LIMIT_EXCEEDED'
            remediation = ("the compiler exhausted the exact setup-owned 12,884,901,888-byte one-time build ceiling. No artifact was published and the Job cleaned its owned tree. Reduce compiler memory through a real crate boundary or measured code-generation change; do not weaken the daemon's separate sub-1-GiB runtime ceiling. Evidence: $first")
        }
    }
    # Ranked above the compiler-error branch on purpose (#1975): a build tool
    # killed by the operating system emitted no diagnostic, so "repair the
    # compiler error lines" names a fault that does not exist. The crash is
    # detected at the job level (cargo itself died) OR in the log (cargo
    # survived and reported a crashed grandchild -- which is the shape that
    # actually occurs here, because rustc is the process that dies).
    $jobCrashed = ($job -and (Test-SynapseStatusAccessViolationExit -Job $job))
    if ($jobCrashed -or $LogSignal.has_toolchain_crash) {
        $status = if ($LogSignal.toolchain_crash_status) { $LogSignal.toolchain_crash_status } else { 'STATUS_ACCESS_VIOLATION' }
        $hex = if ($LogSignal.toolchain_crash_exit_code) { $LogSignal.toolchain_crash_exit_code } elseif ($job) { [string]$job.exit_code_hex } else { '<unknown>' }
        $tool = if ($LogSignal.toolchain_crash_tool) { $LogSignal.toolchain_crash_tool } elseif ($jobCrashed) { 'cargo.exe' } else { '<unnamed tool>' }
        $diagCount = @($LogSignal.compiler_error_matches).Count
        $diagNote = if ($diagCount -gt 0) {
            "The log ALSO carries $diagCount source-diagnostic line(s) (see compiler_error_matches); read those too, but they did not cause this exit."
        } else {
            'ZERO source-diagnostic lines were emitted, so there is nothing in the source to repair.'
        }
        return [pscustomobject]@{
            code = 'SYNAPSE_RELEASE_BUILD_TOOLCHAIN_CRASHED'
            remediation = ("$tool was killed by the operating system with $status (exit=$hex). This is a build-TOOL crash, not a compile error: the tool never reported a problem with the code, the OS terminated it. $diagNote " +
                'Remediation, in order: (1) rerun setup -- this crash is probabilistic on this host and every crate other than the final one is already cached, so a retry costs a fraction of a full build; ' +
                '(2) if it repeats, read toolchain_crash_matches in setup-build.log to see which tool and which stage died, and check compiler_environment.rust_min_stack in the diagnostics -- a rustc codegen worker running out of stack surfaces exactly like this on Windows; ' +
                '(3) treat a change in the crashing stage, tool, or status as new evidence and record it on the tracking issue rather than assuming it is the same fault. Do NOT go looking for compiler error lines.')
        }
    }
    if ($LogSignal.has_compiler_error) {
        $first = @($LogSignal.compiler_error_matches | ForEach-Object { "line $($_.LineNumber): $($_.Line)" } | Select-Object -First 5) -join ' | '
        return [pscustomobject]@{
            code = 'SYNAPSE_RELEASE_BUILD_COMPILER_FAILED'
            remediation = ("repair the compiler error lines recorded in setup-build.log before rerunning setup. The classified diagnostics are: $first")
        }
    }
    # Ranked after the compiler branch: a genuine source defect can also fail the
    # link, and the source diagnostic is the more actionable of the two.
    if ($LogSignal.has_linker_failure) {
        return [pscustomobject]@{
            code = 'SYNAPSE_RELEASE_BUILD_LINKER_FAILED'
            remediation = 'the linker failed with no rustc source diagnostic; inspect the linker_failure_matches lines in setup-build.log (missing symbol, missing native library, or unreadable input) and repair the link inputs or toolchain. There are no compiler error lines to repair.'
        }
    }
    if ($job -and [int]$job.exit_code_signed -eq -1) {
        return [pscustomobject]@{
            code = 'SYNAPSE_RELEASE_BUILD_CHILD_EXIT_NO_COMPILER_ERROR'
            remediation = 'child process exited -1 without compiler diagnostics; inspect process_job child_pid/wait_kind/job_active_process_ids_after, job_owned_build_tool_processes_after, artifact_readback, and Windows host logs; unrelated_build_tool_processes_after are context only'
        }
    }
    return [pscustomobject]@{
        code = 'SYNAPSE_RELEASE_BUILD_CHILD_EXIT'
        remediation = 'child process exited nonzero; inspect setup-build.log, process_job, job_owned_build_tool_processes_after, and artifact_readback; unrelated_build_tool_processes_after are context only'
    }
}

function Get-SynapseCargoVersionFailureKind {
    param([Parameter(Mandatory=$true)]$Diagnostics)

    $job = $Diagnostics.process_job
    if ($job -and $job.completion_kind -eq 'timeout') {
        return [pscustomobject]@{
            code = 'SYNAPSE_CARGO_VERSION_TIMEOUT'
            remediation = 'cargo --version did not return inside the setup preflight timeout; inspect child_pid, wait_kind, terminate_job_ok, and process table before rerunning setup'
        }
    }
    if ($job -and -not [string]::IsNullOrWhiteSpace([string]$job.failure) -and $job.completion_kind -ne 'child_exit') {
        return [pscustomobject]@{
            code = 'SYNAPSE_CARGO_VERSION_PROCESS_JOB_FAILED'
            remediation = 'repair the Windows process/job-object failure recorded in setup-cargo-version-diagnostics.json before rerunning setup'
        }
    }
    return [pscustomobject]@{
        code = 'SYNAPSE_CARGO_VERSION_FAILED'
        remediation = 'cargo --version exited nonzero; inspect setup-cargo-version.log and setup-cargo-version-diagnostics.json, then repair the Rust toolchain before rerunning setup'
    }
}

function Assert-SynapseCodexLauncherExactPropertySet {
    param([Parameter(Mandatory=$true)]$Value,[Parameter(Mandatory=$true)][string[]]$Expected,[Parameter(Mandatory=$true)][string]$Context)
    if($null-eq$Value){Die "SYNAPSE_CODEX_LAUNCHER_DESCRIPTOR_NULL context=$Context"};$actual=@($Value.PSObject.Properties.Name)
    if($actual.Count-ne$Expected.Count-or@($actual|Where-Object{$Expected-cnotcontains$_}).Count-ne0){Die "SYNAPSE_CODEX_LAUNCHER_DESCRIPTOR_KEYS_INVALID context=$Context expected=$($Expected-join',') actual=$($actual-join',')"}
}

function Get-SynapseCodexLauncherInstallRoot {
    return (Get-SynapseNormalizedDirectoryPath -Path (Join-Path $env:LOCALAPPDATA 'synapse\codex-launcher-installs'))
}

function Get-SynapseCodexLauncherPlanSeed {
    param([Parameter(Mandatory=$true)]$Plan)
    return [ordered]@{install_nonce=([string]$Plan.install_nonce).ToUpperInvariant();record_root=[System.IO.Path]::GetFullPath([string]$Plan.record_root);record_root_file_id_128=([string]$Plan.record_root_file_id_128).ToUpperInvariant();npm_dir=Get-SynapseNormalizedDirectoryPath -Path ([string]$Plan.npm_dir);npm_dir_chain=(ConvertTo-SynapseCanonicalValue -Value @($Plan.npm_dir_chain));token_path=[System.IO.Path]::GetFullPath([string]$Plan.token_path);tool_surface_snapshot_path=[System.IO.Path]::GetFullPath([string]$Plan.tool_surface_snapshot_path);target_count=[int]$Plan.target_count;targets=@($Plan.targets|ForEach-Object{[ordered]@{ordinal=[int]$_.ordinal;role=[string]$_.role;path=[System.IO.Path]::GetFullPath([string]$_.path);leaf=[string]$_.leaf;operation=[string]$_.operation;pre_file_id_128=([string]$_.pre_file_id_128).ToUpperInvariant();pre_sha256=([string]$_.pre_sha256).ToUpperInvariant();pre_length=[int64]$_.pre_length;desired_utf8_base64=[string]$_.desired_utf8_base64;desired_sha256=([string]$_.desired_sha256).ToUpperInvariant();desired_length=[int64]$_.desired_length}})}
}

function Assert-SynapseCodexLauncherInstallPlan {
    param([Parameter(Mandatory=$true)]$Record,[Parameter(Mandatory=$true)][string]$Context)
    $p=$Record.Payload;Assert-SynapseCodexLauncherExactPropertySet -Value $p -Expected @('schema','state','install_id','install_nonce','created_at_utc','created_by_pid','record_root','record_root_file_id_128','npm_dir','npm_dir_chain','token_path','tool_surface_snapshot_path','target_count','targets','plan_sha256') -Context $Context
    if([string]$p.schema-cne'synapse_codex_launcher_install_plan/v1'-or[string]$p.state-cne'planned_before_mutation'-or[string]$p.install_id-notmatch'^[0-9A-F]{64}$'-or[string]$p.install_nonce-notmatch'^[0-9A-F]{32}$'-or[string]$Record.Leaf-cne("install-$($p.install_id)-plan.json")-or[string]$p.record_root_file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'-or-not[System.IO.Path]::IsPathFullyQualified([string]$p.token_path)-or-not[System.IO.Path]::IsPathFullyQualified([string]$p.tool_surface_snapshot_path)-or[int]$p.target_count-ne3-or[int]$p.created_by_pid-lt1-or[string]$p.plan_sha256-notmatch'^[0-9A-Fa-f]{64}$'){Die "SYNAPSE_CODEX_LAUNCHER_PLAN_INVALID context=$Context path=$($Record.Path)"}
    $time=[DateTime]::MinValue;if(-not[DateTime]::TryParse([string]$p.created_at_utc,[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::RoundtripKind,[ref]$time)){Die "SYNAPSE_CODEX_LAUNCHER_PLAN_TIME_INVALID context=$Context"}
    $root=Get-SynapseNormalizedDirectoryPath -Path ([string]$p.record_root)
    $actualRecordRoot=Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent ([string]$Record.Path))
    if($root-ine$actualRecordRoot){Die "SYNAPSE_CODEX_LAUNCHER_RECORD_ROOT_DRIFT context=$Context declared=$root actual=$actualRecordRoot"}
    $recordRootChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $actualRecordRoot)
    if([string]$recordRootChain[-1].file_id_128-ine[string]$p.record_root_file_id_128){Die "SYNAPSE_CODEX_LAUNCHER_RECORD_ROOT_IDENTITY_DRIFT context=$Context declared=$($p.record_root_file_id_128) actual=$($recordRootChain[-1].file_id_128)"}
    $npm=Get-SynapseNormalizedDirectoryPath -Path ([string]$p.npm_dir);Assert-SynapsePurgeStoredDirectoryChain -Chain $p.npm_dir_chain -ExpectedPath $npm -Context "${Context}_npm_chain"
    $roles=@('powershell','cmd','shell');$leaves=@('codex.ps1','codex.cmd','codex');$targets=@($p.targets);if($targets.Count-ne3){Die "SYNAPSE_CODEX_LAUNCHER_PLAN_TARGET_COUNT_INVALID context=$Context"}
    foreach($ordinal in 1..3){
        $target=$targets[$ordinal-1]
        Assert-SynapseCodexLauncherExactPropertySet -Value $target -Expected @('ordinal','role','path','leaf','operation','pre_file_id_128','pre_sha256','pre_length','desired_utf8_base64','desired_sha256','desired_length','stage_leaf','park_leaf') -Context "${Context}_target_$ordinal"
        $bytes=$null
        try{$bytes=[Convert]::FromBase64String([string]$target.desired_utf8_base64);[void][Text.UTF8Encoding]::new($false,$true).GetString($bytes)}catch{Die "SYNAPSE_CODEX_LAUNCHER_DESIRED_UTF8_INVALID context=$Context role=$($target.role)"}
        $sha=[Security.Cryptography.SHA256]::Create()
        try{$actualSha=([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','')}finally{$sha.Dispose()}
        $expectedStage=if([string]$target.operation-ceq'replace'){".synapse-codex-$(([string]$p.install_id).Substring(0,32).ToLowerInvariant())-$($target.role)-stage"}else{''}
        $expectedPark=if([string]$target.operation-ceq'replace'){".synapse-codex-$(([string]$p.install_id).Substring(0,32).ToLowerInvariant())-$($target.role)-park"}else{''}
        $expectedPath=[System.IO.Path]::GetFullPath((Join-Path $npm ([string]$target.leaf)))
        $leafName=Split-Path -Leaf ([string]$target.leaf)
        if([int]$target.ordinal-ne$ordinal-or
            [string]$target.role-cne$roles[$ordinal-1]-or
            [string]$target.leaf-cne$leaves[$ordinal-1]-or
            [System.IO.Path]::GetFullPath([string]$target.path)-ine$expectedPath-or
            [string]$target.leaf-cne$leafName-or
            [string]$target.operation-cnotin@('retain','replace')-or
            [string]$target.pre_file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'-or
            [string]$target.pre_sha256-notmatch'^[0-9A-Fa-f]{64}$'-or
            [int64]$target.pre_length-lt0-or
            [string]$target.desired_sha256-ine$actualSha-or
            [int64]$target.desired_length-ne$bytes.Length-or
            [string]$target.stage_leaf-cne$expectedStage-or
            [string]$target.park_leaf-cne$expectedPark-or
            ([string]$target.operation-ceq'retain'-and([string]$target.pre_sha256-ine[string]$target.desired_sha256-or[int64]$target.pre_length-ne[int64]$target.desired_length))){Die "SYNAPSE_CODEX_LAUNCHER_PLAN_TARGET_INVALID context=$Context role=$($target.role)"}
    }
    $seed=Get-SynapseCodexLauncherPlanSeed -Plan $p;$id=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $seed)).ToUpperInvariant();if($id-cne[string]$p.install_id){Die "SYNAPSE_CODEX_LAUNCHER_INSTALL_ID_INVALID context=$Context expected=$($p.install_id) actual=$id"};$core=ConvertTo-SynapseCanonicalValue -Value $p;[void]$core.Remove('plan_sha256');$planSha=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $core)).ToUpperInvariant();if($planSha-ine[string]$p.plan_sha256){Die "SYNAPSE_CODEX_LAUNCHER_PLAN_HASH_INVALID context=$Context"};return $p
}

function Assert-SynapseCodexLauncherPreparedRecord {
    param([Parameter(Mandatory=$true)]$Record,[Parameter(Mandatory=$true)]$Plan,[Parameter(Mandatory=$true)][string]$Context)
    $p=$Record.Payload;Assert-SynapseCodexLauncherExactPropertySet -Value $p -Expected @('schema','state','install_id','plan','stages','prepared_at_utc','prepared_sha256') -Context $Context
    if([string]$p.schema-cne'synapse_codex_launcher_install_prepared/v1'-or[string]$p.state-cne'prepared_before_park'-or[string]$p.install_id-cne[string]$Plan.Payload.install_id-or[string]$Record.Leaf-cne("install-$($p.install_id)-prepared.json")-or[string]$p.prepared_sha256-notmatch'^[0-9A-Fa-f]{64}$'){Die "SYNAPSE_CODEX_LAUNCHER_PREPARED_INVALID context=$Context"};$pr=$p.plan;Assert-SynapseCodexLauncherExactPropertySet -Value $pr -Expected @('leaf','file_id_128','sha256','length','plan_sha256') -Context "${Context}_plan";if([string]$pr.leaf-cne[string]$Plan.Leaf-or[string]$pr.file_id_128-ine[string]$Plan.State.FileId128-or[string]$pr.sha256-ine[string]$Plan.State.Sha256-or[int64]$pr.length-ne[int64]$Plan.State.Length-or[string]$pr.plan_sha256-ine[string]$Plan.Payload.plan_sha256){Die "SYNAPSE_CODEX_LAUNCHER_PREPARED_PLAN_DRIFT context=$Context"}
    $replace=@($Plan.Payload.targets|Where-Object{[string]$_.operation-ceq'replace'});$stages=@($p.stages);if($stages.Count-ne$replace.Count){Die "SYNAPSE_CODEX_LAUNCHER_STAGE_COUNT_INVALID context=$Context"};for($i=0;$i-lt$stages.Count;$i++){$s=$stages[$i];$t=$replace[$i];Assert-SynapseCodexLauncherExactPropertySet -Value $s -Expected @('role','leaf','file_id_128','sha256','length') -Context "${Context}_stage";if([string]$s.role-cne[string]$t.role-or[string]$s.leaf-cne[string]$t.stage_leaf-or[string]$s.file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'-or[string]$s.sha256-ine[string]$t.desired_sha256-or[int64]$s.length-ne[int64]$t.desired_length){Die "SYNAPSE_CODEX_LAUNCHER_STAGE_INVALID context=$Context role=$($s.role)"}}
    $time=[DateTime]::MinValue;if(-not[DateTime]::TryParse([string]$p.prepared_at_utc,[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::RoundtripKind,[ref]$time)){Die "SYNAPSE_CODEX_LAUNCHER_PREPARED_TIME_INVALID context=$Context"};$core=ConvertTo-SynapseCanonicalValue -Value $p;[void]$core.Remove('prepared_sha256');if((Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $core))-ine[string]$p.prepared_sha256){Die "SYNAPSE_CODEX_LAUNCHER_PREPARED_HASH_INVALID context=$Context"};return $p
}

function Assert-SynapseCodexLauncherCompletedRecord {
    param([Parameter(Mandatory=$true)]$Record,[Parameter(Mandatory=$true)]$Plan,[Parameter(Mandatory=$true)]$Prepared,[Parameter(Mandatory=$true)][string]$Context)
    $p=$Record.Payload;Assert-SynapseCodexLauncherExactPropertySet -Value $p -Expected @('schema','state','install_id','plan','prepared','targets','completed_at_utc','terminal_sha256') -Context $Context
    if([string]$p.schema-cne'synapse_codex_launcher_install_terminal/v1'-or[string]$p.state-cne'committed'-or[string]$p.install_id-cne[string]$Plan.Payload.install_id-or[string]$Record.Leaf-cne("install-$($p.install_id)-completed.json")-or[string]$p.terminal_sha256-notmatch'^[0-9A-Fa-f]{64}$'){Die "SYNAPSE_CODEX_LAUNCHER_TERMINAL_INVALID context=$Context"}
    foreach($ref in @([pscustomobject]@{Actual=$p.plan;Source=$Plan;Hash=[string]$Plan.Payload.plan_sha256;HashName='plan_sha256';Role='plan'},[pscustomobject]@{Actual=$p.prepared;Source=$Prepared;Hash=[string]$Prepared.Payload.prepared_sha256;HashName='prepared_sha256';Role='prepared'})){Assert-SynapseCodexLauncherExactPropertySet -Value $ref.Actual -Expected @('leaf','file_id_128','sha256','length',$ref.HashName) -Context "${Context}_$($ref.Role)";if([string]$ref.Actual.leaf-cne[string]$ref.Source.Leaf-or[string]$ref.Actual.file_id_128-ine[string]$ref.Source.State.FileId128-or[string]$ref.Actual.sha256-ine[string]$ref.Source.State.Sha256-or[int64]$ref.Actual.length-ne[int64]$ref.Source.State.Length-or[string]$ref.Actual.($ref.HashName)-ine[string]$ref.Hash){Die "SYNAPSE_CODEX_LAUNCHER_TERMINAL_REFERENCE_DRIFT context=$Context role=$($ref.Role)"}}
    $targets=@($p.targets)
    if($targets.Count-ne3){Die "SYNAPSE_CODEX_LAUNCHER_TERMINAL_TARGET_COUNT_INVALID context=$Context"}
    for($i=0;$i-lt3;$i++){
        $a=$targets[$i];$t=$Plan.Payload.targets[$i]
        $stage=@($Prepared.Payload.stages|Where-Object{[string]$_.role-ceq[string]$t.role})
        $expectedFinalId=if([string]$t.operation-ceq'replace'){if($stage.Count-ne1){Die "SYNAPSE_CODEX_LAUNCHER_TERMINAL_STAGE_AMBIGUOUS context=$Context role=$($t.role) count=$($stage.Count)"};[string]$stage[0].file_id_128}else{[string]$t.pre_file_id_128}
        Assert-SynapseCodexLauncherExactPropertySet -Value $a -Expected @('ordinal','role','path','file_id_128','sha256','length','park_leaf','park_file_id_128','park_sha256','park_length') -Context "${Context}_target"
        if([int]$a.ordinal-ne[int]$t.ordinal-or[string]$a.role-cne[string]$t.role-or[System.IO.Path]::GetFullPath([string]$a.path)-ine[System.IO.Path]::GetFullPath([string]$t.path)-or[string]$a.file_id_128-ine$expectedFinalId-or[string]$a.sha256-ine[string]$t.desired_sha256-or[int64]$a.length-ne[int64]$t.desired_length-or([string]$t.operation-ceq'replace'-and([string]$a.park_leaf-cne[string]$t.park_leaf-or[string]$a.park_file_id_128-ine[string]$t.pre_file_id_128-or[string]$a.park_sha256-ine[string]$t.pre_sha256-or[int64]$a.park_length-ne[int64]$t.pre_length))-or([string]$t.operation-ceq'retain'-and(-not[string]::IsNullOrEmpty([string]$a.park_leaf)-or-not[string]::IsNullOrEmpty([string]$a.park_file_id_128)-or-not[string]::IsNullOrEmpty([string]$a.park_sha256)-or[int64]$a.park_length-ne-1L))){Die "SYNAPSE_CODEX_LAUNCHER_TERMINAL_TARGET_INVALID context=$Context role=$($a.role)"}
    }
    $time=[DateTime]::MinValue;if(-not[DateTime]::TryParse([string]$p.completed_at_utc,[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::RoundtripKind,[ref]$time)){Die "SYNAPSE_CODEX_LAUNCHER_TERMINAL_TIME_INVALID context=$Context"};$core=ConvertTo-SynapseCanonicalValue -Value $p;[void]$core.Remove('terminal_sha256');if((Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $core))-ine[string]$p.terminal_sha256){Die "SYNAPSE_CODEX_LAUNCHER_TERMINAL_HASH_INVALID context=$Context"};return $p
}

function Write-SynapseCodexLauncherInstallRecord {
    param([Parameter(Mandatory=$true)][string]$Root,[Parameter(Mandatory=$true)]$RootChain,[Parameter(Mandatory=$true)][string]$Leaf,[Parameter(Mandatory=$true)]$Payload,[Parameter(Mandatory=$true)][string]$Purpose)
    $state=Get-SynapsePhysicalRelativeState -ParentPath $Root -ParentChain $RootChain -Leaf $Leaf
    if(-not[bool]$state.Exists){$text=(Get-SynapseCanonicalJson -Value $Payload)+"`n";if([Text.UTF8Encoding]::new($false,$true).GetByteCount($text)-gt4MB){Die "SYNAPSE_CODEX_LAUNCHER_RECORD_TOO_LARGE leaf=$Leaf"};Ensure-SynapseAtomicFileType;$rootIdentity=[SynapseSetup.AtomicFileV2]::GetPhysicalDirectoryIdentity($Root);[void](Write-SynapseAtomicUtf8TextFileUnderPhysicalRoot -Root $Root -ExpectedRootIdentity $rootIdentity -LeafName $Leaf -Content $text -Purpose $Purpose)}
    return (Open-SynapsePurgeRecordExact -RecordRoot $Root -RecordRootChain $RootChain -Leaf $Leaf -Context $Purpose)
}

function Get-SynapseCodexLauncherInstallPendingRecord {
    param([Parameter(Mandatory=$true)][string]$Root,[Parameter(Mandatory=$true)][string]$Context)
    $rootFull=Get-SynapseNormalizedDirectoryPath -Path $Root
    $rootBoundary=Get-SynapsePurgePhysicalDirectoryBoundary -Path $rootFull -Context $Context
    if(-not[bool]$rootBoundary.Exists){return $null}
    $rootChain=@($rootBoundary.Chain)
    $published='^install-[0-9A-F]{64}-(plan|prepared|completed)\.json$';$temp='^\.install-[0-9A-F]{64}-(plan|prepared|completed)\.json\.tmp-[1-9][0-9]*-[0-9a-f]{32}$';$entries=@()
    for($pass=0;$pass-le4096;$pass++){$entries=@(Get-SynapsePhysicalDirectoryEntriesBounded -Path $rootFull -Chain $rootChain -MaximumEntries 4096 -Context $Context);$invalid=@($entries|Where-Object{[bool]$_.IsDirectory-or([uint32]$_.Attributes-band[uint32][IO.FileAttributes]::ReparsePoint)-or([string]$_.Name-notmatch$published-and[string]$_.Name-notmatch$temp)});if($invalid.Count){Die "SYNAPSE_CODEX_LAUNCHER_RECORD_NAMESPACE_INVALID entries=$(@($invalid.Name)-join',')"};$temps=@($entries|Where-Object{[string]$_.Name-match$temp});if(-not$temps.Count){break};if($pass-eq4096){Die 'SYNAPSE_CODEX_LAUNCHER_RECORD_TEMP_BOUND_EXCEEDED'};foreach($entry in $temps){$s=Get-SynapsePhysicalRelativeState -ParentPath $rootFull -ParentChain $rootChain -Leaf ([string]$entry.Name);if([bool]$s.Exists){Remove-SynapsePhysicalRelativeEntryExact -ParentPath $rootFull -ParentChain $rootChain -Leaf ([string]$entry.Name) -ExpectedFileId128 ([string]$s.FileId128) -ExpectedSha256 ([string]$s.Sha256) -ExpectedLength ([int64]$s.Length) -Context 'codex_launcher_record_temp'}}}
    $entries=@(Get-SynapsePhysicalDirectoryEntriesBounded -Path $rootFull -Chain $rootChain -MaximumEntries 4096 -Context "${Context}_final");$invalid=@($entries|Where-Object{[bool]$_.IsDirectory-or([uint32]$_.Attributes-band[uint32][IO.FileAttributes]::ReparsePoint)-or[string]$_.Name-notmatch$published});if($invalid.Count){Die "SYNAPSE_CODEX_LAUNCHER_RECORD_FINAL_NAMESPACE_INVALID entries=$(@($invalid.Name)-join',')"};$plans=@($entries|Where-Object{[string]$_.Name-match'-plan\.json$'}|Sort-Object Name);$pending=@()
    foreach($entry in $plans){$plan=$null;$prepared=$null;$completed=$null;try{$plan=Open-SynapsePurgeRecordExact -RecordRoot $rootFull -RecordRootChain $rootChain -Leaf ([string]$entry.Name) -Context 'codex_launcher_plan_scan';[void](Assert-SynapseCodexLauncherInstallPlan -Record $plan -Context 'codex_launcher_plan_scan');$preparedLeaf="install-$($plan.Payload.install_id)-prepared.json";$preparedState=Get-SynapsePhysicalRelativeState -ParentPath $rootFull -ParentChain $rootChain -Leaf $preparedLeaf;if([bool]$preparedState.Exists){$prepared=Open-SynapsePurgeRecordExact -RecordRoot $rootFull -RecordRootChain $rootChain -Leaf $preparedLeaf -Context 'codex_launcher_prepared_scan';[void](Assert-SynapseCodexLauncherPreparedRecord -Record $prepared -Plan $plan -Context 'codex_launcher_prepared_scan')};$completedLeaf="install-$($plan.Payload.install_id)-completed.json";$completedState=Get-SynapsePhysicalRelativeState -ParentPath $rootFull -ParentChain $rootChain -Leaf $completedLeaf;if([bool]$completedState.Exists){if($null-eq$prepared){Die "SYNAPSE_CODEX_LAUNCHER_TERMINAL_WITHOUT_PREPARED install=$($plan.Payload.install_id)"};$completed=Open-SynapsePurgeRecordExact -RecordRoot $rootFull -RecordRootChain $rootChain -Leaf $completedLeaf -Context 'codex_launcher_terminal_scan';[void](Assert-SynapseCodexLauncherCompletedRecord -Record $completed -Plan $plan -Prepared $prepared -Context 'codex_launcher_terminal_scan');$completed.Lease.Dispose();$completed=$null;$prepared.Lease.Dispose();$prepared=$null;$plan.Lease.Dispose();$plan=$null;continue};$pending+=,[pscustomobject][ordered]@{Root=$rootFull;RootChain=$rootChain;Plan=$plan;Prepared=$prepared};$plan=$null;$prepared=$null}catch{foreach($record in @($completed,$prepared,$plan)){if($null-ne$record){try{$record.Lease.Dispose()}catch{}}};throw}}
    $planIds=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    foreach($entry in $plans){[void]$planIds.Add(([regex]::Match([string]$entry.Name,'^install-([0-9A-F]{64})-')).Groups[1].Value)}
    $orphan=@($entries|Where-Object{[string]$_.Name-match'-(prepared|completed)\.json$'-and-not$planIds.Contains(([regex]::Match([string]$_.Name,'^install-([0-9A-F]{64})-')).Groups[1].Value)})
    if($orphan.Count){foreach($p in $pending){if($null-ne$p.Prepared){$p.Prepared.Lease.Dispose()};$p.Plan.Lease.Dispose()};Die "SYNAPSE_CODEX_LAUNCHER_ORPHAN_RECORD entries=$(@($orphan.Name)-join',')"}
    if($pending.Count-gt1){foreach($p in $pending){if($null-ne$p.Prepared){$p.Prepared.Lease.Dispose()};$p.Plan.Lease.Dispose()};Die "SYNAPSE_CODEX_LAUNCHER_PENDING_AMBIGUITY count=$($pending.Count)"};if($pending.Count-eq1){return $pending[0]};return $null
}

function Resume-SynapseCodexLauncherInstallTransactions {
    param([string]$Root=(Get-SynapseCodexLauncherInstallRoot),[Parameter(Mandatory=$true)][string]$Context,[object[]]$InitialPreimageLeases=@())
    $pending=Get-SynapseCodexLauncherInstallPendingRecord -Root $Root -Context $Context
    if($null-eq$pending){return $null}
    $plan=$pending.Plan;$prepared=$pending.Prepared
    $npm=[string]$plan.Payload.npm_dir
    $npmChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $npm)
    if((Get-SynapseCanonicalJson -Value $npmChain)-cne(Get-SynapseCanonicalJson -Value @($plan.Payload.npm_dir_chain))){Die "SYNAPSE_CODEX_LAUNCHER_NPM_DIRECTORY_DRIFT install=$($plan.Payload.install_id)"}
    $rootFull=[string]$pending.Root;$rootChain=@($pending.RootChain);$primary=$null
    $retainedProofs=[Collections.Generic.List[object]]::new()
    $parkProofs=[Collections.Generic.List[object]]::new()
    $postProofs=[Collections.Generic.List[object]]::new()
    $freshStageProofs=[Collections.Generic.List[object]]::new()
    $finalNamespaceGuard=$null
    try{
        $initialByRole=@{}
        if(@($InitialPreimageLeases).Count-notin@(0,3)){Die "SYNAPSE_CODEX_LAUNCHER_INITIAL_PREIMAGE_LEASE_COUNT_INVALID count=$(@($InitialPreimageLeases).Count)"}
        for($i=0;$i-lt@($InitialPreimageLeases).Count;$i++){
            $target=$plan.Payload.targets[$i];$lease=$InitialPreimageLeases[$i]
            if($null-eq$lease-or[string]$lease.CurrentPath-ine[System.IO.Path]::GetFullPath([string]$target.path)-or[string]$lease.FileId128-ine[string]$target.pre_file_id_128-or[string]$lease.Sha256-ine[string]$target.pre_sha256-or[int64]$lease.Length-ne[int64]$target.pre_length){Die "SYNAPSE_CODEX_LAUNCHER_INITIAL_PREIMAGE_LEASE_DRIFT install=$($plan.Payload.install_id) role=$($target.role)"}
            $lease.RequireExact("${Context}_initial_$($target.role)");$initialByRole[[string]$target.role]=$lease
        }
        if($null-eq$prepared){
            try{
                $stageRecords=@()
                foreach($target in @($plan.Payload.targets|Where-Object{[string]$_.operation-ceq'replace'})){
                    $canonical=Get-SynapsePhysicalRelativeState -ParentPath $npm -ParentChain $npmChain -Leaf ([string]$target.leaf)
                    $park=Get-SynapsePhysicalRelativeState -ParentPath $npm -ParentChain $npmChain -Leaf ([string]$target.park_leaf)
                    if(-not[bool]$canonical.Exists-or[string]$canonical.FileId128-ine[string]$target.pre_file_id_128-or[string]$canonical.Sha256-ine[string]$target.pre_sha256-or[int64]$canonical.Length-ne[int64]$target.pre_length-or[bool]$park.Exists){Die "SYNAPSE_CODEX_LAUNCHER_PLAN_ONLY_STATE_INVALID install=$($plan.Payload.install_id) role=$($target.role)"}
                    $stage=Get-SynapsePhysicalRelativeState -ParentPath $npm -ParentChain $npmChain -Leaf ([string]$target.stage_leaf)
                    if([bool]$stage.Exists-and([string]$stage.Sha256-ine[string]$target.desired_sha256-or[int64]$stage.Length-ne[int64]$target.desired_length)){
                        $plan.Lease.RequireExact("${Context}_invalid_stage_delete")
                        Remove-SynapsePhysicalRelativeEntryExact -ParentPath $npm -ParentChain $npmChain -Leaf ([string]$target.stage_leaf) -ExpectedFileId128 ([string]$stage.FileId128) -ExpectedSha256 ([string]$stage.Sha256) -ExpectedLength ([int64]$stage.Length) -Context 'codex_launcher_invalid_stage'
                        $stage=$null
                    }
                    $newStageHandle=$null
                    if($null-eq$stage-or-not[bool]$stage.Exists){
                        $newStageHandle=New-SynapsePhysicalAllocatedFile -ParentPath $npm -ParentChain $npmChain -Leaf ([string]$target.stage_leaf) -Context 'codex_launcher_stage_allocate'
                        try{$bytes=[Convert]::FromBase64String([string]$target.desired_utf8_base64);$text=[Text.UTF8Encoding]::new($false,$true).GetString($bytes);$write=$newStageHandle.FillUtf8($text,[string]$target.desired_sha256,[int64]$target.desired_length);$stage=[pscustomobject]@{Exists=$true;FileId128=[string]$write.FileId128;Sha256=[string]$write.Sha256;Length=[int64]$write.Length}}catch{try{$newStageHandle.Dispose()}catch{};$newStageHandle=$null;throw}
                    }
                    $lease=if($null-ne$newStageHandle){$owned=$newStageHandle;$newStageHandle=$null;$owned}else{Open-SynapsePhysicalFileTransitionLease -ParentPath $npm -ParentChain $npmChain -Leaf ([string]$target.stage_leaf) -ExpectedFileId128 ([string]$stage.FileId128) -ExpectedSha256 ([string]$target.desired_sha256) -ExpectedLength ([int64]$target.desired_length) -Context 'codex_launcher_stage_seal'}
                    $freshStageProofs.Add([pscustomobject]@{Role=[string]$target.role;Lease=$lease})
                    $stageRecords+=,[ordered]@{role=[string]$target.role;leaf=[string]$target.stage_leaf;file_id_128=([string]$stage.FileId128).ToUpperInvariant();sha256=([string]$target.desired_sha256).ToUpperInvariant();length=[int64]$target.desired_length}
                }
                $plan.Lease.RequireExact("${Context}_before_prepared")
                $preparedPayload=[ordered]@{schema='synapse_codex_launcher_install_prepared/v1';state='prepared_before_park';install_id=[string]$plan.Payload.install_id;plan=[ordered]@{leaf=[string]$plan.Leaf;file_id_128=([string]$plan.State.FileId128).ToUpperInvariant();sha256=([string]$plan.State.Sha256).ToUpperInvariant();length=[int64]$plan.State.Length;plan_sha256=([string]$plan.Payload.plan_sha256).ToUpperInvariant()};stages=$stageRecords;prepared_at_utc=[DateTime]::UtcNow.ToString('o')}
                $preparedPayload.prepared_sha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $preparedPayload)).ToUpperInvariant()
                $prepared=Write-SynapseCodexLauncherInstallRecord -Root $rootFull -RootChain $rootChain -Leaf "install-$($plan.Payload.install_id)-prepared.json" -Payload $preparedPayload -Purpose 'codex_launcher_prepared'
                [void](Assert-SynapseCodexLauncherPreparedRecord -Record $prepared -Plan $plan -Context 'codex_launcher_prepared')
                foreach($proof in $freshStageProofs){$proof.Lease.RequireExact("${Context}_prepared_stage_$($proof.Role)")}
            }catch{throw}
        }

        $stageByRole=@{}
        foreach($stage in @($prepared.Payload.stages)){$stageByRole[[string]$stage.role]=$stage}
        $states=@()
        foreach($target in @($plan.Payload.targets)){
            $canonical=Get-SynapsePhysicalRelativeState -ParentPath $npm -ParentChain $npmChain -Leaf ([string]$target.leaf)
            if([string]$target.operation-ceq'retain'){
                if(-not[bool]$canonical.Exists-or[string]$canonical.FileId128-ine[string]$target.pre_file_id_128-or[string]$canonical.Sha256-ine[string]$target.pre_sha256-or[int64]$canonical.Length-ne[int64]$target.pre_length){Die "SYNAPSE_CODEX_LAUNCHER_RETAIN_DRIFT install=$($plan.Payload.install_id) role=$($target.role)"}
                $lease=if($initialByRole.ContainsKey([string]$target.role)){$initialByRole[[string]$target.role]}else{Open-SynapsePhysicalFileReadLease -ParentPath $npm -ParentChain $npmChain -Leaf ([string]$target.leaf) -ExpectedFileId128 ([string]$target.pre_file_id_128) -ExpectedSha256 ([string]$target.pre_sha256) -ExpectedLength ([int64]$target.pre_length) -Context 'codex_launcher_retain_proof'}
                $retainedProofs.Add([pscustomobject]@{Target=$target;Lease=$lease})
                $states+=,[pscustomobject]@{Target=$target;StageRecord=$null;Phase='retain'}
                continue
            }
            $stageRecord=$stageByRole[[string]$target.role]
            if($null-eq$stageRecord){Die "SYNAPSE_CODEX_LAUNCHER_STAGE_RECORD_MISSING install=$($plan.Payload.install_id) role=$($target.role)"}
            $stage=Get-SynapsePhysicalRelativeState -ParentPath $npm -ParentChain $npmChain -Leaf ([string]$target.stage_leaf)
            $park=Get-SynapsePhysicalRelativeState -ParentPath $npm -ParentChain $npmChain -Leaf ([string]$target.park_leaf)
            $canonicalPre=([bool]$canonical.Exists-and[string]$canonical.FileId128-ieq[string]$target.pre_file_id_128-and[string]$canonical.Sha256-ieq[string]$target.pre_sha256-and[int64]$canonical.Length-eq[int64]$target.pre_length)
            $canonicalPost=([bool]$canonical.Exists-and[string]$canonical.FileId128-ieq[string]$stageRecord.file_id_128-and[string]$canonical.Sha256-ieq[string]$stageRecord.sha256-and[int64]$canonical.Length-eq[int64]$stageRecord.length)
            $stageExact=([bool]$stage.Exists-and[string]$stage.FileId128-ieq[string]$stageRecord.file_id_128-and[string]$stage.Sha256-ieq[string]$stageRecord.sha256-and[int64]$stage.Length-eq[int64]$stageRecord.length)
            $parkExact=([bool]$park.Exists-and[string]$park.FileId128-ieq[string]$target.pre_file_id_128-and[string]$park.Sha256-ieq[string]$target.pre_sha256-and[int64]$park.Length-eq[int64]$target.pre_length)
            $isPre=($canonicalPre-and$stageExact-and-not[bool]$park.Exists)
            $isParked=(-not[bool]$canonical.Exists-and$stageExact-and$parkExact)
            $isPost=($canonicalPost-and-not[bool]$stage.Exists-and$parkExact)
            if(-not$isPre-and-not$isParked-and-not$isPost){Die "SYNAPSE_CODEX_LAUNCHER_RECOVERY_STATE_INVALID install=$($plan.Payload.install_id) role=$($target.role)"}
            $states+=,[pscustomobject]@{Target=$target;StageRecord=$stageRecord;Phase=$(if($isPre){'pre'}elseif($isParked){'parked'}else{'post'})}
        }
        if(@($states|Where-Object{$_.Phase-ceq'post'}).Count-and@($states|Where-Object{$_.Phase-ceq'pre'}).Count){Die "SYNAPSE_CODEX_LAUNCHER_PUBLISH_BEFORE_ALL_PARKED install=$($plan.Payload.install_id)"}

        # Acquire every proof before the first mutation.  This prevents a drift
        # in a later target from expanding an otherwise untouched partial cut.
        foreach($state in @($states|Where-Object{$_.Phase-ne'retain'})){
            $target=$state.Target;$stageRecord=$state.StageRecord
            if($state.Phase-ceq'pre'){
                $parkLease=if($initialByRole.ContainsKey([string]$target.role)){$initialByRole[[string]$target.role]}else{Open-SynapsePhysicalFileTransitionLease -ParentPath $npm -ParentChain $npmChain -Leaf ([string]$target.leaf) -ExpectedFileId128 ([string]$target.pre_file_id_128) -ExpectedSha256 ([string]$target.pre_sha256) -ExpectedLength ([int64]$target.pre_length) -Context 'codex_launcher_pre_lease'}
                $parkProofs.Add([pscustomobject]@{Target=$target;Lease=$parkLease;MoveRequired=$true})
            }else{
                $parkLease=Open-SynapsePhysicalFileReadLease -ParentPath $npm -ParentChain $npmChain -Leaf ([string]$target.park_leaf) -ExpectedFileId128 ([string]$target.pre_file_id_128) -ExpectedSha256 ([string]$target.pre_sha256) -ExpectedLength ([int64]$target.pre_length) -Context 'codex_launcher_park_proof'
                $parkProofs.Add([pscustomobject]@{Target=$target;Lease=$parkLease;MoveRequired=$false})
            }
            if($state.Phase-ceq'post'){
                $postLease=Open-SynapsePhysicalFileReadLease -ParentPath $npm -ParentChain $npmChain -Leaf ([string]$target.leaf) -ExpectedFileId128 ([string]$stageRecord.file_id_128) -ExpectedSha256 ([string]$stageRecord.sha256) -ExpectedLength ([int64]$stageRecord.length) -Context 'codex_launcher_existing_post_proof'
                $postProofs.Add([pscustomobject]@{Target=$target;Lease=$postLease;MoveRequired=$false})
            }else{
                $canonical=Get-SynapsePhysicalRelativeState -ParentPath $npm -ParentChain $npmChain -Leaf ([string]$target.leaf)
                if($state.Phase-ceq'parked'-and[bool]$canonical.Exists){Die "SYNAPSE_CODEX_LAUNCHER_CANONICAL_NOT_ABSENT_BEFORE_PUBLISH install=$($plan.Payload.install_id) role=$($target.role)"}
                $fresh=@($freshStageProofs|Where-Object{[string]$_.Role-ceq[string]$target.role-and$null-ne$_.Lease})
                if($fresh.Count-gt1){Die "SYNAPSE_CODEX_LAUNCHER_FRESH_STAGE_AMBIGUOUS install=$($plan.Payload.install_id) role=$($target.role)"}
                if($fresh.Count-eq1){$stageLease=$fresh[0].Lease;$fresh[0].Lease=$null}else{$stageLease=Open-SynapsePhysicalFileTransitionLease -ParentPath $npm -ParentChain $npmChain -Leaf ([string]$target.stage_leaf) -ExpectedFileId128 ([string]$stageRecord.file_id_128) -ExpectedSha256 ([string]$stageRecord.sha256) -ExpectedLength ([int64]$stageRecord.length) -Context 'codex_launcher_publish_stage'}
                $postProofs.Add([pscustomobject]@{Target=$target;Lease=$stageLease;MoveRequired=$true})
            }
        }
        foreach($owned in @($parkProofs|Where-Object{[bool]$_.MoveRequired})){
            $plan.Lease.RequireExact("${Context}_park_$($owned.Target.role)");$prepared.Lease.RequireExact("${Context}_park_prepared_$($owned.Target.role)")
            [void]$owned.Lease.MoveNoReplace($npm,(Get-SynapsePhysicalChainPaths -Chain $npmChain),(Get-SynapsePhysicalChainFileIds -Chain $npmChain),[string]$owned.Target.park_leaf)
        }
        foreach($owned in @($postProofs|Where-Object{[bool]$_.MoveRequired})){
            $plan.Lease.RequireExact("${Context}_publish_$($owned.Target.role)");$prepared.Lease.RequireExact("${Context}_publish_prepared_$($owned.Target.role)")
            [void]$owned.Lease.MoveNoReplace($npm,(Get-SynapsePhysicalChainPaths -Chain $npmChain),(Get-SynapsePhysicalChainFileIds -Chain $npmChain),[string]$owned.Target.leaf)
        }

        try{
            $finalNamespaceGuard=[SynapseSetup.AtomicFileV2]::BeginPhysicalDirectoryChangeGuard($npm,(Get-SynapsePhysicalChainPaths -Chain $npmChain),(Get-SynapsePhysicalChainFileIds -Chain $npmChain),[string]$npmChain[-1].file_id_128,$false)
        }catch{Die "SYNAPSE_CODEX_LAUNCHER_FINAL_NAMESPACE_GUARD_FAILED install=$($plan.Payload.install_id) error=$($_.Exception.Message)"}
        foreach($target in @($plan.Payload.targets|Where-Object{[string]$_.operation-ceq'replace'})){if([bool](Get-SynapsePhysicalRelativeState -ParentPath $npm -ParentChain $npmChain -Leaf ([string]$target.stage_leaf)).Exists){Die "SYNAPSE_CODEX_LAUNCHER_STAGE_PRESENT_AT_TERMINAL_BOUNDARY install=$($plan.Payload.install_id) role=$($target.role)"}}
        $finalNamespaceGuard.RequireCleanCheckpoint("${Context}_before_terminal_projection")

        $terminalTargets=@()
        foreach($target in @($plan.Payload.targets)){
            $expectedId=if([string]$target.operation-ceq'replace'){[string]$stageByRole[[string]$target.role].file_id_128}else{[string]$target.pre_file_id_128}
            $post=Get-SynapsePhysicalRelativeState -ParentPath $npm -ParentChain $npmChain -Leaf ([string]$target.leaf)
            if(-not[bool]$post.Exists-or[string]$post.FileId128-ine$expectedId-or[string]$post.Sha256-ine[string]$target.desired_sha256-or[int64]$post.Length-ne[int64]$target.desired_length){Die "SYNAPSE_CODEX_LAUNCHER_FINAL_DRIFT install=$($plan.Payload.install_id) role=$($target.role)"}
            if([string]$target.operation-ceq'replace'){
                $terminalTargets+=,[ordered]@{ordinal=[int]$target.ordinal;role=[string]$target.role;path=[string]$target.path;file_id_128=$expectedId.ToUpperInvariant();sha256=([string]$post.Sha256).ToUpperInvariant();length=[int64]$post.Length;park_leaf=[string]$target.park_leaf;park_file_id_128=([string]$target.pre_file_id_128).ToUpperInvariant();park_sha256=([string]$target.pre_sha256).ToUpperInvariant();park_length=[int64]$target.pre_length}
            }else{
                $terminalTargets+=,[ordered]@{ordinal=[int]$target.ordinal;role=[string]$target.role;path=[string]$target.path;file_id_128=$expectedId.ToUpperInvariant();sha256=([string]$post.Sha256).ToUpperInvariant();length=[int64]$post.Length;park_leaf='';park_file_id_128='';park_sha256='';park_length=-1L}
            }
        }
        foreach($proof in @($retainedProofs)+@($parkProofs)+@($postProofs)){$proof.Lease.RequireExact("${Context}_terminal_cut")}
        foreach($target in @($plan.Payload.targets|Where-Object{[string]$_.operation-ceq'replace'})){if([bool](Get-SynapsePhysicalRelativeState -ParentPath $npm -ParentChain $npmChain -Leaf ([string]$target.stage_leaf)).Exists){Die "SYNAPSE_CODEX_LAUNCHER_STAGE_PRESENT_AT_FINAL_CUT install=$($plan.Payload.install_id) role=$($target.role)"}}
        $finalNamespaceGuard.RequireCleanCheckpoint("${Context}_terminal_cut")
        $finalNamespaceGuard.CompleteCleanGuard()
        try{$finalNamespaceGuard.Dispose()}catch{[Environment]::FailFast("SYNAPSE_CODEX_LAUNCHER_NAMESPACE_GUARD_RELEASE_FAILED",$_.Exception)}
        $finalNamespaceGuard=$null
        $terminal=[ordered]@{schema='synapse_codex_launcher_install_terminal/v1';state='committed';install_id=[string]$plan.Payload.install_id;plan=[ordered]@{leaf=[string]$plan.Leaf;file_id_128=([string]$plan.State.FileId128).ToUpperInvariant();sha256=([string]$plan.State.Sha256).ToUpperInvariant();length=[int64]$plan.State.Length;plan_sha256=([string]$plan.Payload.plan_sha256).ToUpperInvariant()};prepared=[ordered]@{leaf=[string]$prepared.Leaf;file_id_128=([string]$prepared.State.FileId128).ToUpperInvariant();sha256=([string]$prepared.State.Sha256).ToUpperInvariant();length=[int64]$prepared.State.Length;prepared_sha256=([string]$prepared.Payload.prepared_sha256).ToUpperInvariant()};targets=$terminalTargets;completed_at_utc=[DateTime]::UtcNow.ToString('o')}
        $terminal.terminal_sha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $terminal)).ToUpperInvariant()
        $completed=Write-SynapseCodexLauncherInstallRecord -Root $rootFull -RootChain $rootChain -Leaf "install-$($plan.Payload.install_id)-completed.json" -Payload $terminal -Purpose 'codex_launcher_terminal'
        try{
            [void](Assert-SynapseCodexLauncherCompletedRecord -Record $completed -Plan $plan -Prepared $prepared -Context 'codex_launcher_terminal')
            Info "SYNAPSE_CODEX_LAUNCHER_INSTALL_COMMITTED install_id=$($plan.Payload.install_id) targets=3"
        }finally{$completed.Lease.Dispose()}
        return [string]$plan.Payload.install_id
    }catch{$primary=$_.Exception;throw}finally{
        if($null-ne$finalNamespaceGuard){try{$finalNamespaceGuard.Dispose()}catch{[Environment]::FailFast("SYNAPSE_CODEX_LAUNCHER_NAMESPACE_GUARD_RELEASE_FAILED",$_.Exception)}}
        foreach($proof in @($postProofs)+@($parkProofs)+@($retainedProofs)+@($freshStageProofs)){if($null-ne$proof-and$null-ne$proof.Lease){try{$proof.Lease.Dispose()}catch{[Environment]::FailFast("SYNAPSE_CODEX_LAUNCHER_TARGET_LEASE_RELEASE_FAILED",$_.Exception)}}}
        if($null-ne$prepared){try{$prepared.Lease.Dispose()}catch{[Environment]::FailFast("SYNAPSE_CODEX_LAUNCHER_PREPARED_LEASE_RELEASE_FAILED primary=$($primary.Message)",$_.Exception)}}
        if($null-ne$plan){try{$plan.Lease.Dispose()}catch{[Environment]::FailFast("SYNAPSE_CODEX_LAUNCHER_PLAN_LEASE_RELEASE_FAILED primary=$($primary.Message)",$_.Exception)}}
    }
}

function Complete-SynapseCodexLauncherInstallTransaction {
    param([Parameter(Mandatory=$true)]$Targets,[Parameter(Mandatory=$true)][string]$TokenPath,[Parameter(Mandatory=$true)][string]$ToolSurfaceSnapshotPath,[string]$Root=(Get-SynapseCodexLauncherInstallRoot))
    [void](Resume-SynapseCodexLauncherInstallTransactions -Root $Root -Context 'codex_launcher_preexisting_recovery')
    $items=@($Targets|Sort-Object Ordinal)
    $actualRolesJson=Get-SynapseCanonicalJson -Value @($items.Role)
    $expectedRolesJson=Get-SynapseCanonicalJson -Value @('powershell','cmd','shell')
    if($items.Count-ne3-or$actualRolesJson-cne$expectedRolesJson){Die "SYNAPSE_CODEX_LAUNCHER_TARGET_SET_INVALID count=$($items.Count) roles=$(@($items.Role)-join',')"}
    $expectedLeaves=@('codex.ps1','codex.cmd','codex')
    for($i=0;$i-lt3;$i++){if([int]$items[$i].Ordinal-ne($i+1)){Die "SYNAPSE_CODEX_LAUNCHER_TARGET_ORDINAL_INVALID role=$($items[$i].Role) ordinal=$($items[$i].Ordinal) expected=$($i+1)"};if((Split-Path -Leaf ([string]$items[$i].Path))-cne$expectedLeaves[$i]){Die "SYNAPSE_CODEX_LAUNCHER_TARGET_LEAF_INVALID role=$($items[$i].Role) path=$($items[$i].Path) expected_leaf=$($expectedLeaves[$i])"}}
    $npm=Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent ([string]$items[0].Path))
    $npmChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $npm)
    $leases=@()
    try{
        $seedTargets=@();$allRetain=$true
        foreach($item in $items){
            $full=[System.IO.Path]::GetFullPath([string]$item.Path)
            if((Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $full))-ine$npm){Die "SYNAPSE_CODEX_LAUNCHER_PARENT_MISMATCH role=$($item.Role) path=$full"}
            $leaf=Split-Path -Leaf $full
            $state=Get-SynapsePhysicalRelativeState -ParentPath $npm -ParentChain $npmChain -Leaf $leaf
            if(-not[bool]$state.Exists){Die "SYNAPSE_CODEX_LAUNCHER_PREIMAGE_MISSING role=$($item.Role) path=$full"}
            $lease=Open-SynapsePhysicalFileTransitionLease -ParentPath $npm -ParentChain $npmChain -Leaf $leaf -ExpectedFileId128 ([string]$state.FileId128) -ExpectedSha256 ([string]$state.Sha256) -ExpectedLength ([int64]$state.Length) -Context 'codex_launcher_plan_preimage'
            $leases+=,$lease
            $read=$lease.ReadUtf8(4MB)
            if([string]$read.Sha256-ine[string]$state.Sha256-or[int64]$read.Length-ne[int64]$state.Length){Die "SYNAPSE_CODEX_LAUNCHER_PREIMAGE_READ_DRIFT role=$($item.Role)"}
            $desiredBytes=[Text.UTF8Encoding]::new($false,$true).GetBytes([string]$item.Content)
            $sha=[Security.Cryptography.SHA256]::Create()
            try{$desiredSha=([BitConverter]::ToString($sha.ComputeHash($desiredBytes))).Replace('-','')}finally{$sha.Dispose()}
            $operation=if([string]$state.Sha256-ieq$desiredSha-and[int64]$state.Length-eq$desiredBytes.Length){'retain'}else{'replace'}
            if($operation-ceq'replace'){$allRetain=$false}
            $seedTargets+=,[ordered]@{ordinal=[int]$item.Ordinal;role=[string]$item.Role;path=$full;leaf=$leaf;operation=$operation;pre_file_id_128=([string]$state.FileId128).ToUpperInvariant();pre_sha256=([string]$state.Sha256).ToUpperInvariant();pre_length=[int64]$state.Length;desired_utf8_base64=[Convert]::ToBase64String($desiredBytes);desired_sha256=$desiredSha.ToUpperInvariant();desired_length=[int64]$desiredBytes.Length}
        }
        if($allRetain){foreach($lease in $leases){$lease.RequireExact('codex_launcher_idempotent')};return $null}
        $rootChain=@(Ensure-SynapsePhysicalDirectoryPath -Path $Root -Context 'codex_launcher_record_root')
        $installNonce=[Guid]::NewGuid().ToString('N').ToUpperInvariant()
        $seedPlan=[pscustomobject][ordered]@{install_nonce=$installNonce;record_root=[System.IO.Path]::GetFullPath($Root);record_root_file_id_128=([string]$rootChain[-1].file_id_128).ToUpperInvariant();npm_dir=$npm;npm_dir_chain=@($npmChain|ForEach-Object{[ordered]@{path=[string]$_.path;file_id_128=([string]$_.file_id_128).ToUpperInvariant()}});token_path=[System.IO.Path]::GetFullPath($TokenPath);tool_surface_snapshot_path=[System.IO.Path]::GetFullPath($ToolSurfaceSnapshotPath);target_count=3;targets=$seedTargets}
        $installId=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value (Get-SynapseCodexLauncherPlanSeed -Plan $seedPlan))).ToUpperInvariant()
        $targetsWithSlots=@($seedTargets|ForEach-Object{
            $copy=ConvertTo-SynapseCanonicalValue -Value $_
            $copy['stage_leaf']=if([string]$copy.operation-ceq'replace'){".synapse-codex-$($installId.Substring(0,32).ToLowerInvariant())-$($copy.role)-stage"}else{''}
            $copy['park_leaf']=if([string]$copy.operation-ceq'replace'){".synapse-codex-$($installId.Substring(0,32).ToLowerInvariant())-$($copy.role)-park"}else{''}
            $copy
        })
        foreach($target in @($targetsWithSlots|Where-Object{[string]$_.operation-ceq'replace'})){foreach($reserved in @([string]$target.stage_leaf,[string]$target.park_leaf)){if([bool](Get-SynapsePhysicalRelativeState -ParentPath $npm -ParentChain $npmChain -Leaf $reserved).Exists){Die "SYNAPSE_CODEX_LAUNCHER_RESERVED_LEAF_COLLISION install=$installId leaf=$reserved"}}}
        $planPayload=[ordered]@{schema='synapse_codex_launcher_install_plan/v1';state='planned_before_mutation';install_id=$installId;install_nonce=$installNonce;created_at_utc=[DateTime]::UtcNow.ToString('o');created_by_pid=$PID;record_root=[System.IO.Path]::GetFullPath($Root);record_root_file_id_128=([string]$rootChain[-1].file_id_128).ToUpperInvariant();npm_dir=$npm;npm_dir_chain=$seedPlan.npm_dir_chain;token_path=[System.IO.Path]::GetFullPath($TokenPath);tool_surface_snapshot_path=[System.IO.Path]::GetFullPath($ToolSurfaceSnapshotPath);target_count=3;targets=$targetsWithSlots}
        $planPayload.plan_sha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $planPayload)).ToUpperInvariant()
        $plan=Write-SynapseCodexLauncherInstallRecord -Root $Root -RootChain $rootChain -Leaf "install-$installId-plan.json" -Payload $planPayload -Purpose 'codex_launcher_plan'
        try{
            [void](Assert-SynapseCodexLauncherInstallPlan -Record $plan -Context 'codex_launcher_plan')
            foreach($lease in $leases){$lease.RequireExact('codex_launcher_plan_published')}
            return (Resume-SynapseCodexLauncherInstallTransactions -Root $Root -Context 'codex_launcher_new_install' -InitialPreimageLeases @($leases))
        }finally{$plan.Lease.Dispose()}
    }finally{foreach($lease in $leases){if($null-ne$lease){$lease.Dispose()}}}
}

function Install-CodexSynapseTokenLoader {
    param(
        [Parameter(Mandatory=$true)][string]$CodexCommandPath,
        [Parameter(Mandatory=$true)][string]$TokenPath,
        [Parameter(Mandatory=$true)][string]$CodexToolSurfaceSnapshotPath
    )

    $tokenFull=[System.IO.Path]::GetFullPath($TokenPath)
    $surfaceFull=[System.IO.Path]::GetFullPath($CodexToolSurfaceSnapshotPath)
    foreach($configuredPath in @([pscustomobject]@{Role='token';Path=$tokenFull},[pscustomobject]@{Role='tool_surface';Path=$surfaceFull})){
        if(([string]$configuredPath.Path).IndexOf("`r",[StringComparison]::Ordinal)-ge0-or([string]$configuredPath.Path).IndexOf("`n",[StringComparison]::Ordinal)-ge0){Die "SYNAPSE_CODEX_LAUNCHER_CONFIGURED_PATH_LINE_BREAK_REFUSED role=$($configuredPath.Role) path=$($configuredPath.Path)"}
    }
    $utf8Strict=[System.Text.UTF8Encoding]::new($false,$true)
    $tokenPathBase64=[Convert]::ToBase64String($utf8Strict.GetBytes($tokenFull))
    $surfacePathBase64=[Convert]::ToBase64String($utf8Strict.GetBytes($surfaceFull))

    $commandFull=[System.IO.Path]::GetFullPath($CodexCommandPath)
    $npmDir = Split-Path -Parent $commandFull
    if (-not $npmDir -or -not (Test-Path -LiteralPath $npmDir -PathType Container)) {
        Die "Cannot resolve Codex launcher directory from '$CodexCommandPath'."
    }

    $ps1Path = Join-Path $npmDir 'codex.ps1'
    $cmdPath = Join-Path $npmDir 'codex.cmd'
    $shPath = Join-Path $npmDir 'codex'
    $launcherTargets=[System.Collections.Generic.List[object]]::new()

    if (Test-Path -LiteralPath $ps1Path -PathType Leaf) {
        $ps1 = @'
#!/usr/bin/env pwsh
$basedir=Split-Path $MyInvocation.MyCommand.Definition -Parent

# Synapse MCP token loader: begin
$synapseConfigPath = Join-Path $env:USERPROFILE '.codex\config.toml'
$synapseEmbeddedTokenPathBase64 = '__SYNAPSE_TOKEN_PATH_BASE64__'
$synapseEmbeddedSurfacePathBase64 = '__SYNAPSE_SURFACE_PATH_BASE64__'
if (-not [string]::IsNullOrEmpty($env:SYNAPSE_CODEX_LAUNCHER_TOKEN_PATH_BASE64) -and $env:SYNAPSE_CODEX_LAUNCHER_TOKEN_PATH_BASE64 -cne $synapseEmbeddedTokenPathBase64) {
  Write-Error 'SYNAPSE_CODEX_LAUNCHER_TOKEN_PATH_CROSSBIND_FAILED remediation=rerun scripts\synapse-setup.ps1 to reinstall one coherent launcher generation'
  exit 1
}
if (-not [string]::IsNullOrEmpty($env:SYNAPSE_CODEX_LAUNCHER_SURFACE_PATH_BASE64) -and $env:SYNAPSE_CODEX_LAUNCHER_SURFACE_PATH_BASE64 -cne $synapseEmbeddedSurfacePathBase64) {
  Write-Error 'SYNAPSE_CODEX_LAUNCHER_SURFACE_PATH_CROSSBIND_FAILED remediation=rerun scripts\synapse-setup.ps1 to reinstall one coherent launcher generation'
  exit 1
}
$synapseTokenPath = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($synapseEmbeddedTokenPathBase64))
$synapseHasConfig = $false
$synapseConfigExists = $false
try {
  $synapseConfigAttributes = [IO.File]::GetAttributes($synapseConfigPath)
  $synapseConfigExists = $true
} catch [IO.FileNotFoundException] {
} catch [IO.DirectoryNotFoundException] {
} catch {
  Write-Error "SYNAPSE_CODEX_CONFIG_STATE_UNREADABLE path=$synapseConfigPath error=$($_.Exception.Message) remediation=repair Codex config permissions or rerun scripts\synapse-setup.ps1"
  exit 1
}
if ($synapseConfigExists) {
  if (($synapseConfigAttributes -band [IO.FileAttributes]::Directory) -or ($synapseConfigAttributes -band [IO.FileAttributes]::ReparsePoint)) {
    Write-Error "SYNAPSE_CODEX_CONFIG_TYPE_INVALID path=$synapseConfigPath attributes=$synapseConfigAttributes remediation=replace the unexpected directory/reparse point with the regular Codex config"
    exit 1
  }
  try {
    $synapseConfigBytes = [IO.File]::ReadAllBytes($synapseConfigPath)
    $synapseConfigText = [Text.UTF8Encoding]::new($false,$true).GetString($synapseConfigBytes)
    $synapseHasConfig = ($synapseConfigText -cmatch '(?:^|\r?\n)[ \t]*\[mcp_servers\.synapse\][ \t]*(?:#[^\r\n]*)?(?:\r?\n|$)')
  } catch {
    Write-Error "SYNAPSE_CODEX_CONFIG_UNREADABLE path=$synapseConfigPath remediation=repair Codex config permissions or rerun scripts\synapse-setup.ps1"
    exit 1
  }
}
if ($synapseHasConfig) {
  if (-not (Test-Path -LiteralPath $synapseTokenPath -PathType Leaf)) {
    Write-Error "SYNAPSE_CODEX_TOKEN_MISSING path=$synapseTokenPath remediation=run scripts\synapse-setup.ps1 to generate the bearer token"
    exit 1
  }
  try {
    $synapseTokenBytes = [IO.File]::ReadAllBytes($synapseTokenPath)
    $synapseTokenText = [Text.UTF8Encoding]::new($false,$true).GetString($synapseTokenBytes)
  } catch {
    Write-Error "SYNAPSE_CODEX_TOKEN_UNREADABLE path=$synapseTokenPath error=$($_.Exception.Message) remediation=repair the exact token file or rerun scripts\synapse-setup.ps1"
    exit 1
  }
  $synapseTokenMatch = [Text.RegularExpressions.Regex]::Match($synapseTokenText,'\A[ \t\r\n]*([0-9a-fA-F]{64})[ \t\r\n]*\z',[Text.RegularExpressions.RegexOptions]::CultureInvariant)
  if (-not $synapseTokenMatch.Success) {
    Write-Error "SYNAPSE_CODEX_TOKEN_INVALID path=$synapseTokenPath remediation=delete the malformed token and rerun scripts\synapse-setup.ps1"
    exit 1
  }
  $synapseToken = $synapseTokenMatch.Groups[1].Value
  if ($env:SYNAPSE_BEARER_TOKEN -ne $synapseToken) {
    $env:SYNAPSE_BEARER_TOKEN = $synapseToken
  }
  $synapseToolSurfacePath = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($synapseEmbeddedSurfacePathBase64))
  if (-not (Test-Path -LiteralPath $synapseToolSurfacePath -PathType Leaf)) {
    Write-Error "SYNAPSE_CODEX_TOOL_SURFACE_SNAPSHOT_MISSING path=$synapseToolSurfacePath remediation=run scripts\synapse-setup.ps1 to write the current daemon tools/list fingerprint before starting Codex"
    exit 1
  }
  try {
    $synapseSnapshotBytes = [IO.File]::ReadAllBytes($synapseToolSurfacePath)
    $synapseSnapshotText = [Text.UTF8Encoding]::new($false,$true).GetString($synapseSnapshotBytes)
    $synapseOriginalPSModulePath = $env:PSModulePath
    try {
      if ($PSVersionTable.PSEdition -eq 'Desktop') { $env:PSModulePath = Join-Path $PSHOME 'Modules' }
      $synapseToolSurface = $synapseSnapshotText | ConvertFrom-Json
    } finally {
      if ($null -eq $synapseOriginalPSModulePath) { Remove-Item Env:PSModulePath -ErrorAction SilentlyContinue } else { $env:PSModulePath = $synapseOriginalPSModulePath }
    }
  } catch {
    Write-Error "SYNAPSE_CODEX_TOOL_SURFACE_SNAPSHOT_UNREADABLE path=$synapseToolSurfacePath error=$($_.Exception.Message) remediation=repair the snapshot file or rerun scripts\synapse-setup.ps1"
    exit 1
  }
  $synapseToolSurfaceHash = [string]$synapseToolSurface.tool_surface_sha256
  $synapseToolSurfaceCount = [int]$synapseToolSurface.tool_count
  if ($synapseToolSurfaceHash -notmatch '^[0-9a-fA-F]{64}$' -or $synapseToolSurfaceCount -lt 1) {
    Write-Error "SYNAPSE_CODEX_TOOL_SURFACE_SNAPSHOT_INVALID path=$synapseToolSurfacePath remediation=delete the invalid snapshot and rerun scripts\synapse-setup.ps1"
    exit 1
  }
  $synapseStartSnapshotDir = Join-Path $env:LOCALAPPDATA 'synapse\codex-start-snapshots'
  $synapseStartSnapshotPath = Join-Path $synapseStartSnapshotDir ("codex-tool-surface-{0}-{1}.json" -f $PID, [Guid]::NewGuid().ToString('N'))
  try {
    [void][IO.Directory]::CreateDirectory($synapseStartSnapshotDir)
    $synapseSnapshotTemp = $synapseStartSnapshotPath + '.tmp-' + [Guid]::NewGuid().ToString('N')
    $synapseSnapshotStream = $null
    try {
      $synapseSnapshotStream = [IO.FileStream]::new($synapseSnapshotTemp,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None,4096,[IO.FileOptions]::WriteThrough)
      $synapseSnapshotStream.Write($synapseSnapshotBytes,0,$synapseSnapshotBytes.Length)
      $synapseSnapshotStream.Flush($true)
      $synapseSnapshotStream.Dispose()
      $synapseSnapshotStream = $null
      [IO.File]::Move($synapseSnapshotTemp,$synapseStartSnapshotPath)
      $synapseStartSnapshotReadback = [IO.File]::ReadAllBytes($synapseStartSnapshotPath)
      $synapseStartSnapshotMatches = ($synapseSnapshotBytes.Length -eq $synapseStartSnapshotReadback.Length)
      for ($synapseSnapshotIndex = 0; $synapseStartSnapshotMatches -and $synapseSnapshotIndex -lt $synapseSnapshotBytes.Length; $synapseSnapshotIndex++) {
        if ($synapseSnapshotBytes[$synapseSnapshotIndex] -ne $synapseStartSnapshotReadback[$synapseSnapshotIndex]) { $synapseStartSnapshotMatches = $false }
      }
      if (-not $synapseStartSnapshotMatches) {
        throw "SYNAPSE_CODEX_TOOL_SURFACE_START_SNAPSHOT_READBACK_MISMATCH path=$synapseStartSnapshotPath"
      }
    } finally {
      if ($null -ne $synapseSnapshotStream) { $synapseSnapshotStream.Dispose() }
      if (Test-Path -LiteralPath $synapseSnapshotTemp) { Remove-Item -LiteralPath $synapseSnapshotTemp -Force }
    }
  } catch {
    Write-Error "SYNAPSE_CODEX_TOOL_SURFACE_START_SNAPSHOT_FAILED path=$synapseStartSnapshotPath error=$($_.Exception.Message) remediation=repair permissions on %LOCALAPPDATA%\synapse\codex-start-snapshots before starting Codex"
    exit 1
  }
  $env:SYNAPSE_TOOL_SURFACE_HASH_AT_CODEX_START = $synapseToolSurfaceHash
  $env:SYNAPSE_TOOL_SURFACE_TOOL_COUNT_AT_CODEX_START = [string]$synapseToolSurfaceCount
  $env:SYNAPSE_TOOL_SURFACE_SNAPSHOT_AT_CODEX_START = $synapseStartSnapshotPath
}
