        printf '%s\n' "SYNAPSE_CODEX_TOOL_SURFACE_START_SNAPSHOT_FAILED source=$synapse_surface path=$synapse_start_surface remediation=repair the exact snapshot or permissions on $synapse_start_dir before starting Codex" >&2
