unset synapse_cfg synapse_localappdata synapse_tok_b64 synapse_surface_b64 synapse_tok synapse_file_token synapse_surface synapse_surface_values synapse_surface_hash synapse_surface_count synapse_start_dir synapse_start_surface synapse_node synapse_nonce synapse_has_cfg
