        [Parameter(Mandatory=$true)][ValidatePattern('^[0-9A-Fa-f]{64}$')][string]$ExpectedSha256,
        [ValidateRange(0,[long]::MaxValue)][long]$ExpectedLength,
        [Parameter(Mandatory=$true)][string]$Context
    )

    Ensure-SynapseAtomicFileType
    try {
        return [SynapseSetup.AtomicFileV2]::OpenPhysicalFileTransitionLease(
            (Get-SynapseNormalizedDirectoryPath -Path $ParentPath),
            (Get-SynapsePhysicalChainPaths -Chain $ParentChain),
