            $Leaf,
            $ExpectedFileId128,
            $ExpectedSha256,
            $ExpectedLength)
    } catch {
        Die "SYNAPSE_PHYSICAL_FILE_TRANSITION_LEASE_FAILED context=$Context parent=$ParentPath leaf=$Leaf expected_file_id_128=$ExpectedFileId128 expected_sha256=$ExpectedSha256 expected_length=$ExpectedLength error=$($_.Exception.Message) remediation=preserve all bytes; the transaction could not retain the exact pre/stage object through its no-replace transition"
    }
}

