    }
}

function Convert-SynapsePhysicalTransitionLeaseToReadLease {
    param(
        [Parameter(Mandatory=$true)]$TransitionLease,
        [Parameter(Mandatory=$true)][string]$ParentPath,
        [Parameter(Mandatory=$true)]$ParentChain,
        [Parameter(Mandatory=$true)][string]$Leaf,
        [Parameter(Mandatory=$true)][string]$ExpectedFileId128,
        [Parameter(Mandatory=$true)][string]$ExpectedSha256,
        [Parameter(Mandatory=$true)][long]$ExpectedLength,
        [Parameter(Mandatory=$true)][string]$Context
    )

    Ensure-SynapseAtomicFileType
    $guard = $null
    try {
        $guard = [SynapseSetup.AtomicFileV2]::BeginPhysicalDirectoryChangeGuard(
            (Get-SynapseNormalizedDirectoryPath -Path $ParentPath),
            (Get-SynapsePhysicalChainPaths -Chain $ParentChain),
            (Get-SynapsePhysicalChainFileIds -Chain $ParentChain),
            [string]$ParentChain[-1].file_id_128,
            $false)
        $TransitionLease.RequireExact("${Context}_before_release")
        $guard.RequireCleanCheckpoint("${Context}_before_release")
        $TransitionLease.Dispose()
        $readLease = Open-SynapsePhysicalFileReadLease -ParentPath $ParentPath -ParentChain $ParentChain -Leaf $Leaf -ExpectedFileId128 $ExpectedFileId128 -ExpectedSha256 $ExpectedSha256 -ExpectedLength $ExpectedLength -Context $Context
        $guard.RequireCleanCheckpoint("${Context}_after_read_seal")
        $guard.CompleteCleanGuard()
        $guard.Dispose()
        $guard = $null
        return $readLease
    } finally {
        if ($null -ne $guard) { $guard.Dispose() }
    }
}

function Convert-SynapsePhysicalReadLeaseToTransitionLease {
    param(
        [Parameter(Mandatory=$true)]$ReadLease,
        [Parameter(Mandatory=$true)][string]$ParentPath,
        [Parameter(Mandatory=$true)]$ParentChain,
        [Parameter(Mandatory=$true)][string]$Leaf,
        [Parameter(Mandatory=$true)][string]$ExpectedFileId128,
        [Parameter(Mandatory=$true)][string]$ExpectedSha256,
        [Parameter(Mandatory=$true)][long]$ExpectedLength,
        [Parameter(Mandatory=$true)][string]$Context
    )

    Ensure-SynapseAtomicFileType
    $guard = $null
    try {
        $guard = [SynapseSetup.AtomicFileV2]::BeginPhysicalDirectoryChangeGuard(
            (Get-SynapseNormalizedDirectoryPath -Path $ParentPath),
            (Get-SynapsePhysicalChainPaths -Chain $ParentChain),
            (Get-SynapsePhysicalChainFileIds -Chain $ParentChain),
            [string]$ParentChain[-1].file_id_128,
            $false)
        $ReadLease.RequireExact("${Context}_before_release")
        $guard.RequireCleanCheckpoint("${Context}_before_release")
        $ReadLease.Dispose()
        $transitionLease = Open-SynapsePhysicalFileTransitionLease -ParentPath $ParentPath -ParentChain $ParentChain -Leaf $Leaf -ExpectedFileId128 $ExpectedFileId128 -ExpectedSha256 $ExpectedSha256 -ExpectedLength $ExpectedLength -Context $Context
        $guard.RequireCleanCheckpoint("${Context}_after_transition_seal")
        $guard.CompleteCleanGuard()
        $guard.Dispose()
        $guard = $null
        return $transitionLease
    } finally {
        if ($null -ne $guard) { $guard.Dispose() }
    }
}

function Convert-SynapseAuthorityCanonicalTransitionToSharedReadLease {
    param(
        [Parameter(Mandatory=$true)]$Transition,
        [Parameter(Mandatory=$true)][string]$Context
    )
    if ($null -eq $Transition.CanonicalLease) {
        Die "SYNAPSE_AUTHORITY_CANONICAL_TRANSITION_LEASE_MISSING context=$Context purpose=$($Transition.purpose)"
    }
    if ($null -ne $Transition.PSObject.Properties['CanonicalLeaseIsSharedRead'] -and
        [bool]$Transition.CanonicalLeaseIsSharedRead) {
        $Transition.CanonicalLease.RequireExact("${Context}_already_shared")
        return
    }
    $Transition.CanonicalLease = Convert-SynapsePhysicalTransitionLeaseToReadLease `
        -TransitionLease $Transition.CanonicalLease `
        -ParentPath $Transition.parent `
        -ParentChain $Transition.parent_chain `
        -Leaf $Transition.leaf `
        -ExpectedFileId128 $Transition.post_file_id_128 `
        -ExpectedSha256 $Transition.post_sha256 `
        -ExpectedLength ([int64]$Transition.post_length) `
        -Context $Context
    $Transition | Add-Member -NotePropertyName CanonicalLeaseIsSharedRead -NotePropertyValue $true -Force
}

function Convert-SynapseAuthorityCanonicalSharedReadToTransitionLease {
    param(
        [Parameter(Mandatory=$true)]$Transition,
        [Parameter(Mandatory=$true)][string]$Context
    )
    if ($null -eq $Transition.CanonicalLease) {
        Die "SYNAPSE_AUTHORITY_CANONICAL_READ_LEASE_MISSING context=$Context purpose=$($Transition.purpose)"
    }
    if ($null -eq $Transition.PSObject.Properties['CanonicalLeaseIsSharedRead'] -or
        -not [bool]$Transition.CanonicalLeaseIsSharedRead) {
        $Transition.CanonicalLease.RequireExact("${Context}_already_transition")
        return
    }
    $Transition.CanonicalLease = Convert-SynapsePhysicalReadLeaseToTransitionLease `
        -ReadLease $Transition.CanonicalLease `
        -ParentPath $Transition.parent `
        -ParentChain $Transition.parent_chain `
        -Leaf $Transition.leaf `
        -ExpectedFileId128 $Transition.post_file_id_128 `
        -ExpectedSha256 $Transition.post_sha256 `
        -ExpectedLength ([int64]$Transition.post_length) `
        -Context $Context
    $Transition.CanonicalLeaseIsSharedRead = $false
}

