function Assert-SynapsePhysicalDirectoryChainDescriptor {
    param(
        [Parameter(Mandatory=$true)]$Chain,
        [Parameter(Mandatory=$true)][string]$ExpectedPath,
        [Parameter(Mandatory=$true)][string]$Context
    )

    $entries = @($Chain)
    if ($entries.Count -lt 1 -or $entries.Count -gt 64) {
        Die "SYNAPSE_PHYSICAL_CHAIN_COUNT_INVALID context=$Context count=$($entries.Count) min=1 max=64 remediation=preserve the transaction; its physical ancestor chain is malformed"
    }
    $seen = New-SynapseCaseInsensitiveMap
    foreach ($entry in $entries) {
        $path = [System.IO.Path]::GetFullPath([string]$entry.path)
        if ($path -ine [System.IO.Path]::GetPathRoot($path)) { $path = $path.TrimEnd('\') }
        $fileId = [string]$entry.file_id_128
        if ($fileId -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or $seen.ContainsKey($path)) {
            Die "SYNAPSE_PHYSICAL_CHAIN_ENTRY_INVALID context=$Context path=$path file_id_128=$fileId remediation=the durable physical chain must contain unique paths and full FILE_ID_INFO identities"
        }
        $seen[$path] = $true
    }
    $last = [System.IO.Path]::GetFullPath([string]$entries[-1].path)
    if ($last -ine [System.IO.Path]::GetPathRoot($last)) { $last = $last.TrimEnd('\') }
    $expected = [System.IO.Path]::GetFullPath($ExpectedPath)
    if ($expected -ine [System.IO.Path]::GetPathRoot($expected)) { $expected = $expected.TrimEnd('\') }
    if ($last -ine $expected) {
        Die "SYNAPSE_PHYSICAL_CHAIN_TERMINUS_MISMATCH context=$Context expected=$expected actual=$last remediation=the journaled physical parent chain does not terminate at the authorized directory"
    }
    return $entries
}

function Ensure-SynapsePhysicalDirectoryPath {
    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$Context
    )

    Ensure-SynapseAtomicFileType
    $full = Get-SynapseNormalizedDirectoryPath -Path $Path
    $missing = [System.Collections.Generic.List[string]]::new()
    $cursor = $full
    while (-not [System.IO.Directory]::Exists($cursor)) {
        if ([System.IO.File]::Exists($cursor)) {
            Die "SYNAPSE_PHYSICAL_DIRECTORY_PATH_COLLISION context=$Context path=$cursor remediation=replace the non-directory path before setup creates its bounded physical directory chain"
        }
        $leaf = Split-Path -Leaf $cursor
        if ([string]::IsNullOrWhiteSpace($leaf)) {
            Die "SYNAPSE_PHYSICAL_DIRECTORY_ANCESTOR_MISSING context=$Context path=$full remediation=the volume root must exist before setup can create relative directories"
        }
        $missing.Insert(0, $leaf)
        $next = Split-Path -Parent $cursor
        if ([string]::IsNullOrWhiteSpace($next) -or $next -eq $cursor) {
            Die "SYNAPSE_PHYSICAL_DIRECTORY_ANCESTOR_INVALID context=$Context path=$full cursor=$cursor"
        }
        $cursor = Get-SynapseNormalizedDirectoryPath -Path $next
    }
    $chain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $cursor)
    foreach ($leaf in $missing) {
        try {
            $created = [SynapseSetup.AtomicFileV2]::CreatePhysicalDirectoryRelative(
                $cursor,
                (Get-SynapsePhysicalChainPaths -Chain $chain),
                (Get-SynapsePhysicalChainFileIds -Chain $chain),
                [string]$leaf)
        } catch {
            Die "SYNAPSE_PHYSICAL_DIRECTORY_CREATE_FAILED context=$Context parent=$cursor leaf=$leaf error=$($_.Exception.Message) remediation=preserve any colliding object; setup only creates absent non-reparse directories relative to a pinned parent"
        }
        $cursor = Get-SynapseNormalizedDirectoryPath -Path ([string]$created.Path)
        $chain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $cursor)
    }
    if ($cursor -ine $full) {
        Die "SYNAPSE_PHYSICAL_DIRECTORY_CREATE_PATH_MISMATCH context=$Context expected=$full actual=$cursor"
    }
    return $chain
}

