function ConvertFrom-SynapseBundledProfilesManifestText {
    param(
        [Parameter(Mandatory=$true)][string]$Text,
        [Parameter(Mandatory=$true)][string]$ManifestPath
    )

    try { $manifest = $Text | ConvertFrom-Json -ErrorAction Stop } catch {
        Die "SYNAPSE_BUNDLED_PROFILES_MANIFEST_INVALID_JSON path=$ManifestPath error=$($_.Exception.Message) remediation=manifest exists but is unreadable; inspect it before setup can safely decide which deployed profiles it owns"
    }
    if ([int]$manifest.schema_version -ne 1 -or
        [string]$manifest.owner -ne 'synapse-setup:bundled-profiles') {
        Die "SYNAPSE_BUNDLED_PROFILES_MANIFEST_IDENTITY_INVALID path=$ManifestPath schema_version=$($manifest.schema_version) owner=$($manifest.owner) remediation=setup refuses an unknown ownership manifest"
    }
    $files = @($manifest.files)
    if ($files.Count -gt 512 -or [int]$manifest.bundled_file_count -ne $files.Count) {
        Die "SYNAPSE_BUNDLED_PROFILES_MANIFEST_FILE_BOUND_INVALID path=$ManifestPath declared=$($manifest.bundled_file_count) actual=$($files.Count) max=512"
    }
    $seen = New-SynapseCaseInsensitiveMap
    foreach ($file in $files) {
        $relative = Assert-SynapseProfileRelativePathSafe -RelativePath ([string]$file.relative_path) -Context 'previous_bundled_profiles_manifest'
        if ($relative -match '/' -or
            (Test-SynapseSetupProfileMetadataRelativePath -RelativePath $relative) -or
            $seen.ContainsKey($relative) -or
            [string]$file.sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or
            [int64]$file.length -lt 0) {
            Die "SYNAPSE_BUNDLED_PROFILES_MANIFEST_ENTRY_INVALID path=$ManifestPath relative_path=$relative sha256=$($file.sha256) length=$($file.length) remediation=ownership entries must be bounded unique top-level regular files outside setup metadata"
        }
        $seen[$relative] = $true
    }
    $quarantined = @($manifest.quarantined_retired)
    if ($quarantined.Count -gt 512) {
        Die "SYNAPSE_BUNDLED_PROFILES_MANIFEST_QUARANTINE_BOUND_INVALID path=$ManifestPath count=$($quarantined.Count) max=512"
    }
    $quarantineSeen = New-SynapseCaseInsensitiveMap
    foreach ($record in $quarantined) {
        $relative = Assert-SynapseProfileRelativePathSafe -RelativePath ([string]$record.relative_path) -Context 'previous_bundled_profiles_quarantine_record'
        $quarantinePath = [System.IO.Path]::GetFullPath([string]$record.quarantine_path)
        if ($relative -match '/' -or [string]$record.sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or
            $quarantineSeen.ContainsKey($quarantinePath)) {
            Die "SYNAPSE_BUNDLED_PROFILES_MANIFEST_QUARANTINE_ENTRY_INVALID path=$ManifestPath relative_path=$relative quarantine_path=$quarantinePath sha256=$($record.sha256)"
        }
        $quarantineSeen[$quarantinePath] = $true
    }
    return $manifest
}

function Move-SynapsePhysicalRelativeEntryNoReplace {
    param(
        [Parameter(Mandatory=$true)][string]$SourceParentPath,
        [Parameter(Mandatory=$true)]$SourceParentChain,
        [Parameter(Mandatory=$true)][string]$SourceLeaf,
        [Parameter(Mandatory=$true)][string]$ExpectedSourceFileId128,
        [Parameter(Mandatory=$true)][string]$DestinationParentPath,
        [Parameter(Mandatory=$true)]$DestinationParentChain,
        [Parameter(Mandatory=$true)][string]$DestinationLeaf,
        [switch]$Directory,
        [string]$ExpectedSha256 = '',
        [long]$ExpectedLength = -1,
        [Parameter(Mandatory=$true)][string]$Context
    )

    Ensure-SynapseAtomicFileType
    try {
        if(-not [bool]$Directory -and $null-ne$script:SynapseDeploymentAllocationContext){
            $retained=@($script:SynapseDeploymentAllocationContext.ArtifactOrder|ForEach-Object{$script:SynapseDeploymentAllocationContext.Artifacts[$_]}|Where-Object{
                [string]$_.file_id_128 -ieq $ExpectedSourceFileId128 -and $null-ne$_.handle
            })
            if($retained.Count-gt1){Die "SYNAPSE_PHYSICAL_RELATIVE_MOVE_RETAINED_OWNER_AMBIGUOUS context=$Context file_id_128=$ExpectedSourceFileId128 count=$($retained.Count)"}
            if($retained.Count-eq1){
                $retained[0].handle.RequireExact("${Context}_retained_before")
                $moved=$retained[0].handle.MoveNoReplace(
                    (Get-SynapseNormalizedDirectoryPath -Path $DestinationParentPath),
                    (Get-SynapsePhysicalChainPaths -Chain $DestinationParentChain),
                    (Get-SynapsePhysicalChainFileIds -Chain $DestinationParentChain),
                    $DestinationLeaf)
                $retained[0].handle.RequireExact("${Context}_retained_after")
                return $moved
            }
        }
        return [SynapseSetup.AtomicFileV2]::RenamePhysicalEntryRelativeNoReplace(
            (Get-SynapseNormalizedDirectoryPath -Path $SourceParentPath),
            (Get-SynapsePhysicalChainPaths -Chain $SourceParentChain),
            (Get-SynapsePhysicalChainFileIds -Chain $SourceParentChain),
            $SourceLeaf,
            $ExpectedSourceFileId128,
            (Get-SynapseNormalizedDirectoryPath -Path $DestinationParentPath),
            (Get-SynapsePhysicalChainPaths -Chain $DestinationParentChain),
            (Get-SynapsePhysicalChainFileIds -Chain $DestinationParentChain),
            $DestinationLeaf,
            [bool]$Directory,
            $ExpectedSha256,
            $ExpectedLength)
    } catch {
        Die "SYNAPSE_PHYSICAL_RELATIVE_MOVE_FAILED context=$Context source_parent=$SourceParentPath source_leaf=$SourceLeaf destination_parent=$DestinationParentPath destination_leaf=$DestinationLeaf expected_file_id_128=$ExpectedSourceFileId128 error=$($_.Exception.Message) remediation=the no-replace exact-object transition refused a collision or identity change; preserve all current bytes"
    }
}

function Remove-SynapsePhysicalRelativeEntryExact {
    param(
        [Parameter(Mandatory=$true)][string]$ParentPath,
        [Parameter(Mandatory=$true)]$ParentChain,
        [Parameter(Mandatory=$true)][string]$Leaf,
        [Parameter(Mandatory=$true)][string]$ExpectedFileId128,
        [switch]$Directory,
        [string]$ExpectedSha256 = '',
        [long]$ExpectedLength = -1,
        [Parameter(Mandatory=$true)][string]$Context
    )

    Ensure-SynapseAtomicFileType
    try {
        [SynapseSetup.AtomicFileV2]::DeletePhysicalEntryRelative(
            (Get-SynapseNormalizedDirectoryPath -Path $ParentPath),
            (Get-SynapsePhysicalChainPaths -Chain $ParentChain),
            (Get-SynapsePhysicalChainFileIds -Chain $ParentChain),
            $Leaf,
            $ExpectedFileId128,
            [bool]$Directory,
            $ExpectedSha256,
            $ExpectedLength)
    } catch {
        Die "SYNAPSE_PHYSICAL_RELATIVE_DELETE_FAILED context=$Context parent=$ParentPath leaf=$Leaf expected_file_id_128=$ExpectedFileId128 directory=$([bool]$Directory) error=$($_.Exception.Message) remediation=preserve the object; cleanup only deletes the exact journaled file or empty directory"
    }
}

function Remove-SynapsePhysicalEnumeratedRelativeEntryExact {
    param(
        [Parameter(Mandatory=$true)][string]$ParentPath,
        [Parameter(Mandatory=$true)]$ParentChain,
        [Parameter(Mandatory=$true)][string]$Leaf,
        [Parameter(Mandatory=$true)][string]$ExpectedFileId128,
        [switch]$Directory,
        [string]$ExpectedSha256 = '',
        [long]$ExpectedLength = -1,
        [Parameter(Mandatory=$true)][string]$Context
    )

    Ensure-SynapseAtomicFileType
    try {
        [SynapseSetup.AtomicFileV2]::DeletePhysicalEnumeratedEntryRelative(
            (Get-SynapseNormalizedDirectoryPath -Path $ParentPath),
            (Get-SynapsePhysicalChainPaths -Chain $ParentChain),
            (Get-SynapsePhysicalChainFileIds -Chain $ParentChain),
            $Leaf,
            $ExpectedFileId128,
            [bool]$Directory,
            $ExpectedSha256,
            $ExpectedLength)
    } catch {
        Die "SYNAPSE_PHYSICAL_ENUMERATED_RELATIVE_DELETE_FAILED context=$Context parent=$ParentPath leaf=$Leaf expected_file_id_128=$ExpectedFileId128 directory=$([bool]$Directory) error=$($_.Exception.Message) remediation=preserve the marker-bound tree; cleanup only deletes the exact enumerated file or empty directory"
    }
}

function Test-SynapsePhysicalStateExact {
    param(
        [Parameter(Mandatory=$true)]$State,
        [bool]$ExpectedExists,
        [string]$ExpectedFileId128 = '',
        [string]$ExpectedSha256 = '',
        [long]$ExpectedLength = -1
    )

    if ([bool]$State.Exists -ne $ExpectedExists) { return $false }
    if (-not $ExpectedExists) { return $true }
    if (-not [string]::IsNullOrWhiteSpace($ExpectedFileId128) -and [string]$State.FileId128 -ine $ExpectedFileId128) { return $false }
    if (-not [string]::IsNullOrWhiteSpace($ExpectedSha256) -and [string]$State.Sha256 -ine $ExpectedSha256) { return $false }
    if ($ExpectedLength -ge 0 -and [int64]$State.Length -ne $ExpectedLength) { return $false }
    return $true
}





function Get-SynapseBundledProfilesTransactionPlanSha256 {
    param([Parameter(Mandatory=$true)]$Descriptor)

    $static = ConvertTo-SynapseCanonicalValue -Value $Descriptor
    if ($static -is [System.Collections.IDictionary]) {
        [void]$static.Remove('static_plan_sha256')
    }
    return (Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $static)).ToUpperInvariant()
}

function Assert-SynapseBundledProfilesTransactionDescriptor {
    param(
        [Parameter(Mandatory=$true)]$Descriptor,
        [Parameter(Mandatory=$true)][string]$ProfilesDir,
        [Parameter(Mandatory=$true)][string]$TransactionRoot
    )

    $profilesFull = Get-SynapseNormalizedDirectoryPath -Path $ProfilesDir
    $transactionFull = Get-SynapseNormalizedDirectoryPath -Path $TransactionRoot
    $profilesParent = Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $profilesFull)
    $profilesLeaf = Split-Path -Leaf $profilesFull
    $transactionLeaf = Split-Path -Leaf $transactionFull
    if ([string]$Descriptor.schema -cne 'synapse_bundled_profiles_transaction/v3' -or
        (Get-SynapseNormalizedDirectoryPath -Path ([string]$Descriptor.profiles_dir)) -ine $profilesFull -or
        (Get-SynapseNormalizedDirectoryPath -Path ([string]$Descriptor.profiles_parent)) -ine $profilesParent -or
        [string]$Descriptor.profiles_leaf -cne $profilesLeaf -or
        (Get-SynapseNormalizedDirectoryPath -Path ([string]$Descriptor.transaction_root)) -ine $transactionFull -or
        [string]$Descriptor.transaction_leaf -cne $transactionLeaf -or
        $transactionLeaf -notmatch '^deployment-\d{8}T\d{9}Z-\d+$' -or
        $Descriptor.profiles_root_pre_existed -isnot [bool]) {
        Die "SYNAPSE_PROFILE_ROOT_TRANSACTION_IDENTITY_INVALID schema=$($Descriptor.schema) profiles_dir=$($Descriptor.profiles_dir) transaction_root=$($Descriptor.transaction_root) remediation=preserve the transaction; recovery only accepts its exact v3 root-object descriptor"
    }
    $parentChain = @(Assert-SynapsePhysicalDirectoryChainDescriptor -Chain $Descriptor.profiles_parent_chain -ExpectedPath $profilesParent -Context 'profile_transaction_parent')
    $transactionChain = @(Assert-SynapsePhysicalDirectoryChainDescriptor -Chain $Descriptor.transaction_root_chain -ExpectedPath $transactionFull -Context 'profile_transaction_root')
    $currentParentChain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $profilesParent)
    $currentTransactionChain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $transactionFull)
    if ((Get-SynapseCanonicalJson -Value $currentParentChain) -cne (Get-SynapseCanonicalJson -Value $parentChain) -or
        (Get-SynapseCanonicalJson -Value $currentTransactionChain) -cne (Get-SynapseCanonicalJson -Value $transactionChain)) {
        Die "SYNAPSE_PROFILE_ROOT_TRANSACTION_PHYSICAL_CHAIN_DRIFT profiles_parent=$profilesParent transaction_root=$transactionFull remediation=an ancestor or transaction directory object changed after the durable plan; preserve all current objects"
    }
    if ([string]$Descriptor.profiles_root_file_id_128 -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or
        [string]$Descriptor.volume_serial_number -notmatch '^[0-9A-Fa-f]{8}$' -or
        [string]$Descriptor.volume_filesystem -notin @('NTFS','ReFS') -or
        [string]$Descriptor.work_leaf -cne 'profile-root.work' -or
        [string]$Descriptor.manifest_relative_path -cne $script:SynapseBundledProfilesManifestFileName -or
        [string]$Descriptor.installed_manifest_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or
        [string]$Descriptor.source_manifest_sha256 -notmatch '^[0-9A-Fa-f]{64}$') {
        Die "SYNAPSE_PROFILE_ROOT_TRANSACTION_STATIC_IDENTITY_INVALID root_file_id_128=$($Descriptor.profiles_root_file_id_128) filesystem=$($Descriptor.volume_filesystem) serial=$($Descriptor.volume_serial_number) remediation=profile recovery requires one stable local volume and exact root generation identity"
    }
    Ensure-SynapseAtomicFileType
    $volume = [SynapseSetup.AtomicFileV2]::GetStableLocalVolume($profilesParent)
    $transactionVolume = [SynapseSetup.AtomicFileV2]::GetStableLocalVolume($transactionFull)
    $expectedSerial = '{0:X8}' -f [uint32]$volume.VolumeSerialNumber
    if ($expectedSerial -ine [string]$Descriptor.volume_serial_number -or
        [string]$volume.FileSystemName -ine [string]$Descriptor.volume_filesystem -or
        [uint32]$volume.VolumeSerialNumber -ne [uint32]$transactionVolume.VolumeSerialNumber) {
        Die "SYNAPSE_PROFILE_ROOT_TRANSACTION_VOLUME_MISMATCH expected_serial=$($Descriptor.volume_serial_number) actual_serial=$expectedSerial profiles_fs=$($volume.FileSystemName) transaction_fs=$($transactionVolume.FileSystemName) remediation=root publication is supported only within one journaled local stable-ID volume"
    }

    $sourceRecords = @($Descriptor.source_entries)
    $retiredRecords = @($Descriptor.retired_entries)
    $carriedQuarantineRecords = @($Descriptor.carried_quarantine_entries)
    if ($sourceRecords.Count -lt 1 -or $sourceRecords.Count -gt 512 -or $retiredRecords.Count -gt 512 -or
        $carriedQuarantineRecords.Count -gt 512 -or ($retiredRecords.Count + $carriedQuarantineRecords.Count) -gt 512) {
        Die "SYNAPSE_PROFILE_ROOT_TRANSACTION_RECORD_BOUND_INVALID source_count=$($sourceRecords.Count) retired_count=$($retiredRecords.Count) carried_quarantine_count=$($carriedQuarantineRecords.Count) max=512"
    }
    $relativeSeen = New-SynapseCaseInsensitiveMap
    foreach ($record in @($sourceRecords + $retiredRecords)) {
        $relative = Assert-SynapseProfileRelativePathSafe -RelativePath ([string]$record.relative_path) -Context 'profile_root_transaction_record'
        if ($relative -match '/' -or (Test-SynapseSetupProfileMetadataRelativePath -RelativePath $relative) -or $relativeSeen.ContainsKey($relative)) {
            Die "SYNAPSE_PROFILE_ROOT_TRANSACTION_RELATIVE_INVALID relative_path=$relative remediation=the bounded root-object transaction accepts unique top-level active profile files only"
        }
        $relativeSeen[$relative] = $true
        foreach ($side in @('pre','post')) {
            $exists = [bool]$record."${side}_existed"
            $sha = [string]$record."${side}_sha256"
            $fileId = [string]$record."${side}_file_id_128"
            $length = [int64]$record."${side}_length"
            if (($exists -and ($sha -notmatch '^[0-9A-Fa-f]{64}$' -or $fileId -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or $length -lt 0)) -or
                (-not $exists -and (-not [string]::IsNullOrWhiteSpace($sha) -or -not [string]::IsNullOrWhiteSpace($fileId)))) {
                Die "SYNAPSE_PROFILE_ROOT_TRANSACTION_RECORD_STATE_INVALID relative_path=$relative side=$side exists=$exists sha256=$sha file_id_128=$fileId length=$length"
            }
        }
    }
    foreach($record in $sourceRecords){if(-not [bool]$record.post_existed){Die "SYNAPSE_PROFILE_ROOT_TRANSACTION_SOURCE_POST_ABSENT relative_path=$($record.relative_path)"}}
    foreach($record in $retiredRecords){if(-not [bool]$record.pre_existed -or [bool]$record.post_existed){Die "SYNAPSE_PROFILE_ROOT_TRANSACTION_RETIRED_STATE_INVALID relative_path=$($record.relative_path)"}}
    if (-not [bool]$Descriptor.profiles_root_pre_existed -and (@($sourceRecords | Where-Object pre_existed).Count -gt 0 -or $retiredRecords.Count -gt 0 -or $carriedQuarantineRecords.Count -gt 0 -or [bool]$Descriptor.manifest_entry.pre_existed)) {
        Die 'SYNAPSE_PROFILE_ROOT_TRANSACTION_ABSENT_ROOT_PREIMAGE_INVALID remediation=an absent prior root cannot contain owned file preimages'
    }
    $manifestRecord = $Descriptor.manifest_entry
    if ([string]$manifestRecord.relative_path -cne $script:SynapseBundledProfilesManifestFileName -or
        $manifestRecord.pre_existed -isnot [bool] -or $manifestRecord.post_existed -isnot [bool] -or -not [bool]$manifestRecord.post_existed -or
        ([bool]$manifestRecord.pre_existed -and ([string]$manifestRecord.pre_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [string]$manifestRecord.pre_file_id_128 -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or [int64]$manifestRecord.pre_length -lt 1)) -or
        (-not [bool]$manifestRecord.pre_existed -and (-not [string]::IsNullOrWhiteSpace([string]$manifestRecord.pre_sha256) -or -not [string]::IsNullOrWhiteSpace([string]$manifestRecord.pre_file_id_128))) -or
        [string]$manifestRecord.post_sha256 -ine [string]$Descriptor.installed_manifest_sha256 -or
        [string]$manifestRecord.post_file_id_128 -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or
        [int64]$manifestRecord.post_length -lt 1) {
        Die "SYNAPSE_PROFILE_ROOT_TRANSACTION_MANIFEST_RECORD_INVALID relative_path=$($manifestRecord.relative_path) post_sha256=$($manifestRecord.post_sha256) post_file_id_128=$($manifestRecord.post_file_id_128)"
    }
    $candidateOwned = @($Descriptor.candidate_owned_entries)
    $priorOwned = @($Descriptor.prior_owned_entries)
    if ($candidateOwned.Count -ne ($sourceRecords.Count + $retiredRecords.Count + $carriedQuarantineRecords.Count + 1) -or $candidateOwned.Count -gt 1024 -or $priorOwned.Count -gt 1024) {
        Die "SYNAPSE_PROFILE_ROOT_TRANSACTION_OWNED_BOUND_INVALID candidate_count=$($candidateOwned.Count) prior_count=$($priorOwned.Count) max=1024"
    }
    $candidateOwnedSeen=New-SynapseCaseInsensitiveMap
    foreach ($owned in $candidateOwned) {
        $relative = Assert-SynapseProfileRelativePathSafe -RelativePath ([string]$owned.relative_path) -Context 'profile_root_owned_entry'
        if ($candidateOwnedSeen.ContainsKey($relative) -or [string]$owned.file_id_128 -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or
            [string]$owned.sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [int64]$owned.length -lt 0) {
            Die "SYNAPSE_PROFILE_ROOT_TRANSACTION_OWNED_ENTRY_INVALID relative_path=$relative file_id_128=$($owned.file_id_128) sha256=$($owned.sha256) length=$($owned.length)"
        }
        $candidateOwnedSeen[$relative]=$owned
    }
    $priorOwnedSeen=New-SynapseCaseInsensitiveMap
    foreach ($owned in $priorOwned) {
        $relative = Assert-SynapseProfileRelativePathSafe -RelativePath ([string]$owned.relative_path) -Context 'profile_root_prior_owned_entry'
        if ($priorOwnedSeen.ContainsKey($relative) -or [string]$owned.file_id_128 -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or [string]$owned.sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [int64]$owned.length -lt 0) { Die "SYNAPSE_PROFILE_ROOT_TRANSACTION_PRIOR_OWNED_ENTRY_INVALID relative_path=$relative" }
        $priorOwnedSeen[$relative]=$owned
    }
    $artifacts = @($Descriptor.profile_artifacts)
    if ($artifacts.Count -lt 1 -or $artifacts.Count -gt 128) {
        Die "SYNAPSE_PROFILE_ROOT_TRANSACTION_ARTIFACT_BOUND_INVALID count=$($artifacts.Count) max=128"
    }
    $artifactSeen = New-SynapseCaseInsensitiveMap
    foreach ($artifact in $artifacts) {
        $leaf = [string]$artifact.leaf
        if ([System.IO.Path]::GetFileName($leaf) -cne $leaf -or $leaf -in @('.','..') -or $artifactSeen.ContainsKey($leaf) -or
            $artifact.directory -isnot [bool] -or
            @($artifact.allowed_file_ids_128).Count -lt 1 -or
            @($artifact.allowed_file_ids_128 | Where-Object { [string]$_ -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' }).Count -gt 0 -or
            ((-not [bool]$artifact.directory) -and (@($artifact.allowed_sha256).Count -lt 1 -or @($artifact.allowed_sha256 | Where-Object { [string]$_ -notmatch '^[0-9A-Fa-f]{64}$' }).Count -gt 0)) -or
            ([bool]$artifact.directory -and @($artifact.allowed_sha256).Count -ne 0)) {
            Die "SYNAPSE_PROFILE_ROOT_TRANSACTION_ARTIFACT_INVALID leaf=$leaf remediation=cleanup authority is limited to unique direct transaction children with exact allowed FILE_ID_INFO values"
        }
        $artifactSeen[$leaf] = $artifact
    }
    # Recovery must derive the same lifecycle namespace from the immutable
    # records; a self-consistent hash alone is not authority to seal or delete
    # an unrelated exact-ID object under a reserved-looking leaf.
    $sortedSourceRelatives = @($sourceRecords | ForEach-Object { [string]$_.relative_path } | Sort-Object)
    $sourceRelatives = @($sourceRecords | ForEach-Object { [string]$_.relative_path })
    $sortedRetiredRelatives = @($retiredRecords | ForEach-Object { [string]$_.relative_path } | Sort-Object)
    $retiredRelatives = @($retiredRecords | ForEach-Object { [string]$_.relative_path })
    if ((Get-SynapseCanonicalJson -Value $sourceRelatives) -cne (Get-SynapseCanonicalJson -Value $sortedSourceRelatives) -or
        (Get-SynapseCanonicalJson -Value $retiredRelatives) -cne (Get-SynapseCanonicalJson -Value $sortedRetiredRelatives)) {
        Die 'SYNAPSE_PROFILE_ROOT_TRANSACTION_RECORD_ORDER_INVALID remediation=source and retirement records must retain their deterministic ordinal lifecycle binding'
    }
    $assertOwnedEntry = {
        param($Map,[string]$Relative,[string]$FileId128,[string]$Sha256,[int64]$Length,[string]$Context)
        if (-not $Map.ContainsKey($Relative)) { Die "SYNAPSE_PROFILE_ROOT_TRANSACTION_OWNED_BINDING_MISSING context=$Context relative_path=$Relative" }
        $owned = $Map[$Relative]
        if ([string]$owned.file_id_128 -ine $FileId128 -or [string]$owned.sha256 -ine $Sha256 -or [int64]$owned.length -ne $Length) {
            Die "SYNAPSE_PROFILE_ROOT_TRANSACTION_OWNED_BINDING_MISMATCH context=$Context relative_path=$Relative expected_file_id_128=$FileId128 actual_file_id_128=$($owned.file_id_128)"
        }
    }
    $assertArtifact = {
        param([string]$Leaf,[bool]$Directory,[string]$FileId128,[string]$Sha256,[string]$Context)
        if (-not $artifactSeen.ContainsKey($Leaf)) { Die "SYNAPSE_PROFILE_ROOT_TRANSACTION_ARTIFACT_BINDING_MISSING context=$Context leaf=$Leaf" }
        $artifact = $artifactSeen[$Leaf]
        $ids = @($artifact.allowed_file_ids_128)
        $hashes = @($artifact.allowed_sha256)
        if ([bool]$artifact.directory -ne $Directory -or $ids.Count -ne 1 -or [string]$ids[0] -ine $FileId128 -or
            ($Directory -and $hashes.Count -ne 0) -or
            (-not $Directory -and ($hashes.Count -ne 1 -or [string]$hashes[0] -ine $Sha256))) {
            Die "SYNAPSE_PROFILE_ROOT_TRANSACTION_ARTIFACT_BINDING_MISMATCH context=$Context leaf=$Leaf expected_file_id_128=$FileId128"
        }
    }
    $expectedArtifactCount = 1
    for ($sourceIndex = 0; $sourceIndex -lt $sourceRecords.Count; $sourceIndex++) {
        $record = $sourceRecords[$sourceIndex]
        $relative = [string]$record.relative_path
        if ($record.no_op -isnot [bool]) { Die "SYNAPSE_PROFILE_ROOT_TRANSACTION_SOURCE_NOOP_TYPE_INVALID relative_path=$relative" }
        $samePrePost = ([bool]$record.pre_existed -and
            [string]$record.pre_file_id_128 -ieq [string]$record.post_file_id_128 -and
            [string]$record.pre_sha256 -ieq [string]$record.post_sha256 -and
            [int64]$record.pre_length -eq [int64]$record.post_length)
        $ordinal = $sourceIndex + 1
        $expectedStage = if ([bool]$record.no_op) { '' } else { 'profile-stage-source-{0:D4}.bin' -f $ordinal }
        $expectedPark = if ([bool]$record.pre_existed -and -not [bool]$record.no_op) { 'profile-park-source-{0:D4}.bin' -f $ordinal } else { '' }
        $expectedDiscard = if ([bool]$record.no_op) { '' } else { 'profile-discard-source-{0:D4}.bin' -f $ordinal }
        if ([bool]$record.no_op -ne $samePrePost -or
            [string]$record.stage_leaf -cne $expectedStage -or
            [string]$record.park_leaf -cne $expectedPark -or
            [string]$record.discard_leaf -cne $expectedDiscard) {
            Die "SYNAPSE_PROFILE_ROOT_TRANSACTION_SOURCE_LIFECYCLE_INVALID relative_path=$relative no_op=$($record.no_op) stage=$($record.stage_leaf) park=$($record.park_leaf) discard=$($record.discard_leaf)"
        }
        & $assertOwnedEntry $candidateOwnedSeen $relative ([string]$record.post_file_id_128) ([string]$record.post_sha256) ([int64]$record.post_length) 'candidate_source'
        if ([bool]$record.pre_existed) {
            & $assertOwnedEntry $priorOwnedSeen $relative ([string]$record.pre_file_id_128) ([string]$record.pre_sha256) ([int64]$record.pre_length) 'prior_source'
        } elseif ($priorOwnedSeen.ContainsKey($relative)) {
            Die "SYNAPSE_PROFILE_ROOT_TRANSACTION_PRIOR_SOURCE_ABSENCE_BINDING_INVALID relative_path=$relative"
        }
        if (-not [bool]$record.no_op) {
            & $assertArtifact $expectedStage $false ([string]$record.post_file_id_128) ([string]$record.post_sha256) 'source_stage'
            & $assertArtifact $expectedDiscard $false ([string]$record.post_file_id_128) ([string]$record.post_sha256) 'source_discard'
            $expectedArtifactCount += 2
            if ($expectedPark) {
                & $assertArtifact $expectedPark $false ([string]$record.pre_file_id_128) ([string]$record.pre_sha256) 'source_park'
                $expectedArtifactCount++
            }
        }
    }
    $expectedQuarantineFinalLeaf = "$($script:SynapseBundledProfilesQuarantineDirName).retired-$transactionLeaf"
    if ($retiredRecords.Count -gt 0) {
        if ([string]$Descriptor.quarantine_work_leaf -cne 'profile-quarantine.work' -or
            [string]$Descriptor.quarantine_final_leaf -cne $expectedQuarantineFinalLeaf -or
            [string]$Descriptor.quarantine_directory_file_id_128 -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$') {
            Die 'SYNAPSE_PROFILE_ROOT_TRANSACTION_QUARANTINE_IDENTITY_INVALID'
        }
        & $assertArtifact ([string]$Descriptor.quarantine_work_leaf) $true ([string]$Descriptor.quarantine_directory_file_id_128) '' 'quarantine_work'
        $expectedArtifactCount++
    } elseif (-not [string]::IsNullOrWhiteSpace([string]$Descriptor.quarantine_work_leaf) -or
        -not [string]::IsNullOrWhiteSpace([string]$Descriptor.quarantine_final_leaf) -or
        -not [string]::IsNullOrWhiteSpace([string]$Descriptor.quarantine_directory_file_id_128)) {
        Die 'SYNAPSE_PROFILE_ROOT_TRANSACTION_UNEXPECTED_QUARANTINE_IDENTITY'
    }
    foreach ($record in $retiredRecords) {
        $relative = [string]$record.relative_path
        & $assertOwnedEntry $priorOwnedSeen $relative ([string]$record.pre_file_id_128) ([string]$record.pre_sha256) ([int64]$record.pre_length) 'prior_retired'
        & $assertOwnedEntry $candidateOwnedSeen "$expectedQuarantineFinalLeaf/$relative" ([string]$record.pre_file_id_128) ([string]$record.pre_sha256) ([int64]$record.pre_length) 'candidate_quarantine'
    }
    $carriedSeen = New-SynapseCaseInsensitiveMap
    foreach ($record in $carriedQuarantineRecords) {
        $relative = Assert-SynapseProfileRelativePathSafe -RelativePath ([string]$record.relative_path) -Context 'profile_root_carried_quarantine_record'
        $parts = @($relative.Split('/'))
        if ($parts.Count -ne 2 -or [string]$parts[0] -notmatch '^\.synapse-retired-bundled-profiles\.retired-deployment-\d{8}T\d{9}Z-\d+$' -or
            $carriedSeen.ContainsKey($relative) -or [string]$record.file_id_128 -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or
            [string]$record.sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [int64]$record.length -lt 0) {
            Die "SYNAPSE_PROFILE_ROOT_TRANSACTION_CARRIED_QUARANTINE_INVALID relative_path=$relative"
        }
        $carriedSeen[$relative] = $true
        & $assertOwnedEntry $priorOwnedSeen $relative ([string]$record.file_id_128) ([string]$record.sha256) ([int64]$record.length) 'prior_carried_quarantine'
        & $assertOwnedEntry $candidateOwnedSeen $relative ([string]$record.file_id_128) ([string]$record.sha256) ([int64]$record.length) 'candidate_carried_quarantine'
    }
    if ([string]$manifestRecord.stage_leaf -cne 'profile-stage-manifest.json' -or
        [string]$manifestRecord.discard_leaf -cne 'profile-discard-manifest.json' -or
        [string]$manifestRecord.park_leaf -cne $(if ([bool]$manifestRecord.pre_existed) { 'profile-park-manifest.json' } else { '' })) {
        Die 'SYNAPSE_PROFILE_ROOT_TRANSACTION_MANIFEST_LIFECYCLE_INVALID'
    }
    & $assertOwnedEntry $candidateOwnedSeen $script:SynapseBundledProfilesManifestFileName ([string]$manifestRecord.post_file_id_128) ([string]$manifestRecord.post_sha256) ([int64]$manifestRecord.post_length) 'candidate_manifest'
    if ([bool]$manifestRecord.pre_existed) {
        & $assertOwnedEntry $priorOwnedSeen $script:SynapseBundledProfilesManifestFileName ([string]$manifestRecord.pre_file_id_128) ([string]$manifestRecord.pre_sha256) ([int64]$manifestRecord.pre_length) 'prior_manifest'
    } elseif ($priorOwnedSeen.ContainsKey($script:SynapseBundledProfilesManifestFileName)) {
        Die 'SYNAPSE_PROFILE_ROOT_TRANSACTION_PRIOR_MANIFEST_ABSENCE_BINDING_INVALID'
    }
    & $assertArtifact ([string]$manifestRecord.stage_leaf) $false ([string]$manifestRecord.post_file_id_128) ([string]$manifestRecord.post_sha256) 'manifest_stage'
    & $assertArtifact ([string]$manifestRecord.discard_leaf) $false ([string]$manifestRecord.post_file_id_128) ([string]$manifestRecord.post_sha256) 'manifest_discard'
    $expectedArtifactCount += 2
    if ([string]$manifestRecord.park_leaf) {
        & $assertArtifact ([string]$manifestRecord.park_leaf) $false ([string]$manifestRecord.pre_file_id_128) ([string]$manifestRecord.pre_sha256) 'manifest_park'
        $expectedArtifactCount++
    }
    & $assertArtifact ([string]$Descriptor.work_leaf) $true ([string]$Descriptor.profiles_root_file_id_128) '' 'profile_work_root'
    $expectedPriorOwnedCount = @($sourceRecords | Where-Object pre_existed).Count + $retiredRecords.Count + $carriedQuarantineRecords.Count + $(if ([bool]$manifestRecord.pre_existed) { 1 } else { 0 })
    if ($priorOwned.Count -ne $expectedPriorOwnedCount -or $artifacts.Count -ne $expectedArtifactCount) {
        Die "SYNAPSE_PROFILE_ROOT_TRANSACTION_DERIVED_COUNT_MISMATCH prior_expected=$expectedPriorOwnedCount prior_actual=$($priorOwned.Count) artifacts_expected=$expectedArtifactCount artifacts_actual=$($artifacts.Count)"
    }
    $computed = Get-SynapseBundledProfilesTransactionPlanSha256 -Descriptor $Descriptor
    if ([string]$Descriptor.static_plan_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or $computed -ine [string]$Descriptor.static_plan_sha256) {
        Die "SYNAPSE_PROFILE_ROOT_TRANSACTION_PLAN_HASH_MISMATCH expected=$($Descriptor.static_plan_sha256) actual=$computed remediation=preserve the transaction; its immutable profile plan changed"
    }
    return [pscustomobject]@{
        Descriptor = $Descriptor
        ProfilesDir = $profilesFull
        ProfilesParent = $profilesParent
        ProfilesLeaf = $profilesLeaf
        ProfilesParentChain = $parentChain
        TransactionRoot = $transactionFull
        TransactionRootChain = $transactionChain
        RootFileId128 = ([string]$Descriptor.profiles_root_file_id_128).ToUpperInvariant()
        RootPreExisted = [bool]$Descriptor.profiles_root_pre_existed
        WorkLeaf = [string]$Descriptor.work_leaf
        SourceEntries = $sourceRecords
        RetiredEntries = $retiredRecords
        CarriedQuarantineEntries = $carriedQuarantineRecords
        ManifestEntry = $manifestRecord
        CandidateOwnedEntries = $candidateOwned
        PriorOwnedEntries = $priorOwned
        ProfileArtifacts = $artifacts
        StaticPlanSha256 = $computed
    }
}

function New-SynapseBundledProfilesDeploymentPlan {
    param(
        [Parameter(Mandatory=$true)][string]$SourceProfilesDir,
        [Parameter(Mandatory=$true)][string]$ProfilesDir,
        [Parameter(Mandatory=$true)][string]$TransactionRoot,
        [Parameter(Mandatory=$true)]$AllocationContext
    )

    Ensure-SynapseAtomicFileType
    $profilesFull = Get-SynapseNormalizedDirectoryPath -Path $ProfilesDir
    $profilesParent = Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $profilesFull)
    $profilesLeaf = Split-Path -Leaf $profilesFull
    $transactionFull = Get-SynapseNormalizedDirectoryPath -Path $TransactionRoot
    if ((Get-SynapseNormalizedDirectoryPath -Path ([string]$AllocationContext.Root)) -ine $transactionFull -or
        [bool]$AllocationContext.Frozen) {
        Die "SYNAPSE_PROFILE_TRANSACTION_ALLOCATION_CONTEXT_INVALID transaction_root=$transactionFull allocation_root=$($AllocationContext.Root) frozen=$($AllocationContext.Frozen)"
    }
    $transactionLeaf = Split-Path -Leaf $transactionFull
    $parentChain = @(Ensure-SynapsePhysicalDirectoryPath -Path $profilesParent -Context 'profile_parent')
    $transactionChain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $transactionFull)
    $volume = [SynapseSetup.AtomicFileV2]::GetStableLocalVolume($profilesParent)
    $transactionVolume = [SynapseSetup.AtomicFileV2]::GetStableLocalVolume($transactionFull)
    if ([uint32]$volume.VolumeSerialNumber -ne [uint32]$transactionVolume.VolumeSerialNumber) {
        Die "SYNAPSE_PROFILE_TRANSACTION_VOLUME_SPLIT profiles_parent=$profilesParent transaction_root=$transactionFull remediation=profile work, parks, and journals must share the exact ProfilesDir volume"
    }
    $rootState = Get-SynapsePhysicalRelativeState -ParentPath $profilesParent -ParentChain $parentChain -Leaf $profilesLeaf -Directory
    $rootPreExisted = [bool]$rootState.Exists
    $workLeaf = 'profile-root.work'
    $workState = Get-SynapsePhysicalRelativeState -ParentPath $transactionFull -ParentChain $transactionChain -Leaf $workLeaf -Directory
    if ($workState.Exists) {
        Die "SYNAPSE_PROFILE_TRANSACTION_WORK_ROOT_COLLISION path=$($workState.Path) remediation=preserve the unexpected transaction child and refuse ambiguous root authority"
    }
    $rootChain = @()
    if ($rootPreExisted) {
        $rootChain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $profilesFull)
        if ([string]$rootChain[-1].file_id_128 -ine [string]$rootState.FileId128) {
            Die "SYNAPSE_PROFILE_TRANSACTION_ROOT_PLAN_DRIFT path=$profilesFull parent_file_id_128=$($rootState.FileId128) chain_file_id_128=$($rootChain[-1].file_id_128)"
        }
    } else {
        $createdWork = New-SynapseDeploymentAllocatedDirectory -Context $AllocationContext -Leaf $workLeaf -Purpose 'profile_root_work_new_generation'
        $rootState = [pscustomobject]@{ FileId128 = [string]$createdWork.FileId128 }
    }

    $sourceEntries = @(Get-SynapseBundledProfileSourceEntries -SourceProfilesDir $SourceProfilesDir)
    if (@($sourceEntries | Where-Object { [string]$_.relative_path -match '/' }).Count -gt 0 -or $sourceEntries.Count -gt 512) {
        Die "SYNAPSE_BUNDLED_PROFILE_SOURCE_SHAPE_UNSUPPORTED path=$SourceProfilesDir count=$($sourceEntries.Count) remediation=bundled profile root-object publication requires at most 512 top-level regular source files"
    }
    $sourceMap = Convert-SynapseEntriesToMap -Entries $sourceEntries
    $manifestPath = Join-Path $profilesFull $script:SynapseBundledProfilesManifestFileName
    $manifestPre = if ($rootPreExisted) {
        Get-SynapsePhysicalRelativeState -ParentPath $profilesFull -ParentChain $rootChain -Leaf $script:SynapseBundledProfilesManifestFileName
    } else { [pscustomobject]@{ Exists=$false; Sha256=''; FileId128=''; Length=0; Identity='' } }
    $previousManifest = $null
    if ($manifestPre.Exists) {
        $manifestRead = Read-SynapsePhysicalRelativeUtf8Text -ParentPath $profilesFull -ParentChain $rootChain -Leaf $script:SynapseBundledProfilesManifestFileName -ExpectedFileId128 ([string]$manifestPre.FileId128) -MaxBytes 1MB
        if ([string]$manifestRead.Sha256 -ine [string]$manifestPre.Sha256 -or [int64]$manifestRead.Length -ne [int64]$manifestPre.Length) {
            Die "SYNAPSE_BUNDLED_PROFILES_MANIFEST_PLAN_READBACK_MISMATCH path=$manifestPath"
        }
        $previousManifest = ConvertFrom-SynapseBundledProfilesManifestText -Text ([string]$manifestRead.Content) -ManifestPath $manifestPath
    }
    $previousMap = New-SynapseCaseInsensitiveMap
    if ($previousManifest) { $previousMap = Convert-SynapseEntriesToMap -Entries @($previousManifest.files) }

    $carriedQuarantineEntries = @()
    $carriedQuarantinedManifestRecords = @()
    if ($previousManifest) {
        $profilesPrefix = $profilesFull + [System.IO.Path]::DirectorySeparatorChar
        $carriedSeen = New-SynapseCaseInsensitiveMap
        foreach ($priorQuarantine in @($previousManifest.quarantined_retired)) {
            $quarantinePath = [System.IO.Path]::GetFullPath([string]$priorQuarantine.quarantine_path)
            if (-not $rootPreExisted -or -not $quarantinePath.StartsWith($profilesPrefix, [System.StringComparison]::OrdinalIgnoreCase)) {
                Die "SYNAPSE_PROFILE_CARRIED_QUARANTINE_SCOPE_INVALID quarantine_path=$quarantinePath profiles_dir=$profilesFull"
            }
            $relativeObjectPath = $quarantinePath.Substring($profilesPrefix.Length).Replace('\','/')
            $parts = @($relativeObjectPath.Split('/'))
            $retiredRelative = Assert-SynapseProfileRelativePathSafe -RelativePath ([string]$priorQuarantine.relative_path) -Context 'carried_profile_quarantine_relative'
            if ($parts.Count -ne 2 -or [string]$parts[0] -notmatch '^\.synapse-retired-bundled-profiles\.retired-deployment-\d{8}T\d{9}Z-\d+$' -or
                [string]$parts[1] -cne $retiredRelative -or $carriedSeen.ContainsKey($relativeObjectPath)) {
                Die "SYNAPSE_PROFILE_CARRIED_QUARANTINE_PATH_INVALID relative_object_path=$relativeObjectPath retired_relative=$retiredRelative"
            }
            $quarantineDirectoryState = Get-SynapsePhysicalRelativeState -ParentPath $profilesFull -ParentChain $rootChain -Leaf ([string]$parts[0]) -Directory
            if (-not $quarantineDirectoryState.Exists) {
                Die "SYNAPSE_PROFILE_CARRIED_QUARANTINE_DIRECTORY_MISSING leaf=$($parts[0])"
            }
            $quarantineDirectoryPath = Join-Path $profilesFull ([string]$parts[0])
            $quarantineDirectoryChain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $quarantineDirectoryPath)
            $state = Get-SynapsePhysicalRelativeState -ParentPath $quarantineDirectoryPath -ParentChain $quarantineDirectoryChain -Leaf $retiredRelative
            if (-not $state.Exists -or [string]$state.Sha256 -ine [string]$priorQuarantine.sha256) {
                Die "SYNAPSE_PROFILE_CARRIED_QUARANTINE_IDENTITY_DRIFT path=$quarantinePath exists=$($state.Exists) expected_sha256=$($priorQuarantine.sha256) actual_sha256=$($state.Sha256) remediation=preserve the persistent quarantine object; setup will not silently reclassify or overwrite it"
            }
            $carriedSeen[$relativeObjectPath] = $true
            $carriedQuarantineEntries += [pscustomobject][ordered]@{
                relative_path=$relativeObjectPath
                file_id_128=([string]$state.FileId128).ToUpperInvariant()
                sha256=([string]$state.Sha256).ToUpperInvariant()
                length=[int64]$state.Length
            }
            $carriedQuarantinedManifestRecords += [ordered]@{
                relative_path=$retiredRelative
                original_path=[System.IO.Path]::GetFullPath([string]$priorQuarantine.original_path)
                quarantine_path=$quarantinePath
                sha256=([string]$state.Sha256).ToUpperInvariant()
                reason=[string]$priorQuarantine.reason
            }
        }
    }

    $sourcePreimageMap = New-SynapseCaseInsensitiveMap
    foreach ($entry in $sourceEntries) {
        $relative = [string]$entry.relative_path
        $state = if ($rootPreExisted) {
            Get-SynapsePhysicalRelativeState -ParentPath $profilesFull -ParentChain $rootChain -Leaf $relative
        } else { [pscustomobject]@{ Exists=$false; Sha256=''; FileId128=''; Length=0; Identity='' } }
        $sourcePreimageMap[$relative] = $state
        if (-not $state.Exists) { continue }
        if (-not $previousMap.ContainsKey($relative)) {
            Die "SYNAPSE_BUNDLED_PROFILE_CUSTOM_COLLISION relative_path=$relative current_sha256=$($state.Sha256) source_sha256=$($entry.sha256) same_content=$([string]$state.Sha256 -ieq [string]$entry.sha256) remediation=setup never adopts or overwrites an unowned same-name profile; move the custom file aside before deploying the bundled generation"
        }
        if ([string]$state.Sha256 -ine [string]$previousMap[$relative].sha256) {
            Die "SYNAPSE_BUNDLED_PROFILE_OWNED_PATH_MODIFIED relative_path=$relative manifest_sha256=$($previousMap[$relative].sha256) current_sha256=$($state.Sha256) remediation=the previously owned path contains custom edits and is preserved"
        }
    }

    $retireActions = @()
    $preservedPriorMismatches = @()
    $preservedLegacyMismatches = @()
    foreach ($previous in @($previousMap.Values)) {
        $relative = [string]$previous.relative_path
        if ($sourceMap.ContainsKey($relative)) { continue }
        $state = if ($rootPreExisted) { Get-SynapsePhysicalRelativeState -ParentPath $profilesFull -ParentChain $rootChain -Leaf $relative } else { [pscustomobject]@{ Exists=$false } }
        if (-not $state.Exists) { continue }
        if ([string]$state.Sha256 -ieq [string]$previous.sha256) {
            $retireActions += [pscustomobject]@{ relative_path=$relative; state=$state; reason='previous_manifest_absent_from_source' }
        } else {
            $preservedPriorMismatches += [ordered]@{ relative_path=$relative; path=(Join-Path $profilesFull $relative); expected_sha256=[string]$previous.sha256; actual_sha256=[string]$state.Sha256; reason='previous_manifest_hash_mismatch_preserved_as_custom' }
        }
    }
    foreach ($legacy in @($script:SynapseLegacyRetiredBundledProfiles)) {
        $relative = Assert-SynapseProfileRelativePathSafe -RelativePath ([string]$legacy.relative_path) -Context 'plan_legacy_retired_bundled_profile'
        if ($relative -match '/' -or $sourceMap.ContainsKey($relative) -or @($retireActions | Where-Object relative_path -IEQ $relative).Count -gt 0 -or -not $rootPreExisted) { continue }
        $state = Get-SynapsePhysicalRelativeState -ParentPath $profilesFull -ParentChain $rootChain -Leaf $relative
        if (-not $state.Exists) { continue }
        if ([string]$state.Sha256 -ieq [string]$legacy.sha256) {
            $retireActions += [pscustomobject]@{ relative_path=$relative; state=$state; reason="legacy_retired_seed:$($legacy.issue)" }
        } else {
            $preservedLegacyMismatches += [ordered]@{ relative_path=$relative; path=(Join-Path $profilesFull $relative); expected_sha256=([string]$legacy.sha256).ToUpperInvariant(); actual_sha256=[string]$state.Sha256; reason='legacy_retired_seed_hash_mismatch_preserved_as_custom' }
        }
    }
    $retireActions = @($retireActions | Sort-Object relative_path)

    # Prove the complete direct transaction namespace before creating any
    # per-profile stage. A changed source can occupy three mutually exclusive
    # lifecycle names (stage/park/discard); reserving their union keeps crash
    # recovery bounded even though fewer are present at any one instant.
    $plannedProfileArtifactCount = 1 # profile-root.work
    foreach ($entry in $sourceEntries) {
        $pre = $sourcePreimageMap[[string]$entry.relative_path]
        $noop = [bool]($pre.Exists -and [string]$pre.Sha256 -ieq [string]$entry.sha256)
        if (-not $noop) {
            $plannedProfileArtifactCount += 2 # stage + discard
            if ($pre.Exists) { $plannedProfileArtifactCount++ } # park
        }
    }
    $plannedProfileArtifactCount += 2 # manifest stage + discard
    if ($manifestPre.Exists) { $plannedProfileArtifactCount++ } # manifest park
    if ($retireActions.Count -gt 0) { $plannedProfileArtifactCount++ } # quarantine work directory
    if ($plannedProfileArtifactCount -gt 128) {
        Die "SYNAPSE_PROFILE_TRANSACTION_ARTIFACT_PREFLIGHT_BOUND_EXCEEDED planned_entries=$plannedProfileArtifactCount max=128 source_count=$($sourceEntries.Count) retired_count=$($retireActions.Count) remediation=reduce the bundled generation before any per-profile stages are created"
    }

    $quarantineWorkLeaf = 'profile-quarantine.work'
    $quarantineFinalLeaf = "$($script:SynapseBundledProfilesQuarantineDirName).retired-$transactionLeaf"
    $quarantineDirectory = $null
    if ($retireActions.Count -gt 0) {
        $qState = Get-SynapsePhysicalRelativeState -ParentPath $transactionFull -ParentChain $transactionChain -Leaf $quarantineWorkLeaf -Directory
        if ($qState.Exists) { Die "SYNAPSE_PROFILE_TRANSACTION_QUARANTINE_WORK_COLLISION path=$($qState.Path)" }
        $quarantineDirectory = New-SynapseDeploymentAllocatedDirectory -Context $AllocationContext -Leaf $quarantineWorkLeaf -Purpose 'profile_retirement_quarantine_work'
    }

    $plannedQuarantined = @($retireActions | ForEach-Object {
        [ordered]@{ relative_path=[string]$_.relative_path; original_path=(Join-Path $profilesFull ([string]$_.relative_path)); quarantine_path=(Join-Path (Join-Path $profilesFull $quarantineFinalLeaf) ([string]$_.relative_path)); sha256=([string]$_.state.Sha256).ToUpperInvariant(); reason=[string]$_.reason }
    })
    $allPlannedQuarantined = @($carriedQuarantinedManifestRecords + $plannedQuarantined)
    if ($allPlannedQuarantined.Count -gt 512) {
        Die "SYNAPSE_PROFILE_PERSISTENT_QUARANTINE_BOUND_EXCEEDED carried_count=$($carriedQuarantinedManifestRecords.Count) new_count=$($plannedQuarantined.Count) max=512"
    }
    $customProfiles = @(Get-SynapsePreservedCustomProfiles -ProfilesDir $profilesFull -SourceMap $sourceMap -RetireActions $retireActions)
    $plannedManifest = New-SynapseBundledProfilesManifestObject -SourceProfilesDir $SourceProfilesDir -ProfilesDir $profilesFull -Entries $sourceEntries -Quarantined $allPlannedQuarantined -PreservedCustomProfiles $customProfiles -PreservedLegacyRetiredHashMismatches $preservedLegacyMismatches -GeneratedAtUtc ([DateTime]::UtcNow.ToString('o'))
    $plannedManifest['generation_identity_semantics'] = 'bundled source files plus ownership manifest plus persistent retired quarantine objects; custom profiles and later edits are unowned post-publication deltas'
    $manifestText = ($plannedManifest | ConvertTo-Json -Depth 40) + "`n"
    $manifestBytes = [System.Text.UTF8Encoding]::new($false, $true).GetByteCount($manifestText)
    if ($manifestBytes -gt 1MB) { Die "SYNAPSE_BUNDLED_PROFILES_MANIFEST_BOUND_WOULD_BE_EXCEEDED bytes=$manifestBytes max=$((1MB))" }
    $manifestSha = (Get-SynapseSha256Hex -Text $manifestText).ToUpperInvariant()

    $records = @()
    $artifacts = @()
    $candidateOwned = @()
    $priorOwned = @()
    foreach ($carried in $carriedQuarantineEntries) {
        $candidateOwned += $carried
        $priorOwned += $carried
    }
    $sourceIndex = 0
    foreach ($entry in $sourceEntries) {
        $sourceIndex++
        $relative = [string]$entry.relative_path
        $pre = $sourcePreimageMap[$relative]
        $noop = [bool]($pre.Exists -and [string]$pre.Sha256 -ieq [string]$entry.sha256)
        $stageLeaf = ''
        $stage = $null
        if (-not $noop) {
            $stageLeaf = 'profile-stage-source-{0:D4}.bin' -f $sourceIndex
            $stage = New-SynapseDeploymentAllocatedFileFromSource -Context $AllocationContext -Leaf $stageLeaf -Purpose "profile_source_stage_$sourceIndex" -SourcePath ([string]$entry.source_path) -ExpectedSha256 ([string]$entry.sha256) -ExpectedLength ([int64]$entry.length)
            $artifacts += [pscustomobject][ordered]@{ leaf=$stageLeaf; directory=$false; allowed_file_ids_128=@(([string]$stage.FileId128).ToUpperInvariant()); allowed_sha256=@(([string]$stage.Sha256).ToUpperInvariant()) }
        }
        $postId = if ($noop) { [string]$pre.FileId128 } else { [string]$stage.FileId128 }
        $parkLeaf = if ($pre.Exists -and -not $noop) { 'profile-park-source-{0:D4}.bin' -f $sourceIndex } else { '' }
        $discardLeaf = if (-not $noop) { 'profile-discard-source-{0:D4}.bin' -f $sourceIndex } else { '' }
        if ($parkLeaf) { [void](Reserve-SynapseDeploymentArtifact -Context $AllocationContext -Leaf $parkLeaf -Kind transition_slot -Purpose "profile_source_park_$sourceIndex" -ExpectedSha256 ([string]$pre.Sha256) -ExpectedLength ([int64]$pre.Length) -MaximumLength ([int64]$pre.Length) -AllowedFileIds128 @([string]$pre.FileId128)) }
        if ($discardLeaf) { [void](Reserve-SynapseDeploymentArtifact -Context $AllocationContext -Leaf $discardLeaf -Kind transition_slot -Purpose "profile_source_discard_$sourceIndex" -ExpectedSha256 ([string]$entry.sha256) -ExpectedLength ([int64]$entry.length) -MaximumLength ([int64]$entry.length) -AllowedFileIds128 @([string]$postId)) }
        if ($parkLeaf) { $artifacts += [pscustomobject][ordered]@{ leaf=$parkLeaf; directory=$false; allowed_file_ids_128=@(([string]$pre.FileId128).ToUpperInvariant()); allowed_sha256=@(([string]$pre.Sha256).ToUpperInvariant()) } }
        if ($discardLeaf) { $artifacts += [pscustomobject][ordered]@{ leaf=$discardLeaf; directory=$false; allowed_file_ids_128=@(([string]$postId).ToUpperInvariant()); allowed_sha256=@(([string]$entry.sha256).ToUpperInvariant()) } }
        $record = [pscustomobject][ordered]@{
            relative_path=$relative; pre_existed=[bool]$pre.Exists; pre_sha256=$(if($pre.Exists){([string]$pre.Sha256).ToUpperInvariant()}else{''}); pre_file_id_128=$(if($pre.Exists){([string]$pre.FileId128).ToUpperInvariant()}else{''}); pre_length=$(if($pre.Exists){[int64]$pre.Length}else{-1})
            post_existed=$true; post_sha256=([string]$entry.sha256).ToUpperInvariant(); post_file_id_128=([string]$postId).ToUpperInvariant(); post_length=[int64]$entry.length; no_op=$noop; stage_leaf=$stageLeaf; park_leaf=$parkLeaf; discard_leaf=$discardLeaf
        }
        $records += $record
        $candidateOwned += [pscustomobject][ordered]@{ relative_path=$relative; file_id_128=$record.post_file_id_128; sha256=$record.post_sha256; length=$record.post_length }
        if ($pre.Exists -and $previousMap.ContainsKey($relative) -and [string]$pre.Sha256 -ieq [string]$previousMap[$relative].sha256) {
            $priorOwned += [pscustomobject][ordered]@{ relative_path=$relative; file_id_128=$record.pre_file_id_128; sha256=$record.pre_sha256; length=$record.pre_length }
        }
    }

    $retiredRecords = @()
    foreach ($action in $retireActions) {
        $state = $action.state
        $record = [pscustomobject][ordered]@{ relative_path=[string]$action.relative_path; reason=[string]$action.reason; pre_existed=$true; pre_sha256=([string]$state.Sha256).ToUpperInvariant(); pre_file_id_128=([string]$state.FileId128).ToUpperInvariant(); pre_length=[int64]$state.Length; post_existed=$false; post_sha256=''; post_file_id_128=''; post_length=-1 }
        $retiredRecords += $record
        $priorOwned += [pscustomobject][ordered]@{ relative_path=$record.relative_path; file_id_128=$record.pre_file_id_128; sha256=$record.pre_sha256; length=$record.pre_length }
        $candidateOwned += [pscustomobject][ordered]@{ relative_path="$quarantineFinalLeaf/$($record.relative_path)"; file_id_128=$record.pre_file_id_128; sha256=$record.pre_sha256; length=$record.pre_length }
    }

    $manifestStageLeaf = 'profile-stage-manifest.json'
    $manifestStage = New-SynapseDeploymentAllocatedUtf8File -Context $AllocationContext -Leaf $manifestStageLeaf -Purpose 'profile_manifest_stage' -Content $manifestText
    $manifestParkLeaf = if ($manifestPre.Exists) { 'profile-park-manifest.json' } else { '' }
    $manifestDiscardLeaf = 'profile-discard-manifest.json'
    if ($manifestParkLeaf) { [void](Reserve-SynapseDeploymentArtifact -Context $AllocationContext -Leaf $manifestParkLeaf -Kind transition_slot -Purpose 'profile_manifest_park' -ExpectedSha256 ([string]$manifestPre.Sha256) -ExpectedLength ([int64]$manifestPre.Length) -MaximumLength ([int64]$manifestPre.Length) -AllowedFileIds128 @([string]$manifestPre.FileId128)) }
    [void](Reserve-SynapseDeploymentArtifact -Context $AllocationContext -Leaf $manifestDiscardLeaf -Kind transition_slot -Purpose 'profile_manifest_discard' -ExpectedSha256 $manifestSha -ExpectedLength $manifestBytes -MaximumLength $manifestBytes -AllowedFileIds128 @([string]$manifestStage.FileId128))
    $artifacts += [pscustomobject][ordered]@{ leaf=$manifestStageLeaf; directory=$false; allowed_file_ids_128=@(([string]$manifestStage.FileId128).ToUpperInvariant()); allowed_sha256=@($manifestSha) }
    if ($manifestParkLeaf) { $artifacts += [pscustomobject][ordered]@{ leaf=$manifestParkLeaf; directory=$false; allowed_file_ids_128=@(([string]$manifestPre.FileId128).ToUpperInvariant()); allowed_sha256=@(([string]$manifestPre.Sha256).ToUpperInvariant()) } }
    $artifacts += [pscustomobject][ordered]@{ leaf=$manifestDiscardLeaf; directory=$false; allowed_file_ids_128=@(([string]$manifestStage.FileId128).ToUpperInvariant()); allowed_sha256=@($manifestSha) }
    $manifestRecord = [pscustomobject][ordered]@{ relative_path=$script:SynapseBundledProfilesManifestFileName; pre_existed=[bool]$manifestPre.Exists; pre_sha256=$(if($manifestPre.Exists){([string]$manifestPre.Sha256).ToUpperInvariant()}else{''}); pre_file_id_128=$(if($manifestPre.Exists){([string]$manifestPre.FileId128).ToUpperInvariant()}else{''}); pre_length=$(if($manifestPre.Exists){[int64]$manifestPre.Length}else{-1}); post_existed=$true; post_sha256=$manifestSha; post_file_id_128=([string]$manifestStage.FileId128).ToUpperInvariant(); post_length=[int64]$manifestStage.Length; stage_leaf=$manifestStageLeaf; park_leaf=$manifestParkLeaf; discard_leaf=$manifestDiscardLeaf }
    $candidateOwned += [pscustomobject][ordered]@{ relative_path=$script:SynapseBundledProfilesManifestFileName; file_id_128=$manifestRecord.post_file_id_128; sha256=$manifestRecord.post_sha256; length=$manifestRecord.post_length }
    if ($manifestPre.Exists) { $priorOwned += [pscustomobject][ordered]@{ relative_path=$script:SynapseBundledProfilesManifestFileName; file_id_128=$manifestRecord.pre_file_id_128; sha256=$manifestRecord.pre_sha256; length=$manifestRecord.pre_length } }
    $artifacts += [pscustomobject][ordered]@{ leaf=$workLeaf; directory=$true; allowed_file_ids_128=@(([string]$rootState.FileId128).ToUpperInvariant()); allowed_sha256=@() }
    if ($rootPreExisted) { [void](Reserve-SynapseDeploymentArtifact -Context $AllocationContext -Leaf $workLeaf -Kind transition_slot -Purpose 'profile_root_work_existing_generation' -ExpectedLength -1 -MaximumLength 0 -AllowedFileIds128 @([string]$rootState.FileId128) -DirectoryTransition) }
    if ($quarantineDirectory) { $artifacts += [pscustomobject][ordered]@{ leaf=$quarantineWorkLeaf; directory=$true; allowed_file_ids_128=@(([string]$quarantineDirectory.FileId128).ToUpperInvariant()); allowed_sha256=@() } }

    $descriptor = [pscustomobject][ordered]@{
        schema='synapse_bundled_profiles_transaction/v3'; profiles_dir=$profilesFull; profiles_parent=$profilesParent; profiles_leaf=$profilesLeaf; profiles_parent_chain=$parentChain
        transaction_root=$transactionFull; transaction_leaf=$transactionLeaf; transaction_root_chain=$transactionChain
        volume_root=[string]$volume.RootPath; volume_filesystem=[string]$volume.FileSystemName; volume_serial_number=('{0:X8}' -f [uint32]$volume.VolumeSerialNumber)
        profiles_root_pre_existed=$rootPreExisted; profiles_root_file_id_128=([string]$rootState.FileId128).ToUpperInvariant(); work_leaf=$workLeaf
        quarantine_work_leaf=$(if($quarantineDirectory){$quarantineWorkLeaf}else{''}); quarantine_final_leaf=$(if($quarantineDirectory){$quarantineFinalLeaf}else{''}); quarantine_directory_file_id_128=$(if($quarantineDirectory){([string]$quarantineDirectory.FileId128).ToUpperInvariant()}else{''})
        source_manifest_sha256=(Get-SynapseBundledProfilesSourceManifestSha256 -Entries $sourceEntries).ToUpperInvariant(); installed_manifest_sha256=$manifestSha; manifest_relative_path=$script:SynapseBundledProfilesManifestFileName
        source_entries=$records; retired_entries=$retiredRecords; carried_quarantine_entries=@($carriedQuarantineEntries | Sort-Object relative_path); manifest_entry=$manifestRecord; candidate_owned_entries=@($candidateOwned | Sort-Object relative_path); prior_owned_entries=@($priorOwned | Sort-Object relative_path); profile_artifacts=@($artifacts | Sort-Object leaf); static_plan_sha256=''
    }
    $descriptor.static_plan_sha256 = Get-SynapseBundledProfilesTransactionPlanSha256 -Descriptor $descriptor
    $validated = Assert-SynapseBundledProfilesTransactionDescriptor -Descriptor $descriptor -ProfilesDir $profilesFull -TransactionRoot $transactionFull
    return [pscustomobject]@{ Descriptor=$descriptor; DescriptorSha256=[string]$descriptor.static_plan_sha256; Validated=$validated; SourceEntries=$sourceEntries; PreviousManifest=$previousManifest; PreviousMap=$previousMap; RetireActions=$retireActions; CarriedQuarantineEntries=$carriedQuarantineEntries; PreservedPriorMismatches=$preservedPriorMismatches; PreservedLegacyMismatches=$preservedLegacyMismatches; CustomProfiles=$customProfiles; PlannedQuarantined=$allPlannedQuarantined; Manifest=$plannedManifest; ManifestText=$manifestText; ManifestSha256=$manifestSha }
}

function New-SynapseProfilePreArmGenerationGuard {
    param([Parameter(Mandatory=$true)]$ProfilePlan)

    Ensure-SynapseAtomicFileType
    if ([bool]$ProfilePlan.RootPreExisted) {
        $guardPath = [string]$ProfilePlan.ProfilesDir
        $guardChain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $guardPath)
        if ([string]$guardChain[-1].file_id_128 -ine [string]$ProfilePlan.RootFileId128) {
            Die "SYNAPSE_PROFILE_PREARM_ROOT_IDENTITY_DRIFT path=$guardPath expected_file_id_128=$($ProfilePlan.RootFileId128) actual_file_id_128=$($guardChain[-1].file_id_128)"
        }
        $subtree = $true
    } else {
        $guardPath = [string]$ProfilePlan.ProfilesParent
        $guardChain = @($ProfilePlan.ProfilesParentChain)
        $subtree = $false
    }
    try {
        return [SynapseSetup.AtomicFileV2]::BeginPhysicalDirectoryChangeGuard(
            $guardPath,
            (Get-SynapsePhysicalChainPaths -Chain $guardChain),
            (Get-SynapsePhysicalChainFileIds -Chain $guardChain),
            [string]$guardChain[-1].file_id_128,
            $subtree)
    } catch {
        Die "SYNAPSE_PROFILE_PREARM_GENERATION_GUARD_FAILED path=$guardPath subtree=$subtree error=$($_.Exception.Message) remediation=the armed baseline requires one unchanged physical profile namespace across validation and durable slot publication"
    }
}

function Assert-SynapseProfilePreArmGenerationState {
    param([Parameter(Mandatory=$true)]$ProfilePlan)

    $plan = Assert-SynapseBundledProfilesTransactionDescriptor -Descriptor $ProfilePlan.Descriptor -ProfilesDir $ProfilePlan.ProfilesDir -TransactionRoot $ProfilePlan.TransactionRoot
    $location = Get-SynapseProfileRootLocation -ProfilePlan $plan
    $expectedLocation = if ($plan.RootPreExisted) { 'canonical' } else { 'work' }
    if ([string]$location.Location -cne $expectedLocation) {
        Die "SYNAPSE_PROFILE_PREARM_ROOT_LOCATION_DRIFT expected=$expectedLocation actual=$($location.Location) root_file_id_128=$($plan.RootFileId128)"
    }
    $activeChain = if ($plan.RootPreExisted) { @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $plan.ProfilesDir) } else { @() }
    foreach ($record in @($plan.SourceEntries + $plan.RetiredEntries)) {
        $state = if ($plan.RootPreExisted) {
            Get-SynapsePhysicalRelativeState -ParentPath $plan.ProfilesDir -ParentChain $activeChain -Leaf ([string]$record.relative_path)
        } else { [pscustomobject]@{ Exists=$false; FileId128=''; Sha256=''; Length=0 } }
        if (-not (Test-SynapsePhysicalStateExact -State $state -ExpectedExists ([bool]$record.pre_existed) -ExpectedFileId128 ([string]$record.pre_file_id_128) -ExpectedSha256 ([string]$record.pre_sha256) -ExpectedLength ([int64]$record.pre_length))) {
            Die "SYNAPSE_PROFILE_PREARM_ACTIVE_PREIMAGE_DRIFT relative_path=$($record.relative_path) expected_exists=$($record.pre_existed) expected_file_id_128=$($record.pre_file_id_128) actual_exists=$($state.Exists) actual_file_id_128=$($state.FileId128)"
        }
    }
    foreach ($record in @($plan.CarriedQuarantineEntries)) {
        $parts = @(([string]$record.relative_path).Split('/'))
        $directoryState = Get-SynapsePhysicalRelativeState -ParentPath $plan.ProfilesDir -ParentChain $activeChain -Leaf ([string]$parts[0]) -Directory
        if (-not $directoryState.Exists) { Die "SYNAPSE_PROFILE_PREARM_CARRIED_QUARANTINE_DIRECTORY_MISSING relative_path=$($record.relative_path)" }
        $directoryPath = Join-Path $plan.ProfilesDir ([string]$parts[0])
        $directoryChain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $directoryPath)
        $state = Get-SynapsePhysicalRelativeState -ParentPath $directoryPath -ParentChain $directoryChain -Leaf ([string]$parts[1])
        if (-not (Test-SynapsePhysicalStateExact -State $state -ExpectedExists $true -ExpectedFileId128 ([string]$record.file_id_128) -ExpectedSha256 ([string]$record.sha256) -ExpectedLength ([int64]$record.length))) {
            Die "SYNAPSE_PROFILE_PREARM_CARRIED_QUARANTINE_DRIFT relative_path=$($record.relative_path) expected_file_id_128=$($record.file_id_128) actual_file_id_128=$($state.FileId128)"
        }
    }
    $manifest = $plan.ManifestEntry
    $manifestState = if ($plan.RootPreExisted) {
        Get-SynapsePhysicalRelativeState -ParentPath $plan.ProfilesDir -ParentChain $activeChain -Leaf ([string]$manifest.relative_path)
    } else { [pscustomobject]@{ Exists=$false; FileId128=''; Sha256=''; Length=0 } }
    if (-not (Test-SynapsePhysicalStateExact -State $manifestState -ExpectedExists ([bool]$manifest.pre_existed) -ExpectedFileId128 ([string]$manifest.pre_file_id_128) -ExpectedSha256 ([string]$manifest.pre_sha256) -ExpectedLength ([int64]$manifest.pre_length))) {
        Die "SYNAPSE_PROFILE_PREARM_MANIFEST_PREIMAGE_DRIFT expected_exists=$($manifest.pre_existed) expected_file_id_128=$($manifest.pre_file_id_128) actual_exists=$($manifestState.Exists) actual_file_id_128=$($manifestState.FileId128)"
    }
    foreach ($record in $plan.SourceEntries) {
        if ([bool]$record.no_op) { continue }
        $stage = Get-SynapsePhysicalRelativeState -ParentPath $plan.TransactionRoot -ParentChain $plan.TransactionRootChain -Leaf ([string]$record.stage_leaf)
        if (-not (Test-SynapsePhysicalStateExact -State $stage -ExpectedExists $true -ExpectedFileId128 ([string]$record.post_file_id_128) -ExpectedSha256 ([string]$record.post_sha256) -ExpectedLength ([int64]$record.post_length))) {
            Die "SYNAPSE_PROFILE_PREARM_SOURCE_STAGE_DRIFT relative_path=$($record.relative_path) stage=$($record.stage_leaf)"
        }
        foreach ($leaf in @([string]$record.park_leaf,[string]$record.discard_leaf) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }) {
            $state = Get-SynapsePhysicalRelativeState -ParentPath $plan.TransactionRoot -ParentChain $plan.TransactionRootChain -Leaf $leaf
            if ($state.Exists) { Die "SYNAPSE_PROFILE_PREARM_FUTURE_ARTIFACT_COLLISION relative_path=$($record.relative_path) leaf=$leaf file_id_128=$($state.FileId128)" }
        }
    }
    $manifestStage = Get-SynapsePhysicalRelativeState -ParentPath $plan.TransactionRoot -ParentChain $plan.TransactionRootChain -Leaf ([string]$manifest.stage_leaf)
    if (-not (Test-SynapsePhysicalStateExact -State $manifestStage -ExpectedExists $true -ExpectedFileId128 ([string]$manifest.post_file_id_128) -ExpectedSha256 ([string]$manifest.post_sha256) -ExpectedLength ([int64]$manifest.post_length))) {
        Die "SYNAPSE_PROFILE_PREARM_MANIFEST_STAGE_DRIFT stage=$($manifest.stage_leaf)"
    }
    foreach ($leaf in @([string]$manifest.park_leaf,[string]$manifest.discard_leaf) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }) {
        $state = Get-SynapsePhysicalRelativeState -ParentPath $plan.TransactionRoot -ParentChain $plan.TransactionRootChain -Leaf $leaf
        if ($state.Exists) { Die "SYNAPSE_PROFILE_PREARM_MANIFEST_FUTURE_ARTIFACT_COLLISION leaf=$leaf file_id_128=$($state.FileId128)" }
    }
    if ($plan.RetiredEntries.Count -gt 0) {
        $quarantine = Get-SynapsePhysicalRelativeState -ParentPath $plan.TransactionRoot -ParentChain $plan.TransactionRootChain -Leaf ([string]$plan.Descriptor.quarantine_work_leaf) -Directory
        if (-not (Test-SynapsePhysicalStateExact -State $quarantine -ExpectedExists $true -ExpectedFileId128 ([string]$plan.Descriptor.quarantine_directory_file_id_128))) {
            Die "SYNAPSE_PROFILE_PREARM_QUARANTINE_IDENTITY_DRIFT leaf=$($plan.Descriptor.quarantine_work_leaf)"
        }
    }
    Info "SYNAPSE_PROFILE_PREARM_GENERATION_VALIDATED profiles_dir=$($plan.ProfilesDir) root_pre_existed=$($plan.RootPreExisted) root_file_id_128=$($plan.RootFileId128) source_count=$($plan.SourceEntries.Count) retired_count=$($plan.RetiredEntries.Count)"
    return $plan
}

function Get-SynapseProfileRootLocation {
    param([Parameter(Mandatory=$true)]$ProfilePlan)

    $canonical = Get-SynapsePhysicalRelativeState -ParentPath $ProfilePlan.ProfilesParent -ParentChain $ProfilePlan.ProfilesParentChain -Leaf $ProfilePlan.ProfilesLeaf -Directory
    $work = Get-SynapsePhysicalRelativeState -ParentPath $ProfilePlan.TransactionRoot -ParentChain $ProfilePlan.TransactionRootChain -Leaf $ProfilePlan.WorkLeaf -Directory
    $canonicalExact = Test-SynapsePhysicalStateExact -State $canonical -ExpectedExists $true -ExpectedFileId128 $ProfilePlan.RootFileId128
    $workExact = Test-SynapsePhysicalStateExact -State $work -ExpectedExists $true -ExpectedFileId128 $ProfilePlan.RootFileId128
    if ($canonicalExact -and -not $work.Exists) { return [pscustomobject]@{ Location='canonical'; Canonical=$canonical; Work=$work } }
    if ($workExact -and -not $canonical.Exists) { return [pscustomobject]@{ Location='work'; Canonical=$canonical; Work=$work } }
    if (-not $canonical.Exists -and -not $work.Exists) { return [pscustomobject]@{ Location='absent'; Canonical=$canonical; Work=$work } }
    Die "SYNAPSE_PROFILE_ROOT_LOCATION_AMBIGUOUS canonical_exists=$($canonical.Exists) canonical_file_id_128=$($canonical.FileId128) work_exists=$($work.Exists) work_file_id_128=$($work.FileId128) expected_root_file_id_128=$($ProfilePlan.RootFileId128) remediation=preserve both names; recovery never replaces an intervening root object"
}

function Move-SynapseProfileRootToWork {
    param([Parameter(Mandatory=$true)]$ProfilePlan)

    $location = Get-SynapseProfileRootLocation -ProfilePlan $ProfilePlan
    if ($location.Location -eq 'work') { return }
    if ($location.Location -eq 'absent' -and -not $ProfilePlan.RootPreExisted) {
        Die "SYNAPSE_PROFILE_ROOT_WORK_OBJECT_MISSING expected_file_id_128=$($ProfilePlan.RootFileId128) remediation=preserve the transaction; its precreated first-install root disappeared"
    }
    if ($location.Location -ne 'canonical') {
        Die "SYNAPSE_PROFILE_ROOT_ISOLATION_SOURCE_MISSING location=$($location.Location)"
    }
    [void](Move-SynapsePhysicalRelativeEntryNoReplace -SourceParentPath $ProfilePlan.ProfilesParent -SourceParentChain $ProfilePlan.ProfilesParentChain -SourceLeaf $ProfilePlan.ProfilesLeaf -ExpectedSourceFileId128 $ProfilePlan.RootFileId128 -DestinationParentPath $ProfilePlan.TransactionRoot -DestinationParentChain $ProfilePlan.TransactionRootChain -DestinationLeaf $ProfilePlan.WorkLeaf -Directory -Context 'isolate_profile_root')
}

function Get-SynapseProfileRootWorkChain {
    param([Parameter(Mandatory=$true)]$ProfilePlan)
    return @(Get-SynapsePhysicalDirectoryChainDescriptor -Path (Join-Path $ProfilePlan.TransactionRoot $ProfilePlan.WorkLeaf))
}

function Publish-SynapseProfileRootGeneration {
    param(
        [Parameter(Mandatory=$true)]$ProfilePlan,
        [Parameter(Mandatory=$true)]$OwnedEntries,
        $AllocationContext,
        [switch]$Candidate,
        [Parameter(Mandatory=$true)][string]$Context
    )

    Ensure-SynapseAtomicFileType
    $bridge = $null
    try {
        if ($null -ne $AllocationContext) {
            $workPath = Get-SynapseNormalizedDirectoryPath -Path (Join-Path $ProfilePlan.TransactionRoot $ProfilePlan.WorkLeaf)
            $workPrefix = $workPath + [System.IO.Path]::DirectorySeparatorChar
            foreach ($artifactLeaf in @($AllocationContext.ArtifactOrder)) {
                $artifact = $AllocationContext.Artifacts[$artifactLeaf]
                if ($null -eq $artifact.handle -or -not $artifact.handle.PSObject.Properties['CurrentPath']) { continue }
                $currentPath = [System.IO.Path]::GetFullPath([string]$artifact.handle.CurrentPath)
                if ($currentPath.StartsWith($workPrefix, [System.StringComparison]::OrdinalIgnoreCase)) {
                    $artifact.handle.RequireExact("profile_publication_bridge_release_$artifactLeaf")
                    $artifact.handle.Dispose()
                    $artifact.handle = $null
                }
            }
        }
        $bridge = [SynapseSetup.AtomicFileV2]::BeginPhysicalPublicationBridge(
            $ProfilePlan.TransactionRoot,
            (Get-SynapsePhysicalChainPaths -Chain $ProfilePlan.TransactionRootChain),
            (Get-SynapsePhysicalChainFileIds -Chain $ProfilePlan.TransactionRootChain),
            $ProfilePlan.WorkLeaf,
            $ProfilePlan.RootFileId128)
        if (@($ProfilePlan.RetiredEntries).Count -gt 0 -and $Candidate) {
            $quarantinePath = Join-Path (Join-Path $ProfilePlan.TransactionRoot $ProfilePlan.WorkLeaf) ([string]$ProfilePlan.Descriptor.quarantine_final_leaf)
            $quarantineChain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $quarantinePath)
            $actualQuarantineEntries = @(Get-SynapsePhysicalDirectoryEntriesBounded -Path $quarantinePath -Chain $quarantineChain -MaximumEntries $script:SynapseDeploymentArtifactMaxDirectEntries -Context 'profile_quarantine_publication')
            $actualQuarantineLeaves = @($actualQuarantineEntries | ForEach-Object {
                if ([bool]$_.IsDirectory -or ([uint32]$_.Attributes -band [uint32][System.IO.FileAttributes]::ReparsePoint)) {
                    Die "SYNAPSE_PROFILE_QUARANTINE_CONTENT_INVALID path=$($_.Path) remediation=persistent retirement quarantine accepts exact regular retired objects only"
                }
                $_.Name
            } | Sort-Object)
            $expectedQuarantineLeaves = @($ProfilePlan.RetiredEntries | ForEach-Object { [string]$_.relative_path } | Sort-Object)
            if ((Get-SynapseCanonicalJson -Value $actualQuarantineLeaves) -cne (Get-SynapseCanonicalJson -Value $expectedQuarantineLeaves)) {
                Die "SYNAPSE_PROFILE_QUARANTINE_SET_MISMATCH actual=$($actualQuarantineLeaves -join ',') expected=$($expectedQuarantineLeaves -join ',')"
            }
        }
        $lease = $bridge.PublishAndSeal(
            $ProfilePlan.ProfilesParent,
            (Get-SynapsePhysicalChainPaths -Chain $ProfilePlan.ProfilesParentChain),
            (Get-SynapsePhysicalChainFileIds -Chain $ProfilePlan.ProfilesParentChain),
            $ProfilePlan.ProfilesLeaf,
            [string[]]@($OwnedEntries | ForEach-Object { [string]$_.relative_path }),
            [string[]]@($OwnedEntries | ForEach-Object { [string]$_.file_id_128 }),
            [string[]]@($OwnedEntries | ForEach-Object { [string]$_.sha256 }),
            [long[]]@($OwnedEntries | ForEach-Object { [int64]$_.length }))
        $bridge = $null
        Info "SYNAPSE_PROFILE_ROOT_GENERATION_PUBLISHED context=$Context profiles_dir=$($ProfilePlan.ProfilesDir) root_file_id_128=$($ProfilePlan.RootFileId128) owned_file_count=$(@($OwnedEntries).Count) custom_delta_semantics=unowned_after_publication"
        return $lease
    } finally {
        if ($null -ne $bridge) { $bridge.Dispose() }
    }
}

function Install-SynapseBundledProfiles {
    param(
        [Parameter(Mandatory=$true)]$DeploymentPlan,
        [Parameter(Mandatory=$true)][string]$SourceProfilesDir,
        [Parameter(Mandatory=$true)][string]$ProfilesDir,
        [string]$LogDir = ''
    )

    if ($null -eq $script:SynapseDeploymentTransaction -or -not [bool]$script:SynapseDeploymentTransaction.Armed) {
        Die 'SYNAPSE_PROFILE_ROOT_INSTALL_TRANSACTION_NOT_ARMED remediation=profile mutation requires the durable deployment journal first'
    }
    $plan = Assert-SynapseBundledProfilesTransactionDescriptor -Descriptor $DeploymentPlan.Descriptor -ProfilesDir $ProfilesDir -TransactionRoot $script:SynapseDeploymentTransaction.Root
    Move-SynapseProfileRootToWork -ProfilePlan $plan
    $workPath = Join-Path $plan.TransactionRoot $plan.WorkLeaf
    $workChain = @(Get-SynapseProfileRootWorkChain -ProfilePlan $plan)

    foreach ($record in $plan.SourceEntries) {
        $target = Get-SynapsePhysicalRelativeState -ParentPath $workPath -ParentChain $workChain -Leaf ([string]$record.relative_path)
        if ([bool]$record.no_op) {
            if (-not (Test-SynapsePhysicalStateExact -State $target -ExpectedExists $true -ExpectedFileId128 ([string]$record.pre_file_id_128) -ExpectedSha256 ([string]$record.pre_sha256) -ExpectedLength ([int64]$record.pre_length))) {
                Die "SYNAPSE_PROFILE_INSTALL_NOOP_PREIMAGE_DRIFT relative_path=$($record.relative_path) remediation=the exact no-op object changed after the plan froze"
            }
            continue
        }
        $stage = Get-SynapsePhysicalRelativeState -ParentPath $plan.TransactionRoot -ParentChain $plan.TransactionRootChain -Leaf ([string]$record.stage_leaf)
        $park = if ([string]$record.park_leaf) { Get-SynapsePhysicalRelativeState -ParentPath $plan.TransactionRoot -ParentChain $plan.TransactionRootChain -Leaf ([string]$record.park_leaf) } else { $null }
        if ([bool]$record.pre_existed) {
            if (Test-SynapsePhysicalStateExact -State $target -ExpectedExists $true -ExpectedFileId128 ([string]$record.pre_file_id_128) -ExpectedSha256 ([string]$record.pre_sha256) -ExpectedLength ([int64]$record.pre_length)) {
                if ($park.Exists) { Die "SYNAPSE_PROFILE_INSTALL_PARK_COLLISION relative_path=$($record.relative_path) park=$($record.park_leaf)" }
                [void](Move-SynapsePhysicalRelativeEntryNoReplace -SourceParentPath $workPath -SourceParentChain $workChain -SourceLeaf ([string]$record.relative_path) -ExpectedSourceFileId128 ([string]$record.pre_file_id_128) -DestinationParentPath $plan.TransactionRoot -DestinationParentChain $plan.TransactionRootChain -DestinationLeaf ([string]$record.park_leaf) -ExpectedSha256 ([string]$record.pre_sha256) -ExpectedLength ([int64]$record.pre_length) -Context "park_source_$($record.relative_path)")
                $target = Get-SynapsePhysicalRelativeState -ParentPath $workPath -ParentChain $workChain -Leaf ([string]$record.relative_path)
            } elseif (-not (Test-SynapsePhysicalStateExact -State $target -ExpectedExists $true -ExpectedFileId128 ([string]$record.post_file_id_128) -ExpectedSha256 ([string]$record.post_sha256) -ExpectedLength ([int64]$record.post_length)) -and $target.Exists) {
                Die "SYNAPSE_PROFILE_INSTALL_TARGET_UNKNOWN relative_path=$($record.relative_path) file_id_128=$($target.FileId128) sha256=$($target.Sha256) remediation=preserve concurrent bytes"
            }
        } elseif ($target.Exists -and -not (Test-SynapsePhysicalStateExact -State $target -ExpectedExists $true -ExpectedFileId128 ([string]$record.post_file_id_128) -ExpectedSha256 ([string]$record.post_sha256) -ExpectedLength ([int64]$record.post_length))) {
            Die "SYNAPSE_PROFILE_INSTALL_NEW_TARGET_COLLISION relative_path=$($record.relative_path) file_id_128=$($target.FileId128) remediation=the custom arrival wins and remains untouched"
        }
        if (-not $target.Exists) {
            if (-not (Test-SynapsePhysicalStateExact -State $stage -ExpectedExists $true -ExpectedFileId128 ([string]$record.post_file_id_128) -ExpectedSha256 ([string]$record.post_sha256) -ExpectedLength ([int64]$record.post_length))) {
                Die "SYNAPSE_PROFILE_INSTALL_STAGE_MISSING relative_path=$($record.relative_path) stage=$($record.stage_leaf)"
            }
            [void](Move-SynapseAllocatedArtifactNoReplace -TransactionRoot $plan.TransactionRoot -TransactionRootChain $plan.TransactionRootChain -SourceLeaf ([string]$record.stage_leaf) -ExpectedFileId128 ([string]$record.post_file_id_128) -ExpectedSha256 ([string]$record.post_sha256) -ExpectedLength ([int64]$record.post_length) -DestinationParentPath $workPath -DestinationParentChain $workChain -DestinationLeaf ([string]$record.relative_path) -Context "publish_source_$($record.relative_path)")
        }
    }

    if ($plan.RetiredEntries.Count -gt 0) {
        $qWorkLeaf = [string]$plan.Descriptor.quarantine_work_leaf
        $qPath = Join-Path $plan.TransactionRoot $qWorkLeaf
        $qState = Get-SynapsePhysicalRelativeState -ParentPath $plan.TransactionRoot -ParentChain $plan.TransactionRootChain -Leaf $qWorkLeaf -Directory
        if (-not (Test-SynapsePhysicalStateExact -State $qState -ExpectedExists $true -ExpectedFileId128 ([string]$plan.Descriptor.quarantine_directory_file_id_128))) { Die 'SYNAPSE_PROFILE_QUARANTINE_WORK_IDENTITY_MISSING' }
        $qChain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $qPath)
        foreach ($record in $plan.RetiredEntries) {
            $active = Get-SynapsePhysicalRelativeState -ParentPath $workPath -ParentChain $workChain -Leaf ([string]$record.relative_path)
            $quarantined = Get-SynapsePhysicalRelativeState -ParentPath $qPath -ParentChain $qChain -Leaf ([string]$record.relative_path)
            if (Test-SynapsePhysicalStateExact -State $active -ExpectedExists $true -ExpectedFileId128 ([string]$record.pre_file_id_128) -ExpectedSha256 ([string]$record.pre_sha256) -ExpectedLength ([int64]$record.pre_length)) {
                if ($quarantined.Exists) { Die "SYNAPSE_PROFILE_RETIRE_DESTINATION_COLLISION relative_path=$($record.relative_path)" }
                [void](Move-SynapsePhysicalRelativeEntryNoReplace -SourceParentPath $workPath -SourceParentChain $workChain -SourceLeaf ([string]$record.relative_path) -ExpectedSourceFileId128 ([string]$record.pre_file_id_128) -DestinationParentPath $qPath -DestinationParentChain $qChain -DestinationLeaf ([string]$record.relative_path) -ExpectedSha256 ([string]$record.pre_sha256) -ExpectedLength ([int64]$record.pre_length) -Context "retire_$($record.relative_path)")
            } elseif (-not (Test-SynapsePhysicalStateExact -State $quarantined -ExpectedExists $true -ExpectedFileId128 ([string]$record.pre_file_id_128) -ExpectedSha256 ([string]$record.pre_sha256) -ExpectedLength ([int64]$record.pre_length)) -or $active.Exists) {
                Die "SYNAPSE_PROFILE_RETIRE_STATE_UNKNOWN relative_path=$($record.relative_path) active_exists=$($active.Exists) quarantine_exists=$($quarantined.Exists)"
            }
        }
        [void](Move-SynapsePhysicalRelativeEntryNoReplace -SourceParentPath $plan.TransactionRoot -SourceParentChain $plan.TransactionRootChain -SourceLeaf $qWorkLeaf -ExpectedSourceFileId128 ([string]$plan.Descriptor.quarantine_directory_file_id_128) -DestinationParentPath $workPath -DestinationParentChain $workChain -DestinationLeaf ([string]$plan.Descriptor.quarantine_final_leaf) -Directory -Context 'publish_retirement_quarantine')
    }

    $manifest = $plan.ManifestEntry
    $manifestTarget = Get-SynapsePhysicalRelativeState -ParentPath $workPath -ParentChain $workChain -Leaf ([string]$manifest.relative_path)
    if ([bool]$manifest.pre_existed) {
        if (-not (Test-SynapsePhysicalStateExact -State $manifestTarget -ExpectedExists $true -ExpectedFileId128 ([string]$manifest.pre_file_id_128) -ExpectedSha256 ([string]$manifest.pre_sha256) -ExpectedLength ([int64]$manifest.pre_length))) { Die 'SYNAPSE_PROFILE_MANIFEST_PREIMAGE_DRIFT' }
        [void](Move-SynapsePhysicalRelativeEntryNoReplace -SourceParentPath $workPath -SourceParentChain $workChain -SourceLeaf ([string]$manifest.relative_path) -ExpectedSourceFileId128 ([string]$manifest.pre_file_id_128) -DestinationParentPath $plan.TransactionRoot -DestinationParentChain $plan.TransactionRootChain -DestinationLeaf ([string]$manifest.park_leaf) -ExpectedSha256 ([string]$manifest.pre_sha256) -ExpectedLength ([int64]$manifest.pre_length) -Context 'park_profile_manifest')
    } elseif ($manifestTarget.Exists) { Die 'SYNAPSE_PROFILE_MANIFEST_NEW_COLLISION' }
    [void](Move-SynapseAllocatedArtifactNoReplace -TransactionRoot $plan.TransactionRoot -TransactionRootChain $plan.TransactionRootChain -SourceLeaf ([string]$manifest.stage_leaf) -ExpectedFileId128 ([string]$manifest.post_file_id_128) -ExpectedSha256 ([string]$manifest.post_sha256) -ExpectedLength ([int64]$manifest.post_length) -DestinationParentPath $workPath -DestinationParentChain $workChain -DestinationLeaf ([string]$manifest.relative_path) -Context 'publish_profile_manifest')

    # Legacy v3 used this preparation boundary as candidate_ready. Broker-era
    # v4 deliberately withholds candidate_ready until the installed generation
    # has run under its unique RegistrationTrigger-only probe and passed the
    # authenticated tool/resource contract. Publishing the profile root alone
    # is not candidate acceptance and must not consume slot two.
    if ($null -eq $script:SynapseDeploymentTransaction.PSObject.Properties['AuthorityModel'] -or
        [string]$script:SynapseDeploymentTransaction.AuthorityModel -cne 'immutable_broker/v1') {
        Add-SynapseDeploymentTransactionJournalState -State 'candidate_ready' -Payload ([ordered]@{ profile_generation_prepared=$true; profile_generation_published=$false; profile_generation=[ordered]@{ static_plan_sha256=$plan.StaticPlanSha256; root_file_id_128=$plan.RootFileId128; source_manifest_sha256=[string]$plan.Descriptor.source_manifest_sha256; installed_manifest_sha256=[string]$plan.Descriptor.installed_manifest_sha256; owned_file_count=$plan.CandidateOwnedEntries.Count } })
    }
    $lease = Publish-SynapseProfileRootGeneration -ProfilePlan $plan -OwnedEntries $plan.CandidateOwnedEntries -AllocationContext $script:SynapseDeploymentAllocationContext -Candidate -Context 'candidate'
    $script:SynapseDeploymentTransaction.ProfileGenerationLease = $lease
    $manifestReadback = Read-SynapseBundledProfilesManifest -ManifestPath (Join-Path $plan.ProfilesDir $script:SynapseBundledProfilesManifestFileName)
    if ([string]$manifestReadback.source_manifest_sha256 -ine [string]$plan.Descriptor.source_manifest_sha256) { Die 'SYNAPSE_PROFILE_MANIFEST_SOURCE_READBACK_MISMATCH' }
    Info "Bundled profile reconciliation complete source_files=$($plan.SourceEntries.Count) bundled_profiles=$(@($DeploymentPlan.SourceEntries | Where-Object profile_file).Count) custom_profiles=$($DeploymentPlan.CustomProfiles.Count) newly_quarantined_retired=$($plan.RetiredEntries.Count) carried_quarantined_retired=$($plan.CarriedQuarantineEntries.Count) manifest=$(Join-Path $plan.ProfilesDir $script:SynapseBundledProfilesManifestFileName) source_manifest_sha256=$($plan.Descriptor.source_manifest_sha256)"
    return [pscustomobject]@{ ManifestPath=(Join-Path $plan.ProfilesDir $script:SynapseBundledProfilesManifestFileName); ManifestSha256=[string]$plan.Descriptor.installed_manifest_sha256; SourceManifestSha256=[string]$plan.Descriptor.source_manifest_sha256; TransactionPlanSha256=$plan.StaticPlanSha256; BundledFileCount=$plan.SourceEntries.Count; BundledProfileCount=@($DeploymentPlan.SourceEntries | Where-Object profile_file).Count; CustomProfileCount=$DeploymentPlan.CustomProfiles.Count; QuarantinedRetiredCount=($plan.RetiredEntries.Count + $plan.CarriedQuarantineEntries.Count); RootFileId128=$plan.RootFileId128; OwnedEntries=$plan.CandidateOwnedEntries }
}

function Invoke-SynapseBundledProfilesTransactionRollback {
    param(
        [Parameter(Mandatory=$true)]$ProfilePlan,
        $FileSnapshots
    )

    if ($null -ne $script:SynapseDeploymentTransaction -and $null -ne $script:SynapseDeploymentTransaction.ProfileGenerationLease) {
        try { $script:SynapseDeploymentTransaction.ProfileGenerationLease.Dispose() } finally { $script:SynapseDeploymentTransaction.ProfileGenerationLease = $null }
    }
    $plan = if ($ProfilePlan.PSObject.Properties['Descriptor']) { $ProfilePlan } else {
        Assert-SynapseBundledProfilesTransactionDescriptor -Descriptor $ProfilePlan -ProfilesDir ([string]$ProfilePlan.profiles_dir) -TransactionRoot ([string]$ProfilePlan.transaction_root)
    }
    $location = Get-SynapseProfileRootLocation -ProfilePlan $plan
    if ($location.Location -eq 'canonical') {
        $priorAlreadyExact=$true
        $canonicalPath=[string]$plan.ProfilesDir
        $canonicalChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $canonicalPath)
        foreach($record in @($plan.SourceEntries)+@($plan.RetiredEntries)){
            $state=Get-SynapsePhysicalRelativeState -ParentPath $canonicalPath -ParentChain $canonicalChain -Leaf ([string]$record.relative_path)
            $expectedExists=[bool]$record.pre_existed
            if(-not(Test-SynapsePhysicalStateExact -State $state -ExpectedExists $expectedExists -ExpectedFileId128 ([string]$record.pre_file_id_128) -ExpectedSha256 ([string]$record.pre_sha256) -ExpectedLength ([int64]$record.pre_length))){$priorAlreadyExact=$false;break}
        }
        if($priorAlreadyExact){
            $manifest=$plan.ManifestEntry
            $manifestState=Get-SynapsePhysicalRelativeState -ParentPath $canonicalPath -ParentChain $canonicalChain -Leaf ([string]$manifest.relative_path)
            $priorAlreadyExact=Test-SynapsePhysicalStateExact -State $manifestState -ExpectedExists ([bool]$manifest.pre_existed) -ExpectedFileId128 ([string]$manifest.pre_file_id_128) -ExpectedSha256 ([string]$manifest.pre_sha256) -ExpectedLength ([int64]$manifest.pre_length)
        }
        if($priorAlreadyExact){
            Info "SYNAPSE_PROFILE_ROLLBACK_PRIOR_ALREADY_EXACT profiles_dir=$canonicalPath root_file_id_128=$($plan.RootFileId128)"
            return [pscustomobject]@{RestoredFileCount=0;ArtifactCount=0;PriorRootAbsent=$false;PriorAlreadyExact=$true;Lease=$null}
        }
        [void](Move-SynapsePhysicalRelativeEntryNoReplace -SourceParentPath $plan.ProfilesParent -SourceParentChain $plan.ProfilesParentChain -SourceLeaf $plan.ProfilesLeaf -ExpectedSourceFileId128 $plan.RootFileId128 -DestinationParentPath $plan.TransactionRoot -DestinationParentChain $plan.TransactionRootChain -DestinationLeaf $plan.WorkLeaf -Directory -Context 'rollback_isolate_profile_root')
        $location = Get-SynapseProfileRootLocation -ProfilePlan $plan
    }
    if ($location.Location -eq 'absent') {
        if ($plan.RootPreExisted) { Die 'SYNAPSE_PROFILE_ROLLBACK_PRIOR_ROOT_MISSING' }
        if ($null -ne $script:SynapseDeploymentTransaction -and
            $null -ne $script:SynapseDeploymentTransaction.PSObject.Properties['PreviousTask'] -and
            $null -ne $script:SynapseDeploymentTransaction.PreviousTask -and
            [bool]$script:SynapseDeploymentTransaction.PreviousTask.Present -and
            [bool]$script:SynapseDeploymentTransaction.PreviousTask.Enabled) {
            Die 'SYNAPSE_PROFILE_ROLLBACK_ABSENT_ROOT_ENABLED_TASK_UNSERIALIZABLE remediation=the exact prior absence has already been restored, but restart authority remains revoked because an absent root name cannot be sealed across enabled-task health'
        }
        return [pscustomobject]@{ RestoredFileCount=0; ArtifactCount=0; PriorRootAbsent=$true; Lease=$null }
    }
    if ($location.Location -ne 'work') { Die "SYNAPSE_PROFILE_ROLLBACK_ROOT_NOT_ISOLATED location=$($location.Location)" }
    $workPath = Join-Path $plan.TransactionRoot $plan.WorkLeaf
    $workChain = @(Get-SynapseProfileRootWorkChain -ProfilePlan $plan)
    $restored = 0

    foreach ($record in $plan.SourceEntries) {
        $target = Get-SynapsePhysicalRelativeState -ParentPath $workPath -ParentChain $workChain -Leaf ([string]$record.relative_path)
        if ([bool]$record.no_op) {
            if (-not (Test-SynapsePhysicalStateExact -State $target -ExpectedExists $true -ExpectedFileId128 ([string]$record.pre_file_id_128) -ExpectedSha256 ([string]$record.pre_sha256) -ExpectedLength ([int64]$record.pre_length))) {
                Die "SYNAPSE_PROFILE_ROLLBACK_NOOP_UNKNOWN relative_path=$($record.relative_path) remediation=preserve the unexpected object and keep restart authority revoked"
            }
            continue
        }
        $candidateExact = Test-SynapsePhysicalStateExact -State $target -ExpectedExists $true -ExpectedFileId128 ([string]$record.post_file_id_128) -ExpectedSha256 ([string]$record.post_sha256) -ExpectedLength ([int64]$record.post_length)
        if ($candidateExact) {
            $discard = Get-SynapsePhysicalRelativeState -ParentPath $plan.TransactionRoot -ParentChain $plan.TransactionRootChain -Leaf ([string]$record.discard_leaf)
            if ($discard.Exists) { Die "SYNAPSE_PROFILE_ROLLBACK_DISCARD_COLLISION relative_path=$($record.relative_path) discard=$($record.discard_leaf)" }
            [void](Move-SynapsePhysicalRelativeEntryNoReplace -SourceParentPath $workPath -SourceParentChain $workChain -SourceLeaf ([string]$record.relative_path) -ExpectedSourceFileId128 ([string]$record.post_file_id_128) -DestinationParentPath $plan.TransactionRoot -DestinationParentChain $plan.TransactionRootChain -DestinationLeaf ([string]$record.discard_leaf) -ExpectedSha256 ([string]$record.post_sha256) -ExpectedLength ([int64]$record.post_length) -Context "rollback_discard_source_$($record.relative_path)")
            $target = Get-SynapsePhysicalRelativeState -ParentPath $workPath -ParentChain $workChain -Leaf ([string]$record.relative_path)
        }
        if ([bool]$record.pre_existed) {
            $preExact = Test-SynapsePhysicalStateExact -State $target -ExpectedExists $true -ExpectedFileId128 ([string]$record.pre_file_id_128) -ExpectedSha256 ([string]$record.pre_sha256) -ExpectedLength ([int64]$record.pre_length)
            $park = Get-SynapsePhysicalRelativeState -ParentPath $plan.TransactionRoot -ParentChain $plan.TransactionRootChain -Leaf ([string]$record.park_leaf)
            $parkExact = Test-SynapsePhysicalStateExact -State $park -ExpectedExists $true -ExpectedFileId128 ([string]$record.pre_file_id_128) -ExpectedSha256 ([string]$record.pre_sha256) -ExpectedLength ([int64]$record.pre_length)
            if ($preExact -and -not $park.Exists) { continue }
            if (-not $target.Exists -and $parkExact) {
                [void](Move-SynapsePhysicalRelativeEntryNoReplace -SourceParentPath $plan.TransactionRoot -SourceParentChain $plan.TransactionRootChain -SourceLeaf ([string]$record.park_leaf) -ExpectedSourceFileId128 ([string]$record.pre_file_id_128) -DestinationParentPath $workPath -DestinationParentChain $workChain -DestinationLeaf ([string]$record.relative_path) -ExpectedSha256 ([string]$record.pre_sha256) -ExpectedLength ([int64]$record.pre_length) -Context "rollback_restore_source_$($record.relative_path)")
                $restored++
                continue
            }
            Die "SYNAPSE_PROFILE_ROLLBACK_SOURCE_UNKNOWN relative_path=$($record.relative_path) target_exists=$($target.Exists) target_file_id_128=$($target.FileId128) park_exists=$($park.Exists) park_file_id_128=$($park.FileId128) remediation=unknown concurrent bytes remain untouched"
        } elseif ($target.Exists) {
            Die "SYNAPSE_PROFILE_ROLLBACK_NEW_SOURCE_UNKNOWN relative_path=$($record.relative_path) file_id_128=$($target.FileId128) sha256=$($target.Sha256) remediation=the unexpected custom arrival remains untouched and restart authority stays revoked"
        }
    }

    if ($plan.RetiredEntries.Count -gt 0) {
        $qWorkLeaf = [string]$plan.Descriptor.quarantine_work_leaf
        $qFinalLeaf = [string]$plan.Descriptor.quarantine_final_leaf
        $qFinal = Get-SynapsePhysicalRelativeState -ParentPath $workPath -ParentChain $workChain -Leaf $qFinalLeaf -Directory
        $qWork = Get-SynapsePhysicalRelativeState -ParentPath $plan.TransactionRoot -ParentChain $plan.TransactionRootChain -Leaf $qWorkLeaf -Directory
        $qId = [string]$plan.Descriptor.quarantine_directory_file_id_128
        if (Test-SynapsePhysicalStateExact -State $qFinal -ExpectedExists $true -ExpectedFileId128 $qId) {
            if ($qWork.Exists) { Die 'SYNAPSE_PROFILE_ROLLBACK_QUARANTINE_NAME_COLLISION' }
            [void](Move-SynapsePhysicalRelativeEntryNoReplace -SourceParentPath $workPath -SourceParentChain $workChain -SourceLeaf $qFinalLeaf -ExpectedSourceFileId128 $qId -DestinationParentPath $plan.TransactionRoot -DestinationParentChain $plan.TransactionRootChain -DestinationLeaf $qWorkLeaf -Directory -Context 'rollback_isolate_quarantine')
            $qWork = Get-SynapsePhysicalRelativeState -ParentPath $plan.TransactionRoot -ParentChain $plan.TransactionRootChain -Leaf $qWorkLeaf -Directory
        } elseif ($qFinal.Exists) { Die "SYNAPSE_PROFILE_ROLLBACK_QUARANTINE_UNKNOWN file_id_128=$($qFinal.FileId128)" }
        if ($qWork.Exists) {
            if (-not (Test-SynapsePhysicalStateExact -State $qWork -ExpectedExists $true -ExpectedFileId128 $qId)) { Die 'SYNAPSE_PROFILE_ROLLBACK_QUARANTINE_WORK_UNKNOWN' }
            $qPath = Join-Path $plan.TransactionRoot $qWorkLeaf
            $qChain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $qPath)
            foreach ($record in $plan.RetiredEntries) {
                $active = Get-SynapsePhysicalRelativeState -ParentPath $workPath -ParentChain $workChain -Leaf ([string]$record.relative_path)
                $quarantined = Get-SynapsePhysicalRelativeState -ParentPath $qPath -ParentChain $qChain -Leaf ([string]$record.relative_path)
                $activeExact = Test-SynapsePhysicalStateExact -State $active -ExpectedExists $true -ExpectedFileId128 ([string]$record.pre_file_id_128) -ExpectedSha256 ([string]$record.pre_sha256) -ExpectedLength ([int64]$record.pre_length)
                $qExact = Test-SynapsePhysicalStateExact -State $quarantined -ExpectedExists $true -ExpectedFileId128 ([string]$record.pre_file_id_128) -ExpectedSha256 ([string]$record.pre_sha256) -ExpectedLength ([int64]$record.pre_length)
                if ($activeExact -and -not $quarantined.Exists) { continue }
                if (-not $active.Exists -and $qExact) {
                    [void](Move-SynapsePhysicalRelativeEntryNoReplace -SourceParentPath $qPath -SourceParentChain $qChain -SourceLeaf ([string]$record.relative_path) -ExpectedSourceFileId128 ([string]$record.pre_file_id_128) -DestinationParentPath $workPath -DestinationParentChain $workChain -DestinationLeaf ([string]$record.relative_path) -ExpectedSha256 ([string]$record.pre_sha256) -ExpectedLength ([int64]$record.pre_length) -Context "rollback_restore_retired_$($record.relative_path)")
                    $restored++
                    continue
                }
                Die "SYNAPSE_PROFILE_ROLLBACK_RETIRED_UNKNOWN relative_path=$($record.relative_path) active_exists=$($active.Exists) quarantine_exists=$($quarantined.Exists) remediation=preserve the collision"
            }
        }
    }

    $manifest = $plan.ManifestEntry
    $manifestTarget = Get-SynapsePhysicalRelativeState -ParentPath $workPath -ParentChain $workChain -Leaf ([string]$manifest.relative_path)
    if (Test-SynapsePhysicalStateExact -State $manifestTarget -ExpectedExists $true -ExpectedFileId128 ([string]$manifest.post_file_id_128) -ExpectedSha256 ([string]$manifest.post_sha256) -ExpectedLength ([int64]$manifest.post_length)) {
        $discard = Get-SynapsePhysicalRelativeState -ParentPath $plan.TransactionRoot -ParentChain $plan.TransactionRootChain -Leaf ([string]$manifest.discard_leaf)
        if ($discard.Exists) { Die 'SYNAPSE_PROFILE_ROLLBACK_MANIFEST_DISCARD_COLLISION' }
        [void](Move-SynapsePhysicalRelativeEntryNoReplace -SourceParentPath $workPath -SourceParentChain $workChain -SourceLeaf ([string]$manifest.relative_path) -ExpectedSourceFileId128 ([string]$manifest.post_file_id_128) -DestinationParentPath $plan.TransactionRoot -DestinationParentChain $plan.TransactionRootChain -DestinationLeaf ([string]$manifest.discard_leaf) -ExpectedSha256 ([string]$manifest.post_sha256) -ExpectedLength ([int64]$manifest.post_length) -Context 'rollback_discard_manifest')
        $manifestTarget = Get-SynapsePhysicalRelativeState -ParentPath $workPath -ParentChain $workChain -Leaf ([string]$manifest.relative_path)
    }
    if ([bool]$manifest.pre_existed) {
        $preExact = Test-SynapsePhysicalStateExact -State $manifestTarget -ExpectedExists $true -ExpectedFileId128 ([string]$manifest.pre_file_id_128) -ExpectedSha256 ([string]$manifest.pre_sha256) -ExpectedLength ([int64]$manifest.pre_length)
        $park = Get-SynapsePhysicalRelativeState -ParentPath $plan.TransactionRoot -ParentChain $plan.TransactionRootChain -Leaf ([string]$manifest.park_leaf)
        $parkExact = Test-SynapsePhysicalStateExact -State $park -ExpectedExists $true -ExpectedFileId128 ([string]$manifest.pre_file_id_128) -ExpectedSha256 ([string]$manifest.pre_sha256) -ExpectedLength ([int64]$manifest.pre_length)
        if (-not $preExact) {
            if (-not $manifestTarget.Exists -and $parkExact) {
                [void](Move-SynapsePhysicalRelativeEntryNoReplace -SourceParentPath $plan.TransactionRoot -SourceParentChain $plan.TransactionRootChain -SourceLeaf ([string]$manifest.park_leaf) -ExpectedSourceFileId128 ([string]$manifest.pre_file_id_128) -DestinationParentPath $workPath -DestinationParentChain $workChain -DestinationLeaf ([string]$manifest.relative_path) -ExpectedSha256 ([string]$manifest.pre_sha256) -ExpectedLength ([int64]$manifest.pre_length) -Context 'rollback_restore_manifest')
                $restored++
            } else { Die 'SYNAPSE_PROFILE_ROLLBACK_MANIFEST_UNKNOWN' }
        }
    } elseif ($manifestTarget.Exists) { Die 'SYNAPSE_PROFILE_ROLLBACK_MANIFEST_ABSENCE_COLLISION' }

    if ($plan.RootPreExisted) {
        $lease = Publish-SynapseProfileRootGeneration -ProfilePlan $plan -OwnedEntries $plan.PriorOwnedEntries -AllocationContext $script:SynapseDeploymentAllocationContext -Context 'rollback_prior'
        if ($null -ne $script:SynapseDeploymentTransaction) { $script:SynapseDeploymentTransaction.ProfileGenerationLease = $lease }
        return [pscustomobject]@{ RestoredFileCount=$restored; ArtifactCount=$plan.ProfileArtifacts.Count; PriorRootAbsent=$false; Lease=$lease }
    }
    if ($null -ne $script:SynapseDeploymentTransaction -and
        $null -ne $script:SynapseDeploymentTransaction.PSObject.Properties['PreviousTask'] -and
        $null -ne $script:SynapseDeploymentTransaction.PreviousTask -and
        [bool]$script:SynapseDeploymentTransaction.PreviousTask.Present -and
        [bool]$script:SynapseDeploymentTransaction.PreviousTask.Enabled) {
        Die 'SYNAPSE_PROFILE_ROLLBACK_ABSENT_ROOT_ENABLED_TASK_UNSERIALIZABLE remediation=the exact prior absence is restored but an enabled prior task cannot be authenticated across an unlocked absent directory name; restart authority remains revoked'
    }
    Remove-SynapsePhysicalRelativeEntryExact -ParentPath $plan.TransactionRoot -ParentChain $plan.TransactionRootChain -Leaf $plan.WorkLeaf -ExpectedFileId128 $plan.RootFileId128 -Directory -Context 'rollback_remove_first_install_root'
    return [pscustomobject]@{ RestoredFileCount=$restored; ArtifactCount=$plan.ProfileArtifacts.Count; PriorRootAbsent=$true; Lease=$null }
}

function Complete-SynapseBundledProfilesCommittedGeneration {
    param([Parameter(Mandatory=$true)]$ProfilePlan)

    $location = Get-SynapseProfileRootLocation -ProfilePlan $ProfilePlan
    if ($location.Location -eq 'canonical') {
        Info "SYNAPSE_PROFILE_COMMIT_RECOVERY_ROOT_ALREADY_CANONICAL profiles_dir=$($ProfilePlan.ProfilesDir) root_file_id_128=$($ProfilePlan.RootFileId128) semantics=post_decision_custom_deltas_preserved"
        return
    }
    if ($location.Location -ne 'work') {
        Die "SYNAPSE_PROFILE_COMMIT_RECOVERY_ROOT_MISSING location=$($location.Location) expected_root_file_id_128=$($ProfilePlan.RootFileId128) remediation=commit decision is durable but its exact root object is not at canonical/work; preserve all objects"
    }
    $lease = Publish-SynapseProfileRootGeneration -ProfilePlan $ProfilePlan -OwnedEntries $ProfilePlan.CandidateOwnedEntries -Candidate -Context 'commit_recovery_roll_forward'
    $lease.Dispose()
    Info "SYNAPSE_PROFILE_COMMIT_RECOVERY_ROOT_REPUBLISHED profiles_dir=$($ProfilePlan.ProfilesDir) root_file_id_128=$($ProfilePlan.RootFileId128)"
}

function New-SynapseSetupRunDirectory {
    param(
        [Parameter(Mandatory=$true)][string]$Root,
        [Parameter(Mandatory=$true)][string]$Purpose
    )

    $safePurpose = $Purpose -replace '[^A-Za-z0-9_.-]', '_'
    $stamp = (Get-Date).ToUniversalTime().ToString('yyyyMMddTHHmmssfffZ')
    $path = Join-Path $Root "$safePurpose-$stamp-$PID"
    New-Item -ItemType Directory -Force -Path $path | Out-Null
    return $path
}

function Get-SynapseDaemonStagingDescriptor {
    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$ExpectedRoot
    )

    $rootFull = Get-SynapseFullPathForScopeCheck -Path $ExpectedRoot
    if (-not (Test-Path -LiteralPath $rootFull -PathType Container)) {
        throw "SYNAPSE_DAEMON_STAGING_ROOT_MISSING root=$rootFull remediation=do not delete anything; rerun setup so the exact setup-owned root can be inspected"
    }
    $rootItem = Get-Item -LiteralPath $rootFull -Force -ErrorAction Stop
    if ($rootItem.Attributes -band [System.IO.FileAttributes]::ReparsePoint) {
        throw "SYNAPSE_DAEMON_STAGING_ROOT_REPARSE_POINT root=$rootFull attributes=$($rootItem.Attributes) remediation=do not follow or delete this link; restore setup-staging as a physical directory"
    }

    $pathFull = Get-SynapseFullPathForScopeCheck -Path $Path
    $actualParent = Get-SynapseFullPathForScopeCheck -Path (Split-Path -Parent $pathFull)
    if (-not $actualParent.Equals($rootFull, [System.StringComparison]::OrdinalIgnoreCase)) {
        throw "SYNAPSE_DAEMON_STAGING_SCOPE_INVALID path=$pathFull expected_parent=$rootFull actual_parent=$actualParent remediation=do not delete this path; inspect setup run-directory construction"
    }
    $leaf = Split-Path -Leaf $pathFull
    if ($leaf -notmatch '^daemon-binary-\d{8}T\d{9}Z-\d+$') {
        throw "SYNAPSE_DAEMON_STAGING_NAME_INVALID path=$pathFull leaf=$leaf remediation=do not delete this directory; only exact setup-owned daemon-binary timestamp/PID names are eligible"
    }
    if (-not (Test-Path -LiteralPath $pathFull -PathType Container)) {
        throw "SYNAPSE_DAEMON_STAGING_DIRECTORY_MISSING path=$pathFull remediation=refresh the setup-staging Source of Truth before retrying cleanup"
    }
    $directory = Get-Item -LiteralPath $pathFull -Force -ErrorAction Stop
    if ($directory.Attributes -band [System.IO.FileAttributes]::ReparsePoint) {
        throw "SYNAPSE_DAEMON_STAGING_DIRECTORY_REPARSE_POINT path=$pathFull attributes=$($directory.Attributes) remediation=do not follow or delete this link; inspect the setup-staging directory"
    }

    $items = @(Get-ChildItem -LiteralPath $pathFull -Force -ErrorAction Stop)
    if ($items.Count -gt 4) {
        throw "SYNAPSE_DAEMON_STAGING_ENTRY_BOUND_EXCEEDED path=$pathFull count=$($items.Count) max=4 remediation=do not delete this directory; inspect the unexpected setup-staging contents"
    }
    $invalid = @($items | Where-Object {
        $_.PSIsContainer -or
        ($_.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -or
        $_.Name -notmatch '^(synapse-mcp-[0-9A-Fa-f]{64}\.exe|onnxruntime\.dll|onnxruntime_providers_shared\.dll|onnxruntime_providers_cuda\.dll)$'
    })
    if ($invalid.Count -gt 0) {
        $invalidState = ($invalid | ForEach-Object { "name=$($_.Name),container=$($_.PSIsContainer),attributes=$($_.Attributes)" }) -join ';'
        throw "SYNAPSE_DAEMON_STAGING_CONTENT_INVALID path=$pathFull invalid=[$invalidState] remediation=do not delete this directory; inspect why an unowned entry exists under setup-staging"
    }
    $executables = @($items | Where-Object { $_.Name -match '^synapse-mcp-[0-9A-Fa-f]{64}\.exe$' })
    if ($items.Count -gt 0 -and $executables.Count -ne 1) {
        throw "SYNAPSE_DAEMON_STAGING_EXECUTABLE_CARDINALITY_INVALID path=$pathFull item_count=$($items.Count) executable_count=$($executables.Count) remediation=do not delete this directory; setup-owned non-empty staging must contain exactly one hash-named daemon executable"
    }
    $bytes = ($items | Measure-Object -Property Length -Sum).Sum
    if ($null -eq $bytes) { $bytes = 0 }
    return [pscustomobject]@{
        Path = $pathFull
        ItemCount = $items.Count
        Bytes = [int64]$bytes
    }
}

function Get-SynapseWindowsMemoryReadback {
    $readback = [ordered]@{
        schema = 'synapse_setup_windows_memory_readback/v1'
        observed_at_utc = (Get-Date).ToUniversalTime().ToString('o')
        source_of_truth = 'Win32_OperatingSystem + Win32_PageFileUsage'
        total_physical_bytes = $null
        available_physical_bytes = $null
        commit_limit_bytes = $null
        commit_available_bytes = $null
        commit_charge_bytes = $null
        commit_percent = $null
        pagefiles = @()
        read_succeeded = $false
        error = $null
    }
    try {
        $os = Get-CimInstance Win32_OperatingSystem -ErrorAction Stop
        $totalPhysical = [uint64]$os.TotalVisibleMemorySize * [uint64]1024
        $availablePhysical = [uint64]$os.FreePhysicalMemory * [uint64]1024
        $commitLimit = [uint64]$os.TotalVirtualMemorySize * [uint64]1024
        $commitAvailable = [uint64]$os.FreeVirtualMemory * [uint64]1024
        $commitCharge = if ($commitLimit -ge $commitAvailable) {
            $commitLimit - $commitAvailable
        } else {
            [uint64]0
        }
        $readback.total_physical_bytes = $totalPhysical
        $readback.available_physical_bytes = $availablePhysical
        $readback.commit_limit_bytes = $commitLimit
        $readback.commit_available_bytes = $commitAvailable
        $readback.commit_charge_bytes = $commitCharge
        $readback.commit_percent = if ($commitLimit -gt 0) {
            [math]::Round(([double]$commitCharge / [double]$commitLimit) * 100, 2)
        } else {
            $null
        }
        $readback.pagefiles = @(Get-CimInstance Win32_PageFileUsage -ErrorAction Stop |
            Select-Object Name, AllocatedBaseSize, CurrentUsage, PeakUsage, TempPageFile)
        $readback.read_succeeded = $true
    } catch {
        $readback.error = $_.Exception.Message
    }
    return [pscustomobject]$readback
}

function Assert-SynapseDaemonStagingHasNoLiveExecutable {
    param([Parameter(Mandatory=$true)][string]$Path)

    $pathFull = Get-SynapseFullPathForScopeCheck -Path $Path
    $pathPrefix = $pathFull + [System.IO.Path]::DirectorySeparatorChar
    $processes = @(Get-CimInstance Win32_Process -ErrorAction Stop)
    foreach ($process in $processes) {
        if ([string]::IsNullOrWhiteSpace([string]$process.ExecutablePath)) {
            if ([string]$process.Name -like 'synapse-mcp*') {
                # Win32_Process can retain a row captured immediately before
                # process exit while ExecutablePath is already unavailable.
                # Re-read that exact PID at the deletion boundary.  Only a
                # separately observed absence is safe to ignore; a live row
                # with an unreadable path remains an ownership ambiguity.
                $boundary = @(Get-CimInstance Win32_Process -Filter "ProcessId=$([int]$process.ProcessId)" -ErrorAction Stop)
                if ($boundary.Count -eq 0) { continue }
                throw "SYNAPSE_DAEMON_STAGING_PROCESS_PATH_UNREADABLE pid=$($process.ProcessId) name=$($process.Name) staging_path=$pathFull remediation=do not delete staging while a Synapse executable path cannot be read; inspect this exact PID"
            }
            continue
        }
        $executableFull = [System.IO.Path]::GetFullPath([string]$process.ExecutablePath)
        if ($executableFull.StartsWith($pathPrefix, [System.StringComparison]::OrdinalIgnoreCase)) {
            throw "SYNAPSE_DAEMON_STAGING_EXECUTABLE_LIVE pid=$($process.ProcessId) executable=$executableFull staging_path=$pathFull remediation=stop only this exact setup-owned candidate process, verify it exited, then rerun setup cleanup"
        }
    }
}

function Remove-SynapseDaemonStagingDirectory {
    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$ExpectedRoot,
        [string]$Reason = 'setup_cleanup'
    )

    # Independently re-read the complete descriptor and process SoT at the
    # destructive boundary; callers may have supplied a stale enumeration.
    $descriptor = Get-SynapseDaemonStagingDescriptor -Path $Path -ExpectedRoot $ExpectedRoot
    Assert-SynapseDaemonStagingHasNoLiveExecutable -Path $descriptor.Path
    foreach ($file in @(Get-ChildItem -LiteralPath $descriptor.Path -File -Force -ErrorAction Stop)) {
        Remove-Item -LiteralPath $file.FullName -Force -ErrorAction Stop
        if (Test-Path -LiteralPath $file.FullName) {
            throw "SYNAPSE_DAEMON_STAGING_FILE_CLEANUP_UNVERIFIED path=$($file.FullName) reason=$Reason remediation=inspect filesystem permissions and handles; the exact setup-owned file still exists after Remove-Item"
        }
    }
    Remove-Item -LiteralPath $descriptor.Path -Force -ErrorAction Stop
    if (Test-Path -LiteralPath $descriptor.Path) {
        throw "SYNAPSE_DAEMON_STAGING_CLEANUP_UNVERIFIED path=$($descriptor.Path) reason=$Reason remediation=inspect filesystem permissions and handles; the exact directory still exists after Remove-Item"
    }
    Info "Daemon staging artifact removed reason=$Reason path=$($descriptor.Path) item_count=$($descriptor.ItemCount) bytes=$($descriptor.Bytes) readback_exists=false"
    return $descriptor
}

function Remove-SynapseStaleDaemonStagingArtifacts {
    param([Parameter(Mandatory=$true)][string]$LogDir)

    $stagingRoot = Get-SynapseFullPathForScopeCheck -Path (Join-Path $LogDir 'setup-staging')
    if (-not (Test-Path -LiteralPath $stagingRoot)) {
        Info "Daemon staging stale sweep root=$stagingRoot before_count=0 before_bytes=0 after_count=0 after_bytes=0"
        return
    }
    if (-not (Test-Path -LiteralPath $stagingRoot -PathType Container)) {
        throw "SYNAPSE_DAEMON_STAGING_ROOT_NOT_DIRECTORY root=$stagingRoot remediation=do not delete this path; restore setup-staging as a physical directory"
    }
    $rootItem = Get-Item -LiteralPath $stagingRoot -Force -ErrorAction Stop
    if ($rootItem.Attributes -band [System.IO.FileAttributes]::ReparsePoint) {
        throw "SYNAPSE_DAEMON_STAGING_ROOT_REPARSE_POINT root=$stagingRoot attributes=$($rootItem.Attributes) remediation=do not follow or delete this link; restore setup-staging as a physical directory"
    }
    $children = @(Get-ChildItem -LiteralPath $stagingRoot -Force -ErrorAction Stop)
    if ($children.Count -gt 4096) {
        throw "SYNAPSE_DAEMON_STAGING_DIRECTORY_BOUND_EXCEEDED root=$stagingRoot count=$($children.Count) max=4096 remediation=inspect the unexpectedly large setup-owned root before cleanup"
    }
    $nonDirectories = @($children | Where-Object { -not $_.PSIsContainer })
    if ($nonDirectories.Count -gt 0) {
        $names = ($nonDirectories | Select-Object -ExpandProperty Name) -join ','
        throw "SYNAPSE_DAEMON_STAGING_ROOT_CONTENT_INVALID root=$stagingRoot files=[$names] remediation=do not delete anything; only setup-owned run directories may exist directly under this root"
    }

    $validated = @()
    foreach ($child in @($children | Sort-Object Name)) {
        $validated += Get-SynapseDaemonStagingDescriptor -Path $child.FullName -ExpectedRoot $stagingRoot
    }
    $beforeBytes = ($validated | Measure-Object -Property Bytes -Sum).Sum
    if ($null -eq $beforeBytes) { $beforeBytes = 0 }
    $retainedLive = @()
    foreach ($descriptor in $validated) {
        try {
            [void](Remove-SynapseDaemonStagingDirectory -Path $descriptor.Path -ExpectedRoot $stagingRoot -Reason 'startup_stale_sweep')
        } catch {
            $message=[string]$_.Exception.Message
            if($message.StartsWith('SYNAPSE_DAEMON_STAGING_EXECUTABLE_LIVE ',[System.StringComparison]::Ordinal)){
                $retainedLive += [string]$descriptor.Path
                Info "SYNAPSE_DAEMON_STAGING_LIVE_GENERATION_RETAINED path=$($descriptor.Path) detail=$message"
                continue
            }
            throw
        }
    }
    $after = @(Get-ChildItem -LiteralPath $stagingRoot -Force -ErrorAction Stop)
    $afterPaths=@($after|ForEach-Object{[System.IO.Path]::GetFullPath($_.FullName)}|Sort-Object)
    $expectedAfter=@($retainedLive|ForEach-Object{[System.IO.Path]::GetFullPath($_)}|Sort-Object)
    if(($afterPaths-join "`n") -cne ($expectedAfter-join "`n")){
        throw "SYNAPSE_DAEMON_STAGING_SWEEP_READBACK_FAILED root=$stagingRoot before_count=$($validated.Count) before_bytes=$beforeBytes expected_retained=[$($expectedAfter-join ',')] actual=[$($afterPaths-join ',')] remediation=inspect the exact remaining setup-staging entries before rerunning setup"
    }
    Info "Daemon staging stale sweep root=$stagingRoot before_count=$($validated.Count) before_bytes=$beforeBytes retained_live_count=$($expectedAfter.Count) retained_live=[$($expectedAfter-join ',')]"
}

function Remove-SynapseCurrentDaemonStagingArtifact {
    if ([string]::IsNullOrWhiteSpace([string]$script:SynapseCurrentDaemonStagingDirectory)) {
        return
    }
    $stagingRoot = Get-SynapseFullPathForScopeCheck -Path (Join-Path $LogDir 'setup-staging')
    [void](Remove-SynapseDaemonStagingDirectory -Path $script:SynapseCurrentDaemonStagingDirectory -ExpectedRoot $stagingRoot -Reason 'current_setup_run')
    $script:SynapseCurrentDaemonStagingDirectory = $null
}

function Assert-SynapseAcquisitionExactPropertySet {
    param(
        [Parameter(Mandatory=$true)]$Value,
        [Parameter(Mandatory=$true)][string[]]$Expected,
        [Parameter(Mandatory=$true)][string]$Context
    )

    if ($null -eq $Value) {
        throw "SYNAPSE_ACQUISITION_PROPERTY_SET_NULL context=$Context"
    }
    $actual = if ($Value -is [System.Collections.IDictionary]) {
        @($Value.Keys | ForEach-Object { [string]$_ })
    } else {
        @($Value.PSObject.Properties.Name | ForEach-Object { [string]$_ })
    }
    $expectedSet = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::Ordinal)
    foreach ($name in $Expected) { [void]$expectedSet.Add($name) }
    $actualSet = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::Ordinal)
    foreach ($name in $actual) { [void]$actualSet.Add($name) }
    $missing = @($Expected | Where-Object { -not $actualSet.Contains($_) })
    $extra = @($actual | Where-Object { -not $expectedSet.Contains($_) })
    if ($missing.Count -ne 0 -or $extra.Count -ne 0 -or $actual.Count -ne $Expected.Count) {
        throw "SYNAPSE_ACQUISITION_PROPERTY_SET_INVALID context=$Context missing=$($missing -join ',') extra=$($extra -join ',') actual_count=$($actual.Count) expected_count=$($Expected.Count)"
    }
}

function Get-SynapseAcquisitionCreatorProcessIdentity {
    param(
        [Parameter(Mandatory=$true)][ValidateRange(1,[int]::MaxValue)][int]$CreatorPid,
        [Parameter(Mandatory=$true)][string]$Context
    )

    $process = $null
    try {
        try {
            $process = [System.Diagnostics.Process]::GetProcessById($CreatorPid)
        } catch [System.ArgumentException] {
            return [pscustomobject][ordered]@{
                exists = $false
                pid = $CreatorPid
                creation_time_filetime_utc = [int64]0
            }
        }
        $creation = [int64]$process.StartTime.ToUniversalTime().ToFileTimeUtc()
        if ($creation -le 0) {
            throw "invalid process creation time $creation"
        }
        return [pscustomobject][ordered]@{
            exists = $true
            pid = $CreatorPid
            creation_time_filetime_utc = $creation
        }
    } catch {
        try {
            $probe = [System.Diagnostics.Process]::GetProcessById($CreatorPid)
            $probe.Dispose()
        } catch [System.ArgumentException] {
            return [pscustomobject][ordered]@{
                exists = $false
                pid = $CreatorPid
                creation_time_filetime_utc = [int64]0
            }
        } catch {
            throw "SYNAPSE_ACQUISITION_CREATOR_PRESENCE_UNREADABLE context=$Context pid=$CreatorPid error=$($_.Exception.Message) remediation=preserve the marker-bound allocation until the kernel process table is readable"
        }
        throw "SYNAPSE_ACQUISITION_CREATOR_IDENTITY_UNREADABLE context=$Context pid=$CreatorPid error=$($_.Exception.Message) remediation=preserve the marker-bound allocation until its creator start time can be read exactly"
    } finally {
        if ($null -ne $process) { $process.Dispose() }
    }
}

function Read-SynapseAcquisitionAllocationMarker {
    param(
        [Parameter(Mandatory=$true)][string]$AcquisitionRoot,
        [Parameter(Mandatory=$true)]$AcquisitionRootChain,
        [Parameter(Mandatory=$true)][string]$MarkerLeaf,
        [Parameter(Mandatory=$true)][string]$Context
    )

    $root = Get-SynapseNormalizedDirectoryPath -Path $AcquisitionRoot
    $rootChain = @(Assert-SynapsePhysicalDirectoryChainDescriptor -Chain $AcquisitionRootChain -ExpectedPath $root -Context "${Context}_acquisition_root")
    if ($MarkerLeaf -cnotmatch '^\.synapse-acquisition-[0-9a-f]{32}\.json$') {
        throw "SYNAPSE_ACQUISITION_MARKER_LEAF_INVALID context=$Context root=$root marker=$MarkerLeaf remediation=preserve the acquisition namespace; recovery reads only an exact lowercase nonce marker leaf"
    }
    $markerState = Get-SynapsePhysicalEnumeratedRelativeState -ParentPath $root -ParentChain $rootChain -Leaf $MarkerLeaf -MaximumLength 65536 -Context "${Context}_marker"
    if (-not [bool]$markerState.Exists) {
        throw "SYNAPSE_ACQUISITION_MARKER_MISSING context=$Context root=$root marker=$MarkerLeaf remediation=preserve any unbound allocation directory; recovery never infers ownership from a temp-looking name"
    }
    $markerRead = Read-SynapsePhysicalRelativeUtf8Text -ParentPath $root -ParentChain $rootChain -Leaf $MarkerLeaf -ExpectedFileId128 ([string]$markerState.FileId128) -MaxBytes 65536
    try {
        $payload = $markerRead.Content | ConvertFrom-Json -ErrorAction Stop
    } catch {
        throw "SYNAPSE_ACQUISITION_MARKER_JSON_INVALID context=$Context root=$root marker=$MarkerLeaf file_id_128=$($markerState.FileId128) error=$($_.Exception.Message) remediation=preserve the marker and its possible allocation; torn or foreign marker bytes grant no deletion authority"
    }
    Assert-SynapseAcquisitionExactPropertySet -Value $payload -Expected @(
        'schema','nonce','kind','creator_pid','creator_creation_time_filetime_utc','created_at_utc',
        'acquisition_root','acquisition_root_file_id_128','allocation_leaf','allocation_root',
        'allocation_root_file_id_128','marker_leaf','marker_file_id_128','max_entries','max_depth',
        'max_total_bytes','allocation_capability_sha256'
    ) -Context "${Context}_payload"

    $nonce = [string]$payload.nonce
    $expectedAllocationLeaf = ".synapse-acquisition-$nonce"
    $expectedMarkerLeaf = "$expectedAllocationLeaf.json"
    $expectedAllocationRoot = Get-SynapseNormalizedDirectoryPath -Path (Join-Path $root $expectedAllocationLeaf)
    $createdAt = [DateTime]::MinValue
    $createdAtOk = [DateTime]::TryParse(
        [string]$payload.created_at_utc,
        [Globalization.CultureInfo]::InvariantCulture,
        [Globalization.DateTimeStyles]::RoundtripKind,
        [ref]$createdAt)
    if ([string]$payload.schema -cne 'synapse_setup_acquisition_allocation/v1' -or
        $nonce -cnotmatch '^[0-9a-f]{32}$' -or
        [string]$payload.kind -cnotmatch '^[a-z][a-z0-9_]{0,63}$' -or
        [int64]$payload.creator_pid -le 0 -or [int64]$payload.creator_pid -gt [int]::MaxValue -or
        [int64]$payload.creator_creation_time_filetime_utc -le 0 -or
        -not $createdAtOk -or $createdAt.ToUniversalTime().ToString('o') -cne [string]$payload.created_at_utc -or
        [string]$payload.acquisition_root -ine $root -or
        [string]$payload.acquisition_root_file_id_128 -cnotmatch '^[0-9A-F]{16}:[0-9A-F]{32}$' -or
        [string]$payload.acquisition_root_file_id_128 -ine [string]$rootChain[-1].file_id_128 -or
        [string]$payload.allocation_leaf -cne $expectedAllocationLeaf -or
        [string]$payload.allocation_root -ine $expectedAllocationRoot -or
        [string]$payload.allocation_root_file_id_128 -cnotmatch '^[0-9A-F]{16}:[0-9A-F]{32}$' -or
        [string]$payload.marker_leaf -cne $expectedMarkerLeaf -or
        $MarkerLeaf -cne $expectedMarkerLeaf -or
        [string]$payload.marker_file_id_128 -cnotmatch '^[0-9A-F]{16}:[0-9A-F]{32}$' -or
        [string]$payload.marker_file_id_128 -ine [string]$markerState.FileId128 -or
        [int]$payload.max_entries -ne 8192 -or
        [int]$payload.max_depth -ne 32 -or
        [int64]$payload.max_total_bytes -ne 8589934592L -or
        [string]$payload.allocation_capability_sha256 -cnotmatch '^[0-9A-F]{64}$') {
        throw "SYNAPSE_ACQUISITION_MARKER_CONTRACT_INVALID context=$Context root=$root marker=$MarkerLeaf nonce=$nonce kind=$($payload.kind) creator_pid=$($payload.creator_pid) allocation_root=$($payload.allocation_root) remediation=preserve the marker and possible allocation; only the exact create-only v1 capability authorizes cleanup"
    }
    $capabilityCore = ConvertTo-SynapseCanonicalValue -Value $payload
    [void]$capabilityCore.Remove('allocation_capability_sha256')
    $capabilitySha = (Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $capabilityCore)).ToUpperInvariant()
    $canonicalText = (Get-SynapseCanonicalJson -Value (ConvertTo-SynapseCanonicalValue -Value $payload)) + "`n"
    if ($capabilitySha -ine [string]$payload.allocation_capability_sha256 -or
        $canonicalText -cne [string]$markerRead.Content -or
        [string]$markerRead.FileId128 -ine [string]$markerState.FileId128 -or
        [string]$markerRead.Sha256 -ine [string]$markerState.Sha256 -or
        [int64]$markerRead.Length -ne [int64]$markerState.Length) {
        throw "SYNAPSE_ACQUISITION_MARKER_AUTHORITY_INVALID context=$Context root=$root marker=$MarkerLeaf capability_expected=$($payload.allocation_capability_sha256) capability_actual=$capabilitySha remediation=preserve the exact marker and allocation; canonical bytes, physical identity, and capability hash must all agree"
    }
    $allocationState = Get-SynapsePhysicalRelativeState -ParentPath $root -ParentChain $rootChain -Leaf $expectedAllocationLeaf -Directory
    if ([bool]$allocationState.Exists -and [string]$allocationState.FileId128 -ine [string]$payload.allocation_root_file_id_128) {
        throw "SYNAPSE_ACQUISITION_MARKER_ROOT_REPLACED context=$Context root=$root marker=$MarkerLeaf allocation=$expectedAllocationRoot expected_file_id_128=$($payload.allocation_root_file_id_128) actual_file_id_128=$($allocationState.FileId128) remediation=preserve marker and replacement object; the immutable marker never authorizes a same-name directory"
    }
    return [pscustomobject][ordered]@{
        AcquisitionRoot = $root
        AcquisitionRootChain = $rootChain
        MarkerLeaf = $MarkerLeaf
        MarkerState = $markerState
        MarkerReadback = $markerRead
        Payload = $payload
        CapabilitySha256 = $capabilitySha
        AllocationPath = $expectedAllocationRoot
        AllocationState = $allocationState
    }
}

function New-SynapseAcquisitionAllocation {
    param(
        [Parameter(Mandatory=$true)][string]$Root,
        [Parameter(Mandatory=$true)][ValidatePattern('^[a-z][a-z0-9_]{0,63}$')][string]$Kind
    )

    $root = Get-SynapseNormalizedDirectoryPath -Path $Root
    $rootChain = @(Ensure-SynapsePhysicalDirectoryPath -Path $root -Context "acquisition_${Kind}_root")
    $creator = Get-SynapseAcquisitionCreatorProcessIdentity -CreatorPid $PID -Context "new_${Kind}"
    if (-not [bool]$creator.exists) {
        throw "SYNAPSE_ACQUISITION_CURRENT_PROCESS_IDENTITY_MISSING kind=$Kind pid=$PID remediation=setup cannot allocate acquisition state without its own exact kernel process identity"
    }
    $nonce = [Guid]::NewGuid().ToString('N')
    $allocationLeaf = ".synapse-acquisition-$nonce"
    $markerLeaf = "$allocationLeaf.json"
    Ensure-SynapseAtomicFileType
    try {
        $created = [SynapseSetup.AtomicFileV2]::CreatePhysicalDirectoryRelative(
            $root,
            (Get-SynapsePhysicalChainPaths -Chain $rootChain),
            (Get-SynapsePhysicalChainFileIds -Chain $rootChain),
            $allocationLeaf)
    } catch {
        throw "SYNAPSE_ACQUISITION_ALLOCATION_CREATE_FAILED kind=$Kind root=$root leaf=$allocationLeaf error=$($_.Exception.Message) remediation=preserve any colliding object; allocation names are create-only random nonces and are never adopted"
    }
    $allocationPath = Get-SynapseNormalizedDirectoryPath -Path ([string]$created.Path)
    $expectedAllocationPath = Get-SynapseNormalizedDirectoryPath -Path (Join-Path $root $allocationLeaf)
    if ($allocationPath -ine $expectedAllocationPath -or [string]$created.FileId128 -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$') {
        throw "SYNAPSE_ACQUISITION_ALLOCATION_CREATE_READBACK_INVALID kind=$Kind expected_path=$expectedAllocationPath actual_path=$allocationPath file_id_128=$($created.FileId128) remediation=preserve the unmarked allocation object; setup refuses pathname-only ownership"
    }
    $allocationChain = @($rootChain) + @([pscustomobject][ordered]@{
        path = $allocationPath
        file_id_128 = ([string]$created.FileId128).ToUpperInvariant()
    })
    $allocationChain = @(Assert-SynapsePhysicalDirectoryChainDescriptor -Chain $allocationChain -ExpectedPath $allocationPath -Context "new_${Kind}_allocation_chain")
    $markerStageLeaf = 'allocation-marker-stage.json'
    $markerHandle = $null
    try {
        $markerHandle = New-SynapsePhysicalAllocatedFile -ParentPath $allocationPath -ParentChain $allocationChain -Leaf $markerStageLeaf -Context "acquisition_${Kind}_marker_stage"
        $payload = [ordered]@{
            schema = 'synapse_setup_acquisition_allocation/v1'
            nonce = $nonce
            kind = $Kind
            creator_pid = [int]$PID
            creator_creation_time_filetime_utc = [int64]$creator.creation_time_filetime_utc
            created_at_utc = (Get-Date).ToUniversalTime().ToString('o')
            acquisition_root = $root
            acquisition_root_file_id_128 = ([string]$rootChain[-1].file_id_128).ToUpperInvariant()
            allocation_leaf = $allocationLeaf
            allocation_root = $allocationPath
            allocation_root_file_id_128 = ([string]$created.FileId128).ToUpperInvariant()
            marker_leaf = $markerLeaf
            marker_file_id_128 = ([string]$markerHandle.FileId128).ToUpperInvariant()
            max_entries = 8192
            max_depth = 32
            max_total_bytes = [int64]8589934592L
        }
        $payload.allocation_capability_sha256 = (Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $payload)).ToUpperInvariant()
        $markerText = (Get-SynapseCanonicalJson -Value $payload) + "`n"
        $markerSha = (Get-SynapseSha256Hex -Text $markerText).ToUpperInvariant()
        $markerLength = [Text.UTF8Encoding]::new($false, $true).GetByteCount($markerText)
        [void]$markerHandle.FillUtf8($markerText, $markerSha, [int64]$markerLength)
        $published = $markerHandle.MoveNoReplace(
            $root,
            (Get-SynapsePhysicalChainPaths -Chain $rootChain),
            (Get-SynapsePhysicalChainFileIds -Chain $rootChain),
            $markerLeaf)
        if ([string]$published.Path -ine (Join-Path $root $markerLeaf) -or
            [string]$published.FileId128 -ine [string]$payload.marker_file_id_128) {
            throw "SYNAPSE_ACQUISITION_MARKER_PUBLISH_READBACK_INVALID kind=$Kind expected_path=$(Join-Path $root $markerLeaf) actual_path=$($published.Path) expected_file_id_128=$($payload.marker_file_id_128) actual_file_id_128=$($published.FileId128) remediation=preserve the allocation and any published object; ownership begins only at an exact retained-handle no-replace publication"
        }
        $markerHandle.RequireExact("acquisition_${Kind}_marker_published")
    } finally {
        if ($null -ne $markerHandle) { $markerHandle.Dispose() }
    }
    $record = Read-SynapseAcquisitionAllocationMarker -AcquisitionRoot $root -AcquisitionRootChain $rootChain -MarkerLeaf $markerLeaf -Context "new_${Kind}_readback"
    $allocationState = $record.AllocationState
    if (-not [bool]$allocationState.Exists -or [string]$allocationState.FileId128 -ine [string]$record.Payload.allocation_root_file_id_128) {
        throw "SYNAPSE_ACQUISITION_ALLOCATION_ROOT_DRIFT kind=$Kind root=$root allocation=$allocationPath expected_file_id_128=$($record.Payload.allocation_root_file_id_128) actual_file_id_128=$($allocationState.FileId128) remediation=preserve marker and current object; the allocation root changed before use"
    }
    return $record
}

function Get-SynapseAcquisitionAllocationTreeSnapshot {
    param(
        [Parameter(Mandatory=$true)]$MarkerRecord,
        [Parameter(Mandatory=$true)][string]$Context
    )

    $payload = $MarkerRecord.Payload
    $root = [string]$MarkerRecord.AcquisitionRoot
    $rootChain = @($MarkerRecord.AcquisitionRootChain)
    $allocationLeaf = [string]$payload.allocation_leaf
    $allocationPath = Get-SynapseNormalizedDirectoryPath -Path ([string]$payload.allocation_root)
    $rootState = Get-SynapsePhysicalRelativeState -ParentPath $root -ParentChain $rootChain -Leaf $allocationLeaf -Directory
    if (-not [bool]$rootState.Exists) {
        $emptyCore = [ordered]@{
            allocation_capability_sha256 = ([string]$payload.allocation_capability_sha256).ToUpperInvariant()
            allocation_root_file_id_128 = ([string]$payload.allocation_root_file_id_128).ToUpperInvariant()
            root_exists = $false
            maximum_total_bytes = [int64]$payload.max_total_bytes
            entry_count = 0
            total_bytes = [int64]0
            entries = @()
        }
        return [pscustomobject][ordered]@{
            RootExists = $false
            RootState = $rootState
            RootChain = @()
            EntryCount = 0
            TotalBytes = [int64]0
            Entries = @()
            DeletionEntries = @()
            Stable = $emptyCore
            TreeSha256 = (Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $emptyCore)).ToUpperInvariant()
        }
    }
    if ([string]$rootState.FileId128 -ine [string]$payload.allocation_root_file_id_128) {
        throw "SYNAPSE_ACQUISITION_TREE_ROOT_IDENTITY_MISMATCH context=$Context path=$allocationPath expected_file_id_128=$($payload.allocation_root_file_id_128) actual_file_id_128=$($rootState.FileId128) remediation=preserve marker and replacement object; deletion authority binds only the originally allocated directory"
    }
    $allocationChain = @($rootChain) + @([pscustomobject][ordered]@{
        path = $allocationPath
        file_id_128 = ([string]$rootState.FileId128).ToUpperInvariant()
    })
    $allocationChain = @(Assert-SynapsePhysicalDirectoryChainDescriptor -Chain $allocationChain -ExpectedPath $allocationPath -Context "${Context}_allocation_chain")
    if ($allocationChain.Count -lt 1 -or [string]$allocationChain[-1].file_id_128 -ine [string]$payload.allocation_root_file_id_128) {
        throw "SYNAPSE_ACQUISITION_TREE_ROOT_CHAIN_MISMATCH context=$Context path=$allocationPath expected_file_id_128=$($payload.allocation_root_file_id_128) actual_file_id_128=$(if($allocationChain.Count){$allocationChain[-1].file_id_128}else{'<none>'}) remediation=preserve marker and current tree; the physical chain does not terminate at the allocated root"
    }
    $stableEntries = [System.Collections.Generic.List[object]]::new()
    $deleteEntries = [System.Collections.Generic.List[object]]::new()
    $stack = [System.Collections.Generic.Stack[object]]::new()
    $stack.Push([pscustomobject][ordered]@{
        Path = $allocationPath
        Chain = $allocationChain
        RelativePath = ''
        Depth = 0
        FileId128 = ([string]$payload.allocation_root_file_id_128).ToUpperInvariant()
    })
    $entryCount = 0
    $totalBytes = [decimal]0
    while ($stack.Count -gt 0) {
        $frame = $stack.Pop()
        $entries = @(Get-SynapsePhysicalEnumeratedDirectoryEntriesBounded -Path ([string]$frame.Path) -Chain @($frame.Chain) -MaximumEntries 4096 -Context "${Context}_depth_$($frame.Depth)")
        foreach ($entry in @($entries | Sort-Object Name)) {
            $entryCount++
            if ($entryCount -gt [int]$payload.max_entries) {
                throw "SYNAPSE_ACQUISITION_TREE_ENTRY_BOUND_EXCEEDED context=$Context allocation=$allocationPath count=$entryCount max=$($payload.max_entries) remediation=preserve and inspect the unexpectedly large marker-bound allocation"
            }
            $childDepth = [int]$frame.Depth + 1
            if ($childDepth -gt [int]$payload.max_depth) {
                throw "SYNAPSE_ACQUISITION_TREE_DEPTH_EXCEEDED context=$Context allocation=$allocationPath path=$($entry.Path) depth=$childDepth max=$($payload.max_depth) remediation=preserve and inspect the unexpectedly deep marker-bound allocation"
            }
            $leaf = [string]$entry.Name
            $relative = if ([string]::IsNullOrEmpty([string]$frame.RelativePath)) { $leaf } else { "$($frame.RelativePath)/$leaf" }
            $isDirectory = [bool]$entry.IsDirectory
            $remainingBytes = [int64]$payload.max_total_bytes - [int64]$totalBytes
            if (-not $isDirectory -and ([int64]$entry.Length -lt 0 -or [int64]$entry.Length -gt $remainingBytes)) {
                throw "SYNAPSE_ACQUISITION_TREE_BYTE_BOUND_EXCEEDED context=$Context allocation=$allocationPath relative=$relative enumerated_length=$($entry.Length) accumulated_bytes=$([int64]$totalBytes) remaining_bytes=$remainingBytes max=$($payload.max_total_bytes) remediation=preserve and inspect the unexpectedly large marker-bound allocation before hashing or deletion"
            }
            $state = if ($isDirectory) {
                Get-SynapsePhysicalEnumeratedRelativeState -ParentPath ([string]$frame.Path) -ParentChain @($frame.Chain) -Leaf $leaf -Directory -Context "${Context}_entry"
            } else {
                Get-SynapsePhysicalEnumeratedRelativeState -ParentPath ([string]$frame.Path) -ParentChain @($frame.Chain) -Leaf $leaf -MaximumLength $remainingBytes -Context "${Context}_entry"
            }
            if (-not [bool]$state.Exists -or [string]$state.FileId128 -ine [string]$entry.FileId128) {
                throw "SYNAPSE_ACQUISITION_TREE_ENTRY_DRIFT context=$Context allocation=$allocationPath relative=$relative expected_file_id_128=$($entry.FileId128) actual_exists=$($state.Exists) actual_file_id_128=$($state.FileId128) remediation=preserve the marker-bound tree; enumeration and same-handle identity readback disagree"
            }
            $kind = if ($isDirectory) { 'directory' } else { 'file' }
            $sha = if ($isDirectory) { '' } else { ([string]$state.Sha256).ToUpperInvariant() }
            $length = if ($isDirectory) { [int64]-1 } else { [int64]$state.Length }
            if (-not $isDirectory) {
                if ($length -ne [int64]$entry.Length) {
                    throw "SYNAPSE_ACQUISITION_TREE_ENTRY_LENGTH_DRIFT context=$Context allocation=$allocationPath relative=$relative enumerated_length=$($entry.Length) hashed_length=$length remediation=preserve the marker-bound tree; the exact file length changed between physical enumeration and exclusive bounded hashing"
                }
                $totalBytes += [decimal]$length
                if ($totalBytes -gt [decimal]([int64]$payload.max_total_bytes)) {
                    throw "SYNAPSE_ACQUISITION_TREE_BYTE_BOUND_EXCEEDED context=$Context allocation=$allocationPath accumulated_bytes=$totalBytes max=$($payload.max_total_bytes) remediation=preserve the tree; total byte count exceeds the immutable cleanup capability"
                }
            }
            $stable = [ordered]@{
                relative_path = $relative.Replace('\','/')
                parent_relative_path = ([string]$frame.RelativePath).Replace('\','/')
                parent_file_id_128 = ([string]$frame.FileId128).ToUpperInvariant()
                depth = $childDepth
                kind = $kind
                file_id_128 = ([string]$state.FileId128).ToUpperInvariant()
                sha256 = $sha
                length = $length
            }
            $stableEntries.Add([pscustomobject]$stable)
            $deleteEntries.Add([pscustomobject][ordered]@{
                Stable = [pscustomobject]$stable
                ParentPath = [string]$frame.Path
                ParentChain = @($frame.Chain)
                Leaf = $leaf
            })
            if ($isDirectory) {
                $childPath = Get-SynapseNormalizedDirectoryPath -Path ([string]$state.Path)
                $childChain = @($frame.Chain) + @([pscustomobject][ordered]@{
                    path = $childPath
                    file_id_128 = ([string]$state.FileId128).ToUpperInvariant()
                })
                $childChain = @(Assert-SynapsePhysicalDirectoryChainDescriptor -Chain $childChain -ExpectedPath $childPath -Context "${Context}_directory_chain")
                if ($childChain.Count -lt 1 -or [string]$childChain[-1].file_id_128 -ine [string]$state.FileId128) {
                    throw "SYNAPSE_ACQUISITION_TREE_DIRECTORY_CHAIN_DRIFT context=$Context allocation=$allocationPath relative=$relative expected_file_id_128=$($state.FileId128) actual_file_id_128=$(if($childChain.Count){$childChain[-1].file_id_128}else{'<none>'})"
                }
                $stack.Push([pscustomobject][ordered]@{
                    Path = $childPath
                    Chain = $childChain
                    RelativePath = $relative
                    Depth = $childDepth
                    FileId128 = ([string]$state.FileId128).ToUpperInvariant()
                })
            }
        }
    }
    $orderedStable = @($stableEntries | Sort-Object relative_path)
    $stableCore = [ordered]@{
        allocation_capability_sha256 = ([string]$payload.allocation_capability_sha256).ToUpperInvariant()
        allocation_root_file_id_128 = ([string]$payload.allocation_root_file_id_128).ToUpperInvariant()
        root_exists = $true
        maximum_total_bytes = [int64]$payload.max_total_bytes
        entry_count = $entryCount
        total_bytes = [int64]$totalBytes
        entries = $orderedStable
    }
    return [pscustomobject][ordered]@{
        RootExists = $true
        RootState = $rootState
        RootChain = $allocationChain
        EntryCount = $entryCount
        TotalBytes = [int64]$totalBytes
        Entries = $orderedStable
        DeletionEntries = @($deleteEntries)
        Stable = $stableCore
        TreeSha256 = (Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $stableCore)).ToUpperInvariant()
    }
}

function Remove-SynapseAcquisitionAllocation {
    param(
        [Parameter(Mandatory=$true)]$Allocation,
        [Parameter(Mandatory=$true)][string]$Reason
    )

    $fresh = Read-SynapseAcquisitionAllocationMarker -AcquisitionRoot ([string]$Allocation.AcquisitionRoot) -AcquisitionRootChain @($Allocation.AcquisitionRootChain) -MarkerLeaf ([string]$Allocation.MarkerLeaf) -Context "remove_${Reason}"
    if ([string]$fresh.CapabilitySha256 -ine [string]$Allocation.CapabilitySha256 -or
        [string]$fresh.MarkerState.FileId128 -ine [string]$Allocation.MarkerState.FileId128) {
        throw "SYNAPSE_ACQUISITION_REMOVE_AUTHORITY_DRIFT reason=$Reason marker=$($Allocation.MarkerLeaf) expected_capability=$($Allocation.CapabilitySha256) actual_capability=$($fresh.CapabilitySha256) remediation=preserve marker and tree; cleanup authority changed before deletion"
    }
    $markerLease = Open-SynapsePhysicalFileReadLease -ParentPath $fresh.AcquisitionRoot -ParentChain $fresh.AcquisitionRootChain -Leaf $fresh.MarkerLeaf -ExpectedFileId128 ([string]$fresh.MarkerState.FileId128) -ExpectedSha256 ([string]$fresh.MarkerState.Sha256) -ExpectedLength ([int64]$fresh.MarkerState.Length) -Context "acquisition_${Reason}_marker"
    $snapshot = $null
    try {
        $markerLease.RequireExact("acquisition_${Reason}_before_snapshot")
        $snapshot = Get-SynapseAcquisitionAllocationTreeSnapshot -MarkerRecord $fresh -Context "remove_${Reason}_before"
        $snapshotCheck = Get-SynapseAcquisitionAllocationTreeSnapshot -MarkerRecord $fresh -Context "remove_${Reason}_recheck"
        if ([string]$snapshot.TreeSha256 -ine [string]$snapshotCheck.TreeSha256 -or
            (Get-SynapseCanonicalJson -Value $snapshot.Stable) -cne (Get-SynapseCanonicalJson -Value $snapshotCheck.Stable)) {
            throw "SYNAPSE_ACQUISITION_TREE_CHANGED_BEFORE_DELETE reason=$Reason allocation=$($fresh.AllocationPath) before_sha256=$($snapshot.TreeSha256) after_sha256=$($snapshotCheck.TreeSha256) remediation=preserve marker and current tree; cleanup requires one complete bounded physical snapshot at the destructive boundary"
        }
        if ([bool]$snapshot.RootExists) {
            $files = @($snapshot.DeletionEntries | Where-Object { [string]$_.Stable.kind -ceq 'file' } | Sort-Object { [int]$_.Stable.depth } -Descending)
            foreach ($entry in $files) {
                $markerLease.RequireExact("acquisition_${Reason}_before_file_$($entry.Stable.relative_path)")
                $state = Get-SynapsePhysicalEnumeratedRelativeState -ParentPath $entry.ParentPath -ParentChain @($entry.ParentChain) -Leaf $entry.Leaf -MaximumLength ([int64]$entry.Stable.length) -Context "acquisition_${Reason}_file_before"
                if (-not (Test-SynapsePhysicalStateExact -State $state -ExpectedExists $true -ExpectedFileId128 ([string]$entry.Stable.file_id_128) -ExpectedSha256 ([string]$entry.Stable.sha256) -ExpectedLength ([int64]$entry.Stable.length))) {
                    throw "SYNAPSE_ACQUISITION_FILE_BOUNDARY_DRIFT reason=$Reason relative=$($entry.Stable.relative_path) remediation=preserve marker and remaining tree; the exact file changed before retained-handle deletion"
                }
                Remove-SynapsePhysicalEnumeratedRelativeEntryExact -ParentPath $entry.ParentPath -ParentChain @($entry.ParentChain) -Leaf $entry.Leaf -ExpectedFileId128 ([string]$entry.Stable.file_id_128) -ExpectedSha256 ([string]$entry.Stable.sha256) -ExpectedLength ([int64]$entry.Stable.length) -Context "acquisition_${Reason}_file"
                $after = Get-SynapsePhysicalEnumeratedRelativeState -ParentPath $entry.ParentPath -ParentChain @($entry.ParentChain) -Leaf $entry.Leaf -MaximumLength ([int64]$entry.Stable.length) -Context "acquisition_${Reason}_file_after"
                if ([bool]$after.Exists) {
                    throw "SYNAPSE_ACQUISITION_FILE_DELETE_READBACK_FAILED reason=$Reason relative=$($entry.Stable.relative_path) file_id_128=$($entry.Stable.file_id_128)"
                }
            }
            $directories = @($snapshot.DeletionEntries | Where-Object { [string]$_.Stable.kind -ceq 'directory' } | Sort-Object { [int]$_.Stable.depth } -Descending)
            foreach ($entry in $directories) {
                $markerLease.RequireExact("acquisition_${Reason}_before_directory_$($entry.Stable.relative_path)")
                $state = Get-SynapsePhysicalEnumeratedRelativeState -ParentPath $entry.ParentPath -ParentChain @($entry.ParentChain) -Leaf $entry.Leaf -Directory -Context "acquisition_${Reason}_directory_before"
                if (-not (Test-SynapsePhysicalStateExact -State $state -ExpectedExists $true -ExpectedFileId128 ([string]$entry.Stable.file_id_128))) {
                    throw "SYNAPSE_ACQUISITION_DIRECTORY_BOUNDARY_DRIFT reason=$Reason relative=$($entry.Stable.relative_path) remediation=preserve marker and remaining tree; the exact directory changed before retained-handle deletion"
                }
                Remove-SynapsePhysicalEnumeratedRelativeEntryExact -ParentPath $entry.ParentPath -ParentChain @($entry.ParentChain) -Leaf $entry.Leaf -ExpectedFileId128 ([string]$entry.Stable.file_id_128) -Directory -Context "acquisition_${Reason}_directory"
                $after = Get-SynapsePhysicalEnumeratedRelativeState -ParentPath $entry.ParentPath -ParentChain @($entry.ParentChain) -Leaf $entry.Leaf -Directory -Context "acquisition_${Reason}_directory_after"
                if ([bool]$after.Exists) {
                    throw "SYNAPSE_ACQUISITION_DIRECTORY_DELETE_READBACK_FAILED reason=$Reason relative=$($entry.Stable.relative_path) file_id_128=$($entry.Stable.file_id_128)"
                }
            }
            $markerLease.RequireExact("acquisition_${Reason}_before_root")
            $rootState = Get-SynapsePhysicalRelativeState -ParentPath $fresh.AcquisitionRoot -ParentChain $fresh.AcquisitionRootChain -Leaf ([string]$fresh.Payload.allocation_leaf) -Directory
            if (-not (Test-SynapsePhysicalStateExact -State $rootState -ExpectedExists $true -ExpectedFileId128 ([string]$fresh.Payload.allocation_root_file_id_128))) {
                throw "SYNAPSE_ACQUISITION_ROOT_BOUNDARY_DRIFT reason=$Reason allocation=$($fresh.AllocationPath) remediation=preserve marker and current object; root identity changed before exact empty-directory deletion"
            }
            Remove-SynapsePhysicalRelativeEntryExact -ParentPath $fresh.AcquisitionRoot -ParentChain $fresh.AcquisitionRootChain -Leaf ([string]$fresh.Payload.allocation_leaf) -ExpectedFileId128 ([string]$fresh.Payload.allocation_root_file_id_128) -Directory -Context "acquisition_${Reason}_root"
            $rootAfter = Get-SynapsePhysicalRelativeState -ParentPath $fresh.AcquisitionRoot -ParentChain $fresh.AcquisitionRootChain -Leaf ([string]$fresh.Payload.allocation_leaf) -Directory
            if ([bool]$rootAfter.Exists) {
                throw "SYNAPSE_ACQUISITION_ROOT_DELETE_READBACK_FAILED reason=$Reason allocation=$($fresh.AllocationPath) file_id_128=$($fresh.Payload.allocation_root_file_id_128)"
            }
        }
        $rootTerminal = Get-SynapsePhysicalRelativeState -ParentPath $fresh.AcquisitionRoot -ParentChain $fresh.AcquisitionRootChain -Leaf ([string]$fresh.Payload.allocation_leaf) -Directory
        if ([bool]$rootTerminal.Exists) {
            throw "SYNAPSE_ACQUISITION_ROOT_REAPPEARED_BEFORE_MARKER_RETIRE reason=$Reason allocation=$($fresh.AllocationPath) file_id_128=$($rootTerminal.FileId128) remediation=preserve the immutable marker; the allocation namespace is not stably absent"
        }
        $markerLease.RequireExact("acquisition_${Reason}_after_root_absence")
    } finally {
        if ($null -ne $markerLease) { $markerLease.Dispose() }
    }

    $markerState = Get-SynapsePhysicalEnumeratedRelativeState -ParentPath $fresh.AcquisitionRoot -ParentChain $fresh.AcquisitionRootChain -Leaf $fresh.MarkerLeaf -MaximumLength 65536 -Context "acquisition_${Reason}_marker_delete_before"
    if (-not (Test-SynapsePhysicalStateExact -State $markerState -ExpectedExists $true -ExpectedFileId128 ([string]$fresh.MarkerState.FileId128) -ExpectedSha256 ([string]$fresh.MarkerState.Sha256) -ExpectedLength ([int64]$fresh.MarkerState.Length))) {
        throw "SYNAPSE_ACQUISITION_MARKER_DELETE_BOUNDARY_DRIFT reason=$Reason marker=$($fresh.MarkerLeaf) remediation=the allocation root is absent, but setup refuses to retire a changed cleanup capability"
    }
    Remove-SynapsePhysicalRelativeEntryExact -ParentPath $fresh.AcquisitionRoot -ParentChain $fresh.AcquisitionRootChain -Leaf $fresh.MarkerLeaf -ExpectedFileId128 ([string]$fresh.MarkerState.FileId128) -ExpectedSha256 ([string]$fresh.MarkerState.Sha256) -ExpectedLength ([int64]$fresh.MarkerState.Length) -Context "acquisition_${Reason}_marker_retire"
    $markerAfter = Get-SynapsePhysicalEnumeratedRelativeState -ParentPath $fresh.AcquisitionRoot -ParentChain $fresh.AcquisitionRootChain -Leaf $fresh.MarkerLeaf -MaximumLength 65536 -Context "acquisition_${Reason}_marker_delete_after"
    if ([bool]$markerAfter.Exists) {
        throw "SYNAPSE_ACQUISITION_MARKER_DELETE_READBACK_FAILED reason=$Reason marker=$($fresh.MarkerLeaf) file_id_128=$($fresh.MarkerState.FileId128)"
    }
    $result = [pscustomobject][ordered]@{
        Exists = $true
        Path = $fresh.AllocationPath
        MarkerPath = Join-Path $fresh.AcquisitionRoot $fresh.MarkerLeaf
        Kind = [string]$fresh.Payload.kind
        OwnerPid = [int]$fresh.Payload.creator_pid
        OwnerCreationTimeFileTimeUtc = [int64]$fresh.Payload.creator_creation_time_filetime_utc
        ItemCount = if ($null -eq $snapshot) { 0 } else { [int]$snapshot.EntryCount + $(if ([bool]$snapshot.RootExists) { 1 } else { 0 }) }
        Bytes = if ($null -eq $snapshot) { [int64]0 } else { [int64]$snapshot.TotalBytes }
        TreeSha256 = if ($null -eq $snapshot) { '' } else { [string]$snapshot.TreeSha256 }
        CapabilitySha256 = [string]$fresh.CapabilitySha256
    }
    Info "Acquisition allocation removed reason=$Reason path=$($result.Path) marker=$($result.MarkerPath) kind=$($result.Kind) owner_pid=$($result.OwnerPid) owner_creation_time_filetime_utc=$($result.OwnerCreationTimeFileTimeUtc) item_count=$($result.ItemCount) bytes=$($result.Bytes) tree_sha256=$($result.TreeSha256) readback_exists=false"
    return $result
}

function Remove-SynapseStaleAcquisitionArtifacts {
    param([Parameter(Mandatory=$true)][string[]]$Roots)

    $observedAt = (Get-Date).ToUniversalTime().ToString('o')
    $candidates = [System.Collections.Generic.List[object]]::new()
    $rootReadbacks = [System.Collections.Generic.List[object]]::new()
    $unbound = [System.Collections.Generic.List[object]]::new()
    foreach ($requestedRoot in @($Roots | Sort-Object -Unique)) {
        $root = Get-SynapseNormalizedDirectoryPath -Path $requestedRoot
        $rootItem = $null
        try {
            $rootItem = Get-Item -LiteralPath $root -Force -ErrorAction Stop
        } catch [System.Management.Automation.ItemNotFoundException] {
            $rootReadbacks.Add([pscustomobject][ordered]@{ root = $root; exists = $false; enumerated_count = 0; marker_count = 0; unbound_count = 0 })
            continue
        } catch {
            throw "SYNAPSE_ACQUISITION_ROOT_STATE_UNREADABLE root=$root error=$($_.Exception.Message) remediation=preserve the acquisition namespace; setup distinguishes a truly absent root from an inaccessible, reparsed, or colliding object before recovery"
        }
        if (-not [bool]$rootItem.PSIsContainer) {
            throw "SYNAPSE_ACQUISITION_ROOT_NOT_DIRECTORY root=$root item_type=$($rootItem.GetType().FullName) remediation=do not delete this path; restore the setup-owned acquisition root as a physical directory"
        }
        $rootChain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $root)
        $entries = @(Get-SynapsePhysicalEnumeratedDirectoryEntriesBounded -Path $root -Chain $rootChain -MaximumEntries 4096 -Context 'acquisition_stale_root')
        $markerLeaves = New-SynapseCaseInsensitiveMap
        $allocationLeaves = New-SynapseCaseInsensitiveMap
        foreach ($entry in $entries) {
            $name = [string]$entry.Name
            if ($name -cmatch '^\.synapse-acquisition-([0-9a-f]{32})\.json$') {
                if ([bool]$entry.IsDirectory -or $markerLeaves.ContainsKey($Matches[1])) {
                    throw "SYNAPSE_ACQUISITION_MARKER_NAMESPACE_INVALID root=$root leaf=$name directory=$($entry.IsDirectory) remediation=preserve the private acquisition namespace; marker leaves must be unique regular files"
                }
                $markerLeaves[$Matches[1]] = $name
            } elseif ($name -cmatch '^\.synapse-acquisition-([0-9a-f]{32})$') {
                if (-not [bool]$entry.IsDirectory -or $allocationLeaves.ContainsKey($Matches[1])) {
                    throw "SYNAPSE_ACQUISITION_ALLOCATION_NAMESPACE_INVALID root=$root leaf=$name directory=$($entry.IsDirectory) remediation=preserve the private acquisition namespace; allocation leaves must be unique directories"
                }
                $allocationLeaves[$Matches[1]] = $name
            } elseif ($name.StartsWith('.synapse-acquisition-', [System.StringComparison]::OrdinalIgnoreCase)) {
                throw "SYNAPSE_ACQUISITION_RESERVED_NAMESPACE_INVALID root=$root leaf=$name remediation=preserve the malformed reserved entry; recovery never broadens from a partial nonce or suffix"
            }
        }
        foreach ($nonce in @($allocationLeaves.Keys | Sort-Object)) {
            if (-not $markerLeaves.ContainsKey($nonce)) {
                $unbound.Add([pscustomobject][ordered]@{
                    root = $root
                    allocation_leaf = [string]$allocationLeaves[$nonce]
                    nonce = [string]$nonce
                    disposition = 'preserved_unbound'
                })
            }
        }
        foreach ($nonce in @($markerLeaves.Keys | Sort-Object)) {
            $record = Read-SynapseAcquisitionAllocationMarker -AcquisitionRoot $root -AcquisitionRootChain $rootChain -MarkerLeaf ([string]$markerLeaves[$nonce]) -Context 'stale_scan'
            if ($allocationLeaves.ContainsKey($nonce) -and [string]$allocationLeaves[$nonce] -cne [string]$record.Payload.allocation_leaf) {
                throw "SYNAPSE_ACQUISITION_MARKER_ALLOCATION_LEAF_DRIFT root=$root nonce=$nonce marker_leaf=$($record.MarkerLeaf) allocation_leaf=$($allocationLeaves[$nonce])"
            }
            $candidates.Add($record)
        }
        $rootReadbacks.Add([pscustomobject][ordered]@{
            root = $root
            exists = $true
            root_file_id_128 = ([string]$rootChain[-1].file_id_128).ToUpperInvariant()
            enumerated_count = $entries.Count
            marker_count = $markerLeaves.Count
            unbound_count = @($allocationLeaves.Keys | Where-Object { -not $markerLeaves.ContainsKey($_) }).Count
        })
    }

    $reaped = [System.Collections.Generic.List[object]]::new()
    $retained = [System.Collections.Generic.List[object]]::new()
    foreach ($candidate in @($candidates | Sort-Object { $_.AllocationPath })) {
        $owner = Get-SynapseAcquisitionCreatorProcessIdentity -CreatorPid ([int]$candidate.Payload.creator_pid) -Context 'stale_sweep'
        $exactOwnerLive = [bool]$owner.exists -and
            [int64]$owner.creation_time_filetime_utc -eq [int64]$candidate.Payload.creator_creation_time_filetime_utc
        if ($exactOwnerLive) {
            $candidate.MarkerState = Get-SynapsePhysicalEnumeratedRelativeState -ParentPath $candidate.AcquisitionRoot -ParentChain $candidate.AcquisitionRootChain -Leaf $candidate.MarkerLeaf -MaximumLength 65536 -Context 'acquisition_live_owner_marker'
            if (-not (Test-SynapsePhysicalStateExact -State $candidate.MarkerState -ExpectedExists $true -ExpectedFileId128 ([string]$candidate.Payload.marker_file_id_128) -ExpectedSha256 ([string]$candidate.MarkerReadback.Sha256) -ExpectedLength ([int64]$candidate.MarkerReadback.Length))) {
                throw "SYNAPSE_ACQUISITION_LIVE_OWNER_MARKER_CHANGED path=$($candidate.AllocationPath) owner_pid=$($candidate.Payload.creator_pid) owner_creation_time_filetime_utc=$($candidate.Payload.creator_creation_time_filetime_utc) remediation=preserve the live creator's allocation; its immutable marker changed during classification"
            }
            $retained.Add([pscustomobject][ordered]@{
                root = [string]$candidate.AcquisitionRoot
                path = [string]$candidate.AllocationPath
                marker_leaf = [string]$candidate.MarkerLeaf
                kind = [string]$candidate.Payload.kind
                nonce = [string]$candidate.Payload.nonce
                owner_pid = [int]$candidate.Payload.creator_pid
                owner_creation_time_filetime_utc = [int64]$candidate.Payload.creator_creation_time_filetime_utc
                owner_relation = if ([int]$candidate.Payload.creator_pid -eq $PID) { 'current_process_exact' } else { 'live_creator_exact' }
                capability_sha256 = [string]$candidate.CapabilitySha256
            })
            continue
        }
        $reason = if ([bool]$owner.exists) { 'stale_creator_identity_reused' } else { 'stale_creator_absent' }
        $removed = Remove-SynapseAcquisitionAllocation -Allocation $candidate -Reason $reason
        $reaped.Add([pscustomobject][ordered]@{
            root = [string]$candidate.AcquisitionRoot
            path = [string]$candidate.AllocationPath
            marker_leaf = [string]$candidate.MarkerLeaf
            kind = [string]$candidate.Payload.kind
            nonce = [string]$candidate.Payload.nonce
            owner_pid = [int]$candidate.Payload.creator_pid
            owner_creation_time_filetime_utc = [int64]$candidate.Payload.creator_creation_time_filetime_utc
            stale_reason = $reason
            item_count = [int]$removed.ItemCount
            bytes = [int64]$removed.Bytes
            tree_sha256 = [string]$removed.TreeSha256
            capability_sha256 = [string]$candidate.CapabilitySha256
        })
    }

    $reclaimedBytes = [decimal]0
    foreach ($record in $reaped) { $reclaimedBytes += [decimal][int64]$record.bytes }
    if ($reclaimedBytes -gt [decimal][int64]::MaxValue) {
        throw "SYNAPSE_ACQUISITION_RECLAIMED_BYTE_COUNT_OVERFLOW count=$($reaped.Count) remediation=preserve the cleanup ledger until exact byte totals fit its signed 64-bit schema"
    }
    $readback = [pscustomobject][ordered]@{
        schema = 'synapse_setup_acquisition_cleanup/v2'
        observed_at_utc = $observedAt
        completed_at_utc = (Get-Date).ToUniversalTime().ToString('o')
        roots = @($rootReadbacks)
        candidate_count = $candidates.Count
        reaped_count = $reaped.Count
        reclaimed_bytes = [int64]$reclaimedBytes
        retained_live_count = $retained.Count
        unbound_preserved_count = $unbound.Count
        reaped = @($reaped)
        retained_live = @($retained)
        unbound_preserved = @($unbound)
    }
    Info "Acquisition stale sweep candidate_count=$($readback.candidate_count) reaped_count=$($readback.reaped_count) reclaimed_bytes=$($readback.reclaimed_bytes) retained_live_count=$($readback.retained_live_count) unbound_preserved_count=$($readback.unbound_preserved_count)"
    return $readback
}

function Get-SynapseOrtRuntimeCompanions {
    param([Parameter(Mandatory=$true)][string]$ExecutablePath)

    $directory = Split-Path -Parent $ExecutablePath
    # The installed runtime deliberately carries only the CPU execution core.
    # A CUDA provider DLL beside the executable would make GPU acquisition
    # structurally possible even when configuration currently selects CPU.
    $required = @('onnxruntime.dll', 'onnxruntime_providers_shared.dll')
    $files = @()
    foreach ($name in $required) {
        $path = Join-Path $directory $name
        if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
            Die "SYNAPSE_ORT_RUNTIME_COMPANION_MISSING executable=$ExecutablePath companion=$path remediation=the CPU-only daemon is a runtime bundle; build or install the named ONNX Runtime CPU runtime DLL beside the executable"
        }
        $files += [pscustomobject]@{
            Name = $name
            Path = $path
            Sha256 = Get-SynapseFileSha256 -Path $path
        }
    }
    return @($files)
}

function Install-SynapsePinnedOrtCpuRuntime {
    param([Parameter(Mandatory=$true)][string]$Root)

    $version = '1.27.1'
    $packageSha256 = '9359E46EBA4482DED00E678C98F22B68F51BB411D7934F5516D64050EDFA3383'
    $expectedFiles = [ordered]@{
        'onnxruntime.dll' = '79DF49BCBEFB604C019785925DAEF859C0348280616364E28103D73D4152F6D7'
        'onnxruntime_providers_shared.dll' = 'B8ECC1B05E21D1226DDA18DD3CB70C7FFF16713FCDCEF050CACEA83B8CBF315C'
    }
    $versionRoot = Join-Path $Root $version
    $packagePath = Join-Path $versionRoot "Microsoft.ML.OnnxRuntime.$version.nupkg"
    $extractRoot = Join-Path $versionRoot 'package'
    $nativeDir = Join-Path $extractRoot 'runtimes\win-x64\native'
    New-Item -ItemType Directory -Force -Path $versionRoot | Out-Null
    if (-not (Test-Path -LiteralPath $packagePath -PathType Leaf)) {
        $downloadAllocation = New-SynapseAcquisitionAllocation -Root $Root -Kind 'ort_download'
        $downloadPath = Join-Path $downloadAllocation.AllocationPath 'download.bin'
        try {
            try {
                Invoke-WebRequest -Uri "https://www.nuget.org/api/v2/package/Microsoft.ML.OnnxRuntime/$version" -OutFile $downloadPath -ErrorAction Stop
            } catch {
                Die "SYNAPSE_ORT_RUNTIME_PACKAGE_DOWNLOAD_FAILED path=$downloadPath version=$version error=$($_.Exception.Message) remediation=verify network/TLS access to the authoritative Microsoft NuGet package endpoint and rerun setup"
            }
            $downloadHash = Get-SynapseFileSha256 -Path $downloadPath
            if ($downloadHash -ne $packageSha256) {
                Die "SYNAPSE_ORT_RUNTIME_PACKAGE_HASH_MISMATCH path=$downloadPath expected_sha256=$packageSha256 actual_sha256=$downloadHash remediation=do not install an unverified ONNX Runtime package; inspect the authoritative Microsoft NuGet release"
            }
            Move-Item -LiteralPath $downloadPath -Destination $packagePath -ErrorAction Stop
        } finally {
            [void](Remove-SynapseAcquisitionAllocation -Allocation $downloadAllocation -Reason 'current_ort_download')
        }
    }
    $packageReadback = Get-SynapseFileSha256 -Path $packagePath
    if ($packageReadback -ne $packageSha256) {
        Die "SYNAPSE_ORT_RUNTIME_PACKAGE_HASH_MISMATCH path=$packagePath expected_sha256=$packageSha256 actual_sha256=$packageReadback remediation=delete only this corrupt cached package and rerun setup to reacquire it from Microsoft NuGet"
    }
    if (-not (Test-Path -LiteralPath $nativeDir -PathType Container)) {
        $extractAllocation = New-SynapseAcquisitionAllocation -Root $Root -Kind 'ort_extract'
        $zipPath = Join-Path $extractAllocation.AllocationPath 'package.zip'
        $extractAttempt = Join-Path $extractAllocation.AllocationPath 'extract'
        try {
            try {
                Copy-Item -LiteralPath $packagePath -Destination $zipPath -Force -ErrorAction Stop
                New-Item -ItemType Directory -Force -Path $extractAttempt -ErrorAction Stop | Out-Null
                Expand-Archive -LiteralPath $zipPath -DestinationPath $extractAttempt -ErrorAction Stop
                Move-Item -LiteralPath $extractAttempt -Destination $extractRoot -ErrorAction Stop
            } catch {
                Die "SYNAPSE_ORT_RUNTIME_PACKAGE_EXTRACT_FAILED package=$packagePath zip=$zipPath extract_attempt=$extractAttempt destination=$extractRoot error=$($_.Exception.Message) remediation=verify free disk space and access to the exact runtime cache directory, then rerun setup"
            }
        } finally {
            [void](Remove-SynapseAcquisitionAllocation -Allocation $extractAllocation -Reason 'current_ort_extract')
        }
    }
    foreach ($entry in $expectedFiles.GetEnumerator()) {
        $path = Join-Path $nativeDir $entry.Key
        if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
            Die "SYNAPSE_ORT_RUNTIME_FILE_MISSING path=$path package=$packagePath remediation=the pinned Microsoft ONNX Runtime package did not contain its declared Windows x64 runtime bundle"
        }
        $actual = Get-SynapseFileSha256 -Path $path
        if ($actual -ne $entry.Value) {
            Die "SYNAPSE_ORT_RUNTIME_FILE_HASH_MISMATCH path=$path expected_sha256=$($entry.Value) actual_sha256=$actual remediation=the extracted runtime differs from the pinned Microsoft package; refuse the build and reacquire the exact package"
        }
    }
    Info "Pinned Microsoft ONNX Runtime CPU execution core verified version=$version package_sha256=$packageReadback native_dir=$nativeDir installed_cuda_provider=false"
    return [pscustomobject]@{ Version = $version; NativeDir = $nativeDir; PackagePath = $packagePath; PackageSha256 = $packageReadback }
}

function Get-SynapseOptionalModelPin {
    <#
        Reads the committed pin for an optional embedded model and proves it
        agrees with the constant compiled into the daemon (#1863).

        The pin used to live in two independent hardcoded copies -- one here and
        one in registry.rs. Two copies of a supply-chain constant drift, and a
        drifted pin means the installer packages bytes the daemon will refuse at
        load time. The pin file is now the single authored value and this
        function fails closed if the Rust constant does not match it.
    #>
    param(
        [Parameter(Mandatory=$true)][string]$SourceDir,
        [Parameter(Mandatory=$true)][string]$PinRelativePath,
        [Parameter(Mandatory=$true)][string]$RustConstantName,
        [Parameter(Mandatory=$true)][string]$RustLengthConstantName,
        [Parameter(Mandatory=$true)][string]$RustSourceRelativePath
    )

    $pinPath = Join-Path $SourceDir $PinRelativePath
    if (-not (Test-Path -LiteralPath $pinPath -PathType Leaf)) {
        Die "SYNAPSE_OPTIONAL_MODEL_PIN_MISSING path=$pinPath remediation=restore the committed model pin file; it is the authoritative record of which bytes this checkout accepts"
    }
    try {
        $pin = Get-Content -LiteralPath $pinPath -Raw -Encoding UTF8 | ConvertFrom-Json
    } catch {
        Die "SYNAPSE_OPTIONAL_MODEL_PIN_UNREADABLE path=$pinPath error=$($_.Exception.Message) remediation=the pin file is not valid JSON; repair it from version control"
    }
    if ([string]::IsNullOrWhiteSpace([string]$pin.sha256) -or ([string]$pin.sha256).Length -ne 64) {
        Die "SYNAPSE_OPTIONAL_MODEL_PIN_INVALID path=$pinPath sha256=$($pin.sha256) remediation=sha256 must be exactly 64 hex characters"
    }
    if ([int64]$pin.length -le 0) {
        Die "SYNAPSE_OPTIONAL_MODEL_PIN_INVALID path=$pinPath length=$($pin.length) remediation=length must be a positive byte count"
    }
    $pinSha = ([string]$pin.sha256).ToUpperInvariant()

    $rustPath = Join-Path $SourceDir $RustSourceRelativePath
    if (-not (Test-Path -LiteralPath $rustPath -PathType Leaf)) {
        Die "SYNAPSE_OPTIONAL_MODEL_PIN_SOURCE_MISSING path=$rustPath remediation=the daemon model registry source is required to verify the pin agrees with the compiled constant"
    }
    $rustText = Get-Content -LiteralPath $rustPath -Raw -Encoding UTF8
    $match = [regex]::Match($rustText, "(?s)$([regex]::Escape($RustConstantName))\s*:\s*&str\s*=\s*`"sha256:([0-9a-fA-F]{64})`"")
    if (-not $match.Success) {
        Die "SYNAPSE_OPTIONAL_MODEL_PIN_CONSTANT_NOT_FOUND constant=$RustConstantName path=$rustPath remediation=the daemon constant could not be located; the installer refuses to package a model whose runtime pin it cannot read"
    }
    $rustSha = $match.Groups[1].Value.ToUpperInvariant()
    if ($rustSha -ne $pinSha) {
        Die "SYNAPSE_OPTIONAL_MODEL_PIN_DRIFT pin_path=$pinPath pin_sha256=$pinSha rust_path=$rustPath rust_constant=$RustConstantName rust_sha256=$rustSha remediation=the committed pin and the compiled daemon constant disagree; run scripts/build-whisper-e2e-onnx.ps1 which rewrites both, or reconcile them by hand before installing"
    }
    $lengthMatch = [regex]::Match($rustText, "$([regex]::Escape($RustLengthConstantName))\s*:\s*u64\s*=\s*([0-9_]+)")
    if (-not $lengthMatch.Success) {
        Die "SYNAPSE_OPTIONAL_MODEL_PIN_LENGTH_CONSTANT_NOT_FOUND constant=$RustLengthConstantName path=$rustPath remediation=the daemon length constant could not be located; the installer refuses to certify runtime health metadata it cannot verify"
    }
    $rustLength = [int64]($lengthMatch.Groups[1].Value.Replace('_', ''))
    if ($rustLength -ne [int64]$pin.length) {
        Die "SYNAPSE_OPTIONAL_MODEL_PIN_LENGTH_DRIFT pin_path=$pinPath pin_length=$($pin.length) rust_path=$rustPath rust_constant=$RustLengthConstantName rust_length=$rustLength remediation=run scripts/build-whisper-e2e-onnx.ps1 to repin hash and length atomically"
    }
    Info "Optional model pin verified id=$($pin.id) sha256=$pinSha length=$($pin.length) pin=$pinPath rust_constant=$RustConstantName"
    return [pscustomobject]@{
        Id = [string]$pin.id
        FileName = [string]$pin.filename
        Sha256 = $pinSha
        Length = [int64]$pin.length
        Recipe = [string]$pin.recipe
        OverrideEnv = [string]$pin.acquisition.override_env
        PinPath = $pinPath
    }
}

function Get-SynapseEmbeddedModelPins {
    <#
        The single authored description of every embedded model slot: what it
        is, whether the install may complete without it, and the exact bytes
        that count as legitimate. Both the packaging path and the -SkipBuild
        validation path read this, so they can never disagree (#1863).
    #>
    param([Parameter(Mandatory=$true)][string]$SourceDir)

    $whisperPin = Get-SynapseOptionalModelPin -SourceDir $SourceDir `
        -PinRelativePath 'models\whisper-tiny-int8.pin.json' `
        -RustConstantName 'WHISPER_TINY_INT8_ONNX_SHA256' `
        -RustLengthConstantName 'WHISPER_TINY_INT8_ONNX_LENGTH' `
        -RustSourceRelativePath 'crates\synapse-models\src\registry.rs'
    $extensionsPin = Get-SynapseOptionalModelPin -SourceDir $SourceDir `
        -PinRelativePath 'models\onnxruntime-extensions-whisper.pin.json' `
        -RustConstantName 'ORT_EXTENSIONS_WHISPER_SHA256' `
        -RustLengthConstantName 'ORT_EXTENSIONS_WHISPER_LENGTH' `
        -RustSourceRelativePath 'crates\synapse-models\src\registry.rs'
    $extensionsPath = Join-Path $env:LOCALAPPDATA 'synapse\models\ort-extensions\onnxruntime_extensions.dll'
    # ABSENT and WRONG are not the same fault, and only one of them may stop an
    # install.
    #
    # These custom operators are a prerequisite of exactly one OPTIONAL slot -
    # the end-to-end Whisper graph, `Required = $false`,
    # `Capability = audio_speech_to_text`. `Install-SynapsePinnedDetectionModels`
    # states the rule directly: "a disabled optional capability must never fail
    # the whole install (#1863)". Failing closed here inverted that - it made an
    # optional STT capability a hard gate on the entire deploy, so a host that
    # had never run the heavy Olive/PyTorch Whisper recipe could not install
    # Synapse at all. Observed 2026-08-06: setup died at
    # SYNAPSE_ORT_EXTENSIONS_LIBRARY_MISSING before reaching the build phase,
    # on a machine where every required model was present.
    #
    # So: absent -> the Whisper slot is unavailable and says so, and the install
    # continues with a recorded capability gap. Present-but-wrong-bytes stays
    # fatal, because that is a supply-chain integrity fault, not a gap.
    $whisperPrerequisiteMissing = $null
    if (-not (Test-Path -LiteralPath $extensionsPath -PathType Leaf)) {
        $whisperPrerequisiteMissing = "pinned ONNX Runtime Extensions library absent at $extensionsPath (pin=$($extensionsPin.PinPath)); the end-to-end Whisper graph cannot load its custom operators without it. Produce it with scripts\build-whisper-e2e-onnx.ps1"
        Warn "SYNAPSE_ORT_EXTENSIONS_LIBRARY_ABSENT path=$extensionsPath pin=$($extensionsPin.PinPath) effect=the optional audio_speech_to_text capability will be packaged as unavailable and the install continues remediation=run scripts\build-whisper-e2e-onnx.ps1 to enable end-to-end Whisper"
    } else {
        $extensionsActualLength = [int64](Get-Item -LiteralPath $extensionsPath).Length
        $extensionsActualSha = Get-SynapseFileSha256 -Path $extensionsPath
        if ($extensionsActualLength -ne $extensionsPin.Length -or $extensionsActualSha -ne $extensionsPin.Sha256) {
            Die "SYNAPSE_ORT_EXTENSIONS_LIBRARY_IDENTITY_MISMATCH path=$extensionsPath expected_sha256=$($extensionsPin.Sha256) actual_sha256=$extensionsActualSha expected_length=$($extensionsPin.Length) actual_length=$extensionsActualLength remediation=remove the mismatched file and regenerate it with scripts\build-whisper-e2e-onnx.ps1"
        }
        Info "Pinned ONNX Runtime Extensions library verified path=$extensionsPath sha256=$extensionsActualSha length=$extensionsActualLength"
    }

    # Candidate sources for the optional artifact, in precedence order. The
    # operator override comes first so a freshly produced artifact can be
    # packaged without moving files into a magic location.
    $whisperSources = @()
    if (-not [string]::IsNullOrWhiteSpace($env:SYNAPSE_WHISPER_ONNX_SOURCE)) {
        $whisperSources += $env:SYNAPSE_WHISPER_ONNX_SOURCE
    }
    $whisperSources += (Join-Path $env:LOCALAPPDATA 'synapse\models\whisper-tiny-int8.onnx')
    $whisperSources += (Join-Path $SourceDir 'models\whisper-tiny-int8.onnx')

    $models = @(
        [pscustomobject]@{
            Name = 'gpu'
            Required = $true
            FileName = 'rtdetr_v2_s_coco.onnx'
            Url = 'https://huggingface.co/onnx-community/rtdetr_v2_r18vd-ONNX/resolve/main/onnx/model.onnx'
            Sha256 = '583A236AC21C95A7FD94F284FC21485E42355BFEF82C27011BA78FBC09EE87E2'
            Length = [int64]81057510
            SourcePaths = @()
        },
        [pscustomobject]@{
            Name = 'cpu'
            Required = $true
            FileName = 'rtdetr_v2_s_coco_int8_cpu.onnx'
            Url = 'https://huggingface.co/onnx-community/rtdetr_v2_r18vd-ONNX/resolve/main/onnx/model_int8.onnx'
            Sha256 = 'FED736D2593CF2AB099F665EEEB6D315D909783EEA830F80A807FC1AC1C1B2EC'
            Length = [int64]20991219
            SourcePaths = @()
        },
        [pscustomobject]@{
            Name = 'whisper'
            Required = $false
            Capability = 'audio_speech_to_text'
            FileName = $whisperPin.FileName
            Url = $null
            Sha256 = $whisperPin.Sha256
            Length = $whisperPin.Length
            SourcePaths = @($whisperSources)
            Recipe = $whisperPin.Recipe
            OverrideEnv = $whisperPin.OverrideEnv
            PinPath = $whisperPin.PinPath
            # Non-null when a prerequisite of this optional slot is absent, so
            # the acquisition pass records the REAL cause of the gap instead of
            # reporting "no verified source artifact found" and sending the
            # operator looking for a missing .onnx that was never the problem.
            PrerequisiteMissing = $whisperPrerequisiteMissing
        }
    )
    return @($models)
}

function Install-SynapsePinnedDetectionModels {
    <#
        Acquires every embedded runtime model.

        Required models must be obtained or the build fails. Optional models
        (currently only the end-to-end STT graph) are acquired when a verified
        source is available and are otherwise reported as an explicit capability
        gap -- a disabled optional capability must never fail the whole install
        (#1863).
    #>
    param(
        [Parameter(Mandatory=$true)][string]$Root,
        [Parameter(Mandatory=$true)][string]$SourceDir
    )

    $models = @(Get-SynapseEmbeddedModelPins -SourceDir $SourceDir)
    New-Item -ItemType Directory -Force -Path $Root | Out-Null
    foreach ($model in $models) {
        # An optional slot whose PREREQUISITE is missing is unavailable no
        # matter what bytes are on disk, so acquiring the artifact would prove
        # nothing. Record the real cause and move on. A required slot in this
        # state is still fatal: nothing optional is being protected there.
        $prerequisiteMissing = [string]$model.PrerequisiteMissing
        if (-not [string]::IsNullOrWhiteSpace($prerequisiteMissing)) {
            if ($model.Required) {
                Die "SYNAPSE_EMBEDDED_MODEL_PREREQUISITE_MISSING model=$($model.Name) detail=$prerequisiteMissing remediation=a REQUIRED model slot cannot be packaged while its prerequisite is absent"
            }
            $model | Add-Member -NotePropertyName Path -NotePropertyValue $null -Force
            $model | Add-Member -NotePropertyName Present -NotePropertyValue $false -Force
            $model | Add-Member -NotePropertyName AbsenceReason -NotePropertyValue $prerequisiteMissing -Force
            Warn ("SYNAPSE_OPTIONAL_MODEL_ABSENT model={0} capability={1} reason=prerequisite_missing detail={2} recipe={3} effect=the install continues and this capability reports itself unavailable" -f `
                $model.Name, $model.Capability, $prerequisiteMissing, $model.Recipe)
            continue
        }
        $path = Join-Path $Root $model.FileName
        $valid = (Test-Path -LiteralPath $path -PathType Leaf) -and
            ((Get-Item -LiteralPath $path).Length -eq $model.Length) -and
            ((Get-SynapseFileSha256 -Path $path) -eq $model.Sha256)
        if (-not $valid) {
            $modelAllocation = New-SynapseAcquisitionAllocation -Root $Root -Kind 'model_download'
            $download = Join-Path $modelAllocation.AllocationPath 'model.bin'
            try {
                $acquired = $false
                $attempted = @()
                try {
                    if ($model.Url) {
                        Invoke-WebRequest -Uri $model.Url -OutFile $download -ErrorAction Stop
                        $acquired = $true
                        $attempted += $model.Url
                    } else {
                        foreach ($candidate in @($model.SourcePaths)) {
                            $attempted += $candidate
                            if (Test-Path -LiteralPath $candidate -PathType Leaf) {
                                Copy-Item -LiteralPath $candidate -Destination $download -Force -ErrorAction Stop
                                $acquired = $true
                                break
                            }
                        }
                    }
                } catch {
                    Die "SYNAPSE_EMBEDDED_MODEL_ACQUISITION_FAILED model=$($model.Name) path=$download attempted_sources=$($attempted -join ';') error=$($_.Exception.Message) remediation=repair access to the exact pinned source or its authoritative URL and rerun setup"
                }
                if (-not $acquired) {
                    if ($model.Required) {
                        Die "SYNAPSE_EMBEDDED_MODEL_SOURCE_MISSING model=$($model.Name) attempted_sources=$($attempted -join ';') remediation=a required embedded model could not be acquired; restore the pinned source artifact or network access to its pinned URL"
                    }
                    # Optional and absent: record the capability gap and continue.
                    # The install is still correct; the dependent capability is not
                    # available and says so.
                    $model | Add-Member -NotePropertyName Path -NotePropertyValue $null -Force
                    $model | Add-Member -NotePropertyName Present -NotePropertyValue $false -Force
                    $model | Add-Member -NotePropertyName AbsenceReason -NotePropertyValue (
                        "no verified source artifact found; searched: $($attempted -join '; ')"
                    ) -Force
                    Warn ("SYNAPSE_OPTIONAL_MODEL_ABSENT model={0} capability={1} expected_sha256={2} expected_length={3} searched={4} recipe={5} override_env={6} pin={7} effect=the install continues and this capability reports itself unavailable" -f `
                        $model.Name, $model.Capability, $model.Sha256, $model.Length, ($attempted -join ';'), $model.Recipe, $model.OverrideEnv, $model.PinPath)
                    continue
                }
                $actualLength = (Get-Item -LiteralPath $download).Length
                $actualHash = Get-SynapseFileSha256 -Path $download
                if ($actualLength -ne $model.Length -or $actualHash -ne $model.Sha256) {
                    Die "SYNAPSE_EMBEDDED_MODEL_DOWNLOAD_INVALID model=$($model.Name) path=$download expected_length=$($model.Length) actual_length=$actualLength expected_sha256=$($model.Sha256) actual_sha256=$actualHash remediation=refuse unverified model bytes; inspect the pinned upstream artifact"
                }
                Move-Item -LiteralPath $download -Destination $path -Force -ErrorAction Stop
            } finally {
                [void](Remove-SynapseAcquisitionAllocation -Allocation $modelAllocation -Reason "current_model_$($model.Name)")
            }
        }
        $model | Add-Member -NotePropertyName Path -NotePropertyValue $path -Force
        $model | Add-Member -NotePropertyName Present -NotePropertyValue $true -Force
        Info "Pinned embedded runtime model verified model=$($model.Name) required=$($model.Required) path=$path length=$($model.Length) sha256=$($model.Sha256)"
    }
    return @($models)
}

# Slot order is positional and MUST match REGISTERED_MODELS in
# crates/synapse-models/src/registry.rs. The daemon reads the same table by
# index, so reordering here without reordering there would silently mis-map
# payloads; the daemon refuses a slot count that disagrees with its registry.
$script:SynapseEmbeddedModelSlotOrder = @('gpu', 'cpu', 'whisper')
$script:SynapseEmbeddedModelBundleMagicV1 = 'SYNMODEL_BUNDLE1'
$script:SynapseEmbeddedModelBundleMagicV2 = 'SYNMODEL_BUNDLE2'
$script:SynapseEmbeddedModelBundleFormatVersion = 2
# [int64 length][32-byte sha256] per slot.
$script:SynapseEmbeddedModelBundleSlotSize = 40
# [uint32 slot_count][uint32 format_version][16-byte magic].
$script:SynapseEmbeddedModelBundleFooterSize = 24

function Get-SynapseExecutableModelBundle {
    <#
        Decodes the self-describing model bundle appended to an executable.

        A slot whose length is 0 is a positive record of absence, which is what
        allows an optional model to be missing without making the bundle
        invalid. Returns $null when the executable carries no bundle at all
        (#1863).
    #>
    param([Parameter(Mandatory=$true)][string]$ExecutablePath)

    $magicV1 = [System.Text.Encoding]::ASCII.GetBytes($script:SynapseEmbeddedModelBundleMagicV1)
    $magicV2 = [System.Text.Encoding]::ASCII.GetBytes($script:SynapseEmbeddedModelBundleMagicV2)
    $slotCountExpected = @($script:SynapseEmbeddedModelSlotOrder).Count
    $tableSize = $slotCountExpected * $script:SynapseEmbeddedModelBundleSlotSize
    $trailerSize = $tableSize + $script:SynapseEmbeddedModelBundleFooterSize

    $stream = [System.IO.File]::Open($ExecutablePath, 'Open', 'Read', 'ReadWrite')
    try {
        if ($stream.Length -lt $script:SynapseEmbeddedModelBundleFooterSize) {
            return $null
        }
        $stream.Position = $stream.Length - 16
        $magic = New-Object byte[] 16
        if ($stream.Read($magic, 0, 16) -ne 16) {
            Die "SYNAPSE_EMBEDDED_MODEL_TRAILER_READ_FAILED path=$ExecutablePath remediation=inspect filesystem integrity; the executable trailer could not be read"
        }
        $isV1 = $true
        $isV2 = $true
        for ($index = 0; $index -lt 16; $index++) {
            if ($magic[$index] -ne $magicV1[$index]) { $isV1 = $false }
            if ($magic[$index] -ne $magicV2[$index]) { $isV2 = $false }
        }
        if ($isV1) {
            # A pre-#1863 binary. Report it precisely instead of letting it look
            # like an unpackaged executable, which would silently repackage from
            # an unknown base length and corrupt the image.
            Die "SYNAPSE_EMBEDDED_MODEL_BUNDLE_LEGACY_FORMAT path=$ExecutablePath format=$($script:SynapseEmbeddedModelBundleMagicV1) remediation=this executable was packaged by an installer whose bundle cannot express optional models; rebuild from source through this setup script rather than repackaging the existing binary"
        }
        if (-not $isV2) {
            return $null
        }
        if ($stream.Length -lt $trailerSize) {
            Die "SYNAPSE_EMBEDDED_MODEL_TRAILER_INVALID path=$ExecutablePath executable_length=$($stream.Length) required_trailer=$trailerSize remediation=the executable is smaller than its own bundle trailer; rebuild and repackage it"
        }
        $stream.Position = $stream.Length - $script:SynapseEmbeddedModelBundleFooterSize
        $footer = New-Object byte[] $script:SynapseEmbeddedModelBundleFooterSize
        if ($stream.Read($footer, 0, $script:SynapseEmbeddedModelBundleFooterSize) -ne $script:SynapseEmbeddedModelBundleFooterSize) {
            Die "SYNAPSE_EMBEDDED_MODEL_TRAILER_READ_FAILED path=$ExecutablePath remediation=inspect filesystem integrity; the executable bundle footer could not be read"
        }
        $slotCount = [BitConverter]::ToUInt32($footer, 0)
        $formatVersion = [BitConverter]::ToUInt32($footer, 4)
        if ($formatVersion -ne $script:SynapseEmbeddedModelBundleFormatVersion) {
            Die "SYNAPSE_EMBEDDED_MODEL_BUNDLE_FORMAT_UNSUPPORTED path=$ExecutablePath format_version=$formatVersion expected=$($script:SynapseEmbeddedModelBundleFormatVersion) remediation=the executable was packaged by a different installer version; rebuild from this checkout"
        }
        if ($slotCount -ne $slotCountExpected) {
            Die "SYNAPSE_EMBEDDED_MODEL_BUNDLE_SLOT_COUNT_MISMATCH path=$ExecutablePath slot_count=$slotCount expected=$slotCountExpected remediation=the executable and this installer disagree about the registered model set; rebuild from this checkout"
        }

        $stream.Position = $stream.Length - $trailerSize
        $table = New-Object byte[] $tableSize
        if ($stream.Read($table, 0, $tableSize) -ne $tableSize) {
            Die "SYNAPSE_EMBEDDED_MODEL_TRAILER_READ_FAILED path=$ExecutablePath remediation=inspect filesystem integrity; the executable slot table could not be read"
        }

        $slots = @()
        $payloadLength = [int64]0
        for ($index = 0; $index -lt $slotCount; $index++) {
            $base = $index * $script:SynapseEmbeddedModelBundleSlotSize
            $length = [BitConverter]::ToInt64($table, $base)
            if ($length -lt 0) {
                Die "SYNAPSE_EMBEDDED_MODEL_TRAILER_INVALID path=$ExecutablePath slot=$($script:SynapseEmbeddedModelSlotOrder[$index]) length=$length remediation=the executable advertises a negative model payload length; rebuild and repackage it"
            }
            $payloadLength += $length
            $digest = ''
            if ($length -gt 0) {
                $digestBytes = New-Object byte[] 32
                [Array]::Copy($table, $base + 8, $digestBytes, 0, 32)
                $digest = ($digestBytes | ForEach-Object { $_.ToString('X2') }) -join ''
            }
            $slots += [pscustomobject]@{
                Name = $script:SynapseEmbeddedModelSlotOrder[$index]
                Length = [int64]$length
                Sha256 = $digest
                Present = ($length -gt 0)
                Offset = [int64]0
            }
        }
        $baseLength = [int64]($stream.Length - $trailerSize - $payloadLength)
        if ($baseLength -lt 0) {
            Die "SYNAPSE_EMBEDDED_MODEL_TRAILER_INVALID path=$ExecutablePath executable_length=$($stream.Length) payload_length=$payloadLength trailer_length=$trailerSize remediation=the executable advertises impossible model payload lengths; rebuild and repackage it"
        }
        $offset = $baseLength
        foreach ($slot in $slots) {
            $slot.Offset = [int64]$offset
            $offset += $slot.Length
        }
        return [pscustomobject]@{
            BaseLength = $baseLength
            TotalLength = [int64]$stream.Length
            PayloadLength = $payloadLength
            Slots = @($slots)
        }
    } finally {
        $stream.Dispose()
    }
}

function Get-SynapseExecutableRangeSha256 {
    param(
        [Parameter(Mandatory=$true)][string]$ExecutablePath,
        [Parameter(Mandatory=$true)][int64]$Offset,
        [Parameter(Mandatory=$true)][int64]$Length
    )

    $stream = [System.IO.File]::Open($ExecutablePath, 'Open', 'Read', 'ReadWrite')
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try {
        $stream.Position = $Offset
        $remaining = $Length
        $buffer = New-Object byte[] (1024 * 1024)
        while ($remaining -gt 0) {
            $wanted = [int][Math]::Min($buffer.Length, $remaining)
            $read = $stream.Read($buffer, 0, $wanted)
            if ($read -le 0) {
                Die "SYNAPSE_EMBEDDED_MODEL_PAYLOAD_TRUNCATED path=$ExecutablePath offset=$Offset length=$Length remaining=$remaining remediation=rebuild and repackage the executable"
            }
            [void]$sha.TransformBlock($buffer, 0, $read, $null, 0)
            $remaining -= $read
        }
        [void]$sha.TransformFinalBlock([byte[]]::new(0), 0, 0)
        return ($sha.Hash | ForEach-Object { $_.ToString('X2') }) -join ''
    } finally {
        $sha.Dispose()
        $stream.Dispose()
    }
}

function Assert-SynapseExecutableModelBundle {
    <#
        Re-reads the packaged executable and proves every present slot hashes to
        what the slot table claims, that required models are present, and that
        absent slots are optional. Verification is against the bundle's own
        recorded digests plus the acquired models' verified digests -- no third
        hardcoded copy of the hashes (#1863).
    #>
    param(
        [Parameter(Mandatory=$true)][string]$ExecutablePath,
        [Parameter(Mandatory=$true)]$Models
    )

    $bundle = Get-SynapseExecutableModelBundle -ExecutablePath $ExecutablePath
    if (-not $bundle) {
        Die "SYNAPSE_EMBEDDED_MODEL_BUNDLE_MISSING path=$ExecutablePath remediation=build through synapse-setup.ps1 so the pinned models are packaged into the executable"
    }
    $summary = @()
    foreach ($slot in $bundle.Slots) {
        $model = @($Models | Where-Object { $_.Name -eq $slot.Name })[0]
        if (-not $model) {
            Die "SYNAPSE_EMBEDDED_MODEL_BUNDLE_SLOT_UNKNOWN path=$ExecutablePath slot=$($slot.Name) remediation=the packaged slot table names a model this installer does not know; rebuild from this checkout"
        }
        if (-not $slot.Present) {
            if ($model.Required) {
                Die "SYNAPSE_EMBEDDED_MODEL_BUNDLE_REQUIRED_SLOT_ABSENT path=$ExecutablePath slot=$($slot.Name) remediation=a required model was not packaged; the executable is unusable -- reacquire the model and repackage"
            }
            if ($model.Present) {
                Die "SYNAPSE_EMBEDDED_MODEL_BUNDLE_SLOT_LOST path=$ExecutablePath slot=$($slot.Name) expected_length=$($model.Length) remediation=the model was acquired but is absent from the packaged bundle; the packaging step is defective"
            }
            $summary += "$($slot.Name)=absent"
            continue
        }
        if (-not $model.Present) {
            Die "SYNAPSE_EMBEDDED_MODEL_BUNDLE_SLOT_UNEXPECTED path=$ExecutablePath slot=$($slot.Name) packaged_length=$($slot.Length) remediation=the bundle contains a payload for a model that was never acquired; the packaging step is defective"
        }
        if ($slot.Length -ne $model.Length) {
            Die "SYNAPSE_EMBEDDED_MODEL_BUNDLE_INVALID path=$ExecutablePath slot=$($slot.Name) packaged_length=$($slot.Length) expected_length=$($model.Length) remediation=the executable does not contain the exact pinned model; rebuild and repackage it"
        }
        $actual = Get-SynapseExecutableRangeSha256 -ExecutablePath $ExecutablePath -Offset $slot.Offset -Length $slot.Length
        if ($actual -ne $model.Sha256 -or $actual -ne $slot.Sha256) {
            Die "SYNAPSE_EMBEDDED_MODEL_BUNDLE_INVALID path=$ExecutablePath slot=$($slot.Name) offset=$($slot.Offset) length=$($slot.Length) payload_sha256=$actual slot_table_sha256=$($slot.Sha256) expected_sha256=$($model.Sha256) remediation=the executable does not contain the exact pinned model; rebuild and repackage it"
        }
        $summary += "$($slot.Name)=$actual"
    }
    Info "Executable model bundle verified path=$ExecutablePath base_length=$($bundle.BaseLength) total_length=$($bundle.TotalLength) slots=$($summary -join ' ')"
    return $bundle
}

function Add-SynapseExecutableModelBundle {
    <#
        Appends the payloads and the slot table. Absent optional models occupy a
        zero-length slot with a zero digest, which is how the daemon learns the
        capability is genuinely not packaged rather than guessing (#1863).
    #>
    param(
        [Parameter(Mandatory=$true)][string]$ExecutablePath,
        [Parameter(Mandatory=$true)]$Models
    )

    $ordered = @()
    foreach ($name in $script:SynapseEmbeddedModelSlotOrder) {
        $model = @($Models | Where-Object { $_.Name -eq $name })[0]
        if (-not $model) {
            Die "SYNAPSE_EMBEDDED_MODEL_SELECTION_FAILED slot=$name remediation=the pinned model acquisition did not return an entry for every registered slot"
        }
        if ($model.Required -and -not $model.Present) {
            Die "SYNAPSE_EMBEDDED_MODEL_SELECTION_FAILED slot=$name remediation=a required model was not acquired; refusing to package an unusable executable"
        }
        $ordered += $model
    }

    $existing = Get-SynapseExecutableModelBundle -ExecutablePath $ExecutablePath
    if ($existing) {
        $stream = [System.IO.File]::Open($ExecutablePath, 'Open', 'Write', 'None')
        try { $stream.SetLength($existing.BaseLength) } finally { $stream.Dispose() }
    }
    $output = [System.IO.File]::Open($ExecutablePath, 'Append', 'Write', 'None')
    try {
        foreach ($model in $ordered) {
            if (-not $model.Present) { continue }
            $payload = [System.IO.File]::OpenRead($model.Path)
            try { $payload.CopyTo($output) } finally { $payload.Dispose() }
        }
        foreach ($model in $ordered) {
            if ($model.Present) {
                $output.Write([BitConverter]::GetBytes([int64]$model.Length), 0, 8)
                $digestBytes = [byte[]]::new(32)
                for ($index = 0; $index -lt 32; $index++) {
                    $digestBytes[$index] = [Convert]::ToByte($model.Sha256.Substring($index * 2, 2), 16)
                }
                $output.Write($digestBytes, 0, 32)
            } else {
                $output.Write([BitConverter]::GetBytes([int64]0), 0, 8)
                $output.Write([byte[]]::new(32), 0, 32)
            }
        }
        $output.Write([BitConverter]::GetBytes([uint32]@($script:SynapseEmbeddedModelSlotOrder).Count), 0, 4)
        $output.Write([BitConverter]::GetBytes([uint32]$script:SynapseEmbeddedModelBundleFormatVersion), 0, 4)
        $magic = [System.Text.Encoding]::ASCII.GetBytes($script:SynapseEmbeddedModelBundleMagicV2)
        $output.Write($magic, 0, $magic.Length)
        $output.Flush($true)
    } finally {
        $output.Dispose()
    }
    return Assert-SynapseExecutableModelBundle -ExecutablePath $ExecutablePath -Models $ordered
}

function New-SynapseStagedDaemonBinary {
    param(
        [Parameter(Mandatory=$true)][string]$BuiltPath,
        [Parameter(Mandatory=$true)][string]$LogDir,
        [Parameter(Mandatory=$true)][string]$RuntimeDir,
        [Parameter(Mandatory=$true)]$EmbeddedModels
    )

    if (-not [string]::IsNullOrWhiteSpace([string]$script:SynapseCurrentDaemonStagingDirectory)) {
        Die "SYNAPSE_DAEMON_STAGING_ALREADY_ACTIVE path=$script:SynapseCurrentDaemonStagingDirectory remediation=clean the exact prior setup-owned staging directory before creating another candidate copy"
    }
    $stagingRoot = Join-Path $LogDir 'setup-staging'
    $stagingDir = New-SynapseSetupRunDirectory -Root $stagingRoot -Purpose 'daemon-binary'
    $script:SynapseCurrentDaemonStagingDirectory = Get-SynapseFullPathForScopeCheck -Path $stagingDir
    $builtHash = Get-SynapseFileSha256 -Path $BuiltPath
    $stagedPath = Join-Path $stagingDir "synapse-mcp-$builtHash.exe"
    Copy-Item -LiteralPath $BuiltPath -Destination $stagedPath -Force
    $stagedHash = Get-SynapseFileSha256 -Path $stagedPath
    if ($stagedHash -ne $builtHash) {
        Die "SYNAPSE_STAGED_BINARY_HASH_MISMATCH built=$BuiltPath staged=$stagedPath built_hash=$builtHash staged_hash=$stagedHash remediation=inspect disk/storage; refusing to install an unverified binary"
    }
    # Package models only into the setup-owned staging copy.  Mutating Cargo's
    # target artifact makes every subsequent setup rebuild the enormous
    # top-level release crate even when no Rust source changed.
    [void](Add-SynapseExecutableModelBundle -ExecutablePath $stagedPath -Models $EmbeddedModels)
    $stagedHash = Get-SynapseFileSha256 -Path $stagedPath
    $runtimeFiles = @()
    foreach ($companion in @(Get-SynapseOrtRuntimeCompanions -ExecutablePath (Join-Path $RuntimeDir 'synapse-mcp.exe'))) {
        $stagedCompanion = Join-Path $stagingDir $companion.Name
        Copy-Item -LiteralPath $companion.Path -Destination $stagedCompanion -Force
        $stagedCompanionHash = Get-SynapseFileSha256 -Path $stagedCompanion
        if ($stagedCompanionHash -ne $companion.Sha256) {
            Die "SYNAPSE_STAGED_RUNTIME_COMPANION_HASH_MISMATCH source=$($companion.Path) staged=$stagedCompanion expected_sha256=$($companion.Sha256) actual_sha256=$stagedCompanionHash remediation=inspect disk/storage; refusing to install an incoherent ONNX Runtime bundle"
        }
        $runtimeFiles += [pscustomobject]@{ Name = $companion.Name; Path = $stagedCompanion; Sha256 = $stagedCompanionHash }
    }
    Info "Staged daemon binary path=$stagedPath sha256=$stagedHash"
    return [pscustomobject]@{
        Path = $stagedPath
        Directory = $script:SynapseCurrentDaemonStagingDirectory
        Sha256 = $stagedHash
        SourcePath = $BuiltPath
        RuntimeFiles = @($runtimeFiles)
    }
}

function New-SynapseCandidateBind {
    $listener = [System.Net.Sockets.TcpListener]::new([System.Net.IPAddress]::Parse('127.0.0.1'), 0)
    try {
        $listener.Start()
        $port = [int]$listener.LocalEndpoint.Port
    } finally {
        $listener.Stop()
    }
    return "127.0.0.1:$port"
}

function Get-SynapseCandidateExitReadback {
    param([AllowNull()][System.Diagnostics.Process]$Process)

    if ($null -eq $Process) {
        return [pscustomobject]@{ HasExited = $null; ExitCodeSigned = $null; ExitCodeHex = $null }
    }
    try {
        $Process.Refresh()
        if (-not $Process.HasExited) {
            return [pscustomobject]@{ HasExited = $false; ExitCodeSigned = $null; ExitCodeHex = $null }
        }
        # Complete redirected-stream processing before reading retained exit metadata.
        $Process.WaitForExit()
        $signed = [int]$Process.ExitCode
        $unsigned = [BitConverter]::ToUInt32([BitConverter]::GetBytes($signed), 0)
        return [pscustomobject]@{
            HasExited = $true
            ExitCodeSigned = $signed
            ExitCodeHex = ('0x{0:X8}' -f $unsigned)
        }
    } catch {
        return [pscustomobject]@{
            HasExited = $null
            ExitCodeSigned = $null
            ExitCodeHex = $null
            Error = $_.Exception.Message
        }
    }
}

function Get-SynapseKernelProcessPresence {
    param(
        [Parameter(Mandatory=$true)][int]$ProcessId,
        [Parameter(Mandatory=$true)][string]$Purpose
    )

    if ($ProcessId -le 0) {
        return [pscustomobject]@{ Exists = $false; Process = $null }
    }
    try {
        $process = [System.Diagnostics.Process]::GetProcessById($ProcessId)
        return [pscustomobject]@{ Exists = $true; Process = $process }
    } catch [System.ArgumentException] {
        return [pscustomobject]@{ Exists = $false; Process = $null }
    } catch {
        throw "SYNAPSE_PROCESS_PRESENCE_SOT_UNREADABLE purpose=$Purpose pid=$ProcessId error=$($_.Exception.Message) remediation=preserve candidate state until the kernel process table can be read"
    }
}

function Get-SynapsePhysicalDirectoryTreeSnapshotNoReparse {
    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][ValidatePattern('^(?:[0-9A-Fa-f]{8}:[0-9A-Fa-f]{16}|[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32})$')][string]$ExpectedRootIdentity,
        [ValidateRange(1, 200000)][int]$MaxEntries = 200000,
        [ValidateRange(1, 128)][int]$MaxDepth = 64
    )

    $rootFull = [System.IO.Path]::GetFullPath($Path).TrimEnd('\')
    $rootPrefix = "$rootFull\"
    Ensure-SynapseAtomicFileType
    $rootIdentity = [SynapseSetup.AtomicFileV2]::GetPhysicalDirectoryIdentityExpected($rootFull,$ExpectedRootIdentity)
    if ($rootIdentity -ine $ExpectedRootIdentity) {
        throw "SYNAPSE_PHYSICAL_TREE_ROOT_IDENTITY_MISMATCH path=$rootFull expected_identity=$ExpectedRootIdentity actual_identity=$rootIdentity remediation=preserve the candidate evidence; the authorized directory was replaced before physical traversal"
    }
    $rootInfo = [System.IO.DirectoryInfo]::new($rootFull)
    $rootInfo.Refresh()
    if (-not $rootInfo.Exists) {
        throw "SYNAPSE_PHYSICAL_TREE_ROOT_MISSING path=$rootFull remediation=preserve candidate evidence; the physical directory disappeared during bounded inspection"
    }
    if ($rootInfo.Attributes -band [System.IO.FileAttributes]::ReparsePoint) {
        throw "SYNAPSE_PHYSICAL_TREE_REPARSE_POINT path=$rootFull depth=0 remediation=preserve candidate evidence; setup never follows junctions, symlinks, or other reparse points"
    }
    $files = [System.Collections.Generic.List[object]]::new()
    $directories = [System.Collections.Generic.List[object]]::new()
    $stack = [System.Collections.Generic.Stack[object]]::new()
    $stack.Push([pscustomobject]@{ Directory = $rootInfo; Depth = 0; Identity = $rootIdentity })
    $entryCount = 0
    while ($stack.Count -gt 0) {
        $frame = $stack.Pop()
        $directory = $frame.Directory
        $depth = [int]$frame.Depth
        if ($depth -gt $MaxDepth) {
            throw "SYNAPSE_PHYSICAL_TREE_DEPTH_EXCEEDED root=$rootFull path=$($directory.FullName) depth=$depth max_depth=$MaxDepth remediation=preserve and inspect the unexpectedly deep candidate tree"
        }
        $directory.Refresh()
        if (-not $directory.Exists) { continue }
        if ($directory.Attributes -band [System.IO.FileAttributes]::ReparsePoint) {
            throw "SYNAPSE_PHYSICAL_TREE_REPARSE_POINT root=$rootFull path=$($directory.FullName) depth=$depth remediation=preserve candidate evidence; setup never traverses reparse directories"
        }
        $directoryFull = [System.IO.Path]::GetFullPath($directory.FullName).TrimEnd('\')
        if (-not $directoryFull.Equals($rootFull, [System.StringComparison]::OrdinalIgnoreCase) -and
            -not $directoryFull.StartsWith($rootPrefix, [System.StringComparison]::OrdinalIgnoreCase)) {
            throw "SYNAPSE_PHYSICAL_TREE_SCOPE_ESCAPE root=$rootFull path=$directoryFull depth=$depth remediation=preserve candidate evidence; physical traversal left the exact candidate root"
        }
        $directoryIdentity = [SynapseSetup.AtomicFileV2]::GetPhysicalEntryIdentityUnderRoot(
            $rootFull,
            $rootIdentity,
            $directoryFull,
            [string]$frame.Identity,
            $true).Identity
        $directories.Add([pscustomobject]@{ Path = $directoryFull; Depth = $depth; Identity = $directoryIdentity })
        try {
            $entries = @($directory.EnumerateFileSystemInfos())
        } catch {
            throw "SYNAPSE_PHYSICAL_TREE_ENUMERATION_FAILED root=$rootFull path=$directoryFull depth=$depth error=$($_.Exception.Message) remediation=preserve candidate evidence until every physical directory is readable"
        }
        foreach ($entry in $entries) {
            $entry.Refresh()
            if (-not $entry.Exists) { continue }
            $entryCount++
            if ($entryCount -gt $MaxEntries) {
                throw "SYNAPSE_PHYSICAL_TREE_ENTRY_BOUND_EXCEEDED root=$rootFull count=$entryCount max_entries=$MaxEntries remediation=preserve and inspect the unexpectedly large candidate tree"
            }
            $entryFull = [System.IO.Path]::GetFullPath($entry.FullName)
            if (-not $entryFull.StartsWith($rootPrefix, [System.StringComparison]::OrdinalIgnoreCase)) {
                throw "SYNAPSE_PHYSICAL_TREE_SCOPE_ESCAPE root=$rootFull path=$entryFull depth=$depth remediation=preserve candidate evidence; physical entry left the exact candidate root"
            }
            $attributes = $entry.Attributes
            if ($attributes -band [System.IO.FileAttributes]::ReparsePoint) {
                throw "SYNAPSE_PHYSICAL_TREE_REPARSE_POINT root=$rootFull path=$entryFull depth=$($depth + 1) attributes=$attributes remediation=preserve candidate evidence; setup never reads or deletes through a reparse point"
            }
            $entryIsDirectory = [bool]($attributes -band [System.IO.FileAttributes]::Directory)
            $entryIdentity = [SynapseSetup.AtomicFileV2]::GetPhysicalEntryIdentityUnderRoot(
                $rootFull,
                $rootIdentity,
                $entryFull,
                '',
                $entryIsDirectory).Identity
            if ($entryIsDirectory) {
                $stack.Push([pscustomobject]@{ Directory = [System.IO.DirectoryInfo]::new($entryFull); Depth = $depth + 1; Identity = $entryIdentity })
            } else {
                $files.Add([pscustomobject]@{ Path = $entryFull; Identity = $entryIdentity })
            }
        }
    }
    return [pscustomobject]@{
        Root = $rootFull
        RootIdentity = $rootIdentity
        EntryCount = $entryCount
        Files = @($files | Sort-Object Path)
        Directories = @($directories | Sort-Object Depth -Descending)
    }
}

function Remove-SynapsePhysicalDirectoryTreeNoReparse {
    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][ValidatePattern('^(?:[0-9A-Fa-f]{8}:[0-9A-Fa-f]{16}|[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32})$')][string]$ExpectedRootIdentity
    )

    $snapshot = Get-SynapsePhysicalDirectoryTreeSnapshotNoReparse `
        -Path $Path `
        -ExpectedRootIdentity $ExpectedRootIdentity
    Ensure-SynapseAtomicFileType
    foreach ($file in $snapshot.Files) {
        [SynapseSetup.AtomicFileV2]::DeletePhysicalEntryUnderRoot(
            $snapshot.Root,
            $snapshot.RootIdentity,
            $file.Path,
            $file.Identity,
            $false)
    }
    foreach ($directoryRecord in $snapshot.Directories) {
        [SynapseSetup.AtomicFileV2]::DeletePhysicalEntryUnderRoot(
            $snapshot.Root,
            $snapshot.RootIdentity,
            [string]$directoryRecord.Path,
            [string]$directoryRecord.Identity,
            $true)
    }
    return $snapshot
}

function Test-SynapsePathWithinOrEqual {
    param(
        [Parameter(Mandatory=$true)][string]$Ancestor,
        [Parameter(Mandatory=$true)][string]$Candidate
    )
    $ancestorFull=[System.IO.Path]::GetFullPath($Ancestor)
    $candidateFull=[System.IO.Path]::GetFullPath($Candidate)
    $ancestorRoot=[System.IO.Path]::GetPathRoot($ancestorFull)
    if($ancestorFull-ine$ancestorRoot){$ancestorFull=$ancestorFull.TrimEnd('\')}
    if($candidateFull-ine[System.IO.Path]::GetPathRoot($candidateFull)){$candidateFull=$candidateFull.TrimEnd('\')}
    $prefix=if($ancestorFull.EndsWith('\')){$ancestorFull}else{$ancestorFull+'\'}
    return $candidateFull.Equals($ancestorFull,[System.StringComparison]::OrdinalIgnoreCase) -or
        $candidateFull.StartsWith($prefix,[System.StringComparison]::OrdinalIgnoreCase)
}

function Get-SynapsePurgePhysicalDirectoryBoundary {
    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $full=Get-SynapseNormalizedDirectoryPath -Path $Path
    if([System.IO.Directory]::Exists($full)){
        $chain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $full)
        if($chain.Count-lt1){Die "SYNAPSE_PURGE_PHYSICAL_DIRECTORY_CHAIN_EMPTY context=$Context path=$full"}
        return [pscustomobject][ordered]@{Path=$full;Exists=$true;Chain=$chain;EffectiveChain=$chain;TerminalFileId128=([string]$chain[-1].file_id_128).ToUpperInvariant()}
    }
    if([System.IO.File]::Exists($full)){Die "SYNAPSE_PURGE_DIRECTORY_TYPE_COLLISION context=$Context path=$full"}
    $absence=Get-SynapsePurgeAbsenceAnchor -Path $full -Kind directory -Context $Context
    Assert-SynapsePurgeAbsenceAnchor -Anchor $absence -Context "${Context}_absence"
    $anchorChain=@($absence.anchor_chain)
    return [pscustomobject][ordered]@{Path=$full;Exists=$false;Chain=@();EffectiveChain=$anchorChain;TerminalFileId128=''}
}

function Test-SynapsePurgePhysicalAncestor {
    param(
        [Parameter(Mandatory=$true)]$AncestorBoundary,
        [Parameter(Mandatory=$true)]$CandidateBoundary
    )
    if(-not[bool]$AncestorBoundary.Exists){return $false}
    $ancestorId=([string]$AncestorBoundary.TerminalFileId128).ToUpperInvariant()
    return @($CandidateBoundary.EffectiveChain|Where-Object{[string]$_.file_id_128-ine$null-and([string]$_.file_id_128).ToUpperInvariant()-ceq$ancestorId}).Count-gt0
}

function Get-SynapsePurgePhysicalFileIdentityOrNull {
    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $full=[System.IO.Path]::GetFullPath($Path);$parent=Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $full);$leaf=Split-Path -Leaf $full
    $parentBoundary=Get-SynapsePurgePhysicalDirectoryBoundary -Path $parent -Context "${Context}_parent"
    if(-not[bool]$parentBoundary.Exists){return $null}
    $state=Get-SynapsePhysicalRelativeState -ParentPath $parent -ParentChain $parentBoundary.Chain -Leaf $leaf
    if(-not[bool]$state.Exists){return $null}
    return [pscustomobject][ordered]@{Path=$full;FileId128=([string]$state.FileId128).ToUpperInvariant();Sha256=([string]$state.Sha256).ToUpperInvariant();Length=[int64]$state.Length;ParentBoundary=$parentBoundary}
}

function Assert-SynapsePurgePathContract {
    param(
        [Parameter(Mandatory=$true)][string]$DbPath,
        [Parameter(Mandatory=$true)][string]$ProfilesDir,
        [Parameter(Mandatory=$true)][string]$TokenPath,
        [Parameter(Mandatory=$true)][string]$RuntimeBinDir,
        [Parameter(Mandatory=$true)][string]$LogDir,
        [Parameter(Mandatory=$true)][string]$MaintenanceLockPath,
        [Parameter(Mandatory=$true)][string]$ExePath,
        [AllowEmptyString()][string]$SourceDir,
        [AllowEmptyString()][string]$CodexToolSurfaceSnapshotPath,
        [AllowEmptyString()][string]$ChromeNativeHostExePath,
        [AllowEmptyString()][string]$ChromeBridgePendingPath
    )
    $db=Get-SynapseNormalizedDirectoryPath -Path $DbPath
    $profiles=Get-SynapseNormalizedDirectoryPath -Path $ProfilesDir
    $token=[System.IO.Path]::GetFullPath($TokenPath)
    $recordRoot=Get-SynapseNormalizedDirectoryPath -Path (Join-Path $env:LOCALAPPDATA 'synapse\deletion-records')
    $decommissionRecordRoot=Get-SynapseNormalizedDirectoryPath -Path (Join-Path $env:LOCALAPPDATA 'synapse\decommission-records')
    $authorityRoot=Get-SynapseNormalizedDirectoryPath -Path (Join-Path $RuntimeBinDir $script:SynapseAuthorityRootLeaf)
    foreach($item in @([pscustomobject]@{Role='database';Path=$db},[pscustomobject]@{Role='profiles';Path=$profiles})){
        $root=[System.IO.Path]::GetPathRoot([string]$item.Path)
        if([string]::IsNullOrWhiteSpace($root)-or[string]$item.Path-ieq$root){Die "SYNAPSE_PURGE_BROAD_ROOT_REFUSED role=$($item.Role) path=$($item.Path)"}
    }
    $broad=@($env:USERPROFILE,$env:HOME,$env:LOCALAPPDATA,$env:APPDATA,$env:ProgramData,$env:SystemRoot,[Environment]::GetFolderPath('Desktop'),[Environment]::GetFolderPath('MyDocuments'))|Where-Object{-not[string]::IsNullOrWhiteSpace([string]$_)}|ForEach-Object{[System.IO.Path]::GetFullPath([string]$_)}
    foreach($target in @($db,$profiles)){
        foreach($b in $broad){if(Test-SynapsePathWithinOrEqual -Ancestor $target -Candidate $b){Die "SYNAPSE_PURGE_BROAD_ROOT_REFUSED path=$target protected=$b remediation=choose a dedicated narrow Synapse data directory"}}
    }
    if((Test-SynapsePathWithinOrEqual -Ancestor $db -Candidate $profiles)-or(Test-SynapsePathWithinOrEqual -Ancestor $profiles -Candidate $db)){Die "SYNAPSE_PURGE_DIRECTORY_OVERLAP_REFUSED db=$db profiles=$profiles"}
    if((Test-SynapsePathWithinOrEqual -Ancestor $db -Candidate $token)-or(Test-SynapsePathWithinOrEqual -Ancestor $profiles -Candidate $token)){Die "SYNAPSE_PURGE_TOKEN_DIRECTORY_OVERLAP_REFUSED token=$token db=$db profiles=$profiles"}
    $recordOverlapProtected=[System.IO.Path]::GetFullPath($recordRoot)
    foreach($target in @($db,$profiles)){
        if((Test-SynapsePathWithinOrEqual -Ancestor $target -Candidate $recordOverlapProtected)-or(Test-SynapsePathWithinOrEqual -Ancestor $recordOverlapProtected -Candidate $target)){Die "SYNAPSE_PURGE_RECORD_ROOT_OVERLAP target=$target record_root=$recordOverlapProtected"}
        if((Test-SynapsePathWithinOrEqual -Ancestor $target -Candidate $decommissionRecordRoot)-or(Test-SynapsePathWithinOrEqual -Ancestor $decommissionRecordRoot -Candidate $target)){Die "SYNAPSE_PURGE_DECOMMISSION_RECORD_ROOT_OVERLAP target=$target record_root=$decommissionRecordRoot"}
        if((Test-SynapsePathWithinOrEqual -Ancestor $target -Candidate $authorityRoot)-or(Test-SynapsePathWithinOrEqual -Ancestor $authorityRoot -Candidate $target)){Die "SYNAPSE_PURGE_AUTHORITY_ROOT_OVERLAP target=$target authority_root=$authorityRoot"}
    }
    if((Test-SynapsePathWithinOrEqual -Ancestor $recordOverlapProtected -Candidate $authorityRoot)-or(Test-SynapsePathWithinOrEqual -Ancestor $authorityRoot -Candidate $recordOverlapProtected)){Die "SYNAPSE_PURGE_RECORD_AUTHORITY_ROOT_OVERLAP record_root=$recordOverlapProtected authority_root=$authorityRoot"}
    if((Test-SynapsePathWithinOrEqual -Ancestor $decommissionRecordRoot -Candidate $authorityRoot)-or(Test-SynapsePathWithinOrEqual -Ancestor $authorityRoot -Candidate $decommissionRecordRoot)){Die "SYNAPSE_PURGE_DECOMMISSION_RECORD_AUTHORITY_ROOT_OVERLAP record_root=$decommissionRecordRoot authority_root=$authorityRoot"}
    if((Test-SynapsePathWithinOrEqual -Ancestor $decommissionRecordRoot -Candidate $recordOverlapProtected)-or(Test-SynapsePathWithinOrEqual -Ancestor $recordOverlapProtected -Candidate $decommissionRecordRoot)){Die "SYNAPSE_PURGE_RECORD_ROOTS_OVERLAP purge_record_root=$recordOverlapProtected decommission_record_root=$decommissionRecordRoot"}
    $protected=@($RuntimeBinDir,$LogDir,(Split-Path -Parent $MaintenanceLockPath),(Split-Path -Parent $ExePath),$SourceDir)|Where-Object{-not[string]::IsNullOrWhiteSpace([string]$_)}|ForEach-Object{[System.IO.Path]::GetFullPath([string]$_)}
    foreach($target in @($db,$profiles)){
        foreach($p in $protected){if(Test-SynapsePathWithinOrEqual -Ancestor $target -Candidate $p){Die "SYNAPSE_PURGE_PROTECTED_PATH_OVERLAP role=directory target=$target protected=$p"}}
    }
    $systemProtected=@($env:SystemRoot,[Environment]::SystemDirectory,$env:ProgramFiles,${env:ProgramFiles(x86)},$env:ProgramData)|Where-Object{-not[string]::IsNullOrWhiteSpace([string]$_)}|ForEach-Object{[System.IO.Path]::GetFullPath([string]$_)}
    foreach($target in @($db,$profiles)){
        foreach($p in $systemProtected){if(Test-SynapsePathWithinOrEqual -Ancestor $p -Candidate $target){Die "SYNAPSE_PURGE_SYSTEM_PATH_REFUSED role=directory target=$target protected=$p"}}
    }
    $protectedFiles=@($MaintenanceLockPath,$ExePath,$PSCommandPath,$CodexToolSurfaceSnapshotPath,$ChromeNativeHostExePath,$ChromeBridgePendingPath)|Where-Object{-not[string]::IsNullOrWhiteSpace([string]$_)}
    foreach($protectedFile in $protectedFiles){
        $protectedFileFull=[System.IO.Path]::GetFullPath([string]$protectedFile)
        if($token-ieq$protectedFileFull){Die "SYNAPSE_PURGE_PROTECTED_PATH_OVERLAP role=token target=$token protected=$protectedFileFull"}
        foreach($target in @($db,$profiles)){if(Test-SynapsePathWithinOrEqual -Ancestor $target -Candidate $protectedFileFull){Die "SYNAPSE_PURGE_PROTECTED_PATH_OVERLAP role=directory target=$target protected=$protectedFileFull"}}
    }
    foreach($p in @($systemProtected+$protected+$recordOverlapProtected+$decommissionRecordRoot)){
        if(Test-SynapsePathWithinOrEqual -Ancestor ([string]$p) -Candidate $token){Die "SYNAPSE_PURGE_SYSTEM_PATH_REFUSED role=token target=$token protected=$p"}
    }
    if([string]::IsNullOrWhiteSpace((Split-Path -Leaf $token))){Die "SYNAPSE_PURGE_TOKEN_LEAF_INVALID path=$token"}

    # Lexical normalization does not collapse DOS 8.3 aliases.  Bind the real
    # directory objects as well so an aliased target cannot contain a protected
    # root (or conceal overlap with the other purge target/record root).
    $dbBoundary=Get-SynapsePurgePhysicalDirectoryBoundary -Path $db -Context 'purge_contract_database'
    $profilesBoundary=Get-SynapsePurgePhysicalDirectoryBoundary -Path $profiles -Context 'purge_contract_profiles'
    $recordBoundary=Get-SynapsePurgePhysicalDirectoryBoundary -Path $recordRoot -Context 'purge_contract_record_root'
    $decommissionRecordBoundary=Get-SynapsePurgePhysicalDirectoryBoundary -Path $decommissionRecordRoot -Context 'purge_contract_decommission_record_root'
    $authorityBoundary=Get-SynapsePurgePhysicalDirectoryBoundary -Path $authorityRoot -Context 'purge_contract_authority_root'
    $tokenParentBoundary=Get-SynapsePurgePhysicalDirectoryBoundary -Path (Split-Path -Parent $token) -Context 'purge_contract_token_parent'
    if((Test-SynapsePurgePhysicalAncestor -AncestorBoundary $recordBoundary -CandidateBoundary $authorityBoundary)-or(Test-SynapsePurgePhysicalAncestor -AncestorBoundary $authorityBoundary -CandidateBoundary $recordBoundary)){Die "SYNAPSE_PURGE_PHYSICAL_RECORD_AUTHORITY_ROOT_OVERLAP record_root=$recordRoot authority_root=$authorityRoot"}
    if((Test-SynapsePurgePhysicalAncestor -AncestorBoundary $decommissionRecordBoundary -CandidateBoundary $authorityBoundary)-or(Test-SynapsePurgePhysicalAncestor -AncestorBoundary $authorityBoundary -CandidateBoundary $decommissionRecordBoundary)){Die "SYNAPSE_PURGE_PHYSICAL_DECOMMISSION_RECORD_AUTHORITY_ROOT_OVERLAP record_root=$decommissionRecordRoot authority_root=$authorityRoot"}
    if((Test-SynapsePurgePhysicalAncestor -AncestorBoundary $decommissionRecordBoundary -CandidateBoundary $recordBoundary)-or(Test-SynapsePurgePhysicalAncestor -AncestorBoundary $recordBoundary -CandidateBoundary $decommissionRecordBoundary)){Die "SYNAPSE_PURGE_PHYSICAL_RECORD_ROOTS_OVERLAP purge_record_root=$recordRoot decommission_record_root=$decommissionRecordRoot"}
    if((Test-SynapsePurgePhysicalAncestor -AncestorBoundary $dbBoundary -CandidateBoundary $profilesBoundary)-or(Test-SynapsePurgePhysicalAncestor -AncestorBoundary $profilesBoundary -CandidateBoundary $dbBoundary)){Die "SYNAPSE_PURGE_PHYSICAL_DIRECTORY_OVERLAP_REFUSED db=$db profiles=$profiles"}
    foreach($targetBoundary in @($dbBoundary,$profilesBoundary)){
        if((Test-SynapsePurgePhysicalAncestor -AncestorBoundary $targetBoundary -CandidateBoundary $recordBoundary)-or(Test-SynapsePurgePhysicalAncestor -AncestorBoundary $recordBoundary -CandidateBoundary $targetBoundary)){Die "SYNAPSE_PURGE_PHYSICAL_RECORD_ROOT_OVERLAP target=$($targetBoundary.Path) record_root=$recordRoot"}
        if((Test-SynapsePurgePhysicalAncestor -AncestorBoundary $targetBoundary -CandidateBoundary $decommissionRecordBoundary)-or(Test-SynapsePurgePhysicalAncestor -AncestorBoundary $decommissionRecordBoundary -CandidateBoundary $targetBoundary)){Die "SYNAPSE_PURGE_PHYSICAL_DECOMMISSION_RECORD_ROOT_OVERLAP target=$($targetBoundary.Path) record_root=$decommissionRecordRoot"}
        if((Test-SynapsePurgePhysicalAncestor -AncestorBoundary $targetBoundary -CandidateBoundary $authorityBoundary)-or(Test-SynapsePurgePhysicalAncestor -AncestorBoundary $authorityBoundary -CandidateBoundary $targetBoundary)){Die "SYNAPSE_PURGE_PHYSICAL_AUTHORITY_ROOT_OVERLAP target=$($targetBoundary.Path) authority_root=$authorityRoot"}
        if(Test-SynapsePurgePhysicalAncestor -AncestorBoundary $targetBoundary -CandidateBoundary $tokenParentBoundary){Die "SYNAPSE_PURGE_PHYSICAL_TOKEN_DIRECTORY_OVERLAP target=$($targetBoundary.Path) token=$token"}
    }
    foreach($protectedPath in @($protected+$systemProtected+$broad)|Select-Object -Unique){
        $protectedBoundary=Get-SynapsePurgePhysicalDirectoryBoundary -Path ([string]$protectedPath) -Context 'purge_contract_protected_directory'
        foreach($targetBoundary in @($dbBoundary,$profilesBoundary)){
            if(Test-SynapsePurgePhysicalAncestor -AncestorBoundary $targetBoundary -CandidateBoundary $protectedBoundary){Die "SYNAPSE_PURGE_PHYSICAL_PROTECTED_PATH_OVERLAP target=$($targetBoundary.Path) protected=$($protectedBoundary.Path)"}
        }
    }
    foreach($systemPath in @($systemProtected|Select-Object -Unique)){$systemBoundary=Get-SynapsePurgePhysicalDirectoryBoundary -Path ([string]$systemPath) -Context 'purge_contract_system_directory';foreach($targetBoundary in @($dbBoundary,$profilesBoundary)){if(Test-SynapsePurgePhysicalAncestor -AncestorBoundary $systemBoundary -CandidateBoundary $targetBoundary){Die "SYNAPSE_PURGE_PHYSICAL_SYSTEM_PATH_REFUSED role=directory target=$($targetBoundary.Path) protected=$($systemBoundary.Path)"}}}
    foreach($protectedPath in @($protected+$systemProtected+$recordOverlapProtected+$decommissionRecordRoot)|Select-Object -Unique){$protectedBoundary=Get-SynapsePurgePhysicalDirectoryBoundary -Path ([string]$protectedPath) -Context 'purge_contract_token_protected_directory';if(Test-SynapsePurgePhysicalAncestor -AncestorBoundary $protectedBoundary -CandidateBoundary $tokenParentBoundary){Die "SYNAPSE_PURGE_PHYSICAL_SYSTEM_PATH_REFUSED role=token target=$token protected=$($protectedBoundary.Path)"}}
    $tokenIdentity=Get-SynapsePurgePhysicalFileIdentityOrNull -Path $token -Context 'purge_contract_token'
    foreach($protectedFile in $protectedFiles){
        $protectedParentBoundary=Get-SynapsePurgePhysicalDirectoryBoundary -Path (Split-Path -Parent ([System.IO.Path]::GetFullPath([string]$protectedFile))) -Context 'purge_contract_protected_file_parent'
        foreach($targetBoundary in @($dbBoundary,$profilesBoundary)){if(Test-SynapsePurgePhysicalAncestor -AncestorBoundary $targetBoundary -CandidateBoundary $protectedParentBoundary){Die "SYNAPSE_PURGE_PHYSICAL_PROTECTED_FILE_PARENT_OVERLAP target=$($targetBoundary.Path) protected=$protectedFile"}}
        if($null-ne$tokenIdentity){$protectedIdentity=Get-SynapsePurgePhysicalFileIdentityOrNull -Path ([string]$protectedFile) -Context 'purge_contract_protected_file';if($null-ne$protectedIdentity-and[string]$protectedIdentity.FileId128-ieq[string]$tokenIdentity.FileId128){Die "SYNAPSE_PURGE_PHYSICAL_PROTECTED_FILE_ALIAS role=token target=$token protected=$($protectedIdentity.Path) file_id_128=$($tokenIdentity.FileId128)"}}
    }
    $contract=[ordered]@{schema='synapse_setup_purge_target_contract/v1';db_path=$db;profiles_dir=$profiles;token_path=$token;record_root=$recordRoot}
    return [pscustomobject][ordered]@{DbPath=$db;ProfilesDir=$profiles;TokenPath=$token;RecordRoot=$recordRoot;Contract=$contract;ContractSha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $contract)).ToUpperInvariant()}
}

function Get-SynapsePurgeAbsenceAnchor {
    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][ValidateSet('file','directory')][string]$Kind,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $full=[System.IO.Path]::GetFullPath($Path);$missing=[System.Collections.Generic.List[string]]::new();$cursor=$full
    while(-not[System.IO.Directory]::Exists($cursor)-and-not[System.IO.File]::Exists($cursor)){
        $leaf=Split-Path -Leaf $cursor;if([string]::IsNullOrWhiteSpace($leaf)){Die "SYNAPSE_PURGE_ABSENCE_ANCHOR_INVALID context=$Context path=$full"}
        $missing.Insert(0,$leaf);$next=Split-Path -Parent $cursor;if([string]::IsNullOrWhiteSpace($next)-or$next-eq$cursor){Die "SYNAPSE_PURGE_ABSENCE_ANCESTOR_INVALID context=$Context path=$full"};$cursor=[System.IO.Path]::GetFullPath($next)
    }
    if([System.IO.File]::Exists($cursor)){Die "SYNAPSE_PURGE_ABSENCE_ANCESTOR_FILE context=$Context path=$full ancestor=$cursor"}
    if($missing.Count-lt1){Die "SYNAPSE_PURGE_ABSENCE_REQUESTED_FOR_PRESENT_PATH context=$Context path=$full"}
    $anchor=Get-SynapseNormalizedDirectoryPath -Path $cursor;$chain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $anchor);$first=[string]$missing[0];$firstIsDirectory=($missing.Count-gt1-or$Kind-ceq'directory')
    $state=Get-SynapsePhysicalRelativeState -ParentPath $anchor -ParentChain $chain -Leaf $first -Directory:$firstIsDirectory
    if([bool]$state.Exists){Die "SYNAPSE_PURGE_ABSENCE_ANCHOR_DRIFT context=$Context path=$full first_missing=$(Join-Path $anchor $first)"}
    return [ordered]@{schema='synapse_setup_purge_absence_anchor/v1';path=$full;kind=$Kind;anchor_path=$anchor;anchor_chain=@($chain|ForEach-Object{[ordered]@{path=[string]$_.path;file_id_128=([string]$_.file_id_128).ToUpperInvariant()}});first_missing_leaf=$first;first_missing_is_directory=$firstIsDirectory}
}

function Assert-SynapsePurgeAbsenceAnchor {
    param([Parameter(Mandatory=$true)]$Anchor,[Parameter(Mandatory=$true)][string]$Context)
    if([string]$Anchor.schema-cne'synapse_setup_purge_absence_anchor/v1'){Die "SYNAPSE_PURGE_ABSENCE_SCHEMA_INVALID context=$Context"}
    $chain=@($Anchor.anchor_chain);[void](Assert-SynapsePhysicalDirectoryChainDescriptor -Chain $chain -ExpectedPath ([string]$Anchor.anchor_path) -Context $Context)
    $actual=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path ([string]$Anchor.anchor_path))
    if((Get-SynapseCanonicalJson -Value $actual)-cne(Get-SynapseCanonicalJson -Value $chain)){Die "SYNAPSE_PURGE_ABSENCE_ANCHOR_IDENTITY_DRIFT context=$Context path=$($Anchor.anchor_path)"}
    $state=Get-SynapsePhysicalRelativeState -ParentPath ([string]$Anchor.anchor_path) -ParentChain $actual -Leaf ([string]$Anchor.first_missing_leaf) -Directory:([bool]$Anchor.first_missing_is_directory)
    if([bool]$state.Exists){Die "SYNAPSE_PURGE_ABSENCE_INVALIDATED context=$Context path=$($Anchor.path) first_missing=$($Anchor.first_missing_leaf)"}
}

function Get-SynapsePurgeDirectorySnapshot {
    param([Parameter(Mandatory=$true)][string]$Path,[Parameter(Mandatory=$true)][string]$Context)
    $full=Get-SynapseNormalizedDirectoryPath -Path $Path
    if([System.IO.File]::Exists($full)){Die "SYNAPSE_PURGE_DIRECTORY_TYPE_COLLISION context=$Context path=$full"}
    if(-not[System.IO.Directory]::Exists($full)){return [ordered]@{schema='synapse_setup_purge_directory/v1';path=$full;exists=$false;absence=(Get-SynapsePurgeAbsenceAnchor -Path $full -Kind directory -Context $Context);root_parent='';root_parent_chain=@();root_leaf='';root_file_id_128='';entries=@();tree_sha256=('0'*64)}}
    $chain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $full);$parent=Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $full);$parentChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $parent);$leaf=Split-Path -Leaf $full
    $rootState=Get-SynapsePhysicalRelativeState -ParentPath $parent -ParentChain $parentChain -Leaf $leaf -Directory
    if(-not[bool]$rootState.Exists-or[string]$rootState.FileId128-ine[string]$chain[-1].file_id_128){Die "SYNAPSE_PURGE_ROOT_IDENTITY_INVALID context=$Context path=$full"}
    $records=[System.Collections.Generic.List[object]]::new();$stack=[System.Collections.Generic.Stack[object]]::new();$stack.Push([pscustomobject]@{Path=$full;Relative=''})
    while($stack.Count-gt0){
        $frame=$stack.Pop();$directoryPath=Get-SynapseNormalizedDirectoryPath -Path ([string]$frame.Path);$directoryChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $directoryPath)
        $children=@(Get-SynapsePhysicalDirectoryEntriesBounded -Path $directoryPath -Chain $directoryChain -MaximumEntries 4096 -Context "${Context}_enumerate")
        foreach($entry in @($children|Sort-Object Name)){
            if(([uint32]$entry.Attributes-band[uint32][System.IO.FileAttributes]::ReparsePoint)){Die "SYNAPSE_PURGE_REPARSE_POINT context=$Context path=$($entry.Path)"}
            $isDirectory=[bool]$entry.IsDirectory;$state=Get-SynapsePhysicalRelativeState -ParentPath $directoryPath -ParentChain $directoryChain -Leaf ([string]$entry.Name) -Directory:$isDirectory
            if(-not[bool]$state.Exists-or[string]$state.FileId128-ine[string]$entry.FileId128){Die "SYNAPSE_PURGE_ENTRY_IDENTITY_DRIFT context=$Context path=$($entry.Path)"}
            $relative=if([string]::IsNullOrWhiteSpace([string]$frame.Relative)){[string]$entry.Name}else{([string]$frame.Relative).TrimEnd('/')+'/'+[string]$entry.Name}
            $records.Add([ordered]@{relative_path=$relative;kind=$(if($isDirectory){'directory'}else{'file'});file_id_128=([string]$state.FileId128).ToUpperInvariant();sha256=$(if($isDirectory){''}else{([string]$state.Sha256).ToUpperInvariant()});length=$(if($isDirectory){-1L}else{[int64]$state.Length})})
            if($records.Count-gt200000){Die "SYNAPSE_PURGE_TREE_BOUND_EXCEEDED context=$Context path=$full max=200000"}
            if($isDirectory){$stack.Push([pscustomobject]@{Path=[string]$entry.Path;Relative=$relative})}
        }
    }
    $sorted=@($records|Sort-Object relative_path);$treeSha=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $sorted)).ToUpperInvariant()
    return [ordered]@{schema='synapse_setup_purge_directory/v1';path=$full;exists=$true;absence=$null;root_parent=$parent;root_parent_chain=@($parentChain|ForEach-Object{[ordered]@{path=[string]$_.path;file_id_128=([string]$_.file_id_128).ToUpperInvariant()}});root_leaf=$leaf;root_file_id_128=([string]$rootState.FileId128).ToUpperInvariant();entries=$sorted;tree_sha256=$treeSha}
}

function Get-SynapsePurgeFileSnapshot {
    param([Parameter(Mandatory=$true)][string]$Path,[Parameter(Mandatory=$true)][string]$Context)
    $full=[System.IO.Path]::GetFullPath($Path)
    if([System.IO.Directory]::Exists($full)){Die "SYNAPSE_PURGE_FILE_TYPE_COLLISION context=$Context path=$full"}
    if(-not[System.IO.File]::Exists($full)){return [ordered]@{schema='synapse_setup_purge_file/v1';path=$full;exists=$false;absence=(Get-SynapsePurgeAbsenceAnchor -Path $full -Kind file -Context $Context);parent='';parent_chain=@();leaf='';file_id_128='';sha256='';length=-1L}}
    $parent=Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $full);$chain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $parent);$leaf=Split-Path -Leaf $full;$state=Get-SynapsePhysicalRelativeState -ParentPath $parent -ParentChain $chain -Leaf $leaf
    if(-not[bool]$state.Exists){Die "SYNAPSE_PURGE_FILE_DISAPPEARED context=$Context path=$full"}
    return [ordered]@{schema='synapse_setup_purge_file/v1';path=$full;exists=$true;absence=$null;parent=$parent;parent_chain=@($chain|ForEach-Object{[ordered]@{path=[string]$_.path;file_id_128=([string]$_.file_id_128).ToUpperInvariant()}});leaf=$leaf;file_id_128=([string]$state.FileId128).ToUpperInvariant();sha256=([string]$state.Sha256).ToUpperInvariant();length=[int64]$state.Length}
}

function Open-SynapsePurgeRecordExact {
    param(
        [Parameter(Mandatory=$true)][string]$RecordRoot,
        [Parameter(Mandatory=$true)]$RecordRootChain,
        [Parameter(Mandatory=$true)][string]$Leaf,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $state=Get-SynapsePhysicalRelativeState -ParentPath $RecordRoot -ParentChain $RecordRootChain -Leaf $Leaf
    if(-not[bool]$state.Exists-or[int64]$state.Length-lt1-or[int64]$state.Length-gt16777216){Die "SYNAPSE_PURGE_RECORD_STATE_INVALID context=$Context leaf=$Leaf length=$($state.Length)"}
    $lease=Open-SynapsePhysicalFileReadLease -ParentPath $RecordRoot -ParentChain $RecordRootChain -Leaf $Leaf -ExpectedFileId128 ([string]$state.FileId128) -ExpectedSha256 ([string]$state.Sha256) -ExpectedLength ([int64]$state.Length) -Context $Context
    try{$text=[string]$lease.ReadUtf8(16777216).Content;try{$payload=ConvertTo-SynapseCanonicalValue -Value (ConvertFrom-SynapseJsonPreservingStrings -Json $text -MaximumJsonLength 16777216)}catch{Die "SYNAPSE_PURGE_RECORD_JSON_INVALID context=$Context leaf=$Leaf error=$($_.Exception.Message)"};if(((Get-SynapseCanonicalJson -Value $payload)+"`n")-cne$text){Die "SYNAPSE_PURGE_RECORD_CANONICAL_INVALID context=$Context leaf=$Leaf"};$lease.RequireExact("${Context}_readback");return [pscustomobject][ordered]@{Leaf=$Leaf;Path=(Join-Path $RecordRoot $Leaf);State=$state;Payload=$payload;Lease=$lease}}catch{try{$lease.Dispose()}catch{};throw}
}

function Open-SynapsePurgeRecordFromBoundedState {
    param(
        [Parameter(Mandatory=$true)][string]$RecordRoot,
        [Parameter(Mandatory=$true)]$RecordRootChain,
        [Parameter(Mandatory=$true)][string]$Leaf,
        [Parameter(Mandatory=$true)]$State,
        [Parameter(Mandatory=$true)][string]$Context
    )
    if(-not[bool]$State.Exists-or[string]$State.FileId128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'-or[string]$State.Sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[int64]$State.Length-lt1-or[int64]$State.Length-gt16777216){Die "SYNAPSE_PURGE_BOUNDED_RECORD_STATE_INVALID context=$Context leaf=$Leaf length=$($State.Length)"}
    $lease=Open-SynapsePhysicalFileReadLease -ParentPath $RecordRoot -ParentChain $RecordRootChain -Leaf $Leaf -ExpectedFileId128 ([string]$State.FileId128) -ExpectedSha256 ([string]$State.Sha256) -ExpectedLength ([int64]$State.Length) -Context $Context
    try{$text=[string]$lease.ReadUtf8(16777216).Content;try{$payload=ConvertTo-SynapseCanonicalValue -Value (ConvertFrom-SynapseJsonPreservingStrings -Json $text -MaximumJsonLength 16777216)}catch{Die "SYNAPSE_PURGE_RECORD_JSON_INVALID context=$Context leaf=$Leaf error=$($_.Exception.Message)"};if(((Get-SynapseCanonicalJson -Value $payload)+"`n")-cne$text){Die "SYNAPSE_PURGE_RECORD_CANONICAL_INVALID context=$Context leaf=$Leaf"};$lease.RequireExact("${Context}_readback");return [pscustomobject][ordered]@{Leaf=$Leaf;Path=(Join-Path $RecordRoot $Leaf);State=$State;Payload=$payload;Lease=$lease}}catch{try{$lease.Dispose()}catch{};throw}
}

function Assert-SynapsePurgeExactPropertySet {
    param([Parameter(Mandatory=$true)]$Value,[Parameter(Mandatory=$true)][string[]]$Expected,[Parameter(Mandatory=$true)][string]$Context)
    if($null-eq$Value){Die "SYNAPSE_PURGE_DESCRIPTOR_NULL context=$Context"}
    $actual=@(if($Value-is[System.Collections.IDictionary]){@($Value.Keys|ForEach-Object{[string]$_})}else{@($Value.PSObject.Properties.Name)})
    if($actual.Count-ne$Expected.Count-or@($actual|Where-Object{$Expected-cnotcontains$_}).Count-ne0){Die "SYNAPSE_PURGE_DESCRIPTOR_KEYS_INVALID context=$Context expected=$($Expected-join',') actual=$($actual-join',')"}
}

function Assert-SynapsePurgeStoredDirectoryChain {
    param([Parameter(Mandatory=$true)]$Chain,[Parameter(Mandatory=$true)][string]$ExpectedPath,[Parameter(Mandatory=$true)][string]$Context)
    $items=@($Chain);if($items.Count-lt1){Die "SYNAPSE_PURGE_DIRECTORY_CHAIN_EMPTY context=$Context path=$ExpectedPath"}
    $previous=''
    foreach($item in $items){Assert-SynapsePurgeExactPropertySet -Value $item -Expected @('path','file_id_128') -Context $Context;$path=[System.IO.Path]::GetFullPath([string]$item.path);if([string]$item.file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'){Die "SYNAPSE_PURGE_DIRECTORY_CHAIN_ID_INVALID context=$Context path=$path"};if($previous-and-not(Test-SynapsePathWithinOrEqual -Ancestor $previous -Candidate $path)){Die "SYNAPSE_PURGE_DIRECTORY_CHAIN_ORDER_INVALID context=$Context previous=$previous path=$path"};$previous=$path}
    if($previous-ine[System.IO.Path]::GetFullPath($ExpectedPath)){Die "SYNAPSE_PURGE_DIRECTORY_CHAIN_TERMINAL_INVALID context=$Context expected=$ExpectedPath actual=$previous"}
}

function Assert-SynapsePurgeAbsenceDescriptor {
    param([Parameter(Mandatory=$true)]$Descriptor,[Parameter(Mandatory=$true)][string]$ExpectedPath,[Parameter(Mandatory=$true)][ValidateSet('file','directory')][string]$ExpectedKind,[Parameter(Mandatory=$true)][string]$Context)
    Assert-SynapsePurgeExactPropertySet -Value $Descriptor -Expected @('schema','path','kind','anchor_path','anchor_chain','first_missing_leaf','first_missing_is_directory') -Context $Context
    $path=[System.IO.Path]::GetFullPath([string]$Descriptor.path);$anchor=[System.IO.Path]::GetFullPath([string]$Descriptor.anchor_path);$leaf=[string]$Descriptor.first_missing_leaf
    if([string]$Descriptor.schema-cne'synapse_setup_purge_absence_anchor/v1'-or$path-ine[System.IO.Path]::GetFullPath($ExpectedPath)-or[string]$Descriptor.kind-cne$ExpectedKind-or[string]::IsNullOrWhiteSpace($leaf)-or$leaf.IndexOfAny([System.IO.Path]::GetInvalidFileNameChars())-ge0-or$leaf-ne(Split-Path -Leaf $leaf)-or-not($Descriptor.first_missing_is_directory-is[bool])){Die "SYNAPSE_PURGE_ABSENCE_DESCRIPTOR_INVALID context=$Context path=$path"}
    Assert-SynapsePurgeStoredDirectoryChain -Chain $Descriptor.anchor_chain -ExpectedPath $anchor -Context "${Context}_chain"
    $first=[System.IO.Path]::GetFullPath((Join-Path $anchor $leaf));if(-not(Test-SynapsePathWithinOrEqual -Ancestor $anchor -Candidate $path)-or-not(Test-SynapsePathWithinOrEqual -Ancestor $first -Candidate $path)){Die "SYNAPSE_PURGE_ABSENCE_SCOPE_INVALID context=$Context path=$path anchor=$anchor first=$first"}
}

function Assert-SynapsePurgeDirectoryDescriptor {
    param([Parameter(Mandatory=$true)]$Descriptor,[Parameter(Mandatory=$true)][string]$ExpectedPath,[Parameter(Mandatory=$true)][string]$Context)
    Assert-SynapsePurgeExactPropertySet -Value $Descriptor -Expected @('schema','path','exists','absence','root_parent','root_parent_chain','root_leaf','root_file_id_128','entries','tree_sha256') -Context $Context
    $path=Get-SynapseNormalizedDirectoryPath -Path ([string]$Descriptor.path);$expected=Get-SynapseNormalizedDirectoryPath -Path $ExpectedPath
    if([string]$Descriptor.schema-cne'synapse_setup_purge_directory/v1'-or$path-ine$expected-or-not($Descriptor.exists-is[bool])){Die "SYNAPSE_PURGE_DIRECTORY_DESCRIPTOR_INVALID context=$Context path=$path expected=$expected"}
    if(-not[bool]$Descriptor.exists){if($null-eq$Descriptor.absence-or-not[string]::IsNullOrEmpty([string]$Descriptor.root_parent)-or@($Descriptor.root_parent_chain).Count-ne0-or-not[string]::IsNullOrEmpty([string]$Descriptor.root_leaf)-or-not[string]::IsNullOrEmpty([string]$Descriptor.root_file_id_128)-or@($Descriptor.entries).Count-ne0-or[string]$Descriptor.tree_sha256-cne('0'*64)){Die "SYNAPSE_PURGE_ABSENT_DIRECTORY_DESCRIPTOR_INVALID context=$Context path=$path"};Assert-SynapsePurgeAbsenceDescriptor -Descriptor $Descriptor.absence -ExpectedPath $expected -ExpectedKind directory -Context "${Context}_absence";return}
    if($null-ne$Descriptor.absence-or[string]$Descriptor.root_file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'-or[string]$Descriptor.tree_sha256-notmatch'^[0-9A-Fa-f]{64}$'){Die "SYNAPSE_PURGE_PRESENT_DIRECTORY_DESCRIPTOR_INVALID context=$Context path=$path"}
    $parent=Get-SynapseNormalizedDirectoryPath -Path ([string]$Descriptor.root_parent);$leaf=[string]$Descriptor.root_leaf
    if([System.IO.Path]::GetFullPath((Join-Path $parent $leaf))-ine$path-or$leaf-ne(Split-Path -Leaf $leaf)){Die "SYNAPSE_PURGE_DIRECTORY_ROOT_BINDING_INVALID context=$Context path=$path parent=$parent leaf=$leaf"}
    Assert-SynapsePurgeStoredDirectoryChain -Chain $Descriptor.root_parent_chain -ExpectedPath $parent -Context "${Context}_parent_chain"
    $entries=@($Descriptor.entries);if($entries.Count-gt200000){Die "SYNAPSE_PURGE_DIRECTORY_ENTRY_BOUND_INVALID context=$Context count=$($entries.Count)"};$seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    foreach($entry in $entries){Assert-SynapsePurgeExactPropertySet -Value $entry -Expected @('relative_path','kind','file_id_128','sha256','length') -Context "${Context}_entry";$relative=[string]$entry.relative_path;$segments=@($relative-split'/');if([string]::IsNullOrWhiteSpace($relative)-or$relative.Contains('\')-or[System.IO.Path]::IsPathRooted($relative)-or@($segments|Where-Object{[string]::IsNullOrWhiteSpace($_)-or$_-in@('.','..')}).Count-ne0-or-not$seen.Add($relative)){Die "SYNAPSE_PURGE_DIRECTORY_RELATIVE_PATH_INVALID context=$Context relative=$relative"};$candidate=[System.IO.Path]::GetFullPath((Join-Path $path ($relative.Replace('/','\'))));if(-not(Test-SynapsePathWithinOrEqual -Ancestor $path -Candidate $candidate)-or$candidate-ieq$path-or[string]$entry.file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'-or[string]$entry.kind-notin@('file','directory')){Die "SYNAPSE_PURGE_DIRECTORY_ENTRY_INVALID context=$Context relative=$relative"};if([string]$entry.kind-ceq'file'){if([string]$entry.sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[int64]$entry.length-lt0){Die "SYNAPSE_PURGE_FILE_ENTRY_INVALID context=$Context relative=$relative"}}elseif(-not[string]::IsNullOrEmpty([string]$entry.sha256)-or[int64]$entry.length-ne-1L){Die "SYNAPSE_PURGE_CHILD_DIRECTORY_ENTRY_INVALID context=$Context relative=$relative"}}
    $tree=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $entries)).ToUpperInvariant();if($tree-ine[string]$Descriptor.tree_sha256){Die "SYNAPSE_PURGE_DIRECTORY_TREE_HASH_INVALID context=$Context expected=$($Descriptor.tree_sha256) actual=$tree"}
}

function Assert-SynapsePurgeProfilesOwnershipDescriptor {
    param(
        [Parameter(Mandatory=$true)]$Descriptor,
        [Parameter(Mandatory=$true)]$ProfilesPlan,
        [Parameter(Mandatory=$true)][string]$Context
    )
    Assert-SynapsePurgeExactPropertySet -Value $Descriptor -Expected @('schema','manifest_relative_path','manifest_file_id_128','manifest_sha256','manifest_length','manifest_payload','manifest_payload_sha256','owned_entry_count','owned_entries_sha256','custom_profiles_absent','legacy_mismatches_absent') -Context $Context
    $manifest=$Descriptor.manifest_payload
    Assert-SynapsePurgeExactPropertySet -Value $manifest -Expected @('schema_version','owner','generated_at_utc','source_profiles_dir','deployed_profiles_dir','source_manifest_sha256','bundled_file_count','bundled_profile_count','files','quarantined_retired','preserved_custom_profiles','preserved_legacy_retired_hash_mismatches','generation_identity_semantics') -Context "${Context}_manifest"
    if([string]$Descriptor.schema-cne'synapse_setup_purge_profiles_ownership/v1'-or-not[bool]$ProfilesPlan.exists-or[string]$Descriptor.manifest_relative_path-cne$script:SynapseBundledProfilesManifestFileName-or[string]$Descriptor.manifest_file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'-or[string]$Descriptor.manifest_sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[int64]$Descriptor.manifest_length-lt1-or[string]$Descriptor.manifest_payload_sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[string]$Descriptor.owned_entries_sha256-notmatch'^[0-9A-Fa-f]{64}$'-or-not($Descriptor.custom_profiles_absent-is[bool])-or-not[bool]$Descriptor.custom_profiles_absent-or-not($Descriptor.legacy_mismatches_absent-is[bool])-or-not[bool]$Descriptor.legacy_mismatches_absent){Die "SYNAPSE_PURGE_PROFILES_OWNERSHIP_INVALID context=$Context"}
    if([int]$manifest.schema_version-ne1-or[string]$manifest.owner-cne'synapse-setup:bundled-profiles'-or[System.IO.Path]::GetFullPath([string]$manifest.deployed_profiles_dir)-ine[System.IO.Path]::GetFullPath([string]$ProfilesPlan.path)-or-not[System.IO.Path]::IsPathFullyQualified([string]$manifest.source_profiles_dir)-or[string]$manifest.source_manifest_sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[string]$manifest.generation_identity_semantics-cne'bundled source files plus ownership manifest plus persistent retired quarantine objects; custom profiles and later edits are unowned post-publication deltas'-or@($manifest.preserved_custom_profiles).Count-ne0-or@($manifest.preserved_legacy_retired_hash_mismatches).Count-ne0){Die "SYNAPSE_PURGE_PROFILES_MANIFEST_NOT_EXCLUSIVELY_SETUP_OWNED context=$Context profiles=$($ProfilesPlan.path) custom=$(@($manifest.preserved_custom_profiles).Count) legacy_mismatches=$(@($manifest.preserved_legacy_retired_hash_mismatches).Count)"}
    $payloadSha=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value (ConvertTo-SynapseCanonicalValue -Value $manifest))).ToUpperInvariant()
    if($payloadSha-ine[string]$Descriptor.manifest_payload_sha256){Die "SYNAPSE_PURGE_PROFILES_MANIFEST_PAYLOAD_HASH_INVALID context=$Context expected=$($Descriptor.manifest_payload_sha256) actual=$payloadSha"}
    $actual=New-SynapseCaseInsensitiveMap
    foreach($entry in @($ProfilesPlan.entries)){if($actual.ContainsKey([string]$entry.relative_path)){Die "SYNAPSE_PURGE_PROFILES_PLAN_DUPLICATE context=$Context relative=$($entry.relative_path)"};$actual[[string]$entry.relative_path]=$entry}
    $expected=New-SynapseCaseInsensitiveMap
    $addExpected={param([string]$Relative,[string]$Kind,[string]$Sha,[int64]$Length)
        $safe=Assert-SynapseProfileRelativePathSafe -RelativePath $Relative -Context "${Context}_owned_relative"
        if($expected.ContainsKey($safe)){Die "SYNAPSE_PURGE_PROFILES_OWNERSHIP_DUPLICATE context=$Context relative=$safe"}
        $expected[$safe]=[pscustomobject][ordered]@{kind=$Kind;sha256=$Sha;length=$Length}
    }
    & $addExpected $script:SynapseBundledProfilesManifestFileName 'file' ([string]$Descriptor.manifest_sha256).ToUpperInvariant() ([int64]$Descriptor.manifest_length)
    $files=@($manifest.files)
    if($files.Count-gt512-or[int]$manifest.bundled_file_count-ne$files.Count-or[int]$manifest.bundled_profile_count-ne@($files|Where-Object{[bool]$_.profile_file}).Count){Die "SYNAPSE_PURGE_PROFILES_MANIFEST_COUNT_INVALID context=$Context"}
    foreach($file in $files){Assert-SynapsePurgeExactPropertySet -Value $file -Expected @('relative_path','sha256','length','profile_file') -Context "${Context}_manifest_file";$relative=Assert-SynapseProfileRelativePathSafe -RelativePath ([string]$file.relative_path) -Context "${Context}_manifest_file";if($relative-match'/'-or(Test-SynapseSetupProfileMetadataRelativePath -RelativePath $relative)-or[string]$file.sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[int64]$file.length-lt0-or-not($file.profile_file-is[bool])){Die "SYNAPSE_PURGE_PROFILES_MANIFEST_FILE_INVALID context=$Context relative=$relative"};& $addExpected $relative 'file' ([string]$file.sha256).ToUpperInvariant() ([int64]$file.length)}
    $quarantined=@($manifest.quarantined_retired);if($quarantined.Count-gt512){Die "SYNAPSE_PURGE_PROFILES_QUARANTINE_BOUND_INVALID context=$Context count=$($quarantined.Count)"}
    foreach($record in $quarantined){Assert-SynapsePurgeExactPropertySet -Value $record -Expected @('relative_path','original_path','quarantine_path','sha256','reason') -Context "${Context}_quarantine";$retired=Assert-SynapseProfileRelativePathSafe -RelativePath ([string]$record.relative_path) -Context "${Context}_quarantine_retired";$quarantinePath=[System.IO.Path]::GetFullPath([string]$record.quarantine_path);$relative=Get-SynapseProfileRelativePath -BaseDir ([string]$ProfilesPlan.path) -Path $quarantinePath -Context "${Context}_quarantine_path";$parts=@($relative-split'/');if($parts.Count-ne2-or[string]$parts[0]-notmatch'^\.synapse-retired-bundled-profiles\.retired-deployment-\d{8}T\d{9}Z-\d+$'-or[string]$parts[1]-cne$retired-or[string]$record.sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[string]::IsNullOrWhiteSpace([string]$record.reason)-or-not$actual.ContainsKey($relative)){Die "SYNAPSE_PURGE_PROFILES_QUARANTINE_INVALID context=$Context relative=$relative"};if(-not$expected.ContainsKey([string]$parts[0])){& $addExpected ([string]$parts[0]) 'directory' '' -1L};& $addExpected $relative 'file' ([string]$record.sha256).ToUpperInvariant() ([int64]$actual[$relative].length)}
    if($actual.Count-ne$expected.Count-or[int]$Descriptor.owned_entry_count-ne$expected.Count-or[string]$Descriptor.owned_entries_sha256-ine[string]$ProfilesPlan.tree_sha256){Die "SYNAPSE_PURGE_PROFILES_OWNERSHIP_CARDINALITY_INVALID context=$Context expected=$($expected.Count) actual=$($actual.Count) declared=$($Descriptor.owned_entry_count)"}
    foreach($relative in $expected.Keys){if(-not$actual.ContainsKey($relative)){Die "SYNAPSE_PURGE_PROFILES_OWNED_ENTRY_MISSING context=$Context relative=$relative"};$a=$actual[$relative];$e=$expected[$relative];if([string]$a.kind-cne[string]$e.kind-or([string]$e.kind-ceq'file'-and([string]$a.sha256-ine[string]$e.sha256-or[int64]$a.length-ne[int64]$e.length))){Die "SYNAPSE_PURGE_PROFILES_OWNED_ENTRY_DRIFT context=$Context relative=$relative"}}
    $manifestEntry=$actual[$script:SynapseBundledProfilesManifestFileName]
    if([string]$manifestEntry.file_id_128-ine[string]$Descriptor.manifest_file_id_128){Die "SYNAPSE_PURGE_PROFILES_MANIFEST_FILE_ID_DRIFT context=$Context"}
    return $Descriptor
}

function Get-SynapsePurgeProfilesOwnershipDescriptor {
    param([Parameter(Mandatory=$true)]$ProfilesPlan,[Parameter(Mandatory=$true)]$Generation,[Parameter(Mandatory=$true)][string]$Context)
    if(-not[bool]$ProfilesPlan.exists){Die "SYNAPSE_PURGE_PROFILES_ROOT_MISSING context=$Context path=$($ProfilesPlan.path)"}
    $manifestIdentity=$Generation.Profiles.Manifest;$manifestPath=[System.IO.Path]::GetFullPath([string]$manifestIdentity.path);$profilesPath=Get-SynapseNormalizedDirectoryPath -Path ([string]$ProfilesPlan.path)
    if($manifestPath-ine[System.IO.Path]::GetFullPath((Join-Path $profilesPath $script:SynapseBundledProfilesManifestFileName))-or[string]$manifestIdentity.file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'-or[string]$manifestIdentity.sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[int64]$manifestIdentity.length-lt1){Die "SYNAPSE_PURGE_PROFILES_GENERATION_MANIFEST_INVALID context=$Context path=$manifestPath"}
    $chain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $profilesPath);$read=Read-SynapsePhysicalRelativeUtf8Text -ParentPath $profilesPath -ParentChain $chain -Leaf $script:SynapseBundledProfilesManifestFileName -ExpectedFileId128 ([string]$manifestIdentity.file_id_128) -MaxBytes 1MB
    if([string]$read.Sha256-ine[string]$manifestIdentity.sha256-or[int64]$read.Length-ne[int64]$manifestIdentity.length){Die "SYNAPSE_PURGE_PROFILES_GENERATION_MANIFEST_DRIFT context=$Context path=$manifestPath"}
    $manifest=ConvertFrom-SynapseBundledProfilesManifestText -Text ([string]$read.Content) -ManifestPath $manifestPath
    $canonicalManifest=ConvertTo-SynapseCanonicalValue -Value $manifest
    $descriptor=[ordered]@{schema='synapse_setup_purge_profiles_ownership/v1';manifest_relative_path=$script:SynapseBundledProfilesManifestFileName;manifest_file_id_128=([string]$manifestIdentity.file_id_128).ToUpperInvariant();manifest_sha256=([string]$manifestIdentity.sha256).ToUpperInvariant();manifest_length=[int64]$manifestIdentity.length;manifest_payload=$canonicalManifest;manifest_payload_sha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $canonicalManifest)).ToUpperInvariant();owned_entry_count=@($ProfilesPlan.entries).Count;owned_entries_sha256=([string]$ProfilesPlan.tree_sha256).ToUpperInvariant();custom_profiles_absent=(@($manifest.preserved_custom_profiles).Count-eq0);legacy_mismatches_absent=(@($manifest.preserved_legacy_retired_hash_mismatches).Count-eq0)}
    $roundTrip=(Get-SynapseCanonicalJson -Value $descriptor)|ConvertFrom-Json -ErrorAction Stop
    [void](Assert-SynapsePurgeProfilesOwnershipDescriptor -Descriptor $roundTrip -ProfilesPlan ([pscustomobject]$ProfilesPlan) -Context $Context)
    return $descriptor
}

function Assert-SynapsePurgeFileDescriptor {
    param([Parameter(Mandatory=$true)]$Descriptor,[Parameter(Mandatory=$true)][string]$ExpectedPath,[Parameter(Mandatory=$true)][string]$Context)
    Assert-SynapsePurgeExactPropertySet -Value $Descriptor -Expected @('schema','path','exists','absence','parent','parent_chain','leaf','file_id_128','sha256','length') -Context $Context
    $path=[System.IO.Path]::GetFullPath([string]$Descriptor.path);$expected=[System.IO.Path]::GetFullPath($ExpectedPath)
    if([string]$Descriptor.schema-cne'synapse_setup_purge_file/v1'-or$path-ine$expected-or-not($Descriptor.exists-is[bool])){Die "SYNAPSE_PURGE_FILE_DESCRIPTOR_INVALID context=$Context path=$path expected=$expected"}
    if(-not[bool]$Descriptor.exists){if($null-eq$Descriptor.absence-or-not[string]::IsNullOrEmpty([string]$Descriptor.parent)-or@($Descriptor.parent_chain).Count-ne0-or-not[string]::IsNullOrEmpty([string]$Descriptor.leaf)-or-not[string]::IsNullOrEmpty([string]$Descriptor.file_id_128)-or-not[string]::IsNullOrEmpty([string]$Descriptor.sha256)-or[int64]$Descriptor.length-ne-1L){Die "SYNAPSE_PURGE_ABSENT_FILE_DESCRIPTOR_INVALID context=$Context path=$path"};Assert-SynapsePurgeAbsenceDescriptor -Descriptor $Descriptor.absence -ExpectedPath $expected -ExpectedKind file -Context "${Context}_absence";return}
    $parent=Get-SynapseNormalizedDirectoryPath -Path ([string]$Descriptor.parent);$leaf=[string]$Descriptor.leaf
    if($null-ne$Descriptor.absence-or[System.IO.Path]::GetFullPath((Join-Path $parent $leaf))-ine$path-or$leaf-ne(Split-Path -Leaf $leaf)-or[string]$Descriptor.file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'-or[string]$Descriptor.sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[int64]$Descriptor.length-lt0){Die "SYNAPSE_PURGE_PRESENT_FILE_DESCRIPTOR_INVALID context=$Context path=$path"}
    Assert-SynapsePurgeStoredDirectoryChain -Chain $Descriptor.parent_chain -ExpectedPath $parent -Context "${Context}_parent_chain"
}

function Assert-SynapsePurgeAuthorizedRecord {
    param([Parameter(Mandatory=$true)]$Record,[Parameter(Mandatory=$true)]$PathContract,[switch]$StructuralOnly,[Parameter(Mandatory=$true)][string]$Context)
    $p=$Record.Payload;$names=@($p.PSObject.Properties.Name);$expected=@('schema','state','purge_id','target_contract','target_contract_sha256','record_root_file_id_128','authority','database','profiles','profiles_ownership','token','vault_snapshot','confirmed','authorized_at_utc','authorized_by_pid','authorized_by_user','plan_sha256')
    $computedContractSha=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $p.target_contract)).ToUpperInvariant()
    if($names.Count-ne$expected.Count-or@($names|Where-Object{$expected-cnotcontains$_}).Count-ne0-or[string]$p.schema-cne'synapse_setup_purge_intent/v1'-or[string]$p.state-cne'authorized'-or[string]$p.purge_id-notmatch'^[0-9A-Fa-f]{64}$'-or[string]$Record.Leaf-cne("purge-$($p.purge_id)-authorized.json")-or[string]$p.plan_sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[string]$p.target_contract_sha256-ine$computedContractSha-or[string]$p.target_contract_sha256-ine[string]$PathContract.ContractSha256-or(Get-SynapseCanonicalJson -Value $p.target_contract)-cne(Get-SynapseCanonicalJson -Value $PathContract.Contract)){Die "SYNAPSE_PURGE_AUTHORIZATION_INVALID context=$Context path=$($Record.Path)"}
    Assert-SynapsePurgeExactPropertySet -Value $p.target_contract -Expected @('schema','db_path','profiles_dir','token_path','record_root') -Context "${Context}_target_contract"
    if([string]$p.target_contract.schema-cne'synapse_setup_purge_target_contract/v1'-or[System.IO.Path]::GetFullPath([string]$p.target_contract.db_path)-ine[string]$PathContract.DbPath-or[System.IO.Path]::GetFullPath([string]$p.target_contract.profiles_dir)-ine[string]$PathContract.ProfilesDir-or[System.IO.Path]::GetFullPath([string]$p.target_contract.token_path)-ine[string]$PathContract.TokenPath-or[System.IO.Path]::GetFullPath([string]$p.target_contract.record_root)-ine[string]$PathContract.RecordRoot){Die "SYNAPSE_PURGE_TARGET_CONTRACT_INVALID context=$Context"}
    $recordRootChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path ([string]$PathContract.RecordRoot));if([string]$p.record_root_file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'-or[string]$p.record_root_file_id_128-ine[string]$recordRootChain[-1].file_id_128){Die "SYNAPSE_PURGE_RECORD_ROOT_IDENTITY_INVALID context=$Context record_root=$($PathContract.RecordRoot)"}
    $core=ConvertTo-SynapseCanonicalValue -Value $p;[void]$core.Remove('plan_sha256');$actual=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $core)).ToUpperInvariant();if($actual-ine[string]$p.plan_sha256){Die "SYNAPSE_PURGE_PLAN_HASH_INVALID context=$Context expected=$($p.plan_sha256) actual=$actual"}
    Assert-SynapsePurgeDirectoryDescriptor -Descriptor $p.database -ExpectedPath $PathContract.DbPath -Context "${Context}_database"
    Assert-SynapsePurgeDirectoryDescriptor -Descriptor $p.profiles -ExpectedPath $PathContract.ProfilesDir -Context "${Context}_profiles"
    [void](Assert-SynapsePurgeProfilesOwnershipDescriptor -Descriptor $p.profiles_ownership -ProfilesPlan $p.profiles -Context "${Context}_profiles_ownership")
    Assert-SynapsePurgeFileDescriptor -Descriptor $p.token -ExpectedPath $PathContract.TokenPath -Context "${Context}_token"
    Assert-SynapsePurgeExactPropertySet -Value $p.authority -Expected @('schema','broker_identity_sha256','task_capability_sha256','authority_epoch','generation_id','task','task_receipt','runtime_bin_dir','bind','db_path','active_control_gate','active_roster') -Context "${Context}_authority"
    if([string]$p.authority.schema-cne'synapse_setup_purge_authority/v1'-or[string]$p.authority.broker_identity_sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[string]$p.authority.task_capability_sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[int64]$p.authority.authority_epoch-lt1-or[string]$p.authority.generation_id-notmatch'^(prior|candidate)-[0-9a-f]{40}$'-or-not[System.IO.Path]::IsPathFullyQualified([string]$p.authority.runtime_bin_dir)-or[string]::IsNullOrWhiteSpace([string]$p.authority.bind)-or[System.IO.Path]::GetFullPath([string]$p.authority.db_path)-ine[string]$PathContract.DbPath){Die "SYNAPSE_PURGE_AUTHORITY_DESCRIPTOR_INVALID context=$Context"}
    [void](Assert-SynapseBrokerTaskDescriptorShape -Descriptor $p.authority.task -BrokerIdentitySha256 ([string]$p.authority.broker_identity_sha256) -TaskCapabilitySha256 ([string]$p.authority.task_capability_sha256) -Context "${Context}_broker_task")
    $authorityRoot=Get-SynapseNormalizedDirectoryPath -Path (Join-Path ([string]$p.authority.runtime_bin_dir) $script:SynapseAuthorityRootLeaf)
    $receipt=Assert-SynapseBrokerTaskReceiptDescriptor -Descriptor $p.authority.task_receipt -ExpectedAuthorityRoot $authorityRoot -ExpectedBrokerIdentitySha256 ([string]$p.authority.broker_identity_sha256) -ExpectedTaskName ([string]$p.authority.task.name) -StructuralOnly:$StructuralOnly
    if([string]$receipt.TaskCapabilitySha256-ine[string]$p.authority.task_capability_sha256){Die "SYNAPSE_PURGE_TASK_RECEIPT_CAPABILITY_DRIFT context=$Context task=$($p.authority.task.name)"}
    foreach($identity in @($p.authority.active_control_gate,$p.authority.active_roster)){Assert-SynapsePurgeExactPropertySet -Value $identity -Expected @('path','file_id_128','sha256','length') -Context "${Context}_active_control";if(-not[System.IO.Path]::IsPathFullyQualified([string]$identity.path)-or[string]$identity.file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'-or[string]$identity.sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[int64]$identity.length-lt1){Die "SYNAPSE_PURGE_AUTHORIZATION_ACTIVE_CONTROL_INVALID context=$Context"}}
    if(-not($p.confirmed-is[bool])-or[int]$p.authorized_by_pid-lt1-or[string]::IsNullOrWhiteSpace([string]$p.authorized_by_user)){Die "SYNAPSE_PURGE_AUTHORIZATION_METADATA_INVALID context=$Context"};$time=[DateTime]::MinValue;if(-not[DateTime]::TryParse([string]$p.authorized_at_utc,[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::RoundtripKind,[ref]$time)){Die "SYNAPSE_PURGE_AUTHORIZATION_TIME_INVALID context=$Context"}
    if([string]$p.vault_snapshot.schema-cne'synapse_calyx_physical_snapshot/v2'-or[System.IO.Path]::GetFullPath([string]$p.vault_snapshot.path)-ine[string]$PathContract.DbPath-or-not($p.vault_snapshot.bytes_complete-is[bool])-or-not[bool]$p.vault_snapshot.bytes_complete-or-not[string]::IsNullOrWhiteSpace([string]$p.vault_snapshot.error)-or-not[string]::IsNullOrWhiteSpace([string]$p.vault_snapshot.current_manifest_error)){Die "SYNAPSE_PURGE_AUTHORIZATION_VAULT_INVALID context=$Context"}
    $seed=[ordered]@{target_contract_sha256=([string]$p.target_contract_sha256).ToUpperInvariant();record_root_file_id_128=([string]$p.record_root_file_id_128).ToUpperInvariant();broker_identity_sha256=([string]$p.authority.broker_identity_sha256).ToUpperInvariant();task_capability_sha256=([string]$p.authority.task_capability_sha256).ToUpperInvariant();task_name=[string]$p.authority.task.name;authority_epoch=[int64]$p.authority.authority_epoch;generation_id=[string]$p.authority.generation_id;token_file_id_128=[string]$p.token.file_id_128;database_root_file_id_128=[string]$p.database.root_file_id_128;profiles_root_file_id_128=[string]$p.profiles.root_file_id_128};$purgeId=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $seed)).ToUpperInvariant();if($purgeId-ine[string]$p.purge_id){Die "SYNAPSE_PURGE_ID_INVALID context=$Context expected=$($p.purge_id) actual=$purgeId"}
    return $p
}

function New-SynapsePurgeAuthorizedRecord {
    param([Parameter(Mandatory=$true)]$PathContract,[Parameter(Mandatory=$true)]$Authority,[switch]$Confirmed)
    if($null-eq$Authority.CurrentGeneration){Die 'SYNAPSE_PURGE_CURRENT_GENERATION_REQUIRED remediation=start or repair the exact committed generation before authorizing a new destructive purge'}
    $generation=$Authority.CurrentGeneration;$rp=$generation.RosterPayload
    if([System.IO.Path]::GetFullPath([string]$rp.db_path)-ine[string]$PathContract.DbPath-or[System.IO.Path]::GetFullPath([string]$rp.profiles_dir)-ine[string]$PathContract.ProfilesDir-or[System.IO.Path]::GetFullPath([string]$rp.token_path)-ine[string]$PathContract.TokenPath){Die 'SYNAPSE_PURGE_CURRENT_GENERATION_PATH_MISMATCH'}
    $tokens=@($generation.GenerationObjects|Where-Object{[string]$_.role-ceq'bearer_token'});if($tokens.Count-ne1){Die "SYNAPSE_PURGE_GENERATION_TOKEN_AMBIGUOUS count=$($tokens.Count)"}
    $database=Get-SynapsePurgeDirectorySnapshot -Path $PathContract.DbPath -Context 'purge_authorize_database';$profiles=Get-SynapsePurgeDirectorySnapshot -Path $PathContract.ProfilesDir -Context 'purge_authorize_profiles';$token=Get-SynapsePurgeFileSnapshot -Path $PathContract.TokenPath -Context 'purge_authorize_token'
    if(-not[bool]$token.exists-or[string]$token.file_id_128-ine[string]$tokens[0].file_id_128-or[string]$token.sha256-ine[string]$tokens[0].sha256-or[int64]$token.length-ne[int64]$tokens[0].length){Die 'SYNAPSE_PURGE_GENERATION_TOKEN_IDENTITY_MISMATCH'}
    if(-not[bool]$profiles.exists-or[string]$profiles.root_file_id_128-ine[string]$generation.Profiles.RootFileId128){Die 'SYNAPSE_PURGE_GENERATION_PROFILES_ROOT_MISMATCH'}
    $profilesOwnership=Get-SynapsePurgeProfilesOwnershipDescriptor -ProfilesPlan ([pscustomobject]$profiles) -Generation $generation -Context 'purge_authorize_profiles_ownership'
    $vault=Get-SynapseCalyxPhysicalSnapshot -Path $PathContract.DbPath
    if(-not[string]::IsNullOrWhiteSpace([string]$vault.error)-or-not[string]::IsNullOrWhiteSpace([string]$vault.current_manifest_error)-or-not[bool]$vault.bytes_complete){Die "SYNAPSE_PURGE_VAULT_SNAPSHOT_INCOMPLETE error=$($vault.error) manifest_error=$($vault.current_manifest_error) bytes_complete=$($vault.bytes_complete)"}
    $durable=if($null-eq$vault.current_manifest_durable_seq){0L}else{[int64]$vault.current_manifest_durable_seq};$populated=($durable-gt0-or[int]$vault.cf_file_count-gt0-or[int]$vault.manifest_file_count-gt1-or[int]$vault.wal_segment_count-gt0-or[int64]$vault.wal_bytes-gt0-or@($database.entries).Count-gt0)
    if($populated-and-not$Confirmed){Die "SYNAPSE_SETUP_VAULT_PURGE_REFUSED vault_dir=$($PathContract.DbPath) durable_seq=$durable manifest_files=$($vault.manifest_file_count) cf_files=$($vault.cf_file_count) remediation=take a backup, then rerun with -ConfirmVaultDestruction"}
    $taskDescriptor=ConvertTo-SynapseAuthorityTaskDescriptor -Task $Authority.BrokerTask
    [void](Assert-SynapseBrokerTaskDescriptorAuthorityCrossbind -Descriptor $taskDescriptor -BrokerIdentitySha256 ([string]$Authority.Infrastructure.BrokerIdentitySha256) -TaskCapabilitySha256 ([string]$Authority.Infrastructure.TaskCapabilitySha256) -Infrastructure $Authority.Infrastructure -Context 'purge_authorize_broker_task')
    $taskReceipt=ConvertTo-SynapseBrokerTaskReceiptDescriptor -Infrastructure $Authority.Infrastructure
    $validatedTaskReceipt=Assert-SynapseBrokerTaskReceiptDescriptor -Descriptor ([pscustomobject]$taskReceipt) -ExpectedAuthorityRoot ([string]$Authority.Layout.Root) -ExpectedBrokerIdentitySha256 ([string]$Authority.Infrastructure.BrokerIdentitySha256) -ExpectedTaskName ([string]$Authority.Infrastructure.TaskName)
    if([string]$validatedTaskReceipt.TaskCapabilitySha256-ine[string]$Authority.Infrastructure.TaskCapabilitySha256){Die 'SYNAPSE_PURGE_TASK_RECEIPT_CAPABILITY_MISMATCH'}
    $authorityDescriptor=[ordered]@{schema='synapse_setup_purge_authority/v1';broker_identity_sha256=([string]$Authority.Infrastructure.BrokerIdentitySha256).ToUpperInvariant();task_capability_sha256=([string]$Authority.Infrastructure.TaskCapabilitySha256).ToUpperInvariant();authority_epoch=[int64]$Authority.AuthorityEpoch;generation_id=[string]$generation.GenerationId;task=$taskDescriptor;task_receipt=$taskReceipt;runtime_bin_dir=[string]$Authority.Layout.RuntimeBinDir;bind=[string]$rp.bind;db_path=[System.IO.Path]::GetFullPath([string]$rp.db_path);active_control_gate=(ConvertTo-SynapseAuthorityIdentityDescriptor -Identity $Authority.ActiveControlGate);active_roster=(ConvertTo-SynapseAuthorityIdentityDescriptor -Identity $Authority.ActiveRoster)}
    $rootChain=@(Ensure-SynapsePhysicalDirectoryPath -Path $PathContract.RecordRoot -Context 'purge_record_root');$recordRootFileId=([string]$rootChain[-1].file_id_128).ToUpperInvariant()
    $seed=[ordered]@{target_contract_sha256=[string]$PathContract.ContractSha256;record_root_file_id_128=$recordRootFileId;broker_identity_sha256=[string]$authorityDescriptor.broker_identity_sha256;task_capability_sha256=[string]$authorityDescriptor.task_capability_sha256;task_name=[string]$authorityDescriptor.task.name;authority_epoch=[int64]$authorityDescriptor.authority_epoch;generation_id=[string]$authorityDescriptor.generation_id;token_file_id_128=[string]$token.file_id_128;database_root_file_id_128=[string]$database.root_file_id_128;profiles_root_file_id_128=[string]$profiles.root_file_id_128}
    $purgeId=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $seed)).ToUpperInvariant();$leaf="purge-$purgeId-authorized.json"
    $existingState=Get-SynapsePhysicalRelativeState -ParentPath $PathContract.RecordRoot -ParentChain $rootChain -Leaf $leaf
    if([bool]$existingState.Exists){$existing=Open-SynapsePurgeRecordExact -RecordRoot $PathContract.RecordRoot -RecordRootChain $rootChain -Leaf $leaf -Context 'purge_authorization_existing';[void](Assert-SynapsePurgeAuthorizedRecord -Record $existing -PathContract $PathContract -Context 'purge_authorization_existing');return $existing}
    $record=[ordered]@{schema='synapse_setup_purge_intent/v1';state='authorized';purge_id=$purgeId;target_contract=$PathContract.Contract;target_contract_sha256=[string]$PathContract.ContractSha256;record_root_file_id_128=$recordRootFileId;authority=$authorityDescriptor;database=$database;profiles=$profiles;profiles_ownership=$profilesOwnership;token=$token;vault_snapshot=$vault;confirmed=[bool]$Confirmed;authorized_at_utc=[DateTime]::UtcNow.ToString('o');authorized_by_pid=$PID;authorized_by_user="$env:USERDOMAIN\$env:USERNAME"}
    $record.plan_sha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $record)).ToUpperInvariant();$content=(Get-SynapseCanonicalJson -Value $record)+"`n"
    if([System.Text.UTF8Encoding]::new($false,$true).GetByteCount($content)-gt16777216){Die 'SYNAPSE_PURGE_AUTHORIZATION_TOO_LARGE max_bytes=16777216'}
    Ensure-SynapseAtomicFileType;$rootIdentity=[SynapseSetup.AtomicFileV2]::GetPhysicalDirectoryIdentity([string]$PathContract.RecordRoot);[void](Write-SynapseAtomicUtf8TextFileUnderPhysicalRoot -Root $PathContract.RecordRoot -ExpectedRootIdentity $rootIdentity -LeafName $leaf -Content $content -Purpose 'purge_authorization')
    $opened=Open-SynapsePurgeRecordExact -RecordRoot $PathContract.RecordRoot -RecordRootChain $rootChain -Leaf $leaf -Context 'purge_authorization_readback';[void](Assert-SynapsePurgeAuthorizedRecord -Record $opened -PathContract $PathContract -Context 'purge_authorization_readback');return $opened
}

function Assert-SynapsePurgeConfirmationRecord {
    param([Parameter(Mandatory=$true)]$Record,[Parameter(Mandatory=$true)]$Authorized,[Parameter(Mandatory=$true)][string]$Context)
    $p=$Record.Payload;Assert-SynapsePurgeExactPropertySet -Value $p -Expected @('schema','state','purge_id','authorization','confirmed','confirmed_at_utc','confirmed_by_pid','confirmed_by_user','confirmation_sha256') -Context $Context
    if([string]$p.schema-cne'synapse_setup_purge_confirmation/v1'-or[string]$p.state-cne'confirmed'-or[string]$p.purge_id-ine[string]$Authorized.Payload.purge_id-or[string]$Record.Leaf-cne("purge-$($p.purge_id)-confirmation.json")-or-not($p.confirmed-is[bool])-or-not[bool]$p.confirmed-or[int]$p.confirmed_by_pid-lt1-or[string]::IsNullOrWhiteSpace([string]$p.confirmed_by_user)-or[string]$p.confirmation_sha256-notmatch'^[0-9A-Fa-f]{64}$'){Die "SYNAPSE_PURGE_CONFIRMATION_INVALID context=$Context path=$($Record.Path)"}
    $a=$p.authorization;Assert-SynapsePurgeExactPropertySet -Value $a -Expected @('leaf','file_id_128','sha256','length','plan_sha256') -Context "${Context}_authorization"
    if([string]$a.leaf-cne[string]$Authorized.Leaf-or[string]$a.file_id_128-ine[string]$Authorized.State.FileId128-or[string]$a.sha256-ine[string]$Authorized.State.Sha256-or[int64]$a.length-ne[int64]$Authorized.State.Length-or[string]$a.plan_sha256-ine[string]$Authorized.Payload.plan_sha256){Die "SYNAPSE_PURGE_CONFIRMATION_AUTHORIZATION_DRIFT context=$Context"}
    $time=[DateTime]::MinValue;if(-not[DateTime]::TryParse([string]$p.confirmed_at_utc,[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::RoundtripKind,[ref]$time)){Die "SYNAPSE_PURGE_CONFIRMATION_TIME_INVALID context=$Context"}
    $core=ConvertTo-SynapseCanonicalValue -Value $p;[void]$core.Remove('confirmation_sha256');$actual=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $core)).ToUpperInvariant();if($actual-ine[string]$p.confirmation_sha256){Die "SYNAPSE_PURGE_CONFIRMATION_HASH_INVALID context=$Context expected=$($p.confirmation_sha256) actual=$actual"}
    return $p
}

function New-SynapsePurgeConfirmationRecord {
    param([Parameter(Mandatory=$true)]$Authorized,[Parameter(Mandatory=$true)]$PathContract)
    $Authorized.Lease.RequireExact('purge_confirmation_authorization_before');$rootChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $PathContract.RecordRoot);$leaf="purge-$($Authorized.Payload.purge_id)-confirmation.json";$state=Get-SynapsePhysicalRelativeState -ParentPath $PathContract.RecordRoot -ParentChain $rootChain -Leaf $leaf
    if(-not[bool]$state.Exists){$record=[ordered]@{schema='synapse_setup_purge_confirmation/v1';state='confirmed';purge_id=[string]$Authorized.Payload.purge_id;authorization=[ordered]@{leaf=[string]$Authorized.Leaf;file_id_128=([string]$Authorized.State.FileId128).ToUpperInvariant();sha256=([string]$Authorized.State.Sha256).ToUpperInvariant();length=[int64]$Authorized.State.Length;plan_sha256=([string]$Authorized.Payload.plan_sha256).ToUpperInvariant()};confirmed=$true;confirmed_at_utc=[DateTime]::UtcNow.ToString('o');confirmed_by_pid=$PID;confirmed_by_user="$env:USERDOMAIN\$env:USERNAME"};$record.confirmation_sha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $record)).ToUpperInvariant();Ensure-SynapseAtomicFileType;$rootIdentity=[SynapseSetup.AtomicFileV2]::GetPhysicalDirectoryIdentity([string]$PathContract.RecordRoot);[void](Write-SynapseAtomicUtf8TextFileUnderPhysicalRoot -Root $PathContract.RecordRoot -ExpectedRootIdentity $rootIdentity -LeafName $leaf -Content ((Get-SynapseCanonicalJson -Value $record)+"`n") -Purpose 'purge_confirmation')}
    $opened=Open-SynapsePurgeRecordExact -RecordRoot $PathContract.RecordRoot -RecordRootChain $rootChain -Leaf $leaf -Context 'purge_confirmation_readback';[void](Assert-SynapsePurgeConfirmationRecord -Record $opened -Authorized $Authorized -Context 'purge_confirmation_readback');$Authorized.Lease.RequireExact('purge_confirmation_authorization_after');return $opened
}

