    if($null-eq$Confirmation){if($null-ne$p.confirmation){Die "SYNAPSE_PURGE_READY_UNEXPECTED_CONFIRMATION context=$Context"}}else{[void](Assert-SynapsePurgeConfirmationRecord -Record $Confirmation -Authorized $Authorized -Context "${Context}_confirmation");$c=$p.confirmation;Assert-SynapsePurgeExactPropertySet -Value $c -Expected @('leaf','file_id_128','sha256','length','confirmation_sha256') -Context "${Context}_confirmation_ref";if([string]$c.leaf-cne[string]$Confirmation.Leaf-or[string]$c.file_id_128-ine[string]$Confirmation.State.FileId128-or[string]$c.sha256-ine[string]$Confirmation.State.Sha256-or[int64]$c.length-ne[int64]$Confirmation.State.Length-or[string]$c.confirmation_sha256-ine[string]$Confirmation.Payload.confirmation_sha256){Die "SYNAPSE_PURGE_READY_CONFIRMATION_DRIFT context=$Context"}}
    $expectedConfirmed=([bool]$Authorized.Payload.confirmed-or$null-ne$Confirmation);if([bool]$p.destruction_confirmed-ne$expectedConfirmed){Die "SYNAPSE_PURGE_READY_CONFIRMATION_STATE_INVALID context=$Context"}
