    if([System.IO.Path]::GetFullPath([string]$p.parked_control_gate.path)-ine[System.IO.Path]::GetFullPath([string]$Authorized.Payload.authority.active_control_gate.path)-or[System.IO.Path]::GetFullPath([string]$p.parked_roster.path)-ine[System.IO.Path]::GetFullPath([string]$Authorized.Payload.authority.active_roster.path)){Die "SYNAPSE_PURGE_READY_CONTROL_PATH_DRIFT context=$Context"}
    if((Get-SynapseCanonicalJson -Value $p.broker_task)-cne(Get-SynapseCanonicalJson -Value $Authorized.Payload.authority.task)){Die "SYNAPSE_PURGE_READY_BROKER_TASK_DRIFT context=$Context"};[void](Assert-SynapseBrokerTaskDescriptorShape -Descriptor $p.broker_task -BrokerIdentitySha256 ([string]$Authorized.Payload.authority.broker_identity_sha256) -TaskCapabilitySha256 ([string]$Authorized.Payload.authority.task_capability_sha256) -Context "${Context}_broker_task")
