    Assert-SynapsePurgeDirectoryDescriptor -Descriptor $p.database -ExpectedPath ([string]$Authorized.Payload.target_contract.db_path) -Context "${Context}_database";Assert-SynapsePurgeDirectoryDescriptor -Descriptor $p.profiles -ExpectedPath ([string]$Authorized.Payload.target_contract.profiles_dir) -Context "${Context}_profiles";[void](Assert-SynapsePurgeProfilesOwnershipDescriptor -Descriptor $p.profiles_ownership -ProfilesPlan $p.profiles -Context "${Context}_profiles_ownership");Assert-SynapsePurgeFileDescriptor -Descriptor $p.token -ExpectedPath ([string]$Authorized.Payload.target_contract.token_path) -Context "${Context}_token"
    foreach($pair in @([pscustomobject]@{Current=$p.database;Original=$Authorized.Payload.database;Role='database'},[pscustomobject]@{Current=$p.profiles;Original=$Authorized.Payload.profiles;Role='profiles'})){if([bool]$pair.Current.exists-ne[bool]$pair.Original.exists-or([bool]$pair.Current.exists-and[string]$pair.Current.root_file_id_128-ine[string]$pair.Original.root_file_id_128)){Die "SYNAPSE_PURGE_READY_ROOT_DRIFT context=$Context role=$($pair.Role)"}}
    if((Get-SynapseCanonicalJson -Value $p.token)-cne(Get-SynapseCanonicalJson -Value $Authorized.Payload.token)){Die "SYNAPSE_PURGE_READY_TOKEN_DRIFT context=$Context"}
