    $deleteCore=[ordered]@{database=$p.database;profiles=$p.profiles;profiles_ownership=$p.profiles_ownership;token=$p.token;vault_snapshot=$p.vault_snapshot;destruction_confirmed=[bool]$p.destruction_confirmed};$deleteSha=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $deleteCore)).ToUpperInvariant();if([string]$p.deletion_plan_sha256-ine$deleteSha){Die "SYNAPSE_PURGE_READY_PLAN_HASH_INVALID context=$Context expected=$($p.deletion_plan_sha256) actual=$deleteSha"}
    return $p
}

function Assert-SynapsePurgeCompletedRecord {
    param([Parameter(Mandatory=$true)]$Record,[Parameter(Mandatory=$true)]$Authorized,[AllowNull()]$Confirmation,[Parameter(Mandatory=$true)]$Ready,[Parameter(Mandatory=$true)]$PathContract,[switch]$RequirePhysicalAbsence,[Parameter(Mandatory=$true)][string]$Context)
    [void](Assert-SynapsePurgeReadyRecord -Record $Ready -Authorized $Authorized -Confirmation $Confirmation -Context "${Context}_ready")
    $p=$Record.Payload;Assert-SynapsePurgeExactPropertySet -Value $p -Expected @('schema','state','purge_id','authorization_leaf','authorization_file_id_128','authorization_sha256','authorization_length','ready_leaf','ready_file_id_128','ready_sha256','ready_length','deletion_plan_sha256','database_absent','profiles_absent','token_absent','completed_at_utc') -Context $Context
    if([string]$p.schema-cne'synapse_setup_purge_completed/v2'-or[string]$p.state-cne'completed'-or[string]$p.purge_id-ine[string]$Authorized.Payload.purge_id-or[string]$Record.Leaf-cne("purge-$($p.purge_id)-completed.json")-or[string]$p.authorization_leaf-cne[string]$Authorized.Leaf-or[string]$p.authorization_file_id_128-ine[string]$Authorized.State.FileId128-or[string]$p.authorization_sha256-ine[string]$Authorized.State.Sha256-or[int64]$p.authorization_length-ne[int64]$Authorized.State.Length-or[string]$p.ready_leaf-cne[string]$Ready.Leaf-or[string]$p.ready_file_id_128-ine[string]$Ready.State.FileId128-or[string]$p.ready_sha256-ine[string]$Ready.State.Sha256-or[int64]$p.ready_length-ne[int64]$Ready.State.Length-or[string]$p.deletion_plan_sha256-ine[string]$Ready.Payload.deletion_plan_sha256-or-not($p.database_absent-is[bool])-or-not[bool]$p.database_absent-or-not($p.profiles_absent-is[bool])-or-not[bool]$p.profiles_absent-or-not($p.token_absent-is[bool])-or-not[bool]$p.token_absent){Die "SYNAPSE_PURGE_COMPLETION_INVALID context=$Context path=$($Record.Path)"}
    $time=[DateTime]::MinValue;if(-not[DateTime]::TryParse([string]$p.completed_at_utc,[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::RoundtripKind,[ref]$time)){Die "SYNAPSE_PURGE_COMPLETION_TIME_INVALID context=$Context"}
    if($RequirePhysicalAbsence){
        foreach($directoryPlan in @($Ready.Payload.database,$Ready.Payload.profiles)){
            if([bool]$directoryPlan.exists){
                $parent=[string]$directoryPlan.root_parent;$parentBoundary=Get-SynapsePurgePhysicalDirectoryBoundary -Path $parent -Context "${Context}_old_directory_parent"
                if([bool]$parentBoundary.Exists){$state=Get-SynapsePhysicalRelativeState -ParentPath $parent -ParentChain $parentBoundary.Chain -Leaf ([string]$directoryPlan.root_leaf) -Directory;if([bool]$state.Exists-and[string]$state.FileId128-ieq[string]$directoryPlan.root_file_id_128){Die "SYNAPSE_PURGE_COMPLETION_OLD_DIRECTORY_IDENTITY_PRESENT context=$Context path=$($directoryPlan.path) file_id_128=$($state.FileId128)"}}
            }
        }
        $tokenPlan=$Ready.Payload.token
        if([bool]$tokenPlan.exists){$parentBoundary=Get-SynapsePurgePhysicalDirectoryBoundary -Path ([string]$tokenPlan.parent) -Context "${Context}_old_token_parent";if([bool]$parentBoundary.Exists){$state=Get-SynapsePhysicalRelativeState -ParentPath ([string]$tokenPlan.parent) -ParentChain $parentBoundary.Chain -Leaf ([string]$tokenPlan.leaf);if([bool]$state.Exists-and[string]$state.FileId128-ieq[string]$tokenPlan.file_id_128){Die "SYNAPSE_PURGE_COMPLETION_OLD_TOKEN_IDENTITY_PRESENT context=$Context path=$($tokenPlan.path) file_id_128=$($state.FileId128)"}}}
        $db=Get-SynapsePurgeDirectorySnapshot -Path $PathContract.DbPath -Context "${Context}_database_absence";$profiles=Get-SynapsePurgeDirectorySnapshot -Path $PathContract.ProfilesDir -Context "${Context}_profiles_absence";$token=Get-SynapsePurgeFileSnapshot -Path $PathContract.TokenPath -Context "${Context}_token_absence";if([bool]$db.exists-or[bool]$profiles.exists-or[bool]$token.exists){Die "SYNAPSE_PURGE_COMPLETION_PHYSICAL_STATE_INVALID context=$Context database_exists=$($db.exists) profiles_exists=$($profiles.exists) token_exists=$($token.exists)"}
    }
    return $p
}

function Assert-SynapsePurgeOperatorStopAuthorizationPreimage {
    param(
        [Parameter(Mandatory=$true)]$Record,
        [Parameter(Mandatory=$true)]$Authorized,
        [Parameter(Mandatory=$true)][string]$Context
    )
    if($null-eq$Record-or$null-eq$Record.Journal-or[string]$Record.Journal.State-notin@('armed','candidate_ready','rolled_back','cleanup_ready')){Die "SYNAPSE_PURGE_OPERATOR_STOP_RECORD_INVALID context=$Context state=$($Record.Journal.State)"}
    if($null-ne$Record.Journal.TornTail-and([int]$Record.Journal.TornTail.Sequence-ne([int]$Record.Journal.Sequence+1)-or[string]$Record.Journal.State-notin@('armed','candidate_ready','rolled_back'))){Die "SYNAPSE_PURGE_OPERATOR_STOP_TORN_CUT_INVALID context=$Context state=$($Record.Journal.State) valid_sequence=$($Record.Journal.Sequence) torn_sequence=$($Record.Journal.TornTail.Sequence)"}
    $expected=[string]$Authorized.Payload.authority.generation_id
    if([string]$Record.Journal.Initial.generation_id-cne$expected-or[string]$Record.Validated.GenerationId-cne$expected){Die "SYNAPSE_PURGE_OPERATOR_STOP_GENERATION_DRIFT context=$Context expected=$expected actual=$($Record.Journal.Initial.generation_id)"}
    foreach($check in @(
        [pscustomobject]@{Actual=$Record.Validated.CurrentControlGate;Expected=$Authorized.Payload.authority.active_control_gate;Role='active_gate'},
        [pscustomobject]@{Actual=$Record.Validated.CurrentRoster;Expected=$Authorized.Payload.authority.active_roster;Role='active_roster'})){
        if([System.IO.Path]::GetFullPath([string]$check.Actual.Path)-ine[System.IO.Path]::GetFullPath([string]$check.Expected.path)-or[string]$check.Actual.FileId128-ine[string]$check.Expected.file_id_128-or[string]$check.Actual.Sha256-ine[string]$check.Expected.sha256-or[int64]$check.Actual.Length-ne[int64]$check.Expected.length){Die "SYNAPSE_PURGE_OPERATOR_STOP_PREIMAGE_DRIFT context=$Context role=$($check.Role)"}
    }
    $Authorized.Lease.RequireExact("${Context}_authorization")
    return $Record
}

function Assert-SynapsePurgeOperatorStopProvenance {
    param(
        [Parameter(Mandatory=$true)]$Record,
        [Parameter(Mandatory=$true)]$Authorized,
        [Parameter(Mandatory=$true)]$Authority,
        [Parameter(Mandatory=$true)][string]$Context
    )
    [void](Assert-SynapsePurgeOperatorStopAuthorizationPreimage -Record $Record -Authorized $Authorized -Context "${Context}_preimage")
    $cleanCandidate=([string]$Record.Journal.State-ceq'candidate_ready'-and$null-eq$Record.Journal.TornTail)
    $physicalCandidate=($null-ne$Record.Journal.TornTail-and[string]$Record.Journal.State-in@('armed','candidate_ready')-and[int]$Record.Journal.TornTail.Sequence-eq([int]$Record.Journal.Sequence+1))
    if(-not$cleanCandidate-and-not$physicalCandidate){Die "SYNAPSE_PURGE_OPERATOR_STOP_NOT_READY context=$Context state=$($Record.Journal.State) torn=$($null-ne$Record.Journal.TornTail)"}
    $pair=$null
    try{
        $pair=Read-SynapseAuthorityActiveControlPair -Layout $Authority.Layout -ExpectedState parked -Context "${Context}_parked_pair"
        foreach($check in @(
            [pscustomobject]@{Actual=$pair.Gate;Transition=$Record.Validated.GateTransition;Role='parked_gate'},
            [pscustomobject]@{Actual=$pair.Roster;Transition=$Record.Validated.RosterTransition;Role='parked_roster'})){
            if([string]$check.Actual.FileId128-ine[string]$check.Transition.post_file_id_128-or[string]$check.Actual.Sha256-ine[string]$check.Transition.post_sha256-or[int64]$check.Actual.Length-ne[int64]$check.Transition.post_length){Die "SYNAPSE_PURGE_OPERATOR_STOP_POSTIMAGE_DRIFT context=$Context role=$($check.Role)"}
        }
        [void](Assert-SynapsePurgeStrictNoLiveAuthority -Bind ([string]$Authorized.Payload.authority.bind) -DbPath ([string]$Authorized.Payload.authority.db_path) -Context "${Context}_strict_no_live")
        $Authorized.Lease.RequireExact("${Context}_authorization")
        return $Record
    }finally{Close-SynapseAuthorityActiveControlPair -Pair $pair}
}

function Complete-SynapsePurgeTornOperatorStopToParked {
    param(
        [Parameter(Mandatory=$true)]$Record,
        [Parameter(Mandatory=$true)]$Authorized,
        [Parameter(Mandatory=$true)]$Authority,
        [Parameter(Mandatory=$true)][string]$Context
    )
    [void](Assert-SynapsePurgeOperatorStopAuthorizationPreimage -Record $Record -Authorized $Authorized -Context "${Context}_preimage")
    if($null-eq$Record.Journal.TornTail-or[string]$Record.Journal.State-notin@('armed','candidate_ready')){Die "SYNAPSE_PURGE_OPERATOR_TORN_FORWARD_CUT_INVALID context=$Context state=$($Record.Journal.State)"}
    [void](Invoke-SynapseAuthorityControlTransition -Transition $Record.Validated.GateTransition -AllocationContext $Record.Journal.Allocation)
    [void](Invoke-SynapseAuthorityControlTransition -Transition $Record.Validated.RosterTransition -AllocationContext $Record.Journal.Allocation)
    [void](Assert-SynapsePurgeOperatorStopProvenance -Record $Record -Authorized $Authorized -Authority $Authority -Context "${Context}_parked")
    $Authorized.Lease.RequireExact("${Context}_authorization")
    return $Record
}

function Assert-SynapsePurgeOperatorStopCleanupDescriptor {
    param(
        [Parameter(Mandatory=$true)]$Descriptor,
        [Parameter(Mandatory=$true)]$Authorized,
        [Parameter(Mandatory=$true)][string]$Context
    )
    Assert-SynapsePurgeExactPropertySet -Value $Descriptor -Expected @('schema','root','parent','parent_chain','root_leaf','root_file_id_128','static_transaction_sha256','broker_identity_sha256','authority_epoch','generation_id','entries','entries_sha256') -Context $Context
    $root=Get-SynapseNormalizedDirectoryPath -Path ([string]$Descriptor.root);$parent=Get-SynapseNormalizedDirectoryPath -Path ([string]$Descriptor.parent);$leaf=[string]$Descriptor.root_leaf
    $expectedParent=Get-SynapseNormalizedDirectoryPath -Path (Join-Path (Join-Path ([string]$Authorized.Payload.authority.runtime_bin_dir) $script:SynapseAuthorityRootLeaf) 'operations')
    if([string]$Descriptor.schema-cne'synapse_setup_purge_operator_cleanup/v1'-or
        [System.IO.Path]::GetFullPath((Join-Path $parent $leaf))-ine$root-or
        $parent-ine$expectedParent-or
        $leaf-ne(Split-Path -Leaf $leaf)-or
        $leaf-notmatch'^deployment-\d{8}T\d{9}Z-\d+$'-or
        [string]$Descriptor.root_file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'-or
        [string]$Descriptor.static_transaction_sha256-notmatch'^[0-9A-Fa-f]{64}$'-or
        [string]$Descriptor.broker_identity_sha256-ine[string]$Authorized.Payload.authority.broker_identity_sha256-or
        [int64]$Descriptor.authority_epoch-ne[int64]$Authorized.Payload.authority.authority_epoch-or
        [string]$Descriptor.generation_id-cne[string]$Authorized.Payload.authority.generation_id-or
        [string]$Descriptor.entries_sha256-notmatch'^[0-9A-Fa-f]{64}$'){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_DESCRIPTOR_INVALID context=$Context root=$root expected_parent=$expectedParent"}
    Assert-SynapsePurgeStoredDirectoryChain -Chain $Descriptor.parent_chain -ExpectedPath $parent -Context "${Context}_parent_chain"
    $entries=@($Descriptor.entries);if($entries.Count-lt1-or$entries.Count-gt64){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_ENTRY_BOUND_INVALID context=$Context count=$($entries.Count)"};$seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    foreach($entry in $entries){Assert-SynapsePurgeExactPropertySet -Value $entry -Expected @('leaf','kind','file_id_128','sha256','length') -Context "${Context}_entry";$entryLeaf=[string]$entry.leaf;if([string]::IsNullOrWhiteSpace($entryLeaf)-or$entryLeaf-ne(Split-Path -Leaf $entryLeaf)-or-not$seen.Add($entryLeaf)-or[string]$entry.kind-notin@('file','directory')-or[string]$entry.file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_ENTRY_INVALID context=$Context leaf=$entryLeaf"};if([string]$entry.kind-ceq'file'){if([string]$entry.sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[int64]$entry.length-lt0){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_FILE_INVALID context=$Context leaf=$entryLeaf"}}elseif(-not[string]::IsNullOrEmpty([string]$entry.sha256)-or[int64]$entry.length-ne-1L){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_DIRECTORY_INVALID context=$Context leaf=$entryLeaf"}}
    $sha=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $entries)).ToUpperInvariant();if($sha-ine[string]$Descriptor.entries_sha256){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_ENTRIES_HASH_INVALID context=$Context expected=$($Descriptor.entries_sha256) actual=$sha"}
    return $Descriptor
}

function New-SynapsePurgeOperatorStopCleanupDescriptor {
    param([Parameter(Mandatory=$true)]$Record,[Parameter(Mandatory=$true)]$Authorized,[Parameter(Mandatory=$true)][string]$Context)
    [void](Assert-SynapsePurgeOperatorStopAuthorizationPreimage -Record $Record -Authorized $Authorized -Context "${Context}_preimage")
    $root=Get-SynapseNormalizedDirectoryPath -Path ([string]$Record.Entry.Path);$rootChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $root);$parent=Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $root);$parentChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $parent);$entries=@(Get-SynapsePhysicalDirectoryEntriesBounded -Path $root -Chain $rootChain -MaximumEntries 64 -Context $Context)
    $allocation=$Record.Journal.Allocation
    if($null-eq$allocation-or-not[bool]$allocation.Valid-or-not[bool]$allocation.Frozen){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_ALLOCATION_INVALID context=$Context root=$root"}
    $allocatedNames=New-SynapseCaseInsensitiveMap
    $allocatedNames[$script:SynapseDeploymentAllocationMarkerFileName]=[pscustomobject]@{Kind='allocation_log';Directory=$false;FileIds=@(([string]$allocation.State.FileId128).ToUpperInvariant())}
    foreach($artifactLeaf in @($allocation.ArtifactOrder)){
        $artifact=$allocation.Artifacts[[string]$artifactLeaf]
        $ids=@()
        if(-not[string]::IsNullOrWhiteSpace([string]$artifact.file_id_128)){$ids+=([string]$artifact.file_id_128).ToUpperInvariant()}
        $ids+=@($artifact.allowed_file_ids_128|Where-Object{-not[string]::IsNullOrWhiteSpace([string]$_)}|ForEach-Object{([string]$_).ToUpperInvariant()})
        $ids=@($ids|Sort-Object -Unique)
        if($ids.Count-eq0){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_ALLOCATION_IDENTITY_MISSING context=$Context leaf=$artifactLeaf kind=$($artifact.kind) status=$($artifact.status)"}
        $allocatedNames[[string]$artifactLeaf]=[pscustomobject]@{Kind=[string]$artifact.kind;Directory=([string]$artifact.kind-ceq'directory'-or[bool]$artifact.transition_directory);FileIds=$ids}
    }
    $records=@($entries|ForEach-Object{
        $physicalEntry=$_;$entryLeaf=[string]$physicalEntry.Name
        if(-not$allocatedNames.ContainsKey($entryLeaf)){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_UNKNOWN_ALLOCATION_ENTRY context=$Context leaf=$entryLeaf root=$root"}
        $contract=$allocatedNames[$entryLeaf]
        if([bool]$physicalEntry.IsDirectory-ne[bool]$contract.Directory){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_ALLOCATION_TYPE_DRIFT context=$Context leaf=$entryLeaf allocated_kind=$($contract.Kind) actual_directory=$([bool]$physicalEntry.IsDirectory)"}
        $physicalEntryId=([string]$physicalEntry.FileId128).ToUpperInvariant()
        if(@($contract.FileIds|Where-Object{[string]$_-ieq$physicalEntryId}).Count-ne1){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_ALLOCATION_IDENTITY_DRIFT context=$Context leaf=$entryLeaf actual_file_id_128=$physicalEntryId allowed_file_ids_128=$(@($contract.FileIds)-join',')"}
        $state=Get-SynapsePhysicalRelativeState -ParentPath $root -ParentChain $rootChain -Leaf $entryLeaf -Directory:([bool]$physicalEntry.IsDirectory)
        if(-not[bool]$state.Exists-or[string]$state.FileId128-ine[string]$physicalEntry.FileId128-or([uint32]$physicalEntry.Attributes-band[uint32][IO.FileAttributes]::ReparsePoint)){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_ENTRY_DRIFT context=$Context leaf=$entryLeaf"}
        [ordered]@{leaf=$entryLeaf;kind=$(if([bool]$physicalEntry.IsDirectory){'directory'}else{'file'});file_id_128=([string]$state.FileId128).ToUpperInvariant();sha256=$(if([bool]$physicalEntry.IsDirectory){''}else{([string]$state.Sha256).ToUpperInvariant()});length=$(if([bool]$physicalEntry.IsDirectory){-1L}else{[int64]$state.Length})}
    }|Sort-Object leaf)
    $descriptor=[ordered]@{schema='synapse_setup_purge_operator_cleanup/v1';root=$root;parent=$parent;parent_chain=@($parentChain|ForEach-Object{[ordered]@{path=[string]$_.path;file_id_128=([string]$_.file_id_128).ToUpperInvariant()}});root_leaf=Split-Path -Leaf $root;root_file_id_128=([string]$rootChain[-1].file_id_128).ToUpperInvariant();static_transaction_sha256=([string]$Record.Journal.Initial.static_transaction_sha256).ToUpperInvariant();broker_identity_sha256=([string]$Record.Journal.Initial.broker_identity_sha256).ToUpperInvariant();authority_epoch=[int64]$Record.Journal.Initial.authority_epoch;generation_id=[string]$Record.Journal.Initial.generation_id;entries=$records;entries_sha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $records)).ToUpperInvariant()}
    $roundTrip=(Get-SynapseCanonicalJson -Value $descriptor)|ConvertFrom-Json -ErrorAction Stop;[void](Assert-SynapsePurgeOperatorStopCleanupDescriptor -Descriptor $roundTrip -Authorized $Authorized -Context $Context);return $descriptor
}

function Open-SynapsePurgeAuthorizedActiveControlLeases {
    param(
        [Parameter(Mandatory=$true)]$Authorized,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $gateLease=$null;$rosterLease=$null
    try{
        $opened=@()
        foreach($item in @(
            [pscustomobject]@{Role='gate';Identity=$Authorized.Payload.authority.active_control_gate},
            [pscustomobject]@{Role='roster';Identity=$Authorized.Payload.authority.active_roster})){
            $path=[System.IO.Path]::GetFullPath([string]$item.Identity.path);$parent=Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $path);$chain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $parent);$leaf=Split-Path -Leaf $path
            $lease=Open-SynapsePhysicalFileReadLease -ParentPath $parent -ParentChain $chain -Leaf $leaf -ExpectedFileId128 ([string]$item.Identity.file_id_128) -ExpectedSha256 ([string]$item.Identity.sha256) -ExpectedLength ([int64]$item.Identity.length) -Context "${Context}_$($item.Role)"
            $lease.RequireExact("${Context}_$($item.Role)_readback")
            if([string]$item.Role-ceq'gate'){$gateLease=$lease}else{$rosterLease=$lease}
            $opened+=,[pscustomobject]@{Role=[string]$item.Role;Path=$path;Lease=$lease}
        }
        $Authorized.Lease.RequireExact("${Context}_authorization")
        return [pscustomobject][ordered]@{Gate=$gateLease;Roster=$rosterLease;Items=$opened}
    }catch{if($null-ne$rosterLease){try{$rosterLease.Dispose()}catch{}};if($null-ne$gateLease){try{$gateLease.Dispose()}catch{}};throw}
}

function Close-SynapsePurgeAuthorizedActiveControlLeases {
    param([AllowNull()]$Leases)
    if($null-eq$Leases){return}
    foreach($lease in @($Leases.Roster,$Leases.Gate)){if($null-ne$lease){try{$lease.Dispose()}catch{}}}
}

function Assert-SynapsePurgeOperatorCleanupAuthorityRecord {
    param(
        [Parameter(Mandatory=$true)]$Record,
        [Parameter(Mandatory=$true)]$Authorized,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $p=$Record.Payload
    Assert-SynapsePurgeExactPropertySet -Value $p -Expected @('schema','state','purge_id','authorization','active_control_gate','active_roster','operator_stop','cleanup','authorized_at_utc','cleanup_authority_sha256') -Context $Context
    if([string]$p.schema-cne'synapse_setup_purge_operator_cleanup_authority/v1'-or[string]$p.state-cne'cleanup_authorized_before_mutation'-or[string]$p.purge_id-ine[string]$Authorized.Payload.purge_id-or[string]$Record.Leaf-cne("purge-$($p.purge_id)-operator-cleanup.json")-or[string]$p.cleanup_authority_sha256-notmatch'^[0-9A-Fa-f]{64}$'){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_AUTHORITY_INVALID context=$Context path=$($Record.Path)"}
    $authorization=$p.authorization;Assert-SynapsePurgeExactPropertySet -Value $authorization -Expected @('leaf','file_id_128','sha256','length','plan_sha256') -Context "${Context}_authorization"
    if([string]$authorization.leaf-cne[string]$Authorized.Leaf-or[string]$authorization.file_id_128-ine[string]$Authorized.State.FileId128-or[string]$authorization.sha256-ine[string]$Authorized.State.Sha256-or[int64]$authorization.length-ne[int64]$Authorized.State.Length-or[string]$authorization.plan_sha256-ine[string]$Authorized.Payload.plan_sha256){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_AUTHORIZATION_DRIFT context=$Context"}
    foreach($check in @(
        [pscustomobject]@{Actual=$p.active_control_gate;Expected=$Authorized.Payload.authority.active_control_gate;Role='gate'},
        [pscustomobject]@{Actual=$p.active_roster;Expected=$Authorized.Payload.authority.active_roster;Role='roster'})){
        Assert-SynapsePurgeExactPropertySet -Value $check.Actual -Expected @('path','file_id_128','sha256','length') -Context "${Context}_$($check.Role)"
        if((Get-SynapseCanonicalJson -Value $check.Actual)-cne(Get-SynapseCanonicalJson -Value $check.Expected)){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_CONTROL_DRIFT context=$Context role=$($check.Role)"}
    }
    $cut=$p.operator_stop
    Assert-SynapsePurgeExactPropertySet -Value $cut -Expected @('transaction_root','transaction_root_file_id_128','static_transaction_sha256','valid_prefix','torn_tail','allocation_log','artifacts','artifacts_sha256') -Context "${Context}_operator_stop"
    $root=Get-SynapseNormalizedDirectoryPath -Path ([string]$cut.transaction_root)
    if($root-ine(Get-SynapseNormalizedDirectoryPath -Path ([string]$p.cleanup.root))-or[string]$cut.transaction_root_file_id_128-ine[string]$p.cleanup.root_file_id_128-or[string]$cut.static_transaction_sha256-ine[string]$p.cleanup.static_transaction_sha256-or[string]$cut.artifacts_sha256-notmatch'^[0-9A-Fa-f]{64}$'){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_CUT_ROOT_DRIFT context=$Context root=$root"}
    $prefix=$cut.valid_prefix;Assert-SynapsePurgeExactPropertySet -Value $prefix -Expected @('sequence','state','leaf','file_id_128','sha256','length') -Context "${Context}_valid_prefix"
    $torn=$cut.torn_tail;Assert-SynapsePurgeExactPropertySet -Value $torn -Expected @('sequence','state','leaf','file_id_128','sha256','length') -Context "${Context}_torn_tail"
    if([int]$prefix.sequence-lt2-or[int]$prefix.sequence-ge$script:SynapseDeploymentJournalMaxSlots-or[string]$prefix.state-cne'rolled_back'-or[string]$prefix.leaf-cne('transaction-{0:D4}.json'-f[int]$prefix.sequence)-or[string]$prefix.file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'-or[string]$prefix.sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[int64]$prefix.length-lt1-or[int]$torn.sequence-ne([int]$prefix.sequence+1)-or[string]$torn.state-cne'torn_cleanup_ready'-or[string]$torn.leaf-cne('transaction-{0:D4}.json'-f[int]$torn.sequence)-or[string]$torn.file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'-or[string]$torn.sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[int64]$torn.length-lt1){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_CUT_INVALID context=$Context valid_sequence=$($prefix.sequence) torn_sequence=$($torn.sequence)"}
    $allocation=$cut.allocation_log;Assert-SynapsePurgeExactPropertySet -Value $allocation -Expected @('leaf','file_id_128','sha256','length','last_record_sha256','record_count') -Context "${Context}_allocation"
    if([string]$allocation.leaf-cne$script:SynapseDeploymentAllocationMarkerFileName-or[string]$allocation.file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'-or[string]$allocation.sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[int64]$allocation.length-lt1-or[string]$allocation.last_record_sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[int]$allocation.record_count-lt1){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_ALLOCATION_INVALID context=$Context"}
    $artifacts=@($cut.artifacts);if($artifacts.Count-lt$script:SynapseDeploymentJournalMaxSlots-or$artifacts.Count-gt$script:SynapseDeploymentArtifactMaxDirectEntries){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_ARTIFACT_BOUND_INVALID context=$Context count=$($artifacts.Count)"};$artifactMap=New-SynapseCaseInsensitiveMap
    foreach($artifact in $artifacts){Assert-SynapsePurgeExactPropertySet -Value $artifact -Expected @('leaf','kind','status','file_id_128','allowed_file_ids_128','transition_directory') -Context "${Context}_artifact";$leaf=[string]$artifact.leaf;if([string]::IsNullOrWhiteSpace($leaf)-or$leaf-ne(Split-Path -Leaf $leaf)-or$artifactMap.ContainsKey($leaf)-or[string]$artifact.kind-notin@('file','directory','journal_slot','progress_slot','transition_slot')-or[string]$artifact.status-notin@('reserved','allocated','sealed')-or-not($artifact.transition_directory-is[bool])){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_ARTIFACT_INVALID context=$Context leaf=$leaf"};if([string]$artifact.file_id_128-and[string]$artifact.file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_ARTIFACT_ID_INVALID context=$Context leaf=$leaf"};$ids=@($artifact.allowed_file_ids_128);foreach($id in $ids){if([string]$id-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_ARTIFACT_ALLOWED_ID_INVALID context=$Context leaf=$leaf"}};$artifactMap[$leaf]=$artifact}
    $artifactsSha=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $artifacts)).ToUpperInvariant();if($artifactsSha-ine[string]$cut.artifacts_sha256){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_ARTIFACT_HASH_INVALID context=$Context expected=$($cut.artifacts_sha256) actual=$artifactsSha"}
    foreach($journalRef in @($prefix,$torn)){if(-not$artifactMap.ContainsKey([string]$journalRef.leaf)){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_JOURNAL_ALLOCATION_MISSING context=$Context leaf=$($journalRef.leaf)"};$artifact=$artifactMap[[string]$journalRef.leaf];if([string]$artifact.kind-cne'journal_slot'-or[string]$artifact.file_id_128-ine[string]$journalRef.file_id_128){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_JOURNAL_ALLOCATION_DRIFT context=$Context leaf=$($journalRef.leaf)"}}
    [void](Assert-SynapsePurgeOperatorStopCleanupDescriptor -Descriptor $p.cleanup -Authorized $Authorized -Context "${Context}_cleanup")
    foreach($entry in @($p.cleanup.entries)){
        if([string]$entry.leaf-ceq$script:SynapseDeploymentAllocationMarkerFileName){if([string]$entry.file_id_128-ine[string]$allocation.file_id_128){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_MARKER_ROSTER_DRIFT context=$Context"};continue}
        if(-not$artifactMap.ContainsKey([string]$entry.leaf)){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_ROSTER_UNKNOWN context=$Context leaf=$($entry.leaf)"}
        $artifact=$artifactMap[[string]$entry.leaf];$expectedKind=if([string]$artifact.kind-ceq'directory'-or[bool]$artifact.transition_directory){'directory'}else{'file'};if([string]$entry.kind-cne$expectedKind){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_ROSTER_TYPE_DRIFT context=$Context leaf=$($entry.leaf) expected=$expectedKind actual=$($entry.kind)"};$ids=@();if([string]$artifact.file_id_128){$ids+=([string]$artifact.file_id_128).ToUpperInvariant()};$ids+=@($artifact.allowed_file_ids_128|ForEach-Object{([string]$_).ToUpperInvariant()});$ids=@($ids|Sort-Object -Unique);if(@($ids|Where-Object{[string]$_-ieq[string]$entry.file_id_128}).Count-ne1){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_ROSTER_IDENTITY_DRIFT context=$Context leaf=$($entry.leaf)"}
    }
    $time=[DateTime]::MinValue;if(-not[DateTime]::TryParse([string]$p.authorized_at_utc,[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::RoundtripKind,[ref]$time)){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_TIME_INVALID context=$Context"}
    $core=ConvertTo-SynapseCanonicalValue -Value $p;[void]$core.Remove('cleanup_authority_sha256');$actualSha=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $core)).ToUpperInvariant();if($actualSha-ine[string]$p.cleanup_authority_sha256){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_AUTHORITY_HASH_INVALID context=$Context expected=$($p.cleanup_authority_sha256) actual=$actualSha"}
    return $p
}

function New-SynapsePurgeOperatorCleanupAuthorityRecord {
    param(
        [Parameter(Mandatory=$true)]$Record,
        [Parameter(Mandatory=$true)]$Authorized,
        [Parameter(Mandatory=$true)]$PathContract,
        [Parameter(Mandatory=$true)][string]$Context
    )
    [void](Assert-SynapsePurgeOperatorStopAuthorizationPreimage -Record $Record -Authorized $Authorized -Context "${Context}_preimage")
    if([string]$Record.Journal.State-cne'rolled_back'-or$null-eq$Record.Journal.TornTail){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_AUTHORITY_CUT_INVALID context=$Context state=$($Record.Journal.State) torn=$($null-ne$Record.Journal.TornTail)"}
    $root=Get-SynapseNormalizedDirectoryPath -Path ([string]$Record.Entry.Path);$rootChain=@($Record.Journal.RootChain);$allocation=$Record.Journal.Allocation;$latest=$Record.Journal.Slots[-1];$torn=$Record.Journal.TornTail
    $sourceLeases=@();$controls=$null;$opened=$null;$returning=$false
    try{
        $controls=Open-SynapsePurgeAuthorizedActiveControlLeases -Authorized $Authorized -Context "${Context}_active_controls"
        foreach($source in @(
            [pscustomobject]@{Leaf=$script:SynapseDeploymentAllocationMarkerFileName;FileId=[string]$allocation.State.FileId128;Sha=[string]$allocation.State.Sha256;Length=[int64]$allocation.State.Length;Role='allocation'},
            [pscustomobject]@{Leaf=[string]$latest.Leaf;FileId=[string]$latest.FileId128;Sha=[string]$latest.RawSha256;Length=[int64]$latest.ByteLength;Role='valid_prefix'},
            [pscustomobject]@{Leaf=[string]$torn.Leaf;FileId=[string]$torn.FileId128;Sha=[string]$torn.Sha256;Length=[int64]$torn.Length;Role='torn_tail'})){
            $sourceLeases+=,(Open-SynapsePhysicalFileReadLease -ParentPath $root -ParentChain $rootChain -Leaf ([string]$source.Leaf) -ExpectedFileId128 ([string]$source.FileId) -ExpectedSha256 ([string]$source.Sha) -ExpectedLength ([int64]$source.Length) -Context "${Context}_$($source.Role)")
        }
        $cleanup=New-SynapsePurgeOperatorStopCleanupDescriptor -Record $Record -Authorized $Authorized -Context "${Context}_cleanup"
        $artifacts=@($allocation.ArtifactOrder|ForEach-Object{$artifact=$allocation.Artifacts[[string]$_];[ordered]@{leaf=[string]$artifact.leaf;kind=[string]$artifact.kind;status=[string]$artifact.status;file_id_128=$(if([string]$artifact.file_id_128){([string]$artifact.file_id_128).ToUpperInvariant()}else{''});allowed_file_ids_128=@($artifact.allowed_file_ids_128|ForEach-Object{([string]$_).ToUpperInvariant()}|Sort-Object -Unique);transition_directory=[bool]$artifact.transition_directory}}|Sort-Object leaf)
        $cut=[ordered]@{transaction_root=$root;transaction_root_file_id_128=([string]$rootChain[-1].file_id_128).ToUpperInvariant();static_transaction_sha256=([string]$Record.Journal.Initial.static_transaction_sha256).ToUpperInvariant();valid_prefix=[ordered]@{sequence=[int]$latest.Sequence;state='rolled_back';leaf=[string]$latest.Leaf;file_id_128=([string]$latest.FileId128).ToUpperInvariant();sha256=([string]$latest.RawSha256).ToUpperInvariant();length=[int64]$latest.ByteLength};torn_tail=[ordered]@{sequence=[int]$torn.Sequence;state='torn_cleanup_ready';leaf=[string]$torn.Leaf;file_id_128=([string]$torn.FileId128).ToUpperInvariant();sha256=([string]$torn.Sha256).ToUpperInvariant();length=[int64]$torn.Length};allocation_log=[ordered]@{leaf=$script:SynapseDeploymentAllocationMarkerFileName;file_id_128=([string]$allocation.State.FileId128).ToUpperInvariant();sha256=([string]$allocation.State.Sha256).ToUpperInvariant();length=[int64]$allocation.State.Length;last_record_sha256=([string]$allocation.LastRecordSha256).ToUpperInvariant();record_count=[int]$allocation.RecordCount};artifacts=$artifacts;artifacts_sha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $artifacts)).ToUpperInvariant()}
