        foreach($lease in $sourceLeases){$lease.RequireExact("${Context}_source_after")};$controls.Gate.RequireExact("${Context}_gate_after");$controls.Roster.RequireExact("${Context}_roster_after");$Authorized.Lease.RequireExact("${Context}_authorization_after")
        $returning=$true;return $opened
    }finally{if($null-ne$opened-and-not$returning){try{$opened.Lease.Dispose()}catch{}};foreach($lease in $sourceLeases){if($null-ne$lease){try{$lease.Dispose()}catch{}}};Close-SynapsePurgeAuthorizedActiveControlLeases -Leases $controls}
}

function Remove-SynapsePurgeOperatorCleanupAuthorityRecordExact {
    param(
        [Parameter(Mandatory=$true)]$Pending,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $record=$Pending.OperatorCleanup;if($null-eq$record){return}
    $record.Lease.RequireExact("${Context}_record_before");$Pending.Authorized.Lease.RequireExact("${Context}_authorization_before")
    $recordRoot=Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent ([string]$record.Path));$recordRootChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $recordRoot)
    $state=Get-SynapsePhysicalRelativeState -ParentPath $recordRoot -ParentChain $recordRootChain -Leaf ([string]$record.Leaf)
    if(-not[bool]$state.Exists-or[string]$state.FileId128-ine[string]$record.State.FileId128-or[string]$state.Sha256-ine[string]$record.State.Sha256-or[int64]$state.Length-ne[int64]$record.State.Length){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_AUTHORITY_RECORD_DRIFT context=$Context path=$($record.Path)"}
    $record.Lease.Dispose();$record.Lease=$null
    Remove-SynapsePhysicalRelativeEntryExact -ParentPath $recordRoot -ParentChain $recordRootChain -Leaf ([string]$record.Leaf) -ExpectedFileId128 ([string]$record.State.FileId128) -ExpectedSha256 ([string]$record.State.Sha256) -ExpectedLength ([int64]$record.State.Length) -Context $Context
    $after=Get-SynapsePhysicalRelativeState -ParentPath $recordRoot -ParentChain $recordRootChain -Leaf ([string]$record.Leaf);if([bool]$after.Exists){Die "SYNAPSE_PURGE_OPERATOR_CLEANUP_AUTHORITY_DELETE_UNPROVEN context=$Context path=$($record.Path)"}
    $Pending.OperatorCleanup=$null
}

