        foreach($entry in @($descriptor.entries|Where-Object{[string]$_.kind-ceq'file'}|Sort-Object leaf)){$cleanupAuthority.Lease.RequireExact("${Context}_file_$($entry.leaf)");$controls.Gate.RequireExact("${Context}_gate_$($entry.leaf)");$controls.Roster.RequireExact("${Context}_roster_$($entry.leaf)");$state=Get-SynapsePhysicalRelativeState -ParentPath $root -ParentChain $rootChain -Leaf ([string]$entry.leaf);if([bool]$state.Exists){Remove-SynapsePhysicalRelativeEntryExact -ParentPath $root -ParentChain $rootChain -Leaf ([string]$entry.leaf) -ExpectedFileId128 ([string]$entry.file_id_128) -ExpectedSha256 ([string]$entry.sha256) -ExpectedLength ([int64]$entry.length) -Context "${Context}_file"}}
        foreach($entry in @($descriptor.entries|Where-Object{[string]$_.kind-ceq'directory'}|Sort-Object leaf)){$cleanupAuthority.Lease.RequireExact("${Context}_directory_$($entry.leaf)");$controls.Gate.RequireExact("${Context}_gate_$($entry.leaf)");$controls.Roster.RequireExact("${Context}_roster_$($entry.leaf)");$state=Get-SynapsePhysicalRelativeState -ParentPath $root -ParentChain $rootChain -Leaf ([string]$entry.leaf) -Directory;if([bool]$state.Exists){$child=Join-Path $root ([string]$entry.leaf);$children=@(Get-SynapsePhysicalDirectoryEntriesBounded -Path $child -Chain (Get-SynapsePhysicalDirectoryChainDescriptor -Path $child) -MaximumEntries 0 -Context "${Context}_directory_empty");if($children.Count-ne0){Die "SYNAPSE_PURGE_OPERATOR_EXTERNAL_CLEANUP_DIRECTORY_NOT_EMPTY context=$Context leaf=$($entry.leaf)"};Remove-SynapsePhysicalRelativeEntryExact -ParentPath $root -ParentChain $rootChain -Leaf ([string]$entry.leaf) -ExpectedFileId128 ([string]$entry.file_id_128) -Directory -Context "${Context}_directory"}}
        $cleanupAuthority.Lease.RequireExact("${Context}_root");$authorized.Lease.RequireExact("${Context}_authorized_root");$controls.Gate.RequireExact("${Context}_gate_root");$controls.Roster.RequireExact("${Context}_roster_root");$remaining=@(Get-SynapsePhysicalDirectoryEntriesBounded -Path $root -Chain $rootChain -MaximumEntries 0 -Context "${Context}_root_empty");if($remaining.Count-ne0){Die "SYNAPSE_PURGE_OPERATOR_EXTERNAL_CLEANUP_ROOT_NOT_EMPTY context=$Context count=$($remaining.Count)"};Remove-SynapsePhysicalRelativeEntryExact -ParentPath $parent -ParentChain $parentChain -Leaf ([string]$descriptor.root_leaf) -ExpectedFileId128 ([string]$descriptor.root_file_id_128) -Directory -Context "${Context}_root"
        $rootAfter=Get-SynapsePhysicalRelativeState -ParentPath $parent -ParentChain $parentChain -Leaf ([string]$descriptor.root_leaf) -Directory;if([bool]$rootAfter.Exists){Die "SYNAPSE_PURGE_OPERATOR_EXTERNAL_CLEANUP_ROOT_STILL_PRESENT context=$Context root=$root file_id_128=$($rootAfter.FileId128)"}
        $cleanupAuthority.Lease.RequireExact("${Context}_after");$authorized.Lease.RequireExact("${Context}_authorized_after");$controls.Gate.RequireExact("${Context}_gate_after");$controls.Roster.RequireExact("${Context}_roster_after");Remove-SynapsePurgeOperatorCleanupAuthorityRecordExact -Pending $Pending -Context "${Context}_retire_authority"
    }finally{Close-SynapsePurgeAuthorizedActiveControlLeases -Leases $controls}
