function New-SynapsePurgeReadyRecord {
    param([Parameter(Mandatory=$true)]$Authorized,[AllowNull()]$Confirmation,[Parameter(Mandatory=$true)]$Authority,[Parameter(Mandatory=$true)]$OperatorStopRecord,[Parameter(Mandatory=$true)]$PathContract)
    $Authorized.Lease.RequireExact('purge_ready_authorization_before_control_proof');if($null-ne$Confirmation){$Confirmation.Lease.RequireExact('purge_ready_confirmation_before_control_proof')};$pair=$null
    try{
        [void](Assert-SynapsePurgeOperatorStopProvenance -Record $OperatorStopRecord -Authorized $Authorized -Authority $Authority -Context 'purge_ready_operator_stop')
        $operatorCleanup=New-SynapsePurgeOperatorStopCleanupDescriptor -Record $OperatorStopRecord -Authorized $Authorized -Context 'purge_ready_operator_cleanup'
        $pair=Read-SynapseAuthorityActiveControlPair -Layout $Authority.Layout -ExpectedState parked -Context 'purge_ready_parked_pair'
        $gate=[ordered]@{path=[string]$pair.Gate.Path;file_id_128=([string]$pair.Gate.FileId128).ToUpperInvariant();sha256=([string]$pair.Gate.Sha256).ToUpperInvariant();length=[int64]$pair.Gate.Length}
        $roster=[ordered]@{path=[string]$pair.Roster.Path;file_id_128=([string]$pair.Roster.FileId128).ToUpperInvariant();sha256=([string]$pair.Roster.Sha256).ToUpperInvariant();length=[int64]$pair.Roster.Length}
        $proof=Assert-SynapseBrokerParkedNoAuthority -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -ControlGateIdentity ([pscustomobject]@{Path=$gate.path;FileId128=$gate.file_id_128;Sha256=$gate.sha256;Length=$gate.length}) -RosterIdentity ([pscustomobject]@{Path=$roster.path;FileId128=$roster.file_id_128;Sha256=$roster.sha256;Length=$roster.length}) -ControlGateLease $pair.GateLease -RosterLease $pair.RosterLease -Bind ([string]$Authorized.Payload.authority.bind) -DbPath ([string]$Authorized.Payload.authority.db_path)
        $strictProof=Assert-SynapsePurgeStrictNoLiveAuthority -Bind ([string]$Authorized.Payload.authority.bind) -DbPath ([string]$Authorized.Payload.authority.db_path) -Context 'purge_ready_strict_no_live'
        $database=Get-SynapsePurgeDirectorySnapshot -Path ([string]$Authorized.Payload.target_contract.db_path) -Context 'purge_ready_database';$profiles=Get-SynapsePurgeDirectorySnapshot -Path ([string]$Authorized.Payload.target_contract.profiles_dir) -Context 'purge_ready_profiles';$token=Get-SynapsePurgeFileSnapshot -Path ([string]$Authorized.Payload.target_contract.token_path) -Context 'purge_ready_token'
        if(-not[bool]$token.exists-or[string]$token.file_id_128-ine[string]$Authorized.Payload.token.file_id_128-or[string]$token.sha256-ine[string]$Authorized.Payload.token.sha256-or[int64]$token.length-ne[int64]$Authorized.Payload.token.length){Die 'SYNAPSE_PURGE_READY_TOKEN_DRIFT'}
        if(-not[bool]$profiles.exists-or[string]$profiles.root_file_id_128-ine[string]$Authorized.Payload.profiles.root_file_id_128){Die 'SYNAPSE_PURGE_READY_PROFILES_ROOT_DRIFT'}
        $profilesOwnership=ConvertTo-SynapseCanonicalValue -Value $Authorized.Payload.profiles_ownership
        $profilesOwnershipRoundTrip=(Get-SynapseCanonicalJson -Value $profilesOwnership)|ConvertFrom-Json -ErrorAction Stop
        [void](Assert-SynapsePurgeProfilesOwnershipDescriptor -Descriptor $profilesOwnershipRoundTrip -ProfilesPlan ([pscustomobject]$profiles) -Context 'purge_ready_profiles_ownership')
        if([bool]$database.exists-ne[bool]$Authorized.Payload.database.exists-or([bool]$database.exists-and[string]$database.root_file_id_128-ine[string]$Authorized.Payload.database.root_file_id_128)){Die 'SYNAPSE_PURGE_READY_DATABASE_ROOT_DRIFT'}
        $vault=Get-SynapseCalyxPhysicalSnapshot -Path ([string]$Authorized.Payload.target_contract.db_path);if(-not[string]::IsNullOrWhiteSpace([string]$vault.error)-or-not[string]::IsNullOrWhiteSpace([string]$vault.current_manifest_error)-or-not[bool]$vault.bytes_complete){Die "SYNAPSE_PURGE_READY_VAULT_SNAPSHOT_INCOMPLETE error=$($vault.error) manifest_error=$($vault.current_manifest_error) bytes_complete=$($vault.bytes_complete)"}
        $durable=if($null-eq$vault.current_manifest_durable_seq){0L}else{[int64]$vault.current_manifest_durable_seq};$populated=($durable-gt0-or[int]$vault.cf_file_count-gt0-or[int]$vault.manifest_file_count-gt1-or[int]$vault.wal_segment_count-gt0-or[int64]$vault.wal_bytes-gt0-or@($database.entries).Count-gt0);$destructionConfirmed=([bool]$Authorized.Payload.confirmed-or$null-ne$Confirmation)
        if($populated-and-not$destructionConfirmed){Die "SYNAPSE_SETUP_VAULT_PURGE_REFUSED_AT_READY vault_dir=$($Authorized.Payload.target_contract.db_path) durable_seq=$durable manifest_files=$($vault.manifest_file_count) cf_files=$($vault.cf_file_count) wal_segments=$($vault.wal_segment_count) remediation=rerun the exact pending -Remove -Purge with -ConfirmVaultDestruction; the immutable confirmation will be crossbound before deletion"}
        $deleteCore=[ordered]@{database=$database;profiles=$profiles;profiles_ownership=$profilesOwnership;token=$token;vault_snapshot=$vault;destruction_confirmed=$destructionConfirmed};$deleteSha=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $deleteCore)).ToUpperInvariant()
        $Authorized.Lease.RequireExact('purge_ready_authorization_after_control_proof');if($null-ne$Confirmation){$Confirmation.Lease.RequireExact('purge_ready_confirmation_after_control_proof')}
        $confirmationRef=if($null-eq$Confirmation){$null}else{[ordered]@{leaf=[string]$Confirmation.Leaf;file_id_128=([string]$Confirmation.State.FileId128).ToUpperInvariant();sha256=([string]$Confirmation.State.Sha256).ToUpperInvariant();length=[int64]$Confirmation.State.Length;confirmation_sha256=([string]$Confirmation.Payload.confirmation_sha256).ToUpperInvariant()}}
        $ready=[ordered]@{schema='synapse_setup_purge_ready/v2';state='ready_to_delete';purge_id=[string]$Authorized.Payload.purge_id;authorization=[ordered]@{leaf=[string]$Authorized.Leaf;file_id_128=([string]$Authorized.State.FileId128).ToUpperInvariant();sha256=([string]$Authorized.State.Sha256).ToUpperInvariant();length=[int64]$Authorized.State.Length;plan_sha256=([string]$Authorized.Payload.plan_sha256).ToUpperInvariant()};confirmation=$confirmationRef;destruction_confirmed=$destructionConfirmed;parked_control_gate=$gate;parked_roster=$roster;broker_task=(ConvertTo-SynapseCanonicalValue -Value $Authorized.Payload.authority.task);operator_stop_cleanup=$operatorCleanup;target_process_count=[int]$strictProof.TargetProcessCount;listener_count=[int]$strictProof.ListenerCount;database=$database;profiles=$profiles;profiles_ownership=$profilesOwnership;token=$token;vault_snapshot=$vault;deletion_plan_sha256=$deleteSha;ready_at_utc=[DateTime]::UtcNow.ToString('o')}
    }finally{Close-SynapseAuthorityActiveControlPair -Pair $pair}
    $rootChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $PathContract.RecordRoot);$leaf="purge-$($Authorized.Payload.purge_id)-ready.json";$state=Get-SynapsePhysicalRelativeState -ParentPath $PathContract.RecordRoot -ParentChain $rootChain -Leaf $leaf
    if(-not[bool]$state.Exists){$readyContent=(Get-SynapseCanonicalJson -Value $ready)+"`n";if([System.Text.UTF8Encoding]::new($false,$true).GetByteCount($readyContent)-gt16777216){Die 'SYNAPSE_PURGE_READY_TOO_LARGE max_bytes=16777216'};Ensure-SynapseAtomicFileType;$rootIdentity=[SynapseSetup.AtomicFileV2]::GetPhysicalDirectoryIdentity([string]$PathContract.RecordRoot);[void](Write-SynapseAtomicUtf8TextFileUnderPhysicalRoot -Root $PathContract.RecordRoot -ExpectedRootIdentity $rootIdentity -LeafName $leaf -Content $readyContent -Purpose 'purge_ready')}
    $opened=Open-SynapsePurgeRecordExact -RecordRoot $PathContract.RecordRoot -RecordRootChain $rootChain -Leaf $leaf -Context 'purge_ready_readback';[void](Assert-SynapsePurgeReadyRecord -Record $opened -Authorized $Authorized -Confirmation $Confirmation -Context 'purge_ready_readback');return $opened
}

function Get-SynapsePendingPurgeRecord {
    param([Parameter(Mandatory=$true)]$PathContract)
    $recordRoot=Get-SynapseNormalizedDirectoryPath -Path ([string]$PathContract.RecordRoot);$recordParent=Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $recordRoot);$recordLeaf=Split-Path -Leaf $recordRoot
    if(-not[System.IO.Directory]::Exists($recordParent)){$absence=Get-SynapsePurgeAbsenceAnchor -Path $recordRoot -Kind directory -Context 'purge_record_root_absence';Assert-SynapsePurgeAbsenceAnchor -Anchor $absence -Context 'purge_record_root_absence_readback';return $null}
    $recordParentChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $recordParent);$recordRootState=Get-SynapsePhysicalRelativeState -ParentPath $recordParent -ParentChain $recordParentChain -Leaf $recordLeaf -Directory
    if(-not[bool]$recordRootState.Exists){return $null}
    $rootChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $recordRoot);if([string]$rootChain[-1].file_id_128-ine[string]$recordRootState.FileId128){Die "SYNAPSE_PURGE_RECORD_ROOT_IDENTITY_DRIFT record_root=$recordRoot"}
    $pending=@();$terminal=@();$publishedPattern='^purge-[0-9A-Fa-f]{64}-(authorized|confirmation|operator-cleanup|ready|completed)\.json$';$atomicTempPattern='^\.purge-[0-9A-Fa-f]{64}-(authorized|confirmation|operator-cleanup|ready|completed)\.json\.tmp-[1-9][0-9]*-[0-9a-f]{32}$';$entries=@()
    for($tempPass=0;$tempPass-le4096;$tempPass++){
        $entries=@(Get-SynapsePhysicalDirectoryEntriesBounded -Path $recordRoot -Chain $rootChain -MaximumEntries 4096 -Context 'purge_record_scan')
        $invalid=@($entries|Where-Object{[bool]$_.IsDirectory-or([uint32]$_.Attributes-band[uint32][IO.FileAttributes]::ReparsePoint)-or([string]$_.Name-notmatch$publishedPattern-and[string]$_.Name-notmatch$atomicTempPattern)})
        if($invalid.Count-ne0){Die "SYNAPSE_PURGE_RECORD_NAMESPACE_INVALID record_root=$recordRoot entries=$(@($invalid.Name)-join',')"}
        $temps=@($entries|Where-Object{[string]$_.Name-match$atomicTempPattern}|Sort-Object Name)
        if($temps.Count-eq0){break}
        if($tempPass-eq4096){Die "SYNAPSE_PURGE_RECORD_TEMP_CLEANUP_BOUND_EXCEEDED record_root=$recordRoot"}
        foreach($temp in $temps){$tempState=Get-SynapsePhysicalRelativeState -ParentPath $recordRoot -ParentChain $rootChain -Leaf ([string]$temp.Name);if(-not[bool]$tempState.Exists){continue};Remove-SynapsePhysicalRelativeEntryExact -ParentPath $recordRoot -ParentChain $rootChain -Leaf ([string]$temp.Name) -ExpectedFileId128 ([string]$tempState.FileId128) -ExpectedSha256 ([string]$tempState.Sha256) -ExpectedLength ([int64]$tempState.Length) -Context 'purge_record_abandoned_atomic_temp'}
    }
    $finalInvalid=@($entries|Where-Object{[bool]$_.IsDirectory-or([uint32]$_.Attributes-band[uint32][IO.FileAttributes]::ReparsePoint)-or[string]$_.Name-notmatch$publishedPattern})
    if($finalInvalid.Count-ne0){Die "SYNAPSE_PURGE_RECORD_FINAL_NAMESPACE_INVALID record_root=$recordRoot entries=$(@($finalInvalid.Name)-join',')"}
    $published=@($entries|Where-Object{[string]$_.Name-match$publishedPattern});$groups=@{};foreach($entry in $published){$id=([regex]::Match([string]$entry.Name,'^purge-([0-9A-Fa-f]{64})-')).Groups[1].Value.ToUpperInvariant();if(-not$groups.ContainsKey($id)){$groups[$id]=[Collections.Generic.List[object]]::new()};$groups[$id].Add($entry)}
    foreach($id in $groups.Keys){if(@($groups[$id]|Where-Object{[string]$_.Name-ceq"purge-$id-authorized.json"}).Count-ne1){Die "SYNAPSE_PURGE_RECORD_ORPHAN_GROUP purge_id=$id record_root=$($PathContract.RecordRoot)"}}
    foreach($entry in @($published|Where-Object{[string]$_.Name-match'^purge-[0-9A-Fa-f]{64}-authorized\.json$'}|Sort-Object Name)){
        $authorized=$null;$confirmation=$null;$operatorCleanup=$null;$ready=$null;$completed=$null
        try{
            $scanPurgeId=([regex]::Match([string]$entry.Name,'^purge-([0-9A-Fa-f]{64})-authorized\.json$')).Groups[1].Value.ToUpperInvariant()
            $scanCompletedLeaf="purge-$scanPurgeId-completed.json"
            $scanCompletedState=Get-SynapsePhysicalRelativeState -ParentPath $PathContract.RecordRoot -ParentChain $rootChain -Leaf $scanCompletedLeaf
            $authorized=Open-SynapsePurgeRecordExact -RecordRoot $PathContract.RecordRoot -RecordRootChain $rootChain -Leaf ([string]$entry.Name) -Context 'purge_record_scan_authorized'
            $storedContract=[pscustomobject][ordered]@{DbPath=[System.IO.Path]::GetFullPath([string]$authorized.Payload.target_contract.db_path);ProfilesDir=[System.IO.Path]::GetFullPath([string]$authorized.Payload.target_contract.profiles_dir);TokenPath=[System.IO.Path]::GetFullPath([string]$authorized.Payload.target_contract.token_path);RecordRoot=[System.IO.Path]::GetFullPath([string]$authorized.Payload.target_contract.record_root);Contract=$authorized.Payload.target_contract;ContractSha256=[string]$authorized.Payload.target_contract_sha256}
            [void](Assert-SynapsePurgeAuthorizedRecord -Record $authorized -PathContract $storedContract -StructuralOnly:([bool]$scanCompletedState.Exists) -Context 'purge_record_scan_authorized')
            $confirmationLeaf="purge-$($authorized.Payload.purge_id)-confirmation.json";$confirmationState=Get-SynapsePhysicalRelativeState -ParentPath $PathContract.RecordRoot -ParentChain $rootChain -Leaf $confirmationLeaf
            if([bool]$confirmationState.Exists){$confirmation=Open-SynapsePurgeRecordExact -RecordRoot $PathContract.RecordRoot -RecordRootChain $rootChain -Leaf $confirmationLeaf -Context 'purge_record_scan_confirmation';[void](Assert-SynapsePurgeConfirmationRecord -Record $confirmation -Authorized $authorized -Context 'purge_record_scan_confirmation')}
            $operatorCleanupLeaf="purge-$($authorized.Payload.purge_id)-operator-cleanup.json";$operatorCleanupState=Get-SynapsePhysicalRelativeState -ParentPath $PathContract.RecordRoot -ParentChain $rootChain -Leaf $operatorCleanupLeaf
            if([bool]$operatorCleanupState.Exists){$operatorCleanup=Open-SynapsePurgeRecordExact -RecordRoot $PathContract.RecordRoot -RecordRootChain $rootChain -Leaf $operatorCleanupLeaf -Context 'purge_record_scan_operator_cleanup';[void](Assert-SynapsePurgeOperatorCleanupAuthorityRecord -Record $operatorCleanup -Authorized $authorized -Context 'purge_record_scan_operator_cleanup')}
            $readyLeaf="purge-$($authorized.Payload.purge_id)-ready.json";$readyState=Get-SynapsePhysicalRelativeState -ParentPath $PathContract.RecordRoot -ParentChain $rootChain -Leaf $readyLeaf
            if([bool]$readyState.Exists){$ready=Open-SynapsePurgeRecordExact -RecordRoot $PathContract.RecordRoot -RecordRootChain $rootChain -Leaf $readyLeaf -Context 'purge_record_scan_ready';[void](Assert-SynapsePurgeReadyRecord -Record $ready -Authorized $authorized -Confirmation $confirmation -Context 'purge_record_scan_ready')}
            $completedLeaf="purge-$($authorized.Payload.purge_id)-completed.json";$completedState=Get-SynapsePhysicalRelativeState -ParentPath $PathContract.RecordRoot -ParentChain $rootChain -Leaf $completedLeaf
            if([bool]$completedState.Exists){
                if($null-eq$ready){Die "SYNAPSE_PURGE_COMPLETION_WITHOUT_READY path=$(Join-Path $PathContract.RecordRoot $completedLeaf)"}
                $completed=Open-SynapsePurgeRecordExact -RecordRoot $PathContract.RecordRoot -RecordRootChain $rootChain -Leaf $completedLeaf -Context 'purge_record_scan_completed'
                [void](Assert-SynapsePurgeCompletedRecord -Record $completed -Authorized $authorized -Confirmation $confirmation -Ready $ready -PathContract $storedContract -Context 'purge_record_scan_completed')
                if((Get-SynapseCanonicalJson -Value $storedContract.Contract)-ceq(Get-SynapseCanonicalJson -Value $PathContract.Contract)){
                    $terminal+=,[pscustomobject][ordered]@{Authorized=$authorized;Confirmation=$confirmation;OperatorCleanup=$operatorCleanup;Ready=$ready;Completed=$completed}
                    $authorized=$null;$confirmation=$null;$operatorCleanup=$null;$ready=$null;$completed=$null
                }else{
                    $completed.Lease.Dispose();$completed=$null;$ready.Lease.Dispose();$ready=$null;if($null-ne$operatorCleanup){$operatorCleanup.Lease.Dispose();$operatorCleanup=$null};if($null-ne$confirmation){$confirmation.Lease.Dispose();$confirmation=$null};$authorized.Lease.Dispose();$authorized=$null
                }
                continue
            }
            $pending+=,[pscustomobject][ordered]@{Authorized=$authorized;Confirmation=$confirmation;OperatorCleanup=$operatorCleanup;Ready=$ready}
        }catch{if($null-ne$completed){try{$completed.Lease.Dispose()}catch{}};if($null-ne$ready){try{$ready.Lease.Dispose()}catch{}};if($null-ne$operatorCleanup){try{$operatorCleanup.Lease.Dispose()}catch{}};if($null-ne$confirmation){try{$confirmation.Lease.Dispose()}catch{}};if($null-ne$authorized){try{$authorized.Lease.Dispose()}catch{}};throw}
    }
    $matchingTerminal=@()
    foreach($candidate in $terminal){
        $matches=$true
        foreach($identity in @($candidate.Ready.Payload.parked_control_gate,$candidate.Ready.Payload.parked_roster)){
            $path=[System.IO.Path]::GetFullPath([string]$identity.path);$parent=Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $path);$leaf=Split-Path -Leaf $path
            try{$chain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $parent);$state=Get-SynapsePhysicalRelativeState -ParentPath $parent -ParentChain $chain -Leaf $leaf}catch{$matches=$false;break}
            if(-not[bool]$state.Exists-or[string]$state.FileId128-ine[string]$identity.file_id_128-or[string]$state.Sha256-ine[string]$identity.sha256-or[int64]$state.Length-ne[int64]$identity.length){$matches=$false;break}
        }
        if($matches){[void](Assert-SynapsePurgeCompletedRecord -Record $candidate.Completed -Authorized $candidate.Authorized -Confirmation $candidate.Confirmation -Ready $candidate.Ready -PathContract $PathContract -RequirePhysicalAbsence -Context 'purge_record_scan_current_completed_absence');$matchingTerminal+=,$candidate}else{foreach($record in @($candidate.Completed,$candidate.Ready,$candidate.OperatorCleanup,$candidate.Confirmation,$candidate.Authorized)){if($null-ne$record){$record.Lease.Dispose()}}}
    }
    if($pending.Count-gt1-or$matchingTerminal.Count-gt1-or($pending.Count-gt0-and$matchingTerminal.Count-gt0)){foreach($p in @($pending)+@($matchingTerminal)){if($null-ne$p.Completed){$p.Completed.Lease.Dispose()};if($null-ne$p.Ready){$p.Ready.Lease.Dispose()};if($null-ne$p.OperatorCleanup){$p.OperatorCleanup.Lease.Dispose()};if($null-ne$p.Confirmation){$p.Confirmation.Lease.Dispose()};$p.Authorized.Lease.Dispose()};Die "SYNAPSE_PURGE_PENDING_CARDINALITY_INVALID pending=$($pending.Count) matching_completed=$($matchingTerminal.Count) record_root=$($PathContract.RecordRoot)"}
    if($matchingTerminal.Count-eq1){return $matchingTerminal[0]}
    if($pending.Count-eq0){return $null}
    $selected=$pending[0];if((Get-SynapseCanonicalJson -Value $selected.Authorized.Payload.target_contract)-cne(Get-SynapseCanonicalJson -Value $PathContract.Contract)){if($null-ne$selected.Ready){$selected.Ready.Lease.Dispose()};if($null-ne$selected.OperatorCleanup){$selected.OperatorCleanup.Lease.Dispose()};if($null-ne$selected.Confirmation){$selected.Confirmation.Lease.Dispose()};$selected.Authorized.Lease.Dispose();Die "SYNAPSE_PURGE_PENDING_TARGET_MISMATCH record=$($selected.Authorized.Path)"};return $selected
}

function Assert-SynapsePurgeDirectoryReconcileState {
    param([Parameter(Mandatory=$true)]$Plan,[Parameter(Mandatory=$true)][string]$Context)
    if(-not[bool]$Plan.exists){Assert-SynapsePurgeAbsenceAnchor -Anchor $Plan.absence -Context $Context;return $null}
    if(-not[System.IO.Directory]::Exists([string]$Plan.path)){
        $parentChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path ([string]$Plan.root_parent));if((Get-SynapseCanonicalJson -Value $parentChain)-cne(Get-SynapseCanonicalJson -Value @($Plan.root_parent_chain))){Die "SYNAPSE_PURGE_ROOT_PARENT_DRIFT context=$Context path=$($Plan.path)"};$state=Get-SynapsePhysicalRelativeState -ParentPath ([string]$Plan.root_parent) -ParentChain $parentChain -Leaf ([string]$Plan.root_leaf) -Directory;if([bool]$state.Exists){Die "SYNAPSE_PURGE_ROOT_TYPE_DRIFT context=$Context path=$($Plan.path)"};return $null
    }
    $current=Get-SynapsePurgeDirectorySnapshot -Path ([string]$Plan.path) -Context $Context
    if(-not[bool]$current.exists-or[string]$current.root_file_id_128-ine[string]$Plan.root_file_id_128){Die "SYNAPSE_PURGE_ROOT_REPLACED context=$Context path=$($Plan.path)"}
    if((Get-SynapseCanonicalJson -Value @($current.root_parent_chain))-cne(Get-SynapseCanonicalJson -Value @($Plan.root_parent_chain))){Die "SYNAPSE_PURGE_ROOT_PARENT_DRIFT context=$Context path=$($Plan.path)"}
    $expected=New-SynapseCaseInsensitiveMap;foreach($record in @($Plan.entries)){if($expected.ContainsKey([string]$record.relative_path)){Die "SYNAPSE_PURGE_PLAN_DUPLICATE_ENTRY context=$Context relative=$($record.relative_path)"};$expected[[string]$record.relative_path]=$record}
    foreach($actual in @($current.entries)){
        if(-not$expected.ContainsKey([string]$actual.relative_path)){Die "SYNAPSE_PURGE_UNPLANNED_ENTRY context=$Context path=$($Plan.path) relative=$($actual.relative_path)"}
        $e=$expected[[string]$actual.relative_path];if([string]$actual.kind-cne[string]$e.kind-or[string]$actual.file_id_128-ine[string]$e.file_id_128-or[string]$actual.sha256-ine[string]$e.sha256-or[int64]$actual.length-ne[int64]$e.length){Die "SYNAPSE_PURGE_ENTRY_REPLACED context=$Context path=$($Plan.path) relative=$($actual.relative_path)"}
    }
    return $current
}

function Assert-SynapsePurgeTokenReconcileState {
    param([Parameter(Mandatory=$true)]$Plan,[Parameter(Mandatory=$true)][string]$Context)
    if(-not[bool]$Plan.exists){Assert-SynapsePurgeAbsenceAnchor -Anchor $Plan.absence -Context $Context;return $null}
    if(-not[System.IO.Directory]::Exists([string]$Plan.parent)){
        $parentAbsence=Get-SynapsePurgeAbsenceAnchor -Path ([string]$Plan.parent) -Kind directory -Context "${Context}_parent_absent"
        Assert-SynapsePurgeAbsenceAnchor -Anchor $parentAbsence -Context "${Context}_parent_absent_readback"
        return $null
    }
    $chain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path ([string]$Plan.parent))
    if((Get-SynapseCanonicalJson -Value $chain)-cne(Get-SynapseCanonicalJson -Value @($Plan.parent_chain))){Die "SYNAPSE_PURGE_TOKEN_PARENT_DRIFT context=$Context path=$($Plan.path)"}
    $state=Get-SynapsePhysicalRelativeState -ParentPath ([string]$Plan.parent) -ParentChain $chain -Leaf ([string]$Plan.leaf)
    if(-not[bool]$state.Exists){return $null}
    if([string]$state.FileId128-ine[string]$Plan.file_id_128-or[string]$state.Sha256-ine[string]$Plan.sha256-or[int64]$state.Length-ne[int64]$Plan.length){Die "SYNAPSE_PURGE_TOKEN_DRIFT context=$Context path=$($Plan.path)"}
    return $state
}

function Remove-SynapsePurgeDirectoryPlanExact {
    param([Parameter(Mandatory=$true)]$Plan,[Parameter(Mandatory=$true)][string]$Context)
    $current=Assert-SynapsePurgeDirectoryReconcileState -Plan $Plan -Context "${Context}_predelete";if($null-eq$current){return}
    $files=@($Plan.entries|Where-Object{[string]$_.kind-ceq'file'}|Sort-Object @{Expression={(@([string]$_.relative_path-split'/')).Count};Descending=$true},@{Expression={[string]$_.relative_path};Descending=$true})
    foreach($record in $files){
        $relative=([string]$record.relative_path).Replace('/','\');$leaf=Split-Path -Leaf $relative;$parentRelative=Split-Path -Parent $relative;$parentPath=if([string]::IsNullOrWhiteSpace($parentRelative)){[string]$Plan.path}else{Join-Path ([string]$Plan.path) $parentRelative}
        if(-not[System.IO.Directory]::Exists($parentPath)){continue};$chain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $parentPath);$state=Get-SynapsePhysicalRelativeState -ParentPath $parentPath -ParentChain $chain -Leaf $leaf
        if(-not[bool]$state.Exists){continue};if([string]$state.FileId128-ine[string]$record.file_id_128-or[string]$state.Sha256-ine[string]$record.sha256-or[int64]$state.Length-ne[int64]$record.length){Die "SYNAPSE_PURGE_FILE_DRIFT context=$Context relative=$($record.relative_path)"}
        Remove-SynapsePhysicalRelativeEntryExact -ParentPath $parentPath -ParentChain $chain -Leaf $leaf -ExpectedFileId128 ([string]$record.file_id_128) -ExpectedSha256 ([string]$record.sha256) -ExpectedLength ([int64]$record.length) -Context "${Context}_file"
    }
    $directories=@($Plan.entries|Where-Object{[string]$_.kind-ceq'directory'}|Sort-Object @{Expression={(@([string]$_.relative_path-split'/')).Count};Descending=$true},@{Expression={[string]$_.relative_path};Descending=$true})
    foreach($record in $directories){
        $relative=([string]$record.relative_path).Replace('/','\');$leaf=Split-Path -Leaf $relative;$parentRelative=Split-Path -Parent $relative;$parentPath=if([string]::IsNullOrWhiteSpace($parentRelative)){[string]$Plan.path}else{Join-Path ([string]$Plan.path) $parentRelative}
        if(-not[System.IO.Directory]::Exists($parentPath)){continue};$chain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $parentPath);$state=Get-SynapsePhysicalRelativeState -ParentPath $parentPath -ParentChain $chain -Leaf $leaf -Directory
        if(-not[bool]$state.Exists){continue};if([string]$state.FileId128-ine[string]$record.file_id_128){Die "SYNAPSE_PURGE_DIRECTORY_DRIFT context=$Context relative=$($record.relative_path)"}
        $childPath=Join-Path $parentPath $leaf;$children=@(Get-SynapsePhysicalDirectoryEntriesBounded -Path $childPath -Chain (Get-SynapsePhysicalDirectoryChainDescriptor -Path $childPath) -MaximumEntries 0 -Context "${Context}_empty_directory")
        if($children.Count-ne0){Die "SYNAPSE_PURGE_DIRECTORY_NOT_EMPTY context=$Context relative=$($record.relative_path)"}
        Remove-SynapsePhysicalRelativeEntryExact -ParentPath $parentPath -ParentChain $chain -Leaf $leaf -ExpectedFileId128 ([string]$record.file_id_128) -Directory -Context "${Context}_directory"
    }
    $parentChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path ([string]$Plan.root_parent));if((Get-SynapseCanonicalJson -Value $parentChain)-cne(Get-SynapseCanonicalJson -Value @($Plan.root_parent_chain))){Die "SYNAPSE_PURGE_ROOT_PARENT_DRIFT context=$Context path=$($Plan.path)"}
    $rootState=Get-SynapsePhysicalRelativeState -ParentPath ([string]$Plan.root_parent) -ParentChain $parentChain -Leaf ([string]$Plan.root_leaf) -Directory
    if([bool]$rootState.Exists){if([string]$rootState.FileId128-ine[string]$Plan.root_file_id_128){Die "SYNAPSE_PURGE_ROOT_DRIFT context=$Context path=$($Plan.path)"};$children=@(Get-SynapsePhysicalDirectoryEntriesBounded -Path ([string]$Plan.path) -Chain (Get-SynapsePhysicalDirectoryChainDescriptor -Path ([string]$Plan.path)) -MaximumEntries 0 -Context "${Context}_root_empty");if($children.Count-ne0){Die "SYNAPSE_PURGE_ROOT_NOT_EMPTY context=$Context path=$($Plan.path)"};Remove-SynapsePhysicalRelativeEntryExact -ParentPath ([string]$Plan.root_parent) -ParentChain $parentChain -Leaf ([string]$Plan.root_leaf) -ExpectedFileId128 ([string]$Plan.root_file_id_128) -Directory -Context "${Context}_root"}
    $after=Get-SynapsePhysicalRelativeState -ParentPath ([string]$Plan.root_parent) -ParentChain $parentChain -Leaf ([string]$Plan.root_leaf) -Directory;if([bool]$after.Exists){Die "SYNAPSE_PURGE_ROOT_DELETE_UNPROVEN context=$Context path=$($Plan.path)"}
}

function Remove-SynapsePurgeTokenExact {
    param([Parameter(Mandatory=$true)]$Plan,[Parameter(Mandatory=$true)][string]$Context)
    if(-not[bool]$Plan.exists){Assert-SynapsePurgeAbsenceAnchor -Anchor $Plan.absence -Context $Context;return}
