    $after=Get-SynapsePhysicalRelativeState -ParentPath ([string]$Plan.parent) -ParentChain $chain -Leaf ([string]$Plan.leaf);if([bool]$after.Exists){Die "SYNAPSE_PURGE_TOKEN_DELETE_UNPROVEN context=$Context path=$($Plan.path)"}
