function Assert-SynapsePurgeRetainedLiveBoundary {
    param([Parameter(Mandatory=$true)]$Pending,[Parameter(Mandatory=$true)]$Pair,[Parameter(Mandatory=$true)][string]$Context)
    $authorized=$Pending.Authorized;$ready=$Pending.Ready
    foreach($check in @([pscustomobject]@{Actual=$Pair.Gate;Expected=$ready.Payload.parked_control_gate;Lease=$Pair.GateLease;Role='gate'},[pscustomobject]@{Actual=$Pair.Roster;Expected=$ready.Payload.parked_roster;Lease=$Pair.RosterLease;Role='roster'})){if([string]$check.Actual.Path-ine[System.IO.Path]::GetFullPath([string]$check.Expected.path)-or[string]$check.Actual.FileId128-ine[string]$check.Expected.file_id_128-or[string]$check.Actual.Sha256-ine[string]$check.Expected.sha256-or[int64]$check.Actual.Length-ne[int64]$check.Expected.length){Die "SYNAPSE_PURGE_PARKED_CONTROL_DRIFT context=$Context role=$($check.Role)"};$check.Lease.RequireExact("${Context}_$($check.Role)")}
    [void](Assert-SynapseTaskReadbackIdentity -Expected ([pscustomobject]$ready.Payload.broker_task) -Kind broker)
    [void](Assert-SynapsePurgeStrictNoLiveAuthority -Bind ([string]$authorized.Payload.authority.bind) -DbPath ([string]$authorized.Payload.authority.db_path) -Context $Context)
    $authorized.Lease.RequireExact("${Context}_authorized");if($null-ne$Pending.Confirmation){$Pending.Confirmation.Lease.RequireExact("${Context}_confirmation")};$ready.Lease.RequireExact("${Context}_ready")
}

function Assert-SynapsePurgeReadyLiveBoundary {
    param([Parameter(Mandatory=$true)]$Pending,[Parameter(Mandatory=$true)][string]$RuntimeBinDir,[Parameter(Mandatory=$true)][string]$Context)
    $authorized=$Pending.Authorized;$ready=$Pending.Ready;if($null-eq$ready){Die "SYNAPSE_PURGE_READY_RECORD_MISSING context=$Context"}
    [void](Assert-SynapsePurgeReadyRecord -Record $ready -Authorized $authorized -Confirmation $Pending.Confirmation -Context $Context);$authorized.Lease.RequireExact("${Context}_authorized_before");if($null-ne$Pending.Confirmation){$Pending.Confirmation.Lease.RequireExact("${Context}_confirmation_before")};$ready.Lease.RequireExact("${Context}_ready_before")
    $layout=Get-SynapseAuthorityLayoutReadOnly -RuntimeBinDir $RuntimeBinDir -RequireAuthorityRoot;$pair=$null
    try{$pair=Read-SynapseAuthorityActiveControlPair -Layout $layout -ExpectedState parked -Context $Context;Assert-SynapsePurgeRetainedLiveBoundary -Pending $Pending -Pair $pair -Context "${Context}_opened";return $pair}catch{Close-SynapseAuthorityActiveControlPair -Pair $pair;throw}
}

function Complete-SynapsePurgeFromReadyRecord {
    param([Parameter(Mandatory=$true)]$Pending,[Parameter(Mandatory=$true)]$PathContract,[Parameter(Mandatory=$true)][string]$RuntimeBinDir,[Parameter(Mandatory=$true)][string]$Context)
    $authorized=$Pending.Authorized;$ready=$Pending.Ready;$primary=$null;$controlPair=$null
    try{
        [void](Assert-SynapsePurgeAuthorizedRecord -Record $authorized -PathContract $PathContract -Context $Context)
        if($null-ne$Pending.PSObject.Properties['Completed']-and$null-ne$Pending.Completed){[void](Assert-SynapsePurgeCompletedRecord -Record $Pending.Completed -Authorized $authorized -Confirmation $Pending.Confirmation -Ready $ready -PathContract $PathContract -RequirePhysicalAbsence -Context "${Context}_existing_completion");$Pending.Completed.Lease.RequireExact("${Context}_existing_completion")}
        $controlPair=Assert-SynapsePurgeReadyLiveBoundary -Pending $Pending -RuntimeBinDir $RuntimeBinDir -Context "${Context}_boundary"
        # Prove the complete deletion set before the first irreversible delete.
        # Per-target proofs below are intentionally repeated at each boundary.
        [void](Assert-SynapsePurgeDirectoryReconcileState -Plan $ready.Payload.database -Context "${Context}_preflight_database")
        [void](Assert-SynapsePurgeDirectoryReconcileState -Plan $ready.Payload.profiles -Context "${Context}_preflight_profiles")
        [void](Assert-SynapsePurgeTokenReconcileState -Plan $ready.Payload.token -Context "${Context}_preflight_token")
        Assert-SynapsePurgeRetainedLiveBoundary -Pending $Pending -Pair $controlPair -Context "${Context}_before_database"
        Remove-SynapsePurgeDirectoryPlanExact -Plan $ready.Payload.database -Context "${Context}_database"
        Assert-SynapsePurgeRetainedLiveBoundary -Pending $Pending -Pair $controlPair -Context "${Context}_after_database"
        Remove-SynapsePurgeDirectoryPlanExact -Plan $ready.Payload.profiles -Context "${Context}_profiles"
        Assert-SynapsePurgeRetainedLiveBoundary -Pending $Pending -Pair $controlPair -Context "${Context}_after_profiles"
        Remove-SynapsePurgeTokenExact -Plan $ready.Payload.token -Context "${Context}_token"
        Assert-SynapsePurgeRetainedLiveBoundary -Pending $Pending -Pair $controlPair -Context "${Context}_after_token"
        $dbAbsent=Get-SynapsePurgeDirectorySnapshot -Path $PathContract.DbPath -Context "${Context}_precommit_database_absence";$profilesAbsent=Get-SynapsePurgeDirectorySnapshot -Path $PathContract.ProfilesDir -Context "${Context}_precommit_profiles_absence";$tokenAbsent=Get-SynapsePurgeFileSnapshot -Path $PathContract.TokenPath -Context "${Context}_precommit_token_absence"
        if([bool]$dbAbsent.exists-or[bool]$profilesAbsent.exists-or[bool]$tokenAbsent.exists){Die "SYNAPSE_PURGE_COMPLETION_PRECOMMIT_PHYSICAL_STATE_INVALID context=$Context database_exists=$($dbAbsent.exists) profiles_exists=$($profilesAbsent.exists) token_exists=$($tokenAbsent.exists)"}
        Assert-SynapsePurgeRetainedLiveBoundary -Pending $Pending -Pair $controlPair -Context "${Context}_precommit_boundary"
        $root=[string]$PathContract.RecordRoot;$rootChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $root);$completedLeaf="purge-$($authorized.Payload.purge_id)-completed.json"
        $completed=[ordered]@{schema='synapse_setup_purge_completed/v2';state='completed';purge_id=[string]$authorized.Payload.purge_id;authorization_leaf=[string]$authorized.Leaf;authorization_file_id_128=([string]$authorized.State.FileId128).ToUpperInvariant();authorization_sha256=([string]$authorized.State.Sha256).ToUpperInvariant();authorization_length=[int64]$authorized.State.Length;ready_leaf=[string]$ready.Leaf;ready_file_id_128=([string]$ready.State.FileId128).ToUpperInvariant();ready_sha256=([string]$ready.State.Sha256).ToUpperInvariant();ready_length=[int64]$ready.State.Length;deletion_plan_sha256=([string]$ready.Payload.deletion_plan_sha256).ToUpperInvariant();database_absent=$true;profiles_absent=$true;token_absent=$true;completed_at_utc=[DateTime]::UtcNow.ToString('o')}
        $state=Get-SynapsePhysicalRelativeState -ParentPath $root -ParentChain $rootChain -Leaf $completedLeaf
        if(-not[bool]$state.Exists){Ensure-SynapseAtomicFileType;$rootIdentity=[SynapseSetup.AtomicFileV2]::GetPhysicalDirectoryIdentity($root);[void](Write-SynapseAtomicUtf8TextFileUnderPhysicalRoot -Root $root -ExpectedRootIdentity $rootIdentity -LeafName $completedLeaf -Content ((Get-SynapseCanonicalJson -Value $completed)+"`n") -Purpose 'purge_completed')}
        $readback=Open-SynapsePurgeRecordExact -RecordRoot $root -RecordRootChain $rootChain -Leaf $completedLeaf -Context 'purge_completed_readback'
        try{[void](Assert-SynapsePurgeCompletedRecord -Record $readback -Authorized $authorized -Confirmation $Pending.Confirmation -Ready $ready -PathContract $PathContract -RequirePhysicalAbsence -Context "${Context}_completion");Assert-SynapsePurgeRetainedLiveBoundary -Pending $Pending -Pair $controlPair -Context "${Context}_completion_boundary";Info "SYNAPSE_PURGE_COMPLETED purge_id=$($authorized.Payload.purge_id) record=$($readback.Path) token_scope=file_only";return $readback.Path}finally{$readback.Lease.Dispose()}
    }catch{$primary=$_.Exception;throw}finally{
        Close-SynapseAuthorityActiveControlPair -Pair $controlPair
        foreach($record in @($(if($null-ne$Pending.PSObject.Properties['Completed']){$Pending.Completed}else{$null}),$ready,$Pending.OperatorCleanup,$Pending.Confirmation,$authorized)){if($null-ne$record-and$null-ne$record.Lease){try{$record.Lease.Dispose()}catch{$summary=if($null-ne$primary){$primary.Message}else{'none'};[Environment]::FailFast("SYNAPSE_PURGE_CAPABILITY_LEASE_RELEASE_UNPROVEN context=$Context primary=[$summary]",$_.Exception)}}}
    }
}

# ---------------------------------------------------------------------------
# Forward-only broker decommission authority
# ---------------------------------------------------------------------------
function Get-SynapseBrokerDecommissionRecordRoot {
    return (Get-SynapseNormalizedDirectoryPath -Path (Join-Path $env:LOCALAPPDATA 'synapse\decommission-records'))
}

function Get-SynapseBrokerDecommissionRecordReference {
    param([Parameter(Mandatory=$true)]$Record)
    $Record.Lease.RequireExact('broker_decommission_record_reference')
    return [ordered]@{leaf=[string]$Record.Leaf;file_id_128=([string]$Record.State.FileId128).ToUpperInvariant();sha256=([string]$Record.State.Sha256).ToUpperInvariant();length=[int64]$Record.State.Length;record_sha256=([string]$Record.Payload.record_sha256).ToUpperInvariant()}
}

function Assert-SynapseBrokerDecommissionRecordReference {
    param([Parameter(Mandatory=$true)]$Reference,[Parameter(Mandatory=$true)]$Record,[Parameter(Mandatory=$true)][string]$Context)
    Assert-SynapsePurgeExactPropertySet -Value $Reference -Expected @('leaf','file_id_128','sha256','length','record_sha256') -Context $Context
    if([string]$Reference.leaf-cne[string]$Record.Leaf-or[string]$Reference.file_id_128-ine[string]$Record.State.FileId128-or[string]$Reference.sha256-ine[string]$Record.State.Sha256-or[int64]$Reference.length-ne[int64]$Record.State.Length-or[string]$Reference.record_sha256-ine[string]$Record.Payload.record_sha256){Die "SYNAPSE_BROKER_DECOMMISSION_RECORD_REFERENCE_DRIFT context=$Context leaf=$($Record.Leaf)"}
}

function Assert-SynapseBrokerDecommissionRecordHash {
    param([Parameter(Mandatory=$true)]$Record,[Parameter(Mandatory=$true)][string]$Context)
    if([string]$Record.Payload.record_sha256-notmatch'^[0-9A-Fa-f]{64}$'){Die "SYNAPSE_BROKER_DECOMMISSION_RECORD_HASH_INVALID context=$Context path=$($Record.Path)"}
    $core=ConvertTo-SynapseCanonicalValue -Value $Record.Payload;[void]$core.Remove('record_sha256')
    $actual=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $core)).ToUpperInvariant()
    if($actual-ine[string]$Record.Payload.record_sha256){Die "SYNAPSE_BROKER_DECOMMISSION_RECORD_HASH_MISMATCH context=$Context expected=$($Record.Payload.record_sha256) actual=$actual"}
}

function Assert-SynapseBrokerDecommissionUtcTimestamp {
    param([Parameter(Mandatory=$true)]$Value,[Parameter(Mandatory=$true)][string]$Context)
    if($Value-is[datetime]){
        if(([datetime]$Value).Kind-ne[DateTimeKind]::Utc){Die "SYNAPSE_BROKER_DECOMMISSION_TIMESTAMP_INVALID context=$Context kind=$(([datetime]$Value).Kind)"}
        return [datetime]$Value
    }
    if(-not($Value-is[string])-or[string]::IsNullOrWhiteSpace([string]$Value)){Die "SYNAPSE_BROKER_DECOMMISSION_TIMESTAMP_INVALID context=$Context"}
    $parsed=[datetime]::MinValue
    if(-not[datetime]::TryParseExact([string]$Value,'o',[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::RoundtripKind,[ref]$parsed)-or$parsed.Kind-ne[DateTimeKind]::Utc-or$parsed.ToString('o',[Globalization.CultureInfo]::InvariantCulture)-cne[string]$Value){Die "SYNAPSE_BROKER_DECOMMISSION_TIMESTAMP_INVALID context=$Context value=$Value"}
    return $parsed
}

function Write-SynapseBrokerDecommissionRecord {
    param(
        [Parameter(Mandatory=$true)][ValidatePattern('^[0-9A-Fa-f]{64}$')][string]$DecommissionId,
        [Parameter(Mandatory=$true)][ValidateSet('authorized','confirmation','parked','task-absent','drained','cleanup-ready','quiesced','completed')][string]$Phase,
        [Parameter(Mandatory=$true)][ValidatePattern('^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$')][string]$ExpectedRecordRootFileId128,
        [Parameter(Mandatory=$true)]$RecordRootLease,
        [Parameter(Mandatory=$true)]$Payload,
        [object[]]$Predecessors=@(),
        [Parameter(Mandatory=$true)][string]$Context
    )
    if($null-eq$RecordRootLease){Die "SYNAPSE_BROKER_DECOMMISSION_RECORD_ROOT_LEASE_MISSING context=$Context phase=$Phase"};$RecordRootLease.RequireExact("${Context}_record_root_before")
    foreach($predecessor in @($Predecessors)){if($null-eq$predecessor-or$null-eq$predecessor.Lease){Die "SYNAPSE_BROKER_DECOMMISSION_PREDECESSOR_LEASE_MISSING context=$Context phase=$Phase"};$predecessor.Lease.RequireExact("${Context}_predecessor_before_$($predecessor.Leaf)")}
    $root=Get-SynapseBrokerDecommissionRecordRoot;$rootChain=@(Ensure-SynapsePhysicalDirectoryPath -Path $root -Context 'broker_decommission_record_root')
    if([string]$rootChain[-1].file_id_128-ine$ExpectedRecordRootFileId128){Die "SYNAPSE_BROKER_DECOMMISSION_RECORD_ROOT_IDENTITY_DRIFT context=$Context phase=$Phase expected=$ExpectedRecordRootFileId128 actual=$($rootChain[-1].file_id_128)"}
    $canonical=ConvertTo-SynapseCanonicalValue -Value $Payload
    if($null-ne$canonical.PSObject.Properties['record_sha256']){[void]$canonical.Remove('record_sha256')}
    $canonical.record_sha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $canonical)).ToUpperInvariant()
    $content=(Get-SynapseCanonicalJson -Value $canonical)+"`n";$bytes=[Text.UTF8Encoding]::new($false,$true).GetByteCount($content)
    if($bytes-lt1-or$bytes-gt16777216){Die "SYNAPSE_BROKER_DECOMMISSION_RECORD_BOUND_INVALID context=$Context phase=$Phase bytes=$bytes"}
    $leaf="decommission-$($DecommissionId.ToUpperInvariant())-$Phase.json";$state=Get-SynapsePhysicalRelativeState -ParentPath $root -ParentChain $rootChain -Leaf $leaf
    $candidate=$null;$returning=$false
    try{
        if([bool]$state.Exists){
            $candidate=Open-SynapsePurgeRecordExact -RecordRoot $root -RecordRootChain $rootChain -Leaf $leaf -Context "${Context}_existing"
            if((Get-SynapseCanonicalJson -Value $candidate.Payload)-cne(Get-SynapseCanonicalJson -Value $canonical)){Die "SYNAPSE_BROKER_DECOMMISSION_EXISTING_PHASE_DRIFT context=$Context phase=$Phase leaf=$leaf"}
            foreach($predecessor in @($Predecessors)){$predecessor.Lease.RequireExact("${Context}_predecessor_existing_$($predecessor.Leaf)")}
            $RecordRootLease.RequireExact("${Context}_record_root_existing");$returning=$true;return $candidate
        }
        foreach($predecessor in @($Predecessors)){$predecessor.Lease.RequireExact("${Context}_predecessor_publish_$($predecessor.Leaf)")}
        Ensure-SynapseAtomicFileType;$rootIdentity=[SynapseSetup.AtomicFileV2]::GetPhysicalDirectoryIdentity($root)
        [void](Write-SynapseAtomicUtf8TextFileUnderPhysicalRoot -Root $root -ExpectedRootIdentity $rootIdentity -LeafName $leaf -Content $content -Purpose "broker_decommission_$Phase")
        $candidate=Open-SynapsePurgeRecordExact -RecordRoot $root -RecordRootChain $rootChain -Leaf $leaf -Context "${Context}_readback"
        foreach($predecessor in @($Predecessors)){$predecessor.Lease.RequireExact("${Context}_predecessor_after_$($predecessor.Leaf)")}
        $RecordRootLease.RequireExact("${Context}_record_root_after");$returning=$true;return $candidate
    }finally{
        if(-not$returning-and$null-ne$candidate-and$null-ne$candidate.Lease){try{$candidate.Lease.Dispose()}catch{[Environment]::FailFast("SYNAPSE_BROKER_DECOMMISSION_RECORD_LEASE_RELEASE_UNPROVEN context=$Context phase=$Phase",$_.Exception)}}
    }
}

function Get-SynapseBrokerDecommissionCompletedHistory {
    param(
        [Parameter(Mandatory=$true)][string]$RecordRoot,
        [Parameter(Mandatory=$true)]$RecordRootChain,
        [Parameter(Mandatory=$true)]$RecordRootLease,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $records=[Collections.Generic.List[object]]::new();$returning=$false
    try{
        $RecordRootLease.RequireExact("${Context}_root_before")
        $completedRegex=[regex]::new('\Adecommission-[0-9A-F]{64}-completed\.json\z',[Text.RegularExpressions.RegexOptions]::CultureInvariant)
        $entries=@(Get-SynapsePhysicalDirectoryEntriesBounded -Path $RecordRoot -Chain $RecordRootChain -MaximumEntries 4096 -Context "${Context}_scan"|Where-Object{$completedRegex.IsMatch([string]$_.Name)}|Sort-Object Name)
        $rosterJson=Get-SynapseCanonicalJson -Value @($entries|ForEach-Object{[ordered]@{name=[string]$_.Name;file_id_128=([string]$_.FileId128).ToUpperInvariant();length=[int64]$_.Length;attributes=[uint32]$_.Attributes;is_directory=[bool]$_.IsDirectory}})
        foreach($entry in $entries){
            if([bool]$entry.IsDirectory-or([uint32]$entry.Attributes-band[uint32][IO.FileAttributes]::ReparsePoint)){Die "SYNAPSE_BROKER_DECOMMISSION_HISTORY_ENTRY_INVALID context=$Context leaf=$($entry.Name)"}
            $state=Get-SynapsePhysicalEnumeratedRelativeState -ParentPath $RecordRoot -ParentChain $RecordRootChain -Leaf ([string]$entry.Name) -MaximumLength 16777216 -Context "${Context}_state"
            if(-not[bool]$state.Exists-or[string]$state.FileId128-ine[string]$entry.FileId128){Die "SYNAPSE_BROKER_DECOMMISSION_HISTORY_ENTRY_DRIFT context=$Context leaf=$($entry.Name)"}
            $record=Open-SynapsePurgeRecordFromBoundedState -RecordRoot $RecordRoot -RecordRootChain $RecordRootChain -Leaf ([string]$entry.Name) -State $state -Context "${Context}_record"
            $p=$record.Payload
            Assert-SynapsePurgeExactPropertySet -Value $p -Expected @('schema','state','decommission_id','history_sequence','previous_completed','authorization','parked','task_absent','drained','cleanup_ready','quiesced','mode','deletion_plan_sha256','task_absent_proven','job_absent_proven','outer_identity_gone','broker_identity_gone','authority_root_disposition','runtime_artifacts_disposition','database_disposition','profiles_disposition','token_disposition','completed_at_utc','record_sha256') -Context "${Context}_shape"
            if([string]$p.schema-cne'synapse_broker_decommission_completed/v2'-or[string]$p.state-cne'completed'-or[string]$p.decommission_id-notmatch'^[0-9A-Fa-f]{64}$'-or[string]$record.Leaf-cne("decommission-$($p.decommission_id)-completed.json")-or[int64]$p.history_sequence-lt1){Die "SYNAPSE_BROKER_DECOMMISSION_HISTORY_RECORD_INVALID context=$Context leaf=$($entry.Name)"}
            Assert-SynapseBrokerDecommissionRecordHash -Record $record -Context "${Context}_hash"
            $records.Add($record)
        }
        $ordered=@($records|Sort-Object @{Expression={[int64]$_.Payload.history_sequence};Ascending=$true},@{Expression={[string]$_.Payload.decommission_id};Ascending=$true})
        for($index=0;$index-lt$ordered.Count;$index++){
            $record=$ordered[$index];$expectedSequence=[int64]$index+1L
            if([int64]$record.Payload.history_sequence-ne$expectedSequence){Die "SYNAPSE_BROKER_DECOMMISSION_HISTORY_SEQUENCE_INVALID context=$Context expected=$expectedSequence actual=$($record.Payload.history_sequence) leaf=$($record.Leaf)"}
            if($index-eq0){if($null-ne$record.Payload.previous_completed){Die "SYNAPSE_BROKER_DECOMMISSION_HISTORY_GENESIS_PREDECESSOR_INVALID context=$Context leaf=$($record.Leaf)"}}
            else{if($null-eq$record.Payload.previous_completed){Die "SYNAPSE_BROKER_DECOMMISSION_HISTORY_PREDECESSOR_MISSING context=$Context leaf=$($record.Leaf)"};Assert-SynapseBrokerDecommissionRecordReference -Reference $record.Payload.previous_completed -Record $ordered[$index-1] -Context "${Context}_predecessor_$expectedSequence"}
        }
        $stableEntries=@(Get-SynapsePhysicalDirectoryEntriesBounded -Path $RecordRoot -Chain $RecordRootChain -MaximumEntries 4096 -Context "${Context}_stable_scan"|Where-Object{$completedRegex.IsMatch([string]$_.Name)}|Sort-Object Name)
        $stableRosterJson=Get-SynapseCanonicalJson -Value @($stableEntries|ForEach-Object{[ordered]@{name=[string]$_.Name;file_id_128=([string]$_.FileId128).ToUpperInvariant();length=[int64]$_.Length;attributes=[uint32]$_.Attributes;is_directory=[bool]$_.IsDirectory}})
        if($stableRosterJson-cne$rosterJson){Die "SYNAPSE_BROKER_DECOMMISSION_HISTORY_CHANGED context=$Context"}
        foreach($record in $ordered){$record.Lease.RequireExact("${Context}_final_$($record.Leaf)")};$RecordRootLease.RequireExact("${Context}_root_final")
        $returning=$true
        return [pscustomobject][ordered]@{Sequence=[int64]$ordered.Count;Head=$(if($ordered.Count-eq0){$null}else{$ordered[-1]});Records=$ordered;RosterJson=$rosterJson}
    }finally{
        if(-not$returning){foreach($record in @($records)){if($null-ne$record-and$null-ne$record.Lease){try{$record.Lease.Dispose()}catch{[Environment]::FailFast("SYNAPSE_BROKER_DECOMMISSION_HISTORY_RECORD_RELEASE_UNPROVEN context=$Context",$_.Exception)}}}}
    }
}

function Close-SynapseBrokerDecommissionCompletedHistory {
    param($History,[Parameter(Mandatory=$true)][string]$Context)
    if($null-eq$History){return};$failure=$null
    foreach($record in @($History.Records)){if($null-ne$record-and$null-ne$record.Lease){try{$record.Lease.Dispose()}catch{if($null-eq$failure){$failure=$_.Exception}else{[Environment]::FailFast("SYNAPSE_BROKER_DECOMMISSION_HISTORY_RELEASE_MULTIPLE_FAILURES context=$Context",$_.Exception)}};$record.Lease=$null}}
    if($null-ne$failure){[Environment]::FailFast("SYNAPSE_BROKER_DECOMMISSION_HISTORY_RELEASE_UNPROVEN context=$Context",$failure)}
}

function ConvertTo-SynapseBrokerDecommissionPowerShellDescriptor {
    param([Parameter(Mandatory=$true)]$PowerShell)
    return [ordered]@{role='broker_powershell';path=[System.IO.Path]::GetFullPath([string]$PowerShell.Path);file_id_128=([string]$PowerShell.FileId128).ToUpperInvariant();sha256=([string]$PowerShell.Sha256).ToUpperInvariant();length=[int64]$PowerShell.Length;parent_path=(Get-SynapseNormalizedDirectoryPath -Path ([string]$PowerShell.ParentPath));parent_file_id_128=([string]$PowerShell.ParentFileId128).ToUpperInvariant();protected_os=(ConvertTo-SynapseCanonicalValue -Value $PowerShell.ProtectedOs)}
}

function Assert-SynapseBrokerDecommissionFileDescriptorStructural {
    param([Parameter(Mandatory=$true)]$Descriptor,[Parameter(Mandatory=$true)][string]$ExpectedRole,[switch]$ProtectedOs,[Parameter(Mandatory=$true)][string]$Context)
    $expected=if($ProtectedOs){@('role','path','file_id_128','sha256','length','parent_path','parent_file_id_128','protected_os')}else{@('role','path','file_id_128','sha256','length','parent_path','parent_file_id_128')}
    Assert-SynapsePurgeExactPropertySet -Value $Descriptor -Expected $expected -Context $Context
    $path=[IO.Path]::GetFullPath([string]$Descriptor.path);$parent=Get-SynapseNormalizedDirectoryPath -Path ([string]$Descriptor.parent_path)
    if([string]$Descriptor.role-cne$ExpectedRole-or$parent-ine[IO.Path]::GetFullPath((Split-Path -Parent $path))-or[string]$Descriptor.file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'-or[string]$Descriptor.sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[int64]$Descriptor.length-lt1-or[string]$Descriptor.parent_file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'){Die "SYNAPSE_BROKER_DECOMMISSION_FILE_DESCRIPTOR_INVALID context=$Context role=$ExpectedRole path=$path"}
    if($ProtectedOs){$contract=$Descriptor.protected_os;Assert-SynapsePurgeExactPropertySet -Value $contract -Expected @('schema','link_count','security_descriptor_sddl','hardlink_paths','alias_parent_chains') -Context "${Context}_protected_os";if([string]$contract.schema-cne'synapse_protected_os_interpreter/v1'-or[int]$contract.link_count-ne2-or[string]::IsNullOrWhiteSpace([string]$contract.security_descriptor_sddl)-or@($contract.hardlink_paths).Count-ne2-or@($contract.alias_parent_chains).Count-ne2){Die "SYNAPSE_BROKER_DECOMMISSION_PROTECTED_OS_DESCRIPTOR_INVALID context=$Context path=$path"}}
    return $Descriptor
}

function ConvertTo-SynapseBrokerDecommissionRetainedLegacyAuthority {
    param([Parameter(Mandatory=$true)]$Authority)
    $initial=$Authority.Initial;$commitSlots=@($Authority.Journal.Slots|Where-Object State -CEQ 'commit_decided')
    if($commitSlots.Count-ne1-or[string]$initial.prior_authority-cnotin@('legacy','absent')){Die 'SYNAPSE_BROKER_DECOMMISSION_RETAINED_LEGACY_SOURCE_INVALID'}
    $commitSlot=$commitSlots[0];$previousSlots=@($Authority.Journal.Slots|Where-Object Sequence -EQ ([int]$commitSlot.Sequence-1));if([int]$commitSlot.Sequence-lt2-or$previousSlots.Count-ne1){Die 'SYNAPSE_BROKER_DECOMMISSION_RETAINED_LEGACY_COMMIT_PREDECESSOR_INVALID'}
    $gate=$initial.legacy_gate_transition;$denial=$initial.legacy_denial_stub_transition
    return [ordered]@{
        schema='synapse_broker_decommission_retained_legacy_authority/v1'
        policy=$(if([string]$initial.prior_authority-ceq'legacy'){'retain_exact_legacy_task_under_permanent_denial'}else{'retain_fresh_monotonic_floor'})
        prior_authority=[string]$initial.prior_authority
        source=[ordered]@{transaction_root=[string]$initial.transaction_root;transaction_root_file_id_128=([string]$initial.transaction_root_file_id_128).ToUpperInvariant();invocation_id=[string]$initial.invocation_id;commit_slot_sequence=[int]$commitSlot.Sequence;commit_slot_previous_sha256=([string]$previousSlots[0].RawSha256).ToUpperInvariant();commit_slot_sha256=([string]$commitSlot.RawSha256).ToUpperInvariant();commit_slot_length=[int64]$commitSlot.ByteLength;commit_payload=(ConvertTo-SynapseCanonicalValue -Value $commitSlot.Payload);legacy_denial_pre_existed=[bool]$denial.pre_existed;legacy_denial_pre_file_id_128=[string]$denial.pre_file_id_128;legacy_denial_pre_sha256=[string]$denial.pre_sha256;legacy_denial_pre_length=[int64]$denial.pre_length}
        legacy_task=$(if($null-eq$initial.legacy_task){$null}else{ConvertTo-SynapseCanonicalValue -Value $initial.legacy_task})
        legacy_gate=[ordered]@{path=[IO.Path]::GetFullPath([string]$gate.path);parent_path=(Get-SynapseNormalizedDirectoryPath -Path ([string]$gate.parent));parent_file_id_128=([string]$gate.parent_chain[-1].file_id_128).ToUpperInvariant();file_id_128=([string]$gate.post_file_id_128).ToUpperInvariant();sha256=([string]$gate.post_sha256).ToUpperInvariant();length=[int64]$gate.post_length}
        legacy_denial_stub=[ordered]@{path=[IO.Path]::GetFullPath([string]$denial.path);parent_path=(Get-SynapseNormalizedDirectoryPath -Path ([string]$denial.parent));parent_file_id_128=([string]$denial.parent_chain[-1].file_id_128).ToUpperInvariant();file_id_128=([string]$denial.post_file_id_128).ToUpperInvariant();sha256=([string]$denial.post_sha256).ToUpperInvariant();length=[int64]$denial.post_length}
    }
}

function Assert-SynapseBrokerDecommissionRetainedLegacyAuthorityDescriptor {
    param([Parameter(Mandatory=$true)]$Descriptor,[Parameter(Mandatory=$true)]$AuthorizedPayload,[Parameter(Mandatory=$true)][string]$Context)
    $normalizedDescriptor=$Descriptor;$legacyVbsProjectedLengthMigrated=$false
    Assert-SynapsePurgeExactPropertySet -Value $Descriptor -Expected @('schema','policy','prior_authority','source','legacy_task','legacy_gate','legacy_denial_stub') -Context $Context
    $prior=[string]$Descriptor.prior_authority;$expectedPolicy=if($prior-ceq'legacy'){'retain_exact_legacy_task_under_permanent_denial'}elseif($prior-ceq'absent'){'retain_fresh_monotonic_floor'}else{''}
    if([string]$Descriptor.schema-cne'synapse_broker_decommission_retained_legacy_authority/v1'-or[string]$Descriptor.policy-cne$expectedPolicy){Die "SYNAPSE_BROKER_DECOMMISSION_RETAINED_LEGACY_POLICY_INVALID context=$Context prior=$prior"}
    Assert-SynapsePurgeExactPropertySet -Value $Descriptor.source -Expected @('transaction_root','transaction_root_file_id_128','invocation_id','commit_slot_sequence','commit_slot_previous_sha256','commit_slot_sha256','commit_slot_length','commit_payload','legacy_denial_pre_existed','legacy_denial_pre_file_id_128','legacy_denial_pre_sha256','legacy_denial_pre_length') -Context "${Context}_source"
    $source=$Descriptor.source;$commit=$source.commit_payload
    $rebuiltCommit=New-SynapseDeploymentTransactionJournalSlotText -Sequence ([int]$source.commit_slot_sequence) -InvocationId ([string]$source.invocation_id) -TransactionRoot ([string]$source.transaction_root) -PreviousSlotSha256 ([string]$source.commit_slot_previous_sha256) -Payload $commit;$commitSha=(Get-SynapseSha256Hex -Text ([string]$rebuiltCommit.Text)).ToUpperInvariant()
    if(-not[IO.Path]::IsPathFullyQualified([string]$source.transaction_root)-or[string]$source.transaction_root_file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'-or[string]::IsNullOrWhiteSpace([string]$source.invocation_id)-or[int]$source.commit_slot_sequence-lt2-or[int]$source.commit_slot_sequence-gt4-or[string]$source.commit_slot_previous_sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[string]$source.commit_slot_sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[string]$source.commit_slot_sha256-ine$commitSha-or[int64]$source.commit_slot_length-ne[int64]$rebuiltCommit.ByteLength-or-not($source.legacy_denial_pre_existed-is[bool])-or[string]$commit.state-cne'commit_decided'-or[string]$commit.detail.prior_authority-cne$prior-or[string]$commit.detail.broker_identity_sha256-ine[string]$AuthorizedPayload.broker_identity_sha256-or[int64]$commit.detail.authority_epoch-ne[int64]$AuthorizedPayload.authority_epoch-or[string]$commit.detail.control_nonce-ine[string]$AuthorizedPayload.control_nonce){Die "SYNAPSE_BROKER_DECOMMISSION_RETAINED_LEGACY_SOURCE_INVALID context=$Context"}
    if(([bool]$source.legacy_denial_pre_existed-and([string]$source.legacy_denial_pre_file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'-or[string]$source.legacy_denial_pre_sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[int64]$source.legacy_denial_pre_length-lt1))-or(-not[bool]$source.legacy_denial_pre_existed-and([string]$source.legacy_denial_pre_file_id_128-or[string]$source.legacy_denial_pre_sha256-or[int64]$source.legacy_denial_pre_length-ne-1))){Die "SYNAPSE_BROKER_DECOMMISSION_RETAINED_LEGACY_PREIMAGE_INVALID context=$Context"}
    $runtime=Get-SynapseNormalizedDirectoryPath -Path ([string]$AuthorizedPayload.runtime_bin_dir)
    foreach($item in @([pscustomobject]@{Value=$Descriptor.legacy_gate;Role='gate';Expected=(Join-Path $runtime $script:SynapseDaemonSupervisorStopRequestFileName)},[pscustomobject]@{Value=$Descriptor.legacy_denial_stub;Role='denial';Expected=(Join-Path $runtime 'synapse-daemon-supervisor.ps1')})){
        Assert-SynapsePurgeExactPropertySet -Value $item.Value -Expected @('path','parent_path','parent_file_id_128','file_id_128','sha256','length') -Context "${Context}_$($item.Role)"
        if([IO.Path]::GetFullPath([string]$item.Value.path)-ine[IO.Path]::GetFullPath([string]$item.Expected)-or(Get-SynapseNormalizedDirectoryPath -Path ([string]$item.Value.parent_path))-ine$runtime-or[string]$item.Value.parent_file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'-or[string]$item.Value.file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'-or[string]$item.Value.sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[int64]$item.Value.length-lt1){Die "SYNAPSE_BROKER_DECOMMISSION_RETAINED_LEGACY_FILE_INVALID context=$Context role=$($item.Role)"}
    }
    if([string]$commit.detail.legacy_gate_file_id_128-ine[string]$Descriptor.legacy_gate.file_id_128-or[string]$commit.detail.legacy_gate_sha256-ine[string]$Descriptor.legacy_gate.sha256-or[int64]$commit.detail.legacy_gate_length-ne[int64]$Descriptor.legacy_gate.length-or[string]$commit.detail.legacy_denial_stub_file_id_128-ine[string]$Descriptor.legacy_denial_stub.file_id_128-or[string]$commit.detail.legacy_denial_stub_sha256-ine[string]$Descriptor.legacy_denial_stub.sha256-or[int64]$commit.detail.legacy_denial_stub_length-ne[int64]$Descriptor.legacy_denial_stub.length){Die "SYNAPSE_BROKER_DECOMMISSION_RETAINED_LEGACY_COMMIT_CROSSBIND_INVALID context=$Context"}
    $expectedDenial=New-SynapseLegacyAuthorityDenialStubContent -BrokerIdentitySha256 ([string]$AuthorizedPayload.broker_identity_sha256) -AuthorityEpoch ([int64]$AuthorizedPayload.authority_epoch) -TaskCapabilitySha256 ([string]$AuthorizedPayload.task_capability_sha256)
    if((Get-SynapseSha256Hex -Text $expectedDenial)-ine[string]$Descriptor.legacy_denial_stub.sha256-or[Text.UTF8Encoding]::new($false,$true).GetByteCount($expectedDenial)-ne[int64]$Descriptor.legacy_denial_stub.length){Die "SYNAPSE_BROKER_DECOMMISSION_RETAINED_DENIAL_CONTENT_INVALID context=$Context"}
    if($prior-ceq'absent'){
        if($null-ne$Descriptor.legacy_task){Die "SYNAPSE_BROKER_DECOMMISSION_FRESH_LEGACY_TASK_INVALID context=$Context"}
    }else{
        $task=$Descriptor.legacy_task;$expected=@('name','xml','xml_sha256','security_descriptor','security_descriptor_sha256','execute','arguments','working_directory','state','enabled','scheduler_contract','supervisor_compatibility_contract','native_bootstrap','launcher_objects')
        $hasLegacyToolCount=$null-ne(Get-SynapseObjectPropertyValue -Object $task -Names @('expected_tool_count'));$hasLegacyToolSha=$null-ne(Get-SynapseObjectPropertyValue -Object $task -Names @('expected_tool_surface_sha256'))
        if($hasLegacyToolCount-xor$hasLegacyToolSha){Die "SYNAPSE_BROKER_DECOMMISSION_RETAINED_LEGACY_TOOL_SURFACE_PARTIAL context=$Context"}
        if($hasLegacyToolCount){$expected+=@('expected_tool_count','expected_tool_surface_sha256')}
        Assert-SynapsePurgeExactPropertySet -Value $task -Expected $expected -Context "${Context}_legacy_task"
        if($hasLegacyToolCount-and([int]$task.expected_tool_count-ne40-or[string]$task.expected_tool_surface_sha256-notmatch'^[0-9A-Fa-f]{64}$')){Die "SYNAPSE_BROKER_DECOMMISSION_RETAINED_LEGACY_TOOL_SURFACE_INVALID context=$Context count=$($task.expected_tool_count) sha=$($task.expected_tool_surface_sha256)"}
        if([string]$task.name-cne[string]$AuthorizedPayload.legacy_task_name-or-not[bool]$task.enabled-or[bool]$task.native_bootstrap-or(Get-SynapseSha256Hex -Text ([string]$task.xml))-ine[string]$task.xml_sha256-or(Get-SynapseSha256Hex -Text ([string]$task.security_descriptor))-ine[string]$task.security_descriptor_sha256){Die "SYNAPSE_BROKER_DECOMMISSION_RETAINED_LEGACY_TASK_INVALID context=$Context task=$($task.name)"}
        [void](Assert-SynapseLegacyDirectRescueSchedulerContractDescriptor -Contract $task.scheduler_contract -Context "${Context}_legacy_scheduler")
        $launchers=@($task.launcher_objects);$roles=@($launchers|ForEach-Object{[string]$_.role}|Sort-Object);$expectedRoles=@('legacy_supervisor','legacy_supervisor_interpreter','legacy_task_interpreter','legacy_vbs_launcher')|Sort-Object
        if($launchers.Count-ne4-or($roles-join',')-cne($expectedRoles-join',')){Die "SYNAPSE_BROKER_DECOMMISSION_RETAINED_LEGACY_LAUNCHER_ROSTER_INVALID context=$Context roles=$($roles-join',')"}
        foreach($launcher in $launchers){$role=[string]$launcher.role;if(Test-SynapseProtectedOsInterpreterRole -Role $role){[void](Assert-SynapseBrokerDecommissionFileDescriptorStructural -Descriptor $launcher -ExpectedRole $role -ProtectedOs -Context "${Context}_$role")}else{[void](Assert-SynapseBrokerDecommissionFileDescriptorStructural -Descriptor $launcher -ExpectedRole $role -Context "${Context}_$role")}}
        $supervisor=@($launchers|Where-Object role -CEQ 'legacy_supervisor')[0];$vbs=@($launchers|Where-Object role -CEQ 'legacy_vbs_launcher')[0];$wscript=@($launchers|Where-Object role -CEQ 'legacy_task_interpreter')[0];$powerShell=@($launchers|Where-Object role -CEQ 'legacy_supervisor_interpreter')[0]
        if(-not[bool]$source.legacy_denial_pre_existed-or[string]$supervisor.path-ine[string]$Descriptor.legacy_denial_stub.path-or[string]$supervisor.file_id_128-ine[string]$source.legacy_denial_pre_file_id_128-or[string]$supervisor.sha256-ine[string]$source.legacy_denial_pre_sha256-or[int64]$supervisor.length-ne[int64]$source.legacy_denial_pre_length-or[IO.Path]::GetFullPath([string]$task.execute)-ine[IO.Path]::GetFullPath([string]$wscript.path)-or[string]$task.arguments-cne("//B //Nologo `"$([IO.Path]::GetFullPath([string]$vbs.path))`"") ){Die "SYNAPSE_BROKER_DECOMMISSION_RETAINED_LEGACY_LAUNCH_CHAIN_INVALID context=$Context"}
        [void](Assert-SynapseLegacySupervisorCompatibilityContractDescriptor -Contract $task.supervisor_compatibility_contract -SupervisorDescriptor $supervisor -Context "${Context}_supervisor_compatibility")
        $assignments=$task.supervisor_compatibility_contract.assignments;$expectedVbs=New-SynapseLegacyVbsLauncherContent -LauncherLogPath ([string]$assignments.LauncherLog) -SupervisorPath ([string]$Descriptor.legacy_denial_stub.path) -PowerShellPath ([string]$powerShell.path);$expectedVbsSha=(Get-SynapseSha256Hex -Text $expectedVbs).ToUpperInvariant();$expectedVbsLength=[Text.UTF8Encoding]::new($false,$true).GetByteCount($expectedVbs)
        if([int64]$vbs.length-eq1-and[string]$vbs.sha256-ieq$expectedVbsSha-and$expectedVbsLength-gt1){
            $vbsParent=Get-SynapseNormalizedDirectoryPath -Path ([string]$vbs.parent_path);$vbsParentChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $vbsParent);$vbsState=Get-SynapsePhysicalRelativeState -ParentPath $vbsParent -ParentChain $vbsParentChain -Leaf (Split-Path -Leaf ([string]$vbs.path))
            if(-not[bool]$vbsState.Exists-or[bool]$vbsState.IsDirectory-or[string]$vbsParentChain[-1].file_id_128-ine[string]$vbs.parent_file_id_128-or[string]$vbsState.FileId128-ine[string]$vbs.file_id_128-or[string]$vbsState.Sha256-ine$expectedVbsSha-or[int64]$vbsState.Length-ne$expectedVbsLength){Die "SYNAPSE_BROKER_DECOMMISSION_RETAINED_LEGACY_VBS_PROJECTION_MIGRATION_INVALID context=$Context"}
            Info "SYNAPSE_BROKER_DECOMMISSION_RETAINED_LEGACY_VBS_LENGTH_PROJECTION_MIGRATION context=$Context path=$($vbs.path) projected_length=1 physical_length=$expectedVbsLength sha256=$expectedVbsSha"
            $legacyVbsProjectedLengthMigrated=$true
        }
        if($expectedVbsSha-ine[string]$vbs.sha256-or(-not$legacyVbsProjectedLengthMigrated-and$expectedVbsLength-ne[int64]$vbs.length)){Die "SYNAPSE_BROKER_DECOMMISSION_RETAINED_LEGACY_VBS_INVALID context=$Context"}
        if($legacyVbsProjectedLengthMigrated){$normalizedDescriptor=ConvertTo-SynapseCanonicalValue -Value $Descriptor;$normalizedVbs=@($normalizedDescriptor.legacy_task.launcher_objects|Where-Object role -CEQ 'legacy_vbs_launcher');if($normalizedVbs.Count-ne1){Die "SYNAPSE_BROKER_DECOMMISSION_RETAINED_LEGACY_VBS_PROJECTION_ROSTER_INVALID context=$Context"};$normalizedVbs[0].length=[int64]$expectedVbsLength}
    }
    return $normalizedDescriptor
}

function Open-SynapseBrokerDecommissionRetainedLegacyAuthorityLeases {
    param([Parameter(Mandatory=$true)]$Authorized,[Parameter(Mandatory=$true)][string]$Context)
    $d=Assert-SynapseBrokerDecommissionRetainedLegacyAuthorityDescriptor -Descriptor $Authorized.Payload.retained_legacy_authority -AuthorizedPayload $Authorized.Payload -Context $Context;$leases=@();$launcherFileLeases=@();$protectedBundles=@();$result=$null;$returning=$false
    try{
        foreach($item in @($d.legacy_gate,$d.legacy_denial_stub)){$parent=Get-SynapseNormalizedDirectoryPath -Path ([string]$item.parent_path);$chain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $parent);if([string]$chain[-1].file_id_128-ine[string]$item.parent_file_id_128){Die "SYNAPSE_BROKER_DECOMMISSION_RETAINED_LEGACY_PARENT_DRIFT context=$Context path=$($item.path)"};$leases+=,(Open-SynapsePhysicalFileReadLease -ParentPath $parent -ParentChain $chain -Leaf (Split-Path -Leaf ([string]$item.path)) -ExpectedFileId128 ([string]$item.file_id_128) -ExpectedSha256 ([string]$item.sha256) -ExpectedLength ([int64]$item.length) -Context $Context)}
        if([string]$d.prior_authority-ceq'legacy'){
            foreach($launcher in @($d.legacy_task.launcher_objects|Where-Object role -CNE 'legacy_supervisor')){
                $role=[string]$launcher.role
                if(Test-SynapseProtectedOsInterpreterRole -Role $role){$protectedBundles+=,(Open-SynapseProtectedOsInterpreterAliasLeaseBundle -Descriptor $launcher -ExpectedRole $role -Context "${Context}_$role")}
                else{$parent=Get-SynapseNormalizedDirectoryPath -Path ([string]$launcher.parent_path);$chain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $parent);if([string]$chain[-1].file_id_128-ine[string]$launcher.parent_file_id_128){Die "SYNAPSE_BROKER_DECOMMISSION_RETAINED_LAUNCHER_PARENT_DRIFT context=$Context role=$role"};$launcherFileLeases+=,(Open-SynapsePhysicalFileReadLease -ParentPath $parent -ParentChain $chain -Leaf (Split-Path -Leaf ([string]$launcher.path)) -ExpectedFileId128 ([string]$launcher.file_id_128) -ExpectedSha256 ([string]$launcher.sha256) -ExpectedLength ([int64]$launcher.length) -Context "${Context}_$role")}
            }
        }
        $result=[pscustomobject][ordered]@{Gate=$leases[0];Denial=$leases[1];LauncherFileLeases=@($launcherFileLeases);ProtectedBundles=@($protectedBundles);Descriptor=$d};[void](Assert-SynapseBrokerDecommissionRetainedLegacyAuthorityHeld -Authorized $Authorized -Leases $result -Context $Context);$returning=$true;return $result
    }finally{if(-not$returning){foreach($bundle in $protectedBundles){Close-SynapseProtectedOsInterpreterAliasLeaseBundle -Bundle $bundle -Context "${Context}_failure"};foreach($lease in @($launcherFileLeases)+@($leases)){try{$lease.Dispose()}catch{[Environment]::FailFast('SYNAPSE_BROKER_DECOMMISSION_RETAINED_LEGACY_LEASE_RELEASE_UNPROVEN',$_.Exception)}}}}
}

function Assert-SynapseBrokerDecommissionRetainedLegacyAuthorityHeld {
    param([Parameter(Mandatory=$true)]$Authorized,[Parameter(Mandatory=$true)]$Leases,[Parameter(Mandatory=$true)][string]$Context)
    $d=Assert-SynapseBrokerDecommissionRetainedLegacyAuthorityDescriptor -Descriptor $Authorized.Payload.retained_legacy_authority -AuthorizedPayload $Authorized.Payload -Context $Context
    $Leases.Gate.RequireExact("${Context}_gate");$Leases.Denial.RequireExact("${Context}_denial")
    $gateText=[string]$Leases.Gate.ReadUtf8(65536).Content;try{$gatePayload=$gateText|ConvertFrom-Json -ErrorAction Stop}catch{Die "SYNAPSE_BROKER_DECOMMISSION_RETAINED_GATE_JSON_INVALID context=$Context error=$($_.Exception.Message)"};Assert-SynapsePurgeExactPropertySet -Value $gatePayload -Expected @('schema','state','reason','bind','db_path','supervisor_path','requested_by_pid','requested_at_utc','broker_identity_sha256','authority_epoch','authority_state','invocation_id') -Context "${Context}_gate_payload"
    if((Get-SynapseCanonicalJson -Value (ConvertTo-SynapseCanonicalValue -Value $gatePayload))-cne$gateText-or[string]$gatePayload.schema-cne'synapse_daemon_supervisor_stop_request/v1'-or[string]$gatePayload.state-cne'requested'-or[string]$gatePayload.reason-cne'broker_authority_adoption_epoch'-or[string]$gatePayload.bind-cne[string]$Authorized.Payload.bind-or[IO.Path]::GetFullPath([string]$gatePayload.db_path)-ine[IO.Path]::GetFullPath([string]$Authorized.Payload.db_path)-or[IO.Path]::GetFullPath([string]$gatePayload.supervisor_path)-ine[IO.Path]::GetFullPath([string]$d.legacy_denial_stub.path)-or[int]$gatePayload.requested_by_pid-lt1-or[string]$gatePayload.broker_identity_sha256-ine[string]$Authorized.Payload.broker_identity_sha256-or[int64]$gatePayload.authority_epoch-ne[int64]$Authorized.Payload.authority_epoch-or[string]$gatePayload.authority_state-cne'adoption_epoch'-or[string]$gatePayload.invocation_id-cne[string]$d.source.invocation_id){Die "SYNAPSE_BROKER_DECOMMISSION_RETAINED_GATE_PAYLOAD_INVALID context=$Context"};[void](Assert-SynapseBrokerDecommissionUtcTimestamp -Value $gatePayload.requested_at_utc -Context "${Context}_gate_requested_at")
    foreach($lease in @($Leases.LauncherFileLeases)){$lease.RequireExact("${Context}_launcher")};foreach($bundle in @($Leases.ProtectedBundles)){foreach($lease in @($bundle.Leases)){$lease.RequireExact("${Context}_protected_launcher")}}
    $lookup=Get-SynapseScheduledTaskLookupExact -Name ([string]$Authorized.Payload.legacy_task_name)
    if([string]$d.prior_authority-ceq'legacy'){
        if(-not[bool]$lookup.Exists){Die "SYNAPSE_BROKER_DECOMMISSION_RETAINED_LEGACY_TASK_ABSENT context=$Context task=$($Authorized.Payload.legacy_task_name)"}
        $runtime=Read-SynapseLegacyDirectRescueTaskRuntimeState -LegacySnapshot $d.legacy_task -Context "${Context}_legacy_runtime"
        if([int]$runtime.State-ne3-or[int]$runtime.InstanceCount-ne0){Die "SYNAPSE_BROKER_DECOMMISSION_RETAINED_LEGACY_TASK_NOT_READY context=$Context task=$($Authorized.Payload.legacy_task_name) state=$($runtime.State) instances=$($runtime.InstanceCount)"}
    }elseif([bool]$lookup.Exists){Die "SYNAPSE_BROKER_DECOMMISSION_FRESH_LEGACY_TASK_REAPPEARED context=$Context task=$($Authorized.Payload.legacy_task_name)"}
    return $d
}

function Close-SynapseBrokerDecommissionRetainedLegacyAuthorityLeases {
    param($Leases)
    if($null-eq$Leases){return};$primary=$null
    foreach($bundle in @($Leases.ProtectedBundles)){try{Close-SynapseProtectedOsInterpreterAliasLeaseBundle -Bundle $bundle -Context 'broker_decommission_retained_legacy_close'}catch{if($null-eq$primary){$primary=$_.Exception}else{[Environment]::FailFast('SYNAPSE_BROKER_DECOMMISSION_RETAINED_LEGACY_MULTIPLE_RELEASE_FAILURES',$_.Exception)}}}
    foreach($lease in @($Leases.LauncherFileLeases)+@($Leases.Denial,$Leases.Gate)){if($null-ne$lease){try{$lease.Dispose()}catch{if($null-eq$primary){$primary=$_.Exception}else{[Environment]::FailFast('SYNAPSE_BROKER_DECOMMISSION_RETAINED_LEGACY_MULTIPLE_RELEASE_FAILURES',$_.Exception)}}}}
    if($null-ne$primary){[Environment]::FailFast('SYNAPSE_BROKER_DECOMMISSION_RETAINED_LEGACY_RELEASE_UNPROVEN',$primary)}
}

function ConvertTo-SynapseBrokerDecommissionTaskReceiptEvidence {
    param([Parameter(Mandatory=$true)]$Infrastructure)
    $journal=$Infrastructure.TaskReceipt.Journal
    if($null-eq$journal-or[string]$journal.State-cne'commit_decided'-or@($journal.Slots).Count-lt3){Die 'SYNAPSE_BROKER_DECOMMISSION_TASK_RECEIPT_EVIDENCE_SOURCE_INVALID'}
    $core=[ordered]@{schema='synapse_broker_task_receipt_evidence/v1';slot1=(ConvertTo-SynapseCanonicalValue -Value $journal.Slots[0].Payload);slot2=(ConvertTo-SynapseCanonicalValue -Value $journal.Slots[1].Payload);slot3=(ConvertTo-SynapseCanonicalValue -Value $journal.Slots[2].Payload)}
    $core.evidence_sha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $core)).ToUpperInvariant();return $core
}

function Assert-SynapseBrokerDecommissionTaskReceiptEvidence {
    param([Parameter(Mandatory=$true)]$Evidence,[Parameter(Mandatory=$true)]$ReceiptDescriptor,[Parameter(Mandatory=$true)]$Receipt,[Parameter(Mandatory=$true)][string]$TaskCapabilitySha256,[Parameter(Mandatory=$true)][string]$TaskName,[Parameter(Mandatory=$true)][string]$Context,[switch]$StructuralOnly)
    Assert-SynapsePurgeExactPropertySet -Value $Evidence -Expected @('schema','slot1','slot2','slot3','evidence_sha256') -Context $Context
    if([string]$Evidence.schema-cne'synapse_broker_task_receipt_evidence/v1'-or[string]$Evidence.evidence_sha256-notmatch'^[0-9A-Fa-f]{64}$'){Die "SYNAPSE_BROKER_DECOMMISSION_TASK_RECEIPT_EVIDENCE_INVALID context=$Context"}
    $core=ConvertTo-SynapseCanonicalValue -Value $Evidence;[void]$core.Remove('evidence_sha256');if((Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $core))-ine[string]$Evidence.evidence_sha256){Die "SYNAPSE_BROKER_DECOMMISSION_TASK_RECEIPT_EVIDENCE_HASH_INVALID context=$Context"}
    if([string]$Evidence.slot1.state-cne'armed'-or[string]$Evidence.slot1.schema-cne'synapse_broker_task_create_transaction/v1'-or[string]$Evidence.slot1.transaction_kind-cne'synapse_broker_task_create/v1'-or[string]$Evidence.slot1.task_capability_sha256-ine$TaskCapabilitySha256-or[string]$Evidence.slot1.task.name-cne$TaskName-or[string]$Evidence.slot2.state-cne'candidate_ready'-or[string]$Evidence.slot2.detail.task_capability_sha256-ine$TaskCapabilitySha256-or[string]$Evidence.slot2.detail.task_name-cne$TaskName-or[string]$Evidence.slot3.state-cne'commit_decided'-or[string]$Evidence.slot3.detail.task_capability_sha256-ine$TaskCapabilitySha256-or[string]$Evidence.slot3.detail.task_name-cne$TaskName){Die "SYNAPSE_BROKER_DECOMMISSION_TASK_RECEIPT_EVIDENCE_CROSSBIND_INVALID context=$Context"}
    $invocationId=[string]$Evidence.slot1.invocation_id
    if([string]::IsNullOrWhiteSpace($invocationId)){Die "SYNAPSE_BROKER_DECOMMISSION_TASK_RECEIPT_EVIDENCE_INVOCATION_INVALID context=$Context"}
    if(-not$StructuralOnly){
        foreach($binding in @(@{Name='slot1';Sequence=1},@{Name='slot2';Sequence=2},@{Name='slot3';Sequence=3})){
            $declared=$ReceiptDescriptor.($binding.Name);$physical=@($Receipt.Journal.Slots|Where-Object Sequence -EQ ([int]$binding.Sequence))
            if($physical.Count-ne1-or[int]$declared.sequence-ne[int]$binding.Sequence-or[string]$declared.leaf-cne[string]$physical[0].Leaf-or[string]$declared.file_id_128-ine[string]$physical[0].FileId128-or[string]$declared.sha256-ine[string]$physical[0].RawSha256-or[int64]$declared.length-ne[int64]$physical[0].ByteLength){Die "SYNAPSE_BROKER_DECOMMISSION_TASK_RECEIPT_EVIDENCE_SLOT_BIND_INVALID context=$Context slot=$($binding.Sequence) physical_count=$($physical.Count) declared_sequence=$($declared.sequence) declared_leaf=$($declared.leaf) physical_leaf=$($physical[0].Leaf) declared_file_id=$($declared.file_id_128) physical_file_id=$($physical[0].FileId128) declared_sha=$($declared.sha256) physical_sha=$($physical[0].RawSha256) declared_length=$($declared.length) physical_length=$($physical[0].ByteLength)"}
        }
        if((Get-SynapseCanonicalJson -Value $Evidence.slot1)-cne(Get-SynapseCanonicalJson -Value $Receipt.Journal.Slots[0].Payload)-or(Get-SynapseCanonicalJson -Value $Evidence.slot2)-cne(Get-SynapseCanonicalJson -Value $Receipt.Journal.Slots[1].Payload)-or(Get-SynapseCanonicalJson -Value $Evidence.slot3)-cne(Get-SynapseCanonicalJson -Value $Receipt.Journal.Slots[2].Payload)){Die "SYNAPSE_BROKER_DECOMMISSION_TASK_RECEIPT_EVIDENCE_PHYSICAL_DRIFT context=$Context"}
    }
    return $Evidence
}

function Assert-SynapseBrokerDecommissionTokenAuthorityDescriptor {
    param(
        [Parameter(Mandatory=$true)]$Descriptor,
        [Parameter(Mandatory=$true)][string]$ExpectedPath,
        [Parameter(Mandatory=$true)][string]$Context
    )
    Assert-SynapsePurgeExactPropertySet -Value $Descriptor -Expected @('schema','disposition','token') -Context $Context
    $disposition=[string]$Descriptor.disposition
    if([string]$Descriptor.schema-cne'synapse_broker_decommission_token_authority/v1'-or$disposition-cnotin@('authenticated_present','parked_exact_absence')){Die "SYNAPSE_BROKER_DECOMMISSION_TOKEN_AUTHORITY_INVALID context=$Context disposition=$disposition"}
    Assert-SynapsePurgeFileDescriptor -Descriptor $Descriptor.token -ExpectedPath $ExpectedPath -Context "${Context}_token"
    if(($disposition-ceq'authenticated_present'-and-not[bool]$Descriptor.token.exists)-or($disposition-ceq'parked_exact_absence'-and[bool]$Descriptor.token.exists)){Die "SYNAPSE_BROKER_DECOMMISSION_TOKEN_AUTHORITY_DISPOSITION_INVALID context=$Context disposition=$disposition exists=$([bool]$Descriptor.token.exists)"}
    return $Descriptor
}

function Open-SynapseBrokerDecommissionTokenAuthorityBoundary {
    param(
        [Parameter(Mandatory=$true)]$Descriptor,
        [Parameter(Mandatory=$true)][string]$ExpectedPath,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $d=Assert-SynapseBrokerDecommissionTokenAuthorityDescriptor -Descriptor $Descriptor -ExpectedPath $ExpectedPath -Context $Context
    if([string]$d.disposition-ceq'parked_exact_absence'){
        Assert-SynapsePurgeAbsenceAnchor -Anchor $d.token.absence -Context "${Context}_absence"
        return $null
    }
    $current=Get-SynapsePurgeFileSnapshot -Path $ExpectedPath -Context "${Context}_snapshot"
    if((Get-SynapseCanonicalJson -Value $current)-cne(Get-SynapseCanonicalJson -Value $d.token)){Die "SYNAPSE_BROKER_DECOMMISSION_TOKEN_AUTHORITY_DRIFT context=$Context path=$ExpectedPath"}
    return Open-SynapsePhysicalFileReadLease -ParentPath ([string]$d.token.parent) -ParentChain @($d.token.parent_chain) -Leaf ([string]$d.token.leaf) -ExpectedFileId128 ([string]$d.token.file_id_128) -ExpectedSha256 ([string]$d.token.sha256) -ExpectedLength ([int64]$d.token.length) -Context $Context
}

function Set-SynapseBrokerDecommissionGlobalTokenAuthorityBoundary {
    param(
        [Parameter(Mandatory=$true)]$Descriptor,
        [Parameter(Mandatory=$true)][string]$ExpectedPath,
        [Parameter(Mandatory=$true)][string]$Context
    )
    if($null-ne$script:SynapseBrokerDecommissionGlobalTokenBoundaryLease){Die "SYNAPSE_BROKER_DECOMMISSION_GLOBAL_TOKEN_LEASE_ALREADY_HELD context=$Context"}
    $d=Assert-SynapseBrokerDecommissionTokenAuthorityDescriptor -Descriptor $Descriptor -ExpectedPath $ExpectedPath -Context $Context
    $lease=$null;$transferred=$false
    try{
        $lease=Open-SynapseBrokerDecommissionTokenAuthorityBoundary -Descriptor $d -ExpectedPath $ExpectedPath -Context $Context
        if([string]$d.disposition-ceq'authenticated_present'-and$null-eq$lease){Die "SYNAPSE_BROKER_DECOMMISSION_GLOBAL_TOKEN_LEASE_MISSING context=$Context path=$ExpectedPath"}
        if([string]$d.disposition-ceq'parked_exact_absence'-and$null-ne$lease){Die "SYNAPSE_BROKER_DECOMMISSION_GLOBAL_TOKEN_ABSENCE_LEASE_UNEXPECTED context=$Context path=$ExpectedPath"}
        $script:SynapseBrokerDecommissionGlobalTokenBoundaryLease=$lease
        $transferred=$true
    }finally{if(-not$transferred-and$null-ne$lease){try{$lease.Dispose()}catch{[Environment]::FailFast('SYNAPSE_BROKER_DECOMMISSION_GLOBAL_TOKEN_LEASE_SETUP_RELEASE_UNPROVEN',$_.Exception)}}}
}

function Assert-SynapseBrokerDecommissionGlobalTokenAuthorityBoundary {
    param(
        [Parameter(Mandatory=$true)]$Descriptor,
        [Parameter(Mandatory=$true)][string]$ExpectedPath,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $d=Assert-SynapseBrokerDecommissionTokenAuthorityDescriptor -Descriptor $Descriptor -ExpectedPath $ExpectedPath -Context $Context
    if([string]$d.disposition-ceq'authenticated_present'){
        if($null-eq$script:SynapseBrokerDecommissionGlobalTokenBoundaryLease){Die "SYNAPSE_BROKER_DECOMMISSION_GLOBAL_TOKEN_LEASE_NOT_HELD context=$Context path=$ExpectedPath"}
        $script:SynapseBrokerDecommissionGlobalTokenBoundaryLease.RequireExact($Context)
    }else{
        if($null-ne$script:SynapseBrokerDecommissionGlobalTokenBoundaryLease){Die "SYNAPSE_BROKER_DECOMMISSION_GLOBAL_TOKEN_ABSENCE_LEASE_HELD context=$Context path=$ExpectedPath"}
        [void](Open-SynapseBrokerDecommissionTokenAuthorityBoundary -Descriptor $d -ExpectedPath $ExpectedPath -Context $Context)
    }
}

function Assert-SynapseBrokerDecommissionAuthorizedRecord {
    param([Parameter(Mandatory=$true)]$Record,[switch]$StructuralOnly,[Parameter(Mandatory=$true)][string]$Context)
    $p=$Record.Payload
    Assert-SynapsePurgeExactPropertySet -Value $p -Expected @('schema','state','decommission_id','history_sequence','previous_completed','mode','authority_source','record_root_file_id_128','broker_identity_sha256','task_capability_sha256','authority_epoch','control_nonce','generation_id','legacy_task_name','runtime_bin_dir','exe_path','log_dir','maintenance_lock_path','bootstrap_log_path','authority_root','task','task_receipt','task_receipt_evidence','bootstrap','powershell','broker_script','active_control_gate','active_roster','retained_legacy_authority','bind','db_path','profiles_dir','token_path','runtime_artifacts','database','profiles','profiles_ownership','token_authority','token','vault_snapshot','confirmed','authorized_at_utc','authorized_by_pid','authorized_by_user','record_sha256') -Context $Context
    $source=[string]$p.authority_source
    $sourceValid=($source-ceq'active_generation'-and[string]$p.generation_id-cmatch'^(prior|candidate)-[0-9a-f]{40}$')-or($source-ceq'legacy_parked_no_journal'-and[string]::IsNullOrEmpty([string]$p.generation_id)-and[string]$p.mode-ceq'remove')
    if([string]$p.schema-cne'synapse_broker_decommission_authorized/v2'-or[string]$p.state-cne'authorized_before_mutation'-or[string]$p.decommission_id-notmatch'^[0-9A-Fa-f]{64}$'-or[string]$Record.Leaf-cne("decommission-$($p.decommission_id)-authorized.json")-or[int64]$p.history_sequence-lt1-or[string]$p.mode-cnotin@('remove','remove_purge')-or-not$sourceValid-or[string]$p.record_root_file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'-or[string]$p.broker_identity_sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[string]$p.task_capability_sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[int64]$p.authority_epoch-lt1-or[string]$p.control_nonce-notmatch'^[0-9A-Fa-f]{64}$'-or-not($p.confirmed-is[bool])-or[int]$p.authorized_by_pid-lt1-or[string]::IsNullOrWhiteSpace([string]$p.authorized_by_user)){Die "SYNAPSE_BROKER_DECOMMISSION_AUTHORIZATION_INVALID context=$Context path=$($Record.Path) source=$source"}
    if([int64]$p.history_sequence-eq1){if($null-ne$p.previous_completed){Die "SYNAPSE_BROKER_DECOMMISSION_AUTHORIZATION_GENESIS_PREDECESSOR_INVALID context=$Context"}}else{Assert-SynapsePurgeExactPropertySet -Value $p.previous_completed -Expected @('leaf','file_id_128','sha256','length','record_sha256') -Context "${Context}_previous_completed";if([string]$p.previous_completed.leaf-cnotmatch'\Adecommission-[0-9A-F]{64}-completed\.json\z'-or[string]$p.previous_completed.file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'-or[string]$p.previous_completed.sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[int64]$p.previous_completed.length-lt1-or[string]$p.previous_completed.record_sha256-notmatch'^[0-9A-Fa-f]{64}$'){Die "SYNAPSE_BROKER_DECOMMISSION_AUTHORIZATION_PREDECESSOR_INVALID context=$Context"}}
    [void](Assert-SynapseBrokerDecommissionUtcTimestamp -Value $p.authorized_at_utc -Context "${Context}_authorized_at")
    [void](Assert-SynapseBrokerTaskDescriptorShape -Descriptor $p.task -BrokerIdentitySha256 ([string]$p.broker_identity_sha256) -TaskCapabilitySha256 ([string]$p.task_capability_sha256) -Context "${Context}_task")
    $runtime=Get-SynapseNormalizedDirectoryPath -Path ([string]$p.runtime_bin_dir);$authorityRoot=Get-SynapseNormalizedDirectoryPath -Path ([string]$p.authority_root.path);$expectedAuthorityRoot=Get-SynapseNormalizedDirectoryPath -Path (Join-Path $runtime $script:SynapseAuthorityRootLeaf)
    if([string]::IsNullOrWhiteSpace([string]$p.legacy_task_name)-or-not[IO.Path]::IsPathFullyQualified([string]$p.exe_path)-or-not[IO.Path]::IsPathFullyQualified([string]$p.log_dir)-or-not[IO.Path]::IsPathFullyQualified([string]$p.maintenance_lock_path)-or-not[IO.Path]::IsPathFullyQualified([string]$p.bootstrap_log_path)-or-not(Test-SynapsePathWithinOrEqual -Ancestor ([string]$p.log_dir) -Candidate ([string]$p.bootstrap_log_path))){Die "SYNAPSE_BROKER_DECOMMISSION_INVOCATION_TARGET_INVALID context=$Context"}
    Assert-SynapsePurgeExactPropertySet -Value $p.authority_root -Expected @('path','file_id_128') -Context "${Context}_authority_root"
    if($authorityRoot-ine$expectedAuthorityRoot-or[string]$p.authority_root.file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'){Die "SYNAPSE_BROKER_DECOMMISSION_AUTHORITY_ROOT_INVALID context=$Context path=$authorityRoot"}
    $receipt=Assert-SynapseBrokerTaskReceiptDescriptor -Descriptor $p.task_receipt -ExpectedAuthorityRoot $authorityRoot -ExpectedBrokerIdentitySha256 ([string]$p.broker_identity_sha256) -ExpectedTaskName ([string]$p.task.name) -StructuralOnly:$StructuralOnly
    if([string]$receipt.TaskCapabilitySha256-ine[string]$p.task_capability_sha256){Die "SYNAPSE_BROKER_DECOMMISSION_RECEIPT_CAPABILITY_DRIFT context=$Context"}
    [void](Assert-SynapseBrokerDecommissionTaskReceiptEvidence -Evidence $p.task_receipt_evidence -ReceiptDescriptor $p.task_receipt -Receipt $receipt -TaskCapabilitySha256 ([string]$p.task_capability_sha256) -TaskName ([string]$p.task.name) -Context "${Context}_task_receipt_evidence" -StructuralOnly:$StructuralOnly)
    [void](Assert-SynapseBrokerDecommissionFileDescriptorStructural -Descriptor $p.bootstrap -ExpectedRole broker_bootstrap -Context "${Context}_bootstrap")
    [void](Assert-SynapseBrokerDecommissionFileDescriptorStructural -Descriptor $p.broker_script -ExpectedRole broker_script -Context "${Context}_broker_script")
    [void](Assert-SynapseBrokerDecommissionFileDescriptorStructural -Descriptor $p.powershell -ExpectedRole broker_powershell -ProtectedOs -Context "${Context}_powershell")
    foreach($identity in @($p.active_control_gate,$p.active_roster)){Assert-SynapsePurgeExactPropertySet -Value $identity -Expected @('path','file_id_128','sha256','length') -Context "${Context}_control";if([string]$identity.file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'-or[string]$identity.sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[int64]$identity.length-lt1){Die "SYNAPSE_BROKER_DECOMMISSION_CONTROL_DESCRIPTOR_INVALID context=$Context"}}
    [void](Assert-SynapseBrokerDecommissionRetainedLegacyAuthorityDescriptor -Descriptor $p.retained_legacy_authority -AuthorizedPayload $p -Context "${Context}_retained_legacy")
    if([string]$p.retained_legacy_authority.prior_authority-ceq'legacy'-and[string]$p.task.name-ceq[string]$p.retained_legacy_authority.legacy_task.name){Die "SYNAPSE_BROKER_DECOMMISSION_TASK_AUTHORITY_ALIAS context=$Context task=$($p.task.name)"}
    $artifacts=@($p.runtime_artifacts);$seen=New-SynapseCaseInsensitiveMap
    $retainedFiles=@($p.retained_legacy_authority.legacy_gate,$p.retained_legacy_authority.legacy_denial_stub)+@($(if($null-ne$p.retained_legacy_authority.legacy_task){$p.retained_legacy_authority.legacy_task.launcher_objects}else{@()}))
    foreach($artifact in $artifacts){$role=[string]$artifact.role;[void](Assert-SynapseBrokerDecommissionFileDescriptorStructural -Descriptor $artifact -ExpectedRole $role -Context "${Context}_runtime_$role");$path=[IO.Path]::GetFullPath([string]$artifact.path);$aliases=@($retainedFiles|Where-Object{[IO.Path]::GetFullPath([string]$_.path)-ieq$path-or[string]$_.file_id_128-ieq[string]$artifact.file_id_128});if($seen.ContainsKey($path)-or-not(Test-SynapsePathWithinOrEqual -Ancestor $runtime -Candidate $path)-or$aliases.Count-ne0){Die "SYNAPSE_BROKER_DECOMMISSION_RUNTIME_ARTIFACT_SCOPE_INVALID context=$Context path=$path retained_alias_count=$($aliases.Count)"};$seen[$path]=$true}
    $recordRoot=Get-SynapseBrokerDecommissionRecordRoot;$recordRootChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $recordRoot)
    if([string]$recordRootChain[-1].file_id_128-ine[string]$p.record_root_file_id_128){Die "SYNAPSE_BROKER_DECOMMISSION_RECORD_ROOT_DRIFT context=$Context expected=$($p.record_root_file_id_128) actual=$($recordRootChain[-1].file_id_128)"}
    if($null-ne$Record.PSObject.Properties['RecordRootLease']-and$null-ne$Record.RecordRootLease){$Record.RecordRootLease.RequireExact("${Context}_record_root")}
    if(-not$StructuralOnly){if([System.IO.Directory]::Exists($authorityRoot)-eq$false){Die "SYNAPSE_BROKER_DECOMMISSION_PHYSICAL_AUTHORITY_INVALID context=$Context"};$authorityChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $authorityRoot);if([string]$authorityChain[-1].file_id_128-ine[string]$p.authority_root.file_id_128){Die "SYNAPSE_BROKER_DECOMMISSION_AUTHORITY_ROOT_DRIFT context=$Context"}}
    Assert-SynapsePurgeFileDescriptor -Descriptor $p.token -ExpectedPath ([string]$p.token_path) -Context "${Context}_token"
    $tokenAuthority=Assert-SynapseBrokerDecommissionTokenAuthorityDescriptor -Descriptor $p.token_authority -ExpectedPath ([string]$p.token_path) -Context "${Context}_token_authority"
    if((Get-SynapseCanonicalJson -Value $tokenAuthority.token)-cne(Get-SynapseCanonicalJson -Value $p.token)-or($source-ceq'active_generation'-and[string]$tokenAuthority.disposition-cne'authenticated_present')){Die "SYNAPSE_BROKER_DECOMMISSION_TOKEN_AUTHORITY_CROSSBIND_INVALID context=$Context source=$source disposition=$($tokenAuthority.disposition)"}
    if([string]$p.mode-ceq'remove'){
        if($artifacts.Count-ne0-or$null-ne$p.database-or$null-ne$p.profiles-or$null-ne$p.profiles_ownership-or$null-ne$p.vault_snapshot){Die "SYNAPSE_BROKER_DECOMMISSION_REMOVE_AUTHORIZATION_SCOPE_INVALID context=$Context"}
    }else{
        $daemonArtifacts=@($artifacts|Where-Object role -CEQ 'daemon');$bootstrapArtifacts=@($artifacts|Where-Object role -CEQ 'broker_bootstrap');$calyxArtifacts=@($artifacts|Where-Object role -CEQ 'calyx_config');$runtimeCompanions=@($artifacts|Where-Object{[string]$_.role-cmatch'\Aruntime_[a-z0-9_]+\z'});$unknownArtifacts=@($artifacts|Where-Object{[string]$_.role-cne'daemon'-and[string]$_.role-cne'broker_bootstrap'-and[string]$_.role-cne'calyx_config'-and[string]$_.role-cnotmatch'\Aruntime_[a-z0-9_]+\z'})
        if($daemonArtifacts.Count-ne1-or[IO.Path]::GetFullPath([string]$daemonArtifacts[0].path)-ine[IO.Path]::GetFullPath([string]$p.exe_path)-or$bootstrapArtifacts.Count-gt1-or$calyxArtifacts.Count-gt1-or$unknownArtifacts.Count-ne0-or($runtimeCompanions.Count+$daemonArtifacts.Count+$bootstrapArtifacts.Count+$calyxArtifacts.Count)-ne$artifacts.Count){Die "SYNAPSE_BROKER_DECOMMISSION_RUNTIME_ARTIFACT_ROSTER_INVALID context=$Context daemon=$($daemonArtifacts.Count) bootstrap=$($bootstrapArtifacts.Count) calyx=$($calyxArtifacts.Count) companions=$($runtimeCompanions.Count) unknown=$($unknownArtifacts.Count)"}
        if($bootstrapArtifacts.Count-eq1-and((Get-SynapseCanonicalJson -Value $bootstrapArtifacts[0])-cne(Get-SynapseCanonicalJson -Value $p.bootstrap))){Die "SYNAPSE_BROKER_DECOMMISSION_RUNTIME_BOOTSTRAP_DRIFT context=$Context"}
        Assert-SynapsePurgeDirectoryDescriptor -Descriptor $p.profiles -ExpectedPath ([string]$p.profiles_dir) -Context "${Context}_profiles"
        [void](Assert-SynapsePurgeProfilesOwnershipDescriptor -Descriptor $p.profiles_ownership -ProfilesPlan $p.profiles -Context "${Context}_profiles_ownership")
        Assert-SynapsePurgeDirectoryDescriptor -Descriptor $p.database -ExpectedPath ([string]$p.db_path) -Context "${Context}_database"
        if([string]$p.vault_snapshot.schema-cne'synapse_calyx_physical_snapshot/v2'-or[IO.Path]::GetFullPath([string]$p.vault_snapshot.path)-ine[IO.Path]::GetFullPath([string]$p.db_path)-or-not[bool]$p.vault_snapshot.bytes_complete-or-not[string]::IsNullOrWhiteSpace([string]$p.vault_snapshot.error)-or-not[string]::IsNullOrWhiteSpace([string]$p.vault_snapshot.current_manifest_error)){Die "SYNAPSE_BROKER_DECOMMISSION_VAULT_SNAPSHOT_INVALID context=$Context"}
    }
    if(-not$StructuralOnly){if([string]$p.mode-ceq'remove_purge'){$currentProfiles=Get-SynapsePurgeDirectorySnapshot -Path ([string]$p.profiles_dir) -Context "${Context}_profiles_physical";if((Get-SynapseCanonicalJson -Value $currentProfiles)-cne(Get-SynapseCanonicalJson -Value $p.profiles)){Die "SYNAPSE_BROKER_DECOMMISSION_PROFILES_DRIFT context=$Context"}};$currentToken=Get-SynapsePurgeFileSnapshot -Path ([string]$p.token_path) -Context "${Context}_token_physical";if((Get-SynapseCanonicalJson -Value $currentToken)-cne(Get-SynapseCanonicalJson -Value $p.token)){Die "SYNAPSE_BROKER_DECOMMISSION_TOKEN_DRIFT context=$Context"}}
    Assert-SynapseBrokerDecommissionRecordHash -Record $Record -Context $Context
    $runtimeArtifactsCanonical=if(@($p.runtime_artifacts).Count-eq0){'[]'}else{Get-SynapseCanonicalJson -Value @($p.runtime_artifacts)}
    $seed=[ordered]@{history_sequence=[int64]$p.history_sequence;previous_completed=$(if($null-eq$p.previous_completed){$null}else{ConvertTo-SynapseCanonicalValue -Value $p.previous_completed});mode=[string]$p.mode;authority_source=$source;record_root_file_id_128=([string]$p.record_root_file_id_128).ToUpperInvariant();broker_identity_sha256=([string]$p.broker_identity_sha256).ToUpperInvariant();task_capability_sha256=([string]$p.task_capability_sha256).ToUpperInvariant();task_name=[string]$p.task.name;legacy_task_name=[string]$p.legacy_task_name;authority_epoch=[int64]$p.authority_epoch;generation_id=[string]$p.generation_id;runtime_bin_dir=[IO.Path]::GetFullPath([string]$p.runtime_bin_dir);exe_path=[IO.Path]::GetFullPath([string]$p.exe_path);bind=[string]$p.bind;db_path=[IO.Path]::GetFullPath([string]$p.db_path);profiles_dir=[IO.Path]::GetFullPath([string]$p.profiles_dir);token_path=[IO.Path]::GetFullPath([string]$p.token_path);log_dir=[IO.Path]::GetFullPath([string]$p.log_dir);maintenance_lock_path=[IO.Path]::GetFullPath([string]$p.maintenance_lock_path);bootstrap_log_path=[IO.Path]::GetFullPath([string]$p.bootstrap_log_path);authority_root_file_id_128=([string]$p.authority_root.file_id_128).ToUpperInvariant();task_receipt_slot3_sha256=([string]$p.task_receipt.slot3.sha256).ToUpperInvariant();retained_legacy_authority_sha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $p.retained_legacy_authority)).ToUpperInvariant();runtime_artifacts_sha256=(Get-SynapseSha256Hex -Text $runtimeArtifactsCanonical).ToUpperInvariant();token_authority_sha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $p.token_authority)).ToUpperInvariant()}
    $expectedId=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $seed)).ToUpperInvariant();if($expectedId-ine[string]$p.decommission_id){Die "SYNAPSE_BROKER_DECOMMISSION_ID_INVALID context=$Context expected=$expectedId actual=$($p.decommission_id)"}
    return $p
}

function New-SynapseBrokerDecommissionAuthorizedRecord {
    param(
        [Parameter(Mandatory=$true)]$Authority,
        [Parameter(Mandatory=$true)][string]$ExePath,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$DbPath,
        [Parameter(Mandatory=$true)][string]$ProfilesDir,
        [Parameter(Mandatory=$true)][string]$TokenPath,
        [Parameter(Mandatory=$true)][string]$LogDir,
        [Parameter(Mandatory=$true)][string]$MaintenanceLockPath,
        [switch]$Purge,
        [switch]$Confirmed
    )
    $generation=$Authority.CurrentGeneration
    $authoritySource=if($null-ne$generation){'active_generation'}else{'legacy_parked_no_journal'}
    if($authoritySource-ceq'legacy_parked_no_journal'-and$Purge){
        Die 'SYNAPSE_BROKER_DECOMMISSION_LEGACY_PARKED_PURGE_UNAUTHORIZED remediation=the parked roster intentionally erased executable/runtime ownership; rerun plain -Remove to unregister the exact broker task and drain its process tree, then inspect retained runtime/data explicitly'
    }
    $sourcePair=$null;$tokenAuthorityBoundaryLease=$null
    try{
        if($authoritySource-ceq'active_generation'){
            $rp=$generation.RosterPayload
            $sourceGate=ConvertTo-SynapseAuthorityIdentityDescriptor -Identity $Authority.ActiveControlGate
            $sourceRoster=ConvertTo-SynapseAuthorityIdentityDescriptor -Identity $Authority.ActiveRoster
        }else{
            $sourcePair=Read-SynapseAuthorityActiveControlPair -Layout $Authority.Layout -ExpectedState parked -Context 'broker_decommission_authorize_legacy_parked_pair'
            [void](Assert-SynapseBrokerParkedNoAuthority -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -ControlGateIdentity ([pscustomobject]@{Path=$sourcePair.Gate.Path;FileId128=$sourcePair.Gate.FileId128;Sha256=$sourcePair.Gate.Sha256;Length=$sourcePair.Gate.Length}) -RosterIdentity ([pscustomobject]@{Path=$sourcePair.Roster.Path;FileId128=$sourcePair.Roster.FileId128;Sha256=$sourcePair.Roster.Sha256;Length=$sourcePair.Roster.Length}) -ControlGateLease $sourcePair.GateLease -RosterLease $sourcePair.RosterLease -Bind $Bind -DbPath $DbPath)
            $rp=$sourcePair.Roster.Payload
            $sourceGate=ConvertTo-SynapseAuthorityIdentityDescriptor -Identity $sourcePair.Gate
            $physicalRoster=ConvertTo-SynapseAuthorityIdentityDescriptor -Identity $sourcePair.Roster
            if((Get-SynapseCanonicalJson -Value $sourceGate)-cne(Get-SynapseCanonicalJson -Value (ConvertTo-SynapseAuthorityIdentityDescriptor -Identity $Authority.ActiveControlGate))-or(Get-SynapseCanonicalJson -Value $physicalRoster)-cne(Get-SynapseCanonicalJson -Value (ConvertTo-SynapseAuthorityIdentityDescriptor -Identity $Authority.ActiveRoster))){Die 'SYNAPSE_BROKER_DECOMMISSION_LEGACY_PARKED_AUTHORITY_PAIR_DRIFT'}
            if([string]$rp.previous_file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'-or[string]$rp.previous_sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[int64]$rp.previous_length-lt1){Die 'SYNAPSE_BROKER_DECOMMISSION_LEGACY_PARKED_PREDECESSOR_MISSING'}
            $sourceRoster=[ordered]@{path=[IO.Path]::GetFullPath([string]$sourcePair.Roster.Path);file_id_128=([string]$rp.previous_file_id_128).ToUpperInvariant();sha256=([string]$rp.previous_sha256).ToUpperInvariant();length=[int64]$rp.previous_length}
        }
        if([string]$rp.bind-cne$Bind-or[IO.Path]::GetFullPath([string]$rp.db_path)-ine[IO.Path]::GetFullPath($DbPath)-or[IO.Path]::GetFullPath([string]$rp.profiles_dir)-ine[IO.Path]::GetFullPath($ProfilesDir)-or[IO.Path]::GetFullPath([string]$rp.token_path)-ine[IO.Path]::GetFullPath($TokenPath)-or[IO.Path]::GetFullPath([string]$rp.log_dir)-ine[IO.Path]::GetFullPath($LogDir)-or[IO.Path]::GetFullPath([string]$rp.maintenance_lock_path)-ine[IO.Path]::GetFullPath($MaintenanceLockPath)){Die "SYNAPSE_BROKER_DECOMMISSION_INVOCATION_AUTHORITY_DRIFT source=$authoritySource"}
        $root=Get-SynapseBrokerDecommissionRecordRoot;$rootChain=@(Ensure-SynapsePhysicalDirectoryPath -Path $root -Context 'broker_decommission_authorize_root');$rootFileId=([string]$rootChain[-1].file_id_128).ToUpperInvariant()
    $task=ConvertTo-SynapseAuthorityTaskDescriptor -Task $Authority.BrokerTask;[void](Assert-SynapseBrokerTaskDescriptorAuthorityCrossbind -Descriptor $task -BrokerIdentitySha256 ([string]$Authority.Infrastructure.BrokerIdentitySha256) -TaskCapabilitySha256 ([string]$Authority.Infrastructure.TaskCapabilitySha256) -Infrastructure $Authority.Infrastructure -Context 'broker_decommission_authorize_task')
    $taskReceipt=ConvertTo-SynapseBrokerTaskReceiptDescriptor -Infrastructure $Authority.Infrastructure;[void](Assert-SynapseBrokerTaskReceiptDescriptor -Descriptor ([pscustomobject]$taskReceipt) -ExpectedAuthorityRoot ([string]$Authority.Layout.Root) -ExpectedBrokerIdentitySha256 ([string]$Authority.Infrastructure.BrokerIdentitySha256) -ExpectedTaskName ([string]$Authority.Infrastructure.TaskName))
    $runtimeArtifactSources=if($Purge){@([pscustomobject]@{Identity=$generation.Executable;Role='daemon'})+@($generation.GenerationObjects|Where-Object{[string]$_.role-like'runtime_*'}|ForEach-Object{[pscustomobject]@{Identity=$_;Role=[string]$_.role}})}else{@()}
