function New-SynapseBrokerDecommissionControlGateEnvelopeFromPayload {
    param([Parameter(Mandatory=$true)]$Payload)
    $payloadText=Get-SynapseCanonicalJson -Value $Payload;$payloadBytes=[Text.UTF8Encoding]::new($false,$true).GetBytes($payloadText)
    if($payloadBytes.Length-lt1-or$payloadBytes.Length-gt32768){Die "SYNAPSE_BROKER_DECOMMISSION_GATE_PAYLOAD_BOUND_INVALID length=$($payloadBytes.Length)"}
    $core=[ordered]@{schema='synapse_daemon_authority_control_gate_envelope/v1';payload_utf8_length=[int]$payloadBytes.Length;payload_sha256=(Get-SynapseSha256Hex -Text $payloadText).ToUpperInvariant();payload_base64=[Convert]::ToBase64String($payloadBytes);trailer=$script:SynapseAuthorityControlGateTrailer}
    $selfInput='{0}:{1}:{2}:{3}'-f$core.schema,$core.payload_utf8_length,$core.payload_sha256,$core.trailer;$envelope=[ordered]@{};foreach($key in $core.Keys){$envelope[$key]=$core[$key]};$envelope.self_sha256=(Get-SynapseSha256Hex -Text $selfInput).ToUpperInvariant();$text=Get-SynapseCanonicalJson -Value $envelope;$length=[Text.UTF8Encoding]::new($false,$true).GetByteCount($text)
    if($length-gt65536){Die "SYNAPSE_BROKER_DECOMMISSION_GATE_ENVELOPE_BOUND_INVALID length=$length"}
    return [pscustomobject][ordered]@{Text=$text;Sha256=(Get-SynapseSha256Hex -Text $text).ToUpperInvariant();Length=[int64]$length}
}

