        $po=$Authorized.Payload.powershell.protected_os;$brokerLease=[SynapseAuthorityRuntime.MappedProcessLease]::OpenProtectedOsForTermination([uint32]$brokerCim.ProcessId,0L,[string]$Authorized.Payload.powershell.path,[string]$Authorized.Payload.powershell.file_id_128,[string]$Authorized.Payload.powershell.sha256,[int64]$Authorized.Payload.powershell.length,[uint32]$po.link_count,[string]$po.security_descriptor_sddl,[string[]]@($po.hardlink_paths),'broker_decommission_broker')
        $outerArgv=@([string]$Authorized.Payload.bootstrap.path,'--outer-launch-capability',([string]$Authorized.Payload.task_capability_sha256).ToUpperInvariant(),[string]$pair.Roster.Payload.powershell_path,[string]$Authorized.Payload.broker_script.path,[string]$pair.Roster.Payload.working_directory,[string]$pair.Roster.Payload.bootstrap_log_path)
