    }
    $planCore=[ordered]@{schema='synapse_broker_decommission_deletion_plan/v1';mode=[string]$p.mode;authority_root=(ConvertTo-SynapseCanonicalValue -Value $p.authority_root);runtime_artifacts=(ConvertTo-SynapseCanonicalValue -Value $p.runtime_artifacts);database=(ConvertTo-SynapseCanonicalValue -Value $p.database);profiles=(ConvertTo-SynapseCanonicalValue -Value $p.profiles);profiles_ownership=(ConvertTo-SynapseCanonicalValue -Value $p.profiles_ownership);token=(ConvertTo-SynapseCanonicalValue -Value $p.token);vault_snapshot=(ConvertTo-SynapseCanonicalValue -Value $p.vault_snapshot);destruction_confirmed=[bool]$p.destruction_confirmed}
    if((Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $planCore))-ine[string]$p.deletion_plan_sha256){Die "SYNAPSE_BROKER_DECOMMISSION_DELETION_PLAN_HASH_INVALID context=$Context"}
    Assert-SynapseBrokerDecommissionRecordHash -Record $Record -Context $Context
    return $p
}

function New-SynapseBrokerDecommissionCleanupReadyRecord {
