    [void](Assert-SynapseBrokerDecommissionAuthorizedRecord -Record $Authorized -StructuralOnly -Context 'broker_decommission_cleanup_authorization')
    if($null-ne$Authorized.PSObject.Properties['RetainedLegacyLeases']-and$null-ne$Authorized.RetainedLegacyLeases){$retainedLegacy=$Authorized.RetainedLegacyLeases;[void](Assert-SynapseBrokerDecommissionRetainedLegacyAuthorityHeld -Authorized $Authorized -Leases $retainedLegacy -Context 'broker_decommission_cleanup_retained_legacy_borrowed')}else{$retainedLegacy=Open-SynapseBrokerDecommissionRetainedLegacyAuthorityLeases -Authorized $Authorized -Context 'broker_decommission_cleanup_retained_legacy';$retainedLegacyOwned=$true}
    [void](Assert-SynapseBrokerDecommissionTaskAbsentRecord -Record $TaskAbsent -Authorized $Authorized -Parked $Parked -Context 'broker_decommission_cleanup_task_absent')
    [void](Assert-SynapseBrokerDecommissionDrainedRecord -Record $Drained -Authorized $Authorized -Parked $Parked -TaskAbsent $TaskAbsent -Context 'broker_decommission_cleanup_drained')
    if($null-ne$Confirmation){[void](Assert-SynapseBrokerDecommissionConfirmationRecord -Record $Confirmation -Authorized $Authorized -Context 'broker_decommission_cleanup_confirmation')}
    $lookup=Get-SynapseScheduledTaskLookupExact -Name ([string]$Authorized.Payload.task.name);if([bool]$lookup.Exists){Die "SYNAPSE_BROKER_DECOMMISSION_TASK_REAPPEARED phase=cleanup_ready task=$($Authorized.Payload.task.name)"}
    [SynapseSetup.BrokerDecommissionJobLease]::RequireNameAbsent([string]$Parked.Payload.outer_job.name,'broker_decommission_cleanup_job_absent')
    [SynapseAuthorityRuntime.MappedProcessLease]::RequireIdentityGone([uint32]$Parked.Payload.outer_bootstrap.pid,[int64]$Parked.Payload.outer_bootstrap.creation_time_filetime_utc,'broker_decommission_cleanup_outer_gone');[SynapseAuthorityRuntime.MappedProcessLease]::RequireIdentityGone([uint32]$Parked.Payload.broker_process.pid,[int64]$Parked.Payload.broker_process.creation_time_filetime_utc,'broker_decommission_cleanup_broker_gone')
    [void](Assert-SynapsePurgeStrictNoLiveAuthority -Bind ([string]$Authorized.Payload.bind) -DbPath ([string]$Authorized.Payload.db_path) -Context 'broker_decommission_cleanup_no_live')
    $authorityRoot=Get-SynapsePurgeDirectorySnapshot -Path ([string]$Authorized.Payload.authority_root.path) -Context 'broker_decommission_cleanup_authority_root';if(-not[bool]$authorityRoot.exists-or[string]$authorityRoot.root_file_id_128-ine[string]$Authorized.Payload.authority_root.file_id_128){Die 'SYNAPSE_BROKER_DECOMMISSION_CLEANUP_AUTHORITY_ROOT_DRIFT'}
    $runtimePlans=@();$database=$null;$profiles=$null;$profilesOwnership=$null;$token=$null;$vault=$null;$confirmed=$false
    if([string]$Authorized.Payload.mode-ceq'remove_purge'){
        foreach($artifact in @($Authorized.Payload.runtime_artifacts|Sort-Object path)){$file=Get-SynapsePurgeFileSnapshot -Path ([string]$artifact.path) -Context "broker_decommission_cleanup_runtime_$($artifact.role)";if(-not[bool]$file.exists-or[string]$file.file_id_128-ine[string]$artifact.file_id_128-or[string]$file.sha256-ine[string]$artifact.sha256-or[int64]$file.length-ne[int64]$artifact.length){Die "SYNAPSE_BROKER_DECOMMISSION_RUNTIME_ARTIFACT_DRIFT path=$($artifact.path)"};$runtimePlans+=,[ordered]@{role=[string]$artifact.role;file=$file}}
        $database=Get-SynapsePurgeDirectorySnapshot -Path ([string]$Authorized.Payload.db_path) -Context 'broker_decommission_cleanup_database';$profiles=Get-SynapsePurgeDirectorySnapshot -Path ([string]$Authorized.Payload.profiles_dir) -Context 'broker_decommission_cleanup_profiles';$token=Get-SynapsePurgeFileSnapshot -Path ([string]$Authorized.Payload.token_path) -Context 'broker_decommission_cleanup_token'
        if([bool]$database.exists-ne[bool]$Authorized.Payload.database.exists-or([bool]$database.exists-and[string]$database.root_file_id_128-ine[string]$Authorized.Payload.database.root_file_id_128)-or(Get-SynapseCanonicalJson -Value $profiles)-cne(Get-SynapseCanonicalJson -Value $Authorized.Payload.profiles)-or(Get-SynapseCanonicalJson -Value $token)-cne(Get-SynapseCanonicalJson -Value $Authorized.Payload.token)){Die 'SYNAPSE_BROKER_DECOMMISSION_PURGE_TARGET_IDENTITY_DRIFT'}
        $profilesOwnership=ConvertTo-SynapseCanonicalValue -Value $Authorized.Payload.profiles_ownership;$vault=Get-SynapseCalyxPhysicalSnapshot -Path ([string]$Authorized.Payload.db_path);if(-not[bool]$vault.bytes_complete-or-not[string]::IsNullOrWhiteSpace([string]$vault.error)-or-not[string]::IsNullOrWhiteSpace([string]$vault.current_manifest_error)){Die 'SYNAPSE_BROKER_DECOMMISSION_FINAL_VAULT_SNAPSHOT_INCOMPLETE'}
        $durable=if($null-eq$vault.current_manifest_durable_seq){0L}else{[int64]$vault.current_manifest_durable_seq};$populated=($durable-gt0-or[int]$vault.cf_file_count-gt0-or[int]$vault.manifest_file_count-gt1-or[int]$vault.wal_segment_count-gt0-or[int64]$vault.wal_bytes-gt0-or@($database.entries).Count-gt0);$confirmed=[bool]$Authorized.Payload.confirmed-or$null-ne$Confirmation;if($populated-and-not$confirmed){Die 'SYNAPSE_BROKER_DECOMMISSION_FINAL_VAULT_CONFIRMATION_REQUIRED'}
    }
    $planCore=[ordered]@{schema='synapse_broker_decommission_deletion_plan/v1';mode=[string]$Authorized.Payload.mode;authority_root=$authorityRoot;runtime_artifacts=$runtimePlans;database=$database;profiles=$profiles;profiles_ownership=$profilesOwnership;token=$token;vault_snapshot=$vault;destruction_confirmed=$confirmed}
    $payload=[ordered]@{schema='synapse_broker_decommission_cleanup_ready/v1';state='cleanup_ready';decommission_id=[string]$Authorized.Payload.decommission_id;authorization=(Get-SynapseBrokerDecommissionRecordReference -Record $Authorized);confirmation=$(if($null-eq$Confirmation){$null}else{Get-SynapseBrokerDecommissionRecordReference -Record $Confirmation});parked=(Get-SynapseBrokerDecommissionRecordReference -Record $Parked);task_absent=(Get-SynapseBrokerDecommissionRecordReference -Record $TaskAbsent);drained=(Get-SynapseBrokerDecommissionRecordReference -Record $Drained);mode=[string]$Authorized.Payload.mode;authority_root=$authorityRoot;runtime_artifacts=$runtimePlans;database=$database;profiles=$profiles;profiles_ownership=$profilesOwnership;token=$token;vault_snapshot=$vault;destruction_confirmed=$confirmed;deletion_plan_sha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $planCore)).ToUpperInvariant();cleanup_ready_at_utc=[DateTime]::UtcNow.ToString('o')}
    $predecessors=@($Authorized)+@($(if($null-ne$Confirmation){$Confirmation}))+@($Parked,$TaskAbsent,$Drained)
    $record=Write-SynapseBrokerDecommissionRecord -DecommissionId ([string]$Authorized.Payload.decommission_id) -Phase 'cleanup-ready' -ExpectedRecordRootFileId128 ([string]$Authorized.Payload.record_root_file_id_128) -RecordRootLease $Authorized.RecordRootLease -Payload $payload -Predecessors $predecessors -Context 'broker_decommission_cleanup_ready';[void](Assert-SynapseBrokerDecommissionCleanupReadyRecord -Record $record -Authorized $Authorized -Confirmation $Confirmation -Parked $Parked -TaskAbsent $TaskAbsent -Drained $Drained -Context 'broker_decommission_cleanup_ready_readback');[void](Assert-SynapseBrokerDecommissionRetainedLegacyAuthorityHeld -Authorized $Authorized -Leases $retainedLegacy -Context 'broker_decommission_cleanup_ready_retained_legacy_readback');$returning=$true;return $record
    }finally{if(-not$returning-and$null-ne$record-and$null-ne$record.Lease){try{$record.Lease.Dispose()}catch{[Environment]::FailFast('SYNAPSE_BROKER_DECOMMISSION_CLEANUP_READY_RECORD_RELEASE_UNPROVEN',$_.Exception)}};if($retainedLegacyOwned){Close-SynapseBrokerDecommissionRetainedLegacyAuthorityLeases -Leases $retainedLegacy}}
}

function Assert-SynapseBrokerDecommissionCleanupBoundary {
    param([Parameter(Mandatory=$true)]$Pending,[Parameter(Mandatory=$true)]$RetainedLegacyLeases,[Parameter(Mandatory=$true)][string]$Context)
    foreach($record in @($Pending.Authorized,$Pending.Confirmation,$Pending.Parked,$Pending.TaskAbsent,$Pending.Drained,$Pending.CleanupReady,$Pending.Quiesced)){if($null-ne$record){$record.Lease.RequireExact("${Context}_$($record.Leaf)")}}
    $a=$Pending.Authorized.Payload;$p=$Pending.Parked.Payload
    $lookup=Get-SynapseScheduledTaskLookupExact -Name ([string]$a.task.name);if([bool]$lookup.Exists){Die "SYNAPSE_BROKER_DECOMMISSION_TASK_REAPPEARED context=$Context task=$($a.task.name)"}
    [SynapseSetup.BrokerDecommissionJobLease]::RequireNameAbsent([string]$p.outer_job.name,"${Context}_job")
    [SynapseAuthorityRuntime.MappedProcessLease]::RequireIdentityGone([uint32]$p.outer_bootstrap.pid,[int64]$p.outer_bootstrap.creation_time_filetime_utc,"${Context}_outer");[SynapseAuthorityRuntime.MappedProcessLease]::RequireIdentityGone([uint32]$p.broker_process.pid,[int64]$p.broker_process.creation_time_filetime_utc,"${Context}_broker")
    [void](Assert-SynapsePurgeStrictNoLiveAuthority -Bind ([string]$a.bind) -DbPath ([string]$a.db_path) -Context $Context)
    [void](Assert-SynapseBrokerDecommissionRetainedLegacyAuthorityHeld -Authorized $Pending.Authorized -Leases $RetainedLegacyLeases -Context "${Context}_retained_legacy")
}

function Assert-SynapseBrokerDecommissionCompletedRecord {
    param([Parameter(Mandatory=$true)]$Record,[Parameter(Mandatory=$true)]$Pending,[Parameter(Mandatory=$true)][string]$Context,[switch]$RequireOldIdentitiesGone)
    $p=$Record.Payload;$a=$Pending.Authorized
    Assert-SynapsePurgeExactPropertySet -Value $p -Expected @('schema','state','decommission_id','history_sequence','previous_completed','authorization','parked','task_absent','drained','cleanup_ready','quiesced','mode','deletion_plan_sha256','task_absent_proven','job_absent_proven','outer_identity_gone','broker_identity_gone','authority_root_disposition','runtime_artifacts_disposition','database_disposition','profiles_disposition','token_disposition','completed_at_utc','record_sha256') -Context $Context
    foreach($flag in @('task_absent_proven','job_absent_proven','outer_identity_gone','broker_identity_gone')){if(-not($p.$flag-is[bool])-or-not[bool]$p.$flag){Die "SYNAPSE_BROKER_DECOMMISSION_COMPLETION_PROOF_INVALID context=$Context field=$flag"}}
    $purged=[string]$p.mode-ceq'remove_purge';$ready=$Pending.CleanupReady.Payload;$quiesced=$Pending.Quiesced.Payload
    $planDisposition={param($plan)if($null-eq$plan){'not_targeted'}elseif([bool]$plan.exists){'deleted_old_identity'}else{'absent_when_planned'}}
    $expectedRuntime=if(-not$purged){'not_targeted'}elseif(@($ready.runtime_artifacts).Count-eq0){'absent_when_planned'}elseif(@($ready.runtime_artifacts|Where-Object{[bool]$_.file.exists}).Count-gt0){'deleted_old_identity'}else{'absent_when_planned'}
    $expectedDatabase=&$planDisposition $ready.database;$expectedProfiles=&$planDisposition $ready.profiles;$expectedToken=&$planDisposition $ready.token
    if([string]$p.schema-cne'synapse_broker_decommission_completed/v2'-or[string]$p.state-cne'completed'-or[string]$p.decommission_id-ine[string]$a.Payload.decommission_id-or[string]$Record.Leaf-cne("decommission-$($p.decommission_id)-completed.json")-or[int64]$p.history_sequence-ne[int64]$a.Payload.history_sequence-or(Get-SynapseCanonicalJson -Value $p.previous_completed)-cne(Get-SynapseCanonicalJson -Value $a.Payload.previous_completed)-or[string]$p.mode-cne[string]$a.Payload.mode-or[string]$p.deletion_plan_sha256-ine[string]$quiesced.deletion_plan_sha256-or[string]$p.authority_root_disposition-cne'deleted_old_identity'-or[string]$p.runtime_artifacts_disposition-cne$expectedRuntime-or[string]$p.database_disposition-cne$expectedDatabase-or[string]$p.profiles_disposition-cne$expectedProfiles-or[string]$p.token_disposition-cne$expectedToken){Die "SYNAPSE_BROKER_DECOMMISSION_COMPLETION_INVALID context=$Context"}
    if([int64]$p.history_sequence-eq1){if($null-ne$p.previous_completed){Die "SYNAPSE_BROKER_DECOMMISSION_COMPLETION_GENESIS_PREDECESSOR_INVALID context=$Context"}}else{Assert-SynapsePurgeExactPropertySet -Value $p.previous_completed -Expected @('leaf','file_id_128','sha256','length','record_sha256') -Context "${Context}_previous_completed";if([string]$p.previous_completed.leaf-cnotmatch'\Adecommission-[0-9A-F]{64}-completed\.json\z'-or[string]$p.previous_completed.file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'-or[string]$p.previous_completed.sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[int64]$p.previous_completed.length-lt1-or[string]$p.previous_completed.record_sha256-notmatch'^[0-9A-Fa-f]{64}$'){Die "SYNAPSE_BROKER_DECOMMISSION_COMPLETION_PREDECESSOR_INVALID context=$Context"}}
    [void](Assert-SynapseBrokerDecommissionUtcTimestamp -Value $p.completed_at_utc -Context "${Context}_completed_at")
    Assert-SynapseBrokerDecommissionRecordReference -Reference $p.authorization -Record $a -Context "${Context}_authorization";Assert-SynapseBrokerDecommissionRecordReference -Reference $p.parked -Record $Pending.Parked -Context "${Context}_parked";Assert-SynapseBrokerDecommissionRecordReference -Reference $p.task_absent -Record $Pending.TaskAbsent -Context "${Context}_task_absent";Assert-SynapseBrokerDecommissionRecordReference -Reference $p.drained -Record $Pending.Drained -Context "${Context}_drained";Assert-SynapseBrokerDecommissionRecordReference -Reference $p.cleanup_ready -Record $Pending.CleanupReady -Context "${Context}_cleanup_ready";Assert-SynapseBrokerDecommissionRecordReference -Reference $p.quiesced -Record $Pending.Quiesced -Context "${Context}_quiesced"
    Assert-SynapseBrokerDecommissionRecordHash -Record $Record -Context $Context
    if($RequireOldIdentitiesGone){[void](Assert-SynapseBrokerDecommissionOldObjectIdentitiesGone -Pending $Pending -Context "${Context}_old_objects")}
    return $p
}

function Assert-SynapseBrokerDecommissionOldObjectIdentitiesGone {
    param([Parameter(Mandatory=$true)]$Pending,[Parameter(Mandatory=$true)][string]$Context)
    $ready=$Pending.CleanupReady.Payload
    $assertDirectory={param($plan,[string]$role)if($null-eq$plan-or-not[bool]$plan.exists){return};$path=[IO.Path]::GetFullPath([string]$plan.path);if([IO.File]::Exists($path)){return};$state=Get-SynapsePurgeDirectorySnapshot -Path $path -Context "${Context}_$role";if([bool]$state.exists-and[string]$state.root_file_id_128-ieq[string]$plan.root_file_id_128){Die "SYNAPSE_BROKER_DECOMMISSION_OLD_DIRECTORY_IDENTITY_PRESENT context=$Context role=$role path=$path file_id_128=$($plan.root_file_id_128)"}}
    $assertFile={param($plan,[string]$role)if($null-eq$plan-or-not[bool]$plan.exists){return};$path=[IO.Path]::GetFullPath([string]$plan.path);if([IO.Directory]::Exists($path)){return};$state=Get-SynapsePurgeFileSnapshot -Path $path -Context "${Context}_$role";if([bool]$state.exists-and[string]$state.file_id_128-ieq[string]$plan.file_id_128){Die "SYNAPSE_BROKER_DECOMMISSION_OLD_FILE_IDENTITY_PRESENT context=$Context role=$role path=$path file_id_128=$($plan.file_id_128)"}}
    &$assertDirectory $ready.authority_root 'authority_root'
    foreach($item in @($ready.runtime_artifacts)){&$assertFile $item.file "runtime_$($item.role)"}
    &$assertDirectory $ready.database 'database';&$assertDirectory $ready.profiles 'profiles';&$assertFile $ready.token 'token'
    return [pscustomobject][ordered]@{OldObjectIdentitiesGone=$true}
}

function Assert-SynapseBrokerDecommissionCurrentPostcondition {
    param([Parameter(Mandatory=$true)]$Pending,[Parameter(Mandatory=$true)][string]$Context,$RetainedLegacyLeases,[switch]$BeforeCompleted)
    $a=$Pending.Authorized;$p=$Pending.Parked;$ready=$Pending.CleanupReady;$owned=$false
    if($null-eq$a-or$null-eq$p-or$null-eq$ready-or(-not$BeforeCompleted-and$null-eq$Pending.Completed)-or($BeforeCompleted-and$null-ne$Pending.Completed)){Die "SYNAPSE_BROKER_DECOMMISSION_CURRENT_POSTCONDITION_PHASE_MISSING context=$Context before_completed=$([bool]$BeforeCompleted)"}
    try{
        foreach($record in @($a,$Pending.Confirmation,$p,$Pending.TaskAbsent,$Pending.Drained,$ready,$Pending.Completed)){if($null-ne$record){$record.Lease.RequireExact("${Context}_record_$($record.Leaf)")}}
        if($null-eq$RetainedLegacyLeases-and$null-ne$Pending.PSObject.Properties['RetainedLegacyLeases']-and$null-ne$Pending.RetainedLegacyLeases){$RetainedLegacyLeases=$Pending.RetainedLegacyLeases}
        if($null-eq$RetainedLegacyLeases){$RetainedLegacyLeases=Open-SynapseBrokerDecommissionRetainedLegacyAuthorityLeases -Authorized $a -Context "${Context}_retained_legacy";$owned=$true}else{[void](Assert-SynapseBrokerDecommissionRetainedLegacyAuthorityHeld -Authorized $a -Leases $RetainedLegacyLeases -Context "${Context}_retained_legacy")}
        $assertDeletedPaths={param([string]$cut)
            $authority=Get-SynapsePurgeDirectorySnapshot -Path ([string]$ready.Payload.authority_root.path) -Context "${Context}_${cut}_authority_absence";if([bool]$authority.exists){Die "SYNAPSE_BROKER_DECOMMISSION_CURRENT_AUTHORITY_PATH_PRESENT context=$Context cut=$cut path=$($ready.Payload.authority_root.path)"};Assert-SynapsePurgeAbsenceAnchor -Anchor $authority.absence -Context "${Context}_${cut}_authority_absence_readback"
            if([string]$a.Payload.mode-ceq'remove_purge'){
                foreach($item in @($ready.Payload.runtime_artifacts)){$state=Get-SynapsePurgeFileSnapshot -Path ([string]$item.file.path) -Context "${Context}_${cut}_runtime_absence";if([bool]$state.exists){Die "SYNAPSE_BROKER_DECOMMISSION_CURRENT_RUNTIME_PATH_PRESENT context=$Context cut=$cut path=$($item.file.path)"};Assert-SynapsePurgeAbsenceAnchor -Anchor $state.absence -Context "${Context}_${cut}_runtime_absence_readback"}
                foreach($item in @([pscustomobject]@{Plan=$ready.Payload.database;Kind='directory'},[pscustomobject]@{Plan=$ready.Payload.profiles;Kind='directory'},[pscustomobject]@{Plan=$ready.Payload.token;Kind='file'})){if($null-eq$item.Plan){Die "SYNAPSE_BROKER_DECOMMISSION_CURRENT_PURGE_PLAN_MISSING context=$Context cut=$cut kind=$($item.Kind)"};$state=if($item.Kind-ceq'directory'){Get-SynapsePurgeDirectorySnapshot -Path ([string]$item.Plan.path) -Context "${Context}_${cut}_$($item.Kind)_absence"}else{Get-SynapsePurgeFileSnapshot -Path ([string]$item.Plan.path) -Context "${Context}_${cut}_$($item.Kind)_absence"};if([bool]$state.exists){Die "SYNAPSE_BROKER_DECOMMISSION_CURRENT_PURGE_PATH_PRESENT context=$Context cut=$cut path=$($item.Plan.path)"};Assert-SynapsePurgeAbsenceAnchor -Anchor $state.absence -Context "${Context}_${cut}_$($item.Kind)_absence_readback"}
            }
        }
        & $assertDeletedPaths 'initial'
        $task=Get-SynapseScheduledTaskLookupExact -Name ([string]$a.Payload.task.name);if([bool]$task.Exists){Die "SYNAPSE_BROKER_DECOMMISSION_CURRENT_TASK_PRESENT context=$Context task=$($a.Payload.task.name)"}
        [SynapseSetup.BrokerDecommissionJobLease]::RequireNameAbsent([string]$p.Payload.outer_job.name,"${Context}_job_absent")
        [SynapseAuthorityRuntime.MappedProcessLease]::RequireIdentityGone([uint32]$p.Payload.outer_bootstrap.pid,[int64]$p.Payload.outer_bootstrap.creation_time_filetime_utc,"${Context}_outer_gone");[SynapseAuthorityRuntime.MappedProcessLease]::RequireIdentityGone([uint32]$p.Payload.broker_process.pid,[int64]$p.Payload.broker_process.creation_time_filetime_utc,"${Context}_broker_gone")
        [void](Assert-SynapsePurgeStrictNoLiveAuthority -Bind ([string]$a.Payload.bind) -DbPath ([string]$a.Payload.db_path) -Context "${Context}_no_live")
        foreach($record in @($a,$p,$ready,$Pending.Completed)){if($null-ne$record){$record.Lease.RequireExact("${Context}_final_$($record.Leaf)")}};[void](Assert-SynapseBrokerDecommissionRetainedLegacyAuthorityHeld -Authorized $a -Leases $RetainedLegacyLeases -Context "${Context}_final_retained_legacy")
        $finalTask=Get-SynapseScheduledTaskLookupExact -Name ([string]$a.Payload.task.name);if([bool]$finalTask.Exists){Die "SYNAPSE_BROKER_DECOMMISSION_CURRENT_TASK_PRESENT context=${Context}_final task=$($a.Payload.task.name)"};[SynapseSetup.BrokerDecommissionJobLease]::RequireNameAbsent([string]$p.Payload.outer_job.name,"${Context}_final_job_absent");[SynapseAuthorityRuntime.MappedProcessLease]::RequireIdentityGone([uint32]$p.Payload.outer_bootstrap.pid,[int64]$p.Payload.outer_bootstrap.creation_time_filetime_utc,"${Context}_final_outer_gone");[SynapseAuthorityRuntime.MappedProcessLease]::RequireIdentityGone([uint32]$p.Payload.broker_process.pid,[int64]$p.Payload.broker_process.creation_time_filetime_utc,"${Context}_final_broker_gone");[void](Assert-SynapsePurgeStrictNoLiveAuthority -Bind ([string]$a.Payload.bind) -DbPath ([string]$a.Payload.db_path) -Context "${Context}_final_no_live")
        & $assertDeletedPaths 'final'
        foreach($record in @($a,$p,$ready,$Pending.Completed)){if($null-ne$record){$record.Lease.RequireExact("${Context}_terminal_$($record.Leaf)")}};[void](Assert-SynapseBrokerDecommissionRetainedLegacyAuthorityHeld -Authorized $a -Leases $RetainedLegacyLeases -Context "${Context}_terminal_retained_legacy")
        return [pscustomobject][ordered]@{Current=$true;Mode=[string]$a.Payload.mode;AuthorityPathAbsent=$true;TaskAbsent=$true;JobAbsent=$true;TargetProcessCount=0;ListenerCount=0}
    }finally{if($owned){Close-SynapseBrokerDecommissionRetainedLegacyAuthorityLeases -Leases $RetainedLegacyLeases}}
}

function Assert-SynapseBrokerDecommissionQuiescedRecord {
    param([Parameter(Mandatory=$true)]$Record,[Parameter(Mandatory=$true)]$Pending,[Parameter(Mandatory=$true)][string]$Context)
    $p=$Record.Payload
    Assert-SynapsePurgeExactPropertySet -Value $p -Expected @('schema','state','decommission_id','authorization','cleanup_ready','lineages','authority_root','deletion_plan_sha256','quiesced_at_utc','record_sha256') -Context $Context
    if([string]$p.schema-cne'synapse_broker_decommission_quiesced/v1'-or[string]$p.state-cne'authority_root_quiesced'-or[string]$p.decommission_id-ine[string]$Pending.Authorized.Payload.decommission_id-or[string]$Record.Leaf-cne("decommission-$($p.decommission_id)-quiesced.json")-or[string]$p.deletion_plan_sha256-notmatch'^[0-9A-Fa-f]{64}$'){Die "SYNAPSE_BROKER_DECOMMISSION_QUIESCED_INVALID context=$Context"}
    Assert-SynapseBrokerDecommissionRecordReference -Reference $p.authorization -Record $Pending.Authorized -Context "${Context}_authorization"
    Assert-SynapseBrokerDecommissionRecordReference -Reference $p.cleanup_ready -Record $Pending.CleanupReady -Context "${Context}_cleanup_ready"
    Assert-SynapsePurgeDirectoryDescriptor -Descriptor $p.authority_root -ExpectedPath ([string]$Pending.Authorized.Payload.authority_root.path) -Context "${Context}_authority_root"
    if(-not[bool]$p.authority_root.exists-or[string]$p.authority_root.root_file_id_128-ine[string]$Pending.Authorized.Payload.authority_root.file_id_128-or(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $p.authority_root))-ine[string]$p.deletion_plan_sha256){Die "SYNAPSE_BROKER_DECOMMISSION_QUIESCED_PLAN_INVALID context=$Context"}
    $seen=New-SynapseCaseInsensitiveMap
    foreach($l in @($p.lineages)){
        Assert-SynapsePurgeExactPropertySet -Value $l -Expected @('capability_sha256','job_name','task_name','task_disposition','outer_pid','outer_creation_time_filetime_utc','broker_pid','broker_creation_time_filetime_utc','outer_image','broker_script','terminated_at_utc') -Context "${Context}_lineage"
        if([string]$l.capability_sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[string]$l.job_name-cne("Local\SynapseOwned-$(([string]$l.capability_sha256).ToUpperInvariant())-$([int]$l.outer_pid)")-or[string]$l.task_name-cne("SynapseMcpBroker-$(([string]$l.capability_sha256).Substring(0,40).ToUpperInvariant())")-or[string]$l.task_disposition-cnotin@('deleted_exact','already_absent')-or[int]$l.outer_pid-lt1-or[int]$l.broker_pid-lt1-or[int64]$l.outer_creation_time_filetime_utc-lt1-or[int64]$l.broker_creation_time_filetime_utc-lt1-or$seen.ContainsKey([string]$l.capability_sha256)){Die "SYNAPSE_BROKER_DECOMMISSION_QUIESCED_LINEAGE_INVALID context=$Context"}
        $seen[[string]$l.capability_sha256]=$true;Assert-SynapsePurgeFileDescriptor -Descriptor $l.outer_image -ExpectedPath ([string]$l.outer_image.path) -Context "${Context}_outer_image";Assert-SynapsePurgeFileDescriptor -Descriptor $l.broker_script -ExpectedPath ([string]$l.broker_script.path) -Context "${Context}_broker_script";[void](Assert-SynapseBrokerDecommissionUtcTimestamp -Value $l.terminated_at_utc -Context "${Context}_terminated_at")
    }
    [void](Assert-SynapseBrokerDecommissionUtcTimestamp -Value $p.quiesced_at_utc -Context "${Context}_quiesced_at");Assert-SynapseBrokerDecommissionRecordHash -Record $Record -Context $Context;return $p
}

function New-SynapseBrokerDecommissionQuiescedRecord {
    param([Parameter(Mandatory=$true)]$Pending,[ValidateRange(10,300)][int]$TimeoutSeconds=60)
    Ensure-SynapseDaemonJobReadbackType;Ensure-SynapseWindowsCommandLineArgvType
