    $legacySupervisorCompatibility=Assert-SynapseLegacySupervisorCompatibilityContractDescriptor -Contract $legacy.supervisor_compatibility_contract -SupervisorDescriptor $legacySupervisorDescriptor -Context "adoption_initial_$root"
    $objects=@($Initial.immutable_objects)
    if($objects.Count -ne 4){Die "SYNAPSE_AUTHORITY_ADOPTION_OBJECT_COUNT_INVALID root=$root count=$($objects.Count) expected=4"}
    $objectPaths=New-SynapseCaseInsensitiveMap
    $objectRoles=New-SynapseCaseInsensitiveMap
    foreach($object in $objects){
        $objectNames=@($object.PSObject.Properties.Name)
        $objectExpected=@('role','path','file_id_128','sha256','length','parent_path','parent_file_id_128')
        $objectPath=[System.IO.Path]::GetFullPath([string]$object.path)
        if($objectNames.Count -ne $objectExpected.Count -or @($objectNames|Where-Object{$objectExpected -cnotcontains $_}).Count -gt 0 -or
            [string]$object.role -notin @('broker_bootstrap','broker_script','prior_generation_supervisor','legacy_recovery_keeper_script') -or
            $objectPaths.ContainsKey($objectPath) -or $objectRoles.ContainsKey([string]$object.role) -or [string]$object.file_id_128 -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or
            [string]$object.sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [int64]$object.length -lt 1 -or
            [System.IO.Path]::GetFullPath([string]$object.parent_path) -ine [System.IO.Path]::GetFullPath((Split-Path -Parent $objectPath)) -or
            [string]$object.parent_file_id_128 -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'){
            Die "SYNAPSE_AUTHORITY_ADOPTION_OBJECT_INVALID root=$root role=$($object.role) path=$objectPath"
        }
        $objectPaths[$objectPath]=$true
        $objectRoles[[string]$object.role]=$true
    }
    foreach($requiredRole in @('broker_bootstrap','broker_script','prior_generation_supervisor','legacy_recovery_keeper_script')){if(-not $objectRoles.ContainsKey($requiredRole)){Die "SYNAPSE_AUTHORITY_ADOPTION_OBJECT_ROLE_MISSING root=$root role=$requiredRole"}}
    $keeperScriptObject=@($objects|Where-Object role -CEQ 'legacy_recovery_keeper_script')[0]
