        }
    }
    $legacyGate=ConvertTo-SynapseAuthorityControlTransition -Descriptor $Initial.legacy_gate_transition -TransactionRoot $root -Allocation $Allocation
    $legacyDenial=ConvertTo-SynapseAuthorityControlTransition -Descriptor $Initial.legacy_denial_stub_transition -TransactionRoot $root -Allocation $Allocation
    $legacyMalformedGate=ConvertTo-SynapseAuthorityControlTransition -Descriptor $Initial.legacy_denial_malformed_gate_transition -TransactionRoot $root -Allocation $Allocation
    $legacyGateAbsence=ConvertTo-SynapseLegacyDenialGateAbsencePlan -Descriptor $Initial.legacy_denial_gate_absence -LegacyGateTransition $legacyGate -TransactionRoot $root -Allocation $Allocation
    $malformedGateLiteral='{"schema":'
    $malformedGateLength=[System.Text.UTF8Encoding]::new($false,$true).GetByteCount($malformedGateLiteral)
    $malformedGateSha256=(Get-SynapseSha256Hex -Text $malformedGateLiteral).ToUpperInvariant()
    $malformedGateRejected=$false
    try{[void]($malformedGateLiteral|ConvertFrom-Json -ErrorAction Stop)}catch{$malformedGateRejected=$true}
    $parked=ConvertTo-SynapseAuthorityControlTransition -Descriptor $Initial.parked_roster_transition -TransactionRoot $root -Allocation $Allocation
    $active=ConvertTo-SynapseAuthorityControlTransition -Descriptor $Initial.active_roster_transition -TransactionRoot $root -Allocation $Allocation
    $controlGate=ConvertTo-SynapseAuthorityControlTransition -Descriptor $Initial.active_control_gate_transition -TransactionRoot $root -Allocation $Allocation
    if([string]$legacyGate.path -ine [System.IO.Path]::GetFullPath([string]$Initial.prior_generation.legacy_gate_path) -or
        [string]$controlGate.path -ine [System.IO.Path]::GetFullPath([string]$Initial.prior_generation.control_gate_path) -or
        [string]$Initial.control_nonce -ine [string]$Initial.prior_generation.control_nonce -or
        [string]$parked.path -ine [System.IO.Path]::GetFullPath([string]$Initial.prior_generation.roster_path) -or
        [string]$legacyMalformedGate.purpose -cne 'broker_adoption_legacy_denial_malformed_gate' -or [string]$legacyMalformedGate.path -ine [string]$legacyGate.path -or
        -not [bool]$legacyMalformedGate.pre_existed -or [string]$legacyMalformedGate.pre_file_id_128 -ine [string]$legacyGate.post_file_id_128 -or
        [string]$legacyMalformedGate.pre_sha256 -ine [string]$legacyGate.post_sha256 -or [int64]$legacyMalformedGate.pre_length -ne [int64]$legacyGate.post_length -or
        [string]$legacyMalformedGate.post_sha256 -ine $malformedGateSha256 -or [int64]$legacyMalformedGate.post_length -ne [int64]$malformedGateLength -or -not $malformedGateRejected -or
        [string]$active.path -ine [string]$parked.path -or
        [string]$active.pre_file_id_128 -ine [string]$parked.post_file_id_128 -or
        [string]$active.pre_sha256 -ine [string]$parked.post_sha256 -or [int64]$active.pre_length -ne [int64]$parked.post_length){
