       [string]$legacyAssignments.DaemonLogDir -ine [string]$prior.RosterPayload.log_dir -or [string]$legacyAssignments.TokenPath -ine [string]$Initial.token_path -or
       [string]$legacyAssignments.MaintenanceLockPath -ine [string]$prior.RosterPayload.maintenance_lock_path -or
       [string]$legacyAssignments.ExpectedAllowedPermissions -cne [string]$prior.RosterPayload.allowed_permissions -or
       [bool]::Parse([string]$legacyAssignments.ExpectedEnableAudio) -ne [bool]$prior.RosterPayload.enable_audio){
