    $runtimeBin=Get-SynapseNormalizedDirectoryPath -Path ([string]$prior.RosterPayload.runtime_bin_dir)
    $authorityRoot=Get-SynapseNormalizedDirectoryPath -Path ([string]$prior.RosterPayload.authority_root_path)
    $expectedAuthorityRoot=Get-SynapseNormalizedDirectoryPath -Path (Join-Path $runtimeBin $script:SynapseAuthorityRootLeaf)
    $expectedEpochs=Get-SynapseNormalizedDirectoryPath -Path (Join-Path $authorityRoot 'epochs')
    $expectedRoster=[System.IO.Path]::GetFullPath((Join-Path $authorityRoot $script:SynapseAuthorityRosterFileName))
    $expectedLegacyGate=[System.IO.Path]::GetFullPath((Join-Path $runtimeBin $script:SynapseDaemonSupervisorStopRequestFileName))
    $expectedControlGate=[System.IO.Path]::GetFullPath((Join-Path $authorityRoot $script:SynapseAuthorityControlGateFileName))
    $expectedBrokerName=[string]$Initial.broker_task_receipt.task_name
    if($authorityRoot -ine $expectedAuthorityRoot -or
