        [string]$Initial.task_name -cne [string]$legacy.name -or
        [string]$Initial.bind -cne [string]$prior.RosterPayload.bind -or
        [System.IO.Path]::GetFullPath([string]$Initial.db_path) -ine [System.IO.Path]::GetFullPath([string]$prior.RosterPayload.db_path) -or
        [System.IO.Path]::GetFullPath([string]$Initial.token_path) -ine [System.IO.Path]::GetFullPath([string]$prior.RosterPayload.token_path) -or
        [string]$broker.name -cne $expectedBrokerName -or
        [string]$broker.execute -ine [string]$prior.RosterPayload.bootstrap_path -or
        [string]$broker.working_directory -ine [string]$prior.RosterPayload.working_directory -or
        [string]$broker.arguments -cne (Get-SynapseSupervisorBootstrapTaskArgumentText -PowerShellPath ([string]$prior.RosterPayload.powershell_path) -SupervisorPath ([string]$prior.RosterPayload.broker_script_path) -WorkingDirectory ([string]$prior.RosterPayload.working_directory) -LogPath ([string]$prior.RosterPayload.bootstrap_log_path) -OuterLaunchCapabilitySha256 ([string]$Initial.broker_task_receipt.task_capability_sha256))){
