    }
    $runtimeChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $runtimeBin)
    $authorityChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $authorityRoot)
    if([string]$runtimeChain[-1].file_id_128 -ine [string]$prior.RosterPayload.runtime_bin_file_id_128 -or
