    $bootstrap=@($objects|Where-Object role -CEQ 'broker_bootstrap')[0]
    $brokerScript=@($objects|Where-Object role -CEQ 'broker_script')[0]
    $priorSupervisor=@($objects|Where-Object role -CEQ 'prior_generation_supervisor')[0]
    $legacySupervisorDescriptor=@($legacyLauncherObjects|Where-Object role -CEQ 'legacy_supervisor')[0]
    $expectedDenialContent=New-SynapseLegacyAuthorityDenialStubContent -BrokerIdentitySha256 ([string]$Initial.broker_identity_sha256) -AuthorityEpoch ([int64]$Initial.authority_epoch) -TaskCapabilitySha256 ([string]$taskReceipt.TaskCapabilitySha256)
    $expectedDenialBytes=[System.Text.UTF8Encoding]::new($false,$true).GetBytes($expectedDenialContent)
    if((Get-SynapseCanonicalJson -Value $priorSupervisor) -cne (Get-SynapseCanonicalJson -Value (ConvertTo-SynapseAuthorityFileDescriptor -Identity $prior.Supervisor -Role prior_generation_supervisor)) -or
        [string]$prior.RosterPayload.bootstrap_path -ine [string]$bootstrap.path -or [string]$prior.RosterPayload.bootstrap_file_id_128 -ine [string]$bootstrap.file_id_128 -or
        [string]$prior.RosterPayload.bootstrap_parent_path -ine [string]$bootstrap.parent_path -or [string]$prior.RosterPayload.bootstrap_parent_file_id_128 -ine [string]$bootstrap.parent_file_id_128 -or
        [string]$prior.RosterPayload.bootstrap_sha256 -ine [string]$bootstrap.sha256 -or [int64]$prior.RosterPayload.bootstrap_length -ne [int64]$bootstrap.length -or
        [string]$prior.RosterPayload.broker_script_path -ine [string]$brokerScript.path -or [string]$prior.RosterPayload.broker_script_file_id_128 -ine [string]$brokerScript.file_id_128 -or
        [string]$prior.RosterPayload.broker_script_parent_path -ine [string]$brokerScript.parent_path -or [string]$prior.RosterPayload.broker_script_parent_file_id_128 -ine [string]$brokerScript.parent_file_id_128 -or
        [string]$prior.RosterPayload.broker_script_sha256 -ine [string]$brokerScript.sha256 -or [int64]$prior.RosterPayload.broker_script_length -ne [int64]$brokerScript.length -or
        [string]$legacyDenial.purpose -cne 'broker_adoption_legacy_denial_stub' -or
        [string]$legacyDenial.path -ine [string]$legacySupervisorDescriptor.path -or -not [bool]$legacyDenial.pre_existed -or
        [string]$legacyDenial.pre_file_id_128 -ine [string]$legacySupervisorDescriptor.file_id_128 -or
        [string]$legacyDenial.pre_sha256 -ine [string]$legacySupervisorDescriptor.sha256 -or [int64]$legacyDenial.pre_length -ne [int64]$legacySupervisorDescriptor.length -or
        [string]$legacyDenial.post_sha256 -ine (Get-SynapseSha256Hex -Text $expectedDenialContent) -or [int64]$legacyDenial.post_length -ne [int64]$expectedDenialBytes.Length){
        Die "SYNAPSE_AUTHORITY_ADOPTION_IMMUTABLE_OBJECT_CROSSBIND_INVALID root=$root"
    }
    [void](Get-SynapseAuthorityControlTransitionPhysicalCut -Transition $legacyDenial -Context "legacy_denial_$root")
    return [pscustomobject][ordered]@{Root=$root;PriorAuthority='legacy';BrokerIdentitySha256=([string]$Initial.broker_identity_sha256).ToUpperInvariant();AuthorityEpoch=[int64]$Initial.authority_epoch;ControlNonce=([string]$Initial.control_nonce).ToUpperInvariant();LegacyTask=$legacy;BrokerTask=$broker;TaskReceipt=$taskReceipt;PredecessorReceipt=$predecessorReceipt;PredecessorCleanupProgressSlots=@($predecessorCleanupProgressSlots);ImmutableObjects=$objects;VerifiedImmutableObjects=$verifiedObjects;PriorGeneration=$prior;LegacyGateTransition=$legacyGate;LegacyDenialTransition=$legacyDenial;LegacyMalformedGateTransition=$legacyMalformedGate;LegacyGateAbsence=$legacyGateAbsence;LegacyDenialProbePlans=$legacyDenialProbePlans;LegacyRescueLaunchAttempts=$legacyRescueLaunchAttempts;ControlGateTransition=$controlGate;ParkedRosterTransition=$parked;ActiveRosterTransition=$active}
}

function ConvertTo-SynapseAuthorityInfrastructureFromAdoptionReceipt {
    param(
        [Parameter(Mandatory=$true)]$Layout,
        [Parameter(Mandatory=$true)]$Initial,
        [Parameter(Mandatory=$true)]$Validated,
        [Parameter(Mandatory=$true)]$BrokerTaskReadback
    )
    $bootstrap=@($Validated.VerifiedImmutableObjects|Where-Object Role -CEQ 'broker_bootstrap')
    $brokerScript=@($Validated.VerifiedImmutableObjects|Where-Object Role -CEQ 'broker_script')
    if($bootstrap.Count -ne 1 -or $brokerScript.Count -ne 1){
        Die "SYNAPSE_AUTHORITY_RECEIPT_IMMUTABLE_ROLE_SET_INVALID broker_bootstrap=$($bootstrap.Count) broker_script=$($brokerScript.Count)"
    }
    $receiptInfrastructure=ConvertTo-SynapseBrokerTaskReceiptInfrastructure -Layout $Layout -Journal $Validated.TaskReceipt.Journal -HistoricalTaskReadback $BrokerTaskReadback
    if([string]$receiptInfrastructure.TaskName -cne [string]$BrokerTaskReadback.Name -or
       [string]$receiptInfrastructure.Task.XmlSha256 -ine [string]$BrokerTaskReadback.XmlSha256 -or
       [string]$receiptInfrastructure.Task.SecurityDescriptorSha256 -ine [string]$BrokerTaskReadback.SecurityDescriptorSha256 -or
       [string]$receiptInfrastructure.BrokerIdentitySha256 -ine [string]$Initial.broker_identity_sha256 -or
       [string]$receiptInfrastructure.Bootstrap.FileId128 -ine [string]$bootstrap[0].FileId128 -or
       [string]$receiptInfrastructure.Bootstrap.Sha256 -ine [string]$bootstrap[0].Sha256 -or
       [string]$receiptInfrastructure.BrokerScript.FileId128 -ine [string]$brokerScript[0].FileId128 -or
       [string]$receiptInfrastructure.BrokerScript.Sha256 -ine [string]$brokerScript[0].Sha256){
        Die "SYNAPSE_AUTHORITY_RECEIPT_INFRASTRUCTURE_CROSSBIND_INVALID task=$($BrokerTaskReadback.Name) root=$($Validated.TaskReceipt.Root)"
    }
    return $receiptInfrastructure
}

function ConvertTo-SynapseAuthorityTaskDescriptor {
    param([Parameter(Mandatory=$true)]$Task)
    return [ordered]@{
        name=[string]$Task.Name
        xml_sha256=([string]$Task.XmlSha256).ToUpperInvariant()
        security_descriptor_sha256=([string]$Task.SecurityDescriptorSha256).ToUpperInvariant()
        execute=[System.IO.Path]::GetFullPath([string]$Task.Execute)
        arguments=[string]$Task.Arguments
        working_directory=[System.IO.Path]::GetFullPath([string]$Task.WorkingDirectory)
        state=[string]$Task.State
    }
}

function ConvertTo-SynapseBrokerTaskReceiptDescriptor {
    param([Parameter(Mandatory=$true)]$Infrastructure)
    $receipt=$Infrastructure.TaskReceipt
    if($null -eq $receipt -or [string]$receipt.Journal.State -cne 'commit_decided'){
        Die "SYNAPSE_BROKER_TASK_RECEIPT_DESCRIPTOR_SOURCE_INVALID task=$($Infrastructure.TaskName)"
    }
    $slotDescriptor={param($Slot)[ordered]@{sequence=[int]$Slot.Sequence;leaf=[string]$Slot.Leaf;file_id_128=([string]$Slot.FileId128).ToUpperInvariant();sha256=([string]$Slot.RawSha256).ToUpperInvariant();length=[int64]$Slot.ByteLength}}
    $receiptRootFileId=([string]$receipt.RootFileId128).ToUpperInvariant()
    if($receiptRootFileId-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'){
        $receiptRootChain=@($receipt.RootChain)
        if($receiptRootChain.Count-lt1-or[string]$receiptRootChain[-1].file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'){Die "SYNAPSE_BROKER_TASK_RECEIPT_SOURCE_ROOT_IDENTITY_INVALID root=$($receipt.Root)"}
        $receiptRootFileId=([string]$receiptRootChain[-1].file_id_128).ToUpperInvariant()
    }
    return [ordered]@{
        schema='synapse_broker_task_create_receipt/v1';task_epoch_root=[System.IO.Path]::GetFullPath([string]$receipt.Root)
        task_epoch_root_file_id_128=$receiptRootFileId
        task_capability_sha256=([string]$Infrastructure.TaskCapabilitySha256).ToUpperInvariant()
        broker_identity_sha256=([string]$Infrastructure.BrokerIdentitySha256).ToUpperInvariant();task_name=[string]$Infrastructure.TaskName
        slot1=(& $slotDescriptor $receipt.Slot1);slot2=(& $slotDescriptor $receipt.Slot2);slot3=(& $slotDescriptor $receipt.Slot3)
    }
}

function ConvertTo-SynapseBrokerTaskReceiptDescriptorFromJournal {
    param([Parameter(Mandatory=$true)]$Journal)
    if([string]$Journal.State-cne'commit_decided'-or@($Journal.Slots).Count-ne3){Die "SYNAPSE_BROKER_TASK_RECEIPT_JOURNAL_SOURCE_INVALID root=$($Journal.Root) state=$($Journal.State) slots=$(@($Journal.Slots).Count)"}
    $slotDescriptor={param($Slot)[ordered]@{sequence=[int]$Slot.Sequence;leaf=[string]$Slot.Leaf;file_id_128=([string]$Slot.FileId128).ToUpperInvariant();sha256=([string]$Slot.RawSha256).ToUpperInvariant();length=[int64]$Slot.ByteLength}}
    $rootChain=@($Journal.RootChain)
    if($rootChain.Count-lt1-or[string]$rootChain[-1].file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'){Die "SYNAPSE_BROKER_TASK_RECEIPT_JOURNAL_ROOT_IDENTITY_INVALID root=$($Journal.Root)"}
    return [ordered]@{schema='synapse_broker_task_create_receipt/v1';task_epoch_root=[IO.Path]::GetFullPath([string]$Journal.Root);task_epoch_root_file_id_128=([string]$rootChain[-1].file_id_128).ToUpperInvariant();task_capability_sha256=([string]$Journal.Initial.task_capability_sha256).ToUpperInvariant();broker_identity_sha256=([string]$Journal.Initial.broker_identity_sha256).ToUpperInvariant();task_name=[string]$Journal.Initial.task.name;slot1=(& $slotDescriptor $Journal.Slots[0]);slot2=(& $slotDescriptor $Journal.Slots[1]);slot3=(& $slotDescriptor $Journal.Slots[2])}
}

function Assert-SynapseBrokerTaskReceiptDescriptor {
    param(
        [Parameter(Mandatory=$true)]$Descriptor,
        [Parameter(Mandatory=$true)][string]$ExpectedAuthorityRoot,
        [Parameter(Mandatory=$true)][string]$ExpectedBrokerIdentitySha256,
        [Parameter(Mandatory=$true)][string]$ExpectedTaskName,
        [switch]$StructuralOnly
    )
    $names=@(Get-SynapseObjectPropertyNames -Object $Descriptor);$expected=@('schema','task_epoch_root','task_epoch_root_file_id_128','task_capability_sha256','broker_identity_sha256','task_name','slot1','slot2','slot3')
    $root=Get-SynapseNormalizedDirectoryPath -Path ([string]$Descriptor.task_epoch_root)
    $taskEpochs=Get-SynapseNormalizedDirectoryPath -Path (Join-Path $ExpectedAuthorityRoot 'task-epochs')
    $legacyMissingRootIdentity=[string]::IsNullOrEmpty([string]$Descriptor.task_epoch_root_file_id_128)
    if($names.Count -ne $expected.Count -or @($names|Where-Object{$expected -cnotcontains $_}).Count -gt 0 -or
       [string]$Descriptor.schema -cne 'synapse_broker_task_create_receipt/v1' -or (Split-Path -Parent $root) -ine $taskEpochs -or
       (-not$legacyMissingRootIdentity-and[string]$Descriptor.task_epoch_root_file_id_128 -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$') -or
       [string]$Descriptor.task_capability_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or
       [string]$Descriptor.broker_identity_sha256 -ine $ExpectedBrokerIdentitySha256 -or [string]$Descriptor.task_name -cne $ExpectedTaskName){
        $callers=@(Get-PSCallStack|ForEach-Object{"$($_.FunctionName):$($_.ScriptLineNumber)"})-join' <- '
        Die "SYNAPSE_BROKER_TASK_RECEIPT_DESCRIPTOR_INVALID root=$root task=$($Descriptor.task_name) names=$($names-join ',') expected_parent=$taskEpochs actual_parent=$(Split-Path -Parent $root) root_file_id_128=$($Descriptor.task_epoch_root_file_id_128) task_capability_sha256=$($Descriptor.task_capability_sha256) expected_broker=$ExpectedBrokerIdentitySha256 actual_broker=$($Descriptor.broker_identity_sha256) expected_task=$ExpectedTaskName callers=$callers"
    }
    $derivedTaskName='SynapseMcpBroker-'+([string]$Descriptor.task_capability_sha256).ToUpperInvariant().Substring(0,40)
    if([string]$Descriptor.task_name-cne$derivedTaskName){Die "SYNAPSE_BROKER_TASK_RECEIPT_CAPABILITY_NAME_MISMATCH root=$root expected=$derivedTaskName actual=$($Descriptor.task_name)"}
    foreach($binding in @(@{Name='slot1';Sequence=1},@{Name='slot2';Sequence=2},@{Name='slot3';Sequence=3})){
        $declared=$Descriptor.($binding.Name);$declaredNames=@(Get-SynapseObjectPropertyNames -Object $declared);$expectedNames=@('sequence','leaf','file_id_128','sha256','length')
        if($declaredNames.Count-ne$expectedNames.Count-or@($declaredNames|Where-Object{$expectedNames-cnotcontains$_}).Count-ne0-or[int]$declared.sequence-ne$binding.Sequence-or[string]$declared.leaf-cne('transaction-{0:D4}.json'-f$binding.Sequence)-or[string]$declared.file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'-or[string]$declared.sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[int64]$declared.length-lt1){Die "SYNAPSE_BROKER_TASK_RECEIPT_SLOT_DESCRIPTOR_INVALID root=$root slot=$($binding.Sequence)"}
    }
    if($StructuralOnly){return [pscustomobject][ordered]@{Root=$root;RootChain=@();Journal=$null;Initial=$null;TaskCapabilitySha256=([string]$Descriptor.task_capability_sha256).ToUpperInvariant()}}
    $rootChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $root)
    if($legacyMissingRootIdentity){
        Info "SYNAPSE_BROKER_TASK_RECEIPT_ROOT_ID_PROJECTION_MIGRATION root=$root task=$($Descriptor.task_name) physical_root_file_id_128=$($rootChain[-1].file_id_128)"
        $Descriptor.task_epoch_root_file_id_128=([string]$rootChain[-1].file_id_128).ToUpperInvariant()
    }
    if([string]$rootChain[-1].file_id_128 -ine [string]$Descriptor.task_epoch_root_file_id_128){Die "SYNAPSE_BROKER_TASK_RECEIPT_ROOT_ID_DRIFT root=$root"}
    $journal=Read-SynapseDeploymentTransactionJournal -TransactionRoot $root -TransactionRootChain $rootChain
    if($null -eq $journal -or [string]$journal.State -cne 'commit_decided' -or [string]$journal.Initial.task_capability_sha256 -ine [string]$Descriptor.task_capability_sha256 -or
       [string]$journal.Initial.broker_identity_sha256 -ine $ExpectedBrokerIdentitySha256 -or [string]$journal.Initial.task.name -cne $ExpectedTaskName){
        Die "SYNAPSE_BROKER_TASK_RECEIPT_JOURNAL_CROSSBIND_INVALID root=$root task=$ExpectedTaskName"
    }
    foreach($binding in @(@{Name='slot1';Sequence=1},@{Name='slot2';Sequence=2},@{Name='slot3';Sequence=3})){
        $declared=$Descriptor.($binding.Name);$slot=@($journal.Slots|Where-Object Sequence -EQ $binding.Sequence)
        if($slot.Count -ne 1 -or
           [string]$declared.file_id_128 -ine [string]$slot[0].FileId128 -or [string]$declared.sha256 -ine [string]$slot[0].RawSha256 -or [int64]$declared.length -ne [int64]$slot[0].ByteLength){
            Die "SYNAPSE_BROKER_TASK_RECEIPT_SLOT_DRIFT root=$root slot=$($binding.Sequence)"
        }
    }
    [void](Assert-SynapseBrokerTaskCreateInitialDescriptor -Initial $journal.Initial -TransactionRoot $root -Allocation $journal.Allocation)
    return [pscustomobject][ordered]@{Root=$root;RootChain=$rootChain;Journal=$journal;Initial=$journal.Initial;TaskCapabilitySha256=([string]$Descriptor.task_capability_sha256).ToUpperInvariant()}
}

function ConvertTo-SynapseAuthorityFileDescriptor {
    param(
        [Parameter(Mandatory=$true)]$Identity,
        [Parameter(Mandatory=$true)][ValidatePattern('^[a-z0-9_]{1,64}$')][string]$Role
    )

    $path = [System.IO.Path]::GetFullPath([string](Get-SynapseObjectPropertyValue -Object $Identity -Names @('path','Path')))
    $parentRaw = [string](Get-SynapseObjectPropertyValue -Object $Identity -Names @('parent_path','ParentPath'))
    $parentPath = if ([string]::IsNullOrWhiteSpace($parentRaw)) { [System.IO.Path]::GetFullPath((Split-Path -Parent $path)) } else { [System.IO.Path]::GetFullPath($parentRaw) }
    $fileId = [string](Get-SynapseObjectPropertyValue -Object $Identity -Names @('file_id_128','FileId128'))
    $sha256 = [string](Get-SynapseObjectPropertyValue -Object $Identity -Names @('sha256','Sha256'))
    $length = [int64](Get-SynapseObjectPropertyValue -Object $Identity -Names @('length','Length'))
    $parentFileId = [string](Get-SynapseObjectPropertyValue -Object $Identity -Names @('parent_file_id_128','ParentFileId128'))
    if ($fileId -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or
        $sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or $length -lt 0 -or
        $parentFileId -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or
        $parentPath -ine [System.IO.Path]::GetFullPath((Split-Path -Parent $path))) {
        Die "SYNAPSE_AUTHORITY_FILE_DESCRIPTOR_BUILD_INVALID role=$Role path=$path file_id_128=$fileId sha256=$sha256 length=$length parent=$parentPath parent_file_id_128=$parentFileId"
    }
    $result=[ordered]@{
        role=$Role; path=$path; file_id_128=$fileId.ToUpperInvariant(); sha256=$sha256.ToUpperInvariant(); length=$length
        parent_path=$parentPath; parent_file_id_128=$parentFileId.ToUpperInvariant()
    }
    if(Test-SynapseProtectedOsInterpreterRole -Role $Role){
        $protectedOsValue=Get-SynapseObjectPropertyValue -Object $Identity -Names @('protected_os')
        if($null -eq $protectedOsValue){Die "SYNAPSE_PROTECTED_OS_DESCRIPTOR_BUILD_CONTRACT_MISSING role=$Role path=$path"}
        $result.protected_os=ConvertTo-SynapseCanonicalValue -Value $protectedOsValue
        [void](Assert-SynapseProtectedOsInterpreterDescriptorPhysicalIdentity -Descriptor ([pscustomobject]$result) -ExpectedRole $Role -Context "descriptor_build_$Role")
    }elseif($null-ne(Get-SynapseObjectPropertyValue -Object $Identity -Names @('protected_os'))){
        Die "SYNAPSE_PROTECTED_OS_DESCRIPTOR_BUILD_ROLE_MISMATCH role=$Role path=$path"
    }
    return $result
}

function Assert-SynapseAuthorityFileDescriptorPhysicalIdentity {
    param(
        [Parameter(Mandatory=$true)]$Descriptor,
        [Parameter(Mandatory=$true)][ValidatePattern('^[a-z0-9_]{1,64}$')][string]$ExpectedRole,
        [Parameter(Mandatory=$true)][string]$Context,
        [string]$ExpectedParent = ''
    )

    if(Test-SynapseProtectedOsInterpreterRole -Role $ExpectedRole){
        return Assert-SynapseProtectedOsInterpreterDescriptorPhysicalIdentity -Descriptor $Descriptor -ExpectedRole $ExpectedRole -Context $Context -ExpectedParent $ExpectedParent
    }
    $names = if($Descriptor-is[System.Collections.IDictionary]){@($Descriptor.Keys|ForEach-Object{[string]$_})}else{@($Descriptor.PSObject.Properties.Name)}
    $expectedNames = @('role','path','file_id_128','sha256','length','parent_path','parent_file_id_128')
    $path = [System.IO.Path]::GetFullPath([string]$Descriptor.path)
    $parent = Get-SynapseNormalizedDirectoryPath -Path ([string]$Descriptor.parent_path)
    if ($names.Count -ne $expectedNames.Count -or @($names | Where-Object { $expectedNames -cnotcontains $_ }).Count -gt 0 -or
        [string]$Descriptor.role -cne $ExpectedRole -or
        [string]$Descriptor.file_id_128 -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or
        [string]$Descriptor.sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [int64]$Descriptor.length -lt 0 -or
        [string]$Descriptor.parent_file_id_128 -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or
        $parent -ine [System.IO.Path]::GetFullPath((Split-Path -Parent $path)) -or
        ($ExpectedParent -and $parent -ine (Get-SynapseNormalizedDirectoryPath -Path $ExpectedParent))) {
        Die "SYNAPSE_AUTHORITY_FILE_DESCRIPTOR_INVALID context=$Context role=$($Descriptor.role) expected_role=$ExpectedRole path=$path parent=$parent"
    }
    if (-not (Test-Path -LiteralPath $parent -PathType Container)) {
        $stack=(Get-PSCallStack|ForEach-Object{"$($_.FunctionName):$($_.ScriptLineNumber)"})-join','
        Die "SYNAPSE_AUTHORITY_FILE_PARENT_ABSENT context=$Context role=$ExpectedRole path=$path parent=$parent call_stack=$stack remediation=preserve the sealed failed transaction and classify the missing generation through its owning recovery journal; never recreate an authority parent by pathname"
    }
    $chain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $parent)
    if ([string]$chain[-1].file_id_128 -ine [string]$Descriptor.parent_file_id_128) {
        Die "SYNAPSE_AUTHORITY_FILE_PARENT_ID_DRIFT context=$Context role=$ExpectedRole path=$path expected_parent_file_id_128=$($Descriptor.parent_file_id_128) actual_parent_file_id_128=$($chain[-1].file_id_128)"
    }
    $state = Get-SynapsePhysicalRelativeState -ParentPath $parent -ParentChain $chain -Leaf (Split-Path -Leaf $path)
    $exactPhysical=Test-SynapsePhysicalStateExact -State $state -ExpectedExists $true -ExpectedFileId128 ([string]$Descriptor.file_id_128) -ExpectedSha256 ([string]$Descriptor.sha256) -ExpectedLength ([int64]$Descriptor.length)
    $legacyOrderedLengthMigration = (
        -not $exactPhysical -and
        $ExpectedRole -ceq 'legacy_vbs_launcher' -and
        [int64]$Descriptor.length -eq 1 -and
        [bool]$state.Exists -and
        -not [bool]$state.IsDirectory -and
        [int64]$state.Length -gt 1 -and
        [int64]$state.Length -le 65536 -and
        ([string]$state.FileId128 -ieq [string]$Descriptor.file_id_128) -and
        ([string]$state.Sha256 -ieq [string]$Descriptor.sha256)
    )
    if (-not $exactPhysical -and -not $legacyOrderedLengthMigration) {
        Die "SYNAPSE_AUTHORITY_FILE_IDENTITY_DRIFT context=$Context role=$ExpectedRole path=$path expected_file_id_128=$($Descriptor.file_id_128) actual_file_id_128=$($state.FileId128) expected_sha256=$($Descriptor.sha256) actual_sha256=$($state.Sha256)"
    }
    if ($legacyOrderedLengthMigration) {
        Info "SYNAPSE_LEGACY_VBS_ORDERED_DICTIONARY_LENGTH_MIGRATION context=$Context path=$path sealed_length=1 physical_length=$($state.Length) file_id_128=$($state.FileId128) sha256=$($state.Sha256)"
    }
    return [pscustomobject][ordered]@{
        Role=$ExpectedRole; Path=$path; FileId128=([string]$Descriptor.file_id_128).ToUpperInvariant()
        Sha256=([string]$Descriptor.sha256).ToUpperInvariant(); Length=$(if ($legacyOrderedLengthMigration) { [int64]$state.Length } else { [int64]$Descriptor.length })
        ParentPath=$parent; ParentFileId128=([string]$Descriptor.parent_file_id_128).ToUpperInvariant(); Chain=$chain
    }
}

function Get-SynapseAuthorityProfilesIdentity {
    param([Parameter(Mandatory=$true)][string]$ProfilesDir)
    $root=Get-SynapseNormalizedDirectoryPath -Path $ProfilesDir
    $chain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $root)
    $manifestLeaf=$script:SynapseBundledProfilesManifestFileName
    $manifest=Get-SynapsePhysicalRelativeState -ParentPath $root -ParentChain $chain -Leaf $manifestLeaf
    if(-not $manifest.Exists -or [bool]$manifest.IsDirectory){
        Die "SYNAPSE_AUTHORITY_PROFILE_MANIFEST_MISSING profiles_dir=$root manifest=$manifestLeaf remediation=broker migration requires one exact prior setup-owned profile generation"
    }
    $identity=[ordered]@{
        profiles_dir=$root
        profiles_root_file_id_128=([string]$chain[-1].file_id_128).ToUpperInvariant()
        manifest_path=[System.IO.Path]::GetFullPath((Join-Path $root $manifestLeaf))
        manifest_file_id_128=([string]$manifest.FileId128).ToUpperInvariant()
        manifest_sha256=([string]$manifest.Sha256).ToUpperInvariant()
        manifest_length=[int64]$manifest.Length
    }
    return [pscustomobject][ordered]@{
        Identity=$identity
        Sha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $identity)).ToUpperInvariant()
        RootFileId128=([string]$chain[-1].file_id_128).ToUpperInvariant()
        Manifest=(Get-SynapseRuntimeFileIdentityForAuthority -Path $identity.manifest_path -Role 'profile_manifest')
    }
}

function New-SynapseAuthorityGenerationPlan {
    param(
        [Parameter(Mandatory=$true)]$Layout,
        [Parameter(Mandatory=$true)]$Infrastructure,
        [Parameter(Mandatory=$true)]$BrokerTask,
        [Parameter(Mandatory=$true)][ValidatePattern('^[0-9A-Fa-f]{64}$')][string]$ControlNonce,
        [Parameter(Mandatory=$true)]$LegacyGate,
        [ValidateRange(1,[long]::MaxValue)][long]$AuthorityEpoch,
        [Parameter(Mandatory=$true)][ValidateSet('prior','candidate')][string]$Role,
        [Parameter(Mandatory=$true)][string]$ExePath,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$DbPath,
        [Parameter(Mandatory=$true)][string]$ProfilesDir,
        [Parameter(Mandatory=$true)][string]$LogDir,
        [Parameter(Mandatory=$true)][string]$TokenPath,
        [Parameter(Mandatory=$true)][string]$MaintenanceLockPath,
        [Parameter(Mandatory=$true)][string]$CalyxConfigPath,
        [Parameter(Mandatory=$true)][ValidatePattern('^[0-9A-Fa-f]{64}$')][string]$ExpectedCalyxConfigSha256,
        [bool]$EnableAudio,
        [AllowNull()][string]$AllowedPermissions,
        [Parameter(Mandatory=$true)][string]$PowerShellPath,
        [Parameter(Mandatory=$true)][string]$WorkingDirectory,
        [ValidateRange(1,4096)][int]$ExpectedToolCount,
        [Parameter(Mandatory=$true)][ValidatePattern('^[0-9A-Fa-f]{64}$')][string]$ExpectedToolSurfaceSha256,
        [Parameter(Mandatory=$true)][string]$InvocationId,
        [ValidateRange(1,[long]::MaxValue)][long]$RosterRevision,
        [long]$PreviousRevision=0,
        [string]$PreviousFileId128='',
        [string]$PreviousSha256='',
        [long]$PreviousLength=-1
    )

    $exe=Get-SynapseRuntimeFileIdentityForAuthority -Path $ExePath -Role 'daemon'
    $config=Get-SynapseRuntimeFileIdentityForAuthority -Path $CalyxConfigPath -Role 'calyx_config'
    if([string]$config.sha256 -ine $ExpectedCalyxConfigSha256){
        Die "SYNAPSE_AUTHORITY_GENERATION_CONFIG_DRIFT role=$Role path=$CalyxConfigPath expected_sha256=$ExpectedCalyxConfigSha256 actual_sha256=$($config.sha256)"
    }
    $profiles=Get-SynapseAuthorityProfilesIdentity -ProfilesDir $ProfilesDir
    $objects=@()
    $seen=New-SynapseCaseInsensitiveMap
    $runtimeCandidates=@()
    $runtimeCandidates+=@(Get-SynapseOrtRuntimeCompanions -ExecutablePath $ExePath | ForEach-Object {
        $roleName=('runtime_'+[string]$_.Name).ToLowerInvariant() -replace '[^a-z0-9_]','_'
        [pscustomobject]@{Path=[string]$_.Path;Role=$roleName}
    })
    $runtimeCandidates+=,[pscustomobject]@{Path=$TokenPath;Role='bearer_token'}
    $runtimeCandidates+=,[pscustomobject]@{Path=[string]$profiles.Manifest.path;Role='profile_manifest'}
    foreach($candidate in $runtimeCandidates){
        if($null -eq $candidate){continue}
        $path=[System.IO.Path]::GetFullPath([string]$candidate.Path)
        if($seen.ContainsKey($path)){continue}
        $seen[$path]=$true
        $objects+=,(Get-SynapseRuntimeFileIdentityForAuthority -Path $path -Role ([string]$candidate.Role))
    }
    $runtimeIdentity=[ordered]@{
        executable=$exe
        calyx_config=$config
        objects=@($objects|Sort-Object path)
        daemon_argument_text=(Get-SynapseDaemonArgumentText -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions -CalyxConfigPath $CalyxConfigPath -ExpectedCalyxConfigSha256 $ExpectedCalyxConfigSha256 -CalyxSstWriteVersion $(if($Role -ceq 'prior'){2}else{3}))
    }
    $runtimeSha=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $runtimeIdentity)).ToUpperInvariant()
    $generationCore=[ordered]@{role=$Role;authority_epoch=[int64]$AuthorityEpoch;runtime_generation_sha256=$runtimeSha;profile_generation_sha256=$profiles.Sha256;tool_count=$ExpectedToolCount;tool_surface_sha256=$ExpectedToolSurfaceSha256.ToUpperInvariant()}
    $generationId="$Role-"+(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $generationCore)).Substring(0,40).ToLowerInvariant()
    $generationLaunchCapability=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value ([ordered]@{schema='synapse_generation_launch_capability/v1';broker_identity_sha256=([string]$Infrastructure.BrokerIdentitySha256).ToUpperInvariant();task_capability_sha256=([string]$Infrastructure.TaskCapabilitySha256).ToUpperInvariant();authority_epoch=[int64]$AuthorityEpoch;generation_id=$generationId;runtime_generation_sha256=$runtimeSha;profile_generation_sha256=([string]$profiles.Sha256).ToUpperInvariant();invocation_id=$InvocationId}))).ToUpperInvariant()
    if($generationLaunchCapability -ieq [string]$Infrastructure.BrokerIdentitySha256){Die "SYNAPSE_AUTHORITY_GENERATION_CAPABILITY_DOMAIN_CONFLATION generation=$generationId"}
    $supervisorCandidate=New-HiddenDaemonLauncher `
        -OutputPath (Join-Path $Layout.Objects "generation-$Role-$AuthorityEpoch-launcher.placeholder") `
        -ExePath $ExePath -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -LogDir $LogDir -TokenPath $TokenPath `
        -MaintenanceLockPath $MaintenanceLockPath -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions `
        -CalyxConfigPath $CalyxConfigPath -ExpectedCalyxConfigSha256 $ExpectedCalyxConfigSha256 `
        -CalyxSstWriteVersion $(if($Role -ceq 'prior'){2}else{3}) `
        -AuthorityMode broker -AuthorityRosterPath $Layout.RosterPath -AuthorityLegacyGatePath $LegacyGate.Path `
        -AuthorityLegacyGateFileId128 $LegacyGate.FileId128 -AuthorityLegacyGateSha256 $LegacyGate.Sha256 -AuthorityLegacyGateLength $LegacyGate.Length `
        -AuthorityEpoch $AuthorityEpoch -AuthorityGenerationId $generationId -AuthorityLaunchCapabilitySha256 $generationLaunchCapability -AuthorityBrokerTaskName $BrokerTask.Name `
        -AuthorityBrokerScriptPath $Infrastructure.BrokerScript.Path -AuthorityBrokerScriptSha256 $Infrastructure.BrokerScript.Sha256 `
        -AuthorityBootstrapPath $Infrastructure.Bootstrap.Path -AuthorityBootstrapSha256 $Infrastructure.Bootstrap.Sha256 -ExpectedParentJobCpuRate 10000 -ContentOnly
    $supervisorContent=New-SynapseSupervisorLaunchContractContent -Body ([string]$supervisorCandidate.Content) -Role generation_inner -Mode nested_job -Bootstrap $Infrastructure.Bootstrap -PowerShell $Infrastructure.PowerShell -BrokerIdentitySha256 $Infrastructure.BrokerIdentitySha256 -LaunchCapabilitySha256 $generationLaunchCapability -OuterLaunchCapabilitySha256 $Infrastructure.TaskCapabilitySha256 -AuthorityEpoch $AuthorityEpoch -ExpectedJobCpuRate 10000
    $supervisorSha=(Get-SynapseSha256Hex -Text $supervisorContent).ToUpperInvariant();$supervisorLength=[System.Text.UTF8Encoding]::new($false,$true).GetByteCount($supervisorContent)
    $supervisor=Install-SynapseAuthorityImmutableFile -Layout $Layout -Leaf "authority-supervisor-$supervisorSha.ps1" -Content $supervisorContent -FromContent -ExpectedSha256 $supervisorSha -ExpectedLength $supervisorLength -Context "authority_${Role}_supervisor"
    $payload=New-SynapseAuthorityRosterPayload `
        -BrokerIdentitySha256 $Infrastructure.BrokerIdentitySha256 -TaskCapabilitySha256 $Infrastructure.TaskCapabilitySha256 -AuthorityEpoch $AuthorityEpoch -Revision $RosterRevision -Mode active -Role $Role `
        -BrokerTask $BrokerTask -AuthorityRoot $Layout.Root -AuthorityRootFileId128 ([string]$Layout.RootChain[-1].file_id_128) `
        -RuntimeBinDir $Layout.RuntimeBinDir -RuntimeBinFileId128 ([string]$Layout.RuntimeChain[-1].file_id_128) `
        -BrokerScript $Infrastructure.BrokerScript -Bootstrap $Infrastructure.Bootstrap -ControlGatePath $Layout.ControlGatePath -ControlNonce $ControlNonce -LegacyGate $LegacyGate `
        -GenerationId $generationId -GenerationLaunchCapabilitySha256 $generationLaunchCapability -GenerationSupervisor $supervisor -Executable ([pscustomobject]@{Path=$exe.path;ParentPath=$exe.parent_path;ParentFileId128=$exe.parent_file_id_128;FileId128=$exe.file_id_128;Sha256=$exe.sha256;Length=$exe.length}) `
        -CalyxConfig ([pscustomobject]@{Path=$config.path;ParentPath=$config.parent_path;ParentFileId128=$config.parent_file_id_128;FileId128=$config.file_id_128;Sha256=$config.sha256;Length=$config.length}) -GenerationObjects $objects `
        -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -ProfilesRootFileId128 $profiles.RootFileId128 -TokenPath $TokenPath `
        -DaemonArgumentText $runtimeIdentity.daemon_argument_text -CalyxConfigPath $CalyxConfigPath -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions `
        -PowerShellPath $PowerShellPath -WorkingDirectory $WorkingDirectory -LogDir $LogDir -BrokerBootstrapLogPath $Infrastructure.BootstrapLogPath -MaintenanceLockPath $MaintenanceLockPath -InvocationId $InvocationId `
        -ExpectedToolCount $ExpectedToolCount -ExpectedToolSurfaceSha256 $ExpectedToolSurfaceSha256 -RuntimeGenerationSha256 $runtimeSha -ProfileGenerationSha256 $profiles.Sha256 `
        -PreviousRevision $PreviousRevision -PreviousFileId128 $PreviousFileId128 -PreviousSha256 $PreviousSha256 -PreviousLength $PreviousLength
    $envelope=New-SynapseAuthorityRosterEnvelope -Payload $payload
    return [pscustomobject][ordered]@{
        Role=$Role;GenerationId=$generationId;Executable=$exe;CalyxConfig=$config;Profiles=$profiles;GenerationObjects=$objects
        Supervisor=$supervisor;LaunchCapabilitySha256=$generationLaunchCapability;RuntimeGenerationIdentity=$runtimeIdentity;RuntimeGenerationSha256=$runtimeSha;ProfileGenerationSha256=$profiles.Sha256
        RosterPayload=$payload;RosterEnvelope=$envelope
    }
}

function New-SynapseAuthorityProspectiveGenerationPlan {
    param(
        [Parameter(Mandatory=$true)]$Layout,
        [Parameter(Mandatory=$true)]$Infrastructure,
        [Parameter(Mandatory=$true)]$BrokerTask,
        [Parameter(Mandatory=$true)][ValidatePattern('^[0-9A-Fa-f]{64}$')][string]$ControlNonce,
        [Parameter(Mandatory=$true)]$LegacyGate,
        [ValidateRange(1,[long]::MaxValue)][long]$AuthorityEpoch,
        [Parameter(Mandatory=$true)]$RuntimePlan,
        [Parameter(Mandatory=$true)]$ProfilePlan,
        [Parameter(Mandatory=$true)][string]$ExePath,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$DbPath,
        [Parameter(Mandatory=$true)][string]$ProfilesDir,
        [Parameter(Mandatory=$true)][string]$LogDir,
        [Parameter(Mandatory=$true)][string]$TokenPath,
        [Parameter(Mandatory=$true)][string]$MaintenanceLockPath,
        [Parameter(Mandatory=$true)][string]$CalyxConfigPath,
        [Parameter(Mandatory=$true)][ValidatePattern('^[0-9A-Fa-f]{64}$')][string]$ExpectedCalyxConfigSha256,
        [bool]$EnableAudio,
        [AllowNull()][string]$AllowedPermissions,
        [Parameter(Mandatory=$true)][string]$PowerShellPath,
        [Parameter(Mandatory=$true)][string]$WorkingDirectory,
        [ValidateRange(1,4096)][int]$ExpectedToolCount,
        [Parameter(Mandatory=$true)][ValidatePattern('^[0-9A-Fa-f]{64}$')][string]$ExpectedToolSurfaceSha256,
        [Parameter(Mandatory=$true)][string]$InvocationId,
        [ValidateRange(1,[long]::MaxValue)][long]$RosterRevision,
        [long]$PreviousRevision=0,
        [string]$PreviousFileId128='',
        [string]$PreviousSha256='',
        [long]$PreviousLength=-1
    )
    $runtimeRecords=@($RuntimePlan.Records)
    $exeFull=[System.IO.Path]::GetFullPath($ExePath)
    $exeRecords=@($runtimeRecords|Where-Object{[System.IO.Path]::GetFullPath([string]$_.path) -ieq $exeFull})
    if($exeRecords.Count -ne 1){Die "SYNAPSE_AUTHORITY_PROSPECTIVE_DAEMON_RECORD_INVALID path=$exeFull count=$($exeRecords.Count)"}
    $exeRecord=$exeRecords[0]
    $exe=ConvertTo-SynapseAuthorityFileDescriptor -Identity ([pscustomobject]@{Path=$exeFull;FileId128=[string]$exeRecord.post_file_id_128;Sha256=[string]$exeRecord.post_sha256;Length=[int64]$exeRecord.post_length;ParentPath=[string]$exeRecord.parent;ParentFileId128=[string]$exeRecord.parent_chain[-1].file_id_128}) -Role daemon
    $config=Get-SynapseRuntimeFileIdentityForAuthority -Path $CalyxConfigPath -Role 'calyx_config'
    if([string]$config.sha256 -ine $ExpectedCalyxConfigSha256){Die "SYNAPSE_AUTHORITY_PROSPECTIVE_CONFIG_DRIFT path=$CalyxConfigPath expected=$ExpectedCalyxConfigSha256 actual=$($config.sha256)"}
    $objects=@();$seen=New-SynapseCaseInsensitiveMap
    foreach($record in @($runtimeRecords|Where-Object{[System.IO.Path]::GetFullPath([string]$_.path) -ine $exeFull}|Sort-Object path)){
        $path=[System.IO.Path]::GetFullPath([string]$record.path)
        if($seen.ContainsKey($path)){Die "SYNAPSE_AUTHORITY_PROSPECTIVE_RUNTIME_DUPLICATE path=$path"};$seen[$path]=$true
        $role='runtime_'+(([System.IO.Path]::GetFileName($path).ToLowerInvariant()) -replace '[^a-z0-9_]','_')
        if($role.Length -gt 64){$role=$role.Substring(0,48)+'_'+(Get-SynapseSha256Hex -Text $path).Substring(0,15).ToLowerInvariant()}
        $objects+=,(ConvertTo-SynapseAuthorityFileDescriptor -Identity ([pscustomobject]@{Path=$path;FileId128=[string]$record.post_file_id_128;Sha256=[string]$record.post_sha256;Length=[int64]$record.post_length;ParentPath=[string]$record.parent;ParentFileId128=[string]$record.parent_chain[-1].file_id_128}) -Role $role)
    }
    $token=Get-SynapseRuntimeFileIdentityForAuthority -Path $TokenPath -Role 'bearer_token'
    if($seen.ContainsKey([string]$token.path)){Die "SYNAPSE_AUTHORITY_PROSPECTIVE_TOKEN_DUPLICATE path=$($token.path)"};$seen[[string]$token.path]=$true;$objects+=,$token
    $profile=$ProfilePlan.Validated
    $manifest=$profile.ManifestEntry
    $manifestPath=[System.IO.Path]::GetFullPath((Join-Path $profile.ProfilesDir $script:SynapseBundledProfilesManifestFileName))
    if($seen.ContainsKey($manifestPath)){Die "SYNAPSE_AUTHORITY_PROSPECTIVE_MANIFEST_DUPLICATE path=$manifestPath"};$seen[$manifestPath]=$true
    $manifestDescriptor=ConvertTo-SynapseAuthorityFileDescriptor -Identity ([pscustomobject]@{Path=$manifestPath;FileId128=[string]$manifest.post_file_id_128;Sha256=[string]$manifest.post_sha256;Length=[int64]$manifest.post_length;ParentPath=[string]$profile.ProfilesDir;ParentFileId128=[string]$profile.RootFileId128}) -Role profile_manifest
    $objects+=,$manifestDescriptor;$objects=@($objects|Sort-Object path)
    $profileIdentity=[ordered]@{profiles_dir=$profile.ProfilesDir;profiles_root_file_id_128=([string]$profile.RootFileId128).ToUpperInvariant();manifest_path=$manifestPath;manifest_file_id_128=([string]$manifest.post_file_id_128).ToUpperInvariant();manifest_sha256=([string]$manifest.post_sha256).ToUpperInvariant();manifest_length=[int64]$manifest.post_length}
    $profileSha=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $profileIdentity)).ToUpperInvariant()
    $daemonArgumentText=Get-SynapseDaemonArgumentText -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions -CalyxConfigPath $CalyxConfigPath -ExpectedCalyxConfigSha256 $ExpectedCalyxConfigSha256
    $runtimeIdentity=[ordered]@{executable=$exe;calyx_config=$config;objects=$objects;daemon_argument_text=$daemonArgumentText}
    $runtimeSha=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $runtimeIdentity)).ToUpperInvariant()
    $generationCore=[ordered]@{role='candidate';authority_epoch=[int64]$AuthorityEpoch;runtime_generation_sha256=$runtimeSha;profile_generation_sha256=$profileSha;tool_count=$ExpectedToolCount;tool_surface_sha256=$ExpectedToolSurfaceSha256.ToUpperInvariant()}
    $generationId='candidate-'+(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $generationCore)).Substring(0,40).ToLowerInvariant()
    $generationLaunchCapability=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value ([ordered]@{schema='synapse_generation_launch_capability/v1';broker_identity_sha256=([string]$Infrastructure.BrokerIdentitySha256).ToUpperInvariant();task_capability_sha256=([string]$Infrastructure.TaskCapabilitySha256).ToUpperInvariant();authority_epoch=[int64]$AuthorityEpoch;generation_id=$generationId;runtime_generation_sha256=$runtimeSha;profile_generation_sha256=$profileSha;invocation_id=$InvocationId}))).ToUpperInvariant()
    if($generationLaunchCapability -ieq [string]$Infrastructure.BrokerIdentitySha256){Die "SYNAPSE_AUTHORITY_GENERATION_CAPABILITY_DOMAIN_CONFLATION generation=$generationId"}
    $supervisorCandidate=New-HiddenDaemonLauncher -OutputPath (Join-Path $Layout.Objects "generation-candidate-$AuthorityEpoch-launcher.placeholder") -ExePath $ExePath -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -LogDir $LogDir -TokenPath $TokenPath -MaintenanceLockPath $MaintenanceLockPath -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions -CalyxConfigPath $CalyxConfigPath -ExpectedCalyxConfigSha256 $ExpectedCalyxConfigSha256 -AuthorityMode broker -AuthorityRosterPath $Layout.RosterPath -AuthorityLegacyGatePath $LegacyGate.Path -AuthorityLegacyGateFileId128 $LegacyGate.FileId128 -AuthorityLegacyGateSha256 $LegacyGate.Sha256 -AuthorityLegacyGateLength $LegacyGate.Length -AuthorityEpoch $AuthorityEpoch -AuthorityGenerationId $generationId -AuthorityLaunchCapabilitySha256 $generationLaunchCapability -AuthorityBrokerTaskName $BrokerTask.Name -AuthorityBrokerScriptPath $Infrastructure.BrokerScript.Path -AuthorityBrokerScriptSha256 $Infrastructure.BrokerScript.Sha256 -AuthorityBootstrapPath $Infrastructure.Bootstrap.Path -AuthorityBootstrapSha256 $Infrastructure.Bootstrap.Sha256 -ExpectedParentJobCpuRate 10000 -ContentOnly
    $supervisorContent=New-SynapseSupervisorLaunchContractContent -Body ([string]$supervisorCandidate.Content) -Role generation_inner -Mode nested_job -Bootstrap $Infrastructure.Bootstrap -PowerShell $Infrastructure.PowerShell -BrokerIdentitySha256 $Infrastructure.BrokerIdentitySha256 -LaunchCapabilitySha256 $generationLaunchCapability -OuterLaunchCapabilitySha256 $Infrastructure.TaskCapabilitySha256 -AuthorityEpoch $AuthorityEpoch -ExpectedJobCpuRate 10000
    $supervisorSha=(Get-SynapseSha256Hex -Text $supervisorContent).ToUpperInvariant();$supervisorLength=[System.Text.UTF8Encoding]::new($false,$true).GetByteCount($supervisorContent)
    $supervisor=Install-SynapseAuthorityImmutableFile -Layout $Layout -Leaf "authority-supervisor-$supervisorSha.ps1" -Content $supervisorContent -FromContent -ExpectedSha256 $supervisorSha -ExpectedLength $supervisorLength -Context 'authority_candidate_prospective_supervisor'
    $payload=New-SynapseAuthorityRosterPayload -BrokerIdentitySha256 $Infrastructure.BrokerIdentitySha256 -TaskCapabilitySha256 $Infrastructure.TaskCapabilitySha256 -AuthorityEpoch $AuthorityEpoch -Revision $RosterRevision -Mode active -Role candidate -BrokerTask $BrokerTask -AuthorityRoot $Layout.Root -AuthorityRootFileId128 ([string]$Layout.RootChain[-1].file_id_128) -RuntimeBinDir $Layout.RuntimeBinDir -RuntimeBinFileId128 ([string]$Layout.RuntimeChain[-1].file_id_128) -BrokerScript $Infrastructure.BrokerScript -Bootstrap $Infrastructure.Bootstrap -ControlGatePath $Layout.ControlGatePath -ControlNonce $ControlNonce -LegacyGate $LegacyGate -GenerationId $generationId -GenerationLaunchCapabilitySha256 $generationLaunchCapability -GenerationSupervisor $supervisor -Executable ([pscustomobject]@{Path=$exe.path;ParentPath=$exe.parent_path;ParentFileId128=$exe.parent_file_id_128;FileId128=$exe.file_id_128;Sha256=$exe.sha256;Length=$exe.length}) -CalyxConfig ([pscustomobject]@{Path=$config.path;ParentPath=$config.parent_path;ParentFileId128=$config.parent_file_id_128;FileId128=$config.file_id_128;Sha256=$config.sha256;Length=$config.length}) -GenerationObjects $objects -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -ProfilesRootFileId128 ([string]$profile.RootFileId128) -TokenPath $TokenPath -DaemonArgumentText $daemonArgumentText -CalyxConfigPath $CalyxConfigPath -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions -PowerShellPath $PowerShellPath -WorkingDirectory $WorkingDirectory -LogDir $LogDir -BrokerBootstrapLogPath $Infrastructure.BootstrapLogPath -MaintenanceLockPath $MaintenanceLockPath -InvocationId $InvocationId -ExpectedToolCount $ExpectedToolCount -ExpectedToolSurfaceSha256 $ExpectedToolSurfaceSha256 -RuntimeGenerationSha256 $runtimeSha -ProfileGenerationSha256 $profileSha -PreviousRevision $PreviousRevision -PreviousFileId128 $PreviousFileId128 -PreviousSha256 $PreviousSha256 -PreviousLength $PreviousLength
    $envelope=New-SynapseAuthorityRosterEnvelope -Payload $payload
    return [pscustomobject][ordered]@{Role='candidate';GenerationId=$generationId;LaunchCapabilitySha256=$generationLaunchCapability;Executable=$exe;CalyxConfig=$config;Profiles=[pscustomobject]@{Identity=$profileIdentity;Sha256=$profileSha;RootFileId128=$profile.RootFileId128;Manifest=$manifestDescriptor};GenerationObjects=$objects;Supervisor=$supervisor;RuntimeGenerationIdentity=$runtimeIdentity;RuntimeGenerationSha256=$runtimeSha;ProfileGenerationSha256=$profileSha;RosterPayload=$payload;RosterEnvelope=$envelope}
}

function ConvertTo-SynapseAuthorityGenerationFromCurrentRoster {
    param(
        [Parameter(Mandatory=$true)]$Layout,
        [Parameter(Mandatory=$true)]$Infrastructure,
        [Parameter(Mandatory=$true)]$ControlGate,
        [Parameter(Mandatory=$true)]$Roster,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $p=$Roster.Payload
    if([string]$p.mode -cne 'active' -or [string]$p.role -notin @('prior','candidate') -or
        [string]$p.broker_identity_sha256 -ine [string]$Infrastructure.BrokerIdentitySha256 -or
        [string]$p.broker_task_capability_sha256 -ine [string]$Infrastructure.TaskCapabilitySha256 -or
        [string]$p.broker_task_name -cne [string]$Infrastructure.Task.Name -or
        [string]$p.broker_task_xml_sha256 -ine [string]$Infrastructure.Task.XmlSha256 -or
        [string]$p.broker_task_security_descriptor_sha256 -ine [string]$Infrastructure.Task.SecurityDescriptorSha256 -or
        (Get-SynapseNormalizedDirectoryPath -Path ([string]$p.authority_root_path)) -ine [string]$Layout.Root -or
        [string]$p.authority_root_file_id_128 -ine [string]$Layout.RootChain[-1].file_id_128 -or
        (Get-SynapseNormalizedDirectoryPath -Path ([string]$p.runtime_bin_dir)) -ine [string]$Layout.RuntimeBinDir -or
        [string]$p.runtime_bin_file_id_128 -ine [string]$Layout.RuntimeChain[-1].file_id_128 -or
        [System.IO.Path]::GetFullPath([string]$p.broker_script_path) -ine [System.IO.Path]::GetFullPath([string]$Infrastructure.BrokerScript.Path) -or
        [System.IO.Path]::GetFullPath([string]$p.broker_script_parent_path) -ine [System.IO.Path]::GetFullPath([string]$Infrastructure.BrokerScript.ParentPath) -or
        [string]$p.broker_script_parent_file_id_128 -ine [string]$Infrastructure.BrokerScript.ParentFileId128 -or
        [string]$p.broker_script_file_id_128 -ine [string]$Infrastructure.BrokerScript.FileId128 -or
        [string]$p.broker_script_sha256 -ine [string]$Infrastructure.BrokerScript.Sha256 -or
        [int64]$p.broker_script_length -ne [int64]$Infrastructure.BrokerScript.Length -or
        [System.IO.Path]::GetFullPath([string]$p.bootstrap_path) -ine [System.IO.Path]::GetFullPath([string]$Infrastructure.Bootstrap.Path) -or
        [System.IO.Path]::GetFullPath([string]$p.bootstrap_parent_path) -ine [System.IO.Path]::GetFullPath([string]$Infrastructure.Bootstrap.ParentPath) -or
        [string]$p.bootstrap_parent_file_id_128 -ine [string]$Infrastructure.Bootstrap.ParentFileId128 -or
        [string]$p.bootstrap_file_id_128 -ine [string]$Infrastructure.Bootstrap.FileId128 -or
        [string]$p.bootstrap_sha256 -ine [string]$Infrastructure.Bootstrap.Sha256 -or
        [int64]$p.bootstrap_length -ne [int64]$Infrastructure.Bootstrap.Length -or
        [System.IO.Path]::GetFullPath([string]$p.control_gate_path) -ine [System.IO.Path]::GetFullPath([string]$Layout.ControlGatePath) -or
        [string]$p.control_nonce -ine [string]$ControlGate.Payload.control_nonce -or
        [System.IO.Path]::GetFullPath([string]$p.legacy_gate_path) -ine [System.IO.Path]::GetFullPath([string]$Layout.LegacyGatePath)){
        Die "SYNAPSE_AUTHORITY_CURRENT_ROSTER_CONTEXT_MISMATCH context=$Context generation=$($p.generation_id) role=$($p.role)"
    }
    if([string]$ControlGate.Payload.state -cne 'active' -or [string]$ControlGate.Payload.broker_identity_sha256 -ine [string]$p.broker_identity_sha256 -or
       [int64]$ControlGate.Payload.authority_epoch -ne [int64]$p.authority_epoch -or [string]$ControlGate.Payload.roster_file_id_128 -ine [string]$Roster.FileId128 -or
       [string]$ControlGate.Payload.roster_sha256 -ine [string]$Roster.Sha256 -or [int64]$ControlGate.Payload.roster_length -ne [int64]$Roster.Length){
        Die "SYNAPSE_AUTHORITY_CURRENT_CONTROL_PAIR_INVALID context=$Context generation=$($p.generation_id) gate_state=$($ControlGate.Payload.state)"
    }
    foreach($absolutePath in @($p.exe_path,$p.exe_parent_path,$p.db_path,$p.profiles_dir,$p.token_path,$p.calyx_config_path,$p.calyx_config_parent_path,$p.working_directory,$p.log_dir,$p.maintenance_lock_path,$p.broker_state_path,$p.bootstrap_log_path)){
        if([string]::IsNullOrWhiteSpace([string]$absolutePath) -or -not [System.IO.Path]::IsPathFullyQualified([string]$absolutePath)){
            Die "SYNAPSE_AUTHORITY_CURRENT_ROSTER_PATH_INVALID context=$Context generation=$($p.generation_id) path=$absolutePath"
        }
    }
    $gateState=Get-SynapsePhysicalRelativeState -ParentPath $Layout.RuntimeBinDir -ParentChain $Layout.RuntimeChain -Leaf $Layout.LegacyGateLeaf
    if(-not(Test-SynapsePhysicalStateExact -State $gateState -ExpectedExists $true -ExpectedFileId128 ([string]$p.legacy_gate_file_id_128) -ExpectedSha256 ([string]$p.legacy_gate_sha256) -ExpectedLength ([int64]$p.legacy_gate_length))){Die "SYNAPSE_AUTHORITY_CURRENT_GATE_DRIFT context=$Context path=$($Layout.LegacyGatePath)"}
    $gateRead=Read-SynapsePhysicalRelativeUtf8Text -ParentPath $Layout.RuntimeBinDir -ParentChain $Layout.RuntimeChain -Leaf $Layout.LegacyGateLeaf -ExpectedFileId128 ([string]$p.legacy_gate_file_id_128) -MaxBytes 65536
    try{$gate=$gateRead.Content|ConvertFrom-Json -ErrorAction Stop}catch{Die "SYNAPSE_AUTHORITY_CURRENT_GATE_JSON_INVALID context=$Context error=$($_.Exception.Message)"}
    if([string]$gate.schema -cne 'synapse_daemon_supervisor_stop_request/v1' -or [string]$gate.state -cne 'requested' -or [string]$gate.bind -cne [string]$p.bind -or [string]$gate.broker_identity_sha256 -ine [string]$p.broker_identity_sha256 -or [int64]$gate.authority_epoch -ne [int64]$p.authority_epoch){Die "SYNAPSE_AUTHORITY_CURRENT_GATE_CONTRACT_INVALID context=$Context path=$($Layout.LegacyGatePath)"}

    $exeDescriptor=[ordered]@{role='daemon';path=[string]$p.exe_path;file_id_128=[string]$p.exe_file_id_128;sha256=[string]$p.exe_sha256;length=[int64]$p.exe_length;parent_path=[string]$p.exe_parent_path;parent_file_id_128=[string]$p.exe_parent_file_id_128}
    $configDescriptor=[ordered]@{role='calyx_config';path=[string]$p.calyx_config_path;file_id_128=[string]$p.calyx_config_file_id_128;sha256=[string]$p.calyx_config_sha256;length=[int64]$p.calyx_config_length;parent_path=[string]$p.calyx_config_parent_path;parent_file_id_128=[string]$p.calyx_config_parent_file_id_128}
    $supervisorDescriptor=[ordered]@{role=([string]$p.role+'_generation_supervisor');path=[string]$p.generation_supervisor_path;file_id_128=[string]$p.generation_supervisor_file_id_128;sha256=[string]$p.generation_supervisor_sha256;length=[int64]$p.generation_supervisor_length;parent_path=[string]$p.generation_supervisor_parent_path;parent_file_id_128=[string]$p.generation_supervisor_parent_file_id_128}
    $exe=Assert-SynapseAuthorityFileDescriptorPhysicalIdentity -Descriptor $exeDescriptor -ExpectedRole daemon -Context "${Context}_daemon"
    $config=Assert-SynapseAuthorityFileDescriptorPhysicalIdentity -Descriptor $configDescriptor -ExpectedRole calyx_config -Context "${Context}_config"
    $supervisor=Assert-SynapseAuthorityFileDescriptorPhysicalIdentity -Descriptor $supervisorDescriptor -ExpectedRole ([string]$supervisorDescriptor.role) -ExpectedParent $Layout.Objects -Context "${Context}_supervisor"
    $generation=@();$seen=New-SynapseCaseInsensitiveMap
    foreach($item in @($p.generation_objects)){
        $role=[string]$item.role
        $verified=Assert-SynapseAuthorityFileDescriptorPhysicalIdentity -Descriptor $item -ExpectedRole $role -Context "${Context}_object_$role"
        if($seen.ContainsKey([string]$verified.Path)){Die "SYNAPSE_AUTHORITY_CURRENT_ROSTER_OBJECT_DUPLICATE context=$Context path=$($verified.Path)"}
        $seen[[string]$verified.Path]=$true
        $generation+=,(ConvertTo-SynapseAuthorityFileDescriptor -Identity $verified -Role $role)
    }
    $generation=@($generation|Sort-Object path)
    $manifest=@($generation|Where-Object role -CEQ 'profile_manifest')
    $tokens=@($generation|Where-Object role -CEQ 'bearer_token')
    $runtimeParent=Get-SynapseNormalizedDirectoryPath -Path ([string]$p.exe_parent_path)
    $invalidRuntimeObjects=@($generation|Where-Object{[string]$_.role -like 'runtime_*' -and (Get-SynapseNormalizedDirectoryPath -Path ([string]$_.parent_path)) -ine $runtimeParent})
    if($manifest.Count -ne 1 -or [System.IO.Path]::GetFullPath([string]$manifest[0].path) -ine [System.IO.Path]::GetFullPath((Join-Path ([string]$p.profiles_dir) $script:SynapseBundledProfilesManifestFileName)) -or
        $tokens.Count -ne 1 -or [System.IO.Path]::GetFullPath([string]$tokens[0].path) -ine [System.IO.Path]::GetFullPath([string]$p.token_path) -or
        $invalidRuntimeObjects.Count -ne 0){
        Die "SYNAPSE_AUTHORITY_CURRENT_ROSTER_OBJECT_SCOPE_INVALID context=$Context manifest_count=$($manifest.Count) token_count=$($tokens.Count) invalid_runtime_count=$($invalidRuntimeObjects.Count)"
    }
    $profilesRoot=Get-SynapseNormalizedDirectoryPath -Path ([string]$p.profiles_dir)
    $profilesChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $profilesRoot)
    if([string]$profilesChain[-1].file_id_128 -ine [string]$p.profiles_root_file_id_128){Die "SYNAPSE_AUTHORITY_CURRENT_ROSTER_PROFILE_ROOT_DRIFT context=$Context profiles=$profilesRoot"}
    $profileIdentity=[ordered]@{profiles_dir=$profilesRoot;profiles_root_file_id_128=([string]$p.profiles_root_file_id_128).ToUpperInvariant();manifest_path=[string]$manifest[0].path;manifest_file_id_128=[string]$manifest[0].file_id_128;manifest_sha256=[string]$manifest[0].sha256;manifest_length=[int64]$manifest[0].length}
    $profileSha=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $profileIdentity)).ToUpperInvariant()
    $runtimeIdentity=[ordered]@{executable=$exeDescriptor;calyx_config=$configDescriptor;objects=$generation;daemon_argument_text=[string]$p.daemon_argument_text}
    $runtimeSha=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $runtimeIdentity)).ToUpperInvariant()
    $core=[ordered]@{role=[string]$p.role;authority_epoch=[int64]$p.authority_epoch;runtime_generation_sha256=$runtimeSha;profile_generation_sha256=$profileSha;tool_count=[int]$p.expected_tool_count;tool_surface_sha256=([string]$p.expected_tool_surface_sha256).ToUpperInvariant()}
    $generationId=([string]$p.role)+'-'+((Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $core)).Substring(0,40).ToLowerInvariant())
    $generationLaunchCapability=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value ([ordered]@{schema='synapse_generation_launch_capability/v1';broker_identity_sha256=([string]$p.broker_identity_sha256).ToUpperInvariant();task_capability_sha256=([string]$Infrastructure.TaskCapabilitySha256).ToUpperInvariant();authority_epoch=[int64]$p.authority_epoch;generation_id=$generationId;runtime_generation_sha256=$runtimeSha;profile_generation_sha256=$profileSha;invocation_id=[string]$p.invocation_id}))).ToUpperInvariant()
    if($runtimeSha -ine [string]$p.runtime_generation_sha256 -or $profileSha -ine [string]$p.profile_generation_sha256 -or $generationId -cne [string]$p.generation_id -or $generationLaunchCapability -ine [string]$p.generation_launch_capability_sha256){Die "SYNAPSE_AUTHORITY_CURRENT_ROSTER_GENERATION_HASH_INVALID context=$Context expected_generation=$generationId actual_generation=$($p.generation_id)"}
    return [pscustomobject][ordered]@{Role=[string]$p.role;GenerationId=[string]$p.generation_id;LaunchCapabilitySha256=$generationLaunchCapability;Executable=$exeDescriptor;CalyxConfig=$configDescriptor;Profiles=[pscustomobject]@{Identity=$profileIdentity;Sha256=$profileSha;RootFileId128=[string]$p.profiles_root_file_id_128;Manifest=$manifest[0]};GenerationObjects=$generation;Supervisor=$supervisor;RuntimeGenerationIdentity=$runtimeIdentity;RuntimeGenerationSha256=$runtimeSha;ProfileGenerationSha256=$profileSha;RosterPayload=$p;RosterEnvelope=$Roster.Envelope}
}

function Read-SynapseAuthorityGenerationToken {
    param(
        [Parameter(Mandatory=$true)]$Generation,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $tokens=@($Generation.GenerationObjects|Where-Object role -CEQ 'bearer_token')
    if($tokens.Count -ne 1){Die "SYNAPSE_AUTHORITY_GENERATION_TOKEN_DESCRIPTOR_INVALID context=$Context count=$($tokens.Count)"}
    $descriptor=$tokens[0]
    $parent=Get-SynapseNormalizedDirectoryPath -Path ([string]$descriptor.parent_path)
    $chain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $parent)
    if([string]$chain[-1].file_id_128 -ine [string]$descriptor.parent_file_id_128){Die "SYNAPSE_AUTHORITY_GENERATION_TOKEN_PARENT_DRIFT context=$Context path=$($descriptor.path)"}
    $read=Read-SynapsePhysicalRelativeUtf8Text -ParentPath $parent -ParentChain $chain -Leaf (Split-Path -Leaf ([string]$descriptor.path)) -ExpectedFileId128 ([string]$descriptor.file_id_128) -MaxBytes 65536
    if([string]$read.Sha256 -ine [string]$descriptor.sha256 -or [int64]$read.Length -ne [int64]$descriptor.length){Die "SYNAPSE_AUTHORITY_GENERATION_TOKEN_IDENTITY_DRIFT context=$Context path=$($descriptor.path)"}
    $value=([string]$read.Content).Trim()
    if([string]::IsNullOrWhiteSpace($value)){Die "SYNAPSE_AUTHORITY_GENERATION_TOKEN_EMPTY context=$Context path=$($descriptor.path)"}
    return $value
}

function Ensure-SynapseWindowsCommandLineArgvType {
    if ('SynapseSetup.WindowsCommandLineArgv' -as [type]) { return }
    Add-Type -Language CSharp -TypeDefinition @'
using System;
using System.ComponentModel;
using System.Runtime.InteropServices;

namespace SynapseSetup
{
    public static class WindowsCommandLineArgv
    {
        [DllImport("shell32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
        private static extern IntPtr CommandLineToArgvW(string commandLine, out int argumentCount);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern IntPtr LocalFree(IntPtr memory);

        public static string[] Parse(string commandLine)
        {
            if (String.IsNullOrWhiteSpace(commandLine))
                throw new ArgumentException("SYNAPSE_COMMAND_LINE_EMPTY", "commandLine");
            int count;
            IntPtr pointer = CommandLineToArgvW(commandLine, out count);
            if (pointer == IntPtr.Zero)
                throw new Win32Exception(Marshal.GetLastWin32Error(), "SYNAPSE_COMMAND_LINE_ARGV_PARSE_FAILED");
            try
            {
                if (count < 1 || count > 64)
                    throw new InvalidOperationException("SYNAPSE_COMMAND_LINE_ARGV_COUNT_INVALID count=" + count);
                string[] result = new string[count];
                for (int index = 0; index < count; index++)
                {
                    IntPtr value = Marshal.ReadIntPtr(pointer, checked(index * IntPtr.Size));
                    result[index] = Marshal.PtrToStringUni(value) ?? String.Empty;
                }
                return result;
            }
            finally
            {
                LocalFree(pointer);
            }
        }
    }
}
'@
}

function Assert-SynapseProcessCommandLineExact {
    param(
        [Parameter(Mandatory=$true)]$Process,
        [Parameter(Mandatory=$true)][string[]]$ExpectedArguments,
        [int[]]$PathArgumentIndexes=@(),
        [switch]$AllowExecutablePathUnavailable,
        [Parameter(Mandatory=$true)][string]$Context
    )
    Ensure-SynapseWindowsCommandLineArgvType
    $actual=@([SynapseSetup.WindowsCommandLineArgv]::Parse([string]$Process.CommandLine))
    if($actual.Count -ne $ExpectedArguments.Count){
        Die "SYNAPSE_PROCESS_ARGV_COUNT_MISMATCH context=$Context pid=$($Process.ProcessId) expected=$($ExpectedArguments.Count) actual=$($actual.Count)"
    }
    for($index=0;$index -lt $ExpectedArguments.Count;$index++){
        $expected=[string]$ExpectedArguments[$index];$observed=[string]$actual[$index]
        $matches=if($PathArgumentIndexes -contains $index){
            if([string]::IsNullOrWhiteSpace($expected)-or[string]::IsNullOrWhiteSpace($observed)){Die "SYNAPSE_PROCESS_ARGV_PATH_EMPTY context=$Context pid=$($Process.ProcessId) index=$index expected=[$expected] actual=[$observed] command_line=[$($Process.CommandLine)]"}
            [System.IO.Path]::GetFullPath($observed) -ieq [System.IO.Path]::GetFullPath($expected)
        }else{$observed -ceq $expected}
        if(-not $matches){
            Die "SYNAPSE_PROCESS_ARGV_MISMATCH context=$Context pid=$($Process.ProcessId) index=$index expected=$expected actual=$observed"
        }
    }
    if([string]::IsNullOrWhiteSpace([string]$Process.ExecutablePath)){
        if(-not$AllowExecutablePathUnavailable){Die "SYNAPSE_PROCESS_EXECUTABLE_PATH_MISSING context=$Context pid=$($Process.ProcessId)"}
    }elseif([System.IO.Path]::GetFullPath([string]$Process.ExecutablePath) -ine [System.IO.Path]::GetFullPath([string]$ExpectedArguments[0])){
        Die "SYNAPSE_PROCESS_EXECUTABLE_ARGV_MISMATCH context=$Context pid=$($Process.ProcessId) executable=$($Process.ExecutablePath) argv0=$($actual[0])"
    }
    return $actual
}

function Wait-SynapseBrokerGenerationOperational {
    param(
        [Parameter(Mandatory=$true)]$Layout,
        [Parameter(Mandatory=$true)]$Infrastructure,
        [Parameter(Mandatory=$true)]$Generation,
        [Parameter(Mandatory=$true)]$ControlGateIdentity,
        [Parameter(Mandatory=$true)]$RosterIdentity,
        $ControlGateLease,
        $RosterLease,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$DbPath,
        [Parameter(Mandatory=$true)][string]$ProfilesDir,
        [Parameter(Mandatory=$true)][string]$LogDir,
        [Parameter(Mandatory=$true)][string]$Token,
        [AllowNull()][string]$AllowedPermissions,
        [Parameter(Mandatory=$true)][string]$CalyxConfigPath,
        [Parameter(Mandatory=$true)][ValidatePattern('^[0-9A-Fa-f]{64}$')][string]$ExpectedCalyxConfigSha256,
        [ValidateRange(30,900)][int]$TimeoutSeconds=420,
        [switch]$RequireCpuPolicy,
        # Adopt a generation that is running and identity-proven even when the
        # APPLICATION reports itself unhealthy.
        #
        # Every other proof in this function -- roster/gate cross-binding,
        # broker state, the five-process lineage, the three Job contracts, the
        # executable SHA-256 readback -- answers "is THIS the exact committed
        # generation?", which is what adoption actually needs. `health.ok` does
        # not: it is an application-level rollup that goes false whenever any
        # subsystem is degraded.
        #
        # Gating adoption on it made the supported update path unable to
        # replace a broken daemon, because being broken is precisely what makes
        # `ok` false. On 2026-09-08 a Calyx storage stall set storage,
        # calyx_derived_state and vault_verify to `error`; setup then refused
        # to adopt authority, so it never reached its build step, and the fix
        # for that stall could not be shipped by the tool that exists to ship
        # fixes. The daemon you most need to update is the unhealthy one.
        #
        # This relaxes ONLY the application rollup, and only for callers that
        # are adopting or rolling back an EXISTING generation. Verification of a
        # newly installed daemon still demands `ok -eq $true`, because there the
        # question genuinely is "did the thing I just installed come up well?".
        [switch]$AllowUnhealthyApplication
    )
    # The immutable generation supervisor is the authority for the resource
    # contract that created its already-running daemon Job.  Recovery must
    # validate that sealed historical contract, not reinterpret it using the
    # current producer default.  Only the two explicitly shipped bounded
    # contracts are admissible; unknown supervisor bytes remain fail-closed.
    $generationSupervisorText=[System.IO.File]::ReadAllText([string]$Generation.Supervisor.Path,[System.Text.UTF8Encoding]::new($false,$true))
    if($generationSupervisorText.Contains('$ProcessMemoryLimitBytes = [uint64]5999996928')){
        $SynapseDaemonProcessMemoryLimitBytes=[uint64]5999996928
    }elseif($generationSupervisorText.Contains('$ProcessMemoryLimitBytes = [uint64]789999616')){
        $SynapseDaemonProcessMemoryLimitBytes=[uint64]789999616
    }else{
        Die "SYNAPSE_BROKER_GENERATION_MEMORY_CONTRACT_UNKNOWN generation=$($Generation.GenerationId) supervisor=$($Generation.Supervisor.Path)"
    }
    $deadline=(Get-Date).AddSeconds($TimeoutSeconds)
    $lastError='not_started'
    $lastReportedError=''
    $unhealthyReported=''
    do {
        $currentPair=$null
        try {
            $currentPair=Read-SynapseAuthorityActiveControlPair -Layout $Layout -GateLease $ControlGateLease -RosterLease $RosterLease -Context 'broker_operational_control_pair'
            $currentRoster=$currentPair.Roster
            if([string]$currentPair.Gate.FileId128 -ine [string]$ControlGateIdentity.FileId128 -or
                [string]$currentPair.Gate.Sha256 -ine [string]$ControlGateIdentity.Sha256 -or
                [int64]$currentPair.Gate.Length -ne [int64]$ControlGateIdentity.Length){
                throw "canonical control-gate identity mismatch"
            }
            if([string]$currentRoster.FileId128 -ine [string]$RosterIdentity.FileId128 -or
                [string]$currentRoster.Sha256 -ine [string]$RosterIdentity.Sha256 -or
                [int64]$currentRoster.Length -ne [int64]$RosterIdentity.Length -or
                [string]$currentRoster.Payload.generation_id -cne [string]$Generation.GenerationId){
                throw "canonical roster identity mismatch"
            }
            $health=Invoke-RestMethod -Uri "http://$Bind/health" -Headers @{Authorization="Bearer $Token"} -TimeoutSec 10
            if($health.ok -ne $true){
                if(-not$AllowUnhealthyApplication){throw "health ok was $($health.ok)"}
                $unhealthySubsystems=@()
                if($null -ne $health.subsystems){
                    $unhealthySubsystems=@($health.subsystems.PSObject.Properties|Where-Object{[string]$_.Value.status -cne 'ok'}|ForEach-Object{"$($_.Name)=$([string]$_.Value.status)"})
                }
                if($unhealthyReported -cne [string]$Generation.GenerationId){
                    Write-Warning "[synapse-setup] SYNAPSE_BROKER_GENERATION_ADOPTED_WHILE_UNHEALTHY generation=$($Generation.GenerationId) health_ok=$($health.ok) daemon_pid=$($health.pid) unhealthy_subsystems=$($unhealthySubsystems -join ',') basis=identity_and_lineage_proofs_still_enforced remediation=this generation is being adopted so it can be replaced or rolled back; the named subsystems stay broken until a repaired generation is installed"
                    $unhealthyReported=[string]$Generation.GenerationId
                }
            }
            $pidValue=[int]$health.pid
            $identity=Get-SynapseInstalledDaemonIdentityReadback -HealthPid $pidValue -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -ExpectedExePath $Generation.Executable.path -ExpectedSha256 $Generation.Executable.sha256 -LogDir $LogDir -AllowedPermissions $AllowedPermissions -CalyxConfigPath $CalyxConfigPath -ExpectedCalyxConfigSha256 $ExpectedCalyxConfigSha256 -ExpectedSupervisorCpuRate 10000 -ExpectedSupervisorBootstrapPath ([string]$Generation.RosterPayload.bootstrap_path) -ExpectedSupervisorLaunchCapabilitySha256 ([string]$Generation.LaunchCapabilitySha256)
            if(-not [bool]$identity.Ok){throw "installed identity: $($identity.Detail)"}
            $surface=Read-SynapseDaemonToolSurface -Bind $Bind -Token $Token -Health $health
            if([int]$surface.tool_count -ne [int]$Generation.RosterPayload.expected_tool_count -or
                [string]$surface.tool_surface_sha256 -ine [string]$Generation.RosterPayload.expected_tool_surface_sha256){
                throw "tool surface expected_count=$($Generation.RosterPayload.expected_tool_count) actual_count=$($surface.tool_count) expected_sha=$($Generation.RosterPayload.expected_tool_surface_sha256) actual_sha=$($surface.tool_surface_sha256)"
            }
            if($RequireCpuPolicy){[void](Assert-SynapseNoExplicitGpuRuntimeHealth -Health $health -ProcessId $pidValue -Bind $Bind -Phase 'broker_persistent_generation')}
            $brokerStatePath=[string]$Generation.RosterPayload.broker_state_path
            $brokerState=(Get-Content -Raw -LiteralPath $brokerStatePath -ErrorAction Stop)|ConvertFrom-Json -ErrorAction Stop
            if([string]$brokerState.schema -cne 'synapse_daemon_broker_state/v1' -or
                [int64]$brokerState.authority_epoch -ne [int64]$Generation.RosterPayload.authority_epoch -or
                [string]$brokerState.control_nonce -ine [string]$Generation.RosterPayload.control_nonce -or
                [string]$brokerState.control_gate_file_id_128 -ine [string]$ControlGateIdentity.FileId128 -or
                [string]$brokerState.control_gate_sha256 -ine [string]$ControlGateIdentity.Sha256 -or
                [string]$brokerState.generation_id -cne [string]$Generation.GenerationId -or
                [string]$brokerState.roster_sha256 -ine [string]$RosterIdentity.Sha256){
                throw "broker state identity mismatch"
            }
            $daemon=Get-CimInstance Win32_Process -Filter "ProcessId=$pidValue" -ErrorAction Stop
            $supervisor=Get-CimInstance Win32_Process -Filter "ProcessId=$([int]$daemon.ParentProcessId)" -ErrorAction Stop
            $innerBootstrap=Get-CimInstance Win32_Process -Filter "ProcessId=$([int]$supervisor.ParentProcessId)" -ErrorAction Stop
            $broker=Get-CimInstance Win32_Process -Filter "ProcessId=$([int]$innerBootstrap.ParentProcessId)" -ErrorAction Stop
            $outerBootstrap=Get-CimInstance Win32_Process -Filter "ProcessId=$([int]$broker.ParentProcessId)" -ErrorAction Stop
            if([int]$broker.ProcessId -ne [int]$brokerState.broker_pid -or [int]$innerBootstrap.ProcessId -ne [int]$brokerState.bootstrap_pid){
                throw "five-process lineage mismatch outer=$($outerBootstrap.ProcessId) broker=$($broker.ProcessId) inner=$($innerBootstrap.ProcessId) supervisor=$($supervisor.ProcessId) daemon=$pidValue"
            }
            $outerCapability=([string]$Infrastructure.TaskCapabilitySha256).ToUpperInvariant()
            $innerCapability=([string]$Generation.LaunchCapabilitySha256).ToUpperInvariant()
            $brokerIdentity=([string]$Infrastructure.BrokerIdentitySha256).ToUpperInvariant()
            if(@($brokerIdentity,$outerCapability,$innerCapability|Sort-Object -Unique).Count -ne 3){throw "broker/task/generation launch capability domains are not pairwise distinct broker=$brokerIdentity outer=$outerCapability inner=$innerCapability"}
            $expectedOuterJobName='Local\SynapseOwned-{0}-{1}' -f $outerCapability,[int]$outerBootstrap.ProcessId
            $expectedInnerJobName='Local\SynapseOwned-{0}-{1}' -f $innerCapability,[int]$innerBootstrap.ProcessId
            if([string]$brokerState.parent_job_name -cne $expectedOuterJobName){throw "outer Job name was not derived from the exact outer bootstrap PID expected=$expectedOuterJobName actual=$($brokerState.parent_job_name)"}
            [void](Assert-SynapseProcessCommandLineExact -Process $outerBootstrap -ExpectedArguments @([string]$Infrastructure.Bootstrap.Path,'--outer-launch-capability',$outerCapability,[string]$Generation.RosterPayload.powershell_path,[string]$Infrastructure.BrokerScript.Path,[string]$Generation.RosterPayload.working_directory,[string]$Generation.RosterPayload.bootstrap_log_path) -PathArgumentIndexes @(0,3,4,5,6) -Context 'broker_outer_bootstrap')
            [void](Assert-SynapseProcessCommandLineExact -Process $broker -ExpectedArguments @([string]$Generation.RosterPayload.powershell_path,'-NoProfile','-ExecutionPolicy','Bypass','-File',[string]$Infrastructure.BrokerScript.Path,'-ParentJobName',$expectedOuterJobName) -PathArgumentIndexes @(0,5) -Context 'broker_supervisor')
            [void](Assert-SynapseProcessCommandLineExact -Process $innerBootstrap -ExpectedArguments @([string]$Infrastructure.Bootstrap.Path,'--nested-job',[string]$Generation.RosterPayload.powershell_path,[string]$Generation.Supervisor.Path,[string]$Generation.RosterPayload.working_directory,[string]$Generation.RosterPayload.bootstrap_log_path) -PathArgumentIndexes @(0,2,3,4,5) -Context 'generation_inner_bootstrap')
            [void](Assert-SynapseProcessCommandLineExact -Process $supervisor -ExpectedArguments @([string]$Generation.RosterPayload.powershell_path,'-NoProfile','-ExecutionPolicy','Bypass','-File',[string]$Generation.Supervisor.Path,'-ParentJobName',$expectedInnerJobName) -PathArgumentIndexes @(0,5) -Context 'generation_supervisor')
            $creationDates=@($outerBootstrap.CreationDate,$broker.CreationDate,$innerBootstrap.CreationDate,$supervisor.CreationDate,$daemon.CreationDate)
            if(@($creationDates|Where-Object{[string]::IsNullOrWhiteSpace([string]$_)}).Count -ne 0){throw 'five-process CreationDate identity missing'}
            for($creationIndex=1;$creationIndex -lt $creationDates.Count;$creationIndex++){
                if([DateTime]$creationDates[$creationIndex] -lt [DateTime]$creationDates[$creationIndex-1]){throw "five-process CreationDate order invalid index=$creationIndex"}
            }
            $outerJob=Get-SynapseDaemonJobKernelReadback -JobName $expectedOuterJobName
            $innerJob=Get-SynapseDaemonJobKernelReadback -JobName $expectedInnerJobName
            $daemonJob=Get-SynapseDaemonJobKernelReadback -JobName ([string]$identity.JobName)
            $expectedOuterMembers=@([uint64]$outerBootstrap.ProcessId,[uint64]$broker.ProcessId,[uint64]$innerBootstrap.ProcessId,[uint64]$supervisor.ProcessId,[uint64]$pidValue)|Sort-Object
            $actualOuterMembers=@($outerJob.ProcessIds|ForEach-Object{[uint64]$_}|Sort-Object)
            $expectedInnerMembers=@([uint64]$innerBootstrap.ProcessId,[uint64]$supervisor.ProcessId,[uint64]$pidValue)|Sort-Object
            $actualInnerMembers=@($innerJob.ProcessIds|ForEach-Object{[uint64]$_}|Sort-Object)
            $actualDaemonMembers=@($daemonJob.ProcessIds|ForEach-Object{[uint64]$_}|Sort-Object)
            # Windows creates a headless conhost for console-subsystem descendants even when the
            # launch itself is CREATE_NO_WINDOW.  Those processes inherit the authority Jobs.
            # Admit only the exact OS-owned one-to-one adjunct topology; arbitrary extra members
            # remain a hard failure.
            $conhostPath=[System.IO.Path]::GetFullPath((Join-Path $env:SystemRoot 'System32\conhost.exe'))
            $assertConsoleAdjuncts={
                param([uint64[]]$CoreMembers,[uint64[]]$ActualMembers,[int[]]$AllowedParentPids,[int]$ExpectedSessionId,[string]$Context)
                $extras=@($ActualMembers|Where-Object{$CoreMembers -notcontains [uint64]$_})
                if($extras.Count -gt $AllowedParentPids.Count){throw "$Context has too many console adjuncts extras=$($extras-join ',') allowed_parents=$($AllowedParentPids-join ',')"}
                $seenParents=@{}
                foreach($extraPid64 in $extras){
                    if($extraPid64 -gt [uint64][int]::MaxValue){throw "$Context console adjunct PID overflow pid=$extraPid64"}
                    $extraPid=[int]$extraPid64
                    $extra=Get-CimInstance Win32_Process -Filter "ProcessId=$extraPid" -ErrorAction Stop
                    $extraPath=if([string]::IsNullOrWhiteSpace([string]$extra.ExecutablePath)){''}else{[System.IO.Path]::GetFullPath([string]$extra.ExecutablePath)}
                    $parentPid=[int]$extra.ParentProcessId
                    if([string]$extra.Name -ine 'conhost.exe' -or $extraPath -ine $conhostPath -or $AllowedParentPids -notcontains $parentPid){
                        throw "$Context unexpected Job member pid=$extraPid name=$($extra.Name) path=$extraPath parent=$parentPid"
                    }
                    if($seenParents.ContainsKey($parentPid)){throw "$Context duplicate console adjunct parent=$parentPid pids=$($seenParents[$parentPid]),$extraPid"}
                    if([string]::IsNullOrWhiteSpace([string]$extra.CreationDate)){throw "$Context console adjunct CreationDate missing pid=$extraPid"}
                    $parent=Get-CimInstance Win32_Process -Filter "ProcessId=$parentPid" -ErrorAction Stop
                    if([string]::IsNullOrWhiteSpace([string]$parent.CreationDate) -or [DateTime]$extra.CreationDate -lt [DateTime]$parent.CreationDate){throw "$Context console adjunct creation order invalid pid=$extraPid parent=$parentPid"}
                    $extraSession=(Get-Process -Id $extraPid -ErrorAction Stop).SessionId
                    if([int]$extraSession -ne $ExpectedSessionId){throw "$Context console adjunct session mismatch pid=$extraPid expected=$ExpectedSessionId actual=$extraSession"}
                    $seenParents[$parentPid]=$extraPid
                }
                return $extras
            }
            $authoritySessionId=(Get-Process -Id $pidValue -ErrorAction Stop).SessionId
            $outerConsoleAdjuncts=@(& $assertConsoleAdjuncts -CoreMembers $expectedOuterMembers -ActualMembers $actualOuterMembers -AllowedParentPids @([int]$broker.ProcessId,[int]$supervisor.ProcessId,$pidValue) -ExpectedSessionId $authoritySessionId -Context 'outer Job')
            $innerConsoleAdjuncts=@(& $assertConsoleAdjuncts -CoreMembers $expectedInnerMembers -ActualMembers $actualInnerMembers -AllowedParentPids @([int]$supervisor.ProcessId,$pidValue) -ExpectedSessionId $authoritySessionId -Context 'inner Job')
            $expectedDaemonMembers=@([uint64]$pidValue)
            $daemonConsoleAdjuncts=@(& $assertConsoleAdjuncts -CoreMembers $expectedDaemonMembers -ActualMembers $actualDaemonMembers -AllowedParentPids @($pidValue) -ExpectedSessionId $authoritySessionId -Context 'daemon Job')
            $expectedOuterMembers=@($expectedOuterMembers+$outerConsoleAdjuncts|Sort-Object)
            $expectedInnerMembers=@($expectedInnerMembers+$innerConsoleAdjuncts|Sort-Object)
            $expectedDaemonMembers=@($expectedDaemonMembers+$daemonConsoleAdjuncts|Sort-Object)
            if([uint32]$outerJob.LimitFlags -ne [uint32]0x00002300 -or
                [uint64]$outerJob.ProcessMemoryLimitBytes -ne [uint64]6699999232 -or
                [uint64]$outerJob.JobMemoryLimitBytes -ne [uint64]6699999232 -or
                [uint64]$outerJob.CurrentJobMemoryUsedBytes -gt [uint64]6699999232 -or
                [uint64]$outerJob.PeakJobMemoryUsedBytes -gt [uint64]7000000000 -or
                [uint32]$outerJob.CpuRateControlFlags -ne [uint32]0x00000005 -or [uint32]$outerJob.CpuRate -ne [uint32]2500 -or
                (($expectedOuterMembers -join ',') -cne ($actualOuterMembers -join ','))){
                throw "outer Job contract flags=0x$('{0:X8}'-f [uint32]$outerJob.LimitFlags) process_limit=$($outerJob.ProcessMemoryLimitBytes) job_limit=$($outerJob.JobMemoryLimitBytes) current=$($outerJob.CurrentJobMemoryUsedBytes) peak=$($outerJob.PeakJobMemoryUsedBytes) cpu_flags=0x$('{0:X8}'-f [uint32]$outerJob.CpuRateControlFlags) cpu_rate=$($outerJob.CpuRate) expected_members=$($expectedOuterMembers-join ',') actual_members=$($actualOuterMembers-join ',')"
            }
            if([uint32]$innerJob.LimitFlags -ne [uint32]0x00002300 -or
                [uint64]$innerJob.ProcessMemoryLimitBytes -ne [uint64]6699999232 -or [uint64]$innerJob.JobMemoryLimitBytes -ne [uint64]6699999232 -or
                [uint64]$innerJob.CurrentJobMemoryUsedBytes -gt [uint64]6699999232 -or [uint64]$innerJob.PeakJobMemoryUsedBytes -gt [uint64]7000000000 -or
                [uint32]$innerJob.CpuRateControlFlags -ne [uint32]0x00000005 -or [uint32]$innerJob.CpuRate -ne [uint32]10000 -or
                (($expectedInnerMembers -join ',') -cne ($actualInnerMembers -join ','))){
                throw "inner Job contract flags=0x$('{0:X8}'-f [uint32]$innerJob.LimitFlags) process_limit=$($innerJob.ProcessMemoryLimitBytes) job_limit=$($innerJob.JobMemoryLimitBytes) current=$($innerJob.CurrentJobMemoryUsedBytes) peak=$($innerJob.PeakJobMemoryUsedBytes) cpu_flags=0x$('{0:X8}'-f [uint32]$innerJob.CpuRateControlFlags) cpu_rate=$($innerJob.CpuRate) expected_members=$($expectedInnerMembers-join ',') actual_members=$($actualInnerMembers-join ',')"
            }
            if([uint32]$daemonJob.LimitFlags -ne [uint32]0x00002300 -or
                [uint64]$daemonJob.ProcessMemoryLimitBytes -ne $SynapseDaemonProcessMemoryLimitBytes -or [uint64]$daemonJob.JobMemoryLimitBytes -ne $SynapseDaemonProcessMemoryLimitBytes -or
                [uint64]$daemonJob.CurrentJobMemoryUsedBytes -gt $SynapseDaemonProcessMemoryLimitBytes -or [uint64]$daemonJob.PeakJobMemoryUsedBytes -gt $SynapseDaemonProcessMemoryLimitBytes -or
                [uint32]$daemonJob.CpuRateControlFlags -ne [uint32]0x00000005 -or [uint32]$daemonJob.CpuRate -ne [uint32]10000 -or
                (($expectedDaemonMembers -join ',') -cne ($actualDaemonMembers -join ','))){
                throw "daemon Job contract job=$($identity.JobName) flags=0x$('{0:X8}'-f [uint32]$daemonJob.LimitFlags) process_limit=$($daemonJob.ProcessMemoryLimitBytes) job_limit=$($daemonJob.JobMemoryLimitBytes) current=$($daemonJob.CurrentJobMemoryUsedBytes) peak=$($daemonJob.PeakJobMemoryUsedBytes) cpu_flags=0x$('{0:X8}'-f [uint32]$daemonJob.CpuRateControlFlags) cpu_rate=$($daemonJob.CpuRate) members=$($actualDaemonMembers-join ',')"
            }
            $result=[pscustomobject][ordered]@{
                Health=$health;ToolSurface=$surface;Identity=$identity;BrokerState=$brokerState;OuterJob=$outerJob;InnerJob=$innerJob;DaemonJob=$daemonJob
                OuterBootstrapPid=[int]$outerBootstrap.ProcessId;BrokerPid=[int]$broker.ProcessId;InnerBootstrapPid=[int]$innerBootstrap.ProcessId
                SupervisorPid=[int]$supervisor.ProcessId;DaemonPid=$pidValue
                OuterBootstrapCreationDate=[string]$outerBootstrap.CreationDate;BrokerCreationDate=[string]$broker.CreationDate;InnerBootstrapCreationDate=[string]$innerBootstrap.CreationDate;SupervisorCreationDate=[string]$supervisor.CreationDate;DaemonCreationDate=[string]$daemon.CreationDate
            }
            Close-SynapseAuthorityActiveControlPair -Pair $currentPair
            return $result
        } catch {
            Close-SynapseAuthorityActiveControlPair -Pair $currentPair
            $lastError=(($_.Exception.Message -replace '\s+',' ').Trim())
            if($lastError -cne $lastReportedError){
                Write-Warning "[synapse-setup] SYNAPSE_BROKER_GENERATION_OPERATIONAL_RETRY generation=$($Generation.GenerationId) error=$lastError"
                $lastReportedError=$lastError
            }
        }
        Start-Sleep -Seconds 2
    } while((Get-Date) -lt $deadline)
    $fatalEvidence=Get-SynapseSupervisorBootstrapFatalEvidencePath
    Die "SYNAPSE_BROKER_GENERATION_OPERATIONAL_TIMEOUT generation=$($Generation.GenerationId) bind=$Bind timeout_s=$TimeoutSeconds last_error=$lastError bootstrap_fatal_evidence=$fatalEvidence evidence_semantics=diagnostic_only_never_cleanup_authority remediation=keep the exact authority journal and inspect the broker/supervisor state plus the five-process Job lineage"
}

function Get-SynapseBrokerSupervisorProcessCandidates {
    param([Parameter(Mandatory=$true)]$Infrastructure)
    $brokerScriptPath=[System.IO.Path]::GetFullPath([string]$Infrastructure.BrokerScript.Path)
    $powershellPath=[System.IO.Path]::GetFullPath([string]$Infrastructure.SemanticContract.powershell_path)
    return @(Get-CimInstance Win32_Process -ErrorAction Stop | Where-Object {
        -not [string]::IsNullOrWhiteSpace([string]$_.CommandLine) -and
        -not [string]::IsNullOrWhiteSpace([string]$_.ExecutablePath) -and
        [System.IO.Path]::GetFullPath([string]$_.ExecutablePath).Equals($powershellPath,[System.StringComparison]::OrdinalIgnoreCase) -and
        ([string]$_.CommandLine).IndexOf($brokerScriptPath,[System.StringComparison]::OrdinalIgnoreCase) -ge 0
    })
}

function Get-SynapseBrokerChildClassification {
    param([Parameter(Mandatory=$true)]$Broker)
    $all=@(Get-CimInstance Win32_Process -ErrorAction Stop | Where-Object {[int]$_.ParentProcessId -eq [int]$Broker.ProcessId})
    $authority=@()
    $consoleHosts=@()
    $systemConhost=[System.IO.Path]::GetFullPath((Join-Path $env:WINDIR 'System32\conhost.exe'))
    foreach($child in $all){
        $isConhost=([string]$child.Name).Equals('conhost.exe',[System.StringComparison]::OrdinalIgnoreCase)
        if(-not$isConhost){$authority+=,$child;continue}
        $childPath=if([string]::IsNullOrWhiteSpace([string]$child.ExecutablePath)){''}else{[System.IO.Path]::GetFullPath([string]$child.ExecutablePath)}
        $expectedPrefix='\??\'+$systemConhost
        $command=[string]$child.CommandLine
        $creationDelta=[Math]::Abs((([datetime]$child.CreationDate)-([datetime]$Broker.CreationDate)).TotalSeconds)
        $descendants=@(Get-CimInstance Win32_Process -ErrorAction Stop | Where-Object {[int]$_.ParentProcessId -eq [int]$child.ProcessId})
        if(-not$childPath.Equals($systemConhost,[System.StringComparison]::OrdinalIgnoreCase) -or
           -not$command.StartsWith($expectedPrefix,[System.StringComparison]::OrdinalIgnoreCase) -or
           $command.Substring($expectedPrefix.Length) -notmatch '^ 0x[0-9A-Fa-f]+$' -or
           [int]$child.SessionId -ne [int]$Broker.SessionId -or $creationDelta -gt 2.0 -or $descendants.Count -ne 0){
            Die "SYNAPSE_BROKER_CONSOLE_HOST_IDENTITY_INVALID broker_pid=$($Broker.ProcessId) child_pid=$($child.ProcessId) path=$childPath command=$command creation_delta_s=$creationDelta descendants=$(@($descendants.ProcessId)-join',')"
        }
        $consoleHosts+=,$child
    }
    return [pscustomobject][ordered]@{AuthorityChildren=@($authority);ConsoleHosts=@($consoleHosts)}
}

function Assert-SynapseBrokerParkedNoAuthority {
    param(
        [Parameter(Mandatory=$true)]$Layout,
        [Parameter(Mandatory=$true)]$Infrastructure,
        [Parameter(Mandatory=$true)]$ControlGateIdentity,
        [Parameter(Mandatory=$true)]$RosterIdentity,
        $ControlGateLease,
        $RosterLease,
        $TaskSupersessionInfrastructure,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$DbPath,
        [switch]$AllowHistoricalPeakForDecommission,
        [ValidateRange(10,420)][int]$TimeoutSeconds=360
    )

    $deadline=(Get-Date).AddSeconds($TimeoutSeconds)
    $last='not_checked'
    $lastReported=''
    do {
        $pair=$null
        try {
            $pair=Read-SynapseAuthorityActiveControlPair -Layout $Layout -GateLease $ControlGateLease -RosterLease $RosterLease -ExpectedState parked -Context 'broker_parked_control_pair'
            if([string]$pair.Gate.FileId128 -ine [string]$ControlGateIdentity.FileId128 -or
                [string]$pair.Gate.Sha256 -ine [string]$ControlGateIdentity.Sha256 -or
                [int64]$pair.Gate.Length -ne [int64]$ControlGateIdentity.Length -or
                [string]$pair.Roster.FileId128 -ine [string]$RosterIdentity.FileId128 -or
                [string]$pair.Roster.Sha256 -ine [string]$RosterIdentity.Sha256 -or
                [int64]$pair.Roster.Length -ne [int64]$RosterIdentity.Length -or
                [string]$pair.Roster.Payload.role -cne 'none' -or
                [string]$pair.Roster.Payload.broker_task_capability_sha256 -ine [string]$Infrastructure.TaskCapabilitySha256 -or
                [string]$pair.Roster.Payload.broker_task_name -cne [string]$Infrastructure.TaskName){
                throw 'parked control identity mismatch'
            }
            $scheduler=Get-SynapseScheduledTaskComRoot
            if($null-eq$TaskSupersessionInfrastructure){
                $expectedTask=[pscustomobject]@{Name=$Infrastructure.TaskName;XmlSha256=$Infrastructure.Task.XmlSha256;SecurityDescriptorSha256=$Infrastructure.Task.SecurityDescriptorSha256;Execute=$Infrastructure.Task.Execute;Arguments=$Infrastructure.Task.Arguments;WorkingDirectory=$Infrastructure.Task.WorkingDirectory}
                [void](Assert-SynapseTaskReadbackIdentity -Expected $expectedTask -Kind broker)
                $taskLookup=Get-SynapseScheduledTaskLookupExact -Name ([string]$Infrastructure.TaskName) -Scheduler $scheduler
                if(-not [bool]$taskLookup.Exists){throw "expected immutable broker task disappeared task=$($Infrastructure.TaskName)"}
            }else{
                $oldLookup=Get-SynapseScheduledTaskLookupExact -Name ([string]$Infrastructure.TaskName) -Scheduler $scheduler
                if([bool]$oldLookup.Exists){throw "superseded broker task unexpectedly present task=$($Infrastructure.TaskName)"}
                $successorExpected=[pscustomobject]@{Name=$TaskSupersessionInfrastructure.TaskName;XmlSha256=$TaskSupersessionInfrastructure.Task.XmlSha256;SecurityDescriptorSha256=$TaskSupersessionInfrastructure.Task.SecurityDescriptorSha256;Execute=$TaskSupersessionInfrastructure.Task.Execute;Arguments=$TaskSupersessionInfrastructure.Task.Arguments;WorkingDirectory=$TaskSupersessionInfrastructure.Task.WorkingDirectory}
                [void](Assert-SynapseTaskReadbackIdentity -Expected $successorExpected -Kind broker)
                $taskLookup=Get-SynapseScheduledTaskLookupExact -Name ([string]$TaskSupersessionInfrastructure.TaskName) -Scheduler $scheduler
                if(-not[bool]$taskLookup.Exists){throw "exact successor broker task disappeared task=$($TaskSupersessionInfrastructure.TaskName)"}
            }
            $registered=$taskLookup.Task
            $instances=@($registered.GetInstances(0))
            $targets=@(Select-SynapseMcpDeployTargetProcesses -Snapshot @(Get-SynapseMcpProcessSnapshot) -Bind $Bind -DbPath $DbPath)
            $listeners=@(Get-SynapseTcpBindListenerSnapshot -Bind $Bind)
            $brokerProcesses=@(Get-SynapseBrokerSupervisorProcessCandidates -Infrastructure $Infrastructure)
            # Task Scheduler may report zero running instances after its outer
            # action process has handed ownership to the exact retained Job.
            # The process argv, parent, Job membership and immutable task
            # identity below are the physical authority proof; requiring the
            # advisory COM instance counter to remain one made a valid parked
            # broker impossible to migrate on this host.
            if($instances.Count -in @(0,1) -and $targets.Count -eq 0 -and $listeners.Count -eq 0 -and $brokerProcesses.Count -eq 1){
                $brokerProcess=$brokerProcesses[0]
                $outerBootstrap=Get-CimInstance Win32_Process -Filter "ProcessId=$([int]$brokerProcess.ParentProcessId)" -ErrorAction Stop
                $outerCapability=([string]$Infrastructure.TaskCapabilitySha256).ToUpperInvariant()
                $outerJobName='Local\SynapseOwned-{0}-{1}' -f $outerCapability,[int]$outerBootstrap.ProcessId
                [void](Assert-SynapseProcessCommandLineExact -Process $outerBootstrap -ExpectedArguments @([string]$Infrastructure.Bootstrap.Path,'--outer-launch-capability',$outerCapability,[string]$pair.Roster.Payload.powershell_path,[string]$Infrastructure.BrokerScript.Path,[string]$pair.Roster.Payload.working_directory,[string]$pair.Roster.Payload.bootstrap_log_path) -PathArgumentIndexes @(0,3,4,5,6) -Context 'broker_parked_outer_bootstrap')
                [void](Assert-SynapseProcessCommandLineExact -Process $brokerProcess -ExpectedArguments @([string]$pair.Roster.Payload.powershell_path,'-NoProfile','-ExecutionPolicy','Bypass','-File',[string]$Infrastructure.BrokerScript.Path,'-ParentJobName',$outerJobName) -PathArgumentIndexes @(0,5) -Context 'broker_parked_process')
                $childClass=Get-SynapseBrokerChildClassification -Broker $brokerProcess;$innerChildren=@($childClass.AuthorityChildren)
                if($innerChildren.Count -ne 0){throw "parked broker retained child processes=$(@($innerChildren.ProcessId)-join ',')"}
                $outerJob=Get-SynapseDaemonJobKernelReadback -JobName $outerJobName
                $expectedMembers=@([uint64]$outerBootstrap.ProcessId,[uint64]$brokerProcess.ProcessId)+@($childClass.ConsoleHosts|ForEach-Object{[uint64]$_.ProcessId})|Sort-Object
                $actualMembers=@($outerJob.ProcessIds|ForEach-Object{[uint64]$_}|Sort-Object)
                if([uint32]$outerJob.LimitFlags -ne [uint32]0x00002300 -or [uint64]$outerJob.ProcessMemoryLimitBytes -ne [uint64]6699999232 -or
                    [uint64]$outerJob.JobMemoryLimitBytes -ne [uint64]6699999232 -or (-not$AllowHistoricalPeakForDecommission-and[uint64]$outerJob.CurrentJobMemoryUsedBytes -gt [uint64]6699999232) -or
                    (-not$AllowHistoricalPeakForDecommission-and[uint64]$outerJob.PeakJobMemoryUsedBytes -gt [uint64]7000000000) -or [uint32]$outerJob.CpuRateControlFlags -ne [uint32]0x00000005 -or
                    [uint32]$outerJob.CpuRate -ne [uint32]2500 -or (($expectedMembers-join ',') -cne ($actualMembers-join ','))){
                    throw "parked outer Job contract invalid job=$outerJobName flags=$($outerJob.LimitFlags) process_limit=$($outerJob.ProcessMemoryLimitBytes) job_limit=$($outerJob.JobMemoryLimitBytes) current=$($outerJob.CurrentJobMemoryUsedBytes) peak=$($outerJob.PeakJobMemoryUsedBytes) rate=$($outerJob.CpuRate) expected_members=$($expectedMembers-join ',') actual_members=$($actualMembers-join ',') allow_historical_peak_for_decommission=$([bool]$AllowHistoricalPeakForDecommission)"
                }
                $pair.GateLease.RequireExact('broker_parked_final_gate')
                $pair.RosterLease.RequireExact('broker_parked_final_roster')
                Close-SynapseAuthorityActiveControlPair -Pair $pair
                return [pscustomobject][ordered]@{TaskInstanceCount=[int]$instances.Count;TargetProcessCount=0;ListenerCount=0;BrokerProcessCount=1;OuterBootstrapPid=[int]$outerBootstrap.ProcessId;BrokerPid=[int]$brokerProcess.ProcessId;OuterJob=$outerJob;ControlGateFileId128=[string]$ControlGateIdentity.FileId128;RosterFileId128=[string]$RosterIdentity.FileId128}
            }
            $last="instances=$($instances.Count) targets=$($targets.Count) listeners=$($listeners.Count) broker_processes=$($brokerProcesses.Count)"
        } catch {
            $last=(($_.Exception.Message -replace '\s+',' ').Trim())
            if($last-cne$lastReported){Warn "SYNAPSE_BROKER_PARKED_PROOF_RETRY task=$($Infrastructure.TaskName) error=$last";$lastReported=$last}
        } finally {
            Close-SynapseAuthorityActiveControlPair -Pair $pair
        }
        Start-Sleep -Milliseconds 500
    } while((Get-Date) -lt $deadline)
    Die "SYNAPSE_BROKER_PARKED_AUTHORITY_NOT_ZERO task=$($Infrastructure.TaskName) bind=$Bind timeout_s=$TimeoutSeconds last=$last remediation=keep the exact adoption journal and inspect only its bound task instance/processes; a parked broker must retain exactly its inert outer-bootstrap/broker lineage and no daemon/inner-bootstrap/listener authority"
}

function Assert-SynapseBrokerInertWithoutControls {
    param(
        [Parameter(Mandatory=$true)]$Layout,
        [Parameter(Mandatory=$true)]$Infrastructure,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$DbPath,
        [ValidateRange(10,420)][int]$TimeoutSeconds=360
    )
    $expectedTask=[pscustomobject]@{Name=$Infrastructure.TaskName;XmlSha256=$Infrastructure.Task.XmlSha256;SecurityDescriptorSha256=$Infrastructure.Task.SecurityDescriptorSha256;Execute=$Infrastructure.Task.Execute;Arguments=$Infrastructure.Task.Arguments;WorkingDirectory=$Infrastructure.Task.WorkingDirectory}
    $deadline=(Get-Date).AddSeconds($TimeoutSeconds);$last='not_checked'
    do{
        try{
            [void](Assert-SynapseTaskReadbackIdentity -Expected $expectedTask -Kind broker)
            $scheduler=Get-SynapseScheduledTaskComRoot
            $taskLookup=Get-SynapseScheduledTaskLookupExact -Name ([string]$Infrastructure.TaskName) -Scheduler $scheduler
            if(-not [bool]$taskLookup.Exists){throw "expected immutable broker task disappeared task=$($Infrastructure.TaskName)"}
            $registered=$taskLookup.Task;$instances=@($registered.GetInstances(0))
            $targets=@(Select-SynapseMcpDeployTargetProcesses -Snapshot @(Get-SynapseMcpProcessSnapshot) -Bind $Bind -DbPath $DbPath);$listeners=@(Get-SynapseTcpBindListenerSnapshot -Bind $Bind)
            $brokers=@(Get-SynapseBrokerSupervisorProcessCandidates -Infrastructure $Infrastructure)
            $legacy=Get-SynapsePhysicalRelativeState -ParentPath $Layout.RuntimeBinDir -ParentChain $Layout.RuntimeChain -Leaf $Layout.LegacyGateLeaf
            $gate=Get-SynapsePhysicalRelativeState -ParentPath $Layout.Root -ParentChain $Layout.RootChain -Leaf $Layout.ControlGateLeaf
            $roster=Get-SynapsePhysicalRelativeState -ParentPath $Layout.Root -ParentChain $Layout.RootChain -Leaf $Layout.RosterLeaf
            if($instances.Count -ne 1 -or $brokers.Count -ne 1 -or $targets.Count -ne 0 -or $listeners.Count -ne 0 -or $legacy.Exists -or $gate.Exists -or $roster.Exists){throw "instances=$($instances.Count) brokers=$($brokers.Count) targets=$($targets.Count) listeners=$($listeners.Count) legacy_gate=$($legacy.Exists) control_gate=$($gate.Exists) roster=$($roster.Exists)"}
            $broker=$brokers[0];$outer=Get-CimInstance Win32_Process -Filter "ProcessId=$([int]$broker.ParentProcessId)" -ErrorAction Stop
            $outerCapability=([string]$Infrastructure.TaskCapabilitySha256).ToUpperInvariant()
            $jobName='Local\SynapseOwned-{0}-{1}' -f $outerCapability,[int]$outer.ProcessId
            [void](Assert-SynapseProcessCommandLineExact -Process $outer -ExpectedArguments @([string]$Infrastructure.Bootstrap.Path,'--outer-launch-capability',$outerCapability,[string]$Infrastructure.SemanticContract.powershell_path,[string]$Infrastructure.BrokerScript.Path,[string]$Infrastructure.SemanticContract.working_directory,[string]$Infrastructure.BootstrapLogPath) -PathArgumentIndexes @(0,3,4,5,6) -Context 'broker_inert_outer_bootstrap')
            [void](Assert-SynapseProcessCommandLineExact -Process $broker -ExpectedArguments @([string]$Infrastructure.SemanticContract.powershell_path,'-NoProfile','-ExecutionPolicy','Bypass','-File',[string]$Infrastructure.BrokerScript.Path,'-ParentJobName',$jobName) -PathArgumentIndexes @(0,5) -Context 'broker_inert_process')
            $childClass=Get-SynapseBrokerChildClassification -Broker $broker;$children=@($childClass.AuthorityChildren)
            if($children.Count -ne 0){throw "inert broker retained children=$(@($children.ProcessId)-join ',')"}
            $job=Get-SynapseDaemonJobKernelReadback -JobName $jobName;$expectedMembers=@([uint64]$outer.ProcessId,[uint64]$broker.ProcessId)+@($childClass.ConsoleHosts|ForEach-Object{[uint64]$_.ProcessId})|Sort-Object;$actualMembers=@($job.ProcessIds|ForEach-Object{[uint64]$_}|Sort-Object)
            if([uint32]$job.LimitFlags -ne [uint32]0x00002300 -or [uint64]$job.ProcessMemoryLimitBytes -ne [uint64]6699999232 -or [uint64]$job.JobMemoryLimitBytes -ne [uint64]6699999232 -or [uint32]$job.CpuRateControlFlags -ne [uint32]0x00000005 -or [uint32]$job.CpuRate -ne [uint32]2500 -or (($expectedMembers-join ',') -cne ($actualMembers-join ','))){throw "inert broker outer Job contract invalid job=$jobName"}
            return [pscustomobject][ordered]@{TaskInstanceCount=1;BrokerProcessCount=1;OuterBootstrapPid=[int]$outer.ProcessId;BrokerPid=[int]$broker.ProcessId;TargetProcessCount=0;ListenerCount=0;OuterJob=$job}
        }catch{$last=(($_.Exception.Message-replace '\s+',' ').Trim())}
        Start-Sleep -Milliseconds 500
    }while((Get-Date)-lt$deadline)
    Die "SYNAPSE_BROKER_INERT_WITHOUT_CONTROLS_FAILED task=$($Infrastructure.TaskName) bind=$Bind timeout_s=$TimeoutSeconds last=$last remediation=the monotonic immutable broker task may remain after a predecision fresh-host rollback, but it must retain only its bounded outer bootstrap/broker lineage and no control files, child, listener, or daemon authority"
}

function Assert-SynapseBrokerInertAtFreshMonotonicFloor {
    param(
        [Parameter(Mandatory=$true)]$Layout,
        [Parameter(Mandatory=$true)]$Infrastructure,
        [Parameter(Mandatory=$true)]$LegacyGateTransition,
        [Parameter(Mandatory=$true)]$LegacyDenialTransition,
        [Parameter(Mandatory=$true)][string]$LegacyTaskName,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$DbPath,
        [ValidateRange(10,420)][int]$TimeoutSeconds=360
    )
    $expectedTask=[pscustomobject]@{Name=$Infrastructure.TaskName;XmlSha256=$Infrastructure.Task.XmlSha256;SecurityDescriptorSha256=$Infrastructure.Task.SecurityDescriptorSha256;Execute=$Infrastructure.Task.Execute;Arguments=$Infrastructure.Task.Arguments;WorkingDirectory=$Infrastructure.Task.WorkingDirectory}
    $clock=[Diagnostics.Stopwatch]::StartNew();$last='not_checked'
    do{
        try{
            [void](Assert-SynapseTaskReadbackIdentity -Expected $expectedTask -Kind broker)
            $scheduler=Get-SynapseScheduledTaskComRoot
            $legacyLookup=Get-SynapseScheduledTaskLookupExact -Name $LegacyTaskName -Scheduler $scheduler
            if([bool]$legacyLookup.Exists){throw "legacy fixed task unexpectedly exists task=$LegacyTaskName"}
            $brokerLookup=Get-SynapseScheduledTaskLookupExact -Name ([string]$Infrastructure.TaskName) -Scheduler $scheduler
            if(-not [bool]$brokerLookup.Exists){throw "expected immutable broker task disappeared task=$($Infrastructure.TaskName)"}
            $instances=@($brokerLookup.Task.GetInstances(0))
            $targets=@(Select-SynapseMcpDeployTargetProcesses -Snapshot @(Get-SynapseMcpProcessSnapshot) -Bind $Bind -DbPath $DbPath)
            $listeners=@(Get-SynapseTcpBindListenerSnapshot -Bind $Bind)
            $supervisorPath=[System.IO.Path]::GetFullPath((Join-Path $Layout.RuntimeBinDir 'synapse-daemon-supervisor.ps1'))
            $launcherPath=[System.IO.Path]::GetFullPath((Join-Path $Layout.RuntimeBinDir 'synapse-daemon-launcher.vbs'))
            $supervisors=@(Get-SynapseDaemonSupervisorProcessSnapshot -SupervisorPath $supervisorPath)
            $launcherActions=@(Get-CimInstance Win32_Process -ErrorAction Stop|Where-Object{-not [string]::IsNullOrWhiteSpace([string]$_.CommandLine)-and([string]$_.CommandLine).IndexOf($launcherPath,[StringComparison]::OrdinalIgnoreCase)-ge0})
            $brokers=@(Get-SynapseBrokerSupervisorProcessCandidates -Infrastructure $Infrastructure)
            $controlGate=Get-SynapsePhysicalRelativeState -ParentPath $Layout.Root -ParentChain $Layout.RootChain -Leaf $Layout.ControlGateLeaf
            $roster=Get-SynapsePhysicalRelativeState -ParentPath $Layout.Root -ParentChain $Layout.RootChain -Leaf $Layout.RosterLeaf
            $gateState=Get-SynapsePhysicalRelativeState -ParentPath $LegacyGateTransition.parent -ParentChain $LegacyGateTransition.parent_chain -Leaf $LegacyGateTransition.leaf
            $denialState=Get-SynapsePhysicalRelativeState -ParentPath $LegacyDenialTransition.parent -ParentChain $LegacyDenialTransition.parent_chain -Leaf $LegacyDenialTransition.leaf
            if(-not(Test-SynapsePhysicalStateExact -State $gateState -ExpectedExists $true -ExpectedFileId128 $LegacyGateTransition.post_file_id_128 -ExpectedSha256 $LegacyGateTransition.post_sha256 -ExpectedLength $LegacyGateTransition.post_length) -or
               -not(Test-SynapsePhysicalStateExact -State $denialState -ExpectedExists $true -ExpectedFileId128 $LegacyDenialTransition.post_file_id_128 -ExpectedSha256 $LegacyDenialTransition.post_sha256 -ExpectedLength $LegacyDenialTransition.post_length)){
                throw 'fresh monotonic floor file identity drift'
            }
            if($instances.Count-notin@(0,1) -or $brokers.Count-ne1 -or $targets.Count-ne0 -or $listeners.Count-ne0 -or $supervisors.Count-ne0 -or $launcherActions.Count-ne0 -or $controlGate.Exists -or $roster.Exists){throw "instances=$($instances.Count) brokers=$($brokers.Count) targets=$($targets.Count) listeners=$($listeners.Count) supervisors=$($supervisors.Count) launcher_actions=$($launcherActions.Count) control_gate=$($controlGate.Exists) roster=$($roster.Exists)"}
            $broker=$brokers[0];$childClass=Get-SynapseBrokerChildClassification -Broker $broker;$children=@($childClass.AuthorityChildren)
            if($children.Count-ne0){throw "inert broker retained children=$(@($children.ProcessId)-join ',')"}
            $outer=Get-CimInstance Win32_Process -Filter "ProcessId=$([int]$broker.ParentProcessId)" -ErrorAction Stop
            $outerCapability=([string]$Infrastructure.TaskCapabilitySha256).ToUpperInvariant();$jobName='Local\SynapseOwned-{0}-{1}' -f $outerCapability,[int]$outer.ProcessId
            [void](Assert-SynapseProcessCommandLineExact -Process $outer -ExpectedArguments @([string]$Infrastructure.Bootstrap.Path,'--outer-launch-capability',$outerCapability,[string]$Infrastructure.SemanticContract.powershell_path,[string]$Infrastructure.BrokerScript.Path,[string]$Infrastructure.SemanticContract.working_directory,[string]$Infrastructure.BootstrapLogPath) -PathArgumentIndexes @(0,3,4,5,6) -Context 'broker_fresh_floor_outer')
            [void](Assert-SynapseProcessCommandLineExact -Process $broker -ExpectedArguments @([string]$Infrastructure.SemanticContract.powershell_path,'-NoProfile','-ExecutionPolicy','Bypass','-File',[string]$Infrastructure.BrokerScript.Path,'-ParentJobName',$jobName) -PathArgumentIndexes @(0,5) -Context 'broker_fresh_floor_broker')
            $job=Get-SynapseDaemonJobKernelReadback -JobName $jobName;$expectedMembers=@([uint64]$outer.ProcessId,[uint64]$broker.ProcessId)+@($childClass.ConsoleHosts|ForEach-Object{[uint64]$_.ProcessId})|Sort-Object;$actualMembers=@($job.ProcessIds|ForEach-Object{[uint64]$_}|Sort-Object)
            if([uint32]$job.LimitFlags-ne[uint32]0x00002300 -or [uint64]$job.ProcessMemoryLimitBytes-ne[uint64]6699999232 -or [uint64]$job.JobMemoryLimitBytes-ne[uint64]6699999232 -or [uint32]$job.CpuRateControlFlags-ne[uint32]0x00000005 -or [uint32]$job.CpuRate-ne[uint32]2500 -or (($expectedMembers-join ',')-cne($actualMembers-join ','))){throw "inert broker outer Job contract invalid job=$jobName"}
            $LegacyGateTransition.CanonicalLease.RequireExact('fresh_floor_gate')
            $LegacyDenialTransition.CanonicalLease.RequireExact('fresh_floor_denial')
            return [pscustomobject][ordered]@{LegacyTaskAbsent=$true;BrokerTaskInert=$true;TaskInstanceCount=[int]$instances.Count;BrokerProcessCount=1;OuterBootstrapPid=[int]$outer.ProcessId;BrokerPid=[int]$broker.ProcessId;ActionProcessCount=0;TargetProcessCount=0;ListenerCount=0;SupervisorProcessCount=0;ControlGateAbsent=$true;RosterAbsent=$true;OuterJob=$job}
        }catch{$last=(($_.Exception.Message-replace '\s+',' ').Trim())}
        Start-Sleep -Milliseconds 500
    }while($clock.Elapsed.TotalSeconds-lt$TimeoutSeconds)
    Die "SYNAPSE_BROKER_FRESH_MONOTONIC_FLOOR_FAILED task=$($Infrastructure.TaskName) legacy_task=$LegacyTaskName bind=$Bind timeout_s=$TimeoutSeconds last=$last"
}

function Wait-SynapseBrokerInnerAuthorityDrained {
    param(
        [Parameter(Mandatory=$true)]$Infrastructure,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$DbPath,
        [ValidateRange(10,420)][int]$TimeoutSeconds=360,
        [switch]$AllowPriorAuthority,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $expectedTask=[pscustomobject]@{Name=$Infrastructure.TaskName;XmlSha256=$Infrastructure.Task.XmlSha256;SecurityDescriptorSha256=$Infrastructure.Task.SecurityDescriptorSha256;Execute=$Infrastructure.Task.Execute;Arguments=$Infrastructure.Task.Arguments;WorkingDirectory=$Infrastructure.Task.WorkingDirectory}
    $deadline=(Get-Date).AddSeconds($TimeoutSeconds);$last='not_checked';$reportedLast=''
    do{
        try{
            [void](Assert-SynapseTaskReadbackIdentity -Expected $expectedTask -Kind broker)
            $brokers=@(Get-SynapseBrokerSupervisorProcessCandidates -Infrastructure $Infrastructure)
            $targets=@(Select-SynapseMcpDeployTargetProcesses -Snapshot @(Get-SynapseMcpProcessSnapshot) -Bind $Bind -DbPath $DbPath)
            $listeners=@(Get-SynapseTcpBindListenerSnapshot -Bind $Bind)
            $brokerCountValid = $brokers.Count -in @(0,1)
            $priorCountValid=if($AllowPriorAuthority){$targets.Count-in@(0,1)-and$listeners.Count-eq$targets.Count}else{$targets.Count-eq0-and$listeners.Count-eq0}
            if(-not $brokerCountValid -or -not $priorCountValid){throw "brokers=$($brokers.Count) targets=$($targets.Count) listeners=$($listeners.Count) expected_prior=$(if($AllowPriorAuthority){'coherent_0_or_1'}else{'0'})"}
            if ($brokers.Count -eq 0) {
                return [pscustomobject][ordered]@{BrokerPid=$null;OuterBootstrapPid=$null;InnerChildCount=0;TargetProcessCount=$targets.Count;ListenerCount=$listeners.Count;PriorAuthorityRetained=($targets.Count-eq1);PriorAuthorityAbsent=($targets.Count-eq0);OuterJob=$null;BrokerLineageAbsent=$true}
            }
            $broker=$brokers[0]
            $childClass=Get-SynapseBrokerChildClassification -Broker $broker;$children=@($childClass.AuthorityChildren)
            if($children.Count -ne 0){throw "inner_children=$(@($children.ProcessId)-join ',')"}
            $outer=Get-CimInstance Win32_Process -Filter "ProcessId=$([int]$broker.ParentProcessId)" -ErrorAction Stop
            $outerCapability=([string]$Infrastructure.TaskCapabilitySha256).ToUpperInvariant()
            $jobName='Local\SynapseOwned-{0}-{1}' -f $outerCapability,[int]$outer.ProcessId
            [void](Assert-SynapseProcessCommandLineExact -Process $outer -ExpectedArguments @([string]$Infrastructure.Bootstrap.Path,'--outer-launch-capability',$outerCapability,[string]$Infrastructure.SemanticContract.powershell_path,[string]$Infrastructure.BrokerScript.Path,[string]$Infrastructure.SemanticContract.working_directory,[string]$Infrastructure.BootstrapLogPath) -PathArgumentIndexes @(0,3,4,5,6) -Context "${Context}_outer_bootstrap")
            [void](Assert-SynapseProcessCommandLineExact -Process $broker -ExpectedArguments @([string]$Infrastructure.SemanticContract.powershell_path,'-NoProfile','-ExecutionPolicy','Bypass','-File',[string]$Infrastructure.BrokerScript.Path,'-ParentJobName',$jobName) -PathArgumentIndexes @(0,5) -Context "${Context}_broker")
            $job=Get-SynapseDaemonJobKernelReadback -JobName $jobName
            $expectedMembers=@([uint64]$outer.ProcessId,[uint64]$broker.ProcessId)+@($childClass.ConsoleHosts|ForEach-Object{[uint64]$_.ProcessId})|Sort-Object
            $actualMembers=@($job.ProcessIds|ForEach-Object{[uint64]$_}|Sort-Object)
            if([uint32]$job.LimitFlags -ne [uint32]0x00002300 -or [uint64]$job.ProcessMemoryLimitBytes -ne [uint64]6699999232 -or [uint64]$job.JobMemoryLimitBytes -ne [uint64]6699999232 -or [uint32]$job.CpuRateControlFlags -ne [uint32]0x00000005 -or [uint32]$job.CpuRate -ne [uint32]2500 -or (($expectedMembers-join ',') -cne ($actualMembers-join ','))){throw "outer_job_contract_invalid job=$jobName flags=$($job.LimitFlags) process_memory=$($job.ProcessMemoryLimitBytes) job_memory=$($job.JobMemoryLimitBytes) cpu_flags=$($job.CpuRateControlFlags) cpu_rate=$($job.CpuRate) expected_members=$($expectedMembers-join',') actual_members=$($actualMembers-join',')"}
            return [pscustomobject][ordered]@{BrokerPid=[int]$broker.ProcessId;OuterBootstrapPid=[int]$outer.ProcessId;InnerChildCount=0;TargetProcessCount=$targets.Count;ListenerCount=$listeners.Count;PriorAuthorityRetained=([bool]$AllowPriorAuthority-and$targets.Count-eq1);PriorAuthorityAbsent=([bool]$AllowPriorAuthority-and$targets.Count-eq0);OuterJob=$job}
        }catch{
            $last=(($_.Exception.Message-replace '\s+',' ').Trim())
            if($last-cne$reportedLast){Write-Host "[synapse-setup] SYNAPSE_BROKER_INNER_AUTHORITY_DRAIN_WAIT context=$Context reason=$last";$reportedLast=$last}
        }
        Start-Sleep -Milliseconds 500
    }while((Get-Date)-lt$deadline)
    Die "SYNAPSE_BROKER_INNER_AUTHORITY_DRAIN_TIMEOUT context=$Context task=$($Infrastructure.TaskName) bind=$Bind timeout_s=$TimeoutSeconds last=$last remediation=control revocation must terminate only the exact retained inner bootstrap tree while leaving the outer broker polling"
}

function Stop-SynapseFreshBrokerSurvivorExact {
    param([Parameter(Mandatory=$true)]$Infrastructure,[Parameter(Mandatory=$true)]$Detail,[ValidateRange(10,300)][int]$TimeoutSeconds=60)
    Ensure-SynapseDaemonJobReadbackType;Ensure-SynapseWindowsCommandLineArgvType
    $outerPid=[uint32]$Detail.outer_bootstrap_pid;$brokerPid=[uint32]$Detail.broker_pid;if($outerPid-lt1-or$brokerPid-lt1){Die 'SYNAPSE_FRESH_BROKER_SURVIVOR_IDENTITY_MISSING'};$all=@(Get-CimInstance Win32_Process -ErrorAction Stop);$outer=@($all|Where-Object{[uint32]$_.ProcessId-eq$outerPid});$broker=@($all|Where-Object{[uint32]$_.ProcessId-eq$brokerPid});if($outer.Count-ne1-or$broker.Count-ne1-or[uint32]$broker[0].ParentProcessId-ne$outerPid){Die "SYNAPSE_FRESH_BROKER_SURVIVOR_LINEAGE_INVALID outer=$outerPid broker=$brokerPid"}
    $outerNative=[string]$outer[0].CommandLine;$outerArgv=@([SynapseSetup.WindowsCommandLineArgv]::Parse($outerNative));$cap=([string]$Infrastructure.TaskCapabilitySha256).ToUpperInvariant();$jobName="Local\SynapseOwned-$cap-$outerPid";if($outerArgv.Count-ne7-or[IO.Path]::GetFullPath([string]$outerArgv[0])-ine[IO.Path]::GetFullPath([string]$Infrastructure.Bootstrap.Path)-or[string]$outerArgv[1]-cne'--outer-launch-capability'-or[string]$outerArgv[2]-ine$cap-or[IO.Path]::GetFullPath([string]$outerArgv[3])-ine[IO.Path]::GetFullPath([string]$Infrastructure.PowerShell.Path)-or[IO.Path]::GetFullPath([string]$outerArgv[4])-ine[IO.Path]::GetFullPath([string]$Infrastructure.BrokerScript.Path)){Die "SYNAPSE_FRESH_BROKER_SURVIVOR_OUTER_ARGV_INVALID pid=$outerPid"}
    $brokerNative=[string]$broker[0].CommandLine;$brokerArgv=@([SynapseSetup.WindowsCommandLineArgv]::Parse($brokerNative));if($brokerArgv.Count-ne8-or[IO.Path]::GetFullPath([string]$brokerArgv[0])-ine[IO.Path]::GetFullPath([string]$Infrastructure.PowerShell.Path)-or[string]$brokerArgv[1]-cne'-NoProfile'-or[string]$brokerArgv[2]-cne'-ExecutionPolicy'-or[string]$brokerArgv[3]-cne'Bypass'-or[string]$brokerArgv[4]-cne'-File'-or[IO.Path]::GetFullPath([string]$brokerArgv[5])-ine[IO.Path]::GetFullPath([string]$Infrastructure.BrokerScript.Path)-or[string]$brokerArgv[6]-cne'-ParentJobName'-or[string]$brokerArgv[7]-cne$jobName){Die "SYNAPSE_FRESH_BROKER_SURVIVOR_BROKER_ARGV_INVALID pid=$brokerPid"}
    $outerLease=$null;$brokerLease=$null;$jobLease=$null
    try{
        $outerLease=[SynapseAuthorityRuntime.MappedProcessLease]::OpenForTermination($outerPid,0L,[string]$Infrastructure.Bootstrap.Path,[string]$Infrastructure.Bootstrap.FileId128,[string]$Infrastructure.Bootstrap.Sha256,[int64]$Infrastructure.Bootstrap.Length,'fresh_broker_survivor_outer');$po=$Infrastructure.PowerShell.ProtectedOs;$brokerLease=[SynapseAuthorityRuntime.MappedProcessLease]::OpenProtectedOsForTermination($brokerPid,0L,[string]$Infrastructure.PowerShell.Path,[string]$Infrastructure.PowerShell.FileId128,[string]$Infrastructure.PowerShell.Sha256,[int64]$Infrastructure.PowerShell.Length,[uint32]$po.LinkCount,[string]$po.SecurityDescriptorSddl,[string[]]@($po.HardlinkPaths),'fresh_broker_survivor_broker');if([string]$outerLease.ReadCommandLine('fresh_broker_survivor_outer_argv')-cne$outerNative-or[string]$brokerLease.ReadCommandLine('fresh_broker_survivor_broker_argv')-cne$brokerNative){Die 'SYNAPSE_FRESH_BROKER_SURVIVOR_NATIVE_ARGV_DRIFT'}
        $classification=Get-SynapseBrokerChildClassification -Broker $broker[0];if(@($classification.AuthorityChildren).Count-ne0){Die "SYNAPSE_FRESH_BROKER_SURVIVOR_DESCENDANTS_INVALID pids=$(@($classification.AuthorityChildren.ProcessId)-join',')"};$members=[uint64[]]@([uint64]$outerPid,[uint64]$brokerPid)+@($classification.ConsoleHosts|ForEach-Object{[uint64]$_.ProcessId});$members=[uint64[]]@($members|Sort-Object -Unique);$jobLease=[SynapseSetup.BrokerDecommissionJobLease]::OpenOrNull($jobName,$cap,$outerPid,(Get-SynapseBrokerDecommissionExpectedJobSecurityDescriptor),$members,$true,'fresh_broker_survivor_job');if($null-eq$jobLease){Die "SYNAPSE_FRESH_BROKER_SURVIVOR_JOB_ABSENT name=$jobName"};$jobLease.RequireExact($members,'fresh_broker_survivor_boundary');[void]$brokerLease.TerminateAndWait([uint32]($TimeoutSeconds*1000),127,'fresh_broker_survivor_broker_terminal');[void]$outerLease.TerminateAndWait([uint32]($TimeoutSeconds*1000),127,'fresh_broker_survivor_outer_terminal');$jobLease.ProveEmptyAfterProcessTermination($members,$TimeoutSeconds*1000,'fresh_broker_survivor_drain');$jobLease.Dispose();$jobLease=$null;[SynapseSetup.BrokerDecommissionJobLease]::RequireNameAbsent($jobName,'fresh_broker_survivor_job_absent');Info "SYNAPSE_FRESH_BROKER_SURVIVOR_DRAINED outer_pid=$outerPid broker_pid=$brokerPid job=$jobName"
    }finally{foreach($l in @($jobLease,$brokerLease,$outerLease)){if($null-ne$l){try{$l.Dispose()}catch{[Environment]::FailFast('SYNAPSE_FRESH_BROKER_SURVIVOR_LEASE_RELEASE_UNPROVEN',$_.Exception)}}}}
}

function Assert-SynapseAuthorityLegacyRollbackEvidence {
    param(
        [Parameter(Mandatory=$true)][ValidateSet('legacy_prior_unchanged','legacy_direct_recovery')][string]$Mode,
        [Parameter(Mandatory=$true)]$Evidence,
        [Parameter(Mandatory=$true)]$Initial,
        $Validated,
        [Parameter(Mandatory=$true)]$Allocation,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $attempts=@();$ownedAttempts=$false;$classification=$null
    try{
        if($null-ne$Validated -and $null-ne$Validated.PSObject.Properties['LegacyRescueLaunchAttempts'] -and @($Validated.LegacyRescueLaunchAttempts).Count-eq4){$attempts=@($Validated.LegacyRescueLaunchAttempts)}
        else{
            $attempts=@(Assert-SynapseLegacyDirectRescueAttemptPlans -Plans @($Initial.legacy_rescue_launch_attempts) -LegacyTask $Initial.legacy_task -TransactionRoot ([string]$Initial.transaction_root) -TransactionRootFileId128 ([string]$Initial.transaction_root_file_id_128) -InvocationId ([string]$Initial.invocation_id) -BrokerIdentitySha256 ([string]$Initial.broker_identity_sha256) -AuthorityEpoch ([int64]$Initial.authority_epoch) -Allocation $Allocation)
            $ownedAttempts=$true
        }
        if($attempts.Count-ne4){Die "SYNAPSE_AUTHORITY_ROLLBACK_ATTEMPT_COUNT_INVALID context=$Context count=$($attempts.Count)"}
        $classification=Get-SynapseLegacyDirectRescueRecoveryClassification -Attempts $attempts -TransactionRoot ([string]$Initial.transaction_root) -TransactionRootFileId128 ([string]$Initial.transaction_root_file_id_128) -Allocation $Allocation -PriorGenerationDescriptor $Initial.prior_generation -Context "${Context}_physical"
        $compat=$classification.AttemptStates[0]
        if($Mode-ceq'legacy_direct_recovery' -and (-not[bool]$classification.CompatibilityComplete -or $null-eq$compat.KeeperReceipt -or $null-eq$compat.ActionReceipt -or $null-eq$compat.FinalTransferReceipt -or $compat.JobPresent)){Die "SYNAPSE_AUTHORITY_ROLLBACK_COMPATIBILITY_STATE_INVALID context=$Context class=$($classification.Class)"}
        $expectedCompatibility=[ordered]@{attempt_index=1;launch_capability_sha256=([string]$compat.Attempt.Plan.launch_capability_sha256).ToUpperInvariant();intent=[string]$compat.Intent;progress=[string]$compat.ProgressSymbol;keeper_prepared=$(if($null-ne$compat.KeeperReceipt){ConvertTo-SynapseLegacyDirectRescueProgressReference -Receipt $compat.KeeperReceipt}else{$null});action_prepared=$(if($null-ne$compat.ActionReceipt){ConvertTo-SynapseLegacyDirectRescueProgressReference -Receipt $compat.ActionReceipt}else{$null});final_transfer=$(if($null-ne$compat.FinalTransferReceipt){ConvertTo-SynapseLegacyDirectRescueProgressReference -Receipt $compat.FinalTransferReceipt}else{$null});job_absent=(-not[bool]$compat.JobPresent)}
        if((Get-SynapseCanonicalJson -Value $Evidence.compatibility)-cne(Get-SynapseCanonicalJson -Value $expectedCompatibility)){Die "SYNAPSE_AUTHORITY_ROLLBACK_COMPATIBILITY_EVIDENCE_INVALID context=$Context"}
        $states=@($classification.AttemptStates|Where-Object{$_.Index-gt1}|Sort-Object Index)
        if($states.Count-ne3 -or (@($states.Index)-join ',')-cne'2,3,4'){Die "SYNAPSE_AUTHORITY_ROLLBACK_RECOVERY_ATTEMPT_SET_INVALID context=$Context"}
        if($Mode-ceq'legacy_prior_unchanged'){
            $runtime=$Evidence.task_runtime;$runtimeNames=@(Get-SynapseObjectPropertyNames -Object $runtime);$runtimeExpected=@('Schema','TaskName','State','LastRunTimeUtc','LastRunTimeFileTimeUtc','LastTaskResult','NextRunTimePresent','NextRunTimeUtc','InstanceCount','Instances')
            $lastRun=[datetime]::MinValue
            try{$lastRun=[datetime]::Parse([string]$runtime.LastRunTimeUtc,[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::RoundtripKind).ToUniversalTime()}catch{Die "SYNAPSE_AUTHORITY_LEGACY_PRIOR_TASK_RUNTIME_TIME_INVALID context=$Context"}
            $instances=@($runtime.Instances);$invalidInstances=@($instances|Where-Object{$n=@(Get-SynapseObjectPropertyNames -Object $_);$n.Count-ne3 -or @($n|Where-Object{@('instance_guid','engine_pid','current_action')-cnotcontains$_}).Count-ne0 -or [string]$_.instance_guid-notmatch'^[{]?[0-9A-Fa-f-]{36}[}]?$' -or [int]$_.engine_pid-lt1})
            if($runtimeNames.Count-ne$runtimeExpected.Count -or @($runtimeNames|Where-Object{$runtimeExpected-cnotcontains$_}).Count-ne0 -or [string]$runtime.Schema-cne'synapse_legacy_direct_rescue_task_runtime/v1' -or [string]$runtime.TaskName-cne[string]$Initial.legacy_task.name -or [int]$runtime.State-notin@(3,4) -or [int64]$runtime.LastRunTimeFileTimeUtc-ne[int64]$lastRun.ToFileTimeUtc() -or ([bool]$runtime.NextRunTimePresent-ne(-not[string]::IsNullOrEmpty([string]$runtime.NextRunTimeUtc))) -or [int]$runtime.InstanceCount-ne$instances.Count -or $instances.Count-gt1 -or $invalidInstances.Count-ne0 -or @($instances.instance_guid|Sort-Object -Unique).Count-ne$instances.Count -or @($instances.engine_pid|Sort-Object -Unique).Count-ne$instances.Count){Die "SYNAPSE_AUTHORITY_LEGACY_PRIOR_TASK_RUNTIME_INVALID context=$Context"}
            $expectedAttempts=@($states|ForEach-Object{ConvertTo-SynapseLegacyRecoveryAttemptTerminalEvidence -State $_})
            if((Get-SynapseCanonicalJson -Value @($Evidence.recovery_attempts))-cne(Get-SynapseCanonicalJson -Value $expectedAttempts) -or @($states|Where-Object{$_.JobPresent -or $_.Intent-ceq'C' -or ($_.Intent-ceq'S' -and $_.ProgressSymbol-cne'EEE')}).Count-ne0){Die "SYNAPSE_AUTHORITY_LEGACY_PRIOR_RECOVERY_ATTEMPT_EVIDENCE_INVALID context=$Context"}
            $seenUnused=$false
            foreach($state in $states){if($state.Intent-ceq'S'){$seenUnused=$true}elseif($seenUnused){Die "SYNAPSE_AUTHORITY_LEGACY_PRIOR_RECOVERY_ATTEMPT_ORDER_INVALID context=$Context attempt=$($state.Index)"}}
        }else{
            $selected=@($states|Where-Object{[int]$_.Index-eq[int]$Evidence.attempt_index})
            if($selected.Count-ne1 -or $null-eq$selected[0].KeeperReceipt -or $null-eq$selected[0].ActionReceipt -or [string]$selected[0].Intent-cne'C'){Die "SYNAPSE_AUTHORITY_LEGACY_DIRECT_SELECTED_ATTEMPT_INVALID context=$Context attempt=$($Evidence.attempt_index) class=$($classification.Class)"}
            $selected=$selected[0]
            $finalCut=@($selected.Classifications|Where-Object{[string]$_.Phase-ceq'final_transfer'})
            if($finalCut.Count-ne1){Die "SYNAPSE_AUTHORITY_LEGACY_DIRECT_FINAL_CUT_MISSING context=$Context attempt=$($selected.Index)"}
            $finalCut=$finalCut[0]
            if([string]$Evidence.final_transfer_kind-ceq'valid'){
                if($null-eq$selected.FinalTransferReceipt -or [string]$selected.ProgressSymbol-cne'VVV' -or [string]$classification.Class-notin@('transferred','transferred_job_absent') -or [string]$finalCut.Kind-cne'valid'){Die "SYNAPSE_AUTHORITY_LEGACY_DIRECT_VALID_TRANSFER_STATE_INVALID context=$Context attempt=$($selected.Index) class=$($classification.Class) progress=$($selected.ProgressSymbol)"}
                $expectedFinalReference=ConvertTo-SynapseLegacyDirectRescueProgressReference -Receipt $selected.FinalTransferReceipt
                $expectedLineage=$selected.FinalTransferReceipt.Detail.evidence
            }else{
                if($null-ne$selected.FinalTransferReceipt -or [string]$selected.ProgressSymbol-cne'VVT' -or [string]$classification.Class-notin@('transfer_evidence_torn_candidate','partial') -or [string]$finalCut.Kind-cne'torn'){Die "SYNAPSE_AUTHORITY_LEGACY_DIRECT_TORN_TRANSFER_STATE_INVALID context=$Context attempt=$($selected.Index) class=$($classification.Class) progress=$($selected.ProgressSymbol)"}
                $expectedFinalReference=[ordered]@{phase='final_transfer';leaf=[string]$finalCut.Leaf;file_id_128=([string]$finalCut.FileId128).ToUpperInvariant();sha256=([string]$finalCut.Sha256).ToUpperInvariant();length=[int64]$finalCut.Length}
                $syntheticDetail=[ordered]@{schema='synapse_legacy_direct_rescue_final_transfer/v1';mode='direct_recovery';keeper_progress_file_id_128=[string]$selected.KeeperReceipt.FileId128;keeper_progress_sha256=[string]$selected.KeeperReceipt.RawSha256;keeper_progress_length=[int64]$selected.KeeperReceipt.RawLength;action_progress_file_id_128=[string]$selected.ActionReceipt.FileId128;action_progress_sha256=[string]$selected.ActionReceipt.RawSha256;action_progress_length=[int64]$selected.ActionReceipt.RawLength;authority_transferred=$true;probe_job_terminated=$false;evidence=(ConvertTo-SynapseCanonicalValue -Value $Evidence.lineage)}
                $syntheticReceipt=[pscustomobject][ordered]@{Phase='final_transfer';Payload=[pscustomobject]@{previous_progress_sha256=[string]$selected.ActionReceipt.RawSha256};Detail=$syntheticDetail}
                [void](Assert-SynapseLegacyDirectRescueProgressDetail -Receipt $syntheticReceipt -Attempt $selected.Attempt -KeeperReceipt $selected.KeeperReceipt -ActionReceipt $selected.ActionReceipt -PriorGeneration $Initial.prior_generation -Context "${Context}_torn_lineage")
                $expectedLineage=$Evidence.lineage
            }
            $intentExpected=[ordered]@{leaf=[string]$selected.Attempt.Transition.leaf;file_id_128=([string]$selected.Attempt.Transition.post_file_id_128).ToUpperInvariant();sha256=([string]$selected.Attempt.Transition.post_sha256).ToUpperInvariant();length=[int64]$selected.Attempt.Transition.post_length;location='canonical'}
            if((Get-SynapseCanonicalJson -Value $Evidence.intent)-cne(Get-SynapseCanonicalJson -Value $intentExpected) -or
               (Get-SynapseCanonicalJson -Value $Evidence.keeper_prepared)-cne(Get-SynapseCanonicalJson -Value (ConvertTo-SynapseLegacyDirectRescueProgressReference -Receipt $selected.KeeperReceipt)) -or
               (Get-SynapseCanonicalJson -Value $Evidence.action_prepared)-cne(Get-SynapseCanonicalJson -Value (ConvertTo-SynapseLegacyDirectRescueProgressReference -Receipt $selected.ActionReceipt)) -or
               (Get-SynapseCanonicalJson -Value $Evidence.final_transfer)-cne(Get-SynapseCanonicalJson -Value $expectedFinalReference) -or
               (Get-SynapseCanonicalJson -Value $Evidence.lineage)-cne(Get-SynapseCanonicalJson -Value $expectedLineage)){Die "SYNAPSE_AUTHORITY_LEGACY_DIRECT_PROGRESS_EVIDENCE_INVALID context=$Context attempt=$($selected.Index)"}
            $job=$Evidence.recovery_job;$jobNames=@($job.PSObject.Properties.Name);$jobExpected=@('name','security_descriptor_sddl','remote_job_handle_value','process_ids');$pids=@($job.process_ids|ForEach-Object{[uint64]$_}|Sort-Object)
            $lineagePids=@($Evidence.lineage.process_ids|ForEach-Object{[uint64]$_}|Sort-Object)
            if($jobNames.Count-ne$jobExpected.Count -or @($jobNames|Where-Object{$jobExpected-cnotcontains$_}).Count-ne0 -or [string]$job.name-cne[string]$selected.Attempt.Plan.recovery_job.name -or [string]$job.security_descriptor_sddl-cne[string]$selected.Attempt.Plan.recovery_job.security_descriptor_sddl -or [int64]$job.remote_job_handle_value-ne[int64]$selected.KeeperReceipt.Detail.remote_job_handle_value -or $pids.Count-ne4 -or @($pids|Sort-Object -Unique).Count-ne4 -or ($pids-join',')-cne($lineagePids-join',') -or ($selected.JobPresent -and (@($selected.JobProcessIds|ForEach-Object{[uint64]$_}|Sort-Object)-join',')-cne($pids-join','))){Die "SYNAPSE_AUTHORITY_LEGACY_DIRECT_JOB_EVIDENCE_INVALID context=$Context attempt=$($selected.Index)"}
            $expectedLineageSource=if([string]$Evidence.final_transfer_kind-ceq'valid'){'final_transfer_receipt'}else{'terminalization_job_proof'}
            if([string]$Evidence.lineage_source-cne$expectedLineageSource -or [string]$Evidence.authority_resolution_policy-cne'exact_job_else_recorded_lineage_gone_then_scheduler' -or [int]$Evidence.health_pid-ne[int]$Evidence.lineage.health_pid -or [int]$Evidence.tool_count-ne[int]$Evidence.lineage.tool_count -or [string]$Evidence.tool_surface_sha256-ine[string]$Evidence.lineage.tool_surface_sha256 -or [int]$Evidence.listener_count-ne[int]$Evidence.lineage.listener_count -or (Get-SynapseCanonicalJson -Value $Evidence.lineage.keeper)-cne(Get-SynapseCanonicalJson -Value $selected.Attempt.Plan.keeper)){Die "SYNAPSE_AUTHORITY_LEGACY_DIRECT_LINEAGE_SUMMARY_INVALID context=$Context attempt=$($selected.Index)"}
            $expectedAttempts=@($states|ForEach-Object{[ordered]@{attempt_index=[int]$_.Index;launch_capability_sha256=([string]$_.Attempt.Plan.launch_capability_sha256).ToUpperInvariant();intent=[string]$_.Intent;progress=[string]$_.ProgressSymbol;selected_transfer_attempt=([int]$_.Index-eq[int]$selected.Index)}})
            if((Get-SynapseCanonicalJson -Value @($Evidence.recovery_attempts))-cne(Get-SynapseCanonicalJson -Value $expectedAttempts)){Die "SYNAPSE_AUTHORITY_LEGACY_DIRECT_RECOVERY_ATTEMPT_EVIDENCE_INVALID context=$Context attempt=$($selected.Index)"}
        }
    }finally{
        Close-SynapseLegacyDirectRescueRecoveryClassification -Classification $classification
        if($ownedAttempts){Close-SynapseAuthorityControlTransitionLeases -Transitions @($attempts|ForEach-Object{$_.Transition})}
    }
}

function Assert-SynapseAuthorityRollbackTerminalDetail {
    param(
        [Parameter(Mandatory=$true)]$Detail,
        [Parameter(Mandatory=$true)]$Initial,
        $Validated=$null,
        $Allocation=$null,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $names=@(Get-SynapseObjectPropertyNames -Object $Detail);$expected=@('schema','mode','trigger','primary_failure_sha256','prior_authority','authority_restored','broker_identity_sha256','unknown_objects_preserved','authority_evidence')
    if($names.Count-ne$expected.Count -or @($names|Where-Object{$expected-cnotcontains$_}).Count-ne0 -or [string]$Detail.schema-cne'synapse_authority_rollback/v2' -or [string]$Detail.trigger-notin@('cold_predecision','normal_catch') -or [string]$Detail.broker_identity_sha256-ine[string]$Initial.broker_identity_sha256 -or -not[bool]$Detail.unknown_objects_preserved){Die "SYNAPSE_AUTHORITY_ROLLBACK_TERMINAL_SHAPE_INVALID context=$Context mode=$($Detail.mode)"}
    if(([string]$Detail.trigger-ceq'normal_catch' -and [string]$Detail.primary_failure_sha256-notmatch'^[0-9A-Fa-f]{64}$') -or ([string]$Detail.trigger-ceq'cold_predecision' -and -not([string]::IsNullOrEmpty([string]$Detail.primary_failure_sha256)))){Die "SYNAPSE_AUTHORITY_ROLLBACK_FAILURE_IDENTITY_INVALID context=$Context trigger=$($Detail.trigger)"}
    $mode=[string]$Detail.mode;$e=$Detail.authority_evidence
    $gateTransition=if($null-ne$Validated -and $null-ne$Validated.PSObject.Properties['LegacyGateTransition']){$Validated.LegacyGateTransition}else{$Initial.legacy_gate_transition}
    $denialTransition=if($null-ne$Validated -and $null-ne$Validated.PSObject.Properties['LegacyDenialTransition']){$Validated.LegacyDenialTransition}else{$Initial.legacy_denial_stub_transition}
    $expectedPrior=if($mode-ceq'fresh_monotonic_floor'){'absent'}elseif($mode-ceq'predecessor_restored'){[string]$Initial.prior_authority}else{'legacy'};$expectedRestored=if($mode-ceq'predecessor_restored'){'predecessor'}else{$mode}
    if($mode-notin@('legacy_prior_unchanged','legacy_direct_recovery','fresh_monotonic_floor','predecessor_restored') -or [string]$Detail.prior_authority-cne$expectedPrior -or [string]$Detail.authority_restored-cne$expectedRestored){Die "SYNAPSE_AUTHORITY_ROLLBACK_MODE_INVALID context=$Context mode=$mode prior=$($Detail.prior_authority) restored=$($Detail.authority_restored)"}
    if($mode-ceq'predecessor_restored'){
        $receipt=Assert-SynapseAuthorityPredecessorReceiptDescriptor -Receipt $Initial.predecessor_authority_receipt -Context "${Context}_restored_receipt"
        $eNames=@(Get-SynapseObjectPropertyNames -Object $e);$eExpected=@('schema','predecessor_restored','predecessor_receipt_sha256','predecessor_mode','predecessor_authority_descriptor')
        $declaredReceiptSha=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $receipt)).ToUpperInvariant()
        $receiptHashMatches=[string]$e.predecessor_receipt_sha256-ieq$declaredReceiptSha
        $evidenceNamesMatch=($eNames.Count-eq$eExpected.Count -and @($eNames|Where-Object{$eExpected-cnotcontains$_}).Count-eq0)
        $schemaMatches=[string]$e.schema-ceq'synapse_authority_predecessor_restored/v1'
        $modeMatches=[string]$e.predecessor_mode-ceq[string]$receipt.terminal_mode
        $descriptorMatches=(Get-SynapseCanonicalJson -Value $e.predecessor_authority_descriptor)-ceq(Get-SynapseCanonicalJson -Value $receipt.authority_descriptor)
        if(-not$evidenceNamesMatch -or -not$schemaMatches -or -not[bool]$e.predecessor_restored -or -not$receiptHashMatches -or -not$modeMatches -or -not$descriptorMatches){Die "SYNAPSE_AUTHORITY_PREDECESSOR_RESTORED_TERMINAL_INVALID context=$Context names=$evidenceNamesMatch schema=$schemaMatches restored=$([bool]$e.predecessor_restored) expected_receipt_sha=$declaredReceiptSha actual_receipt_sha=$($e.predecessor_receipt_sha256) mode=$modeMatches descriptor=$descriptorMatches expected_descriptor_sha=$((Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $receipt.authority_descriptor)).ToUpperInvariant()) actual_descriptor_sha=$((Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $e.predecessor_authority_descriptor)).ToUpperInvariant())"}
        return (ConvertTo-SynapseCanonicalValue -Value $Detail)
    }
    if($mode-ceq'fresh_monotonic_floor'){
        $eNames=@(Get-SynapseObjectPropertyNames -Object $e);$eExpected=@('schema','legacy_gate','legacy_denial_stub','legacy_task_absent','control_gate_absent','roster_absent','broker_task','broker_task_inert','action_process_count','target_process_count','listener_count','supervisor_process_count','recovery_job_count')
        $fileRefExpected=@('path','file_id_128','sha256','length');$gateNames=@(Get-SynapseObjectPropertyNames -Object $e.legacy_gate);$denialNames=@(Get-SynapseObjectPropertyNames -Object $e.legacy_denial_stub)
        $nonzeroEvidence=@(@($e.action_process_count,$e.target_process_count,$e.listener_count,$e.supervisor_process_count,$e.recovery_job_count)|Where-Object{[int]$_-ne0})
        if($eNames.Count-ne$eExpected.Count -or @($eNames|Where-Object{$eExpected-cnotcontains$_}).Count-ne0 -or [string]$e.schema-cne'synapse_authority_fresh_monotonic_floor/v1' -or -not[bool]$e.legacy_task_absent -or -not[bool]$e.control_gate_absent -or -not[bool]$e.roster_absent -or -not[bool]$e.broker_task_inert -or @(@($e.action_process_count,$e.target_process_count,$e.listener_count,$e.supervisor_process_count,$e.recovery_job_count)|Where-Object{[int]$_-ne0}).Count-ne0 -or
           $gateNames.Count-ne$fileRefExpected.Count -or @($gateNames|Where-Object{$fileRefExpected-cnotcontains$_}).Count-ne0 -or $denialNames.Count-ne$fileRefExpected.Count -or @($denialNames|Where-Object{$fileRefExpected-cnotcontains$_}).Count-ne0 -or
           (Get-SynapseCanonicalJson -Value $e.broker_task)-cne(Get-SynapseCanonicalJson -Value $Initial.broker_task) -or
           [string]$e.legacy_gate.path-ine[string]$gateTransition.path -or [string]$e.legacy_gate.file_id_128-ine[string]$gateTransition.post_file_id_128 -or [string]$e.legacy_gate.sha256-ine[string]$gateTransition.post_sha256 -or [int64]$e.legacy_gate.length-ne[int64]$gateTransition.post_length -or
           [string]$e.legacy_denial_stub.path-ine[string]$denialTransition.path -or [string]$e.legacy_denial_stub.file_id_128-ine[string]$denialTransition.post_file_id_128 -or [string]$e.legacy_denial_stub.sha256-ine[string]$denialTransition.post_sha256 -or [int64]$e.legacy_denial_stub.length-ne[int64]$denialTransition.post_length){Die "SYNAPSE_AUTHORITY_FRESH_FLOOR_TERMINAL_INVALID context=$Context evidence_names=$($eNames-join',') expected_names=$($eExpected-join',') counters=$($nonzeroEvidence-join',') broker_task_expected_sha=$((Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $Initial.broker_task)).ToUpperInvariant()) broker_task_actual_sha=$((Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $e.broker_task)).ToUpperInvariant()) gate_expected=$($gateTransition.post_file_id_128)/$($gateTransition.post_sha256)/$($gateTransition.post_length) gate_actual=$($e.legacy_gate.file_id_128)/$($e.legacy_gate.sha256)/$($e.legacy_gate.length) denial_expected=$($denialTransition.post_file_id_128)/$($denialTransition.post_sha256)/$($denialTransition.post_length) denial_actual=$($e.legacy_denial_stub.file_id_128)/$($e.legacy_denial_stub.sha256)/$($e.legacy_denial_stub.length)"}
    }elseif($mode-ceq'legacy_prior_unchanged'){
        $eNames=@(Get-SynapseObjectPropertyNames -Object $e);$eExpected=@('schema','legacy_task','task_runtime','legacy_task_unchanged','health_pid','tool_count','tool_surface_sha256','listener_count','compatibility','recovery_attempts')
        $eLegacyTaskJson=Get-SynapseCanonicalJson -Value $e.legacy_task
        $initialLegacyTaskJson=Get-SynapseCanonicalJson -Value (ConvertTo-SynapseLegacySnapshotPersistedDescriptor -Snapshot $Initial.legacy_task)
        if($eNames.Count-ne$eExpected.Count -or @($eNames|Where-Object{$eExpected-cnotcontains$_}).Count-ne0 -or [string]$e.schema-cne'synapse_authority_legacy_prior_unchanged/v2' -or -not[bool]$e.legacy_task_unchanged -or [int]$e.health_pid-lt1 -or [int]$e.tool_count-ne[int]$Initial.prior_generation.expected_tool_count -or [string]$e.tool_surface_sha256-ine[string]$Initial.prior_generation.expected_tool_surface_sha256 -or [int]$e.listener_count-ne1 -or $eLegacyTaskJson-cne$initialLegacyTaskJson){Die "SYNAPSE_AUTHORITY_LEGACY_PRIOR_TERMINAL_INVALID context=$Context names=$($eNames-join',') schema=$($e.schema) unchanged=$($e.legacy_task_unchanged) health_pid=$($e.health_pid) tool_count=$($e.tool_count)/$($Initial.prior_generation.expected_tool_count) tool_sha=$($e.tool_surface_sha256)/$($Initial.prior_generation.expected_tool_surface_sha256) listeners=$($e.listener_count) legacy_task_sha=$((Get-SynapseSha256Hex -Text $eLegacyTaskJson).ToUpperInvariant())/$((Get-SynapseSha256Hex -Text $initialLegacyTaskJson).ToUpperInvariant())"}
        if($null-eq$Allocation){Die "SYNAPSE_AUTHORITY_LEGACY_PRIOR_TERMINAL_ALLOCATION_MISSING context=$Context"}
        [void](Assert-SynapseAuthorityLegacyRollbackEvidence -Mode legacy_prior_unchanged -Evidence $e -Initial $Initial -Validated $Validated -Allocation $Allocation -Context $Context)
    }else{
        $eNames=@(Get-SynapseObjectPropertyNames -Object $e);$eExpected=@('schema','mode','attempt_index','launch_capability_sha256','intent','keeper_prepared','action_prepared','final_transfer_kind','final_transfer','compatibility','recovery_job','lineage','lineage_source','authority_resolution_policy','health_pid','tool_count','tool_surface_sha256','listener_count','legacy_task_unchanged','recovery_attempts')
        if($eNames.Count-ne$eExpected.Count -or @($eNames|Where-Object{$eExpected-cnotcontains$_}).Count-ne0 -or [string]$e.schema-cne'synapse_legacy_rollback_authority/v2' -or [string]$e.mode-cne'legacy_direct_recovery' -or [string]$e.final_transfer_kind-notin@('valid','torn') -or [int]$e.attempt_index-notin@(2,3,4) -or [int]$e.health_pid-lt1 -or [int]$e.tool_count-ne[int]$Initial.prior_generation.expected_tool_count -or [string]$e.tool_surface_sha256-ine[string]$Initial.prior_generation.expected_tool_surface_sha256 -or [int]$e.listener_count-ne1 -or -not[bool]$e.legacy_task_unchanged){Die "SYNAPSE_AUTHORITY_LEGACY_DIRECT_TERMINAL_INVALID context=$Context"}
        $attempts=if($null-ne$Validated){@($Validated.LegacyRescueLaunchAttempts|Where-Object{[int]$_.Plan.attempt_index-eq[int]$e.attempt_index})}else{@($Initial.legacy_rescue_launch_attempts|Where-Object{[int]$_.attempt_index-eq[int]$e.attempt_index}|ForEach-Object{[pscustomobject]@{Plan=$_}})}
        if($attempts.Count-ne1 -or [string]$e.launch_capability_sha256-ine[string]$attempts[0].Plan.launch_capability_sha256 -or [string]$e.recovery_job.name-cne[string]$attempts[0].Plan.recovery_job.name -or [string]$e.recovery_job.security_descriptor_sddl-cne[string]$attempts[0].Plan.recovery_job.security_descriptor_sddl){Die "SYNAPSE_AUTHORITY_LEGACY_DIRECT_ATTEMPT_CROSSBIND_INVALID context=$Context attempt=$($e.attempt_index)"}
        if($null-eq$Allocation){Die "SYNAPSE_AUTHORITY_LEGACY_DIRECT_TERMINAL_ALLOCATION_MISSING context=$Context"}
        [void](Assert-SynapseAuthorityLegacyRollbackEvidence -Mode legacy_direct_recovery -Evidence $e -Initial $Initial -Validated $Validated -Allocation $Allocation -Context $Context)
    }
    return (ConvertTo-SynapseCanonicalValue -Value $Detail)
}

function Complete-SynapseAuthorityRollbackTerminalCut {
    param(
        [Parameter(Mandatory=$true)]$Transaction,
        [Parameter(Mandatory=$true)]$Detail,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $root=[System.IO.Path]::GetFullPath([string]$Transaction.Root)
    $before=Read-SynapseDeploymentTransactionJournal -TransactionRoot $root -TransactionRootChain $Transaction.RootChain
    if([string]$before.State-cne'rolled_back' -and [string]$before.State-notin@('armed','candidate_ready')){Die "SYNAPSE_AUTHORITY_ROLLBACK_TERMINAL_PREFIX_INVALID context=$Context root=$root state=$($before.State)"}
    if([string]$before.State-ceq'rolled_back'){
        $actual=Assert-SynapseAuthorityRollbackTerminalDetail -Detail $before.Slots[-1].LexicalPayload.detail -Initial $before.Initial -Allocation $before.Allocation -Context "${Context}_existing"
        if((Get-SynapseCanonicalJson -Value $actual)-cne(Get-SynapseCanonicalJson -Value $Detail)){Die "SYNAPSE_AUTHORITY_ROLLBACK_TERMINAL_EXISTING_DRIFT context=$Context root=$root"}
        return [pscustomobject][ordered]@{Kind='valid_slot';Journal=$before;Detail=$actual;ValidPrefix=$before.Slots[-1];TerminalCut=$before.Slots[-1]}
    }
    $appendError=$null
    if($null-eq$before.TornTail){
        try{[void](Add-SynapseDeploymentTransactionJournalState -State rolled_back -Payload $Detail -Transaction $Transaction)}catch{$appendError=$_.Exception}
    }
    $after=Read-SynapseDeploymentTransactionJournal -TransactionRoot $root -TransactionRootChain $Transaction.RootChain
    if([string]$after.State-ceq'rolled_back'){
        $actual=Assert-SynapseAuthorityRollbackTerminalDetail -Detail $after.Slots[-1].LexicalPayload.detail -Initial $after.Initial -Allocation $after.Allocation -Context "${Context}_readback"
        if((Get-SynapseCanonicalJson -Value $actual)-cne(Get-SynapseCanonicalJson -Value $Detail)){Die "SYNAPSE_AUTHORITY_ROLLBACK_TERMINAL_READBACK_DRIFT context=$Context root=$root"}
        return [pscustomobject][ordered]@{Kind='valid_slot';Journal=$after;Detail=$actual;ValidPrefix=$after.Slots[-1];TerminalCut=$after.Slots[-1]}
    }
    if($null-eq$after.TornTail -or [string]$after.State-notin@('armed','candidate_ready') -or [int]$after.TornTail.Sequence-ne([int]$after.Sequence+1) -or [string]$after.TornTail.Leaf-cne('transaction-{0:D4}.json'-f[int]$after.TornTail.Sequence)){
        if($null-ne$appendError){throw $appendError}
        Die "SYNAPSE_AUTHORITY_ROLLBACK_TERMINAL_CUT_INVALID context=$Context root=$root state=$($after.State)"
    }
    return [pscustomobject][ordered]@{Kind='torn_tail_physical';Journal=$after;Detail=(ConvertTo-SynapseCanonicalValue -Value $Detail);ValidPrefix=$after.Slots[-1];TerminalCut=$after.TornTail;AppendError=$(if($null-ne$appendError){[string]$appendError.Message}else{'preexisting_torn_tail'})}
}

function New-SynapseAuthorityPhysicalRollbackPredecessor {
    param(
        [Parameter(Mandatory=$true)]$Entry,
        [Parameter(Mandatory=$true)]$TerminalResult,
        $Validated=$null
    )
    $journal=$TerminalResult.Journal
    if([string]$TerminalResult.Kind-cne'torn_tail_physical' -or $null-eq$journal.TornTail -or [string]$journal.State-notin@('armed','candidate_ready') -or [int]$journal.TornTail.Sequence-ne([int]$journal.Sequence+1)){Die "SYNAPSE_AUTHORITY_PHYSICAL_ROLLBACK_SOURCE_INVALID root=$($Entry.Path) state=$($journal.State)"}
    if($null-eq$Validated){$validated=Assert-SynapseAuthorityAdoptionInitialDescriptor -Initial $journal.Initial -TransactionRoot ([string]$Entry.Path) -Allocation $journal.Allocation -StructuralOnly}
    $detail=Assert-SynapseAuthorityRollbackTerminalDetail -Detail $TerminalResult.Detail -Initial $journal.Initial -Validated $Validated -Allocation $journal.Allocation -Context "authority_physical_predecessor_$($Entry.Path)"
    $cut=[pscustomobject][ordered]@{Kind='torn_tail_physical';Sequence=[int]$journal.TornTail.Sequence;State='torn';Leaf=[string]$journal.TornTail.Leaf;FileId128=([string]$journal.TornTail.FileId128).ToUpperInvariant();RawSha256=([string]$journal.TornTail.Sha256).ToUpperInvariant();ByteLength=[int64]$journal.TornTail.Length}
    return [pscustomobject][ordered]@{Entry=$Entry;Journal=$journal;TerminalSlot=$journal.Slots[-1];TerminalCut=$cut;Validated=$Validated;Mode=[string]$detail.mode;Detail=$detail;AuthorityEpoch=[int64]$journal.Initial.authority_epoch;AuthorityEvidenceSha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $detail.authority_evidence)).ToUpperInvariant();PhysicalRollback=$true}
}

function Assert-SynapseAuthorityRolledBackPredecessor {
    param(
        $Layout=$null,
        [Parameter(Mandatory=$true)]$Entry,
        [Parameter(Mandatory=$true)]$Journal,
        [string]$Bind='',
        [string]$DbPath='',
        [string]$Token='',
        [switch]$StructuralOnly
    )
    $terminalSlot=$null;$terminalCut=$null
    if([string]$Journal.State-ceq'rolled_back'){
        $terminalSlot=$Journal.Slots[-1]
        if($null-ne$Journal.TornTail){
            if([int]$Journal.TornTail.Sequence-ne([int]$terminalSlot.Sequence+1) -or [string]$Journal.TornTail.Leaf-cne('transaction-{0:D4}.json'-f[int]$Journal.TornTail.Sequence)){Die "SYNAPSE_AUTHORITY_PREDECESSOR_TORN_TAIL_SEQUENCE_INVALID root=$($Entry.Path) sequence=$($Journal.TornTail.Sequence) prefix=$($terminalSlot.Sequence)"}
            $terminalCut=[pscustomobject][ordered]@{Kind='torn_tail_physical';Sequence=[int]$Journal.TornTail.Sequence;State='torn';Leaf=[string]$Journal.TornTail.Leaf;FileId128=([string]$Journal.TornTail.FileId128).ToUpperInvariant();RawSha256=([string]$Journal.TornTail.Sha256).ToUpperInvariant();ByteLength=[int64]$Journal.TornTail.Length}
        }else{
            $terminalCut=[pscustomobject][ordered]@{Kind='valid_slot';Sequence=[int]$terminalSlot.Sequence;State='rolled_back';Leaf=[string]$terminalSlot.Leaf;FileId128=([string]$terminalSlot.FileId128).ToUpperInvariant();RawSha256=([string]$terminalSlot.RawSha256).ToUpperInvariant();ByteLength=[int64]$terminalSlot.ByteLength}
        }
    }elseif([string]$Journal.State-ceq'cleanup_ready' -and [string]$Journal.Latest.detail.terminal_state-ceq'rolled_back'){
        if($null-ne$Journal.TornTail){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_READY_TORN_SUFFIX_INVALID root=$($Entry.Path) sequence=$($Journal.TornTail.Sequence)"}
        $terminalMatches=@($Journal.Slots|Where-Object{[string]$_.State-ceq'rolled_back' -and [int]$_.Sequence-eq([int]$Journal.Sequence-1)})
        if($terminalMatches.Count-ne1){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_TAIL_INVALID root=$($Entry.Path) sequence=$($Journal.Sequence)"}
        $terminalSlot=$terminalMatches[0]
        $cleanupSlot=$Journal.Slots[-1]
        $terminalCut=[pscustomobject][ordered]@{Kind='valid_slot';Sequence=[int]$cleanupSlot.Sequence;State='cleanup_ready';Leaf=[string]$cleanupSlot.Leaf;FileId128=([string]$cleanupSlot.FileId128).ToUpperInvariant();RawSha256=([string]$cleanupSlot.RawSha256).ToUpperInvariant();ByteLength=[int64]$cleanupSlot.ByteLength}
    }else{Die "SYNAPSE_AUTHORITY_PREDECESSOR_STATE_INVALID root=$($Entry.Path) state=$($Journal.State)"}
    $validated=Assert-SynapseAuthorityAdoptionInitialDescriptor -Initial $Journal.Initial -TransactionRoot ([string]$Entry.Path) -Allocation $Journal.Allocation -StructuralOnly:$StructuralOnly
    # Persisted authority evidence must be validated from the lexical payload.
    # ConvertFrom-Json coerces ISO-8601 strings to DateTime and changes their
    # canonical representation even though the durable bytes are unchanged.
    $detail=Assert-SynapseAuthorityRollbackTerminalDetail -Detail $terminalSlot.LexicalPayload.detail -Initial $Journal.Initial -Validated $validated -Allocation $Journal.Allocation -Context "authority_predecessor_$($Entry.Path)"
    return [pscustomobject][ordered]@{Entry=$Entry;Journal=$Journal;TerminalSlot=$terminalSlot;TerminalCut=$terminalCut;Validated=$validated;Mode=[string]$detail.mode;Detail=$detail;AuthorityEpoch=[int64]$Journal.Initial.authority_epoch;AuthorityEvidenceSha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $detail.authority_evidence)).ToUpperInvariant()}
}

function New-SynapseAuthorityPredecessorReceipt {
    param([Parameter(Mandatory=$true)]$Predecessor)
    $journal=$Predecessor.Journal;$slot=$Predecessor.TerminalSlot
    $physicalRollback=($null-ne$Predecessor.PSObject.Properties['PhysicalRollback'] -and [bool]$Predecessor.PhysicalRollback)
    if($null-eq$slot -or $null-eq$Predecessor.TerminalCut -or
       (-not$physicalRollback -and [string]$slot.State-cne'rolled_back') -or
       ($physicalRollback -and ([string]$slot.State-notin@('armed','candidate_ready') -or [string]$Predecessor.TerminalCut.Kind-cne'torn_tail_physical'))){Die "SYNAPSE_AUTHORITY_PREDECESSOR_RECEIPT_SOURCE_INVALID root=$($journal.Root) state=$($journal.State) physical=$physicalRollback"}
    $actualRootFileId=([string]$journal.RootChain[-1].file_id_128).ToUpperInvariant()
    if ([string]$journal.Initial.transaction_root_file_id_128 -ine $actualRootFileId -or
        [string]$Predecessor.Entry.FileId128 -ine $actualRootFileId) {
        Die "SYNAPSE_AUTHORITY_PREDECESSOR_ROOT_ID_DRIFT root=$($journal.Root) initial=$($journal.Initial.transaction_root_file_id_128) entry=$($Predecessor.Entry.FileId128) actual=$actualRootFileId"
    }
    $cut=[ordered]@{kind='valid_slot';sequence=[int]$slot.Sequence;state=[string]$slot.State;leaf=[string]$slot.Leaf;file_id_128=([string]$slot.FileId128).ToUpperInvariant();sha256=([string]$slot.RawSha256).ToUpperInvariant();length=[int64]$slot.ByteLength}
    $physicalCut=$Predecessor.TerminalCut
    $physicalState=Get-SynapsePhysicalRelativeState -ParentPath ([string]$journal.Root) -ParentChain $journal.RootChain -Leaf ([string]$physicalCut.Leaf)
    if(-not (Test-SynapsePhysicalStateExact -State $physicalState -ExpectedExists $true -ExpectedFileId128 ([string]$physicalCut.FileId128) -ExpectedSha256 ([string]$physicalCut.RawSha256) -ExpectedLength ([int64]$physicalCut.ByteLength))){Die "SYNAPSE_AUTHORITY_PREDECESSOR_TERMINAL_CUT_DRIFT root=$($journal.Root) leaf=$($physicalCut.Leaf)"}
    $terminal=[ordered]@{kind=[string]$physicalCut.Kind;sequence=[int]$physicalCut.Sequence;state=[string]$physicalCut.State;leaf=[string]$physicalCut.Leaf;file_id_128=([string]$physicalCut.FileId128).ToUpperInvariant();sha256=([string]$physicalCut.RawSha256).ToUpperInvariant();length=[int64]$physicalCut.ByteLength}
    return [ordered]@{schema='synapse_authority_predecessor_receipt/v1';journal=[ordered]@{transaction_root=[System.IO.Path]::GetFullPath([string]$journal.Root);transaction_root_file_id_128=$actualRootFileId;initial_static_transaction_sha256=([string]$journal.Initial.static_transaction_sha256).ToUpperInvariant();valid_prefix=$cut;terminal_cut=$terminal};terminal_mode=[string]$Predecessor.Mode;authority_evidence_sha256=([string]$Predecessor.AuthorityEvidenceSha256).ToUpperInvariant();authority_descriptor=(ConvertTo-SynapseCanonicalValue -Value $Predecessor.Detail.authority_evidence);authority_epoch=[int64]$Predecessor.AuthorityEpoch}
}

function Assert-SynapseAuthorityPredecessorReceiptDescriptor {
    param([Parameter(Mandatory=$true)]$Receipt,[Parameter(Mandatory=$true)][string]$Context)
    $names=@(Get-SynapseObjectPropertyNames -Object $Receipt);$expected=@('schema','journal','terminal_mode','authority_evidence_sha256','authority_descriptor','authority_epoch')
    $journalNames=@(Get-SynapseObjectPropertyNames -Object $Receipt.journal);$journalExpected=@('transaction_root','transaction_root_file_id_128','initial_static_transaction_sha256','valid_prefix','terminal_cut')
    if($names.Count-ne$expected.Count -or @($names|Where-Object{$expected-cnotcontains$_}).Count-ne0 -or $journalNames.Count-ne$journalExpected.Count -or @($journalNames|Where-Object{$journalExpected-cnotcontains$_}).Count-ne0 -or [string]$Receipt.schema-cne'synapse_authority_predecessor_receipt/v1' -or [string]$Receipt.terminal_mode-notin@('legacy_prior_unchanged','legacy_direct_recovery','fresh_monotonic_floor') -or [string]$Receipt.authority_evidence_sha256-notmatch'^[0-9A-Fa-f]{64}$' -or [int64]$Receipt.authority_epoch-lt1 -or [string]$Receipt.journal.transaction_root_file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or [string]$Receipt.journal.initial_static_transaction_sha256-notmatch'^[0-9A-Fa-f]{64}$'){Die "SYNAPSE_AUTHORITY_PREDECESSOR_RECEIPT_INVALID context=$Context"}
    $valid=$Receipt.journal.valid_prefix;$terminal=$Receipt.journal.terminal_cut;$cutExpected=@('kind','sequence','state','leaf','file_id_128','sha256','length')
    $validNames=@(Get-SynapseObjectPropertyNames -Object $valid)
    if($validNames.Count-ne$cutExpected.Count -or @($validNames|Where-Object{$cutExpected-cnotcontains$_}).Count-ne0 -or [string]$valid.kind-cne'valid_slot' -or [int]$valid.sequence-lt1 -or [int]$valid.sequence-gt$script:SynapseDeploymentJournalMaxSlots -or [string]$valid.state-notin@('armed','candidate_ready','rolled_back') -or [string]$valid.leaf-cne('transaction-{0:D4}.json'-f[int]$valid.sequence) -or [string]$valid.file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or [string]$valid.sha256-notmatch'^[0-9A-Fa-f]{64}$' -or [int64]$valid.length-lt1){Die "SYNAPSE_AUTHORITY_PREDECESSOR_RECEIPT_PREFIX_INVALID context=$Context"}
    $terminalNames=@(Get-SynapseObjectPropertyNames -Object $terminal)
    $terminalValid=$terminalNames.Count-eq$cutExpected.Count -and @($terminalNames|Where-Object{$cutExpected-cnotcontains$_}).Count-eq0 -and [int]$terminal.sequence-ge[int]$valid.sequence -and [int]$terminal.sequence-le$script:SynapseDeploymentJournalMaxSlots -and [string]$terminal.leaf-ceq('transaction-{0:D4}.json'-f[int]$terminal.sequence) -and [string]$terminal.file_id_128-match'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -and [string]$terminal.sha256-match'^[0-9A-Fa-f]{64}$' -and [int64]$terminal.length-ge1
    $terminalValid=$terminalValid -and (([string]$terminal.kind-ceq'valid_slot' -and [string]$valid.state-ceq'rolled_back' -and (([int]$terminal.sequence-eq[int]$valid.sequence -and [string]$terminal.state-ceq'rolled_back') -or ([int]$terminal.sequence-eq([int]$valid.sequence+1) -and [string]$terminal.state-ceq'cleanup_ready'))) -or ([string]$terminal.kind-ceq'torn_tail_physical' -and [int]$terminal.sequence-eq([int]$valid.sequence+1) -and [string]$terminal.state-ceq'torn'))
    if(-not$terminalValid){Die "SYNAPSE_AUTHORITY_PREDECESSOR_RECEIPT_TERMINAL_CUT_INVALID context=$Context"}
    $expectedDescriptorSchema=switch([string]$Receipt.terminal_mode){
        'fresh_monotonic_floor'{'synapse_authority_fresh_monotonic_floor/v1'}
        'legacy_prior_unchanged'{'synapse_authority_legacy_prior_unchanged/v2'}
        'legacy_direct_recovery'{'synapse_legacy_rollback_authority/v2'}
    }
    if([string]$Receipt.authority_descriptor.schema-cne$expectedDescriptorSchema -or
       ([string]$Receipt.terminal_mode-ceq'legacy_direct_recovery' -and [string]$Receipt.authority_descriptor.mode-cne'legacy_direct_recovery') -or
       (Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $Receipt.authority_descriptor))-ine[string]$Receipt.authority_evidence_sha256){Die "SYNAPSE_AUTHORITY_PREDECESSOR_RECEIPT_VALID_TERMINAL_DRIFT context=$Context"}
    return (ConvertTo-SynapseCanonicalValue -Value $Receipt)
}

function Assert-SynapseAuthorityPredecessorSuccessorPair {
    param(
        [Parameter(Mandatory=$true)]$PredecessorRecord,
        [Parameter(Mandatory=$true)]$SuccessorInitial,
        [Parameter(Mandatory=$true)][string]$SuccessorRoot,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $receipt=Assert-SynapseAuthorityPredecessorReceiptDescriptor -Receipt $PredecessorRecord.PredecessorReceipt -Context "${Context}_predecessor"
    $declared=Assert-SynapseAuthorityPredecessorReceiptDescriptor -Receipt $SuccessorInitial.predecessor_authority_receipt -Context "${Context}_successor"
    if((Get-SynapseCanonicalJson -Value $declared)-cne(Get-SynapseCanonicalJson -Value $receipt)){Die "SYNAPSE_AUTHORITY_SUCCESSOR_PREDECESSOR_CROSSBIND_INVALID context=$Context predecessor=$($PredecessorRecord.Root) successor=$SuccessorRoot"}
    $predecessorRoot=Get-SynapseNormalizedDirectoryPath -Path ([string]$receipt.journal.transaction_root);$successorPath=Get-SynapseNormalizedDirectoryPath -Path $SuccessorRoot
    $expectedPrior=if([string]$receipt.terminal_mode-ceq'fresh_monotonic_floor'){'absent'}else{'legacy'}
    if($predecessorRoot-ieq$successorPath -or (Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $predecessorRoot))-ine(Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $successorPath)) -or [string]$receipt.journal.transaction_root_file_id_128-ine[string]$PredecessorRecord.RootFileId128 -or [string]$SuccessorInitial.prior_authority-cne$expectedPrior -or [int64]$SuccessorInitial.authority_epoch-ne([int64]$receipt.authority_epoch+1)){Die "SYNAPSE_AUTHORITY_SUCCESSOR_PREDECESSOR_TOPOLOGY_INVALID context=$Context predecessor=$predecessorRoot successor=$successorPath mode=$($receipt.terminal_mode) prior=$($SuccessorInitial.prior_authority) epoch=$($SuccessorInitial.authority_epoch)"}
    return [pscustomobject][ordered]@{Receipt=$receipt;PriorAuthority=$expectedPrior;PredecessorRoot=$predecessorRoot;SuccessorRoot=$successorPath}
}

function New-SynapseAuthorityCommittedSuccessorPredecessorCleanupAuthorityFromReceipt {
    param(
        [Parameter(Mandatory=$true)]$PredecessorReceipt,
        [Parameter(Mandatory=$true)]$SuccessorRecord,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $receipt=Assert-SynapseAuthorityPredecessorReceiptDescriptor -Receipt $PredecessorReceipt -Context "${Context}_receipt"
    $journal=$SuccessorRecord.Journal
    if($null-eq$journal -or [string]$journal.State-cne'commit_decided' -or $null-ne$journal.TornTail){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_SUCCESSOR_STATE_INVALID context=$Context root=$($SuccessorRecord.Root) state=$($journal.State)"}
    $successorRoot=Get-SynapseNormalizedDirectoryPath -Path ([string]$SuccessorRecord.Root);$predecessorRoot=Get-SynapseNormalizedDirectoryPath -Path ([string]$receipt.journal.transaction_root)
    $expectedPrior=if([string]$receipt.terminal_mode-ceq'fresh_monotonic_floor'){'absent'}else{'legacy'}
    if($successorRoot-ieq$predecessorRoot -or (Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $successorRoot))-ine(Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $predecessorRoot)) -or (Get-SynapseCanonicalJson -Value $journal.Initial.predecessor_authority_receipt)-cne(Get-SynapseCanonicalJson -Value $receipt) -or [int64]$journal.Initial.authority_epoch-ne([int64]$receipt.authority_epoch+1) -or [string]$journal.Initial.prior_authority-cne$expectedPrior){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_SUCCESSOR_TOPOLOGY_INVALID context=$Context predecessor=$predecessorRoot successor=$successorRoot"}
    $commit=@($journal.Slots|Where-Object State -CEQ 'commit_decided')
    if($commit.Count-ne1 -or [int]$commit[0].Sequence-ne[int]$journal.Sequence){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_COMMIT_SLOT_INVALID context=$Context root=$($SuccessorRecord.Root) count=$($commit.Count)"}
    $receiptSha=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $receipt)).ToUpperInvariant();$detail=$commit[0].Payload.detail
    if(-not[bool]$detail.predecessor_superseded -or [string]$detail.predecessor_receipt_sha256-ine$receiptSha){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_COMMIT_CROSSBIND_INVALID context=$Context root=$($SuccessorRecord.Root)"}
    $successorRootFileId=([string]$journal.RootChain[-1].file_id_128).ToUpperInvariant()
    if([string]$SuccessorRecord.RootFileId128-ine$successorRootFileId -or [string]$journal.Initial.transaction_root_file_id_128-ine$successorRootFileId){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_SUCCESSOR_ROOT_DRIFT context=$Context root=$($SuccessorRecord.Root)"}
    return [ordered]@{
        schema='synapse_authority_committed_successor_predecessor_cleanup/v1'
        predecessor_receipt=(ConvertTo-SynapseCanonicalValue -Value $receipt)
        predecessor_receipt_sha256=$receiptSha
        successor_root=[System.IO.Path]::GetFullPath([string]$journal.Root)
        successor_root_file_id_128=$successorRootFileId
        successor_initial_static_transaction_sha256=([string]$journal.Initial.static_transaction_sha256).ToUpperInvariant()
        commit_slot=[ordered]@{sequence=[int]$commit[0].Sequence;state='commit_decided';leaf=[string]$commit[0].Leaf;file_id_128=([string]$commit[0].FileId128).ToUpperInvariant();sha256=([string]$commit[0].RawSha256).ToUpperInvariant();length=[int64]$commit[0].ByteLength}
        commit_detail_sha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $detail)).ToUpperInvariant()
    }
}

function New-SynapseAuthorityCommittedSuccessorPredecessorCleanupAuthority {
    param(
        [Parameter(Mandatory=$true)]$PredecessorRecord,
        [Parameter(Mandatory=$true)]$SuccessorRecord,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $pair=Assert-SynapseAuthorityPredecessorSuccessorPair -PredecessorRecord $PredecessorRecord -SuccessorInitial $SuccessorRecord.Journal.Initial -SuccessorRoot ([string]$SuccessorRecord.Root) -Context "${Context}_pair"
    return (New-SynapseAuthorityCommittedSuccessorPredecessorCleanupAuthorityFromReceipt -PredecessorReceipt $pair.Receipt -SuccessorRecord $SuccessorRecord -Context $Context)
}

function Assert-SynapseAuthorityCommittedSuccessorPredecessorCleanupAuthority {
    param(
        [Parameter(Mandatory=$true)]$Authority,
        $ExpectedPredecessorReceipt=$null,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $names=@(if($Authority-is[System.Collections.IDictionary]){$Authority.Keys}else{$Authority.PSObject.Properties.Name});$expected=@('schema','predecessor_receipt','predecessor_receipt_sha256','successor_root','successor_root_file_id_128','successor_initial_static_transaction_sha256','commit_slot','commit_detail_sha256')
    $slot=$Authority.commit_slot;$slotNames=@(if($slot-is[System.Collections.IDictionary]){$slot.Keys}else{$slot.PSObject.Properties.Name});$slotExpected=@('sequence','state','leaf','file_id_128','sha256','length')
    if($names.Count-ne$expected.Count -or @($names|Where-Object{$expected-cnotcontains$_}).Count-ne0 -or [string]$Authority.schema-cne'synapse_authority_committed_successor_predecessor_cleanup/v1' -or [string]$Authority.predecessor_receipt_sha256-notmatch'^[0-9A-Fa-f]{64}$' -or [string]$Authority.successor_root_file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or [string]$Authority.successor_initial_static_transaction_sha256-notmatch'^[0-9A-Fa-f]{64}$' -or [string]$Authority.commit_detail_sha256-notmatch'^[0-9A-Fa-f]{64}$' -or $slotNames.Count-ne$slotExpected.Count -or @($slotNames|Where-Object{$slotExpected-cnotcontains$_}).Count-ne0 -or [int]$slot.sequence-lt2 -or [int]$slot.sequence-gt$script:SynapseDeploymentJournalMaxSlots -or [string]$slot.state-cne'commit_decided' -or [string]$slot.leaf-cne('transaction-{0:D4}.json'-f[int]$slot.sequence) -or [string]$slot.file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or [string]$slot.sha256-notmatch'^[0-9A-Fa-f]{64}$' -or [int64]$slot.length-lt1){Die "SYNAPSE_AUTHORITY_COMMITTED_SUCCESSOR_CLEANUP_AUTHORITY_INVALID context=$Context"}
    $receipt=Assert-SynapseAuthorityPredecessorReceiptDescriptor -Receipt $Authority.predecessor_receipt -Context "${Context}_receipt"
    if([string]$Authority.predecessor_receipt_sha256-ine(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $receipt)) -or ($null-ne$ExpectedPredecessorReceipt -and (Get-SynapseCanonicalJson -Value $receipt)-cne(Get-SynapseCanonicalJson -Value $ExpectedPredecessorReceipt))){Die "SYNAPSE_AUTHORITY_COMMITTED_SUCCESSOR_CLEANUP_RECEIPT_DRIFT context=$Context"}
    $successorRoot=Get-SynapseNormalizedDirectoryPath -Path ([string]$Authority.successor_root);$journal=Read-SynapseDeploymentTransactionJournal -TransactionRoot $successorRoot
    if($null-eq$journal -or [string]$journal.State-cne'commit_decided' -or $null-ne$journal.TornTail -or [string]$journal.RootChain[-1].file_id_128-ine[string]$Authority.successor_root_file_id_128 -or [string]$journal.Initial.static_transaction_sha256-ine[string]$Authority.successor_initial_static_transaction_sha256 -or (Get-SynapseNormalizedDirectoryPath -Path ([string]$receipt.journal.transaction_root))-ieq$successorRoot -or (Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent ([string]$receipt.journal.transaction_root)))-ine(Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $successorRoot))){Die "SYNAPSE_AUTHORITY_COMMITTED_SUCCESSOR_CLEANUP_SUCCESSOR_DRIFT context=$Context root=$successorRoot"}
    $actual=@($journal.Slots|Where-Object Sequence -EQ ([int]$slot.sequence))
    if($actual.Count-ne1 -or [string]$actual[0].State-cne'commit_decided' -or [string]$actual[0].Leaf-cne[string]$slot.leaf -or [string]$actual[0].FileId128-ine[string]$slot.file_id_128 -or [string]$actual[0].RawSha256-ine[string]$slot.sha256 -or [int64]$actual[0].ByteLength-ne[int64]$slot.length -or [string]$Authority.commit_detail_sha256-ine(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $actual[0].Payload.detail)) -or (Get-SynapseCanonicalJson -Value $journal.Initial.predecessor_authority_receipt)-cne(Get-SynapseCanonicalJson -Value $receipt) -or -not[bool]$actual[0].Payload.detail.predecessor_superseded -or [string]$actual[0].Payload.detail.predecessor_receipt_sha256-ine[string]$Authority.predecessor_receipt_sha256){Die "SYNAPSE_AUTHORITY_COMMITTED_SUCCESSOR_CLEANUP_COMMIT_DRIFT context=$Context root=$successorRoot"}
    return [pscustomobject][ordered]@{Authority=(ConvertTo-SynapseCanonicalValue -Value $Authority);Receipt=$receipt;SuccessorJournal=$journal;CommitSlot=$actual[0]}
}

function Get-SynapseAuthorityPredecessorCleanupEntryRoster {
    param([Parameter(Mandatory=$true)]$PredecessorRecord,[Parameter(Mandatory=$true)][string]$Context)
    $journal=$PredecessorRecord.Journal
    if($null-eq$journal -or $null-eq$journal.Allocation){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_ALLOCATION_MISSING context=$Context root=$($PredecessorRecord.Root)"}
    $root=Get-SynapseNormalizedDirectoryPath -Path ([string]$PredecessorRecord.Root);$chain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $root)
    if([string]$chain[-1].file_id_128-ine[string]$PredecessorRecord.RootFileId128){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_ROOT_DRIFT context=$Context root=$root"}
    $allocation=$journal.Allocation;$entries=@(Get-SynapsePhysicalDirectoryEntriesBounded -Path $root -Chain $chain -MaximumEntries $script:SynapseDeploymentArtifactMaxDirectEntries -Context $Context)
    if($entries.Count-ne[int]$allocation.FrozenDetail.direct_entry_count){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_ENTRY_COUNT_DRIFT context=$Context root=$root expected=$($allocation.FrozenDetail.direct_entry_count) actual=$($entries.Count)"}
    $roster=@()
    foreach($entry in @($entries|Sort-Object Name)){
        if(([uint32]$entry.Attributes-band[uint32][System.IO.FileAttributes]::ReparsePoint)){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_REPARSE_POINT context=$Context path=$($entry.Path)"}
        if([string]$entry.Name-ceq$script:SynapseDeploymentAllocationMarkerFileName){
            $state=Get-SynapsePhysicalRelativeState -ParentPath $root -ParentChain $chain -Leaf ([string]$entry.Name)
            if([bool]$entry.IsDirectory -or [string]$state.FileId128-ine[string]$allocation.State.FileId128 -or [string]$state.Sha256-ine[string]$allocation.RawSha256 -or [int64]$state.Length-ne[int64]$allocation.ByteLength){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_ALLOCATION_DRIFT context=$Context root=$root"}
            $roster+=,[ordered]@{leaf=[string]$entry.Name;is_directory=$false;file_id_128=([string]$state.FileId128).ToUpperInvariant();sha256=([string]$state.Sha256).ToUpperInvariant();length=[int64]$state.Length}
            continue
        }
        if(-not$allocation.Artifacts.ContainsKey([string]$entry.Name)){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_UNKNOWN_ENTRY context=$Context root=$root leaf=$($entry.Name)"}
        $artifact=$allocation.Artifacts[[string]$entry.Name];$directory=([string]$artifact.kind-ceq'directory' -or ([string]$artifact.kind-ceq'transition_slot' -and [bool]$artifact.transition_directory))
        if([bool]$entry.IsDirectory-ne$directory){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_ENTRY_TYPE_DRIFT context=$Context path=$($entry.Path)"}
        $state=Get-SynapsePhysicalRelativeState -ParentPath $root -ParentChain $chain -Leaf ([string]$entry.Name) -Directory:$directory
        $allowedIds=if([string]$artifact.kind-ceq'transition_slot'){@($artifact.allowed_file_ids_128)}else{@([string]$artifact.file_id_128)}
        if($allowedIds-inotcontains[string]$state.FileId128){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_ENTRY_ID_DRIFT context=$Context path=$($entry.Path) file_id_128=$($state.FileId128)"}
        if($directory){
            $children=@(Get-SynapsePhysicalDirectoryEntriesBounded -Path ([string]$entry.Path) -Chain (Get-SynapsePhysicalDirectoryChainDescriptor -Path ([string]$entry.Path)) -MaximumEntries 0 -Context "${Context}_empty_$($entry.Name)")
            if($children.Count-ne0){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_DIRECTORY_NOT_EMPTY context=$Context path=$($entry.Path)"}
            $roster+=,[ordered]@{leaf=[string]$entry.Name;is_directory=$true;file_id_128=([string]$state.FileId128).ToUpperInvariant();sha256='';length=-1L}
            continue
        }
        $contentValid=switch([string]$artifact.kind){
            'file'{[string]$state.Sha256-ieq[string]$artifact.sealed_sha256 -and [int64]$state.Length-eq[int64]$artifact.sealed_length}
            'transition_slot'{[string]$state.Sha256-ieq[string]$artifact.expected_sha256 -and [int64]$state.Length-eq[int64]$artifact.expected_length}
            'journal_slot'{[int64]$state.Length-ge0 -and [int64]$state.Length-le[int64]$artifact.maximum_length}
            'progress_slot'{[int64]$state.Length-ge0 -and [int64]$state.Length-le[int64]$artifact.maximum_length}
            default{$false}
        }
        if(-not$contentValid){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_ENTRY_CONTENT_DRIFT context=$Context path=$($entry.Path) kind=$($artifact.kind) sha256=$($state.Sha256) length=$($state.Length)"}
        $roster+=,[ordered]@{leaf=[string]$entry.Name;is_directory=$false;file_id_128=([string]$state.FileId128).ToUpperInvariant();sha256=([string]$state.Sha256).ToUpperInvariant();length=[int64]$state.Length}
    }
    return @($roster)
}

function New-SynapseAuthorityPredecessorCleanupMarkerText {
    param([Parameter(Mandatory=$true)][ValidateRange(1,3)][int]$AttemptIndex,[AllowEmptyString()][string]$PreviousMarkerSha256,[Parameter(Mandatory=$true)]$CleanupAuthority,[Parameter(Mandatory=$true)][string]$PredecessorRoot,[Parameter(Mandatory=$true)][string]$PredecessorRootFileId128,[Parameter(Mandatory=$true)]$Entries)
    $body=[ordered]@{schema='synapse_authority_predecessor_cleanup_marker/v1';state='cleanup_ready';attempt_index=$AttemptIndex;previous_marker_sha256=$(if($PreviousMarkerSha256){$PreviousMarkerSha256.ToUpperInvariant()}else{''});cleanup_authority=(ConvertTo-SynapseCanonicalValue -Value $CleanupAuthority);predecessor_root=[System.IO.Path]::GetFullPath($PredecessorRoot);predecessor_root_file_id_128=$PredecessorRootFileId128.ToUpperInvariant();entries=@($Entries|ForEach-Object{ConvertTo-SynapseCanonicalValue -Value $_});trailer='SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_V1'}
    $self=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $body)).ToUpperInvariant();$envelope=[ordered]@{};foreach($key in $body.Keys){$envelope[$key]=$body[$key]};$envelope.self_sha256=$self
    $text=(Get-SynapseCanonicalJson -Value $envelope)+"`n";return [pscustomobject][ordered]@{Text=$text;Sha256=(Get-SynapseSha256Hex -Text $text).ToUpperInvariant();Length=[System.Text.UTF8Encoding]::new($false,$true).GetByteCount($text);Payload=$envelope}
}

function Read-SynapseAuthorityPredecessorCleanupMarkerSlot {
    param([Parameter(Mandatory=$true)]$SuccessorRecord,[Parameter(Mandatory=$true)]$Descriptor,[Parameter(Mandatory=$true)][ValidateRange(1,3)][int]$AttemptIndex,[Parameter(Mandatory=$true)][string]$Context)
    $root=Get-SynapseNormalizedDirectoryPath -Path ([string]$SuccessorRecord.Root);$chain=@($SuccessorRecord.Journal.RootChain)
    $proof=Assert-SynapseDeploymentProgressSlotDescriptor -Descriptor $Descriptor -TransactionRoot $root -Allocation $SuccessorRecord.Journal.Allocation -ExpectedLeaf ('predecessor-cleanup-{0:D2}.json'-f$AttemptIndex) -ExpectedPurpose ('authority_predecessor_cleanup_{0:D2}'-f$AttemptIndex) -Context $Context
    if([int64]$proof.State.Length-eq0){return [pscustomobject][ordered]@{Kind='empty';AttemptIndex=$AttemptIndex;Descriptor=$proof.Descriptor;FileId128=[string]$proof.State.FileId128;Sha256=[string]$proof.State.Sha256;Length=0L;Payload=$null}}
    $raw=Read-SynapsePhysicalRelativeUtf8Text -ParentPath $root -ParentChain $chain -Leaf ([string]$proof.Descriptor.leaf) -ExpectedFileId128 ([string]$proof.Descriptor.file_id_128) -MaxBytes ([int]$proof.Descriptor.maximum_length)
    try{
        # Preserve timestamp-looking JSON strings exactly. ConvertFrom-Json
        # coerces ISO-8601 strings nested in the predecessor receipt to
        # DateTime and rewrites fractional seconds on reserialization, which
        # falsely classifies a byte-perfect write-once marker as torn.
        $value=ConvertFrom-SynapseJsonPreservingStrings -Json ([string]$raw.Content) -MaximumJsonLength ([int]$proof.Descriptor.maximum_length)
        $names=@(if($value-is[System.Collections.IDictionary]){$value.Keys}else{$value.PSObject.Properties.Name});$expected=@('schema','state','attempt_index','previous_marker_sha256','cleanup_authority','predecessor_root','predecessor_root_file_id_128','entries','trailer','self_sha256')
        $body=[ordered]@{schema=[string]$value.schema;state=[string]$value.state;attempt_index=[int]$value.attempt_index;previous_marker_sha256=[string]$value.previous_marker_sha256;cleanup_authority=(ConvertTo-SynapseCanonicalValue -Value $value.cleanup_authority);predecessor_root=[string]$value.predecessor_root;predecessor_root_file_id_128=[string]$value.predecessor_root_file_id_128;entries=@($value.entries|ForEach-Object{ConvertTo-SynapseCanonicalValue -Value $_});trailer=[string]$value.trailer}
        $self=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $body)).ToUpperInvariant();$canonical=[ordered]@{};foreach($key in $body.Keys){$canonical[$key]=$body[$key]};$canonical.self_sha256=$self
        $canonicalText=(Get-SynapseCanonicalJson -Value $canonical)+"`n"
        $invalid=@()
        if($names.Count-ne$expected.Count -or @($names|Where-Object{$expected-cnotcontains$_}).Count-ne0){$invalid+='shape'}
        if([string]$value.schema-cne'synapse_authority_predecessor_cleanup_marker/v1'){$invalid+='schema'}
        if([string]$value.state-cne'cleanup_ready'){$invalid+='state'}
        if([int]$value.attempt_index-ne$AttemptIndex){$invalid+='attempt'}
        if([string]$value.previous_marker_sha256-notmatch'^(|[0-9A-Fa-f]{64})$'){$invalid+='previous_sha'}
        if([string]$value.predecessor_root_file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'){$invalid+='root_id'}
        if([string]$value.trailer-cne'SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_V1'){$invalid+='trailer'}
        if([string]$value.self_sha256-ine$self){$invalid+="self_sha(expected=$self actual=$($value.self_sha256))"}
        if($canonicalText-cne[string]$raw.Content){$invalid+="canonical_bytes(expected_length=$([Text.Encoding]::UTF8.GetByteCount($canonicalText)) actual_length=$($raw.Length))"}
        if($invalid.Count-ne0){throw "marker canonical identity invalid reasons=$($invalid-join',')"}
        return [pscustomobject][ordered]@{Kind='valid';AttemptIndex=$AttemptIndex;Descriptor=$proof.Descriptor;FileId128=[string]$proof.State.FileId128;Sha256=([string]$raw.Sha256).ToUpperInvariant();Length=[int64]$raw.Length;Payload=(ConvertTo-SynapseCanonicalValue -Value $value)}
    }catch{
        Warn "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_MARKER_CLASSIFIED_TORN context=$Context attempt=$AttemptIndex file_id_128=$($proof.State.FileId128) sha256=$($raw.Sha256) length=$($raw.Length) error=$($_.Exception.Message)"
        return [pscustomobject][ordered]@{Kind='torn';AttemptIndex=$AttemptIndex;Descriptor=$proof.Descriptor;FileId128=[string]$proof.State.FileId128;Sha256=([string]$raw.Sha256).ToUpperInvariant();Length=[int64]$raw.Length;Payload=$null;Error=$_.Exception.Message}
    }
}

function Get-SynapseAuthorityCommittedPredecessorCleanupMarkerSet {
    param([Parameter(Mandatory=$true)]$SuccessorRecord,[Parameter(Mandatory=$true)]$CleanupAuthority,$ExpectedEntries=$null,[Parameter(Mandatory=$true)][string]$Context)
    $validated=Assert-SynapseAuthorityAdoptionInitialDescriptor -Initial $SuccessorRecord.Journal.Initial -TransactionRoot ([string]$SuccessorRecord.Root) -Allocation $SuccessorRecord.Journal.Allocation -HistoricalMutableGeneration -StructuralOnly
    $states=@();foreach($index in 1..3){$states+=,((Read-SynapseAuthorityPredecessorCleanupMarkerSlot -SuccessorRecord $SuccessorRecord -Descriptor $validated.PredecessorCleanupProgressSlots[$index-1] -AttemptIndex $index -Context "${Context}_$index"))}
    $valid=@($states|Where-Object Kind -CEQ 'valid')
    if($valid.Count-gt1){
        # Historical readers used ConvertFrom-Json, which coerced a nested
        # timestamp string and falsely reported a successfully written marker
        # as torn. The producer then consumed the next write-once slot. Admit
        # that history only when every occupied slot is itself canonical, the
        # raw-SHA chain is continuous, and all cleanup authority/roster/root
        # bytes are identical. The final marker is then the unique effective
        # REDO decision; any divergence remains ambiguous and fail-closed.
        $previous='';$reference=$null
        foreach($state in $states){
            if([string]$state.Kind-cne'valid' -or [string]$state.Payload.previous_marker_sha256-ine$previous){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_MARKER_AMBIGUOUS context=$Context successor=$($SuccessorRecord.Root) valid=$($valid.Count)"}
            $projection=Get-SynapseCanonicalJson -Value ([ordered]@{cleanup_authority=(ConvertTo-SynapseCanonicalValue -Value $state.Payload.cleanup_authority);predecessor_root=[string]$state.Payload.predecessor_root;predecessor_root_file_id_128=[string]$state.Payload.predecessor_root_file_id_128;entries=@($state.Payload.entries|ForEach-Object{ConvertTo-SynapseCanonicalValue -Value $_})})
            if($null-eq$reference){$reference=$projection}elseif($projection-cne$reference){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_MARKER_AMBIGUOUS context=$Context successor=$($SuccessorRecord.Root) valid=$($valid.Count) reason=projection_drift"}
            $previous=[string]$state.Sha256
        }
        if((Get-SynapseCanonicalJson -Value $valid[-1].Payload.cleanup_authority)-cne(Get-SynapseCanonicalJson -Value $CleanupAuthority) -or ($null-ne$ExpectedEntries -and (Get-SynapseCanonicalJson -Value @($valid[-1].Payload.entries))-cne(Get-SynapseCanonicalJson -Value @($ExpectedEntries)))){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_MARKER_AMBIGUOUS context=$Context successor=$($SuccessorRecord.Root) valid=$($valid.Count) reason=expected_projection_drift"}
        Warn "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_MARKER_READER_RETRY_MIGRATION context=$Context successor=$($SuccessorRecord.Root) valid_count=$($valid.Count) effective_attempt=$($valid[-1].AttemptIndex)"
        return [pscustomobject][ordered]@{States=$states;Valid=$valid[-1];Next=$null;PreviousSha256=$previous;Exhausted=$false}
    }
    $seenEmpty=$false;$seenValid=$false;$previousSha=''
    foreach($state in $states){
        if([string]$state.Kind-ceq'torn'){if($seenEmpty-or$seenValid){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_MARKER_ORDER_INVALID context=$Context attempt=$($state.AttemptIndex) kind=torn"};$previousSha=[string]$state.Sha256;continue}
        if([string]$state.Kind-ceq'valid'){
            if($seenEmpty-or$seenValid -or [string]$state.Payload.previous_marker_sha256-ine$previousSha -or (Get-SynapseCanonicalJson -Value $state.Payload.cleanup_authority)-cne(Get-SynapseCanonicalJson -Value $CleanupAuthority)){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_MARKER_VALID_DRIFT context=$Context attempt=$($state.AttemptIndex)"}
            $receipt=$CleanupAuthority.predecessor_receipt
            if((Get-SynapseNormalizedDirectoryPath -Path ([string]$state.Payload.predecessor_root))-ine(Get-SynapseNormalizedDirectoryPath -Path ([string]$receipt.journal.transaction_root)) -or [string]$state.Payload.predecessor_root_file_id_128-ine[string]$receipt.journal.transaction_root_file_id_128){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_MARKER_ROOT_DRIFT context=$Context attempt=$($state.AttemptIndex)"}
            if($null-ne$ExpectedEntries -and (Get-SynapseCanonicalJson -Value @($state.Payload.entries))-cne(Get-SynapseCanonicalJson -Value @($ExpectedEntries))){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_MARKER_ROSTER_DRIFT context=$Context attempt=$($state.AttemptIndex)"}
            $seenValid=$true;continue
        }
        $seenEmpty=$true
    }
    return [pscustomobject][ordered]@{States=$states;Valid=$(if($valid.Count-eq1){$valid[0]}else{$null});Next=$(if($valid.Count-eq0){@($states|Where-Object Kind -CEQ 'empty'|Select-Object -First 1)}else{$null});PreviousSha256=$previousSha;Exhausted=($valid.Count-eq0 -and @($states|Where-Object Kind -CEQ 'empty').Count-eq0)}
}

function Ensure-SynapseAuthorityCommittedPredecessorCleanupMarker {
    param([Parameter(Mandatory=$true)]$SuccessorRecord,[Parameter(Mandatory=$true)]$CleanupAuthority,[Parameter(Mandatory=$true)]$Entries,[Parameter(Mandatory=$true)][string]$Context)
    while($true){
        $set=Get-SynapseAuthorityCommittedPredecessorCleanupMarkerSet -SuccessorRecord $SuccessorRecord -CleanupAuthority $CleanupAuthority -ExpectedEntries $Entries -Context "${Context}_scan"
        if($null-ne$set.Valid){return $set.Valid}
        if([bool]$set.Exhausted){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_MARKERS_EXHAUSTED context=$Context successor=$($SuccessorRecord.Root) remediation=preserve predecessor and successor; three write-once cleanup markers tore before deletion began"}
        $next=@($set.Next);if($next.Count-ne1){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_MARKER_NEXT_INVALID context=$Context successor=$($SuccessorRecord.Root)"};$next=$next[0]
        $marker=New-SynapseAuthorityPredecessorCleanupMarkerText -AttemptIndex ([int]$next.AttemptIndex) -PreviousMarkerSha256 ([string]$set.PreviousSha256) -CleanupAuthority $CleanupAuthority -PredecessorRoot ([string]$CleanupAuthority.predecessor_receipt.journal.transaction_root) -PredecessorRootFileId128 ([string]$CleanupAuthority.predecessor_receipt.journal.transaction_root_file_id_128) -Entries $Entries
        if([int64]$marker.Length-gt[int64]$next.Descriptor.maximum_length){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_MARKER_BOUND_EXCEEDED context=$Context length=$($marker.Length) max=$($next.Descriptor.maximum_length)"}
        $handle=$null;$activeArtifact=$null;$writeError=$null
        $active=$script:SynapseDeploymentAllocationContext
        if($null-ne$active -and (Get-SynapseNormalizedDirectoryPath -Path ([string]$active.Root))-ieq(Get-SynapseNormalizedDirectoryPath -Path ([string]$SuccessorRecord.Root)) -and $active.Artifacts.ContainsKey([string]$next.Descriptor.leaf)){
            $activeArtifact=$active.Artifacts[[string]$next.Descriptor.leaf]
            if($null-ne$activeArtifact.handle){$handle=$activeArtifact.handle}
        }
        try{
            if($null-eq$handle){$handle=Open-SynapsePhysicalAllocatedFileForFill -ParentPath ([string]$SuccessorRecord.Root) -ParentChain $SuccessorRecord.Journal.RootChain -Leaf ([string]$next.Descriptor.leaf) -ExpectedFileId128 ([string]$next.Descriptor.file_id_128) -MaximumLength ([int64]$next.Descriptor.maximum_length) -Context "${Context}_fill_$($next.AttemptIndex)"}
            [void]$handle.FillUtf8([string]$marker.Text,[string]$marker.Sha256,[int64]$marker.Length)
        }catch{$writeError=$_.Exception}finally{
            if($null-ne$handle){try{$handle.Dispose();if($null-ne$activeArtifact){$activeArtifact.handle=$null}}catch{
                $primaryText=if($null-eq$writeError){'<none>'}else{$writeError.Message}
                [Environment]::FailFast("SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_MARKER_CLOSE_UNPROVEN context=$Context attempt=$($next.AttemptIndex) primary=[$primaryText]",$_.Exception)
            }}
        }
        $after=Read-SynapseAuthorityPredecessorCleanupMarkerSlot -SuccessorRecord $SuccessorRecord -Descriptor $next.Descriptor -AttemptIndex ([int]$next.AttemptIndex) -Context "${Context}_after_fill"
        if([string]$after.Kind-ceq'valid'){continue}
        if([string]$after.Kind-ceq'torn'){continue}
        if($null-ne$writeError){throw $writeError}
        Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_MARKER_RETURN_LOSS context=$Context attempt=$($next.AttemptIndex)"
    }
}

function Remove-SynapseAuthorityTornPredecessorWithCommittedSuccessor {
    param(
        [Parameter(Mandatory=$true)]$PredecessorRecord,
        [Parameter(Mandatory=$true)]$SuccessorRecord,
        [Parameter(Mandatory=$true)]$CleanupAuthority,
        [Parameter(Mandatory=$true)][string]$ExpectedParent,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $cleanupProof=Assert-SynapseAuthorityCommittedSuccessorPredecessorCleanupAuthority -Authority $CleanupAuthority -ExpectedPredecessorReceipt $PredecessorRecord.PredecessorReceipt -Context "${Context}_authority"
    $root=Get-SynapseNormalizedDirectoryPath -Path ([string]$CleanupAuthority.predecessor_receipt.journal.transaction_root)
    $expectedParent=Get-SynapseNormalizedDirectoryPath -Path $ExpectedParent
    if((Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $root))-ine$expectedParent){Die "SYNAPSE_AUTHORITY_TORN_PREDECESSOR_CLEANUP_SCOPE_INVALID context=$Context root=$root parent=$expectedParent"}
    $entries=$null
    if($null-ne$PredecessorRecord.PSObject.Properties['CleanupMarker'] -and $null-ne$PredecessorRecord.CleanupMarker){
        $entries=@($PredecessorRecord.CleanupMarker.Payload.entries|ForEach-Object{ConvertTo-SynapseCanonicalValue -Value $_})
    }else{
        $entries=@(Get-SynapseAuthorityPredecessorCleanupEntryRoster -PredecessorRecord $PredecessorRecord -Context "${Context}_roster")
    }
    $marker=Ensure-SynapseAuthorityCommittedPredecessorCleanupMarker -SuccessorRecord $SuccessorRecord -CleanupAuthority $CleanupAuthority -Entries $entries -Context "${Context}_marker"
    if((Get-SynapseCanonicalJson -Value @($marker.Payload.entries))-cne(Get-SynapseCanonicalJson -Value @($entries))){Die "SYNAPSE_AUTHORITY_TORN_PREDECESSOR_CLEANUP_MARKER_ROSTER_DRIFT context=$Context root=$root"}
    $activeSuccessorAllocation=$script:SynapseDeploymentAllocationContext
    if($null-ne$activeSuccessorAllocation -and
       (Get-SynapseNormalizedDirectoryPath -Path ([string]$activeSuccessorAllocation.Root))-ieq(Get-SynapseNormalizedDirectoryPath -Path ([string]$SuccessorRecord.Root))){
        $commitSequence=[int]$cleanupProof.CommitSlot.Sequence
        $commitLeaf=[string]$cleanupProof.CommitSlot.Leaf
        $retainedCommitHandle=if($activeSuccessorAllocation.JournalSlotHandles.ContainsKey($commitSequence)){$activeSuccessorAllocation.JournalSlotHandles[$commitSequence]}else{$null}
        $artifactCommitHandle=if($activeSuccessorAllocation.Artifacts.ContainsKey($commitLeaf)){$activeSuccessorAllocation.Artifacts[$commitLeaf].handle}else{$null}
        if($null-ne$retainedCommitHandle -and $null-ne$artifactCommitHandle -and -not[object]::ReferenceEquals($retainedCommitHandle,$artifactCommitHandle)){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_ACTIVE_COMMIT_OWNER_AMBIGUOUS context=$Context sequence=$commitSequence"}
        $commitOwner=if($null-ne$retainedCommitHandle){$retainedCommitHandle}else{$artifactCommitHandle}
        if($null-ne$commitOwner){
            if([string]$commitOwner.FileId128-ine[string]$cleanupProof.CommitSlot.FileId128){Die "SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_ACTIVE_COMMIT_HANDLE_DRIFT context=$Context sequence=$commitSequence"}
            try{$commitOwner.Dispose()}catch{[Environment]::FailFast("SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_ACTIVE_COMMIT_CLOSE_UNPROVEN context=$Context sequence=$commitSequence",$_.Exception)}
        }
        [void]$activeSuccessorAllocation.JournalSlotHandles.Remove($commitSequence)
        if($activeSuccessorAllocation.Artifacts.ContainsKey($commitLeaf)){$activeSuccessorAllocation.Artifacts[$commitLeaf].handle=$null}
    }
    $commitLease=$null;$markerLease=$null;$primary=$null
    try{
        # Retain both pieces of external REDO authority under exact
        # read/delete-denying leases from before the first predecessor delete
        # through root removal.  Control leases alone do not protect the
        # successor's durable commit or its selected cleanup marker.
        $commitLease=Open-SynapsePhysicalFileReadLease -ParentPath ([string]$SuccessorRecord.Root) -ParentChain $SuccessorRecord.Journal.RootChain -Leaf ([string]$cleanupProof.CommitSlot.Leaf) -ExpectedFileId128 ([string]$cleanupProof.CommitSlot.FileId128) -ExpectedSha256 ([string]$cleanupProof.CommitSlot.RawSha256) -ExpectedLength ([int64]$cleanupProof.CommitSlot.ByteLength) -Context "${Context}_commit_authority"
        $markerLease=Open-SynapsePhysicalFileReadLease -ParentPath ([string]$SuccessorRecord.Root) -ParentChain $SuccessorRecord.Journal.RootChain -Leaf ([string]$marker.Descriptor.leaf) -ExpectedFileId128 ([string]$marker.FileId128) -ExpectedSha256 ([string]$marker.Sha256) -ExpectedLength ([int64]$marker.Length) -Context "${Context}_marker_authority"
        $commitLease.RequireExact("${Context}_before_predecessor_delete")
        $markerLease.RequireExact("${Context}_before_predecessor_delete")
        $roster=New-SynapseCaseInsensitiveMap
        foreach($item in @($marker.Payload.entries)){
        $names=@(if($item-is[System.Collections.IDictionary]){$item.Keys}else{$item.PSObject.Properties.Name});$expected=@('leaf','is_directory','file_id_128','sha256','length')
        if($names.Count-ne$expected.Count -or @($names|Where-Object{$expected-cnotcontains$_}).Count-ne0 -or [string]$item.leaf-notmatch'^[A-Za-z0-9._-]{1,128}$' -or $roster.ContainsKey([string]$item.leaf) -or [string]$item.file_id_128-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or ([bool]$item.is_directory -and ([string]$item.sha256 -or [int64]$item.length-ne-1)) -or (-not[bool]$item.is_directory -and ([string]$item.sha256-notmatch'^[0-9A-Fa-f]{64}$' -or [int64]$item.length-lt0))){Die "SYNAPSE_AUTHORITY_TORN_PREDECESSOR_CLEANUP_MARKER_ENTRY_INVALID context=$Context root=$root leaf=$($item.leaf)"}
        $roster[[string]$item.leaf]=$item
        }
        if(-not(Test-Path -LiteralPath $root)){return $true}
        $rootChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $root)
        if([string]$rootChain[-1].file_id_128-ine[string]$marker.Payload.predecessor_root_file_id_128){Die "SYNAPSE_AUTHORITY_TORN_PREDECESSOR_CLEANUP_ROOT_DRIFT context=$Context root=$root"}
        $current=@(Get-SynapsePhysicalDirectoryEntriesBounded -Path $root -Chain $rootChain -MaximumEntries $script:SynapseDeploymentArtifactMaxDirectEntries -Context "${Context}_current")
        foreach($entry in $current){
        if(-not$roster.ContainsKey([string]$entry.Name)){Die "SYNAPSE_AUTHORITY_TORN_PREDECESSOR_CLEANUP_UNKNOWN_ENTRY context=$Context root=$root leaf=$($entry.Name)"}
        $expectedEntry=$roster[[string]$entry.Name]
        if([bool]$entry.IsDirectory-ne[bool]$expectedEntry.is_directory -or ([uint32]$entry.Attributes-band[uint32][System.IO.FileAttributes]::ReparsePoint)){Die "SYNAPSE_AUTHORITY_TORN_PREDECESSOR_CLEANUP_ENTRY_TYPE_DRIFT context=$Context path=$($entry.Path)"}
        $state=Get-SynapsePhysicalRelativeState -ParentPath $root -ParentChain $rootChain -Leaf ([string]$entry.Name) -Directory:([bool]$expectedEntry.is_directory)
        if([string]$state.FileId128-ine[string]$expectedEntry.file_id_128 -or (-not[bool]$expectedEntry.is_directory -and ([string]$state.Sha256-ine[string]$expectedEntry.sha256 -or [int64]$state.Length-ne[int64]$expectedEntry.length))){Die "SYNAPSE_AUTHORITY_TORN_PREDECESSOR_CLEANUP_ENTRY_DRIFT context=$Context path=$($entry.Path)"}
        }
        $activeAllocation=$script:SynapseDeploymentAllocationContext
        if($null-ne$activeAllocation -and (Get-SynapseNormalizedDirectoryPath -Path ([string]$activeAllocation.Root))-ieq$root){Close-SynapseDeploymentAllocationHandles -Context $activeAllocation;$script:SynapseDeploymentAllocationContext=$null}
    # Keep the receipt-bearing cuts until the allocation-only payload has
    # gone.  The cleanup decision lives in the successor, so a restart can
    # recognize every subset, while this ordering also preserves the local
    # allocation chain for as long as possible.
        $receipt=$CleanupAuthority.predecessor_receipt
        $priorityLeaves=@(
        [string]$script:SynapseDeploymentAllocationMarkerFileName,
        'transaction-0001.json',
        [string]$receipt.journal.valid_prefix.leaf,
        [string]$receipt.journal.terminal_cut.leaf
        )|Where-Object{$_}|Select-Object -Unique
        foreach($entry in @($current|Where-Object{-not[bool]$_.IsDirectory -and $priorityLeaves-inotcontains[string]$_.Name}|Sort-Object Name)){
        $expectedEntry=$roster[[string]$entry.Name]
        Remove-SynapsePhysicalRelativeEntryExact -ParentPath $root -ParentChain $rootChain -Leaf ([string]$entry.Name) -ExpectedFileId128 ([string]$expectedEntry.file_id_128) -ExpectedSha256 ([string]$expectedEntry.sha256) -ExpectedLength ([int64]$expectedEntry.length) -Context "${Context}_file"
        }
        foreach($entry in @($current|Where-Object{[bool]$_.IsDirectory -and $priorityLeaves-inotcontains[string]$_.Name}|Sort-Object Name)){
        $expectedEntry=$roster[[string]$entry.Name]
        Remove-SynapsePhysicalRelativeEntryExact -ParentPath $root -ParentChain $rootChain -Leaf ([string]$entry.Name) -ExpectedFileId128 ([string]$expectedEntry.file_id_128) -Directory -Context "${Context}_directory"
        }
        foreach($leaf in $priorityLeaves){
        $remaining=@(Get-SynapsePhysicalDirectoryEntriesBounded -Path $root -Chain $rootChain -MaximumEntries $script:SynapseDeploymentArtifactMaxDirectEntries -Context "${Context}_priority_$leaf"|Where-Object Name -CEQ $leaf)
        if($remaining.Count-gt1){Die "SYNAPSE_AUTHORITY_TORN_PREDECESSOR_CLEANUP_PRIORITY_AMBIGUOUS context=$Context root=$root leaf=$leaf count=$($remaining.Count)"}
        if($remaining.Count-eq0){continue}
        $expectedEntry=$roster[$leaf]
        if($null-eq$expectedEntry -or [bool]$expectedEntry.is_directory){Die "SYNAPSE_AUTHORITY_TORN_PREDECESSOR_CLEANUP_PRIORITY_DESCRIPTOR_INVALID context=$Context root=$root leaf=$leaf"}
        Remove-SynapsePhysicalRelativeEntryExact -ParentPath $root -ParentChain $rootChain -Leaf $leaf -ExpectedFileId128 ([string]$expectedEntry.file_id_128) -ExpectedSha256 ([string]$expectedEntry.sha256) -ExpectedLength ([int64]$expectedEntry.length) -Context "${Context}_priority"
        }
        $remainingAfter=@(Get-SynapsePhysicalDirectoryEntriesBounded -Path $root -Chain $rootChain -MaximumEntries 0 -Context "${Context}_empty_before_root")
        if($remainingAfter.Count-ne0){Die "SYNAPSE_AUTHORITY_TORN_PREDECESSOR_CLEANUP_ROOT_NOT_EMPTY context=$Context root=$root entries=$(@($remainingAfter.Name)-join',')"}
        $markerReadback=Get-SynapseAuthorityCommittedPredecessorCleanupMarkerSet -SuccessorRecord $SuccessorRecord -CleanupAuthority $CleanupAuthority -ExpectedEntries $entries -Context "${Context}_before_root"
        if($null-eq$markerReadback.Valid){Die "SYNAPSE_AUTHORITY_TORN_PREDECESSOR_CLEANUP_MARKER_LOST context=$Context root=$root"}
        $commitLease.RequireExact("${Context}_before_root_delete")
        $markerLease.RequireExact("${Context}_before_root_delete")
        $parentChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $expectedParent)
        Remove-SynapsePhysicalRelativeEntryExact -ParentPath $expectedParent -ParentChain $parentChain -Leaf (Split-Path -Leaf $root) -ExpectedFileId128 ([string]$marker.Payload.predecessor_root_file_id_128) -Directory -Context "${Context}_root"
        $commitLease.RequireExact("${Context}_after_root_delete")
        $markerLease.RequireExact("${Context}_after_root_delete")
        [void](Assert-SynapseAuthorityCommittedSuccessorPredecessorCleanupAuthority -Authority $CleanupAuthority -ExpectedPredecessorReceipt $PredecessorRecord.PredecessorReceipt -Context "${Context}_after_root")
        return $true
    }catch{
        $primary=$_.Exception
        throw
    }finally{
        foreach($lease in @($markerLease,$commitLease)){
            if($null-eq$lease){continue}
            try{$lease.Dispose()}catch{
                $primaryText=if($null-eq$primary){'<none>'}else{$primary.Message}
                [Environment]::FailFast("SYNAPSE_AUTHORITY_PREDECESSOR_CLEANUP_AUTHORITY_CLOSE_UNPROVEN context=$Context primary=[$primaryText]",$_.Exception)
            }
        }
    }
}

function Restore-SynapseDeclaredAuthorityPredecessorForRollback {
    param(
        [Parameter(Mandatory=$true)]$PredecessorRecord,
        [Parameter(Mandatory=$true)]$PredecessorReceipt,
        [Parameter(Mandatory=$true)]$CurrentInitial,
        [Parameter(Mandatory=$true)]$CurrentValidated,
        $LegacySnapshot,
        [Parameter(Mandatory=$true)]$TaskInfrastructure,
        [Parameter(Mandatory=$true)][string]$RuntimeBinDir,
        [Parameter(Mandatory=$true)][ValidateSet('cold_predecision','normal_catch')][string]$Trigger,
        [AllowEmptyString()][string]$PrimaryFailureSha256,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $declared=Assert-SynapseAuthorityPredecessorReceiptDescriptor -Receipt $CurrentInitial.predecessor_authority_receipt -Context "${Context}_declared"
    if((Get-SynapseCanonicalJson -Value $declared)-cne(Get-SynapseCanonicalJson -Value $PredecessorReceipt)){Die "SYNAPSE_AUTHORITY_ROLLBACK_PREDECESSOR_RECEIPT_DRIFT context=$Context"}
    [void](Invoke-SynapseAuthorityControlTransitionRollback -Transition $CurrentValidated.LegacyDenialTransition)
    if([string]$CurrentInitial.prior_authority-ceq'legacy'){
        if($null-eq$LegacySnapshot){Die "SYNAPSE_AUTHORITY_ROLLBACK_PREDECESSOR_LEGACY_SNAPSHOT_MISSING context=$Context"}
        Move-SynapseLegacyDenialPreimageLeaseToSnapshot -Snapshot $LegacySnapshot -LegacyDenialTransition $CurrentValidated.LegacyDenialTransition -Context "${Context}_supervisor_handoff"
    }
    $borrowedLegacySupervisorLease=if([string]$CurrentInitial.prior_authority-ceq'legacy' -and $null-ne$LegacySnapshot -and $null-ne$LegacySnapshot.PSObject.Properties['SupervisorLease']){$LegacySnapshot.SupervisorLease}else{$null}
    if([string]$CurrentInitial.prior_authority-ceq'legacy' -and $null-eq$borrowedLegacySupervisorLease){Die "SYNAPSE_AUTHORITY_ROLLBACK_PREDECESSOR_SUPERVISOR_LEASE_MISSING context=$Context"}
    [void](Invoke-SynapseAuthorityControlTransitionRollback -Transition $CurrentValidated.LegacyGateTransition)
    if([string]$PredecessorReceipt.terminal_mode-ceq'legacy_prior_unchanged'){
        # The successor removes/stops the exact legacy Scheduler lineage before
        # taking authority.  Rolling its files back is necessary but does not
        # demand-start that still-registered logon task.  Restore the declared
        # predecessor by running only the exact sealed task, then independently
        # prove its full Scheduler/process/socket/tool identity before the
        # physical predecessor is reconstructed.
        [void](Assert-SynapseLegacyAuthoritySnapshotUnchanged -Snapshot $LegacySnapshot)
        $tokenRead=Read-SynapseSetupTokenForRestartGuard -TokenPath ([string]$CurrentInitial.token_path)
        if(-not[bool]$tokenRead.Ok){Die "$($tokenRead.Code) reason=declared_predecessor_demand_start $($tokenRead.Detail)"}
        $prior=Get-SynapseLegacyPriorAuthorityOperationalClassification -LegacySnapshot $LegacySnapshot -PriorGeneration $CurrentValidated.PriorGeneration -Bind ([string]$CurrentInitial.bind) -DbPath ([string]$CurrentInitial.db_path) -Token ([string]$tokenRead.Token) -Context "${Context}_before_demand_start"
        if([string]$prior.State-ceq'absent'){
            if($null-eq$LegacySnapshot.PSObject.Properties['SupervisorLease'] -or $null-eq$LegacySnapshot.SupervisorLease -or ($null-ne$LegacySnapshot.PSObject.Properties['SupervisorLeaseBorrowed'] -and [bool]$LegacySnapshot.SupervisorLeaseBorrowed)){
                Die "SYNAPSE_AUTHORITY_ROLLBACK_PREDECESSOR_SUPERVISOR_LEASE_OWNER_INVALID context=$Context"
            }
            $LegacySnapshot.SupervisorLease.RequireExact("${Context}_before_demand_start_release")
            try{$LegacySnapshot.SupervisorLease.Dispose()}catch{[Environment]::FailFast("SYNAPSE_AUTHORITY_ROLLBACK_PREDECESSOR_SUPERVISOR_RELEASE_UNPROVEN context=$Context",$_.Exception)}
            $LegacySnapshot.SupervisorLease=$null;$borrowedLegacySupervisorLease=$null
            $lookup=Get-SynapseScheduledTaskLookupExact -Name ([string]$LegacySnapshot.name)
            if(-not[bool]$lookup.Exists){Die "SYNAPSE_AUTHORITY_ROLLBACK_PREDECESSOR_TASK_ABSENT context=$Context task=$($LegacySnapshot.name) hresult=$($lookup.HResult)"}
            $instances=@($lookup.Task.GetInstances(0))
            if($instances.Count-ne0){Die "SYNAPSE_AUTHORITY_ROLLBACK_PREDECESSOR_TASK_INSTANCE_AMBIGUOUS context=$Context task=$($LegacySnapshot.name) instances=$($instances.Count)"}
            try{$null=$lookup.Task.Run($null)}catch{Die "SYNAPSE_AUTHORITY_ROLLBACK_PREDECESSOR_TASK_RUN_FAILED context=$Context task=$($LegacySnapshot.name) error=$($_.Exception.Message)"}
            $clock=[System.Diagnostics.Stopwatch]::StartNew();$last='absent'
            do{
                Start-Sleep -Milliseconds 250
                try{
                    $prior=Get-SynapseLegacyPriorAuthorityOperationalClassification -LegacySnapshot $LegacySnapshot -PriorGeneration $CurrentValidated.PriorGeneration -Bind ([string]$CurrentInitial.bind) -DbPath ([string]$CurrentInitial.db_path) -Token ([string]$tokenRead.Token) -Context "${Context}_after_demand_start"
                    $last=[string]$prior.State
                    if($last-ceq'scheduler_operational'){break}
                }catch{$last=(($_.Exception.Message-replace'\s+',' ').Trim())}
                if($clock.Elapsed.TotalSeconds-ge120){Die "SYNAPSE_AUTHORITY_ROLLBACK_PREDECESSOR_TASK_START_TIMEOUT context=$Context task=$($LegacySnapshot.name) timeout_s=120 last=[$last]"}
            }while($true)
            $supervisorDescriptor=Get-SynapseLegacySnapshotSupervisorDescriptor -Snapshot $LegacySnapshot -Context "${Context}_after_demand_start_supervisor"
            $verifiedSupervisor=Assert-SynapseAuthorityFileDescriptorPhysicalIdentity -Descriptor $supervisorDescriptor -ExpectedRole legacy_supervisor -Context "${Context}_after_demand_start_supervisor"
            $borrowedLegacySupervisorLease=Open-SynapsePhysicalFileReadLease -ParentPath $verifiedSupervisor.ParentPath -ParentChain $verifiedSupervisor.Chain -Leaf (Split-Path -Leaf $verifiedSupervisor.Path) -ExpectedFileId128 $verifiedSupervisor.FileId128 -ExpectedSha256 $verifiedSupervisor.Sha256 -ExpectedLength $verifiedSupervisor.Length -Context "${Context}_after_demand_start_supervisor_lease"
            $borrowedLegacySupervisorLease.RequireExact("${Context}_after_demand_start_supervisor_exact")
            $LegacySnapshot.SupervisorLease=$borrowedLegacySupervisorLease
        }elseif([string]$prior.State-cne'scheduler_operational'){
            Die "SYNAPSE_AUTHORITY_ROLLBACK_PREDECESSOR_TASK_STATE_AMBIGUOUS context=$Context state=$($prior.State)"
        }
    }
    if($null-ne$PredecessorRecord.PSObject.Properties['PhysicalRollbackCandidate'] -and
       $null-ne$PredecessorRecord.PhysicalRollbackCandidate -and
       ($null-eq$PredecessorRecord.RolledBackPredecessor -or $null-eq$PredecessorRecord.RolledBackPredecessor.Validated)){
        # A declared physical predecessor may have been structurally paired
        # while this successor held its gate/denial prestates.  Only after the
        # exact prestates are restored can its mode-specific live proof be
        # reconstructed.  Re-resolve now and replace the structural shell
        # before any caller treats the predecessor as restored authority.
        $resolved=Resolve-SynapseAuthorityPhysicalRollbackPredecessor -Record $PredecessorRecord -TaskInfrastructure $TaskInfrastructure -RuntimeBinDir $RuntimeBinDir -RequestedLegacyTaskName ([string]$CurrentInitial.task_name) -DeclaredPredecessorReceipt $PredecessorReceipt -BorrowedLegacySupervisorLease $borrowedLegacySupervisorLease
        if([string]$resolved.Kind-cne'predecessor' -or
           (Get-SynapseCanonicalJson -Value $resolved.PredecessorReceipt)-cne(Get-SynapseCanonicalJson -Value $PredecessorReceipt)){
            Die "SYNAPSE_AUTHORITY_ROLLBACK_PHYSICAL_PREDECESSOR_RECONSTRUCTION_INVALID context=$Context kind=$($resolved.Kind)"
        }
        $PredecessorRecord.RolledBackPredecessor=$resolved.Predecessor
        $PredecessorRecord.PredecessorReceipt=$resolved.PredecessorReceipt
    }
    $live=Assert-SynapseGlobalAuthorityPredecessorLive -Record $PredecessorRecord -TaskInfrastructure $TaskInfrastructure -RuntimeBinDir $RuntimeBinDir -RequestedLegacyTaskName ([string]$CurrentInitial.task_name) -BorrowedLegacySupervisorLease $borrowedLegacySupervisorLease
    if([string]$live.Mode-cne[string]$PredecessorReceipt.terminal_mode){Die "SYNAPSE_AUTHORITY_ROLLBACK_PREDECESSOR_LIVE_MODE_DRIFT context=$Context expected=$($PredecessorReceipt.terminal_mode) actual=$($live.Mode)"}
    # Bind the immutable receipt declared by the current transaction.  The
    # live/physical resolver may legitimately replace its runtime predecessor
    # view as a torn slot becomes readable; that mutable view must never alter
    # durable rollback evidence.
    $authorityEvidence=[ordered]@{schema='synapse_authority_predecessor_restored/v1';predecessor_restored=$true;predecessor_receipt_sha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $declared)).ToUpperInvariant();predecessor_mode=[string]$declared.terminal_mode;predecessor_authority_descriptor=(ConvertTo-SynapseCanonicalValue -Value $declared.authority_descriptor)}
    $detail=[ordered]@{schema='synapse_authority_rollback/v2';mode='predecessor_restored';trigger=$Trigger;primary_failure_sha256=$(if($PrimaryFailureSha256){$PrimaryFailureSha256.ToUpperInvariant()}else{''});prior_authority=[string]$CurrentInitial.prior_authority;authority_restored='predecessor';broker_identity_sha256=([string]$CurrentInitial.broker_identity_sha256).ToUpperInvariant();unknown_objects_preserved=$true;authority_evidence=$authorityEvidence}
    return [pscustomobject][ordered]@{Detail=$detail;Live=$live}
}

function Ensure-SynapseBrokerAuthorityAdopted {
    param(
        [Parameter(Mandatory=$true)][string]$RuntimeBinDir,
        [Parameter(Mandatory=$true)][string]$BootstrapSourcePath,
        [Parameter(Mandatory=$true)][string]$PowerShellPath,
        [Parameter(Mandatory=$true)][string]$WorkingDirectory,
        [Parameter(Mandatory=$true)][string]$LogDir,
        [Parameter(Mandatory=$true)][string]$TaskName,
        [Parameter(Mandatory=$true)][string]$ExePath,
        [AllowEmptyString()][string]$AdoptionRehearsalExePath='',
        [ValidateRange(0,1000)][int]$AdoptionRehearsalExpectedToolCount=0,
        [AllowEmptyString()][string]$AdoptionRehearsalExpectedToolSurfaceSha256='',
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$DbPath,
        [Parameter(Mandatory=$true)][string]$ProfilesDir,
        [Parameter(Mandatory=$true)][string]$TokenPath,
        [Parameter(Mandatory=$true)][string]$Token,
        [Parameter(Mandatory=$true)][string]$MaintenanceLockPath,
        [Parameter(Mandatory=$true)][string]$CalyxConfigPath,
        [Parameter(Mandatory=$true)][ValidatePattern('^[0-9A-Fa-f]{64}$')][string]$ExpectedCalyxConfigSha256,
        [bool]$EnableAudio,
        [AllowNull()][string]$AllowedPermissions,
        [switch]$RequireCommitted,
        [switch]$DecommissionStructuralOnly,
        [switch]$AllowMissingTokenWhenParked,
        [switch]$RecoveryOnly,
        [ValidateRange(60,900)][int]$HealthTimeoutSeconds=600
    )

    if($RequireCommitted -and $RecoveryOnly){
        Die 'SYNAPSE_BROKER_AUTHORITY_RECOVERY_MODE_CONFLICT require_committed=true recovery_only=true'
    }
    if($DecommissionStructuralOnly -and -not $RequireCommitted){
        Die 'SYNAPSE_BROKER_AUTHORITY_DECOMMISSION_MODE_INVALID require_committed=false'
    }
    if(-not[string]::IsNullOrWhiteSpace($AdoptionRehearsalExePath)){
        $script:SynapseAdoptionRehearsalExePath=[System.IO.Path]::GetFullPath($AdoptionRehearsalExePath)
        if($AdoptionRehearsalExpectedToolCount-ne40 -or $AdoptionRehearsalExpectedToolSurfaceSha256-notmatch'^[0-9A-Fa-f]{64}$'){Die "SYNAPSE_BROKER_ADOPTION_REHEARSAL_SURFACE_INVALID count=$AdoptionRehearsalExpectedToolCount sha=$AdoptionRehearsalExpectedToolSurfaceSha256"}
        $script:SynapseAdoptionRehearsalExpectedToolCount=[int]$AdoptionRehearsalExpectedToolCount
        $script:SynapseAdoptionRehearsalExpectedToolSurfaceSha256=$AdoptionRehearsalExpectedToolSurfaceSha256.ToUpperInvariant()
    }
    $rehearsalVariable=Get-Variable -Name SynapseAdoptionRehearsalExePath -Scope Script -ErrorAction SilentlyContinue
    $effectiveAdoptionRehearsalExePath=if($null-ne$rehearsalVariable){[string]$rehearsalVariable.Value}else{''}
    $rehearsalCountVariable=Get-Variable -Name SynapseAdoptionRehearsalExpectedToolCount -Scope Script -ErrorAction SilentlyContinue
    $rehearsalHashVariable=Get-Variable -Name SynapseAdoptionRehearsalExpectedToolSurfaceSha256 -Scope Script -ErrorAction SilentlyContinue
    $effectiveAdoptionRehearsalExpectedToolCount=if($null-ne$rehearsalCountVariable){[int]$rehearsalCountVariable.Value}else{0}
    $effectiveAdoptionRehearsalExpectedToolSurfaceSha256=if($null-ne$rehearsalHashVariable){[string]$rehearsalHashVariable.Value}else{''}
    if($AllowMissingTokenWhenParked -and -not$RequireCommitted){Die 'SYNAPSE_BROKER_AUTHORITY_MISSING_TOKEN_MODE_INVALID require_committed=false'}

    $layout=if($RequireCommitted){Get-SynapseAuthorityLayoutReadOnly -RuntimeBinDir $RuntimeBinDir -RequireAuthorityRoot}else{Get-SynapseAuthorityLayout -RuntimeBinDir $RuntimeBinDir}
    $epochEntries=@(Get-SynapsePhysicalDirectoryEntriesBounded -Path $layout.Epochs -Chain $layout.EpochsChain -MaximumEntries $script:SynapseAuthorityMaxEpochs -Context 'authority_epoch_scan')
    $unexpected=@($epochEntries|Where-Object{-not [bool]$_.IsDirectory -or ([uint32]$_.Attributes -band [uint32][System.IO.FileAttributes]::ReparsePoint) -or [string]$_.Name -notmatch '^deployment-\d{8}T\d{9}Z-\d+$'})
    if($unexpected.Count -gt 0){Die "SYNAPSE_AUTHORITY_EPOCH_NAMESPACE_INVALID root=$($layout.Epochs) entries=$(@($unexpected.Name)-join ',')"}
    $committed=@();$recoverable=@();$predecessors=@();$failedSuccessors=@();$physicalFailedSuccessors=@();$failedCleanupTails=@();$committedPredecessorCleanupTails=@();$declaredPhysicalPredecessor=$null
        foreach($entry in @($epochEntries|Sort-Object Name)){
        $journal=$null
        try{$journal=Read-SynapseDeploymentTransactionJournal -TransactionRoot ([string]$entry.Path)}catch{
            $readError=$_.Exception.Message
            $cleanupTail=Get-SynapseDeploymentCleanupTailDescriptor -TransactionRoot ([string]$entry.Path)
            if($null-ne$cleanupTail -and [string]$cleanupTail.TerminalState-ceq'rolled_back' -and $null-ne$cleanupTail.CleanupAuthority){
                if([string]$cleanupTail.CleanupAuthority.schema-ceq'synapse_authority_failed_successor_cleanup/v1'){$failedCleanupTails+=,[pscustomobject]@{Entry=$entry;Tail=$cleanupTail}}
                elseif([string]$cleanupTail.CleanupAuthority.schema-ceq'synapse_authority_committed_successor_predecessor_cleanup/v1'){$committedPredecessorCleanupTails+=,[pscustomobject]@{Entry=$entry;Tail=$cleanupTail}}
                else{Die "SYNAPSE_AUTHORITY_CLEANUP_TAIL_AUTHORITY_SCHEMA_INVALID root=$($entry.Path) schema=$($cleanupTail.CleanupAuthority.schema)"}
                continue
            }
            if($AllowMissingTokenWhenParked){Die "SYNAPSE_BROKER_AUTHORITY_MISSING_TOKEN_UNREADABLE_EPOCH_REFUSED root=$($entry.Path) error=$readError remediation=restore the exact token or repair/remove the ambiguous authority epoch before decommission"}
            try{
                [void](Remove-SynapseDeploymentTransactionArtifact -Path ([string]$entry.Path) -ExpectedRoot $layout.Epochs -ExpectedState unarmed -Reason 'authority_torn_initial_cleanup' -Domain authority)
                Info "SYNAPSE_AUTHORITY_TORN_INITIAL_CLEANED root=$($entry.Path) error=$readError"
                continue
            }catch{
                Die "SYNAPSE_AUTHORITY_EPOCH_JOURNAL_UNREADABLE root=$($entry.Path) error=$readError cleanup_error=$($_.Exception.Message) remediation=preserve the exact authority epoch; neither an unknown object nor an unallocated CreateNew cut grants cleanup authority"
            }
        }
        if($null -eq $journal){
            if($AllowMissingTokenWhenParked){Die "SYNAPSE_BROKER_AUTHORITY_MISSING_TOKEN_UNARMED_EPOCH_REFUSED root=$($entry.Path) remediation=restore the exact token or finish ordinary setup recovery before decommission"}
            [void](Remove-SynapseDeploymentTransactionArtifact -Path ([string]$entry.Path) -ExpectedRoot $layout.Epochs -ExpectedState unarmed -Reason 'authority_unarmed_cleanup' -Domain authority)
            continue
        }
        $epochSchema=[string]$journal.Initial.schema;$epochKind=[string]$journal.Initial.transaction_kind
        $epochV3=($epochSchema-ceq'synapse_broker_adoption_transaction/v3') -and ($epochKind-ceq'synapse_broker_adoption/v3')
        $epochV4=($epochSchema-ceq'synapse_broker_adoption_transaction/v4') -and ($epochKind-ceq'synapse_broker_adoption/v4')
        if(-not($epochV3 -or $epochV4)){
            Die "SYNAPSE_AUTHORITY_EPOCH_SCHEMA_INVALID root=$($entry.Path) schema=$epochSchema kind=$epochKind"
        }
        # Generation executables/profiles are mutable application payload, not
        # rollback authority. A failed setup may exact-delete its staging tree
        # after an armed cut; recovery must still validate and reverse the
        # immutable journal/control transaction without recreating a vanished
        # FILE_ID or treating pathname-equivalent bytes as authority. Every
        # path that actually adopts or launches a generation performs its own
        # retained physical descriptor proof.
        [void](Assert-SynapseAuthorityAdoptionInitialDescriptor -Initial $journal.Initial -TransactionRoot ([string]$entry.Path) -Allocation $journal.Allocation -HistoricalMutableGeneration -StructuralOnly)
        $journalTerminal=if([string]$journal.State -eq 'cleanup_ready'){[string]$journal.Latest.detail.terminal_state}else{[string]$journal.State}
        if($journalTerminal -ne 'commit_decided' -and ([string]$journal.Initial.task_name -cne $TaskName -or [string]$journal.Initial.bind -cne $Bind -or
            [System.IO.Path]::GetFullPath([string]$journal.Initial.db_path) -ine [System.IO.Path]::GetFullPath($DbPath) -or
            [System.IO.Path]::GetFullPath([string]$journal.Initial.token_path) -ine [System.IO.Path]::GetFullPath($TokenPath))){
            Die "SYNAPSE_AUTHORITY_EPOCH_INVOCATION_IDENTITY_MISMATCH root=$($entry.Path) task=$($journal.Initial.task_name) bind=$($journal.Initial.bind) db=$($journal.Initial.db_path) token=$($journal.Initial.token_path)"
        }
        $effectiveState=if([string]$journal.State -eq 'cleanup_ready'){[string]$journal.Latest.detail.terminal_state}else{[string]$journal.State}
        if([string]$journal.State -eq 'cleanup_ready'){
            $cleanupExpected=if($effectiveState -eq 'commit_decided'){'committed'}elseif($effectiveState -eq 'rolled_back'){'rolled_back'}else{Die "SYNAPSE_AUTHORITY_CLEANUP_READY_TERMINAL_INVALID root=$($entry.Path) terminal=$effectiveState"}
            # Authority adoption terminals are retained receipts.  A committed
            # successor may later authorize deletion of its exact predecessor;
            # cleanup_ready alone never grants authority to erase either record.
        }
        if($effectiveState -eq 'commit_decided'){$committed+=,[pscustomobject]@{Entry=$entry;Journal=$journal}}
        elseif($effectiveState -in @('armed','candidate_ready')){
            if($null-ne$journal.TornTail -and [string]$journal.Initial.schema-ceq'synapse_broker_adoption_transaction/v4' -and $null-ne$journal.Initial.predecessor_authority_receipt){$physicalFailedSuccessors+=,[pscustomobject]@{Entry=$entry;Journal=$journal;PredecessorReceipt=(ConvertTo-SynapseCanonicalValue -Value $journal.Initial.predecessor_authority_receipt)}}
            else{$recoverable+=,[pscustomobject]@{Entry=$entry;Journal=$journal}}
        }
        elseif($effectiveState -eq 'rolled_back'){
            $rollbackSlot=if([string]$journal.State-ceq'cleanup_ready'){@($journal.Slots|Where-Object{[string]$_.State-ceq'rolled_back'}|Select-Object -Last 1)}else{@($journal.Slots[-1])}
            if($rollbackSlot.Count-ne1){Die "SYNAPSE_AUTHORITY_ROLLBACK_SLOT_MISSING root=$($entry.Path) state=$($journal.State)"}
            if([string]$rollbackSlot[0].Payload.detail.mode-ceq'predecessor_restored'){$failedSuccessors+=,[pscustomobject]@{Entry=$entry;Journal=$journal;TerminalSlot=$rollbackSlot[0]}}else{$predecessors+=,[pscustomobject]@{Entry=$entry;Journal=$journal}}
        }
        else{Die "SYNAPSE_AUTHORITY_EPOCH_STATE_INVALID root=$($entry.Path) state=$($journal.State)"}
    }
    $declaringSuccessors=@(@($committed)+@($recoverable)+@($failedSuccessors)+@($physicalFailedSuccessors)|Where-Object{$null-ne$_.Journal.Initial.predecessor_authority_receipt})
    $declaredReceipt=$null;$declaredReceiptJson='';$declaringRoots=@()
    foreach($declaringSuccessor in $declaringSuccessors){
        $candidateReceipt=Assert-SynapseAuthorityPredecessorReceiptDescriptor -Receipt $declaringSuccessor.Journal.Initial.predecessor_authority_receipt -Context "authority_local_declared_physical_$($declaringSuccessor.Entry.Path)"
        $candidateReceiptJson=Get-SynapseCanonicalJson -Value $candidateReceipt
        if($null-eq$declaredReceipt){$declaredReceipt=$candidateReceipt;$declaredReceiptJson=$candidateReceiptJson}
        elseif($candidateReceiptJson-cne$declaredReceiptJson){Die "SYNAPSE_AUTHORITY_LOCAL_PHYSICAL_PREDECESSOR_DECLARATION_AMBIGUOUS successors=$(@($declaringRoots)+@([string]$declaringSuccessor.Entry.Path)-join',')"}
        $declaringRoots+=,[string]$declaringSuccessor.Entry.Path
    }
    if($null-ne$declaredReceipt){
        $physicalMatches=@($recoverable|Where-Object{(Get-SynapseNormalizedDirectoryPath -Path ([string]$_.Entry.Path))-ieq(Get-SynapseNormalizedDirectoryPath -Path ([string]$declaredReceipt.journal.transaction_root))})
        if($physicalMatches.Count-gt1){Die "SYNAPSE_AUTHORITY_LOCAL_DECLARED_PHYSICAL_PREDECESSOR_AMBIGUOUS successors=$($declaringRoots-join',') matches=$($physicalMatches.Count)"}
        if($physicalMatches.Count-eq1){
            $physical=$physicalMatches[0];$valid=$declaredReceipt.journal.valid_prefix;$terminal=$declaredReceipt.journal.terminal_cut;$tail=$physical.Journal.TornTail;$validSlots=@($physical.Journal.Slots|Where-Object Sequence -EQ ([int]$valid.sequence))
            if([string]$physical.Entry.FileId128-ine[string]$declaredReceipt.journal.transaction_root_file_id_128 -or [string]$physical.Journal.Initial.static_transaction_sha256-ine[string]$declaredReceipt.journal.initial_static_transaction_sha256 -or [int64]$physical.Journal.Initial.authority_epoch-ne[int64]$declaredReceipt.authority_epoch -or $validSlots.Count-ne1 -or [string]$validSlots[0].State-cne[string]$valid.state -or [string]$validSlots[0].Leaf-cne[string]$valid.leaf -or [string]$validSlots[0].FileId128-ine[string]$valid.file_id_128 -or [string]$validSlots[0].RawSha256-ine[string]$valid.sha256 -or [int64]$validSlots[0].ByteLength-ne[int64]$valid.length -or [string]$terminal.kind-cne'torn_tail_physical' -or $null-eq$tail -or [int]$tail.Sequence-ne[int]$terminal.sequence -or [string]$tail.Leaf-cne[string]$terminal.leaf -or [string]$tail.FileId128-ine[string]$terminal.file_id_128 -or [string]$tail.Sha256-ine[string]$terminal.sha256 -or [int64]$tail.Length-ne[int64]$terminal.length){Die "SYNAPSE_AUTHORITY_LOCAL_DECLARED_PHYSICAL_PREDECESSOR_CUT_DRIFT predecessor=$($physical.Entry.Path) successors=$($declaringRoots-join',')"}
            $record=[pscustomobject][ordered]@{Entry=$physical.Entry;Journal=$physical.Journal;Root=[string]$physical.Entry.Path;RootFileId128=[string]$physical.Entry.FileId128;RolledBackPredecessor=$null;PredecessorReceipt=$declaredReceipt;PhysicalRollbackCandidate=[pscustomobject][ordered]@{ValidPrefixState=[string]$physical.Journal.State;ValidPrefixSequence=[int]$physical.Journal.Sequence;TornSequence=[int]$tail.Sequence;TornLeaf=[string]$tail.Leaf;TornFileId128=[string]$tail.FileId128;TornSha256=[string]$tail.Sha256;TornLength=[int64]$tail.Length}}
            # The declaring successor may already own newer canonical control
            # objects, so the displaced predecessor cannot be revalidated as a
            # standalone live cut here.  The receipt/prefix/torn identities
            # above are the immutable descriptor used by successor recovery.
            $record.RolledBackPredecessor=[pscustomobject][ordered]@{Mode=[string]$declaredReceipt.terminal_mode;Entry=$physical.Entry;Journal=$physical.Journal;Detail=[pscustomobject][ordered]@{authority_evidence=(ConvertTo-SynapseCanonicalValue -Value $declaredReceipt.authority_descriptor)};Validated=$null;PhysicalRollback=$true;DeclaredBySuccessor=$true}
            $declaredPhysicalPredecessor=$record
            $recoverable=@($recoverable|Where-Object{(Get-SynapseNormalizedDirectoryPath -Path ([string]$_.Entry.Path))-ine(Get-SynapseNormalizedDirectoryPath -Path ([string]$physical.Entry.Path))})
        }
    }
    if($committed.Count -gt 1 -or $recoverable.Count -gt 1 -or $predecessors.Count -gt 1 -or $failedSuccessors.Count-gt1 -or $failedCleanupTails.Count-gt1 -or $committedPredecessorCleanupTails.Count-gt1 -or ($committed.Count -gt 0 -and $recoverable.Count -gt 0)){
        Die "SYNAPSE_AUTHORITY_EPOCH_AMBIGUOUS root=$($layout.Epochs) committed=$($committed.Count) recoverable=$($recoverable.Count) predecessors=$($predecessors.Count) failed_successors=$($failedSuccessors.Count) physical_failed_successors=$($physicalFailedSuccessors.Count) failed_cleanup_tails=$($failedCleanupTails.Count) committed_predecessor_cleanup_tails=$($committedPredecessorCleanupTails.Count)"
    }
    if($AllowMissingTokenWhenParked-and($committed.Count-ne1-or$recoverable.Count-ne0-or$predecessors.Count-ne0-or$failedSuccessors.Count-ne0-or$failedCleanupTails.Count-ne0-or$committedPredecessorCleanupTails.Count-ne0-or$null-ne$declaredPhysicalPredecessor)){Die "SYNAPSE_BROKER_AUTHORITY_MISSING_TOKEN_HISTORY_NOT_SINGLE_COMMITTED committed=$($committed.Count) epochs=$($epochEntries.Count) recoverable=$($recoverable.Count) predecessors=$($predecessors.Count) failed_successors=$($failedSuccessors.Count) physical_failed_successors=$($physicalFailedSuccessors.Count) cleanup_tails=$($failedCleanupTails.Count) committed_cleanup_tails=$($committedPredecessorCleanupTails.Count) remediation=restore the exact token and converge ordinary setup recovery before decommission"}
    $predecessor=$null;$predecessorReceipt=$null;$predecessorLiveRecord=$null
    if($null-ne$declaredPhysicalPredecessor){
        $predecessor=$declaredPhysicalPredecessor.RolledBackPredecessor;$predecessorReceipt=$declaredPhysicalPredecessor.PredecessorReceipt;$predecessorLiveRecord=$declaredPhysicalPredecessor
    }elseif($predecessors.Count-eq1){
        $predecessor=Assert-SynapseAuthorityRolledBackPredecessor -Layout $layout -Entry $predecessors[0].Entry -Journal $predecessors[0].Journal -Bind $Bind -DbPath $DbPath -Token $Token -StructuralOnly:($committed.Count+$recoverable.Count-gt0)
        $predecessorReceipt=New-SynapseAuthorityPredecessorReceipt -Predecessor $predecessor
        $predecessorLiveRecord=[pscustomobject][ordered]@{Entry=$predecessors[0].Entry;Journal=$predecessors[0].Journal;Root=[string]$predecessors[0].Entry.Path;RootFileId128=[string]$predecessors[0].Entry.FileId128;RolledBackPredecessor=$predecessor;PredecessorReceipt=$predecessorReceipt}
    }
    if($failedCleanupTails.Count-eq1){
        if($null-eq$predecessor){Die "SYNAPSE_AUTHORITY_FAILED_SUCCESSOR_CLEANUP_PREDECESSOR_MISSING successor=$($failedCleanupTails[0].Entry.Path)"}
        if(-not(Remove-SynapseDeploymentCleanupTailIfPresent -TransactionRoot ([string]$failedCleanupTails[0].Entry.Path) -ExpectedParent $layout.Epochs -RequireAuthorityFailedSuccessor -ExpectedAuthorityPredecessorReceipt $predecessorReceipt)){
            Die "SYNAPSE_AUTHORITY_FAILED_SUCCESSOR_CLEANUP_AUTHORITY_INVALID predecessor=$($predecessor.Entry.Path) successor=$($failedCleanupTails[0].Entry.Path)"
        }
        return Ensure-SynapseBrokerAuthorityAdopted -RuntimeBinDir $RuntimeBinDir -BootstrapSourcePath $BootstrapSourcePath -PowerShellPath $PowerShellPath -WorkingDirectory $WorkingDirectory -LogDir $LogDir -TaskName $TaskName -ExePath $ExePath -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -Token $Token -MaintenanceLockPath $MaintenanceLockPath -CalyxConfigPath $CalyxConfigPath -ExpectedCalyxConfigSha256 $ExpectedCalyxConfigSha256 -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions -RequireCommitted:$RequireCommitted -DecommissionStructuralOnly:$DecommissionStructuralOnly -RecoveryOnly:$RecoveryOnly -HealthTimeoutSeconds $HealthTimeoutSeconds
    }
    if($committedPredecessorCleanupTails.Count-eq1){
        if($committed.Count-ne1){Die "SYNAPSE_AUTHORITY_COMMITTED_PREDECESSOR_CLEANUP_SUCCESSOR_MISSING predecessor=$($committedPredecessorCleanupTails[0].Entry.Path) committed=$($committed.Count)"}
        $tailRecord=[pscustomobject][ordered]@{Entry=$committedPredecessorCleanupTails[0].Entry;Journal=$null;Root=[string]$committedPredecessorCleanupTails[0].Entry.Path;RootFileId128=[string]$committedPredecessorCleanupTails[0].Tail.RootFileId128;CleanupTail=$committedPredecessorCleanupTails[0].Tail;PredecessorReceipt=(ConvertTo-SynapseCanonicalValue -Value $committedPredecessorCleanupTails[0].Tail.CleanupAuthority.predecessor_receipt)}
        $successorRecord=[pscustomobject][ordered]@{Entry=$committed[0].Entry;Journal=$committed[0].Journal;Initial=$committed[0].Journal.Initial;Root=[string]$committed[0].Entry.Path;RootFileId128=[string]$committed[0].Entry.FileId128}
        [void](Remove-SynapseAuthorityCommittedSuccessorPredecessor -PredecessorRecord $tailRecord -SuccessorRecord $successorRecord -ExpectedParent $layout.Epochs -Context 'authority_local_resume_committed_predecessor_cleanup')
        return Ensure-SynapseBrokerAuthorityAdopted -RuntimeBinDir $RuntimeBinDir -BootstrapSourcePath $BootstrapSourcePath -PowerShellPath $PowerShellPath -WorkingDirectory $WorkingDirectory -LogDir $LogDir -TaskName $TaskName -ExePath $ExePath -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -Token $Token -MaintenanceLockPath $MaintenanceLockPath -CalyxConfigPath $CalyxConfigPath -ExpectedCalyxConfigSha256 $ExpectedCalyxConfigSha256 -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions -RequireCommitted:$RequireCommitted -DecommissionStructuralOnly:$DecommissionStructuralOnly -RecoveryOnly:$RecoveryOnly -HealthTimeoutSeconds $HealthTimeoutSeconds
    }
    foreach($physicalFailed in @($physicalFailedSuccessors)){
        $physicalReceiptJson=Get-SynapseCanonicalJson -Value $physicalFailed.PredecessorReceipt
        $boundToLivePredecessor=($null-ne$predecessor -and $physicalReceiptJson-ceq(Get-SynapseCanonicalJson -Value $predecessorReceipt))
        $boundToCommittedSuccessor=($committed.Count-eq1 -and $null-ne$committed[0].Journal.Initial.predecessor_authority_receipt -and $physicalReceiptJson-ceq(Get-SynapseCanonicalJson -Value $committed[0].Journal.Initial.predecessor_authority_receipt))
        if(-not$boundToLivePredecessor -and -not$boundToCommittedSuccessor){Die "SYNAPSE_AUTHORITY_PHYSICAL_FAILED_SUCCESSOR_PREDECESSOR_INVALID successor=$($physicalFailed.Entry.Path) predecessor_present=$($null-ne$predecessor) committed=$($committed.Count)"}
        # The torn predecessor_restored child is immutable, inert history.  It
        # is never an owner and never grants cleanup authority.  Before the
        # predecessor is superseded it is bound to that live receipt; after an
        # exact committed successor removes the predecessor, the successor's
        # own immutable receipt preserves the same crossbind.  Retaining this
        # bounded record avoids inventing a root-local deletion decision whose
        # last-file/root crash cut would be non-recoverable.
        $physicalAnchor=if($boundToLivePredecessor){[string]$predecessor.Entry.Path}else{[string]$committed[0].Entry.Path}
        Info "SYNAPSE_AUTHORITY_PHYSICAL_FAILED_SUCCESSOR_ARCHIVED successor=$($physicalFailed.Entry.Path) receipt_anchor=$physicalAnchor archive_count=$($physicalFailedSuccessors.Count) archive_bound=$($script:SynapseAuthorityMaxEpochs-1) reason=torn_terminal_cut_preserved_non_owner"
    }
    $successors=@($committed)+@($recoverable)
    if($successors.Count-eq1){
        $declared=$successors[0].Journal.Initial.predecessor_authority_receipt
        if($null-ne$predecessor){
            if($null-eq$declared){Die "SYNAPSE_AUTHORITY_SUCCESSOR_PREDECESSOR_RECEIPT_MISSING predecessor=$($predecessor.Entry.Path) successor=$($successors[0].Entry.Path)"}
            [void](Assert-SynapseAuthorityPredecessorSuccessorPair -PredecessorRecord $predecessorLiveRecord -SuccessorInitial $successors[0].Journal.Initial -SuccessorRoot ([string]$successors[0].Entry.Path) -Context 'authority_local_pair')
        }elseif($null-ne$declared -and $recoverable.Count-eq1){
            Die "SYNAPSE_AUTHORITY_PRECOMMIT_PREDECESSOR_MISSING successor=$($successors[0].Entry.Path) predecessor=$($declared.journal.transaction_root)"
        }
    }
    if($failedSuccessors.Count-eq1){
        if($null-eq$predecessor){Die "SYNAPSE_AUTHORITY_FAILED_SUCCESSOR_PREDECESSOR_MISSING successor=$($failedSuccessors[0].Entry.Path)"}
        $failedInitial=$failedSuccessors[0].Journal.Initial;$declared=$failedInitial.predecessor_authority_receipt
        $terminalDetail=Assert-SynapseAuthorityRollbackTerminalDetail -Detail $failedSuccessors[0].TerminalSlot.LexicalPayload.detail -Initial $failedInitial -Allocation $failedSuccessors[0].Journal.Allocation -Context "failed_successor_$($failedSuccessors[0].Entry.Path)"
        if($null-eq$declared -or (Get-SynapseCanonicalJson -Value $declared)-cne(Get-SynapseCanonicalJson -Value $predecessorReceipt) -or [string]$terminalDetail.mode-cne'predecessor_restored'){
            Die "SYNAPSE_AUTHORITY_FAILED_SUCCESSOR_CROSSBIND_INVALID predecessor=$($predecessor.Entry.Path) successor=$($failedSuccessors[0].Entry.Path)"
        }
        $cleanupAuthorization=[ordered]@{schema='synapse_authority_failed_successor_cleanup/v1';predecessor_receipt=(ConvertTo-SynapseCanonicalValue -Value $predecessorReceipt);predecessor_receipt_sha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $predecessorReceipt)).ToUpperInvariant();failed_terminal_detail_sha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $terminalDetail)).ToUpperInvariant()}
        [void](Remove-SynapseDeploymentTransactionArtifact -Path ([string]$failedSuccessors[0].Entry.Path) -ExpectedRoot $layout.Epochs -ExpectedState rolled_back -Reason 'authority_failed_successor_predecessor_restored' -Domain authority -CleanupAuthorization $cleanupAuthorization)
        return Ensure-SynapseBrokerAuthorityAdopted -RuntimeBinDir $RuntimeBinDir -BootstrapSourcePath $BootstrapSourcePath -PowerShellPath $PowerShellPath -WorkingDirectory $WorkingDirectory -LogDir $LogDir -TaskName $TaskName -ExePath $ExePath -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -Token $Token -MaintenanceLockPath $MaintenanceLockPath -CalyxConfigPath $CalyxConfigPath -ExpectedCalyxConfigSha256 $ExpectedCalyxConfigSha256 -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions -RequireCommitted:$RequireCommitted -DecommissionStructuralOnly:$DecommissionStructuralOnly -RecoveryOnly:$RecoveryOnly -HealthTimeoutSeconds $HealthTimeoutSeconds
    }

    if($RequireCommitted -and $recoverable.Count -ne 0){
        Die "SYNAPSE_BROKER_AUTHORITY_COMMITTED_REQUIRED_RECOVERY_PENDING root=$($recoverable[0].Entry.Path) state=$($recoverable[0].Journal.State) remediation=run ordinary setup recovery before an operator lifecycle mode; lifecycle control never guesses through an interrupted adoption epoch"
    }
    if($recoverable.Count -eq 1){
        $pending=$recoverable[0]
        $journal=$pending.Journal
        $initial=$journal.Initial
        if([string]$journal.State -ne 'rolled_back'){
            $validated=Assert-SynapseAuthorityAdoptionInitialDescriptor -Initial $initial -TransactionRoot $pending.Entry.Path -Allocation $journal.Allocation -HistoricalMutableGeneration
            $localTransaction=[pscustomobject][ordered]@{Armed=$true;Committed=$false;Root=[string]$pending.Entry.Path;RootChain=@($journal.RootChain);ParentRoot=$layout.Epochs;InvocationId=[string]$initial.invocation_id;JournalSequence=[int]$journal.Sequence;JournalSha256=[string]$journal.LatestRawSha256;JournalState=[string]$journal.State;StaticTransactionSha256=[string]$initial.static_transaction_sha256}
            $rollbackTerminal=$null
            $active=$validated.ActiveRosterTransition;$parked=$validated.ParkedRosterTransition;$legacyGate=$validated.LegacyGateTransition;$legacyDenial=$validated.LegacyDenialTransition;$legacyMalformed=$validated.LegacyMalformedGateTransition;$legacyAbsence=$validated.LegacyGateAbsence;$probePlans=@($validated.LegacyDenialProbePlans);$controlGate=$validated.ControlGateTransition
            $legacy=if([string]$initial.prior_authority -eq 'legacy'){ConvertTo-SynapseLegacySnapshotPersistedDescriptor -Snapshot $initial.legacy_task}else{$null}
            $probeSlotAuthority=$null
            $rollbackInfrastructure=$null;$rollbackInfrastructureOwned=$false
            if([string]$initial.prior_authority -eq 'legacy'){
                $probeSlotAuthority=Open-SynapseLegacyDenialProbeSlotAuthority -Journal $journal -Context 'authority_predecision_recovery'
                $legacy | Add-Member -NotePropertyName Leases -NotePropertyValue @(Open-SynapseLegacyAuthorityDescriptorLeases -Descriptor $legacy -LegacyDenialTransition $legacyDenial -Context 'authority_predecision_recovery') -Force
            }
            try {
                $rollbackBrokerExpected=[pscustomobject]@{Name=[string]$initial.broker_task.name;XmlSha256=[string]$initial.broker_task.xml_sha256;SecurityDescriptorSha256=[string]$initial.broker_task.security_descriptor_sha256;Execute=[string]$initial.broker_task.execute;Arguments=[string]$initial.broker_task.arguments;WorkingDirectory=[string]$initial.broker_task.working_directory}
                $rollbackBrokerLookup=Get-SynapseScheduledTaskLookupExact -Name ([string]$rollbackBrokerExpected.Name)
                if([bool]$rollbackBrokerLookup.Exists){
                    $rollbackBrokerTask=Assert-SynapseTaskReadbackIdentity -Expected $rollbackBrokerExpected -Kind broker
                    $rollbackInfrastructure=ConvertTo-SynapseAuthorityInfrastructureFromAdoptionReceipt -Layout $layout -Initial $initial -Validated $validated -BrokerTaskReadback $rollbackBrokerTask
                }else{
                    $rollbackInfrastructure=Open-SynapseLatestBrokerTaskInfrastructureForSupersededReceipt -Layout $layout -SupersededReceipt $initial.broker_task_receipt
                    $rollbackInfrastructureOwned=$true
                    Info "SYNAPSE_AUTHORITY_RECOVERY_BROKER_TASK_SUPERSESSION_PROVEN retired_task=$($rollbackBrokerExpected.Name) current_task=$($rollbackInfrastructure.TaskName)"
                }
                if([string]$initial.prior_authority -eq 'legacy'){
                    [void](Resolve-SynapseLegacyCompatibilityProbeBeforePredecessorRestore -Journal $journal -Validated $validated -SlotAuthority $probeSlotAuthority -LegacySnapshot $legacy -PredecessorRecord $predecessorLiveRecord -TaskInfrastructure $rollbackInfrastructure -RuntimeBinDir $RuntimeBinDir -RequestedLegacyTaskName ([string]$initial.task_name) -Bind $Bind -DbPath $DbPath -Token $Token -Context 'authority_predecision_compatibility_before_action_drain')
                    # Park the generated broker lineage before restoring the
                    # legacy gate.  Its supervisor intentionally retains a
                    # shared read lease on the active gate/roster; attempting
                    # to acquire a delete-capable transition lease first is an
                    # unavoidable sharing violation.  The journaled reverse
                    # transition is the shutdown authority and the subsequent
                    # drain proves that no generated reader remains.
                    [void](Invoke-SynapseAuthorityControlTransitionRollback -Transition $controlGate)
                    if($null -ne $active){
                        [void](Invoke-SynapseAuthorityChainedControlRollback -DownstreamTransition $active -UpstreamTransition $parked)
                        if($null -ne $active.RestoredLease){Move-SynapseAuthorityControlLeaseReverse -FromTransition $active -ToTransition $parked}
                    }
                    [void](Wait-SynapseBrokerInnerAuthorityDrained -Infrastructure $rollbackInfrastructure -Bind $Bind -DbPath $DbPath -AllowPriorAuthority -Context 'authority_predecision_recovery_before_legacy_gate_restore')
                    [void](Assert-SynapseLegacyAuthoritySnapshotUnchanged -Snapshot $legacy -LegacyDenialTransition $legacyDenial)
                    $preexistingAuthorityActionIds=@(Get-SynapseLegacyPreexistingAuthorityActionProcessIds -LegacySnapshot $legacy -PriorGeneration $validated.PriorGeneration -Bind $Bind -DbPath $DbPath -Token $Token -LegacyDenialTransition $legacyDenial -Context 'authority_predecision_preexisting_authority')
                    [void](Remove-SynapseLegacyDenialProbeTasksForRecovery -Plans $probePlans -SlotLease $probeSlotAuthority.Lease -LegacySnapshot $legacy -LegacyDenialTransition $legacyDenial -Bind $Bind -DbPath $DbPath -SupervisorPath ([string]$legacyDenial.path) -NotBeforeUtc ([datetime]$initial.armed_at_utc) -ExcludedProcessIds $preexistingAuthorityActionIds -Context 'authority_predecision_recovery')
                    [void](Restore-SynapseLegacyDenialProbeControlState -LegacyGateTransition $legacyGate -MalformedGateTransition $legacyMalformed -AbsencePlan $legacyAbsence -Context 'authority_predecision_recovery')
                    [void](Assert-SynapseLegacyAuthoritySnapshotUnchanged -Snapshot $legacy -LegacyDenialTransition $legacyDenial)
                }
                if([string]$initial.prior_authority -ne 'legacy'){
                    [void](Invoke-SynapseAuthorityControlTransitionRollback -Transition $controlGate)
                    if($null -ne $active){[void](Invoke-SynapseAuthorityChainedControlRollback -DownstreamTransition $active -UpstreamTransition $parked);if($null -ne $active.RestoredLease){Move-SynapseAuthorityControlLeaseReverse -FromTransition $active -ToTransition $parked}}
                }
                [void](Invoke-SynapseAuthorityControlTransitionRollback -Transition $parked)
                [void](Wait-SynapseBrokerInnerAuthorityDrained -Infrastructure $rollbackInfrastructure -Bind $Bind -DbPath $DbPath -AllowPriorAuthority -Context 'authority_predecision_recovery_before_legacy_gate_restore')
                if($null-ne$initial.predecessor_authority_receipt){
                    if($null-eq$predecessorLiveRecord -or $null-eq$predecessorReceipt){Die "SYNAPSE_AUTHORITY_PREDECISION_DECLARED_PREDECESSOR_MISSING root=$($pending.Entry.Path)"}
                    $restored=Restore-SynapseDeclaredAuthorityPredecessorForRollback -PredecessorRecord $predecessorLiveRecord -PredecessorReceipt $predecessorReceipt -CurrentInitial $initial -CurrentValidated $validated -LegacySnapshot $legacy -TaskInfrastructure $rollbackInfrastructure -RuntimeBinDir $RuntimeBinDir -Trigger cold_predecision -PrimaryFailureSha256 '' -Context 'authority_predecision_declared_predecessor'
                    $detail=$restored.Detail
                    $rollbackTerminal=Complete-SynapseAuthorityRollbackTerminalCut -Transaction $localTransaction -Detail $detail -Context 'authority_predecision_predecessor_restored_terminal'
                $borrowedLegacySupervisorLease=if($null-ne$legacyDenial.PreLease){$legacyDenial.PreLease}elseif($null-ne$legacyDenial.RestoredLease){$legacyDenial.RestoredLease}elseif($null-ne$legacyDenial.CanonicalLease){$legacyDenial.CanonicalLease}elseif($null-ne$legacy.PSObject.Properties['SupervisorLease'] -and $null-ne$legacy.SupervisorLease){$legacy.SupervisorLease}else{$null}
                if($null-eq$borrowedLegacySupervisorLease){Die "SYNAPSE_AUTHORITY_PREDECISION_PREDECESSOR_SUPERVISOR_LEASE_MISSING root=$($pending.Entry.Path)"}
                [void](Assert-SynapseGlobalAuthorityPredecessorLive -Record $predecessorLiveRecord -TaskInfrastructure $rollbackInfrastructure -RuntimeBinDir $RuntimeBinDir -RequestedLegacyTaskName ([string]$initial.task_name) -BorrowedLegacySupervisorLease $borrowedLegacySupervisorLease -TimeoutSeconds ([Math]::Min(420,$HealthTimeoutSeconds)))
                    Info "SYNAPSE_BROKER_ADOPTION_PREDECISION_RECOVERY_COMPLETE root=$($pending.Entry.Path) prior_authority=$($initial.prior_authority) mode=predecessor_restored terminal_retained=true"
                }elseif([string]$initial.prior_authority -eq 'legacy'){
                    $rollbackAuthority=Resolve-SynapseLegacyRollbackAuthority -Journal $journal -Validated $validated -SlotAuthority $probeSlotAuthority -LegacySnapshot $legacy -PriorGeneration $validated.PriorGeneration -Transaction $localTransaction -Trigger cold_predecision -PrimaryFailureSha256 '' -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -Token $Token -HealthTimeoutSeconds $HealthTimeoutSeconds -Context 'authority_predecision_recovery'
                    $rollbackTerminal=$rollbackAuthority.TerminalResult
                    Info "SYNAPSE_BROKER_ADOPTION_PREDECISION_RECOVERY_COMPLETE root=$($pending.Entry.Path) prior_authority=legacy mode=$($rollbackAuthority.Mode) prior_pid=$($rollbackAuthority.Health.pid) terminal_retained=true"
                }else{
                    $brokerExpected=[pscustomobject]@{Name=[string]$initial.broker_task.name;XmlSha256=[string]$initial.broker_task.xml_sha256;SecurityDescriptorSha256=[string]$initial.broker_task.security_descriptor_sha256;Execute=[string]$initial.broker_task.execute;Arguments=[string]$initial.broker_task.arguments;WorkingDirectory=[string]$initial.broker_task.working_directory}
                    $brokerReadback=Assert-SynapseTaskReadbackIdentity -Expected $brokerExpected -Kind broker
                    $freshInfrastructure=ConvertTo-SynapseAuthorityInfrastructureFromAdoptionReceipt -Layout $layout -Initial $initial -Validated $validated -BrokerTaskReadback $brokerReadback
                    [void](Restore-SynapseAuthorityTransitionPostCanonical -Transition $legacyGate -Allocation $journal.Allocation -Context 'authority_predecision_fresh_floor_gate')
                    [void](Restore-SynapseAuthorityTransitionPostCanonical -Transition $legacyDenial -Allocation $journal.Allocation -Context 'authority_predecision_fresh_floor_denial')
                    $inert=Assert-SynapseBrokerInertAtFreshMonotonicFloor -Layout $layout -Infrastructure $freshInfrastructure -LegacyGateTransition $legacyGate -LegacyDenialTransition $legacyDenial -LegacyTaskName ([string]$initial.task_name) -Bind $Bind -DbPath $DbPath
                    $authorityEvidence=[ordered]@{schema='synapse_authority_fresh_monotonic_floor/v1';legacy_gate=[ordered]@{path=[string]$legacyGate.path;file_id_128=([string]$legacyGate.post_file_id_128).ToUpperInvariant();sha256=([string]$legacyGate.post_sha256).ToUpperInvariant();length=[int64]$legacyGate.post_length};legacy_denial_stub=[ordered]@{path=[string]$legacyDenial.path;file_id_128=([string]$legacyDenial.post_file_id_128).ToUpperInvariant();sha256=([string]$legacyDenial.post_sha256).ToUpperInvariant();length=[int64]$legacyDenial.post_length};legacy_task_absent=$true;control_gate_absent=$true;roster_absent=$true;broker_task=(ConvertTo-SynapseCanonicalValue -Value $initial.broker_task);broker_task_inert=$true;action_process_count=0;target_process_count=0;listener_count=0;supervisor_process_count=0;recovery_job_count=0}
                    $detail=[ordered]@{schema='synapse_authority_rollback/v2';mode='fresh_monotonic_floor';trigger='cold_predecision';primary_failure_sha256='';prior_authority='absent';authority_restored='fresh_monotonic_floor';broker_identity_sha256=([string]$initial.broker_identity_sha256).ToUpperInvariant();unknown_objects_preserved=$true;authority_evidence=$authorityEvidence}
                    $rollbackTerminal=Complete-SynapseAuthorityRollbackTerminalCut -Transaction $localTransaction -Detail $detail -Context 'authority_predecision_fresh_floor_terminal'
                    [void](Assert-SynapseBrokerInertAtFreshMonotonicFloor -Layout $layout -Infrastructure $freshInfrastructure -LegacyGateTransition $legacyGate -LegacyDenialTransition $legacyDenial -LegacyTaskName ([string]$initial.task_name) -Bind $Bind -DbPath $DbPath)
                    Info "SYNAPSE_BROKER_ADOPTION_PREDECISION_RECOVERY_COMPLETE root=$($pending.Entry.Path) prior_authority=absent mode=$($detail.mode) broker_task=$($brokerExpected.Name) terminal_retained=true"
                }
            } finally {
                Close-SynapseAuthorityControlTransitionLeases -Transitions @($controlGate,$active,$parked,$legacyMalformed,$legacyDenial,$legacyGate)
                Close-SynapseLegacyDenialGateAbsenceLease -AbsencePlan $legacyAbsence
                if($null -ne $probeSlotAuthority -and [bool]$probeSlotAuthority.Owned -and $null -ne $probeSlotAuthority.Lease){try{$probeSlotAuthority.Lease.Dispose()}catch{};$probeSlotAuthority.Lease=$null}
                Close-SynapseLegacyAuthoritySnapshotLeases -Snapshot $legacy
                if($rollbackInfrastructureOwned-and$null-ne$rollbackInfrastructure){Close-SynapseBrokerTaskReceiptInfrastructure -Infrastructure $rollbackInfrastructure;$rollbackInfrastructure=$null}
            }
            # A durable rolled_back record is not the terminal cleanup receipt.
            # Re-read it from disk, complete the exact rescue/inertness cleanup
            # in this invocation, and only then permit a replacement epoch.
            $rolledBackJournal=Read-SynapseDeploymentTransactionJournal -TransactionRoot ([string]$pending.Entry.Path)
            if([string]$rolledBackJournal.State-ceq'rolled_back'){$rolledBackMode=[string]$rolledBackJournal.Latest.detail.mode}
            elseif($null-ne$rollbackTerminal -and [string]$rollbackTerminal.Kind-ceq'torn_tail_physical' -and $null-ne$rolledBackJournal.TornTail){$rolledBackMode=[string]$rollbackTerminal.Detail.mode}
            else{Die "SYNAPSE_AUTHORITY_ROLLBACK_DURABLE_RECLASSIFICATION_FAILED root=$($pending.Entry.Path) state=$($rolledBackJournal.State) torn=$($null-ne$rolledBackJournal.TornTail)"}
            if($rolledBackMode-ceq'predecessor_restored'){
                if($null-eq$predecessor -or $null-eq$predecessorReceipt){Die "SYNAPSE_AUTHORITY_RECOVERED_FAILED_SUCCESSOR_PREDECESSOR_MISSING successor=$($pending.Entry.Path)"}
                if([string]$rollbackTerminal.Kind-ceq'torn_tail_physical'){
                    Info "SYNAPSE_AUTHORITY_RECOVERED_FAILED_SUCCESSOR_TORN_RETAINED successor=$($pending.Entry.Path) predecessor=$($predecessor.Entry.Path)"
                    return Ensure-SynapseBrokerAuthorityAdopted -RuntimeBinDir $RuntimeBinDir -BootstrapSourcePath $BootstrapSourcePath -PowerShellPath $PowerShellPath -WorkingDirectory $WorkingDirectory -LogDir $LogDir -TaskName $TaskName -ExePath $ExePath -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -Token $Token -MaintenanceLockPath $MaintenanceLockPath -CalyxConfigPath $CalyxConfigPath -ExpectedCalyxConfigSha256 $ExpectedCalyxConfigSha256 -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions -RequireCommitted:$RequireCommitted -DecommissionStructuralOnly:$DecommissionStructuralOnly -RecoveryOnly:$RecoveryOnly -HealthTimeoutSeconds $HealthTimeoutSeconds
                }
                $restoredDetail=Assert-SynapseAuthorityRollbackTerminalDetail -Detail $rolledBackJournal.Slots[-1].LexicalPayload.detail -Initial $rolledBackJournal.Initial -Allocation $rolledBackJournal.Allocation -Context "recovered_failed_successor_$($pending.Entry.Path)"
                $cleanupAuthorization=[ordered]@{schema='synapse_authority_failed_successor_cleanup/v1';predecessor_receipt=(ConvertTo-SynapseCanonicalValue -Value $predecessorReceipt);predecessor_receipt_sha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $predecessorReceipt)).ToUpperInvariant();failed_terminal_detail_sha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $restoredDetail)).ToUpperInvariant()}
                [void](Remove-SynapseDeploymentTransactionArtifact -Path ([string]$pending.Entry.Path) -ExpectedRoot $layout.Epochs -ExpectedState rolled_back -Reason 'authority_recovered_failed_successor_predecessor_restored' -Domain authority -CleanupAuthorization $cleanupAuthorization)
                return Ensure-SynapseBrokerAuthorityAdopted -RuntimeBinDir $RuntimeBinDir -BootstrapSourcePath $BootstrapSourcePath -PowerShellPath $PowerShellPath -WorkingDirectory $WorkingDirectory -LogDir $LogDir -TaskName $TaskName -ExePath $ExePath -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -Token $Token -MaintenanceLockPath $MaintenanceLockPath -CalyxConfigPath $CalyxConfigPath -ExpectedCalyxConfigSha256 $ExpectedCalyxConfigSha256 -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions -RequireCommitted:$RequireCommitted -DecommissionStructuralOnly:$DecommissionStructuralOnly -RecoveryOnly:$RecoveryOnly -HealthTimeoutSeconds $HealthTimeoutSeconds
            }
            $predecessor=if([string]$rollbackTerminal.Kind-ceq'torn_tail_physical'){New-SynapseAuthorityPhysicalRollbackPredecessor -Entry $pending.Entry -TerminalResult $rollbackTerminal -Validated $validated}else{Assert-SynapseAuthorityRolledBackPredecessor -Layout $layout -Entry $pending.Entry -Journal $rolledBackJournal -Bind $Bind -DbPath $DbPath -Token $Token}
            $predecessorReceipt=New-SynapseAuthorityPredecessorReceipt -Predecessor $predecessor
            $predecessorLiveRecord=[pscustomobject][ordered]@{Entry=$pending.Entry;Journal=$rolledBackJournal;Root=[string]$pending.Entry.Path;RootFileId128=[string]$pending.Entry.FileId128;RolledBackPredecessor=$predecessor;PredecessorReceipt=$predecessorReceipt}
        }
    }

    if($RecoveryOnly){
        return [pscustomobject][ordered]@{
            RecoveryCompleted=$true
            Layout=$layout
            Committed=$false
            AuthorityEpoch=0L
            ControlNonce=''
        }
    }

    if($committed.Count -eq 1){
        $record=$committed[0];$initial=$record.Journal.Initial
        $validated=Assert-SynapseAuthorityAdoptionInitialDescriptor -Initial $initial -TransactionRoot $record.Entry.Path -Allocation $record.Journal.Allocation -HistoricalMutableGeneration -AllowRetiredControlPostimage
        $receiptLegacyTaskName=[string]$initial.task_name
        if($TaskName -cne $receiptLegacyTaskName){Die "SYNAPSE_AUTHORITY_COMMITTED_LOGICAL_TASK_NAME_MISMATCH requested=$TaskName receipt=$receiptLegacyTaskName remediation=the committed adoption receipt defines the only legacy fixed-name namespace whose absence or retained definition is authoritative"}
        if([string]$initial.prior_authority -eq 'legacy'){
            [void](Assert-SynapseLegacyAuthoritySnapshotUnchanged -Snapshot $initial.legacy_task)
        }elseif(Test-SynapseScheduledTaskExistsExact -Name $receiptLegacyTaskName){
            Die "SYNAPSE_AUTHORITY_COMMITTED_FRESH_LEGACY_TASK_APPEARED task=$receiptLegacyTaskName"
        }
        $brokerExpected=[pscustomobject]@{Name=[string]$initial.broker_task.name;XmlSha256=[string]$initial.broker_task.xml_sha256;SecurityDescriptorSha256=[string]$initial.broker_task.security_descriptor_sha256;Execute=[string]$initial.broker_task.execute;Arguments=[string]$initial.broker_task.arguments;WorkingDirectory=[string]$initial.broker_task.working_directory;State=[string]$initial.broker_task.state}
        $brokerLookup=Get-SynapseScheduledTaskLookupExact -Name ([string]$brokerExpected.Name)
        $taskSupersessionInfrastructure=$null
        if([bool]$brokerLookup.Exists){
            $brokerTask=Assert-SynapseTaskReadbackIdentity -Expected $brokerExpected -Kind broker
        }else{
            # Task implementation epochs are forward-only and may supersede the
            # task embedded in an older adoption while that adoption's parked
            # broker process is still draining a crash-spanning transaction.
            # Prove the complete immutable successor chain; the historical
            # descriptor remains the only authority for that retained process.
            $taskSupersessionInfrastructure=Open-SynapseLatestBrokerTaskInfrastructureForSupersededReceipt -Layout $layout -SupersededReceipt $initial.broker_task_receipt
            $brokerTask=$brokerExpected
            Info "SYNAPSE_BROKER_ADOPTION_TASK_SUPERSESSION_VERIFIED historical_task=$($brokerExpected.Name) successor_task=$($taskSupersessionInfrastructure.TaskName)"
        }
        $legacyGateState=Get-SynapsePhysicalRelativeState -ParentPath $validated.LegacyGateTransition.parent -ParentChain $validated.LegacyGateTransition.parent_chain -Leaf $validated.LegacyGateTransition.leaf
        if(-not(Test-SynapsePhysicalStateExact -State $legacyGateState -ExpectedExists $true -ExpectedFileId128 $validated.LegacyGateTransition.post_file_id_128 -ExpectedSha256 $validated.LegacyGateTransition.post_sha256 -ExpectedLength $validated.LegacyGateTransition.post_length)){Die "SYNAPSE_AUTHORITY_COMMITTED_LEGACY_GATE_DRIFT path=$($validated.LegacyGateTransition.path)"}
        $legacyDenialState=Get-SynapsePhysicalRelativeState -ParentPath $validated.LegacyDenialTransition.parent -ParentChain $validated.LegacyDenialTransition.parent_chain -Leaf $validated.LegacyDenialTransition.leaf
        if(-not(Test-SynapsePhysicalStateExact -State $legacyDenialState -ExpectedExists $true -ExpectedFileId128 $validated.LegacyDenialTransition.post_file_id_128 -ExpectedSha256 $validated.LegacyDenialTransition.post_sha256 -ExpectedLength $validated.LegacyDenialTransition.post_length)){
            Die "SYNAPSE_AUTHORITY_COMMITTED_LEGACY_DENIAL_STUB_DRIFT path=$($validated.LegacyDenialTransition.path) prior_authority=$($initial.prior_authority) remediation=the permanent legacy launch endpoint is monotonic broker infrastructure; missing, restored, or unknown bytes never regain daemon authority"
        }
        if([string]$initial.prior_authority -eq 'legacy'){
            [void](Assert-SynapseLegacyDenialProbeCommittedControlState -Plans @($validated.LegacyDenialProbePlans) -LegacyGateTransition $validated.LegacyGateTransition -MalformedGateTransition $validated.LegacyMalformedGateTransition -LegacyDenialTransition $validated.LegacyDenialTransition -GateAbsence $validated.LegacyGateAbsence -Context 'authority_committed_recovery')
        }
        # The adoption receipt proves the immutable broker epoch, not the
        # forever-current application generation.  A later broker-aware app
        # transaction may legitimately advance a fresh-host parked roster to
        # an active candidate, or leave either prior/candidate parked while its
        # own journal is being recovered.  Derive the physical pair state from
        # the exact current gate; app-journal reconciliation decides which
        # generation is authorized next.
        $currentGateReadback=Read-SynapseAuthorityControlGateCurrent -Layout $layout -Context 'authority_committed_control_gate_classification'
        $expectedControlState=[string]$currentGateReadback.Payload.state
        if($AllowMissingTokenWhenParked-and$expectedControlState-cne'parked'){Die "SYNAPSE_BROKER_AUTHORITY_MISSING_TOKEN_ACTIVE_REFUSED state=$expectedControlState remediation=restore the exact committed token before controlling an active generation"}
        $controlPair=Read-SynapseAuthorityActiveControlPair -Layout $layout -ExpectedState $expectedControlState -Context 'authority_committed_control_pair'
        $roster=$controlPair.Roster
        if($null-ne$taskSupersessionInfrastructure-and$expectedControlState-ceq'active'){
            # A task rotation must never retire the task still named by the
            # active immutable roster.  Older setup revisions did so after
            # proving only a zero Scheduler-instance predecessor, stranding
            # the active generation because every successor broker is bound
            # to a different identity.  The committed task-create receipt is
            # the original create-only authority; restore only that exact task
            # while the exact active gate/roster and complete successor chain
            # are continuously retained and cross-bound.
            $brokerTask=Restore-SynapseActiveBrokerTaskFromCommittedReceipt -Layout $layout -AuthorityInitial $initial -ControlPair $controlPair -TaskSupersessionInfrastructure $taskSupersessionInfrastructure
        }
        $infrastructure=ConvertTo-SynapseAuthorityInfrastructureFromAdoptionReceipt -Layout $layout -Initial $initial -Validated $validated -BrokerTaskReadback $brokerTask
        $rosterIdentity=[pscustomobject]@{Path=$layout.RosterPath;FileId128=[string]$roster.FileId128;Sha256=[string]$roster.Sha256;Length=[int64]$roster.Length}
        if([string]$record.Journal.Latest.detail.prior_authority -cne [string]$initial.prior_authority -or [string]$record.Journal.Latest.detail.broker_identity_sha256 -ine [string]$initial.broker_identity_sha256){Die "SYNAPSE_AUTHORITY_COMMITTED_DECISION_CROSSBIND_INVALID root=$($record.Entry.Path)"}
        if($expectedControlState -eq 'active'){
            $currentGeneration=ConvertTo-SynapseAuthorityGenerationFromCurrentRoster -Layout $layout -Infrastructure $infrastructure -ControlGate $controlPair.Gate -Roster $roster -Context 'authority_committed_current_generation'
            $currentToken=Read-SynapseAuthorityGenerationToken -Generation $currentGeneration -Context 'authority_committed_current_generation'
            $proof=if($DecommissionStructuralOnly){
                # Removal must be able to retire an exact committed generation
                # whose daemon is crash-looping under the current hard resource
                # policy.  This mode grants no start/adoption authority: the
                # decommission transaction below independently binds and drains
                # the exact Scheduler/control/Job/process objects before deletion.
                [pscustomobject][ordered]@{DaemonPid=0;DecommissionStructuralOnly=$true}
            }else{
                Wait-SynapseBrokerGenerationOperational -Layout $layout -Infrastructure $infrastructure -Generation $currentGeneration -ControlGateIdentity ([pscustomobject]@{Path=$controlPair.Gate.Path;FileId128=$controlPair.Gate.FileId128;Sha256=$controlPair.Gate.Sha256;Length=$controlPair.Gate.Length}) -RosterIdentity $rosterIdentity -ControlGateLease $controlPair.GateLease -RosterLease $controlPair.RosterLease -Bind ([string]$currentGeneration.RosterPayload.bind) -DbPath ([string]$currentGeneration.RosterPayload.db_path) -ProfilesDir ([string]$currentGeneration.RosterPayload.profiles_dir) -LogDir ([string]$currentGeneration.RosterPayload.log_dir) -Token $currentToken -AllowedPermissions ([string]$currentGeneration.RosterPayload.allowed_permissions) -CalyxConfigPath ([string]$currentGeneration.CalyxConfig.path) -ExpectedCalyxConfigSha256 ([string]$currentGeneration.CalyxConfig.sha256) -TimeoutSeconds $HealthTimeoutSeconds -AllowUnhealthyApplication
            }
        }else{
            $currentGeneration=$null
            $proof=Assert-SynapseBrokerParkedNoAuthority -Layout $layout -Infrastructure $infrastructure -ControlGateIdentity ([pscustomobject]@{Path=$controlPair.Gate.Path;FileId128=$controlPair.Gate.FileId128;Sha256=$controlPair.Gate.Sha256;Length=$controlPair.Gate.Length}) -RosterIdentity $rosterIdentity -ControlGateLease $controlPair.GateLease -RosterLease $controlPair.RosterLease -TaskSupersessionInfrastructure $taskSupersessionInfrastructure -Bind ([string]$roster.Payload.bind) -DbPath ([string]$roster.Payload.db_path) -AllowHistoricalPeakForDecommission:$DecommissionStructuralOnly -TimeoutSeconds $(if($DecommissionStructuralOnly){30}else{360})
        }
        Close-SynapseAuthorityActiveControlPair -Pair $controlPair
        # The committed receipt validator opens exact transition leases while
        # rehydrating the historical transaction.  They are proof-local: the
        # returned authority carries immutable identities, not ownership of
        # those transition handles.  Release them before the next transaction
        # reopens the live gate/roster under its own continuous lease.
        Close-SynapseAuthorityControlTransitionLeases -Transitions @($validated.ControlGateTransition,$validated.ActiveRosterTransition,$validated.ParkedRosterTransition,$validated.LegacyMalformedGateTransition,$validated.LegacyDenialTransition,$validated.LegacyGateTransition)
        Close-SynapseLegacyDenialGateAbsenceLease -AbsencePlan $validated.LegacyGateAbsence
        if($null-ne$taskSupersessionInfrastructure){Close-SynapseBrokerTaskReceiptInfrastructure -Infrastructure $taskSupersessionInfrastructure;$taskSupersessionInfrastructure=$null}
        $generationLabel=if($null -ne $currentGeneration){[string]$currentGeneration.GenerationId}else{'<absent>'};$daemonLabel=if($null -ne $proof.PSObject.Properties['DaemonPid']){[int]$proof.DaemonPid}else{0}
        if($null-ne$predecessorLiveRecord){
            $successorRecord=[pscustomobject][ordered]@{Entry=$record.Entry;Journal=$record.Journal;Initial=$record.Journal.Initial;Root=[string]$record.Entry.Path;RootFileId128=[string]$record.Entry.FileId128}
            [void](Remove-SynapseAuthorityCommittedSuccessorPredecessor -PredecessorRecord $predecessorLiveRecord -SuccessorRecord $successorRecord -ExpectedParent $layout.Epochs -Context 'authority_local_committed_successor_predecessor_cleanup')
            $predecessorLiveRecord=$null;$predecessor=$null;$predecessorReceipt=$null
        }
        Info "SYNAPSE_BROKER_ADOPTION_COMMITTED_RECOVERY_VERIFIED root=$($record.Entry.Path) broker_task=$($brokerTask.Name) prior_authority=$($initial.prior_authority) generation=$generationLabel daemon_pid=$daemonLabel"
        return [pscustomobject][ordered]@{Layout=$layout;Infrastructure=$infrastructure;AuthorityEpoch=[int64]$initial.authority_epoch;ControlNonce=[string]$initial.control_nonce;PriorAuthority=[string]$initial.prior_authority;BrokerTask=$brokerTask;ActiveControlGate=[pscustomobject]@{Path=$controlPair.Gate.Path;FileId128=$controlPair.Gate.FileId128;Sha256=$controlPair.Gate.Sha256;Length=$controlPair.Gate.Length};ActiveRoster=$rosterIdentity;PriorGeneration=$validated.PriorGeneration;CurrentGeneration=$currentGeneration;Initial=$initial;Journal=$record.Journal;Committed=$true;OperationalProof=$proof}
    }

    if($RequireCommitted){
        Die "SYNAPSE_BROKER_AUTHORITY_NOT_ADOPTED runtime_bin=$RuntimeBinDir authority_epochs=$($layout.Epochs) remediation=run ordinary setup once to complete the immutable broker authority migration before using -Start, -Stop, or -Remove"
    }

    if($epochEntries.Count-ge$script:SynapseAuthorityMaxEpochs){
        Die "SYNAPSE_AUTHORITY_EPOCH_ARCHIVE_CAPACITY_EXHAUSTED root=$($layout.Epochs) entries=$($epochEntries.Count) max=$script:SynapseAuthorityMaxEpochs physical_failed_successors=$($physicalFailedSuccessors.Count) remediation=preserve the exact bounded inert archive and current predecessor; repeated torn predecessor-restored cuts exhausted the predeclared authority epoch namespace"
    }

    $predecessorReceipt=if($null-ne$predecessor){New-SynapseAuthorityPredecessorReceipt -Predecessor $predecessor}else{$null}
    $legacySupervisor=[System.IO.Path]::GetFullPath((Join-Path $RuntimeBinDir 'synapse-daemon-supervisor.ps1'))
    $retainedDeniedLegacyFloor=$null
    if(Test-SynapseScheduledTaskExistsExact -Name $TaskName){$retainedDeniedLegacyFloor=Get-SynapseRetainedDeniedLegacyFloor -TaskName $TaskName -RuntimeBinDir $RuntimeBinDir -SupervisorPath $legacySupervisor -LogDir $LogDir -Bind $Bind -DbPath $DbPath}
    $priorAuthority=if($null-ne$retainedDeniedLegacyFloor){'absent'}elseif(Test-SynapseScheduledTaskExistsExact -Name $TaskName){'legacy'}else{'absent'}
    $legacy=$null;$priorHealth=$null;$priorSurface=$null;$priorIdentity=$null
    if($priorAuthority -eq 'legacy'){
        $legacy=Get-SynapseLegacyAuthoritySnapshot -TaskName $TaskName -SupervisorPath $legacySupervisor -LogDir $LogDir -ExePath $ExePath -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -MaintenanceLockPath $MaintenanceLockPath -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions -Reason 'broker_adoption_fresh'
        if($null-ne$predecessorLiveRecord){
            $predecessorSupervisorLease=$legacy.SupervisorLease
            if($null-eq$predecessorSupervisorLease){Die 'SYNAPSE_BROKER_ADOPTION_PREDECESSOR_BORROWED_SUPERVISOR_LEASE_MISSING context=broker_adoption_fresh'}
            $predecessorSupervisorLease.RequireExact('broker_adoption_predecessor_borrowed_supervisor_before_live_proof')
            $incumbent=Assert-SynapseGlobalAuthorityPredecessorLive -Record $predecessorLiveRecord -TaskInfrastructure $null -RuntimeBinDir $RuntimeBinDir -RequestedLegacyTaskName $TaskName -BorrowedLegacySupervisorLease $predecessorSupervisorLease -TimeoutSeconds ([Math]::Min(420,$HealthTimeoutSeconds))
            if([string]$incumbent.Mode-cne[string]$predecessorReceipt.terminal_mode -or [string]$incumbent.Mode-notin@('legacy_prior_unchanged','legacy_direct_recovery')){Die "SYNAPSE_BROKER_ADOPTION_PREDECESSOR_PRIOR_MODE_INVALID expected=$($predecessorReceipt.terminal_mode) actual=$($incumbent.Mode)"}
            $priorHealth=$incumbent.Proof.Health;$priorSurface=$incumbent.Proof.ToolSurface;$priorIdentity=$incumbent.Proof.Identity
            if($null-eq$priorHealth -or $null-eq$priorSurface){Die "SYNAPSE_BROKER_ADOPTION_PREDECESSOR_PRIOR_PROOF_INCOMPLETE mode=$($incumbent.Mode) authority=$($incumbent.Authority)"}
        }else{
            $priorHealth=Invoke-RestMethod -Uri "http://$Bind/health" -Headers @{Authorization="Bearer $Token"} -TimeoutSec 30
            if($priorHealth.ok -ne $true){Die "SYNAPSE_BROKER_ADOPTION_PRIOR_HEALTH_INVALID bind=$Bind ok=$($priorHealth.ok)"}
            $priorSurface=Read-SynapseDaemonToolSurface -Bind $Bind -Token $Token -Health $priorHealth
            $priorIdentity=Get-SynapseLegacySchedulerDaemonIdentityReadback -HealthPid ([int]$priorHealth.pid) -LegacySnapshot $legacy -Context 'broker_adoption_prior_identity'
            if(-not [bool]$priorIdentity.Ok){Die "SYNAPSE_BROKER_ADOPTION_PRIOR_IDENTITY_INVALID detail=$($priorIdentity.Detail)"}
        }
    }else{
        $freshTargets=@(Select-SynapseMcpDeployTargetProcesses -Snapshot @(Get-SynapseMcpProcessSnapshot) -Bind $Bind -DbPath $DbPath)
        $freshListeners=@(Get-SynapseTcpBindListenerSnapshot -Bind $Bind)
        if($freshTargets.Count -ne 0 -or $freshListeners.Count -ne 0){Die "SYNAPSE_BROKER_ADOPTION_FRESH_AUTHORITY_NOT_ABSENT task=$TaskName target_process_count=$($freshTargets.Count) listener_count=$($freshListeners.Count) remediation=a missing task is fresh authority only when the configured daemon process and listener SoTs are also empty"}
    }
    # Complete every refusal-capable fresh-control validation before the
    # permanent TASK_CREATE epoch may make a Registration/Logon/periodic task
    # visible. Registration fires while controls are absent and the immutable
    # broker is required to remain inert.
    $preTaskLegacyGate=Get-SynapsePhysicalRelativeState -ParentPath $layout.RuntimeBinDir -ParentChain $layout.RuntimeChain -Leaf $layout.LegacyGateLeaf
    $preTaskLegacyDenial=Get-SynapsePhysicalRelativeState -ParentPath $layout.RuntimeBinDir -ParentChain $layout.RuntimeChain -Leaf 'synapse-daemon-supervisor.ps1'
    $preTaskControlGate=Get-SynapsePhysicalRelativeState -ParentPath $layout.Root -ParentChain $layout.RootChain -Leaf $layout.ControlGateLeaf
    $preTaskRoster=Get-SynapsePhysicalRelativeState -ParentPath $layout.Root -ParentChain $layout.RootChain -Leaf $layout.RosterLeaf
    $predecessorFloorGate=($null-ne$predecessorReceipt -and [string]$predecessorReceipt.terminal_mode-ceq'fresh_monotonic_floor')
    $legacyGateAllowed=if($null-ne$retainedDeniedLegacyFloor){Test-SynapsePhysicalStateExact -State $preTaskLegacyGate -ExpectedExists $true -ExpectedFileId128 ([string]$retainedDeniedLegacyFloor.legacy_gate.file_id_128) -ExpectedSha256 ([string]$retainedDeniedLegacyFloor.legacy_gate.sha256) -ExpectedLength ([int64]$retainedDeniedLegacyFloor.legacy_gate.length)}elseif($predecessorFloorGate){Test-SynapsePhysicalStateExact -State $preTaskLegacyGate -ExpectedExists $true -ExpectedFileId128 ([string]$predecessorReceipt.authority_descriptor.legacy_gate.file_id_128) -ExpectedSha256 ([string]$predecessorReceipt.authority_descriptor.legacy_gate.sha256) -ExpectedLength ([int64]$predecessorReceipt.authority_descriptor.legacy_gate.length)}else{-not[bool]$preTaskLegacyGate.Exists}
    $legacyDenialAllowed=if($priorAuthority-ceq'legacy'){
        Test-SynapsePhysicalStateExact -State $preTaskLegacyDenial -ExpectedExists $true -ExpectedFileId128 ([string]$legacy.supervisor.file_id_128) -ExpectedSha256 ([string]$legacy.supervisor.sha256) -ExpectedLength ([int64]$legacy.supervisor.length)
    }elseif($null-ne$retainedDeniedLegacyFloor){Test-SynapsePhysicalStateExact -State $preTaskLegacyDenial -ExpectedExists $true -ExpectedFileId128 ([string]$retainedDeniedLegacyFloor.legacy_denial_stub.file_id_128) -ExpectedSha256 ([string]$retainedDeniedLegacyFloor.legacy_denial_stub.sha256) -ExpectedLength ([int64]$retainedDeniedLegacyFloor.legacy_denial_stub.length)
    }elseif($predecessorFloorGate){
        Test-SynapsePhysicalStateExact -State $preTaskLegacyDenial -ExpectedExists $true -ExpectedFileId128 ([string]$predecessorReceipt.authority_descriptor.legacy_denial_stub.file_id_128) -ExpectedSha256 ([string]$predecessorReceipt.authority_descriptor.legacy_denial_stub.sha256) -ExpectedLength ([int64]$predecessorReceipt.authority_descriptor.legacy_denial_stub.length)
    }else{-not[bool]$preTaskLegacyDenial.Exists}
    if(-not$legacyGateAllowed -or -not$legacyDenialAllowed -or $preTaskControlGate.Exists -or $preTaskRoster.Exists){Die "SYNAPSE_BROKER_ADOPTION_PRETASK_CONTROL_PRESTATE_INVALID legacy_gate_exists=$($preTaskLegacyGate.Exists) legacy_denial_exists=$($preTaskLegacyDenial.Exists) predecessor_floor=$predecessorFloorGate control_gate_exists=$($preTaskControlGate.Exists) roster_exists=$($preTaskRoster.Exists) remediation=classify/recover the exact prior authority journal before creating any broker task"}
    $infrastructure=Initialize-SynapseAuthorityBrokerInfrastructure -Layout $layout -BootstrapSourcePath $BootstrapSourcePath -PowerShellPath $PowerShellPath -WorkingDirectory $WorkingDirectory -LogDir $LogDir
    $stamp=(Get-Date).ToUniversalTime().ToString('yyyyMMddTHHmmssfffZ');$leaf="deployment-$stamp-$PID"
    $created=[SynapseSetup.AtomicFileV2]::CreatePhysicalDirectoryRelative($layout.Epochs,(Get-SynapsePhysicalChainPaths -Chain $layout.EpochsChain),(Get-SynapsePhysicalChainFileIds -Chain $layout.EpochsChain),$leaf)
    $root=Get-SynapseNormalizedDirectoryPath -Path ([string]$created.Path);$rootChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $root)
    $allocation=New-SynapseDeploymentAllocationContext -TransactionRoot $root -TransactionRootChain $rootChain -InvocationId $script:SynapseSetupInvocationId -OwnerPid $PID
    $previousAllocation=$script:SynapseDeploymentAllocationContext;$script:SynapseDeploymentAllocationContext=$allocation
    $localTransaction=$null;$legacyGateTransition=$null;$legacyDenialTransition=$null;$legacyMalformedGateTransition=$null;$legacyGateAbsence=$null;$legacyDenialProbePlans=@();$legacyDenialProbeReceipts=@();$legacyRecoveryKeeperScript=$null;$probeSlotAuthority=$null;$controlGateTransition=$null;$parkedTransition=$null;$activeTransition=$null;$predecessorCleanupProgressSlots=@()
    try {
        New-SynapseDeploymentPreallocatedJournalSlots -Context $allocation
        $predecessorCleanupProgressSlots=@(1..3|ForEach-Object{$cleanupText='{0:D2}'-f$_;New-SynapseDeploymentPreallocatedProgressSlot -Context $allocation -Leaf "predecessor-cleanup-$cleanupText.json" -Purpose "authority_predecessor_cleanup_$cleanupText" -MaximumLength 131072})
        $legacyGatePre=Get-SynapsePhysicalRelativeState -ParentPath $layout.RuntimeBinDir -ParentChain $layout.RuntimeChain -Leaf $layout.LegacyGateLeaf
        $legacyDenialPre=Get-SynapsePhysicalRelativeState -ParentPath $layout.RuntimeBinDir -ParentChain $layout.RuntimeChain -Leaf 'synapse-daemon-supervisor.ps1'
        $controlGatePre=Get-SynapsePhysicalRelativeState -ParentPath $layout.Root -ParentChain $layout.RootChain -Leaf $layout.ControlGateLeaf
        $rosterPre=Get-SynapsePhysicalRelativeState -ParentPath $layout.Root -ParentChain $layout.RootChain -Leaf $layout.RosterLeaf
        $legacyGateAllowed=if($null-ne$retainedDeniedLegacyFloor){Test-SynapsePhysicalStateExact -State $legacyGatePre -ExpectedExists $true -ExpectedFileId128 ([string]$retainedDeniedLegacyFloor.legacy_gate.file_id_128) -ExpectedSha256 ([string]$retainedDeniedLegacyFloor.legacy_gate.sha256) -ExpectedLength ([int64]$retainedDeniedLegacyFloor.legacy_gate.length)}elseif($predecessorFloorGate){Test-SynapsePhysicalStateExact -State $legacyGatePre -ExpectedExists $true -ExpectedFileId128 ([string]$predecessorReceipt.authority_descriptor.legacy_gate.file_id_128) -ExpectedSha256 ([string]$predecessorReceipt.authority_descriptor.legacy_gate.sha256) -ExpectedLength ([int64]$predecessorReceipt.authority_descriptor.legacy_gate.length)}else{-not[bool]$legacyGatePre.Exists}
        $legacyDenialAllowed=if($priorAuthority-ceq'legacy'){
            Test-SynapsePhysicalStateExact -State $legacyDenialPre -ExpectedExists $true -ExpectedFileId128 ([string]$legacy.supervisor.file_id_128) -ExpectedSha256 ([string]$legacy.supervisor.sha256) -ExpectedLength ([int64]$legacy.supervisor.length)
        }elseif($null-ne$retainedDeniedLegacyFloor){Test-SynapsePhysicalStateExact -State $legacyDenialPre -ExpectedExists $true -ExpectedFileId128 ([string]$retainedDeniedLegacyFloor.legacy_denial_stub.file_id_128) -ExpectedSha256 ([string]$retainedDeniedLegacyFloor.legacy_denial_stub.sha256) -ExpectedLength ([int64]$retainedDeniedLegacyFloor.legacy_denial_stub.length)
        }elseif($predecessorFloorGate){
            Test-SynapsePhysicalStateExact -State $legacyDenialPre -ExpectedExists $true -ExpectedFileId128 ([string]$predecessorReceipt.authority_descriptor.legacy_denial_stub.file_id_128) -ExpectedSha256 ([string]$predecessorReceipt.authority_descriptor.legacy_denial_stub.sha256) -ExpectedLength ([int64]$predecessorReceipt.authority_descriptor.legacy_denial_stub.length)
        }else{-not[bool]$legacyDenialPre.Exists}
        if(-not$legacyGateAllowed -or -not$legacyDenialAllowed -or $controlGatePre.Exists -or $rosterPre.Exists){Die "SYNAPSE_BROKER_ADOPTION_FRESH_CONTROL_PRESTATE_INVALID legacy_gate_exists=$($legacyGatePre.Exists) legacy_denial_exists=$($legacyDenialPre.Exists) predecessor_floor=$predecessorFloorGate control_gate_exists=$($controlGatePre.Exists) roster_exists=$($rosterPre.Exists)"}
        if($null-ne$predecessorReceipt -and [int64]$predecessorReceipt.authority_epoch-eq[int64]::MaxValue){Die 'SYNAPSE_AUTHORITY_PREDECESSOR_EPOCH_EXHAUSTED'}
        $epoch=if($null-ne$predecessorReceipt){[int64]$predecessorReceipt.authority_epoch+1L}else{1L}
        $controlNonce=(Get-SynapseSha256Hex -Text "synapse-authority-control:$($infrastructure.BrokerIdentitySha256):${epoch}:$($script:SynapseSetupInvocationId):$root").ToUpperInvariant()
        $gateContent=New-SynapseAuthorityLegacyGateContent -Bind $Bind -DbPath $DbPath -SupervisorPath $legacySupervisor -BrokerIdentitySha256 $infrastructure.BrokerIdentitySha256 -AuthorityEpoch $epoch -InvocationId $script:SynapseSetupInvocationId
        $legacyGateTransition=New-SynapseAuthorityControlTransitionPlan -AllocationContext $allocation -DestinationParent $layout.RuntimeBinDir -DestinationParentChain $layout.RuntimeChain -DestinationLeaf $layout.LegacyGateLeaf -StageLeaf 'legacy-gate-stage.json' -ParkLeaf 'legacy-gate-park.json' -DiscardLeaf 'legacy-gate-discard.json' -ReplacementContent $gateContent -ExpectedPreState $legacyGatePre -Purpose 'broker_adoption_legacy_gate'
        $futureLegacyGate=[pscustomobject]@{Path=$layout.LegacyGatePath;FileId128=[string]$legacyGateTransition.post_file_id_128;Sha256=[string]$legacyGateTransition.post_sha256;Length=[int64]$legacyGateTransition.post_length}
        $parkedPayload=New-SynapseAuthorityRosterPayload -BrokerIdentitySha256 $infrastructure.BrokerIdentitySha256 -TaskCapabilitySha256 $infrastructure.TaskCapabilitySha256 -AuthorityEpoch $epoch -Revision 1 -Mode parked -Role none -BrokerTask $infrastructure.Task -AuthorityRoot $layout.Root -AuthorityRootFileId128 ([string]$layout.RootChain[-1].file_id_128) -RuntimeBinDir $layout.RuntimeBinDir -RuntimeBinFileId128 ([string]$layout.RuntimeChain[-1].file_id_128) -BrokerScript $infrastructure.BrokerScript -Bootstrap $infrastructure.Bootstrap -ControlGatePath $layout.ControlGatePath -ControlNonce $controlNonce -LegacyGate $futureLegacyGate -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -CalyxConfigPath $CalyxConfigPath -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions -PowerShellPath $PowerShellPath -WorkingDirectory $WorkingDirectory -LogDir $LogDir -BrokerBootstrapLogPath $infrastructure.BootstrapLogPath -MaintenanceLockPath $MaintenanceLockPath -InvocationId $script:SynapseSetupInvocationId
        $parkedEnvelope=New-SynapseAuthorityRosterEnvelope -Payload $parkedPayload
        $parkedTransition=New-SynapseAuthorityControlTransitionPlan -AllocationContext $allocation -DestinationParent $layout.Root -DestinationParentChain $layout.RootChain -DestinationLeaf $layout.RosterLeaf -StageLeaf 'roster-parked-stage.json' -ParkLeaf 'roster-pre-park.json' -DiscardLeaf 'roster-parked-discard.json' -ReplacementContent $parkedEnvelope.Text -ExpectedPreState $rosterPre -Purpose 'broker_adoption_parked_roster'
        $brokerDescriptor=ConvertTo-SynapseAuthorityTaskDescriptor -Task $infrastructure.Task
        $immutable=@(
            (ConvertTo-SynapseAuthorityFileDescriptor -Identity $infrastructure.Bootstrap -Role 'broker_bootstrap'),
            (ConvertTo-SynapseAuthorityFileDescriptor -Identity $infrastructure.BrokerScript -Role 'broker_script')
        )
        $legacyDescriptor=$null;$priorDescriptor=$null;$legacyRescueLaunchAttempts=@();$priorGeneration=$null;$activeTransition=$null
        # The canonical legacy supervisor endpoint is denied in both the
        # admitted-legacy and fresh-host branches.  Its exact prestate (present
        # or absent) is journaled so predecision rollback is reversible; after
        # decision the same stub bytes and FILE_ID become monotonic authority
        # infrastructure and a stale fixed-name task cannot regain launch
        # authority even if the positive stop record is damaged.
        $legacySupervisorPreState=$legacyDenialPre
        if($priorAuthority -eq 'legacy' -and -not(Test-SynapsePhysicalStateExact -State $legacySupervisorPreState -ExpectedExists $true -ExpectedFileId128 ([string]$legacy.supervisor.file_id_128) -ExpectedSha256 ([string]$legacy.supervisor.sha256) -ExpectedLength ([int64]$legacy.supervisor.length))){
            Die "SYNAPSE_BROKER_ADOPTION_LEGACY_SUPERVISOR_PRESTATE_DRIFT path=$legacySupervisor expected_file_id_128=$($legacy.supervisor.file_id_128) actual_file_id_128=$($legacySupervisorPreState.FileId128)"
        }
        $legacySupervisorExpected=if($legacySupervisorPreState.Exists){
            [pscustomobject]@{Exists=$true;FileId128=([string]$legacySupervisorPreState.FileId128).ToUpperInvariant();Sha256=([string]$legacySupervisorPreState.Sha256).ToUpperInvariant();Length=[int64]$legacySupervisorPreState.Length}
        }else{[pscustomobject]@{Exists=$false;FileId128='';Sha256='';Length=-1L}}
        $denialContent=New-SynapseLegacyAuthorityDenialStubContent -BrokerIdentitySha256 $infrastructure.BrokerIdentitySha256 -AuthorityEpoch $epoch -TaskCapabilitySha256 $infrastructure.TaskCapabilitySha256
        $legacyDenialTransition=New-SynapseAuthorityControlTransitionPlan -AllocationContext $allocation -DestinationParent $layout.RuntimeBinDir -DestinationParentChain $layout.RuntimeChain -DestinationLeaf 'synapse-daemon-supervisor.ps1' -StageLeaf 'legacy-denial-stub-stage.ps1' -ParkLeaf 'legacy-supervisor-pre-denial.ps1' -DiscardLeaf 'legacy-denial-stub-discard.ps1' -ReplacementContent $denialContent -ExpectedPreState $legacySupervisorExpected -Purpose 'broker_adoption_legacy_denial_stub'
        if($priorAuthority -eq 'legacy'){
            $futureValidGate=[pscustomobject]@{Exists=$true;FileId128=([string]$legacyGateTransition.post_file_id_128).ToUpperInvariant();Sha256=([string]$legacyGateTransition.post_sha256).ToUpperInvariant();Length=[int64]$legacyGateTransition.post_length}
            $legacyMalformedGateTransition=New-SynapseAuthorityControlTransitionPlan -AllocationContext $allocation -DestinationParent $layout.RuntimeBinDir -DestinationParentChain $layout.RuntimeChain -DestinationLeaf $layout.LegacyGateLeaf -StageLeaf 'legacy-denial-malformed-gate-stage.json' -ParkLeaf 'legacy-denial-valid-gate-park.json' -DiscardLeaf 'legacy-denial-malformed-gate-discard.json' -ReplacementContent '{"schema":' -ExpectedPreState $futureValidGate -Purpose 'broker_adoption_legacy_denial_malformed_gate'
            $legacyGateAbsence=New-SynapseLegacyDenialGateAbsencePlan -AllocationContext $allocation -LegacyGateTransition $legacyGateTransition -ParkLeaf 'legacy-denial-valid-gate-absent-park.json'
            $priorToolSurfaceSha256=([string]$priorSurface.tool_surface_sha256).ToUpperInvariant()
            if($priorToolSurfaceSha256 -notmatch '^[0-9A-F]{64}$'){Die "SYNAPSE_BROKER_ADOPTION_PRIOR_TOOL_SURFACE_HASH_INVALID value=$priorToolSurfaceSha256"}
            if([string]::IsNullOrWhiteSpace($effectiveAdoptionRehearsalExePath)){Die 'SYNAPSE_BROKER_ADOPTION_REHEARSAL_EXECUTABLE_MISSING remediation=ordinary setup must bind the exact repo-built candidate before superseding legacy authority'}
