            $rehearsalJournal=Add-SynapseDeploymentTransactionJournalState -State candidate_ready -Payload ([ordered]@{prior_authority='absent';prior_production_rehearsed=$false;legacy_denial_probe_receipts=@();rehearsal='not_applicable_fresh_host';broker_identity_sha256=$infrastructure.BrokerIdentitySha256;task_instance_count=[int]$proof.TaskInstanceCount;target_process_count=0;listener_count=0;broker_process_count=[int]$proof.BrokerProcessCount;outer_bootstrap_pid=[int]$proof.OuterBootstrapPid;broker_pid=[int]$proof.BrokerPid;outer_job_memory_limit_bytes=[uint64]$proof.OuterJob.JobMemoryLimitBytes}) -Transaction $localTransaction
            $rehearsalSlot=$rehearsalJournal.Slots[-1]
            $decision=Add-SynapseDeploymentTransactionJournalState -State commit_decided -Payload ([ordered]@{broker_adoption_decided=$true;prior_authority='absent';rehearsal='not_applicable_fresh_host';legacy_denial_probes_complete=$false;broker_identity_sha256=$infrastructure.BrokerIdentitySha256;authority_epoch=$epoch;control_nonce=$controlNonce;legacy_gate_file_id_128=$legacyGateTransition.post_file_id_128;legacy_gate_sha256=$legacyGateTransition.post_sha256;legacy_gate_length=[int64]$legacyGateTransition.post_length;legacy_denial_stub_file_id_128=$legacyDenialTransition.post_file_id_128;legacy_denial_stub_sha256=$legacyDenialTransition.post_sha256;legacy_denial_stub_length=[int64]$legacyDenialTransition.post_length;legacy_authority_floor=1;control_gate_file_id_128=$controlGateTransition.post_file_id_128;control_gate_sha256=$controlGateTransition.post_sha256;control_gate_length=[int64]$controlGateTransition.post_length;roster_file_id_128=$parkedTransition.post_file_id_128;roster_sha256=$parkedTransition.post_sha256;roster_length=[int64]$parkedTransition.post_length;prior_generation_id='';daemon_pid=0;legacy_task_unchanged=$true;candidate_ready_slot_file_id_128=[string]$rehearsalSlot.FileId128;candidate_ready_slot_sha256=[string]$rehearsalSlot.RawSha256;candidate_ready_slot_length=[int64]$rehearsalSlot.ByteLength;predecessor_superseded=($null-ne$predecessorReceipt);predecessor_receipt_sha256=$(if($null-ne$predecessorReceipt){(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $predecessorReceipt)).ToUpperInvariant()}else{''})}) -Transaction $localTransaction
        }
        $localTransaction.Committed=$true
        if($priorAuthority-ceq'legacy'){
            $proof=Wait-SynapseBrokerGenerationOperational -Layout $layout -Infrastructure $infrastructure -Generation $priorGeneration -ControlGateIdentity $activeControlIdentity -RosterIdentity $activeIdentity -ControlGateLease $controlGateTransition.CanonicalLease -RosterLease $activeTransition.CanonicalLease -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -LogDir $LogDir -Token $Token -AllowedPermissions $AllowedPermissions -CalyxConfigPath $CalyxConfigPath -ExpectedCalyxConfigSha256 $ExpectedCalyxConfigSha256 -TimeoutSeconds $HealthTimeoutSeconds -AllowUnhealthyApplication
        }else{
            $proof=Assert-SynapseBrokerParkedNoAuthority -Layout $layout -Infrastructure $infrastructure -ControlGateIdentity $activeControlIdentity -RosterIdentity $activeIdentity -ControlGateLease $controlGateTransition.CanonicalLease -RosterLease $parkedTransition.CanonicalLease -Bind $Bind -DbPath $DbPath
        }
        if($null-ne$predecessorLiveRecord){
            $successorRecord=[pscustomobject][ordered]@{Journal=$decision;Initial=$decision.Initial;Root=$root;RootFileId128=[string]$decision.RootChain[-1].file_id_128}
            $cleanupRosterLease=if($priorAuthority-ceq'legacy'){$activeTransition.CanonicalLease}else{$parkedTransition.CanonicalLease}
            [void](Remove-SynapseAuthorityCommittedSuccessorPredecessor -PredecessorRecord $predecessorLiveRecord -SuccessorRecord $successorRecord -ExpectedParent $layout.Epochs -ExistingLegacyGateLease $legacyGateTransition.CanonicalLease -ExistingLegacyDenialLease $legacyDenialTransition.CanonicalLease -ExistingControlGateLease $controlGateTransition.CanonicalLease -ExistingRosterLease $cleanupRosterLease -Context 'authority_hot_committed_successor_predecessor_cleanup')
            $predecessorLiveRecord=$null;$predecessor=$null;$predecessorReceipt=$null
        }
        Close-SynapseLegacyAuthoritySnapshotLeases -Snapshot $legacy
        Close-SynapseDeploymentAllocationHandles -Context $allocation -PayloadsOnly
        $script:SynapseDeploymentAllocationContext=$previousAllocation
        $generationLabel=if($null -ne $priorGeneration){[string]$priorGeneration.GenerationId}else{'<absent>'}
        Info "SYNAPSE_BROKER_ADOPTION_COMMITTED root=$root broker_task=$($infrastructure.TaskName) authority_epoch=$epoch prior_authority=$priorAuthority prior_generation=$generationLabel sequence=$($decision.Sequence) legacy_task_unchanged=$TaskName permanent_gate_file_id_128=$($legacyGateTransition.post_file_id_128) control_gate_file_id_128=$($controlGateTransition.post_file_id_128)"
        return [pscustomobject][ordered]@{Layout=$layout;Infrastructure=$infrastructure;AuthorityEpoch=$epoch;ControlNonce=$controlNonce;PriorAuthority=$priorAuthority;BrokerTask=$infrastructure.Task;ActiveControlGate=$activeControlIdentity;ActiveRoster=$activeIdentity;PriorGeneration=$priorGeneration;CurrentGeneration=$priorGeneration;Initial=$initial;Journal=$decision;Committed=$true;LegacyGateTransition=$legacyGateTransition;ControlGateTransition=$controlGateTransition;ActiveRosterTransition=$activeTransition;OperationalProof=$proof}
    } catch {
        $primary=$_.Exception.Message
        $primaryStack=[string]$_.ScriptStackTrace
        if($null -ne $localTransaction -and -not [bool]$localTransaction.Committed){
            try{
                $durableJournal=Read-SynapseDeploymentTransactionJournal -TransactionRoot $root -TransactionRootChain $rootChain
                if([string]$durableJournal.State -eq 'commit_decided'){
                    $localTransaction.Committed=$true
                    Close-SynapseAuthorityControlTransitionLeases -Transitions @($controlGateTransition,$activeTransition,$parkedTransition,$legacyMalformedGateTransition,$legacyDenialTransition,$legacyGateTransition)
                    Close-SynapseLegacyDenialGateAbsenceLease -AbsencePlan $legacyGateAbsence
                    Close-SynapseLegacyAuthoritySnapshotLeases -Snapshot $legacy
                    Close-SynapseDeploymentAllocationHandles -Context $allocation
                    $script:SynapseDeploymentAllocationContext=$previousAllocation
                    Warn "SYNAPSE_BROKER_ADOPTION_DECISION_RECLASSIFIED root=$root primary_error=$primary effect=the durable decision is authoritative; recovery converges and re-proves the broker generation"
                    return Ensure-SynapseBrokerAuthorityAdopted -RuntimeBinDir $RuntimeBinDir -BootstrapSourcePath $BootstrapSourcePath -PowerShellPath $PowerShellPath -WorkingDirectory $WorkingDirectory -LogDir $LogDir -TaskName $TaskName -ExePath $ExePath -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -Token $Token -MaintenanceLockPath $MaintenanceLockPath -CalyxConfigPath $CalyxConfigPath -ExpectedCalyxConfigSha256 $ExpectedCalyxConfigSha256 -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions -HealthTimeoutSeconds $HealthTimeoutSeconds
                }
                if([string]$durableJournal.State -notin @('armed','candidate_ready')){Die "SYNAPSE_BROKER_ADOPTION_ROLLBACK_STATE_INVALID root=$root state=$($durableJournal.State)"}
                $rollbackValidated=Assert-SynapseAuthorityAdoptionInitialDescriptor -Initial $durableJournal.Initial -TransactionRoot $root -Allocation $durableJournal.Allocation
                if((Get-SynapseCanonicalJson -Value (Get-SynapseAuthorityControlTransitionDescriptor $rollbackValidated.LegacyGateTransition)) -cne (Get-SynapseCanonicalJson -Value (Get-SynapseAuthorityControlTransitionDescriptor $legacyGateTransition)) -or
                   (Get-SynapseCanonicalJson -Value (Get-SynapseAuthorityControlTransitionDescriptor $rollbackValidated.LegacyDenialTransition)) -cne (Get-SynapseCanonicalJson -Value (Get-SynapseAuthorityControlTransitionDescriptor $legacyDenialTransition))){Die "SYNAPSE_BROKER_ADOPTION_ROLLBACK_LIVE_TRANSITION_DRIFT root=$root"}
                $rollbackValidated.LegacyGateTransition=$legacyGateTransition
                $rollbackValidated.LegacyDenialTransition=$legacyDenialTransition
                if($priorAuthority -eq 'legacy'){
                    if($null -eq $legacyDenialTransition.PreLease){
                        if($null -eq $legacy.SupervisorLease){Die "SYNAPSE_BROKER_ADOPTION_ROLLBACK_SUPERVISOR_LEASE_MISSING root=$root"}
                        $legacy.SupervisorLease.RequireExact('broker_adoption_normal_rollback_supervisor_handoff')
                        $legacyDenialTransition.PreLease=$legacy.SupervisorLease;$legacy.SupervisorLease=$null
                    }
                    if($null -eq $probeSlotAuthority){$probeSlotAuthority=Open-SynapseLegacyDenialProbeSlotAuthority -Journal $durableJournal -ExistingLease $allocation.JournalSlotHandles[1] -Context 'authority_normal_rollback'}
                    [void](Resolve-SynapseLegacyCompatibilityProbeBeforePredecessorRestore -Journal $durableJournal -Validated $rollbackValidated -SlotAuthority $probeSlotAuthority -LegacySnapshot $legacy -PredecessorRecord $predecessorLiveRecord -TaskInfrastructure $infrastructure -RuntimeBinDir $RuntimeBinDir -RequestedLegacyTaskName ([string]$durableJournal.Initial.task_name) -Bind $Bind -DbPath $DbPath -Token $Token -Context 'authority_normal_compatibility_before_action_drain')
                    [void](Assert-SynapseLegacyAuthoritySnapshotUnchanged -Snapshot $legacy -LegacyDenialTransition $legacyDenialTransition)
                    $preexistingAuthorityActionIds=@(Get-SynapseLegacyPreexistingAuthorityActionProcessIds -LegacySnapshot $legacy -PriorGeneration $rollbackValidated.PriorGeneration -Bind $Bind -DbPath $DbPath -Token $Token -LegacyDenialTransition $legacyDenialTransition -Context 'authority_normal_preexisting_authority')
                    [void](Remove-SynapseLegacyDenialProbeTasksForRecovery -Plans @($rollbackValidated.LegacyDenialProbePlans) -SlotLease $probeSlotAuthority.Lease -LegacySnapshot $legacy -LegacyDenialTransition $legacyDenialTransition -Bind $Bind -DbPath $DbPath -SupervisorPath ([string]$legacyDenialTransition.path) -NotBeforeUtc ([datetime]$durableJournal.Initial.armed_at_utc) -ExcludedProcessIds $preexistingAuthorityActionIds -Context 'authority_normal_rollback')
                    [void](Restore-SynapseLegacyDenialProbeControlState -LegacyGateTransition $legacyGateTransition -MalformedGateTransition $legacyMalformedGateTransition -AbsencePlan $legacyGateAbsence -Context 'authority_normal_rollback')
                    [void](Assert-SynapseLegacyAuthoritySnapshotUnchanged -Snapshot $legacy -LegacyDenialTransition $legacyDenialTransition)
                }
                if($null -ne $controlGateTransition){[void](Invoke-SynapseAuthorityControlTransitionRollback -Transition $controlGateTransition)}
                if($null -ne $activeTransition){[void](Invoke-SynapseAuthorityChainedControlRollback -DownstreamTransition $activeTransition -UpstreamTransition $parkedTransition);if($null -ne $activeTransition.RestoredLease -and $null -ne $parkedTransition){Move-SynapseAuthorityControlLeaseReverse -FromTransition $activeTransition -ToTransition $parkedTransition}}
                if($null -ne $parkedTransition){[void](Invoke-SynapseAuthorityControlTransitionRollback -Transition $parkedTransition)}
                [void](Wait-SynapseBrokerInnerAuthorityDrained -Infrastructure $infrastructure -Bind $Bind -DbPath $DbPath -Context 'authority_normal_rollback_before_legacy_gate_restore')
                if($null-ne$durableJournal.Initial.predecessor_authority_receipt){
                    if($null-eq$predecessorLiveRecord -or $null-eq$predecessorReceipt){Die "SYNAPSE_AUTHORITY_NORMAL_DECLARED_PREDECESSOR_MISSING root=$root"}
                    $restored=Restore-SynapseDeclaredAuthorityPredecessorForRollback -PredecessorRecord $predecessorLiveRecord -PredecessorReceipt $predecessorReceipt -CurrentInitial $durableJournal.Initial -CurrentValidated $rollbackValidated -LegacySnapshot $legacy -TaskInfrastructure $infrastructure -RuntimeBinDir $RuntimeBinDir -Trigger normal_catch -PrimaryFailureSha256 (Get-SynapseSha256Hex -Text $primary) -Context 'authority_normal_declared_predecessor'
                    $detail=$restored.Detail
                    $rollbackTerminal=Complete-SynapseAuthorityRollbackTerminalCut -Transaction $localTransaction -Detail $detail -Context 'authority_normal_predecessor_restored_terminal'
                    $rollbackPredecessorSupervisorLease=if($null-ne$legacyDenialTransition.PreLease){$legacyDenialTransition.PreLease}elseif($null-ne$legacyDenialTransition.RestoredLease){$legacyDenialTransition.RestoredLease}elseif($null-ne$legacyDenialTransition.CanonicalLease){$legacyDenialTransition.CanonicalLease}elseif($null-ne$legacy.SupervisorLease){$legacy.SupervisorLease}else{$null}
                    if($null-eq$rollbackPredecessorSupervisorLease){Die "SYNAPSE_BROKER_ADOPTION_ROLLBACK_PREDECESSOR_SUPERVISOR_LEASE_MISSING root=$root"}
                    $rollbackPredecessorSupervisorLease.RequireExact('broker_adoption_rollback_predecessor_before_live_proof')
                    [void](Assert-SynapseGlobalAuthorityPredecessorLive -Record $predecessorLiveRecord -TaskInfrastructure $infrastructure -RuntimeBinDir $RuntimeBinDir -RequestedLegacyTaskName ([string]$durableJournal.Initial.task_name) -BorrowedLegacySupervisorLease $rollbackPredecessorSupervisorLease -TimeoutSeconds ([Math]::Min(420,$HealthTimeoutSeconds)))
                    Info "SYNAPSE_BROKER_ADOPTION_NORMAL_ROLLBACK_COMPLETE root=$root mode=predecessor_restored terminal_retained=true"
                }elseif($priorAuthority -eq 'legacy'){
                    $rollbackAuthority=Resolve-SynapseLegacyRollbackAuthority -Journal $durableJournal -Validated $rollbackValidated -SlotAuthority $probeSlotAuthority -LegacySnapshot $legacy -PriorGeneration $priorGeneration -Transaction $localTransaction -Trigger normal_catch -PrimaryFailureSha256 (Get-SynapseSha256Hex -Text $primary) -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -Token $Token -HealthTimeoutSeconds $HealthTimeoutSeconds -Context 'authority_normal_rollback'
                    $rollbackTerminal=$rollbackAuthority.TerminalResult
                    Info "SYNAPSE_BROKER_ADOPTION_NORMAL_ROLLBACK_COMPLETE root=$root mode=$($rollbackAuthority.Mode) prior_pid=$($rollbackAuthority.Health.pid) terminal_retained=true"
                }else{
                    $expectedBroker=[pscustomobject]@{Name=$infrastructure.TaskName;XmlSha256=$infrastructure.Task.XmlSha256;SecurityDescriptorSha256=$infrastructure.Task.SecurityDescriptorSha256;Execute=$infrastructure.Task.Execute;Arguments=$infrastructure.Task.Arguments;WorkingDirectory=$infrastructure.Task.WorkingDirectory}
                    [void](Assert-SynapseTaskReadbackIdentity -Expected $expectedBroker -Kind broker)
                    [void](Restore-SynapseAuthorityTransitionPostCanonical -Transition $legacyGateTransition -Allocation $durableJournal.Allocation -Context 'authority_normal_fresh_floor_gate')
                    [void](Restore-SynapseAuthorityTransitionPostCanonical -Transition $legacyDenialTransition -Allocation $durableJournal.Allocation -Context 'authority_normal_fresh_floor_denial')
                    $inert=Assert-SynapseBrokerInertAtFreshMonotonicFloor -Layout $layout -Infrastructure $infrastructure -LegacyGateTransition $legacyGateTransition -LegacyDenialTransition $legacyDenialTransition -LegacyTaskName ([string]$durableJournal.Initial.task_name) -Bind $Bind -DbPath $DbPath
                    $authorityEvidence=[ordered]@{schema='synapse_authority_fresh_monotonic_floor/v1';legacy_gate=[ordered]@{path=[string]$legacyGateTransition.path;file_id_128=([string]$legacyGateTransition.post_file_id_128).ToUpperInvariant();sha256=([string]$legacyGateTransition.post_sha256).ToUpperInvariant();length=[int64]$legacyGateTransition.post_length};legacy_denial_stub=[ordered]@{path=[string]$legacyDenialTransition.path;file_id_128=([string]$legacyDenialTransition.post_file_id_128).ToUpperInvariant();sha256=([string]$legacyDenialTransition.post_sha256).ToUpperInvariant();length=[int64]$legacyDenialTransition.post_length};legacy_task_absent=$true;control_gate_absent=$true;roster_absent=$true;broker_task=(ConvertTo-SynapseCanonicalValue -Value $durableJournal.Initial.broker_task);broker_task_inert=$true;action_process_count=0;target_process_count=0;listener_count=0;supervisor_process_count=0;recovery_job_count=0}
                    $detail=[ordered]@{schema='synapse_authority_rollback/v2';mode='fresh_monotonic_floor';trigger='normal_catch';primary_failure_sha256=(Get-SynapseSha256Hex -Text $primary).ToUpperInvariant();prior_authority='absent';authority_restored='fresh_monotonic_floor';broker_identity_sha256=([string]$durableJournal.Initial.broker_identity_sha256).ToUpperInvariant();unknown_objects_preserved=$true;authority_evidence=$authorityEvidence}
                    $rollbackTerminal=Complete-SynapseAuthorityRollbackTerminalCut -Transaction $localTransaction -Detail $detail -Context 'authority_normal_fresh_floor_terminal'
                    [void](Assert-SynapseBrokerInertAtFreshMonotonicFloor -Layout $layout -Infrastructure $infrastructure -LegacyGateTransition $legacyGateTransition -LegacyDenialTransition $legacyDenialTransition -LegacyTaskName ([string]$durableJournal.Initial.task_name) -Bind $Bind -DbPath $DbPath)
                }
            }catch{Die "SYNAPSE_BROKER_ADOPTION_FAILED_AND_ROLLBACK_FAILED primary=[$primary] primary_stack=[$primaryStack] rollback=[$($_.Exception.Message)] rollback_stack=[$($_.ScriptStackTrace)] root=$root"}
        }
        throw
    } finally {
        if($null -ne $allocation){try{Close-SynapseDeploymentAllocationHandles -Context $allocation}catch{}}
        if($script:SynapseDeploymentAllocationContext -eq $allocation){$script:SynapseDeploymentAllocationContext=$previousAllocation}
        if($null -ne $localTransaction -and -not [bool]$localTransaction.Committed){Close-SynapseAuthorityControlTransitionLeases -Transitions @($controlGateTransition,$activeTransition,$parkedTransition,$legacyMalformedGateTransition,$legacyDenialTransition,$legacyGateTransition)}
        Close-SynapseLegacyDenialGateAbsenceLease -AbsencePlan $legacyGateAbsence
        if($null -ne $legacyRecoveryKeeperScript -and $null -ne $legacyRecoveryKeeperScript.PSObject.Properties['Lease'] -and $null -ne $legacyRecoveryKeeperScript.Lease){try{$legacyRecoveryKeeperScript.Lease.Dispose();$legacyRecoveryKeeperScript.Lease=$null}catch{[Environment]::FailFast('SYNAPSE_LEGACY_RECOVERY_KEEPER_SCRIPT_LEASE_RELEASE_UNPROVEN',$_.Exception)}}
        Close-SynapseLegacyAuthoritySnapshotLeases -Snapshot $legacy
    }
}

function Get-SynapseRuntimeTransactionPlanSha256 {
    param([Parameter(Mandatory=$true)]$Descriptor)
    $copy = ConvertTo-SynapseCanonicalValue -Value $Descriptor
    if ($copy -is [System.Collections.IDictionary]) { [void]$copy.Remove('static_plan_sha256') }
    return (Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $copy)).ToUpperInvariant()
}

function Assert-SynapseRuntimeTransactionDescriptor {
    param(
        [Parameter(Mandatory=$true)]$Descriptor,
        [Parameter(Mandatory=$true)][string]$TransactionRoot,
        [string[]]$ExpectedPaths = @(),
        $Allocation
    )

    $root = Get-SynapseNormalizedDirectoryPath -Path $TransactionRoot
    if ([string]$Descriptor.schema -cne 'synapse_runtime_file_transaction/v1' -or
        (Get-SynapseNormalizedDirectoryPath -Path ([string]$Descriptor.transaction_root)) -ine $root -or
        [string]$Descriptor.volume_filesystem -cne 'NTFS' -or
        [string]$Descriptor.volume_serial_number -notmatch '^[0-9A-Fa-f]{8}$') {
        Die "SYNAPSE_RUNTIME_TRANSACTION_IDENTITY_INVALID root=$root schema=$($Descriptor.schema) filesystem=$($Descriptor.volume_filesystem)"
    }
    $records = @($Descriptor.records)
    if ($records.Count -lt 1 -or $records.Count -gt 96) {
        Die "SYNAPSE_RUNTIME_TRANSACTION_RECORD_BOUND_INVALID root=$root count=$($records.Count) min=1 max=96"
    }
    $paths = @($records | ForEach-Object { [System.IO.Path]::GetFullPath([string]$_.path) })
    $sortedPaths = @($paths | Sort-Object -Unique)
    if ($sortedPaths.Count -ne $paths.Count -or (Get-SynapseCanonicalJson -Value $paths) -cne (Get-SynapseCanonicalJson -Value $sortedPaths)) {
        Die "SYNAPSE_RUNTIME_TRANSACTION_PATH_ORDER_INVALID root=$root"
    }
    if ($ExpectedPaths.Count -gt 0) {
        $expected = @($ExpectedPaths | ForEach-Object { [System.IO.Path]::GetFullPath($_) } | Sort-Object -Unique)
        if ((Get-SynapseCanonicalJson -Value $paths) -cne (Get-SynapseCanonicalJson -Value $expected)) {
            Die "SYNAPSE_RUNTIME_TRANSACTION_MANAGED_PATH_SET_MISMATCH root=$root expected=$($expected -join ',') actual=$($paths -join ',')"
        }
    }
    $volume = [SynapseSetup.AtomicFileV2]::GetStableLocalVolume($root)
    if ([string]$volume.FileSystemName -cne 'NTFS' -or ('{0:X8}' -f [uint32]$volume.VolumeSerialNumber) -ine [string]$Descriptor.volume_serial_number) {
        Die "SYNAPSE_RUNTIME_TRANSACTION_VOLUME_DRIFT root=$root expected_fs=$($Descriptor.volume_filesystem) expected_serial=$($Descriptor.volume_serial_number) actual_fs=$($volume.FileSystemName) actual_serial=$('{0:X8}' -f [uint32]$volume.VolumeSerialNumber)"
    }
    for ($index=0; $index -lt $records.Count; $index++) {
        $record = $records[$index]
        $ordinal = $index + 1
        $recordProperties = @(Get-SynapseObjectPropertyNames -Object $record)
        $expectedRecordProperties = @('path','parent','parent_chain','leaf','pre_existed','pre_file_id_128','pre_sha256','pre_length','post_file_id_128','post_sha256','post_length','stage_leaf','park_leaf','discard_leaf')
        if ($recordProperties.Count -ne $expectedRecordProperties.Count -or
            @($recordProperties | Where-Object { $expectedRecordProperties -cnotcontains $_ }).Count -gt 0) {
            Die "SYNAPSE_RUNTIME_TRANSACTION_RECORD_SHAPE_INVALID ordinal=$ordinal properties=$($recordProperties -join ',')"
        }
        $path = [System.IO.Path]::GetFullPath([string]$record.path)
        $parent = Get-SynapseNormalizedDirectoryPath -Path ([string]$record.parent)
        $leaf = [string]$record.leaf
        if ((Split-Path -Parent $path) -ine $parent -or (Split-Path -Leaf $path) -cne $leaf -or
            [string]$record.stage_leaf -cne ('runtime-stage-{0:D4}.bin' -f $ordinal) -or
            [string]$record.discard_leaf -cne ('runtime-discard-{0:D4}.bin' -f $ordinal) -or
            [string]$record.park_leaf -cne $(if([bool]$record.pre_existed){'runtime-park-{0:D4}.bin' -f $ordinal}else{''}) -or
            $record.pre_existed -isnot [bool] -or [string]$record.post_file_id_128 -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or
            [string]$record.post_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [int64]$record.post_length -lt 0) {
            Die "SYNAPSE_RUNTIME_TRANSACTION_RECORD_INVALID ordinal=$ordinal path=$path"
        }
        $parentChain = @(Assert-SynapsePhysicalDirectoryChainDescriptor -Chain $record.parent_chain -ExpectedPath $parent -Context "runtime_parent_$ordinal")
        $parentVolume = [SynapseSetup.AtomicFileV2]::GetStableLocalVolume($parent)
        if ([string]$parentVolume.FileSystemName -cne 'NTFS' -or [uint32]$parentVolume.VolumeSerialNumber -ne [uint32]$volume.VolumeSerialNumber) {
            Die "SYNAPSE_RUNTIME_TRANSACTION_TARGET_VOLUME_SPLIT ordinal=$ordinal path=$path"
        }
        if (([bool]$record.pre_existed -and ([string]$record.pre_file_id_128 -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or
                [string]$record.pre_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [int64]$record.pre_length -lt 0)) -or
            (-not [bool]$record.pre_existed -and ([string]$record.pre_file_id_128 -or [string]$record.pre_sha256 -or [int64]$record.pre_length -ne -1))) {
            Die "SYNAPSE_RUNTIME_TRANSACTION_PREIMAGE_INVALID ordinal=$ordinal path=$path"
        }
        if ($null -ne $Allocation) {
            foreach ($binding in @(
                [pscustomobject]@{ Leaf=[string]$record.stage_leaf; Kind='file'; Id=[string]$record.post_file_id_128; Sha=[string]$record.post_sha256; Length=[int64]$record.post_length },
                [pscustomobject]@{ Leaf=[string]$record.discard_leaf; Kind='transition_slot'; Id=[string]$record.post_file_id_128; Sha=[string]$record.post_sha256; Length=[int64]$record.post_length }
            )) {
                if (-not $Allocation.Artifacts.ContainsKey($binding.Leaf)) { Die "SYNAPSE_RUNTIME_TRANSACTION_ALLOCATION_BINDING_MISSING ordinal=$ordinal leaf=$($binding.Leaf)" }
                $artifact = $Allocation.Artifacts[$binding.Leaf]
                $ids = if ([string]$artifact.kind -eq 'file') { @([string]$artifact.file_id_128) } else { @($artifact.allowed_file_ids_128) }
                $sha = if ([string]$artifact.kind -eq 'file') { [string]$artifact.sealed_sha256 } else { [string]$artifact.expected_sha256 }
                $length = if ([string]$artifact.kind -eq 'file') { [int64]$artifact.sealed_length } else { [int64]$artifact.expected_length }
                if ([string]$artifact.kind -cne $binding.Kind -or $ids.Count -ne 1 -or $ids -inotcontains $binding.Id -or $sha -ine $binding.Sha -or $length -ne $binding.Length) {
                    Die "SYNAPSE_RUNTIME_TRANSACTION_ALLOCATION_BINDING_INVALID ordinal=$ordinal leaf=$($binding.Leaf)"
                }
            }
            if ([bool]$record.pre_existed) {
                if (-not $Allocation.Artifacts.ContainsKey([string]$record.park_leaf)) { Die "SYNAPSE_RUNTIME_TRANSACTION_PARK_BINDING_MISSING ordinal=$ordinal" }
                $park = $Allocation.Artifacts[[string]$record.park_leaf]
                if ([string]$park.kind -cne 'transition_slot' -or @($park.allowed_file_ids_128).Count -ne 1 -or @($park.allowed_file_ids_128) -inotcontains [string]$record.pre_file_id_128 -or
                    [string]$park.expected_sha256 -ine [string]$record.pre_sha256 -or [int64]$park.expected_length -ne [int64]$record.pre_length) {
                    Die "SYNAPSE_RUNTIME_TRANSACTION_PARK_BINDING_INVALID ordinal=$ordinal"
                }
            }
        }
    }
    $computed = Get-SynapseRuntimeTransactionPlanSha256 -Descriptor $Descriptor
    if ([string]$Descriptor.static_plan_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [string]$Descriptor.static_plan_sha256 -ine $computed) {
        Die "SYNAPSE_RUNTIME_TRANSACTION_PLAN_HASH_MISMATCH root=$root expected=$($Descriptor.static_plan_sha256) actual=$computed"
    }
    return [pscustomobject]@{ Descriptor=$Descriptor; Records=$records; Root=$root; StaticPlanSha256=$computed }
}

function Read-SynapseAuthorityTransitionStageText {
    param(
        [Parameter(Mandatory=$true)]$Transition,
        [Parameter(Mandatory=$true)]$Allocation,
        [ValidateRange(1,1048576)][int]$MaximumBytes=65536,
        [Parameter(Mandatory=$true)][string]$Context,
        [switch]$AllowDiscardedPost
    )
    $artifact=Get-SynapseObjectPropertyValue -Object $Transition -Names @('StageArtifact','stage_artifact')
    if($null-eq$artifact){$artifact=$Allocation.Artifacts[[string]$Transition.stage_leaf]}
    if($null -eq $artifact){Die "SYNAPSE_AUTHORITY_TRANSITION_STAGE_ARTIFACT_MISSING context=$Context leaf=$($Transition.stage_leaf)"}
    $handle=Get-SynapseObjectPropertyValue -Object $artifact -Names @('handle','Handle')
    if($null-eq$handle -and $null-ne$script:SynapseDeploymentAllocationContext -and
       (Get-SynapseNormalizedDirectoryPath -Path ([string]$script:SynapseDeploymentAllocationContext.Root)) -ieq (Get-SynapseNormalizedDirectoryPath -Path ([string]$Transition.transaction_root)) -and
       $script:SynapseDeploymentAllocationContext.Artifacts.ContainsKey([string]$Transition.stage_leaf)){
        $artifact=$script:SynapseDeploymentAllocationContext.Artifacts[[string]$Transition.stage_leaf]
        $handle=Get-SynapseObjectPropertyValue -Object $artifact -Names @('handle','Handle')
    }
    if($null -ne $handle){
        $handle.RequireExact("${Context}_retained")
        $read=$handle.ReadUtf8($MaximumBytes)
    }else{
        $readParent=[string]$Transition.transaction_root
        $readChain=@($Transition.transaction_root_chain)
        $readLeaf=[string]$Transition.stage_leaf
        if($AllowDiscardedPost){
            $stageState=Get-SynapseAuthorityControlRootState -Transition $Transition -Leaf $readLeaf
            if(-not $stageState.Exists){
                $discardState=Get-SynapseAuthorityControlRootState -Transition $Transition -Leaf ([string]$Transition.discard_leaf)
                if(Test-SynapsePhysicalStateExact -State $discardState -ExpectedExists $true -ExpectedFileId128 $Transition.post_file_id_128 -ExpectedSha256 $Transition.post_sha256 -ExpectedLength $Transition.post_length){$readLeaf=[string]$Transition.discard_leaf}
                else{
                    $canonicalState=Get-SynapsePhysicalRelativeState -ParentPath $Transition.parent -ParentChain $Transition.parent_chain -Leaf $Transition.leaf
                    if(Test-SynapsePhysicalStateExact -State $canonicalState -ExpectedExists $true -ExpectedFileId128 $Transition.post_file_id_128 -ExpectedSha256 $Transition.post_sha256 -ExpectedLength $Transition.post_length){
                        $readParent=[string]$Transition.parent;$readChain=@($Transition.parent_chain);$readLeaf=[string]$Transition.leaf
                    }
                }
            }
        }
        $read=Read-SynapsePhysicalRelativeUtf8Text -ParentPath $readParent -ParentChain $readChain -Leaf $readLeaf -ExpectedFileId128 ([string]$Transition.post_file_id_128) -MaxBytes $MaximumBytes
    }
    if([string]$read.Sha256 -ine [string]$Transition.post_sha256 -or [int64]$read.Length -ne [int64]$Transition.post_length){
        Die "SYNAPSE_AUTHORITY_TRANSITION_STAGE_READBACK_MISMATCH context=$Context leaf=$($Transition.stage_leaf) expected_sha256=$($Transition.post_sha256) actual_sha256=$($read.Sha256)"
    }
    return [string]$read.Content
}

function Read-SynapseAuthorityTransitionPostText {
    param(
        [Parameter(Mandatory=$true)]$Transition,
        [ValidateRange(1,1048576)][int]$MaximumBytes=65536,
        [Parameter(Mandatory=$true)][string]$Context
    )
    if($null-ne$Transition.CanonicalLease){
        $Transition.CanonicalLease.RequireExact("${Context}_canonical_owner")
        if([string]$Transition.CanonicalLease.FileId128-ine[string]$Transition.post_file_id_128-or
           [string]$Transition.CanonicalLease.Sha256-ine[string]$Transition.post_sha256-or
           [int64]$Transition.CanonicalLease.Length-ne[int64]$Transition.post_length){
            Die "SYNAPSE_AUTHORITY_TRANSITION_POST_CANONICAL_OWNER_MISMATCH context=$Context purpose=$($Transition.purpose)"
        }
        foreach($alternate in @(
            [pscustomobject]@{Name='stage';Parent=[string]$Transition.transaction_root;Chain=@($Transition.transaction_root_chain);Leaf=[string]$Transition.stage_leaf},
            [pscustomobject]@{Name='discard';Parent=[string]$Transition.transaction_root;Chain=@($Transition.transaction_root_chain);Leaf=[string]$Transition.discard_leaf}
        )){
            $alternateState=Get-SynapsePhysicalRelativeState -ParentPath $alternate.Parent -ParentChain $alternate.Chain -Leaf $alternate.Leaf
            if(Test-SynapsePhysicalStateExact -State $alternateState -ExpectedExists $true -ExpectedFileId128 ([string]$Transition.post_file_id_128) -ExpectedSha256 ([string]$Transition.post_sha256) -ExpectedLength ([int64]$Transition.post_length)){
                Die "SYNAPSE_AUTHORITY_TRANSITION_POST_DUPLICATE context=$Context purpose=$($Transition.purpose) alternate=$($alternate.Name)"
            }
        }
        $ownedRead=$Transition.CanonicalLease.ReadUtf8($MaximumBytes)
        if([string]$ownedRead.Sha256-ine[string]$Transition.post_sha256-or[int64]$ownedRead.Length-ne[int64]$Transition.post_length){
            Die "SYNAPSE_AUTHORITY_TRANSITION_POST_READBACK_MISMATCH context=$Context purpose=$($Transition.purpose) location=canonical_owner"
        }
        return [string]$ownedRead.Content
    }
    $locations=@(
        [pscustomobject]@{Name='canonical';Parent=[string]$Transition.parent;Chain=@($Transition.parent_chain);Leaf=[string]$Transition.leaf},
        [pscustomobject]@{Name='stage';Parent=[string]$Transition.transaction_root;Chain=@($Transition.transaction_root_chain);Leaf=[string]$Transition.stage_leaf},
        [pscustomobject]@{Name='discard';Parent=[string]$Transition.transaction_root;Chain=@($Transition.transaction_root_chain);Leaf=[string]$Transition.discard_leaf}
    )
    $matches=@()
    foreach($location in $locations){
        $state=Get-SynapsePhysicalRelativeState -ParentPath $location.Parent -ParentChain $location.Chain -Leaf $location.Leaf
        if(Test-SynapsePhysicalStateExact -State $state -ExpectedExists $true -ExpectedFileId128 ([string]$Transition.post_file_id_128) -ExpectedSha256 ([string]$Transition.post_sha256) -ExpectedLength ([int64]$Transition.post_length)){$matches+=,[pscustomobject]@{Location=$location;State=$state}}
    }
    if($matches.Count -ne 1){Die "SYNAPSE_AUTHORITY_TRANSITION_POST_LOCATION_INVALID context=$Context purpose=$($Transition.purpose) count=$($matches.Count) locations=$(@($matches.Location.Name)-join ',')"}
    $match=$matches[0]
    $read=Read-SynapsePhysicalRelativeUtf8Text -ParentPath $match.Location.Parent -ParentChain $match.Location.Chain -Leaf $match.Location.Leaf -ExpectedFileId128 ([string]$Transition.post_file_id_128) -MaxBytes $MaximumBytes
    if([string]$read.Sha256 -ine [string]$Transition.post_sha256 -or [int64]$read.Length -ne [int64]$Transition.post_length){Die "SYNAPSE_AUTHORITY_TRANSITION_POST_READBACK_MISMATCH context=$Context purpose=$($Transition.purpose) location=$($match.Location.Name)"}
    return [string]$read.Content
}

function Assert-SynapseBrokerTaskDescriptorShape {
    param(
        [Parameter(Mandatory=$true)]$Descriptor,
        [Parameter(Mandatory=$true)][ValidatePattern('^[0-9A-Fa-f]{64}$')][string]$BrokerIdentitySha256,
        [Parameter(Mandatory=$true)][ValidatePattern('^[0-9A-Fa-f]{64}$')][string]$TaskCapabilitySha256,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $names=if($Descriptor -is [System.Collections.IDictionary]){@($Descriptor.Keys|ForEach-Object{[string]$_})}else{@($Descriptor.PSObject.Properties.Name)}
    $expected=@('name','xml_sha256','security_descriptor_sha256','execute','arguments','working_directory','state')
    $expectedName='SynapseMcpBroker-'+$TaskCapabilitySha256.ToUpperInvariant().Substring(0,40)
    if($names.Count -ne $expected.Count -or @($names|Where-Object{$expected -cnotcontains $_}).Count -gt 0 -or
        [string]$Descriptor.name -cne $expectedName -or [string]$Descriptor.xml_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or
        [string]$Descriptor.security_descriptor_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or
        -not [System.IO.Path]::IsPathFullyQualified([string]$Descriptor.execute) -or
        -not [System.IO.Path]::IsPathFullyQualified([string]$Descriptor.working_directory)){
        Die "SYNAPSE_BROKER_TASK_DESCRIPTOR_INVALID context=$Context task=$($Descriptor.name) expected_task=$expectedName broker=$BrokerIdentitySha256 task_capability=$TaskCapabilitySha256"
    }
    return $Descriptor
}

function Assert-SynapseBrokerTaskDescriptorAuthorityCrossbind {
    param(
        [Parameter(Mandatory=$true)]$Descriptor,
        [Parameter(Mandatory=$true)][ValidatePattern('^[0-9A-Fa-f]{64}$')][string]$BrokerIdentitySha256,
        [Parameter(Mandatory=$true)][ValidatePattern('^[0-9A-Fa-f]{64}$')][string]$TaskCapabilitySha256,
        [Parameter(Mandatory=$true)]$Infrastructure,
        [Parameter(Mandatory=$true)][string]$Context
    )
    [void](Assert-SynapseBrokerTaskDescriptorShape -Descriptor $Descriptor -BrokerIdentitySha256 $BrokerIdentitySha256 -TaskCapabilitySha256 $TaskCapabilitySha256 -Context $Context)
    $receiptTask=ConvertTo-SynapseAuthorityTaskDescriptor -Task $Infrastructure.Task
    if([string]$BrokerIdentitySha256 -ine [string]$Infrastructure.BrokerIdentitySha256 -or
       [string]$TaskCapabilitySha256 -ine [string]$Infrastructure.TaskCapabilitySha256 -or
       [string]$Descriptor.name -cne [string]$Infrastructure.TaskName -or
       (Get-SynapseCanonicalJson -Value $Descriptor) -cne (Get-SynapseCanonicalJson -Value $receiptTask)){
        Die "SYNAPSE_BROKER_TASK_DESCRIPTOR_RECEIPT_CROSSBIND_INVALID context=$Context task=$($Descriptor.name) receipt_task=$($Infrastructure.TaskName) capability=$TaskCapabilitySha256 receipt_capability=$($Infrastructure.TaskCapabilitySha256) broker=$BrokerIdentitySha256 receipt_broker=$($Infrastructure.BrokerIdentitySha256)"
    }
    return $Descriptor
}

function Assert-SynapseAuthorityIdentityDescriptor {
    param(
        [Parameter(Mandatory=$true)]$Descriptor,
        [Parameter(Mandatory=$true)][string]$ExpectedPath,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $names=if($Descriptor-is[System.Collections.IDictionary]){@($Descriptor.Keys|ForEach-Object{[string]$_})}else{@($Descriptor.PSObject.Properties.Name)};$expected=@('path','file_id_128','sha256','length')
    $path=[System.IO.Path]::GetFullPath([string]$Descriptor.path)
    if($names.Count -ne $expected.Count -or @($names|Where-Object{$expected -cnotcontains $_}).Count -gt 0 -or
        $path -ine [System.IO.Path]::GetFullPath($ExpectedPath) -or [string]$Descriptor.file_id_128 -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or
        [string]$Descriptor.sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [int64]$Descriptor.length -lt 1){
        Die "SYNAPSE_AUTHORITY_IDENTITY_DESCRIPTOR_INVALID context=$Context path=$path expected_path=$ExpectedPath"
    }
    return [pscustomobject][ordered]@{Path=$path;FileId128=([string]$Descriptor.file_id_128).ToUpperInvariant();Sha256=([string]$Descriptor.sha256).ToUpperInvariant();Length=[int64]$Descriptor.length}
}

function ConvertTo-SynapseAuthorityIdentityDescriptor {
    param([Parameter(Mandatory=$true)]$Identity)
    return [ordered]@{path=[System.IO.Path]::GetFullPath([string]$Identity.Path);file_id_128=([string]$Identity.FileId128).ToUpperInvariant();sha256=([string]$Identity.Sha256).ToUpperInvariant();length=[int64]$Identity.Length}
}

function Get-SynapseAuthorityGenerationJournalDescriptor {
    param([Parameter(Mandatory=$true)]$Generation)
    return [ordered]@{
        generation_id=[string]$Generation.GenerationId
        runtime_generation_sha256=([string]$Generation.RuntimeGenerationSha256).ToUpperInvariant()
        profile_generation_sha256=([string]$Generation.ProfileGenerationSha256).ToUpperInvariant()
        expected_tool_count=[int]$Generation.RosterPayload.expected_tool_count
        expected_tool_surface_sha256=([string]$Generation.RosterPayload.expected_tool_surface_sha256).ToUpperInvariant()
        supervisor=(ConvertTo-SynapseAuthorityFileDescriptor -Identity $Generation.Supervisor -Role 'candidate_generation_supervisor')
    }
}

function ConvertTo-SynapseCandidateProbePlanJournalDescriptor {
    param([Parameter(Mandatory=$true)]$PlanAuthority)
    $PlanAuthority.Lease.RequireExact('candidate_probe_plan_before_journal')
    $payload=$PlanAuthority.Payload
    return [ordered]@{
        path=[System.IO.Path]::GetFullPath([string]$PlanAuthority.Path)
        file_id_128=([string]$PlanAuthority.FileId128).ToUpperInvariant()
        sha256=([string]$PlanAuthority.Sha256).ToUpperInvariant()
        length=[int64]$PlanAuthority.Length
        candidate_root=Get-SynapseNormalizedDirectoryPath -Path ([string]$payload.candidate_root)
        candidate_root_file_id_128=([string]$payload.candidate_root_file_id_128).ToUpperInvariant()
        task_name=[string]$payload.task_name
        capability_sha256=([string]$payload.capability_sha256).ToUpperInvariant()
        plan_sha256=([string]$payload.plan_sha256).ToUpperInvariant()
        execute=[System.IO.Path]::GetFullPath([string]$payload.execute)
        arguments=[string]$payload.arguments
        working_directory=[System.IO.Path]::GetFullPath([string]$payload.working_directory)
        explicit_security_descriptor=[string]$payload.explicit_security_descriptor
        payload=(ConvertTo-SynapseCanonicalValue -Value $payload)
    }
}

function Read-SynapseCandidateProbePlanFromJournal {
    param(
        [Parameter(Mandatory=$true)]$Descriptor,
        [Parameter(Mandatory=$true)][ValidatePattern('^[0-9A-Fa-f]{64}$')][string]$ExpectedCapabilitySha256,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $names=@(Get-SynapseObjectPropertyNames -Object $Descriptor)
    $expected=@('path','file_id_128','sha256','length','candidate_root','candidate_root_file_id_128','task_name','capability_sha256','plan_sha256','execute','arguments','working_directory','explicit_security_descriptor','payload')
    $root=Get-SynapseNormalizedDirectoryPath -Path ([string]$Descriptor.candidate_root)
    $path=[System.IO.Path]::GetFullPath([string]$Descriptor.path)
    $expectedName='SynapseMcpProbe-'+$ExpectedCapabilitySha256.Substring(0,40)
    if($names.Count -ne $expected.Count -or @($names|Where-Object{$expected -cnotcontains $_}).Count -gt 0 -or
       [string]$Descriptor.file_id_128 -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or [string]$Descriptor.sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [int64]$Descriptor.length -lt 1 -or
       [string]$Descriptor.candidate_root_file_id_128 -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or
       $path -ine (Join-Path $root 'candidate-probe-task-plan.json') -or [string]$Descriptor.task_name -cne $expectedName -or
       [string]$Descriptor.capability_sha256 -ine $ExpectedCapabilitySha256 -or [string]$Descriptor.plan_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or
       -not [System.IO.Path]::IsPathFullyQualified([string]$Descriptor.execute) -or
       (Get-SynapseNormalizedDirectoryPath -Path ([string]$Descriptor.working_directory)) -ine $root -or
       [string]::IsNullOrWhiteSpace([string]$Descriptor.explicit_security_descriptor)){
        Die "SYNAPSE_CANDIDATE_PROBE_JOURNAL_PLAN_DESCRIPTOR_INVALID context=$Context task=$($Descriptor.task_name) path=$path names_count=$($names.Count) expected_count=$($expected.Count) extra=$(@($names|Where-Object{$expected-cnotcontains$_})-join ',') file_id=$($Descriptor.file_id_128) sha256=$($Descriptor.sha256) length=$($Descriptor.length) candidate_root=$root candidate_root_file_id=$($Descriptor.candidate_root_file_id_128) expected_path=$(Join-Path $root 'candidate-probe-task-plan.json') expected_task=$expectedName capability=$($Descriptor.capability_sha256) expected_capability=$ExpectedCapabilitySha256 plan_sha256=$($Descriptor.plan_sha256) execute=$($Descriptor.execute) working_directory=$($Descriptor.working_directory) sddl_blank=$([string]::IsNullOrWhiteSpace([string]$Descriptor.explicit_security_descriptor))"
    }
    $payload=$Descriptor.payload
    $payloadText=Get-SynapseCanonicalJson -Value (ConvertTo-SynapseCanonicalValue -Value $payload)
    $payloadLength=[System.Text.UTF8Encoding]::new($false,$true).GetByteCount($payloadText)
    $payloadFileSha=(Get-SynapseSha256Hex -Text $payloadText).ToUpperInvariant()
    if($payloadLength -ne [int64]$Descriptor.length -or $payloadFileSha -ine [string]$Descriptor.sha256){Die "SYNAPSE_CANDIDATE_PROBE_JOURNAL_EMBEDDED_PAYLOAD_IDENTITY_INVALID context=$Context path=$path"}
    $chain=@();$lease=$null
    if(Test-Path -LiteralPath $root -PathType Container){
        $chain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $root)
        if([string]$chain[-1].file_id_128 -ine [string]$Descriptor.candidate_root_file_id_128){
            Die "SYNAPSE_CANDIDATE_PROBE_JOURNAL_ROOT_IDENTITY_DRIFT context=$Context root=$root"
        }
        $planState=Get-SynapsePhysicalRelativeState -ParentPath $root -ParentChain $chain -Leaf 'candidate-probe-task-plan.json'
        if($planState.Exists){
            $lease=Open-SynapsePhysicalFileReadLease -ParentPath $root -ParentChain $chain -Leaf 'candidate-probe-task-plan.json' -ExpectedFileId128 ([string]$Descriptor.file_id_128) -ExpectedSha256 ([string]$Descriptor.sha256) -ExpectedLength ([int64]$Descriptor.length) -Context "${Context}_plan"
        }
    }
    try{
        if($null -ne $lease){
            $raw=$lease.ReadUtf8(65536)
            if([string]$raw.Sha256 -ine [string]$Descriptor.sha256 -or [int64]$raw.Length -ne [int64]$Descriptor.length -or [string]$raw.Content -cne $payloadText){Die "SYNAPSE_CANDIDATE_PROBE_JOURNAL_PLAN_READBACK_DRIFT context=$Context path=$path"}
        }
        $payloadHasKeys=($payload -is [System.Collections.IDictionary])
        $payloadNames=@(Get-SynapseObjectPropertyNames -Object $payload)
        $payloadExpected=@('schema','state','launch_contract_schema','probe_broker_identity_sha256','capability_sha256','invocation_id','candidate_root','candidate_root_file_id_128','task_name','kind','execute','arguments','working_directory','powershell_path','powershell_file_id_128','powershell_sha256','powershell_length','powershell_descriptor','bootstrap_log_path','user_sid','task_create_flag','task_ignore_registration_triggers_flag_absent','trigger_types','task_instance_semantics','maximum_concurrent_instances','cleanup_requires_zero_running_instances','submitted_task_xml_sha256','explicit_security_descriptor','security_descriptor_readback_flags','bootstrap_file_id_128','bootstrap_sha256','bootstrap_length','supervisor_path','supervisor_file_id_128','supervisor_sha256','supervisor_length','bind','db_path','profiles_dir','token_path','created_at_utc','plan_sha256')
        $hasSubmittedSemantic=($payloadNames -ccontains 'submitted_task_semantic_sha256')
        if($hasSubmittedSemantic){$payloadExpected += 'submitted_task_semantic_sha256'}
        $core=[ordered]@{}
        if($payloadHasKeys){
            foreach($name in @($payloadNames)){if([string]$name-cne'plan_sha256'){$core[[string]$name]=$payload[$name]}}
        }else{
            foreach($property in @($payload.PSObject.Properties)){if([string]$property.Name -cne 'plan_sha256'){$core[[string]$property.Name]=$property.Value}}
        }
        $computed=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $core)).ToUpperInvariant()
        if($payloadNames.Count -ne $payloadExpected.Count -or @($payloadNames|Where-Object{$payloadExpected -cnotcontains $_}).Count -gt 0 -or
           [string]$payload.schema -cne 'synapse_candidate_probe_task_plan/v4' -or [string]$payload.state -cne 'prepared_before_task_create' -or
           [string]$payload.launch_contract_schema -cne 'synapse_supervisor_launch_contract/v2' -or [string]$payload.probe_broker_identity_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [string]$payload.probe_broker_identity_sha256 -ieq $ExpectedCapabilitySha256 -or
           [string]$payload.capability_sha256 -ine $ExpectedCapabilitySha256 -or [string]$payload.task_name -cne $expectedName -or [string]$payload.kind -cne 'probe' -or
           (Get-SynapseNormalizedDirectoryPath -Path ([string]$payload.candidate_root)) -ine $root -or [string]$payload.candidate_root_file_id_128 -ine [string]$Descriptor.candidate_root_file_id_128 -or
           [System.IO.Path]::GetFullPath([string]$payload.execute) -ine [System.IO.Path]::GetFullPath([string]$Descriptor.execute) -or [string]$payload.arguments -cne [string]$Descriptor.arguments -or
           (Get-SynapseNormalizedDirectoryPath -Path ([string]$payload.working_directory)) -ine $root -or [string]$payload.explicit_security_descriptor -cne [string]$Descriptor.explicit_security_descriptor -or
           [string]$payload.plan_sha256 -ine [string]$Descriptor.plan_sha256 -or [string]$payload.plan_sha256 -ine $computed -or
           [int]$payload.task_create_flag -ne 2 -or [bool]$payload.task_ignore_registration_triggers_flag_absent -ne $true -or @($payload.trigger_types).Count -ne 1 -or [string]$payload.trigger_types[0] -cne 'registration' -or
           [string]$payload.task_instance_semantics -cne 'registration_trigger_single_oneshot_ignore_new' -or [int]$payload.maximum_concurrent_instances -ne 1 -or [bool]$payload.cleanup_requires_zero_running_instances -ne $true -or
           [string]$payload.submitted_task_xml_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or
           ($hasSubmittedSemantic -and [string]$payload.submitted_task_semantic_sha256 -notmatch '^[0-9A-Fa-f]{64}$') -or
           [int]$payload.security_descriptor_readback_flags -ne 7 -or [string]$payload.user_sid -ine (Get-SynapseCurrentUserSid)){
            Die "SYNAPSE_CANDIDATE_PROBE_JOURNAL_PLAN_CONTRACT_INVALID context=$Context task=$expectedName path=$path"
        }
        [void](Assert-SynapseAuthorityTaskSecurityDescriptorSemantic -SecurityDescriptor ([string]$payload.explicit_security_descriptor) -ExpectedOwnerSid (Get-SynapseCurrentUserSid) -Context "${Context}_sddl")
        $powerShellIdentity=Assert-SynapseAuthorityFileDescriptorPhysicalIdentity -Descriptor $payload.powershell_descriptor -ExpectedRole probe_powershell -Context "${Context}_powershell"
        if([string]$powerShellIdentity.Path -ine [System.IO.Path]::GetFullPath([string]$payload.powershell_path) -or [string]$powerShellIdentity.FileId128 -ine [string]$payload.powershell_file_id_128 -or [string]$powerShellIdentity.Sha256 -ine [string]$payload.powershell_sha256 -or [int64]$powerShellIdentity.Length -ne [int64]$payload.powershell_length){Die "SYNAPSE_CANDIDATE_PROBE_POWERSHELL_DESCRIPTOR_CROSSBIND_INVALID context=$Context task=$expectedName"}
        $submittedDefinition=New-SynapseTaskCreateDefinitionPlan -Name ([string]$payload.task_name) -Kind probe -Execute ([string]$payload.execute) -Arguments ([string]$payload.arguments) -WorkingDirectory ([string]$payload.working_directory) -UserSid ([string]$payload.user_sid)
        if([string]$submittedDefinition.SubmittedXmlSha256 -ine [string]$payload.submitted_task_xml_sha256 -or
           ($hasSubmittedSemantic -and [string]$submittedDefinition.SemanticSha256 -ine [string]$payload.submitted_task_semantic_sha256)){
            Die "SYNAPSE_CANDIDATE_PROBE_SUBMITTED_XML_PLAN_DRIFT context=$Context task=$expectedName expected=$($payload.submitted_task_xml_sha256) actual=$($submittedDefinition.SubmittedXmlSha256)"
        }
        return [pscustomobject][ordered]@{Descriptor=$Descriptor;Payload=$payload;Lease=$lease;Root=$root;RootChain=$chain}
    }catch{if($null -ne $lease){$lease.Dispose()};throw}
}

function Remove-SynapseJournalBoundCandidateProbeTask {
    param(
        [Parameter(Mandatory=$true)]$Plan,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $scheduler=Get-SynapseScheduledTaskComRoot
    $lookup=Get-SynapseScheduledTaskLookupExact -Name ([string]$Plan.Payload.task_name) -Scheduler $scheduler
    if(-not [bool]$lookup.Exists){return [pscustomobject]@{TaskAbsent=$true;Name=[string]$Plan.Payload.task_name}}
    $registered=$lookup.Task
    $readback=Get-SynapseTaskDefinitionReadback -RegisteredTask $registered -Kind probe -ExpectedName ([string]$Plan.Payload.task_name) -ExpectedExecute ([string]$Plan.Payload.execute) -ExpectedArguments ([string]$Plan.Payload.arguments) -ExpectedWorkingDirectory ([string]$Plan.Payload.working_directory) -ExpectedUserSid ([string]$Plan.Payload.user_sid)
    [void](Assert-SynapseAuthorityTaskSecurityDescriptorSemantic -SecurityDescriptor ([string]$readback.SecurityDescriptor) -ExpectedOwnerSid ([string]$Plan.Payload.user_sid) -ExpectedSecurityDescriptor ([string]$Plan.Payload.explicit_security_descriptor) -Context "${Context}_task_sddl")
    $instances=@($registered.GetInstances(0))
    if($instances.Count -gt 1){Die "SYNAPSE_CANDIDATE_PROBE_JOURNAL_TASK_INSTANCE_CARDINALITY_INVALID context=$Context task=$($Plan.Payload.task_name) count=$($instances.Count) expected=0_or_1"}
    foreach($instance in $instances){$instance.Stop()}
    $deadline=(Get-Date).AddSeconds(30)
    do{
        $pollLookup=Get-SynapseScheduledTaskLookupExact -Name ([string]$Plan.Payload.task_name) -Scheduler $scheduler
        if(-not [bool]$pollLookup.Exists){Die "SYNAPSE_CANDIDATE_PROBE_JOURNAL_TASK_DISAPPEARED_DURING_DRAIN context=$Context task=$($Plan.Payload.task_name)"}
        $registered=$pollLookup.Task
        $remaining=@($registered.GetInstances(0))
        if($remaining.Count -eq 0){break}
        Start-Sleep -Milliseconds 250
    }while((Get-Date) -lt $deadline)
    if($remaining.Count -ne 0){Die "SYNAPSE_CANDIDATE_PROBE_JOURNAL_TASK_INSTANCE_DRAIN_FAILED context=$Context task=$($Plan.Payload.task_name) count=$($remaining.Count)"}
    [void](Remove-SynapseTransientTaskExact -Expected $readback -Kind probe -RequireNoRunningInstances)
    return [pscustomobject]@{TaskAbsent=$false;Name=[string]$readback.Name;XmlSha256=[string]$readback.XmlSha256;SecurityDescriptorSha256=[string]$readback.SecurityDescriptorSha256}
}

function Assert-SynapseBrokerProbeParkInitialDescriptor {
    param(
        [Parameter(Mandatory=$true)]$Initial,
        [Parameter(Mandatory=$true)][string]$TransactionRoot,
        [Parameter(Mandatory=$true)]$Allocation,
        $Layout,
        $ExistingGateTransition,
        $ExistingRosterTransition
    )
    $root=Get-SynapseNormalizedDirectoryPath -Path $TransactionRoot
    $rootChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $root)
    $names=@($Initial.PSObject.Properties.Name)
    $expected=@('schema','state','transaction_kind','invocation_id','armed_at_utc','transaction_root','transaction_root_file_id_128','allocation_marker','runtime_bin_dir','profiles_dir','bind','db_path','token_path','broker_identity_sha256','broker_task_capability_sha256','authority_epoch','control_nonce','broker_task','prior_authority','current_generation_id','current_control_gate','current_roster','parked_control_gate_transition','parked_roster_transition','probe_capability_sha256','static_transaction_sha256')
    if($names.Count -ne $expected.Count -or @($names|Where-Object{$expected -cnotcontains $_}).Count -gt 0 -or
        [string]$Initial.schema -cne 'synapse_broker_probe_park_transaction/v1' -or [string]$Initial.state -cne 'armed' -or
        [string]$Initial.transaction_kind -cne 'synapse_broker_probe_park/v1' -or [string]::IsNullOrWhiteSpace([string]$Initial.invocation_id) -or
        (Get-SynapseNormalizedDirectoryPath -Path ([string]$Initial.transaction_root)) -ine $root -or
        [string]$Initial.transaction_root_file_id_128 -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or
        [string]$Initial.broker_identity_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [string]$Initial.broker_task_capability_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [int64]$Initial.authority_epoch -lt 1 -or
        [string]$Initial.control_nonce -notmatch '^[0-9A-Fa-f]{64}$' -or [string]$Initial.prior_authority -notin @('present','absent') -or
        [string]$Initial.probe_capability_sha256 -notmatch '^[0-9A-Fa-f]{64}$'){
        Die "SYNAPSE_BROKER_PROBE_PARK_INITIAL_INVALID root=$root"
    }
    $staticCore=[ordered]@{}
    foreach($property in @($Initial.PSObject.Properties)){if([string]$property.Name -cne 'static_transaction_sha256'){$staticCore[[string]$property.Name]=$property.Value}}
    $persistedStaticCore=ConvertTo-SynapsePersistedAuthorityHashValue -Value $staticCore
    $computedStatic=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $persistedStaticCore)).ToUpperInvariant()
    if([string]$Initial.static_transaction_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [string]$Initial.static_transaction_sha256 -ine $computedStatic){
        Die "SYNAPSE_BROKER_PROBE_PARK_STATIC_HASH_INVALID root=$root expected=$($Initial.static_transaction_sha256) actual=$computedStatic"
    }
    $runtime=Get-SynapseNormalizedDirectoryPath -Path ([string]$Initial.runtime_bin_dir)
    $profiles=Get-SynapseNormalizedDirectoryPath -Path ([string]$Initial.profiles_dir)
    $actualParent=Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $root)
    if((Split-Path -Leaf $actualParent) -ine $script:SynapseDeploymentTransactionParentDirName -or
        -not [System.IO.Path]::IsPathFullyQualified([string]$Initial.db_path) -or -not [System.IO.Path]::IsPathFullyQualified([string]$Initial.token_path)){
        Die "SYNAPSE_BROKER_PROBE_PARK_TOPOLOGY_INVALID root=$root profiles=$profiles actual_parent=$actualParent expected_parent_leaf=$script:SynapseDeploymentTransactionParentDirName"
    }
    $layout=if($null -ne $Layout){$Layout}else{Get-SynapseAuthorityLayout -RuntimeBinDir $runtime}
    if((Get-SynapseNormalizedDirectoryPath -Path ([string]$layout.RuntimeBinDir)) -ine $runtime -or
       ($null -ne $layout.PSObject.Properties['RootExists'] -and -not [bool]$layout.RootExists)){
        Die "SYNAPSE_BROKER_PROBE_AUTHORITY_LAYOUT_INVALID root=$root runtime=$runtime layout_runtime=$($layout.RuntimeBinDir)"
    }
    [void](Assert-SynapseBrokerTaskDescriptorShape -Descriptor $Initial.broker_task -BrokerIdentitySha256 ([string]$Initial.broker_identity_sha256) -TaskCapabilitySha256 ([string]$Initial.broker_task_capability_sha256) -Context "probe_park_$root")
    $currentGate=Assert-SynapseAuthorityIdentityDescriptor -Descriptor $Initial.current_control_gate -ExpectedPath $layout.ControlGatePath -Context "probe_park_current_gate_$root"
    $currentRoster=Assert-SynapseAuthorityIdentityDescriptor -Descriptor $Initial.current_roster -ExpectedPath $layout.RosterPath -Context "probe_park_current_roster_$root"
    if([string]$Initial.prior_authority -ceq 'absent'){
        if(-not [string]::IsNullOrEmpty([string]$Initial.current_generation_id) -or $null -ne $Initial.parked_control_gate_transition -or $null -ne $Initial.parked_roster_transition){
            Die "SYNAPSE_BROKER_PROBE_FRESH_DESCRIPTOR_INVALID root=$root generation=$($Initial.current_generation_id)"
        }
        $pair=Read-SynapseAuthorityActiveControlPair -Layout $layout -ExpectedState parked -Context "probe_fresh_current_pair_$root"
        try{
            if([string]$pair.Gate.FileId128 -ine $currentGate.FileId128 -or [string]$pair.Gate.Sha256 -ine $currentGate.Sha256 -or [int64]$pair.Gate.Length -ne $currentGate.Length -or
               [string]$pair.Roster.FileId128 -ine $currentRoster.FileId128 -or [string]$pair.Roster.Sha256 -ine $currentRoster.Sha256 -or [int64]$pair.Roster.Length -ne $currentRoster.Length -or
               [string]$pair.Roster.Payload.mode -cne 'parked' -or [string]$pair.Roster.Payload.role -cne 'none' -or
               [string]$pair.Roster.Payload.broker_identity_sha256 -ine [string]$Initial.broker_identity_sha256 -or [int64]$pair.Roster.Payload.authority_epoch -ne [int64]$Initial.authority_epoch -or
               [string]$pair.Roster.Payload.control_nonce -ine [string]$Initial.control_nonce){
                Die "SYNAPSE_BROKER_PROBE_FRESH_PAIR_IDENTITY_INVALID root=$root"
            }
        }finally{Close-SynapseAuthorityActiveControlPair -Pair $pair}
        return [pscustomobject][ordered]@{Root=$root;Layout=$layout;PriorAuthority='absent';CurrentControlGate=$currentGate;CurrentRoster=$currentRoster;GateTransition=$null;RosterTransition=$null;ParkedRosterEnvelope=$null;ParkedGateEnvelope=$null;StaticTransactionSha256=$computedStatic}
    }
    if([string]$Initial.current_generation_id -notmatch '^(prior|candidate)-[0-9a-f]{40}$' -or $null -eq $Initial.parked_control_gate_transition -or $null -eq $Initial.parked_roster_transition){
        Die "SYNAPSE_BROKER_PROBE_PRESENT_DESCRIPTOR_INVALID root=$root generation=$($Initial.current_generation_id)"
    }
    $gateTransition=ConvertTo-SynapseAuthorityControlTransition -Descriptor $Initial.parked_control_gate_transition -TransactionRoot $root -Allocation $Allocation
    $rosterTransition=ConvertTo-SynapseAuthorityControlTransition -Descriptor $Initial.parked_roster_transition -TransactionRoot $root -Allocation $Allocation
    foreach($binding in @(
        [pscustomobject]@{Name='gate';Existing=$ExistingGateTransition;Reconstructed=$gateTransition;Descriptor=$Initial.parked_control_gate_transition},
        [pscustomobject]@{Name='roster';Existing=$ExistingRosterTransition;Reconstructed=$rosterTransition;Descriptor=$Initial.parked_roster_transition}
    )){
        if($null-eq$binding.Existing){continue}
        $existingDescriptor=Get-SynapseAuthorityControlTransitionDescriptor -Transition $binding.Existing
        if((Get-SynapseCanonicalJson -Value $existingDescriptor) -cne (Get-SynapseCanonicalJson -Value $binding.Descriptor)){
            Die "SYNAPSE_BROKER_PROBE_LIVE_TRANSITION_DESCRIPTOR_MISMATCH root=$root role=$($binding.Name)"
        }
        if($binding.Name-ceq'gate'){$gateTransition=$binding.Existing}else{$rosterTransition=$binding.Existing}
    }
    if([string]$gateTransition.path -ine $layout.ControlGatePath -or [string]$rosterTransition.path -ine $layout.RosterPath -or
        -not [bool]$gateTransition.pre_existed -or -not [bool]$rosterTransition.pre_existed -or
        [string]$gateTransition.pre_file_id_128 -ine $currentGate.FileId128 -or [string]$gateTransition.pre_sha256 -ine $currentGate.Sha256 -or [int64]$gateTransition.pre_length -ne $currentGate.Length -or
        [string]$rosterTransition.pre_file_id_128 -ine $currentRoster.FileId128 -or [string]$rosterTransition.pre_sha256 -ine $currentRoster.Sha256 -or [int64]$rosterTransition.pre_length -ne $currentRoster.Length){
        Die "SYNAPSE_BROKER_PROBE_PARK_PREIMAGE_CHAIN_INVALID root=$root"
    }
    # Recovery can observe the postimage in stage, canonical, or discard.  The
    # immutable descriptor binds the same object at every location; requiring
    # the pre-publication stage pathname after a successful no-replace move
    # made the first crash-safe recovery deterministically impossible.
    $rosterText=if($null-ne$rosterTransition.StageArtifact-and$null-ne$rosterTransition.StageArtifact.handle){
        Read-SynapseAuthorityTransitionStageText -Transition $rosterTransition -Allocation $Allocation -MaximumBytes $script:SynapseAuthorityRosterMaxBytes -Context "probe_park_roster_live_stage_$root"
    }else{
        Read-SynapseAuthorityTransitionPostText -Transition $rosterTransition -MaximumBytes $script:SynapseAuthorityRosterMaxBytes -Context "probe_park_roster_post_$root"
    }
    $rosterEnvelope=Read-SynapseAuthorityRosterEnvelopeText -Text $rosterText -Context "probe_park_roster_stage_$root"
    $gateText=if($null-ne$gateTransition.StageArtifact-and$null-ne$gateTransition.StageArtifact.handle){
        Read-SynapseAuthorityTransitionStageText -Transition $gateTransition -Allocation $Allocation -MaximumBytes 65536 -Context "probe_park_gate_live_stage_$root"
    }else{
        Read-SynapseAuthorityTransitionPostText -Transition $gateTransition -MaximumBytes 65536 -Context "probe_park_gate_post_$root"
    }
    $gateEnvelope=Read-SynapseAuthorityControlGateEnvelopeText -Text $gateText -ExpectedPath $layout.RosterPath -Context "probe_park_gate_stage_$root"
    if([string]$rosterEnvelope.Payload.mode -cne 'parked' -or [string]$rosterEnvelope.Payload.role -cne 'none' -or
        [string]$rosterEnvelope.Payload.broker_identity_sha256 -ine [string]$Initial.broker_identity_sha256 -or
        [int64]$rosterEnvelope.Payload.authority_epoch -ne [int64]$Initial.authority_epoch -or [string]$rosterEnvelope.Payload.control_nonce -ine [string]$Initial.control_nonce -or
        [string]$gateEnvelope.Payload.state -cne 'parked' -or [string]$gateEnvelope.Payload.broker_identity_sha256 -ine [string]$Initial.broker_identity_sha256 -or
        [int64]$gateEnvelope.Payload.authority_epoch -ne [int64]$Initial.authority_epoch -or [string]$gateEnvelope.Payload.control_nonce -ine [string]$Initial.control_nonce -or
        [string]$gateEnvelope.Payload.roster_file_id_128 -ine [string]$rosterTransition.post_file_id_128 -or
        [string]$gateEnvelope.Payload.roster_sha256 -ine [string]$rosterTransition.post_sha256 -or [int64]$gateEnvelope.Payload.roster_length -ne [int64]$rosterTransition.post_length){
        Die "SYNAPSE_BROKER_PROBE_PARK_POSTIMAGE_CHAIN_INVALID root=$root"
    }
    return [pscustomobject][ordered]@{Root=$root;Layout=$layout;PriorAuthority='present';CurrentControlGate=$currentGate;CurrentRoster=$currentRoster;GateTransition=$gateTransition;RosterTransition=$rosterTransition;ParkedRosterEnvelope=$rosterEnvelope;ParkedGateEnvelope=$gateEnvelope;StaticTransactionSha256=$computedStatic}
}

function Assert-SynapseBrokerApplicationInitialDescriptor {
    param(
        [Parameter(Mandatory=$true)]$Initial,
        [Parameter(Mandatory=$true)][string]$TransactionRoot,
        [Parameter(Mandatory=$true)]$Allocation,
        [string[]]$ExpectedRuntimePaths = @(),
        $Layout,
        [switch]$AllowCommittedDiscardedPost
    )
    $root=Get-SynapseNormalizedDirectoryPath -Path $TransactionRoot
    $names=@($Initial.PSObject.Properties.Name)
    $expected=@('schema','state','transaction_kind','authority_model','invocation_id','armed_at_utc','transaction_root','transaction_root_file_id_128','allocation_marker','runtime_bin_dir','profiles_dir','bind','db_path','token_path','calyx_config_path','calyx_config_sha256','broker_identity_sha256','broker_task_capability_sha256','authority_epoch','control_nonce','broker_task','prior_authority','current_generation_id','current_control_gate','current_roster','parked_control_gate_transition','parked_roster_transition','candidate_control_gate_transition','candidate_roster_transition','runtime_expected_paths','runtime_transaction','profile_transaction','candidate_generation','installed_probe_plan','static_transaction_sha256')
    if($names.Count -ne $expected.Count -or @($names|Where-Object{$expected -cnotcontains $_}).Count -gt 0 -or
       [string]$Initial.schema -cne 'synapse_deployment_transaction/v4' -or [string]$Initial.state -cne 'armed' -or [string]$Initial.transaction_kind -cne 'synapse_broker_application/v1' -or [string]$Initial.authority_model -cne 'immutable_broker/v1' -or
       [string]::IsNullOrWhiteSpace([string]$Initial.invocation_id) -or (Get-SynapseNormalizedDirectoryPath -Path ([string]$Initial.transaction_root)) -ine $root -or
       [string]$Initial.transaction_root_file_id_128 -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or [string]$Initial.broker_identity_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [string]$Initial.broker_task_capability_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or
       [int64]$Initial.authority_epoch -lt 1 -or [string]$Initial.control_nonce -notmatch '^[0-9A-Fa-f]{64}$' -or [string]$Initial.prior_authority -notin @('present','absent') -or
       [string]$Initial.calyx_config_sha256 -notmatch '^[0-9A-Fa-f]{64}$'){
        Die "SYNAPSE_BROKER_APPLICATION_INITIAL_INVALID root=$root"
    }
    $static=[ordered]@{};foreach($property in @($Initial.PSObject.Properties)){if([string]$property.Name -cne 'static_transaction_sha256'){$static[[string]$property.Name]=$property.Value}}
    $computed=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $static)).ToUpperInvariant()
    if([string]$Initial.static_transaction_sha256 -ine $computed){Die "SYNAPSE_BROKER_APPLICATION_STATIC_HASH_INVALID root=$root expected=$($Initial.static_transaction_sha256) actual=$computed"}
    $runtime=Get-SynapseNormalizedDirectoryPath -Path ([string]$Initial.runtime_bin_dir);$profiles=Get-SynapseNormalizedDirectoryPath -Path ([string]$Initial.profiles_dir)
    $layout=if($null -ne $Layout){$Layout}else{Get-SynapseAuthorityLayout -RuntimeBinDir $runtime}
    if((Get-SynapseNormalizedDirectoryPath -Path ([string]$layout.RuntimeBinDir)) -ine $runtime -or
       ($null -ne $layout.PSObject.Properties['RootExists'] -and -not [bool]$layout.RootExists)){
        Die "SYNAPSE_BROKER_APPLICATION_AUTHORITY_LAYOUT_INVALID root=$root runtime=$runtime layout_runtime=$($layout.RuntimeBinDir)"
    }
    $actualParent=Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $root)
    if((Split-Path -Leaf $actualParent) -ine $script:SynapseDeploymentTransactionParentDirName -or -not [System.IO.Path]::IsPathFullyQualified([string]$Initial.db_path) -or -not [System.IO.Path]::IsPathFullyQualified([string]$Initial.token_path) -or -not [System.IO.Path]::IsPathFullyQualified([string]$Initial.calyx_config_path)){
        Die "SYNAPSE_BROKER_APPLICATION_TOPOLOGY_INVALID root=$root runtime=$runtime profiles=$profiles"
    }
    [void](Assert-SynapseBrokerTaskDescriptorShape -Descriptor $Initial.broker_task -BrokerIdentitySha256 ([string]$Initial.broker_identity_sha256) -TaskCapabilitySha256 ([string]$Initial.broker_task_capability_sha256) -Context "app_v4_$root")
    $currentGate=Assert-SynapseAuthorityIdentityDescriptor -Descriptor $Initial.current_control_gate -ExpectedPath $layout.ControlGatePath -Context "app_v4_current_gate_$root"
    $currentRoster=Assert-SynapseAuthorityIdentityDescriptor -Descriptor $Initial.current_roster -ExpectedPath $layout.RosterPath -Context "app_v4_current_roster_$root"
    if(([string]$Initial.prior_authority -ceq 'present' -and [string]$Initial.current_generation_id -notmatch '^(prior|candidate)-[0-9a-f]{40}$') -or
       ([string]$Initial.prior_authority -ceq 'absent' -and -not [string]::IsNullOrEmpty([string]$Initial.current_generation_id))){Die "SYNAPSE_BROKER_APPLICATION_PRIOR_GENERATION_INVALID root=$root prior=$($Initial.prior_authority) generation=$($Initial.current_generation_id)"}
    $runtimePaths=@($Initial.runtime_expected_paths|ForEach-Object{[System.IO.Path]::GetFullPath([string]$_)})
    if($runtimePaths.Count -lt 1 -or $runtimePaths.Count -gt 64 -or @($runtimePaths|Sort-Object -Unique).Count -ne $runtimePaths.Count){Die "SYNAPSE_BROKER_APPLICATION_RUNTIME_PATH_SET_INVALID root=$root count=$($runtimePaths.Count)"}
    if(@($ExpectedRuntimePaths).Count -gt 0){
        $expectedRuntimePathsNormalized=@($ExpectedRuntimePaths|ForEach-Object{[System.IO.Path]::GetFullPath([string]$_)}|Sort-Object)
        if((Get-SynapseCanonicalJson -Value @($runtimePaths|Sort-Object)) -cne (Get-SynapseCanonicalJson -Value $expectedRuntimePathsNormalized)){
            Die "SYNAPSE_BROKER_APPLICATION_RUNTIME_PATH_AUTHORITY_MISMATCH root=$root journal_paths=$($runtimePaths -join ',') expected_paths=$($expectedRuntimePathsNormalized -join ',')"
        }
    }
    $runtimePlan=ConvertTo-SynapseRuntimeDeploymentPlan -Descriptor $Initial.runtime_transaction -TransactionRoot $root -ExpectedPaths $runtimePaths -Allocation $Allocation
    $profilePlan=Assert-SynapseBundledProfilesTransactionDescriptor -Descriptor $Initial.profile_transaction -ProfilesDir $profiles -TransactionRoot $root
    $parkedGate=$null;$parkedRoster=$null
    if([string]$Initial.prior_authority -ceq 'present'){
        $parkedGate=ConvertTo-SynapseAuthorityControlTransition -Descriptor $Initial.parked_control_gate_transition -TransactionRoot $root -Allocation $Allocation
        $parkedRoster=ConvertTo-SynapseAuthorityControlTransition -Descriptor $Initial.parked_roster_transition -TransactionRoot $root -Allocation $Allocation
        if([string]$parkedGate.path -ine $layout.ControlGatePath -or [string]$parkedRoster.path -ine $layout.RosterPath -or
           [string]$parkedGate.pre_file_id_128 -ine $currentGate.FileId128 -or [string]$parkedGate.pre_sha256 -ine $currentGate.Sha256 -or [int64]$parkedGate.pre_length -ne $currentGate.Length -or
           [string]$parkedRoster.pre_file_id_128 -ine $currentRoster.FileId128 -or [string]$parkedRoster.pre_sha256 -ine $currentRoster.Sha256 -or [int64]$parkedRoster.pre_length -ne $currentRoster.Length){Die "SYNAPSE_BROKER_APPLICATION_PARK_CHAIN_INVALID root=$root"}
    }elseif($null -ne $Initial.parked_control_gate_transition -or $null -ne $Initial.parked_roster_transition){Die "SYNAPSE_BROKER_APPLICATION_FRESH_PARK_TRANSITION_FORBIDDEN root=$root"}
    $candidateRoster=ConvertTo-SynapseAuthorityControlTransition -Descriptor $Initial.candidate_roster_transition -TransactionRoot $root -Allocation $Allocation
    $candidateGate=ConvertTo-SynapseAuthorityControlTransition -Descriptor $Initial.candidate_control_gate_transition -TransactionRoot $root -Allocation $Allocation
    $expectedParkRoster=if($null -ne $parkedRoster){[pscustomobject]@{FileId128=$parkedRoster.post_file_id_128;Sha256=$parkedRoster.post_sha256;Length=$parkedRoster.post_length}}else{$currentRoster}
    $expectedParkGate=if($null -ne $parkedGate){[pscustomobject]@{FileId128=$parkedGate.post_file_id_128;Sha256=$parkedGate.post_sha256;Length=$parkedGate.post_length}}else{$currentGate}
    if([string]$candidateRoster.path -ine $layout.RosterPath -or [string]$candidateGate.path -ine $layout.ControlGatePath -or
       [string]$candidateRoster.pre_file_id_128 -ine $expectedParkRoster.FileId128 -or [string]$candidateRoster.pre_sha256 -ine $expectedParkRoster.Sha256 -or [int64]$candidateRoster.pre_length -ne $expectedParkRoster.Length -or
       [string]$candidateGate.pre_file_id_128 -ine $expectedParkGate.FileId128 -or [string]$candidateGate.pre_sha256 -ine $expectedParkGate.Sha256 -or [int64]$candidateGate.pre_length -ne $expectedParkGate.Length){Die "SYNAPSE_BROKER_APPLICATION_CANDIDATE_CONTROL_CHAIN_INVALID root=$root"}
    $rosterArtifact=$Allocation.Artifacts[[string]$candidateRoster.stage_leaf]
    $rosterStageHandle=if($null-ne$rosterArtifact){Get-SynapseObjectPropertyValue -Object $rosterArtifact -Names @('handle','Handle')}else{$null}
    $rosterStageState=Get-SynapseAuthorityControlRootState -Transition $candidateRoster -Leaf ([string]$candidateRoster.stage_leaf)
    $rosterHasRetainedStage=($null-ne$rosterStageHandle -and (Test-SynapsePhysicalStateExact -State $rosterStageState -ExpectedExists $true -ExpectedFileId128 $candidateRoster.post_file_id_128 -ExpectedSha256 $candidateRoster.post_sha256 -ExpectedLength $candidateRoster.post_length))
    $rosterText=if($AllowCommittedDiscardedPost -and -not$rosterHasRetainedStage){Read-SynapseAuthorityTransitionPostText -Transition $candidateRoster -MaximumBytes $script:SynapseAuthorityRosterMaxBytes -Context "app_v4_candidate_roster_$root"}else{Read-SynapseAuthorityTransitionStageText -Transition $candidateRoster -Allocation $Allocation -MaximumBytes $script:SynapseAuthorityRosterMaxBytes -Context "app_v4_candidate_roster_$root"}
    $gateArtifact=$Allocation.Artifacts[[string]$candidateGate.stage_leaf]
    $gateStageHandle=if($null-ne$gateArtifact){Get-SynapseObjectPropertyValue -Object $gateArtifact -Names @('handle','Handle')}else{$null}
    $gateStageState=Get-SynapseAuthorityControlRootState -Transition $candidateGate -Leaf ([string]$candidateGate.stage_leaf)
    $gateHasRetainedStage=($null-ne$gateStageHandle -and (Test-SynapsePhysicalStateExact -State $gateStageState -ExpectedExists $true -ExpectedFileId128 $candidateGate.post_file_id_128 -ExpectedSha256 $candidateGate.post_sha256 -ExpectedLength $candidateGate.post_length))
    $gateText=if($AllowCommittedDiscardedPost -and -not$gateHasRetainedStage){Read-SynapseAuthorityTransitionPostText -Transition $candidateGate -MaximumBytes 65536 -Context "app_v4_candidate_gate_$root"}else{Read-SynapseAuthorityTransitionStageText -Transition $candidateGate -Allocation $Allocation -MaximumBytes 65536 -Context "app_v4_candidate_gate_$root"}
    $rosterEnvelope=Read-SynapseAuthorityRosterEnvelopeText -Text $rosterText -Context "app_v4_candidate_roster_$root";$gateEnvelope=Read-SynapseAuthorityControlGateEnvelopeText -Text $gateText -ExpectedPath $layout.RosterPath -Context "app_v4_candidate_gate_$root"
    $generation=$Initial.candidate_generation;$generationNames=@(Get-SynapseObjectPropertyNames -Object $generation);$generationExpected=@('generation_id','runtime_generation_sha256','profile_generation_sha256','expected_tool_count','expected_tool_surface_sha256','supervisor')
    if($generationNames.Count -ne $generationExpected.Count -or @($generationNames|Where-Object{$generationExpected -cnotcontains $_}).Count -gt 0 -or [string]$generation.generation_id -notmatch '^candidate-[0-9a-f]{40}$' -or [string]$generation.runtime_generation_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [string]$generation.profile_generation_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [int]$generation.expected_tool_count -lt 1 -or [string]$generation.expected_tool_surface_sha256 -notmatch '^[0-9A-Fa-f]{64}$'){Die "SYNAPSE_BROKER_APPLICATION_CANDIDATE_GENERATION_INVALID root=$root"}
    $supervisor=Assert-SynapseAuthorityFileDescriptorPhysicalIdentity -Descriptor $generation.supervisor -ExpectedRole candidate_generation_supervisor -ExpectedParent $layout.Objects -Context "app_v4_candidate_supervisor_$root"
    $rp=$rosterEnvelope.Payload
    $runtimeByPath=New-SynapseCaseInsensitiveMap
    foreach($record in @($runtimePlan.Records)){$runtimeByPath[[System.IO.Path]::GetFullPath([string]$record.path)]=$record}
    $candidateExePath=[System.IO.Path]::GetFullPath([string]$rp.exe_path)
    if(-not $runtimeByPath.ContainsKey($candidateExePath)){Die "SYNAPSE_BROKER_APPLICATION_CANDIDATE_EXE_NOT_IN_RUNTIME_PLAN root=$root path=$candidateExePath"}
    $candidateExeRecord=$runtimeByPath[$candidateExePath]
    $rosterObjectByPath=New-SynapseCaseInsensitiveMap
    foreach($object in @($rp.generation_objects)){$rosterObjectByPath[[System.IO.Path]::GetFullPath([string]$object.path)]=$object}
    foreach($record in @($runtimePlan.Records|Where-Object{[System.IO.Path]::GetFullPath([string]$_.path) -ine $candidateExePath})){
        $runtimeObjectPath=[System.IO.Path]::GetFullPath([string]$record.path)
        if(-not $rosterObjectByPath.ContainsKey($runtimeObjectPath)){Die "SYNAPSE_BROKER_APPLICATION_RUNTIME_OBJECT_BINDING_MISSING root=$root path=$runtimeObjectPath"}
        $runtimeObject=$rosterObjectByPath[$runtimeObjectPath]
        if([string]$runtimeObject.file_id_128 -ine [string]$record.post_file_id_128 -or [string]$runtimeObject.sha256 -ine [string]$record.post_sha256 -or [int64]$runtimeObject.length -ne [int64]$record.post_length){Die "SYNAPSE_BROKER_APPLICATION_RUNTIME_OBJECT_BINDING_MISMATCH root=$root path=$runtimeObjectPath"}
    }
    $manifestPath=[System.IO.Path]::GetFullPath((Join-Path $profiles $script:SynapseBundledProfilesManifestFileName))
    $expectedRosterObjectPaths=New-SynapseCaseInsensitiveMap
    foreach($record in @($runtimePlan.Records|Where-Object{[System.IO.Path]::GetFullPath([string]$_.path) -ine $candidateExePath})){
        $expectedRosterObjectPaths[[System.IO.Path]::GetFullPath([string]$record.path)]=$true
    }
    $expectedRosterObjectPaths[[System.IO.Path]::GetFullPath([string]$Initial.token_path)]=$true
    $expectedRosterObjectPaths[$manifestPath]=$true
    $manifestObjects=@($rp.generation_objects|Where-Object{[string]$_.role -ceq 'profile_manifest' -and [System.IO.Path]::GetFullPath([string]$_.path) -ieq $manifestPath})
    $tokenObjects=@($rp.generation_objects|Where-Object{[string]$_.role -ceq 'bearer_token' -and [System.IO.Path]::GetFullPath([string]$_.path) -ieq [System.IO.Path]::GetFullPath([string]$Initial.token_path)})
    $unexpectedRosterObjects=@($rp.generation_objects|Where-Object{-not $expectedRosterObjectPaths.ContainsKey([System.IO.Path]::GetFullPath([string]$_.path))})
    if([string]$rp.mode -cne 'active' -or [string]$rp.role -cne 'candidate' -or [string]$rp.broker_identity_sha256 -ine [string]$Initial.broker_identity_sha256 -or [int64]$rp.authority_epoch -ne [int64]$Initial.authority_epoch -or [string]$rp.control_nonce -ine [string]$Initial.control_nonce -or [string]$rp.broker_task_capability_sha256 -ine [string]$Initial.broker_task_capability_sha256 -or
       [string]$rp.broker_task_name -cne [string]$Initial.broker_task.name -or [string]$rp.broker_task_xml_sha256 -ine [string]$Initial.broker_task.xml_sha256 -or [string]$rp.broker_task_security_descriptor_sha256 -ine [string]$Initial.broker_task.security_descriptor_sha256 -or
       [string]$rp.generation_id -cne [string]$generation.generation_id -or [string]$rp.runtime_generation_sha256 -ine [string]$generation.runtime_generation_sha256 -or [string]$rp.profile_generation_sha256 -ine [string]$generation.profile_generation_sha256 -or
       [int]$rp.expected_tool_count -ne [int]$generation.expected_tool_count -or [string]$rp.expected_tool_surface_sha256 -ine [string]$generation.expected_tool_surface_sha256 -or
       [string]$rp.generation_supervisor_file_id_128 -ine [string]$supervisor.FileId128 -or [string]$rp.generation_supervisor_sha256 -ine [string]$supervisor.Sha256 -or
       [string]$rp.exe_file_id_128 -ine [string]$candidateExeRecord.post_file_id_128 -or [string]$rp.exe_sha256 -ine [string]$candidateExeRecord.post_sha256 -or [int64]$rp.exe_length -ne [int64]$candidateExeRecord.post_length -or
       [string]$rp.bind -cne [string]$Initial.bind -or [System.IO.Path]::GetFullPath([string]$rp.db_path) -ine [System.IO.Path]::GetFullPath([string]$Initial.db_path) -or [System.IO.Path]::GetFullPath([string]$rp.token_path) -ine [System.IO.Path]::GetFullPath([string]$Initial.token_path) -or
       [System.IO.Path]::GetFullPath([string]$rp.calyx_config_path) -ine [System.IO.Path]::GetFullPath([string]$Initial.calyx_config_path) -or [string]$rp.calyx_config_sha256 -ine [string]$Initial.calyx_config_sha256 -or
       [System.IO.Path]::GetFullPath([string]$rp.profiles_dir) -ine $profiles -or [string]$rp.profiles_root_file_id_128 -ine [string]$profilePlan.RootFileId128 -or
       [int]$rp.generation_object_count -ne $expectedRosterObjectPaths.Count -or @($rp.generation_objects).Count -ne $expectedRosterObjectPaths.Count -or $unexpectedRosterObjects.Count -ne 0 -or
       $manifestObjects.Count -ne 1 -or $tokenObjects.Count -ne 1 -or
       [string]$manifestObjects[0].file_id_128 -ine [string]$profilePlan.ManifestEntry.post_file_id_128 -or [string]$manifestObjects[0].sha256 -ine [string]$profilePlan.ManifestEntry.post_sha256 -or [int64]$manifestObjects[0].length -ne [int64]$profilePlan.ManifestEntry.post_length -or
       [string]$gateEnvelope.Payload.state -cne 'active' -or [string]$gateEnvelope.Payload.roster_file_id_128 -ine [string]$candidateRoster.post_file_id_128 -or [string]$gateEnvelope.Payload.roster_sha256 -ine [string]$candidateRoster.post_sha256 -or [int64]$gateEnvelope.Payload.roster_length -ne [int64]$candidateRoster.post_length){Die "SYNAPSE_BROKER_APPLICATION_CANDIDATE_ROSTER_BINDING_INVALID root=$root generation=$($generation.generation_id)"}
    $probe=Read-SynapseCandidateProbePlanFromJournal -Descriptor $Initial.installed_probe_plan -ExpectedCapabilitySha256 ([string]$Initial.installed_probe_plan.capability_sha256) -Context "app_v4_installed_probe_$root"
    try{
        if([System.IO.Path]::GetFullPath([string]$probe.Payload.execute) -ine [System.IO.Path]::GetFullPath([string]$rp.bootstrap_path) -or [System.IO.Path]::GetFullPath([string]$probe.Payload.profiles_dir) -ine $profiles -or [System.IO.Path]::GetFullPath([string]$probe.Payload.token_path) -ine [System.IO.Path]::GetFullPath([string]$Initial.token_path)){Die "SYNAPSE_BROKER_APPLICATION_PROBE_GENERATION_MISMATCH root=$root task=$($probe.Payload.task_name)"}
    }finally{if($null -ne $probe.Lease){$probe.Lease.Dispose()}}
    return [pscustomobject][ordered]@{Root=$root;Layout=$layout;RuntimePlan=$runtimePlan;ProfilePlan=$profilePlan;CurrentControlGate=$currentGate;CurrentRoster=$currentRoster;ParkedGateTransition=$parkedGate;ParkedRosterTransition=$parkedRoster;CandidateGateTransition=$candidateGate;CandidateRosterTransition=$candidateRoster;CandidateRosterEnvelope=$rosterEnvelope;CandidateGateEnvelope=$gateEnvelope;CandidateSupervisor=$supervisor;StaticTransactionSha256=$computed}
}

function Invoke-SynapseBrokerApplicationRollback {
    param(
        [Parameter(Mandatory=$true)]$Transaction,
        [Parameter(Mandatory=$true)]$Authority,
        [Parameter(Mandatory=$true)][string]$PrimaryFailure,
        [ValidateRange(30,900)][int]$HealthTimeoutSeconds=420
    )
    $journal=Read-SynapseDeploymentTransactionJournal -TransactionRoot $Transaction.Root -TransactionRootChain $Transaction.RootChain
    $effective=if([string]$journal.State -ceq 'cleanup_ready'){[string]$journal.Latest.detail.terminal_state}else{[string]$journal.State}
    if($effective -eq 'commit_decided'){return [pscustomobject]@{Ok=$false;ForwardRequired=$true;Detail='durable commit decision forbids rollback'}}
    if($effective -notin @('armed','candidate_ready','rolled_back')){Die "SYNAPSE_BROKER_APPLICATION_ROLLBACK_STATE_INVALID root=$($Transaction.Root) state=$($journal.State) effective=$effective"}
    $validated=Assert-SynapseBrokerApplicationInitialDescriptor -Initial $journal.Initial -TransactionRoot $Transaction.Root -Allocation $journal.Allocation -ExpectedRuntimePaths @($Transaction.ExpectedRuntimePaths) -AllowCommittedDiscardedPost
    Merge-SynapseBrokerApplicationLiveTransitions -Validated $validated -Transaction $Transaction -Initial $journal.Initial
    $plan=Read-SynapseCandidateProbePlanFromJournal -Descriptor $journal.Initial.installed_probe_plan -ExpectedCapabilitySha256 ([string]$journal.Initial.installed_probe_plan.capability_sha256) -Context 'app_v4_rollback_probe'
    try{[void](Remove-SynapseJournalBoundCandidateProbeTask -Plan $plan -Context 'app_v4_rollback_probe');Wait-SynapseBindReleased -Reason 'app_v4_rollback_probe' -Bind ([string]$plan.Payload.bind) -TimeoutSeconds 30}finally{if($null -ne $plan.Lease){$plan.Lease.Dispose()}}
    if($effective -eq 'rolled_back'){
        $terminal=Assert-SynapseBrokerApplicationPriorOperational -Validated $validated -Initial $journal.Initial -Authority $Authority -HealthTimeoutSeconds $HealthTimeoutSeconds -Context 'app_v4_terminal_rollback'
        return [pscustomobject]@{Ok=$true;AlreadyRolledBack=$true;ForwardRequired=$false;PriorDaemonPid=[int]$terminal.DaemonPid;Detail='durable rollback exact prior state re-proved operational'}
    }
    [void](Invoke-SynapseBrokerApplicationDownstreamControlRollback -DownstreamTransition $validated.CandidateGateTransition -UpstreamTransition $validated.ParkedGateTransition -Context 'app_v4_candidate_gate')
    [void](Invoke-SynapseBrokerApplicationDownstreamControlRollback -DownstreamTransition $validated.CandidateRosterTransition -UpstreamTransition $validated.ParkedRosterTransition -Context 'app_v4_candidate_roster')
    if($null -ne $validated.CandidateRosterTransition.RestoredLease -and $null -ne $validated.ParkedRosterTransition){Move-SynapseAuthorityControlLeaseReverse -FromTransition $validated.CandidateRosterTransition -ToTransition $validated.ParkedRosterTransition}
    if($null -ne $validated.CandidateGateTransition.RestoredLease -and $null -ne $validated.ParkedGateTransition){Move-SynapseAuthorityControlLeaseReverse -FromTransition $validated.CandidateGateTransition -ToTransition $validated.ParkedGateTransition}
    $script:SynapseDeploymentTransaction=$Transaction
    [void](Invoke-SynapseBundledProfilesTransactionRollback -ProfilePlan $validated.ProfilePlan)
    [void](Invoke-SynapseRuntimeTransactionRollback -RuntimePlan $validated.RuntimePlan)
    if([string]$journal.Initial.prior_authority -ceq 'present'){
        [void](Invoke-SynapseAuthorityControlTransitionRollback -Transition $validated.ParkedRosterTransition)
        [void](Invoke-SynapseAuthorityControlTransitionRollback -Transition $validated.ParkedGateTransition)
    }
    $priorOperational=Assert-SynapseBrokerApplicationPriorOperational -Validated $validated -Initial $journal.Initial -Authority $Authority -HealthTimeoutSeconds $HealthTimeoutSeconds -Context 'app_v4_rollback_prior_generation'
    $priorPid=[int]$priorOperational.DaemonPid
    $local=$Transaction;$local.JournalSequence=[int]$journal.Sequence;$local.JournalSha256=[string]$journal.LatestRawSha256;$local.JournalState=[string]$journal.State
    [void](Add-SynapseDeploymentTransactionJournalState -State rolled_back -Payload ([ordered]@{authority_model='immutable_broker/v1';primary_failure_sha256=(Get-SynapseSha256Hex -Text $PrimaryFailure);prior_authority=[string]$journal.Initial.prior_authority;prior_generation_id=[string]$journal.Initial.current_generation_id;prior_daemon_pid=$priorPid;probe_task_absent=$true;runtime_restored=$true;profile_restored=$true;unknown_objects_preserved=$true}) -Transaction $local)
    $Transaction.RolledBack=$true;$Transaction.JournalState='rolled_back'
    return [pscustomobject]@{Ok=$true;ForwardRequired=$false;PriorDaemonPid=$priorPid;Detail='broker application prior generation restored and proved operational'}
}

function Assert-SynapseBrokerApplicationPriorOperational {
    param(
        [Parameter(Mandatory=$true)]$Validated,
        [Parameter(Mandatory=$true)]$Initial,
        [Parameter(Mandatory=$true)]$Authority,
        [ValidateRange(30,900)][int]$HealthTimeoutSeconds=420,
        [Parameter(Mandatory=$true)][string]$Context
    )
    if([string]$Initial.prior_authority -ceq 'present'){
        $pair=Read-SynapseAuthorityActiveControlPair -Layout $Authority.Layout -ExpectedState active -Context "${Context}_pair"
        try{
            $generation=ConvertTo-SynapseAuthorityGenerationFromCurrentRoster -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -ControlGate $pair.Gate -Roster $pair.Roster -Context "${Context}_generation"
            if([string]$generation.GenerationId -cne [string]$Initial.current_generation_id){Die "SYNAPSE_BROKER_APPLICATION_PRIOR_GENERATION_MISMATCH context=$Context expected=$($Initial.current_generation_id) actual=$($generation.GenerationId)"}
            $proof=Wait-SynapseCurrentAuthorityGenerationOperational -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -Generation $generation -ControlGateIdentity $Validated.CurrentControlGate -RosterIdentity $Validated.CurrentRoster -ControlGateLease $pair.GateLease -RosterLease $pair.RosterLease -HealthTimeoutSeconds $HealthTimeoutSeconds -Context $Context
            return [pscustomobject]@{DaemonPid=[int]$proof.DaemonPid;Generation=$generation;Proof=$proof;PriorAuthority='present'}
        }finally{Close-SynapseAuthorityActiveControlPair -Pair $pair}
    }
    $gateLease=$null;$rosterLease=$null
    foreach($transition in @($Validated.CandidateGateTransition,$Validated.ParkedGateTransition)){
        if($null-ne$transition){foreach($name in @('RestoredLease','PreLease','CanonicalLease')){if($null-ne$transition.$name){$gateLease=$transition.$name;break}}}
        if($null-ne$gateLease){break}
    }
    foreach($transition in @($Validated.CandidateRosterTransition,$Validated.ParkedRosterTransition)){
        if($null-ne$transition){foreach($name in @('RestoredLease','PreLease','CanonicalLease')){if($null-ne$transition.$name){$rosterLease=$transition.$name;break}}}
        if($null-ne$rosterLease){break}
    }
    $pair=Read-SynapseAuthorityActiveControlPair -Layout $Authority.Layout -GateLease $gateLease -RosterLease $rosterLease -ExpectedState parked -Context "${Context}_fresh_pair"
    try{
        $proof=Assert-SynapseBrokerParkedNoAuthority -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -ControlGateIdentity $Validated.CurrentControlGate -RosterIdentity $Validated.CurrentRoster -ControlGateLease $pair.GateLease -RosterLease $pair.RosterLease -Bind ([string]$Initial.bind) -DbPath ([string]$Initial.db_path)
        return [pscustomobject]@{DaemonPid=0;Generation=$null;Proof=$proof;PriorAuthority='absent'}
    }finally{Close-SynapseAuthorityActiveControlPair -Pair $pair}
}

function Merge-SynapseBrokerApplicationLiveTransitions {
    param(
        [Parameter(Mandatory=$true)]$Validated,
        [Parameter(Mandatory=$true)]$Transaction,
        [Parameter(Mandatory=$true)]$Initial
    )
    $bindings=@(
        @('ParkedGateTransition','parked_control_gate_transition'),
        @('ParkedRosterTransition','parked_roster_transition'),
        @('CandidateGateTransition','candidate_control_gate_transition'),
        @('CandidateRosterTransition','candidate_roster_transition')
    )
    foreach($binding in $bindings){
        $property=[string]$binding[0];$initialProperty=[string]$binding[1]
        if($null -eq $Transaction.PSObject.Properties[$property] -or $null -eq $Transaction.$property){continue}
        $live=$Transaction.$property;$declared=$Initial.$initialProperty
        if($null -eq $declared -or (Get-SynapseCanonicalJson -Value (Get-SynapseAuthorityControlTransitionDescriptor $live)) -cne (Get-SynapseCanonicalJson -Value (ConvertTo-SynapseCanonicalValue -Value $declared))){
            Die "SYNAPSE_BROKER_APPLICATION_LIVE_TRANSITION_DESCRIPTOR_MISMATCH property=$property root=$($Transaction.Root)"
        }
        $Validated.$property=$live
    }
    if($null -ne $Transaction.PSObject.Properties['RuntimePlan'] -and $null -ne $Transaction.RuntimePlan){
        $liveRuntimeDescriptor=$Transaction.RuntimePlan.Descriptor
        $declaredRuntimeDescriptor=$Initial.runtime_transaction
        if([string]$liveRuntimeDescriptor.static_plan_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or
           [string]$liveRuntimeDescriptor.static_plan_sha256 -ine [string]$declaredRuntimeDescriptor.static_plan_sha256 -or
           (Get-SynapseNormalizedDirectoryPath -Path ([string]$liveRuntimeDescriptor.transaction_root)) -ine (Get-SynapseNormalizedDirectoryPath -Path ([string]$declaredRuntimeDescriptor.transaction_root))){
            Die "SYNAPSE_BROKER_APPLICATION_LIVE_RUNTIME_DESCRIPTOR_MISMATCH root=$($Transaction.Root)"
        }
        $Validated.RuntimePlan=$Transaction.RuntimePlan
    }
}

function Invoke-SynapseBrokerApplicationDownstreamControlRollback {
    param(
        [Parameter(Mandatory=$true)]$DownstreamTransition,
        $UpstreamTransition,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $canonical=Get-SynapsePhysicalRelativeState -ParentPath $DownstreamTransition.parent -ParentChain $DownstreamTransition.parent_chain -Leaf $DownstreamTransition.leaf
    $canonicalIsPre=Test-SynapsePhysicalStateExact -State $canonical -ExpectedExists ([bool]$DownstreamTransition.pre_existed) -ExpectedFileId128 $DownstreamTransition.pre_file_id_128 -ExpectedSha256 $DownstreamTransition.pre_sha256 -ExpectedLength $DownstreamTransition.pre_length
    $canonicalIsPost=Test-SynapsePhysicalStateExact -State $canonical -ExpectedExists $true -ExpectedFileId128 $DownstreamTransition.post_file_id_128 -ExpectedSha256 $DownstreamTransition.post_sha256 -ExpectedLength $DownstreamTransition.post_length
    $discard=Get-SynapseAuthorityControlRootState -Transition $DownstreamTransition -Leaf $DownstreamTransition.discard_leaf
    $discardIsPost=Test-SynapsePhysicalStateExact -State $discard -ExpectedExists $true -ExpectedFileId128 $DownstreamTransition.post_file_id_128 -ExpectedSha256 $DownstreamTransition.post_sha256 -ExpectedLength $DownstreamTransition.post_length
    if($discard.Exists -and -not $discardIsPost){Die "SYNAPSE_BROKER_APPLICATION_DOWNSTREAM_DISCARD_UNKNOWN context=$Context leaf=$($DownstreamTransition.discard_leaf) file_id_128=$($discard.FileId128)"}
    if($discardIsPost){
        # A crash may occur after the downstream postimage was retired and the
        # upstream rollback subsequently moved its postimage again.  The exact
        # downstream discard is the durable proof that this transition has
        # already been reversed; the upstream rollback below still validates
        # every possible location of its own exact pre/post objects.
        return [pscustomobject]@{Restored=$true;State='downstream_post_already_discarded'}
    }
    if($canonicalIsPre -or $canonicalIsPost){return Invoke-SynapseAuthorityControlTransitionRollback -Transition $DownstreamTransition}
    if($null -eq $UpstreamTransition){
        Die "SYNAPSE_BROKER_APPLICATION_DOWNSTREAM_CANONICAL_UNKNOWN context=$Context path=$($DownstreamTransition.path) file_id_128=$($canonical.FileId128)"
    }
    $stage=Get-SynapseAuthorityControlRootState -Transition $DownstreamTransition -Leaf $DownstreamTransition.stage_leaf
    $park=Get-SynapseAuthorityControlRootState -Transition $DownstreamTransition -Leaf $DownstreamTransition.park_leaf
    $stageIsPost=Test-SynapsePhysicalStateExact -State $stage -ExpectedExists $true -ExpectedFileId128 $DownstreamTransition.post_file_id_128 -ExpectedSha256 $DownstreamTransition.post_sha256 -ExpectedLength $DownstreamTransition.post_length
    if($park.Exists -or -not $stageIsPost){
        Die "SYNAPSE_BROKER_APPLICATION_DOWNSTREAM_LIFECYCLE_UNKNOWN context=$Context canonical_exists=$($canonical.Exists) stage_exact=$stageIsPost park_exists=$($park.Exists)"
    }
    $upstreamCanonicalIsPre=Test-SynapsePhysicalStateExact -State $canonical -ExpectedExists ([bool]$UpstreamTransition.pre_existed) -ExpectedFileId128 $UpstreamTransition.pre_file_id_128 -ExpectedSha256 $UpstreamTransition.pre_sha256 -ExpectedLength $UpstreamTransition.pre_length
    $upstreamPark=Get-SynapseAuthorityControlRootState -Transition $UpstreamTransition -Leaf $UpstreamTransition.park_leaf
    $upstreamStage=Get-SynapseAuthorityControlRootState -Transition $UpstreamTransition -Leaf $UpstreamTransition.stage_leaf
    $upstreamParkIsPre=Test-SynapsePhysicalStateExact -State $upstreamPark -ExpectedExists ([bool]$UpstreamTransition.pre_existed) -ExpectedFileId128 $UpstreamTransition.pre_file_id_128 -ExpectedSha256 $UpstreamTransition.pre_sha256 -ExpectedLength $UpstreamTransition.pre_length
    $upstreamStageIsPost=Test-SynapsePhysicalStateExact -State $upstreamStage -ExpectedExists $true -ExpectedFileId128 $UpstreamTransition.post_file_id_128 -ExpectedSha256 $UpstreamTransition.post_sha256 -ExpectedLength $UpstreamTransition.post_length
    if($upstreamCanonicalIsPre -or (-not $canonical.Exists -and $upstreamParkIsPre -and $upstreamStageIsPost)){
        return [pscustomobject]@{Restored=$true;State='downstream_not_materialized'}
    }
    Die "SYNAPSE_BROKER_APPLICATION_DOWNSTREAM_PREPUBLICATION_UNKNOWN context=$Context canonical_exists=$($canonical.Exists) upstream_pre_exact=$upstreamCanonicalIsPre upstream_park_exact=$upstreamParkIsPre upstream_stage_exact=$upstreamStageIsPost"
}

function Invoke-SynapseBrokerApplicationForwardControlChain {
    param(
        $UpstreamTransition,
        [Parameter(Mandatory=$true)]$DownstreamTransition,
        [Parameter(Mandatory=$true)]$Allocation,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $canonical=Get-SynapsePhysicalRelativeState -ParentPath $DownstreamTransition.parent -ParentChain $DownstreamTransition.parent_chain -Leaf $DownstreamTransition.leaf
    $candidateIsPost=Test-SynapsePhysicalStateExact -State $canonical -ExpectedExists $true -ExpectedFileId128 $DownstreamTransition.post_file_id_128 -ExpectedSha256 $DownstreamTransition.post_sha256 -ExpectedLength $DownstreamTransition.post_length
    if(-not $candidateIsPost){
        $stage=Get-SynapseAuthorityControlRootState -Transition $DownstreamTransition -Leaf $DownstreamTransition.stage_leaf
        $discard=Get-SynapseAuthorityControlRootState -Transition $DownstreamTransition -Leaf $DownstreamTransition.discard_leaf
        $discardIsPost=Test-SynapsePhysicalStateExact -State $discard -ExpectedExists $true -ExpectedFileId128 $DownstreamTransition.post_file_id_128 -ExpectedSha256 $DownstreamTransition.post_sha256 -ExpectedLength $DownstreamTransition.post_length
        if(-not $stage.Exists -and $discardIsPost){
            $artifact=$Allocation.Artifacts[[string]$DownstreamTransition.stage_leaf]
            if($null-eq$artifact){Die "SYNAPSE_BROKER_APPLICATION_FORWARD_STAGE_DESCRIPTOR_MISSING context=$Context leaf=$($DownstreamTransition.stage_leaf)"}
            $lease=Open-SynapsePhysicalFileTransitionLease -ParentPath $DownstreamTransition.transaction_root -ParentChain $DownstreamTransition.transaction_root_chain -Leaf $DownstreamTransition.discard_leaf -ExpectedFileId128 $DownstreamTransition.post_file_id_128 -ExpectedSha256 $DownstreamTransition.post_sha256 -ExpectedLength $DownstreamTransition.post_length -Context "${Context}_recover_discarded_post"
            try{
                [void]$lease.MoveNoReplace($Allocation.Root,(Get-SynapsePhysicalChainPaths -Chain $Allocation.RootChain),(Get-SynapsePhysicalChainFileIds -Chain $Allocation.RootChain),[string]$DownstreamTransition.stage_leaf)
                if($null-eq$artifact.PSObject.Properties['handle']){$artifact|Add-Member -NotePropertyName handle -NotePropertyValue $lease}else{$artifact.handle=$lease}
                $lease=$null
            }finally{if($null-ne$lease){$lease.Dispose()}}
        }
    }
    if(-not $candidateIsPost -and $null -ne $UpstreamTransition){
        $downstreamPark=Get-SynapseAuthorityControlRootState -Transition $DownstreamTransition -Leaf $DownstreamTransition.park_leaf
        $downstreamParkIsPre=Test-SynapsePhysicalStateExact -State $downstreamPark -ExpectedExists $true -ExpectedFileId128 $DownstreamTransition.pre_file_id_128 -ExpectedSha256 $DownstreamTransition.pre_sha256 -ExpectedLength $DownstreamTransition.pre_length
        if(-not $downstreamParkIsPre){
            [void](Invoke-SynapseAuthorityControlTransition -Transition $UpstreamTransition -AllocationContext $Allocation -ForwardOnly)
            Move-SynapseAuthorityControlLeaseForward -FromTransition $UpstreamTransition -ToTransition $DownstreamTransition
        }
    }
    [void](Invoke-SynapseAuthorityControlTransition -Transition $DownstreamTransition -AllocationContext $Allocation -ForwardOnly)
    return $DownstreamTransition.CanonicalLease
}

function Restore-SynapseBrokerApplicationCommittedDiscardedPost {
    param(
        [Parameter(Mandatory=$true)]$Descriptor,
        [Parameter(Mandatory=$true)][string]$TransactionRoot,
        [Parameter(Mandatory=$true)]$Allocation,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $transition=ConvertTo-SynapseAuthorityControlTransition -Descriptor $Descriptor -TransactionRoot $TransactionRoot -Allocation $Allocation
    $stage=Get-SynapseAuthorityControlRootState -Transition $transition -Leaf $transition.stage_leaf
    if($stage.Exists){return}
    $discard=Get-SynapseAuthorityControlRootState -Transition $transition -Leaf $transition.discard_leaf
    if(-not (Test-SynapsePhysicalStateExact -State $discard -ExpectedExists $true -ExpectedFileId128 $transition.post_file_id_128 -ExpectedSha256 $transition.post_sha256 -ExpectedLength $transition.post_length)){return}
    $canonical=Get-SynapsePhysicalRelativeState -ParentPath $transition.parent -ParentChain $transition.parent_chain -Leaf $transition.leaf
    if(-not (Test-SynapsePhysicalStateExact -State $canonical -ExpectedExists ([bool]$transition.pre_existed) -ExpectedFileId128 $transition.pre_file_id_128 -ExpectedSha256 $transition.pre_sha256 -ExpectedLength $transition.pre_length)){
        Die "SYNAPSE_BROKER_APPLICATION_COMMITTED_DISCARD_RECOVERY_CANONICAL_DRIFT context=$Context path=$($transition.path)"
    }
    $artifact=$Allocation.Artifacts[[string]$transition.stage_leaf]
    $lease=Open-SynapsePhysicalFileTransitionLease -ParentPath $transition.transaction_root -ParentChain $transition.transaction_root_chain -Leaf $transition.discard_leaf -ExpectedFileId128 $transition.post_file_id_128 -ExpectedSha256 $transition.post_sha256 -ExpectedLength $transition.post_length -Context "${Context}_discard"
    try{
        [void]$lease.MoveNoReplace($Allocation.Root,(Get-SynapsePhysicalChainPaths -Chain $Allocation.RootChain),(Get-SynapsePhysicalChainFileIds -Chain $Allocation.RootChain),[string]$transition.stage_leaf)
        if($null-eq$artifact.PSObject.Properties['handle']){$artifact|Add-Member -NotePropertyName handle -NotePropertyValue $lease}else{$artifact.handle=$lease}
        $lease=$null
    }finally{if($null-ne$lease){$lease.Dispose()}}
    Info "SYNAPSE_BROKER_APPLICATION_COMMITTED_DISCARDED_POST_RESTORED context=$Context leaf=$($transition.stage_leaf) file_id_128=$($transition.post_file_id_128)"
}

function Complete-SynapseBrokerApplicationCommittedGeneration {
    param(
        [Parameter(Mandatory=$true)]$Transaction,
        [Parameter(Mandatory=$true)]$Authority,
        [ValidateRange(30,900)][int]$HealthTimeoutSeconds=420
    )
    $journal=Read-SynapseDeploymentTransactionJournal -TransactionRoot $Transaction.Root -TransactionRootChain $Transaction.RootChain
    $effective=if([string]$journal.State -ceq 'cleanup_ready'){[string]$journal.Latest.detail.terminal_state}else{[string]$journal.State}
    if($effective -ne 'commit_decided'){Die "SYNAPSE_BROKER_APPLICATION_FORWARD_STATE_INVALID root=$($Transaction.Root) state=$($journal.State) effective=$effective"}
    Restore-SynapseBrokerApplicationCommittedDiscardedPost -Descriptor $journal.Initial.candidate_roster_transition -TransactionRoot $Transaction.Root -Allocation $journal.Allocation -Context 'app_v4_candidate_roster'
    Restore-SynapseBrokerApplicationCommittedDiscardedPost -Descriptor $journal.Initial.candidate_control_gate_transition -TransactionRoot $Transaction.Root -Allocation $journal.Allocation -Context 'app_v4_candidate_gate'
    # In the no-crash commit path the live transitions retain the stage files
    # with deny-write sharing until publication completes. Crossbind those
    # descriptors before lending their exact read handles to the reconstructed
    # journal view; crash recovery has no live handles and instead locates the
    # sole exact postimage on disk.
    foreach($binding in @(
        @('CandidateRosterTransition','candidate_roster_transition'),
        @('CandidateGateTransition','candidate_control_gate_transition')
    )){
        $property=[string]$binding[0];$initialProperty=[string]$binding[1]
        if($null-eq$Transaction.PSObject.Properties[$property]-or$null-eq$Transaction.$property){continue}
        $live=$Transaction.$property;$declared=$journal.Initial.$initialProperty
        if((Get-SynapseCanonicalJson -Value (Get-SynapseAuthorityControlTransitionDescriptor $live)) -cne (Get-SynapseCanonicalJson -Value (ConvertTo-SynapseCanonicalValue -Value $declared))){Die "SYNAPSE_BROKER_APPLICATION_LIVE_TRANSITION_DESCRIPTOR_MISMATCH property=$property root=$($Transaction.Root)"}
        $liveArtifact=Get-SynapseObjectPropertyValue -Object $live -Names @('StageArtifact','stage_artifact')
        $liveHandle=if($null-ne$liveArtifact){Get-SynapseObjectPropertyValue -Object $liveArtifact -Names @('handle','Handle')}else{$null}
        if($null-ne$liveHandle){
            $journalArtifact=$journal.Allocation.Artifacts[[string]$declared.stage_leaf]
            if($null-eq$journalArtifact.PSObject.Properties['handle']){$journalArtifact|Add-Member -NotePropertyName handle -NotePropertyValue $liveHandle}else{$journalArtifact.handle=$liveHandle}
        }
    }
    $validated=Assert-SynapseBrokerApplicationInitialDescriptor -Initial $journal.Initial -TransactionRoot $Transaction.Root -Allocation $journal.Allocation -ExpectedRuntimePaths @($Transaction.ExpectedRuntimePaths) -AllowCommittedDiscardedPost
    Merge-SynapseBrokerApplicationLiveTransitions -Validated $validated -Transaction $Transaction -Initial $journal.Initial
    $script:SynapseDeploymentTransaction=$Transaction
    Complete-SynapseRuntimeCommittedGeneration -RuntimePlan $validated.RuntimePlan
    Complete-SynapseBundledProfilesCommittedGeneration -ProfilePlan $validated.ProfilePlan
    # Roster first while the canonical control gate remains parked; only the
    # final gate publication grants persistent authority to the candidate.
    [void](Invoke-SynapseBrokerApplicationForwardControlChain -UpstreamTransition $validated.ParkedRosterTransition -DownstreamTransition $validated.CandidateRosterTransition -Allocation $journal.Allocation -Context 'app_v4_candidate_roster')
    [void](Invoke-SynapseBrokerApplicationForwardControlChain -UpstreamTransition $validated.ParkedGateTransition -DownstreamTransition $validated.CandidateGateTransition -Allocation $journal.Allocation -Context 'app_v4_candidate_gate')
    $pair=Read-SynapseAuthorityActiveControlPair -Layout $Authority.Layout -GateLease $validated.CandidateGateTransition.CanonicalLease -RosterLease $validated.CandidateRosterTransition.CanonicalLease -ExpectedState active -Context 'app_v4_candidate_active_pair'
    try{
        $generation=ConvertTo-SynapseAuthorityGenerationFromCurrentRoster -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -ControlGate $pair.Gate -Roster $pair.Roster -Context 'app_v4_candidate_generation'
        if([string]$generation.GenerationId -cne [string]$journal.Initial.candidate_generation.generation_id){Die "SYNAPSE_BROKER_APPLICATION_FORWARD_GENERATION_MISMATCH expected=$($journal.Initial.candidate_generation.generation_id) actual=$($generation.GenerationId)"}
        $proof=Wait-SynapseCurrentAuthorityGenerationOperational -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -Generation $generation -ControlGateIdentity ([pscustomobject]@{Path=$Authority.Layout.ControlGatePath;FileId128=$validated.CandidateGateTransition.post_file_id_128;Sha256=$validated.CandidateGateTransition.post_sha256;Length=$validated.CandidateGateTransition.post_length}) -RosterIdentity ([pscustomobject]@{Path=$Authority.Layout.RosterPath;FileId128=$validated.CandidateRosterTransition.post_file_id_128;Sha256=$validated.CandidateRosterTransition.post_sha256;Length=$validated.CandidateRosterTransition.post_length}) -ControlGateLease $pair.GateLease -RosterLease $pair.RosterLease -HealthTimeoutSeconds $HealthTimeoutSeconds -Context 'app_v4_candidate_generation'
    }finally{Close-SynapseAuthorityActiveControlPair -Pair $pair}
    $Transaction.Committed=$true;$Transaction.JournalState='commit_decided'
    return [pscustomobject][ordered]@{Generation=$generation;Proof=$proof;Validated=$validated;Journal=$journal}
}

function Invoke-SynapseBrokerApplicationDeployment {
    param(
        [Parameter(Mandatory=$true)]$Authority,
        [Parameter(Mandatory=$true)][string]$DeploymentTransactionParent,
        [Parameter(Mandatory=$true)]$DeploymentTransactionParentChain,
        [Parameter(Mandatory=$true)]$RuntimeMappings,
        [Parameter(Mandatory=$true)][string]$SourceProfilesDir,
        [Parameter(Mandatory=$true)][string]$ExePath,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$DbPath,
        [Parameter(Mandatory=$true)][string]$ProfilesDir,
        [Parameter(Mandatory=$true)][string]$LogDir,
        [Parameter(Mandatory=$true)][string]$TokenPath,
        [Parameter(Mandatory=$true)][string]$Token,
        [Parameter(Mandatory=$true)][string]$MaintenanceLockPath,
        [Parameter(Mandatory=$true)][string]$CalyxConfigPath,
        [Parameter(Mandatory=$true)][ValidatePattern('^[0-9A-Fa-f]{64}$')][string]$ExpectedCalyxConfigSha256,
        [bool]$EnableAudio,
        [AllowNull()][string]$AllowedPermissions,
        [Parameter(Mandatory=$true)][string]$PowerShellPath,
        [Parameter(Mandatory=$true)][string]$WorkingDirectory,
        [Parameter(Mandatory=$true)]$SourceProbe,
        [AllowNull()][string]$ReplacementReservationId,
        [ValidateRange(30,900)][int]$HealthTimeoutSeconds=420
    )
    $authorityTaskDescriptor=ConvertTo-SynapseAuthorityTaskDescriptor -Task $Authority.BrokerTask
    [void](Assert-SynapseBrokerTaskDescriptorAuthorityCrossbind -Descriptor $authorityTaskDescriptor -BrokerIdentitySha256 ([string]$Authority.Infrastructure.BrokerIdentitySha256) -TaskCapabilitySha256 ([string]$Authority.Infrastructure.TaskCapabilitySha256) -Infrastructure $Authority.Infrastructure -Context 'broker_application_prearm_task')
    $runtimeExpectedPaths=@($RuntimeMappings|ForEach-Object{[System.IO.Path]::GetFullPath([string]$_.DestinationPath)}|Sort-Object -Unique)
    if($runtimeExpectedPaths.Count -ne @($RuntimeMappings).Count -or $runtimeExpectedPaths.Count -lt 1){Die "SYNAPSE_BROKER_APPLICATION_RUNTIME_MAPPING_SET_INVALID count=$(@($RuntimeMappings).Count) unique=$($runtimeExpectedPaths.Count)"}
    if([int]$SourceProbe.ToolCount -lt 1 -or [string]$SourceProbe.ToolSurfaceSha256 -notmatch '^[0-9A-Fa-f]{64}$'){Die "SYNAPSE_BROKER_APPLICATION_SOURCE_PROBE_INVALID tool_count=$($SourceProbe.ToolCount) tool_surface_sha256=$($SourceProbe.ToolSurfaceSha256)"}
    $priorAuthority=if($null -eq $Authority.CurrentGeneration){'absent'}else{'present'}
    if($script:SynapseManualInstallHealthRollbackProbe -and $priorAuthority -ceq 'absent'){
        Die 'SYNAPSE_MANUAL_INSTALL_HEALTH_ROLLBACK_PROBE_REQUIRES_PRIOR_BROKER_GENERATION remediation=complete one broker-owned deployment before exercising exact prior-generation rollback'
    }
    if($script:SynapseManualInstallHealthRollbackProbe -and [string]$script:SynapseManualInstallHealthRollbackPauseMode -cne 'normal'){
        Die "SYNAPSE_MANUAL_INSTALL_HEALTH_ROLLBACK_PROBE_BROKER_PAUSE_MODE_UNSUPPORTED mode=$($script:SynapseManualInstallHealthRollbackPauseMode) remediation=use normal; broker-v4 revokes persistent candidate authority before the one-shot installed probe and does not borrow Chrome bridge acknowledgment as rollback authority"
    }
    $expectedPairState=if($priorAuthority -ceq 'present'){'active'}else{'parked'}
    $pair=Read-SynapseAuthorityActiveControlPair -Layout $Authority.Layout -ExpectedState $expectedPairState -Context "app_v4_plan_${priorAuthority}_pair"
    $root=$null;$rootChain=$null;$allocation=$null;$localTransaction=$null;$profilePlan=$null;$runtimePlan=$null;$preparedProbe=$null
    $parkedGateTransition=$null;$parkedRosterTransition=$null;$candidateGateTransition=$null;$candidateRosterTransition=$null
    $profileGuard=$null;$runtimeGuards=@();$previousAllocation=$script:SynapseDeploymentAllocationContext;$previousTransaction=$script:SynapseDeploymentTransaction
    try{
        $currentPayload=$pair.Roster.Payload
        if([string]$currentPayload.broker_identity_sha256 -ine [string]$Authority.Infrastructure.BrokerIdentitySha256 -or [int64]$currentPayload.authority_epoch -ne [int64]$Authority.AuthorityEpoch -or [string]$currentPayload.control_nonce -ine [string]$Authority.ControlNonce){Die "SYNAPSE_BROKER_APPLICATION_CURRENT_PAIR_EPOCH_DRIFT prior=$priorAuthority"}
        if($priorAuthority -ceq 'present' -and [string]$currentPayload.generation_id -cne [string]$Authority.CurrentGeneration.GenerationId){Die "SYNAPSE_BROKER_APPLICATION_CURRENT_GENERATION_DRIFT expected=$($Authority.CurrentGeneration.GenerationId) actual=$($currentPayload.generation_id)"}
        $stamp=(Get-Date).ToUniversalTime().ToString('yyyyMMddTHHmmssfffZ');$leaf="deployment-$stamp-$PID"
        $created=[SynapseSetup.AtomicFileV2]::CreatePhysicalDirectoryRelative($DeploymentTransactionParent,(Get-SynapsePhysicalChainPaths -Chain $DeploymentTransactionParentChain),(Get-SynapsePhysicalChainFileIds -Chain $DeploymentTransactionParentChain),$leaf)
        $root=Get-SynapseNormalizedDirectoryPath -Path ([string]$created.Path);$rootChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $root)
        $allocation=New-SynapseDeploymentAllocationContext -TransactionRoot $root -TransactionRootChain $rootChain -InvocationId $script:SynapseSetupInvocationId -OwnerPid $PID
        $script:SynapseDeploymentAllocationContext=$allocation
        New-SynapseDeploymentPreallocatedJournalSlots -Context $allocation
        $profilePlan=New-SynapseBundledProfilesDeploymentPlan -SourceProfilesDir $SourceProfilesDir -ProfilesDir $ProfilesDir -TransactionRoot $root -AllocationContext $allocation
        $runtimePlan=New-SynapseRuntimeDeploymentPlan -AllocationContext $allocation -Mappings $RuntimeMappings -PreArmReadOnly
        $probeCapability=(Get-SynapseSha256Hex -Text "synapse-installed-probe:$($script:SynapseSetupInvocationId):${leaf}:$([Guid]::NewGuid().ToString('N'))").ToUpperInvariant()
        $preparedProbe=New-SynapseCandidateTaskProbePreparation -CandidateExePath $ExePath -CandidateBootstrapPath ([string]$Authority.Infrastructure.Bootstrap.Path) -ExpectedCandidateBootstrapSha256 ([string]$Authority.Infrastructure.Bootstrap.Sha256) -ProfilesDir $ProfilesDir -TokenPath $TokenPath -LogDir $LogDir -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions -CalyxConfigPath $CalyxConfigPath -ExpectedCalyxConfigSha256 $ExpectedCalyxConfigSha256 -ReplacementReservationId $ReplacementReservationId -ProbeCapability $probeCapability
        $probeDescriptor=ConvertTo-SynapseCandidateProbePlanJournalDescriptor -PlanAuthority $preparedProbe.PlanAuthority
        $currentGateIdentity=[pscustomobject]@{Path=$Authority.Layout.ControlGatePath;FileId128=$pair.Gate.FileId128;Sha256=$pair.Gate.Sha256;Length=$pair.Gate.Length}
        $currentRosterIdentity=[pscustomobject]@{Path=$Authority.Layout.RosterPath;FileId128=$pair.Roster.FileId128;Sha256=$pair.Roster.Sha256;Length=$pair.Roster.Length}
        $legacyGate=[pscustomobject]@{Path=[string]$currentPayload.legacy_gate_path;FileId128=[string]$currentPayload.legacy_gate_file_id_128;Sha256=[string]$currentPayload.legacy_gate_sha256;Length=[int64]$currentPayload.legacy_gate_length}
        $parkedRosterIdentity=$currentRosterIdentity;$parkedGateIdentity=$currentGateIdentity
        $nextRevision=[int64]$currentPayload.revision+1
        if($priorAuthority -ceq 'present'){
            $parkedPayload=New-SynapseAuthorityRosterPayload -BrokerIdentitySha256 $Authority.Infrastructure.BrokerIdentitySha256 -TaskCapabilitySha256 $Authority.Infrastructure.TaskCapabilitySha256 -AuthorityEpoch ([int64]$Authority.AuthorityEpoch) -Revision $nextRevision -Mode parked -Role none -BrokerTask $Authority.BrokerTask -AuthorityRoot $Authority.Layout.Root -AuthorityRootFileId128 ([string]$Authority.Layout.RootChain[-1].file_id_128) -RuntimeBinDir $Authority.Layout.RuntimeBinDir -RuntimeBinFileId128 ([string]$Authority.Layout.RuntimeChain[-1].file_id_128) -BrokerScript $Authority.Infrastructure.BrokerScript -Bootstrap $Authority.Infrastructure.Bootstrap -ControlGatePath $Authority.Layout.ControlGatePath -ControlNonce ([string]$Authority.ControlNonce) -LegacyGate $legacyGate -Bind ([string]$currentPayload.bind) -DbPath ([string]$currentPayload.db_path) -ProfilesDir ([string]$currentPayload.profiles_dir) -TokenPath ([string]$currentPayload.token_path) -CalyxConfigPath ([string]$currentPayload.calyx_config_path) -EnableAudio ([bool]$currentPayload.enable_audio) -AllowedPermissions ([string]$currentPayload.allowed_permissions) -PowerShellPath ([string]$currentPayload.powershell_path) -WorkingDirectory ([string]$currentPayload.working_directory) -LogDir ([string]$currentPayload.log_dir) -BrokerBootstrapLogPath ([string]$currentPayload.bootstrap_log_path) -MaintenanceLockPath ([string]$currentPayload.maintenance_lock_path) -InvocationId $leaf -PreviousRevision ([int64]$currentPayload.revision) -PreviousFileId128 ([string]$pair.Roster.FileId128) -PreviousSha256 ([string]$pair.Roster.Sha256) -PreviousLength ([int64]$pair.Roster.Length)
            $parkedEnvelope=New-SynapseAuthorityRosterEnvelope -Payload $parkedPayload
            $parkedRosterTransition=New-SynapseAuthorityControlTransitionPlan -AllocationContext $allocation -DestinationParent $Authority.Layout.Root -DestinationParentChain $Authority.Layout.RootChain -DestinationLeaf $Authority.Layout.RosterLeaf -StageLeaf 'app-roster-parked-stage.json' -ParkLeaf 'app-roster-prior-park.json' -DiscardLeaf 'app-roster-parked-discard.json' -ReplacementContent $parkedEnvelope.Text -ExpectedPreState ([pscustomobject]@{Exists=$true;FileId128=$pair.Roster.FileId128;Sha256=$pair.Roster.Sha256;Length=$pair.Roster.Length}) -Purpose 'broker_application_parked_roster'
            $parkedRosterIdentity=[pscustomobject]@{Path=$Authority.Layout.RosterPath;FileId128=$parkedRosterTransition.post_file_id_128;Sha256=$parkedRosterTransition.post_sha256;Length=$parkedRosterTransition.post_length}
            $parkedGateEnvelope=New-SynapseAuthorityControlGateEnvelope -BrokerIdentitySha256 $Authority.Infrastructure.BrokerIdentitySha256 -AuthorityEpoch ([int64]$Authority.AuthorityEpoch) -ControlNonce ([string]$Authority.ControlNonce) -State parked -Roster $parkedRosterIdentity -ApplicationTransactionId $leaf
            $parkedGateTransition=New-SynapseAuthorityControlTransitionPlan -AllocationContext $allocation -DestinationParent $Authority.Layout.Root -DestinationParentChain $Authority.Layout.RootChain -DestinationLeaf $Authority.Layout.ControlGateLeaf -StageLeaf 'app-gate-parked-stage.json' -ParkLeaf 'app-gate-prior-park.json' -DiscardLeaf 'app-gate-parked-discard.json' -ReplacementContent $parkedGateEnvelope.Text -ExpectedPreState ([pscustomobject]@{Exists=$true;FileId128=$pair.Gate.FileId128;Sha256=$pair.Gate.Sha256;Length=$pair.Gate.Length}) -Purpose 'broker_application_parked_gate'
            $parkedGateIdentity=[pscustomobject]@{Path=$Authority.Layout.ControlGatePath;FileId128=$parkedGateTransition.post_file_id_128;Sha256=$parkedGateTransition.post_sha256;Length=$parkedGateTransition.post_length}
            $parkedGateTransition.PreLease=$pair.GateLease;$pair.GateLease=$null;$pair.OwnsGateLease=$false
            $parkedRosterTransition.PreLease=$pair.RosterLease;$pair.RosterLease=$null;$pair.OwnsRosterLease=$false
            $nextRevision++
        }
        $candidateGeneration=New-SynapseAuthorityProspectiveGenerationPlan -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -BrokerTask $Authority.BrokerTask -ControlNonce ([string]$Authority.ControlNonce) -LegacyGate $legacyGate -AuthorityEpoch ([int64]$Authority.AuthorityEpoch) -RuntimePlan $runtimePlan -ProfilePlan $profilePlan -ExePath $ExePath -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -LogDir $LogDir -TokenPath $TokenPath -MaintenanceLockPath $MaintenanceLockPath -CalyxConfigPath $CalyxConfigPath -ExpectedCalyxConfigSha256 $ExpectedCalyxConfigSha256 -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions -PowerShellPath $PowerShellPath -WorkingDirectory $WorkingDirectory -ExpectedToolCount ([int]$SourceProbe.ToolCount) -ExpectedToolSurfaceSha256 ([string]$SourceProbe.ToolSurfaceSha256) -InvocationId $leaf -RosterRevision $nextRevision -PreviousRevision ($nextRevision-1) -PreviousFileId128 ([string]$parkedRosterIdentity.FileId128) -PreviousSha256 ([string]$parkedRosterIdentity.Sha256) -PreviousLength ([int64]$parkedRosterIdentity.Length)
        $candidateRosterTransition=New-SynapseAuthorityControlTransitionPlan -AllocationContext $allocation -DestinationParent $Authority.Layout.Root -DestinationParentChain $Authority.Layout.RootChain -DestinationLeaf $Authority.Layout.RosterLeaf -StageLeaf 'app-roster-candidate-stage.json' -ParkLeaf 'app-roster-parked-park.json' -DiscardLeaf 'app-roster-candidate-discard.json' -ReplacementContent $candidateGeneration.RosterEnvelope.Text -ExpectedPreState ([pscustomobject]@{Exists=$true;FileId128=$parkedRosterIdentity.FileId128;Sha256=$parkedRosterIdentity.Sha256;Length=$parkedRosterIdentity.Length}) -Purpose 'broker_application_candidate_roster'
        $candidateRosterIdentity=[pscustomobject]@{Path=$Authority.Layout.RosterPath;FileId128=$candidateRosterTransition.post_file_id_128;Sha256=$candidateRosterTransition.post_sha256;Length=$candidateRosterTransition.post_length}
        $candidateGateEnvelope=New-SynapseAuthorityControlGateEnvelope -BrokerIdentitySha256 $Authority.Infrastructure.BrokerIdentitySha256 -AuthorityEpoch ([int64]$Authority.AuthorityEpoch) -ControlNonce ([string]$Authority.ControlNonce) -State active -Roster $candidateRosterIdentity -ApplicationTransactionId $leaf
        $candidateGateTransition=New-SynapseAuthorityControlTransitionPlan -AllocationContext $allocation -DestinationParent $Authority.Layout.Root -DestinationParentChain $Authority.Layout.RootChain -DestinationLeaf $Authority.Layout.ControlGateLeaf -StageLeaf 'app-gate-candidate-stage.json' -ParkLeaf 'app-gate-parked-park.json' -DiscardLeaf 'app-gate-candidate-discard.json' -ReplacementContent $candidateGateEnvelope.Text -ExpectedPreState ([pscustomobject]@{Exists=$true;FileId128=$parkedGateIdentity.FileId128;Sha256=$parkedGateIdentity.Sha256;Length=$parkedGateIdentity.Length}) -Purpose 'broker_application_candidate_gate'
        if($priorAuthority -ceq 'absent'){
            $candidateGateTransition.PreLease=$pair.GateLease;$pair.GateLease=$null;$pair.OwnsGateLease=$false
            $candidateRosterTransition.PreLease=$pair.RosterLease;$pair.RosterLease=$null;$pair.OwnsRosterLease=$false
        }
        Close-SynapseAuthorityActiveControlPair -Pair $pair;$pair=$null
        $allocationRecord=Complete-SynapseDeploymentAllocationLog -Context $allocation
        $candidateDescriptor=[ordered]@{generation_id=[string]$candidateGeneration.GenerationId;runtime_generation_sha256=([string]$candidateGeneration.RuntimeGenerationSha256).ToUpperInvariant();profile_generation_sha256=([string]$candidateGeneration.ProfileGenerationSha256).ToUpperInvariant();expected_tool_count=[int]$SourceProbe.ToolCount;expected_tool_surface_sha256=([string]$SourceProbe.ToolSurfaceSha256).ToUpperInvariant();supervisor=(ConvertTo-SynapseAuthorityFileDescriptor -Identity $candidateGeneration.Supervisor -Role 'candidate_generation_supervisor')}
        $initial=[ordered]@{schema='synapse_deployment_transaction/v4';state='armed';transaction_kind='synapse_broker_application/v1';authority_model='immutable_broker/v1';invocation_id=$script:SynapseSetupInvocationId;armed_at_utc=[DateTime]::UtcNow.ToString('o');transaction_root=$root;transaction_root_file_id_128=([string]$created.FileId128).ToUpperInvariant();allocation_marker=$allocationRecord;runtime_bin_dir=$Authority.Layout.RuntimeBinDir;profiles_dir=[System.IO.Path]::GetFullPath($ProfilesDir);bind=$Bind;db_path=[System.IO.Path]::GetFullPath($DbPath);token_path=[System.IO.Path]::GetFullPath($TokenPath);calyx_config_path=[System.IO.Path]::GetFullPath($CalyxConfigPath);calyx_config_sha256=$ExpectedCalyxConfigSha256.ToUpperInvariant();broker_identity_sha256=$Authority.Infrastructure.BrokerIdentitySha256;broker_task_capability_sha256=([string]$Authority.Infrastructure.TaskCapabilitySha256).ToUpperInvariant();authority_epoch=[int64]$Authority.AuthorityEpoch;control_nonce=([string]$Authority.ControlNonce).ToUpperInvariant();broker_task=$authorityTaskDescriptor;prior_authority=$priorAuthority;current_generation_id=$(if($priorAuthority -ceq 'present'){[string]$Authority.CurrentGeneration.GenerationId}else{''});current_control_gate=(ConvertTo-SynapseAuthorityIdentityDescriptor -Identity $currentGateIdentity);current_roster=(ConvertTo-SynapseAuthorityIdentityDescriptor -Identity $currentRosterIdentity);parked_control_gate_transition=$(if($null -ne $parkedGateTransition){Get-SynapseAuthorityControlTransitionDescriptor $parkedGateTransition}else{$null});parked_roster_transition=$(if($null -ne $parkedRosterTransition){Get-SynapseAuthorityControlTransitionDescriptor $parkedRosterTransition}else{$null});candidate_control_gate_transition=(Get-SynapseAuthorityControlTransitionDescriptor $candidateGateTransition);candidate_roster_transition=(Get-SynapseAuthorityControlTransitionDescriptor $candidateRosterTransition);runtime_expected_paths=$runtimeExpectedPaths;runtime_transaction=$runtimePlan.Descriptor;profile_transaction=$profilePlan.Descriptor;candidate_generation=$candidateDescriptor;installed_probe_plan=$probeDescriptor}
        $initial.static_transaction_sha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $initial)).ToUpperInvariant()
        $profileGuard=New-SynapseProfilePreArmGenerationGuard -ProfilePlan $profilePlan.Validated
        $runtimeGuards=@(New-SynapseRuntimePreArmGuards -RuntimePlan $runtimePlan)
        [void](Assert-SynapseProfilePreArmGenerationState -ProfilePlan $profilePlan.Validated)
        [void](Assert-SynapseRuntimePreArmState -RuntimePlan $runtimePlan)
        [void](Assert-SynapseBrokerApplicationInitialDescriptor -Initial ([pscustomobject]$initial) -TransactionRoot $root -Allocation $allocation -ExpectedRuntimePaths $runtimeExpectedPaths)
        $journal=Write-SynapseDeploymentTransactionJournalSlot -TransactionRoot $root -TransactionRootChain $rootChain -Sequence 1 -InvocationId $script:SynapseSetupInvocationId -PreviousSlotSha256 '' -Payload $initial
        $localTransaction=[pscustomobject][ordered]@{Armed=$true;Committed=$false;RollbackInProgress=$false;RolledBack=$false;AuthorityModel='immutable_broker/v1';Authority=$Authority;Root=$root;RootChain=$rootChain;ParentRoot=$DeploymentTransactionParent;InvocationId=$script:SynapseSetupInvocationId;JournalSequence=1;JournalSha256=$journal.LatestRawSha256;JournalState='armed';StaticTransactionSha256=$initial.static_transaction_sha256;Bind=$Bind;DbPath=$DbPath;TokenPath=$TokenPath;ExpectedRuntimePaths=$runtimeExpectedPaths;RuntimeTransaction=$runtimePlan.Descriptor;RuntimePlan=$runtimePlan;ProfileTransaction=$profilePlan.Descriptor;ProfileGenerationLease=$null;AllocationContext=$allocation;ParkedGateTransition=$parkedGateTransition;ParkedRosterTransition=$parkedRosterTransition;CandidateGateTransition=$candidateGateTransition;CandidateRosterTransition=$candidateRosterTransition;PreviousTask=$null}
        $script:SynapseDeploymentTransaction=$localTransaction
        if($null -ne $profileGuard){$profileGuard.CompleteCleanGuard();$profileGuard.Dispose();$profileGuard=$null}
        foreach($guard in @($runtimeGuards)){if($null -ne $guard){$guard.CompleteCleanGuard();$guard.Dispose()}};$runtimeGuards=@()
        if($priorAuthority -ceq 'present'){
            [void](Invoke-SynapseAuthorityControlTransition -Transition $parkedGateTransition -AllocationContext $allocation)
            [void](Invoke-SynapseAuthorityControlTransition -Transition $parkedRosterTransition -AllocationContext $allocation)
            $parkedGateLease=$parkedGateTransition.CanonicalLease;$parkedRosterLease=$parkedRosterTransition.CanonicalLease
        }else{$parkedGateLease=$candidateGateTransition.PreLease;$parkedRosterLease=$candidateRosterTransition.PreLease}
        $parkedProof=Assert-SynapseBrokerParkedNoAuthority -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -ControlGateIdentity $parkedGateIdentity -RosterIdentity $parkedRosterIdentity -ControlGateLease $parkedGateLease -RosterLease $parkedRosterLease -Bind $Bind -DbPath $DbPath
        $profileDeploy=Install-SynapseBundledProfiles -DeploymentPlan $profilePlan -SourceProfilesDir $SourceProfilesDir -ProfilesDir $ProfilesDir -LogDir $LogDir
        $runtimePlan=Install-SynapseRuntimeTransactionGeneration -RuntimePlan $runtimePlan;$localTransaction.RuntimePlan=$runtimePlan
        $installedProbe=Test-SynapseCandidateDaemon -CandidateExePath $ExePath -CandidateBootstrapPath ([string]$Authority.Infrastructure.Bootstrap.Path) -ExpectedCandidateBootstrapSha256 ([string]$Authority.Infrastructure.Bootstrap.Sha256) -ProfilesDir $ProfilesDir -TokenPath $TokenPath -LogDir $LogDir -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions -CalyxConfigPath $CalyxConfigPath -ExpectedCalyxConfigSha256 $ExpectedCalyxConfigSha256 -ReplacementReservationId $ReplacementReservationId -UseTaskProbe -ProbeCapability $probeCapability -PreparedTaskProbe $preparedProbe
        if([int]$installedProbe.ToolCount -ne [int]$SourceProbe.ToolCount -or [string]$installedProbe.ToolSurfaceSha256 -ine [string]$SourceProbe.ToolSurfaceSha256){Die "SYNAPSE_BROKER_APPLICATION_INSTALLED_PROBE_SURFACE_DRIFT source_count=$($SourceProbe.ToolCount) installed_count=$($installedProbe.ToolCount) source_sha256=$($SourceProbe.ToolSurfaceSha256) installed_sha256=$($installedProbe.ToolSurfaceSha256)"}
        $probePlan=Read-SynapseCandidateProbePlanFromJournal -Descriptor $probeDescriptor -ExpectedCapabilitySha256 $probeCapability -Context 'app_v4_installed_probe_terminal'
        try{[void](Remove-SynapseJournalBoundCandidateProbeTask -Plan $probePlan -Context 'app_v4_installed_probe_terminal')}finally{if($null -ne $probePlan.Lease){$probePlan.Lease.Dispose()}}
        [void](Add-SynapseDeploymentTransactionJournalState -State candidate_ready -Payload ([ordered]@{authority_model='immutable_broker/v1';installed_probe_complete=$true;persistent_candidate_authority_active=$false;candidate_generation_id=[string]$candidateGeneration.GenerationId;candidate_sha256=[string]$installedProbe.Sha256;tool_count=[int]$installedProbe.ToolCount;tool_surface_sha256=[string]$installedProbe.ToolSurfaceSha256;profile_root_file_id_128=[string]$profileDeploy.RootFileId128;profile_manifest_sha256=[string]$profileDeploy.ManifestSha256;parked_outer_bootstrap_pid=[int]$parkedProof.OuterBootstrapPid;probe_task_absent=$true}) -Transaction $localTransaction)
        if($script:SynapseManualInstallHealthRollbackProbe){
            Die 'SYNAPSE_INSTALL_HEALTH_MANUAL_PROBE_REJECTED broker-v4 deliberately rejected the installed one-shot candidate after exact health/tools/resource acceptance and before durable commit_decided; unified rollback must restore and re-prove the prior broker generation'
        }
        $decision=Add-SynapseDeploymentTransactionJournalState -State commit_decided -Payload ([ordered]@{authority_model='immutable_broker/v1';candidate_generation_id=[string]$candidateGeneration.GenerationId;runtime_generation_sha256=[string]$candidateGeneration.RuntimeGenerationSha256;profile_generation_sha256=[string]$candidateGeneration.ProfileGenerationSha256;installed_probe_sha256=[string]$installedProbe.Sha256;tool_count=[int]$installedProbe.ToolCount;tool_surface_sha256=[string]$installedProbe.ToolSurfaceSha256;persistent_candidate_authority_active=$false;forward_only=$true}) -Transaction $localTransaction
        $localTransaction.Committed=$true;$localTransaction.JournalState='commit_decided'
        $forward=Complete-SynapseBrokerApplicationCommittedGeneration -Transaction $localTransaction -Authority $Authority -HealthTimeoutSeconds $HealthTimeoutSeconds
        Close-SynapseRuntimeTransactionLeases -RuntimePlan $runtimePlan
        if($null -ne $localTransaction.ProfileGenerationLease){$localTransaction.ProfileGenerationLease.Dispose();$localTransaction.ProfileGenerationLease=$null}
        Close-SynapseAuthorityControlTransitionLeases -Transitions @($parkedGateTransition,$parkedRosterTransition,$candidateGateTransition,$candidateRosterTransition)
        Close-SynapseDeploymentAllocationHandles -Context $allocation -PayloadsOnly
        [void](Remove-SynapseDeploymentTransactionArtifact -Path $root -ExpectedRoot $DeploymentTransactionParent -ExpectedState committed -Reason 'broker_application_v4_committed_cleanup' -Domain application)
        $script:SynapseDeploymentTransaction=$null;$script:SynapseDeploymentAllocationContext=$null
        Info "SYNAPSE_BROKER_APPLICATION_V4_COMMITTED root=$root generation=$($candidateGeneration.GenerationId) sequence=$($decision.Sequence) daemon_pid=$($forward.Proof.DaemonPid) tool_count=$($forward.Proof.ToolSurface.tool_count) tool_surface_sha256=$($forward.Proof.ToolSurface.tool_surface_sha256)"
        return [pscustomobject][ordered]@{Committed=$true;Generation=$forward.Generation;Proof=$forward.Proof;Health=$forward.Proof.Health;ToolSurface=$forward.Proof.ToolSurface;CandidatePreflight=$installedProbe;ProfileDeploy=$profileDeploy;RuntimePlan=$runtimePlan;TransactionRoot=$root}
    }catch{
        $primary=$_.Exception.Message
        foreach($guard in @($runtimeGuards)){if($null -ne $guard){try{$guard.Dispose()}catch{}}};if($null -ne $profileGuard){try{$profileGuard.Dispose()}catch{}}
        if($null -ne $localTransaction){
            try{
                $durable=Read-SynapseDeploymentTransactionJournal -TransactionRoot $root -TransactionRootChain $rootChain
                $effective=if([string]$durable.State -ceq 'cleanup_ready'){[string]$durable.Latest.detail.terminal_state}else{[string]$durable.State}
                if($effective -eq 'commit_decided'){
                    $localTransaction.JournalSequence=[int]$durable.Sequence;$localTransaction.JournalSha256=[string]$durable.LatestRawSha256;$localTransaction.JournalState=[string]$durable.State;$localTransaction.Committed=$true
                    $forward=Complete-SynapseBrokerApplicationCommittedGeneration -Transaction $localTransaction -Authority $Authority -HealthTimeoutSeconds $HealthTimeoutSeconds
                    Close-SynapseRuntimeTransactionLeases -RuntimePlan $localTransaction.RuntimePlan
                    if($null -ne $localTransaction.ProfileGenerationLease){$localTransaction.ProfileGenerationLease.Dispose();$localTransaction.ProfileGenerationLease=$null}
                    Close-SynapseAuthorityControlTransitionLeases -Transitions @($parkedGateTransition,$parkedRosterTransition,$candidateGateTransition,$candidateRosterTransition)
                    Close-SynapseDeploymentAllocationHandles -Context $allocation -PayloadsOnly
                    [void](Remove-SynapseDeploymentTransactionArtifact -Path $root -ExpectedRoot $DeploymentTransactionParent -ExpectedState committed -Reason 'broker_application_v4_reclassified_commit_cleanup' -Domain application)
                    $script:SynapseDeploymentTransaction=$null;$script:SynapseDeploymentAllocationContext=$null
                    Warn "SYNAPSE_BROKER_APPLICATION_V4_DECISION_RECLASSIFIED root=$root primary_error=$primary generation=$($forward.Generation.GenerationId) daemon_pid=$($forward.Proof.DaemonPid)"
                    return [pscustomobject][ordered]@{Committed=$true;Reclassified=$true;Generation=$forward.Generation;Proof=$forward.Proof;Health=$forward.Proof.Health;ToolSurface=$forward.Proof.ToolSurface;CandidatePreflight=$installedProbe;ProfileDeploy=$profileDeploy;RuntimePlan=$runtimePlan;TransactionRoot=$root}
                }
                $localTransaction.JournalSequence=[int]$durable.Sequence;$localTransaction.JournalSha256=[string]$durable.LatestRawSha256;$localTransaction.JournalState=[string]$durable.State
                $rollback=Invoke-SynapseBrokerApplicationRollback -Transaction $localTransaction -Authority $Authority -PrimaryFailure $primary -HealthTimeoutSeconds $HealthTimeoutSeconds
                if(-not $rollback.Ok){Die "SYNAPSE_BROKER_APPLICATION_V4_ROLLBACK_FAILED root=$root detail=$($rollback.Detail) primary=$primary"}
                Close-SynapseRuntimeTransactionLeases -RuntimePlan $localTransaction.RuntimePlan
                if($null -ne $localTransaction.ProfileGenerationLease){$localTransaction.ProfileGenerationLease.Dispose();$localTransaction.ProfileGenerationLease=$null}
                Close-SynapseAuthorityControlTransitionLeases -Transitions @($parkedGateTransition,$parkedRosterTransition,$candidateGateTransition,$candidateRosterTransition)
                Close-SynapseDeploymentAllocationHandles -Context $allocation -PayloadsOnly
                [void](Remove-SynapseDeploymentTransactionArtifact -Path $root -ExpectedRoot $DeploymentTransactionParent -ExpectedState rolled_back -Reason 'broker_application_v4_failure_cleanup' -Domain application)
            }finally{$script:SynapseDeploymentTransaction=$null;$script:SynapseDeploymentAllocationContext=$previousAllocation}
        }elseif($null -ne $root){
            try{Close-SynapseRuntimeTransactionLeases -RuntimePlan $runtimePlan}catch{};try{Close-SynapseAuthorityControlTransitionLeases -Transitions @($parkedGateTransition,$parkedRosterTransition,$candidateGateTransition,$candidateRosterTransition)}catch{};try{Close-SynapseDeploymentAllocationHandles -Context $allocation}catch{}
            try{[void](Remove-SynapseDeploymentTransactionArtifact -Path $root -ExpectedRoot $DeploymentTransactionParent -ExpectedState unarmed -Reason 'broker_application_v4_prearm_cleanup' -Domain application)}catch{Warn "SYNAPSE_BROKER_APPLICATION_V4_PREARM_CLEANUP_FAILED root=$root error=$($_.Exception.Message)"}
        }
        throw $primary
    }finally{
        if($null -ne $preparedProbe -and $null -ne $preparedProbe.PSObject.Properties['PowerShellAliasLeaseBundle'] -and $null -ne $preparedProbe.PowerShellAliasLeaseBundle){
            Close-SynapseProtectedOsInterpreterAliasLeaseBundle -Bundle $preparedProbe.PowerShellAliasLeaseBundle -Context 'broker_application_prepared_probe_untransferred'
            $preparedProbe.PowerShellAliasLeaseBundle=$null
        }
        if($null -ne $pair){Close-SynapseAuthorityActiveControlPair -Pair $pair}
        $script:SynapseDeploymentAllocationContext=$previousAllocation
        if($null -eq $script:SynapseDeploymentTransaction -or
            ($null -ne $script:SynapseDeploymentTransaction.PSObject.Properties['AuthorityModel'] -and [string]$script:SynapseDeploymentTransaction.AuthorityModel -ceq 'immutable_broker/v1')){
            $script:SynapseDeploymentTransaction=$previousTransaction
        }
    }
}

function Recover-SynapseBrokerApplicationTransaction {
    param(
        [Parameter(Mandatory=$true)]$Record,
        [Parameter(Mandatory=$true)]$Authority,
        [Parameter(Mandatory=$true)][string]$ExpectedParent,
        [ValidateRange(30,900)][int]$HealthTimeoutSeconds=420
    )

    $root=Get-SynapseNormalizedDirectoryPath -Path ([string]$Record.Directory.Path)
    $expectedParentFull=Get-SynapseNormalizedDirectoryPath -Path $ExpectedParent
    if((Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $root)) -ine $expectedParentFull){
        Die "SYNAPSE_BROKER_APPLICATION_RECOVERY_PARENT_MISMATCH root=$root expected_parent=$expectedParentFull"
    }
    # Re-read the durable chain immediately before classification.  The Record
    # object came from the namespace scan and is never authority to choose
    # rollback versus forward convergence after another append could have
    # reached stable storage.
    $rootChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $root)
    $journal=Read-SynapseDeploymentTransactionJournal -TransactionRoot $root -TransactionRootChain $rootChain
    if($null -eq $journal -or [string]$journal.Initial.schema -cne 'synapse_deployment_transaction/v4' -or
       [string]$journal.Initial.transaction_kind -cne 'synapse_broker_application/v1' -or
       [string]$journal.Initial.authority_model -cne 'immutable_broker/v1'){
        Die "SYNAPSE_BROKER_APPLICATION_RECOVERY_SCHEMA_INVALID root=$root schema=$($journal.Initial.schema) kind=$($journal.Initial.transaction_kind)"
    }
    $initial=$journal.Initial
    $task=$initial.broker_task;$authorityTask=$Authority.BrokerTask
    [void](Assert-SynapseBrokerTaskDescriptorAuthorityCrossbind -Descriptor $task -BrokerIdentitySha256 ([string]$initial.broker_identity_sha256) -TaskCapabilitySha256 ([string]$initial.broker_task_capability_sha256) -Infrastructure $Authority.Infrastructure -Context "broker_application_recovery_task_$root")
    if([string]$initial.broker_identity_sha256 -ine [string]$Authority.Infrastructure.BrokerIdentitySha256 -or
       [int64]$initial.authority_epoch -ne [int64]$Authority.AuthorityEpoch -or [string]$initial.control_nonce -ine [string]$Authority.ControlNonce -or
       (Get-SynapseNormalizedDirectoryPath -Path ([string]$initial.runtime_bin_dir)) -ine [string]$Authority.Layout.RuntimeBinDir -or
       [string]$task.name -cne [string]$authorityTask.Name -or [string]$task.xml_sha256 -ine [string]$authorityTask.XmlSha256 -or
       [string]$task.security_descriptor_sha256 -ine [string]$authorityTask.SecurityDescriptorSha256 -or
       [System.IO.Path]::GetFullPath([string]$task.execute) -ine [System.IO.Path]::GetFullPath([string]$authorityTask.Execute) -or
       [string]$task.arguments -cne [string]$authorityTask.Arguments -or
       [System.IO.Path]::GetFullPath([string]$task.working_directory) -ine [System.IO.Path]::GetFullPath([string]$authorityTask.WorkingDirectory)){
        Die "SYNAPSE_BROKER_APPLICATION_RECOVERY_AUTHORITY_CROSSBIND_INVALID root=$root broker=$($initial.broker_identity_sha256) epoch=$($initial.authority_epoch) task=$($task.name)"
    }

    $effective=if([string]$journal.State -ceq 'cleanup_ready'){[string]$journal.Latest.detail.terminal_state}else{[string]$journal.State}
    if([string]$journal.State -ceq 'cleanup_ready'){
        # All non-journal artifacts may already be gone at this cut.  Re-prove
        # the externally visible terminal generation, then use only the exact
        # cleanup receipt roster to delete the bounded transaction tail.  Do
        # not reconstruct mutation authority from missing stage/park objects.
        $currentGate=Assert-SynapseAuthorityIdentityDescriptor -Descriptor $initial.current_control_gate -ExpectedPath $Authority.Layout.ControlGatePath -Context "app_v4_cleanup_current_gate_$root"
        $currentRoster=Assert-SynapseAuthorityIdentityDescriptor -Descriptor $initial.current_roster -ExpectedPath $Authority.Layout.RosterPath -Context "app_v4_cleanup_current_roster_$root"
        if($effective -ceq 'commit_decided'){
            $pair=Read-SynapseAuthorityActiveControlPair -Layout $Authority.Layout -ExpectedState active -Context 'app_v4_cleanup_committed_pair'
            try{
                $generation=ConvertTo-SynapseAuthorityGenerationFromCurrentRoster -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -ControlGate $pair.Gate -Roster $pair.Roster -Context 'app_v4_cleanup_committed_generation'
                if([string]$generation.GenerationId -cne [string]$initial.candidate_generation.generation_id){Die "SYNAPSE_BROKER_APPLICATION_CLEANUP_COMMITTED_GENERATION_MISMATCH root=$root expected=$($initial.candidate_generation.generation_id) actual=$($generation.GenerationId)"}
                $proof=Wait-SynapseCurrentAuthorityGenerationOperational -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -Generation $generation -ControlGateIdentity ([pscustomobject]@{Path=$pair.Gate.Path;FileId128=$pair.Gate.FileId128;Sha256=$pair.Gate.Sha256;Length=$pair.Gate.Length}) -RosterIdentity ([pscustomobject]@{Path=$pair.Roster.Path;FileId128=$pair.Roster.FileId128;Sha256=$pair.Roster.Sha256;Length=$pair.Roster.Length}) -ControlGateLease $pair.GateLease -RosterLease $pair.RosterLease -HealthTimeoutSeconds $HealthTimeoutSeconds -Context 'app_v4_cleanup_committed_generation'
            }finally{Close-SynapseAuthorityActiveControlPair -Pair $pair}
        }elseif($effective -ceq 'rolled_back'){
            $expectedState=if([string]$initial.prior_authority -ceq 'present'){'active'}else{'parked'}
            $pair=Read-SynapseAuthorityActiveControlPair -Layout $Authority.Layout -ExpectedState $expectedState -Context 'app_v4_cleanup_rolledback_pair'
            try{
                if([string]$pair.Gate.FileId128 -ine $currentGate.FileId128 -or [string]$pair.Gate.Sha256 -ine $currentGate.Sha256 -or [int64]$pair.Gate.Length -ne $currentGate.Length -or
                   [string]$pair.Roster.FileId128 -ine $currentRoster.FileId128 -or [string]$pair.Roster.Sha256 -ine $currentRoster.Sha256 -or [int64]$pair.Roster.Length -ne $currentRoster.Length){
                    Die "SYNAPSE_BROKER_APPLICATION_CLEANUP_ROLLBACK_CONTROL_MISMATCH root=$root prior=$($initial.prior_authority)"
                }
                if([string]$initial.prior_authority -ceq 'present'){
                    $generation=ConvertTo-SynapseAuthorityGenerationFromCurrentRoster -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -ControlGate $pair.Gate -Roster $pair.Roster -Context 'app_v4_cleanup_rolledback_generation'
                    if([string]$generation.GenerationId -cne [string]$initial.current_generation_id){Die "SYNAPSE_BROKER_APPLICATION_CLEANUP_ROLLBACK_GENERATION_MISMATCH root=$root expected=$($initial.current_generation_id) actual=$($generation.GenerationId)"}
                    $proof=Wait-SynapseCurrentAuthorityGenerationOperational -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -Generation $generation -ControlGateIdentity $currentGate -RosterIdentity $currentRoster -ControlGateLease $pair.GateLease -RosterLease $pair.RosterLease -HealthTimeoutSeconds $HealthTimeoutSeconds -Context 'app_v4_cleanup_rolledback_generation'
                }else{
                    $proof=Assert-SynapseBrokerParkedNoAuthority -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -ControlGateIdentity $currentGate -RosterIdentity $currentRoster -ControlGateLease $pair.GateLease -RosterLease $pair.RosterLease -Bind ([string]$initial.bind) -DbPath ([string]$initial.db_path)
                }
            }finally{Close-SynapseAuthorityActiveControlPair -Pair $pair}
        }else{Die "SYNAPSE_BROKER_APPLICATION_CLEANUP_TERMINAL_INVALID root=$root terminal=$effective"}
        if(-not(Remove-SynapseDeploymentCleanupTailIfPresent -TransactionRoot $root -ExpectedParent $expectedParentFull)){
            Die "SYNAPSE_BROKER_APPLICATION_CLEANUP_RECEIPT_INVALID root=$root terminal=$effective"
        }
        Info "SYNAPSE_BROKER_APPLICATION_V4_CLEANUP_RECOVERED root=$root terminal=$effective"
        return [pscustomobject][ordered]@{Recovered=$true;TerminalState=$effective;Generation=$generation;Proof=$proof;Root=$root}
    }

    if($effective -notin @('armed','candidate_ready','commit_decided','rolled_back')){Die "SYNAPSE_BROKER_APPLICATION_RECOVERY_STATE_INVALID root=$root state=$($journal.State)"}
    $runtimePaths=@($initial.runtime_expected_paths|ForEach-Object{[System.IO.Path]::GetFullPath([string]$_)})
    $validated=Assert-SynapseBrokerApplicationInitialDescriptor -Initial $initial -TransactionRoot $root -Allocation $journal.Allocation -ExpectedRuntimePaths $runtimePaths -AllowCommittedDiscardedPost:($effective-ceq'commit_decided')
    $transaction=[pscustomobject][ordered]@{
        Armed=$true;Committed=($effective -ceq 'commit_decided');RollbackInProgress=$false;RolledBack=($effective -ceq 'rolled_back')
        AuthorityModel='immutable_broker/v1';Authority=$Authority;Root=$root;RootChain=$rootChain;ParentRoot=$expectedParentFull
        InvocationId=[string]$initial.invocation_id;JournalSequence=[int]$journal.Sequence;JournalSha256=[string]$journal.LatestRawSha256;JournalState=[string]$journal.State;StaticTransactionSha256=[string]$initial.static_transaction_sha256
        Bind=[string]$initial.bind;DbPath=[string]$initial.db_path;TokenPath=[string]$initial.token_path;ExpectedRuntimePaths=$runtimePaths
        RuntimeTransaction=$initial.runtime_transaction;RuntimePlan=$validated.RuntimePlan;ProfileTransaction=$initial.profile_transaction;ProfileGenerationLease=$null;AllocationContext=$journal.Allocation
        ParkedGateTransition=$validated.ParkedGateTransition;ParkedRosterTransition=$validated.ParkedRosterTransition;CandidateGateTransition=$validated.CandidateGateTransition;CandidateRosterTransition=$validated.CandidateRosterTransition;PreviousTask=$null
    }
    $previousTransaction=$script:SynapseDeploymentTransaction;$script:SynapseDeploymentTransaction=$transaction
    try{
        if($effective -ceq 'commit_decided'){
            $result=Complete-SynapseBrokerApplicationCommittedGeneration -Transaction $transaction -Authority $Authority -HealthTimeoutSeconds $HealthTimeoutSeconds
            Close-SynapseRuntimeTransactionLeases -RuntimePlan $transaction.RuntimePlan
            if($null -ne $transaction.ProfileGenerationLease){$transaction.ProfileGenerationLease.Dispose();$transaction.ProfileGenerationLease=$null}
            Close-SynapseAuthorityControlTransitionLeases -Transitions @($transaction.ParkedGateTransition,$transaction.ParkedRosterTransition,$transaction.CandidateGateTransition,$transaction.CandidateRosterTransition)
            [void](Remove-SynapseDeploymentTransactionArtifact -Path $root -ExpectedRoot $expectedParentFull -ExpectedState committed -Reason 'broker_application_v4_interrupted_commit_cleanup' -Domain application)
            Info "SYNAPSE_BROKER_APPLICATION_V4_COMMIT_RECOVERED root=$root generation=$($result.Generation.GenerationId) daemon_pid=$($result.Proof.DaemonPid)"
            return [pscustomobject][ordered]@{Recovered=$true;TerminalState='commit_decided';Generation=$result.Generation;Proof=$result.Proof;Root=$root}
        }
        $rollback=Invoke-SynapseBrokerApplicationRollback -Transaction $transaction -Authority $Authority -PrimaryFailure 'interrupted_broker_application_v4_recovery' -HealthTimeoutSeconds $HealthTimeoutSeconds
        if(-not [bool]$rollback.Ok){Die "SYNAPSE_BROKER_APPLICATION_V4_INTERRUPTED_ROLLBACK_FAILED root=$root detail=$($rollback.Detail)"}
        Close-SynapseRuntimeTransactionLeases -RuntimePlan $transaction.RuntimePlan
        if($null -ne $transaction.ProfileGenerationLease){$transaction.ProfileGenerationLease.Dispose();$transaction.ProfileGenerationLease=$null}
        Close-SynapseAuthorityControlTransitionLeases -Transitions @($transaction.ParkedGateTransition,$transaction.ParkedRosterTransition,$transaction.CandidateGateTransition,$transaction.CandidateRosterTransition)
        [void](Remove-SynapseDeploymentTransactionArtifact -Path $root -ExpectedRoot $expectedParentFull -ExpectedState rolled_back -Reason 'broker_application_v4_interrupted_rollback_cleanup' -Domain application)
        Info "SYNAPSE_BROKER_APPLICATION_V4_ROLLBACK_RECOVERED root=$root prior_authority=$($initial.prior_authority) prior_pid=$($rollback.PriorDaemonPid)"
        return [pscustomobject][ordered]@{Recovered=$true;TerminalState='rolled_back';Generation=$null;Proof=$null;Root=$root}
    }finally{
        try{Close-SynapseRuntimeTransactionLeases -RuntimePlan $transaction.RuntimePlan}catch{}
        if($null -ne $transaction.ProfileGenerationLease){try{$transaction.ProfileGenerationLease.Dispose()}catch{};$transaction.ProfileGenerationLease=$null}
        Close-SynapseAuthorityControlTransitionLeases -Transitions @($transaction.ParkedGateTransition,$transaction.ParkedRosterTransition,$transaction.CandidateGateTransition,$transaction.CandidateRosterTransition)
        $script:SynapseDeploymentTransaction=$previousTransaction
    }
}

function Wait-SynapseCurrentAuthorityGenerationOperational {
    param(
        [Parameter(Mandatory=$true)]$Layout,
        [Parameter(Mandatory=$true)]$Infrastructure,
        [Parameter(Mandatory=$true)]$Generation,
        [Parameter(Mandatory=$true)]$ControlGateIdentity,
        [Parameter(Mandatory=$true)]$RosterIdentity,
        $ControlGateLease,
        $RosterLease,
        [ValidateRange(30,900)][int]$HealthTimeoutSeconds=420,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $p=$Generation.RosterPayload
    $token=Read-SynapseAuthorityGenerationToken -Generation $Generation -Context "${Context}_token"
    return Wait-SynapseBrokerGenerationOperational -Layout $Layout -Infrastructure $Infrastructure -Generation $Generation `
        -ControlGateIdentity $ControlGateIdentity -RosterIdentity $RosterIdentity -ControlGateLease $ControlGateLease -RosterLease $RosterLease `
        -Bind ([string]$p.bind) -DbPath ([string]$p.db_path) -ProfilesDir ([string]$p.profiles_dir) -LogDir ([string]$p.log_dir) -Token $token `
        -AllowedPermissions ([string]$p.allowed_permissions) -CalyxConfigPath ([string]$p.calyx_config_path) -ExpectedCalyxConfigSha256 ([string]$p.calyx_config_sha256) `
        -TimeoutSeconds $HealthTimeoutSeconds
}

function Assert-SynapseCurrentBrokerAuthorityGenerationOperational {
    param(
        [Parameter(Mandatory=$true)]$Authority,
        [Parameter(Mandatory=$true)][ValidatePattern('^(prior|candidate)-[0-9a-f]{40}$')][string]$ExpectedGenerationId,
        [ValidateRange(30,900)][int]$HealthTimeoutSeconds=420,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $pair=$null
    try{
        $pair=Read-SynapseAuthorityActiveControlPair -Layout $Authority.Layout -ExpectedState active -Context "${Context}_pair"
        $generation=ConvertTo-SynapseAuthorityGenerationFromCurrentRoster -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -ControlGate $pair.Gate -Roster $pair.Roster -Context "${Context}_generation"
        if([string]$generation.GenerationId -cne $ExpectedGenerationId){
            Die "SYNAPSE_BROKER_CURRENT_GENERATION_MISMATCH context=$Context expected=$ExpectedGenerationId actual=$($generation.GenerationId)"
        }
        $gateIdentity=[pscustomobject][ordered]@{Path=$pair.Gate.Path;FileId128=$pair.Gate.FileId128;Sha256=$pair.Gate.Sha256;Length=[int64]$pair.Gate.Length}
        $rosterIdentity=[pscustomobject][ordered]@{Path=$pair.Roster.Path;FileId128=$pair.Roster.FileId128;Sha256=$pair.Roster.Sha256;Length=[int64]$pair.Roster.Length}
        $proof=Wait-SynapseCurrentAuthorityGenerationOperational -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -Generation $generation -ControlGateIdentity $gateIdentity -RosterIdentity $rosterIdentity -ControlGateLease $pair.GateLease -RosterLease $pair.RosterLease -HealthTimeoutSeconds $HealthTimeoutSeconds -Context $Context
        return [pscustomobject][ordered]@{Generation=$generation;Proof=$proof;ControlGate=$gateIdentity;Roster=$rosterIdentity}
    }finally{
        Close-SynapseAuthorityActiveControlPair -Pair $pair
    }
}

function Assert-SynapseBrokerOperatorStopInitialDescriptor {
    param(
        [Parameter(Mandatory=$true)]$Initial,
        [Parameter(Mandatory=$true)][string]$TransactionRoot,
        [Parameter(Mandatory=$true)]$Allocation,
        [Parameter(Mandatory=$true)]$Layout
    )
    $root=Get-SynapseNormalizedDirectoryPath -Path $TransactionRoot
    $rootChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $root)
    $names=@($Initial.PSObject.Properties.Name)
    $expected=@('schema','state','transaction_kind','authority_model','invocation_id','armed_at_utc','transaction_root','transaction_root_file_id_128','allocation_marker','runtime_bin_dir','broker_identity_sha256','broker_task_capability_sha256','authority_epoch','control_nonce','broker_task','bind','db_path','token_path','generation_id','current_control_gate','current_roster','parked_control_gate_transition','parked_roster_transition','static_transaction_sha256')
    if($names.Count -ne $expected.Count -or @($names|Where-Object{$expected -cnotcontains $_}).Count -gt 0 -or
       [string]$Initial.schema -cne 'synapse_broker_operator_stop_transaction/v1' -or [string]$Initial.state -cne 'armed' -or
       [string]$Initial.transaction_kind -cne 'synapse_broker_operator_stop/v1' -or [string]$Initial.authority_model -cne 'immutable_broker/v1' -or
       [string]::IsNullOrWhiteSpace([string]$Initial.invocation_id) -or (Get-SynapseNormalizedDirectoryPath -Path ([string]$Initial.transaction_root)) -ine $root -or
       (Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $root)) -ine [string]$Layout.Operations -or
       [string]$Initial.transaction_root_file_id_128 -ine [string]$rootChain[-1].file_id_128 -or
       (Get-SynapseNormalizedDirectoryPath -Path ([string]$Initial.runtime_bin_dir)) -ine [string]$Layout.RuntimeBinDir -or
       [string]$Initial.broker_identity_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [string]$Initial.broker_task_capability_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [int64]$Initial.authority_epoch -lt 1 -or
       [string]$Initial.control_nonce -notmatch '^[0-9A-Fa-f]{64}$' -or [string]$Initial.generation_id -notmatch '^(prior|candidate)-[0-9a-f]{40}$' -or
       [string]::IsNullOrWhiteSpace([string]$Initial.bind) -or -not [System.IO.Path]::IsPathFullyQualified([string]$Initial.db_path) -or -not [System.IO.Path]::IsPathFullyQualified([string]$Initial.token_path) -or
       [string]$Initial.static_transaction_sha256 -notmatch '^[0-9A-Fa-f]{64}$'){
        Die "SYNAPSE_BROKER_OPERATOR_STOP_INITIAL_INVALID root=$root schema=$($Initial.schema) kind=$($Initial.transaction_kind)"
    }
    [void](Assert-SynapseBrokerTaskDescriptorShape -Descriptor $Initial.broker_task -BrokerIdentitySha256 ([string]$Initial.broker_identity_sha256) -TaskCapabilitySha256 ([string]$Initial.broker_task_capability_sha256) -Context 'operator_stop_broker_task')
    $currentGate=Assert-SynapseAuthorityIdentityDescriptor -Descriptor $Initial.current_control_gate -ExpectedPath $Layout.ControlGatePath -Context 'operator_stop_current_gate'
    $currentRoster=Assert-SynapseAuthorityIdentityDescriptor -Descriptor $Initial.current_roster -ExpectedPath $Layout.RosterPath -Context 'operator_stop_current_roster'
    $gateTransition=ConvertTo-SynapseAuthorityControlTransition -Descriptor $Initial.parked_control_gate_transition -TransactionRoot $root -Allocation $Allocation
    $rosterTransition=ConvertTo-SynapseAuthorityControlTransition -Descriptor $Initial.parked_roster_transition -TransactionRoot $root -Allocation $Allocation
    if([string]$gateTransition.purpose -cne 'operator_stop_parked_control_gate' -or [string]$rosterTransition.purpose -cne 'operator_stop_parked_roster' -or
       [string]$gateTransition.parent -ine [string]$Layout.Root -or [string]$gateTransition.path -ine [string]$Layout.ControlGatePath -or
       [string]$rosterTransition.parent -ine [string]$Layout.Root -or [string]$rosterTransition.path -ine [string]$Layout.RosterPath -or
       -not [bool]$gateTransition.pre_existed -or -not [bool]$rosterTransition.pre_existed -or
       [string]$gateTransition.pre_file_id_128 -ine [string]$currentGate.FileId128 -or [string]$gateTransition.pre_sha256 -ine [string]$currentGate.Sha256 -or [int64]$gateTransition.pre_length -ne [int64]$currentGate.Length -or
       [string]$rosterTransition.pre_file_id_128 -ine [string]$currentRoster.FileId128 -or [string]$rosterTransition.pre_sha256 -ine [string]$currentRoster.Sha256 -or [int64]$rosterTransition.pre_length -ne [int64]$currentRoster.Length){
        Die "SYNAPSE_BROKER_OPERATOR_STOP_TRANSITION_BINDING_INVALID root=$root generation=$($Initial.generation_id)"
    }
    return [pscustomobject][ordered]@{Root=$root;CurrentControlGate=$currentGate;CurrentRoster=$currentRoster;GateTransition=$gateTransition;RosterTransition=$rosterTransition;GenerationId=[string]$Initial.generation_id}
}

function Get-SynapseBrokerOperatorStopRecord {
    param(
        [Parameter(Mandatory=$true)]$Authority,
        [switch]$CleanupUnarmed
    )
    $entries=@(Get-SynapsePhysicalDirectoryEntriesBounded -Path $Authority.Layout.Operations -Chain $Authority.Layout.OperationsChain -MaximumEntries 1 -Context 'operator_stop_transaction_scan')
    if($entries.Count -eq 0){return $null}
    $entry=$entries[0]
    if(-not [bool]$entry.IsDirectory -or ([uint32]$entry.Attributes -band [uint32][System.IO.FileAttributes]::ReparsePoint) -or [string]$entry.Name -notmatch '^deployment-\d{8}T\d{9}Z-\d+$'){
        Die "SYNAPSE_BROKER_OPERATOR_STOP_NAMESPACE_INVALID root=$($Authority.Layout.Operations) entry=$($entry.Name)"
    }
    $journal=$null
    try{$journal=Read-SynapseDeploymentTransactionJournal -TransactionRoot ([string]$entry.Path)}catch{
        $readError=$_.Exception.Message
        if($CleanupUnarmed){
            try{[void](Remove-SynapseDeploymentTransactionArtifact -Path ([string]$entry.Path) -ExpectedRoot $Authority.Layout.Operations -ExpectedState unarmed -Reason 'operator_stop_torn_initial_cleanup' -Domain authority);return $null}catch{}
        }
        Die "SYNAPSE_BROKER_OPERATOR_STOP_JOURNAL_UNREADABLE root=$($entry.Path) error=$readError remediation=preserve the exact operator control transaction and run ordinary setup recovery"
    }
    if($null -eq $journal){
        if($CleanupUnarmed){[void](Remove-SynapseDeploymentTransactionArtifact -Path ([string]$entry.Path) -ExpectedRoot $Authority.Layout.Operations -ExpectedState unarmed -Reason 'operator_stop_unarmed_cleanup' -Domain authority);return $null}
        Die "SYNAPSE_BROKER_OPERATOR_STOP_JOURNAL_MISSING root=$($entry.Path)"
    }
    $validated=Assert-SynapseBrokerOperatorStopInitialDescriptor -Initial $journal.Initial -TransactionRoot ([string]$entry.Path) -Allocation $journal.Allocation -Layout $Authority.Layout
    if([string]$journal.Initial.broker_identity_sha256 -ine [string]$Authority.Infrastructure.BrokerIdentitySha256 -or
       [int64]$journal.Initial.authority_epoch -ne [int64]$Authority.AuthorityEpoch -or [string]$journal.Initial.control_nonce -ine [string]$Authority.ControlNonce -or
       [string]$journal.Initial.broker_task.name -cne [string]$Authority.BrokerTask.Name -or [string]$journal.Initial.broker_task.xml_sha256 -ine [string]$Authority.BrokerTask.XmlSha256 -or
       [string]$journal.Initial.broker_task.security_descriptor_sha256 -ine [string]$Authority.BrokerTask.SecurityDescriptorSha256){
        Die "SYNAPSE_BROKER_OPERATOR_STOP_EPOCH_MISMATCH root=$($entry.Path)"
    }
    return [pscustomobject][ordered]@{Entry=$entry;Journal=$journal;Validated=$validated}
}

function Restore-SynapseBrokerOperatorStoppedGeneration {
    param(
        [Parameter(Mandatory=$true)]$Record,
        [Parameter(Mandatory=$true)]$Authority,
        [ValidateRange(30,900)][int]$HealthTimeoutSeconds=420,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $validated=$Record.Validated
    [void](Invoke-SynapseAuthorityControlTransitionRollback -Transition $validated.RosterTransition)
    [void](Invoke-SynapseAuthorityControlTransitionRollback -Transition $validated.GateTransition)
    $pair=Read-SynapseAuthorityActiveControlPair -Layout $Authority.Layout -GateLease $validated.GateTransition.RestoredLease -RosterLease $validated.RosterTransition.RestoredLease -ExpectedState active -Context "${Context}_restored_pair"
    try{
        $generation=ConvertTo-SynapseAuthorityGenerationFromCurrentRoster -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -ControlGate $pair.Gate -Roster $pair.Roster -Context "${Context}_restored_generation"
        if([string]$generation.GenerationId -cne [string]$validated.GenerationId){Die "SYNAPSE_BROKER_OPERATOR_STOP_RESTORED_GENERATION_MISMATCH expected=$($validated.GenerationId) actual=$($generation.GenerationId)"}
        $proof=Wait-SynapseCurrentAuthorityGenerationOperational -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -Generation $generation -ControlGateIdentity $validated.CurrentControlGate -RosterIdentity $validated.CurrentRoster -ControlGateLease $pair.GateLease -RosterLease $pair.RosterLease -HealthTimeoutSeconds $HealthTimeoutSeconds -Context $Context
        return [pscustomobject][ordered]@{Generation=$generation;Proof=$proof}
    }finally{Close-SynapseAuthorityActiveControlPair -Pair $pair}
}

function Resolve-SynapseBrokerOperatorStopTransaction {
    param(
        [Parameter(Mandatory=$true)]$Authority,
        [ValidateSet('inspect','start','setup','remove')][string]$Mode='inspect',
        [ValidateRange(30,900)][int]$HealthTimeoutSeconds=420
    )
    $record=Get-SynapseBrokerOperatorStopRecord -Authority $Authority -CleanupUnarmed
    if($null -eq $record){return [pscustomobject][ordered]@{Exists=$false;Stopped=$false;Restored=$false}}
    $journal=$record.Journal;$effective=if([string]$journal.State -ceq 'cleanup_ready'){[string]$journal.Latest.detail.terminal_state}else{[string]$journal.State}
    [void](Assert-SynapseBrokerTaskDescriptorAuthorityCrossbind -Descriptor $journal.Initial.broker_task -BrokerIdentitySha256 ([string]$journal.Initial.broker_identity_sha256) -TaskCapabilitySha256 ([string]$journal.Initial.broker_task_capability_sha256) -Infrastructure $Authority.Infrastructure -Context "operator_stop_recovery_task_$($record.Entry.Path)")
    if([string]$journal.State -ceq 'cleanup_ready'){
        $terminalSlot=@($journal.Slots|Where-Object{[string]$_.State -ceq $effective}|Select-Object -Last 1)
        $removed=($effective -ceq 'commit_decided' -and $terminalSlot.Count -eq 1 -and $null -ne $terminalSlot[0].Payload.detail.PSObject.Properties['operator_remove_decided'] -and [bool]$terminalSlot[0].Payload.detail.operator_remove_decided)
        $expected=if($effective -ceq 'commit_decided'){'committed'}else{'rolled_back'}
        [void](Remove-SynapseDeploymentTransactionArtifact -Path ([string]$record.Entry.Path) -ExpectedRoot $Authority.Layout.Operations -ExpectedState $expected -Reason 'operator_stop_cleanup_tail_resume' -Domain authority)
        return [pscustomobject][ordered]@{Exists=$false;Stopped=$removed;Restored=($effective -ceq 'commit_decided' -and -not $removed);Removed=$removed}
    }
    $transaction=[pscustomobject][ordered]@{Armed=$true;Committed=($effective -ceq 'commit_decided');Root=[string]$record.Entry.Path;RootChain=@($journal.RootChain);ParentRoot=$Authority.Layout.Operations;InvocationId=[string]$journal.Initial.invocation_id;JournalSequence=[int]$journal.Sequence;JournalSha256=[string]$journal.LatestRawSha256;JournalState=[string]$journal.State;StaticTransactionSha256=[string]$journal.Initial.static_transaction_sha256}
    try{
        if($effective -ceq 'rolled_back'){
            [void](Remove-SynapseDeploymentTransactionArtifact -Path $transaction.Root -ExpectedRoot $Authority.Layout.Operations -ExpectedState rolled_back -Reason 'operator_stop_aborted_cleanup' -Domain authority)
            return [pscustomobject][ordered]@{Exists=$false;Stopped=$false;Restored=$true}
        }
        if($effective -ceq 'armed'){
            if($Mode-ceq'remove'){
                $pair=Read-SynapseAuthorityActiveControlPair -Layout $Authority.Layout -ExpectedState parked -Context 'operator_stop_armed_remove_pair'
                try{$parkedProof=Assert-SynapseBrokerParkedNoAuthority -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -ControlGateIdentity ([pscustomobject]@{Path=$pair.Gate.Path;FileId128=$pair.Gate.FileId128;Sha256=$pair.Gate.Sha256;Length=$pair.Gate.Length}) -RosterIdentity ([pscustomobject]@{Path=$pair.Roster.Path;FileId128=$pair.Roster.FileId128;Sha256=$pair.Roster.Sha256;Length=$pair.Roster.Length}) -ControlGateLease $pair.GateLease -RosterLease $pair.RosterLease -Bind ([string]$journal.Initial.bind) -DbPath ([string]$journal.Initial.db_path) -AllowHistoricalPeakForDecommission -TimeoutSeconds 30}finally{Close-SynapseAuthorityActiveControlPair -Pair $pair}
                [void](Add-SynapseDeploymentTransactionJournalState -State candidate_ready -Payload ([ordered]@{operator_stopped=$true;broker_identity_sha256=[string]$Authority.Infrastructure.BrokerIdentitySha256;generation_id=[string]$journal.Initial.generation_id;parked_authority_proven=$true;daemon_count=0;listener_count=0;recovered_from_armed_cut=$true}) -Transaction $transaction)
                $effective='candidate_ready';$journal=Read-SynapseDeploymentTransactionJournal -TransactionRoot $transaction.Root
            }else{
                $restored=Restore-SynapseBrokerOperatorStoppedGeneration -Record $record -Authority $Authority -HealthTimeoutSeconds $HealthTimeoutSeconds -Context 'operator_stop_armed_recovery'
                [void](Add-SynapseDeploymentTransactionJournalState -State rolled_back -Payload ([ordered]@{operator_stop_aborted=$true;broker_identity_sha256=[string]$Authority.Infrastructure.BrokerIdentitySha256;generation_id=[string]$restored.Generation.GenerationId;prior_operational=$true;daemon_pid=[int]$restored.Proof.DaemonPid;unknown_objects_preserved=$true}) -Transaction $transaction)
                Close-SynapseAuthorityControlTransitionLeases -Transitions @($record.Validated.GateTransition,$record.Validated.RosterTransition)
                Close-SynapseDeploymentAllocationHandles -Context $journal.Allocation -PayloadsOnly
                [void](Remove-SynapseDeploymentTransactionArtifact -Path $transaction.Root -ExpectedRoot $Authority.Layout.Operations -ExpectedState rolled_back -Reason 'operator_stop_armed_recovery_cleanup' -Domain authority)
                return [pscustomobject][ordered]@{Exists=$false;Stopped=$false;Restored=$true;Generation=$restored.Generation;Proof=$restored.Proof}
            }
        }
        if($effective -ceq 'candidate_ready' -and $Mode -ceq 'inspect'){
            $pair=Read-SynapseAuthorityActiveControlPair -Layout $Authority.Layout -ExpectedState parked -Context 'operator_stop_persistent_pair'
            try{[void](Assert-SynapseBrokerParkedNoAuthority -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -ControlGateIdentity ([pscustomobject]@{Path=$pair.Gate.Path;FileId128=$pair.Gate.FileId128;Sha256=$pair.Gate.Sha256;Length=$pair.Gate.Length}) -RosterIdentity ([pscustomobject]@{Path=$pair.Roster.Path;FileId128=$pair.Roster.FileId128;Sha256=$pair.Roster.Sha256;Length=$pair.Roster.Length}) -ControlGateLease $pair.GateLease -RosterLease $pair.RosterLease -Bind ([string]$journal.Initial.bind) -DbPath ([string]$journal.Initial.db_path))}finally{Close-SynapseAuthorityActiveControlPair -Pair $pair}
            return [pscustomobject][ordered]@{Exists=$true;Stopped=$true;Restored=$false;GenerationId=[string]$journal.Initial.generation_id;Root=$transaction.Root}
        }
        if($effective -ceq 'candidate_ready'){
            $decisionDetail=if($Mode -ceq 'remove'){
                [ordered]@{operator_remove_decided=$true;broker_identity_sha256=[string]$Authority.Infrastructure.BrokerIdentitySha256;generation_id=[string]$journal.Initial.generation_id;forward_only=$true}
            }else{
                [ordered]@{operator_start_decided=$true;broker_identity_sha256=[string]$Authority.Infrastructure.BrokerIdentitySha256;generation_id=[string]$journal.Initial.generation_id;forward_only=$true}
            }
            [void](Add-SynapseDeploymentTransactionJournalState -State commit_decided -Payload $decisionDetail -Transaction $transaction)
            $effective='commit_decided'
            $journal=Read-SynapseDeploymentTransactionJournal -TransactionRoot $transaction.Root
        }
        if($effective -ceq 'commit_decided'){
            $removeDecided=($null -ne $journal.Latest.detail.PSObject.Properties['operator_remove_decided'] -and [bool]$journal.Latest.detail.operator_remove_decided)
            if($removeDecided){
                $pair=Read-SynapseAuthorityActiveControlPair -Layout $Authority.Layout -ExpectedState parked -Context "operator_${Mode}_decommission_pair"
                try{
                    [void](Assert-SynapseBrokerParkedNoAuthority -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -ControlGateIdentity ([pscustomobject]@{Path=$pair.Gate.Path;FileId128=$pair.Gate.FileId128;Sha256=$pair.Gate.Sha256;Length=$pair.Gate.Length}) -RosterIdentity ([pscustomobject]@{Path=$pair.Roster.Path;FileId128=$pair.Roster.FileId128;Sha256=$pair.Roster.Sha256;Length=$pair.Roster.Length}) -ControlGateLease $pair.GateLease -RosterLease $pair.RosterLease -Bind ([string]$journal.Initial.bind) -DbPath ([string]$journal.Initial.db_path) -AllowHistoricalPeakForDecommission)
                }finally{Close-SynapseAuthorityActiveControlPair -Pair $pair}
                Close-SynapseAuthorityControlTransitionLeases -Transitions @($record.Validated.GateTransition,$record.Validated.RosterTransition)
                Close-SynapseDeploymentAllocationHandles -Context $journal.Allocation -PayloadsOnly
                [void](Remove-SynapseDeploymentTransactionArtifact -Path $transaction.Root -ExpectedRoot $Authority.Layout.Operations -ExpectedState committed -Reason 'operator_remove_forward_cleanup' -Domain authority)
                return [pscustomobject][ordered]@{Exists=$false;Stopped=$true;Restored=$false;Removed=$true;GenerationId=[string]$journal.Initial.generation_id}
            }
            $restored=Restore-SynapseBrokerOperatorStoppedGeneration -Record $record -Authority $Authority -HealthTimeoutSeconds $HealthTimeoutSeconds -Context "operator_${Mode}_forward"
            Close-SynapseAuthorityControlTransitionLeases -Transitions @($record.Validated.GateTransition,$record.Validated.RosterTransition)
            Close-SynapseDeploymentAllocationHandles -Context $journal.Allocation -PayloadsOnly
            [void](Remove-SynapseDeploymentTransactionArtifact -Path $transaction.Root -ExpectedRoot $Authority.Layout.Operations -ExpectedState committed -Reason "operator_${Mode}_forward_cleanup" -Domain authority)
            return [pscustomobject][ordered]@{Exists=$false;Stopped=$false;Restored=$true;Generation=$restored.Generation;Proof=$restored.Proof}
        }
        Die "SYNAPSE_BROKER_OPERATOR_STOP_STATE_INVALID root=$($record.Entry.Path) state=$($journal.State) effective=$effective"
    }finally{Close-SynapseAuthorityControlTransitionLeases -Transitions @($record.Validated.GateTransition,$record.Validated.RosterTransition)}
}

function Invoke-SynapseBrokerOperatorStop {
    param(
        [Parameter(Mandatory=$true)]$Authority,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$DbPath,
        [switch]$Decommission,
        [ValidateRange(30,900)][int]$HealthTimeoutSeconds=420
    )
    $authorityTaskDescriptor=ConvertTo-SynapseAuthorityTaskDescriptor -Task $Authority.BrokerTask
    [void](Assert-SynapseBrokerTaskDescriptorAuthorityCrossbind -Descriptor $authorityTaskDescriptor -BrokerIdentitySha256 ([string]$Authority.Infrastructure.BrokerIdentitySha256) -TaskCapabilitySha256 ([string]$Authority.Infrastructure.TaskCapabilitySha256) -Infrastructure $Authority.Infrastructure -Context 'operator_stop_preflight_task')
    $existing=Resolve-SynapseBrokerOperatorStopTransaction -Authority $Authority -Mode inspect -HealthTimeoutSeconds $HealthTimeoutSeconds
    if([bool]$existing.Stopped){Info "SYNAPSE_BROKER_OPERATOR_ALREADY_STOPPED generation=$($existing.GenerationId) root=$($existing.Root)";return $existing}
    if($null -eq $Authority.CurrentGeneration){
        $parkedPair=Read-SynapseAuthorityActiveControlPair -Layout $Authority.Layout -ExpectedState parked -Context 'operator_stop_inert_pair'
        try{
            $parkedProof=Assert-SynapseBrokerParkedNoAuthority -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -ControlGateIdentity ([pscustomobject]@{Path=$parkedPair.Gate.Path;FileId128=$parkedPair.Gate.FileId128;Sha256=$parkedPair.Gate.Sha256;Length=$parkedPair.Gate.Length}) -RosterIdentity ([pscustomobject]@{Path=$parkedPair.Roster.Path;FileId128=$parkedPair.Roster.FileId128;Sha256=$parkedPair.Roster.Sha256;Length=$parkedPair.Roster.Length}) -ControlGateLease $parkedPair.GateLease -RosterLease $parkedPair.RosterLease -Bind $Bind -DbPath $DbPath -AllowHistoricalPeakForDecommission:$Decommission
            return [pscustomobject][ordered]@{Exists=$false;Stopped=$true;Restored=$false;GenerationId='';Root='';Proof=$parkedProof}
        }finally{Close-SynapseAuthorityActiveControlPair -Pair $parkedPair}
    }
    $pair=Read-SynapseAuthorityActiveControlPair -Layout $Authority.Layout -ExpectedState active -Context 'operator_stop_prearm_pair'
    $root=$null;$allocation=$null;$gateTransition=$null;$rosterTransition=$null;$previousAllocation=$script:SynapseDeploymentAllocationContext
    try{
        $generation=ConvertTo-SynapseAuthorityGenerationFromCurrentRoster -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -ControlGate $pair.Gate -Roster $pair.Roster -Context 'operator_stop_prearm_generation'
        if([string]$generation.GenerationId -cne [string]$Authority.CurrentGeneration.GenerationId){Die "SYNAPSE_BROKER_OPERATOR_STOP_GENERATION_DRIFT expected=$($Authority.CurrentGeneration.GenerationId) actual=$($generation.GenerationId)"}
        $leaf='deployment-{0}-{1}' -f (Get-Date).ToUniversalTime().ToString('yyyyMMddTHHmmssfffZ'),$PID
        $created=[SynapseSetup.AtomicFileV2]::CreatePhysicalDirectoryRelative($Authority.Layout.Operations,(Get-SynapsePhysicalChainPaths -Chain $Authority.Layout.OperationsChain),(Get-SynapsePhysicalChainFileIds -Chain $Authority.Layout.OperationsChain),$leaf)
        $root=Get-SynapseNormalizedDirectoryPath -Path ([string]$created.Path);$rootChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $root)
        $allocation=New-SynapseDeploymentAllocationContext -TransactionRoot $root -TransactionRootChain $rootChain -InvocationId $script:SynapseSetupInvocationId -OwnerPid $PID
        $script:SynapseDeploymentAllocationContext=$allocation;New-SynapseDeploymentPreallocatedJournalSlots -Context $allocation
        $p=$generation.RosterPayload
        $legacyGate=[pscustomobject]@{Path=[string]$p.legacy_gate_path;FileId128=[string]$p.legacy_gate_file_id_128;Sha256=[string]$p.legacy_gate_sha256;Length=[int64]$p.legacy_gate_length}
        $parkedPayload=New-SynapseAuthorityRosterPayload -BrokerIdentitySha256 $Authority.Infrastructure.BrokerIdentitySha256 -TaskCapabilitySha256 $Authority.Infrastructure.TaskCapabilitySha256 -AuthorityEpoch ([int64]$p.authority_epoch) -Revision ([int64]$p.revision+1) -Mode parked -Role none -BrokerTask $Authority.BrokerTask -AuthorityRoot $Authority.Layout.Root -AuthorityRootFileId128 ([string]$Authority.Layout.RootChain[-1].file_id_128) -RuntimeBinDir $Authority.Layout.RuntimeBinDir -RuntimeBinFileId128 ([string]$Authority.Layout.RuntimeChain[-1].file_id_128) -BrokerScript $Authority.Infrastructure.BrokerScript -Bootstrap $Authority.Infrastructure.Bootstrap -ControlGatePath $Authority.Layout.ControlGatePath -ControlNonce ([string]$p.control_nonce) -LegacyGate $legacyGate -Bind ([string]$p.bind) -DbPath ([string]$p.db_path) -ProfilesDir ([string]$p.profiles_dir) -TokenPath ([string]$p.token_path) -CalyxConfigPath ([string]$p.calyx_config_path) -EnableAudio ([bool]$p.enable_audio) -AllowedPermissions ([string]$p.allowed_permissions) -PowerShellPath ([string]$p.powershell_path) -WorkingDirectory ([string]$p.working_directory) -LogDir ([string]$p.log_dir) -BrokerBootstrapLogPath ([string]$p.bootstrap_log_path) -MaintenanceLockPath ([string]$p.maintenance_lock_path) -InvocationId $script:SynapseSetupInvocationId -PreviousRevision ([int64]$p.revision) -PreviousFileId128 ([string]$pair.Roster.FileId128) -PreviousSha256 ([string]$pair.Roster.Sha256) -PreviousLength ([int64]$pair.Roster.Length)
        $parkedEnvelope=New-SynapseAuthorityRosterEnvelope -Payload $parkedPayload
        $rosterTransition=New-SynapseAuthorityControlTransitionPlan -AllocationContext $allocation -DestinationParent $Authority.Layout.Root -DestinationParentChain $Authority.Layout.RootChain -DestinationLeaf $Authority.Layout.RosterLeaf -StageLeaf 'operator-roster-parked-stage.json' -ParkLeaf 'operator-roster-active-park.json' -DiscardLeaf 'operator-roster-parked-discard.json' -ReplacementContent $parkedEnvelope.Text -ExpectedPreState ([pscustomobject]@{Exists=$true;FileId128=$pair.Roster.FileId128;Sha256=$pair.Roster.Sha256;Length=$pair.Roster.Length}) -Purpose 'operator_stop_parked_roster'
        $futureRoster=[pscustomobject]@{Path=$Authority.Layout.RosterPath;FileId128=$rosterTransition.post_file_id_128;Sha256=$rosterTransition.post_sha256;Length=$rosterTransition.post_length}
        $gateEnvelope=New-SynapseAuthorityControlGateEnvelope -BrokerIdentitySha256 $Authority.Infrastructure.BrokerIdentitySha256 -AuthorityEpoch ([int64]$p.authority_epoch) -ControlNonce ([string]$p.control_nonce) -State parked -Roster $futureRoster -ApplicationTransactionId $script:SynapseSetupInvocationId
        $gateTransition=New-SynapseAuthorityControlTransitionPlan -AllocationContext $allocation -DestinationParent $Authority.Layout.Root -DestinationParentChain $Authority.Layout.RootChain -DestinationLeaf $Authority.Layout.ControlGateLeaf -StageLeaf 'operator-gate-parked-stage.json' -ParkLeaf 'operator-gate-active-park.json' -DiscardLeaf 'operator-gate-parked-discard.json' -ReplacementContent $gateEnvelope.Text -ExpectedPreState ([pscustomobject]@{Exists=$true;FileId128=$pair.Gate.FileId128;Sha256=$pair.Gate.Sha256;Length=$pair.Gate.Length}) -Purpose 'operator_stop_parked_control_gate'
        $gateTransition.PreLease=$pair.GateLease;$pair.GateLease=$null;$pair.OwnsGateLease=$false
        $rosterTransition.PreLease=$pair.RosterLease;$pair.RosterLease=$null;$pair.OwnsRosterLease=$false
        Close-SynapseAuthorityActiveControlPair -Pair $pair;$pair=$null
        $allocationRecord=Complete-SynapseDeploymentAllocationLog -Context $allocation
        $initial=[ordered]@{schema='synapse_broker_operator_stop_transaction/v1';state='armed';transaction_kind='synapse_broker_operator_stop/v1';authority_model='immutable_broker/v1';invocation_id=$script:SynapseSetupInvocationId;armed_at_utc=[DateTime]::UtcNow.ToString('o');transaction_root=$root;transaction_root_file_id_128=([string]$created.FileId128).ToUpperInvariant();allocation_marker=$allocationRecord;runtime_bin_dir=$Authority.Layout.RuntimeBinDir;broker_identity_sha256=$Authority.Infrastructure.BrokerIdentitySha256;broker_task_capability_sha256=([string]$Authority.Infrastructure.TaskCapabilitySha256).ToUpperInvariant();authority_epoch=[int64]$Authority.AuthorityEpoch;control_nonce=([string]$Authority.ControlNonce).ToUpperInvariant();broker_task=$authorityTaskDescriptor;bind=[string]$p.bind;db_path=[System.IO.Path]::GetFullPath([string]$p.db_path);token_path=[System.IO.Path]::GetFullPath([string]$p.token_path);generation_id=[string]$generation.GenerationId;current_control_gate=(ConvertTo-SynapseAuthorityIdentityDescriptor -Identity ([pscustomobject]@{Path=$Authority.Layout.ControlGatePath;FileId128=$gateTransition.pre_file_id_128;Sha256=$gateTransition.pre_sha256;Length=$gateTransition.pre_length}));current_roster=(ConvertTo-SynapseAuthorityIdentityDescriptor -Identity ([pscustomobject]@{Path=$Authority.Layout.RosterPath;FileId128=$rosterTransition.pre_file_id_128;Sha256=$rosterTransition.pre_sha256;Length=$rosterTransition.pre_length}));parked_control_gate_transition=(Get-SynapseAuthorityControlTransitionDescriptor $gateTransition);parked_roster_transition=(Get-SynapseAuthorityControlTransitionDescriptor $rosterTransition)}
        $initial.static_transaction_sha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $initial)).ToUpperInvariant()
        [void](Assert-SynapseBrokerOperatorStopInitialDescriptor -Initial ([pscustomobject]$initial) -TransactionRoot $root -Allocation $allocation -Layout $Authority.Layout)
        $journal=Write-SynapseDeploymentTransactionJournalSlot -TransactionRoot $root -TransactionRootChain $rootChain -Sequence 1 -InvocationId $script:SynapseSetupInvocationId -PreviousSlotSha256 '' -Payload $initial
        $transaction=[pscustomobject][ordered]@{Armed=$true;Root=$root;RootChain=$rootChain;ParentRoot=$Authority.Layout.Operations;InvocationId=$script:SynapseSetupInvocationId;JournalSequence=1;JournalSha256=$journal.LatestRawSha256;JournalState='armed';StaticTransactionSha256=$initial.static_transaction_sha256}
        [void](Invoke-SynapseAuthorityControlTransition -Transition $gateTransition -AllocationContext $allocation)
        [void](Invoke-SynapseAuthorityControlTransition -Transition $rosterTransition -AllocationContext $allocation)
        $parkedPair=Read-SynapseAuthorityActiveControlPair -Layout $Authority.Layout -GateLease $gateTransition.CanonicalLease -RosterLease $rosterTransition.CanonicalLease -ExpectedState parked -Context 'operator_stop_parked_pair'
        try{$parkedProof=Assert-SynapseBrokerParkedNoAuthority -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -ControlGateIdentity ([pscustomobject]@{Path=$parkedPair.Gate.Path;FileId128=$parkedPair.Gate.FileId128;Sha256=$parkedPair.Gate.Sha256;Length=$parkedPair.Gate.Length}) -RosterIdentity ([pscustomobject]@{Path=$parkedPair.Roster.Path;FileId128=$parkedPair.Roster.FileId128;Sha256=$parkedPair.Roster.Sha256;Length=$parkedPair.Roster.Length}) -ControlGateLease $parkedPair.GateLease -RosterLease $parkedPair.RosterLease -Bind ([string]$p.bind) -DbPath ([string]$p.db_path) -AllowHistoricalPeakForDecommission:$Decommission}finally{Close-SynapseAuthorityActiveControlPair -Pair $parkedPair}
        [void](Add-SynapseDeploymentTransactionJournalState -State candidate_ready -Payload ([ordered]@{operator_stopped=$true;broker_identity_sha256=[string]$Authority.Infrastructure.BrokerIdentitySha256;generation_id=[string]$generation.GenerationId;parked_authority_proven=$true;daemon_count=0;listener_count=0}) -Transaction $transaction)
        Close-SynapseAuthorityControlTransitionLeases -Transitions @($gateTransition,$rosterTransition);Close-SynapseDeploymentAllocationHandles -Context $allocation
        return [pscustomobject][ordered]@{Exists=$true;Stopped=$true;Restored=$false;GenerationId=[string]$generation.GenerationId;Root=$root;Proof=$parkedProof}
    }catch{
        $primary=$_.Exception.Message
        if($null -ne $root){
            try{
                $record=Get-SynapseBrokerOperatorStopRecord -Authority $Authority
                if($null -ne $record -and [string]$record.Journal.State -ceq 'candidate_ready'){return [pscustomobject][ordered]@{Exists=$true;Stopped=$true;Restored=$false;GenerationId=[string]$record.Journal.Initial.generation_id;Root=[string]$record.Entry.Path}}
                if($null -ne $record){[void](Resolve-SynapseBrokerOperatorStopTransaction -Authority $Authority -Mode setup -HealthTimeoutSeconds $HealthTimeoutSeconds)}
            }catch{Die "SYNAPSE_BROKER_OPERATOR_STOP_FAILED_AND_RESTORE_FAILED primary=[$primary] rollback=[$($_.Exception.Message)] root=$root"}
        }
        throw $primary
    }finally{
        Close-SynapseAuthorityActiveControlPair -Pair $pair;Close-SynapseAuthorityControlTransitionLeases -Transitions @($gateTransition,$rosterTransition)
        if($null -ne $allocation){try{Close-SynapseDeploymentAllocationHandles -Context $allocation}catch{}};$script:SynapseDeploymentAllocationContext=$previousAllocation
    }
}

function Get-SynapseBrokerAuthorityForOperatorLifecycle {
    param(
        [Parameter(Mandatory=$true)][string]$RuntimeBinDir,
        [Parameter(Mandatory=$true)][string]$TaskName,
        [Parameter(Mandatory=$true)][string]$ExePath,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$DbPath,
        [Parameter(Mandatory=$true)][string]$ProfilesDir,
        [Parameter(Mandatory=$true)][string]$TokenPath,
        [Parameter(Mandatory=$true)][string]$LogDir,
        [Parameter(Mandatory=$true)][string]$MaintenanceLockPath,
        [switch]$AllowMissingTokenWhenParked,
        [switch]$DecommissionStructuralOnly,
        [AllowNull()]$ExpectedTokenAuthority,
        [ValidateRange(60,900)][int]$HealthTimeoutSeconds=420
    )
    $expectedTokenAuthority=$null;$expectedTokenBoundaryLease=$null
    if($null-ne$ExpectedTokenAuthority){
        $expectedTokenAuthority=Assert-SynapseBrokerDecommissionTokenAuthorityDescriptor -Descriptor $ExpectedTokenAuthority -ExpectedPath $TokenPath -Context 'broker_operator_lifecycle_expected_token'
        $expectedMissing=([string]$expectedTokenAuthority.disposition-ceq'parked_exact_absence')
        if($expectedMissing-ne[bool]$AllowMissingTokenWhenParked){Die "SYNAPSE_BROKER_AUTHORITY_EXPECTED_TOKEN_MODE_INVALID disposition=$($expectedTokenAuthority.disposition) allow_missing=$([bool]$AllowMissingTokenWhenParked)"}
        $expectedTokenBoundaryLease=Open-SynapseBrokerDecommissionTokenAuthorityBoundary -Descriptor $expectedTokenAuthority -ExpectedPath $TokenPath -Context 'broker_operator_lifecycle_expected_token_before'
    }
    $tokenBoundaryLease=$null;$authority=$null;$returning=$false
    try{
        $tokenRead=Read-SynapseSetupTokenForRestartGuard -TokenPath $TokenPath
        $tokenMissing=(-not[bool]$tokenRead.Ok)
        if($tokenMissing-and(-not$AllowMissingTokenWhenParked-or[string]$tokenRead.Code-cne'SYNAPSE_RESTART_GUARD_TOKEN_MISSING')){Die "$($tokenRead.Code) reason=broker_operator_lifecycle $($tokenRead.Detail) remediation=repair the exact committed broker token before using -Start or -Stop; only an exactly absent token may be bypassed for a physically parked plain -Remove"}
        $tokenSnapshot=Get-SynapsePurgeFileSnapshot -Path $TokenPath -Context 'broker_operator_lifecycle_token_authority'
        $tokenDisposition=if($tokenMissing){'parked_exact_absence'}else{'authenticated_present'}
        if(($tokenMissing-and[bool]$tokenSnapshot.exists)-or(-not$tokenMissing-and-not[bool]$tokenSnapshot.exists)){Die "SYNAPSE_BROKER_AUTHORITY_TOKEN_CLASSIFICATION_DRIFT missing=$tokenMissing exists=$([bool]$tokenSnapshot.exists)"}
        $tokenAuthority=[ordered]@{schema='synapse_broker_decommission_token_authority/v1';disposition=$tokenDisposition;token=(ConvertTo-SynapseCanonicalValue -Value $tokenSnapshot)}
        [void](Assert-SynapseBrokerDecommissionTokenAuthorityDescriptor -Descriptor $tokenAuthority -ExpectedPath $TokenPath -Context 'broker_operator_lifecycle_token_authority')
        if($null-ne$expectedTokenAuthority-and(Get-SynapseCanonicalJson -Value $tokenAuthority)-cne(Get-SynapseCanonicalJson -Value $expectedTokenAuthority)){Die "SYNAPSE_BROKER_AUTHORITY_EXPECTED_TOKEN_DRIFT path=$TokenPath expected=$($expectedTokenAuthority.disposition) actual=$tokenDisposition"}
        $tokenBoundaryLease=$expectedTokenBoundaryLease;$expectedTokenBoundaryLease=$null
        if($null-eq$tokenBoundaryLease){$tokenBoundaryLease=Open-SynapseBrokerDecommissionTokenAuthorityBoundary -Descriptor $tokenAuthority -ExpectedPath $TokenPath -Context 'broker_operator_lifecycle_token_boundary'}
        if($tokenMissing){$authorityToken='missing-token-not-consumed-for-parked-decommission'}else{
            $tokenText=[string]$tokenBoundaryLease.ReadUtf8(4096).Content;$authorityToken=$tokenText.Trim()
            if($authorityToken.Length-lt16-or$authorityToken-cne[string]$tokenRead.Token){Die "SYNAPSE_BROKER_AUTHORITY_TOKEN_EXACT_READ_DRIFT path=$TokenPath chars=$($authorityToken.Length)"}
            $tokenBoundaryLease.RequireExact('broker_operator_lifecycle_token_exact_read')
        }
        $powerShellPath=[System.IO.Path]::GetFullPath((Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'))
        $bootstrapHint=[System.IO.Path]::GetFullPath((Join-Path $RuntimeBinDir 'synapse-supervisor-bootstrap.exe'))
        $configHint=[System.IO.Path]::GetFullPath((Join-Path $RuntimeBinDir '.broker-committed-receipt-config-placeholder'))
        $authority=Ensure-SynapseBrokerAuthorityAdopted -RuntimeBinDir $RuntimeBinDir -BootstrapSourcePath $bootstrapHint -PowerShellPath $powerShellPath -WorkingDirectory $RuntimeBinDir -LogDir $LogDir -TaskName $TaskName -ExePath $ExePath -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -Token $authorityToken -MaintenanceLockPath $MaintenanceLockPath -CalyxConfigPath $configHint -ExpectedCalyxConfigSha256 ('0'*64) -EnableAudio:$false -AllowedPermissions '' -RequireCommitted -DecommissionStructuralOnly:$DecommissionStructuralOnly -AllowMissingTokenWhenParked:$tokenMissing -HealthTimeoutSeconds $HealthTimeoutSeconds
        if($tokenMissing-and$null-ne$authority.CurrentGeneration){Die 'SYNAPSE_BROKER_AUTHORITY_MISSING_TOKEN_ACTIVE_GENERATION_REFUSED'}
        if($null-ne$tokenBoundaryLease){$tokenBoundaryLease.RequireExact('broker_operator_lifecycle_token_readback')}else{[void](Open-SynapseBrokerDecommissionTokenAuthorityBoundary -Descriptor $tokenAuthority -ExpectedPath $TokenPath -Context 'broker_operator_lifecycle_token_readback')}
        $authority|Add-Member -NotePropertyName TokenAuthority -NotePropertyValue (ConvertTo-SynapseCanonicalValue -Value $tokenAuthority) -Force
        $returning=$true
        return $authority
    }finally{
        if($null-ne$tokenBoundaryLease){try{$tokenBoundaryLease.Dispose()}catch{[Environment]::FailFast('SYNAPSE_BROKER_LIFECYCLE_TOKEN_LEASE_RELEASE_UNPROVEN',$_.Exception)}}
        if($null-ne$expectedTokenBoundaryLease){try{$expectedTokenBoundaryLease.Dispose()}catch{[Environment]::FailFast('SYNAPSE_BROKER_LIFECYCLE_EXPECTED_TOKEN_LEASE_RELEASE_UNPROVEN',$_.Exception)}}
        if(-not$returning-and$null-ne$authority-and$null-ne$authority.Infrastructure){Close-SynapseBrokerTaskReceiptInfrastructure -Infrastructure $authority.Infrastructure}
    }
}

function Assert-SynapseBrokerDecommissionMissingTokenGlobalPreflight {
    param(
        [Parameter(Mandatory=$true)][string]$RuntimeBinDir,
        [Parameter(Mandatory=$true)][string]$TaskName,
        [Parameter(Mandatory=$true)][string]$ExePath,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$DbPath,
        [Parameter(Mandatory=$true)][string]$ProfilesDir,
        [Parameter(Mandatory=$true)][string]$TokenPath,
        [Parameter(Mandatory=$true)][string]$LogDir,
        [Parameter(Mandatory=$true)][string]$MaintenanceLockPath,
        [ValidateRange(60,900)][int]$HealthTimeoutSeconds=420
    )
    $tokenRead=Read-SynapseSetupTokenForRestartGuard -TokenPath $TokenPath
    $tokenMissing=(-not[bool]$tokenRead.Ok)
    if($tokenMissing-and[string]$tokenRead.Code-cne'SYNAPSE_RESTART_GUARD_TOKEN_MISSING'){Die "$($tokenRead.Code) reason=broker_decommission_pre_global_recovery $($tokenRead.Detail) remediation=repair the exact committed token before any recovery or removal mutation"}
    $tokenSnapshot=Get-SynapsePurgeFileSnapshot -Path $TokenPath -Context 'broker_decommission_pre_global_token'
    if(($tokenMissing-and[bool]$tokenSnapshot.exists)-or(-not$tokenMissing-and-not[bool]$tokenSnapshot.exists)){Die "SYNAPSE_BROKER_DECOMMISSION_PRE_GLOBAL_TOKEN_CLASSIFICATION_DRIFT path=$TokenPath missing=$tokenMissing exists=$([bool]$tokenSnapshot.exists)"}
    $tokenAuthority=[ordered]@{schema='synapse_broker_decommission_token_authority/v1';disposition=$(if($tokenMissing){'parked_exact_absence'}else{'authenticated_present'});token=(ConvertTo-SynapseCanonicalValue -Value $tokenSnapshot)}
    [void](Assert-SynapseBrokerDecommissionTokenAuthorityDescriptor -Descriptor $tokenAuthority -ExpectedPath $TokenPath -Context 'broker_decommission_pre_global_token_authority')
    $authority=$null;$tokenBoundaryLease=$null
    try{
        $tokenBoundaryLease=Open-SynapseBrokerDecommissionTokenAuthorityBoundary -Descriptor $tokenAuthority -ExpectedPath $TokenPath -Context 'broker_decommission_pre_global_token_boundary'
        if(-not$tokenMissing){
            $tokenText=[string]$tokenBoundaryLease.ReadUtf8(4096).Content;$exactToken=$tokenText.Trim()
            if($exactToken.Length-lt16-or$exactToken-cne[string]$tokenRead.Token){Die "SYNAPSE_BROKER_DECOMMISSION_PRE_GLOBAL_TOKEN_EXACT_READ_DRIFT path=$TokenPath chars=$($exactToken.Length)"}
            $tokenBoundaryLease.RequireExact('broker_decommission_pre_global_token_exact_read')
            return [pscustomobject][ordered]@{Missing=$false;TokenAuthority=(ConvertTo-SynapseCanonicalValue -Value $tokenAuthority);InventoryFingerprintSha256=''}
        }
        $authority=Get-SynapseBrokerAuthorityForOperatorLifecycle -RuntimeBinDir $RuntimeBinDir -TaskName $TaskName -ExePath $ExePath -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -LogDir $LogDir -MaintenanceLockPath $MaintenanceLockPath -AllowMissingTokenWhenParked -ExpectedTokenAuthority $tokenAuthority -HealthTimeoutSeconds $HealthTimeoutSeconds
        if($null-ne$authority.CurrentGeneration-or$null-eq$authority.PSObject.Properties['TokenAuthority']-or(Get-SynapseCanonicalJson -Value $authority.TokenAuthority)-cne(Get-SynapseCanonicalJson -Value $tokenAuthority)){Die 'SYNAPSE_BROKER_DECOMMISSION_PRE_GLOBAL_PARKED_AUTHORITY_INVALID'}
        $inventory=Get-SynapseGlobalRecoveryInventory -LogDir $LogDir -ProfilesDir $ProfilesDir -RuntimeBinDir $RuntimeBinDir
        $prerequisite=Assert-SynapseGlobalCommittedAuthorityPreflight -Inventory $inventory -TaskInfrastructure $authority.Infrastructure -RuntimeBinDir $RuntimeBinDir -RequestedLegacyTaskName $TaskName -DecommissionStructuralOnly
        $selection=Select-SynapseGlobalRecoveryAction -Inventory $inventory -Mode setup
        $terminalV1=@($inventory.V1|Where-Object{[string]$_.State-in@('committed','rolled_back')})
        $terminalV3=@($inventory.LegacyV3|Where-Object{[string]$_.EffectiveState-ceq'rolled_back'})
        if(-not[bool]$selection.Allowed-or[string]$selection.Action-cne'none'-or[string]$prerequisite.ControlState-cne'parked'-or$terminalV1.Count-ne0-or$terminalV3.Count-ne0){Die "SYNAPSE_BROKER_DECOMMISSION_MISSING_TOKEN_GLOBAL_RECOVERY_REFUSED allowed=$([bool]$selection.Allowed) action=$($selection.Action) control_state=$($prerequisite.ControlState) terminal_v1=$($terminalV1.Count) terminal_v3=$($terminalV3.Count) remediation=restore the exact committed token and converge every recovery owner before plain -Remove"}
        [void](Open-SynapseBrokerDecommissionTokenAuthorityBoundary -Descriptor $tokenAuthority -ExpectedPath $TokenPath -Context 'broker_decommission_pre_global_token_readback')
        Info "SYNAPSE_BROKER_DECOMMISSION_MISSING_TOKEN_PREFLIGHT_VERIFIED control_state=parked recovery_action=none inventory=$($inventory.FingerprintSha256)"
        return [pscustomobject][ordered]@{Missing=$true;TokenAuthority=(ConvertTo-SynapseCanonicalValue -Value $tokenAuthority);InventoryFingerprintSha256=([string]$inventory.FingerprintSha256).ToUpperInvariant()}
    }finally{if($null-ne$tokenBoundaryLease){try{$tokenBoundaryLease.Dispose()}catch{[Environment]::FailFast('SYNAPSE_BROKER_DECOMMISSION_PRE_GLOBAL_TOKEN_LEASE_RELEASE_UNPROVEN',$_.Exception)}};if($null-ne$authority-and$null-ne$authority.Infrastructure){Close-SynapseBrokerTaskReceiptInfrastructure -Infrastructure $authority.Infrastructure}}
}

function Restore-SynapseBrokerProbeParkTransaction {
    param(
        [Parameter(Mandatory=$true)]$Validated,
        [Parameter(Mandatory=$true)]$Authority,
        [Parameter(Mandatory=$true)][ValidatePattern('^(prior|candidate)-[0-9a-f]{40}$')][string]$ExpectedGenerationId,
        [ValidateRange(30,900)][int]$HealthTimeoutSeconds=420
    )
    [void](Invoke-SynapseAuthorityControlTransitionRollback -Transition $Validated.RosterTransition)
    [void](Invoke-SynapseAuthorityControlTransitionRollback -Transition $Validated.GateTransition)
    $pair=Read-SynapseAuthorityActiveControlPair -Layout $Validated.Layout -GateLease $Validated.GateTransition.RestoredLease -RosterLease $Validated.RosterTransition.RestoredLease -ExpectedState active -Context 'probe_park_restore_pair'
    try{
        $generation=ConvertTo-SynapseAuthorityGenerationFromCurrentRoster -Layout $Validated.Layout -Infrastructure $Authority.Infrastructure -ControlGate $pair.Gate -Roster $pair.Roster -Context 'probe_park_restored_generation'
        if([string]$generation.GenerationId -cne $ExpectedGenerationId){Die "SYNAPSE_BROKER_PROBE_PARK_RESTORED_GENERATION_MISMATCH expected=$ExpectedGenerationId actual=$($generation.GenerationId)"}
        $proof=Wait-SynapseCurrentAuthorityGenerationOperational -Layout $Validated.Layout -Infrastructure $Authority.Infrastructure -Generation $generation -ControlGateIdentity $Validated.CurrentControlGate -RosterIdentity $Validated.CurrentRoster -ControlGateLease $pair.GateLease -RosterLease $pair.RosterLease -HealthTimeoutSeconds $HealthTimeoutSeconds -Context 'probe_park_restored_generation'
        return [pscustomobject][ordered]@{Generation=$generation;Proof=$proof;Pair=$pair}
    }catch{Close-SynapseAuthorityActiveControlPair -Pair $pair;throw}
}

function Invoke-SynapseBrokerSourceCandidateProbe {
    param(
        [Parameter(Mandatory=$true)]$Authority,
        [Parameter(Mandatory=$true)][string]$DeploymentTransactionParent,
        [Parameter(Mandatory=$true)]$DeploymentTransactionParentChain,
        [Parameter(Mandatory=$true)][string]$CandidateExePath,
        [Parameter(Mandatory=$true)][string]$CandidateBootstrapPath,
        [Parameter(Mandatory=$true)][string]$ExpectedCandidateBootstrapSha256,
        [Parameter(Mandatory=$true)][string]$ProfilesDir,
        [Parameter(Mandatory=$true)][string]$TokenPath,
        [Parameter(Mandatory=$true)][string]$Token,
        [Parameter(Mandatory=$true)][string]$LogDir,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$DbPath,
        [bool]$EnableAudio,
        [AllowNull()][string]$AllowedPermissions,
        [Parameter(Mandatory=$true)][string]$CalyxConfigPath,
        [Parameter(Mandatory=$true)][string]$ExpectedCalyxConfigSha256,
        [AllowNull()][string]$ReplacementReservationId,
        [ValidateRange(30,900)][int]$HealthTimeoutSeconds=420
    )
    $taskSupersessionInfrastructure=$null
    if(-not(Test-SynapseScheduledTaskExistsExact -Name ([string]$Authority.BrokerTask.Name))){
        if($null-eq$Authority.Initial-or$null-eq$Authority.Initial.broker_task_receipt){Die "SYNAPSE_BROKER_SOURCE_PROBE_SUPERSEDED_TASK_RECEIPT_MISSING task=$($Authority.BrokerTask.Name)"}
        $taskSupersessionInfrastructure=Open-SynapseLatestBrokerTaskInfrastructureForSupersededReceipt -Layout $Authority.Layout -SupersededReceipt $Authority.Initial.broker_task_receipt
    }
    $authorityTaskDescriptor=ConvertTo-SynapseAuthorityTaskDescriptor -Task $Authority.BrokerTask
    [void](Assert-SynapseBrokerTaskDescriptorAuthorityCrossbind -Descriptor $authorityTaskDescriptor -BrokerIdentitySha256 ([string]$Authority.Infrastructure.BrokerIdentitySha256) -TaskCapabilitySha256 ([string]$Authority.Infrastructure.TaskCapabilitySha256) -Infrastructure $Authority.Infrastructure -Context 'source_probe_prearm_task')
    $probeCapability=(Get-SynapseSha256Hex -Text "synapse-source-probe:$($script:SynapseSetupInvocationId):$([Guid]::NewGuid().ToString('N'))").ToUpperInvariant()
    $priorAuthority=if($null -eq $Authority.CurrentGeneration){'absent'}else{'present'}
    $pair=Read-SynapseAuthorityActiveControlPair -Layout $Authority.Layout -ExpectedState $(if($priorAuthority -ceq 'present'){'active'}else{'parked'}) -Context "source_probe_${priorAuthority}_pair"
    $root=$null;$rootChain=$null;$allocation=$null;$localTransaction=$null;$gateTransition=$null;$rosterTransition=$null;$previousAllocation=$script:SynapseDeploymentAllocationContext
    try{
        if($priorAuthority -ceq 'present' -and [string]$pair.Roster.Payload.generation_id -cne [string]$Authority.CurrentGeneration.GenerationId){Die "SYNAPSE_BROKER_SOURCE_PROBE_CURRENT_GENERATION_DRIFT expected=$($Authority.CurrentGeneration.GenerationId) actual=$($pair.Roster.Payload.generation_id)"}
        $stamp=(Get-Date).ToUniversalTime().ToString('yyyyMMddTHHmmssfffZ');$leaf="deployment-$stamp-$PID"
        $created=[SynapseSetup.AtomicFileV2]::CreatePhysicalDirectoryRelative($DeploymentTransactionParent,(Get-SynapsePhysicalChainPaths -Chain $DeploymentTransactionParentChain),(Get-SynapsePhysicalChainFileIds -Chain $DeploymentTransactionParentChain),$leaf)
        $root=Get-SynapseNormalizedDirectoryPath -Path ([string]$created.Path);$rootChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $root)
        $allocation=New-SynapseDeploymentAllocationContext -TransactionRoot $root -TransactionRootChain $rootChain -InvocationId $script:SynapseSetupInvocationId -OwnerPid $PID
        $script:SynapseDeploymentAllocationContext=$allocation
        New-SynapseDeploymentPreallocatedJournalSlots -Context $allocation
        $p=$pair.Roster.Payload
        $currentGateIdentity=[pscustomobject]@{Path=$Authority.Layout.ControlGatePath;FileId128=$pair.Gate.FileId128;Sha256=$pair.Gate.Sha256;Length=$pair.Gate.Length}
        $currentRosterIdentity=[pscustomobject]@{Path=$Authority.Layout.RosterPath;FileId128=$pair.Roster.FileId128;Sha256=$pair.Roster.Sha256;Length=$pair.Roster.Length}
        if($priorAuthority -ceq 'present'){
            $legacyGate=[pscustomobject]@{Path=[string]$p.legacy_gate_path;FileId128=[string]$p.legacy_gate_file_id_128;Sha256=[string]$p.legacy_gate_sha256;Length=[int64]$p.legacy_gate_length}
            $parkedPayload=New-SynapseAuthorityRosterPayload -BrokerIdentitySha256 $Authority.Infrastructure.BrokerIdentitySha256 -TaskCapabilitySha256 $Authority.Infrastructure.TaskCapabilitySha256 -AuthorityEpoch ([int64]$p.authority_epoch) -Revision ([int64]$p.revision+1) -Mode parked -Role none -BrokerTask $Authority.BrokerTask -AuthorityRoot $Authority.Layout.Root -AuthorityRootFileId128 ([string]$Authority.Layout.RootChain[-1].file_id_128) -RuntimeBinDir $Authority.Layout.RuntimeBinDir -RuntimeBinFileId128 ([string]$Authority.Layout.RuntimeChain[-1].file_id_128) -BrokerScript $Authority.Infrastructure.BrokerScript -Bootstrap $Authority.Infrastructure.Bootstrap -ControlGatePath $Authority.Layout.ControlGatePath -ControlNonce ([string]$p.control_nonce) -LegacyGate $legacyGate -Bind ([string]$p.bind) -DbPath ([string]$p.db_path) -ProfilesDir ([string]$p.profiles_dir) -TokenPath ([string]$p.token_path) -CalyxConfigPath ([string]$p.calyx_config_path) -EnableAudio ([bool]$p.enable_audio) -AllowedPermissions ([string]$p.allowed_permissions) -PowerShellPath ([string]$p.powershell_path) -WorkingDirectory ([string]$p.working_directory) -LogDir ([string]$p.log_dir) -BrokerBootstrapLogPath ([string]$p.bootstrap_log_path) -MaintenanceLockPath ([string]$p.maintenance_lock_path) -InvocationId $script:SynapseSetupInvocationId -PreviousRevision ([int64]$p.revision) -PreviousFileId128 ([string]$pair.Roster.FileId128) -PreviousSha256 ([string]$pair.Roster.Sha256) -PreviousLength ([int64]$pair.Roster.Length)
            $parkedEnvelope=New-SynapseAuthorityRosterEnvelope -Payload $parkedPayload
            $rosterTransition=New-SynapseAuthorityControlTransitionPlan -AllocationContext $allocation -DestinationParent $Authority.Layout.Root -DestinationParentChain $Authority.Layout.RootChain -DestinationLeaf $Authority.Layout.RosterLeaf -StageLeaf 'probe-roster-parked-stage.json' -ParkLeaf 'probe-roster-active-park.json' -DiscardLeaf 'probe-roster-parked-discard.json' -ReplacementContent $parkedEnvelope.Text -ExpectedPreState ([pscustomobject]@{Exists=$true;FileId128=$pair.Roster.FileId128;Sha256=$pair.Roster.Sha256;Length=$pair.Roster.Length}) -Purpose 'source_probe_parked_roster'
            $futureParked=[pscustomobject]@{Path=$Authority.Layout.RosterPath;FileId128=$rosterTransition.post_file_id_128;Sha256=$rosterTransition.post_sha256;Length=$rosterTransition.post_length}
            $gateEnvelope=New-SynapseAuthorityControlGateEnvelope -BrokerIdentitySha256 $Authority.Infrastructure.BrokerIdentitySha256 -AuthorityEpoch ([int64]$p.authority_epoch) -ControlNonce ([string]$p.control_nonce) -State parked -Roster $futureParked -ApplicationTransactionId $script:SynapseSetupInvocationId
            $gateTransition=New-SynapseAuthorityControlTransitionPlan -AllocationContext $allocation -DestinationParent $Authority.Layout.Root -DestinationParentChain $Authority.Layout.RootChain -DestinationLeaf $Authority.Layout.ControlGateLeaf -StageLeaf 'probe-gate-parked-stage.json' -ParkLeaf 'probe-gate-active-park.json' -DiscardLeaf 'probe-gate-parked-discard.json' -ReplacementContent $gateEnvelope.Text -ExpectedPreState ([pscustomobject]@{Exists=$true;FileId128=$pair.Gate.FileId128;Sha256=$pair.Gate.Sha256;Length=$pair.Gate.Length}) -Purpose 'source_probe_parked_control_gate'
            $gateTransition.PreLease=$pair.GateLease;$pair.GateLease=$null;$pair.OwnsGateLease=$false
            $rosterTransition.PreLease=$pair.RosterLease;$pair.RosterLease=$null;$pair.OwnsRosterLease=$false
            Close-SynapseAuthorityActiveControlPair -Pair $pair;$pair=$null
        }else{
            # The immutable initial descriptor below carries the exact current
            # identities.  Do not retain the construction read leases while
            # its validator independently reopens those files.  Reacquire a
            # fresh continuous pair after journal publication for the probe's
            # actual mutation/observation boundary.
            Close-SynapseAuthorityActiveControlPair -Pair $pair;$pair=$null
        }
        $allocationRecord=Complete-SynapseDeploymentAllocationLog -Context $allocation
        $initial=[ordered]@{schema='synapse_broker_probe_park_transaction/v1';state='armed';transaction_kind='synapse_broker_probe_park/v1';invocation_id=$script:SynapseSetupInvocationId;armed_at_utc=[DateTime]::UtcNow.ToString('o');transaction_root=$root;transaction_root_file_id_128=([string]$created.FileId128).ToUpperInvariant();allocation_marker=$allocationRecord;runtime_bin_dir=$Authority.Layout.RuntimeBinDir;profiles_dir=[System.IO.Path]::GetFullPath($ProfilesDir);bind=$Bind;db_path=[System.IO.Path]::GetFullPath($DbPath);token_path=[System.IO.Path]::GetFullPath($TokenPath);broker_identity_sha256=$Authority.Infrastructure.BrokerIdentitySha256;broker_task_capability_sha256=([string]$Authority.Infrastructure.TaskCapabilitySha256).ToUpperInvariant();authority_epoch=[int64]$p.authority_epoch;control_nonce=([string]$p.control_nonce).ToUpperInvariant();broker_task=$authorityTaskDescriptor;prior_authority=$priorAuthority;current_generation_id=$(if($priorAuthority -ceq 'present'){[string]$Authority.CurrentGeneration.GenerationId}else{''});current_control_gate=(ConvertTo-SynapseAuthorityIdentityDescriptor -Identity $currentGateIdentity);current_roster=(ConvertTo-SynapseAuthorityIdentityDescriptor -Identity $currentRosterIdentity);parked_control_gate_transition=$(if($null -ne $gateTransition){Get-SynapseAuthorityControlTransitionDescriptor $gateTransition}else{$null});parked_roster_transition=$(if($null -ne $rosterTransition){Get-SynapseAuthorityControlTransitionDescriptor $rosterTransition}else{$null});probe_capability_sha256=$probeCapability}
        $initial.static_transaction_sha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $initial)).ToUpperInvariant()
        [void](Assert-SynapseBrokerProbeParkInitialDescriptor -Initial ([pscustomobject]$initial) -TransactionRoot $root -Allocation $allocation)
        $journal=Write-SynapseDeploymentTransactionJournalSlot -TransactionRoot $root -TransactionRootChain $rootChain -Sequence 1 -InvocationId $script:SynapseSetupInvocationId -PreviousSlotSha256 '' -Payload $initial
        $localTransaction=[pscustomobject][ordered]@{Armed=$true;Committed=$false;Root=$root;RootChain=$rootChain;ParentRoot=$DeploymentTransactionParent;InvocationId=$script:SynapseSetupInvocationId;JournalSequence=1;JournalSha256=$journal.LatestRawSha256;JournalState='armed';StaticTransactionSha256=$initial.static_transaction_sha256}
        if($priorAuthority -ceq 'present'){
            [void](Invoke-SynapseAuthorityControlTransition -Transition $gateTransition -AllocationContext $allocation)
            [void](Invoke-SynapseAuthorityControlTransition -Transition $rosterTransition -AllocationContext $allocation)
            $parkedProof=Assert-SynapseBrokerParkedNoAuthority -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -ControlGateIdentity ([pscustomobject]@{Path=$Authority.Layout.ControlGatePath;FileId128=$gateTransition.post_file_id_128;Sha256=$gateTransition.post_sha256;Length=$gateTransition.post_length}) -RosterIdentity ([pscustomobject]@{Path=$Authority.Layout.RosterPath;FileId128=$rosterTransition.post_file_id_128;Sha256=$rosterTransition.post_sha256;Length=$rosterTransition.post_length}) -ControlGateLease $gateTransition.CanonicalLease -RosterLease $rosterTransition.CanonicalLease -TaskSupersessionInfrastructure $taskSupersessionInfrastructure -Bind ([string]$p.bind) -DbPath ([string]$p.db_path)
        }else{
            $pair=Read-SynapseAuthorityActiveControlPair -Layout $Authority.Layout -ExpectedState parked -Context "source_probe_fresh_boundary_$root"
            if([string]$pair.Gate.FileId128-ine$currentGateIdentity.FileId128 -or [string]$pair.Gate.Sha256-ine$currentGateIdentity.Sha256 -or [int64]$pair.Gate.Length-ne$currentGateIdentity.Length -or
               [string]$pair.Roster.FileId128-ine$currentRosterIdentity.FileId128 -or [string]$pair.Roster.Sha256-ine$currentRosterIdentity.Sha256 -or [int64]$pair.Roster.Length-ne$currentRosterIdentity.Length){Die "SYNAPSE_BROKER_SOURCE_PROBE_FRESH_BOUNDARY_DRIFT root=$root"}
            $parkedProof=Assert-SynapseBrokerParkedNoAuthority -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -ControlGateIdentity ([pscustomobject]@{Path=$Authority.Layout.ControlGatePath;FileId128=$pair.Gate.FileId128;Sha256=$pair.Gate.Sha256;Length=$pair.Gate.Length}) -RosterIdentity ([pscustomobject]@{Path=$Authority.Layout.RosterPath;FileId128=$pair.Roster.FileId128;Sha256=$pair.Roster.Sha256;Length=$pair.Roster.Length}) -ControlGateLease $pair.GateLease -RosterLease $pair.RosterLease -TaskSupersessionInfrastructure $taskSupersessionInfrastructure -Bind $Bind -DbPath $DbPath
        }
        $convertProbePlanJournalDescriptor=${function:ConvertTo-SynapseCandidateProbePlanJournalDescriptor}
        $appendDeploymentJournalState=${function:Add-SynapseDeploymentTransactionJournalState}
        $beforeTaskCreate={param($planAuthority)
            $planDescriptor=& $convertProbePlanJournalDescriptor -PlanAuthority $planAuthority
            [void](& $appendDeploymentJournalState -State candidate_ready -Payload ([ordered]@{purpose='source_probe_task_create_authorized';prior_authority=$priorAuthority;probe_capability_sha256=$probeCapability;probe_plan=$planDescriptor;parked_authority_proven=$true;parked_outer_bootstrap_pid=[int]$parkedProof.OuterBootstrapPid}) -Transaction $localTransaction)
        }.GetNewClosure()
        $candidate=Test-SynapseCandidateDaemon -CandidateExePath $CandidateExePath -CandidateBootstrapPath $CandidateBootstrapPath -ExpectedCandidateBootstrapSha256 $ExpectedCandidateBootstrapSha256 -ProfilesDir $ProfilesDir -TokenPath $TokenPath -LogDir $LogDir -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions -CalyxConfigPath $CalyxConfigPath -ExpectedCalyxConfigSha256 $ExpectedCalyxConfigSha256 -ReplacementReservationId $ReplacementReservationId -UseTaskProbe -ProbeCapability $probeCapability -BeforeTaskCreate $beforeTaskCreate
        # Candidate validation owns nested allocation contexts for its probe task.
        # Re-establish this source-probe allocation as the exact same-handle read
        # authority before inspecting its journal.  A pathname reopen is expected
        # to fail while the live allocation log lease denies replacement/deletion.
        $script:SynapseDeploymentAllocationContext=$allocation
        $afterProbe=Read-SynapseDeploymentTransactionJournal -TransactionRoot $root -TransactionRootChain $rootChain
        if([string]$afterProbe.State -cne 'candidate_ready'){Die "SYNAPSE_BROKER_SOURCE_PROBE_TASK_AUTHORITY_JOURNAL_MISSING root=$root state=$($afterProbe.State)"}
        $plan=Read-SynapseCandidateProbePlanFromJournal -Descriptor $afterProbe.Slots[-1].LexicalPayload.detail.probe_plan -ExpectedCapabilitySha256 $probeCapability -Context 'source_probe_after_candidate'
        try{[void](Remove-SynapseJournalBoundCandidateProbeTask -Plan $plan -Context 'source_probe_after_candidate')}finally{if($null -ne $plan.Lease){$plan.Lease.Dispose()}}
        $priorDaemonPid=0
        if($priorAuthority -ceq 'present'){
            $validated=Assert-SynapseBrokerProbeParkInitialDescriptor -Initial $afterProbe.Initial -TransactionRoot $root -Allocation $allocation -ExistingGateTransition $gateTransition -ExistingRosterTransition $rosterTransition
            $validated.GateTransition=$gateTransition;$validated.RosterTransition=$rosterTransition
            $restored=Restore-SynapseBrokerProbeParkTransaction -Validated $validated -Authority $Authority -ExpectedGenerationId ([string]$afterProbe.Initial.current_generation_id) -HealthTimeoutSeconds $HealthTimeoutSeconds
            $priorDaemonPid=[int]$restored.Proof.DaemonPid
            Close-SynapseAuthorityActiveControlPair -Pair $restored.Pair
        }else{
            $pair.GateLease.RequireExact('source_probe_fresh_gate_after_candidate');$pair.RosterLease.RequireExact('source_probe_fresh_roster_after_candidate')
            [void](Assert-SynapseBrokerParkedNoAuthority -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -ControlGateIdentity ([pscustomobject]@{Path=$Authority.Layout.ControlGatePath;FileId128=$pair.Gate.FileId128;Sha256=$pair.Gate.Sha256;Length=$pair.Gate.Length}) -RosterIdentity ([pscustomobject]@{Path=$Authority.Layout.RosterPath;FileId128=$pair.Roster.FileId128;Sha256=$pair.Roster.Sha256;Length=$pair.Roster.Length}) -ControlGateLease $pair.GateLease -RosterLease $pair.RosterLease -TaskSupersessionInfrastructure $taskSupersessionInfrastructure -Bind $Bind -DbPath $DbPath)
        }
        $script:SynapseDeploymentAllocationContext=$allocation
        [void](Add-SynapseDeploymentTransactionJournalState -State rolled_back -Payload ([ordered]@{purpose='source_probe_temporary_park_completed';probe_capability_sha256=$probeCapability;candidate_sha256=[string]$candidate.Sha256;tool_count=[int]$candidate.ToolCount;tool_surface_sha256=[string]$candidate.ToolSurfaceSha256;prior_authority=$priorAuthority;prior_generation_id=[string]$afterProbe.Initial.current_generation_id;prior_daemon_pid=$priorDaemonPid;parked_outer_bootstrap_pid=[int]$parkedProof.OuterBootstrapPid;probe_task_absent=$true;unknown_objects_preserved=$true}) -Transaction $localTransaction)
        Close-SynapseAuthorityActiveControlPair -Pair $pair;$pair=$null
        Close-SynapseAuthorityControlTransitionLeases -Transitions @($rosterTransition,$gateTransition)
        # Keep the allocation context current through artifact cleanup.  The
        # remover first validates the terminal journal through these retained
        # handles, then closes them itself immediately before exact deletion.
        [void](Remove-SynapseDeploymentTransactionArtifact -Path $root -ExpectedRoot $DeploymentTransactionParent -ExpectedState rolled_back -Reason 'source_probe_park_transaction_cleanup' -Domain application)
        $script:SynapseDeploymentAllocationContext=$previousAllocation
        return $candidate
    }catch{
        $primary=$_.Exception.Message
        if($null -ne $localTransaction){
            try{
                $script:SynapseDeploymentAllocationContext=$allocation
                $durable=Read-SynapseDeploymentTransactionJournal -TransactionRoot $root -TransactionRootChain $rootChain
                if([string]$durable.State -in @('armed','candidate_ready')){
                    if([string]$durable.State -ceq 'candidate_ready'){
                        $plan=Read-SynapseCandidateProbePlanFromJournal -Descriptor $durable.Slots[-1].LexicalPayload.detail.probe_plan -ExpectedCapabilitySha256 ([string]$durable.Initial.probe_capability_sha256) -Context 'source_probe_failure_task'
                        try{[void](Remove-SynapseJournalBoundCandidateProbeTask -Plan $plan -Context 'source_probe_failure_task');Wait-SynapseBindReleased -Reason 'source_probe_failure_task' -Bind ([string]$plan.Payload.bind) -TimeoutSeconds 30}finally{if($null -ne $plan.Lease){$plan.Lease.Dispose()}}
                    }
                    if([string]$durable.Initial.prior_authority-ceq'absent'){Close-SynapseAuthorityActiveControlPair -Pair $pair;$pair=$null}
                    $validated=Assert-SynapseBrokerProbeParkInitialDescriptor -Initial $durable.Initial -TransactionRoot $root -Allocation $allocation -ExistingGateTransition $gateTransition -ExistingRosterTransition $rosterTransition
                    $restoredPid=0
                    if([string]$durable.Initial.prior_authority -ceq 'present'){
                        if($null -ne $rosterTransition){$validated.RosterTransition=$rosterTransition};if($null -ne $gateTransition){$validated.GateTransition=$gateTransition}
                        $restored=Restore-SynapseBrokerProbeParkTransaction -Validated $validated -Authority $Authority -ExpectedGenerationId ([string]$durable.Initial.current_generation_id) -HealthTimeoutSeconds $HealthTimeoutSeconds
                        $restoredPid=[int]$restored.Proof.DaemonPid;Close-SynapseAuthorityActiveControlPair -Pair $restored.Pair
                    }else{
                        $pair=Read-SynapseAuthorityActiveControlPair -Layout $Authority.Layout -ExpectedState parked -Context 'source_probe_failure_fresh_pair'
                        if([string]$pair.Gate.FileId128-ine$validated.CurrentControlGate.FileId128 -or [string]$pair.Gate.Sha256-ine$validated.CurrentControlGate.Sha256 -or [int64]$pair.Gate.Length-ne$validated.CurrentControlGate.Length -or [string]$pair.Roster.FileId128-ine$validated.CurrentRoster.FileId128 -or [string]$pair.Roster.Sha256-ine$validated.CurrentRoster.Sha256 -or [int64]$pair.Roster.Length-ne$validated.CurrentRoster.Length){Die 'SYNAPSE_BROKER_SOURCE_PROBE_FAILURE_FRESH_PAIR_DRIFT'}
                        $pair.GateLease.RequireExact('source_probe_failure_fresh_gate');$pair.RosterLease.RequireExact('source_probe_failure_fresh_roster')
                        [void](Assert-SynapseBrokerParkedNoAuthority -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -ControlGateIdentity $validated.CurrentControlGate -RosterIdentity $validated.CurrentRoster -ControlGateLease $pair.GateLease -RosterLease $pair.RosterLease -TaskSupersessionInfrastructure $taskSupersessionInfrastructure -Bind ([string]$durable.Initial.bind) -DbPath ([string]$durable.Initial.db_path))
                    }
                    $script:SynapseDeploymentAllocationContext=$allocation
                    [void](Add-SynapseDeploymentTransactionJournalState -State rolled_back -Payload ([ordered]@{purpose='source_probe_failure_restored_prior';primary_failure_sha256=(Get-SynapseSha256Hex -Text $primary);prior_authority=[string]$durable.Initial.prior_authority;prior_generation_id=[string]$durable.Initial.current_generation_id;prior_daemon_pid=$restoredPid;probe_task_absent=$true;unknown_objects_preserved=$true}) -Transaction $localTransaction)
                }
                if([string]$durable.State -eq 'rolled_back' -or [string]$localTransaction.JournalState -eq 'rolled_back'){
                    Close-SynapseAuthorityActiveControlPair -Pair $pair;$pair=$null
                    Close-SynapseAuthorityControlTransitionLeases -Transitions @($rosterTransition,$gateTransition)
                    $script:SynapseDeploymentAllocationContext=$allocation
                    [void](Remove-SynapseDeploymentTransactionArtifact -Path $root -ExpectedRoot $DeploymentTransactionParent -ExpectedState rolled_back -Reason 'source_probe_failure_transaction_cleanup' -Domain application)
                    $script:SynapseDeploymentAllocationContext=$previousAllocation
                }
            }catch{Die "SYNAPSE_BROKER_SOURCE_PROBE_FAILED_AND_RESTORE_FAILED primary=[$primary] rollback=[$($_.Exception.Message)] root=$root"}
        }
        throw
    }finally{
        Close-SynapseAuthorityActiveControlPair -Pair $pair
        Close-SynapseAuthorityControlTransitionLeases -Transitions @($rosterTransition,$gateTransition)
        if($null -ne $allocation){try{Close-SynapseDeploymentAllocationHandles -Context $allocation}catch{}}
        if($null-ne$taskSupersessionInfrastructure){Close-SynapseBrokerTaskReceiptInfrastructure -Infrastructure $taskSupersessionInfrastructure;$taskSupersessionInfrastructure=$null}
        $script:SynapseDeploymentAllocationContext=$previousAllocation
    }
}

function Recover-SynapseBrokerSourceCandidateProbeTransaction {
    param(
        [Parameter(Mandatory=$true)]$Record,
        [Parameter(Mandatory=$true)]$Authority,
        [Parameter(Mandatory=$true)][string]$ExpectedParent,
        [ValidateRange(30,900)][int]$HealthTimeoutSeconds=420
    )
    $journal=$Record.Journal;$root=Get-SynapseNormalizedDirectoryPath -Path ([string]$Record.Directory.Path)
    $validated=Assert-SynapseBrokerProbeParkInitialDescriptor -Initial $journal.Initial -TransactionRoot $root -Allocation $journal.Allocation
    [void](Assert-SynapseBrokerTaskDescriptorAuthorityCrossbind -Descriptor $journal.Initial.broker_task -BrokerIdentitySha256 ([string]$journal.Initial.broker_identity_sha256) -TaskCapabilitySha256 ([string]$journal.Initial.broker_task_capability_sha256) -Infrastructure $Authority.Infrastructure -Context "source_probe_recovery_task_$root")
    if([string]$journal.Initial.broker_identity_sha256 -ine [string]$Authority.Infrastructure.BrokerIdentitySha256 -or
       [string]$journal.Initial.broker_task_capability_sha256 -ine [string]$Authority.Infrastructure.TaskCapabilitySha256 -or
       [string]$journal.Initial.broker_task.name -cne [string]$Authority.BrokerTask.Name -or
       [string]$journal.Initial.broker_task.xml_sha256 -ine [string]$Authority.BrokerTask.XmlSha256 -or
       [string]$journal.Initial.broker_task.security_descriptor_sha256 -ine [string]$Authority.BrokerTask.SecurityDescriptorSha256){
        Die "SYNAPSE_BROKER_PROBE_PARK_RECOVERY_EPOCH_MISMATCH root=$root broker=$($journal.Initial.broker_identity_sha256) current=$($Authority.Infrastructure.BrokerIdentitySha256)"
    }
    $candidateReady=@($journal.Slots|Where-Object State -CEQ 'candidate_ready')
    if($candidateReady.Count -gt 1){Die "SYNAPSE_BROKER_PROBE_PARK_RECOVERY_TASK_PLAN_AMBIGUOUS root=$root count=$($candidateReady.Count)"}
    if($candidateReady.Count -eq 1){
        $plan=Read-SynapseCandidateProbePlanFromJournal -Descriptor $candidateReady[0].LexicalPayload.detail.probe_plan -ExpectedCapabilitySha256 ([string]$journal.Initial.probe_capability_sha256) -Context "probe_recovery_$root"
        try{
            [void](Remove-SynapseJournalBoundCandidateProbeTask -Plan $plan -Context "probe_recovery_$root")
            Wait-SynapseBindReleased -Reason 'source_probe_recovery' -Bind ([string]$plan.Payload.bind) -TimeoutSeconds 30
        }finally{if($null -ne $plan.Lease){$plan.Lease.Dispose()}}
    }elseif([string]$journal.State -ceq 'candidate_ready'){
        Die "SYNAPSE_BROKER_PROBE_PARK_RECOVERY_TASK_PLAN_MISSING root=$root"
    }
    $effectiveState=if([string]$journal.State -ceq 'cleanup_ready'){[string]$journal.Latest.detail.terminal_state}else{[string]$journal.State}
    if($effectiveState -notin @('armed','candidate_ready','rolled_back')){Die "SYNAPSE_BROKER_PROBE_PARK_RECOVERY_STATE_INVALID root=$root state=$($journal.State) effective=$effectiveState"}
    $localTransaction=[pscustomobject][ordered]@{Armed=$true;Committed=$false;Root=$root;RootChain=@($journal.RootChain);ParentRoot=$ExpectedParent;InvocationId=[string]$journal.Initial.invocation_id;JournalSequence=[int]$journal.Sequence;JournalSha256=[string]$journal.LatestRawSha256;JournalState=[string]$journal.State;StaticTransactionSha256=[string]$journal.Initial.static_transaction_sha256}
    if($effectiveState -ne 'rolled_back'){
        $restoredPid=0
        if([string]$journal.Initial.prior_authority -ceq 'present'){
            $restored=Restore-SynapseBrokerProbeParkTransaction -Validated $validated -Authority $Authority -ExpectedGenerationId ([string]$journal.Initial.current_generation_id) -HealthTimeoutSeconds $HealthTimeoutSeconds
            $restoredPid=[int]$restored.Proof.DaemonPid
            Close-SynapseAuthorityActiveControlPair -Pair $restored.Pair
        }else{
            $freshPair=Read-SynapseAuthorityActiveControlPair -Layout $Authority.Layout -ExpectedState parked -Context "probe_recovery_fresh_$root"
            try{
                [void](Assert-SynapseBrokerParkedNoAuthority -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -ControlGateIdentity $validated.CurrentControlGate -RosterIdentity $validated.CurrentRoster -ControlGateLease $freshPair.GateLease -RosterLease $freshPair.RosterLease -Bind ([string]$journal.Initial.bind) -DbPath ([string]$journal.Initial.db_path))
            }finally{Close-SynapseAuthorityActiveControlPair -Pair $freshPair}
        }
        [void](Add-SynapseDeploymentTransactionJournalState -State rolled_back -Payload ([ordered]@{purpose='source_probe_interrupted_recovery';prior_authority=[string]$journal.Initial.prior_authority;prior_generation_id=[string]$journal.Initial.current_generation_id;prior_daemon_pid=$restoredPid;probe_task_absent=$true;unknown_objects_preserved=$true}) -Transaction $localTransaction)
    }else{
        if([string]$journal.Initial.prior_authority -ceq 'present'){
            $pair=Read-SynapseAuthorityActiveControlPair -Layout $Authority.Layout -ExpectedState active -Context "probe_recovery_terminal_pair_$root"
            try{
                $generation=ConvertTo-SynapseAuthorityGenerationFromCurrentRoster -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -ControlGate $pair.Gate -Roster $pair.Roster -Context "probe_recovery_terminal_generation_$root"
                if([string]$generation.GenerationId -cne [string]$journal.Initial.current_generation_id){Die "SYNAPSE_BROKER_PROBE_PARK_RECOVERY_TERMINAL_GENERATION_MISMATCH root=$root expected=$($journal.Initial.current_generation_id) actual=$($generation.GenerationId)"}
                [void](Wait-SynapseCurrentAuthorityGenerationOperational -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -Generation $generation -ControlGateIdentity $validated.CurrentControlGate -RosterIdentity $validated.CurrentRoster -ControlGateLease $pair.GateLease -RosterLease $pair.RosterLease -HealthTimeoutSeconds $HealthTimeoutSeconds -Context "probe_recovery_terminal_$root")
            }finally{Close-SynapseAuthorityActiveControlPair -Pair $pair}
        }else{
            $freshPair=Read-SynapseAuthorityActiveControlPair -Layout $Authority.Layout -ExpectedState parked -Context "probe_recovery_terminal_fresh_$root"
            try{[void](Assert-SynapseBrokerParkedNoAuthority -Layout $Authority.Layout -Infrastructure $Authority.Infrastructure -ControlGateIdentity $validated.CurrentControlGate -RosterIdentity $validated.CurrentRoster -ControlGateLease $freshPair.GateLease -RosterLease $freshPair.RosterLease -Bind ([string]$journal.Initial.bind) -DbPath ([string]$journal.Initial.db_path))}finally{Close-SynapseAuthorityActiveControlPair -Pair $freshPair}
        }
    }
    Close-SynapseAuthorityControlTransitionLeases -Transitions @($validated.RosterTransition,$validated.GateTransition)
    Close-SynapseDeploymentAllocationHandles -Context $journal.Allocation -PayloadsOnly
    [void](Remove-SynapseDeploymentTransactionArtifact -Path $root -ExpectedRoot $ExpectedParent -ExpectedState rolled_back -Reason 'source_probe_interrupted_transaction_cleanup' -Domain application)
    Info "SYNAPSE_BROKER_SOURCE_PROBE_RECOVERED root=$root prior_authority=$($journal.Initial.prior_authority) generation=$($journal.Initial.current_generation_id)"
}

function New-SynapseRuntimeDeploymentPlan {
    param(
        [Parameter(Mandatory=$true)]$AllocationContext,
        [Parameter(Mandatory=$true)]$Mappings,
        [switch]$PreArmReadOnly
    )

    $root = Get-SynapseNormalizedDirectoryPath -Path ([string]$AllocationContext.Root)
    $rootVolume = [SynapseSetup.AtomicFileV2]::GetStableLocalVolume($root)
    if ([string]$rootVolume.FileSystemName -cne 'NTFS') {
        Die "SYNAPSE_RUNTIME_TRANSACTION_FILESYSTEM_UNSUPPORTED root=$root filesystem=$($rootVolume.FileSystemName) remediation=runtime exact-object publication requires one local stable-ID NTFS volume"
    }
    $normalizedMappings = @($Mappings | Sort-Object { [System.IO.Path]::GetFullPath([string]$_.DestinationPath) })
    $seen = New-SynapseCaseInsensitiveMap
    $records = @()
    $pendingPreLease = $null
    try {
        for ($index=0; $index -lt $normalizedMappings.Count; $index++) {
            $mapping = $normalizedMappings[$index]
            $ordinal = $index + 1
            $path = [System.IO.Path]::GetFullPath([string]$mapping.DestinationPath)
            if ($seen.ContainsKey($path)) { Die "SYNAPSE_RUNTIME_TRANSACTION_MAPPING_DUPLICATE path=$path" }
            $seen[$path] = $true
            $parent = Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $path)
            if (-not (Test-Path -LiteralPath $parent -PathType Container)) {
                Die "SYNAPSE_RUNTIME_TRANSACTION_PARENT_MISSING path=$path parent=$parent remediation=precreate and journal the exact directory before runtime planning"
            }
            $parentChain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $parent)
            $parentVolume = [SynapseSetup.AtomicFileV2]::GetStableLocalVolume($parent)
            if ([string]$parentVolume.FileSystemName -cne 'NTFS' -or [uint32]$parentVolume.VolumeSerialNumber -ne [uint32]$rootVolume.VolumeSerialNumber) {
                Die "SYNAPSE_RUNTIME_TRANSACTION_VOLUME_SPLIT path=$path parent=$parent transaction_root=$root"
            }
            $leaf = Split-Path -Leaf $path
            # Materialize and durably seal the candidate before leasing the
            # canonical preimage.  On -SkipBuild the source and destination are
            # intentionally the same object; taking a DELETE-capable preimage
            # lease first would either make the source copy sharing-violate or
            # force the copy to weaken the mutation-denying lease.
            $stageLeaf = 'runtime-stage-{0:D4}.bin' -f $ordinal
            if ($mapping.PSObject.Properties['Content']) {
                $stage = New-SynapseDeploymentAllocatedUtf8File -Context $AllocationContext -Leaf $stageLeaf -Purpose "runtime_stage_$ordinal" -Content ([string]$mapping.Content)
            } else {
                $sourcePath = [System.IO.Path]::GetFullPath([string]$mapping.SourcePath)
                $stage = New-SynapseDeploymentAllocatedFileFromSource -Context $AllocationContext -Leaf $stageLeaf -Purpose "runtime_stage_$ordinal" -SourcePath $sourcePath -ExpectedSha256 ([string]$mapping.Sha256) -ExpectedLength ([int64]$mapping.Length)
            }
            $pre = Get-SynapsePhysicalRelativeState -ParentPath $parent -ParentChain $parentChain -Leaf $leaf
            $preLease = $null
            if ($pre.Exists) {
                $preLease = if($PreArmReadOnly){
                    Open-SynapsePhysicalFileReadLease -ParentPath $parent -ParentChain $parentChain -Leaf $leaf -ExpectedFileId128 ([string]$pre.FileId128) -ExpectedSha256 ([string]$pre.Sha256) -ExpectedLength ([int64]$pre.Length) -Context "runtime_pre_read_$ordinal"
                }else{
                    Open-SynapsePhysicalFileTransitionLease -ParentPath $parent -ParentChain $parentChain -Leaf $leaf -ExpectedFileId128 ([string]$pre.FileId128) -ExpectedSha256 ([string]$pre.Sha256) -ExpectedLength ([int64]$pre.Length) -Context "runtime_pre_$ordinal"
                }
                $pendingPreLease = $preLease
            }
            $parkLeaf = if ($pre.Exists) { 'runtime-park-{0:D4}.bin' -f $ordinal } else { '' }
            $discardLeaf = 'runtime-discard-{0:D4}.bin' -f $ordinal
            if ($parkLeaf) { [void](Reserve-SynapseDeploymentArtifact -Context $AllocationContext -Leaf $parkLeaf -Kind transition_slot -Purpose "runtime_park_$ordinal" -ExpectedSha256 ([string]$pre.Sha256) -ExpectedLength ([int64]$pre.Length) -MaximumLength ([int64]$pre.Length) -AllowedFileIds128 @([string]$pre.FileId128)) }
            [void](Reserve-SynapseDeploymentArtifact -Context $AllocationContext -Leaf $discardLeaf -Kind transition_slot -Purpose "runtime_discard_$ordinal" -ExpectedSha256 ([string]$stage.Sha256) -ExpectedLength ([int64]$stage.Length) -MaximumLength ([int64]$stage.Length) -AllowedFileIds128 @([string]$stage.FileId128))
            $records += [pscustomobject][ordered]@{
                path=$path; parent=$parent; parent_chain=$parentChain; leaf=$leaf
                pre_existed=[bool]$pre.Exists; pre_file_id_128=$(if($pre.Exists){([string]$pre.FileId128).ToUpperInvariant()}else{''}); pre_sha256=$(if($pre.Exists){([string]$pre.Sha256).ToUpperInvariant()}else{''}); pre_length=$(if($pre.Exists){[int64]$pre.Length}else{-1L})
                post_file_id_128=([string]$stage.FileId128).ToUpperInvariant(); post_sha256=([string]$stage.Sha256).ToUpperInvariant(); post_length=[int64]$stage.Length
                stage_leaf=$stageLeaf; park_leaf=$parkLeaf; discard_leaf=$discardLeaf
                PreLease=$preLease; PreLeaseReadOnly=[bool]$PreArmReadOnly; PostLease=$null
            }
            $pendingPreLease = $null
        }
    } catch {
        if ($null -ne $pendingPreLease) { try { $pendingPreLease.Dispose() } catch {}; $pendingPreLease=$null }
        foreach ($record in @($records)) {
            foreach ($property in @('PreLease','PostLease')) {
                if ($null -ne $record.$property) { try { $record.$property.Dispose() } catch {}; $record.$property=$null }
            }
        }
        throw
    }
    $serializedRecords = @($records | ForEach-Object {
        [ordered]@{ path=$_.path; parent=$_.parent; parent_chain=$_.parent_chain; leaf=$_.leaf; pre_existed=$_.pre_existed; pre_file_id_128=$_.pre_file_id_128; pre_sha256=$_.pre_sha256; pre_length=$_.pre_length; post_file_id_128=$_.post_file_id_128; post_sha256=$_.post_sha256; post_length=$_.post_length; stage_leaf=$_.stage_leaf; park_leaf=$_.park_leaf; discard_leaf=$_.discard_leaf }
    })
    $descriptor = [pscustomobject][ordered]@{
        schema='synapse_runtime_file_transaction/v1'; transaction_root=$root
        volume_filesystem=[string]$rootVolume.FileSystemName; volume_serial_number=('{0:X8}' -f [uint32]$rootVolume.VolumeSerialNumber)
        records=$serializedRecords; static_plan_sha256=''
    }
    $descriptor.static_plan_sha256 = Get-SynapseRuntimeTransactionPlanSha256 -Descriptor $descriptor
    [void](Assert-SynapseRuntimeTransactionDescriptor -Descriptor $descriptor -TransactionRoot $root -ExpectedPaths @($records.path) -Allocation $AllocationContext)
    return [pscustomobject]@{ Descriptor=$descriptor; Records=$records; StaticPlanSha256=[string]$descriptor.static_plan_sha256; PostLeases=@(); PriorLeases=@() }
}

function ConvertTo-SynapseRuntimeDeploymentPlan {
    param(
        [Parameter(Mandatory=$true)]$Descriptor,
        [Parameter(Mandatory=$true)][string]$TransactionRoot,
        [string[]]$ExpectedPaths = @(),
        $Allocation
    )

    $validated = Assert-SynapseRuntimeTransactionDescriptor `
        -Descriptor $Descriptor `
        -TransactionRoot $TransactionRoot `
        -ExpectedPaths $ExpectedPaths `
        -Allocation $Allocation
    $records = @($validated.Records)
    foreach ($record in $records) {
        if ($null -eq $record.PSObject.Properties['PreLease']) { $record | Add-Member -NotePropertyName PreLease -NotePropertyValue $null }
        if ($null -eq $record.PSObject.Properties['PreLeaseReadOnly']) { $record | Add-Member -NotePropertyName PreLeaseReadOnly -NotePropertyValue $false }
        if ($null -eq $record.PSObject.Properties['PostLease']) { $record | Add-Member -NotePropertyName PostLease -NotePropertyValue $null }
    }
    return [pscustomobject]@{
        Descriptor = $Descriptor
        Records = $records
        StaticPlanSha256 = [string]$validated.StaticPlanSha256
        PostLeases = @()
        PriorLeases = @()
    }
}

function New-SynapseRuntimePreArmGuards {
    param([Parameter(Mandatory=$true)]$RuntimePlan)
    $guards = @()
    $seen = New-SynapseCaseInsensitiveMap
    foreach ($record in $RuntimePlan.Records) {
        if ($seen.ContainsKey([string]$record.parent)) { continue }
        $seen[[string]$record.parent] = $true
        $guards += [SynapseSetup.AtomicFileV2]::BeginPhysicalDirectoryChangeGuard(
            [string]$record.parent,
            (Get-SynapsePhysicalChainPaths -Chain $record.parent_chain),
            (Get-SynapsePhysicalChainFileIds -Chain $record.parent_chain),
            [string]$record.parent_chain[-1].file_id_128,
            $false)
    }
    return $guards
}

function Assert-SynapseRuntimePreArmState {
    param([Parameter(Mandatory=$true)]$RuntimePlan)
    foreach ($record in $RuntimePlan.Records) {
        $state = Get-SynapsePhysicalRelativeState -ParentPath $record.parent -ParentChain $record.parent_chain -Leaf $record.leaf
        if (-not (Test-SynapsePhysicalStateExact -State $state -ExpectedExists ([bool]$record.pre_existed) -ExpectedFileId128 ([string]$record.pre_file_id_128) -ExpectedSha256 ([string]$record.pre_sha256) -ExpectedLength ([int64]$record.pre_length))) {
            Die "SYNAPSE_RUNTIME_PREARM_PREIMAGE_DRIFT path=$($record.path) expected_file_id_128=$($record.pre_file_id_128) actual_file_id_128=$($state.FileId128)"
        }
        if ($null -ne $record.PreLease) { $record.PreLease.RequireExact("runtime_prearm_$($record.leaf)") }
        $stage = Get-SynapsePhysicalRelativeState -ParentPath $RuntimePlan.Descriptor.transaction_root -ParentChain $script:SynapseDeploymentAllocationContext.RootChain -Leaf $record.stage_leaf
        if (-not (Test-SynapsePhysicalStateExact -State $stage -ExpectedExists $true -ExpectedFileId128 ([string]$record.post_file_id_128) -ExpectedSha256 ([string]$record.post_sha256) -ExpectedLength ([int64]$record.post_length))) {
            Die "SYNAPSE_RUNTIME_PREARM_STAGE_DRIFT path=$($record.path) stage=$($record.stage_leaf)"
        }
        foreach ($futureLeaf in @([string]$record.park_leaf,[string]$record.discard_leaf) | Where-Object { $_ }) {
            $future = Get-SynapsePhysicalRelativeState -ParentPath $RuntimePlan.Descriptor.transaction_root -ParentChain $script:SynapseDeploymentAllocationContext.RootChain -Leaf $futureLeaf
            if ($future.Exists) { Die "SYNAPSE_RUNTIME_PREARM_FUTURE_COLLISION path=$($record.path) leaf=$futureLeaf" }
        }
    }
}

function Install-SynapseRuntimeTransactionGeneration {
    param([Parameter(Mandatory=$true)]$RuntimePlan)
    $root = [string]$RuntimePlan.Descriptor.transaction_root
    $rootChain = @($script:SynapseDeploymentTransaction.RootChain)
    $postLeases = @()
    foreach ($record in $RuntimePlan.Records) {
        $target = Get-SynapsePhysicalRelativeState -ParentPath $record.parent -ParentChain $record.parent_chain -Leaf $record.leaf
        if ([bool]$record.pre_existed -and (Test-SynapsePhysicalStateExact -State $target -ExpectedExists $true -ExpectedFileId128 $record.pre_file_id_128 -ExpectedSha256 $record.pre_sha256 -ExpectedLength $record.pre_length)) {
            if ($null -eq $record.PreLease) { $record.PreLease = Open-SynapsePhysicalFileTransitionLease -ParentPath $record.parent -ParentChain $record.parent_chain -Leaf $record.leaf -ExpectedFileId128 $record.pre_file_id_128 -ExpectedSha256 $record.pre_sha256 -ExpectedLength $record.pre_length -Context "runtime_install_pre_$($record.leaf)" }
            elseif([bool]$record.PreLeaseReadOnly){
                $record.PreLease=Convert-SynapsePhysicalReadLeaseToTransitionLease -ReadLease $record.PreLease -ParentPath $record.parent -ParentChain $record.parent_chain -Leaf $record.leaf -ExpectedFileId128 $record.pre_file_id_128 -ExpectedSha256 $record.pre_sha256 -ExpectedLength $record.pre_length -Context "runtime_install_pre_handoff_$($record.leaf)"
                $record.PreLeaseReadOnly=$false
            }
            [void]$record.PreLease.MoveNoReplace($root,(Get-SynapsePhysicalChainPaths -Chain $rootChain),(Get-SynapsePhysicalChainFileIds -Chain $rootChain),[string]$record.park_leaf)
            $target = Get-SynapsePhysicalRelativeState -ParentPath $record.parent -ParentChain $record.parent_chain -Leaf $record.leaf
        }
        if ($target.Exists) {
            if (-not (Test-SynapsePhysicalStateExact -State $target -ExpectedExists $true -ExpectedFileId128 $record.post_file_id_128 -ExpectedSha256 $record.post_sha256 -ExpectedLength $record.post_length)) {
                Die "SYNAPSE_RUNTIME_INSTALL_TARGET_UNKNOWN path=$($record.path) file_id_128=$($target.FileId128) sha256=$($target.Sha256)"
            }
            $transition = Open-SynapsePhysicalFileTransitionLease -ParentPath $record.parent -ParentChain $record.parent_chain -Leaf $record.leaf -ExpectedFileId128 $record.post_file_id_128 -ExpectedSha256 $record.post_sha256 -ExpectedLength $record.post_length -Context "runtime_install_existing_post_$($record.leaf)"
        } else {
            $artifact = $null
            if ($null -ne $script:SynapseDeploymentAllocationContext -and
                $script:SynapseDeploymentAllocationContext.Artifacts.ContainsKey([string]$record.stage_leaf)) {
                $artifact = $script:SynapseDeploymentAllocationContext.Artifacts[[string]$record.stage_leaf]
            }
            $transition = if ($null -ne $artifact) { $artifact.handle } else { $null }
            if ($null -eq $transition) { $transition = Open-SynapsePhysicalFileTransitionLease -ParentPath $root -ParentChain $rootChain -Leaf $record.stage_leaf -ExpectedFileId128 $record.post_file_id_128 -ExpectedSha256 $record.post_sha256 -ExpectedLength $record.post_length -Context "runtime_install_stage_$($record.leaf)" }
            [void]$transition.MoveNoReplace([string]$record.parent,(Get-SynapsePhysicalChainPaths -Chain $record.parent_chain),(Get-SynapsePhysicalChainFileIds -Chain $record.parent_chain),[string]$record.leaf)
        }
        $record.PostLease = Convert-SynapsePhysicalTransitionLeaseToReadLease -TransitionLease $transition -ParentPath $record.parent -ParentChain $record.parent_chain -Leaf $record.leaf -ExpectedFileId128 $record.post_file_id_128 -ExpectedSha256 $record.post_sha256 -ExpectedLength $record.post_length -Context "runtime_install_post_$($record.leaf)"
        if ($null -ne $script:SynapseDeploymentAllocationContext -and $script:SynapseDeploymentAllocationContext.Artifacts.ContainsKey([string]$record.stage_leaf)) { $script:SynapseDeploymentAllocationContext.Artifacts[[string]$record.stage_leaf].handle = $null }
        $postLeases += $record.PostLease
    }
    $RuntimePlan.PostLeases = $postLeases
    return $RuntimePlan
}

function Invoke-SynapseRuntimeTransactionRollback {
    param([Parameter(Mandatory=$true)]$RuntimePlan)
    $root = [string]$RuntimePlan.Descriptor.transaction_root
    $rootChain = @($script:SynapseDeploymentTransaction.RootChain)
    $priorLeases = @()
    foreach ($record in @($RuntimePlan.Records | Sort-Object path -Descending)) {
        $target = Get-SynapsePhysicalRelativeState -ParentPath $record.parent -ParentChain $record.parent_chain -Leaf $record.leaf
        if (Test-SynapsePhysicalStateExact -State $target -ExpectedExists $true -ExpectedFileId128 $record.post_file_id_128 -ExpectedSha256 $record.post_sha256 -ExpectedLength $record.post_length) {
            $transition = if ($null -ne $record.PostLease) {
                Convert-SynapsePhysicalReadLeaseToTransitionLease -ReadLease $record.PostLease -ParentPath $record.parent -ParentChain $record.parent_chain -Leaf $record.leaf -ExpectedFileId128 $record.post_file_id_128 -ExpectedSha256 $record.post_sha256 -ExpectedLength $record.post_length -Context "runtime_rollback_candidate_$($record.leaf)"
            } else {
                Open-SynapsePhysicalFileTransitionLease -ParentPath $record.parent -ParentChain $record.parent_chain -Leaf $record.leaf -ExpectedFileId128 $record.post_file_id_128 -ExpectedSha256 $record.post_sha256 -ExpectedLength $record.post_length -Context "runtime_rollback_candidate_$($record.leaf)"
            }
            [void]$transition.MoveNoReplace($root,(Get-SynapsePhysicalChainPaths -Chain $rootChain),(Get-SynapsePhysicalChainFileIds -Chain $rootChain),[string]$record.discard_leaf)
            $transition.Dispose()
            $record.PostLease = $null
            $target = Get-SynapsePhysicalRelativeState -ParentPath $record.parent -ParentChain $record.parent_chain -Leaf $record.leaf
        }
        if ([bool]$record.pre_existed) {
            if (Test-SynapsePhysicalStateExact -State $target -ExpectedExists $true -ExpectedFileId128 $record.pre_file_id_128 -ExpectedSha256 $record.pre_sha256 -ExpectedLength $record.pre_length) {
                $readLease = Open-SynapsePhysicalFileReadLease -ParentPath $record.parent -ParentChain $record.parent_chain -Leaf $record.leaf -ExpectedFileId128 $record.pre_file_id_128 -ExpectedSha256 $record.pre_sha256 -ExpectedLength $record.pre_length -Context "runtime_rollback_existing_pre_$($record.leaf)"
            } elseif (-not $target.Exists) {
                if ($null -eq $record.PreLease) { $record.PreLease = Open-SynapsePhysicalFileTransitionLease -ParentPath $root -ParentChain $rootChain -Leaf $record.park_leaf -ExpectedFileId128 $record.pre_file_id_128 -ExpectedSha256 $record.pre_sha256 -ExpectedLength $record.pre_length -Context "runtime_rollback_park_$($record.leaf)" }
                [void]$record.PreLease.MoveNoReplace([string]$record.parent,(Get-SynapsePhysicalChainPaths -Chain $record.parent_chain),(Get-SynapsePhysicalChainFileIds -Chain $record.parent_chain),[string]$record.leaf)
                $readLease = Convert-SynapsePhysicalTransitionLeaseToReadLease -TransitionLease $record.PreLease -ParentPath $record.parent -ParentChain $record.parent_chain -Leaf $record.leaf -ExpectedFileId128 $record.pre_file_id_128 -ExpectedSha256 $record.pre_sha256 -ExpectedLength $record.pre_length -Context "runtime_rollback_restore_$($record.leaf)"
                $record.PreLease = $null
            } else {
                Die "SYNAPSE_RUNTIME_ROLLBACK_PREIMAGE_COLLISION path=$($record.path) current_file_id_128=$($target.FileId128) current_sha256=$($target.Sha256) remediation=preserve the concurrent object and keep restart authority parked"
            }
            $priorLeases += $readLease
        } elseif ($target.Exists) {
            Die "SYNAPSE_RUNTIME_ROLLBACK_PRIOR_ABSENCE_COLLISION path=$($record.path) current_file_id_128=$($target.FileId128) remediation=preserve the concurrent arrival"
        }
    }
    $RuntimePlan.PriorLeases = $priorLeases
    return $RuntimePlan
}

function Complete-SynapseRuntimeCommittedGeneration {
    param([Parameter(Mandatory=$true)]$RuntimePlan)

    $root = [string]$RuntimePlan.Descriptor.transaction_root
    $rootChain = if ($null -ne $script:SynapseDeploymentTransaction -and $null -ne $script:SynapseDeploymentTransaction.RootChain) {
        @($script:SynapseDeploymentTransaction.RootChain)
    } else {
        @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $root)
    }
    foreach ($record in $RuntimePlan.Records) {
        $target = Get-SynapsePhysicalRelativeState -ParentPath $record.parent -ParentChain $record.parent_chain -Leaf $record.leaf
        if (Test-SynapsePhysicalStateExact -State $target -ExpectedExists $true -ExpectedFileId128 $record.post_file_id_128 -ExpectedSha256 $record.post_sha256 -ExpectedLength $record.post_length) {
            continue
        }
        if ($target.Exists) {
            Die "SYNAPSE_RUNTIME_COMMIT_RECOVERY_TARGET_COLLISION path=$($record.path) file_id_128=$($target.FileId128) sha256=$($target.Sha256) remediation=preserve the unexpected current object; a durable decision never grants overwrite authority over a later generation"
        }
        $stage = Get-SynapsePhysicalRelativeState -ParentPath $root -ParentChain $rootChain -Leaf $record.stage_leaf
        if (-not (Test-SynapsePhysicalStateExact -State $stage -ExpectedExists $true -ExpectedFileId128 $record.post_file_id_128 -ExpectedSha256 $record.post_sha256 -ExpectedLength $record.post_length)) {
            Die "SYNAPSE_RUNTIME_COMMIT_RECOVERY_POSTIMAGE_MISSING path=$($record.path) stage_leaf=$($record.stage_leaf) canonical_exists=$($target.Exists) remediation=preserve the transaction; the exact decided postimage is neither canonical nor staged"
        }
        $transition = Open-SynapsePhysicalFileTransitionLease -ParentPath $root -ParentChain $rootChain -Leaf $record.stage_leaf -ExpectedFileId128 $record.post_file_id_128 -ExpectedSha256 $record.post_sha256 -ExpectedLength $record.post_length -Context "runtime_commit_recovery_$($record.leaf)"
        try {
            [void]$transition.MoveNoReplace([string]$record.parent,(Get-SynapsePhysicalChainPaths -Chain $record.parent_chain),(Get-SynapsePhysicalChainFileIds -Chain $record.parent_chain),[string]$record.leaf)
            $transition.RequireExact("runtime_commit_recovery_readback_$($record.leaf)")
        } finally {
            $transition.Dispose()
        }
    }
}

function Close-SynapseRuntimeTransactionLeases {
    param([Parameter(Mandatory=$true)]$RuntimePlan)
    foreach ($record in $RuntimePlan.Records) {
        foreach ($property in @('PreLease','PostLease')) {
            if ($null -ne $record.$property) { try { $record.$property.Dispose() } catch {}; $record.$property=$null }
        }
    }
    foreach ($lease in @($RuntimePlan.PostLeases + $RuntimePlan.PriorLeases)) { if ($null -ne $lease) { try { $lease.Dispose() } catch {} } }
    $RuntimePlan.PostLeases=@(); $RuntimePlan.PriorLeases=@()
}

function New-SynapseDeploymentTransactionJournalSlotText {
    param(
        [Parameter(Mandatory=$true)][ValidateRange(1,4)][int]$Sequence,
        [Parameter(Mandatory=$true)][string]$InvocationId,
        [Parameter(Mandatory=$true)][string]$TransactionRoot,
        [AllowEmptyString()][string]$PreviousSlotSha256,
        [Parameter(Mandatory=$true)]$Payload
    )

    $payloadText = Get-SynapseCanonicalJson -Value $Payload
    $payloadBytes = [System.Text.UTF8Encoding]::new($false, $true).GetBytes($payloadText)
    $payloadSha256 = (Get-SynapseSha256Hex -Text $payloadText).ToUpperInvariant()
    $body = [ordered]@{
        schema = 'synapse_deployment_transaction_journal_slot/v2'
        sequence = $Sequence
        invocation_id = $InvocationId
        transaction_root = Get-SynapseNormalizedDirectoryPath -Path $TransactionRoot
        previous_slot_sha256 = $(if ($Sequence -eq 1) { '' } else { $PreviousSlotSha256.ToUpperInvariant() })
        payload_utf8_length = $payloadBytes.Length
        payload_sha256 = $payloadSha256
        payload_base64 = [Convert]::ToBase64String($payloadBytes)
        trailer = $script:SynapseDeploymentJournalTrailer
    }
    $selfSha256 = (Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $body)).ToUpperInvariant()
    $envelope = [ordered]@{}
    foreach ($key in $body.Keys) { $envelope[$key] = $body[$key] }
    $envelope.self_sha256 = $selfSha256
    $text = (Get-SynapseCanonicalJson -Value $envelope) + "`n"
    $byteLength = [System.Text.UTF8Encoding]::new($false, $true).GetByteCount($text)
    if ($byteLength -gt $script:SynapseDeploymentJournalMaxBytes) {
        Die "SYNAPSE_DEPLOYMENT_JOURNAL_SLOT_BOUND_WOULD_BE_EXCEEDED sequence=$Sequence bytes=$byteLength max=$($script:SynapseDeploymentJournalMaxBytes)"
    }
    if ($Sequence -gt 1 -and $byteLength -gt $script:SynapseDeploymentJournalAppendMaxBytes) {
        Die "SYNAPSE_DEPLOYMENT_JOURNAL_APPEND_SLOT_BOUND_WOULD_BE_EXCEEDED sequence=$Sequence bytes=$byteLength max=$($script:SynapseDeploymentJournalAppendMaxBytes)"
    }
    return [pscustomobject]@{ Text=$text; ByteLength=$byteLength; PayloadSha256=$payloadSha256; SelfSha256=$selfSha256 }
}

function Assert-SynapseDeploymentCleanupReadyDetail {
    param(
        [Parameter(Mandatory=$true)]$Detail,
        [Parameter(Mandatory=$true)][string]$TransactionRootFileId128,
        [Parameter(Mandatory=$true)]$Allocation,
        [Parameter(Mandatory=$true)]$CleanupSlot,
        [Parameter(Mandatory=$true)]$PredecessorSlot,
        [Parameter(Mandatory=$true)]$AllCompleteSlots,
        [Parameter(Mandatory=$true)][string]$Context
    )

    $detailProperties = @(Get-SynapseObjectPropertyNames -Object $Detail)
    $expectedDetailProperties = @(
        'terminal_state','transaction_root_file_id_128','predecessor',
        'allocation_log','journal_slots','non_journal_artifacts_remaining'
    )
    $hasCleanupAuthority=$detailProperties-ccontains'cleanup_authority'
    if($hasCleanupAuthority){$expectedDetailProperties+=,'cleanup_authority'}
    if ($detailProperties.Count -ne $expectedDetailProperties.Count -or
        @($detailProperties | Where-Object { $expectedDetailProperties -cnotcontains $_ }).Count -gt 0 -or
        [string]$Detail.terminal_state -notin @('commit_decided','rolled_back') -or
        [string]$Detail.transaction_root_file_id_128 -ine $TransactionRootFileId128 -or
        [int]$Detail.non_journal_artifacts_remaining -ne 1) {
        Die "SYNAPSE_DEPLOYMENT_CLEANUP_READY_DETAIL_INVALID context=$Context"
    }
    if($hasCleanupAuthority){
        $authority=$Detail.cleanup_authority;$authorityNames=@(Get-SynapseObjectPropertyNames -Object $authority);$authorityExpected=@('schema','predecessor_receipt','predecessor_receipt_sha256','failed_terminal_detail_sha256')
        if([string]$authority.schema-ceq'synapse_authority_failed_successor_cleanup/v1'){
            if($authorityNames.Count-ne$authorityExpected.Count -or @($authorityNames|Where-Object{$authorityExpected-cnotcontains$_}).Count-ne0 -or [string]$authority.predecessor_receipt_sha256-notmatch'^[0-9A-Fa-f]{64}$' -or [string]$authority.failed_terminal_detail_sha256-notmatch'^[0-9A-Fa-f]{64}$'){Die "SYNAPSE_DEPLOYMENT_CLEANUP_READY_AUTHORITY_INVALID context=$Context"}
            $receipt=Assert-SynapseAuthorityPredecessorReceiptDescriptor -Receipt $authority.predecessor_receipt -Context "${Context}_cleanup_authority"
            if([string]$authority.predecessor_receipt_sha256-ine(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $receipt))){Die "SYNAPSE_DEPLOYMENT_CLEANUP_READY_AUTHORITY_RECEIPT_DRIFT context=$Context"}
            if([string]$Detail.terminal_state-cne'rolled_back' -or [string]$PredecessorSlot.LexicalPayload.detail.mode-cne'predecessor_restored' -or [string]$authority.failed_terminal_detail_sha256-ine(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $PredecessorSlot.LexicalPayload.detail))){Die "SYNAPSE_DEPLOYMENT_CLEANUP_READY_AUTHORITY_TERMINAL_DRIFT context=$Context"}
        }elseif([string]$authority.schema-ceq'synapse_authority_committed_successor_predecessor_cleanup/v1'){
            $validatedAuthority=Assert-SynapseAuthorityCommittedSuccessorPredecessorCleanupAuthority -Authority $authority -Context "${Context}_committed_successor"
            if([string]$Detail.terminal_state-cne'rolled_back' -or [string]$PredecessorSlot.Payload.detail.mode-notin@('fresh_monotonic_floor','legacy_prior_unchanged','legacy_direct_recovery') -or [string]$validatedAuthority.Receipt.terminal_mode-cne[string]$PredecessorSlot.Payload.detail.mode -or (Get-SynapseCanonicalJson -Value $validatedAuthority.Receipt.authority_descriptor)-cne(Get-SynapseCanonicalJson -Value $PredecessorSlot.Payload.detail.authority_evidence)){Die "SYNAPSE_DEPLOYMENT_CLEANUP_READY_COMMITTED_SUCCESSOR_TERMINAL_DRIFT context=$Context"}
        }else{Die "SYNAPSE_DEPLOYMENT_CLEANUP_READY_AUTHORITY_SCHEMA_INVALID context=$Context schema=$($authority.schema)"}
    }

    $predecessor = $Detail.predecessor
    $predecessorProperties = @(Get-SynapseObjectPropertyNames -Object $predecessor)
    $expectedPredecessorProperties = @('sequence','state','leaf','file_id_128','sha256','length')
    if ($predecessorProperties.Count -ne $expectedPredecessorProperties.Count -or
        @($predecessorProperties | Where-Object { $expectedPredecessorProperties -cnotcontains $_ }).Count -gt 0 -or
        [int]$predecessor.sequence -ne [int]$PredecessorSlot.Sequence -or
        [string]$predecessor.state -cne [string]$PredecessorSlot.State -or
        [string]$predecessor.state -cne [string]$Detail.terminal_state -or
        [string]$predecessor.leaf -cne [string]$PredecessorSlot.Leaf -or
        [string]$predecessor.file_id_128 -ine [string]$PredecessorSlot.FileId128 -or
        [string]$predecessor.sha256 -ine [string]$PredecessorSlot.RawSha256 -or
        [int64]$predecessor.length -ne [int64]$PredecessorSlot.ByteLength) {
        Die "SYNAPSE_DEPLOYMENT_CLEANUP_READY_PREDECESSOR_INVALID context=$Context cleanup_sequence=$($CleanupSlot.Sequence)"
    }

    $allocationLog = $Detail.allocation_log
    $allocationProperties = @(Get-SynapseObjectPropertyNames -Object $allocationLog)
    $expectedAllocationProperties = @('leaf','file_id_128','sha256','length','last_record_sha256','record_count','artifact_count')
    if ($allocationProperties.Count -ne $expectedAllocationProperties.Count -or
        @($allocationProperties | Where-Object { $expectedAllocationProperties -cnotcontains $_ }).Count -gt 0 -or
        [string]$allocationLog.leaf -cne $script:SynapseDeploymentAllocationMarkerFileName -or
        [string]$allocationLog.file_id_128 -ine [string]$Allocation.State.FileId128 -or
        [string]$allocationLog.sha256 -ine [string]$Allocation.RawSha256 -or
        [int64]$allocationLog.length -ne [int64]$Allocation.ByteLength -or
        [string]$allocationLog.last_record_sha256 -ine [string]$Allocation.LastRecordSha256 -or
        [int]$allocationLog.record_count -ne [int]$Allocation.RecordCount -or
        [int]$allocationLog.artifact_count -ne [int]$Allocation.Artifacts.Count) {
        Die "SYNAPSE_DEPLOYMENT_CLEANUP_READY_ALLOCATION_INVALID context=$Context"
    }

    $declaredSlots = @($Detail.journal_slots)
    if ($declaredSlots.Count -ne $script:SynapseDeploymentJournalMaxSlots) {
        Die "SYNAPSE_DEPLOYMENT_CLEANUP_READY_SLOT_COUNT_INVALID context=$Context expected=$($script:SynapseDeploymentJournalMaxSlots) actual=$($declaredSlots.Count)"
    }
    for ($sequence=1; $sequence -le $script:SynapseDeploymentJournalMaxSlots; $sequence++) {
        $declared = $declaredSlots[$sequence-1]
        $properties = @(Get-SynapseObjectPropertyNames -Object $declared)
        $expectedProperties = @('sequence','leaf','file_id_128','maximum_length','content_state','sha256','length')
        $allocated = $Allocation.JournalSlots[$sequence-1]
        $expectedLeaf = 'transaction-{0:D4}.json' -f $sequence
        if ($properties.Count -ne $expectedProperties.Count -or
            @($properties | Where-Object { $expectedProperties -cnotcontains $_ }).Count -gt 0 -or
            [int]$declared.sequence -ne $sequence -or [string]$declared.leaf -cne $expectedLeaf -or
            [string]$declared.file_id_128 -ine [string]$allocated.file_id_128 -or
            [int64]$declared.maximum_length -ne [int64]$allocated.maximum_length) {
            Die "SYNAPSE_DEPLOYMENT_CLEANUP_READY_SLOT_IDENTITY_INVALID context=$Context sequence=$sequence"
        }
        if ($sequence -eq [int]$CleanupSlot.Sequence) {
            if ([string]$declared.content_state -cne 'cleanup_ready_self' -or
                -not [string]::IsNullOrEmpty([string]$declared.sha256) -or [int64]$declared.length -ne -1) {
                Die "SYNAPSE_DEPLOYMENT_CLEANUP_READY_SELF_SLOT_INVALID context=$Context sequence=$sequence"
            }
        } elseif ($sequence -lt [int]$CleanupSlot.Sequence) {
            $prior = @($AllCompleteSlots | Where-Object Sequence -EQ $sequence)
            if ($prior.Count -ne 1 -or [string]$declared.content_state -cne 'sealed' -or
                [string]$declared.file_id_128 -ine [string]$prior[0].FileId128 -or
                [string]$declared.sha256 -ine [string]$prior[0].RawSha256 -or
                [int64]$declared.length -ne [int64]$prior[0].ByteLength) {
                Die "SYNAPSE_DEPLOYMENT_CLEANUP_READY_PRIOR_SLOT_INVALID context=$Context sequence=$sequence"
            }
        } else {
            if ([string]$declared.content_state -cne 'empty' -or
                -not [string]::IsNullOrEmpty([string]$declared.sha256) -or [int64]$declared.length -ne 0) {
                Die "SYNAPSE_DEPLOYMENT_CLEANUP_READY_EMPTY_SLOT_INVALID context=$Context sequence=$sequence"
            }
        }
    }
    return $true
}

function Get-SynapseDeploymentAllocationMarkerDescriptor {
    param(
        [Parameter(Mandatory=$true)][string]$TransactionRoot,
        [Parameter(Mandatory=$true)]$TransactionRootChain,
        [Parameter(Mandatory=$true)][int]$OwnerPid,
        [switch]$AllowTorn
    )

    $root = Get-SynapseNormalizedDirectoryPath -Path $TransactionRoot
    $leaf = $script:SynapseDeploymentAllocationMarkerFileName
    $state = Get-SynapsePhysicalRelativeState -ParentPath $root -ParentChain $TransactionRootChain -Leaf $leaf
    if (-not $state.Exists) { return $null }
    $records = @()
    $artifacts = New-SynapseCaseInsensitiveMap
    $artifactOrder = [System.Collections.Generic.List[string]]::new()
    $allocatedFileIds = New-SynapseCaseInsensitiveMap
    $previousRecordSha256 = ''
    $invocationId = ''
    $frozen = $false
    $frozenDetail = $null
    $tornRecordText = ''
    try {
        if ([int64]$state.Length -lt 1 -or [int64]$state.Length -gt $script:SynapseDeploymentAllocationLogMaxBytes) {
            throw "allocation log length invalid length=$($state.Length) max=$($script:SynapseDeploymentAllocationLogMaxBytes)"
        }
        $activeAllocation = $script:SynapseDeploymentAllocationContext
        $raw = if ($null -ne $activeAllocation -and
            (Get-SynapseNormalizedDirectoryPath -Path ([string]$activeAllocation.Root)) -ieq $root -and
            [string]$activeAllocation.LogFileId128 -ine [string]$state.FileId128) {
            throw "active allocation log FILE_ID mismatch expected=$($activeAllocation.LogFileId128) actual=$($state.FileId128)"
        } elseif ($null -ne $activeAllocation -and
            (Get-SynapseNormalizedDirectoryPath -Path ([string]$activeAllocation.Root)) -ieq $root) {
            $activeAllocation.Log.ReadUtf8([int]$script:SynapseDeploymentAllocationLogMaxBytes)
        } else {
            Read-SynapsePhysicalRelativeUtf8Text `
                -ParentPath $root `
                -ParentChain $TransactionRootChain `
                -Leaf $leaf `
                -ExpectedFileId128 ([string]$state.FileId128) `
                -MaxBytes $script:SynapseDeploymentAllocationLogMaxBytes
        }
        if ([string]$raw.Sha256 -ine [string]$state.Sha256 -or [int64]$raw.Length -ne [int64]$state.Length) {
            throw 'allocation log same-handle readback mismatch'
        }
        $content = [string]$raw.Content
        if ($content.IndexOf("`r", [System.StringComparison]::Ordinal) -ge 0) {
            throw 'allocation log contains forbidden CR bytes'
        }
        $terminated = $content.EndsWith("`n", [System.StringComparison]::Ordinal)
        $segments = @($content.Split([char]"`n"))
        if ($terminated) {
            if ($segments.Count -lt 2 -or $segments[-1] -cne '') { throw 'allocation log LF termination invalid' }
            $lines = @($segments | Select-Object -First ($segments.Count - 1))
        } else {
            $tornRecordText = [string]$segments[-1]
            $lines = if ($segments.Count -gt 1) { @($segments | Select-Object -First ($segments.Count - 1)) } else { @() }
        }
        if ($lines.Count -lt 1 -or $lines.Count -gt $script:SynapseDeploymentAllocationMaxRecords -or @($lines | Where-Object { [string]::IsNullOrWhiteSpace($_) }).Count -gt 0) {
            throw "allocation log record count/shape invalid count=$($lines.Count)"
        }
        for ($index=0; $index -lt $lines.Count; $index++) {
            $sequence = $index + 1
            $record = $lines[$index] | ConvertFrom-Json -ErrorAction Stop
            $recordLexical = ConvertFrom-SynapseJsonPreservingStrings -Json ([string]$lines[$index]) -MaximumJsonLength $script:SynapseDeploymentJournalAppendMaxBytes
            $propertyNames = @($record.PSObject.Properties.Name)
            $expectedProperties = @('schema','sequence','invocation_id','transaction_root','transaction_root_file_id_128','previous_record_sha256','phase','detail','trailer','self_sha256')
            if ($propertyNames.Count -ne $expectedProperties.Count -or @($propertyNames | Where-Object { $expectedProperties -cnotcontains $_ }).Count -gt 0) {
                throw "allocation record property set invalid sequence=$sequence actual=$($propertyNames -join ',')"
            }
            if ([string]$record.schema -cne 'synapse_deployment_transaction_allocation_record/v2' -or
                [int]$record.sequence -ne $sequence -or
                (Get-SynapseNormalizedDirectoryPath -Path ([string]$record.transaction_root)) -ine $root -or
                [string]$record.transaction_root_file_id_128 -ine [string]$TransactionRootChain[-1].file_id_128 -or
                [string]$record.trailer -cne $script:SynapseDeploymentAllocationTrailer -or
                [string]$record.self_sha256 -notmatch '^[0-9A-Fa-f]{64}$') {
                throw "allocation record envelope invalid sequence=$sequence"
            }
            if ($sequence -eq 1) {
                $invocationId = [string]$record.invocation_id
                if ([string]::IsNullOrWhiteSpace($invocationId) -or $invocationId.Length -gt 256 -or
                    -not [string]::IsNullOrEmpty([string]$record.previous_record_sha256)) {
                    throw 'allocation initial invocation/previous hash invalid'
                }
            } elseif ([string]$record.invocation_id -cne $invocationId -or
                [string]$record.previous_record_sha256 -ine $previousRecordSha256) {
                throw "allocation record hash-chain mismatch sequence=$sequence"
            }
            $body = [ordered]@{
                schema=[string]$record.schema; sequence=[int]$record.sequence; invocation_id=[string]$record.invocation_id
                transaction_root=[string]$record.transaction_root; transaction_root_file_id_128=[string]$record.transaction_root_file_id_128
                previous_record_sha256=[string]$record.previous_record_sha256; phase=[string]$record.phase
                detail=(ConvertTo-SynapseCanonicalValue -Value $recordLexical['detail']); trailer=[string]$record.trailer
            }
            $computedSelf = (Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $body)).ToUpperInvariant()
            if ($computedSelf -ine [string]$record.self_sha256) { throw "allocation record self hash mismatch sequence=$sequence" }
            $canonicalEnvelope = [ordered]@{}
            foreach ($bodyKey in $body.Keys) { $canonicalEnvelope[$bodyKey] = $body[$bodyKey] }
            $canonicalEnvelope.self_sha256 = $computedSelf
            if ((Get-SynapseCanonicalJson -Value $canonicalEnvelope) -cne [string]$lines[$index]) {
                throw "allocation record raw canonical form mismatch sequence=$sequence"
            }
            $phase = [string]$record.phase
            $detail = $record.detail
            if ($frozen) { throw "allocation record follows frozen terminus sequence=$sequence phase=$phase" }
            if ($sequence -eq 1) {
                $detailNames = @($detail.PSObject.Properties.Name)
                $expectedDetailNames = @('schema','owner_pid','log_leaf','log_file_id_128','maximum_log_bytes','maximum_direct_entries','journal_slot_count','created_at_utc')
                if ($phase -cne 'header' -or $detailNames.Count -ne $expectedDetailNames.Count -or
                    @($detailNames | Where-Object { $expectedDetailNames -cnotcontains $_ }).Count -gt 0 -or
                    [string]$detail.schema -cne 'synapse_deployment_transaction_allocation/v2' -or
                    [int]$detail.owner_pid -ne $OwnerPid -or
                    [string]$detail.log_leaf -cne $leaf -or
                    [string]$detail.log_file_id_128 -ine [string]$state.FileId128 -or
                    [int64]$detail.maximum_log_bytes -ne [int64]$script:SynapseDeploymentAllocationLogMaxBytes -or
                    [int]$detail.maximum_direct_entries -ne [int]$script:SynapseDeploymentArtifactMaxDirectEntries -or
                    [int]$detail.journal_slot_count -ne [int]$script:SynapseDeploymentJournalMaxSlots) {
                    throw 'allocation header detail invalid'
                }
            } elseif ($phase -ceq 'reserved') {
                $detailNames = @($detail.PSObject.Properties.Name)
                $expectedDetailNames = @('leaf','kind','purpose','expected_sha256','expected_length','maximum_length','allowed_file_ids_128','transition_directory')
                $artifactLeaf = [string]$detail.leaf
                $kind = [string]$detail.kind
                $allowedIds = @($detail.allowed_file_ids_128)
                $normalizedAllowedIds = @($allowedIds | ForEach-Object { ([string]$_).ToUpperInvariant() } | Sort-Object -Unique)
                if ($detailNames.Count -ne $expectedDetailNames.Count -or @($detailNames | Where-Object { $expectedDetailNames -cnotcontains $_ }).Count -gt 0 -or
                    [string]::IsNullOrWhiteSpace($artifactLeaf) -or $artifactLeaf -notmatch '^[A-Za-z0-9._-]{1,128}$' -or
                    $artifactLeaf.EndsWith('.', [System.StringComparison]::Ordinal) -or [System.IO.Path]::GetFileName($artifactLeaf) -cne $artifactLeaf -or
                    $artifacts.ContainsKey($artifactLeaf) -or $kind -notin @('file','directory','journal_slot','progress_slot','transition_slot') -or
                    [string]::IsNullOrWhiteSpace([string]$detail.purpose) -or ([string]$detail.purpose).Length -gt 256 -or
                    @($allowedIds | Where-Object { [string]$_ -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' }).Count -gt 0 -or
                    $allowedIds.Count -gt 4 -or $normalizedAllowedIds.Count -ne $allowedIds.Count -or
                    (($normalizedAllowedIds -join ',') -cne (@($allowedIds | ForEach-Object { ([string]$_).ToUpperInvariant() }) -join ','))) {
                    throw "allocation reservation invalid sequence=$sequence leaf=$artifactLeaf kind=$kind"
                }
                $expectedSha = [string]$detail.expected_sha256
                $expectedLength = [int64]$detail.expected_length
                $maximumLength = [int64]$detail.maximum_length
                $transitionDirectory = [bool]$detail.transition_directory
                if (($expectedSha -and $expectedSha -notmatch '^[0-9A-Fa-f]{64}$') -or $maximumLength -lt 0 -or
                    ($kind -eq 'file' -and (-not $expectedSha -or $expectedLength -lt 0 -or $maximumLength -ne $expectedLength)) -or
                    ($kind -in @('journal_slot','progress_slot') -and ($expectedSha -or $expectedLength -ne -1 -or $maximumLength -lt 1 -or $transitionDirectory)) -or
                    ($kind -ne 'transition_slot' -and $transitionDirectory) -or
                    ($kind -eq 'transition_slot' -and ($allowedIds.Count -lt 1 -or
                        ($transitionDirectory -and ($expectedSha -or $expectedLength -ne -1)) -or
                        (-not $transitionDirectory -and (-not $expectedSha -or $expectedLength -lt 0 -or $maximumLength -ne $expectedLength))))) {
                    throw "allocation reservation expectation invalid sequence=$sequence leaf=$artifactLeaf kind=$kind"
                }
                $artifact = [pscustomobject][ordered]@{
                    leaf=$artifactLeaf; kind=$kind; purpose=[string]$detail.purpose
                    expected_sha256=$(if($expectedSha){$expectedSha.ToUpperInvariant()}else{''}); expected_length=$expectedLength
                    maximum_length=$maximumLength; allowed_file_ids_128=$normalizedAllowedIds
                    transition_directory=$transitionDirectory
                    status='reserved'; file_id_128=''; sealed_sha256=''; sealed_length=-1L
                }
                $artifacts[$artifactLeaf] = $artifact
        [void]$artifactOrder.Add($artifactLeaf)
                if ((1 + $artifacts.Count) -gt $script:SynapseDeploymentArtifactMaxDirectEntries) { throw 'allocation artifact count bound exceeded' }
            } elseif ($phase -ceq 'allocated') {
                $detailNames = @($detail.PSObject.Properties.Name)
                $expectedDetailNames = @('leaf','kind','file_id_128','initial_length')
                $artifactLeaf = [string]$detail.leaf
                if ($detailNames.Count -ne $expectedDetailNames.Count -or @($detailNames | Where-Object { $expectedDetailNames -cnotcontains $_ }).Count -gt 0 -or
                    -not $artifacts.ContainsKey($artifactLeaf)) { throw "allocation allocated leaf invalid sequence=$sequence leaf=$artifactLeaf" }
                $artifact = $artifacts[$artifactLeaf]
                if ([string]$artifact.status -cne 'reserved' -or [string]$artifact.kind -eq 'transition_slot' -or
                    [string]$detail.kind -cne [string]$artifact.kind -or [string]$detail.file_id_128 -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or
                    [int64]$detail.initial_length -ne 0 -or $allocatedFileIds.ContainsKey([string]$detail.file_id_128)) { throw "allocation allocated phase invalid sequence=$sequence leaf=$artifactLeaf" }
                $artifact.file_id_128 = ([string]$detail.file_id_128).ToUpperInvariant()
                $artifact.status = 'allocated'
                $allocatedFileIds[$artifact.file_id_128] = $artifactLeaf
            } elseif ($phase -ceq 'sealed') {
                $detailNames = @($detail.PSObject.Properties.Name)
                $expectedDetailNames = @('leaf','kind','file_id_128','sha256','length')
                $artifactLeaf = [string]$detail.leaf
                if ($detailNames.Count -ne $expectedDetailNames.Count -or @($detailNames | Where-Object { $expectedDetailNames -cnotcontains $_ }).Count -gt 0 -or
                    -not $artifacts.ContainsKey($artifactLeaf)) { throw "allocation sealed leaf invalid sequence=$sequence leaf=$artifactLeaf" }
                $artifact = $artifacts[$artifactLeaf]
                $sealedSha = [string]$detail.sha256
                $sealedLength = [int64]$detail.length
                if ([string]$artifact.status -cne 'allocated' -or [string]$artifact.kind -in @('journal_slot','progress_slot') -or
                    [string]$detail.kind -cne [string]$artifact.kind -or [string]$detail.file_id_128 -ine [string]$artifact.file_id_128 -or
                    ([string]$artifact.kind -eq 'file' -and ($sealedSha -ine [string]$artifact.expected_sha256 -or $sealedLength -ne [int64]$artifact.expected_length)) -or
                    ([string]$artifact.kind -eq 'directory' -and ($sealedSha -or $sealedLength -ne -1))) {
                    throw "allocation sealed phase invalid sequence=$sequence leaf=$artifactLeaf"
                }
                $artifact.sealed_sha256 = $(if($sealedSha){$sealedSha.ToUpperInvariant()}else{''})
                $artifact.sealed_length = $sealedLength
                $artifact.status = 'sealed'
            } elseif ($phase -ceq 'frozen') {
                $detailNames = @($detail.PSObject.Properties.Name)
                $expectedDetailNames = @('artifact_count','direct_entry_count','journal_slot_count','final_record_sequence','frozen_at_utc')
                $invalidArtifacts = @($artifactOrder | ForEach-Object { $artifacts[$_] } | Where-Object {
                    ([string]$_.kind -in @('file','directory') -and [string]$_.status -cne 'sealed') -or
                    ([string]$_.kind -in @('journal_slot','progress_slot') -and [string]$_.status -cne 'allocated') -or
                    ([string]$_.kind -eq 'transition_slot' -and [string]$_.status -cne 'reserved')
                })
                if ($detailNames.Count -ne $expectedDetailNames.Count -or @($detailNames | Where-Object { $expectedDetailNames -cnotcontains $_ }).Count -gt 0 -or
                    [int]$detail.artifact_count -ne $artifacts.Count -or [int]$detail.journal_slot_count -ne $script:SynapseDeploymentJournalMaxSlots -or
                    [int]$detail.final_record_sequence -ne $sequence -or [int]$detail.direct_entry_count -lt 1 -or
                    [int]$detail.direct_entry_count -gt $script:SynapseDeploymentArtifactMaxDirectEntries -or $invalidArtifacts.Count -gt 0) {
                    throw "allocation frozen detail invalid sequence=$sequence invalid_artifacts=$($invalidArtifacts.Count)"
                }
                $frozen = $true
                $frozenDetail = $detail
            } else {
                throw "allocation record phase invalid sequence=$sequence phase=$phase"
            }
            $records += [pscustomobject]@{ Sequence=$sequence; Phase=$phase; Detail=$detail; SelfSha256=$computedSelf }
            $previousRecordSha256 = $computedSelf
        }
        if (-not $frozen) {
            if (-not $AllowTorn) { throw 'allocation log has no complete frozen terminus' }
            return [pscustomobject]@{
                Valid = $false
                PrefixValid = $true
                Frozen = $false
                Root = $root
                RootChain = @($TransactionRootChain)
                FrozenDetail = $null
                Leaf = $leaf
                State = $state
                Payload = $records[0].Detail
                Records = $records
                Artifacts = $artifacts
                ArtifactOrder = @($artifactOrder)
                JournalSlots = @($artifactOrder | ForEach-Object { $artifacts[$_] } | Where-Object kind -CEQ 'journal_slot')
                ProgressSlots = @($artifactOrder | ForEach-Object { $artifacts[$_] } | Where-Object kind -CEQ 'progress_slot')
                TransactionRootFileId128 = ([string]$TransactionRootChain[-1].file_id_128).ToUpperInvariant()
                InvocationId = $invocationId
                LastRecordSha256 = $previousRecordSha256
                RecordCount = $records.Count
                RawSha256 = ([string]$raw.Sha256).ToUpperInvariant()
                ByteLength = [int64]$raw.Length
                TornRecordTextLength = [System.Text.UTF8Encoding]::new($false,$true).GetByteCount($tornRecordText)
                Error = 'allocation log contains a valid durable prefix without a frozen terminus'
            }
        }
        $journalSlots = @()
        for ($slot=1; $slot -le $script:SynapseDeploymentJournalMaxSlots; $slot++) {
            $slotLeaf = 'transaction-{0:D4}.json' -f $slot
            if (-not $artifacts.ContainsKey($slotLeaf)) { throw "allocation journal slot reservation missing leaf=$slotLeaf" }
            $slotArtifact = $artifacts[$slotLeaf]
            $expectedMaximum = if ($slot -eq 1) { [int64]$script:SynapseDeploymentJournalMaxBytes } else { [int64]$script:SynapseDeploymentJournalAppendMaxBytes }
            if ([string]$slotArtifact.kind -cne 'journal_slot' -or [string]$slotArtifact.status -cne 'allocated' -or
                [int64]$slotArtifact.maximum_length -ne $expectedMaximum) { throw "allocation journal slot contract invalid leaf=$slotLeaf" }
            $journalSlots += $slotArtifact
        }
        return [pscustomobject]@{
            Valid = $true
            PrefixValid = $true
            Frozen = $true
            Root = $root
            RootChain = @($TransactionRootChain)
            FrozenDetail = $frozenDetail
            Leaf = $leaf
            State = $state
            Payload = $records[0].Detail
            Records = $records
            Artifacts = $artifacts
            ArtifactOrder = @($artifactOrder)
            JournalSlots = $journalSlots
            ProgressSlots = @($artifactOrder | ForEach-Object { $artifacts[$_] } | Where-Object kind -CEQ 'progress_slot')
            TransactionRootFileId128 = ([string]$TransactionRootChain[-1].file_id_128).ToUpperInvariant()
            InvocationId = $invocationId
            LastRecordSha256 = $previousRecordSha256
            RecordCount = $records.Count
            RawSha256 = ([string]$raw.Sha256).ToUpperInvariant()
            ByteLength = [int64]$raw.Length
            Error = $null
        }
    } catch {
        if (-not $AllowTorn) { throw }
        return [pscustomobject]@{
            Valid = $false
            PrefixValid = $false
            Frozen = $false
            Root = $root
            RootChain = @($TransactionRootChain)
            FrozenDetail = $null
            Leaf = $leaf
            State = $state
            Payload = $null
            Records = @()
            Artifacts = (New-SynapseCaseInsensitiveMap)
            ArtifactOrder = @()
            JournalSlots = @()
            ProgressSlots = @()
            TransactionRootFileId128 = ([string]$TransactionRootChain[-1].file_id_128).ToUpperInvariant()
            InvocationId = ''
            LastRecordSha256 = ''
            RecordCount = 0
            RawSha256 = ([string]$state.Sha256).ToUpperInvariant()
            ByteLength = [int64]$state.Length
            TornRecordTextLength = 0
            Error = $_.Exception.Message
        }
    }
}

function Read-SynapseDeploymentTransactionJournal {
    param(
        [Parameter(Mandatory=$true)][string]$TransactionRoot,
        $TransactionRootChain
    )

    Ensure-SynapseAtomicFileType
    $root = Get-SynapseNormalizedDirectoryPath -Path $TransactionRoot
    $chain = if ($null -eq $TransactionRootChain) { @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $root) } else { @($TransactionRootChain) }
    [void](Assert-SynapsePhysicalDirectoryChainDescriptor -Chain $chain -ExpectedPath $root -Context 'deployment_journal_root')
    $rootOwnerMatch = [regex]::Match((Split-Path -Leaf $root), '^deployment-\d{8}T\d{9}Z-(\d+)$')
    if (-not $rootOwnerMatch.Success) { Die "SYNAPSE_DEPLOYMENT_JOURNAL_ROOT_LEAF_INVALID root=$root" }
    $allocation = Get-SynapseDeploymentAllocationMarkerDescriptor `
        -TransactionRoot $root `
        -TransactionRootChain $chain `
        -OwnerPid ([int]$rootOwnerMatch.Groups[1].Value)
    if ($null -eq $allocation -or -not $allocation.Valid) {
        Die "SYNAPSE_DEPLOYMENT_JOURNAL_ALLOCATION_LOG_MISSING root=$root"
    }
    $entries = @(Get-SynapsePhysicalDirectoryEntriesBounded -Path $root -Chain $chain -MaximumEntries $script:SynapseDeploymentArtifactMaxDirectEntries -Context 'deployment_journal_slots')
    $slotItems = @{}
    foreach ($entry in @($entries | Where-Object { [string]$_.Name -match '^transaction-\d{4}\.json$' })) {
        $slotNameMatch = [regex]::Match([string]$entry.Name, '^transaction-(\d{4})\.json$')
        $sequence = if ($slotNameMatch.Success) { [int]$slotNameMatch.Groups[1].Value } else { 0 }
        if (-not $slotNameMatch.Success -or $sequence -lt 1 -or $sequence -gt $script:SynapseDeploymentJournalMaxSlots -or
            $slotItems.ContainsKey($sequence) -or [bool]$entry.IsDirectory -or
            ([uint32]$entry.Attributes -band [uint32][System.IO.FileAttributes]::ReparsePoint)) {
            Die "SYNAPSE_DEPLOYMENT_JOURNAL_SLOT_TYPE_OR_NAME_INVALID root=$root leaf=$($entry.Name) sequence=$sequence"
        }
        $declaredSlot = $allocation.JournalSlots[$sequence-1]
        if ([string]$entry.FileId128 -ine [string]$declaredSlot.file_id_128) {
            Die "SYNAPSE_DEPLOYMENT_JOURNAL_SLOT_FILE_ID_MISMATCH root=$root leaf=$($entry.Name) expected=$($declaredSlot.file_id_128) actual=$($entry.FileId128)"
        }
        $slotItems[$sequence] = $entry
    }
    if ($slotItems.Count -ne $script:SynapseDeploymentJournalMaxSlots) {
        Die "SYNAPSE_DEPLOYMENT_JOURNAL_PREALLOCATED_SLOT_SET_INVALID root=$root expected=$($script:SynapseDeploymentJournalMaxSlots) actual=$($slotItems.Count)"
    }
    $slots = @()
    $previousRawSha256 = ''
    $invocationId = ''
    $aggregateBytes = 0
    $tornTail = $null
    $emptySuffix = @()
    for ($sequence = 1; $sequence -le $script:SynapseDeploymentJournalMaxSlots; $sequence++) {
        $leaf = 'transaction-{0:D4}.json' -f $sequence
        $state = Get-SynapsePhysicalRelativeState -ParentPath $root -ParentChain $chain -Leaf $leaf
        $declaredSlot = $allocation.JournalSlots[$sequence-1]
        $maximumLength = [int64]$declaredSlot.maximum_length
        if (-not $state.Exists -or [string]$state.FileId128 -ine [string]$declaredSlot.file_id_128 -or
            [int64]$state.Length -gt $maximumLength) {
            Die "SYNAPSE_DEPLOYMENT_JOURNAL_SLOT_PHYSICAL_INVALID path=$(Join-Path $root $leaf) exists=$($state.Exists) length=$($state.Length)"
        }
        if ([int64]$state.Length -eq 0) {
            $emptySuffix += [pscustomobject]@{ Sequence=$sequence; Leaf=$leaf; FileId128=[string]$state.FileId128; Length=0L }
            continue
        }
        if ($emptySuffix.Count -gt 0) {
            Die "SYNAPSE_DEPLOYMENT_JOURNAL_NONEMPTY_AFTER_EMPTY_SUFFIX root=$root sequence=$sequence first_empty=$($emptySuffix[0].Sequence)"
        }
        $slotError = $null
        $raw = $null
        $envelope = $null
        $payload = $null
        try {
            $activeAllocation = $script:SynapseDeploymentAllocationContext
            if ($null -ne $activeAllocation -and
                (Get-SynapseNormalizedDirectoryPath -Path ([string]$activeAllocation.Root)) -ieq $root -and
                $activeAllocation.JournalSlotHandles.ContainsKey($sequence)) {
                $activeSlot = $activeAllocation.JournalSlotHandles[$sequence]
                if ([string]$activeSlot.FileId128 -ine [string]$state.FileId128) { throw 'active journal slot FILE_ID mismatch' }
                $raw = $activeSlot.ReadUtf8([int]$maximumLength)
            } else {
                $raw = Read-SynapsePhysicalRelativeUtf8Text -ParentPath $root -ParentChain $chain -Leaf $leaf -ExpectedFileId128 ([string]$state.FileId128) -MaxBytes $maximumLength
            }
            $aggregateBytes += [int]$raw.Length
            if ($aggregateBytes -gt $script:SynapseDeploymentJournalMaxBytes) { throw "aggregate journal bytes $aggregateBytes exceed $($script:SynapseDeploymentJournalMaxBytes)" }
            $envelope = [string]$raw.Content | ConvertFrom-Json -ErrorAction Stop
            $envelopeProperties = @($envelope.PSObject.Properties.Name)
            $expectedEnvelopeProperties = @('schema','sequence','invocation_id','transaction_root','previous_slot_sha256','payload_utf8_length','payload_sha256','payload_base64','trailer','self_sha256')
            if ($envelopeProperties.Count -ne $expectedEnvelopeProperties.Count -or @($envelopeProperties | Where-Object { $expectedEnvelopeProperties -cnotcontains $_ }).Count -gt 0 -or
                [string]$envelope.schema -cne 'synapse_deployment_transaction_journal_slot/v2' -or
                [int]$envelope.sequence -ne $sequence -or
                (Get-SynapseNormalizedDirectoryPath -Path ([string]$envelope.transaction_root)) -ine $root -or
                [string]$envelope.trailer -cne $script:SynapseDeploymentJournalTrailer -or
                [string]$envelope.payload_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or
                [string]$envelope.self_sha256 -notmatch '^[0-9A-Fa-f]{64}$') { throw 'slot envelope identity invalid' }
            if ($slots.Count -eq 0) {
                if ($sequence -ne 1) { throw 'complete journal prefix did not begin at slot one' }
                if (-not [string]::IsNullOrWhiteSpace([string]$envelope.previous_slot_sha256)) { throw 'initial previous hash was nonempty' }
                $invocationId = [string]$envelope.invocation_id
                if ([string]::IsNullOrWhiteSpace($invocationId)) { throw 'invocation id missing' }
            } elseif ([string]$envelope.invocation_id -cne $invocationId -or [string]$envelope.previous_slot_sha256 -ine $previousRawSha256) {
                throw 'slot invocation/previous hash chain mismatch'
            }
            $payloadBytes = [Convert]::FromBase64String([string]$envelope.payload_base64)
            if ($payloadBytes.Length -ne [int]$envelope.payload_utf8_length) { throw 'payload length mismatch' }
            $payloadText = [System.Text.UTF8Encoding]::new($false, $true).GetString($payloadBytes)
            if ((Get-SynapseSha256Hex -Text $payloadText) -ine [string]$envelope.payload_sha256) { throw 'payload hash mismatch' }
            $body = [ordered]@{ schema=[string]$envelope.schema; sequence=[int]$envelope.sequence; invocation_id=[string]$envelope.invocation_id; transaction_root=[string]$envelope.transaction_root; previous_slot_sha256=[string]$envelope.previous_slot_sha256; payload_utf8_length=[int]$envelope.payload_utf8_length; payload_sha256=[string]$envelope.payload_sha256; payload_base64=[string]$envelope.payload_base64; trailer=[string]$envelope.trailer }
            if ((Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $body)) -ine [string]$envelope.self_sha256) { throw 'slot self hash mismatch' }
            $canonicalEnvelope = [ordered]@{}
            foreach ($bodyKey in $body.Keys) { $canonicalEnvelope[$bodyKey] = $body[$bodyKey] }
            $canonicalEnvelope.self_sha256 = ([string]$envelope.self_sha256).ToUpperInvariant()
            if (((Get-SynapseCanonicalJson -Value $canonicalEnvelope) + "`n") -cne [string]$raw.Content) {
                throw 'slot raw canonical form mismatch'
            }
            $payload = $payloadText | ConvertFrom-Json -ErrorAction Stop
            $payloadLexical = ConvertFrom-SynapseJsonPreservingStrings -Json $payloadText -MaximumJsonLength $maximumLength
            if ((Get-SynapseCanonicalJson -Value (ConvertTo-SynapseCanonicalValue -Value $payloadLexical)) -cne $payloadText) { throw 'payload raw canonical form mismatch' }
            if ([string]$payload.state -notin @('armed','candidate_ready','commit_decided','rolled_back','cleanup_ready')) { throw "payload state invalid: $($payload.state)" }
            if ($sequence -eq 1 -and [string]$payload.state -ne 'armed') { throw 'initial payload was not armed' }
            $rawSha256 = (Get-SynapseSha256Hex -Text ([string]$raw.Content)).ToUpperInvariant()
            if ($rawSha256 -ine [string]$raw.Sha256) { throw 'same-handle raw hash mismatch' }
            $slots += [pscustomobject]@{ Sequence=$sequence; Leaf=$leaf; State=[string]$payload.state; Payload=$payload; LexicalPayload=$payloadLexical; RawSha256=$rawSha256; FileId128=[string]$state.FileId128; ByteLength=[int]$raw.Length }
            $previousRawSha256 = $rawSha256
        } catch {
            $slotError = $_.Exception.Message
        }
        if ($slotError) {
            $laterNonEmpty = @()
            for ($laterSequence=$sequence+1; $laterSequence -le $script:SynapseDeploymentJournalMaxSlots; $laterSequence++) {
                $laterState = Get-SynapsePhysicalRelativeState -ParentPath $root -ParentChain $chain -Leaf ('transaction-{0:D4}.json' -f $laterSequence)
                $laterDeclared = $allocation.JournalSlots[$laterSequence-1]
                if (-not $laterState.Exists -or [string]$laterState.FileId128 -ine [string]$laterDeclared.file_id_128) {
                    Die "SYNAPSE_DEPLOYMENT_JOURNAL_SUFFIX_SLOT_IDENTITY_INVALID root=$root sequence=$laterSequence"
                }
                if ([int64]$laterState.Length -ne 0) { $laterNonEmpty += $laterSequence }
            }
            if ($sequence -eq ($slots.Count + 1) -and $laterNonEmpty.Count -eq 0) {
                $tornTail = [pscustomobject]@{ Sequence=$sequence; Leaf=$leaf; FileId128=[string]$state.FileId128; Sha256=[string]$state.Sha256; Length=[int64]$state.Length; Error=$slotError }
                break
            }
            Die "SYNAPSE_DEPLOYMENT_JOURNAL_SLOT_INVALID root=$root sequence=$sequence error=$slotError later_nonempty=$($laterNonEmpty -join ',') remediation=preserve the non-tail or gapped journal"
        }
    }
    if ($slots.Count -lt 1) {
        if ($null -eq $tornTail -and $emptySuffix.Count -eq $script:SynapseDeploymentJournalMaxSlots) { return $null }
        Die "SYNAPSE_DEPLOYMENT_JOURNAL_NO_COMPLETE_SLOT root=$root"
    }
    for ($index=1; $index -lt $slots.Count; $index++) {
        $from=[string]$slots[$index-1].State; $to=[string]$slots[$index].State
        $valid=(($from -eq 'armed' -and $to -in @('candidate_ready','rolled_back')) -or ($from -eq 'candidate_ready' -and $to -in @('commit_decided','rolled_back')) -or ($from -in @('commit_decided','rolled_back') -and $to -eq 'cleanup_ready'))
        if(-not $valid){Die "SYNAPSE_DEPLOYMENT_JOURNAL_STATE_CHAIN_INVALID root=$root sequence=$($slots[$index].Sequence) from=$from to=$to"}
        if ($to -eq 'cleanup_ready' -and [string]$slots[$index].Payload.detail.terminal_state -cne $from) {
            Die "SYNAPSE_DEPLOYMENT_JOURNAL_CLEANUP_PREDECESSOR_MISMATCH root=$root sequence=$($slots[$index].Sequence) predecessor=$from declared_terminal=$($slots[$index].Payload.detail.terminal_state)"
        }
    }
    $initial = $slots[0].Payload
    $initialStatic = $slots[0].LexicalPayload
    $declaredStaticSha256 = [string]$initialStatic.static_transaction_sha256
    if ($initialStatic -isnot [System.Collections.IDictionary] -or
        $declaredStaticSha256 -notmatch '^[0-9A-Fa-f]{64}$') {
        Die "SYNAPSE_DEPLOYMENT_JOURNAL_STATIC_IDENTITY_MISSING root=$root"
    }
    [void]$initialStatic.Remove('static_transaction_sha256')
    $computedStaticSha256 = (Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $initialStatic)).ToUpperInvariant()
    if ($computedStaticSha256 -ine $declaredStaticSha256) {
        Die "SYNAPSE_DEPLOYMENT_JOURNAL_STATIC_IDENTITY_MISMATCH root=$root expected=$declaredStaticSha256 actual=$computedStaticSha256"
    }
    if ($null -ne $slots[0].LexicalPayload.predecessor_authority_receipt) {
        $initial.predecessor_authority_receipt = $slots[0].LexicalPayload.predecessor_authority_receipt
    }
    $initialSchema = [string]$initial.schema
    $initialKind = if ($null -ne $initial.PSObject.Properties['transaction_kind']) { [string]$initial.transaction_kind } else { '' }
    $supportedInitial = (
        ($initialSchema -ceq 'synapse_deployment_transaction/v3' -and [string]::IsNullOrEmpty($initialKind)) -or
        ($initialSchema -ceq 'synapse_broker_adoption_transaction/v3' -and $initialKind -ceq 'synapse_broker_adoption/v3') -or
        ($initialSchema -ceq 'synapse_broker_adoption_transaction/v4' -and $initialKind -ceq 'synapse_broker_adoption/v4') -or
        ($initialSchema -ceq 'synapse_deployment_transaction/v4' -and $initialKind -ceq 'synapse_broker_application/v1') -or
        ($initialSchema -ceq 'synapse_broker_probe_park_transaction/v1' -and $initialKind -ceq 'synapse_broker_probe_park/v1') -or
        ($initialSchema -ceq 'synapse_broker_task_create_transaction/v1' -and $initialKind -ceq 'synapse_broker_task_create/v1') -or
        ($initialSchema -ceq 'synapse_broker_operator_stop_transaction/v1' -and $initialKind -ceq 'synapse_broker_operator_stop/v1'))
    if (-not $supportedInitial -or
        [string]$initial.invocation_id -cne $invocationId -or
        (Get-SynapseNormalizedDirectoryPath -Path ([string]$initial.transaction_root)) -ine $root) {
        Die "SYNAPSE_DEPLOYMENT_JOURNAL_INITIAL_PAYLOAD_INVALID root=$root schema=$initialSchema kind=$initialKind invocation=$($initial.invocation_id)"
    }
    foreach ($candidateReadySlot in @($slots | Where-Object State -CEQ 'candidate_ready')) {
        if ($initialSchema -ceq 'synapse_deployment_transaction/v3') {
            if ([bool]$candidateReadySlot.Payload.detail.profile_generation_prepared -ne $true -or
                [bool]$candidateReadySlot.Payload.detail.profile_generation_published -ne $false) {
                Die "SYNAPSE_DEPLOYMENT_JOURNAL_CANDIDATE_READY_PROFILE_PHASE_INVALID root=$root sequence=$($candidateReadySlot.Sequence) prepared=$($candidateReadySlot.Payload.detail.profile_generation_prepared) published=$($candidateReadySlot.Payload.detail.profile_generation_published)"
            }
        } elseif ($initialSchema -in @('synapse_broker_adoption_transaction/v3','synapse_broker_adoption_transaction/v4')) {
            $detail=$candidateReadySlot.Payload.detail
            $detailNames=@($detail.PSObject.Properties.Name)
            $rehearsalValid=if([string]$initial.prior_authority -ceq 'legacy'){
                $expectedDetailNames=@('prior_authority','prior_production_rehearsed','legacy_denial_probe_receipts','broker_identity_sha256','generation_id','daemon_pid','outer_bootstrap_pid','broker_pid','inner_bootstrap_pid','supervisor_pid','tool_count','tool_surface_sha256','outer_job_memory_limit_bytes')
                $detailNames.Count -eq $expectedDetailNames.Count -and @($detailNames|Where-Object{$expectedDetailNames -cnotcontains $_}).Count -eq 0 -and
                [bool]$detail.prior_production_rehearsed -eq $true -and [string]$detail.prior_authority -ceq 'legacy' -and
                @(Assert-SynapseLegacyDenialProbeReceipts -Receipts @($detail.legacy_denial_probe_receipts) -Plans @($initial.legacy_denial_probe_plans) -Context "journal_candidate_$root").Count -eq 3 -and
                [string]$detail.generation_id -ceq [string]$initial.prior_generation.generation_id -and [int]$detail.daemon_pid -gt 0 -and
                [int]$detail.outer_bootstrap_pid -gt 0 -and [int]$detail.broker_pid -gt 0 -and [int]$detail.inner_bootstrap_pid -gt 0 -and [int]$detail.supervisor_pid -gt 0 -and
                [int]$detail.tool_count -eq [int]$initial.prior_generation.expected_tool_count -and [string]$detail.tool_surface_sha256 -ieq [string]$initial.prior_generation.expected_tool_surface_sha256 -and
                [uint64]$detail.outer_job_memory_limit_bytes -eq [uint64]6699999232
            }else{
                $expectedDetailNames=@('prior_authority','prior_production_rehearsed','legacy_denial_probe_receipts','rehearsal','broker_identity_sha256','task_instance_count','target_process_count','listener_count','broker_process_count','outer_bootstrap_pid','broker_pid','outer_job_memory_limit_bytes')
                $detailNames.Count -eq $expectedDetailNames.Count -and @($detailNames|Where-Object{$expectedDetailNames -cnotcontains $_}).Count -eq 0 -and
                [bool]$detail.prior_production_rehearsed -eq $false -and [string]$detail.prior_authority -ceq 'absent' -and [string]$detail.rehearsal -ceq 'not_applicable_fresh_host' -and
                @($detail.legacy_denial_probe_receipts).Count -eq 0 -and
                [int]$detail.task_instance_count -in @(0,1) -and [int]$detail.target_process_count -eq 0 -and [int]$detail.listener_count -eq 0 -and [int]$detail.broker_process_count -eq 1 -and
                [int]$detail.outer_bootstrap_pid -gt 0 -and [int]$detail.broker_pid -gt 0 -and [uint64]$detail.outer_job_memory_limit_bytes -eq [uint64]6699999232
            }
            if (-not $rehearsalValid -or [string]$detail.broker_identity_sha256 -ine [string]$initial.broker_identity_sha256) {
                Die "SYNAPSE_BROKER_ADOPTION_JOURNAL_REHEARSAL_INVALID root=$root sequence=$($candidateReadySlot.Sequence) rehearsed=$($detail.prior_production_rehearsed)"
            }
        } elseif ($initialSchema -ceq 'synapse_deployment_transaction/v4') {
            $detail=$candidateReadySlot.Payload.detail
            $detailNames=@($detail.PSObject.Properties.Name)
            $expectedDetailNames=@('authority_model','installed_probe_complete','persistent_candidate_authority_active','candidate_generation_id','candidate_sha256','tool_count','tool_surface_sha256','profile_root_file_id_128','profile_manifest_sha256','parked_outer_bootstrap_pid','probe_task_absent')
            if ($detailNames.Count -ne $expectedDetailNames.Count -or @($detailNames|Where-Object{$expectedDetailNames -cnotcontains $_}).Count -gt 0 -or
                [string]$detail.authority_model -cne 'immutable_broker/v1' -or
                [bool]$detail.installed_probe_complete -ne $true -or
                [bool]$detail.persistent_candidate_authority_active -ne $false -or
                [bool]$detail.probe_task_absent -ne $true -or
                [string]$detail.candidate_generation_id -cne [string]$initial.candidate_generation.generation_id -or
                [string]$detail.candidate_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or
                [int]$detail.tool_count -ne [int]$initial.candidate_generation.expected_tool_count -or
                [string]$detail.tool_surface_sha256 -ine [string]$initial.candidate_generation.expected_tool_surface_sha256 -or
                [string]$detail.profile_root_file_id_128 -ine [string]$initial.profile_transaction.profiles_root_file_id_128 -or
                [string]$detail.profile_manifest_sha256 -ine [string]$initial.profile_transaction.manifest_entry.post_sha256 -or
                [int]$detail.parked_outer_bootstrap_pid -le 0) {
                Die "SYNAPSE_BROKER_APPLICATION_JOURNAL_CANDIDATE_READY_INVALID root=$root sequence=$($candidateReadySlot.Sequence) installed_probe=$($candidateReadySlot.Payload.detail.installed_probe_complete) persistent_active=$($candidateReadySlot.Payload.detail.persistent_candidate_authority_active)"
            }
        } elseif ($initialSchema -ceq 'synapse_broker_probe_park_transaction/v1') {
            if ([string]$candidateReadySlot.Payload.detail.purpose -cne 'source_probe_task_create_authorized' -or
                [string]$candidateReadySlot.Payload.detail.probe_capability_sha256 -ine [string]$initial.probe_capability_sha256 -or
                [string]$candidateReadySlot.Payload.detail.prior_authority -cne [string]$initial.prior_authority -or
                [bool]$candidateReadySlot.Payload.detail.parked_authority_proven -ne $true -or
                $null -eq $candidateReadySlot.Payload.detail.probe_plan) {
                Die "SYNAPSE_BROKER_PROBE_PARK_TASK_AUTHORITY_INVALID root=$root sequence=$($candidateReadySlot.Sequence)"
            }
        } elseif ($initialSchema -ceq 'synapse_broker_task_create_transaction/v1') {
            $detail=$candidateReadySlot.Payload.detail
            $detailNames=@($detail.PSObject.Properties.Name)
            $expectedDetailNames=@('task_created_or_adopted','task_capability_sha256','task_name','submitted_xml_sha256','submitted_semantic_sha256','observed_xml','observed_xml_sha256','observed_xml_length','observed_semantic_contract','observed_semantic_sha256','observed_security_descriptor','observed_security_descriptor_sha256','observed_canonical_security_descriptor','observed_canonical_security_descriptor_sha256','observed_state','instance_count','instances','instances_sha256','task_receipt_forward_only')
            $observedXml=[string]$detail.observed_xml
            $observedXmlLength=[System.Text.UTF8Encoding]::new($false,$true).GetByteCount($observedXml)
            $observedSemanticText=Get-SynapseCanonicalJson -Value (ConvertTo-SynapseCanonicalValue -Value $detail.observed_semantic_contract)
            $observedCanonicalSddl=Get-SynapseAuthorityTaskCanonicalSecurityDescriptor -SecurityDescriptor ([string]$detail.observed_security_descriptor) -Context "broker_task_observation_sddl_$root"
            $instanceEvidence=@($detail.instances)
            $instanceContractInvalid=@($instanceEvidence|Where-Object{
                $instanceNames=@($_.PSObject.Properties.Name)
                $instanceNames.Count -ne 4 -or @($instanceNames|Where-Object{@('instance_guid','engine_pid','state','current_action') -cnotcontains $_}).Count -gt 0 -or
                [string]$_.instance_guid -notmatch '^[{]?[0-9A-Fa-f-]{36}[}]?$' -or [int]$_.engine_pid -lt 0
            })
            $instanceEvidenceJson=if($instanceEvidence.Count -eq 0){'[]'}else{Get-SynapseCanonicalJson -Value $instanceEvidence}
            if($detailNames.Count -ne $expectedDetailNames.Count -or @($detailNames|Where-Object{$expectedDetailNames -cnotcontains $_}).Count -gt 0 -or
               [bool]$detail.task_created_or_adopted -ne $true -or [bool]$detail.task_receipt_forward_only -ne $true -or
               [string]$detail.task_capability_sha256 -ine [string]$initial.task_capability_sha256 -or [string]$detail.task_name -cne [string]$initial.task.name -or
               [string]$detail.submitted_xml_sha256 -ine [string]$initial.task.submitted_xml_sha256 -or [string]$detail.submitted_semantic_sha256 -ine [string]$initial.task.submitted_semantic_sha256 -or
               [string]$detail.observed_xml_sha256 -ine (Get-SynapseSha256Hex -Text $observedXml) -or [int64]$detail.observed_xml_length -ne [int64]$observedXmlLength -or $observedXmlLength -lt 1 -or
               [string]$detail.observed_semantic_sha256 -ine (Get-SynapseSha256Hex -Text $observedSemanticText) -or [string]$detail.observed_semantic_sha256 -ine [string]$initial.task.submitted_semantic_sha256 -or
               $observedSemanticText -cne (Get-SynapseCanonicalJson -Value (ConvertTo-SynapseCanonicalValue -Value $initial.task.submitted_semantic_contract)) -or
               [string]$detail.observed_security_descriptor_sha256 -ine (Get-SynapseSha256Hex -Text ([string]$detail.observed_security_descriptor)) -or
               [string]$detail.observed_canonical_security_descriptor -cne $observedCanonicalSddl -or
               [string]$detail.observed_canonical_security_descriptor_sha256 -ine (Get-SynapseSha256Hex -Text $observedCanonicalSddl) -or
               [int]$detail.instance_count -lt 0 -or [int]$detail.instance_count -gt 1 -or [int]$detail.instance_count -ne $instanceEvidence.Count -or
               $instanceContractInvalid.Count -gt 0 -or @($instanceEvidence.instance_guid|Sort-Object -Unique).Count -ne $instanceEvidence.Count -or
               [string]$detail.instances_sha256 -ine (Get-SynapseSha256Hex -Text $instanceEvidenceJson)){
                Die "SYNAPSE_BROKER_TASK_CREATE_OBSERVATION_INVALID root=$root sequence=$($candidateReadySlot.Sequence) task=$($detail.task_name)"
            }
        } elseif ($initialSchema -ceq 'synapse_broker_operator_stop_transaction/v1') {
            $detail=$candidateReadySlot.Payload.detail
            $detailNames=@($detail.PSObject.Properties.Name)
            $expectedDetailNames=@('operator_stopped','broker_identity_sha256','generation_id','parked_authority_proven','daemon_count','listener_count')
            $recoveredFromArmed=$null-ne$detail.PSObject.Properties['recovered_from_armed_cut']
            if($recoveredFromArmed){$expectedDetailNames+=@('recovered_from_armed_cut')}
            if($detailNames.Count -ne $expectedDetailNames.Count -or @($detailNames|Where-Object{$expectedDetailNames -cnotcontains $_}).Count -gt 0 -or
               [bool]$detail.operator_stopped -ne $true -or [string]$detail.broker_identity_sha256 -ine [string]$initial.broker_identity_sha256 -or
               [string]$detail.generation_id -cne [string]$initial.generation_id -or [bool]$detail.parked_authority_proven -ne $true -or
               [int]$detail.daemon_count -ne 0 -or [int]$detail.listener_count -ne 0 -or ($recoveredFromArmed-and[bool]$detail.recovered_from_armed_cut-ne$true)){
                Die "SYNAPSE_BROKER_OPERATOR_STOP_JOURNAL_STOPPED_INVALID root=$root sequence=$($candidateReadySlot.Sequence)"
            }
        } else {
            Die "SYNAPSE_DEPLOYMENT_JOURNAL_CANDIDATE_READY_SCHEMA_INVALID root=$root sequence=$($candidateReadySlot.Sequence) schema=$initialSchema"
        }
    }
    foreach($commitSlot in @($slots|Where-Object State -CEQ 'commit_decided')){
        if($initialSchema -in @('synapse_broker_adoption_transaction/v3','synapse_broker_adoption_transaction/v4')){
            $detail=$commitSlot.Payload.detail
            $detailNames=@($detail.PSObject.Properties.Name)
            $expectedDetailNames=@('broker_adoption_decided','prior_authority','rehearsal','legacy_denial_probes_complete','broker_identity_sha256','authority_epoch','control_nonce','legacy_gate_file_id_128','legacy_gate_sha256','legacy_gate_length','legacy_denial_stub_file_id_128','legacy_denial_stub_sha256','legacy_denial_stub_length','legacy_authority_floor','control_gate_file_id_128','control_gate_sha256','control_gate_length','roster_file_id_128','roster_sha256','roster_length','prior_generation_id','daemon_pid','legacy_task_unchanged','candidate_ready_slot_file_id_128','candidate_ready_slot_sha256','candidate_ready_slot_length')
            if($initialSchema-ceq'synapse_broker_adoption_transaction/v4'){$expectedDetailNames+=@('predecessor_superseded','predecessor_receipt_sha256')}
            $candidateReady=@($slots|Where-Object{[int]$_.Sequence -lt [int]$commitSlot.Sequence -and [string]$_.State -ceq 'candidate_ready'}|Select-Object -Last 1)
            $rosterTransition=if([string]$initial.prior_authority -ceq 'legacy'){$initial.active_roster_transition}else{$initial.parked_roster_transition}
            $expectedRehearsal=if([string]$initial.prior_authority -ceq 'legacy'){'production_prior_verified'}else{'not_applicable_fresh_host'}
            $expectedGeneration=if([string]$initial.prior_authority -ceq 'legacy'){[string]$initial.prior_generation.generation_id}else{''}
            # One historical producer stored the journal aggregate returned by
            # Add-SynapseDeploymentTransactionJournalState as though it were
            # the appended slot.  The resulting projection is exactly
            # empty/empty/zero.  Recovery may derive that redundant triplet
            # only from the immediately preceding, already authenticated
            # candidate_ready slot; no other missing or partial projection is
            # admitted and new producers always seal the exact slot values.
            $candidateReadyProjectionMissing=($candidateReady.Count-eq1 -and [int]$commitSlot.Sequence-eq([int]$candidateReady[0].Sequence+1) -and [string]::IsNullOrEmpty([string]$detail.candidate_ready_slot_file_id_128) -and [string]::IsNullOrEmpty([string]$detail.candidate_ready_slot_sha256) -and [int64]$detail.candidate_ready_slot_length-eq0)
            $candidateReadyProjectionExact=($candidateReady.Count-eq1 -and [string]$detail.candidate_ready_slot_file_id_128-ieq[string]$candidateReady[0].FileId128 -and [string]$detail.candidate_ready_slot_sha256-ieq[string]$candidateReady[0].RawSha256 -and [int64]$detail.candidate_ready_slot_length-eq[int64]$candidateReady[0].ByteLength)
            if($candidateReady.Count -ne 1 -or $detailNames.Count -ne $expectedDetailNames.Count -or @($detailNames|Where-Object{$expectedDetailNames -cnotcontains $_}).Count -gt 0 -or
               [bool]$detail.broker_adoption_decided -ne $true -or [string]$detail.prior_authority -cne [string]$initial.prior_authority -or [string]$detail.rehearsal -cne $expectedRehearsal -or
               ($initialSchema-ceq'synapse_broker_adoption_transaction/v4' -and ([bool]$detail.predecessor_superseded-ne($null-ne$initial.predecessor_authority_receipt) -or [string]$detail.predecessor_receipt_sha256-ine$(if($null-ne$initial.predecessor_authority_receipt){Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $initial.predecessor_authority_receipt)}else{''}))) -or
               [string]$detail.broker_identity_sha256 -ine [string]$initial.broker_identity_sha256 -or [int64]$detail.authority_epoch -ne [int64]$initial.authority_epoch -or [string]$detail.control_nonce -ine [string]$initial.control_nonce -or
               [int]$detail.legacy_authority_floor -ne 1 -or [bool]$detail.legacy_task_unchanged -ne $true -or [string]$detail.prior_generation_id -cne $expectedGeneration -or
               [bool]$detail.legacy_denial_probes_complete -ne ([string]$initial.prior_authority -ceq 'legacy') -or
               [string]$detail.legacy_gate_file_id_128 -ine [string]$initial.legacy_gate_transition.post_file_id_128 -or [string]$detail.legacy_gate_sha256 -ine [string]$initial.legacy_gate_transition.post_sha256 -or [int64]$detail.legacy_gate_length -ne [int64]$initial.legacy_gate_transition.post_length -or
               [string]$detail.legacy_denial_stub_file_id_128 -ine [string]$initial.legacy_denial_stub_transition.post_file_id_128 -or [string]$detail.legacy_denial_stub_sha256 -ine [string]$initial.legacy_denial_stub_transition.post_sha256 -or [int64]$detail.legacy_denial_stub_length -ne [int64]$initial.legacy_denial_stub_transition.post_length -or
               [string]$detail.control_gate_file_id_128 -ine [string]$initial.active_control_gate_transition.post_file_id_128 -or [string]$detail.control_gate_sha256 -ine [string]$initial.active_control_gate_transition.post_sha256 -or [int64]$detail.control_gate_length -ne [int64]$initial.active_control_gate_transition.post_length -or
               [string]$detail.roster_file_id_128 -ine [string]$rosterTransition.post_file_id_128 -or [string]$detail.roster_sha256 -ine [string]$rosterTransition.post_sha256 -or [int64]$detail.roster_length -ne [int64]$rosterTransition.post_length -or
               (-not($candidateReadyProjectionExact-or$candidateReadyProjectionMissing)) -or
               ([string]$initial.prior_authority -ceq 'legacy' -and [int]$detail.daemon_pid -le 0) -or ([string]$initial.prior_authority -ceq 'absent' -and [int]$detail.daemon_pid -ne 0)){
                 Die "SYNAPSE_BROKER_ADOPTION_JOURNAL_DECISION_INVALID root=$root sequence=$($commitSlot.Sequence) prior=$($detail.prior_authority) floor=$($detail.legacy_authority_floor)"
            }
            if($candidateReadyProjectionMissing){
                Warn "SYNAPSE_BROKER_ADOPTION_CANDIDATE_SLOT_PROJECTION_MIGRATION root=$root commit_sequence=$($commitSlot.Sequence) candidate_sequence=$($candidateReady[0].Sequence) candidate_file_id_128=$($candidateReady[0].FileId128) candidate_sha256=$($candidateReady[0].RawSha256) candidate_length=$($candidateReady[0].ByteLength)"
            }
        }elseif($initialSchema -ceq 'synapse_deployment_transaction/v4'){
            $detail=$commitSlot.Payload.detail
            $detailNames=@($detail.PSObject.Properties.Name)
            $expectedDetailNames=@('authority_model','candidate_generation_id','runtime_generation_sha256','profile_generation_sha256','installed_probe_sha256','tool_count','tool_surface_sha256','persistent_candidate_authority_active','forward_only')
            $candidateReady=@($slots|Where-Object{[int]$_.Sequence -lt [int]$commitSlot.Sequence -and [string]$_.State -ceq 'candidate_ready'}|Select-Object -Last 1)
            if($candidateReady.Count -ne 1 -or $detailNames.Count -ne $expectedDetailNames.Count -or @($detailNames|Where-Object{$expectedDetailNames -cnotcontains $_}).Count -gt 0 -or
               [string]$detail.authority_model -cne 'immutable_broker/v1' -or [bool]$detail.persistent_candidate_authority_active -ne $false -or [bool]$detail.forward_only -ne $true -or
               [string]$detail.candidate_generation_id -cne [string]$initial.candidate_generation.generation_id -or
               [string]$detail.runtime_generation_sha256 -ine [string]$initial.candidate_generation.runtime_generation_sha256 -or
               [string]$detail.profile_generation_sha256 -ine [string]$initial.candidate_generation.profile_generation_sha256 -or
               [string]$detail.installed_probe_sha256 -ine [string]$candidateReady[0].Payload.detail.candidate_sha256 -or
               [int]$detail.tool_count -ne [int]$candidateReady[0].Payload.detail.tool_count -or
               [string]$detail.tool_surface_sha256 -ine [string]$candidateReady[0].Payload.detail.tool_surface_sha256){
                Die "SYNAPSE_BROKER_APPLICATION_JOURNAL_COMMIT_DECISION_INVALID root=$root sequence=$($commitSlot.Sequence) generation=$($detail.candidate_generation_id)"
            }
        }elseif($initialSchema -ceq 'synapse_broker_task_create_transaction/v1'){
            $detail=$commitSlot.Payload.detail
            $detailNames=@($detail.PSObject.Properties.Name)
            $expectedDetailNames=@('broker_task_create_decided','task_capability_sha256','task_name','broker_identity_sha256','observed_xml_sha256','observed_security_descriptor_sha256','candidate_ready_slot_file_id_128','candidate_ready_slot_sha256','task_namespace_monotonic','forward_only')
            $hasPredecessorRetired=$null-ne$detail.PSObject.Properties['predecessor_retired'];$hasPredecessorSha=$null-ne$detail.PSObject.Properties['predecessor_receipt_sha256']
            if($hasPredecessorRetired-and$hasPredecessorSha){$expectedDetailNames+=@('predecessor_retired','predecessor_receipt_sha256')}
            $candidateReady=@($slots|Where-Object{[int]$_.Sequence -lt [int]$commitSlot.Sequence -and [string]$_.State -ceq 'candidate_ready'}|Select-Object -Last 1)
            $expectedPredecessorSha=if([int64]$initial.task_epoch-gt1-and$null-ne$initial.predecessor_receipt){(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $initial.predecessor_receipt)).ToUpperInvariant()}else{''}
            if($candidateReady.Count -ne 1 -or $detailNames.Count -ne $expectedDetailNames.Count -or @($detailNames|Where-Object{$expectedDetailNames -cnotcontains $_}).Count -gt 0 -or
               [bool]$detail.broker_task_create_decided -ne $true -or [bool]$detail.task_namespace_monotonic -ne $true -or [bool]$detail.forward_only -ne $true -or
               $hasPredecessorRetired-ne$hasPredecessorSha -or ([int64]$initial.task_epoch-gt1-and-not$hasPredecessorRetired) -or
               # predecessor_retired records the OUTCOME of the rotation, not
               # the epoch. Remove-SynapseBrokerTaskRotationPredecessorExact
               # deliberately returns false and logs
               # SYNAPSE_BROKER_TASK_ROTATION_PREDECESSOR_RETAINED_AUTHORITY
               # when the active roster still names the predecessor: that task
               # still owns the live daemon generation and must NOT be deleted.
               # Demanding predecessor_retired -eq (task_epoch -gt 1) made that
               # supported outcome unvalidatable, so every rotation over a
               # still-active predecessor died here AFTER registering the
               # successor task, stranding a second broker task. Both outcomes
               # are legal at task_epoch>1; only a first epoch must be false.
               ($hasPredecessorRetired-and(([int64]$initial.task_epoch-le1-and[bool]$detail.predecessor_retired-ne$false) -or [string]$detail.predecessor_receipt_sha256 -ine $expectedPredecessorSha)) -or
               [string]$detail.task_capability_sha256 -ine [string]$initial.task_capability_sha256 -or [string]$detail.task_name -cne [string]$initial.task.name -or
               [string]$detail.broker_identity_sha256 -ine [string]$initial.broker_identity_sha256 -or
               [string]$detail.observed_xml_sha256 -ine [string]$candidateReady[0].Payload.detail.observed_xml_sha256 -or
               [string]$detail.observed_security_descriptor_sha256 -ine [string]$candidateReady[0].Payload.detail.observed_security_descriptor_sha256 -or
               [string]$detail.candidate_ready_slot_file_id_128 -ine [string]$candidateReady[0].FileId128 -or
               [string]$detail.candidate_ready_slot_sha256 -ine [string]$candidateReady[0].RawSha256){
                Die "SYNAPSE_BROKER_TASK_CREATE_DECISION_INVALID root=$root sequence=$($commitSlot.Sequence) task=$($detail.task_name)"
            }
        }elseif($initialSchema -ceq 'synapse_broker_operator_stop_transaction/v1'){
            $detail=$commitSlot.Payload.detail
            $detailNames=@($detail.PSObject.Properties.Name)
            $decisionNames=@('operator_start_decided','operator_remove_decided')
            $presentDecisionNames=@($decisionNames|Where-Object{$null -ne $detail.PSObject.Properties[$_]})
            $expectedDetailNames=@($presentDecisionNames[0],'broker_identity_sha256','generation_id','forward_only')
            if($presentDecisionNames.Count -ne 1 -or $detailNames.Count -ne $expectedDetailNames.Count -or @($detailNames|Where-Object{$expectedDetailNames -cnotcontains $_}).Count -gt 0 -or
               [bool]$detail.($presentDecisionNames[0]) -ne $true -or [bool]$detail.forward_only -ne $true -or
               [string]$detail.broker_identity_sha256 -ine [string]$initial.broker_identity_sha256 -or [string]$detail.generation_id -cne [string]$initial.generation_id){
                Die "SYNAPSE_BROKER_OPERATOR_DECISION_INVALID root=$root sequence=$($commitSlot.Sequence) decisions=$($presentDecisionNames -join ',')"
            }
        }
    }
    $initialAllocation = $initial.allocation_marker
    if ($null -eq $allocation -or
        [string]$allocation.InvocationId -cne $invocationId -or
        [string]$initialAllocation.Leaf -cne $script:SynapseDeploymentAllocationMarkerFileName -or
        [string]$initialAllocation.FileId128 -ine [string]$allocation.State.FileId128 -or
        [string]$initialAllocation.Sha256 -ine [string]$allocation.RawSha256 -or
        [int64]$initialAllocation.Length -ne [int64]$allocation.ByteLength -or
        [string]$initialAllocation.LastRecordSha256 -ine [string]$allocation.LastRecordSha256 -or
        [int]$initialAllocation.RecordCount -ne [int]$allocation.RecordCount -or
        [int]$initialAllocation.ArtifactCount -ne [int]$allocation.Artifacts.Count) {
        Die "SYNAPSE_DEPLOYMENT_JOURNAL_ALLOCATION_MARKER_MISMATCH root=$root expected_file_id_128=$($initialAllocation.FileId128) actual_file_id_128=$(if($allocation){$allocation.State.FileId128}else{'<missing>'})"
    }
    foreach ($slot in @($slots | Select-Object -Skip 1)) {
        if ([string]$slot.Payload.static_transaction_sha256 -ine $declaredStaticSha256) {
            Die "SYNAPSE_DEPLOYMENT_JOURNAL_APPEND_STATIC_IDENTITY_MISMATCH root=$root sequence=$($slot.Sequence) expected=$declaredStaticSha256 actual=$($slot.Payload.static_transaction_sha256)"
        }
    }
    foreach($rollbackSlot in @($slots|Where-Object State -CEQ 'rolled_back')){
        if($initialSchema -in @('synapse_broker_adoption_transaction/v3','synapse_broker_adoption_transaction/v4')){
            [void](Assert-SynapseAuthorityRollbackTerminalDetail -Detail $rollbackSlot.LexicalPayload.detail -Initial $initial -Allocation $allocation -Context "journal_rollback_$root`_$($rollbackSlot.Sequence)")
        }
    }
    foreach ($cleanupSlot in @($slots | Where-Object State -CEQ 'cleanup_ready')) {
        $predecessorSlot = @($slots | Where-Object Sequence -EQ ([int]$cleanupSlot.Sequence - 1))
        if ($predecessorSlot.Count -ne 1) {
            Die "SYNAPSE_DEPLOYMENT_CLEANUP_READY_PREDECESSOR_MISSING root=$root sequence=$($cleanupSlot.Sequence)"
        }
        [void](Assert-SynapseDeploymentCleanupReadyDetail `
            -Detail $cleanupSlot.LexicalPayload.detail `
            -TransactionRootFileId128 ([string]$chain[-1].file_id_128) `
            -Allocation $allocation `
            -CleanupSlot $cleanupSlot `
            -PredecessorSlot $predecessorSlot[0] `
            -AllCompleteSlots $slots `
            -Context "full_journal_sequence_$($cleanupSlot.Sequence)")
    }
    return [pscustomobject]@{ Root=$root; RootChain=$chain; Slots=$slots; Initial=$initial; Latest=$slots[-1].Payload; State=[string]$slots[-1].State; Sequence=[int]$slots[-1].Sequence; LatestRawSha256=[string]$slots[-1].RawSha256; AggregateBytes=$aggregateBytes; TornTail=$tornTail; EmptySuffix=$emptySuffix; Allocation=$allocation }
}

function Write-SynapseDeploymentTransactionJournalSlot {
    param(
        [Parameter(Mandatory=$true)][string]$TransactionRoot,
        [Parameter(Mandatory=$true)]$TransactionRootChain,
        [Parameter(Mandatory=$true)][ValidateRange(1,4)][int]$Sequence,
        [Parameter(Mandatory=$true)][string]$InvocationId,
        [AllowEmptyString()][string]$PreviousSlotSha256,
        [Parameter(Mandatory=$true)]$Payload
    )

    $slot = New-SynapseDeploymentTransactionJournalSlotText -Sequence $Sequence -InvocationId $InvocationId -TransactionRoot $TransactionRoot -PreviousSlotSha256 $PreviousSlotSha256 -Payload $Payload
    $allocation = Get-SynapseDeploymentAllocationMarkerDescriptor -TransactionRoot $TransactionRoot -TransactionRootChain $TransactionRootChain -OwnerPid ([int]([regex]::Match((Split-Path -Leaf $TransactionRoot), '^deployment-\d{8}T\d{9}Z-(\d+)$').Groups[1].Value))
    if ($null -eq $allocation -or -not $allocation.Valid -or [string]$allocation.InvocationId -cne $InvocationId) {
        Die "SYNAPSE_DEPLOYMENT_JOURNAL_WRITE_ALLOCATION_AUTHORITY_INVALID root=$TransactionRoot sequence=$Sequence"
    }
    $existing = Read-SynapseDeploymentTransactionJournal -TransactionRoot $TransactionRoot -TransactionRootChain $TransactionRootChain
    $existingBytes = if ($null -eq $existing) { 0 } else { [int]$existing.AggregateBytes }
    if (($existingBytes + $slot.ByteLength) -gt $script:SynapseDeploymentJournalMaxBytes) {
        Die "SYNAPSE_DEPLOYMENT_JOURNAL_AGGREGATE_BOUND_WOULD_BE_EXCEEDED root=$TransactionRoot existing_bytes=$existingBytes next_bytes=$($slot.ByteLength) max=$($script:SynapseDeploymentJournalMaxBytes)"
    }
    if (($Sequence -eq 1 -and $null -ne $existing) -or
        ($Sequence -gt 1 -and ($null -eq $existing -or [int]$existing.Sequence -ne ($Sequence - 1)))) {
        Die "SYNAPSE_DEPLOYMENT_JOURNAL_WRITE_SEQUENCE_BASE_INVALID root=$TransactionRoot sequence=$Sequence existing_sequence=$(if($existing){$existing.Sequence}else{0})"
    }
    $leaf = 'transaction-{0:D4}.json' -f $Sequence
    $declaredSlot = $allocation.JournalSlots[$Sequence-1]
    if ([string]$declaredSlot.leaf -cne $leaf -or [string]$declaredSlot.file_id_128 -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$') {
        Die "SYNAPSE_DEPLOYMENT_JOURNAL_WRITE_SLOT_DECLARATION_INVALID root=$TransactionRoot sequence=$Sequence leaf=$leaf"
    }
    $slotHandle = $null
    $disposeSlotHandle = $false
    $activeAllocation = $script:SynapseDeploymentAllocationContext
    if ($null -ne $activeAllocation -and
        (Get-SynapseNormalizedDirectoryPath -Path ([string]$activeAllocation.Root)) -ieq (Get-SynapseNormalizedDirectoryPath -Path $TransactionRoot) -and
        $activeAllocation.JournalSlotHandles.ContainsKey($Sequence)) {
        $slotHandle = $activeAllocation.JournalSlotHandles[$Sequence]
        if ([string]$slotHandle.FileId128 -ine [string]$declaredSlot.file_id_128) {
            Die "SYNAPSE_DEPLOYMENT_JOURNAL_WRITE_RETAINED_SLOT_ID_MISMATCH root=$TransactionRoot sequence=$Sequence expected=$($declaredSlot.file_id_128) actual=$($slotHandle.FileId128)"
        }
    } else {
        $slotHandle = Open-SynapsePhysicalAllocatedFileForFill `
            -ParentPath $TransactionRoot `
            -ParentChain $TransactionRootChain `
            -Leaf $leaf `
            -ExpectedFileId128 ([string]$declaredSlot.file_id_128) `
            -MaximumLength ([int64]$declaredSlot.maximum_length) `
            -Context "deployment_journal_slot_$Sequence"
        $disposeSlotHandle = $true
    }
    try {
        $slotRawSha256 = (Get-SynapseSha256Hex -Text $slot.Text).ToUpperInvariant()
        $write = $slotHandle.FillUtf8($slot.Text, $slotRawSha256, [int64]$slot.ByteLength)
    } finally {
        if ($disposeSlotHandle -and $null -ne $slotHandle) { $slotHandle.Dispose() }
    }
    $readback = Read-SynapseDeploymentTransactionJournal -TransactionRoot $TransactionRoot -TransactionRootChain $TransactionRootChain
    if ($readback.Sequence -ne $Sequence -or [string]$readback.LatestRawSha256 -ine [string]$write.Sha256) {
        Die "SYNAPSE_DEPLOYMENT_JOURNAL_SLOT_READBACK_MISMATCH root=$TransactionRoot sequence=$Sequence expected_sha256=$($write.Sha256) actual_sha256=$($readback.LatestRawSha256)"
    }
    return $readback
}

function Get-SynapseDeploymentCleanupTailDescriptor {
    param([Parameter(Mandatory=$true)][string]$TransactionRoot)

    $root = Get-SynapseNormalizedDirectoryPath -Path $TransactionRoot
    $chain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $root)
    $entries = @(Get-SynapsePhysicalDirectoryEntriesBounded -Path $root -Chain $chain -MaximumEntries $script:SynapseDeploymentArtifactMaxDirectEntries -Context 'deployment_cleanup_tail_entries')
    if ($entries.Count -lt 1 -or @($entries | Where-Object {
        [bool]$_.IsDirectory -or
        ([uint32]$_.Attributes -band [uint32][System.IO.FileAttributes]::ReparsePoint) -or
        ([string]$_.Name -cne $script:SynapseDeploymentAllocationMarkerFileName -and [string]$_.Name -notmatch '^transaction-\d{4}\.json$')
    }).Count -gt 0) { return $null }
    try {
        $cleanupCandidates = @()
        foreach ($entry in @($entries | Where-Object { [string]$_.Name -match '^transaction-\d{4}\.json$' -and [int64]$_.Length -gt 0 })) {
            $match = [regex]::Match([string]$entry.Name, '^transaction-(\d{4})\.json$')
            $sequence = [int]$match.Groups[1].Value
            if ($sequence -lt 1 -or $sequence -gt $script:SynapseDeploymentJournalMaxSlots) { return $null }
            $maximumLength = if ($sequence -eq 1) { [int]$script:SynapseDeploymentJournalMaxBytes } else { [int]$script:SynapseDeploymentJournalAppendMaxBytes }
            $raw = Read-SynapsePhysicalRelativeUtf8Text -ParentPath $root -ParentChain $chain -Leaf ([string]$entry.Name) -ExpectedFileId128 ([string]$entry.FileId128) -MaxBytes $maximumLength
            $envelope = [string]$raw.Content | ConvertFrom-Json -ErrorAction Stop
            $properties = @($envelope.PSObject.Properties.Name)
            $expectedProperties = @('schema','sequence','invocation_id','transaction_root','previous_slot_sha256','payload_utf8_length','payload_sha256','payload_base64','trailer','self_sha256')
            if ($properties.Count -ne $expectedProperties.Count -or @($properties | Where-Object { $expectedProperties -cnotcontains $_ }).Count -gt 0 -or
                [string]$envelope.schema -cne 'synapse_deployment_transaction_journal_slot/v2' -or [int]$envelope.sequence -ne $sequence -or
                (Get-SynapseNormalizedDirectoryPath -Path ([string]$envelope.transaction_root)) -ine $root -or
                [string]$envelope.trailer -cne $script:SynapseDeploymentJournalTrailer) { continue }
            $body = [ordered]@{ schema=[string]$envelope.schema; sequence=[int]$envelope.sequence; invocation_id=[string]$envelope.invocation_id; transaction_root=[string]$envelope.transaction_root; previous_slot_sha256=[string]$envelope.previous_slot_sha256; payload_utf8_length=[int]$envelope.payload_utf8_length; payload_sha256=[string]$envelope.payload_sha256; payload_base64=[string]$envelope.payload_base64; trailer=[string]$envelope.trailer }
            $computedSelf = (Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $body)).ToUpperInvariant()
            $canonical = [ordered]@{}; foreach ($key in $body.Keys) { $canonical[$key]=$body[$key] }; $canonical.self_sha256=$computedSelf
            if ($computedSelf -ine [string]$envelope.self_sha256 -or ((Get-SynapseCanonicalJson -Value $canonical)+"`n") -cne [string]$raw.Content) { continue }
            $payloadBytes = [Convert]::FromBase64String([string]$envelope.payload_base64)
            if ($payloadBytes.Length -ne [int]$envelope.payload_utf8_length) { continue }
            $payloadText = [System.Text.UTF8Encoding]::new($false,$true).GetString($payloadBytes)
            if ((Get-SynapseSha256Hex -Text $payloadText) -ine [string]$envelope.payload_sha256) { continue }
            $payload = ConvertFrom-SynapseJsonPreservingStrings -Json $payloadText -MaximumJsonLength $maximumLength
            if ((Get-SynapseCanonicalJson -Value (ConvertTo-SynapseCanonicalValue -Value $payload)) -cne $payloadText) { continue }
            if ([string]$payload.state -ceq 'cleanup_ready' -and [string]$payload.static_transaction_sha256 -match '^[0-9A-Fa-f]{64}$') {
                $cleanupCandidates += [pscustomobject]@{ Sequence=$sequence; Leaf=[string]$entry.Name; State='cleanup_ready'; Payload=$payload; RawSha256=([string]$raw.Sha256).ToUpperInvariant(); FileId128=[string]$entry.FileId128; ByteLength=[int64]$raw.Length }
            }
        }
        if ($cleanupCandidates.Count -ne 1) { return $null }
        $cleanup = $cleanupCandidates[0]
        $detail = $cleanup.Payload.detail
        $detailProperties = @($detail.PSObject.Properties.Name)
        $expectedDetailProperties = @('terminal_state','transaction_root_file_id_128','predecessor','allocation_log','journal_slots','non_journal_artifacts_remaining')
        $cleanupAuthority = $null
        $hasCleanupAuthority = $null -ne $detail.PSObject.Properties['cleanup_authority']
        if ($hasCleanupAuthority) { $expectedDetailProperties += ,'cleanup_authority' }
        if ($detailProperties.Count -ne $expectedDetailProperties.Count -or @($detailProperties | Where-Object { $expectedDetailProperties -cnotcontains $_ }).Count -gt 0 -or
            [string]$detail.terminal_state -notin @('commit_decided','rolled_back') -or
            [string]$detail.transaction_root_file_id_128 -ine [string]$chain[-1].file_id_128 -or [int]$detail.non_journal_artifacts_remaining -ne 1) { return $null }
        if ($hasCleanupAuthority) {
            $authority = $detail.cleanup_authority
            $authorityProperties = @($authority.PSObject.Properties.Name)
            if([string]$authority.schema-ceq'synapse_authority_failed_successor_cleanup/v1'){
                $expectedAuthorityProperties = @('schema','predecessor_receipt','predecessor_receipt_sha256','failed_terminal_detail_sha256')
                if ([string]$detail.terminal_state -cne 'rolled_back' -or $authorityProperties.Count -ne $expectedAuthorityProperties.Count -or @($authorityProperties | Where-Object { $expectedAuthorityProperties -cnotcontains $_ }).Count -gt 0 -or [string]$authority.predecessor_receipt_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [string]$authority.failed_terminal_detail_sha256 -notmatch '^[0-9A-Fa-f]{64}$') { return $null }
                $receipt = Assert-SynapseAuthorityPredecessorReceiptDescriptor -Receipt $authority.predecessor_receipt -Context "cleanup_tail_$root"
                if ([string]$authority.predecessor_receipt_sha256 -ine (Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $receipt))) { return $null }
            }elseif([string]$authority.schema-ceq'synapse_authority_committed_successor_predecessor_cleanup/v1'){
                if([string]$detail.terminal_state-cne'rolled_back'){return $null}
                $validatedAuthority=Assert-SynapseAuthorityCommittedSuccessorPredecessorCleanupAuthority -Authority $authority -Context "cleanup_tail_committed_$root"
                $receipt=$validatedAuthority.Receipt
                if([string]$receipt.journal.transaction_root_file_id_128-ine[string]$chain[-1].file_id_128){return $null}
            }else{return $null}
            $cleanupAuthority = ConvertTo-SynapseCanonicalValue -Value $authority
        }
        $predecessor = $detail.predecessor
        $predecessorProperties = @($predecessor.PSObject.Properties.Name)
        if ($predecessorProperties.Count -ne 6 -or @($predecessorProperties | Where-Object { @('sequence','state','leaf','file_id_128','sha256','length') -cnotcontains $_ }).Count -gt 0 -or
            [int]$predecessor.sequence -ne ([int]$cleanup.Sequence-1) -or [string]$predecessor.state -cne [string]$detail.terminal_state -or
            [string]$predecessor.leaf -cne ('transaction-{0:D4}.json' -f [int]$predecessor.sequence) -or
            [string]$predecessor.file_id_128 -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or [string]$predecessor.sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [int64]$predecessor.length -lt 1) { return $null }
        $allocationLog = $detail.allocation_log
        if (@($allocationLog.PSObject.Properties.Name).Count -ne 7 -or @($allocationLog.PSObject.Properties.Name | Where-Object { @('leaf','file_id_128','sha256','length','last_record_sha256','record_count','artifact_count') -cnotcontains $_ }).Count -gt 0 -or
            [string]$allocationLog.leaf -cne $script:SynapseDeploymentAllocationMarkerFileName -or [string]$allocationLog.file_id_128 -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or
            [string]$allocationLog.sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [int64]$allocationLog.length -lt 1 -or [int64]$allocationLog.length -gt $script:SynapseDeploymentAllocationLogMaxBytes -or
            [string]$allocationLog.last_record_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [int]$allocationLog.record_count -lt 1 -or [int]$allocationLog.record_count -gt $script:SynapseDeploymentAllocationMaxRecords -or
            [int]$allocationLog.artifact_count -lt $script:SynapseDeploymentJournalMaxSlots -or [int]$allocationLog.artifact_count -ge $script:SynapseDeploymentArtifactMaxDirectEntries) { return $null }
        $roster = @($detail.journal_slots)
        if ($roster.Count -ne $script:SynapseDeploymentJournalMaxSlots) { return $null }
        $rosterByLeaf = New-SynapseCaseInsensitiveMap
        for ($sequence=1; $sequence -le $script:SynapseDeploymentJournalMaxSlots; $sequence++) {
            $slot = $roster[$sequence-1]
            $slotProperties = @($slot.PSObject.Properties.Name)
            $expectedLeaf = 'transaction-{0:D4}.json' -f $sequence
            $expectedMaximum = if ($sequence -eq 1) { [int64]$script:SynapseDeploymentJournalMaxBytes } else { [int64]$script:SynapseDeploymentJournalAppendMaxBytes }
            if ($slotProperties.Count -ne 7 -or @($slotProperties | Where-Object { @('sequence','leaf','file_id_128','maximum_length','content_state','sha256','length') -cnotcontains $_ }).Count -gt 0 -or
                [int]$slot.sequence -ne $sequence -or [string]$slot.leaf -cne $expectedLeaf -or [string]$slot.file_id_128 -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$' -or [int64]$slot.maximum_length -ne $expectedMaximum) { return $null }
            if ($sequence -eq [int]$cleanup.Sequence) {
                if ([string]$slot.content_state -cne 'cleanup_ready_self' -or [string]$slot.file_id_128 -ine [string]$cleanup.FileId128 -or [string]$slot.sha256 -or [int64]$slot.length -ne -1) { return $null }
            } elseif ($sequence -lt [int]$cleanup.Sequence) {
                if ([string]$slot.content_state -cne 'sealed' -or [string]$slot.sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [int64]$slot.length -lt 1) { return $null }
            } else {
                if ([string]$slot.content_state -cne 'empty' -or [string]$slot.sha256 -or [int64]$slot.length -ne 0) { return $null }
            }
            $rosterByLeaf[$expectedLeaf] = $slot
        }
        $predecessorRoster = $rosterByLeaf[[string]$predecessor.leaf]
        if ($null -eq $predecessorRoster -or [string]$predecessorRoster.file_id_128 -ine [string]$predecessor.file_id_128 -or
            [string]$predecessorRoster.sha256 -ine [string]$predecessor.sha256 -or [int64]$predecessorRoster.length -ne [int64]$predecessor.length) { return $null }

        $deleteEntries = @()
        foreach ($entry in $entries) {
            if ([string]$entry.Name -ceq $script:SynapseDeploymentAllocationMarkerFileName) {
                if ([string]$entry.FileId128 -ine [string]$allocationLog.file_id_128 -or [int64]$entry.Length -ne [int64]$allocationLog.length) { return $null }
                $state = Get-SynapsePhysicalRelativeState -ParentPath $root -ParentChain $chain -Leaf ([string]$entry.Name)
                if ([string]$state.Sha256 -ine [string]$allocationLog.sha256) { return $null }
                $deleteEntries += [pscustomobject]@{ Sequence=0; Leaf=[string]$entry.Name; FileId128=[string]$state.FileId128; RawSha256=[string]$state.Sha256; ByteLength=[int64]$state.Length; IsCleanup=$false }
                continue
            }
            $slot = $rosterByLeaf[[string]$entry.Name]
            if ($null -eq $slot -or [string]$entry.FileId128 -ine [string]$slot.file_id_128) { return $null }
            $state = Get-SynapsePhysicalRelativeState -ParentPath $root -ParentChain $chain -Leaf ([string]$entry.Name)
            if ([string]$entry.Name -ceq [string]$cleanup.Leaf) {
                if ([string]$state.Sha256 -ine [string]$cleanup.RawSha256 -or [int64]$state.Length -ne [int64]$cleanup.ByteLength) { return $null }
                $deleteEntries += [pscustomobject]@{ Sequence=[int]$slot.sequence; Leaf=[string]$entry.Name; FileId128=[string]$state.FileId128; RawSha256=[string]$state.Sha256; ByteLength=[int64]$state.Length; IsCleanup=$true }
            } elseif ([string]$slot.content_state -ceq 'sealed') {
                if ([string]$state.Sha256 -ine [string]$slot.sha256 -or [int64]$state.Length -ne [int64]$slot.length) { return $null }
                $deleteEntries += [pscustomobject]@{ Sequence=[int]$slot.sequence; Leaf=[string]$entry.Name; FileId128=[string]$state.FileId128; RawSha256=[string]$state.Sha256; ByteLength=[int64]$state.Length; IsCleanup=$false }
            } elseif ([string]$slot.content_state -ceq 'empty') {
                if ([int64]$state.Length -ne 0) { return $null }
                $deleteEntries += [pscustomobject]@{ Sequence=[int]$slot.sequence; Leaf=[string]$entry.Name; FileId128=[string]$state.FileId128; RawSha256=[string]$state.Sha256; ByteLength=0L; IsCleanup=$false }
            } else { return $null }
        }
        $orderedDeletes = @($deleteEntries | Where-Object { -not [bool]$_.IsCleanup } | Sort-Object Sequence) + @($deleteEntries | Where-Object IsCleanup)
        return [pscustomobject]@{ Root=$root; RootChain=$chain; RootFileId128=[string]$chain[-1].file_id_128; Entries=$orderedDeletes; TerminalState=[string]$detail.terminal_state; CleanupAuthority=$cleanupAuthority }
    } catch { return $null }
}

function Get-SynapseGlobalRecoveryInventory {
    param(
        [Parameter(Mandatory=$true)][string]$LogDir,
        [Parameter(Mandatory=$true)][string]$ProfilesDir,
        [Parameter(Mandatory=$true)][string]$RuntimeBinDir
    )

    # This function is the mutation-free global classifier.  It intentionally
    # does not call any Ensure/New/Write/Remove/Register/Start/Stop/recovery
    # helper.  A later recovery action must re-read its own exact journal and
    # physical identities before changing state.
    $observeRoot = {
        param([string]$Name,[string]$Path)
        $full=Get-SynapseNormalizedDirectoryPath -Path $Path
        if(-not(Test-Path -LiteralPath $full)){
            return [pscustomobject][ordered]@{Name=$Name;Path=$full;Exists=$false;Chain=@();FileId128=''}
        }
        $item=Get-Item -LiteralPath $full -Force -ErrorAction Stop
        if(-not [bool]$item.PSIsContainer -or ([uint32]$item.Attributes -band [uint32][System.IO.FileAttributes]::ReparsePoint)){
            Die "SYNAPSE_GLOBAL_RECOVERY_ROOT_INVALID domain=$Name path=$full attributes=$($item.Attributes)"
        }
        $chain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $full)
        [void](Assert-SynapsePhysicalDirectoryChainDescriptor -Chain $chain -ExpectedPath $full -Context "global_recovery_$Name")
        return [pscustomobject][ordered]@{Name=$Name;Path=$full;Exists=$true;Chain=$chain;FileId128=([string]$chain[-1].file_id_128).ToUpperInvariant()}
    }

    $log=Get-SynapseNormalizedDirectoryPath -Path $LogDir
    $profiles=Get-SynapseNormalizedDirectoryPath -Path $ProfilesDir
    $runtime=Get-SynapseNormalizedDirectoryPath -Path $RuntimeBinDir
    $v1Path=Get-SynapseNormalizedDirectoryPath -Path (Join-Path $log 'setup-transactions')
    $applicationPath=Get-SynapseNormalizedDirectoryPath -Path (Join-Path (Split-Path -Parent $profiles) $script:SynapseDeploymentTransactionParentDirName)
    $authorityPath=Get-SynapseNormalizedDirectoryPath -Path (Join-Path $runtime $script:SynapseAuthorityRootLeaf)
    if($profiles -ieq $applicationPath -or $v1Path -ieq $applicationPath -or $v1Path -ieq $authorityPath -or $applicationPath -ieq $authorityPath){
        Die "SYNAPSE_GLOBAL_RECOVERY_ROOT_ALIAS v1=$v1Path application=$applicationPath authority=$authorityPath"
    }

    $v1Root=& $observeRoot 'legacy_v1' $v1Path
    $applicationRoot=& $observeRoot 'application' $applicationPath
    $authorityRoot=& $observeRoot 'authority' $authorityPath
    $taskRoot=& $observeRoot 'task' (Join-Path $authorityPath 'task-epochs')
    $adoptionRoot=& $observeRoot 'adoption' (Join-Path $authorityPath 'epochs')
    $operatorRoot=& $observeRoot 'operator' (Join-Path $authorityPath 'operations')
    $authorityLayout=if($authorityRoot.Exists){Get-SynapseAuthorityLayoutReadOnly -RuntimeBinDir $runtime -RequireAuthorityRoot}else{$null}

    $v1=@()
    if($v1Root.Exists){
        $entries=@(Get-SynapsePhysicalDirectoryEntriesBounded -Path $v1Root.Path -Chain $v1Root.Chain -MaximumEntries 128 -Context 'global_recovery_v1_parent')
        $invalid=@($entries|Where-Object{-not [bool]$_.IsDirectory -or ([uint32]$_.Attributes -band [uint32][System.IO.FileAttributes]::ReparsePoint) -or [string]$_.Name -notmatch '^deployment-\d{8}T\d{9}Z-\d+$'})
        if($invalid.Count){Die "SYNAPSE_GLOBAL_RECOVERY_V1_NAMESPACE_INVALID root=$($v1Root.Path) entries=$(@($invalid.Name)-join ',')"}
        foreach($entry in @($entries|Sort-Object Name)){
            $chain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path ([string]$entry.Path))
            if([string]$chain[-1].file_id_128 -ine [string]$entry.FileId128){Die "SYNAPSE_GLOBAL_RECOVERY_ENTRY_DRIFT domain=legacy_v1 root=$($entry.Path)"}
            $children=@(Get-SynapsePhysicalDirectoryEntriesBounded -Path ([string]$entry.Path) -Chain $chain -MaximumEntries 128 -Context 'global_recovery_v1_entry')
            $bad=@($children|Where-Object{[bool]$_.IsDirectory -or ([uint32]$_.Attributes -band [uint32][System.IO.FileAttributes]::ReparsePoint) -or [string]$_.Name -notmatch '^(transaction\.json|previous-task\.xml|file-\d{4}\.bin)$' -or [int64]$_.Length -gt 2GB})
            if($bad.Count){Die "SYNAPSE_GLOBAL_RECOVERY_V1_CONTENT_INVALID root=$($entry.Path) entries=$(@($bad.Name)-join ',')"}
            $manifestEntry=@($children|Where-Object Name -CEQ 'transaction.json')
            if($manifestEntry.Count -eq 0){
                $descriptor=Get-SynapseDeploymentTransactionArtifactDescriptorV1 -Path ([string]$entry.Path) -ExpectedRoot $v1Root.Path -ExpectedState unarmed
                $v1+=,[pscustomobject][ordered]@{Domain='legacy_v1';RecordKind='unarmed';Entry=$entry;Root=[string]$entry.Path;RootFileId128=[string]$descriptor.RootFileId128;State='unarmed';EffectiveState='unarmed';Journal=$null;Initial=$null}
                continue
            }
            if($manifestEntry.Count -ne 1 -or [int64]$manifestEntry[0].Length -gt 1MB){Die "SYNAPSE_GLOBAL_RECOVERY_V1_MANIFEST_INVALID root=$($entry.Path)"}
            $raw=Read-SynapsePhysicalRelativeUtf8Text -ParentPath ([string]$entry.Path) -ParentChain $chain -Leaf 'transaction.json' -ExpectedFileId128 ([string]$manifestEntry[0].FileId128) -MaxBytes 1MB
            try{$manifest=[string]$raw.Content|ConvertFrom-Json -ErrorAction Stop}catch{Die "SYNAPSE_GLOBAL_RECOVERY_V1_MANIFEST_UNREADABLE root=$($entry.Path) error=$($_.Exception.Message)"}
            if([string]$manifest.schema -cne 'synapse_deployment_transaction/v1' -or [string]$manifest.state -notin @('armed','committed','rolled_back')){Die "SYNAPSE_GLOBAL_RECOVERY_V1_STATE_INVALID root=$($entry.Path) schema=$($manifest.schema) state=$($manifest.state)"}
            if($null -ne $manifest.PSObject.Properties['transaction_root'] -and -not [string]::IsNullOrWhiteSpace([string]$manifest.transaction_root) -and (Get-SynapseNormalizedDirectoryPath -Path ([string]$manifest.transaction_root)) -ine (Get-SynapseNormalizedDirectoryPath -Path ([string]$entry.Path))){Die "SYNAPSE_GLOBAL_RECOVERY_V1_ROOT_MISMATCH root=$($entry.Path)"}
            if([string]$manifest.state -in @('committed','rolled_back')){[void](Get-SynapseDeploymentTransactionArtifactDescriptorV1 -Path ([string]$entry.Path) -ExpectedRoot $v1Root.Path -ExpectedState ([string]$manifest.state))}
            $v1+=,[pscustomobject][ordered]@{Domain='legacy_v1';RecordKind='manifest';Entry=$entry;Root=[string]$entry.Path;RootFileId128=[string]$entry.FileId128;State=[string]$manifest.state;EffectiveState=[string]$manifest.state;Journal=$null;Initial=$manifest;ManifestSha256=([string]$raw.Sha256).ToUpperInvariant()}
        }
    }

    $scanJournalParent={
        param($ObservedRoot,[string]$ParentDomain,[int]$MaximumEntries,$Accepted)
        $records=@()
        if(-not $ObservedRoot.Exists){return @()}
        $entries=@(Get-SynapsePhysicalDirectoryEntriesBounded -Path $ObservedRoot.Path -Chain $ObservedRoot.Chain -MaximumEntries $MaximumEntries -Context "global_recovery_$ParentDomain")
        $invalid=@($entries|Where-Object{-not [bool]$_.IsDirectory -or ([uint32]$_.Attributes -band [uint32][System.IO.FileAttributes]::ReparsePoint) -or [string]$_.Name -notmatch '^deployment-\d{8}T\d{9}Z-\d+$'})
        if($invalid.Count){Die "SYNAPSE_GLOBAL_RECOVERY_NAMESPACE_INVALID domain=$ParentDomain root=$($ObservedRoot.Path) entries=$(@($invalid.Name)-join ',')"}
        foreach($entry in @($entries|Sort-Object Name)){
            $journal=$null;$readError=''
            try{$journal=Read-SynapseDeploymentTransactionJournal -TransactionRoot ([string]$entry.Path)}catch{$readError=$_.Exception.Message}
            if($null -eq $journal){
                $tail=if($readError){Get-SynapseDeploymentCleanupTailDescriptor -TransactionRoot ([string]$entry.Path)}else{$null}
                if($null -ne $tail){
                    $tailKind=if($ParentDomain-ceq'adoption' -and [string]$tail.TerminalState-ceq'rolled_back' -and $null-ne$tail.CleanupAuthority){if([string]$tail.CleanupAuthority.schema-ceq'synapse_authority_failed_successor_cleanup/v1'){'authority_failed_successor_cleanup_tail'}elseif([string]$tail.CleanupAuthority.schema-ceq'synapse_authority_committed_successor_predecessor_cleanup/v1'){'authority_committed_predecessor_cleanup_tail'}else{Die "SYNAPSE_GLOBAL_RECOVERY_AUTHORITY_CLEANUP_TAIL_SCHEMA_INVALID root=$($entry.Path) schema=$($tail.CleanupAuthority.schema)"}}else{'cleanup_tail'}
                    $records+=,[pscustomobject][ordered]@{Domain=$ParentDomain;RecordKind=$tailKind;Entry=$entry;Root=[string]$entry.Path;RootFileId128=[string]$tail.RootFileId128;State='cleanup_ready';EffectiveState=[string]$tail.TerminalState;Journal=$null;Initial=$null;CleanupTail=$tail;PredecessorReceipt=$(if($tailKind-in@('authority_failed_successor_cleanup_tail','authority_committed_predecessor_cleanup_tail')){ConvertTo-SynapseCanonicalValue -Value $tail.CleanupAuthority.predecessor_receipt}else{$null})}
                    continue
                }
                $artifactDomain=if($ParentDomain -eq 'task'){'task'}elseif($ParentDomain -in @('adoption','operator')){'authority'}else{'application'}
                $descriptor=$null;$unarmedProofError=''
                try{$descriptor=Get-SynapseDeploymentTransactionArtifactDescriptor -Path ([string]$entry.Path) -ExpectedRoot $ObservedRoot.Path -ExpectedState unarmed -Domain $artifactDomain}catch{$unarmedProofError=$_.Exception.Message}
                if($null-eq$descriptor -and $ParentDomain-ceq'adoption'){
                    # A fully allocated, all-empty journal is the intentional
                    # pre-slot1 crash cut, not cleanup residue.  Only roots that
                    # fail that complete allocation-owned proof are deferred to
                    # committed-successor marker classification.
                    $records+=,[pscustomobject][ordered]@{Domain=$ParentDomain;RecordKind='authority_unreadable_cleanup_candidate';Entry=$entry;Root=[string]$entry.Path;RootFileId128=[string]$entry.FileId128;State='unreadable';EffectiveState='unreadable';Journal=$null;Initial=$null;CleanupTail=$null;CleanupMarker=$null;PredecessorReceipt=$null;ReadError=$(if($readError){$readError}else{$unarmedProofError})}
                    continue
                }
                if($null-eq$descriptor){Die "SYNAPSE_GLOBAL_RECOVERY_JOURNAL_UNREADABLE domain=$ParentDomain root=$($entry.Path) read_error=$readError proof_error=$unarmedProofError"}
                $records+=,[pscustomobject][ordered]@{Domain=$ParentDomain;RecordKind='unarmed';Entry=$entry;Root=[string]$entry.Path;RootFileId128=[string]$descriptor.RootFileId128;State='unarmed';EffectiveState='unarmed';Journal=$null;Initial=$null;CleanupTail=$null}
                continue
            }
            if([string]$journal.RootChain[-1].file_id_128 -ine [string]$entry.FileId128){Die "SYNAPSE_GLOBAL_RECOVERY_ENTRY_DRIFT domain=$ParentDomain root=$($entry.Path)"}
            $schema=[string]$journal.Initial.schema;$kind=if($null -ne $journal.Initial.PSObject.Properties['transaction_kind']){[string]$journal.Initial.transaction_kind}else{''}
            $match=@($Accepted|Where-Object{[string]$_.Schema -ceq $schema -and [string]$_.Kind -ceq $kind})
            if($match.Count -ne 1){Die "SYNAPSE_GLOBAL_RECOVERY_SCHEMA_INVALID domain=$ParentDomain root=$($entry.Path) schema=$schema kind=$kind"}
            $effective=if([string]$journal.State -ceq 'cleanup_ready'){[string]$journal.Latest.detail.terminal_state}else{[string]$journal.State}
            $adoptionStructure=$null;$rolledBackPredecessor=$null;$failedSuccessor=$null;$predecessorReceipt=$null;$physicalRollbackCandidate=$null
            try{switch([string]$match[0].Domain){
                'task' {[void](Assert-SynapseBrokerTaskCreateInitialDescriptor -Initial $journal.Initial -TransactionRoot ([string]$entry.Path) -Allocation $journal.Allocation)}
                'adoption' {
                    $adoptionStructure=Assert-SynapseAuthorityAdoptionInitialDescriptor -Initial $journal.Initial -TransactionRoot ([string]$entry.Path) -Allocation $journal.Allocation -HistoricalMutableGeneration:($effective -eq 'commit_decided') -StructuralOnly
                    if($effective-ceq'rolled_back'){
                        $rollbackRecord=Assert-SynapseAuthorityRolledBackPredecessor -Entry $entry -Journal $journal -StructuralOnly
                        if([string]$rollbackRecord.Mode-in@('fresh_monotonic_floor','legacy_prior_unchanged','legacy_direct_recovery')){
                            $rolledBackPredecessor=$rollbackRecord
                            $predecessorReceipt=New-SynapseAuthorityPredecessorReceipt -Predecessor $rolledBackPredecessor
                        }elseif([string]$rollbackRecord.Mode-ceq'predecessor_restored'){
                            $failedSuccessor=$rollbackRecord
                            $predecessorReceipt=ConvertTo-SynapseCanonicalValue -Value $journal.Initial.predecessor_authority_receipt
                        }else{Die "SYNAPSE_GLOBAL_RECOVERY_ADOPTION_ROLLBACK_MODE_INVALID root=$($entry.Path) mode=$($rollbackRecord.Mode)"}
                    }elseif($null-ne$journal.TornTail -and $effective-in@('armed','candidate_ready')){
                        $physicalRollbackCandidate=[pscustomobject][ordered]@{ValidPrefixState=$effective;ValidPrefixSequence=[int]$journal.Sequence;TornSequence=[int]$journal.TornTail.Sequence;TornLeaf=[string]$journal.TornTail.Leaf;TornFileId128=([string]$journal.TornTail.FileId128).ToUpperInvariant();TornSha256=([string]$journal.TornTail.Sha256).ToUpperInvariant();TornLength=[int64]$journal.TornTail.Length}
                    }
                }
                'operator' {if($null -eq $authorityLayout){Die "SYNAPSE_GLOBAL_RECOVERY_AUTHORITY_LAYOUT_MISSING domain=operator root=$($entry.Path)"};[void](Assert-SynapseBrokerOperatorStopInitialDescriptor -Initial $journal.Initial -TransactionRoot ([string]$entry.Path) -Allocation $journal.Allocation -Layout $authorityLayout)}
                'probe' {if($null -eq $authorityLayout){Die "SYNAPSE_GLOBAL_RECOVERY_AUTHORITY_LAYOUT_MISSING domain=probe root=$($entry.Path)"};[void](Assert-SynapseBrokerProbeParkInitialDescriptor -Initial $journal.Initial -TransactionRoot ([string]$entry.Path) -Allocation $journal.Allocation -Layout $authorityLayout)}
                'application_v4' {if($null -eq $authorityLayout){Die "SYNAPSE_GLOBAL_RECOVERY_AUTHORITY_LAYOUT_MISSING domain=application_v4 root=$($entry.Path)"};[void](Assert-SynapseBrokerApplicationInitialDescriptor -Initial $journal.Initial -TransactionRoot ([string]$entry.Path) -Allocation $journal.Allocation -Layout $authorityLayout -AllowCommittedDiscardedPost:($effective-ceq'commit_decided'))}
                'legacy_v3' {
                    [void](Assert-SynapseBundledProfilesTransactionDescriptor -Descriptor $journal.Initial.profile_transaction -ProfilesDir ([string]$journal.Initial.profile_transaction.profiles_dir) -TransactionRoot ([string]$entry.Path))
                    $legacyPaths=@($journal.Initial.runtime_transaction.records|ForEach-Object{[System.IO.Path]::GetFullPath([string]$_.path)})
                    [void](Assert-SynapseRuntimeTransactionDescriptor -Descriptor $journal.Initial.runtime_transaction -TransactionRoot ([string]$entry.Path) -ExpectedPaths $legacyPaths -Allocation $journal.Allocation)
                }
            }}catch{
                if($ParentDomain-ceq'adoption'){
                    # A successor-owned cleanup marker may already authorize a
                    # redo-only predecessor deletion while enough predecessor
                    # journal bytes remain for the generic reader to parse a
                    # prefix.  Defer every structural failure to the later
                    # committed-successor/marker proof; this scanner grants no
                    # mutation authority by itself.
                    $records+=,[pscustomobject][ordered]@{Domain=$ParentDomain;RecordKind='authority_unreadable_cleanup_candidate';Entry=$entry;Root=[string]$entry.Path;RootFileId128=[string]$entry.FileId128;State='unreadable';EffectiveState='unreadable';Journal=$null;Initial=$null;CleanupTail=$null;CleanupMarker=$null;PredecessorReceipt=$null;ReadError=$_.Exception.Message}
                    continue
                }
                throw
            }
            $records+=,[pscustomobject][ordered]@{Domain=[string]$match[0].Domain;RecordKind='journal';Entry=$entry;Root=[string]$entry.Path;RootFileId128=[string]$entry.FileId128;Schema=$schema;Kind=$kind;State=[string]$journal.State;EffectiveState=$effective;Journal=$journal;Initial=$journal.Initial;CleanupTail=$null;AdoptionStructure=$adoptionStructure;RolledBackPredecessor=$rolledBackPredecessor;FailedSuccessor=$failedSuccessor;PredecessorReceipt=$predecessorReceipt;PhysicalRollbackCandidate=$physicalRollbackCandidate}
        }
        return @($records)
    }

    $task=@(& $scanJournalParent $taskRoot 'task' $script:SynapseAuthorityMaxEpochs @([pscustomobject]@{Schema='synapse_broker_task_create_transaction/v1';Kind='synapse_broker_task_create/v1';Domain='task'}))
    $adoption=@(& $scanJournalParent $adoptionRoot 'adoption' $script:SynapseAuthorityMaxEpochs @([pscustomobject]@{Schema='synapse_broker_adoption_transaction/v3';Kind='synapse_broker_adoption/v3';Domain='adoption'},[pscustomobject]@{Schema='synapse_broker_adoption_transaction/v4';Kind='synapse_broker_adoption/v4';Domain='adoption'}))
    $operator=@(& $scanJournalParent $operatorRoot 'operator' 1 @([pscustomobject]@{Schema='synapse_broker_operator_stop_transaction/v1';Kind='synapse_broker_operator_stop/v1';Domain='operator'}))
    $application=@(& $scanJournalParent $applicationRoot 'application' $script:SynapseDeploymentArtifactMaxDirectEntries @(
        [pscustomobject]@{Schema='synapse_deployment_transaction/v3';Kind='';Domain='legacy_v3'},
        [pscustomobject]@{Schema='synapse_broker_probe_park_transaction/v1';Kind='synapse_broker_probe_park/v1';Domain='probe'},
        [pscustomobject]@{Schema='synapse_deployment_transaction/v4';Kind='synapse_broker_application/v1';Domain='application_v4'}
    ))
    $result=[pscustomobject][ordered]@{
        Roots=[pscustomobject][ordered]@{V1=$v1Root;Application=$applicationRoot;Authority=$authorityRoot;Task=$taskRoot;Adoption=$adoptionRoot;Operator=$operatorRoot}
        V1=@($v1);LegacyV3=@($application|Where-Object Domain -CEQ 'legacy_v3');TaskEpochs=@($task);Adoptions=@($adoption)
        Probe=@($application|Where-Object Domain -CEQ 'probe');ApplicationV4=@($application|Where-Object Domain -CEQ 'application_v4')
        ApplicationCleanup=@($application|Where-Object RecordKind -CNE 'journal');Operations=@($operator)
    }
    $fingerprintRecords=@($v1)+@($task)+@($adoption)+@($application)+@($operator)
    $fingerprint=[ordered]@{
        roots=@($result.Roots.PSObject.Properties|ForEach-Object{[ordered]@{domain=[string]$_.Name;path=[string]$_.Value.Path;exists=[bool]$_.Value.Exists;file_id_128=[string]$_.Value.FileId128}}|Sort-Object domain)
        records=@($fingerprintRecords|ForEach-Object{[ordered]@{domain=[string]$_.Domain;record_kind=[string]$_.RecordKind;root=[string]$_.Root;root_file_id_128=[string]$_.RootFileId128;schema=$(if($null -ne $_.PSObject.Properties['Schema']){[string]$_.Schema}else{''});kind=$(if($null -ne $_.PSObject.Properties['Kind']){[string]$_.Kind}else{''});state=[string]$_.State;effective_state=[string]$_.EffectiveState;latest_sequence=$(if($null-ne$_.Journal){[int]$_.Journal.Sequence}else{0});latest_leaf=$(if($null-ne$_.Journal){[string]$_.Journal.Slots[-1].Leaf}else{''});latest_file_id_128=$(if($null-ne$_.Journal){[string]$_.Journal.Slots[-1].FileId128}else{''});latest_sha256=$(if($null -ne $_.Journal){[string]$_.Journal.LatestRawSha256}else{''});latest_length=$(if($null-ne$_.Journal){[int64]$_.Journal.Slots[-1].ByteLength}else{0L});torn_sequence=$(if($null-ne$_.Journal -and $null-ne$_.Journal.TornTail){[int]$_.Journal.TornTail.Sequence}else{0});torn_leaf=$(if($null-ne$_.Journal -and $null-ne$_.Journal.TornTail){[string]$_.Journal.TornTail.Leaf}else{''});torn_file_id_128=$(if($null-ne$_.Journal -and $null-ne$_.Journal.TornTail){[string]$_.Journal.TornTail.FileId128}else{''});torn_sha256=$(if($null-ne$_.Journal -and $null-ne$_.Journal.TornTail){[string]$_.Journal.TornTail.Sha256}else{''});torn_length=$(if($null-ne$_.Journal -and $null-ne$_.Journal.TornTail){[int64]$_.Journal.TornTail.Length}else{0L});predecessor_receipt_sha256=$(if($null-ne$_.PSObject.Properties['PredecessorReceipt'] -and $null-ne$_.PredecessorReceipt){(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $_.PredecessorReceipt)).ToUpperInvariant()}else{''});manifest_sha256=$(if($null -ne $_.PSObject.Properties['ManifestSha256']){[string]$_.ManifestSha256}else{''})}}|Sort-Object domain,root)
    }
    $result|Add-Member -NotePropertyName FingerprintSha256 -NotePropertyValue ((Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $fingerprint)).ToUpperInvariant())
    return $result
}

function Select-SynapseGlobalRecoveryAction {
    param(
        [Parameter(Mandatory=$true)]$Inventory,
        [ValidateSet('setup','start','stop','remove','resume_chrome')][string]$Mode='setup'
    )
    $deny={param([string]$Code,[string]$Detail)[pscustomobject][ordered]@{Allowed=$false;Action='fail';Mode=$Mode;Code=$Code;Error="$Code $Detail"}}

    # Shipped v3 journals depended on mutable fixed-name Scheduler authority.
    # That authority is permanently retired: no nonterminal or forward-decision
    # v3 state may recover by changing runtime/profile/task reality.  Only an
    # already-terminal exact cleanup receipt is eligible for bounded cleanup.
    $activeV3=@($Inventory.LegacyV3|Where-Object{[string]$_.EffectiveState -in @('armed','candidate_ready','commit_decided')})
    if($activeV3.Count){return (& $deny 'SYNAPSE_DEPLOYMENT_TRANSACTION_V3_FROZEN_ACTIVE_PRESERVED' "count=$($activeV3.Count) roots=$(@($activeV3.Root)-join ',') runtime_mutations=0 task_mutations=0")}

    $invalidTask=@($Inventory.TaskEpochs|Where-Object{[string]$_.RecordKind -eq 'cleanup_tail' -or ([string]$_.RecordKind -eq 'journal' -and [string]$_.State -notin @('armed','candidate_ready','commit_decided'))})
    if($invalidTask.Count){return (& $deny 'SYNAPSE_BROKER_TASK_EPOCH_STATE_INVALID' "roots=$(@($invalidTask.Root)-join ',') states=$(@($invalidTask.State)-join ',')")}
    $taskCommitted=@($Inventory.TaskEpochs|Where-Object{$_.RecordKind -eq 'journal' -and $_.State -eq 'commit_decided'})
    $taskLive=@($Inventory.TaskEpochs|Where-Object{$_.RecordKind -eq 'unarmed' -or ($_.RecordKind -eq 'journal' -and $_.State -in @('armed','candidate_ready'))})
    $validCommittedTaskChain=$taskCommitted.Count-le1
    if($taskCommitted.Count-gt1){
        $orderedCommittedTasks=@($taskCommitted|Sort-Object{[int64]$_.Initial.task_epoch});$validCommittedTaskChain=$true
        for($i=0;$i-lt$orderedCommittedTasks.Count;$i++){
            if([int64]$orderedCommittedTasks[$i].Initial.task_epoch-ne($i+1L)-or($i-eq0-and$null-ne$orderedCommittedTasks[$i].Initial.predecessor_receipt)-or($i-gt0-and(Get-SynapseCanonicalJson -Value $orderedCommittedTasks[$i].Initial.predecessor_receipt)-cne(Get-SynapseCanonicalJson -Value (ConvertTo-SynapseBrokerTaskReceiptDescriptorFromJournal -Journal $orderedCommittedTasks[$i-1].Journal)))){$validCommittedTaskChain=$false;break}
        }
    }
    $validTaskRotation=$false
    if($taskCommitted.Count-eq1-and$taskLive.Count-eq1-and$taskLive[0].RecordKind-eq'journal'){
        $declared=$taskLive[0].Journal.Initial.predecessor_receipt
        $expected=ConvertTo-SynapseBrokerTaskReceiptDescriptorFromJournal -Journal $taskCommitted[0].Journal
        $validTaskRotation=([int64]$taskLive[0].Journal.Initial.task_epoch-eq([int64]$taskCommitted[0].Journal.Initial.task_epoch+1L)-and$null-ne$declared-and(Get-SynapseCanonicalJson -Value $declared)-ceq(Get-SynapseCanonicalJson -Value $expected))
    }
    if(-not$validCommittedTaskChain-or$taskLive.Count -gt 1 -or ($taskCommitted.Count -gt 0 -and $taskLive.Count -gt 0 -and-not$validTaskRotation)){return (& $deny 'SYNAPSE_BROKER_TASK_EPOCH_AMBIGUOUS' "committed=$($taskCommitted.Count) live=$($taskLive.Count) valid_committed_chain=$validCommittedTaskChain valid_rotation=$validTaskRotation")}

    $adoptionJournal=@($Inventory.Adoptions|Where-Object RecordKind -CEQ 'journal')
    $adoptionCommitted=@($adoptionJournal|Where-Object State -CEQ 'commit_decided')
    $adoptionPredecessor=@($adoptionJournal|Where-Object{$null-ne$_.RolledBackPredecessor})
    $adoptionFailedSuccessor=@($adoptionJournal|Where-Object{$null-ne$_.FailedSuccessor})
    $adoptionPhysicalFailedSuccessor=@($adoptionFailedSuccessor|Where-Object{$null-ne$_.FailedSuccessor.PSObject.Properties['PhysicalRollback'] -and [bool]$_.FailedSuccessor.PhysicalRollback})
    $adoptionDurableFailedSuccessor=@($adoptionFailedSuccessor|Where-Object{$null-eq$_.FailedSuccessor.PSObject.Properties['PhysicalRollback'] -or -not[bool]$_.FailedSuccessor.PhysicalRollback})
    $adoptionFailedCleanupTail=@($Inventory.Adoptions|Where-Object RecordKind -CEQ 'authority_failed_successor_cleanup_tail')
    $adoptionCommittedCleanupTail=@($Inventory.Adoptions|Where-Object{$_.RecordKind-in@('authority_committed_predecessor_cleanup_tail','authority_committed_predecessor_cleanup_residue')})
    $adoptionRepair=@($adoptionDurableFailedSuccessor)+@($adoptionFailedCleanupTail)
    $adoptionLive=@($Inventory.Adoptions|Where-Object{$_.RecordKind -eq 'unarmed' -or ($_.RecordKind -eq 'journal' -and $_.State -in @('armed','candidate_ready') -and $null-eq$_.RolledBackPredecessor -and $null-eq$_.FailedSuccessor)})
    $invalidAdoptionRollbackTail=@($Inventory.Adoptions|Where-Object{$_.RecordKind-eq'cleanup_tail' -and $_.EffectiveState-eq'rolled_back'})
    if($invalidAdoptionRollbackTail.Count){return (& $deny 'SYNAPSE_AUTHORITY_PREDECESSOR_PARTIAL_CLEANUP_PRESERVED' "roots=$(@($invalidAdoptionRollbackTail.Root)-join ',')")}
    $invalidAdoptionCommitTail=@($Inventory.Adoptions|Where-Object{$_.State -eq 'cleanup_ready' -and $_.EffectiveState -eq 'commit_decided'})
    if($invalidAdoptionCommitTail.Count){return (& $deny 'SYNAPSE_AUTHORITY_COMMITTED_RECEIPT_CLEANUP_FORBIDDEN' "roots=$(@($invalidAdoptionCommitTail.Root)-join ',')")}
    if($adoptionCommitted.Count -gt 1 -or $adoptionLive.Count -gt 1 -or $adoptionPredecessor.Count-gt1 -or $adoptionRepair.Count-gt1 -or $adoptionCommittedCleanupTail.Count-gt1 -or ($adoptionCommitted.Count -gt 0 -and $adoptionLive.Count -gt 0)){return (& $deny 'SYNAPSE_AUTHORITY_EPOCH_AMBIGUOUS' "committed=$($adoptionCommitted.Count) live=$($adoptionLive.Count) predecessor=$($adoptionPredecessor.Count) repair=$($adoptionRepair.Count) committed_cleanup=$($adoptionCommittedCleanupTail.Count) physical_failed=$($adoptionPhysicalFailedSuccessor.Count)")}
    $successor=@($adoptionCommitted)+@($adoptionLive|Where-Object RecordKind -CEQ 'journal')
    if($adoptionPredecessor.Count-eq1){
        if($null-eq$adoptionPredecessor[0].PredecessorReceipt){return (& $deny 'SYNAPSE_AUTHORITY_PREDECESSOR_RECEIPT_MISSING' "root=$($adoptionPredecessor[0].Root)")}
        if($successor.Count-eq1){
            try{[void](Assert-SynapseAuthorityPredecessorSuccessorPair -PredecessorRecord $adoptionPredecessor[0] -SuccessorInitial $successor[0].Initial -SuccessorRoot ([string]$successor[0].Root) -Context 'authority_global_selector_pair')}catch{return (& $deny 'SYNAPSE_AUTHORITY_SUCCESSOR_PREDECESSOR_PAIR_INVALID' "predecessor=$($adoptionPredecessor[0].Root) successor=$($successor[0].Root) error=$($_.Exception.Message)")}
        }
    }elseif($adoptionLive.Count-eq1 -and $adoptionLive[0].RecordKind-ceq'journal' -and $null-ne$adoptionLive[0].Initial.predecessor_authority_receipt){
        return (& $deny 'SYNAPSE_AUTHORITY_PRECOMMIT_PREDECESSOR_MISSING' "successor=$($adoptionLive[0].Root) predecessor=$($adoptionLive[0].Initial.predecessor_authority_receipt.journal.transaction_root)")
    }
    if($adoptionRepair.Count-eq1){
        if($adoptionPredecessor.Count-ne1){return (& $deny 'SYNAPSE_AUTHORITY_FAILED_SUCCESSOR_PREDECESSOR_MISSING' "successor=$($adoptionRepair[0].Root)")}
        $repairReceipt=$adoptionRepair[0].PredecessorReceipt
        if($null-eq$repairReceipt -or (Get-SynapseCanonicalJson -Value $repairReceipt)-cne(Get-SynapseCanonicalJson -Value $adoptionPredecessor[0].PredecessorReceipt)){
            return (& $deny 'SYNAPSE_AUTHORITY_FAILED_SUCCESSOR_CROSSBIND_INVALID' "predecessor=$($adoptionPredecessor[0].Root) successor=$($adoptionRepair[0].Root)")
        }
    }
    foreach($physicalFailed in @($adoptionPhysicalFailedSuccessor)){
        $physicalReceiptJson=Get-SynapseCanonicalJson -Value $physicalFailed.PredecessorReceipt
        $boundToPredecessor=($adoptionPredecessor.Count-eq1 -and $physicalReceiptJson-ceq(Get-SynapseCanonicalJson -Value $adoptionPredecessor[0].PredecessorReceipt))
        $boundToCommitted=($adoptionCommitted.Count-eq1 -and $null-ne$adoptionCommitted[0].Initial.predecessor_authority_receipt -and $physicalReceiptJson-ceq(Get-SynapseCanonicalJson -Value $adoptionCommitted[0].Initial.predecessor_authority_receipt))
        if(-not$boundToPredecessor -and -not$boundToCommitted){
            return (& $deny 'SYNAPSE_AUTHORITY_PHYSICAL_FAILED_SUCCESSOR_CROSSBIND_INVALID' "predecessor_count=$($adoptionPredecessor.Count) committed=$($adoptionCommitted.Count) successor=$($physicalFailed.Root)")
        }
    }
    $adoptionPredecessorCleanup=@()
    if($adoptionCommittedCleanupTail.Count-eq1){
        if($adoptionCommitted.Count-ne1 -or $adoptionPredecessor.Count-ne0 -or $adoptionLive.Count-ne0 -or $adoptionRepair.Count-ne0){return (& $deny 'SYNAPSE_AUTHORITY_COMMITTED_PREDECESSOR_CLEANUP_AMBIGUOUS' "tail=$($adoptionCommittedCleanupTail[0].Root) committed=$($adoptionCommitted.Count) predecessor=$($adoptionPredecessor.Count) live=$($adoptionLive.Count) repair=$($adoptionRepair.Count)")}
        try{
            $cleanupAuthority=if([string]$adoptionCommittedCleanupTail[0].RecordKind-ceq'authority_committed_predecessor_cleanup_residue'){$adoptionCommittedCleanupTail[0].CleanupMarker.Payload.cleanup_authority}else{$adoptionCommittedCleanupTail[0].CleanupTail.CleanupAuthority}
            $cleanupProof=Assert-SynapseAuthorityCommittedSuccessorPredecessorCleanupAuthority -Authority $cleanupAuthority -ExpectedPredecessorReceipt $adoptionCommittedCleanupTail[0].PredecessorReceipt -Context 'authority_global_selector_cleanup_tail'
        }catch{return (& $deny 'SYNAPSE_AUTHORITY_COMMITTED_PREDECESSOR_CLEANUP_AUTHORITY_INVALID' "tail=$($adoptionCommittedCleanupTail[0].Root) error=$($_.Exception.Message)")}
        if((Get-SynapseNormalizedDirectoryPath -Path ([string]$cleanupProof.Authority.successor_root))-ine(Get-SynapseNormalizedDirectoryPath -Path ([string]$adoptionCommitted[0].Root))){return (& $deny 'SYNAPSE_AUTHORITY_COMMITTED_PREDECESSOR_CLEANUP_SUCCESSOR_MISMATCH' "tail=$($adoptionCommittedCleanupTail[0].Root) successor=$($adoptionCommitted[0].Root)")}
        $adoptionPredecessorCleanup=@($adoptionCommittedCleanupTail[0])
    }elseif($adoptionPredecessor.Count-eq1 -and $adoptionCommitted.Count-eq1){$adoptionPredecessorCleanup=@($adoptionPredecessor[0])}

    foreach($record in $adoptionJournal){
        if($taskCommitted.Count -lt 1){return (& $deny 'SYNAPSE_AUTHORITY_TASK_RECEIPT_PREREQUISITE_MISSING' "adoption=$($record.Root) committed_task_receipts=$($taskCommitted.Count)")}
        $receipt=$record.Initial.broker_task_receipt
        $matchingTaskRecords=@($taskCommitted|Where-Object{(Get-SynapseNormalizedDirectoryPath -Path ([string]$_.Root))-ieq(Get-SynapseNormalizedDirectoryPath -Path ([string]$receipt.task_epoch_root))})
        if($matchingTaskRecords.Count-ne1){return (& $deny 'SYNAPSE_AUTHORITY_TASK_RECEIPT_PREREQUISITE_MISSING' "adoption=$($record.Root) matching_task_receipts=$($matchingTaskRecords.Count) committed_task_receipts=$($taskCommitted.Count)")}
        $taskRecord=$matchingTaskRecords[0]
        if($null -eq $receipt -or (Get-SynapseNormalizedDirectoryPath -Path ([string]$receipt.task_epoch_root)) -ine (Get-SynapseNormalizedDirectoryPath -Path ([string]$taskRecord.Root)) -or
           [string]$receipt.task_epoch_root_file_id_128 -ine [string]$taskRecord.RootFileId128 -or [string]$receipt.task_capability_sha256 -ine [string]$taskRecord.Initial.task_capability_sha256 -or
           [string]$receipt.broker_identity_sha256 -ine [string]$taskRecord.Initial.broker_identity_sha256 -or [string]$receipt.task_name -cne [string]$taskRecord.Initial.task.name){
            return (& $deny 'SYNAPSE_AUTHORITY_TASK_RECEIPT_CROSSBIND_INVALID' "adoption=$($record.Root) task_epoch=$($taskRecord.Root)")
        }
        foreach($sequence in 1..3){
            $declared=$receipt.("slot$sequence");$actual=@($taskRecord.Journal.Slots|Where-Object Sequence -EQ $sequence)
            if($actual.Count -ne 1 -or [int]$declared.sequence -ne $sequence -or [string]$declared.file_id_128 -ine [string]$actual[0].FileId128 -or [string]$declared.sha256 -ine [string]$actual[0].RawSha256 -or [int64]$declared.length -ne [int64]$actual[0].ByteLength){return (& $deny 'SYNAPSE_AUTHORITY_TASK_RECEIPT_SLOT_CROSSBIND_INVALID' "adoption=$($record.Root) slot=$sequence")}
        }
    }

    $downstream=@($Inventory.Probe)+@($Inventory.ApplicationV4)+@($Inventory.Operations|Where-Object RecordKind -CEQ 'journal')
    $downstreamUnarmed=@($Inventory.ApplicationCleanup|Where-Object RecordKind -In @('unarmed','cleanup_tail'))+@($Inventory.Operations|Where-Object RecordKind -In @('unarmed','cleanup_tail'))
    if(($downstream.Count+$downstreamUnarmed.Count) -gt 1){return (& $deny 'SYNAPSE_GLOBAL_RECOVERY_DOWNSTREAM_AMBIGUOUS' "probe=$(@($Inventory.Probe).Count) application_v4=$(@($Inventory.ApplicationV4).Count) operator=$(@($Inventory.Operations|Where-Object RecordKind -CEQ 'journal').Count) unarmed=$($downstreamUnarmed.Count)")}
    foreach($record in $downstream){
        if($adoptionCommitted.Count -ne 1){return (& $deny 'SYNAPSE_GLOBAL_RECOVERY_ADOPTION_PREREQUISITE_MISSING' "domain=$($record.Domain) root=$($record.Root) committed_adoptions=$($adoptionCommitted.Count)")}
        $a=$adoptionCommitted[0].Initial;$i=$record.Initial
        if([string]$i.broker_identity_sha256 -ine [string]$a.broker_identity_sha256 -or [int64]$i.authority_epoch -ne [int64]$a.authority_epoch -or [string]$i.control_nonce -ine [string]$a.control_nonce -or
           [string]$i.broker_task_capability_sha256 -ine [string]$a.broker_task_receipt.task_capability_sha256 -or
           (Get-SynapseCanonicalJson -Value $i.broker_task) -cne (Get-SynapseCanonicalJson -Value $a.broker_task)){
            return (& $deny 'SYNAPSE_GLOBAL_RECOVERY_ADOPTION_CROSSBIND_INVALID' "domain=$($record.Domain) root=$($record.Root) adoption=$($adoptionCommitted[0].Root)")
        }
    }

    $v1Live=@($Inventory.V1|Where-Object State -In @('armed','unarmed'))
    if($v1Live.Count -gt 1){return (& $deny 'SYNAPSE_DEPLOYMENT_TRANSACTION_RECOVERY_AMBIGUOUS' "active_count=$($v1Live.Count)")}
    $owners=@()
    $owners+=@($v1Live|ForEach-Object{[pscustomobject]@{Domain='legacy_v1';Record=$_}})
    $owners+=@($taskLive|ForEach-Object{[pscustomobject]@{Domain='task';Record=$_}})
    $owners+=@($adoptionLive|ForEach-Object{[pscustomobject]@{Domain='adoption';Record=$_}})
    $owners+=@($adoptionRepair|ForEach-Object{[pscustomobject]@{Domain='adoption';Record=$_}})
    $owners+=@($adoptionPredecessorCleanup|ForEach-Object{[pscustomobject]@{Domain='adoption_predecessor_cleanup';Record=$_}})
    $owners+=@($downstream|ForEach-Object{[pscustomobject]@{Domain=[string]$_.Domain;Record=$_}})
    $owners+=@($downstreamUnarmed|ForEach-Object{[pscustomobject]@{Domain='downstream_unarmed';Record=$_}})
    if($owners.Count -gt 1){return (& $deny 'SYNAPSE_GLOBAL_RECOVERY_OWNER_AMBIGUOUS' "count=$($owners.Count) domains=$(@($owners.Domain)-join ',') roots=$(@($owners.Record.Root)-join ',')")}
    if($taskLive.Count -and ($adoptionLive.Count -or $adoptionRepair.Count -or $adoptionPredecessorCleanup.Count -or $downstream.Count)){return (& $deny 'SYNAPSE_GLOBAL_RECOVERY_TASK_ORDER_INVALID' "task=$($taskLive[0].Root) adoption_live=$($adoptionLive.Count) adoption_repair=$($adoptionRepair.Count) adoption_cleanup=$($adoptionPredecessorCleanup.Count) downstream_count=$($downstream.Count)")}
    if($v1Live.Count -and ($Inventory.LegacyV3.Count -or $Inventory.TaskEpochs.Count -or $Inventory.Adoptions.Count -or $downstream.Count)){return (& $deny 'SYNAPSE_GLOBAL_RECOVERY_LEGACY_V1_ORDER_INVALID' "v1=$($v1Live[0].Root)")}
    return [pscustomobject][ordered]@{Allowed=$true;Action=$(if($owners.Count -eq 1){[string]$owners[0].Domain}else{'none'});Mode=$Mode;Code='accepted';Record=$(if($owners.Count -eq 1){$owners[0].Record}else{$null});Predecessor=$(if($adoptionPredecessor.Count-eq1){$adoptionPredecessor[0]}else{$null});Successor=$(if($adoptionPredecessorCleanup.Count-eq1 -and $adoptionCommitted.Count-eq1){$adoptionCommitted[0]}else{$null});Inventory=$Inventory}
}

function ConvertTo-SynapseLegacyRecoveryAttemptTerminalEvidence {
    param([Parameter(Mandatory=$true)]$State)
    return [ordered]@{attempt_index=[int]$State.Index;launch_capability_sha256=([string]$State.Attempt.Plan.launch_capability_sha256).ToUpperInvariant();intent=[string]$State.Intent;progress=[string]$State.ProgressSymbol;job_absent=(-not[bool]$State.JobPresent)}
}

function Resolve-SynapseAuthorityPhysicalRollbackPredecessor {
    param(
        [Parameter(Mandatory=$true)]$Record,
        $TaskInfrastructure=$null,
        [Parameter(Mandatory=$true)][string]$RuntimeBinDir,
        [Parameter(Mandatory=$true)][string]$RequestedLegacyTaskName,
        $DeclaredPredecessorReceipt=$null,
        $BorrowedLegacySupervisorLease=$null,
        [ValidateRange(30,420)][int]$TimeoutSeconds=120
    )
    $journal=$Record.Journal;$entry=$Record.Entry
    if($null-eq$journal -or $null-eq$journal.TornTail -or [string]$journal.State-notin@('armed','candidate_ready') -or [int]$journal.TornTail.Sequence-ne([int]$journal.Sequence+1)){Die "SYNAPSE_AUTHORITY_PHYSICAL_ROLLBACK_CUT_INVALID root=$($Record.Root)"}
    $initial=$journal.Initial
    if([string]$initial.schema-cne'synapse_broker_adoption_transaction/v4'){Die "SYNAPSE_AUTHORITY_PHYSICAL_ROLLBACK_SCHEMA_UNSUPPORTED root=$($Record.Root) schema=$($initial.schema)"}
    $declaredReceipt=$null
    if($null-ne$DeclaredPredecessorReceipt){
        $declaredReceipt=Assert-SynapseAuthorityPredecessorReceiptDescriptor -Receipt $DeclaredPredecessorReceipt -Context "physical_declared_predecessor_$($Record.Root)"
        $declaredPrefix=$declaredReceipt.journal.valid_prefix;$declaredCut=$declaredReceipt.journal.terminal_cut;$actualPrefix=$journal.Slots[-1]
        if((Get-SynapseNormalizedDirectoryPath -Path ([string]$declaredReceipt.journal.transaction_root))-ine(Get-SynapseNormalizedDirectoryPath -Path ([string]$Record.Root)) -or
           [string]$declaredReceipt.journal.transaction_root_file_id_128-ine[string]$Record.RootFileId128 -or
           [string]$declaredReceipt.journal.transaction_root_file_id_128-ine[string]$journal.RootChain[-1].file_id_128 -or
           [string]$declaredReceipt.journal.initial_static_transaction_sha256-ine[string]$initial.static_transaction_sha256 -or
           [int64]$declaredReceipt.authority_epoch-ne[int64]$initial.authority_epoch -or
           [string]$declaredPrefix.kind-cne'valid_slot' -or [int]$declaredPrefix.sequence-ne[int]$actualPrefix.Sequence -or [string]$declaredPrefix.state-cne[string]$actualPrefix.State -or [string]$declaredPrefix.leaf-cne[string]$actualPrefix.Leaf -or [string]$declaredPrefix.file_id_128-ine[string]$actualPrefix.FileId128 -or [string]$declaredPrefix.sha256-ine[string]$actualPrefix.RawSha256 -or [int64]$declaredPrefix.length-ne[int64]$actualPrefix.ByteLength -or
           [string]$declaredCut.kind-cne'torn_tail_physical' -or [int]$declaredCut.sequence-ne[int]$journal.TornTail.Sequence -or [string]$declaredCut.state-cne'torn' -or [string]$declaredCut.leaf-cne[string]$journal.TornTail.Leaf -or [string]$declaredCut.file_id_128-ine[string]$journal.TornTail.FileId128 -or [string]$declaredCut.sha256-ine[string]$journal.TornTail.Sha256 -or [int64]$declaredCut.length-ne[int64]$journal.TornTail.Length){
            Die "SYNAPSE_AUTHORITY_PHYSICAL_DECLARED_PREDECESSOR_CUT_DRIFT root=$($Record.Root)"
        }
    }
    if($null-ne$initial.predecessor_authority_receipt){
        if($null-ne$declaredReceipt){Die "SYNAPSE_AUTHORITY_PHYSICAL_FAILED_SUCCESSOR_DECLARED_AS_PREDECESSOR root=$($Record.Root)"}
        return [pscustomobject][ordered]@{Kind='failed_successor';PredecessorReceipt=(Assert-SynapseAuthorityPredecessorReceiptDescriptor -Receipt $initial.predecessor_authority_receipt -Context "physical_failed_successor_$($Record.Root)");PhysicalCut=$journal.TornTail}
    }
    $validated=$null;$snapshot=$null;$classification=$null;$proof=$null;$job=$null;$finalCut=$null
    try{
        $validated=Assert-SynapseAuthorityAdoptionInitialDescriptor -Initial $initial -TransactionRoot ([string]$entry.Path) -Allocation $journal.Allocation
        if([string]$initial.task_name-cne$RequestedLegacyTaskName){Die "SYNAPSE_AUTHORITY_PHYSICAL_ROLLBACK_TASK_MISMATCH root=$($Record.Root) requested=$RequestedLegacyTaskName actual=$($initial.task_name)"}
        if([string]$initial.prior_authority-ceq'absent'){
            if($null-eq$TaskInfrastructure){Die "SYNAPSE_AUTHORITY_PHYSICAL_FRESH_INFRASTRUCTURE_MISSING root=$($Record.Root)"}
            foreach($transition in @($validated.LegacyGateTransition,$validated.LegacyDenialTransition)){
                $state=Get-SynapsePhysicalRelativeState -ParentPath $transition.parent -ParentChain $transition.parent_chain -Leaf $transition.leaf
                if(-not(Test-SynapsePhysicalStateExact -State $state -ExpectedExists $true -ExpectedFileId128 $transition.post_file_id_128 -ExpectedSha256 $transition.post_sha256 -ExpectedLength $transition.post_length)){Die "SYNAPSE_AUTHORITY_PHYSICAL_FRESH_FLOOR_DRIFT root=$($Record.Root) path=$($transition.path)"}
                if($null-eq$transition.CanonicalLease){$transition.CanonicalLease=Open-SynapsePhysicalFileTransitionLease -ParentPath $transition.parent -ParentChain $transition.parent_chain -Leaf $transition.leaf -ExpectedFileId128 $transition.post_file_id_128 -ExpectedSha256 $transition.post_sha256 -ExpectedLength $transition.post_length -Context 'physical_fresh_predecessor'}
            }
            $inert=Assert-SynapseBrokerInertAtFreshMonotonicFloor -Layout (Get-SynapseAuthorityLayoutReadOnly -RuntimeBinDir $RuntimeBinDir -RequireAuthorityRoot) -Infrastructure $TaskInfrastructure -LegacyGateTransition $validated.LegacyGateTransition -LegacyDenialTransition $validated.LegacyDenialTransition -LegacyTaskName ([string]$initial.task_name) -Bind ([string]$initial.bind) -DbPath ([string]$initial.db_path) -TimeoutSeconds $TimeoutSeconds
            $e=[ordered]@{schema='synapse_authority_fresh_monotonic_floor/v1';legacy_gate=[ordered]@{path=[string]$validated.LegacyGateTransition.path;file_id_128=([string]$validated.LegacyGateTransition.post_file_id_128).ToUpperInvariant();sha256=([string]$validated.LegacyGateTransition.post_sha256).ToUpperInvariant();length=[int64]$validated.LegacyGateTransition.post_length};legacy_denial_stub=[ordered]@{path=[string]$validated.LegacyDenialTransition.path;file_id_128=([string]$validated.LegacyDenialTransition.post_file_id_128).ToUpperInvariant();sha256=([string]$validated.LegacyDenialTransition.post_sha256).ToUpperInvariant();length=[int64]$validated.LegacyDenialTransition.post_length};legacy_task_absent=$true;control_gate_absent=$true;roster_absent=$true;broker_task=(ConvertTo-SynapseCanonicalValue -Value $initial.broker_task);broker_task_inert=$true;action_process_count=0;target_process_count=0;listener_count=0;supervisor_process_count=0;recovery_job_count=0}
            $detail=[ordered]@{schema='synapse_authority_rollback/v2';mode='fresh_monotonic_floor';trigger='cold_predecision';primary_failure_sha256='';prior_authority='absent';authority_restored='fresh_monotonic_floor';broker_identity_sha256=([string]$initial.broker_identity_sha256).ToUpperInvariant();unknown_objects_preserved=$true;authority_evidence=$e}
        }else{
            $tokenRead=Read-SynapseSetupTokenForRestartGuard -TokenPath ([string]$initial.token_path);if(-not[bool]$tokenRead.Ok){Die "$($tokenRead.Code) reason=physical_rollback $($tokenRead.Detail)"}
            if($null-ne$BorrowedLegacySupervisorLease){$BorrowedLegacySupervisorLease.RequireExact('physical_rollback_borrowed_supervisor_entry')}
            $snapshot=ConvertTo-SynapseLegacySnapshotPersistedDescriptor -Snapshot $initial.legacy_task;$snapshot|Add-Member -NotePropertyName Leases -NotePropertyValue @(Open-SynapseLegacyAuthorityDescriptorLeases -Descriptor $snapshot -LegacyDenialTransition $validated.LegacyDenialTransition -BorrowedLegacySupervisorLease $BorrowedLegacySupervisorLease -ReadOnlyLegacySupervisor -Context 'physical_rollback') -Force
            $classification=Get-SynapseLegacyDirectRescueRecoveryClassification -Attempts @($validated.LegacyRescueLaunchAttempts) -TransactionRoot ([string]$Record.Root) -TransactionRootFileId128 ([string]$initial.transaction_root_file_id_128) -Allocation $journal.Allocation -PriorGenerationDescriptor $initial.prior_generation -Context 'physical_rollback'
            $compat=$classification.AttemptStates[0]
            $compatEvidence=[ordered]@{attempt_index=1;launch_capability_sha256=([string]$compat.Attempt.Plan.launch_capability_sha256).ToUpperInvariant();intent=[string]$compat.Intent;progress=[string]$compat.ProgressSymbol;keeper_prepared=$(if($null-ne$compat.KeeperReceipt){ConvertTo-SynapseLegacyDirectRescueProgressReference -Receipt $compat.KeeperReceipt}else{$null});action_prepared=$(if($null-ne$compat.ActionReceipt){ConvertTo-SynapseLegacyDirectRescueProgressReference -Receipt $compat.ActionReceipt}else{$null});final_transfer=$(if($null-ne$compat.FinalTransferReceipt){ConvertTo-SynapseLegacyDirectRescueProgressReference -Receipt $compat.FinalTransferReceipt}else{$null});job_absent=(-not[bool]$compat.JobPresent)}
            $direct=@($classification.AttemptStates|Where-Object{$_.Index-gt1 -and ($null-ne$_.FinalTransferReceipt -or ($_.ProgressSymbol-ceq'VVT' -and $_.JobPresent -and $_.JobProcessIds.Count-eq4))})
            if($direct.Count-eq1){
                if(-not[bool]$classification.CompatibilityComplete){Die "SYNAPSE_AUTHORITY_PHYSICAL_ROLLBACK_COMPATIBILITY_INCOMPLETE root=$($Record.Root) class=$($classification.Class)"}
                $selected=$direct[0];$finalKind=if($null-ne$selected.FinalTransferReceipt){'valid'}else{'torn'}
                $finalReference=if($finalKind-ceq'valid'){ConvertTo-SynapseLegacyDirectRescueProgressReference -Receipt $selected.FinalTransferReceipt}else{$finalCut=@($selected.Classifications|Where-Object{[string]$_.Phase-ceq'final_transfer'});if($finalCut.Count-ne1 -or [string]$finalCut[0].Kind-cne'torn' -or $null-eq$finalCut[0].RawLease){Die "SYNAPSE_AUTHORITY_PHYSICAL_DIRECT_TORN_CUT_INVALID root=$($Record.Root) attempt=$($selected.Index)"};$finalCut[0].RawLease.RequireExact('physical_direct_torn_before_proof');ConvertTo-SynapseLegacyDirectRescueProgressCutReference -Classification $finalCut[0]}
                $lineage=if($finalKind-ceq'valid'){ConvertTo-SynapseCanonicalValue -Value $selected.FinalTransferReceipt.Detail.evidence}elseif($null-ne$declaredReceipt){
                    if([string]$declaredReceipt.terminal_mode-cne'legacy_direct_recovery' -or [string]$declaredReceipt.authority_descriptor.final_transfer_kind-cne'torn' -or [int]$declaredReceipt.authority_descriptor.attempt_index-ne[int]$selected.Index){Die "SYNAPSE_AUTHORITY_PHYSICAL_DECLARED_DIRECT_ATTEMPT_DRIFT root=$($Record.Root) attempt=$($selected.Index)"}
                    ConvertTo-SynapseCanonicalValue -Value $declaredReceipt.authority_descriptor.lineage
                }else{$null}
                if($selected.JobPresent){
                    if($selected.JobProcessIds.Count-ne4){Die "SYNAPSE_AUTHORITY_PHYSICAL_DIRECT_JOB_CARDINALITY_INVALID root=$($Record.Root) count=$($selected.JobProcessIds.Count)"}
                    $job=$selected.Job;$selected.Job=$null;$selected.JobPresent=$false
                    $proof=Wait-SynapseLegacyDirectRescueRecoveryJobOperational -JobOwner $job -JobName ([string]$selected.Attempt.Plan.recovery_job.name) -LegacySnapshot $snapshot -PriorGeneration $validated.PriorGeneration -KeeperContract $selected.Attempt.Plan.keeper -ExpectedRemoteJobHandleValue ([int64]$selected.KeeperReceipt.Detail.remote_job_handle_value) -ExpectedSessionId ([int]$selected.ActionReceipt.Detail.session_id) -Bind ([string]$initial.bind) -DbPath ([string]$initial.db_path) -ProfilesDir ([string]$validated.PriorGeneration.RosterPayload.profiles_dir) -Token ([string]$tokenRead.Token) -Context 'physical_direct_predecessor' -TimeoutSeconds $TimeoutSeconds
                    if($null-ne$lineage -and (Get-SynapseCanonicalJson -Value $proof.Lineage)-cne(Get-SynapseCanonicalJson -Value $lineage)){Die "SYNAPSE_AUTHORITY_PHYSICAL_DIRECT_LINEAGE_DRIFT root=$($Record.Root)"}
                    if($finalKind-ceq'torn'){
                        if($null-eq$lineage){$lineage=ConvertTo-SynapseCanonicalValue -Value $proof.Lineage}
                        $finalCut[0].RawLease.RequireExact('physical_direct_torn_after_proof')
                    }
                }else{
                    if($finalKind-cne'valid' -and $null-eq$declaredReceipt){Die "SYNAPSE_AUTHORITY_PHYSICAL_DIRECT_TORN_JOB_ABSENT root=$($Record.Root) attempt=$($selected.Index)"}
                    [void](Assert-SynapseLegacyDirectRescueRecordedLineageGone -Lineage $lineage -Context 'physical_direct_scheduler_fallback_recorded_lineage')
                    $fallback=Get-SynapseLegacyPriorAuthorityOperationalClassification -LegacySnapshot $snapshot -PriorGeneration $validated.PriorGeneration -Bind ([string]$initial.bind) -DbPath ([string]$initial.db_path) -Token ([string]$tokenRead.Token) -LegacyDenialTransition $validated.LegacyDenialTransition -Context 'physical_direct_scheduler_fallback'
                    if([string]$fallback.State-cne'scheduler_operational'){Die "SYNAPSE_AUTHORITY_PHYSICAL_DIRECT_AUTHORITY_ABSENT root=$($Record.Root)"}
                }
                $e=New-SynapseLegacyDirectRollbackAuthorityEvidence -Selected $selected -Compatibility $compatEvidence -FinalTransferKind $finalKind -FinalTransferReference $finalReference -Lineage $lineage -Classification $classification -Context 'physical_direct_terminal_evidence'
                $detail=[ordered]@{schema='synapse_authority_rollback/v2';mode='legacy_direct_recovery';trigger='cold_predecision';primary_failure_sha256='';prior_authority='legacy';authority_restored='legacy_direct_recovery';broker_identity_sha256=([string]$initial.broker_identity_sha256).ToUpperInvariant();unknown_objects_preserved=$true;authority_evidence=$e}
            }elseif($direct.Count-eq0){
                if(@($classification.AttemptStates|Where-Object{$_.Index-gt1 -and ($_.JobPresent -or $_.Intent-ceq'C')}).Count-ne0){Die "SYNAPSE_AUTHORITY_PHYSICAL_PRIOR_RECOVERY_STATE_ACTIVE root=$($Record.Root)"}
                $prior=Get-SynapseLegacyPriorAuthorityOperationalClassification -LegacySnapshot $snapshot -PriorGeneration $validated.PriorGeneration -Bind ([string]$initial.bind) -DbPath ([string]$initial.db_path) -Token ([string]$tokenRead.Token) -LegacyDenialTransition $validated.LegacyDenialTransition -Context 'physical_prior_predecessor'
                if([string]$prior.State-cne'scheduler_operational'){Die "SYNAPSE_AUTHORITY_PHYSICAL_PRIOR_NOT_OPERATIONAL root=$($Record.Root) state=$($prior.State)"}
                $taskRuntime=Read-SynapseLegacyDirectRescueTaskRuntimeState -LegacySnapshot $snapshot -Context 'physical_prior_predecessor'
                $e=[ordered]@{schema='synapse_authority_legacy_prior_unchanged/v2';legacy_task=(ConvertTo-SynapseLegacySnapshotPersistedDescriptor -Snapshot $initial.legacy_task);task_runtime=(ConvertTo-SynapseCanonicalValue -Value $taskRuntime);legacy_task_unchanged=$true;health_pid=[int]$prior.Health.pid;tool_count=[int]$prior.ToolSurface.tool_count;tool_surface_sha256=([string]$prior.ToolSurface.tool_surface_sha256).ToUpperInvariant();listener_count=1;compatibility=$compatEvidence;recovery_attempts=@($classification.AttemptStates|Where-Object{$_.Index-gt1}|ForEach-Object{ConvertTo-SynapseLegacyRecoveryAttemptTerminalEvidence -State $_})}
                $detail=[ordered]@{schema='synapse_authority_rollback/v2';mode='legacy_prior_unchanged';trigger='cold_predecision';primary_failure_sha256='';prior_authority='legacy';authority_restored='legacy_prior_unchanged';broker_identity_sha256=([string]$initial.broker_identity_sha256).ToUpperInvariant();unknown_objects_preserved=$true;authority_evidence=$e}
            }else{Die "SYNAPSE_AUTHORITY_PHYSICAL_DIRECT_ATTEMPT_AMBIGUOUS root=$($Record.Root) count=$($direct.Count)"}
        }
        $terminal=[pscustomobject][ordered]@{Kind='torn_tail_physical';Journal=$journal;Detail=$detail;ValidPrefix=$journal.Slots[-1];TerminalCut=$journal.TornTail}
        $predecessor=New-SynapseAuthorityPhysicalRollbackPredecessor -Entry $entry -TerminalResult $terminal -Validated $validated
        $receipt=New-SynapseAuthorityPredecessorReceipt -Predecessor $predecessor
        if($null-ne$declaredReceipt -and (Get-SynapseCanonicalJson -Value $receipt)-cne(Get-SynapseCanonicalJson -Value $declaredReceipt)){
            $runtimeEquivalent=$false
            if([string]$receipt.terminal_mode-ceq'legacy_prior_unchanged' -and [string]$declaredReceipt.terminal_mode-ceq'legacy_prior_unchanged'){
                $actualEvidence=$receipt.authority_descriptor;$declaredEvidence=$declaredReceipt.authority_descriptor
                $actualRuntime=$actualEvidence.task_runtime;$declaredRuntime=$declaredEvidence.task_runtime
                $runtimeEquivalent=(
                    [string]$receipt.schema-ceq[string]$declaredReceipt.schema -and [int64]$receipt.authority_epoch-eq[int64]$declaredReceipt.authority_epoch -and
                    (Get-SynapseCanonicalJson -Value $receipt.journal)-ceq(Get-SynapseCanonicalJson -Value $declaredReceipt.journal) -and
                    [string]$actualEvidence.schema-ceq[string]$declaredEvidence.schema -and [bool]$actualEvidence.legacy_task_unchanged -and [bool]$declaredEvidence.legacy_task_unchanged -and
                    (Get-SynapseCanonicalJson -Value $actualEvidence.legacy_task)-ceq(Get-SynapseCanonicalJson -Value $declaredEvidence.legacy_task) -and
                    (Get-SynapseCanonicalJson -Value $actualEvidence.compatibility)-ceq(Get-SynapseCanonicalJson -Value $declaredEvidence.compatibility) -and
                    (Get-SynapseCanonicalJson -Value @($actualEvidence.recovery_attempts))-ceq(Get-SynapseCanonicalJson -Value @($declaredEvidence.recovery_attempts)) -and
                    [int]$actualEvidence.tool_count-eq[int]$declaredEvidence.tool_count -and [string]$actualEvidence.tool_surface_sha256-ieq[string]$declaredEvidence.tool_surface_sha256 -and
                    [int]$actualEvidence.listener_count-eq1 -and [int]$declaredEvidence.listener_count-eq1 -and [int]$actualEvidence.health_pid-gt0 -and [int]$declaredEvidence.health_pid-gt0 -and
                    [string]$actualRuntime.Schema-ceq'synapse_legacy_direct_rescue_task_runtime/v1' -and [string]$declaredRuntime.Schema-ceq'synapse_legacy_direct_rescue_task_runtime/v1' -and
                    [string]$actualRuntime.TaskName-ceq[string]$declaredRuntime.TaskName -and [int]$actualRuntime.State-in@(3,4) -and [int]$declaredRuntime.State-in@(3,4) -and
                    [int]$actualRuntime.InstanceCount-ge0 -and [int]$actualRuntime.InstanceCount-le4 -and [int]$declaredRuntime.InstanceCount-ge0 -and [int]$declaredRuntime.InstanceCount-le4
                )
            }
            if(-not$runtimeEquivalent){Die "SYNAPSE_AUTHORITY_PHYSICAL_DECLARED_PREDECESSOR_RECEIPT_DRIFT root=$($Record.Root) mode=$($receipt.terminal_mode)"}
            # Runtime PID/task timestamps are deliberately not allowed to mint a
            # new causal receipt.  The successor remains bound to the exact
            # receipt it declared before mutation.
            $receipt=$declaredReceipt
        }
        if($null-ne$finalCut -and @($finalCut).Count-eq1 -and [string]$finalCut[0].Kind-ceq'torn' -and $null-ne$finalCut[0].RawLease){$finalCut[0].RawLease.RequireExact('physical_direct_torn_after_predecessor_receipt')}
        return [pscustomobject][ordered]@{Kind='predecessor';Predecessor=$predecessor;PredecessorReceipt=$receipt;PhysicalCut=$journal.TornTail}
    }finally{
        Close-SynapseLegacyDirectRescueOperationalProof -Proof $proof -Context 'physical_rollback'
        if($null-ne$job){try{$job.Dispose()}catch{[Environment]::FailFast('SYNAPSE_AUTHORITY_PHYSICAL_ROLLBACK_JOB_RELEASE_UNPROVEN',$_.Exception)}}
        Close-SynapseLegacyDirectRescueRecoveryClassification -Classification $classification
        if($null-ne$snapshot){Close-SynapseLegacyAuthoritySnapshotLeases -Snapshot $snapshot}
        if($null-ne$validated){Close-SynapseAuthorityControlTransitionLeases -Transitions @($validated.ControlGateTransition,$validated.ActiveRosterTransition,$validated.ParkedRosterTransition,$validated.LegacyMalformedGateTransition,$validated.LegacyDenialTransition,$validated.LegacyGateTransition);Close-SynapseLegacyDenialGateAbsenceLease -AbsencePlan $validated.LegacyGateAbsence}
    }
}

function Assert-SynapseGlobalAuthorityPredecessorLive {
    param(
        [Parameter(Mandatory=$true)]$Record,
        $TaskInfrastructure=$null,
        [Parameter(Mandatory=$true)][string]$RuntimeBinDir,
        [Parameter(Mandatory=$true)][string]$RequestedLegacyTaskName,
        [uint64[]]$ExcludedProcessIds=@(),
        $BorrowedLegacySupervisorLease=$null,
        [ValidateRange(30,420)][int]$TimeoutSeconds=120
    )
    if($null-eq$Record.Journal -or $null-eq$Record.Entry){Die "SYNAPSE_GLOBAL_PREDECESSOR_JOURNAL_MISSING root=$($Record.Root)"}
    $layout=Get-SynapseAuthorityLayoutReadOnly -RuntimeBinDir $RuntimeBinDir -RequireAuthorityRoot
    $predecessor=$null;$snapshot=$null;$classification=$null;$proof=$null
    try{
        $predecessor=if($null-ne$Record.RolledBackPredecessor -and $null-ne$Record.RolledBackPredecessor.PSObject.Properties['PhysicalRollback'] -and [bool]$Record.RolledBackPredecessor.PhysicalRollback){$Record.RolledBackPredecessor}else{Assert-SynapseAuthorityRolledBackPredecessor -Layout $layout -Entry $Record.Entry -Journal $Record.Journal}
        if([string]$predecessor.Mode-cne[string]$Record.PredecessorReceipt.terminal_mode){Die "SYNAPSE_GLOBAL_PREDECESSOR_MODE_DRIFT root=$($Record.Root) expected=$($Record.PredecessorReceipt.terminal_mode) actual=$($predecessor.Mode)"}
        $initial=$Record.Journal.Initial;$validated=$predecessor.Validated;$e=$predecessor.Detail.authority_evidence
        if($null-eq$validated -or $null-eq$validated.PSObject.Properties['LegacyRescueLaunchAttempts'] -or @($validated.LegacyRescueLaunchAttempts).Count-ne4){
            # A physically reconstructed rollback descriptor intentionally does
            # not retain runtime transition objects.  Rehydrate those objects
            # from the immutable slot-1/allocation pair before classifying its
            # recovery attempts, and attach the owner so the common finally
            # path proves every acquired lease closed.
            $validated=Assert-SynapseAuthorityAdoptionInitialDescriptor -Initial $initial -TransactionRoot ([string]$Record.Root) -Allocation $Record.Journal.Allocation
            if($null-eq$predecessor.PSObject.Properties['Validated']){$predecessor|Add-Member -NotePropertyName Validated -NotePropertyValue $validated}else{$predecessor.Validated=$validated}
        }
        $recoveryAttemptCount=@($validated.LegacyRescueLaunchAttempts).Count
        if([string]$predecessor.Mode-ceq'fresh_monotonic_floor'){
            if($recoveryAttemptCount-ne0){Die "SYNAPSE_GLOBAL_FRESH_PREDECESSOR_RECOVERY_ATTEMPTS_UNEXPECTED root=$($Record.Root) count=$recoveryAttemptCount"}
        }elseif($recoveryAttemptCount-ne4){Die "SYNAPSE_GLOBAL_PREDECESSOR_RECOVERY_ATTEMPTS_MISSING root=$($Record.Root) count=$recoveryAttemptCount"}
        if([string]$initial.task_name-cne$RequestedLegacyTaskName){Die "SYNAPSE_GLOBAL_PREDECESSOR_LEGACY_TASK_NAME_MISMATCH root=$($Record.Root) requested=$RequestedLegacyTaskName actual=$($initial.task_name)"}
        if([string]$predecessor.Mode-ceq'fresh_monotonic_floor'){
            if($null-eq$TaskInfrastructure){Die "SYNAPSE_GLOBAL_PREDECESSOR_BROKER_TASK_INFRASTRUCTURE_MISSING root=$($Record.Root)"}
            foreach($transition in @($validated.LegacyGateTransition,$validated.LegacyDenialTransition)){
                $state=Get-SynapsePhysicalRelativeState -ParentPath $transition.parent -ParentChain $transition.parent_chain -Leaf $transition.leaf
                if(-not(Test-SynapsePhysicalStateExact -State $state -ExpectedExists $true -ExpectedFileId128 $transition.post_file_id_128 -ExpectedSha256 $transition.post_sha256 -ExpectedLength $transition.post_length)){Die "SYNAPSE_GLOBAL_FRESH_PREDECESSOR_FLOOR_DRIFT root=$($Record.Root) path=$($transition.path)"}
                if($null-eq$transition.CanonicalLease){$transition.CanonicalLease=Open-SynapsePhysicalFileTransitionLease -ParentPath $transition.parent -ParentChain $transition.parent_chain -Leaf $transition.leaf -ExpectedFileId128 $transition.post_file_id_128 -ExpectedSha256 $transition.post_sha256 -ExpectedLength $transition.post_length -Context 'global_fresh_predecessor'}
            }
            $inert=Assert-SynapseBrokerInertAtFreshMonotonicFloor -Layout $layout -Infrastructure $TaskInfrastructure -LegacyGateTransition $validated.LegacyGateTransition -LegacyDenialTransition $validated.LegacyDenialTransition -LegacyTaskName ([string]$initial.task_name) -Bind ([string]$initial.bind) -DbPath ([string]$initial.db_path) -TimeoutSeconds $TimeoutSeconds
            return [pscustomobject][ordered]@{Mode='fresh_monotonic_floor';Predecessor=$predecessor;Proof=$inert;Authority='fresh_floor'}
        }
        $tokenRead=Read-SynapseSetupTokenForRestartGuard -TokenPath ([string]$initial.token_path)
        if(-not[bool]$tokenRead.Ok){Die "$($tokenRead.Code) reason=global_predecessor_live $($tokenRead.Detail)"}
        # Runtime lease ownership must never pollute the immutable slot-1
        # descriptor that later validators canonicalize.  Materialize a fresh
        # persisted-only object before attaching process-local handles.
        $snapshot=ConvertTo-SynapseLegacySnapshotPersistedDescriptor -Snapshot $initial.legacy_task
        if($null-ne$BorrowedLegacySupervisorLease){
            $BorrowedLegacySupervisorLease.RequireExact('global_predecessor_borrowed_supervisor_entry')
        }
        try{
            $snapshot|Add-Member -NotePropertyName Leases -NotePropertyValue @(Open-SynapseLegacyAuthorityDescriptorLeases -Descriptor $snapshot -LegacyDenialTransition $validated.LegacyDenialTransition -BorrowedLegacySupervisorLease $BorrowedLegacySupervisorLease -ReadOnlyLegacySupervisor -Context 'global_predecessor') -Force
        }catch{
            $callPath=@(Get-PSCallStack|ForEach-Object{"$($_.FunctionName)@$($_.ScriptLineNumber)"})-join' <- '
            Write-Warning "SYNAPSE_GLOBAL_PREDECESSOR_DESCRIPTOR_LEASE_FAILED borrowed_supervisor=$($null-ne$BorrowedLegacySupervisorLease) call_path=[$callPath] error=$($_.Exception.Message)"
            Die "SYNAPSE_GLOBAL_PREDECESSOR_DESCRIPTOR_LEASE_FAILED borrowed_supervisor=$($null-ne$BorrowedLegacySupervisorLease) call_path=[$callPath] error=$($_.Exception.Message)"
        }
        $classification=Get-SynapseLegacyDirectRescueRecoveryClassification -Attempts @($validated.LegacyRescueLaunchAttempts) -TransactionRoot ([string]$Record.Root) -TransactionRootFileId128 ([string]$initial.transaction_root_file_id_128) -Allocation $Record.Journal.Allocation -PriorGenerationDescriptor $initial.prior_generation -Context 'global_predecessor'
        if([string]$predecessor.Mode-ceq'legacy_prior_unchanged'){
            if(@($classification.AttemptStates|Where-Object{$_.Index-gt1 -and $_.JobPresent}).Count-ne0){Die "SYNAPSE_GLOBAL_LEGACY_PRIOR_PREDECESSOR_RECOVERY_STATE_INVALID root=$($Record.Root) class=$($classification.Class)"}
            $prior=Get-SynapseLegacyPriorAuthorityOperationalClassification -LegacySnapshot $snapshot -PriorGeneration $validated.PriorGeneration -Bind ([string]$initial.bind) -DbPath ([string]$initial.db_path) -Token ([string]$tokenRead.Token) -LegacyDenialTransition $validated.LegacyDenialTransition -ExcludedProcessIds $ExcludedProcessIds -Context 'global_legacy_prior_predecessor'
            $taskRuntime=Read-SynapseLegacyDirectRescueTaskRuntimeState -LegacySnapshot $snapshot -Context 'global_legacy_prior_predecessor'
            if([string]$prior.State-cne'scheduler_operational' -or [int]$prior.ToolSurface.tool_count-ne[int]$e.tool_count -or [string]$prior.ToolSurface.tool_surface_sha256-ine[string]$e.tool_surface_sha256 -or [string]$taskRuntime.TaskName-cne[string]$e.task_runtime.TaskName -or [int]$taskRuntime.State-notin@(3,4)){Die "SYNAPSE_GLOBAL_LEGACY_PRIOR_PREDECESSOR_LIVE_DRIFT root=$($Record.Root)"}
            return [pscustomobject][ordered]@{Mode='legacy_prior_unchanged';Predecessor=$predecessor;Proof=$prior;Authority='scheduler'}
        }
        if([string]$predecessor.Mode-cne'legacy_direct_recovery'){Die "SYNAPSE_GLOBAL_PREDECESSOR_MODE_INVALID root=$($Record.Root) mode=$($predecessor.Mode)"}
        $selected=@($classification.AttemptStates|Where-Object{[int]$_.Index-eq[int]$e.attempt_index})
        if($selected.Count-ne1 -or ([string]$e.final_transfer_kind-ceq'valid' -and $null-eq$selected[0].FinalTransferReceipt) -or ([string]$e.final_transfer_kind-ceq'torn' -and [string]$selected[0].ProgressSymbol-cne'VVT')){Die "SYNAPSE_GLOBAL_DIRECT_PREDECESSOR_ATTEMPT_INVALID root=$($Record.Root) attempt=$($e.attempt_index) final=$($e.final_transfer_kind)"}
        if($selected[0].JobPresent){
            if($selected[0].JobProcessIds.Count-ne4){Die "SYNAPSE_GLOBAL_DIRECT_PREDECESSOR_JOB_CARDINALITY_INVALID root=$($Record.Root) count=$($selected[0].JobProcessIds.Count)"}
            $job=$selected[0].Job;$selected[0].Job=$null;$selected[0].JobPresent=$false
            try{
                $proof=Wait-SynapseLegacyDirectRescueRecoveryJobOperational -JobOwner $job -JobName ([string]$selected[0].Attempt.Plan.recovery_job.name) -LegacySnapshot $snapshot -PriorGeneration $validated.PriorGeneration -KeeperContract $selected[0].Attempt.Plan.keeper -ExpectedRemoteJobHandleValue ([int64]$selected[0].KeeperReceipt.Detail.remote_job_handle_value) -ExpectedSessionId ([int]$selected[0].ActionReceipt.Detail.session_id) -Bind ([string]$initial.bind) -DbPath ([string]$initial.db_path) -ProfilesDir ([string]$validated.PriorGeneration.RosterPayload.profiles_dir) -Token ([string]$tokenRead.Token) -Context 'global_direct_predecessor' -TimeoutSeconds $TimeoutSeconds
                if((Get-SynapseCanonicalJson -Value $proof.Lineage)-cne(Get-SynapseCanonicalJson -Value $e.lineage) -or (@($proof.ProcessIds|Sort-Object)-join ',')-cne(@($e.recovery_job.process_ids|ForEach-Object{[uint64]$_}|Sort-Object)-join ',')){Die "SYNAPSE_GLOBAL_DIRECT_PREDECESSOR_LINEAGE_DRIFT root=$($Record.Root)"}
                return [pscustomobject][ordered]@{Mode='legacy_direct_recovery';Predecessor=$predecessor;Proof=$proof;Authority='recovery_job'}
            }finally{if($null-ne$job){try{$job.Dispose()}catch{[Environment]::FailFast('SYNAPSE_GLOBAL_DIRECT_PREDECESSOR_JOB_RELEASE_UNPROVEN',$_.Exception)}}}
        }
        if(@($classification.AttemptStates|Where-Object{$_.Index-gt1 -and $_.JobPresent}).Count-ne0){Die "SYNAPSE_GLOBAL_DIRECT_PREDECESSOR_JOB_SET_AMBIGUOUS root=$($Record.Root)"}
        [void](Assert-SynapseLegacyDirectRescueRecordedLineageGone -Lineage $e.lineage -Context 'global_direct_predecessor_recorded_lineage')
        $fallback=Get-SynapseLegacyPriorAuthorityOperationalClassification -LegacySnapshot $snapshot -PriorGeneration $validated.PriorGeneration -Bind ([string]$initial.bind) -DbPath ([string]$initial.db_path) -Token ([string]$tokenRead.Token) -LegacyDenialTransition $validated.LegacyDenialTransition -ExcludedProcessIds $ExcludedProcessIds -Context 'global_direct_predecessor_scheduler_fallback'
        if([string]$fallback.State-cne'scheduler_operational' -or [int]$fallback.ToolSurface.tool_count-ne[int]$e.tool_count -or [string]$fallback.ToolSurface.tool_surface_sha256-ine[string]$e.tool_surface_sha256){Die "SYNAPSE_GLOBAL_DIRECT_PREDECESSOR_AUTHORITY_ABSENT root=$($Record.Root)"}
        return [pscustomobject][ordered]@{Mode='legacy_direct_recovery';Predecessor=$predecessor;Proof=$fallback;Authority='scheduler_fallback'}
    }finally{
        Close-SynapseLegacyDirectRescueOperationalProof -Proof $proof -Context 'global_predecessor'
        Close-SynapseLegacyDirectRescueRecoveryClassification -Classification $classification
        if($null-ne$snapshot){Close-SynapseLegacyAuthoritySnapshotLeases -Snapshot $snapshot}
        if($null-ne$predecessor -and $null-ne$predecessor.Validated){Close-SynapseAuthorityControlTransitionLeases -Transitions @($predecessor.Validated.ControlGateTransition,$predecessor.Validated.ActiveRosterTransition,$predecessor.Validated.ParkedRosterTransition,$predecessor.Validated.LegacyMalformedGateTransition,$predecessor.Validated.LegacyDenialTransition,$predecessor.Validated.LegacyGateTransition);Close-SynapseLegacyDenialGateAbsenceLease -AbsencePlan $predecessor.Validated.LegacyGateAbsence}
    }
}

function Assert-SynapseGlobalCommittedAuthorityPreflight {
    param(
        [Parameter(Mandatory=$true)]$Inventory,
        $TaskInfrastructure,
        [Parameter(Mandatory=$true)][string]$RuntimeBinDir,
        [Parameter(Mandatory=$true)][string]$RequestedLegacyTaskName,
        [switch]$DecommissionStructuralOnly
    )
    # A valid successor marker is the authoritative REDO decision even while
    # enough predecessor journal bytes remain for ordinary classification.
    # Promote both readable subsets and unreadable residues before owner
    # partitioning so resumption always consumes the marker's frozen roster.
    foreach($residue in @($Inventory.Adoptions|Where-Object{[string]$_.RecordKind-notin@('authority_failed_successor_cleanup_tail','authority_committed_predecessor_cleanup_residue')})){
        $matches=@()
        foreach($possibleSuccessor in @($Inventory.Adoptions|Where-Object{$_.RecordKind-ceq'journal' -and [string]$_.State-ceq'commit_decided' -and $null-ne$_.Initial.predecessor_authority_receipt})){
            $receipt=Assert-SynapseAuthorityPredecessorReceiptDescriptor -Receipt $possibleSuccessor.Initial.predecessor_authority_receipt -Context "global_cleanup_residue_$($possibleSuccessor.Root)"
            if((Get-SynapseNormalizedDirectoryPath -Path ([string]$receipt.journal.transaction_root))-ieq(Get-SynapseNormalizedDirectoryPath -Path ([string]$residue.Root))){$matches+=,[pscustomobject][ordered]@{Record=$possibleSuccessor;Receipt=$receipt}}
        }
        if($matches.Count-gt1){Die "SYNAPSE_GLOBAL_AUTHORITY_CLEANUP_AUTHORITY_AMBIGUOUS root=$($residue.Root) successors=$($matches.Count)"}
        if($matches.Count-eq0){
            if([string]$residue.RecordKind-ceq'authority_unreadable_cleanup_candidate'){Die "SYNAPSE_GLOBAL_AUTHORITY_UNREADABLE_CLEANUP_AUTHORITY_MISSING root=$($residue.Root) successors=0 read_error=$($residue.ReadError)"}
            continue
        }
        if([string]$matches[0].Receipt.journal.transaction_root_file_id_128-ine[string]$residue.RootFileId128){Die "SYNAPSE_GLOBAL_AUTHORITY_UNREADABLE_CLEANUP_ROOT_DRIFT root=$($residue.Root) expected=$($matches[0].Receipt.journal.transaction_root_file_id_128) actual=$($residue.RootFileId128)"}
        $authority=New-SynapseAuthorityCommittedSuccessorPredecessorCleanupAuthorityFromReceipt -PredecessorReceipt $matches[0].Receipt -SuccessorRecord $matches[0].Record -Context "global_cleanup_residue_$($residue.Root)"
        $markerSet=Get-SynapseAuthorityCommittedPredecessorCleanupMarkerSet -SuccessorRecord $matches[0].Record -CleanupAuthority $authority -Context "global_cleanup_residue_$($residue.Root)"
        if($null-eq$markerSet.Valid){
            if([string]$residue.RecordKind-ceq'authority_unreadable_cleanup_candidate'){Die "SYNAPSE_GLOBAL_AUTHORITY_UNREADABLE_CLEANUP_MARKER_MISSING root=$($residue.Root) read_error=$($residue.ReadError)"}
            continue
        }
        if((Get-SynapseNormalizedDirectoryPath -Path ([string]$markerSet.Valid.Payload.predecessor_root))-ine(Get-SynapseNormalizedDirectoryPath -Path ([string]$residue.Root)) -or [string]$markerSet.Valid.Payload.predecessor_root_file_id_128-ine[string]$residue.RootFileId128){Die "SYNAPSE_GLOBAL_AUTHORITY_UNREADABLE_CLEANUP_MARKER_ROOT_DRIFT root=$($residue.Root)"}
        $residue.RecordKind='authority_committed_predecessor_cleanup_residue';$residue.State='cleanup_ready';$residue.EffectiveState='rolled_back';$residue.PredecessorReceipt=$matches[0].Receipt
        $residue|Add-Member -NotePropertyName CleanupMarker -NotePropertyValue $markerSet.Valid -Force
        $residue|Add-Member -NotePropertyName Successor -NotePropertyValue $matches[0].Record -Force
        $residue|Add-Member -NotePropertyName ReadError -NotePropertyValue '' -Force
        $residue|Add-Member -NotePropertyName PhysicalRollbackCandidate -NotePropertyValue $null -Force
        $residue|Add-Member -NotePropertyName RolledBackPredecessor -NotePropertyValue $null -Force
        $residue|Add-Member -NotePropertyName FailedSuccessor -NotePropertyValue $null -Force
    }
    foreach($candidate in @($Inventory.Adoptions|Where-Object{$null-ne$_.PhysicalRollbackCandidate})){
        $declaredMatches=@()
        foreach($possibleSuccessor in @($Inventory.Adoptions|Where-Object{$_.RecordKind-ceq'journal' -and $null-ne$_.Initial -and $null-ne$_.Initial.PSObject.Properties['predecessor_authority_receipt'] -and $null-ne$_.Initial.predecessor_authority_receipt})){
            if((Get-SynapseNormalizedDirectoryPath -Path ([string]$possibleSuccessor.Root))-ieq(Get-SynapseNormalizedDirectoryPath -Path ([string]$candidate.Root))){continue}
            $possibleReceipt=Assert-SynapseAuthorityPredecessorReceiptDescriptor -Receipt $possibleSuccessor.Initial.predecessor_authority_receipt -Context "global_physical_declared_predecessor_$($possibleSuccessor.Root)"
            if((Get-SynapseNormalizedDirectoryPath -Path ([string]$possibleReceipt.journal.transaction_root))-ieq(Get-SynapseNormalizedDirectoryPath -Path ([string]$candidate.Root))){$declaredMatches+=,[pscustomobject][ordered]@{Record=$possibleSuccessor;Receipt=$possibleReceipt}}
        }
        $declaredReceipt=$null;$declaredReceiptJson=''
        foreach($declaredMatch in $declaredMatches){
            $candidateReceiptJson=Get-SynapseCanonicalJson -Value $declaredMatch.Receipt
            if($null-eq$declaredReceipt){$declaredReceipt=$declaredMatch.Receipt;$declaredReceiptJson=$candidateReceiptJson}
            elseif($candidateReceiptJson-cne$declaredReceiptJson){Die "SYNAPSE_GLOBAL_PHYSICAL_PREDECESSOR_DECLARATION_AMBIGUOUS root=$($candidate.Root) successors=$(@($declaredMatches.Record.Root)-join',')"}
        }
        if($null-ne$declaredReceipt){
            # A successor's sealed predecessor receipt is intentionally the
            # stable authority after that successor has displaced any of the
            # predecessor's canonical transition objects.  Re-running the
            # predecessor's live physical-cut validator here is contradictory:
            # it requires those canonical objects to still carry the older
            # FileIds even though the exact successor is allowed to replace
            # them.  Bind the receipt directly to the still-physical journal
            # prefix/torn cut below; successor recovery separately restores or
            # re-proves the predecessor before terminalizing.
            $declaredLiveError='superseded_by_declared_successor'
            # Once a crossbound successor has displaced the predecessor, the
            # predecessor cannot independently satisfy its old live-authority
            # proof.  Its durable successor receipt is the canonical stable
            # descriptor; bind that descriptor directly to the preserved
            # valid prefix and torn physical cut here.  The successor recovery
            # path must still restore/reprove it before a failed successor can
            # terminalize, while a committed successor may only REDO cleanup.
            $valid=$declaredReceipt.journal.valid_prefix;$terminal=$declaredReceipt.journal.terminal_cut;$tail=$candidate.Journal.TornTail
            $validSlots=@($candidate.Journal.Slots|Where-Object Sequence -EQ ([int]$valid.sequence))
            if((Get-SynapseNormalizedDirectoryPath -Path ([string]$declaredReceipt.journal.transaction_root))-ine(Get-SynapseNormalizedDirectoryPath -Path ([string]$candidate.Root)) -or
               [string]$declaredReceipt.journal.transaction_root_file_id_128-ine[string]$candidate.RootFileId128 -or [string]$candidate.Journal.Initial.static_transaction_sha256-ine[string]$declaredReceipt.journal.initial_static_transaction_sha256 -or
               [int64]$candidate.Journal.Initial.authority_epoch-ne[int64]$declaredReceipt.authority_epoch -or $validSlots.Count-ne1 -or
               [string]$validSlots[0].State-cne[string]$valid.state -or [string]$validSlots[0].Leaf-cne[string]$valid.leaf -or [string]$validSlots[0].FileId128-ine[string]$valid.file_id_128 -or [string]$validSlots[0].RawSha256-ine[string]$valid.sha256 -or [int64]$validSlots[0].ByteLength-ne[int64]$valid.length -or
               [string]$terminal.kind-cne'torn_tail_physical' -or $null-eq$tail -or [int]$tail.Sequence-ne[int]$terminal.sequence -or [string]$tail.Leaf-cne[string]$terminal.leaf -or [string]$tail.FileId128-ine[string]$terminal.file_id_128 -or [string]$tail.Sha256-ine[string]$terminal.sha256 -or [int64]$tail.Length-ne[int64]$terminal.length){
                Die "SYNAPSE_GLOBAL_DECLARED_PHYSICAL_PREDECESSOR_CUT_DRIFT root=$($candidate.Root) successor=$($declaredMatches[0].Record.Root) live_error=$declaredLiveError"
            }
            $candidate.RolledBackPredecessor=[pscustomobject][ordered]@{Mode=[string]$declaredReceipt.terminal_mode;Entry=$candidate.Entry;Journal=$candidate.Journal;Detail=[pscustomobject][ordered]@{authority_evidence=(ConvertTo-SynapseCanonicalValue -Value $declaredReceipt.authority_descriptor)};Validated=$null;PhysicalRollback=$true;DeclaredBySuccessor=$true}
            $candidate.PredecessorReceipt=$declaredReceipt;$candidate.EffectiveState='physical_rollback_predecessor';$candidate.PhysicalRollbackCandidate=$null
            continue
        }
        $resolved=Resolve-SynapseAuthorityPhysicalRollbackPredecessor -Record $candidate -TaskInfrastructure $TaskInfrastructure -RuntimeBinDir $RuntimeBinDir -RequestedLegacyTaskName $RequestedLegacyTaskName -DeclaredPredecessorReceipt $declaredReceipt
        if([string]$resolved.Kind-ceq'predecessor'){
            $candidate.RolledBackPredecessor=$resolved.Predecessor;$candidate.PredecessorReceipt=$resolved.PredecessorReceipt;$candidate.EffectiveState='physical_rollback_predecessor'
        }elseif([string]$resolved.Kind-ceq'failed_successor'){
            $candidate.FailedSuccessor=[pscustomobject][ordered]@{Mode='predecessor_restored';PhysicalRollback=$true;PhysicalCut=$resolved.PhysicalCut};$candidate.PredecessorReceipt=$resolved.PredecessorReceipt;$candidate.EffectiveState='physical_failed_successor'
        }else{Die "SYNAPSE_GLOBAL_PHYSICAL_ROLLBACK_CLASS_INVALID root=$($candidate.Root) kind=$($resolved.Kind)"}
        $candidate.PhysicalRollbackCandidate=$null
    }
    $committedTasks=@($Inventory.TaskEpochs|Where-Object{[string]$_.RecordKind -ceq 'journal' -and [string]$_.State -ceq 'commit_decided'})
    $committedAdoptions=@($Inventory.Adoptions|Where-Object{[string]$_.RecordKind -ceq 'journal' -and [string]$_.State -ceq 'commit_decided'})
    $liveAdoptions=@($Inventory.Adoptions|Where-Object{[string]$_.RecordKind-ceq'journal' -and [string]$_.State-in@('armed','candidate_ready') -and $null-eq$_.RolledBackPredecessor -and $null-eq$_.FailedSuccessor})
    $predecessors=@($Inventory.Adoptions|Where-Object{[string]$_.RecordKind-ceq'journal' -and $null-ne$_.RolledBackPredecessor})
    if($committedAdoptions.Count -gt 1 -or $liveAdoptions.Count-gt1 -or $predecessors.Count-gt1 -or ($committedAdoptions.Count+$liveAdoptions.Count)-gt1){Die "SYNAPSE_GLOBAL_COMMITTED_AUTHORITY_PREFLIGHT_AMBIGUOUS tasks=$($committedTasks.Count) adoptions=$($committedAdoptions.Count) live=$($liveAdoptions.Count) predecessors=$($predecessors.Count)"}
    if($committedTasks.Count -eq 0){
        if($committedAdoptions.Count -ne 0 -or $liveAdoptions.Count-ne0 -or $predecessors.Count-ne0){Die 'SYNAPSE_GLOBAL_COMMITTED_ADOPTION_WITHOUT_TASK_RECEIPT'}
        return [pscustomobject][ordered]@{Task=$null;Adoption=$null;Predecessor=$null;PredecessorProof=$null;ControlState='absent'}
    }
    if($null -eq $TaskInfrastructure){Die "SYNAPSE_GLOBAL_COMMITTED_TASK_LIVE_PREFLIGHT_MISSING root=$($committedTasks[0].Root)"}
    $orderedTasks=@($committedTasks|Sort-Object{[int64]$_.Initial.task_epoch})
    for($i=0;$i-lt$orderedTasks.Count;$i++){
        if([int64]$orderedTasks[$i].Initial.task_epoch-ne($i+1L)){Die "SYNAPSE_GLOBAL_COMMITTED_TASK_EPOCH_CHAIN_GAP root=$($orderedTasks[$i].Root) epoch=$($orderedTasks[$i].Initial.task_epoch) index=$i"}
        if($i-eq0){if($null-ne$orderedTasks[$i].Initial.predecessor_receipt){Die "SYNAPSE_GLOBAL_COMMITTED_TASK_FIRST_PREDECESSOR_INVALID root=$($orderedTasks[$i].Root)"}}
        elseif((Get-SynapseCanonicalJson -Value $orderedTasks[$i].Initial.predecessor_receipt)-cne(Get-SynapseCanonicalJson -Value (ConvertTo-SynapseBrokerTaskReceiptDescriptorFromJournal -Journal $orderedTasks[$i-1].Journal))){Die "SYNAPSE_GLOBAL_COMMITTED_TASK_PREDECESSOR_CHAIN_INVALID root=$($orderedTasks[$i].Root) epoch=$($orderedTasks[$i].Initial.task_epoch)"}
    }
    $taskMatches=@($orderedTasks|Where-Object{(Get-SynapseNormalizedDirectoryPath -Path ([string]$TaskInfrastructure.TaskReceipt.Root))-ieq(Get-SynapseNormalizedDirectoryPath -Path ([string]$_.Root))})
    if($taskMatches.Count-ne1){Die "SYNAPSE_GLOBAL_COMMITTED_TASK_RECEIPT_MISMATCH matches=$($taskMatches.Count) committed=$($orderedTasks.Count)"}
    $taskRecord=$taskMatches[0]
    $taskRecordIsLatest=((Get-SynapseNormalizedDirectoryPath -Path ([string]$taskRecord.Root))-ieq(Get-SynapseNormalizedDirectoryPath -Path ([string]$orderedTasks[-1].Root)))
    # A committed adoption can intentionally retain the broker process and
    # immutable task receipt from an older task epoch after a forward-only
    # task implementation rotation.  Ensure-SynapseBrokerAuthorityAdopted has
    # just proved the complete successor chain and the exact latest Scheduler
    # task before returning this historical infrastructure bundle.  Admit the
    # historical bundle only when the sole committed adoption below binds it;
    # without an adoption, the current task receipt must remain the newest.
    if(-not$taskRecordIsLatest-and$committedAdoptions.Count-ne1){Die "SYNAPSE_GLOBAL_COMMITTED_TASK_HISTORICAL_WITHOUT_ADOPTION root=$($taskRecord.Root) latest=$($orderedTasks[-1].Root) adoptions=$($committedAdoptions.Count)"}
    $taskReceiptRootFileId=([string]$TaskInfrastructure.TaskReceipt.RootFileId128).ToUpperInvariant()
    if($taskReceiptRootFileId-notmatch'^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'){$taskReceiptRootChain=@($TaskInfrastructure.TaskReceipt.RootChain);if($taskReceiptRootChain.Count){$taskReceiptRootFileId=([string]$taskReceiptRootChain[-1].file_id_128).ToUpperInvariant()}}
    if((Get-SynapseNormalizedDirectoryPath -Path ([string]$TaskInfrastructure.TaskReceipt.Root)) -ine (Get-SynapseNormalizedDirectoryPath -Path ([string]$taskRecord.Root)) -or
       $taskReceiptRootFileId -ine [string]$taskRecord.RootFileId128 -or
       [string]$TaskInfrastructure.TaskCapabilitySha256 -ine [string]$taskRecord.Initial.task_capability_sha256 -or
       [string]$TaskInfrastructure.TaskName -cne [string]$taskRecord.Initial.task.name){
        Die "SYNAPSE_GLOBAL_COMMITTED_TASK_LIVE_PREFLIGHT_CROSSBIND_INVALID root=$($taskRecord.Root) receipt_root=$($TaskInfrastructure.TaskReceipt.Root) task=$($TaskInfrastructure.TaskName) expected_task=$($taskRecord.Initial.task.name) receipt_root_file_id_128=$taskReceiptRootFileId expected_root_file_id_128=$($taskRecord.RootFileId128) receipt_capability=$($TaskInfrastructure.TaskCapabilitySha256) expected_capability=$($taskRecord.Initial.task_capability_sha256)"
    }
    foreach($record in @($Inventory.Probe)+@($Inventory.ApplicationV4)+@($Inventory.Operations)){
        if([string]$record.RecordKind -cne 'journal' -or $null -eq $record.Initial){continue}
        # A durable transaction may outlive a legitimate broker upgrade.  Its
        # immutable task descriptor is authority for recovering that historical
        # transaction; comparing it to the newly committed receipt makes every
        # crash-spanning upgrade unrecoverable.  Validate the complete sealed
        # historical shape/capability here.  Live mutation paths separately
        # crossbind the current receipt before creating new authority.
        [void](Assert-SynapseBrokerTaskDescriptorShape -Descriptor $record.Initial.broker_task -BrokerIdentitySha256 ([string]$record.Initial.broker_identity_sha256) -TaskCapabilitySha256 ([string]$record.Initial.broker_task_capability_sha256) -Context "global_$($record.Domain)_task_$($record.Root)")
    }
    $predecessorProof=$null
    if($predecessors.Count-eq1){
        $successor=@($committedAdoptions)+@($liveAdoptions)
        if($successor.Count-eq0){
            $predecessorProof=Assert-SynapseGlobalAuthorityPredecessorLive -Record $predecessors[0] -TaskInfrastructure $TaskInfrastructure -RuntimeBinDir $RuntimeBinDir -RequestedLegacyTaskName $RequestedLegacyTaskName
        }else{
            [void](Assert-SynapseAuthorityPredecessorSuccessorPair -PredecessorRecord $predecessors[0] -SuccessorInitial $successor[0].Initial -SuccessorRoot ([string]$successor[0].Root) -Context 'authority_global_preflight_pair')
            if([string]$successor[0].State-ceq'commit_decided'){
                # The committed-generation proof below binds the durable
                # decision to the exact canonical gate, denial stub, roster,
                # and control pair.  Until that proof completes, this value is
                # only a structural pairing result.
                $predecessorProof=[pscustomobject][ordered]@{Mode=[string]$predecessors[0].PredecessorReceipt.terminal_mode;Predecessor=$predecessors[0].RolledBackPredecessor;Proof=$null;Authority='committed_successor_pair_pending_live_proof'}
            }else{
                # The exact precommit successor is the only live mutation
                # authority and may already have displaced predecessor
                # canonical FileIds.  Do not re-run the predecessor's
                # standalone live proof against those successor-owned paths;
                # prove the successor's denial/rollback cut below instead.
                $predecessorLiveError='superseded_by_exact_crossbound_precommit_successor'
                if($null-eq$predecessorProof){
                    # A precommit successor may legitimately have parked a
                    # predecessor file, but that displacement is authoritative
                    # only after one of its exact denial controls is canonical.
                    # Merely possessing a crossbound receipt or staged bytes is
                    # not a physical ownership cut.
                    $successorValidated=$null
                    try{
                        $successorValidated=Assert-SynapseAuthorityAdoptionInitialDescriptor -Initial $successor[0].Initial -TransactionRoot ([string]$successor[0].Root) -Allocation $successor[0].Journal.Allocation -HistoricalMutableGeneration
                        $denialCut=Get-SynapseAuthorityControlTransitionPhysicalCut -Transition $successorValidated.LegacyDenialTransition -Context 'authority_global_preflight_successor_denial'
                        $positiveGateHeld=$false;$gateCut=$null;$gateCutError=''
                        try{
                            $gateCut=Get-SynapseAuthorityControlTransitionPhysicalCut -Transition $successorValidated.LegacyGateTransition -Context 'authority_global_preflight_successor_gate'
                            $positiveGateHeld=([string]$gateCut.PostLocation-ceq'canonical')
                        }catch{$gateCutError=$_.Exception.Message}
                        $denialStubHeld=([string]$denialCut.PostLocation-ceq'canonical')
                        if(-not$positiveGateHeld -and -not$denialStubHeld){
                            # A crash during failed-successor rollback can occur
                            # after both legacy denial controls were retired but
                            # before the predecessor roster was restored.  At
                            # that cut the legacy supervisor is still parked in
                            # its exact successor-owned stage, so the old task
                            # cannot launch, while the exact chained roster cut
                            # is sufficient for the rollback resolver to REDO.
                            # Admit only that complete immutable cut here; this
                            # is classification, never mutation or authority.
                            $activeStage=Get-SynapseAuthorityControlRootState -Transition $successorValidated.ActiveRosterTransition -Leaf $successorValidated.ActiveRosterTransition.stage_leaf
                            $activePark=Get-SynapseAuthorityControlRootState -Transition $successorValidated.ActiveRosterTransition -Leaf $successorValidated.ActiveRosterTransition.park_leaf
                            $activeDiscard=Get-SynapseAuthorityControlRootState -Transition $successorValidated.ActiveRosterTransition -Leaf $successorValidated.ActiveRosterTransition.discard_leaf
                            $activeCanonical=Get-SynapsePhysicalRelativeState -ParentPath $successorValidated.ActiveRosterTransition.parent -ParentChain $successorValidated.ActiveRosterTransition.parent_chain -Leaf $successorValidated.ActiveRosterTransition.leaf
                            $parkedStage=Get-SynapseAuthorityControlRootState -Transition $successorValidated.ParkedRosterTransition -Leaf $successorValidated.ParkedRosterTransition.stage_leaf
                            $parkedPark=Get-SynapseAuthorityControlRootState -Transition $successorValidated.ParkedRosterTransition -Leaf $successorValidated.ParkedRosterTransition.park_leaf
                            $parkedDiscard=Get-SynapseAuthorityControlRootState -Transition $successorValidated.ParkedRosterTransition -Leaf $successorValidated.ParkedRosterTransition.discard_leaf
                            $rollbackCutHeld=(
                                $null-ne$gateCut -and [string]$denialCut.PostLocation-ceq'discard' -and [string]$gateCut.PostLocation-ceq'discard' -and
                                -not$activeCanonical.Exists -and -not$activePark.Exists -and -not$activeDiscard.Exists -and
                                (Test-SynapsePhysicalStateExact -State $activeStage -ExpectedExists $true -ExpectedFileId128 $successorValidated.ActiveRosterTransition.post_file_id_128 -ExpectedSha256 $successorValidated.ActiveRosterTransition.post_sha256 -ExpectedLength $successorValidated.ActiveRosterTransition.post_length) -and
                                -not$parkedStage.Exists -and -not$parkedPark.Exists -and
                                (Test-SynapsePhysicalStateExact -State $parkedDiscard -ExpectedExists $true -ExpectedFileId128 $successorValidated.ParkedRosterTransition.post_file_id_128 -ExpectedSha256 $successorValidated.ParkedRosterTransition.post_sha256 -ExpectedLength $successorValidated.ParkedRosterTransition.post_length)
                            )
                            $lateRollbackCutHeld=(
                                $null-ne$gateCut -and [string]$denialCut.PostLocation-ceq'discard' -and [string]$gateCut.PostLocation-ceq'discard' -and
                                [string]$denialCut.PreLocation-ceq'canonical' -and [string]$gateCut.PreLocation-ceq'absent' -and
                                -not$activeCanonical.Exists -and -not$activeStage.Exists -and -not$activePark.Exists -and
                                (Test-SynapsePhysicalStateExact -State $activeDiscard -ExpectedExists $true -ExpectedFileId128 $successorValidated.ActiveRosterTransition.post_file_id_128 -ExpectedSha256 $successorValidated.ActiveRosterTransition.post_sha256 -ExpectedLength $successorValidated.ActiveRosterTransition.post_length) -and
                                -not$parkedStage.Exists -and -not$parkedPark.Exists -and
                                (Test-SynapsePhysicalStateExact -State $parkedDiscard -ExpectedExists $true -ExpectedFileId128 $successorValidated.ParkedRosterTransition.post_file_id_128 -ExpectedSha256 $successorValidated.ParkedRosterTransition.post_sha256 -ExpectedLength $successorValidated.ParkedRosterTransition.post_length)
                            )
                            $rollbackCutHeld=$rollbackCutHeld-or$lateRollbackCutHeld
                            if(-not$rollbackCutHeld){
                                Die "SYNAPSE_GLOBAL_PRECOMMIT_SUCCESSOR_DENIAL_CONTROL_NOT_HELD successor=$($successor[0].Root) predecessor_error=$predecessorLiveError gate_error=$gateCutError denial_pre=$($denialCut.PreLocation) denial_post=$($denialCut.PostLocation) gate_pre=$($gateCut.PreLocation) gate_post=$($gateCut.PostLocation)"
                            }
                            $predecessorProof=[pscustomobject][ordered]@{Mode=[string]$predecessors[0].PredecessorReceipt.terminal_mode;Predecessor=$predecessors[0].RolledBackPredecessor;Proof=[pscustomobject][ordered]@{PositiveGateHeld=$false;DenialStubHeld=$false;RollbackCutHeld=$true;DenialPostLocation=[string]$denialCut.PostLocation;GatePostLocation=[string]$gateCut.PostLocation};Authority='displaced_by_exact_crossbound_successor_rollback_cut'}
                        }else{
                            $predecessorProof=[pscustomobject][ordered]@{Mode=[string]$predecessors[0].PredecessorReceipt.terminal_mode;Predecessor=$predecessors[0].RolledBackPredecessor;Proof=[pscustomobject][ordered]@{PositiveGateHeld=$positiveGateHeld;DenialStubHeld=$denialStubHeld;RollbackCutHeld=$false;DenialPostLocation=[string]$denialCut.PostLocation};Authority='displaced_by_exact_crossbound_successor_denial_control'}
                        }
                    }finally{
                        if($null-ne$successorValidated){
                            Close-SynapseAuthorityControlTransitionLeases -Transitions @($successorValidated.ControlGateTransition,$successorValidated.ActiveRosterTransition,$successorValidated.ParkedRosterTransition,$successorValidated.LegacyMalformedGateTransition,$successorValidated.LegacyDenialTransition,$successorValidated.LegacyGateTransition)
                            Close-SynapseLegacyDenialGateAbsenceLease -AbsencePlan $successorValidated.LegacyGateAbsence
                        }
                    }
                }
            }
        }
    }
    if($committedAdoptions.Count -eq 0){return [pscustomobject][ordered]@{Task=$TaskInfrastructure.Task;Adoption=$null;Predecessor=$(if($predecessors.Count-eq1){$predecessors[0]}else{$null});PredecessorProof=$predecessorProof;ControlState='absent'}}
    $adoptionRecord=$committedAdoptions[0];$journal=$adoptionRecord.Journal;$initial=$journal.Initial;$detail=$journal.Latest.detail
    $layout=Get-SynapseAuthorityLayoutReadOnly -RuntimeBinDir $RuntimeBinDir -RequireAuthorityRoot
    $committedApplicationSuccessors=@($Inventory.ApplicationV4|Where-Object{[string]$_.RecordKind-ceq'journal' -and [string]$_.EffectiveState-ceq'commit_decided'})
    if($committedApplicationSuccessors.Count-eq1 -and [string]$initial.prior_authority-ceq'absent'){
        [void](Assert-SynapseAuthorityAdoptionInitialDescriptor -Initial $initial -TransactionRoot ([string]$adoptionRecord.Root) -Allocation $journal.Allocation -HistoricalMutableGeneration -StructuralOnly)
        $validated=[pscustomobject][ordered]@{
            LegacyGateTransition=ConvertTo-SynapseAuthorityControlTransition -Descriptor $initial.legacy_gate_transition -TransactionRoot ([string]$adoptionRecord.Root) -Allocation $journal.Allocation
            LegacyDenialTransition=ConvertTo-SynapseAuthorityControlTransition -Descriptor $initial.legacy_denial_stub_transition -TransactionRoot ([string]$adoptionRecord.Root) -Allocation $journal.Allocation
            LegacyDenialProbePlans=@()
        }
    }else{
        # The immutable adoption epoch proves the permanent broker floor. Its
        # original parked control pair is expected to be retired once any
        # broker application generation is committed. Validate the exact live
        # pair under the retained authority root instead of requiring the
        # historical parked postimage to remain present forever.
        $validated=Assert-SynapseAuthorityAdoptionInitialDescriptor -Initial $initial -TransactionRoot ([string]$adoptionRecord.Root) -Allocation $journal.Allocation -HistoricalMutableGeneration -AllowRetiredControlPostimage
    }
    if([int]$detail.legacy_authority_floor -ne 1 -or -not [bool]$detail.broker_adoption_decided -or
       [string]$detail.broker_identity_sha256 -ine [string]$initial.broker_identity_sha256 -or
       [string]$detail.legacy_gate_file_id_128 -ine [string]$validated.LegacyGateTransition.post_file_id_128 -or
       [string]$detail.legacy_denial_stub_file_id_128 -ine [string]$validated.LegacyDenialTransition.post_file_id_128){
        Die "SYNAPSE_GLOBAL_COMMITTED_ADOPTION_DECISION_INVALID root=$($adoptionRecord.Root) floor=$($detail.legacy_authority_floor) decided=$([bool]$detail.broker_adoption_decided) detail_identity=$($detail.broker_identity_sha256) initial_identity=$($initial.broker_identity_sha256) detail_gate=$($detail.legacy_gate_file_id_128) validated_gate=$($validated.LegacyGateTransition.post_file_id_128) detail_denial=$($detail.legacy_denial_stub_file_id_128) validated_denial=$($validated.LegacyDenialTransition.post_file_id_128) structural_only=$([bool]$DecommissionStructuralOnly)"
    }
    if([string]$initial.task_name -cne $RequestedLegacyTaskName){Die "SYNAPSE_GLOBAL_COMMITTED_LEGACY_TASK_NAME_MISMATCH requested=$RequestedLegacyTaskName receipt=$($initial.task_name)"}
    # Resolve the exact historical task receipt referenced by the immutable
    # adoption instead of assuming the newest task epoch created by an upgrade.
    $adoptionTaskMatches=@()
    foreach($historicalTask in $orderedTasks){
        if([string]$historicalTask.RootFileId128-ine[string]$initial.broker_task_receipt.task_epoch_root_file_id_128){continue}
        if([string]$historicalTask.Initial.task_capability_sha256-ine[string]$initial.broker_task_receipt.task_capability_sha256){continue}
        $adoptionTaskMatches+=@($historicalTask)
    }
    if($adoptionTaskMatches.Count-ne1){Die "SYNAPSE_GLOBAL_COMMITTED_ADOPTION_TASK_RECEIPT_AMBIGUOUS root=$($adoptionRecord.Root) matches=$($adoptionTaskMatches.Count)"}
    $adoptionTask=$adoptionTaskMatches[0]
    $taskRecordIsAdoption=((Get-SynapseNormalizedDirectoryPath -Path ([string]$adoptionTask.Root))-ieq(Get-SynapseNormalizedDirectoryPath -Path ([string]$taskRecord.Root)))
    if(-not$taskRecordIsLatest-and-not$taskRecordIsAdoption){Die "SYNAPSE_GLOBAL_COMMITTED_ADOPTION_TASK_INFRASTRUCTURE_MISMATCH adoption_task=$($adoptionTask.Root) infrastructure_task=$($taskRecord.Root) latest_task=$($orderedTasks[-1].Root)"}
    $historicalTaskCommit=$adoptionTask.Journal.Latest.detail
    if([string]$initial.broker_task.name -cne [string]$historicalTaskCommit.task_name -or
       [string]$initial.broker_task.xml_sha256 -ine [string]$historicalTaskCommit.observed_xml_sha256 -or
       [string]$initial.broker_task.security_descriptor_sha256 -ine [string]$historicalTaskCommit.observed_security_descriptor_sha256){
        Die "SYNAPSE_GLOBAL_COMMITTED_ADOPTION_TASK_CROSSBIND_INVALID root=$($adoptionRecord.Root) historical_task=$($historicalTaskCommit.task_name) current_task=$($TaskInfrastructure.TaskName)"
    }
    if([string]$initial.prior_authority -ceq 'legacy'){
        [void](Assert-SynapseLegacyAuthoritySnapshotUnchanged -Snapshot $initial.legacy_task)
    }elseif([string]$initial.prior_authority -ceq 'absent'){
        if(Test-SynapseScheduledTaskExistsExact -Name ([string]$initial.task_name)){Die "SYNAPSE_GLOBAL_COMMITTED_FRESH_LEGACY_TASK_APPEARED root=$($adoptionRecord.Root) task=$($initial.task_name)"}
    }else{Die "SYNAPSE_GLOBAL_COMMITTED_PRIOR_AUTHORITY_INVALID root=$($adoptionRecord.Root) prior=$($initial.prior_authority)"}
    $legacyGate=Get-SynapsePhysicalRelativeState -ParentPath $validated.LegacyGateTransition.parent -ParentChain $validated.LegacyGateTransition.parent_chain -Leaf $validated.LegacyGateTransition.leaf
    $legacyDenial=Get-SynapsePhysicalRelativeState -ParentPath $validated.LegacyDenialTransition.parent -ParentChain $validated.LegacyDenialTransition.parent_chain -Leaf $validated.LegacyDenialTransition.leaf
    if(-not(Test-SynapsePhysicalStateExact -State $legacyGate -ExpectedExists $true -ExpectedFileId128 $validated.LegacyGateTransition.post_file_id_128 -ExpectedSha256 $validated.LegacyGateTransition.post_sha256 -ExpectedLength $validated.LegacyGateTransition.post_length) -or
       -not(Test-SynapsePhysicalStateExact -State $legacyDenial -ExpectedExists $true -ExpectedFileId128 $validated.LegacyDenialTransition.post_file_id_128 -ExpectedSha256 $validated.LegacyDenialTransition.post_sha256 -ExpectedLength $validated.LegacyDenialTransition.post_length)){
        Die "SYNAPSE_GLOBAL_COMMITTED_LEGACY_FLOOR_DRIFT root=$($adoptionRecord.Root) gate_id=$($legacyGate.FileId128) denial_id=$($legacyDenial.FileId128)"
    }
    if([string]$initial.prior_authority -ceq 'legacy'){
        if(-not [bool]$detail.legacy_denial_probes_complete){Die "SYNAPSE_GLOBAL_COMMITTED_LEGACY_DENIAL_PROBE_DECISION_MISSING root=$($adoptionRecord.Root)"}
        [void](Assert-SynapseLegacyDenialProbeCommittedControlState -Plans @($validated.LegacyDenialProbePlans) -LegacyGateTransition $validated.LegacyGateTransition -MalformedGateTransition $validated.LegacyMalformedGateTransition -LegacyDenialTransition $validated.LegacyDenialTransition -GateAbsence $validated.LegacyGateAbsence -Context 'global_committed_authority')
    }elseif([bool]$detail.legacy_denial_probes_complete){Die "SYNAPSE_GLOBAL_COMMITTED_FRESH_DENIAL_PROBE_DECISION_INVALID root=$($adoptionRecord.Root)"}
    $gateRead=Read-SynapseAuthorityControlGateCurrent -Layout $layout -Context 'global_committed_authority_control_gate'
    if([string]$gateRead.Payload.state -notin @('active','parked')){Die "SYNAPSE_GLOBAL_COMMITTED_CONTROL_STATE_INVALID state=$($gateRead.Payload.state)"}
    $pair=Read-SynapseAuthorityActiveControlPair -Layout $layout -ExpectedState ([string]$gateRead.Payload.state) -Context 'global_committed_authority_pair'
    try{
        if([string]$pair.Gate.Payload.broker_identity_sha256 -ine [string]$initial.broker_identity_sha256 -or [int64]$pair.Gate.Payload.authority_epoch -ne [int64]$initial.authority_epoch -or [string]$pair.Gate.Payload.control_nonce -ine [string]$initial.control_nonce -or
           [string]$pair.Roster.Payload.broker_identity_sha256 -ine [string]$initial.broker_identity_sha256 -or [int64]$pair.Roster.Payload.authority_epoch -ne [int64]$initial.authority_epoch -or [string]$pair.Roster.Payload.control_nonce -ine [string]$initial.control_nonce){
            Die "SYNAPSE_GLOBAL_COMMITTED_CONTROL_PAIR_CROSSBIND_INVALID root=$($adoptionRecord.Root) state=$($gateRead.Payload.state)"
        }
    }finally{Close-SynapseAuthorityActiveControlPair -Pair $pair}
    return [pscustomobject][ordered]@{Task=$TaskInfrastructure.Task;Adoption=$validated;Predecessor=$(if($predecessors.Count-eq1){$predecessors[0]}else{$null});PredecessorProof=$predecessorProof;ControlState=[string]$gateRead.Payload.state}
}

function Remove-SynapseDeploymentCleanupTailIfPresent {
    param(
        [Parameter(Mandatory=$true)][string]$TransactionRoot,
        [Parameter(Mandatory=$true)][string]$ExpectedParent,
        [switch]$RequireAuthorityFailedSuccessor,
        [switch]$RequireAuthorityCommittedSuccessor,
        $ExpectedAuthorityPredecessorReceipt=$null,
        $ExpectedSuccessorRecord=$null
    )

    $tail=Get-SynapseDeploymentCleanupTailDescriptor -TransactionRoot $TransactionRoot
    if($null -eq $tail){return $false}
    if ($RequireAuthorityFailedSuccessor -and
        ([string]$tail.TerminalState -cne 'rolled_back' -or $null -eq $tail.CleanupAuthority -or
         [string]$tail.CleanupAuthority.schema -cne 'synapse_authority_failed_successor_cleanup/v1' -or
         $null -eq $ExpectedAuthorityPredecessorReceipt -or
         (Get-SynapseCanonicalJson -Value $tail.CleanupAuthority.predecessor_receipt) -cne (Get-SynapseCanonicalJson -Value $ExpectedAuthorityPredecessorReceipt) -or
         [string]$tail.CleanupAuthority.predecessor_receipt_sha256 -ine (Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $ExpectedAuthorityPredecessorReceipt)))) {
        return $false
    }
    if($RequireAuthorityCommittedSuccessor){
        if([string]$tail.TerminalState-cne'rolled_back' -or $null-eq$tail.CleanupAuthority -or [string]$tail.CleanupAuthority.schema-cne'synapse_authority_committed_successor_predecessor_cleanup/v1' -or $null-eq$ExpectedAuthorityPredecessorReceipt -or $null-eq$ExpectedSuccessorRecord -or (Get-SynapseCanonicalJson -Value $tail.CleanupAuthority.predecessor_receipt)-cne(Get-SynapseCanonicalJson -Value $ExpectedAuthorityPredecessorReceipt)){return $false}
        $cleanupProof=Assert-SynapseAuthorityCommittedSuccessorPredecessorCleanupAuthority -Authority $tail.CleanupAuthority -ExpectedPredecessorReceipt $ExpectedAuthorityPredecessorReceipt -Context "resume_committed_predecessor_cleanup_$($tail.Root)"
        if((Get-SynapseNormalizedDirectoryPath -Path ([string]$cleanupProof.Authority.successor_root))-ine(Get-SynapseNormalizedDirectoryPath -Path ([string]$ExpectedSuccessorRecord.Root))){return $false}
    }
    foreach($entry in $tail.Entries){
        Remove-SynapsePhysicalRelativeEntryExact -ParentPath $tail.Root -ParentChain $tail.RootChain -Leaf ([string]$entry.Leaf) -ExpectedFileId128 ([string]$entry.FileId128) -ExpectedSha256 ([string]$entry.RawSha256) -ExpectedLength ([int64]$entry.ByteLength) -Context 'resume_transaction_cleanup_tail'
    }
    $parent=Get-SynapseNormalizedDirectoryPath -Path $ExpectedParent
    $parentChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $parent)
    Remove-SynapsePhysicalRelativeEntryExact -ParentPath $parent -ParentChain $parentChain -Leaf (Split-Path -Leaf $tail.Root) -ExpectedFileId128 ([string]$tail.RootFileId128) -Directory -Context 'resume_transaction_cleanup_tail_root'
    Info "SYNAPSE_DEPLOYMENT_TRANSACTION_CLEANUP_TAIL_COMPLETED root=$($tail.Root) terminal_state=$($tail.TerminalState) authority_failed_successor=$([bool]($null-ne$tail.CleanupAuthority))"
    return $true
}

function Open-SynapseAuthorityCommittedSuccessorCleanupControlLease {
    param(
        [Parameter(Mandatory=$true)]$SuccessorRecord,
        $ExistingLegacyGateLease=$null,
        $ExistingLegacyDenialLease=$null,
        $ExistingControlGateLease=$null,
        $ExistingRosterLease=$null,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $validated=$null;$pair=$null
    $existingLeases=@($ExistingLegacyGateLease,$ExistingLegacyDenialLease,$ExistingControlGateLease,$ExistingRosterLease)
    $borrowedCount=@($existingLeases|Where-Object{$null-ne$_}).Count
    if($borrowedCount-notin@(0,4)){Die "SYNAPSE_AUTHORITY_COMMITTED_SUCCESSOR_CLEANUP_BORROWED_LEASE_SET_INCOMPLETE context=$Context count=$borrowedCount"}
    $borrowed=($borrowedCount-eq4)
    try{
        $validated=Assert-SynapseAuthorityAdoptionInitialDescriptor -Initial $SuccessorRecord.Journal.Initial -TransactionRoot ([string]$SuccessorRecord.Root) -Allocation $SuccessorRecord.Journal.Allocation -HistoricalMutableGeneration -StructuralOnly:$borrowed
        $authorityRoot=Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent (Split-Path -Parent ([string]$SuccessorRecord.Root)))
        $runtimeBin=Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $authorityRoot)
        $layout=Get-SynapseAuthorityLayoutReadOnly -RuntimeBinDir $runtimeBin -RequireAuthorityRoot
        if($borrowed){
            # Structural-only adoption validation deliberately returns a small
            # two-pass descriptor and never reopens mutable transition files.
            # Rehydrate the two denial-control contracts from the sealed
            # initial/allocation instead, then bind them to both the durable
            # commit and the continuously retained hot-path leases.
            $legacyGate=ConvertTo-SynapseAuthorityControlTransition -Descriptor $SuccessorRecord.Journal.Initial.legacy_gate_transition -TransactionRoot ([string]$SuccessorRecord.Root) -Allocation $SuccessorRecord.Journal.Allocation
            $legacyDenial=ConvertTo-SynapseAuthorityControlTransition -Descriptor $SuccessorRecord.Journal.Initial.legacy_denial_stub_transition -TransactionRoot ([string]$SuccessorRecord.Root) -Allocation $SuccessorRecord.Journal.Allocation
            $commitSlots=@($SuccessorRecord.Journal.Slots|Where-Object{[string]$_.State-ceq'commit_decided'})
            if($commitSlots.Count-ne1){Die "SYNAPSE_AUTHORITY_COMMITTED_SUCCESSOR_CLEANUP_COMMIT_SLOT_INVALID context=$Context count=$($commitSlots.Count)"}
            $commitDetail=$commitSlots[0].Payload.detail
            if([string]$legacyGate.purpose-cne'broker_adoption_legacy_gate' -or [string]$legacyGate.path-ine[string]$layout.LegacyGatePath -or
               [string]$legacyDenial.purpose-cne'broker_adoption_legacy_denial_stub' -or [string]$legacyDenial.path-ine[System.IO.Path]::GetFullPath((Join-Path $layout.RuntimeBinDir 'synapse-daemon-supervisor.ps1')) -or
               [string]$legacyGate.post_file_id_128-ine[string]$commitDetail.legacy_gate_file_id_128 -or [string]$legacyGate.post_sha256-ine[string]$commitDetail.legacy_gate_sha256 -or [int64]$legacyGate.post_length-ne[int64]$commitDetail.legacy_gate_length -or
               [string]$legacyDenial.post_file_id_128-ine[string]$commitDetail.legacy_denial_stub_file_id_128 -or [string]$legacyDenial.post_sha256-ine[string]$commitDetail.legacy_denial_stub_sha256 -or [int64]$legacyDenial.post_length-ne[int64]$commitDetail.legacy_denial_stub_length){
                Die "SYNAPSE_AUTHORITY_COMMITTED_SUCCESSOR_CLEANUP_BORROWED_TRANSITION_CONTRACT_INVALID context=$Context"
            }
            $validated|Add-Member -NotePropertyName LegacyGateTransition -NotePropertyValue $legacyGate
            $validated|Add-Member -NotePropertyName LegacyDenialTransition -NotePropertyValue $legacyDenial
            $borrowedTransitions=@(
                [pscustomobject]@{Transition=$validated.LegacyGateTransition;Lease=$ExistingLegacyGateLease;Role='legacy_gate'},
                [pscustomobject]@{Transition=$validated.LegacyDenialTransition;Lease=$ExistingLegacyDenialLease;Role='legacy_denial'}
            )
            foreach($binding in $borrowedTransitions){
                $transition=$binding.Transition;$lease=$binding.Lease
                if([string]$lease.FileId128-ine[string]$transition.post_file_id_128 -or [string]$lease.Sha256-ine[string]$transition.post_sha256 -or [int64]$lease.Length-ne[int64]$transition.post_length){Die "SYNAPSE_AUTHORITY_COMMITTED_SUCCESSOR_CLEANUP_BORROWED_TRANSITION_DRIFT context=$Context role=$($binding.Role)"}
                $lease.RequireExact("${Context}_borrowed_$($binding.Role)")
                $transition.CanonicalLease=$lease
            }
            $expectedState=if([string]$SuccessorRecord.Journal.Initial.prior_authority-ceq'legacy'){'active'}else{'parked'}
            $pair=Read-SynapseAuthorityActiveControlPair -Layout $layout -GateLease $ExistingControlGateLease -RosterLease $ExistingRosterLease -ExpectedState $expectedState -Context "${Context}_control_pair"
        }else{
            foreach($transition in @($validated.LegacyGateTransition,$validated.LegacyDenialTransition)){
                $state=Get-SynapsePhysicalRelativeState -ParentPath $transition.parent -ParentChain $transition.parent_chain -Leaf $transition.leaf
                if(-not(Test-SynapsePhysicalStateExact -State $state -ExpectedExists $true -ExpectedFileId128 $transition.post_file_id_128 -ExpectedSha256 $transition.post_sha256 -ExpectedLength $transition.post_length)){
                    Die "SYNAPSE_AUTHORITY_COMMITTED_SUCCESSOR_CLEANUP_DENIAL_CONTROL_DRIFT context=$Context path=$($transition.path) file_id_128=$($state.FileId128)"
                }
                # These are the committed successor's permanent monotonic
                # denial controls, not predecessor cleanup targets.  A
                # retained exact read lease is sufficient to prevent content
                # replacement while predecessor artifacts are removed and is
                # compatible with the live daemon's no-delete-share reader.
                # Requesting DELETE access here incorrectly makes safe cleanup
                # depend on stopping the committed successor.
                $transition.CanonicalLease=Open-SynapsePhysicalFileReadLease -ParentPath $transition.parent -ParentChain $transition.parent_chain -Leaf $transition.leaf -ExpectedFileId128 $transition.post_file_id_128 -ExpectedSha256 $transition.post_sha256 -ExpectedLength $transition.post_length -Context "${Context}_$($transition.purpose)"
            }
            $gate=Read-SynapseAuthorityControlGateCurrent -Layout $layout -Context "${Context}_control_gate"
            if([string]$gate.Payload.state-notin@('active','parked')){Die "SYNAPSE_AUTHORITY_COMMITTED_SUCCESSOR_CLEANUP_CONTROL_STATE_INVALID context=$Context state=$($gate.Payload.state)"}
            $pair=Read-SynapseAuthorityActiveControlPair -Layout $layout -ExpectedState ([string]$gate.Payload.state) -Context "${Context}_control_pair"
        }
        foreach($payload in @($pair.Gate.Payload,$pair.Roster.Payload)){
            if([string]$payload.broker_identity_sha256-ine[string]$SuccessorRecord.Journal.Initial.broker_identity_sha256 -or [int64]$payload.authority_epoch-ne[int64]$SuccessorRecord.Journal.Initial.authority_epoch -or [string]$payload.control_nonce-ine[string]$SuccessorRecord.Journal.Initial.control_nonce){
                Die "SYNAPSE_AUTHORITY_COMMITTED_SUCCESSOR_CLEANUP_CONTROL_CROSSBIND_INVALID context=$Context successor=$($SuccessorRecord.Root)"
            }
        }
        return [pscustomobject][ordered]@{Validated=$validated;Pair=$pair;Layout=$layout;Borrowed=$borrowed}
    }catch{
        if($null-ne$pair){Close-SynapseAuthorityActiveControlPair -Pair $pair;$pair=$null}
        if($null-ne$validated -and -not$borrowed){Close-SynapseAuthorityControlTransitionLeases -Transitions @($validated.ControlGateTransition,$validated.ActiveRosterTransition,$validated.ParkedRosterTransition,$validated.LegacyMalformedGateTransition,$validated.LegacyDenialTransition,$validated.LegacyGateTransition);Close-SynapseLegacyDenialGateAbsenceLease -AbsencePlan $validated.LegacyGateAbsence}
        throw
    }
}

function Close-SynapseAuthorityCommittedSuccessorCleanupControlLease {
    param($Lease)
    if($null-eq$Lease){return}
    $primary=$null
    try{if([bool]$Lease.Borrowed -and $null-ne$Lease.Pair){$Lease.Pair.GateLease.RequireExact('authority_committed_successor_cleanup_borrowed_gate_release');$Lease.Pair.RosterLease.RequireExact('authority_committed_successor_cleanup_borrowed_roster_release')}}catch{$primary=$_.Exception}
    try{if($null-ne$Lease.Pair){Close-SynapseAuthorityActiveControlPair -Pair $Lease.Pair;$Lease.Pair=$null}}catch{if($null-eq$primary){$primary=$_.Exception}else{[Environment]::FailFast('SYNAPSE_AUTHORITY_COMMITTED_SUCCESSOR_CLEANUP_PAIR_CLOSE_MULTIPLE_FAILURES',$_.Exception)}}
    try{if($null-ne$Lease.Validated){
        if([bool]$Lease.Borrowed){foreach($transition in @($Lease.Validated.LegacyDenialTransition,$Lease.Validated.LegacyGateTransition)){if($null-ne$transition.CanonicalLease){$transition.CanonicalLease.RequireExact('authority_committed_successor_cleanup_borrowed_release');$transition.CanonicalLease=$null}}}
        else{Close-SynapseAuthorityControlTransitionLeases -Transitions @($Lease.Validated.ControlGateTransition,$Lease.Validated.ActiveRosterTransition,$Lease.Validated.ParkedRosterTransition,$Lease.Validated.LegacyMalformedGateTransition,$Lease.Validated.LegacyDenialTransition,$Lease.Validated.LegacyGateTransition);Close-SynapseLegacyDenialGateAbsenceLease -AbsencePlan $Lease.Validated.LegacyGateAbsence}
        $Lease.Validated=$null
    }}catch{if($null-eq$primary){$primary=$_.Exception}else{[Environment]::FailFast('SYNAPSE_AUTHORITY_COMMITTED_SUCCESSOR_CLEANUP_CONTROL_CLOSE_MULTIPLE_FAILURES',$_.Exception)}}
    if($null-ne$primary){throw $primary}
}

function Remove-SynapseAuthorityCommittedSuccessorPredecessor {
    param(
        [Parameter(Mandatory=$true)]$PredecessorRecord,
        [Parameter(Mandatory=$true)]$SuccessorRecord,
        [Parameter(Mandatory=$true)][string]$ExpectedParent,
        $ExistingLegacyGateLease=$null,
        $ExistingLegacyDenialLease=$null,
        $ExistingControlGateLease=$null,
        $ExistingRosterLease=$null,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $controlLease=Open-SynapseAuthorityCommittedSuccessorCleanupControlLease -SuccessorRecord $SuccessorRecord -ExistingLegacyGateLease $ExistingLegacyGateLease -ExistingLegacyDenialLease $ExistingLegacyDenialLease -ExistingControlGateLease $ExistingControlGateLease -ExistingRosterLease $ExistingRosterLease -Context "${Context}_successor_control"
    try{
        $receipt=Assert-SynapseAuthorityPredecessorReceiptDescriptor -Receipt $PredecessorRecord.PredecessorReceipt -Context "${Context}_receipt"
        if($null-ne$PredecessorRecord.PSObject.Properties['CleanupMarker'] -and $null-ne$PredecessorRecord.CleanupMarker){
            $cleanupAuthority=ConvertTo-SynapseCanonicalValue -Value $PredecessorRecord.CleanupMarker.Payload.cleanup_authority
            $cleanupProof=Assert-SynapseAuthorityCommittedSuccessorPredecessorCleanupAuthority -Authority $cleanupAuthority -ExpectedPredecessorReceipt $receipt -Context "${Context}_residue_authority"
            if((Get-SynapseNormalizedDirectoryPath -Path ([string]$cleanupProof.Authority.successor_root))-ine(Get-SynapseNormalizedDirectoryPath -Path ([string]$SuccessorRecord.Root))){Die "SYNAPSE_AUTHORITY_COMMITTED_PREDECESSOR_CLEANUP_RESIDUE_SUCCESSOR_DRIFT context=$Context predecessor=$($PredecessorRecord.Root)"}
            return (Remove-SynapseAuthorityTornPredecessorWithCommittedSuccessor -PredecessorRecord $PredecessorRecord -SuccessorRecord $SuccessorRecord -CleanupAuthority $cleanupAuthority -ExpectedParent $ExpectedParent -Context $Context)
        }
        if($null-ne$PredecessorRecord.PSObject.Properties['CleanupTail'] -and $null-ne$PredecessorRecord.CleanupTail){
            # A predecessor-local cleanup_ready tail is not durable deletion
            # authority: the tail slot itself is intentionally deleted last,
            # and a crash between that delete and root removal otherwise loses
            # the only restart signal.  Migrate the exact remaining subset to
            # a successor-owned REDO marker before deleting another byte.
            $tail=$PredecessorRecord.CleanupTail
            $entries=@($tail.Entries|ForEach-Object{
                [ordered]@{leaf=[string]$_.Leaf;is_directory=$false;file_id_128=([string]$_.FileId128).ToUpperInvariant();sha256=([string]$_.RawSha256).ToUpperInvariant();length=[int64]$_.ByteLength}
            })
            if($entries.Count-lt1){Die "SYNAPSE_AUTHORITY_COMMITTED_PREDECESSOR_CLEANUP_TAIL_EMPTY context=$Context predecessor=$($PredecessorRecord.Root)"}
            $cleanupAuthority=New-SynapseAuthorityCommittedSuccessorPredecessorCleanupAuthorityFromReceipt -PredecessorReceipt $receipt -SuccessorRecord $SuccessorRecord -Context "${Context}_tail_authority"
            $marker=Ensure-SynapseAuthorityCommittedPredecessorCleanupMarker -SuccessorRecord $SuccessorRecord -CleanupAuthority $cleanupAuthority -Entries $entries -Context "${Context}_tail_marker"
            $markerRecord=[pscustomobject][ordered]@{Entry=$PredecessorRecord.Entry;Journal=$null;Root=[string]$PredecessorRecord.Root;RootFileId128=[string]$PredecessorRecord.RootFileId128;CleanupTail=$tail;CleanupMarker=$marker;PredecessorReceipt=$receipt}
            return (Remove-SynapseAuthorityTornPredecessorWithCommittedSuccessor -PredecessorRecord $markerRecord -SuccessorRecord $SuccessorRecord -CleanupAuthority $cleanupAuthority -ExpectedParent $ExpectedParent -Context $Context)
        }
        $cleanupAuthority=New-SynapseAuthorityCommittedSuccessorPredecessorCleanupAuthority -PredecessorRecord $PredecessorRecord -SuccessorRecord $SuccessorRecord -Context "${Context}_authority"
        [void](Assert-SynapseAuthorityCommittedSuccessorPredecessorCleanupAuthority -Authority $cleanupAuthority -ExpectedPredecessorReceipt $receipt -Context "${Context}_authority_readback")
        # Every predecessor class, including a fully valid historical v3/v4
        # terminal, acquires the successor-owned write-once cleanup decision
        # before the first predecessor byte is removed.  This avoids relying
        # on a predecessor-local cleanup_ready append, which can itself tear.
        return (Remove-SynapseAuthorityTornPredecessorWithCommittedSuccessor -PredecessorRecord $PredecessorRecord -SuccessorRecord $SuccessorRecord -CleanupAuthority $cleanupAuthority -ExpectedParent $ExpectedParent -Context $Context)
    }finally{
        Close-SynapseAuthorityCommittedSuccessorCleanupControlLease -Lease $controlLease
    }
}

function Add-SynapseDeploymentTransactionJournalState {
    param(
        [Parameter(Mandatory=$true)][ValidateSet('candidate_ready','commit_decided','rolled_back')][string]$State,
        [Parameter(Mandatory=$true)]$Payload,
        $Transaction
    )

    if($null -eq $Transaction){$Transaction=$script:SynapseDeploymentTransaction}
    $transaction = $Transaction
    if ($null -eq $transaction -or -not [bool]$transaction.Armed) { Die "SYNAPSE_DEPLOYMENT_JOURNAL_APPEND_NOT_ARMED state=$State" }
    $journal = Read-SynapseDeploymentTransactionJournal -TransactionRoot $transaction.Root -TransactionRootChain $transaction.RootChain
    if ($null -eq $journal -or [int]$journal.Sequence -ne [int]$transaction.JournalSequence -or [string]$journal.LatestRawSha256 -ine [string]$transaction.JournalSha256) {
        Die "SYNAPSE_DEPLOYMENT_JOURNAL_APPEND_BASE_MISMATCH state=$State expected_sequence=$($transaction.JournalSequence) actual_sequence=$($journal.Sequence) expected_sha256=$($transaction.JournalSha256) actual_sha256=$($journal.LatestRawSha256)"
    }
    $allowedPriorStates = if ($State -eq 'candidate_ready') { @('armed') } elseif ($State -eq 'commit_decided') { @('candidate_ready') } else { @('armed','candidate_ready') }
    if ([string]$journal.State -notin $allowedPriorStates) {
        Die "SYNAPSE_DEPLOYMENT_JOURNAL_STATE_TRANSITION_INVALID from=$($journal.State) to=$State sequence=$($journal.Sequence)"
    }
    if ($null -ne $journal.TornTail) {
        Die "SYNAPSE_DEPLOYMENT_JOURNAL_TORN_PREALLOCATED_SLOT_PRESERVED root=$($transaction.Root) sequence=$($journal.TornTail.Sequence) file_id_128=$($journal.TornTail.FileId128) length=$($journal.TornTail.Length) error=$($journal.TornTail.Error) remediation=preserve the exact partial slot and keep restart authority parked; a torn durable journal object is never truncated or replaced"
    }
    # A torn append remains the exact preallocated FILE_ID declared by the
    # frozen allocation log. Refill that object in place; never delete it and
    # recreate a same-name slot, which would discard the durable identity.
    $sequence = [int]$journal.Sequence + 1
    if ($sequence -gt $script:SynapseDeploymentJournalMaxSlots) { Die "SYNAPSE_DEPLOYMENT_JOURNAL_SLOT_EXHAUSTED state=$State max=$($script:SynapseDeploymentJournalMaxSlots)" }
    $statePayload = [ordered]@{ state=$State; recorded_at_utc=[DateTime]::UtcNow.ToString('o'); static_transaction_sha256=[string]$transaction.StaticTransactionSha256; detail=$Payload }
    $next = Write-SynapseDeploymentTransactionJournalSlot -TransactionRoot $transaction.Root -TransactionRootChain $transaction.RootChain -Sequence $sequence -InvocationId $transaction.InvocationId -PreviousSlotSha256 $journal.LatestRawSha256 -Payload $statePayload
    $transaction.JournalSequence = $next.Sequence
    $transaction.JournalSha256 = $next.LatestRawSha256
    $transaction.JournalState = $next.State
    Info "SYNAPSE_DEPLOYMENT_TRANSACTION_JOURNAL_APPENDED root=$($transaction.Root) sequence=$($next.Sequence) state=$State slot_sha256=$($next.LatestRawSha256) aggregate_bytes=$($next.AggregateBytes)"
    return $next
}

function Complete-SynapseLegacyV1NoMutationRecovery {
    param(
        [Parameter(Mandatory=$true)][string]$ManifestPath,
        [Parameter(Mandatory=$true)]$Manifest,
        [Parameter(Mandatory=$true)][ValidatePattern('^[0-9A-Fa-f]{64}$')][string]$ExpectedManifestSha256,
        [Parameter(Mandatory=$true)][string]$ExpectedTaskName
    )

    $manifestPathFull = [System.IO.Path]::GetFullPath($ManifestPath)
    if ([string]$Manifest.schema -cne 'synapse_deployment_transaction/v1' -or
        [string]$Manifest.state -cne 'armed' -or
        [string]$Manifest.task_name -cne $ExpectedTaskName) {
        Die "SYNAPSE_DEPLOYMENT_V1_NOOP_IDENTITY_INVALID manifest=$manifestPathFull schema=$($Manifest.schema) state=$($Manifest.state) task=$($Manifest.task_name)"
    }
    if ($null -ne $Manifest.PSObject.Properties['profile_transaction']) {
        Die "SYNAPSE_DEPLOYMENT_V1_PROFILE_SCHEMA_UNSHIPPED manifest=$manifestPathFull remediation=preserve the unknown profile-bearing legacy transaction; no such schema was ever persisted by a released setup"
    }
    $seenPaths = New-SynapseCaseInsensitiveMap
    foreach ($snapshot in @($Manifest.file_snapshots)) {
        $path = [System.IO.Path]::GetFullPath([string]$snapshot.Path)
        if ($seenPaths.ContainsKey($path)) {
            Die "SYNAPSE_DEPLOYMENT_V1_NOOP_DUPLICATE_PATH manifest=$manifestPathFull path=$path"
        }
        $seenPaths[$path] = $true
        $parent = Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $path)
        if (-not (Test-Path -LiteralPath $parent -PathType Container)) {
            Die "SYNAPSE_DEPLOYMENT_V1_NOOP_PARENT_MISSING path=$path remediation=legacy recovery never creates a parent directory"
        }
        $parentChain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $parent)
        $state = Get-SynapsePhysicalRelativeState -ParentPath $parent -ParentChain $parentChain -Leaf (Split-Path -Leaf $path)
        if ([bool]$snapshot.Existed) {
            if ([string]$snapshot.Sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or
                -not $state.Exists -or [bool]$state.IsDirectory -or
                [string]$state.Sha256 -ine [string]$snapshot.Sha256) {
                Die "SYNAPSE_DEPLOYMENT_V1_NOOP_PREIMAGE_DRIFT path=$path expected_sha256=$($snapshot.Sha256) actual_exists=$($state.Exists) actual_sha256=$($state.Sha256) remediation=preserve current bytes and the legacy transaction; v1 has no postimage FILE_ID authority and therefore may never restore over drift"
            }
            $backupPath = [System.IO.Path]::GetFullPath([string]$snapshot.BackupPath)
            $transactionRoot = [System.IO.Path]::GetFullPath([string]$Manifest.transaction_root)
            if ((Split-Path -Parent $backupPath) -ine $transactionRoot) {
                Die "SYNAPSE_DEPLOYMENT_V1_NOOP_BACKUP_SCOPE_INVALID path=$path backup=$backupPath root=$transactionRoot"
            }
            $backupState = Get-SynapsePhysicalRelativeState -ParentPath $transactionRoot -ParentChain (Get-SynapsePhysicalDirectoryChainDescriptor -Path $transactionRoot) -Leaf (Split-Path -Leaf $backupPath)
            if (-not $backupState.Exists -or [string]$backupState.Sha256 -ine [string]$snapshot.Sha256) {
                Die "SYNAPSE_DEPLOYMENT_V1_NOOP_BACKUP_DRIFT path=$path backup=$backupPath expected_sha256=$($snapshot.Sha256) actual_sha256=$($backupState.Sha256)"
            }
        } elseif ($state.Exists) {
            Die "SYNAPSE_DEPLOYMENT_V1_NOOP_PRIOR_ABSENCE_DRIFT path=$path actual_file_id_128=$($state.FileId128) remediation=preserve the arrival; v1 never recorded a candidate postimage identity that could authorize deletion"
        }
    }

    $priorTask = $Manifest.previous_task
    $taskLookup = Get-SynapseScheduledTaskLookupExact -Name $ExpectedTaskName
    $currentTask = if([bool]$taskLookup.Exists){$taskLookup.Task}else{$null}
    if ([bool]$priorTask.Present) {
        if ($null -eq $currentTask) {
            Die "SYNAPSE_DEPLOYMENT_V1_NOOP_PRIOR_TASK_MISSING task=$ExpectedTaskName remediation=v1 recovery never recreates task authority"
        }
        $actions = @($currentTask.Definition.Actions)
        $xml = [string]$currentTask.Xml
        $xmlSha256 = (Get-SynapseSha256Hex -Text $xml).ToUpperInvariant()
        $enabled = [bool]$currentTask.Definition.Settings.Enabled
        if ($actions.Count -ne 1 -or $xmlSha256 -ine [string]$priorTask.XmlSha256 -or
            [string]$actions[0].Path -cne [string]$priorTask.Execute -or
            [string]$actions[0].Arguments -cne [string]$priorTask.Arguments -or
            [string]$actions[0].WorkingDirectory -cne [string]$priorTask.WorkingDirectory -or
            $enabled -ne [bool]$priorTask.Enabled) {
            Die "SYNAPSE_DEPLOYMENT_V1_NOOP_PRIOR_TASK_DRIFT task=$ExpectedTaskName xml_sha256=$xmlSha256 expected_xml_sha256=$($priorTask.XmlSha256) enabled=$enabled expected_enabled=$($priorTask.Enabled) remediation=preserve the current task; Task Scheduler exposes no conditional replacement primitive"
        }
    } elseif ($null -ne $currentTask) {
        Die "SYNAPSE_DEPLOYMENT_V1_NOOP_PRIOR_TASK_ABSENCE_DRIFT task=$ExpectedTaskName remediation=preserve the current task; v1 recovery never unregisters an unversioned name"
    }

    $currentManifestSha256 = Get-SynapseFileSha256 -Path $manifestPathFull
    if ($currentManifestSha256 -ine $ExpectedManifestSha256) {
        Die "SYNAPSE_DEPLOYMENT_V1_NOOP_MANIFEST_DRIFT path=$manifestPathFull expected_sha256=$ExpectedManifestSha256 actual_sha256=$currentManifestSha256"
    }
    $rolledBackAtUtc = [DateTime]::UtcNow.ToString('o')
    $Manifest.state = 'rolled_back'
    $Manifest | Add-Member -NotePropertyName rolled_back_at_utc -NotePropertyValue $rolledBackAtUtc -Force
    $Manifest | Add-Member -NotePropertyName rollback_detail -NotePropertyValue 'legacy_v1_exact_preimage_no_mutation' -Force
    $Manifest | Add-Member -NotePropertyName rollback_detail_sha256 -NotePropertyValue ((Get-SynapseSha256Hex -Text 'legacy_v1_exact_preimage_no_mutation').ToUpperInvariant()) -Force
    $terminalText = $Manifest | ConvertTo-Json -Depth 10
    $terminalLength = [System.Text.UTF8Encoding]::new($false, $true).GetByteCount($terminalText)
    if ($terminalLength -gt 1MB) {
        Die "SYNAPSE_DEPLOYMENT_V1_NOOP_TERMINAL_BOUND_EXCEEDED path=$manifestPathFull length=$terminalLength max=1048576"
    }
    $write = Write-SynapseAtomicUtf8TextFile -Path $manifestPathFull -Content $terminalText -Purpose 'legacy_v1_exact_preimage_noop_terminal'
    $readback = Get-Content -Raw -LiteralPath $manifestPathFull -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
    if ([string]$readback.schema -cne 'synapse_deployment_transaction/v1' -or
        [string]$readback.state -cne 'rolled_back' -or
        [string]$readback.rollback_detail -cne 'legacy_v1_exact_preimage_no_mutation' -or
        (Get-SynapseFileSha256 -Path $manifestPathFull) -ine [string]$write.sha256) {
        Die "SYNAPSE_DEPLOYMENT_V1_NOOP_TERMINAL_READBACK_INVALID path=$manifestPathFull"
    }
    return $write
}

function Get-SynapseDeploymentTransactionArtifactDescriptorV1 {
    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$ExpectedRoot,
        [Parameter(Mandatory=$true)][ValidateSet('unarmed','rolled_back','committed')][string]$ExpectedState
    )

    $rootFull = [System.IO.Path]::GetFullPath($ExpectedRoot).TrimEnd('\')
    $pathFull = [System.IO.Path]::GetFullPath($Path).TrimEnd('\')
    $parentFull = [System.IO.Path]::GetFullPath((Split-Path -Parent $pathFull)).TrimEnd('\')
    $leaf = Split-Path -Leaf $pathFull
    $leafMatch = [regex]::Match($leaf, '^deployment-\d{8}T\d{9}Z-(\d+)$')
    if (-not $parentFull.Equals($rootFull, [System.StringComparison]::OrdinalIgnoreCase) -or -not $leafMatch.Success) {
        throw "SYNAPSE_DEPLOYMENT_TRANSACTION_ARTIFACT_SCOPE_INVALID path=$pathFull expected_parent=$rootFull actual_parent=$parentFull leaf=$leaf remediation=do not delete the path; only exact setup-transactions/deployment-{UTC timestamp}-{PID} directories are eligible"
    }
    $ownerPid = [int]$leafMatch.Groups[1].Value
    if (-not (Test-Path -LiteralPath $pathFull)) {
        return [pscustomobject]@{ Path = $pathFull; Exists = $false; OwnerPid = $ownerPid; Entries = @(); ManifestPath = (Join-Path $pathFull 'transaction.json') }
    }
    if (-not (Test-Path -LiteralPath $rootFull -PathType Container)) {
        throw "SYNAPSE_DEPLOYMENT_TRANSACTION_ROOT_MISSING root=$rootFull path=$pathFull remediation=do not delete anything; inspect the physical setup-transactions root"
    }
    $rootItem = Get-Item -LiteralPath $rootFull -Force -ErrorAction Stop
    if ($rootItem.Attributes -band [System.IO.FileAttributes]::ReparsePoint) {
        throw "SYNAPSE_DEPLOYMENT_TRANSACTION_ROOT_REPARSE_POINT root=$rootFull attributes=$($rootItem.Attributes) remediation=do not follow or delete this link; restore setup-transactions as a physical directory"
    }
    $pathChain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $pathFull)
    $liveOwner = Get-Process -Id $ownerPid -ErrorAction SilentlyContinue
    if ($null -ne $liveOwner -and $ownerPid -ne $PID) {
        throw "SYNAPSE_DEPLOYMENT_TRANSACTION_OWNER_STILL_LIVE path=$pathFull owner_pid=$ownerPid current_pid=$PID owner_name=$($liveOwner.ProcessName) remediation=do not delete another live setup invocation's transaction directory"
    }
    $pathReferences = @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object {
        $_.ProcessId -ne $PID -and
        -not [string]::IsNullOrWhiteSpace([string]$_.CommandLine) -and
        ([string]$_.CommandLine).IndexOf($pathFull, [System.StringComparison]::OrdinalIgnoreCase) -ge 0
    })
    if ($pathReferences.Count -gt 0) {
        $referenceText = ($pathReferences | ForEach-Object { "pid=$($_.ProcessId),name=$($_.Name)" }) -join ';'
        throw "SYNAPSE_DEPLOYMENT_TRANSACTION_PROCESS_REFERENCE_LIVE path=$pathFull references=$referenceText remediation=inspect these exact processes; do not delete rollback storage referenced by a live command line"
    }

    $entries = @(Get-SynapsePhysicalDirectoryEntriesBounded -Path $pathFull -Chain $pathChain -MaximumEntries 128 -Context 'legacy_v1_transaction_entries' | Sort-Object Name)
    $invalidEntries = @($entries | Where-Object {
        [bool]$_.IsDirectory -or
        ([uint32]$_.Attributes -band [uint32][System.IO.FileAttributes]::ReparsePoint) -or
        $_.Name -notmatch '^(transaction\.json|previous-task\.xml|file-\d{4}\.bin)$'
    })
    if ($invalidEntries.Count -gt 0) {
        $invalidText = ($invalidEntries | ForEach-Object { "name=$($_.Name),container=$($_.IsDirectory),attributes=$($_.Attributes)" }) -join ';'
        throw "SYNAPSE_DEPLOYMENT_TRANSACTION_CONTENT_INVALID path=$pathFull invalid=[$invalidText] remediation=do not broaden cleanup; inspect every unexpected entry"
    }
    $oversizedEntries = @($entries | Where-Object { [int64]$_.Length -gt 2GB })
    if ($oversizedEntries.Count -gt 0) {
        throw "SYNAPSE_DEPLOYMENT_TRANSACTION_V1_ENTRY_LENGTH_BOUND_EXCEEDED path=$pathFull entries=$(@($oversizedEntries | ForEach-Object { $_.Name }) -join ',') max=2147483648"
    }
    $validatedStates = @{}
    foreach ($entry in $entries) {
        $state = Get-SynapsePhysicalRelativeState -ParentPath $pathFull -ParentChain $pathChain -Leaf ([string]$entry.Name)
        if (-not $state.Exists -or [bool]$state.IsDirectory -or [string]$state.FileId128 -ine [string]$entry.FileId128 -or [int64]$state.Length -ne [int64]$entry.Length) {
            throw "SYNAPSE_DEPLOYMENT_TRANSACTION_V1_ENTRY_DRIFT path=$pathFull leaf=$($entry.Name) expected_file_id_128=$($entry.FileId128) actual_file_id_128=$($state.FileId128)"
        }
        $validatedStates[[string]$entry.Name] = $state
    }

    $manifestPath = Join-Path $pathFull 'transaction.json'
    if ($ExpectedState -eq 'unarmed') {
        if (Test-Path -LiteralPath $manifestPath) {
            throw "SYNAPSE_DEPLOYMENT_TRANSACTION_UNARMED_MANIFEST_PRESENT path=$manifestPath remediation=preserve the manifest; a directory with durable transaction state is not an unarmed artifact"
        }
    } else {
        if (-not (Test-Path -LiteralPath $manifestPath -PathType Leaf)) {
            throw "SYNAPSE_DEPLOYMENT_TRANSACTION_TERMINAL_MANIFEST_MISSING path=$manifestPath expected_state=$ExpectedState remediation=preserve the backup directory until its terminal state is readable"
        }
        $manifestState = $validatedStates['transaction.json']
        if ($null -eq $manifestState -or [int64]$manifestState.Length -gt 1MB) {
            throw "SYNAPSE_DEPLOYMENT_TRANSACTION_TERMINAL_MANIFEST_INVALID path=$manifestPath length=$(if($manifestState){$manifestState.Length}else{-1})"
        }
        try {
            $manifest = Get-Content -Raw -LiteralPath $manifestPath -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
        } catch {
            throw "SYNAPSE_DEPLOYMENT_TRANSACTION_TERMINAL_MANIFEST_UNREADABLE path=$manifestPath error=$($_.Exception.Message)"
        }
        if ([string]$manifest.schema -ne 'synapse_deployment_transaction/v1' -or [string]$manifest.state -ne $ExpectedState) {
            throw "SYNAPSE_DEPLOYMENT_TRANSACTION_TERMINAL_STATE_MISMATCH path=$manifestPath expected_schema=synapse_deployment_transaction/v1 actual_schema=$($manifest.schema) expected_state=$ExpectedState actual_state=$($manifest.state)"
        }
        $manifestRootProperty = $manifest.PSObject.Properties['transaction_root']
        if ($null -ne $manifestRootProperty -and
            -not [string]::IsNullOrWhiteSpace([string]$manifestRootProperty.Value) -and
            [System.IO.Path]::GetFullPath([string]$manifestRootProperty.Value) -ine $pathFull) {
            throw "SYNAPSE_DEPLOYMENT_TRANSACTION_TERMINAL_ROOT_MISMATCH path=$manifestPath expected_root=$pathFull actual_root=$($manifestRootProperty.Value)"
        }

        # Rolled-back v1 manifests retain their original file/task snapshot
        # references. Prove every referenced backup stays a regular direct child
        # of this exact transaction directory, and that no unreferenced backup
        # leaf has appeared. Committed manifests intentionally contain only the
        # terminal installed-generation summary, so their exact namespace/type
        # guard above is the deletion authority.
        $snapshotProperty = $manifest.PSObject.Properties['file_snapshots']
        if ($null -ne $snapshotProperty) {
            $referencedBackups = @()
            foreach ($snapshot in @($snapshotProperty.Value)) {
                if (-not [bool]$snapshot.Existed) { continue }
                $backupPath = [System.IO.Path]::GetFullPath([string]$snapshot.BackupPath)
                $backupParent = [System.IO.Path]::GetFullPath((Split-Path -Parent $backupPath)).TrimEnd('\')
                $backupLeaf = Split-Path -Leaf $backupPath
                if (-not $backupParent.Equals($pathFull, [System.StringComparison]::OrdinalIgnoreCase) -or
                    $backupLeaf -notmatch '^file-\d{4}\.bin$') {
                    throw "SYNAPSE_DEPLOYMENT_TRANSACTION_BACKUP_REFERENCE_OUT_OF_SCOPE manifest=$manifestPath backup=$backupPath expected_parent=$pathFull"
                }
                $referencedBackups += $backupPath
            }
            $unreferencedBackups = @($entries | Where-Object {
                $_.Name -match '^file-\d{4}\.bin$' -and $referencedBackups -inotcontains [System.IO.Path]::GetFullPath($_.Path)
            })
            if ($unreferencedBackups.Count -gt 0) {
                throw "SYNAPSE_DEPLOYMENT_TRANSACTION_UNREFERENCED_BACKUP path=$pathFull files=$(@($unreferencedBackups | ForEach-Object { $_.Name }) -join ',')"
            }
        }

        $previousTaskProperty = $manifest.PSObject.Properties['previous_task']
        if ($null -ne $previousTaskProperty) {
            $previousTaskPath = Join-Path $pathFull 'previous-task.xml'
            if ([bool]$previousTaskProperty.Value.Present) {
                if (Test-Path -LiteralPath $previousTaskPath -PathType Leaf) {
                    $previousTaskHash = Get-SynapseFileSha256 -Path $previousTaskPath
                    if ($previousTaskHash -ine [string]$previousTaskProperty.Value.XmlSha256) {
                        throw "SYNAPSE_DEPLOYMENT_TRANSACTION_PREVIOUS_TASK_SNAPSHOT_MISMATCH manifest=$manifestPath path=$previousTaskPath expected_sha256=$($previousTaskProperty.Value.XmlSha256) actual_sha256=$previousTaskHash"
                    }
                }
            } elseif (Test-Path -LiteralPath $previousTaskPath) {
                throw "SYNAPSE_DEPLOYMENT_TRANSACTION_UNEXPECTED_PREVIOUS_TASK_SNAPSHOT manifest=$manifestPath path=$previousTaskPath"
            }
        }
    }

    return [pscustomobject]@{
        Path = $pathFull
        Exists = $true
        OwnerPid = $ownerPid
        Entries = $entries
        ManifestPath = $manifestPath
        RootChain = $pathChain
        RootFileId128 = [string]$pathChain[-1].file_id_128
        ValidatedStates = $validatedStates
    }
}

function Remove-SynapseDeploymentTransactionArtifactV1 {
    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$ExpectedRoot,
        [Parameter(Mandatory=$true)][ValidateSet('unarmed','rolled_back','committed')][string]$ExpectedState,
        [Parameter(Mandatory=$true)][string]$Reason,
        [ValidateRange(1, 60)][int]$TimeoutSeconds = 20
    )

    $clock = [System.Diagnostics.Stopwatch]::StartNew()
    $attempt = 0
    $lastNativeError = 0
    $lastError = '<none>'
    $terminalManifestRemovedByThisCall = $false
    $expectedRootFileId128 = $null
    while ($true) {
        $attempt++
        # Removing the final manifest and its now-empty parent cannot be one
        # atomic filesystem operation. If only the directory removal hit a
        # transient sharing violation, revalidate the exact path as an empty
        # no-manifest artifact instead of making the same bounded call unable to
        # finish. This state is reachable only after this invocation validated
        # and removed the requested terminal manifest itself.
        $descriptorState = if ($terminalManifestRemovedByThisCall) { 'unarmed' } else { $ExpectedState }
        $descriptor = Get-SynapseDeploymentTransactionArtifactDescriptorV1 `
            -Path $Path `
            -ExpectedRoot $ExpectedRoot `
            -ExpectedState $descriptorState
        if (-not $descriptor.Exists) {
            Info "Deployment transaction artifact absence verified reason=$Reason expected_state=$ExpectedState path=$($descriptor.Path) attempts=$attempt elapsed_ms=$($clock.ElapsedMilliseconds)"
            return $descriptor
        }
        if ([string]::IsNullOrWhiteSpace([string]$expectedRootFileId128)) {
            $expectedRootFileId128 = [string]$descriptor.RootFileId128
        } elseif ([string]$descriptor.RootFileId128 -ine [string]$expectedRootFileId128) {
            throw "SYNAPSE_DEPLOYMENT_TRANSACTION_V1_ROOT_IDENTITY_CHANGED path=$($descriptor.Path) expected_file_id_128=$expectedRootFileId128 actual_file_id_128=$($descriptor.RootFileId128)"
        }
        if ($terminalManifestRemovedByThisCall -and $descriptor.Entries.Count -ne 0) {
            throw "SYNAPSE_DEPLOYMENT_TRANSACTION_PARTIAL_CLEANUP_CONTENT_REAPPEARED reason=$Reason expected_state=$ExpectedState path=$($descriptor.Path) entries=$(@($descriptor.Entries | ForEach-Object { $_.Name }) -join ',') remediation=do not delete new content that appeared after the verified terminal manifest was removed"
        }
        try {
            # Keep transaction.json until every potentially large backup has
            # been removed. A sharing violation therefore leaves the durable
            # terminal verdict intact for the next bounded retry/setup run.
            foreach ($entry in @($descriptor.Entries | Where-Object { $_.Name -cne 'transaction.json' })) {
                $state = $descriptor.ValidatedStates[[string]$entry.Name]
                if ($null -eq $state) { throw "validated state missing for $($entry.Name)" }
                Remove-SynapsePhysicalRelativeEntryExact `
                    -ParentPath $descriptor.Path `
                    -ParentChain $descriptor.RootChain `
                    -Leaf ([string]$entry.Name) `
                    -ExpectedFileId128 ([string]$state.FileId128) `
                    -ExpectedSha256 ([string]$state.Sha256) `
                    -ExpectedLength ([int64]$state.Length) `
                    -Context "cleanup_v1_payload_$Reason"
            }
            $manifestState = $descriptor.ValidatedStates['transaction.json']
            if ($null -ne $manifestState) {
                Remove-SynapsePhysicalRelativeEntryExact `
                    -ParentPath $descriptor.Path `
                    -ParentChain $descriptor.RootChain `
                    -Leaf 'transaction.json' `
                    -ExpectedFileId128 ([string]$manifestState.FileId128) `
                    -ExpectedSha256 ([string]$manifestState.Sha256) `
                    -ExpectedLength ([int64]$manifestState.Length) `
                    -Context "cleanup_v1_terminal_$Reason"
            }
            if ($ExpectedState -ne 'unarmed' -and -not (Test-Path -LiteralPath $descriptor.ManifestPath)) {
                $terminalManifestRemovedByThisCall = $true
            }
            $parentPath = Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $descriptor.Path)
            $parentChain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $parentPath)
            Remove-SynapsePhysicalRelativeEntryExact `
                -ParentPath $parentPath `
                -ParentChain $parentChain `
                -Leaf (Split-Path -Leaf $descriptor.Path) `
                -ExpectedFileId128 ([string]$expectedRootFileId128) `
                -Directory `
                -Context "cleanup_v1_root_$Reason"
            if (-not (Test-Path -LiteralPath $descriptor.Path)) {
                Info "Deployment transaction artifact cleanup verified reason=$Reason expected_state=$ExpectedState path=$($descriptor.Path) owner_pid=$($descriptor.OwnerPid) attempts=$attempt elapsed_ms=$($clock.ElapsedMilliseconds)"
                return $descriptor
            }
            $lastNativeError = 0
            $lastError = 'Remove-Item returned but the transaction directory remains present'
        } catch {
            $lastNativeError = Get-SynapseCandidateCleanupNativeErrorCode -Exception $_.Exception
            $lastError = $_.Exception.Message
            if ($lastNativeError -notin @(5, 32, 33)) {
                throw "SYNAPSE_DEPLOYMENT_TRANSACTION_ARTIFACT_CLEANUP_FAILED reason=$Reason expected_state=$ExpectedState path=$($descriptor.Path) attempt=$attempt elapsed_ms=$($clock.ElapsedMilliseconds) native_error=$lastNativeError error=$lastError remediation=inspect the exact non-transient filesystem failure; cleanup never broadens outside the verified deployment namespace"
            }
        }
        if ($clock.Elapsed.TotalSeconds -ge $TimeoutSeconds) {
            throw "SYNAPSE_DEPLOYMENT_TRANSACTION_ARTIFACT_CLEANUP_TIMEOUT reason=$Reason expected_state=$ExpectedState path=$($descriptor.Path) attempts=$attempt timeout_seconds=$TimeoutSeconds native_error=$lastNativeError error=$lastError remediation=identify the exact handle retaining a verified transaction backup and rerun setup"
        }
        Info "Deployment transaction artifact cleanup waiting reason=$Reason expected_state=$ExpectedState path=$($descriptor.Path) attempt=$attempt elapsed_ms=$($clock.ElapsedMilliseconds) native_error=$lastNativeError error=$lastError"
        Start-Sleep -Milliseconds 250
    }
}

function Get-SynapseDeploymentTransactionArtifactDescriptor {
    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$ExpectedRoot,
        [Parameter(Mandatory=$true)][ValidateSet('unarmed','rolled_back','committed')][string]$ExpectedState,
        [ValidateSet('application','authority','task')][string]$Domain='application'
    )

    $pathFull = Get-SynapseNormalizedDirectoryPath -Path $Path
    $rootFull = Get-SynapseNormalizedDirectoryPath -Path $ExpectedRoot
    $leaf = Split-Path -Leaf $pathFull
    $parent = Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $pathFull)
    $match = [regex]::Match($leaf, '^deployment-\d{8}T\d{9}Z-(\d+)$')
    if ($parent -ine $rootFull -or -not $match.Success) { throw "SYNAPSE_DEPLOYMENT_TRANSACTION_ARTIFACT_SCOPE_INVALID path=$pathFull expected_parent=$rootFull" }
    $ownerPid = [int]$match.Groups[1].Value
    if (-not (Test-Path -LiteralPath $pathFull)) { return [pscustomobject]@{ Path=$pathFull; Exists=$false; OwnerPid=$ownerPid; Entries=@(); Version='none' } }
    if ($ownerPid -ne $PID -and $null -ne (Get-Process -Id $ownerPid -ErrorAction SilentlyContinue)) { throw "SYNAPSE_DEPLOYMENT_TRANSACTION_OWNER_STILL_LIVE path=$pathFull owner_pid=$ownerPid" }
    $rootChain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $pathFull)
    [void](Assert-SynapsePhysicalDirectoryChainDescriptor -Chain $rootChain -ExpectedPath $pathFull -Context 'deployment_transaction_artifact_root')
    $entries = @(Get-SynapsePhysicalDirectoryEntriesBounded -Path $pathFull -Chain $rootChain -MaximumEntries $script:SynapseDeploymentArtifactMaxDirectEntries -Context 'deployment_transaction_artifact_entries')
    $v1Entries = @($entries | Where-Object Name -CEQ 'transaction.json')
    if ($v1Entries.Count -gt 0) {
        if($Domain -cne 'application'){throw "SYNAPSE_DEPLOYMENT_TRANSACTION_V1_DOMAIN_INVALID path=$pathFull domain=$Domain"}
        if ($v1Entries.Count -ne 1 -or [bool]$v1Entries[0].IsDirectory -or
            ([uint32]$v1Entries[0].Attributes -band [uint32][System.IO.FileAttributes]::ReparsePoint) -or
            (Split-Path -Leaf $rootFull) -cne 'setup-transactions') {
            throw "SYNAPSE_DEPLOYMENT_TRANSACTION_UNSHIPPED_OR_MIXED_SCHEMA_PRESERVED path=$pathFull expected_root=$rootFull remediation=only the shipped LogDir\\setup-transactions\\transaction.json schema may enter v1 recovery"
        }
        return Get-SynapseDeploymentTransactionArtifactDescriptorV1 -Path $pathFull -ExpectedRoot $rootFull -ExpectedState $ExpectedState
    }
    $allocationEntries = @($entries | Where-Object Name -CEQ $script:SynapseDeploymentAllocationMarkerFileName)
    if ($allocationEntries.Count -gt 1 -or
        ($allocationEntries.Count -eq 1 -and ([bool]$allocationEntries[0].IsDirectory -or ([uint32]$allocationEntries[0].Attributes -band [uint32][System.IO.FileAttributes]::ReparsePoint)))) {
        throw "SYNAPSE_DEPLOYMENT_TRANSACTION_ALLOCATION_MARKER_TYPE_INVALID path=$(Join-Path $pathFull $script:SynapseDeploymentAllocationMarkerFileName)"
    }
    $allocation = $null
    if ($allocationEntries.Count -eq 1) {
        $allowTornAllocation = ($ExpectedState -eq 'unarmed')
        $allocation = Get-SynapseDeploymentAllocationMarkerDescriptor `
            -TransactionRoot $pathFull `
            -TransactionRootChain $rootChain `
            -OwnerPid $ownerPid `
            -AllowTorn:$allowTornAllocation
        if ((-not $allocation.PrefixValid) -or (-not $allocation.Valid -and -not $allowTornAllocation)) {
            throw "SYNAPSE_DEPLOYMENT_TRANSACTION_ALLOCATION_MARKER_INVALID path=$pathFull error=$($allocation.Error)"
        }
        if ($ExpectedState -eq 'unarmed' -and [bool]$allocation.Valid -and [int]$allocation.FrozenDetail.direct_entry_count -ne $entries.Count) {
            throw "SYNAPSE_DEPLOYMENT_TRANSACTION_FROZEN_DIRECT_ENTRY_COUNT_MISMATCH path=$pathFull declared=$($allocation.FrozenDetail.direct_entry_count) actual=$($entries.Count)"
        }
    }
    $journal = $null
    $journalError = $null
    if (@($entries | Where-Object Name -Match '^transaction-\d{4}\.json$').Count -gt 0) {
        try { $journal = Read-SynapseDeploymentTransactionJournal -TransactionRoot $pathFull -TransactionRootChain $rootChain } catch { $journalError = $_.Exception.Message }
    }
    if ($null -eq $journal) {
        if ($ExpectedState -ne 'unarmed') { throw "SYNAPSE_DEPLOYMENT_TRANSACTION_JOURNAL_MISSING path=$pathFull expected_state=$ExpectedState error=$journalError" }
        if ($null -eq $allocation -or -not [bool]$allocation.PrefixValid) {
            throw "SYNAPSE_DEPLOYMENT_TRANSACTION_UNARMED_ALLOCATION_AUTHORITY_MISSING path=$pathFull allocation_present=$($null -ne $allocation) error=$($allocation.Error) remediation=preserve the entire private root; neither an absent log nor a torn initial header grants deletion authority"
        }

        $actualByName = New-SynapseCaseInsensitiveMap
        foreach ($entry in $entries) {
            if ($actualByName.ContainsKey([string]$entry.Name)) {
                throw "SYNAPSE_DEPLOYMENT_TRANSACTION_UNARMED_DUPLICATE_ENTRY path=$pathFull leaf=$($entry.Name)"
            }
            $actualByName[[string]$entry.Name] = $entry
        }
        $declaredNames = New-SynapseCaseInsensitiveMap
        $declaredNames[$script:SynapseDeploymentAllocationMarkerFileName] = $true
        foreach ($artifactLeaf in @($allocation.ArtifactOrder)) { $declaredNames[[string]$artifactLeaf] = $true }
        $unknownEntries = @($entries | Where-Object { -not $declaredNames.ContainsKey([string]$_.Name) })
        if ($unknownEntries.Count -gt 0) {
            throw "SYNAPSE_DEPLOYMENT_TRANSACTION_UNARMED_UNKNOWN_OBJECT_PRESERVED path=$pathFull entries=$(@($unknownEntries.Name) -join ',') remediation=preserve every object absent from the durable allocation prefix"
        }

        $validatedStates = New-SynapseCaseInsensitiveMap
        $validatedStates[$script:SynapseDeploymentAllocationMarkerFileName] = $allocation.State
        foreach ($artifactLeaf in @($allocation.ArtifactOrder)) {
            $artifact = $allocation.Artifacts[$artifactLeaf]
            $present = $actualByName.ContainsKey($artifactLeaf)
            if ([string]$artifact.status -ceq 'reserved') {
                if ($present) {
                    throw "SYNAPSE_DEPLOYMENT_TRANSACTION_UNARMED_UNALLOCATED_OBJECT_PRESERVED path=$(Join-Path $pathFull $artifactLeaf) kind=$($artifact.kind) remediation=CreateNew preceded its durable FILE_ID record; filename and expected bytes never grant deletion authority"
                }
                continue
            }
            if (-not $present) {
                throw "SYNAPSE_DEPLOYMENT_TRANSACTION_UNARMED_ALLOCATED_OBJECT_MISSING path=$(Join-Path $pathFull $artifactLeaf) status=$($artifact.status) expected_file_id_128=$($artifact.file_id_128) remediation=preserve the root; an allocated object disappeared before arm"
            }
            $entry = $actualByName[$artifactLeaf]
            $isDirectory = [string]$artifact.kind -eq 'directory'
            if ([bool]$entry.IsDirectory -ne $isDirectory -or
                ([uint32]$entry.Attributes -band [uint32][System.IO.FileAttributes]::ReparsePoint) -or
                [string]$entry.FileId128 -ine [string]$artifact.file_id_128) {
                throw "SYNAPSE_DEPLOYMENT_TRANSACTION_UNARMED_ALLOCATED_IDENTITY_DRIFT path=$($entry.Path) kind=$($artifact.kind) expected_file_id_128=$($artifact.file_id_128) actual_file_id_128=$($entry.FileId128)"
            }
            if ($isDirectory) {
                $directoryPath = Get-SynapseNormalizedDirectoryPath -Path ([string]$entry.Path)
                $directoryChain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $directoryPath)
                $children = @(Get-SynapsePhysicalDirectoryEntriesBounded -Path $directoryPath -Chain $directoryChain -MaximumEntries 0 -Context "unarmed_allocated_directory_$artifactLeaf")
                if ($children.Count -ne 0) {
                    throw "SYNAPSE_DEPLOYMENT_TRANSACTION_UNARMED_ALLOCATED_DIRECTORY_NOT_EMPTY path=$directoryPath"
                }
                $state = Get-SynapsePhysicalRelativeState -ParentPath $pathFull -ParentChain $rootChain -Leaf $artifactLeaf -Directory
            } else {
                $state = Get-SynapsePhysicalRelativeState -ParentPath $pathFull -ParentChain $rootChain -Leaf $artifactLeaf
                $safe = $false
                if ([string]$artifact.kind -eq 'journal_slot') {
                    $slotMatch = [regex]::Match($artifactLeaf, '^transaction-(\d{4})\.json$')
                    $slotSequence = if ($slotMatch.Success) { [int]$slotMatch.Groups[1].Value } else { 0 }
                    $safe = ([int64]$state.Length -eq 0 -or ($slotSequence -eq 1 -and [int64]$state.Length -le [int64]$artifact.maximum_length))
                } elseif ([string]$artifact.kind -eq 'progress_slot') {
                    $safe = ([int64]$state.Length -eq 0)
                } elseif ([string]$artifact.status -ceq 'sealed') {
                    $safe = ([string]$state.Sha256 -ieq [string]$artifact.sealed_sha256 -and [int64]$state.Length -eq [int64]$artifact.sealed_length)
                } else {
                    $safe = ([int64]$state.Length -eq 0 -or
                        ([string]$state.Sha256 -ieq [string]$artifact.expected_sha256 -and [int64]$state.Length -eq [int64]$artifact.expected_length))
                }
                if (-not $safe) {
                    throw "SYNAPSE_DEPLOYMENT_TRANSACTION_UNARMED_ALLOCATED_CONTENT_AMBIGUOUS path=$($entry.Path) kind=$($artifact.kind) status=$($artifact.status) length=$($state.Length) sha256=$($state.Sha256) remediation=preserve the partial or unexpected exact-ID object"
                }
            }
            $validatedStates[$artifactLeaf] = $state
        }
        return [pscustomobject]@{ Path=$pathFull; Exists=$true; OwnerPid=$ownerPid; Entries=$entries; Version='v3-unarmed-allocation-prefix'; RootChain=$rootChain; RootFileId128=[string]$rootChain[-1].file_id_128; Journal=$null; Allocation=$allocation; Allowed=@{}; ValidatedStates=$validatedStates }
    }
    if ($null -eq $allocation -or -not $allocation.Valid) {
        throw "SYNAPSE_DEPLOYMENT_TRANSACTION_ALLOCATION_MARKER_MISSING path=$pathFull remediation=v3 armed recovery requires the exact durable private-namespace allocation marker"
    }
    if ($null -ne $journal.TornTail) {
        throw "SYNAPSE_DEPLOYMENT_TRANSACTION_LATER_TORN_SLOT_PRESERVED path=$pathFull sequence=$($journal.TornTail.Sequence) file_id_128=$($journal.TornTail.FileId128) length=$($journal.TornTail.Length) remediation=only a torn initial slot before arm is cleanup-safe; a later torn append is durable ambiguous state"
    }
    $initial = $journal.Initial
    if ([string]$initial.transaction_root_file_id_128 -ine [string]$rootChain[-1].file_id_128) { throw "SYNAPSE_DEPLOYMENT_TRANSACTION_ROOT_FILE_ID_MISMATCH path=$pathFull expected=$($initial.transaction_root_file_id_128) actual=$($rootChain[-1].file_id_128)" }
    $initialAllocation = $initial.allocation_marker
    if ([string]$initialAllocation.Leaf -cne $script:SynapseDeploymentAllocationMarkerFileName -or
        [string]$initialAllocation.FileId128 -ine [string]$allocation.State.FileId128 -or
        [string]$initialAllocation.Sha256 -ine [string]$allocation.RawSha256 -or
        [int64]$initialAllocation.Length -ne [int64]$allocation.ByteLength) {
        throw "SYNAPSE_DEPLOYMENT_TRANSACTION_ALLOCATION_MARKER_BINDING_MISMATCH path=$pathFull expected_file_id_128=$($initialAllocation.FileId128) actual_file_id_128=$($allocation.State.FileId128)"
    }
    $transactionKind = if($null -ne $initial.PSObject.Properties['transaction_kind']){[string]$initial.transaction_kind}else{'synapse_application_legacy_v3'}
    $schemaDomain = if([string]$initial.schema -in @('synapse_broker_adoption_transaction/v3','synapse_broker_adoption_transaction/v4','synapse_broker_operator_stop_transaction/v1')){'authority'}elseif([string]$initial.schema -ceq 'synapse_broker_task_create_transaction/v1'){'task'}elseif([string]$initial.schema -in @('synapse_deployment_transaction/v3','synapse_deployment_transaction/v4','synapse_broker_probe_park_transaction/v1')){'application'}else{'unknown'}
    if($schemaDomain -cne $Domain){
        throw "SYNAPSE_DEPLOYMENT_TRANSACTION_DOMAIN_MISMATCH path=$pathFull schema=$($initial.schema) expected_domain=$Domain actual_domain=$schemaDomain"
    }
    $authorityParentLeaf=Split-Path -Leaf $rootFull
    $authorityTopologyValid=($Domain -cne 'authority') -or
        (([string]$initial.schema -in @('synapse_broker_adoption_transaction/v3','synapse_broker_adoption_transaction/v4') -and $authorityParentLeaf -ceq 'epochs') -or
         ([string]$initial.schema -ceq 'synapse_broker_operator_stop_transaction/v1' -and $authorityParentLeaf -ceq 'operations'))
    $taskTopologyValid=($Domain -cne 'task') -or
        ([string]$initial.schema -ceq 'synapse_broker_task_create_transaction/v1' -and $authorityParentLeaf -ceq 'task-epochs')
    if((-not $authorityTopologyValid -or ($Domain -ceq 'authority' -and (Split-Path -Leaf (Split-Path -Parent $rootFull)) -cne $script:SynapseAuthorityRootLeaf)) -or
       (-not $taskTopologyValid -or ($Domain -ceq 'task' -and (Split-Path -Leaf (Split-Path -Parent $rootFull)) -cne $script:SynapseAuthorityRootLeaf)) -or
       ($Domain -ceq 'application' -and [string]$initial.schema -in @('synapse_deployment_transaction/v3','synapse_deployment_transaction/v4','synapse_broker_probe_park_transaction/v1') -and (Split-Path -Leaf $rootFull) -cne $script:SynapseDeploymentTransactionParentDirName)){
        throw "SYNAPSE_DEPLOYMENT_TRANSACTION_DOMAIN_TOPOLOGY_INVALID path=$pathFull domain=$Domain expected_root=$rootFull"
    }
    if((([string]$initial.schema-ceq'synapse_broker_adoption_transaction/v3') -and $transactionKind-ceq'synapse_broker_adoption/v3') -or (([string]$initial.schema-ceq'synapse_broker_adoption_transaction/v4') -and $transactionKind-ceq'synapse_broker_adoption/v4')){
        [void](Assert-SynapseAuthorityAdoptionInitialDescriptor -Initial $initial -TransactionRoot $pathFull -Allocation $allocation -HistoricalMutableGeneration:($ExpectedState -eq 'committed') -StructuralOnly:($ExpectedState -eq 'rolled_back'))
    } elseif([string]$initial.schema -ceq 'synapse_deployment_transaction/v3' -and $transactionKind -ceq 'synapse_application_legacy_v3'){
        $profile = Assert-SynapseBundledProfilesTransactionDescriptor -Descriptor $initial.profile_transaction -ProfilesDir ([string]$initial.profile_transaction.profiles_dir) -TransactionRoot $pathFull
    } elseif([string]$initial.schema -ceq 'synapse_deployment_transaction/v4' -and $transactionKind -ceq 'synapse_broker_application/v1'){
        if($null -eq (Get-Command Assert-SynapseBrokerApplicationInitialDescriptor -ErrorAction SilentlyContinue)){
            throw "SYNAPSE_BROKER_APPLICATION_VALIDATOR_MISSING path=$pathFull"
        }
        [void](Assert-SynapseBrokerApplicationInitialDescriptor -Initial $initial -TransactionRoot $pathFull -Allocation $allocation -AllowCommittedDiscardedPost:($ExpectedState -eq 'committed'))
    } elseif([string]$initial.schema -ceq 'synapse_broker_probe_park_transaction/v1' -and $transactionKind -ceq 'synapse_broker_probe_park/v1'){
        if($null -eq (Get-Command Assert-SynapseBrokerProbeParkInitialDescriptor -ErrorAction SilentlyContinue)){
            throw "SYNAPSE_BROKER_PROBE_PARK_VALIDATOR_MISSING path=$pathFull"
        }
        [void](Assert-SynapseBrokerProbeParkInitialDescriptor -Initial $initial -TransactionRoot $pathFull -Allocation $allocation)
    } elseif([string]$initial.schema -ceq 'synapse_broker_operator_stop_transaction/v1' -and $transactionKind -ceq 'synapse_broker_operator_stop/v1'){
        if($null -eq (Get-Command Assert-SynapseBrokerOperatorStopInitialDescriptor -ErrorAction SilentlyContinue)){
            throw "SYNAPSE_BROKER_OPERATOR_STOP_VALIDATOR_MISSING path=$pathFull"
        }
        $operatorLayout=Get-SynapseAuthorityLayoutReadOnly -RuntimeBinDir ([string]$initial.runtime_bin_dir) -RequireAuthorityRoot
        [void](Assert-SynapseBrokerOperatorStopInitialDescriptor -Initial $initial -TransactionRoot $pathFull -Allocation $allocation -Layout $operatorLayout)
    } elseif([string]$initial.schema -ceq 'synapse_broker_task_create_transaction/v1' -and $transactionKind -ceq 'synapse_broker_task_create/v1'){
        if($null -eq (Get-Command Assert-SynapseBrokerTaskCreateInitialDescriptor -ErrorAction SilentlyContinue)){
            throw "SYNAPSE_BROKER_TASK_CREATE_VALIDATOR_MISSING path=$pathFull"
        }
        [void](Assert-SynapseBrokerTaskCreateInitialDescriptor -Initial $initial -TransactionRoot $pathFull -Allocation $allocation)
    } else {
        throw "SYNAPSE_DEPLOYMENT_TRANSACTION_KIND_UNKNOWN path=$pathFull schema=$($initial.schema) kind=$transactionKind"
    }
    $expectedJournalState = if ($ExpectedState -eq 'committed') { 'commit_decided' } else { $ExpectedState }
    $cleanupTerminalState = if ([string]$journal.State -eq 'cleanup_ready') { [string]$journal.Latest.detail.terminal_state } else { '' }
    if ([string]$journal.State -ne $expectedJournalState -and $cleanupTerminalState -ne $expectedJournalState) { throw "SYNAPSE_DEPLOYMENT_TRANSACTION_TERMINAL_STATE_MISMATCH path=$pathFull expected=$expectedJournalState actual=$($journal.State) cleanup_terminal=$cleanupTerminalState" }
    $allowed = New-SynapseCaseInsensitiveMap
    $allowed[$script:SynapseDeploymentAllocationMarkerFileName] = [pscustomobject]@{ Directory=$false; Kind='allocation_log'; FileIds=@([string]$allocation.State.FileId128); Hashes=@([string]$allocation.RawSha256); Lengths=@([int64]$allocation.ByteLength) }
    foreach ($artifactLeaf in @($allocation.ArtifactOrder)) {
        $artifact = $allocation.Artifacts[$artifactLeaf]
        if ([string]$artifact.kind -eq 'transition_slot') {
            $allowed[$artifactLeaf] = [pscustomobject]@{
                Directory=[bool]$artifact.transition_directory; Kind='transition_slot'
                FileIds=@($artifact.allowed_file_ids_128); Hashes=$(if([bool]$artifact.transition_directory){@()}else{@([string]$artifact.expected_sha256)})
                Lengths=$(if([bool]$artifact.transition_directory){@()}else{@([int64]$artifact.expected_length)})
            }
        } elseif ([string]$artifact.kind -eq 'journal_slot') {
            $allowed[$artifactLeaf] = [pscustomobject]@{ Directory=$false; Kind='journal_slot'; FileIds=@([string]$artifact.file_id_128); Hashes=@(); Lengths=@() }
        } elseif ([string]$artifact.kind -eq 'progress_slot') {
            $allowed[$artifactLeaf] = [pscustomobject]@{ Directory=$false; Kind='progress_slot'; FileIds=@([string]$artifact.file_id_128); Hashes=@(); Lengths=@(); MaximumLength=[int64]$artifact.maximum_length }
        } elseif ([string]$artifact.kind -eq 'directory') {
            $allowed[$artifactLeaf] = [pscustomobject]@{ Directory=$true; Kind='directory'; FileIds=@([string]$artifact.file_id_128); Hashes=@(); Lengths=@() }
        } else {
            $allowed[$artifactLeaf] = [pscustomobject]@{ Directory=$false; Kind='file'; FileIds=@([string]$artifact.file_id_128); Hashes=@([string]$artifact.sealed_sha256); Lengths=@([int64]$artifact.sealed_length) }
        }
    }
    $invalid = @($entries | Where-Object { $_.Name -notmatch '^transaction-\d{4}\.json$' -and -not $allowed.ContainsKey($_.Name) })
    if ($invalid.Count -gt 0) { throw "SYNAPSE_DEPLOYMENT_TRANSACTION_CONTENT_INVALID path=$pathFull entries=$(@($invalid.Name) -join ',')" }
    $validatedStates = New-SynapseCaseInsensitiveMap
    foreach ($entry in @($entries | Where-Object { $_.Name -notmatch '^transaction-\d{4}\.json$' })) {
        $contract = $allowed[$entry.Name]
        if ([bool]$entry.IsDirectory -ne [bool]$contract.Directory -or ([uint32]$entry.Attributes -band [uint32][System.IO.FileAttributes]::ReparsePoint)) { throw "SYNAPSE_DEPLOYMENT_TRANSACTION_ARTIFACT_TYPE_MISMATCH path=$($entry.Path)" }
        $state = Get-SynapsePhysicalRelativeState -ParentPath $pathFull -ParentChain $rootChain -Leaf $entry.Name -Directory:$contract.Directory
        if ($contract.FileIds -inotcontains [string]$state.FileId128 -or
            (-not $contract.Directory -and [string]$contract.Kind -notin @('journal_slot','progress_slot') -and
                ($contract.Hashes -inotcontains [string]$state.Sha256 -or $contract.Lengths -notcontains [int64]$state.Length)) -or
            ([string]$contract.Kind -eq 'progress_slot' -and ([int64]$state.Length -lt 0 -or [int64]$state.Length -gt [int64]$contract.MaximumLength))) {
            throw "SYNAPSE_DEPLOYMENT_TRANSACTION_ARTIFACT_IDENTITY_MISMATCH path=$($entry.Path) file_id_128=$($state.FileId128) sha256=$($state.Sha256) length=$($state.Length)"
        }
        $validatedStates[$entry.Name] = $state
    }
    foreach ($slot in @($journal.Slots)) {
        $state = Get-SynapsePhysicalRelativeState -ParentPath $pathFull -ParentChain $rootChain -Leaf ([string]$slot.Leaf)
        if ([string]$state.FileId128 -ine [string]$slot.FileId128 -or [string]$state.Sha256 -ine [string]$slot.RawSha256 -or [int64]$state.Length -ne [int64]$slot.ByteLength) {
            throw "SYNAPSE_DEPLOYMENT_TRANSACTION_JOURNAL_IDENTITY_DRIFT path=$(Join-Path $pathFull ([string]$slot.Leaf)) sequence=$($slot.Sequence)"
        }
        $validatedStates[[string]$slot.Leaf] = $state
    }
    if ($null -ne $journal.TornTail) {
        $tail = $journal.TornTail
        $state = Get-SynapsePhysicalRelativeState -ParentPath $pathFull -ParentChain $rootChain -Leaf ([string]$tail.Leaf)
        if ([string]$state.FileId128 -ine [string]$tail.FileId128 -or [string]$state.Sha256 -ine [string]$tail.Sha256 -or [int64]$state.Length -ne [int64]$tail.Length) {
            throw "SYNAPSE_DEPLOYMENT_TRANSACTION_TORN_TAIL_IDENTITY_DRIFT path=$(Join-Path $pathFull ([string]$tail.Leaf)) sequence=$($tail.Sequence)"
        }
        $validatedStates[[string]$tail.Leaf] = $state
    }
    foreach ($emptySlot in @($journal.EmptySuffix)) {
        $state = Get-SynapsePhysicalRelativeState -ParentPath $pathFull -ParentChain $rootChain -Leaf ([string]$emptySlot.Leaf)
        if (-not $state.Exists -or [string]$state.FileId128 -ine [string]$emptySlot.FileId128 -or [int64]$state.Length -ne 0) {
            throw "SYNAPSE_DEPLOYMENT_TRANSACTION_EMPTY_SUFFIX_IDENTITY_DRIFT path=$(Join-Path $pathFull ([string]$emptySlot.Leaf)) sequence=$($emptySlot.Sequence)"
        }
        $validatedStates[[string]$emptySlot.Leaf] = $state
    }
    return [pscustomobject]@{ Path=$pathFull; Exists=$true; OwnerPid=$ownerPid; Entries=$entries; Version='v3'; RootChain=$rootChain; RootFileId128=[string]$rootChain[-1].file_id_128; Journal=$journal; Allocation=$allocation; Allowed=$allowed; ValidatedStates=$validatedStates }
}

function Remove-SynapseDeploymentTransactionArtifact {
    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$ExpectedRoot,
        [Parameter(Mandatory=$true)][ValidateSet('unarmed','rolled_back','committed')][string]$ExpectedState,
        [Parameter(Mandatory=$true)][string]$Reason,
        [ValidateSet('application','authority','task')][string]$Domain='application',
        $CleanupAuthorization=$null,
        [ValidateRange(1,60)][int]$TimeoutSeconds=20
    )

    $descriptor = Get-SynapseDeploymentTransactionArtifactDescriptor -Path $Path -ExpectedRoot $ExpectedRoot -ExpectedState $ExpectedState -Domain $Domain
    if (-not $descriptor.Exists) { return $descriptor }
    if ($descriptor.PSObject.Properties['ManifestPath']) {
        return Remove-SynapseDeploymentTransactionArtifactV1 -Path $Path -ExpectedRoot $ExpectedRoot -ExpectedState $ExpectedState -Reason $Reason -TimeoutSeconds $TimeoutSeconds
    }
    $root = [string]$descriptor.Path
    $rootChain = @($descriptor.RootChain)
    $activeAllocation = $script:SynapseDeploymentAllocationContext
    $authorityRollbackSlot = @()
    if ($Domain -ceq 'authority' -and $ExpectedState -ceq 'rolled_back') {
        $authorityRollbackSlot = @($descriptor.Journal.Slots | Where-Object { [string]$_.State -ceq 'rolled_back' } | Select-Object -Last 1)
    }
    if($null-ne$CleanupAuthorization){
        $cleanupReadyRollback = [string]$descriptor.Journal.State -ceq 'cleanup_ready' -and [string]$descriptor.Journal.Latest.detail.terminal_state -ceq 'rolled_back'
        if($Domain-cne'authority' -or $ExpectedState-cne'rolled_back' -or $authorityRollbackSlot.Count-ne1 -or
           ([string]$descriptor.Journal.State-cne'rolled_back' -and -not $cleanupReadyRollback)){throw "SYNAPSE_AUTHORITY_ROLLBACK_CLEANUP_SCOPE_INVALID root=$root domain=$Domain state=$ExpectedState journal=$($descriptor.Journal.State)"}
        $terminal=$authorityRollbackSlot[0].LexicalPayload.detail
        if([string]$CleanupAuthorization.schema-ceq'synapse_authority_failed_successor_cleanup/v1'){
            $authNames=@(Get-SynapseObjectPropertyNames -Object $CleanupAuthorization);$authExpected=@('schema','predecessor_receipt','predecessor_receipt_sha256','failed_terminal_detail_sha256')
            $terminalSha=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $terminal)).ToUpperInvariant()
            $authNamesMatch=$authNames.Count-eq$authExpected.Count -and @($authNames|Where-Object{$authExpected-cnotcontains$_}).Count-eq0
            $terminalModeMatches=[string]$terminal.mode-ceq'predecessor_restored'
            $terminalHashMatches=[string]$CleanupAuthorization.failed_terminal_detail_sha256-ieq$terminalSha
            $receiptHashMatches=[string]$CleanupAuthorization.predecessor_receipt_sha256-ieq[string]$terminal.authority_evidence.predecessor_receipt_sha256
            $receiptMatches=(Get-SynapseCanonicalJson -Value $CleanupAuthorization.predecessor_receipt)-ceq(Get-SynapseCanonicalJson -Value $descriptor.Journal.Initial.predecessor_authority_receipt)
            if(-not$authNamesMatch -or -not$terminalModeMatches -or -not$terminalHashMatches -or -not$receiptHashMatches -or -not$receiptMatches){throw "SYNAPSE_AUTHORITY_FAILED_SUCCESSOR_CLEANUP_AUTHORITY_INVALID root=$root names=$authNamesMatch mode=$terminalModeMatches terminal_hash=$terminalHashMatches expected_terminal_sha=$terminalSha actual_terminal_sha=$($CleanupAuthorization.failed_terminal_detail_sha256) receipt_hash=$receiptHashMatches receipt=$receiptMatches"}
            [void](Assert-SynapseAuthorityPredecessorReceiptDescriptor -Receipt $CleanupAuthorization.predecessor_receipt -Context "failed_successor_cleanup_$root")
        }elseif([string]$CleanupAuthorization.schema-ceq'synapse_authority_committed_successor_predecessor_cleanup/v1'){
            $validatedCleanup=Assert-SynapseAuthorityCommittedSuccessorPredecessorCleanupAuthority -Authority $CleanupAuthorization -Context "committed_successor_cleanup_$root"
            if([string]$terminal.mode-notin@('fresh_monotonic_floor','legacy_prior_unchanged','legacy_direct_recovery') -or [string]$validatedCleanup.Receipt.terminal_mode-cne[string]$terminal.mode -or [string]$validatedCleanup.Receipt.journal.transaction_root_file_id_128-ine[string]$descriptor.RootFileId128 -or (Get-SynapseCanonicalJson -Value $validatedCleanup.Receipt.authority_descriptor)-cne(Get-SynapseCanonicalJson -Value $terminal.authority_evidence)){throw "SYNAPSE_AUTHORITY_COMMITTED_SUCCESSOR_CLEANUP_AUTHORITY_INVALID root=$root"}
        }else{throw "SYNAPSE_AUTHORITY_ROLLBACK_CLEANUP_AUTHORITY_SCHEMA_INVALID root=$root schema=$($CleanupAuthorization.schema)"}
        if ($cleanupReadyRollback) {
            $latestCleanupDetail=$descriptor.Journal.Slots[-1].LexicalPayload.detail
            $latestCleanupNames=@(Get-SynapseObjectPropertyNames -Object $latestCleanupDetail)
            if ($latestCleanupNames-cnotcontains'cleanup_authority' -or
                (Get-SynapseCanonicalJson -Value $latestCleanupDetail.cleanup_authority) -cne (Get-SynapseCanonicalJson -Value $CleanupAuthorization)) {
                throw "SYNAPSE_AUTHORITY_FAILED_SUCCESSOR_CLEANUP_READY_AUTHORITY_DRIFT root=$root"
            }
        }
    }elseif($Domain-ceq'authority' -and $ExpectedState-ceq'rolled_back' -and $authorityRollbackSlot.Count-eq1 -and [string]$authorityRollbackSlot[0].Payload.detail.mode-in@('predecessor_restored','fresh_monotonic_floor','legacy_prior_unchanged','legacy_direct_recovery')){
        throw "SYNAPSE_AUTHORITY_ROLLBACK_CLEANUP_AUTHORITY_REQUIRED root=$root mode=$($authorityRollbackSlot[0].Payload.detail.mode)"
    }
    if ($null -ne $activeAllocation -and
        (Get-SynapseNormalizedDirectoryPath -Path ([string]$activeAllocation.Root)) -ieq $root) {
        Close-SynapseDeploymentAllocationHandles -Context $activeAllocation -PayloadsOnly
    }
    # The fixed allocation marker is the durable authority for every private
    # pre-arm object. Retain it until cleanup_ready is durable; otherwise a
    # crash after deleting one payload artifact but before the cleanup slot
    # would leave the remaining nonempty artifacts without recovery authority.
    foreach ($entry in @($descriptor.Entries | Where-Object {
        $_.Name -notmatch '^transaction-\d{4}\.json$' -and
        $_.Name -cne $script:SynapseDeploymentAllocationMarkerFileName -and
        -not [bool]$_.IsDirectory
    })) {
        $state = $descriptor.ValidatedStates[$entry.Name]
        if ($null -eq $state) { throw "SYNAPSE_DEPLOYMENT_TRANSACTION_CLEANUP_FILE_STATE_MISSING root=$root leaf=$($entry.Name)" }
        Remove-SynapsePhysicalRelativeEntryExact -ParentPath $root -ParentChain $rootChain -Leaf $entry.Name -ExpectedFileId128 ([string]$state.FileId128) -ExpectedSha256 ([string]$state.Sha256) -ExpectedLength ([int64]$state.Length) -Context "cleanup_transaction_file_$Reason"
    }
    foreach ($entry in @($descriptor.Entries | Where-Object { $_.Name -notmatch '^transaction-\d{4}\.json$' -and [bool]$_.IsDirectory })) {
        $state = $descriptor.ValidatedStates[$entry.Name]
        if ($null -eq $state) { throw "SYNAPSE_DEPLOYMENT_TRANSACTION_CLEANUP_DIRECTORY_STATE_MISSING root=$root leaf=$($entry.Name)" }
        Remove-SynapsePhysicalRelativeEntryExact -ParentPath $root -ParentChain $rootChain -Leaf $entry.Name -ExpectedFileId128 ([string]$state.FileId128) -Directory -Context "cleanup_transaction_directory_$Reason"
    }
    if ($descriptor.Version -eq 'v3' -and [string]$descriptor.Journal.State -ne 'cleanup_ready') {
        $terminalState = if ($ExpectedState -eq 'committed') { 'commit_decided' } else { 'rolled_back' }
        $allocationState = $descriptor.ValidatedStates[$script:SynapseDeploymentAllocationMarkerFileName]
        if ($null -eq $allocationState) { throw "SYNAPSE_DEPLOYMENT_TRANSACTION_CLEANUP_ALLOCATION_MARKER_STATE_MISSING root=$root" }
        $cleanupSequence = [int]$descriptor.Journal.Sequence + 1
        if ($cleanupSequence -gt $script:SynapseDeploymentJournalMaxSlots) { throw "SYNAPSE_DEPLOYMENT_TRANSACTION_CLEANUP_SLOT_EXHAUSTED root=$root sequence=$cleanupSequence" }
        $predecessor = $descriptor.Journal.Slots[-1]
        if ([string]$predecessor.State -cne $terminalState) {
            throw "SYNAPSE_DEPLOYMENT_TRANSACTION_CLEANUP_PREDECESSOR_STATE_INVALID root=$root expected=$terminalState actual=$($predecessor.State)"
        }
        $slotRoster = @()
        for ($sequence=1; $sequence -le $script:SynapseDeploymentJournalMaxSlots; $sequence++) {
            $allocatedSlot = $descriptor.Allocation.JournalSlots[$sequence-1]
            $priorSlot = @($descriptor.Journal.Slots | Where-Object Sequence -EQ $sequence)
            if ($sequence -eq $cleanupSequence) {
                $contentState = 'cleanup_ready_self'; $sha256 = ''; $length = -1L
            } elseif ($sequence -lt $cleanupSequence) {
                if ($priorSlot.Count -ne 1) { throw "SYNAPSE_DEPLOYMENT_TRANSACTION_CLEANUP_PRIOR_SLOT_MISSING root=$root sequence=$sequence" }
                $contentState = 'sealed'; $sha256 = ([string]$priorSlot[0].RawSha256).ToUpperInvariant(); $length = [int64]$priorSlot[0].ByteLength
            } else {
                $empty = @($descriptor.Journal.EmptySuffix | Where-Object Sequence -EQ $sequence)
                if ($empty.Count -ne 1) { throw "SYNAPSE_DEPLOYMENT_TRANSACTION_CLEANUP_EMPTY_SLOT_MISSING root=$root sequence=$sequence" }
                $contentState = 'empty'; $sha256 = ''; $length = 0L
            }
            $slotRoster += [ordered]@{
                sequence = $sequence
                leaf = 'transaction-{0:D4}.json' -f $sequence
                file_id_128 = ([string]$allocatedSlot.file_id_128).ToUpperInvariant()
                maximum_length = [int64]$allocatedSlot.maximum_length
                content_state = $contentState
                sha256 = $sha256
                length = $length
            }
        }
        $cleanupPayload = [ordered]@{
            state = 'cleanup_ready'
            recorded_at_utc = [DateTime]::UtcNow.ToString('o')
            static_transaction_sha256 = [string]$descriptor.Journal.Initial.static_transaction_sha256
            detail = [ordered]@{
                terminal_state = $terminalState
                transaction_root_file_id_128 = [string]$descriptor.RootFileId128
                predecessor = [ordered]@{
                    sequence = [int]$predecessor.Sequence
                    state = [string]$predecessor.State
                    leaf = [string]$predecessor.Leaf
                    file_id_128 = ([string]$predecessor.FileId128).ToUpperInvariant()
                    sha256 = ([string]$predecessor.RawSha256).ToUpperInvariant()
                    length = [int64]$predecessor.ByteLength
                }
                allocation_log = [ordered]@{
                    leaf = $script:SynapseDeploymentAllocationMarkerFileName
                    file_id_128 = ([string]$descriptor.Allocation.State.FileId128).ToUpperInvariant()
                    sha256 = ([string]$descriptor.Allocation.RawSha256).ToUpperInvariant()
                    length = [int64]$descriptor.Allocation.ByteLength
                    last_record_sha256 = ([string]$descriptor.Allocation.LastRecordSha256).ToUpperInvariant()
                    record_count = [int]$descriptor.Allocation.RecordCount
                    artifact_count = [int]$descriptor.Allocation.Artifacts.Count
                }
                journal_slots = $slotRoster
                non_journal_artifacts_remaining = 1
            }
        }
        if($null-ne$CleanupAuthorization){$cleanupPayload.detail.cleanup_authority=ConvertTo-SynapseCanonicalValue -Value $CleanupAuthorization}
        $cleanupJournal = Write-SynapseDeploymentTransactionJournalSlot -TransactionRoot $root -TransactionRootChain $rootChain -Sequence $cleanupSequence -InvocationId ([string]$descriptor.Journal.Initial.invocation_id) -PreviousSlotSha256 ([string]$descriptor.Journal.LatestRawSha256) -Payload $cleanupPayload
        $descriptor.Journal = $cleanupJournal
    }
    if ($null -ne $activeAllocation -and
        (Get-SynapseNormalizedDirectoryPath -Path ([string]$activeAllocation.Root)) -ieq $root) {
        Close-SynapseDeploymentAllocationHandles -Context $activeAllocation
        $script:SynapseDeploymentAllocationContext = $null
    }
    $allocationMarkerState = $descriptor.ValidatedStates[$script:SynapseDeploymentAllocationMarkerFileName]
    if ($null -ne $allocationMarkerState) {
        Remove-SynapsePhysicalRelativeEntryExact `
            -ParentPath $root `
            -ParentChain $rootChain `
            -Leaf $script:SynapseDeploymentAllocationMarkerFileName `
            -ExpectedFileId128 ([string]$allocationMarkerState.FileId128) `
            -ExpectedSha256 ([string]$allocationMarkerState.Sha256) `
            -ExpectedLength ([int64]$allocationMarkerState.Length) `
            -Context "cleanup_transaction_allocation_marker_$Reason"
    }
    $journalEntries = @()
    if ($null -ne $descriptor.Journal) {
        $journalEntries += @($descriptor.Journal.Slots | ForEach-Object {
            [pscustomobject]@{ Sequence=[int]$_.Sequence; Leaf=[string]$_.Leaf; FileId128=[string]$_.FileId128; RawSha256=[string]$_.RawSha256; ByteLength=[int64]$_.ByteLength; IsCleanup=([string]$_.State -ceq 'cleanup_ready') }
        })
        $journalEntries += @($descriptor.Journal.EmptySuffix | ForEach-Object {
            $emptyState = $descriptor.ValidatedStates[[string]$_.Leaf]
            [pscustomobject]@{ Sequence=[int]$_.Sequence; Leaf=[string]$_.Leaf; FileId128=[string]$_.FileId128; RawSha256=[string]$emptyState.Sha256; ByteLength=0L; IsCleanup=$false }
        })
    } elseif ($null -ne $descriptor.Allocation) {
        foreach ($slotArtifact in @($descriptor.Allocation.ArtifactOrder | ForEach-Object { $descriptor.Allocation.Artifacts[$_] } | Where-Object kind -CEQ 'journal_slot')) {
            $slotState = $descriptor.ValidatedStates[[string]$slotArtifact.leaf]
            if ($null -ne $slotState) {
                $slotMatch = [regex]::Match([string]$slotArtifact.leaf, '^transaction-(\d{4})\.json$')
                $journalEntries += [pscustomobject]@{ Sequence=[int]$slotMatch.Groups[1].Value; Leaf=[string]$slotArtifact.leaf; FileId128=[string]$slotState.FileId128; RawSha256=[string]$slotState.Sha256; ByteLength=[int64]$slotState.Length; IsCleanup=$false }
            }
        }
    }
    # Keep the latest terminal verdict until every earlier slot and every
    # non-journal artifact is gone. A crash in this final journal-only tail is
    # therefore distinguishable from an armed generation with rollback bytes.
    foreach ($entry in @($journalEntries | Where-Object { -not [bool]$_.IsCleanup } | Sort-Object Sequence)) {
        Remove-SynapsePhysicalRelativeEntryExact -ParentPath $root -ParentChain $rootChain -Leaf ([string]$entry.Leaf) -ExpectedFileId128 ([string]$entry.FileId128) -ExpectedSha256 ([string]$entry.RawSha256) -ExpectedLength ([int64]$entry.ByteLength) -Context "cleanup_transaction_journal_$Reason"
    }
    foreach ($entry in @($journalEntries | Where-Object { [bool]$_.IsCleanup })) {
        Remove-SynapsePhysicalRelativeEntryExact -ParentPath $root -ParentChain $rootChain -Leaf ([string]$entry.Leaf) -ExpectedFileId128 ([string]$entry.FileId128) -ExpectedSha256 ([string]$entry.RawSha256) -ExpectedLength ([int64]$entry.ByteLength) -Context "cleanup_transaction_cleanup_ready_$Reason"
    }
    $parent = Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $root)
    $parentChain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $parent)
    Remove-SynapsePhysicalRelativeEntryExact -ParentPath $parent -ParentChain $parentChain -Leaf (Split-Path -Leaf $root) -ExpectedFileId128 ([string]$descriptor.RootFileId128) -Directory -Context "cleanup_transaction_root_$Reason"
    Info "Deployment transaction artifact cleanup verified reason=$Reason expected_state=$ExpectedState path=$root version=$($descriptor.Version)"
    return $descriptor
}

function Read-SynapseCandidateProbeTaskPlan {
    param(
        [Parameter(Mandatory=$true)][string]$CandidatePath,
        [Parameter(Mandatory=$true)][string]$ExpectedRoot
    )

    $descriptor = Get-SynapseCandidateArtifactDescriptor -Path $CandidatePath -ExpectedRoot $ExpectedRoot
    if (-not $descriptor.Exists) {
        Die "SYNAPSE_CANDIDATE_PROBE_PLAN_ROOT_MISSING path=$CandidatePath"
    }
    $candidateRoot = [string]$descriptor.Path
    $candidateChain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $candidateRoot)
    if ($candidateChain.Count -lt 1) {
        Die "SYNAPSE_CANDIDATE_PROBE_PLAN_ROOT_CHAIN_EMPTY path=$candidateRoot"
    }
    $planLeaf = 'candidate-probe-task-plan.json'
    $planPath = Join-Path $candidateRoot $planLeaf
    $planState = Get-SynapsePhysicalRelativeState -ParentPath $candidateRoot -ParentChain $candidateChain -Leaf $planLeaf
    if (-not $planState.Exists) { return $null }
    if ([int64]$planState.Length -le 0 -or [int64]$planState.Length -gt 65536) {
        Die "SYNAPSE_CANDIDATE_PROBE_PLAN_SIZE_INVALID path=$planPath length=$($planState.Length) max=65536"
    }
    $read = Read-SynapseUtf8TextFileUnderPhysicalRoot -Root $candidateRoot -ExpectedRootIdentity ([string]$descriptor.RootIdentity) -Path $planPath -MaxBytes 65536 -Purpose 'candidate_probe_recovery_plan'
    try {
        $planLexical = ConvertFrom-SynapseJsonPreservingStrings -Json ([string]$read.Content) -MaximumJsonLength 65536
        $plan = [string]$read.Content | ConvertFrom-Json -ErrorAction Stop
    } catch {
        Die "SYNAPSE_CANDIDATE_PROBE_PLAN_JSON_INVALID path=$planPath error=$($_.Exception.Message)"
    }
    if([string]$plan.schema -cne 'synapse_candidate_probe_task_plan/v4'){
        Info "SYNAPSE_CANDIDATE_PROBE_LEGACY_PLAN_PRESERVED path=$planPath schema=$($plan.schema) policy=no_task_cleanup_authority_without_v3_launch_contract_submitted_xml_and_instance_contract"
        return $null
    }
    $expectedNames = @(
        'schema','state','launch_contract_schema','probe_broker_identity_sha256','capability_sha256','invocation_id','candidate_root','candidate_root_file_id_128',
        'task_name','kind','execute','arguments','working_directory','powershell_path','powershell_file_id_128','powershell_sha256','powershell_length','powershell_descriptor','bootstrap_log_path',
        'user_sid','task_create_flag','task_ignore_registration_triggers_flag_absent','trigger_types',
        'task_instance_semantics','maximum_concurrent_instances','cleanup_requires_zero_running_instances','submitted_task_xml_sha256',
        'explicit_security_descriptor','security_descriptor_readback_flags','bootstrap_file_id_128','bootstrap_sha256',
        'bootstrap_length','supervisor_path','supervisor_file_id_128','supervisor_sha256','supervisor_length',
        'bind','db_path','profiles_dir','token_path','created_at_utc','plan_sha256'
    )
    $hasSubmittedSemantic=($null-ne$plan.PSObject.Properties['submitted_task_semantic_sha256'])
    if($hasSubmittedSemantic){$expectedNames += 'submitted_task_semantic_sha256'}
    $actualNames = @($plan.PSObject.Properties.Name)
    if ($actualNames.Count -ne $expectedNames.Count -or @($actualNames | Where-Object { $expectedNames -cnotcontains $_ }).Count -ne 0) {
        Die "SYNAPSE_CANDIDATE_PROBE_PLAN_SHAPE_INVALID path=$planPath expected=$($expectedNames -join ',') actual=$($actualNames -join ',')"
    }
    $canonicalRaw = Get-SynapseCanonicalJson -Value (ConvertTo-SynapseCanonicalValue -Value $planLexical)
    if ([string]$read.Content -cne $canonicalRaw) {
        Die "SYNAPSE_CANDIDATE_PROBE_PLAN_NOT_CANONICAL path=$planPath"
    }
    $core = [ordered]@{}
    foreach ($name in @($expectedNames | Where-Object { $_ -cne 'plan_sha256' })) {
        $core[$name] = $planLexical[$name]
    }
    $calculatedPlanSha256 = (Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $core)).ToUpperInvariant()
    $capability = ([string]$plan.capability_sha256).ToUpperInvariant()
    $taskName = [string]$plan.task_name
    $rootFileId = ([string]$candidateChain[-1].file_id_128).ToUpperInvariant()
    $triggerTypes = @($plan.trigger_types)
    $createdAt = [DateTime]::MinValue
    $createdAtText = if ($plan.created_at_utc -is [DateTime]) {
        ([DateTime]$plan.created_at_utc).ToUniversalTime().ToString('o',[Globalization.CultureInfo]::InvariantCulture)
    } else {
        [string]$plan.created_at_utc
    }
    if ([string]$plan.schema -cne 'synapse_candidate_probe_task_plan/v4' -or
        [string]$plan.state -cne 'prepared_before_task_create' -or
        [string]$plan.launch_contract_schema -cne 'synapse_supervisor_launch_contract/v2' -or
        [string]$plan.probe_broker_identity_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [string]$plan.probe_broker_identity_sha256 -ieq $capability -or
        $capability -notmatch '^[0-9A-F]{64}$' -or
        $taskName -cne ('SynapseMcpProbe-' + $capability.Substring(0,40)) -or
        [string]$plan.kind -cne 'probe' -or
        [string]$plan.plan_sha256 -ine $calculatedPlanSha256 -or
        [string]$plan.invocation_id -notmatch '^[A-Za-z0-9._:-]{1,128}$' -or
        (Get-SynapseNormalizedDirectoryPath -Path ([string]$plan.candidate_root)) -ine $candidateRoot -or
        [string]$plan.candidate_root_file_id_128 -ine $rootFileId -or
        [string]$plan.user_sid -ine (Get-SynapseCurrentUserSid) -or
        [int]$plan.task_create_flag -ne 2 -or
        $plan.task_ignore_registration_triggers_flag_absent -ne $true -or
        $triggerTypes.Count -ne 1 -or [string]$triggerTypes[0] -cne 'registration' -or
        [string]$plan.task_instance_semantics -cne 'registration_trigger_single_oneshot_ignore_new' -or
        [int]$plan.maximum_concurrent_instances -ne 1 -or [bool]$plan.cleanup_requires_zero_running_instances -ne $true -or
        [string]$plan.submitted_task_xml_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or
        ($hasSubmittedSemantic -and [string]$plan.submitted_task_semantic_sha256 -notmatch '^[0-9A-Fa-f]{64}$') -or
        [int]$plan.security_descriptor_readback_flags -ne 7 -or
        -not [DateTime]::TryParseExact($createdAtText,'o',[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::RoundtripKind,[ref]$createdAt)) {
        Die "SYNAPSE_CANDIDATE_PROBE_PLAN_IDENTITY_INVALID path=$planPath task=$taskName capability=$capability"
    }
    [void](Assert-SynapseAuthorityTaskSecurityDescriptorSemantic -SecurityDescriptor ([string]$plan.explicit_security_descriptor) -ExpectedOwnerSid (Get-SynapseCurrentUserSid) -Context "candidate_probe_recovery_plan_$taskName")
    $submittedDefinition=New-SynapseTaskCreateDefinitionPlan -Name ([string]$plan.task_name) -Kind probe -Execute ([string]$plan.execute) -Arguments ([string]$plan.arguments) -WorkingDirectory ([string]$plan.working_directory) -UserSid ([string]$plan.user_sid)
    if([string]$submittedDefinition.SubmittedXmlSha256 -ine [string]$plan.submitted_task_xml_sha256 -or
       ($hasSubmittedSemantic -and [string]$submittedDefinition.SemanticSha256 -ine [string]$plan.submitted_task_semantic_sha256)){Die "SYNAPSE_CANDIDATE_PROBE_RECOVERY_SUBMITTED_DEFINITION_DRIFT path=$planPath task=$taskName"}

    $workingDirectory = Get-SynapseNormalizedDirectoryPath -Path ([string]$plan.working_directory)
    $supervisorPath = [System.IO.Path]::GetFullPath([string]$plan.supervisor_path)
    $bootstrapLogPath = [System.IO.Path]::GetFullPath([string]$plan.bootstrap_log_path)
    $dbPath = Get-SynapseNormalizedDirectoryPath -Path ([string]$plan.db_path)
    $powerShellPath = [System.IO.Path]::GetFullPath([string]$plan.powershell_path)
    $expectedPowerShellPath = [System.IO.Path]::GetFullPath((Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'))
    if ($workingDirectory -ine $candidateRoot -or
        (Split-Path -Parent $supervisorPath) -ine $candidateRoot -or (Split-Path -Leaf $supervisorPath) -cnotmatch '^probe-supervisor-[0-9A-F]{64}\.ps1$' -or
        ([System.IO.Path]::GetFileNameWithoutExtension($supervisorPath)).Substring('probe-supervisor-'.Length) -ine [string]$plan.supervisor_sha256 -or
        $bootstrapLogPath -ine [System.IO.Path]::GetFullPath((Join-Path $candidateRoot 'daemon-supervisor-bootstrap.log')) -or
        $dbPath -ine (Get-SynapseNormalizedDirectoryPath -Path (Join-Path $candidateRoot 'db')) -or
        $powerShellPath -ine $expectedPowerShellPath -or
        [string]$plan.arguments -cne (Get-SynapseSupervisorBootstrapTaskArgumentText -PowerShellPath $powerShellPath -SupervisorPath $supervisorPath -WorkingDirectory $candidateRoot -LogPath $bootstrapLogPath)) {
        Die "SYNAPSE_CANDIDATE_PROBE_PLAN_ACTION_INVALID path=$planPath task=$taskName"
    }
    [void](Get-SynapseBindEndpoint -Bind ([string]$plan.bind))
    foreach ($absoluteField in @('execute','profiles_dir','token_path')) {
        $value = [System.IO.Path]::GetFullPath([string]$plan.$absoluteField)
        if ([string]::IsNullOrWhiteSpace($value) -or -not [System.IO.Path]::IsPathRooted($value)) {
            Die "SYNAPSE_CANDIDATE_PROBE_PLAN_PATH_INVALID path=$planPath field=$absoluteField value=$($plan.$absoluteField)"
        }
    }
    $bootstrapPath = [System.IO.Path]::GetFullPath([string]$plan.execute)
    $bootstrapParent = Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $bootstrapPath)
    if(-not[IO.Directory]::Exists($bootstrapParent)){
        $bootstrapParentAbsence=Get-SynapsePurgeAbsenceAnchor -Path $bootstrapParent -Kind directory -Context "candidate_probe_recovery_bootstrap_parent_absent_$taskName";Assert-SynapsePurgeAbsenceAnchor -Anchor $bootstrapParentAbsence -Context "candidate_probe_recovery_bootstrap_parent_absent_readback_$taskName"
        $lease=Open-SynapsePhysicalFileReadLease -ParentPath $candidateRoot -ParentChain $candidateChain -Leaf $planLeaf -ExpectedFileId128 ([string]$planState.FileId128) -ExpectedSha256 ([string]$planState.Sha256) -ExpectedLength ([int64]$planState.Length) -Context 'candidate_probe_recovery_plan_authority_external_absent'
        return [pscustomobject][ordered]@{Candidate=$descriptor;CandidateChain=$candidateChain;Path=$planPath;State=$planState;Payload=$plan;Lease=$lease;TaskName=$taskName;Kind='probe';Execute=$bootstrapPath;Arguments=[string]$plan.arguments;WorkingDirectory=$candidateRoot;PlanSha256=$calculatedPlanSha256;PowerShellAliasLeaseBundle=$null;ExternalBootstrapAbsent=$true}
    }
    $bootstrapChain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $bootstrapParent)
    $bootstrapState = Get-SynapsePhysicalRelativeState -ParentPath $bootstrapParent -ParentChain $bootstrapChain -Leaf (Split-Path -Leaf $bootstrapPath)
    $supervisorState = Get-SynapsePhysicalRelativeState -ParentPath $candidateRoot -ParentChain $candidateChain -Leaf (Split-Path -Leaf $supervisorPath)
    $powerShellIdentity=Assert-SynapseAuthorityFileDescriptorPhysicalIdentity -Descriptor $plan.powershell_descriptor -ExpectedRole probe_powershell -Context "candidate_probe_recovery_powershell_$taskName"
    if (-not (Test-SynapsePhysicalStateExact -State $bootstrapState -ExpectedExists $true -ExpectedFileId128 ([string]$plan.bootstrap_file_id_128) -ExpectedSha256 ([string]$plan.bootstrap_sha256) -ExpectedLength ([int64]$plan.bootstrap_length)) -or
        -not (Test-SynapsePhysicalStateExact -State $supervisorState -ExpectedExists $true -ExpectedFileId128 ([string]$plan.supervisor_file_id_128) -ExpectedSha256 ([string]$plan.supervisor_sha256) -ExpectedLength ([int64]$plan.supervisor_length)) -or
        [string]$powerShellIdentity.Path -ine $powerShellPath -or [string]$powerShellIdentity.FileId128 -ine [string]$plan.powershell_file_id_128 -or [string]$powerShellIdentity.Sha256 -ine [string]$plan.powershell_sha256 -or [int64]$powerShellIdentity.Length -ne [int64]$plan.powershell_length) {
        $staleLookup=Get-SynapseScheduledTaskLookupExact -Name $taskName;if([bool]$staleLookup.Exists){Die "SYNAPSE_CANDIDATE_PROBE_PLAN_OBJECT_DRIFT path=$planPath task=$taskName task_present=true"}
        $lease=Open-SynapsePhysicalFileReadLease -ParentPath $candidateRoot -ParentChain $candidateChain -Leaf $planLeaf -ExpectedFileId128 ([string]$planState.FileId128) -ExpectedSha256 ([string]$planState.Sha256) -ExpectedLength ([int64]$planState.Length) -Context 'candidate_probe_recovery_plan_authority_external_superseded'
        return [pscustomobject][ordered]@{Candidate=$descriptor;CandidateChain=$candidateChain;Path=$planPath;State=$planState;Payload=$plan;Lease=$lease;TaskName=$taskName;Kind='probe';Execute=$bootstrapPath;Arguments=[string]$plan.arguments;WorkingDirectory=$candidateRoot;PlanSha256=$calculatedPlanSha256;PowerShellAliasLeaseBundle=$null;ExternalBootstrapAbsent=$true}
    }
    $lease = Open-SynapsePhysicalFileReadLease -ParentPath $candidateRoot -ParentChain $candidateChain -Leaf $planLeaf -ExpectedFileId128 ([string]$planState.FileId128) -ExpectedSha256 ([string]$planState.Sha256) -ExpectedLength ([int64]$planState.Length) -Context 'candidate_probe_recovery_plan_authority'
    $powerShellAliasLeaseBundle=$null
    try{
        $powerShellAliasLeaseBundle=Open-SynapseProtectedOsInterpreterAliasLeaseBundle -Descriptor $plan.powershell_descriptor -ExpectedRole probe_powershell -Context "candidate_probe_recovery_powershell_aliases_$taskName"
    }catch{
        try{$lease.Dispose()}catch{[Environment]::FailFast("SYNAPSE_CANDIDATE_PROBE_RECOVERY_PLAN_LEASE_RELEASE_UNPROVEN task=$taskName primary=[$($_.Exception.Message)]",$_.Exception)}
        throw
    }
    return [pscustomobject][ordered]@{
        Candidate=$descriptor; CandidateChain=$candidateChain; Path=$planPath; State=$planState; Payload=$plan
        Lease=$lease; TaskName=$taskName; Kind='probe'; Execute=$bootstrapPath; Arguments=[string]$plan.arguments
        WorkingDirectory=$candidateRoot; PlanSha256=$calculatedPlanSha256; PowerShellAliasLeaseBundle=$powerShellAliasLeaseBundle;ExternalBootstrapAbsent=$false
    }
}

function Resume-SynapseCandidateProbeTaskIntents {
    param([Parameter(Mandatory=$true)][string]$Root)

    $rootDescriptor = Get-SynapseCandidateArtifactRootDescriptor -ExpectedRoot $Root
    if (-not $rootDescriptor.Exists) {
        Info "Candidate probe task recovery root=$($rootDescriptor.Path) planned_count=0 resumed_count=0 retained_count=0"
        return
    }
    $rootFull = [string]$rootDescriptor.Path
    $rootChain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $rootFull)
    $entries = @(Get-SynapsePhysicalDirectoryEntriesBounded -Path $rootFull -Chain $rootChain -MaximumEntries 128 -Context 'candidate_probe_task_root')
    $candidateEntries = @($entries | Where-Object { $_.IsDirectory -and [string]$_.Name -match '^candidate-\d{8}T\d{9}Z-\d+$' } | Sort-Object Name)
    $planned = 0
    $resumed = 0
    $retained = 0
    foreach ($entry in $candidateEntries) {
        $plan = $null
        try {
            $candidatePath = [System.IO.Path]::GetFullPath([string]$entry.Path)
            $candidateDescriptor = Get-SynapseCandidateArtifactDescriptor -Path $candidatePath -ExpectedRoot $rootFull
            $candidateChain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $candidatePath)
            $planState = Get-SynapsePhysicalRelativeState -ParentPath $candidatePath -ParentChain $candidateChain -Leaf 'candidate-probe-task-plan.json'
            if (-not $planState.Exists) { continue }
            $planned++
            $ownerPresence = Get-SynapseKernelProcessPresence -ProcessId ([int]$candidateDescriptor.OwnerPid) -Purpose 'candidate_probe_task_plan_owner'
            if ($ownerPresence.Exists) {
                $retained++
                Info "Candidate probe task plan retained path=$candidatePath setup_owner_pid=$($candidateDescriptor.OwnerPid) reason=setup_owner_pid_still_live"
                continue
            }
            $plan = Read-SynapseCandidateProbeTaskPlan -CandidatePath $candidatePath -ExpectedRoot $rootFull
            if ($null -eq $plan) { continue }
            $terminalPath = Join-Path $candidatePath 'candidate-probe-task-terminal.json'
            $terminalState = Get-SynapsePhysicalRelativeState -ParentPath $candidatePath -ParentChain $candidateChain -Leaf 'candidate-probe-task-terminal.json'
            $scheduler = Get-SynapseScheduledTaskComRoot
            $taskLookup=Get-SynapseScheduledTaskLookupExact -Name ([string]$plan.TaskName) -Scheduler $scheduler
            $registered=if([bool]$taskLookup.Exists){$taskLookup.Task}else{$null}
            if([bool]$plan.ExternalBootstrapAbsent-and$null-ne$registered){Die "SYNAPSE_CANDIDATE_PROBE_EXTERNAL_BOOTSTRAP_ABSENT_TASK_PRESENT task=$($plan.TaskName) bootstrap=$($plan.Execute)"}
            if ($terminalState.Exists) {
                if ($null -ne $registered) {
                    Die "SYNAPSE_CANDIDATE_PROBE_TERMINAL_TASK_PRESENT path=$terminalPath task=$($plan.TaskName)"
                }
                $terminalRead = Read-SynapseUtf8TextFileUnderPhysicalRoot -Root $candidatePath -ExpectedRootIdentity ([string]$candidateDescriptor.RootIdentity) -Path $terminalPath -MaxBytes 65536 -Purpose 'candidate_probe_recovery_terminal'
                try { $terminal = [string]$terminalRead.Content | ConvertFrom-Json -ErrorAction Stop } catch { Die "SYNAPSE_CANDIDATE_PROBE_TERMINAL_JSON_INVALID path=$terminalPath error=$($_.Exception.Message)" }
                $terminalNames = @($terminal.PSObject.Properties.Name)
                $expectedTerminalNames = @('schema','capability_sha256','plan_sha256','task_name','xml_sha256','security_descriptor_sha256','state','deleted_at_utc')
                if ($terminalNames.Count -ne $expectedTerminalNames.Count -or @($terminalNames | Where-Object { $expectedTerminalNames -cnotcontains $_ }).Count -ne 0 -or
                    [string]$terminal.schema -cne 'synapse_candidate_probe_task_terminal/v1' -or
                    [string]$terminal.capability_sha256 -ine [string]$plan.Payload.capability_sha256 -or
                    [string]$terminal.plan_sha256 -ine [string]$plan.PlanSha256 -or
                    [string]$terminal.task_name -cne [string]$plan.TaskName -or
                    [string]$terminal.state -notin @('deleted_after_exact_instance_drain','absent_before_or_after_create')) {
                    Die "SYNAPSE_CANDIDATE_PROBE_TERMINAL_INVALID path=$terminalPath task=$($plan.TaskName)"
                }
                $resumed++
                continue
            }

            $observedTask = $null
            if ($null -ne $registered) {
                foreach($aliasLease in @($plan.PowerShellAliasLeaseBundle.Leases)){$aliasLease.RequireExact("candidate_probe_recovery_before_task_readback_$($plan.TaskName)")}
                $semanticAuthority = [pscustomobject][ordered]@{Path=$plan.Path;FileId128=$plan.State.FileId128;Sha256=$plan.State.Sha256;Length=$plan.State.Length;Lease=$plan.Lease;TaskName=$plan.TaskName;Kind='probe';Execute=$plan.Execute;Arguments=$plan.Arguments;WorkingDirectory=$plan.WorkingDirectory;Payload=$plan.Payload}
                $observedTask = Register-SynapseTaskCreateOnly -Name $plan.TaskName -Kind probe -Execute $plan.Execute -Arguments $plan.Arguments -WorkingDirectory $plan.WorkingDirectory -PlannedSecurityDescriptor ([string]$plan.Payload.explicit_security_descriptor) -SemanticPlanAuthority $semanticAuthority
                foreach($aliasLease in @($plan.PowerShellAliasLeaseBundle.Leases)){$aliasLease.RequireExact("candidate_probe_recovery_after_task_readback_$($plan.TaskName)")}
                $taskLookup=Get-SynapseScheduledTaskLookupExact -Name ([string]$plan.TaskName) -Scheduler $scheduler
                if(-not [bool]$taskLookup.Exists){Die "SYNAPSE_CANDIDATE_PROBE_RECOVERY_TASK_DISAPPEARED task=$($plan.TaskName)"}
                $registered=$taskLookup.Task
                $instances = @($registered.GetInstances(0))
                if($instances.Count -gt 1){Die "SYNAPSE_CANDIDATE_PROBE_RECOVERY_INSTANCE_CARDINALITY_INVALID task=$($plan.TaskName) count=$($instances.Count) expected=0_or_1"}
                foreach ($instance in $instances) { $instance.Stop() }
                $deadline = (Get-Date).AddSeconds(30)
                do {
                    Start-Sleep -Milliseconds 250
                    $taskLookup=Get-SynapseScheduledTaskLookupExact -Name ([string]$plan.TaskName) -Scheduler $scheduler
                    if(-not [bool]$taskLookup.Exists){Die "SYNAPSE_CANDIDATE_PROBE_RECOVERY_TASK_DISAPPEARED_DURING_DRAIN task=$($plan.TaskName)"}
                    $registered=$taskLookup.Task
                    $instances = @($registered.GetInstances(0))
                } while ($instances.Count -ne 0 -and (Get-Date) -lt $deadline)
                if ($instances.Count -ne 0) {
                    Die "SYNAPSE_CANDIDATE_PROBE_RECOVERY_INSTANCES_REMAIN task=$($plan.TaskName) count=$($instances.Count)"
                }
            }
            [void](Assert-SynapseCandidateArtifactCleanupSafe -Path $candidatePath -ExpectedRoot $rootFull -ExpectedCandidateRootIdentity ([string]$candidateDescriptor.RootIdentity) -Bind ([string]$plan.Payload.bind))
            if ($null -ne $observedTask) {
                foreach($aliasLease in @($plan.PowerShellAliasLeaseBundle.Leases)){$aliasLease.RequireExact("candidate_probe_recovery_before_task_delete_$($plan.TaskName)")}
                [void](Remove-SynapseTransientTaskExact -Expected $observedTask -Kind probe -RequireNoRunningInstances)
            }
            $terminal = [ordered]@{
                schema='synapse_candidate_probe_task_terminal/v1';capability_sha256=([string]$plan.Payload.capability_sha256).ToUpperInvariant()
                plan_sha256=([string]$plan.PlanSha256).ToUpperInvariant();task_name=[string]$plan.TaskName
                xml_sha256=$(if($null -eq $observedTask){''}else{[string]$observedTask.XmlSha256})
                security_descriptor_sha256=$(if($null -eq $observedTask){''}else{[string]$observedTask.SecurityDescriptorSha256})
                state=$(if($null -eq $observedTask){'absent_before_or_after_create'}else{'deleted_after_exact_instance_drain'})
                deleted_at_utc=[DateTime]::UtcNow.ToString('o')
            }
            [void](Write-SynapseAtomicUtf8TextFileUnderPhysicalRoot -Root $candidatePath -ExpectedRootIdentity ([string]$candidateDescriptor.RootIdentity) -LeafName 'candidate-probe-task-terminal.json' -Content (Get-SynapseCanonicalJson -Value $terminal) -Purpose 'candidate_probe_recovery_terminal')
            $resumed++
        } catch {
            $retained++
            Info "WARN: candidate probe task plan retained path=$($entry.Path) reason=exact_plan_task_or_quiescence_unverified error=$($_.Exception.Message) remediation=the journal-bound task and candidate storage remain preserved; setup refuses prefix-based task ownership"
            throw
        } finally {
            Close-SynapseCandidateProbeTaskPlanReadLeases -Plan $plan -Context "candidate_probe_recovery_$($(if($null -eq $plan){'unknown'}else{$plan.TaskName}))"
        }
    }
    Info "Candidate probe task recovery root=$rootFull planned_count=$planned resumed_count=$resumed retained_count=$retained"
}

function Resume-SynapseCandidateCleanupIntents {
    param([Parameter(Mandatory=$true)][string]$Root)

    $rootDescriptor = Get-SynapseCandidateArtifactRootDescriptor -ExpectedRoot $Root
    if (-not $rootDescriptor.Exists) {
        Info "Candidate cleanup intent recovery root=$($rootDescriptor.Path) intent_count=0 resumed_count=0 retained_count=0"
        return
    }
    $rootFull = $rootDescriptor.Path
    $resumed = 0
    $retained = 0
    $intents = @(Get-ChildItem -LiteralPath $rootFull -Force -ErrorAction Stop | Where-Object {
        $_.Name -match '^candidate-cleanup-\d{8}T\d{9}Z-\d+\.json$'
    } | Sort-Object Name)
    foreach ($file in $intents) {
        $intent = $null
        try {
            $intent = Read-SynapseCandidateCleanupIntent -IntentPath $file.FullName -ExpectedRoot $rootFull
            $intentOwnerPresence = Get-SynapseKernelProcessPresence -ProcessId $intent.SetupOwnerPid -Purpose 'candidate_cleanup_intent_owner'
            if ($intentOwnerPresence.Exists) {
                $retained++
                Info "Candidate cleanup intent retained path=$($intent.Path) candidate=$($intent.CandidatePath) setup_owner_pid=$($intent.SetupOwnerPid) reason=setup_owner_pid_still_live"
                continue
            }
            $intentCandidateDescriptor=Get-SynapseCandidateArtifactDescriptor -Path $intent.CandidatePath -ExpectedRoot $rootFull
            $intentCandidateChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $intentCandidateDescriptor.Path)
            $intentProbePlanState=Get-SynapsePhysicalRelativeState -ParentPath $intentCandidateDescriptor.Path -ParentChain $intentCandidateChain -Leaf 'candidate-probe-task-plan.json'
            if($intentProbePlanState.Exists){
                $intentProbePlan=Read-SynapseCandidateProbeTaskPlan -CandidatePath $intentCandidateDescriptor.Path -ExpectedRoot $rootFull
                if($null -eq $intentProbePlan){
                    $retained++
                    Info "SYNAPSE_CANDIDATE_CLEANUP_INTENT_LEGACY_PROBE_PLAN_PRESERVED path=$($intentCandidateDescriptor.Path) intent=$($intent.Path) policy=v1_plan_cannot_authorize_task_or_wrapper_cleanup"
                    continue
                }
                Close-SynapseCandidateProbeTaskPlanReadLeases -Plan $intentProbePlan -Context "candidate_cleanup_intent_$($intentProbePlan.TaskName)"
            }
            [void](Remove-SynapseCandidateArtifact `
                -Path $intent.CandidatePath `
                -ExpectedRoot $rootFull `
                -ExpectedCandidateRootIdentity $intent.CandidateRootIdentity `
                -CandidateProcessId $intent.CandidatePid `
                -Bind $intent.Bind `
                -Reason $intent.Reason)
            $resumed++
        } catch {
            $retained++
            $intentPath = if ($null -eq $intent) { $file.FullName } else { $intent.Path }
            $intentCandidate = if ($null -eq $intent) { '<unreadable>' } else { $intent.CandidatePath }
            $intentCandidatePid = if ($null -eq $intent) { 0 } else { $intent.CandidatePid }
            $intentBind = if ($null -eq $intent) { '<unreadable>' } else { $intent.Bind }
            Info "WARN: candidate cleanup intent retained path=$intentPath candidate=$intentCandidate candidate_pid=$intentCandidatePid bind=$intentBind reason=journal_or_exact_quiescence_unverified error=$($_.Exception.Message) remediation=the durable journal and candidate evidence remain untouched; setup retries deletion only after typed authority and PID/path/socket Source of Truth are readable and unowned"
            continue
        }
    }
    Info "Candidate cleanup intent recovery root=$rootFull intent_count=$($intents.Count) resumed_count=$resumed retained_count=$retained"
}

function Remove-SynapseStaleSuccessfulCandidateArtifacts {
    param([Parameter(Mandatory=$true)][string]$Root)

    $rootDescriptor = Get-SynapseCandidateArtifactRootDescriptor -ExpectedRoot $Root
    if (-not $rootDescriptor.Exists) {
        Info "Stale successful candidate sweep root=$($rootDescriptor.Path) eligible_count=0 removed_count=0 retained_count=0"
        return
    }
    $rootFull = $rootDescriptor.Path
    $removed = 0
    $retained = 0
    $eligible = 0
    foreach ($child in @(Get-ChildItem -LiteralPath $rootFull -Force -ErrorAction Stop | Where-Object {
        $_.Name -match '^candidate-\d{8}T\d{9}Z-\d+$'
    } | Sort-Object Name)) {
        $descriptor = $null
        try {
        $descriptor = Get-SynapseCandidateArtifactDescriptor -Path $child.FullName -ExpectedRoot $rootFull
        $candidateChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $descriptor.Path)
        $probePlanState=Get-SynapsePhysicalRelativeState -ParentPath $descriptor.Path -ParentChain $candidateChain -Leaf 'candidate-probe-task-plan.json'
        if($probePlanState.Exists){
            $cleanupPlan=Read-SynapseCandidateProbeTaskPlan -CandidatePath $descriptor.Path -ExpectedRoot $rootFull
            if($null -eq $cleanupPlan){
                $retained++
                Info "SYNAPSE_CANDIDATE_STALE_LEGACY_PROBE_PLAN_PRESERVED path=$($descriptor.Path) policy=v1_plan_cannot_authorize_task_or_wrapper_cleanup"
                continue
            }
            Close-SynapseCandidateProbeTaskPlanReadLeases -Plan $cleanupPlan -Context "candidate_stale_success_$($cleanupPlan.TaskName)"
        }
        $diagnosticPath = Join-Path $descriptor.Path 'candidate-diagnostic.json'
        $diagnosticEntries = @(Get-ChildItem -LiteralPath $descriptor.Path -Force -ErrorAction Stop | Where-Object {
            $_.Name.Equals('candidate-diagnostic.json', [System.StringComparison]::OrdinalIgnoreCase)
        })
        if ($diagnosticEntries.Count -gt 0) {
            $retained++
            Info "Candidate failure evidence retained path=$($descriptor.Path) diagnostic_path=$diagnosticPath matching_entry_count=$($diagnosticEntries.Count) reason=diagnostic_entry_present"
            continue
        }
        $successMarkerPath = Join-Path $descriptor.Path 'candidate-success.json'
        try {
            $successMarkerRead = Read-SynapseUtf8TextFileUnderPhysicalRoot `
                -Root $descriptor.Path `
                -ExpectedRootIdentity ([string]$descriptor.RootIdentity) `
                -Path $successMarkerPath `
                -MaxBytes 131072 `
                -Purpose 'stale_candidate_success_marker'
            $success = [string]$successMarkerRead.Content | ConvertFrom-Json -ErrorAction Stop
        } catch {
            throw "SYNAPSE_CANDIDATE_STALE_SUCCESS_MARKER_MISSING_OR_UNREADABLE path=$successMarkerPath error=$($_.Exception.Message) remediation=preserve the exact candidate directory; setup will not infer success from partial health, shutdown, or Job evidence"
        }
        $successDrift = [System.Collections.Generic.List[string]]::new()
        if ([string]$success.schema -cne 'synapse_candidate_success/v1') { $successDrift.Add("schema expected=synapse_candidate_success/v1 actual=$($success.schema)") }
        if ([string]$success.state -cne 'verified') { $successDrift.Add("state expected=verified actual=$($success.state)") }
        if ([int]$success.setup_owner_pid -ne $descriptor.OwnerPid) { $successDrift.Add("setup_owner_pid expected=$($descriptor.OwnerPid) actual=$($success.setup_owner_pid)") }
        if (-not ([string]$success.candidate_root).Equals($descriptor.Path, [System.StringComparison]::OrdinalIgnoreCase)) { $successDrift.Add("candidate_root expected=$($descriptor.Path) actual=$($success.candidate_root)") }
        if ([string]$success.candidate_root_identity -notmatch '^(?:[0-9A-Fa-f]{8}:[0-9A-Fa-f]{16}|[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32})$') { $successDrift.Add("candidate_root_identity invalid=$($success.candidate_root_identity)") }
        elseif ([string]$success.candidate_root_identity -ine [string]$descriptor.RootIdentity) { $successDrift.Add("candidate_root_identity expected=$($descriptor.RootIdentity) actual=$($success.candidate_root_identity)") }
        if ([int]$success.candidate_pid -le 0) { $successDrift.Add("candidate_pid invalid=$($success.candidate_pid)") }
        if ([int]$success.supervisor_pid -le 0) { $successDrift.Add("supervisor_pid invalid=$($success.supervisor_pid)") }
        if ([int]$success.bootstrap_pid -le 0) { $successDrift.Add("bootstrap_pid invalid=$($success.bootstrap_pid)") }
        if ([int]$success.authenticated_shutdown_exit_code -ne $SynapseAuthenticatedShutdownExitCode) { $successDrift.Add("authenticated_shutdown_exit_code expected=$SynapseAuthenticatedShutdownExitCode actual=$($success.authenticated_shutdown_exit_code)") }
        if ([string]::IsNullOrWhiteSpace([string]$success.bind)) { $successDrift.Add('bind missing') }
        if ([string]$success.job_limit_flags_hex -cne '0x00002300') { $successDrift.Add("job_limit_flags_hex expected=0x00002300 actual=$($success.job_limit_flags_hex)") }
        if ([string]$success.daemon_process_memory_limit_bytes -cne [string]$SynapseDaemonProcessMemoryLimitBytes) { $successDrift.Add("daemon_process_memory_limit_bytes expected=$SynapseDaemonProcessMemoryLimitBytes actual=$($success.daemon_process_memory_limit_bytes)") }
        if ([string]$success.daemon_job_memory_limit_bytes -cne [string]$SynapseDaemonProcessMemoryLimitBytes) { $successDrift.Add("daemon_job_memory_limit_bytes expected=$SynapseDaemonProcessMemoryLimitBytes actual=$($success.daemon_job_memory_limit_bytes)") }
        if ([string]$success.parent_process_memory_limit_bytes -cne [string]$SynapseOwnedMemoryLimitBytes) { $successDrift.Add("parent_process_memory_limit_bytes expected=$SynapseOwnedMemoryLimitBytes actual=$($success.parent_process_memory_limit_bytes)") }
        if ([string]$success.parent_job_memory_limit_bytes -cne [string]$SynapseOwnedMemoryLimitBytes) { $successDrift.Add("parent_job_memory_limit_bytes expected=$SynapseOwnedMemoryLimitBytes actual=$($success.parent_job_memory_limit_bytes)") }
        if ([string]$success.daemon_cpu_rate -cne [string]$SynapseDaemonCpuRate) { $successDrift.Add("daemon_cpu_rate expected=$SynapseDaemonCpuRate actual=$($success.daemon_cpu_rate)") }
        if ([string]$success.parent_cpu_rate -cne [string]$SynapseSupervisorCpuRate) { $successDrift.Add("parent_cpu_rate expected=$SynapseSupervisorCpuRate actual=$($success.parent_cpu_rate)") }
        if ([string]$success.working_set_policy -cne 'measured_only') { $successDrift.Add("working_set_policy expected=measured_only actual=$($success.working_set_policy)") }
        foreach ($hashField in @('candidate_health_final_sha256', 'bootstrap_sha256', 'bootstrap_log_sha256', 'final_state_sha256', 'executable_sha256', 'tool_surface_sha256')) {
            if ([string]$success.$hashField -notmatch '^[0-9A-Fa-f]{64}$') {
                $successDrift.Add("$hashField invalid=$($success.$hashField)")
            }
        }
        $probeTaskName = [string]$success.probe_task_name
        if (-not [string]::IsNullOrWhiteSpace($probeTaskName)) {
            if ($probeTaskName -notmatch '^SynapseMcpProbe-[0-9A-Fa-f]{40}$') { $successDrift.Add("probe_task_name invalid=$probeTaskName") }
            if ([string]$success.probe_task_xml_sha256 -notmatch '^[0-9A-Fa-f]{64}$') { $successDrift.Add("probe_task_xml_sha256 invalid=$($success.probe_task_xml_sha256)") }
            if ([string]$success.probe_task_security_descriptor_sha256 -notmatch '^[0-9A-Fa-f]{64}$') { $successDrift.Add("probe_task_security_descriptor_sha256 invalid=$($success.probe_task_security_descriptor_sha256)") }
            if ([string]$success.probe_task_terminal -cne 'deleted_after_exact_instance_drain') { $successDrift.Add("probe_task_terminal expected=deleted_after_exact_instance_drain actual=$($success.probe_task_terminal)") }
        } elseif ($success.PSObject.Properties.Name -contains 'probe_task_terminal' -and [string]$success.probe_task_terminal -cne 'not_applicable_direct_launch') {
            $successDrift.Add("probe_task_terminal expected=not_applicable_direct_launch actual=$($success.probe_task_terminal)")
        }
        if ($successDrift.Count -gt 0) {
            throw "SYNAPSE_CANDIDATE_STALE_SUCCESS_MARKER_MISMATCH path=$successMarkerPath drift=$($successDrift -join '; ') remediation=preserve the exact candidate directory; the durable post-validation marker is not the expected closed contract"
        }

        if (-not [string]::IsNullOrWhiteSpace($probeTaskName)) {
            $probeTerminalPath = Join-Path $descriptor.Path 'candidate-probe-task-terminal.json'
            try {
                $probeTerminalRead = Read-SynapseUtf8TextFileUnderPhysicalRoot -Root $descriptor.Path -ExpectedRootIdentity ([string]$descriptor.RootIdentity) -Path $probeTerminalPath -MaxBytes 65536 -Purpose 'stale_candidate_probe_terminal'
                $probeTerminal = [string]$probeTerminalRead.Content | ConvertFrom-Json -ErrorAction Stop
            } catch {
                throw "SYNAPSE_CANDIDATE_STALE_PROBE_TERMINAL_UNREADABLE path=$probeTerminalPath error=$($_.Exception.Message) remediation=preserve the candidate directory until its journal-bound transient task terminal record is exact"
            }
            if ([string]$probeTerminal.schema -cne 'synapse_candidate_probe_task_terminal/v1' -or
                [string]$probeTerminal.task_name -cne $probeTaskName -or
                [string]$probeTerminal.xml_sha256 -ine [string]$success.probe_task_xml_sha256 -or
                [string]$probeTerminal.security_descriptor_sha256 -ine [string]$success.probe_task_security_descriptor_sha256 -or
                [string]$probeTerminal.state -cne 'deleted_after_exact_instance_drain') {
                throw "SYNAPSE_CANDIDATE_STALE_PROBE_TERMINAL_MISMATCH path=$probeTerminalPath task=$probeTaskName remediation=preserve the candidate directory; cleanup requires the exact task XML/SD deletion receipt"
            }
            $probeScheduler = Get-SynapseScheduledTaskComRoot
            $unexpectedProbeLookup=Get-SynapseScheduledTaskLookupExact -Name $probeTaskName -Scheduler $probeScheduler
            if ([bool]$unexpectedProbeLookup.Exists) {
                throw "SYNAPSE_CANDIDATE_STALE_PROBE_TASK_PRESENT path=$($descriptor.Path) task=$probeTaskName remediation=preserve candidate storage; the random journal-bound transient task must be absent before recursive cleanup"
            }
        }

        $healthPath = Join-Path $descriptor.Path 'candidate-health-final.json'
        $terminalStatePath = Join-Path $descriptor.Path 'daemon-supervisor-current.json'
        $bootstrapLogPath = Join-Path $descriptor.Path 'daemon-supervisor-bootstrap.log'
        $successEvidenceContent = @{}
        foreach ($evidenceContract in @(
            [pscustomobject]@{ Name = 'candidate_health_final'; Path = $healthPath; Sha256 = [string]$success.candidate_health_final_sha256 },
            [pscustomobject]@{ Name = 'supervisor_final_state'; Path = $terminalStatePath; Sha256 = [string]$success.final_state_sha256 },
            [pscustomobject]@{ Name = 'bootstrap_log'; Path = $bootstrapLogPath; Sha256 = [string]$success.bootstrap_log_sha256 }
        )) {
            try {
                $evidenceRead = Read-SynapseUtf8TextFileUnderPhysicalRoot `
                    -Root $descriptor.Path `
                    -ExpectedRootIdentity ([string]$descriptor.RootIdentity) `
                    -Path $evidenceContract.Path `
                    -MaxBytes 16777216 `
                    -Purpose "stale_candidate_$($evidenceContract.Name)"
                $evidenceSha256 = [string]$evidenceRead.Sha256
                $successEvidenceContent[$evidenceContract.Name] = [string]$evidenceRead.Content
            } catch {
                throw "SYNAPSE_CANDIDATE_STALE_SUCCESS_EVIDENCE_UNREADABLE path=$($descriptor.Path) evidence=$($evidenceContract.Name) evidence_path=$($evidenceContract.Path) error=$($_.Exception.Message) remediation=preserve the exact candidate directory; cleanup requires every success-marker-bound evidence file"
            }
            if ($evidenceSha256 -ine $evidenceContract.Sha256) {
                throw "SYNAPSE_CANDIDATE_STALE_SUCCESS_EVIDENCE_MISMATCH path=$($descriptor.Path) evidence=$($evidenceContract.Name) evidence_path=$($evidenceContract.Path) expected_sha256=$($evidenceContract.Sha256) actual_sha256=$evidenceSha256 remediation=preserve the exact candidate directory; marker-bound evidence changed after validation"
            }
        }
        try {
            $health = [string]$successEvidenceContent['candidate_health_final'] | ConvertFrom-Json -ErrorAction Stop
            $terminalState = [string]$successEvidenceContent['supervisor_final_state'] | ConvertFrom-Json -ErrorAction Stop
            $bootstrapLog = [string]$successEvidenceContent['bootstrap_log']
        } catch {
            throw "SYNAPSE_CANDIDATE_STALE_SUCCESS_EVIDENCE_DECODE_FAILED path=$($descriptor.Path) health_path=$healthPath state_path=$terminalStatePath bootstrap_log=$bootstrapLogPath error=$($_.Exception.Message) remediation=preserve the exact candidate directory; cleanup requires decodable marker-bound evidence"
        }
        $recordedPid = [int]$success.candidate_pid
        $terminalSupervisorPid = [int]$success.supervisor_pid
        $terminalBootstrapPid = [int]$success.bootstrap_pid
        $terminalDrift = [System.Collections.Generic.List[string]]::new()
        if ($health.ok -ne $true) { $terminalDrift.Add("health_ok expected=True actual=$($health.ok)") }
        if ([int]$health.pid -ne $recordedPid) { $terminalDrift.Add("health_pid expected=$recordedPid actual=$($health.pid)") }
        if ([int]$health.tool_count -ne [int]$success.tool_count -or [int]$health.tool_count -lt 1) { $terminalDrift.Add("tool_count expected=$($success.tool_count) actual=$($health.tool_count)") }
        if ([string]$health.tool_surface_sha256 -ine [string]$success.tool_surface_sha256) { $terminalDrift.Add("tool_surface_sha256 expected=$($success.tool_surface_sha256) actual=$($health.tool_surface_sha256)") }
        if ([string]::IsNullOrWhiteSpace([string]$health.build)) { $terminalDrift.Add('health_build missing') }
        if (-not ([string]$health.subsystems.http.bind_addr).Equals([string]$success.bind, [System.StringComparison]::Ordinal)) { $terminalDrift.Add("health_bind expected=$($success.bind) actual=$($health.subsystems.http.bind_addr)") }
        if ([string]$terminalState.state -cne 'stopped') { $terminalDrift.Add("state expected=stopped actual=$($terminalState.state)") }
        if ([int]$terminalState.supervisor_pid -ne $terminalSupervisorPid) { $terminalDrift.Add("supervisor_pid expected=$terminalSupervisorPid actual=$($terminalState.supervisor_pid)") }
        if ([int]$terminalState.child_pid -ne $recordedPid) { $terminalDrift.Add("child_pid expected=$recordedPid actual=$($terminalState.child_pid)") }
        if ([int]$terminalState.exit_code -ne $SynapseAuthenticatedShutdownExitCode) { $terminalDrift.Add("exit_code expected=$SynapseAuthenticatedShutdownExitCode actual=$($terminalState.exit_code)") }
        if ([string]$terminalState.supervisor_job_name -cne [string]$success.parent_job_name) { $terminalDrift.Add("supervisor_job_name expected=$($success.parent_job_name) actual=$($terminalState.supervisor_job_name)") }
        $expectedBootstrapExit = "SYNAPSE_SUPERVISOR_BOOTSTRAP_CHILD_EXIT bootstrap_pid=$terminalBootstrapPid mode=outer_complete_tree supervisor_pid=$terminalSupervisorPid job_cpu_rate=$SynapseSupervisorCpuRate exit_code=$SynapseAuthenticatedShutdownExitCode"
        if (-not $bootstrapLog.Contains($expectedBootstrapExit)) { $terminalDrift.Add("bootstrap_terminal_entry missing=[$expectedBootstrapExit]") }
        foreach ($terminalPid in @($recordedPid, $terminalSupervisorPid, $terminalBootstrapPid) | Sort-Object -Unique) {
            $terminalPresence = Get-SynapseKernelProcessPresence -ProcessId $terminalPid -Purpose 'stale_candidate_terminal_identity'
            if ($terminalPresence.Exists) {
                $terminalDrift.Add("terminal_pid_still_live pid=$terminalPid")
            }
        }
        if ($terminalDrift.Count -gt 0) {
            throw "SYNAPSE_CANDIDATE_STALE_TERMINAL_IDENTITY_MISMATCH path=$($descriptor.Path) marker=$successMarkerPath drift=$($terminalDrift -join '; ') remediation=preserve the exact candidate directory; cleanup requires the marker-bound stopped one-shot tree and final healthy identity"
        }
        $recordedPidPath = Join-Path $descriptor.Path 'db\daemon.pid'
        $recordedPidSource = 'durable_success_marker'
        $recordedPidParent = Split-Path -Parent $recordedPidPath
        try {
            $recordedPidParentItem = Get-Item -LiteralPath $recordedPidParent -Force -ErrorAction Stop
            if (-not $recordedPidParentItem.PSIsContainer -or
                ($recordedPidParentItem.Attributes -band [System.IO.FileAttributes]::ReparsePoint)) {
                throw "PID parent is not a non-reparse directory attributes=$($recordedPidParentItem.Attributes)"
            }
            $recordedPidEntries = @(Get-ChildItem -LiteralPath $recordedPidParent -Force -ErrorAction Stop | Where-Object {
                $_.Name.Equals('daemon.pid', [System.StringComparison]::OrdinalIgnoreCase)
            })
        } catch {
            throw "SYNAPSE_CANDIDATE_STALE_PID_PARENT_UNREADABLE path=$($descriptor.Path) pid_parent=$recordedPidParent error=$($_.Exception.Message) remediation=preserve the exact candidate directory; cleanup must enumerate the physical PID parent before treating daemon.pid as absent"
        }
        if ($recordedPidEntries.Count -gt 1) {
            throw "SYNAPSE_CANDIDATE_STALE_PID_AMBIGUOUS path=$($descriptor.Path) pid_path=$recordedPidPath matching_entry_count=$($recordedPidEntries.Count) remediation=preserve the exact candidate directory; cleanup requires zero or one exact daemon.pid child entry"
        }
        if ($recordedPidEntries.Count -eq 1) {
            $pidSidecarValue = 0
            try {
                $pidSidecarItem = $recordedPidEntries[0]
                if ($pidSidecarItem.PSIsContainer -or
                    ($pidSidecarItem.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -or
                    -not $pidSidecarItem.FullName.Equals([System.IO.Path]::GetFullPath($recordedPidPath), [System.StringComparison]::OrdinalIgnoreCase)) {
                    throw "PID sidecar is not a non-reparse regular file attributes=$($pidSidecarItem.Attributes)"
                }
                $pidSidecarRead = Read-SynapseUtf8TextFileUnderPhysicalRoot `
                    -Root $descriptor.Path `
                    -ExpectedRootIdentity ([string]$descriptor.RootIdentity) `
                    -Path $pidSidecarItem.FullName `
                    -MaxBytes 64 `
                    -Purpose 'stale_candidate_daemon_pid'
                $recordedPidText = ([string]$pidSidecarRead.Content).Trim()
            } catch {
                throw "SYNAPSE_CANDIDATE_STALE_PID_UNREADABLE path=$($descriptor.Path) pid_path=$recordedPidPath error=$($_.Exception.Message) remediation=preserve the exact candidate directory; the present physical PID record must be readable"
            }
            if (-not [int]::TryParse($recordedPidText, [ref]$pidSidecarValue) -or $pidSidecarValue -ne $recordedPid) {
                throw "SYNAPSE_CANDIDATE_STALE_PID_MISMATCH path=$($descriptor.Path) health_pid=$($health.pid) recorded_pid=$pidSidecarValue pid_path=$recordedPidPath remediation=preserve the directory; stale cleanup authority is inconsistent"
            }
            $recordedPidSource = 'live_daemon_pid_sidecar'
        } else {
            Info "Stale successful candidate marker and terminal identity verified path=$($descriptor.Path) marker=$successMarkerPath candidate_pid=$recordedPid supervisor_pid=$terminalSupervisorPid bootstrap_pid=$terminalBootstrapPid exit_code=$SynapseAuthenticatedShutdownExitCode pid_sidecar=absent source=$recordedPidSource"
        }
        $recordedBind = [string]$success.bind
        $ownerPresence = Get-SynapseKernelProcessPresence -ProcessId $descriptor.OwnerPid -Purpose 'stale_candidate_setup_owner'
        if ($ownerPresence.Exists) {
            $retained++
            Info "Stale successful candidate retained path=$($descriptor.Path) owner_pid=$($descriptor.OwnerPid) candidate_pid=$recordedPid candidate_pid_source=$recordedPidSource reason=setup_owner_pid_still_live"
            continue
        }
        $eligible++
        # Avoid creating a durable cleanup intent for routine PID, path-reference,
        # or ephemeral-port reuse. The journal begins only after this independent
        # read-only quiescence check succeeds; Remove rechecks it before deletion.
        [void](Assert-SynapseCandidateArtifactCleanupSafe `
            -Path $descriptor.Path `
            -ExpectedRoot $rootFull `
            -ExpectedCandidateRootIdentity ([string]$success.candidate_root_identity) `
            -CandidateProcessId $recordedPid `
            -Bind $recordedBind)
        [void](Remove-SynapseCandidateArtifact `
            -Path $descriptor.Path `
            -ExpectedRoot $rootFull `
            -ExpectedCandidateRootIdentity ([string]$success.candidate_root_identity) `
            -CandidateProcessId $recordedPid `
            -Bind $recordedBind `
            -Reason 'startup_stale_validated_candidate')
        Info "Stale successful candidate cleanup identity consumed path=$($descriptor.Path) candidate_pid=$recordedPid candidate_pid_source=$recordedPidSource bind=$recordedBind"
        $removed++
        } catch {
            $retained++
            $retainedPath = if ($null -eq $descriptor) { $child.FullName } else { $descriptor.Path }
            Info "WARN: SYNAPSE_CANDIDATE_STALE_STATE_RETAINED path=$retainedPath error=$($_.Exception.Message) remediation=the exact candidate artifact was preserved because success evidence, physical path type, or current PID/path/socket quiescence was not independently provable"
            continue
        }
    }
    Info "Stale successful candidate sweep root=$rootFull eligible_count=$eligible removed_count=$removed retained_count=$retained"
}

function Remove-SynapseExpiredCandidateFailureEvidence {
    param(
        [Parameter(Mandatory=$true)][string]$Root,
        [ValidateRange(1, 20)][int]$Keep = 5
    )

    $rootDescriptor = Get-SynapseCandidateArtifactRootDescriptor -ExpectedRoot $Root
    if (-not $rootDescriptor.Exists) { return }
    $rootFull = $rootDescriptor.Path
    $failureBundles = [System.Collections.Generic.List[object]]::new()
    foreach ($child in @(Get-ChildItem -LiteralPath $rootFull -Force -ErrorAction Stop | Where-Object {
        $_.Name -match '^candidate-\d{8}T\d{9}Z-\d+$'
    })) {
        try {
            $descriptor = Get-SynapseCandidateArtifactDescriptor -Path $child.FullName -ExpectedRoot $rootFull
            $candidateChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $descriptor.Path)
            $probePlanState=Get-SynapsePhysicalRelativeState -ParentPath $descriptor.Path -ParentChain $candidateChain -Leaf 'candidate-probe-task-plan.json'
            if($probePlanState.Exists){
                $retentionPlan=Read-SynapseCandidateProbeTaskPlan -CandidatePath $descriptor.Path -ExpectedRoot $rootFull
                if($null -eq $retentionPlan){
                    Info "SYNAPSE_CANDIDATE_FAILURE_LEGACY_PROBE_PLAN_PRESERVED path=$($descriptor.Path) policy=v1_plan_cannot_authorize_task_or_wrapper_cleanup"
                    continue
                }
                Close-SynapseCandidateProbeTaskPlanReadLeases -Plan $retentionPlan -Context "candidate_failure_retention_$($retentionPlan.TaskName)"
            }
            $diagnosticEntries = @(Get-ChildItem -LiteralPath $descriptor.Path -Force -ErrorAction Stop | Where-Object {
                $_.Name.Equals('candidate-diagnostic.json', [System.StringComparison]::OrdinalIgnoreCase)
            })
        } catch {
            Info "WARN: candidate failure retention skipped ambiguous artifact path=$($child.FullName) error=$($_.Exception.Message) remediation=the exact entry is preserved; retention never follows or deletes an unreadable/non-physical candidate path"
            continue
        }
        if ($diagnosticEntries.Count -gt 0) {
            $failureBundles.Add([pscustomobject]@{
                Descriptor = $descriptor
                DiagnosticEntries = @($diagnosticEntries)
                LastWriteTimeUtc = $child.LastWriteTimeUtc
            })
        }
    }
    $orderedBundles = @($failureBundles | Sort-Object LastWriteTimeUtc -Descending)
    foreach ($expired in @($orderedBundles | Select-Object -Skip $Keep)) {
        $descriptor = $expired.Descriptor
        $diagnosticPath = Join-Path $descriptor.Path 'candidate-diagnostic.json'
        if ($expired.DiagnosticEntries.Count -ne 1) {
            Info "WARN: expired candidate failure evidence retained path=$($descriptor.Path) diagnostic_path=$diagnosticPath reason=diagnostic_entry_ambiguous matching_entry_count=$($expired.DiagnosticEntries.Count)"
            continue
        }
        $diagnosticItem = $expired.DiagnosticEntries[0]
        if (-not $diagnosticItem.FullName.Equals($diagnosticPath, [System.StringComparison]::OrdinalIgnoreCase) -or
            $diagnosticItem.PSIsContainer -or
            ($diagnosticItem.Attributes -band [System.IO.FileAttributes]::ReparsePoint)) {
            Info "WARN: expired candidate failure evidence retained path=$($descriptor.Path) diagnostic_path=$diagnosticPath reason=diagnostic_entry_not_regular attributes=$($diagnosticItem.Attributes)"
            continue
        }
        try {
            $diagnosticRead = Read-SynapseUtf8TextFileUnderPhysicalRoot `
                -Root $descriptor.Path `
                -ExpectedRootIdentity ([string]$descriptor.RootIdentity) `
                -Path $diagnosticItem.FullName `
                -MaxBytes 1048576 `
                -Purpose 'expired_candidate_failure_diagnostic'
            $failure = [string]$diagnosticRead.Content | ConvertFrom-Json -ErrorAction Stop
            $candidatePid = [int]$failure.candidate_pid
            $candidateRootIdentity = [string]$failure.candidate_root_identity
            $supervisorPid = [int]$failure.supervisor_pid
            $bootstrapPid = [int]$failure.bootstrap_pid
            $recordedBind = [string]$failure.bind
        } catch {
            Info "WARN: expired candidate failure evidence retained path=$($descriptor.Path) diagnostic_path=$diagnosticPath reason=diagnostic_decode_failed error=$($_.Exception.Message)"
            continue
        }
        if ([string]$failure.schema -cne 'synapse_candidate_failure/v1' -or
            $failure.cleanup_verified -isnot [bool] -or
            $failure.cleanup_verified -ne $true -or
            $failure.process_has_exited -isnot [bool] -or
            $failure.process_has_exited -ne $true -or
            $candidatePid -le 0 -or
            $supervisorPid -le 0 -or
            $bootstrapPid -le 0 -or
            $candidateRootIdentity -notmatch '^(?:[0-9A-Fa-f]{8}:[0-9A-Fa-f]{16}|[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32})$' -or
            $candidateRootIdentity -ine [string]$descriptor.RootIdentity -or
            @($failure.cleanup_errors).Count -ne 0 -or
            [string]::IsNullOrWhiteSpace($recordedBind)) {
            Info "WARN: expired candidate failure evidence retained path=$($descriptor.Path) diagnostic_path=$diagnosticPath reason=cleanup_or_identity_not_verified schema=$($failure.schema) cleanup_verified=$($failure.cleanup_verified) cleanup_error_count=$(@($failure.cleanup_errors).Count) process_has_exited=$($failure.process_has_exited) candidate_pid=$candidatePid supervisor_pid=$supervisorPid bootstrap_pid=$bootstrapPid candidate_root_identity=$candidateRootIdentity actual_root_identity=$($descriptor.RootIdentity) bind=$recordedBind"
            continue
        }
        $terminalIdentityLive = [System.Collections.Generic.List[string]]::new()
        try {
            foreach ($terminalIdentity in @(
                [pscustomobject]@{ Role = 'setup_owner'; Pid = [int]$descriptor.OwnerPid },
                [pscustomobject]@{ Role = 'candidate'; Pid = $candidatePid },
                [pscustomobject]@{ Role = 'supervisor'; Pid = $supervisorPid },
                [pscustomobject]@{ Role = 'bootstrap'; Pid = $bootstrapPid }
            )) {
                $presence = Get-SynapseKernelProcessPresence `
                    -ProcessId ([int]$terminalIdentity.Pid) `
                    -Purpose "expired_candidate_failure_$($terminalIdentity.Role)"
                if ($presence.Exists) {
                    $terminalIdentityLive.Add("role=$($terminalIdentity.Role),pid=$($terminalIdentity.Pid)")
                }
            }
        } catch {
            Info "WARN: expired candidate failure evidence retained path=$($descriptor.Path) diagnostic_path=$diagnosticPath reason=terminal_identity_sot_unreadable error=$($_.Exception.Message)"
            continue
        }
        if ($terminalIdentityLive.Count -gt 0) {
            Info "WARN: expired candidate failure evidence retained path=$($descriptor.Path) diagnostic_path=$diagnosticPath reason=terminal_identity_live identities=$($terminalIdentityLive -join ';')"
            continue
        }
        try {
            # Check before journaling so routine PID/port reuse keeps evidence but
            # does not create a cleanup intent that would block the next setup.
            [void](Assert-SynapseCandidateArtifactCleanupSafe `
                -Path $descriptor.Path `
                -ExpectedRoot $rootFull `
                -ExpectedCandidateRootIdentity $candidateRootIdentity `
                -CandidateProcessId $candidatePid `
                -Bind $recordedBind)
            [void](Remove-SynapseCandidateArtifact `
                -Path $descriptor.Path `
                -ExpectedRoot $rootFull `
                -ExpectedCandidateRootIdentity $candidateRootIdentity `
                -CandidateProcessId $candidatePid `
                -Bind $recordedBind `
                -Reason 'expired_verified_candidate_failure')
            Info "Expired verified candidate failure evidence removed path=$($descriptor.Path) candidate_pid=$candidatePid bind=$recordedBind retention_keep=$Keep"
        } catch {
            Info "WARN: expired candidate failure evidence retained path=$($descriptor.Path) candidate_pid=$candidatePid bind=$recordedBind reason=exact_quiescence_or_cleanup_unverified error=$($_.Exception.Message)"
        }
    }
}

function Stop-SynapseExactCandidateProcess {
    param(
        [Parameter(Mandatory=$true)][System.Diagnostics.Process]$Process,
        [Parameter(Mandatory=$true)]$MappedLease,
        [Parameter(Mandatory=$true)][int]$ExpectedParentProcessId,
        [Parameter(Mandatory=$true)][int]$ExpectedSessionId,
        [Parameter(Mandatory=$true)][string]$ExpectedImagePath,
        [Parameter(Mandatory=$true)][string]$ExpectedCommandLine,
        [Parameter(Mandatory=$true)][string[]]$ExpectedArguments,
        [Parameter(Mandatory=$true)][int[]]$PathArgumentIndexes,
        [Parameter(Mandatory=$true)][string]$ExpectedCreationDate,
        [Parameter(Mandatory=$true)][string]$JobName,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$Token,
        [string]$Reason = 'candidate_health'
    )
    $processId=[int]$Process.Id
    $creation=[int64]$MappedLease.CreationTimeFileTime
    $Process.Refresh()
    if($Process.HasExited){
        [SynapseAuthorityRuntime.MappedProcessLease]::RequireIdentityGone([uint32]$processId,$creation,"${Reason}_already_exited")
        Wait-SynapseBindReleased -Reason $Reason -Bind $Bind -TimeoutSeconds 5
        return
    }
    $assertBoundary={
        param([string]$Phase)
        $MappedLease.RequireExact("${Reason}_${Phase}_mapped")
        $record=Assert-SynapseMappedProcessMetadataUnderLease -Lease $MappedLease -ExpectedProcessId $processId -ExpectedParentProcessId $ExpectedParentProcessId -ExpectedSessionId $ExpectedSessionId -ExpectedImagePath $ExpectedImagePath -ExpectedCommandLine $ExpectedCommandLine -ExpectedCreationDate $ExpectedCreationDate -Context "${Reason}_${Phase}_metadata"
        [void](Assert-SynapseProcessCommandLineExact -Process $record -ExpectedArguments $ExpectedArguments -PathArgumentIndexes $PathArgumentIndexes -Context "${Reason}_${Phase}_argv")
        $job=Get-SynapseDaemonJobKernelReadback -JobName $JobName
        $jobIds=@($job.ProcessIds|ForEach-Object{[int]$_})
        # Candidate MCP calls may create setup-owned descendants (for example a
        # shell tool child) which inherit the daemon Job.  The exact mapped
        # daemon and listener remain the destructive authority; every additional
        # member is already kernel-contained by that same sealed Job.  Requiring
        # singleton membership makes safe cleanup fail precisely when a real
        # tool exercised descendant creation.
        if($jobIds.Count-lt 1 -or $processId-notin$jobIds){Die "SYNAPSE_CANDIDATE_STOP_JOB_IDENTITY_DRIFT phase=$Phase pid=$processId job=$JobName members=$($jobIds-join ',')"}
        $listeners=@(Get-SynapseTcpBindListenerSnapshot -Bind $Bind)
        if($listeners.Count-ne 1 -or [int]$listeners[0].OwningProcess-ne$processId){Die "SYNAPSE_CANDIDATE_STOP_LISTENER_IDENTITY_DRIFT phase=$Phase pid=$processId bind=$Bind listeners=$(Format-SynapseTcpBindListenerSnapshot -Snapshot $listeners)"}
    }
    & $assertBoundary 'before_graceful_shutdown'

    $shutdown = Request-SynapseGracefulShutdown -Bind $Bind -Token $Token -ExpectedPids @($processId) -Reason $Reason
    if ($shutdown.Ok) {
        if($Process.WaitForExit(10000)){
            [SynapseAuthorityRuntime.MappedProcessLease]::RequireIdentityGone([uint32]$processId,$creation,"${Reason}_graceful_exit")
            Wait-SynapseBindReleased -Reason $Reason -Bind $Bind -TimeoutSeconds 5
            Info "Candidate daemon graceful shutdown verified pid=$processId creation_filetime_utc=$creation bind=$Bind"
            return
        }
    } else {
        Info "WARN: candidate graceful shutdown failed pid=$processId bind=$Bind code=$($shutdown.Code) error=$($shutdown.Error); falling back to retained-handle stop"
    }
    & $assertBoundary 'immediately_before_force'
    try{$Process.Kill()}catch{if(-not $Process.WaitForExit(0)){throw}}
    if(-not $Process.WaitForExit(10000)){Die "SYNAPSE_CANDIDATE_STOP_TIMEOUT pid=$processId bind=$Bind job=$JobName"}
    [SynapseAuthorityRuntime.MappedProcessLease]::RequireIdentityGone([uint32]$processId,$creation,"${Reason}_forced_exit")
    Info "Candidate daemon retained-handle force stop verified pid=$processId creation_filetime_utc=$creation bind=$Bind"
    Wait-SynapseBindReleased -Reason $Reason -Bind $Bind -TimeoutSeconds 5
}

function Get-SynapseCandidateReplacementReservationId {
    param(
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$Token,
        [Parameter(Mandatory=$true)][string]$LogDir,
        [Parameter(Mandatory=$true)][string]$CalyxConfigPath,
        [Parameter(Mandatory=$true)][ValidatePattern('^[0-9A-Fa-f]{64}$')][string]$ExpectedCalyxConfigSha256
    )

    $listeners = @(Get-SynapseTcpBindListenerSnapshot -Bind $Bind)
    if ($listeners.Count -eq 0) { return $null }
    if ($listeners.Count -ne 1) {
        Die "SYNAPSE_GPU_REPLACEMENT_LISTENER_AMBIGUOUS bind=$Bind listeners=$(Format-SynapseTcpBindListenerSnapshot -Snapshot $listeners) remediation=repair the configured daemon listener before candidate validation"
    }
    $listener = $listeners[0]
    if (-not $listener.OwnerExists -or -not (Test-SynapseMcpExecutableLeafName -Name $listener.OwnerName)) {
        Die "SYNAPSE_GPU_REPLACEMENT_LISTENER_INVALID bind=$Bind pid=$($listener.OwningProcess) owner=$($listener.OwnerName) remediation=the configured bind must be owned by the exact live Synapse daemon before replacement admission"
    }

    $expectedConfigPath = [System.IO.Path]::GetFullPath($CalyxConfigPath)
    $expectedConfigSha = $ExpectedCalyxConfigSha256.ToUpperInvariant()
    if (-not (Test-Path -LiteralPath $expectedConfigPath -PathType Leaf) -or
        (Get-SynapseFileSha256 -Path $expectedConfigPath) -ine $expectedConfigSha) {
        Die "SYNAPSE_GPU_REPLACEMENT_CPU_CONFIG_IDENTITY_MISMATCH path=$expectedConfigPath expected_sha256=$expectedConfigSha remediation=restore the exact setup-sealed CPU-only configuration before candidate validation"
    }

    $healthRead = Read-SynapseHealthForRestartGuard -Bind $Bind -Token $Token -TimeoutSec 10
    $health = if ($healthRead.Ok) { $healthRead.Health } else { $null }
    # #1890: identity and fitness are two different questions about the outgoing daemon and must
    # not share one gate. Identity (does the process answering /health hold the listen socket?) is
    # the real replacement hazard -- a leaked socket or a second daemon -- and still refuses.
    # Fitness (health.ok) is NOT a precondition for replacing the outgoing daemon: an unhealthy
    # daemon is the strongest reason to replace it, and gating on it deadlocks every deploy whose
    # whole purpose is to fix why health is false. The candidate's fitness is decided separately
    # in Test-SynapseCandidateDaemon, which is the process whose fitness is actually in question.
    $liveHealthPid = if ($null -eq $health -or $null -eq $health.pid) { 0 } else { [int]$health.pid }
    if ($null -ne $health -and $liveHealthPid -ne [int]$listener.OwningProcess) {
        Die "SYNAPSE_GPU_REPLACEMENT_HEALTH_IDENTITY_MISMATCH bind=$Bind listener_pid=$($listener.OwningProcess) health_pid=$(if ($null -eq $health.pid) { '<absent>' } else { $liveHealthPid }) failing_term=health_pid_ne_listener_pid remediation=the process answering authenticated /health is not the process holding the listen socket; repair the exact daemon process/socket identity (leaked listen socket or a second daemon) before candidate validation"
    }
    if ($null -ne $health -and $health.ok -ne $true) {
        $liveSubsystemStatuses = @()
        if ($health.subsystems) {
            foreach ($prop in @($health.subsystems.PSObject.Properties | Sort-Object Name)) {
                $status = [string]$prop.Value.status
                if ($status -and $status -ne 'ok') { $liveSubsystemStatuses += ("{0}={1}" -f $prop.Name, $status) }
            }
        }
        $liveStatusText = if ($liveSubsystemStatuses.Count -gt 0) { $liveSubsystemStatuses -join ',' } else { '<none-not-ok>' }
        Info "SYNAPSE_GPU_REPLACEMENT_OUTGOING_DAEMON_UNHEALTHY bind=$Bind live_pid=$($listener.OwningProcess) health_ok=false identity_verified=true not_ok_subsystems=$liveStatusText note=replacement proceeds; process/socket/health identity is consistent and replacing an unhealthy daemon is the remedy, not a reason to refuse"
    }
    $calyxHealth = if ($null -ne $health) { $health.subsystems.calyx_vault } else { $null }
    $selectedBackend = if ($null -ne $calyxHealth) { [string]$calyxHealth.calyx_math_backend } else { '' }
    $probeStatus = if ($null -ne $calyxHealth) { [string]$calyxHealth.calyx_math_probe_status } else { '' }
    $healthReservationId = if ($null -ne $calyxHealth) { [string]$calyxHealth.calyx_gpu_reservation_id } else { '' }
    if ($null -eq $health) {
        $supervisorStatePath = Join-Path $LogDir 'daemon-supervisor-current.json'
        try { $supervisorState = Get-Content -LiteralPath $supervisorStatePath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop }
        catch { Die "SYNAPSE_GPU_REPLACEMENT_CPU_STATE_UNREADABLE path=$supervisorStatePath health_error=$($healthRead.Error) state_error=$($_.Exception.Message) remediation=repair the exact supervisor state publication before candidate validation" }
        $stateConfigPath = try { [System.IO.Path]::GetFullPath([string]$supervisorState.calyx_config_path) } catch { '' }
        if ([int]$supervisorState.child_pid -ne [int]$listener.OwningProcess -or
            [string]$supervisorState.bind -cne $Bind -or
            [string]$supervisorState.math_backend -cne 'cpu' -or
            [int64]$supervisorState.vram_budget_bytes -ne 0 -or
            $stateConfigPath -ine $expectedConfigPath -or
            [string]$supervisorState.calyx_config_sha256 -ine $expectedConfigSha) {
            Die "SYNAPSE_GPU_REPLACEMENT_CPU_STATE_MISMATCH path=$supervisorStatePath listener_pid=$($listener.OwningProcess) state_child_pid=$($supervisorState.child_pid) bind=$Bind state_bind=$($supervisorState.bind) state_backend=$($supervisorState.math_backend) state_vram_budget_bytes=$($supervisorState.vram_budget_bytes) expected_config=$expectedConfigPath state_config=$stateConfigPath expected_config_sha256=$expectedConfigSha state_config_sha256=$($supervisorState.calyx_config_sha256) remediation=repair the exact CPU-only supervisor/process/config identity before candidate validation"
        }
        $selectedBackend = 'cpu'
        Info "SYNAPSE_GPU_REPLACEMENT_CPU_IDENTITY_FROM_SUPERVISOR bind=$Bind live_pid=$($listener.OwningProcess) state_path=$supervisorStatePath health_unreadable=$($healthRead.Error) note=the sealed CPU-only supervisor state and physical GPU ledger are the reservation Source of Truth"
    }
    # Same split for the Calyx subsystem: the datum this function needs from it is the selected math
    # backend (which decides whether a GPU reservation has to be handed off at all). That datum being
    # readable is the precondition; the subsystem's aggregate verdict is not. Every exactness check
    # the handoff actually depends on -- ledger row, reservation id shape, lease file -- still runs
    # below and still refuses under its own precise code.
    if ([string]::IsNullOrWhiteSpace($selectedBackend)) {
        Die "SYNAPSE_GPU_REPLACEMENT_CALYX_BACKEND_UNREADABLE bind=$Bind live_pid=$($listener.OwningProcess) calyx_status=$(if ([string]$calyxHealth.status) { [string]$calyxHealth.status } else { '<absent>' }) selected_backend=<absent> failing_term=calyx_math_backend_absent remediation=authenticated health must name the live daemon's Calyx math backend so the GPU reservation handoff can be decided; repair the live Calyx vault subsystem before candidate validation"
    }
    if ([string]$calyxHealth.status -ne 'ok') {
        Info "SYNAPSE_GPU_REPLACEMENT_OUTGOING_CALYX_NOT_OK bind=$Bind live_pid=$($listener.OwningProcess) calyx_status=$([string]$calyxHealth.status) selected_backend=$selectedBackend note=replacement proceeds; the backend needed for the reservation decision is readable and every reservation exactness check below still refuses under its own code"
    }

    $programData = [Environment]::GetFolderPath([Environment+SpecialFolder]::CommonApplicationData)
    if ([string]::IsNullOrWhiteSpace($programData)) {
        Die 'SYNAPSE_GPU_REPLACEMENT_ROOT_UNAVAILABLE remediation=Windows CommonApplicationData is required to verify the host GPU reservation ledger'
    }
    $statePath = Join-Path $programData 'Calyx\gpu-reservations\device-0\reservations.json'
    $state = $null
    $statePresent = Test-Path -LiteralPath $statePath -PathType Leaf
    if ($statePresent) {
        try {
            $state = Get-Content -LiteralPath $statePath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
        } catch {
            Die "SYNAPSE_GPU_REPLACEMENT_LEDGER_UNREADABLE path=$statePath error=$($_.Exception.Message) remediation=repair the host GPU reservation Source of Truth before candidate validation"
        }
        $stateProperties = @($state.PSObject.Properties.Name)
        if ([int]$state.schema_version -ne 1 -or [int]$state.device_index -ne 0 -or $stateProperties -notcontains 'reservations') {
            Die "SYNAPSE_GPU_REPLACEMENT_LEDGER_SCHEMA_INVALID path=$statePath schema_version=$(if ($null -eq $state.schema_version) { '<absent>' } else { [string]$state.schema_version }) device_index=$(if ($null -eq $state.device_index) { '<absent>' } else { [string]$state.device_index }) reservations_present=$($stateProperties -contains 'reservations') remediation=repair the device-0 host GPU reservation ledger schema before candidate validation"
        }
    }

    $pidRows = if ($null -eq $state) {
        @()
    } else {
        @($state.reservations | Where-Object { [int]$_.pid -eq [int]$listener.OwningProcess })
    }
    if ($selectedBackend -ine 'cuda') {
        if (-not [string]::IsNullOrWhiteSpace($healthReservationId) -or $pidRows.Count -ne 0) {
            Die "SYNAPSE_GPU_REPLACEMENT_NON_CUDA_STATE_CONFLICT path=$(if ($statePresent) { $statePath } else { '<absent>' }) live_pid=$($listener.OwningProcess) selected_backend=$selectedBackend health_reservation_id=$(if ($healthReservationId) { $healthReservationId } else { '<none>' }) ledger_pid_row_count=$($pidRows.Count) remediation=repair the mixed Calyx backend/GPU reservation state before candidate validation"
        }
        Info "Candidate replacement reservation not required bind=$Bind live_pid=$($listener.OwningProcess) selected_backend=$selectedBackend health_reservation_id=<none> ledger_pid_row_count=0 state_path=$(if ($statePresent) { $statePath } else { '<absent>' })"
        return $null
    }

    if (-not $statePresent) {
        Die "SYNAPSE_GPU_REPLACEMENT_LEDGER_MISSING path=$statePath live_pid=$($listener.OwningProcess) selected_backend=$selectedBackend health_reservation_id=$(if ($healthReservationId) { $healthReservationId } else { '<none>' }) remediation=repair the live CUDA daemon GPU reservation Source of Truth before candidate validation"
    }
    # #2239 made CUDA ownership demand-driven. `dormant` means no caller has
    # created a context or reservation yet; after a caller, the final release
    # destroys the context and publishes `dormant_verified` only after a
    # separate ledger read. A candidate therefore needs a replacement
    # reservation only while the outgoing daemon has an active lease. Preserve
    # every mixed-state refusal: only those two explicit idle lifecycle states
    # are accepted, and only when health plus the current physical ledger
    # independently prove there is nothing to hand off.
    if (@('dormant', 'dormant_verified') -icontains $probeStatus) {
        if (-not [string]::IsNullOrWhiteSpace($healthReservationId) -or $pidRows.Count -ne 0) {
            Die "SYNAPSE_GPU_REPLACEMENT_IDLE_STATE_CONFLICT path=$statePath live_pid=$($listener.OwningProcess) selected_backend=$selectedBackend probe_status=$probeStatus health_reservation_id=$(if ($healthReservationId) { $healthReservationId } else { '<none>' }) ledger_pid_row_count=$($pidRows.Count) remediation=dormant and dormant_verified require an absent health reservation identity and zero physical ledger rows for the exact live daemon"
        }
        try {
            $stateHash = (Get-FileHash -LiteralPath $statePath -Algorithm SHA256 -ErrorAction Stop).Hash
        } catch {
            Die "SYNAPSE_GPU_REPLACEMENT_LEDGER_HASH_FAILED path=$statePath live_pid=$($listener.OwningProcess) error=$($_.Exception.Message) remediation=repair physical read access to the host GPU reservation Source of Truth before candidate validation"
        }
        Info "SYNAPSE_GPU_REPLACEMENT_IDLE_VERIFIED bind=$Bind live_pid=$($listener.OwningProcess) selected_backend=$selectedBackend probe_status=$probeStatus health_reservation_id=<none> ledger_pid_row_count=0 ledger_reservation_count=$(@($state.reservations).Count) ledger_sha256=$stateHash state_path=$statePath note=no active CUDA context or host lease exists to hand off; candidate admission remains independently validated"
        return $null
    }
    if ($healthReservationId -notmatch '^[0-9a-fA-F]{32}$') {
        Die "SYNAPSE_GPU_REPLACEMENT_HEALTH_RESERVATION_INVALID path=$statePath live_pid=$($listener.OwningProcess) selected_backend=$selectedBackend probe_status=$(if ($probeStatus) { $probeStatus } else { '<absent>' }) health_reservation_id=$(if ($healthReservationId) { $healthReservationId } else { '<none>' }) remediation=repair the live CUDA daemon health reservation identity before candidate validation"
    }
    $matches = @($pidRows | Where-Object {
        [string]$_.owner -eq 'synapse-mcp' -and
        [string]$_.reservation_id -ieq $healthReservationId -and
        [string]::IsNullOrWhiteSpace([string]$_.replaces_reservation_id)
    })
    if ($pidRows.Count -ne 1 -or $matches.Count -ne 1) {
        Die "SYNAPSE_GPU_REPLACEMENT_RESERVATION_AMBIGUOUS path=$statePath live_pid=$($listener.OwningProcess) health_reservation_id=$healthReservationId ledger_pid_row_count=$($pidRows.Count) exact_match_count=$($matches.Count) remediation=the live CUDA daemon must own exactly one primary device-0 reservation matching authenticated health before candidate validation"
    }
    $row = $matches[0]
    if (-not (Test-Path -LiteralPath ([string]$row.lease_file) -PathType Leaf)) {
        Die "SYNAPSE_GPU_REPLACEMENT_RESERVATION_INVALID path=$statePath live_pid=$($listener.OwningProcess) reservation_id=$($row.reservation_id) lease=$($row.lease_file) remediation=repair the exact live reservation row/lease before candidate validation"
    }
    Info "Candidate replacement reservation verified bind=$Bind live_pid=$($listener.OwningProcess) reservation_id=$($row.reservation_id) requested_mib=$($row.requested_mib) state_path=$statePath"
    return [string]$row.reservation_id
}

function Write-SynapseCandidateJsonEvidence {
    param(
        [Parameter(Mandatory=$true)][string]$CandidateRoot,
        [Parameter(Mandatory=$true)][ValidatePattern('^(?:[0-9A-Fa-f]{8}:[0-9A-Fa-f]{16}|[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32})$')][string]$CandidateRootIdentity,
        [Parameter(Mandatory=$true)][ValidatePattern('^candidate-[a-z0-9-]+\.json$')][string]$LeafName,
        [Parameter(Mandatory=$true)]$Value
    )

    $rootFull = [System.IO.Path]::GetFullPath($CandidateRoot).TrimEnd('\')
    $path = [System.IO.Path]::GetFullPath((Join-Path $CandidateRoot $LeafName))
    $parent = [System.IO.Path]::GetFullPath((Split-Path -Parent $path)).TrimEnd('\')
    if (-not $parent.Equals($rootFull, [System.StringComparison]::OrdinalIgnoreCase)) {
        Die "SYNAPSE_CANDIDATE_EVIDENCE_SCOPE_INVALID path=$path expected_parent=$rootFull actual_parent=$parent remediation=refuse to write candidate evidence outside the exact isolated candidate directory"
    }
    try {
        $json = $Value | ConvertTo-Json -Depth 30
        $readback = $json | ConvertFrom-Json -ErrorAction Stop
        $physicalWrite = Write-SynapseAtomicUtf8TextFileUnderPhysicalRoot `
            -Root $rootFull `
            -ExpectedRootIdentity $CandidateRootIdentity `
            -LeafName $LeafName `
            -Content $json `
            -Purpose 'candidate_json_evidence'
        $sha256 = [string]$physicalWrite.sha256
        $length = [uint64]$physicalWrite.byte_length
    } catch {
        Die "SYNAPSE_CANDIDATE_EVIDENCE_WRITE_FAILED path=$path error=$($_.Exception.Message) remediation=repair the exact candidate evidence directory before setup can accept or reject this binary"
    }
    return [pscustomobject]@{
        Path = $path
        Sha256 = $sha256
        Length = $length
        FileIdentity = [string]$physicalWrite.file_identity
        Readback = $readback
    }
}

function Test-SynapseCpuOnlyRuntimeHealth {
    param([Parameter(Mandatory=$true)]$Health)

    $calyx = $Health.subsystems.calyx_vault
    if ($null -eq $calyx) {
        return [pscustomobject]@{
            Ok = $false
            Detail = 'SYNAPSE_CPU_ONLY_HEALTH_MISSING: health.subsystems.calyx_vault is absent; remediation=repair Calyx startup health before accepting the daemon'
        }
    }
    $requiredFields = @(
        'calyx_math_backend_requested',
        'calyx_math_backend',
        'calyx_assay_compute_backend',
        'calyx_math_cuda_compiled',
        'calyx_registry_embedding_runtimes_compiled',
        'calyx_ward_model_lenses_compiled',
        'calyx_sextant_cuvs_compiled',
        'calyx_sextant_cuda_pq_compiled',
        'calyx_vram_budget_bytes',
        'calyx_vram_budget_enforced'
    )
    $missingFields = @($requiredFields | Where-Object {
        $null -eq $calyx.PSObject.Properties[$_] -or
        $null -eq $calyx.PSObject.Properties[$_].Value
    })
    if ($missingFields.Count -gt 0) {
        return [pscustomobject]@{
            Ok = $false
            Detail = "SYNAPSE_CPU_ONLY_HEALTH_FIELD_MISSING: fields=$($missingFields -join ','); remediation=run the current CPU-only binary whose health schema explicitly attests every accelerator compile/runtime field"
        }
    }
    $requested = $calyx.calyx_math_backend_requested
    $selected = $calyx.calyx_math_backend
    $assay = $calyx.calyx_assay_compute_backend
    $cudaCompiled = $calyx.calyx_math_cuda_compiled
    $registryEmbeddingRuntimesCompiled = $calyx.calyx_registry_embedding_runtimes_compiled
    $wardModelLensesCompiled = $calyx.calyx_ward_model_lenses_compiled
    $sextantCuvsCompiled = $calyx.calyx_sextant_cuvs_compiled
    $sextantCudaPqCompiled = $calyx.calyx_sextant_cuda_pq_compiled
    $vramBudgetEnforced = $calyx.calyx_vram_budget_enforced
    $reservationId = [string]$calyx.calyx_gpu_reservation_id
    $booleanFields = @(
        $cudaCompiled,
        $registryEmbeddingRuntimesCompiled,
        $wardModelLensesCompiled,
        $sextantCuvsCompiled,
        $sextantCudaPqCompiled,
        $vramBudgetEnforced
    )
    # These five Rust Option fields use skip_serializing_if=None. Their JSON
    # property absence is therefore the authoritative CPU-only `None`, not a
    # schema omission: the required false VRAM-enforcement and accelerator
    # compile flags above establish this health contract. PowerShell reads both
    # an absent property and an explicit null as $null; any non-null dispatch
    # value remains rejected by $dispatchAbsent below.
    $dispatchFields = @(
        $calyx.calyx_vram_dispatch_soft_cap_bytes,
        $calyx.calyx_vram_dispatch_allocated_bytes,
        $calyx.calyx_vram_dispatch_serving_allocated_bytes,
        $calyx.calyx_vram_dispatch_anneal_allocated_bytes,
        $calyx.calyx_vram_dispatch_device_free_bytes
    )
    if (@($booleanFields | Where-Object { $_ -isnot [bool] }).Count -gt 0 -or
        $requested -isnot [string] -or $selected -isnot [string] -or $assay -isnot [string] -or
        $calyx.calyx_vram_budget_bytes -is [string] -or
        $calyx.calyx_vram_budget_bytes -is [bool]) {
        return [pscustomobject]@{
            Ok = $false
            Detail = 'SYNAPSE_CPU_ONLY_HEALTH_TYPE_INVALID: backend fields must be JSON strings, compile fields JSON booleans, and VRAM fields JSON numbers; remediation=repair the typed health schema instead of relying on PowerShell null/string coercion'
        }
    }
    try {
        $vramBudget = [uint64]$calyx.calyx_vram_budget_bytes
    } catch {
        return [pscustomobject]@{
            Ok = $false
            Detail = "SYNAPSE_CPU_ONLY_HEALTH_NUMERIC_INVALID: vram_budget=$($calyx.calyx_vram_budget_bytes) error=$($_.Exception.Message); remediation=repair typed Calyx health serialization"
        }
    }
    $dispatchAbsent = @($dispatchFields | Where-Object { $null -ne $_ }).Count -eq 0
    $ok = (
        $requested -ceq 'cpu' -and
        $selected -ceq 'cpu' -and
        $assay -ceq 'cpu' -and
        $cudaCompiled -eq $false -and
        $registryEmbeddingRuntimesCompiled -eq $false -and
        $wardModelLensesCompiled -eq $false -and
        $sextantCuvsCompiled -eq $false -and
        $sextantCudaPqCompiled -eq $false -and
        $vramBudget -eq 0 -and
        $vramBudgetEnforced -eq $false -and
        $dispatchAbsent -and
        [string]::IsNullOrWhiteSpace($reservationId))
    return [pscustomobject]@{
        Ok = $ok
        Detail = $(if ($ok) {
            "requested=cpu selected=cpu assay=cpu cuda_compiled=false registry_embedding_runtimes_compiled=false ward_model_lenses_compiled=false sextant_cuvs_compiled=false sextant_cuda_pq_compiled=false vram_budget_bytes=0 vram_budget_enforced=false vram_dispatch=<absent> gpu_reservation_id=<none>"
        } else {
            "SYNAPSE_CPU_ONLY_HEALTH_CONTRACT_FAILED requested=$requested selected=$selected assay=$assay cuda_compiled=$cudaCompiled registry_embedding_runtimes_compiled=$registryEmbeddingRuntimesCompiled ward_model_lenses_compiled=$wardModelLensesCompiled sextant_cuvs_compiled=$sextantCuvsCompiled sextant_cuda_pq_compiled=$sextantCudaPqCompiled vram_budget_bytes=$vramBudget vram_budget_enforced=$vramBudgetEnforced vram_dispatch_absent=$dispatchAbsent gpu_reservation_id=$(if ($reservationId) { $reservationId } else { '<none>' }); remediation=use the setup-managed CPU-only Calyx config and rebuild synapse-mcp without Calyx/model accelerator or heavyweight embedding/model-lens features"
        })
    }
}

function Assert-SynapseNoExplicitGpuRuntimeHealth {
    param(
        [Parameter(Mandatory=$true)]$Health,
        [Parameter(Mandatory=$true)][int]$ProcessId,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$Phase
    )

    if ([int]$Health.pid -ne $ProcessId) {
        Die "SYNAPSE_ACCELERATOR_POLICY_HEALTH_PID_MISMATCH phase=$Phase expected_pid=$ProcessId actual_pid=$($Health.pid) bind=$Bind remediation=refuse health from a different process identity"
    }
    $calyxProof = Test-SynapseCpuOnlyRuntimeHealth -Health $Health
    if (-not $calyxProof.Ok) {
        Die "$($calyxProof.Detail) phase=$Phase pid=$ProcessId bind=$Bind"
    }

    $perception = $Health.subsystems.perception
    $detection = if ($null -eq $perception) { $null } else { $perception.perception_detection }
    $capture = if ($null -eq $perception) { $null } else { $perception.capture_runtime }
    $captureRequested = if ($null -eq $perception) { '<missing>' } else { [string]$perception.capture_backend_requested }
    $captureEffective = if ($null -eq $perception) { '<missing>' } else { [string]$perception.capture_backend_effective }
    $captureCompiled = if ($null -eq $perception -or $null -eq $perception.PSObject.Properties['capture_gpu_backends_compiled']) { $null } else { $perception.capture_gpu_backends_compiled }
    $detectionCudaCompiled = if ($null -eq $perception -or $null -eq $perception.PSObject.Properties['detection_cuda_execution_provider_compiled']) { $null } else { $perception.detection_cuda_execution_provider_compiled }
    $captureSelected = if ($null -eq $capture) { '<missing>' } else { [string]$capture.selected_backend }
    $captureActiveBackend = if ($null -eq $capture) { '<missing>' } else { [string]$capture.backend }
    $bundledDetectionProvider = if ($null -eq $detection) { '<missing>' } else { [string]$detection.bundled_provider }
    $persistentDetectionBackend = if ($null -eq $detection) { '<missing>' } else { [string]$detection.persistent_worker_backend }
    $captureOk = (
        $null -ne $perception -and
        $captureRequested -ceq 'gdi_bitblt_no_explicit_gpu_api' -and
        $captureEffective -ceq 'gdi_bitblt_no_explicit_gpu_api' -and
        $captureCompiled -is [bool] -and $captureCompiled -eq $false -and
        $detectionCudaCompiled -is [bool] -and $detectionCudaCompiled -eq $false -and
        $null -ne $capture -and
        $captureSelected -ceq 'gdi_bitblt_no_explicit_gpu_api' -and
        ([string]::IsNullOrWhiteSpace($captureActiveBackend) -or $captureActiveBackend -ceq 'gdi_bitblt_no_explicit_gpu_api') -and
        $null -ne $detection -and
        $bundledDetectionProvider -ceq 'cpu' -and
        ([string]::IsNullOrWhiteSpace($persistentDetectionBackend) -or $persistentDetectionBackend -ceq 'cpu'))
    if (-not $captureOk) {
        Die "SYNAPSE_ACCELERATOR_POLICY_PERCEPTION_CONTRACT_FAILED phase=$Phase pid=$ProcessId bind=$Bind capture_requested=$captureRequested capture_effective=$captureEffective capture_selected=$captureSelected capture_active=$(if ($captureActiveBackend) { $captureActiveBackend } else { '<inactive>' }) capture_gpu_backends_compiled=$(if ($null -eq $captureCompiled) { '<missing>' } else { $captureCompiled }) detection_cuda_compiled=$(if ($null -eq $detectionCudaCompiled) { '<missing>' } else { $detectionCudaCompiled }) bundled_detection_provider=$bundledDetectionProvider persistent_detection_backend=$(if ($persistentDetectionBackend) { $persistentDetectionBackend } else { '<not-started>' }) remediation=run the CPU-only build with the exact no-explicit-GPU-API GDI BitBlt backend and no model/capture accelerator features; GDI may still be accelerated internally by Windows or the display driver"
    }

    $audio = $Health.subsystems.audio
    $sttPolicy = if ($null -eq $audio) { '<missing>' } else { [string]$audio.stt_backend_policy }
    $sttSelected = if ($null -eq $audio) { '<missing>' } else { [string]$audio.stt_selected_backend }
    $sttDeviceMemory = if ($null -eq $audio) { '<missing>' } else { [string]$audio.stt_device_memory_policy }
    $sttReservationId = if ($null -eq $audio) { '<missing>' } else { [string]$audio.stt_gpu_reservation_id }
    $sttReservationMib = if ($null -eq $audio -or $null -eq $audio.stt_gpu_reservation_mib) { [uint64]0 } else { [uint64]$audio.stt_gpu_reservation_mib }
    $sttCudaCompiled = if ($null -eq $audio -or $null -eq $audio.PSObject.Properties['stt_cuda_execution_provider_compiled']) { $null } else { $audio.stt_cuda_execution_provider_compiled }
    $audioOk = (
        $null -ne $audio -and
        $sttPolicy -ceq 'pinned:Cpu' -and
        $sttCudaCompiled -is [bool] -and $sttCudaCompiled -eq $false -and
        ([string]::IsNullOrWhiteSpace($sttSelected) -or $sttSelected -ceq 'Cpu') -and
        ([string]::IsNullOrWhiteSpace($sttDeviceMemory) -or $sttDeviceMemory -ceq 'host_memory') -and
        [string]::IsNullOrWhiteSpace($sttReservationId) -and
        $sttReservationMib -eq 0)
    if (-not $audioOk) {
        Die "SYNAPSE_ACCELERATOR_POLICY_AUDIO_CONTRACT_FAILED phase=$Phase pid=$ProcessId bind=$Bind stt_policy=$sttPolicy stt_cuda_compiled=$(if ($null -eq $sttCudaCompiled) { '<missing>' } else { $sttCudaCompiled }) selected_backend=$(if ($sttSelected) { $sttSelected } else { '<not-loaded>' }) device_memory_policy=$(if ($sttDeviceMemory) { $sttDeviceMemory } else { '<not-loaded>' }) gpu_reservation_id=$(if ($sttReservationId) { $sttReservationId } else { '<none>' }) gpu_reservation_mib=$sttReservationMib remediation=run the CPU-only audio build with pinned CPU policy and no GPU reservation"
    }

    try {
        $process = Get-Process -Id $ProcessId -ErrorAction Stop
        $process.Refresh()
        $cudaModules = @($process.Modules | Where-Object {
            $_.ModuleName -match '^(?i:onnxruntime_providers_cuda|nvcuda|cudart(?:64.*)?|cublas(?:Lt)?64.*|cudnn.*)\.dll$'
        } | ForEach-Object { [string]$_.FileName })
    } catch {
        Die "SYNAPSE_ACCELERATOR_POLICY_MODULE_READBACK_FAILED phase=$Phase pid=$ProcessId bind=$Bind error=$($_.Exception.Message) remediation=repair same-user module query access; setup will not infer that CUDA modules are absent"
    }
    if ($cudaModules.Count -gt 0) {
        Die "SYNAPSE_ACCELERATOR_POLICY_CUDA_MODULE_LOADED phase=$Phase pid=$ProcessId bind=$Bind modules=$($cudaModules -join ',') remediation=remove every CUDA-linked runtime/provider and rebuild the CPU-only daemon"
    }
    Info "SYNAPSE_NO_EXPLICIT_GPU_POLICY_CLOSURE_VERIFIED phase=$Phase pid=$ProcessId bind=$Bind capture_requested=$captureRequested capture_effective=$captureEffective capture_selected=$captureSelected capture_gpu_backends_compiled=false detection_cuda_compiled=false bundled_detection_provider=$bundledDetectionProvider persistent_detection_backend=$(if ($persistentDetectionBackend) { $persistentDetectionBackend } else { '<not-started>' }) stt_policy=$sttPolicy stt_cuda_compiled=false loaded_cuda_module_count=0 $($calyxProof.Detail) note=compile_policy_provider_and_module_closure_only; GDI may be accelerated internally by Windows/the display driver and physical per-process GPU memory is a separate OS Source-of-Truth readback"
    return [pscustomobject]@{
        Ok = $true
        LoadedCudaModuleCount = 0
        CaptureBackend = $captureEffective
        DetectionBackend = $bundledDetectionProvider
        SttBackendPolicy = $sttPolicy
        Detail = [string]$calyxProof.Detail
    }
}

function Format-SynapseCandidateHealthFailures {
    param([Parameter(Mandatory=$true)]$Health)

    $failures = @()
    if ($Health.subsystems) {
        foreach ($prop in @($Health.subsystems.PSObject.Properties | Sort-Object Name)) {
            $status = [string]$prop.Value.status
            if ($status -eq 'error') {
                $failures += [ordered]@{
                    name = [string]$prop.Name
                    status = $status
                    detail = [string]$prop.Value.detail
                }
            }
        }
    }
    return @($failures)
}

function New-SynapseCandidateTaskProbePreparation {
    param(
        [Parameter(Mandatory=$true)][string]$CandidateExePath,
        [Parameter(Mandatory=$true)][string]$CandidateBootstrapPath,
        [Parameter(Mandatory=$true)][ValidatePattern('^[0-9A-Fa-f]{64}$')][string]$ExpectedCandidateBootstrapSha256,
        [Parameter(Mandatory=$true)][string]$ProfilesDir,
        [Parameter(Mandatory=$true)][string]$TokenPath,
        [Parameter(Mandatory=$true)][string]$LogDir,
        [bool]$EnableAudio,
        [AllowNull()][string]$AllowedPermissions,
        [Parameter(Mandatory=$true)][string]$CalyxConfigPath,
        [Parameter(Mandatory=$true)][ValidatePattern('^[0-9A-Fa-f]{64}$')][string]$ExpectedCalyxConfigSha256,
        [AllowNull()][string]$ReplacementReservationId=$null,
        [Parameter(Mandatory=$true)][ValidatePattern('^[0-9A-Fa-f]{64}$')][string]$ProbeCapability
    )
    $candidateRoot=New-SynapseSetupRunDirectory -Root (Join-Path $LogDir 'setup-candidates') -Purpose 'candidate'
    $candidateDb=Join-Path $candidateRoot 'db';$candidateShellJobRoot=Join-Path $candidateRoot 'shell-jobs'
    New-Item -ItemType Directory -Force -Path $candidateDb|Out-Null;New-Item -ItemType Directory -Force -Path $candidateShellJobRoot|Out-Null
    $candidateLauncher=Join-Path $candidateRoot 'candidate-launch-hidden.vbs';$candidateSupervisorPath=$null
    $candidateSupervisorStatePath=Join-Path $candidateRoot 'daemon-supervisor-current.json';$candidateBootstrapLogPath=Join-Path $candidateRoot 'daemon-supervisor-bootstrap.log'
    $candidateMaintenanceLockPath=Join-Path $candidateRoot 'candidate-maintenance.lock';$candidateSupervisorExe=Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
    $candidateBind=New-SynapseCandidateBind;$candidateProbeTaskName='SynapseMcpProbe-'+$ProbeCapability.Substring(0,40)
    $rootChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $candidateRoot)
    $candidateRootIdentity=([string]$rootChain[-1].file_id_128).ToUpperInvariant()
    $bootstrapParent=Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent ([System.IO.Path]::GetFullPath($CandidateBootstrapPath)))
    $bootstrapChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $bootstrapParent)
    $bootstrapState=Get-SynapsePhysicalRelativeState -ParentPath $bootstrapParent -ParentChain $bootstrapChain -Leaf (Split-Path -Leaf $CandidateBootstrapPath)
    if(-not(Test-SynapsePhysicalStateExact -State $bootstrapState -ExpectedExists $true -ExpectedSha256 $ExpectedCandidateBootstrapSha256)){Die "SYNAPSE_CANDIDATE_PROBE_PREPARATION_BOOTSTRAP_INVALID root=$candidateRoot path=$CandidateBootstrapPath"}
    $powerShellIdentity=Get-SynapseRuntimeFileIdentityForAuthority -Path $candidateSupervisorExe -Role probe_powershell
    $powerShellDescriptor=ConvertTo-SynapseAuthorityFileDescriptor -Identity $powerShellIdentity -Role probe_powershell
    $probeBrokerIdentity=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value ([ordered]@{schema='synapse_probe_outer_broker_identity/v1';invocation_id=$script:SynapseSetupInvocationId;candidate_root=$candidateRoot;candidate_root_file_id_128=$candidateRootIdentity;bootstrap_sha256=([string]$bootstrapState.Sha256).ToUpperInvariant();powershell_sha256=([string]$powerShellIdentity.sha256).ToUpperInvariant();launch_capability_sha256=$ProbeCapability.ToUpperInvariant()}))).ToUpperInvariant()
    if($probeBrokerIdentity -ieq $ProbeCapability){Die "SYNAPSE_CANDIDATE_PROBE_IDENTITY_CAPABILITY_COLLISION root=$candidateRoot capability=$ProbeCapability"}
    $supervisorBody=New-HiddenDaemonLauncher -OutputPath $candidateLauncher -ExePath $CandidateExePath -Bind $candidateBind -DbPath $candidateDb -ProfilesDir $ProfilesDir -LogDir $candidateRoot -TokenPath $TokenPath -MaintenanceLockPath $candidateMaintenanceLockPath -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions -CalyxConfigPath $CalyxConfigPath -ExpectedCalyxConfigSha256 $ExpectedCalyxConfigSha256 -AuthorityMode probe -AuthorityBrokerTaskName $candidateProbeTaskName -AuthorityBootstrapPath $CandidateBootstrapPath -AuthorityBootstrapSha256 $ExpectedCandidateBootstrapSha256 -AuthorityTransactionId $ProbeCapability -AuthorityShellJobRoot $candidateShellJobRoot -AuthorityReplacementReservationId $(if([string]::IsNullOrWhiteSpace($ReplacementReservationId)){''}else{$ReplacementReservationId}) -ExpectedParentJobCpuRate 2500 -OneShot $true -ContentOnly
    $bootstrapIdentity=[pscustomobject][ordered]@{Path=[System.IO.Path]::GetFullPath($CandidateBootstrapPath);FileId128=([string]$bootstrapState.FileId128).ToUpperInvariant();Sha256=([string]$bootstrapState.Sha256).ToUpperInvariant();Length=[int64]$bootstrapState.Length}
    $supervisorContent=New-SynapseSupervisorLaunchContractContent -Body ([string]$supervisorBody.Content) -Role probe_outer -Mode outer_complete_tree_legacy -Bootstrap $bootstrapIdentity -PowerShell $powerShellIdentity -BrokerIdentitySha256 $probeBrokerIdentity -LaunchCapabilitySha256 $ProbeCapability -OuterLaunchCapabilitySha256 $ProbeCapability -AuthorityEpoch 0 -ExpectedJobCpuRate 2500
    $supervisorSha=(Get-SynapseSha256Hex -Text $supervisorContent).ToUpperInvariant()
    $candidateSupervisorPath=Join-Path $candidateRoot "probe-supervisor-$supervisorSha.ps1"
    [void](Write-SynapseAtomicUtf8TextFileUnderPhysicalRoot -Root $candidateRoot -ExpectedRootIdentity $candidateRootIdentity -LeafName (Split-Path -Leaf $candidateSupervisorPath) -Content $supervisorContent -Purpose 'candidate_probe_supervisor_v2')
    $supervisorState=Get-SynapsePhysicalRelativeState -ParentPath $candidateRoot -ParentChain $rootChain -Leaf (Split-Path -Leaf $candidateSupervisorPath)
    $supervisorLength=[System.Text.UTF8Encoding]::new($false,$true).GetByteCount($supervisorContent)
    if(-not(Test-SynapsePhysicalStateExact -State $supervisorState -ExpectedExists $true -ExpectedSha256 $supervisorSha -ExpectedLength $supervisorLength)){Die "SYNAPSE_CANDIDATE_PROBE_PREPARATION_OBJECT_INVALID root=$candidateRoot"}
    $arguments=Get-SynapseSupervisorBootstrapTaskArgumentText -PowerShellPath $candidateSupervisorExe -SupervisorPath $candidateSupervisorPath -WorkingDirectory $candidateRoot -LogPath $candidateBootstrapLogPath
    $probeUserSid=Get-SynapseCurrentUserSid
    $sddl=Get-SynapseAuthorityTaskExplicitSecurityDescriptor -UserSid $probeUserSid
    $submittedDefinition=New-SynapseTaskCreateDefinitionPlan -Name $candidateProbeTaskName -Kind probe -Execute $CandidateBootstrapPath -Arguments $arguments -WorkingDirectory $candidateRoot -UserSid $probeUserSid
    $core=[ordered]@{schema='synapse_candidate_probe_task_plan/v4';state='prepared_before_task_create';launch_contract_schema='synapse_supervisor_launch_contract/v2';probe_broker_identity_sha256=$probeBrokerIdentity;capability_sha256=$ProbeCapability.ToUpperInvariant();invocation_id=$script:SynapseSetupInvocationId;candidate_root=$candidateRoot;candidate_root_file_id_128=$candidateRootIdentity;task_name=$candidateProbeTaskName;kind='probe';execute=[System.IO.Path]::GetFullPath($CandidateBootstrapPath);arguments=$arguments;working_directory=$candidateRoot;powershell_path=[System.IO.Path]::GetFullPath($candidateSupervisorExe);powershell_file_id_128=([string]$powerShellIdentity.file_id_128).ToUpperInvariant();powershell_sha256=([string]$powerShellIdentity.sha256).ToUpperInvariant();powershell_length=[int64]$powerShellIdentity.length;powershell_descriptor=(ConvertTo-SynapseCanonicalValue -Value $powerShellDescriptor);bootstrap_log_path=[System.IO.Path]::GetFullPath($candidateBootstrapLogPath);user_sid=$probeUserSid;task_create_flag=2;task_ignore_registration_triggers_flag_absent=$true;trigger_types=@('registration');task_instance_semantics='registration_trigger_single_oneshot_ignore_new';maximum_concurrent_instances=1;cleanup_requires_zero_running_instances=$true;submitted_task_xml_sha256=([string]$submittedDefinition.SubmittedXmlSha256).ToUpperInvariant();explicit_security_descriptor=$sddl;security_descriptor_readback_flags=7;bootstrap_file_id_128=([string]$bootstrapState.FileId128).ToUpperInvariant();bootstrap_sha256=([string]$bootstrapState.Sha256).ToUpperInvariant();bootstrap_length=[int64]$bootstrapState.Length;supervisor_path=$candidateSupervisorPath;supervisor_file_id_128=([string]$supervisorState.FileId128).ToUpperInvariant();supervisor_sha256=([string]$supervisorState.Sha256).ToUpperInvariant();supervisor_length=[int64]$supervisorState.Length;bind=$candidateBind;db_path=$candidateDb;profiles_dir=[System.IO.Path]::GetFullPath($ProfilesDir);token_path=[System.IO.Path]::GetFullPath($TokenPath);created_at_utc=[DateTime]::UtcNow.ToString('o')}
    $core.submitted_task_semantic_sha256=([string]$submittedDefinition.SemanticSha256).ToUpperInvariant()
    $core.plan_sha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $core)).ToUpperInvariant()
    [void](Write-SynapseAtomicUtf8TextFileUnderPhysicalRoot -Root $candidateRoot -ExpectedRootIdentity $candidateRootIdentity -LeafName 'candidate-probe-task-plan.json' -Content (Get-SynapseCanonicalJson -Value $core) -Purpose 'candidate_probe_precreate_task_plan')
    $planState=Get-SynapsePhysicalRelativeState -ParentPath $candidateRoot -ParentChain $rootChain -Leaf 'candidate-probe-task-plan.json'
    $planLease=Open-SynapsePhysicalFileReadLease -ParentPath $candidateRoot -ParentChain $rootChain -Leaf 'candidate-probe-task-plan.json' -ExpectedFileId128 $planState.FileId128 -ExpectedSha256 $planState.Sha256 -ExpectedLength $planState.Length -Context 'candidate_probe_prepared_plan'
    $powerShellAliasLeaseBundle=$null
    try{
        $powerShellAliasLeaseBundle=Open-SynapseProtectedOsInterpreterAliasLeaseBundle -Descriptor ([pscustomobject]$powerShellDescriptor) -ExpectedRole probe_powershell -Context 'candidate_probe_prepared_powershell_aliases'
    }catch{
        try{$planLease.Dispose()}catch{[Environment]::FailFast("SYNAPSE_CANDIDATE_PROBE_PREPARED_PLAN_LEASE_RELEASE_UNPROVEN primary=[$($_.Exception.Message)]",$_.Exception)}
        throw
    }
    $authority=[pscustomobject][ordered]@{Path=(Join-Path $candidateRoot 'candidate-probe-task-plan.json');FileId128=$planState.FileId128;Sha256=$planState.Sha256;Length=$planState.Length;Lease=$planLease;TaskName=$candidateProbeTaskName;Kind='probe';Execute=[System.IO.Path]::GetFullPath($CandidateBootstrapPath);Arguments=$arguments;WorkingDirectory=$candidateRoot;Payload=[pscustomobject]$core}
    return [pscustomobject][ordered]@{CandidateRoot=$candidateRoot;CandidateRootIdentity=$candidateRootIdentity;CandidateRootChain=$rootChain;CandidateDb=$candidateDb;CandidateShellJobRoot=$candidateShellJobRoot;CandidateLauncher=$candidateLauncher;CandidateSupervisorPath=$candidateSupervisorPath;CandidateSupervisorStatePath=$candidateSupervisorStatePath;CandidateBootstrapLogPath=$candidateBootstrapLogPath;CandidateMaintenanceLockPath=$candidateMaintenanceLockPath;CandidateBind=$candidateBind;CandidateSupervisorExe=$candidateSupervisorExe;ProbeBrokerIdentitySha256=$probeBrokerIdentity;TaskName=$candidateProbeTaskName;Capability=$ProbeCapability.ToUpperInvariant();PlanAuthority=$authority;PowerShellAliasLeaseBundle=$powerShellAliasLeaseBundle}
}

function Test-SynapseCandidateDaemon {
    param(
        [Parameter(Mandatory=$true)][string]$CandidateExePath,
        [Parameter(Mandatory=$true)][string]$CandidateBootstrapPath,
        [Parameter(Mandatory=$true)][ValidatePattern('^[0-9A-Fa-f]{64}$')][string]$ExpectedCandidateBootstrapSha256,
        [Parameter(Mandatory=$true)][string]$ProfilesDir,
        [Parameter(Mandatory=$true)][string]$TokenPath,
        [Parameter(Mandatory=$true)][string]$LogDir,
        [bool]$EnableAudio,
        [AllowNull()][string]$AllowedPermissions,
        [Parameter(Mandatory=$true)][string]$CalyxConfigPath,
        [Parameter(Mandatory=$true)][ValidatePattern('^[0-9A-Fa-f]{64}$')][string]$ExpectedCalyxConfigSha256,
        [AllowNull()][string]$ReplacementReservationId = $null,
        [switch]$UseTaskProbe,
        [AllowEmptyString()][string]$ProbeCapability = '',
        [AllowNull()][scriptblock]$BeforeTaskCreate = $null,
        [AllowNull()]$PreparedTaskProbe = $null
    )

    if (-not (Test-Path -LiteralPath $CandidateExePath)) {
        Die "SYNAPSE_CANDIDATE_BINARY_MISSING path=$CandidateExePath remediation=build or provide a real synapse-mcp.exe before setup can touch the live daemon"
    }
    if (-not (Test-Path -LiteralPath $CandidateBootstrapPath -PathType Leaf)) {
        Die "SYNAPSE_CANDIDATE_SUPERVISOR_BOOTSTRAP_MISSING path=$CandidateBootstrapPath remediation=build or provide the exact native supervisor bootstrap before candidate acceptance"
    }
    $candidateBootstrapPath = [System.IO.Path]::GetFullPath($CandidateBootstrapPath)
    $expectedCandidateBootstrapSha256 = $ExpectedCandidateBootstrapSha256.ToUpperInvariant()
    $candidateBootstrapHashBefore = Get-SynapseFileSha256 -Path $candidateBootstrapPath
    if ($candidateBootstrapHashBefore -ine $expectedCandidateBootstrapSha256) {
        Die "SYNAPSE_CANDIDATE_SUPERVISOR_BOOTSTRAP_IDENTITY_MISMATCH phase=before_launch path=$candidateBootstrapPath expected_sha256=$expectedCandidateBootstrapSha256 actual_sha256=$candidateBootstrapHashBefore remediation=validate the exact setup-built bootstrap generation; candidate acceptance never substitutes a setup-only launcher"
    }
    if (-not (Test-Path -LiteralPath $ProfilesDir)) {
        Die "SYNAPSE_CANDIDATE_PROFILES_MISSING path=$ProfilesDir remediation=build/deploy profiles before validating the daemon candidate"
    }
    if (-not (Test-Path -LiteralPath $CalyxConfigPath -PathType Leaf)) {
        Die "SYNAPSE_CANDIDATE_CALYX_CONFIG_MISSING path=$CalyxConfigPath remediation=preserve the exact setup-validated CPU-only config through candidate validation"
    }
    $expectedCalyxConfigSha256 = $ExpectedCalyxConfigSha256.ToUpperInvariant()
    $candidateConfigHashBefore = Get-SynapseFileSha256 -Path $CalyxConfigPath
    if ($candidateConfigHashBefore -ine $expectedCalyxConfigSha256) {
        Die "SYNAPSE_CANDIDATE_CALYX_CONFIG_IDENTITY_MISMATCH phase=before_launch path=$CalyxConfigPath expected_sha256=$expectedCalyxConfigSha256 actual_sha256=$candidateConfigHashBefore remediation=stop the concurrent config writer and rerun setup; candidate validation must consume the exact locked bytes"
    }
    $candidateRuntimeDir = Split-Path -Parent ([System.IO.Path]::GetFullPath($CandidateExePath))
    $cudaProviderPath = Join-Path $candidateRuntimeDir 'onnxruntime_providers_cuda.dll'
    if (Test-Path -LiteralPath $cudaProviderPath) {
        $staleCudaProviderSha256=Get-SynapseFileSha256 -Path $cudaProviderPath
        Info "SYNAPSE_CANDIDATE_UNOWNED_CUDA_PROVIDER_PRESENT path=$cudaProviderPath sha256=$staleCudaProviderSha256 semantics=presence_is_an_external_delta_not_launch_authority; acceptance requires compiled CPU features, exact CPU execution provider, loaded-module absence, and physical GPU SoT proof"
    }
    $tokenRead = Read-SynapseSetupTokenForRestartGuard -TokenPath $TokenPath
    if (-not $tokenRead.Ok) {
        Die "$($tokenRead.Code) stage=candidate_health $($tokenRead.Detail) remediation=setup must have a valid bearer token before candidate health can be proven"
    }

    if(-not $UseTaskProbe){
        Die 'SYNAPSE_CANDIDATE_DIRECT_LAUNCH_AUTHORITY_REMOVED remediation=all broker-era source and installed candidate probes require a journal-bound unique TASK_CREATE RegistrationTrigger-only capability'
    }
    if($null -eq $PreparedTaskProbe){
        if([string]::IsNullOrWhiteSpace($ProbeCapability)){
            $probeNonce=[Guid]::NewGuid().ToString('N')
            $ProbeCapability=(Get-SynapseSha256Hex -Text "synapse-candidate-probe:$($script:SynapseSetupInvocationId):$probeNonce").ToUpperInvariant()
        }
        $PreparedTaskProbe=New-SynapseCandidateTaskProbePreparation -CandidateExePath $CandidateExePath -CandidateBootstrapPath $candidateBootstrapPath -ExpectedCandidateBootstrapSha256 $expectedCandidateBootstrapSha256 -ProfilesDir $ProfilesDir -TokenPath $TokenPath -LogDir $LogDir -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions -CalyxConfigPath $CalyxConfigPath -ExpectedCalyxConfigSha256 $expectedCalyxConfigSha256 -ReplacementReservationId $ReplacementReservationId -ProbeCapability $ProbeCapability
    }

    if($null -ne $PreparedTaskProbe){
