                }
                $candidateCim=Get-CimInstance Win32_Process -Filter "ProcessId=$candidateChildPid" -ErrorAction Stop
                $candidateExpectedParentPid=[int]$candidateSupervisor.Id
                $candidateExpectedSessionId=[int]$candidateCim.SessionId
                $candidateExpectedCommandLine=[string]$candidateCim.CommandLine
                $candidateExpectedCreationDate=[string]$candidateCim.CreationDate
                $candidateDaemonArgumentText=Get-SynapseDaemonArgumentText -Bind $candidateBind -DbPath $candidateDb -ProfilesDir $ProfilesDir -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions -CalyxConfigPath $CalyxConfigPath -ExpectedCalyxConfigSha256 $expectedCalyxConfigSha256
                Ensure-SynapseWindowsCommandLineArgvType
                $candidateExpectedArguments=@([SynapseSetup.WindowsCommandLineArgv]::Parse((Quote-WindowsCommandArgument $CandidateExePath)+' '+$candidateDaemonArgumentText+' --parent-pid '+$candidateExpectedParentPid))
                $candidateExpectedPathArgumentIndexes=@(0)
                for($argumentIndex=1;$argumentIndex-lt($candidateExpectedArguments.Count-1);$argumentIndex++){
                    if([string]$candidateExpectedArguments[$argumentIndex] -in @('--db','--profile-dir','--calyx-config')){$candidateExpectedPathArgumentIndexes+=,$argumentIndex+1}
                }
                [void](Assert-SynapseProcessCommandLineExact -Process $candidateCim -ExpectedArguments $candidateExpectedArguments -PathArgumentIndexes $candidateExpectedPathArgumentIndexes -Context 'candidate_daemon_initial_argv')
                $candidateCreation=[SynapseAuthorityRuntime.MappedProcessLease]::ReadCreationTimeFileTime([uint32]$candidateChildPid,'candidate_daemon_creation')
                $candidateMappedDaemonLease=[SynapseAuthorityRuntime.MappedProcessLease]::Open([uint32]$candidateChildPid,[int64]$candidateCreation,[string]$candidateFileIdentity.path,[string]$candidateFileIdentity.file_id_128,[string]$candidateFileIdentity.sha256,[int64]$candidateFileIdentity.length,'candidate_daemon_mapped')
                [void](Assert-SynapseMappedProcessMetadataUnderLease -Lease $candidateMappedDaemonLease -ExpectedProcessId $candidateChildPid -ExpectedParentProcessId $candidateExpectedParentPid -ExpectedSessionId $candidateExpectedSessionId -ExpectedImagePath ([string]$candidateFileIdentity.path) -ExpectedCommandLine $candidateExpectedCommandLine -ExpectedCreationDate $candidateExpectedCreationDate -Context 'candidate_daemon_initial_mapped')
                $candidateExactStopReady=$true
                $candidateStderrReadback = @(Get-ChildItem -LiteralPath $candidateRoot -Filter 'daemon-stderr-gen*.log' -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1)
                if ($candidateStderrReadback.Count -eq 1) {
                    $candidateStderr = $candidateStderrReadback[0].FullName
                }
                $candidateKernelHeadroom = if ([uint64]$candidateKernelJob.CurrentJobMemoryUsedBytes -ge $SynapseDaemonProcessMemoryLimitBytes) { [uint64]0 } else { [uint64]($SynapseDaemonProcessMemoryLimitBytes - [uint64]$candidateKernelJob.CurrentJobMemoryUsedBytes) }
                $candidateParentHeadroom = if ([uint64]$candidateParentKernelJob.CurrentJobMemoryUsedBytes -ge $SynapseOwnedMemoryLimitBytes) { [uint64]0 } else { [uint64]($SynapseOwnedMemoryLimitBytes - [uint64]$candidateParentKernelJob.CurrentJobMemoryUsedBytes) }
                Info "Candidate native-bootstrap Job launch verified bootstrap_pid=$($candidateBootstrap.Id) bootstrap_path=$candidateBootstrapPath bootstrap_sha256=$expectedCandidateBootstrapSha256 supervisor_pid=$($candidateSupervisor.Id) candidate_pid=$($candidate.Id) state_path=$candidateSupervisorStatePath parent_job_name=$candidateParentJobName parent_job_limit_bytes=$SynapseOwnedMemoryLimitBytes parent_cpu_rate=$($candidateParentKernelJob.CpuRate) parent_current_job_memory_used_bytes=$($candidateParentKernelJob.CurrentJobMemoryUsedBytes) parent_job_memory_headroom_bytes=$candidateParentHeadroom parent_peak_job_memory_used_bytes=$($candidateParentKernelJob.PeakJobMemoryUsedBytes) daemon_job_name=$candidateJobName daemon_job_limit_flags=$($candidateSupervisorState.job_limit_flags_hex) daemon_cpu_rate=$($candidateKernelJob.CpuRate) daemon_process_memory_limit_bytes=$($candidateSupervisorState.job_process_memory_limit_bytes) daemon_job_memory_limit_bytes=$($candidateSupervisorState.job_memory_limit_bytes) working_set_policy=measured_only daemon_working_set_bytes=$candidateWorkingSetBytes daemon_current_job_memory_used_bytes=$($candidateKernelJob.CurrentJobMemoryUsedBytes) daemon_job_memory_headroom_bytes=$candidateKernelHeadroom daemon_peak_job_memory_used_bytes=$($candidateKernelJob.PeakJobMemoryUsedBytes)"
                break
            }
            if ($null -ne $candidateBootstrap) {
                $candidateBootstrap.Refresh()
                if ($candidateBootstrap.HasExited) {
                    Die "SYNAPSE_CANDIDATE_SUPERVISOR_BOOTSTRAP_EXITED_BEFORE_CHILD bootstrap_pid=$($candidateBootstrap.Id) exit_code=$($candidateBootstrap.ExitCode) bootstrap_log=$candidateBootstrapLogPath state_path=$candidateSupervisorStatePath state_error=$(if ($candidateSupervisorStateError) { $candidateSupervisorStateError } else { '<none>' }) remediation=inspect the exact native-bootstrap log/state evidence; the production candidate topology was never published"
                }
            } elseif (-not $UseTaskProbe) {
                Die 'SYNAPSE_CANDIDATE_BOOTSTRAP_PROCESS_IDENTITY_MISSING mode=direct'
            }
            if ((Get-Date) -ge $candidateLaunchDeadline) {
                Die "SYNAPSE_CANDIDATE_SUPERVISOR_CHILD_TIMEOUT supervisor_pid=$($candidateSupervisor.Id) timeout_seconds=60 state_path=$candidateSupervisorStatePath state=$(if ($candidateSupervisorState) { $candidateSupervisorState | ConvertTo-Json -Depth 8 -Compress } else { '<missing>' }) state_error=$(if ($candidateSupervisorStateError) { $candidateSupervisorStateError } else { '<none>' }) remediation=inspect candidate supervisor events and daemon stderr; setup refuses an unproven Job assignment"
            }
            Start-Sleep -Milliseconds 100
        }
        $candidateWatchdog = New-SynapseDaemonStartupWatchdog `
            -Phase 'candidate' `
            -LogDir $candidateRoot `
            -Bind $candidateBind `
            -DbPath $candidateDb `
            -VaultPath $candidateCalyxVault `
            -BaseTimeoutSeconds 25 `
            -MaxSeconds 180 `
            -StallSeconds 45 `
            -SampleIntervalSeconds 5
        $candidateGateVerdict = 'continue'
        Info ("SYNAPSE_STARTUP_WATCHDOG_ARMED phase=candidate base_timeout_s={0} absolute_cap_s={1} stall_window_s={2} sample_interval_s={3} vault={4} remediation=candidate validation keeps waiting only while the exact isolated process proves CPU, I/O, or vault progress and always retains a hard ceiling" -f `
            $candidateWatchdog.BaseTimeoutSeconds,
            $candidateWatchdog.MaxSeconds,
            $candidateWatchdog.StallSeconds,
            $candidateWatchdog.SampleIntervalSeconds,
            $candidateWatchdog.VaultPath)
        while ($true) {
            Start-Sleep -Milliseconds 500
            $read = Read-SynapseHealthForRestartGuard -Bind $candidateBind -Token $tokenRead.Token -TimeoutSec 2
            if ($read.Ok) {
                $health = $read.Health
                break
            }
            $lastHealthError = $read.Error
            $candidate.Refresh()
            if ($candidate.HasExited) {
                $candidateGateVerdict = 'daemon_exited'
                $candidateWatchdog.Verdict = 'daemon_exited'
                $candidateWatchdog.TerminalFailureLine = Get-SynapseCandidateTerminalFailureLine -Path $candidateStderr
                $candidateExit = Get-SynapseCandidateExitReadback -Process $candidate
                Info ("SYNAPSE_CANDIDATE_PROCESS_EXITED_BEFORE_HEALTH pid={0} exit_code_signed={1} exit_code_hex={2} terminal_failure_line={3} remediation=fix the retained terminal cause; setup will not wait, retry, or take a stack dump of an exited process" -f `
                    $candidate.Id,
                    $(if ($null -eq $candidateExit.ExitCodeSigned) { '<unavailable>' } else { $candidateExit.ExitCodeSigned }),
                    $(if ($null -eq $candidateExit.ExitCodeHex) { '<unavailable>' } else { $candidateExit.ExitCodeHex }),
                    $(if ([string]::IsNullOrWhiteSpace($candidateWatchdog.TerminalFailureLine)) { '<empty stderr>' } else { $candidateWatchdog.TerminalFailureLine }))
                break
            }
            $candidateTick = Update-SynapseDaemonStartupWatchdog -Watchdog $candidateWatchdog
            if (-not $candidateTick.Continue) {
                $candidateGateVerdict = $candidateTick.Verdict
                break
            }
        }

        if ($null -eq $health) {
            $alive = [bool](Get-Process -Id $candidate.Id -ErrorAction SilentlyContinue)
            $exit = Get-SynapseCandidateExitReadback -Process $candidate
            $listeners = @(Get-SynapseTcpBindListenerSnapshot -Bind $candidateBind)
            $candidatePhysicalState = Format-SynapseDaemonStartupPhysicalState -DbPath $candidateDb -CalyxVaultPath $candidateCalyxVault
            $stdoutHash = if (Test-Path -LiteralPath $candidateStdout -PathType Leaf) { Get-SynapseFileSha256 -Path $candidateStdout } else { '<missing>' }
            $stderrHash = if (Test-Path -LiteralPath $candidateStderr -PathType Leaf) { Get-SynapseFileSha256 -Path $candidateStderr } else { '<missing>' }
            Die ("SYNAPSE_CANDIDATE_HEALTH_FAILED exe={0} sha256={1} pid={2} alive={3} exit_code_signed={4} exit_code_hex={5} bind={6} listeners={7} gate_verdict={8} last_error={9} evidence_root={10} stdout={11} stdout_sha256={12} stderr={13} stderr_sha256={14}`nstartup_watchdog:`n{15}`nphysical_storage_state:`n{16}`nremediation={17} Old live daemon was not touched. Inspect retained candidate-diagnostic.json, stdout, stderr, and isolated lifecycle ledgers." -f `
                $CandidateExePath,
                $candidateHash,
                $candidate.Id,
                $alive,
                $(if ($null -eq $exit.ExitCodeSigned) { '<running-or-unavailable>' } else { $exit.ExitCodeSigned }),
                $(if ($null -eq $exit.ExitCodeHex) { '<running-or-unavailable>' } else { $exit.ExitCodeHex }),
                $candidateBind,
                (Format-SynapseTcpBindListenerSnapshot -Snapshot $listeners),
                $candidateGateVerdict,
                $lastHealthError,
                $candidateRoot,
                $candidateStdout,
                $stdoutHash,
                $candidateStderr,
                $stderrHash,
                (Format-SynapseDaemonStartupWatchdogState -Watchdog $candidateWatchdog),
                $candidatePhysicalState,
                (Get-SynapseDaemonStartupWatchdogRemediation -Verdict $candidateGateVerdict -Phase 'candidate'))
        }

        $healthPid = [int]$health.pid
        if ($healthPid -ne [int]$candidate.Id) {
            Die "SYNAPSE_CANDIDATE_PID_MISMATCH expected_pid=$($candidate.Id) health_pid=$healthPid bind=$candidateBind remediation=health came from an unexpected process; refusing handoff"
        }
        $initialHealthEvidence = Write-SynapseCandidateJsonEvidence `
            -CandidateRoot $candidateRoot `
            -CandidateRootIdentity $candidateRootIdentity `
            -LeafName 'candidate-health-before.json' `
            -Value $health
        Info "Candidate initial health evidence written path=$($initialHealthEvidence.Path) sha256=$($initialHealthEvidence.Sha256) length=$($initialHealthEvidence.Length) ok=$($health.ok)"
        [void](Assert-SynapseNoExplicitGpuRuntimeHealth -Health $health -ProcessId $healthPid -Bind $candidateBind -Phase 'candidate_initial')
        $candidateCpuOnly = Test-SynapseCpuOnlyRuntimeHealth -Health $health
        if (-not $candidateCpuOnly.Ok) {
            Die "$($candidateCpuOnly.Detail) pid=$healthPid bind=$candidateBind health_evidence=$($initialHealthEvidence.Path) health_evidence_sha256=$($initialHealthEvidence.Sha256)"
        }
        $perceptionDetection = $health.subsystems.perception.perception_detection
        $bundledDetectionProvider = if ($null -eq $perceptionDetection) { '<missing>' } else { [string]$perceptionDetection.bundled_provider }
        $persistentDetectionBackend = if ($null -eq $perceptionDetection) { '' } else { [string]$perceptionDetection.persistent_worker_backend }
        if ($null -eq $perceptionDetection -or
            $bundledDetectionProvider -cne 'cpu' -or
            (-not [string]::IsNullOrWhiteSpace($persistentDetectionBackend) -and $persistentDetectionBackend -cne 'cpu')) {
            Die "SYNAPSE_CANDIDATE_PERCEPTION_BACKEND_NOT_CPU pid=$healthPid bind=$candidateBind bundled_provider=$(if ($bundledDetectionProvider) { $bundledDetectionProvider } else { '<missing>' }) persistent_worker_backend=$(if ($persistentDetectionBackend) { $persistentDetectionBackend } else { '<not-started>' }) remediation=package the CPU-only ONNX Runtime and launch the detector with SYNAPSE_DETECTION_BACKEND=cpu"
        }
        $audioHealth = $health.subsystems.audio
        $audioBackendPolicy = if ($null -eq $audioHealth) { '' } else { [string]$audioHealth.stt_backend_policy }
        $audioSelectedBackend = if ($null -eq $audioHealth) { '' } else { [string]$audioHealth.stt_selected_backend }
        $audioDeviceMemoryPolicy = if ($null -eq $audioHealth) { '' } else { [string]$audioHealth.stt_device_memory_policy }
        $audioReservationId = if ($null -eq $audioHealth) { '' } else { [string]$audioHealth.stt_gpu_reservation_id }
        $audioReservationMib = if ($null -eq $audioHealth -or $null -eq $audioHealth.stt_gpu_reservation_mib) { [uint64]0 } else { [uint64]$audioHealth.stt_gpu_reservation_mib }
        if ((-not [string]::IsNullOrWhiteSpace($audioBackendPolicy) -and $audioBackendPolicy -cne 'pinned:Cpu') -or
            (-not [string]::IsNullOrWhiteSpace($audioSelectedBackend) -and $audioSelectedBackend -cne 'Cpu') -or
            (-not [string]::IsNullOrWhiteSpace($audioDeviceMemoryPolicy) -and $audioDeviceMemoryPolicy -cne 'host_memory') -or
            (-not [string]::IsNullOrWhiteSpace($audioReservationId)) -or
            $audioReservationMib -ne 0) {
            Die "SYNAPSE_CANDIDATE_AUDIO_BACKEND_NOT_CPU pid=$healthPid bind=$candidateBind policy=$(if ($audioBackendPolicy) { $audioBackendPolicy } else { '<not-loaded>' }) selected=$(if ($audioSelectedBackend) { $audioSelectedBackend } else { '<not-loaded>' }) device_memory_policy=$(if ($audioDeviceMemoryPolicy) { $audioDeviceMemoryPolicy } else { '<not-loaded>' }) gpu_reservation_id=$(if ($audioReservationId) { $audioReservationId } else { '<none>' }) gpu_reservation_mib=$audioReservationMib remediation=launch STT with SYNAPSE_STT_BACKEND=cpu and remove every CUDA execution-provider feature/artifact"
        }
        try {
            $candidate.Refresh()
            $candidateCudaModules = @($candidate.Modules | Where-Object {
                $_.ModuleName -match '^(?i:onnxruntime_providers_cuda|nvcuda|cudart(?:64.*)?|cublas(?:Lt)?64.*|cudnn.*)\.dll$'
            } | ForEach-Object { [string]$_.FileName })
        } catch {
            Die "SYNAPSE_CANDIDATE_MODULE_READBACK_FAILED pid=$healthPid bind=$candidateBind error=$($_.Exception.Message) remediation=repair same-user process module read access; setup cannot prove the CPU-only binary loaded no CUDA runtime/provider"
        }
        if ($candidateCudaModules.Count -gt 0) {
            Die "SYNAPSE_CANDIDATE_CUDA_MODULE_LOADED pid=$healthPid bind=$candidateBind modules=$($candidateCudaModules -join ',') remediation=remove the CUDA-linked dependency/provider and rebuild the CPU-only candidate"
        }
        Info "Candidate CPU-only/no-explicit-GPU-provider-or-API health contract verified pid=$healthPid bind=$candidateBind bundled_detection_provider=$bundledDetectionProvider persistent_detection_backend=$(if ($persistentDetectionBackend) { $persistentDetectionBackend } else { '<not-started>' }) stt_backend_policy=$(if ($audioBackendPolicy) { $audioBackendPolicy } else { '<not-loaded>' }) loaded_cuda_module_count=$($candidateCudaModules.Count) $($candidateCpuOnly.Detail) note=GDI may be accelerated internally and is not a physical zero-VRAM attestation"

        # #2196: global health deliberately treats a known dirty build as
        # degraded rather than operationally dead, but a production installer
        # has a stronger contract: it must never replace the live binary with
        # bytes that do not attest to one exact clean checkout. Keep that policy
        # here at the deployment boundary instead of weakening health's useful
        # diagnostic distinction.
        $buildProvenance = $health.subsystems.build_provenance
        $buildProvenanceAcceptable = (
            $null -ne $buildProvenance -and
            [string]$buildProvenance.status -eq 'ok' -and
            [string]$buildProvenance.build_tree_state -eq 'clean' -and
            $buildProvenance.build_matches_checkout -eq $true -and
            [int64]$buildProvenance.build_changed_input_count -eq 0 -and
            [int64]$buildProvenance.build_changed_input_omitted -eq 0)
        if (-not $buildProvenanceAcceptable) {
            $provenanceReadback = if ($null -eq $buildProvenance) { '<missing>' } else { $buildProvenance | ConvertTo-Json -Depth 12 -Compress }
            Die "SYNAPSE_CANDIDATE_BUILD_PROVENANCE_UNACCEPTABLE exe=$CandidateExePath sha256=$candidateHash pid=$healthPid bind=$candidateBind health_evidence=$($initialHealthEvidence.Path) health_evidence_sha256=$($initialHealthEvidence.Sha256) build_provenance=$provenanceReadback remediation=build from one exact clean Git checkout, commit it locally before release validation, and rerun setup; the old installed executable and live daemon have not been touched"
        }
        if ($EnableAudio) {
            $audioHealth = $health.subsystems.audio
            if ($null -eq $audioHealth -or [string]$audioHealth.status -eq 'disabled' -or $audioHealth.stt_model_available -ne $true) {
                $audioReadback = if ($null -eq $audioHealth) { '<missing>' } else { $audioHealth | ConvertTo-Json -Depth 8 -Compress }
                Die "SYNAPSE_CANDIDATE_AUDIO_CONTRACT_FAILED pid=$healthPid bind=$candidateBind audio=$audioReadback remediation=verify --enable-audio reached the candidate, READ_AUDIO is granted, and the pinned Whisper/ORT Extensions artifacts are packaged before replacing the live daemon"
            }
        }

        # The isolated vault is intentionally new, so its active panel has no
        # search generation yet. Do not reinterpret that real error as success.
        # Bootstrap it through the same public, permission-gated, audited route
        # an operator uses, then independently read health and the manifest from
        # disk. Any other error is left untouched and refused below.
        if ($health.ok -ne $true) {
            $initialFailures = @(Format-SynapseCandidateHealthFailures -Health $health)
            $searchHealth = $health.subsystems.calyx_search_generation
            $searchPanelVersion = try { [int64]$searchHealth.calyx_search_generation_panel_version } catch { 0 }
            $isExactEmptySearchState = (
                $initialFailures.Count -eq 1 -and
                [string]$initialFailures[0].name -eq 'calyx_search_generation' -and
                [string]$searchHealth.status -eq 'error' -and
                [string]$searchHealth.calyx_search_generation_state -eq 'absent' -and
                $searchHealth.calyx_search_generation_manifest_present -eq $false -and
                $searchPanelVersion -gt 0 -and
                [string]$health.subsystems.calyx_vault.status -eq 'ok' -and
                [string]$health.subsystems.storage.status -eq 'ok')
            if ($isExactEmptySearchState) {
                $searchArgs = [ordered]@{
                    operation = 'search_rebuild'
                    search_rebuild = [ordered]@{
                        expected_panel_version = $searchPanelVersion
                    }
                }
                Info "Candidate isolated vault has no active-panel search generation; bootstrapping through public storage facade panel_version=$searchPanelVersion initial_health_sha256=$($initialHealthEvidence.Sha256)"
                $searchBootstrap = Invoke-SynapseSetupMcpTool `
                    -Bind $candidateBind `
                    -Token $tokenRead.Token `
                    -Name 'storage' `
                    -Arguments $searchArgs `
                    -Profile 'break_glass' `
                    -ProfileReason 'synapse-setup candidate preflight must build and physically verify the isolated active-panel search generation before handoff' `
                    -AcquireForegroundLease `
                    -TimeoutSec 120
                $searchBootstrapEvidence = Write-SynapseCandidateJsonEvidence `
                    -CandidateRoot $candidateRoot `
                    -CandidateRootIdentity $candidateRootIdentity `
                    -LeafName 'candidate-search-bootstrap.json' `
                    -Value $searchBootstrap.Json
                $searchReadback = $searchBootstrap.Json.search_rebuild
                $manifestPath = [string]$searchReadback.manifest_path
                $manifestExpectedSha256 = [string]$searchReadback.manifest_sha256
                if ($null -eq $searchReadback -or [int64]$searchReadback.panel_version -ne $searchPanelVersion -or [string]::IsNullOrWhiteSpace($manifestPath) -or [string]::IsNullOrWhiteSpace($manifestExpectedSha256) -or -not (Test-Path -LiteralPath $manifestPath -PathType Leaf)) {
                    $bootstrapReadback = if ($null -eq $searchReadback) { '<missing>' } else { $searchReadback | ConvertTo-Json -Depth 16 -Compress }
                    Die "SYNAPSE_CANDIDATE_SEARCH_BOOTSTRAP_READBACK_INVALID pid=$healthPid bind=$candidateBind panel_version=$searchPanelVersion evidence=$($searchBootstrapEvidence.Path) evidence_sha256=$($searchBootstrapEvidence.Sha256) readback=$bootstrapReadback remediation=the real storage search_rebuild call did not publish and report the exact active-panel manifest; inspect retained candidate evidence before retrying"
                }
                Ensure-SynapseAtomicFileType
                $manifestPhysicalReadback = [SynapseSetup.AtomicFileV2]::Sha256PhysicalFileUnderRoot(
                    $candidateRoot,
                    $candidateRootIdentity,
                    $manifestPath,
                    '')
                $manifestActualSha256 = [string]$manifestPhysicalReadback.Sha256
                if ($manifestActualSha256 -ine $manifestExpectedSha256) {
                    Die "SYNAPSE_CANDIDATE_SEARCH_BOOTSTRAP_MANIFEST_MISMATCH pid=$healthPid bind=$candidateBind panel_version=$searchPanelVersion manifest=$manifestPath expected_sha256=$manifestExpectedSha256 actual_sha256=$manifestActualSha256 evidence=$($searchBootstrapEvidence.Path) remediation=the independently read physical manifest bytes do not match the storage facade's committed readback; inspect the isolated vault and candidate logs"
                }
                $postBootstrapHealthRead = Read-SynapseHealthForRestartGuard -Bind $candidateBind -Token $tokenRead.Token -TimeoutSec 30
                if (-not $postBootstrapHealthRead.Ok) {
                    Die "SYNAPSE_CANDIDATE_POST_BOOTSTRAP_HEALTH_UNREADABLE pid=$healthPid bind=$candidateBind panel_version=$searchPanelVersion manifest=$manifestPath manifest_sha256=$manifestActualSha256 error=$($postBootstrapHealthRead.Error) remediation=the search manifest exists on disk but authenticated health cannot independently report candidate state; inspect retained candidate evidence"
                }
                $health = $postBootstrapHealthRead.Health
                if ([int]$health.pid -ne $healthPid) {
                    Die "SYNAPSE_CANDIDATE_POST_BOOTSTRAP_PID_MISMATCH expected_pid=$healthPid health_pid=$($health.pid) bind=$candidateBind remediation=post-bootstrap health came from an unexpected process; refusing handoff"
                }
                $postBootstrapHealthEvidence = Write-SynapseCandidateJsonEvidence `
                    -CandidateRoot $candidateRoot `
                    -CandidateRootIdentity $candidateRootIdentity `
                    -LeafName 'candidate-health-after-bootstrap.json' `
                    -Value $health
                Info "Candidate isolated search generation physically verified panel_version=$searchPanelVersion manifest=$manifestPath manifest_sha256=$manifestActualSha256 health_evidence=$($postBootstrapHealthEvidence.Path) health_evidence_sha256=$($postBootstrapHealthEvidence.Sha256) health_ok=$($health.ok)"
            }
        }
        if ($health.ok -ne $true) {
            $failures = @(Format-SynapseCandidateHealthFailures -Health $health)
            $failuresJson = if ($failures.Count -eq 0) { '[]' } else { $failures | ConvertTo-Json -Depth 12 -Compress }
            $subsystemStatuses = @()
            if ($health.subsystems) {
                foreach ($prop in @($health.subsystems.PSObject.Properties | Sort-Object Name)) {
                    $subsystemStatuses += ("{0}={1}" -f $prop.Name, ([string]$prop.Value.status))
                }
            }
            $statusText = if ($subsystemStatuses.Count -gt 0) { $subsystemStatuses -join ',' } else { '<none>' }
            Die "SYNAPSE_CANDIDATE_HEALTH_UNHEALTHY exe=$CandidateExePath sha256=$candidateHash pid=$healthPid bind=$candidateBind failures=$failuresJson subsystem_statuses=$statusText health_evidence=$($initialHealthEvidence.Path) health_evidence_sha256=$($initialHealthEvidence.Sha256) evidence_root=$candidateRoot stdout=$candidateStdout stderr=$candidateStderr remediation=repair every subsystem reporting error and rerun setup; setup refuses to replace the old installed executable or live daemon while candidate semantic health is false"
        }
        $surface = Read-SynapseDaemonToolSurface -Bind $candidateBind -Token $tokenRead.Token -Health $health
        if ($surface.tool_count -lt 1) {
            Die "SYNAPSE_CANDIDATE_TOOL_SURFACE_EMPTY pid=$healthPid bind=$candidateBind remediation=tools/list returned no tools; refusing handoff"
        }
        $finalCandidateHealthRead = Read-SynapseHealthForRestartGuard -Bind $candidateBind -Token $tokenRead.Token -TimeoutSec 30
        if (-not $finalCandidateHealthRead.Ok) {
            Die "SYNAPSE_CANDIDATE_FINAL_ACCELERATOR_POLICY_HEALTH_UNREADABLE pid=$healthPid bind=$candidateBind error=$($finalCandidateHealthRead.Error) remediation=the lazily exercised candidate must return authenticated health before CPU/no-explicit-GPU-provider-or-API acceptance"
        }
        $health = $finalCandidateHealthRead.Health
        $finalCandidateHealthEvidence = Write-SynapseCandidateJsonEvidence `
            -CandidateRoot $candidateRoot `
            -CandidateRootIdentity $candidateRootIdentity `
            -LeafName 'candidate-health-final.json' `
            -Value $health
        [void](Assert-SynapseNoExplicitGpuRuntimeHealth -Health $health -ProcessId $healthPid -Bind $candidateBind -Phase 'candidate_after_search_and_tools_list')
        # Independently query both live kernel Jobs after every lazy workload
        # and before the one-shot tree exits. The terminal supervisor JSON is
        # durable evidence, but it cannot replace class-28 kernel state read
        # while the bootstrap still owns the authoritative Job handle.
        $candidateTerminalKernelJob = Get-SynapseDaemonJobKernelReadback -JobName $candidateJobName
        $candidateTerminalParentKernelJob = Get-SynapseDaemonJobKernelReadback -JobName $candidateParentJobName
        $candidateTerminalKernelDrift = [System.Collections.Generic.List[string]]::new()
        foreach ($terminalMembership in @(
            [pscustomobject]@{ Name = 'daemon'; Job = $candidateTerminalKernelJob; Pids = @([int]$candidate.Id) },
            [pscustomobject]@{ Name = 'parent'; Job = $candidateTerminalParentKernelJob; Pids = @([int]$candidateBootstrap.Id, [int]$candidateSupervisor.Id, [int]$candidate.Id) }
        )) {
            foreach ($expectedTerminalPid in $terminalMembership.Pids) {
                if (@($terminalMembership.Job.ProcessIds | Where-Object { [uint64]$_ -eq [uint64]$expectedTerminalPid }).Count -ne 1) {
                    $candidateTerminalKernelDrift.Add("$($terminalMembership.Name)_membership expected_pid=$expectedTerminalPid actual_pids=$(@($terminalMembership.Job.ProcessIds) -join ',')")
                }
            }
        }
        if ([uint64]$candidateTerminalKernelJob.CurrentJobMemoryUsedBytes -gt $SynapseDaemonProcessMemoryLimitBytes -or
            [uint64]$candidateTerminalKernelJob.PeakJobMemoryUsedBytes -gt $SynapseDaemonProcessMemoryLimitBytes) {
