                authenticated_shutdown_exit_code = [int]$SynapseAuthenticatedShutdownExitCode
                candidate_health_final_sha256 = [string]$finalCandidateHealthEvidence.Sha256
                bootstrap_path = $candidateBootstrapPath
                bootstrap_sha256 = $candidateBootstrapHashAfter
                bootstrap_log_sha256 = $candidateBootstrapLogSha256
                final_state_sha256 = $candidateFinalStateSha256
                daemon_job_name = $candidateJobName
                parent_job_name = $candidateExpectedParentJobName
                job_limit_flags_hex = '0x00002300'
                daemon_process_memory_limit_bytes = [uint64]$SynapseDaemonProcessMemoryLimitBytes
                daemon_job_memory_limit_bytes = [uint64]$SynapseDaemonProcessMemoryLimitBytes
                parent_process_memory_limit_bytes = [uint64]$SynapseOwnedMemoryLimitBytes
                parent_job_memory_limit_bytes = [uint64]$SynapseOwnedMemoryLimitBytes
                daemon_cpu_rate = [uint32]$SynapseDaemonCpuRate
                parent_cpu_rate = [uint32]$SynapseSupervisorCpuRate
                working_set_policy = 'measured_only'
                probe_task_name = $(if ($UseTaskProbe) { $candidateProbeTaskName } else { '' })
                probe_task_xml_sha256 = $(if ($UseTaskProbe -and $null -ne $candidateProbeTask) { [string]$candidateProbeTask.XmlSha256 } else { '' })
                probe_task_security_descriptor_sha256 = $(if ($UseTaskProbe -and $null -ne $candidateProbeTask) { [string]$candidateProbeTask.SecurityDescriptorSha256 } else { '' })
                probe_task_terminal = $(if ($UseTaskProbe) { 'deleted_after_exact_instance_drain' } else { 'not_applicable_direct_launch' })
            }
            $candidateSuccessMarkerJson = ($candidateSuccessMarker | ConvertTo-Json -Depth 10) + "`n"
            try {
                $candidateSuccessMarkerReadback = $candidateSuccessMarkerJson | ConvertFrom-Json -ErrorAction Stop
            } catch {
                throw "SYNAPSE_CANDIDATE_SUCCESS_MARKER_SERIALIZATION_INVALID path=$candidateSuccessMarkerPath error=$($_.Exception.Message) remediation=preserve candidate evidence and repair the exact marker schema before publication"
            }
            $candidateSuccessMarkerWrite = Write-SynapseAtomicUtf8TextFileUnderPhysicalRoot `
                -Root $candidateRoot `
                -ExpectedRootIdentity $candidateRootIdentity `
                -LeafName 'candidate-success.json' `
                -Content $candidateSuccessMarkerJson `
                -Purpose 'candidate_post_validation_success_marker'
            if ([string]$candidateSuccessMarkerReadback.schema -cne 'synapse_candidate_success/v1' -or
                [string]$candidateSuccessMarkerReadback.state -cne 'verified' -or
                [int]$candidateSuccessMarkerReadback.setup_owner_pid -ne [int]$PID -or
                [string]$candidateSuccessMarkerReadback.candidate_root_identity -ine $candidateRootIdentity -or
                [int]$candidateSuccessMarkerReadback.candidate_pid -ne [int]$candidate.Id -or
                [int]$candidateSuccessMarkerReadback.supervisor_pid -ne [int]$candidateSupervisor.Id -or
                [int]$candidateSuccessMarkerReadback.bootstrap_pid -ne [int]$candidateBootstrap.Id -or
                [int]$candidateSuccessMarkerReadback.authenticated_shutdown_exit_code -ne $SynapseAuthenticatedShutdownExitCode -or
                [string]$candidateSuccessMarkerReadback.candidate_health_final_sha256 -ine [string]$finalCandidateHealthEvidence.Sha256 -or
                [string]$candidateSuccessMarkerReadback.bootstrap_log_sha256 -ine $candidateBootstrapLogSha256 -or
                [string]$candidateSuccessMarkerReadback.final_state_sha256 -ine $candidateFinalStateSha256 -or
                ($UseTaskProbe -and ([string]$candidateSuccessMarkerReadback.probe_task_name -cne $candidateProbeTaskName -or
                    [string]$candidateSuccessMarkerReadback.probe_task_xml_sha256 -ine [string]$candidateProbeTask.XmlSha256 -or
                    [string]$candidateSuccessMarkerReadback.probe_task_security_descriptor_sha256 -ine [string]$candidateProbeTask.SecurityDescriptorSha256 -or
                    [string]$candidateSuccessMarkerReadback.probe_task_terminal -cne 'deleted_after_exact_instance_drain'))) {
                throw "SYNAPSE_CANDIDATE_SUCCESS_MARKER_READBACK_MISMATCH path=$candidateSuccessMarkerPath remediation=preserve candidate evidence; the atomic marker did not decode to the exact terminal validation identities and hashes"
            }
            $candidateResult | Add-Member -NotePropertyName SuccessMarkerSha256 -NotePropertyValue ([string]$candidateSuccessMarkerWrite.sha256) -Force
            Info "SYNAPSE_CANDIDATE_SUCCESS_MARKER_VERIFIED path=$candidateSuccessMarkerPath sha256=$($candidateSuccessMarkerWrite.sha256) candidate_pid=$($candidate.Id) supervisor_pid=$($candidateSupervisor.Id) bootstrap_pid=$($candidateBootstrap.Id) final_health_sha256=$($finalCandidateHealthEvidence.Sha256) bootstrap_log_sha256=$candidateBootstrapLogSha256 final_state_sha256=$candidateFinalStateSha256"
            $candidateSucceeded = $true
            } catch {
                $candidateTerminalFailureMessage = $_.Exception.Message
            }
        }
        if ((Test-Path -LiteralPath $candidateRoot) -and -not $candidateSucceeded) {
            try {
                $candidateDiagnosticPrimaryFailure = if ([string]::IsNullOrWhiteSpace($candidateFailureMessage)) { '' } else { $candidateFailureMessage }
                $candidateDiagnosticTerminalFailure = if ([string]::IsNullOrWhiteSpace($candidateTerminalFailureMessage)) {
                    ''
                } else {
                    $candidateTerminalFailureMessage
                }
                $candidateDiagnosticFailure = if ([string]::IsNullOrWhiteSpace($candidateDiagnosticPrimaryFailure) -and [string]::IsNullOrWhiteSpace($candidateDiagnosticTerminalFailure)) {
                    'candidate validation failed without a captured primary or terminal exception message'
                } elseif ([string]::IsNullOrWhiteSpace($candidateDiagnosticTerminalFailure)) {
                    $candidateDiagnosticPrimaryFailure
                } elseif ([string]::IsNullOrWhiteSpace($candidateDiagnosticPrimaryFailure)) {
                    $candidateDiagnosticTerminalFailure
                } else {
                    "primary_failure=[$candidateDiagnosticPrimaryFailure] terminal_failure=[$candidateDiagnosticTerminalFailure]"
                }
                $diagnostic = Write-SynapseCandidateFailureEvidence `
                    -CandidateRoot $candidateRoot `
                    -CandidateRootIdentity $candidateRootIdentity `
                    -Process $candidate `
                    -SupervisorProcess $candidateSupervisor `
                    -BootstrapProcess $candidateBootstrap `
                    -FailureMessage $candidateDiagnosticFailure `
                    -PrimaryFailureMessage $candidateDiagnosticPrimaryFailure `
                    -TerminalFailureMessage $candidateDiagnosticTerminalFailure `
                    -Bind $candidateBind `
                    -ExecutablePath $CandidateExePath `
                    -ExecutableSha256 $candidateHash `
                    -CleanupVerified ($candidateCleanupErrors.Count -eq 0) `
                    -CleanupErrors @($candidateCleanupErrors)
                Info "Candidate failure evidence retained path=$($diagnostic.Path) sha256=$($diagnostic.Sha256) evidence_count=$($diagnostic.EvidenceCount) exit_code_signed=$($diagnostic.Exit.ExitCodeSigned) exit_code_hex=$($diagnostic.Exit.ExitCodeHex)"
                Remove-SynapseExpiredCandidateFailureEvidence -Root (Join-Path $LogDir 'setup-candidates') -Keep 5
            } catch {
                throw "SYNAPSE_CANDIDATE_EVIDENCE_WRITE_FAILED path=$candidateRoot error=$($_.Exception.Message) primary_failure=[$candidateFailureMessage] terminal_failure=[$candidateTerminalFailureMessage] remediation=preserve the exact candidate directory and repair log-directory permissions before rerunning setup"
            }
        } elseif (Test-Path -LiteralPath $candidateRoot) {
            [void](Remove-SynapseCandidateArtifact `
                -Path $candidateRoot `
                -ExpectedRoot $candidateArtifactRoot `
                -ExpectedCandidateRootIdentity $candidateRootIdentity `
                -CandidateProcessId ([int]$candidate.Id) `
                -Bind $candidateBind `
                -Reason 'validated_candidate_success')
        }
        if (-not [string]::IsNullOrWhiteSpace($candidateTerminalFailureMessage)) {
            if ([string]::IsNullOrWhiteSpace($candidateFailureMessage)) {
                throw $candidateTerminalFailureMessage
            }
            throw "$candidateTerminalFailureMessage primary_failure=[$candidateFailureMessage]"
        }
        } finally {
            if($null-ne$candidate){try{$candidate.Dispose()}catch{[Environment]::FailFast("SYNAPSE_CANDIDATE_PROCESS_HANDLE_RELEASE_UNPROVEN primary=[$candidateFailureMessage] terminal=[$candidateTerminalFailureMessage]",$_.Exception)};$candidate=$null}
            if($null-ne$candidateSupervisor){try{$candidateSupervisor.Dispose()}catch{[Environment]::FailFast("SYNAPSE_CANDIDATE_SUPERVISOR_HANDLE_RELEASE_UNPROVEN primary=[$candidateFailureMessage] terminal=[$candidateTerminalFailureMessage]",$_.Exception)};$candidateSupervisor=$null}
            if($null-ne$candidateBootstrap){try{$candidateBootstrap.Dispose()}catch{[Environment]::FailFast("SYNAPSE_CANDIDATE_BOOTSTRAP_HANDLE_RELEASE_UNPROVEN primary=[$candidateFailureMessage] terminal=[$candidateTerminalFailureMessage]",$_.Exception)};$candidateBootstrap=$null}
        }
    }
    return $candidateResult
}

function Write-SynapseCodexToolSurfaceSnapshot {
    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)]$Surface
    )

    $full=[System.IO.Path]::GetFullPath($Path)
    try {
        $dir = Split-Path -Parent $full
        New-Item -ItemType Directory -Force -Path $dir | Out-Null
        $content=(Get-SynapseCanonicalJson -Value $Surface)+"`n"
        $write=Write-SynapseAtomicUtf8TextFile -Path $full -Content $content -Purpose 'codex_tool_surface_snapshot_v2'
        $read=[System.IO.File]::ReadAllText($full,[System.Text.UTF8Encoding]::new($false,$true))
        if($read-cne$content){throw 'atomic snapshot byte readback differs from the rendered canonical bytes'}
        $parsed=$read|ConvertFrom-Json -ErrorAction Stop
        $expectedHash=[string]$Surface.tool_surface_sha256
        $actualHash=[string]$parsed.tool_surface_sha256
        if($expectedHash-notmatch'^[0-9A-Fa-f]{64}$' -or $actualHash-ine$expectedHash -or [int]$parsed.tool_count-ne[int]$Surface.tool_count -or [int]$parsed.tool_count-lt 1 -or [int]$parsed.daemon_pid-ne[int]$Surface.daemon_pid){
            throw "snapshot semantic readback drift expected_daemon_pid=$($Surface.daemon_pid) actual_daemon_pid=$($parsed.daemon_pid) expected_tool_count=$($Surface.tool_count) actual_tool_count=$($parsed.tool_count) expected_surface_sha256=$expectedHash actual_surface_sha256=$actualHash"
        }
    } catch {
        Die "SYNAPSE_CODEX_TOOL_SURFACE_SNAPSHOT_WRITE_FAILED path=$full error=$($_.Exception.Message) remediation=repair permissions on the Synapse appdata directory before starting Codex"
    }
    Info "Codex tool-surface snapshot atomically written and read back path=$full file_sha256=$($write.sha256) daemon_pid=$($Surface.daemon_pid) tool_count=$($Surface.tool_count) tool_surface_sha256=$($Surface.tool_surface_sha256)"
}

function Read-SynapseCodexToolSurfaceSnapshotOrNull {
    param([AllowNull()][string]$Path)

    if ([string]::IsNullOrWhiteSpace($Path) -or -not (Test-Path -LiteralPath $Path)) {
        return $null
    }
    try {
        return Get-Content -Raw -LiteralPath $Path | ConvertFrom-Json
    } catch {
        return [pscustomobject]@{
            unreadable = $true
            path = $Path
            error = $_.Exception.Message
        }
    }
}

function New-SynapseToolRecordMap {
    param([AllowNull()]$Surface)

    $map = @{}
    if ($null -eq $Surface -or $Surface.unreadable) {
        return $map
    }
    foreach ($record in @($Surface.tool_schemas)) {
        $name = [string]$record.name
        if (-not [string]::IsNullOrWhiteSpace($name)) {
            $map[$name] = $record
        }
    }
    return $map
}

function Get-SynapseNullableSchemaHash {
    param([AllowNull()]$Schema)

    if ($null -eq $Schema) {
        return '<null>'
    }
    return Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $Schema)
}

function Get-SynapseStoredHashOrEmpty {
    param(
        [AllowNull()]$Record,
        [Parameter(Mandatory=$true)][string]$Name
    )

    if ($null -eq $Record) {
        return ''
    }
    if ($Record -is [System.Collections.IDictionary] -and $Record.Contains($Name)) {
        if ($null -eq $Record[$Name]) {
            return ''
        }
        return [string]$Record[$Name]
    }
    $property = $Record.PSObject.Properties[$Name]
    if (-not $property -or $null -eq $property.Value) {
        return ''
    }
    return [string]$property.Value
}

function Get-SynapseRecordSchemaHash {
    param(
        [AllowNull()]$Record,
        [Parameter(Mandatory=$true)][string]$StoredHashName,
        [Parameter(Mandatory=$true)][string]$SchemaPropertyName
    )

    $stored = Get-SynapseStoredHashOrEmpty -Record $Record -Name $StoredHashName
    if (-not [string]::IsNullOrWhiteSpace($stored)) {
        return $stored
    }
    if ($null -eq $Record) {
        return '<null>'
    }
    if ($Record -is [System.Collections.IDictionary] -and $Record.Contains($SchemaPropertyName)) {
        return Get-SynapseNullableSchemaHash -Schema $Record[$SchemaPropertyName]
    }
    $property = $Record.PSObject.Properties[$SchemaPropertyName]
    $schema = if ($property) { $property.Value } else { $null }
    return Get-SynapseNullableSchemaHash -Schema $schema
}

function Format-SynapseLimitedList {
    param(
        [AllowNull()]$Items,
        [int]$Limit = 20
    )

    $values = @($Items | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | Sort-Object -Unique)
    if ($values.Count -eq 0) {
        return 'none'
    }
    $shown = @($values | Select-Object -First $Limit)
    $suffix = if ($values.Count -gt $Limit) { ",+$($values.Count - $Limit)_more" } else { '' }
    return (($shown -join ',') + $suffix)
}

function Get-SynapseToolSurfaceDiff {
    param(
        [AllowNull()]$StartSurface,
        [Parameter(Mandatory=$true)]$CurrentSurface
    )

    if ($null -eq $StartSurface) {
        return [pscustomobject]([ordered]@{
            Summary = 'start_snapshot=missing added=unknown removed=unknown callable_schema_changed=unknown'
            SchemaDetail = 'missing'
            HasRestartRequired = $true
            HasNameDelta = $true
            HasCallableSchemaChange = $true
        })
    }
    if ($StartSurface.unreadable) {
        return [pscustomobject]([ordered]@{
            Summary = "start_snapshot=unreadable error=$($StartSurface.error) added=unknown removed=unknown callable_schema_changed=unknown"
            SchemaDetail = 'unreadable'
            HasRestartRequired = $true
            HasNameDelta = $true
            HasCallableSchemaChange = $true
        })
    }

    $startNames = @($StartSurface.tool_names | ForEach-Object { [string]$_ } | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Sort-Object -Unique)
    $currentNames = @($CurrentSurface.tool_names | ForEach-Object { [string]$_ } | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Sort-Object -Unique)
    $added = @($currentNames | Where-Object { $startNames -notcontains $_ })
    $removed = @($startNames | Where-Object { $currentNames -notcontains $_ })

    $startMap = New-SynapseToolRecordMap -Surface $StartSurface
    $currentMap = New-SynapseToolRecordMap -Surface $CurrentSurface
    $inputChanged = @()
    $outputChanged = @()
    $descriptionChanged = @()
    $storedHashChanged = @()
    $storedSchemaHashOnlyChanged = @()
    if ($startMap.Count -gt 0 -and $currentMap.Count -gt 0) {
        foreach ($name in $currentNames) {
            if ($startMap.ContainsKey($name) -and $currentMap.ContainsKey($name)) {
                $startRecord = $startMap[$name]
                $currentRecord = $currentMap[$name]
                $startInputHash = Get-SynapseRecordSchemaHash -Record $startRecord -StoredHashName 'input_schema_sha256' -SchemaPropertyName 'input_schema'
                $currentInputHash = Get-SynapseRecordSchemaHash -Record $currentRecord -StoredHashName 'input_schema_sha256' -SchemaPropertyName 'input_schema'
                $startOutputHash = Get-SynapseRecordSchemaHash -Record $startRecord -StoredHashName 'output_schema_sha256' -SchemaPropertyName 'output_schema'
                $currentOutputHash = Get-SynapseRecordSchemaHash -Record $currentRecord -StoredHashName 'output_schema_sha256' -SchemaPropertyName 'output_schema'
                if ($startInputHash -ne $currentInputHash) {
                    $inputChanged += $name
                }
                if ($startOutputHash -ne $currentOutputHash) {
                    $outputChanged += $name
                }
                if ([string]$startRecord.description -ne [string]$currentRecord.description) {
                    $descriptionChanged += $name
                }
                $storedInputChanged = (Get-SynapseStoredHashOrEmpty -Record $startRecord -Name 'input_schema_sha256') -ne (Get-SynapseStoredHashOrEmpty -Record $currentRecord -Name 'input_schema_sha256')
                $storedOutputChanged = (Get-SynapseStoredHashOrEmpty -Record $startRecord -Name 'output_schema_sha256') -ne (Get-SynapseStoredHashOrEmpty -Record $currentRecord -Name 'output_schema_sha256')
                $storedToolChanged = (Get-SynapseStoredHashOrEmpty -Record $startRecord -Name 'tool_sha256') -ne (Get-SynapseStoredHashOrEmpty -Record $currentRecord -Name 'tool_sha256')
                if ($storedToolChanged) {
                    $storedHashChanged += $name
                }
                if (($storedInputChanged -or $storedOutputChanged) -and $startInputHash -eq $currentInputHash -and $startOutputHash -eq $currentOutputHash) {
                    $storedSchemaHashOnlyChanged += $name
                }
            }
        }
    }
    $schemaDetail = if ($startMap.Count -gt 0 -and $currentMap.Count -gt 0) { 'present' } else { 'missing' }
    $callableSchemaChanged = @($inputChanged + $outputChanged | Sort-Object -Unique)
    $hasNameDelta = ($added.Count -gt 0 -or $removed.Count -gt 0)
    $hasCallableSchemaChange = ($schemaDetail -ne 'present' -or $callableSchemaChanged.Count -gt 0)
    $summary = ("start_snapshot_schema_detail={0} added={1} removed={2} callable_schema_changed={3} input_schema_changed={4} output_schema_changed={5} description_changed={6} stored_tool_hash_changed={7} stored_schema_hash_only_changed={8}" -f `
        $schemaDetail,
        (Format-SynapseLimitedList -Items $added),
        (Format-SynapseLimitedList -Items $removed),
        (Format-SynapseLimitedList -Items $callableSchemaChanged),
        (Format-SynapseLimitedList -Items $inputChanged),
        (Format-SynapseLimitedList -Items $outputChanged),
        (Format-SynapseLimitedList -Items $descriptionChanged),
        (Format-SynapseLimitedList -Items $storedHashChanged),
        (Format-SynapseLimitedList -Items $storedSchemaHashOnlyChanged))
    return [pscustomobject]([ordered]@{
        Summary = $summary
        SchemaDetail = $schemaDetail
        Added = $added
        Removed = $removed
        InputSchemaChanged = $inputChanged
        OutputSchemaChanged = $outputChanged
        CallableSchemaChanged = $callableSchemaChanged
        DescriptionChanged = $descriptionChanged
        StoredToolHashChanged = $storedHashChanged
        StoredSchemaHashOnlyChanged = $storedSchemaHashOnlyChanged
        HasDescriptionChange = ($descriptionChanged.Count -gt 0)
        HasNameDelta = $hasNameDelta
        HasCallableSchemaChange = $hasCallableSchemaChange
        HasRestartRequired = ($hasNameDelta -or $hasCallableSchemaChange -or $descriptionChanged.Count -gt 0)
    })
}

function Get-SynapseToolSurfaceDiffSummary {
    param(
        [AllowNull()]$StartSurface,
        [Parameter(Mandatory=$true)]$CurrentSurface
    )

    $diff = Get-SynapseToolSurfaceDiff -StartSurface $StartSurface -CurrentSurface $CurrentSurface
    return $diff.Summary
}

function Write-SynapseUtf8NoBomFile {
    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$Text
    )

    $dir = Split-Path -Parent $Path
    New-Item -ItemType Directory -Force -Path $dir | Out-Null
    $encoding = [System.Text.UTF8Encoding]::new($false)
    [System.IO.File]::WriteAllText($Path, $Text, $encoding)
}

function Write-SynapseChromeBridgeCheckpoint {
    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][System.Collections.IDictionary]$Checkpoint
    )

    if ([string]::IsNullOrWhiteSpace($Path)) {
        throw 'SYNAPSE_SETUP_BRIDGE_CHECKPOINT_PATH_EMPTY remediation=provide an absolute checkpoint path under the configured host local appdata directory'
    }
    $resolvedPath = [System.IO.Path]::GetFullPath($Path)
    $directory = Split-Path -Parent $resolvedPath
    if ([string]::IsNullOrWhiteSpace($directory)) {
        throw "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_DIRECTORY_EMPTY path=$resolvedPath remediation=provide a checkpoint path with a parent directory"
    }
    New-Item -ItemType Directory -Force -Path $directory | Out-Null

    $now = [DateTime]::UtcNow.ToString('o')
    $Checkpoint['schema'] = 'synapse_setup_bridge_pending/v5'
    $Checkpoint['phase'] = 'chrome_bridge_activation'
    if (-not $Checkpoint.Contains('checkpoint_generation_id') -or [string]::IsNullOrWhiteSpace([string]$Checkpoint['checkpoint_generation_id'])) {
        throw "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_GENERATION_MISSING path=$resolvedPath state=$($Checkpoint['state']) remediation=a bridge checkpoint must retain the exact setup generation that created the pending transaction"
    }
    if (-not $Checkpoint.Contains('created_at_utc') -or [string]::IsNullOrWhiteSpace([string]$Checkpoint['created_at_utc'])) {
        $Checkpoint['created_at_utc'] = $now
    }
    $Checkpoint['updated_at_utc'] = $now
    $Checkpoint['checkpoint_path'] = $resolvedPath

    $temporaryPath = "$resolvedPath.tmp.$PID.$([guid]::NewGuid().ToString('N'))"
    $replacementBackupPath = "$resolvedPath.replace-backup.$PID.$([guid]::NewGuid().ToString('N'))"
    $replacementCompleted = $false
    try {
        Write-SynapseUtf8NoBomFile `
            -Path $temporaryPath `
            -Text (($Checkpoint | ConvertTo-Json -Depth 40) + "`n")
        if (Test-Path -LiteralPath $resolvedPath -PathType Leaf) {
            [System.IO.File]::Replace($temporaryPath, $resolvedPath, $replacementBackupPath, $true)
            $replacementCompleted = $true
        } else {
            [System.IO.File]::Move($temporaryPath, $resolvedPath)
            $replacementCompleted = $true
        }
    } catch {
        throw "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_ATOMIC_WRITE_FAILED path=$resolvedPath temp=$temporaryPath recovery_backup=$replacementBackupPath replacement_completed=$replacementCompleted error=$($_.Exception.Message) remediation=repair checkpoint directory permissions and free space; preserve any named recovery backup for inspection because a resumable phase is never reported without an atomic durable write"
    } finally {
        if (Test-Path -LiteralPath $temporaryPath -PathType Leaf) {
            Remove-Item -LiteralPath $temporaryPath -Force -ErrorAction SilentlyContinue
        }
    }
    if ($replacementCompleted -and (Test-Path -LiteralPath $replacementBackupPath -PathType Leaf)) {
        try {
            Remove-Item -LiteralPath $replacementBackupPath -Force -ErrorAction Stop
        } catch {
            throw "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_BACKUP_CLEANUP_FAILED path=$resolvedPath recovery_backup=$replacementBackupPath error=$($_.Exception.Message) remediation=the new checkpoint is committed, but its exact replace backup could not be removed; repair permissions and remove only the named backup"
        }
        if (Test-Path -LiteralPath $replacementBackupPath) {
            throw "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_BACKUP_STILL_PRESENT path=$resolvedPath recovery_backup=$replacementBackupPath remediation=the new checkpoint is committed, but the exact replace backup still exists; repair storage state before accepting resume"
        }
    }

    try {
        $bytes = [System.IO.File]::ReadAllBytes($resolvedPath)
        $readback = [System.Text.Encoding]::UTF8.GetString($bytes) | ConvertFrom-Json
    } catch {
        throw "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_READBACK_FAILED path=$resolvedPath error=$($_.Exception.Message) remediation=inspect the checkpoint storage device; the atomically written JSON could not be read back"
    }
    if ([string]$readback.schema -ne 'synapse_setup_bridge_pending/v5' -or
        [string]$readback.phase -ne 'chrome_bridge_activation' -or
        [string]$readback.state -ne [string]$Checkpoint['state'] -or
        [string]$readback.checkpoint_generation_id -ne [string]$Checkpoint['checkpoint_generation_id']) {
        throw "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_READBACK_MISMATCH path=$resolvedPath expected_schema=synapse_setup_bridge_pending/v5 actual_schema=$($readback.schema) expected_phase=chrome_bridge_activation actual_phase=$($readback.phase) expected_state=$($Checkpoint['state']) actual_state=$($readback.state) expected_generation=$($Checkpoint['checkpoint_generation_id']) actual_generation=$($readback.checkpoint_generation_id) remediation=repair the checkpoint storage path before retrying"
    }
    return [pscustomobject]([ordered]@{
        Path = $resolvedPath
        Sha256 = Get-SynapseFileSha256 -Path $resolvedPath
        LenBytes = $bytes.Length
        State = [string]$readback.state
    })
}

function Read-SynapseChromeBridgeCheckpoint {
    param([Parameter(Mandatory=$true)][string]$Path)

    if ([string]::IsNullOrWhiteSpace($Path)) {
        Die 'SYNAPSE_SETUP_BRIDGE_CHECKPOINT_PATH_EMPTY remediation=-ResumeChromeBridgePending requires the durable checkpoint path'
    }
    $resolvedPath = [System.IO.Path]::GetFullPath($Path)
    if (-not (Test-Path -LiteralPath $resolvedPath -PathType Leaf)) {
        Die "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_MISSING path=$resolvedPath remediation=resume only a physically present bridge_pending checkpoint; run ordinary setup repair when no phase is pending"
    }
    try {
        $bytes = [System.IO.File]::ReadAllBytes($resolvedPath)
    } catch {
        Die "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_READ_FAILED path=$resolvedPath error=$($_.Exception.Message) remediation=repair checkpoint file permissions before retrying resume"
    }
    if ($bytes.Length -eq 0) {
        Die "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_EMPTY path=$resolvedPath remediation=inspect the interrupted checkpoint write; resume refuses to infer state from an empty file"
    }
    try {
        $checkpoint = [System.Text.Encoding]::UTF8.GetString($bytes) | ConvertFrom-Json
    } catch {
        Die "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_JSON_INVALID path=$resolvedPath error=$($_.Exception.Message) remediation=inspect the checkpoint bytes; resume refuses to infer state from malformed JSON"
    }

    if ([string]$checkpoint.schema -ne 'synapse_setup_bridge_pending/v5') {
        Die "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_SCHEMA_INVALID path=$resolvedPath expected=synapse_setup_bridge_pending/v5 actual=$($checkpoint.schema) remediation=older checkpoints do not bind the immutable broker task, physical control pair, and authority generation; preserve them and run a new full setup"
    }
    if ([string]$checkpoint.phase -ne 'chrome_bridge_activation') {
        Die "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_PHASE_INVALID path=$resolvedPath expected=chrome_bridge_activation actual=$($checkpoint.phase) remediation=resume refuses to infer or replay an unknown phase"
    }
    if ([string]$checkpoint.state -ne 'pending') {
        Die "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_NOT_PENDING path=$resolvedPath actual=$($checkpoint.state) remediation=completed and superseded records are terminal evidence, not resumable work; run ordinary full setup if repair is still required"
    }
    foreach ($required in @(
        'checkpoint_generation_id',
        'daemon_handoff',
        'daemon_pid',
        'bind',
        'db_path',
        'installed_binary_path',
        'installed_binary_sha256',
        'daemon_process_executable_path',
        'daemon_process_command_line',
        'daemon_process_creation_date',
        'daemon_run_current_path',
        'daemon_run_current_sha256',
        'token_path',
        'token_sha256',
        'setup_script_path',
        'setup_script_sha256',
        'chrome_bridge_installer_path',
        'chrome_bridge_installer_sha256',
        'chrome_native_host_exe_path',
        'chrome_native_host_exe_sha256',
        'broker_identity_sha256',
        'authority_epoch',
        'authority_root_path',
        'authority_root_file_id_128',
        'runtime_bin_dir',
        'runtime_bin_file_id_128',
        'authority_generation_id',
        'control_gate_file_id_128',
        'control_gate_sha256',
        'control_gate_length',
        'roster_file_id_128',
        'roster_sha256',
        'roster_length',
        'broker_task_capability_sha256',
        'broker_task_name',
        'broker_task_xml_sha256',
        'broker_task_security_descriptor_sha256',
        'broker_task_action_execute',
        'broker_task_action_arguments',
        'broker_task_action_working_directory',
        'broker_bootstrap_path',
        'broker_bootstrap_parent_path',
        'broker_bootstrap_parent_file_id_128',
        'broker_bootstrap_file_id_128',
        'broker_bootstrap_sha256',
        'broker_bootstrap_length',
        'broker_script_path',
        'broker_script_parent_path',
        'broker_script_parent_file_id_128',
        'broker_script_file_id_128',
        'broker_script_sha256',
        'broker_script_length',
        'maintenance_lock_path'
    )) {
        $property = $checkpoint.PSObject.Properties[$required]
        if ($null -eq $property -or [string]::IsNullOrWhiteSpace([string]$property.Value)) {
            Die "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_FIELD_MISSING path=$resolvedPath field=$required remediation=resume requires a complete identity-bound checkpoint and never guesses missing state"
        }
    }
    if ([string]$checkpoint.daemon_handoff -ne 'committed') {
        Die "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_HANDOFF_UNCOMMITTED path=$resolvedPath actual=$($checkpoint.daemon_handoff) remediation=only a physically committed daemon handoff can resume at Chrome activation"
    }
    $checkpoint | Add-Member -NotePropertyName checkpoint_file_path -NotePropertyValue $resolvedPath -Force
    $checkpoint | Add-Member -NotePropertyName checkpoint_file_sha256 -NotePropertyValue (Get-SynapseFileSha256 -Path $resolvedPath) -Force
    $checkpoint | Add-Member -NotePropertyName checkpoint_file_len_bytes -NotePropertyValue $bytes.Length -Force
    return $checkpoint
}

function Get-SynapseDaemonProcessIdentity {
    param([Parameter(Mandatory=$true)][int]$ProcessId)

    $process = Get-CimInstance Win32_Process -Filter "ProcessId=$ProcessId" -ErrorAction SilentlyContinue
    if ($null -eq $process) {
        Die "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_DAEMON_PROCESS_MISSING pid=$ProcessId remediation=the checkpointed daemon is no longer live; perform a new full setup repair instead of resuming stale Chrome activation"
    }
    if (-not (Test-SynapseMcpExecutableLeafName -Name ([string]$process.Name))) {
        Die "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_DAEMON_PROCESS_NAME_INVALID pid=$ProcessId name=$($process.Name) remediation=the checkpoint PID was reused by a non-Synapse process; perform a new full setup repair"
    }
    return [pscustomobject]([ordered]@{
        Pid = [int]$process.ProcessId
        ParentPid = [int]$process.ParentProcessId
        CreationDate = [string]$process.CreationDate
        Name = [string]$process.Name
        ExecutablePath = [string]$process.ExecutablePath
        CommandLine = [string]$process.CommandLine
    })
}

function Assert-SynapseChromeBridgeCheckpointFileIdentity {
    param(
        [Parameter(Mandatory=$true)][string]$Kind,
        [Parameter(Mandatory=$true)][string]$ExpectedPath,
        [Parameter(Mandatory=$true)][string]$ExpectedSha256
    )

    $resolvedExpectedPath = [System.IO.Path]::GetFullPath($ExpectedPath)
    if (-not (Test-Path -LiteralPath $resolvedExpectedPath -PathType Leaf)) {
        Die "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_${Kind}_MISSING path=$resolvedExpectedPath remediation=restore the exact checkpointed file or perform a new full setup repair"
    }
    $actualSha256 = Get-SynapseFileSha256 -Path $resolvedExpectedPath
    if ($actualSha256 -ine $ExpectedSha256) {
        Die "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_${Kind}_DRIFT path=$resolvedExpectedPath expected_sha256=$ExpectedSha256 actual_sha256=$actualSha256 remediation=the checkpointed phase belongs to different bytes; perform a new full setup repair"
    }
    return [pscustomobject]([ordered]@{
        Path = $resolvedExpectedPath
        Sha256 = $actualSha256
    })
}

function ConvertTo-SynapseBrokerAuthorityFromChromeCheckpoint {
    param(
        [Parameter(Mandatory=$true)]$Checkpoint,
        [Parameter(Mandatory=$true)][string]$Context
    )
    foreach($hashName in @('broker_identity_sha256','broker_task_capability_sha256','broker_task_xml_sha256','broker_task_security_descriptor_sha256','broker_bootstrap_sha256','broker_script_sha256','control_gate_sha256','roster_sha256')){
        if([string]$Checkpoint.$hashName -notmatch '^[0-9A-Fa-f]{64}$'){Die "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_HASH_INVALID context=$Context field=$hashName value=$($Checkpoint.$hashName)"}
    }
    foreach($idName in @('authority_root_file_id_128','runtime_bin_file_id_128','broker_bootstrap_parent_file_id_128','broker_bootstrap_file_id_128','broker_script_parent_file_id_128','broker_script_file_id_128','control_gate_file_id_128','roster_file_id_128')){
        if([string]$Checkpoint.$idName -notmatch '^[0-9A-Fa-f]{16}:[0-9A-Fa-f]{32}$'){Die "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_FILE_ID_INVALID context=$Context field=$idName value=$($Checkpoint.$idName)"}
    }
    $runtime=Get-SynapseNormalizedDirectoryPath -Path ([string]$Checkpoint.runtime_bin_dir)
    $layout=Get-SynapseAuthorityLayout -RuntimeBinDir $runtime
    if((Get-SynapseNormalizedDirectoryPath -Path ([string]$Checkpoint.authority_root_path)) -ine [string]$layout.Root -or
       [string]$Checkpoint.authority_root_file_id_128 -ine [string]$layout.RootChain[-1].file_id_128 -or
       [string]$Checkpoint.runtime_bin_file_id_128 -ine [string]$layout.RuntimeChain[-1].file_id_128){
        Die "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_AUTHORITY_ROOT_DRIFT context=$Context expected_root=$($Checkpoint.authority_root_path) actual_root=$($layout.Root)"
    }
    $expectedTask=[pscustomobject][ordered]@{
        Name=[string]$Checkpoint.broker_task_name;XmlSha256=[string]$Checkpoint.broker_task_xml_sha256
        SecurityDescriptorSha256=[string]$Checkpoint.broker_task_security_descriptor_sha256
        Execute=[string]$Checkpoint.broker_task_action_execute;Arguments=[string]$Checkpoint.broker_task_action_arguments
        WorkingDirectory=[string]$Checkpoint.broker_task_action_working_directory
    }
    $task=Assert-SynapseTaskReadbackIdentity -Expected $expectedTask -Kind broker
    [void](Assert-SynapseBrokerTaskDescriptorShape -Descriptor (ConvertTo-SynapseAuthorityTaskDescriptor -Task $task) -BrokerIdentitySha256 ([string]$Checkpoint.broker_identity_sha256) -TaskCapabilitySha256 ([string]$Checkpoint.broker_task_capability_sha256) -Context "${Context}_task")
    $bootstrapDescriptor=[pscustomobject][ordered]@{
        role='broker_bootstrap';path=[string]$Checkpoint.broker_bootstrap_path;file_id_128=[string]$Checkpoint.broker_bootstrap_file_id_128
        sha256=[string]$Checkpoint.broker_bootstrap_sha256;length=[int64]$Checkpoint.broker_bootstrap_length
        parent_path=[string]$Checkpoint.broker_bootstrap_parent_path;parent_file_id_128=[string]$Checkpoint.broker_bootstrap_parent_file_id_128
    }
    $scriptDescriptor=[pscustomobject][ordered]@{
        role='broker_script';path=[string]$Checkpoint.broker_script_path;file_id_128=[string]$Checkpoint.broker_script_file_id_128
        sha256=[string]$Checkpoint.broker_script_sha256;length=[int64]$Checkpoint.broker_script_length
        parent_path=[string]$Checkpoint.broker_script_parent_path;parent_file_id_128=[string]$Checkpoint.broker_script_parent_file_id_128
    }
    $bootstrap=Assert-SynapseAuthorityFileDescriptorPhysicalIdentity -Descriptor $bootstrapDescriptor -ExpectedRole broker_bootstrap -ExpectedParent $layout.Objects -Context "${Context}_bootstrap"
    $brokerScript=Assert-SynapseAuthorityFileDescriptorPhysicalIdentity -Descriptor $scriptDescriptor -ExpectedRole broker_script -ExpectedParent $layout.Objects -Context "${Context}_script"
    $infrastructure=[pscustomobject][ordered]@{
        BrokerIdentitySha256=([string]$Checkpoint.broker_identity_sha256).ToUpperInvariant();TaskCapabilitySha256=([string]$Checkpoint.broker_task_capability_sha256).ToUpperInvariant();TaskName=[string]$task.Name;Task=$task
        Bootstrap=$bootstrap;BrokerScript=$brokerScript;Arguments=[string]$task.Arguments
        BootstrapLogPath='';BootstrapFatalEvidencePath=Get-SynapseSupervisorBootstrapFatalEvidencePath;SemanticContract=$null
    }
    return [pscustomobject][ordered]@{Layout=$layout;Infrastructure=$infrastructure;BrokerTask=$task;AuthorityEpoch=[int64]$Checkpoint.authority_epoch}
}

function Invoke-SynapseChromeBridgePendingResume {
    param([Parameter(Mandatory=$true)][string]$CheckpointPath)

    if ($Remove -or $Purge -or $ForceRestart -or $SkipBuild -or $SkipClientWiring -or
        $ManualInstallHealthRollbackProbe -or $script:SynapsePostExitStartOnly) {
        Die "SYNAPSE_SETUP_BRIDGE_RESUME_MODE_CONFLICT remove=$Remove purge=$Purge force_restart=$ForceRestart skip_build=$SkipBuild skip_client_wiring=$SkipClientWiring rollback_probe=$ManualInstallHealthRollbackProbe post_exit=$script:SynapsePostExitStartOnly remediation=-ResumeChromeBridgePending is a complete phase-specific mode; remove all full-setup/remove/rollback switches"
    }

    Step 'Resuming checkpointed Chrome bridge activation'
    $checkpoint = Read-SynapseChromeBridgeCheckpoint -Path $CheckpointPath
    $script:SynapseChromeBridgePendingPath = [string]$checkpoint.checkpoint_file_path

    $checkpointLockPath = [System.IO.Path]::GetFullPath([string]$checkpoint.maintenance_lock_path)
    $actualLockPath = [System.IO.Path]::GetFullPath($MaintenanceLockPath)
    if ($checkpointLockPath -ine $actualLockPath) {
        Die "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_MAINTENANCE_LOCK_DRIFT expected=$checkpointLockPath actual=$actualLockPath remediation=resume must reacquire the exact maintenance lock recorded by the committed setup"
    }

    $scriptIdentity = Assert-SynapseChromeBridgeCheckpointFileIdentity `
        -Kind 'SETUP_SCRIPT' `
        -ExpectedPath ([string]$checkpoint.setup_script_path) `
        -ExpectedSha256 ([string]$checkpoint.setup_script_sha256)
    $runningScriptPath = [System.IO.Path]::GetFullPath($PSCommandPath)
    if ($runningScriptPath -ine $scriptIdentity.Path) {
        Die "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_SETUP_SCRIPT_PATH_DRIFT expected=$($scriptIdentity.Path) actual=$runningScriptPath remediation=invoke the exact setup script that wrote the checkpoint"
    }
    $installerIdentity = Assert-SynapseChromeBridgeCheckpointFileIdentity `
        -Kind 'CHROME_INSTALLER' `
        -ExpectedPath ([string]$checkpoint.chrome_bridge_installer_path) `
        -ExpectedSha256 ([string]$checkpoint.chrome_bridge_installer_sha256)
    $nativeHostIdentity = Assert-SynapseChromeBridgeCheckpointFileIdentity `
        -Kind 'CHROME_NATIVE_HOST' `
        -ExpectedPath ([string]$checkpoint.chrome_native_host_exe_path) `
        -ExpectedSha256 ([string]$checkpoint.chrome_native_host_exe_sha256)
    $binaryIdentity = Assert-SynapseChromeBridgeCheckpointFileIdentity `
        -Kind 'INSTALLED_BINARY' `
        -ExpectedPath ([string]$checkpoint.installed_binary_path) `
        -ExpectedSha256 ([string]$checkpoint.installed_binary_sha256)
    $tokenIdentity = Assert-SynapseChromeBridgeCheckpointFileIdentity `
        -Kind 'TOKEN' `
        -ExpectedPath ([string]$checkpoint.token_path) `
        -ExpectedSha256 ([string]$checkpoint.token_sha256)
    $Bind = [string]$checkpoint.bind
    $DbPath = [string]$checkpoint.db_path
    $ExePath = $binaryIdentity.Path
    $TokenPath = $tokenIdentity.Path
    $ChromeNativeHostExePath = $nativeHostIdentity.Path

    $token = (Get-Content -Raw -LiteralPath $TokenPath).Trim()
    if ([string]::IsNullOrWhiteSpace($token)) {
        Die "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_TOKEN_EMPTY path=$TokenPath remediation=restore the exact non-empty checkpointed bearer token or perform a new full setup repair"
    }
    $checkpointAuthority=ConvertTo-SynapseBrokerAuthorityFromChromeCheckpoint -Checkpoint $checkpoint -Context 'chrome_resume_authority'
    $brokerReadback=Assert-SynapseCurrentBrokerAuthorityGenerationOperational -Authority $checkpointAuthority -ExpectedGenerationId ([string]$checkpoint.authority_generation_id) -HealthTimeoutSeconds 420 -Context 'chrome_resume_before_activation'
    if([string]$brokerReadback.ControlGate.FileId128 -ine [string]$checkpoint.control_gate_file_id_128 -or
       [string]$brokerReadback.ControlGate.Sha256 -ine [string]$checkpoint.control_gate_sha256 -or [int64]$brokerReadback.ControlGate.Length -ne [int64]$checkpoint.control_gate_length -or
       [string]$brokerReadback.Roster.FileId128 -ine [string]$checkpoint.roster_file_id_128 -or
       [string]$brokerReadback.Roster.Sha256 -ine [string]$checkpoint.roster_sha256 -or [int64]$brokerReadback.Roster.Length -ne [int64]$checkpoint.roster_length){
        Die "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_CONTROL_PAIR_DRIFT generation=$($checkpoint.authority_generation_id) remediation=the broker control generation changed after the checkpoint; perform a new full setup repair"
    }
    $health=$brokerReadback.Proof.Health
    $actualPid=[int]$brokerReadback.Proof.DaemonPid
    $daemonProcess=Get-SynapseDaemonProcessIdentity -ProcessId $actualPid

    $health = Assert-SynapseChromeBridgeLiveAfterSetup `
        -Bind $Bind `
        -Token $token `
        -Health $health `
        -ChromeBridgeInstallerPath $installerIdentity.Path `
        -ChromeNativeHostExePath $ChromeNativeHostExePath
    $postChromeBroker=Assert-SynapseCurrentBrokerAuthorityGenerationOperational -Authority $checkpointAuthority -ExpectedGenerationId ([string]$checkpoint.authority_generation_id) -HealthTimeoutSeconds 420 -Context 'chrome_resume_after_activation'
    $health=$postChromeBroker.Proof.Health
    $actualPid=[int]$postChromeBroker.Proof.DaemonPid
    $daemonProcess=Get-SynapseDaemonProcessIdentity -ProcessId $actualPid
    $toolSurface=$postChromeBroker.Proof.ToolSurface
    $bridge = $health.subsystems.chrome_bridge
    $completion = [ordered]@{
        completed_at_utc = [DateTime]::UtcNow.ToString('o')
        daemon_pid = $actualPid
        bind = $Bind
        installed_binary_path = $binaryIdentity.Path
        installed_binary_sha256 = $binaryIdentity.Sha256
        daemon_process_command_line = $daemonProcess.CommandLine
        token_sha256 = $tokenIdentity.Sha256
        setup_script_sha256 = $scriptIdentity.Sha256
        chrome_bridge_installer_sha256 = $installerIdentity.Sha256
        chrome_native_host_exe_path = $nativeHostIdentity.Path
        chrome_native_host_exe_sha256 = $nativeHostIdentity.Sha256
        broker_task_name = [string]$checkpointAuthority.BrokerTask.Name
        broker_task_xml_sha256 = [string]$checkpointAuthority.BrokerTask.XmlSha256
        broker_task_security_descriptor_sha256 = [string]$checkpointAuthority.BrokerTask.SecurityDescriptorSha256
        chrome_bridge_status = [string]$bridge.status
        chrome_bridge_detail = [string]$bridge.detail
        tool_count = $toolSurface.tool_count
        tool_surface_sha256 = $toolSurface.tool_surface_sha256
    }
    $checkpointMap = [ordered]@{}
    foreach ($property in $checkpoint.PSObject.Properties) {
        if ($property.Name -notin @('checkpoint_file_path','checkpoint_file_sha256','checkpoint_file_len_bytes')) {
            $checkpointMap[$property.Name] = $property.Value
        }
    }
    $checkpointMap['state'] = 'completed'
    $checkpointMap['resume_attempt_count'] = ([int]$checkpoint.resume_attempt_count) + 1
    $checkpointMap['completion'] = $completion
    $checkpointFile = Write-SynapseChromeBridgeCheckpoint -Path $checkpoint.checkpoint_file_path -Checkpoint $checkpointMap
    $completion['checkpoint_path'] = $checkpointFile.Path
    $completion['checkpoint_sha256'] = $checkpointFile.Sha256
    $completion['checkpoint_len_bytes'] = $checkpointFile.LenBytes
    Write-SynapseSetupRepairManifestState `
        -State 'completed' `
        -Message 'checkpointed Chrome bridge activation completed without replaying daemon installation or task registration' `
        -ExitCode 0 `
        -Readback $completion
    Info "SYNAPSE_SETUP_BRIDGE_RESUME_COMPLETED checkpoint=$($checkpointFile.Path) checkpoint_sha256=$($checkpointFile.Sha256) daemon_pid=$actualPid tool_count=$($toolSurface.tool_count) tool_surface_sha256=$($toolSurface.tool_surface_sha256)"
}

function Complete-SynapseObsoleteChromeBridgeCheckpoint {
    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][int]$DaemonPid,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$DbPath,
        [Parameter(Mandatory=$true)][string]$InstalledBinaryPath,
        [Parameter(Mandatory=$true)][string]$InstalledBinarySha256,
        [Parameter(Mandatory=$true)][string]$ChromeNativeHostExePath,
        [Parameter(Mandatory=$true)][string]$ChromeNativeHostExeSha256,
        [Parameter(Mandatory=$true)]$ToolSurface,
        [Parameter(Mandatory=$true)]$ChromeBridge
    )

    $resolvedPath = [System.IO.Path]::GetFullPath($Path)
    if (-not (Test-Path -LiteralPath $resolvedPath -PathType Leaf)) {
        Info "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_ABSENT path=$resolvedPath terminalizing_generation=$($script:SynapseSetupInvocationId)"
        return [ordered]@{ state = 'absent'; path = $resolvedPath; terminalizing_generation_id = $script:SynapseSetupInvocationId }
    }
    try {
        $priorBytes = [System.IO.File]::ReadAllBytes($resolvedPath)
        $prior = [System.Text.Encoding]::UTF8.GetString($priorBytes) | ConvertFrom-Json
    } catch {
        Die "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_TERMINALIZE_READ_FAILED path=$resolvedPath error=$($_.Exception.Message) remediation=the current setup succeeded but refuses to conceal malformed historical transaction state; inspect and repair the named checkpoint"
    }
    $priorSha256 = Get-SynapseFileSha256 -Path $resolvedPath
    $priorSchema = [string]$prior.schema
    $priorState = [string]$prior.state
    if ($priorSchema -notin @('synapse_setup_bridge_pending/v2','synapse_setup_bridge_pending/v3','synapse_setup_bridge_pending/v4','synapse_setup_bridge_pending/v5')) {
        Die "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_TERMINALIZE_SCHEMA_UNKNOWN path=$resolvedPath schema=$priorSchema sha256=$priorSha256 remediation=setup refuses to reinterpret or delete an unknown transaction schema"
    }
    if ($priorState -in @('completed','superseded')) {
        Info "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_ALREADY_TERMINAL path=$resolvedPath schema=$priorSchema state=$priorState sha256=$priorSha256"
        return [ordered]@{ state = $priorState; path = $resolvedPath; sha256 = $priorSha256; schema = $priorSchema }
    }
    if ($priorState -ne 'pending') {
        Die "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_TERMINALIZE_STATE_UNKNOWN path=$resolvedPath schema=$priorSchema state=$priorState sha256=$priorSha256 remediation=setup refuses to reinterpret or delete an unknown transaction state"
    }

    $checkpointMap = [ordered]@{}
    foreach ($property in $prior.PSObject.Properties) {
        $checkpointMap[$property.Name] = $property.Value
    }
    if ($priorSchema -eq 'synapse_setup_bridge_pending/v2' -or [string]::IsNullOrWhiteSpace([string]$checkpointMap['checkpoint_generation_id'])) {
        $checkpointMap['checkpoint_generation_id'] = "legacy-unbound-$($priorSha256.ToLowerInvariant())"
    }
    $daemonProcess = Get-SynapseDaemonProcessIdentity -ProcessId $DaemonPid
    $daemonRunPath = Join-Path $DbPath 'daemon-run-current.json'
    if (-not (Test-Path -LiteralPath $daemonRunPath -PathType Leaf)) {
        Die "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_TERMINALIZE_DAEMON_RUN_MISSING path=$daemonRunPath daemon_pid=$DaemonPid remediation=the newer deployment generation is not physically proven; repair its lifecycle ledger before terminalizing older work"
    }
    $checkpointMap['state'] = 'superseded'
    $checkpointMap['chrome_native_host_exe_path'] = [System.IO.Path]::GetFullPath($ChromeNativeHostExePath)
    $checkpointMap['chrome_native_host_exe_sha256'] = $ChromeNativeHostExeSha256
    $checkpointMap['terminal_generation_id'] = $script:SynapseSetupInvocationId
    $checkpointMap['terminalized_at_utc'] = [DateTime]::UtcNow.ToString('o')
    $checkpointMap['supersession'] = [ordered]@{
        reason = 'newer_full_setup_completed_and_physically_verified'
        prior_schema = $priorSchema
        prior_state = $priorState
        prior_checkpoint_sha256 = $priorSha256
        daemon_pid = $DaemonPid
        daemon_process_creation_date = $daemonProcess.CreationDate
        daemon_process_executable_path = $daemonProcess.ExecutablePath
        daemon_process_command_line = $daemonProcess.CommandLine
        bind = $Bind
        daemon_run_current_path = $daemonRunPath
        daemon_run_current_sha256 = (Get-SynapseFileSha256 -Path $daemonRunPath)
        installed_binary_path = $InstalledBinaryPath
        installed_binary_sha256 = $InstalledBinarySha256
        chrome_native_host_exe_path = [System.IO.Path]::GetFullPath($ChromeNativeHostExePath)
        chrome_native_host_exe_sha256 = $ChromeNativeHostExeSha256
        tool_count = $ToolSurface.tool_count
        tool_surface_sha256 = $ToolSurface.tool_surface_sha256
        chrome_bridge_status = [string]$ChromeBridge.status
        chrome_bridge_detail = [string]$ChromeBridge.detail
    }
    $terminal = Write-SynapseChromeBridgeCheckpoint -Path $resolvedPath -Checkpoint $checkpointMap
    Info "SYNAPSE_SETUP_BRIDGE_CHECKPOINT_SUPERSEDED path=$($terminal.Path) sha256=$($terminal.Sha256) prior_sha256=$priorSha256 prior_schema=$priorSchema checkpoint_generation=$($checkpointMap['checkpoint_generation_id']) terminal_generation=$($script:SynapseSetupInvocationId) daemon_pid=$DaemonPid"
    return [ordered]@{
        state = 'superseded'
        path = $terminal.Path
        sha256 = $terminal.Sha256
        len_bytes = $terminal.LenBytes
        prior_sha256 = $priorSha256
        checkpoint_generation_id = [string]$checkpointMap['checkpoint_generation_id']
        terminal_generation_id = $script:SynapseSetupInvocationId
    }
}

function Get-SynapseHandoffGitReadback {
    param([AllowNull()][string]$SourceDir)

    if ([string]::IsNullOrWhiteSpace($SourceDir) -or -not (Test-Path -LiteralPath $SourceDir)) {
        return [ordered]@{
            available = $false
            reason = 'source_dir_missing_or_not_supplied'
            source_dir = $SourceDir
        }
    }
    if (-not (Get-Command git -ErrorAction SilentlyContinue)) {
        return [ordered]@{
            available = $false
            reason = 'git_not_found'
            source_dir = $SourceDir
        }
    }

    try {
        $status = @(& git -C $SourceDir status --short --branch 2>&1)
        $head = @(& git -C $SourceDir rev-parse HEAD 2>&1)
        $origin = @(& git -C $SourceDir rev-parse origin/main 2>&1)
        $branch = @(& git -C $SourceDir branch --show-current 2>&1)
        return [ordered]@{
            available = $true
            source_dir = $SourceDir
            branch = (($branch | Select-Object -First 1) -join '').Trim()
            head = (($head | Select-Object -First 1) -join '').Trim()
            origin_main = (($origin | Select-Object -First 1) -join '').Trim()
            status_short_branch = @($status)
        }
    } catch {
        return [ordered]@{
            available = $false
            reason = 'git_readback_failed'
            source_dir = $SourceDir
            error = $_.Exception.Message
        }
    }
}

function Get-SynapseRecoveryNotesPath {
    param([AllowNull()][string]$SourceDir)

    $candidates = @()
    if (-not [string]::IsNullOrWhiteSpace($SourceDir)) {
        $candidates += (Join-Path $SourceDir 'STATE\RECOVERY_NOTES.md')
    }
    $repoRootFromScript = Split-Path -Parent $PSScriptRoot
    if (-not [string]::IsNullOrWhiteSpace($repoRootFromScript)) {
        $candidates += (Join-Path $repoRootFromScript 'STATE\RECOVERY_NOTES.md')
    }

    foreach ($candidate in @($candidates | Select-Object -Unique)) {
        if (Test-Path -LiteralPath $candidate) {
            return $candidate
        }
    }
    $first = @($candidates | Select-Object -First 1)
    if ($first.Count -gt 0) {
        return [string]$first[0]
    }
    return $null
}

function Get-SynapseNormalizedIssueRef {
    param([AllowNull()][string]$Issue)

    if ([string]::IsNullOrWhiteSpace($Issue)) {
        return $null
    }

    $trimmed = $Issue.Trim()
    if ($trimmed -match '^#?(?<number>[0-9]+)$') {
        return "#$($Matches['number'])"
    }
    if ($trimmed -match '^https://github\.com/ChrisRoyse/Synapse/issues/(?<number>[0-9]+)(?:[/?#].*)?$') {
        return "#$($Matches['number'])"
    }

    Die "SYNAPSE_ACTIVE_ISSUE_INVALID value=$trimmed remediation=pass an issue number like 1441, #1441, or https://github.com/ChrisRoyse/Synapse/issues/1441"
}

function Get-SynapseIssueNumberFromRef {
    param([AllowNull()][string]$IssueRef)

    if ([string]::IsNullOrWhiteSpace($IssueRef)) {
        return $null
    }
    if ($IssueRef -match '^#(?<number>[0-9]+)$') {
        return $Matches['number']
    }
    return $null
}

function ConvertTo-SynapseHandoffDiffObject {
    param([AllowNull()]$Diff)

    if ($null -eq $Diff) {
        return [ordered]@{
            available = $false
            reason = 'diff_not_supplied'
        }
    }

    return [ordered]@{
        available = $true
        summary = [string]$Diff.Summary
        schema_detail = [string]$Diff.SchemaDetail
        has_restart_required = [bool]$Diff.HasRestartRequired
        has_name_delta = [bool]$Diff.HasNameDelta
        has_callable_schema_change = [bool]$Diff.HasCallableSchemaChange
        has_description_change = [bool]$Diff.HasDescriptionChange
        added = @($Diff.Added | ForEach-Object { [string]$_ })
        removed = @($Diff.Removed | ForEach-Object { [string]$_ })
        input_schema_changed = @($Diff.InputSchemaChanged | ForEach-Object { [string]$_ })
        output_schema_changed = @($Diff.OutputSchemaChanged | ForEach-Object { [string]$_ })
        callable_schema_changed = @($Diff.CallableSchemaChanged | ForEach-Object { [string]$_ })
        description_changed = @($Diff.DescriptionChanged | ForEach-Object { [string]$_ })
        stored_tool_hash_changed = @($Diff.StoredToolHashChanged | ForEach-Object { [string]$_ })
        stored_schema_hash_only_changed = @($Diff.StoredSchemaHashOnlyChanged | ForEach-Object { [string]$_ })
    }
}

function ConvertTo-SynapseTcpClientEvidenceObject {
    param([object[]]$TcpClients)

    return @($TcpClients | ForEach-Object {
        [ordered]@{
            state = [string]$_.State
            local_address = [string]$_.LocalAddress
            local_port = [int]$_.LocalPort
            remote_address = [string]$_.RemoteAddress
            remote_port = [int]$_.RemotePort
            owning_process = [int]$_.OwningProcess
            owner_name = [string]$_.OwnerName
            owner_command_line = [string]$_.OwnerCommandLine
            peer_owning_process = [int]$_.PeerOwningProcess
            peer_owner_exists = [bool]$_.PeerOwnerExists
            peer_owner_name = [string]$_.PeerOwnerName
            peer_owner_command_line = [string]$_.PeerOwnerCommandLine
            has_live_peer = [bool]$_.HasLivePeer
        }
    })
}

function ConvertTo-SynapseListenerEvidenceObject {
    param([object[]]$Listeners)

    return @($Listeners | ForEach-Object {
        [ordered]@{
            state = [string]$_.State
            local_address = [string]$_.LocalAddress
            local_port = [int]$_.LocalPort
            owning_process = [int]$_.OwningProcess
            owner_exists = [bool]$_.OwnerExists
            owner_name = [string]$_.OwnerName
            owner_command_line = [string]$_.OwnerCommandLine
            creation_time = [string]$_.CreationTime
        }
    })
}

function Get-SynapseCodexPeerRows {
    param([object[]]$TcpClients)

    return @($TcpClients | Where-Object {
        if (-not $_.HasLivePeer -or [int]$_.PeerOwningProcess -le 0) {
            $false
        } else {
            $peer = Get-CimInstance Win32_Process -Filter "ProcessId=$([int]$_.PeerOwningProcess)" -ErrorAction SilentlyContinue
            Test-SynapseCodexProcess -Process $peer
        }
    })
}

function Write-SynapseCodexSocketRestartHandoff {
    param(
        [Parameter(Mandatory=$true)][string]$Reason,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][object[]]$CodexTcpClients,
        [Parameter(Mandatory=$true)][object[]]$TcpClients,
        [Parameter(Mandatory=$true)][object[]]$StaleListeners,
        [Parameter(Mandatory=$true)][AllowNull()][string]$BindProbeError,
        [AllowNull()][string]$SourceDir,
        [AllowNull()][string]$TokenPath,
        [AllowNull()][string]$ActiveIssue
    )

    $root = Join-Path $env:LOCALAPPDATA 'synapse\codex-restart-handoffs'
    $stamp = [DateTime]::UtcNow.ToString('yyyyMMddTHHmmssfffZ')
    $firstCodexPid = @($CodexTcpClients | ForEach-Object { [int]$_.PeerOwningProcess } | Sort-Object -Unique | Select-Object -First 1)
    $codexPidForName = if ($firstCodexPid.Count -gt 0) { [int]$firstCodexPid[0] } else { 0 }
    $baseName = "codex-socket-handoff-$codexPidForName-$stamp"
    $jsonPath = Join-Path $root "$baseName.json"
    $mdPath = Join-Path $root "$baseName.md"
    $recoveryNotesPath = Get-SynapseRecoveryNotesPath -SourceDir $SourceDir
    $activeIssueRef = Get-SynapseNormalizedIssueRef -Issue $ActiveIssue
    $activeIssueNumber = Get-SynapseIssueNumberFromRef -IssueRef $activeIssueRef
    $activeIssueRead = if ([string]::IsNullOrWhiteSpace($activeIssueNumber)) {
        $null
    } else {
        "gh issue view $activeIssueNumber --repo ChrisRoyse/Synapse --comments"
    }
    $codexPeers = @($CodexTcpClients | ForEach-Object {
        $peerPid = [int]$_.PeerOwningProcess
        $peer = Get-CimInstance Win32_Process -Filter "ProcessId=$peerPid" -ErrorAction SilentlyContinue
        [ordered]@{
            pid = $peerPid
            name = if ($peer) { [string]$peer.Name } else { [string]$_.PeerOwnerName }
            command_line = if ($peer) { [string]$peer.CommandLine } else { [string]$_.PeerOwnerCommandLine }
            tcp_local = "$($_.LocalAddress):$($_.LocalPort)"
            tcp_remote = "$($_.RemoteAddress):$($_.RemotePort)"
        }
    })
    $codexPeerPids = @($codexPeers | ForEach-Object { [int]$_.pid } | Sort-Object -Unique)
    $postRestartRequiredReads = @(
        'C:\Users\hotra\Downloads\AICodingAgentSuperPrompt.md',
        'C:\code\Synapse\docs\compressionprompt.md',
        'C:\code\Synapse\AGENTS.md',
        $recoveryNotesPath
    ) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) }
    $githubReads = @(
        'gh issue view 351 --repo ChrisRoyse/Synapse --comments',
        $activeIssueRead,
        'gh issue view 1405 --repo ChrisRoyse/Synapse --comments',
        'gh issue list --repo ChrisRoyse/Synapse --state open --limit 100'
    ) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) }
    $restartCommandHint = if ([string]::IsNullOrWhiteSpace($activeIssueRef)) {
        "Close the exact Codex peer process(es) named in this handoff by ending their owning Codex session(s), start a new Codex session through the patched launcher, verify those stale peer PID(s) are gone, then resume from GitHub issue state."
    } else {
        "Close the exact Codex peer process(es) named in this handoff by ending their owning Codex session(s), start a new Codex session through the patched launcher, verify those stale peer PID(s) are gone, then resume $activeIssueRef."
    }

    $record = [ordered]@{
        schema_version = 1
        artifact_kind = 'synapse_codex_socket_restart_handoff'
        created_at_utc = [DateTime]::UtcNow.ToString('o')
        reason_code = 'SYNAPSE_CODEX_CURRENT_PROCESS_SOCKET_STALE'
        reason = $Reason
        phase = 'dead_owner_bind_drain'
        required_restart = $true
        no_in_process_socket_release = $true
        explanation = 'The old synapse-mcp daemon exited, but Windows still reports dead-owner listener/socket rows because a live Codex MCP client peer is attached to the stopped daemon socket. Setup must not kill Codex, terminal, IDE, or WSL processes globally; restart the exact Codex session named here so Windows releases the stale socket, then rerun setup repair.'
        bind = $Bind
        bind_probe = [ordered]@{
            ok = $false
            error = $BindProbeError
        }
        codex_peer_pids = $codexPeerPids
        codex_peers = $codexPeers
        stale_listeners = ConvertTo-SynapseListenerEvidenceObject -Listeners $StaleListeners
        tcp_clients = ConvertTo-SynapseTcpClientEvidenceObject -TcpClients $TcpClients
        active_issue = [ordered]@{
            issue_ref = $activeIssueRef
            issue_number = $activeIssueNumber
            source = 'ActiveIssue parameter or SYNAPSE_ACTIVE_ISSUE environment variable'
            status = if ([string]::IsNullOrWhiteSpace($activeIssueRef)) { 'unknown' } else { 'provided' }
        }
        github_reads = $githubReads
        post_restart_required_reads = $postRestartRequiredReads
        post_restart_verification = @(
            'Run git status --short --branch and confirm the working tree matches this handoff/recovery note.',
            "Read the OS process table and confirm stale Codex peer PID(s) $($codexPeerPids -join ',') no longer exist.",
            'Read Get-NetTCPConnection for 127.0.0.1:7700 and confirm no rows point at the stopped daemon PID from this handoff.',
            'Run deferred Synapse tool discovery, then call real mcp__synapse.health and setup status from the fresh Codex session.',
            'Rerun setup.repair through the real MCP setup facade; direct HTTP/stdio helper calls are diagnostics only.'
        )
        restart_command_hint = $restartCommandHint
        repo_readback = Get-SynapseHandoffGitReadback -SourceDir $SourceDir
        token_path = $TokenPath
        recovery_notes_path = $recoveryNotesPath
    }

    try {
        New-Item -ItemType Directory -Force -Path $root | Out-Null
        Write-SynapseUtf8NoBomFile -Path $jsonPath -Text (($record | ConvertTo-Json -Depth 40) + "`n")
        $md = @(
            '# Synapse Codex Socket Restart Handoff',
            '',
            "- Reason: SYNAPSE_CODEX_CURRENT_PROCESS_SOCKET_STALE ($Reason)",
            '- Phase: dead_owner_bind_drain',
            "- Created UTC: $($record.created_at_utc)",
            "- Bind: $Bind",
            "- Codex peer PID(s): $($codexPeerPids -join ',')",
            "- Active issue: $(if ([string]::IsNullOrWhiteSpace($activeIssueRef)) { 'unknown; recover from caller/session context or open issue queue' } else { $activeIssueRef })",
            '',
            '## Required Restart',
            'The running Codex peer still has a TCP connection to the stopped daemon. Setup cannot safely kill Codex or terminal/IDE/WSL hosts. End the exact Codex session owning the listed PID(s), start a new Codex session through the patched launcher, and prove those PID(s) disappeared before retrying setup repair.',
            '',
            '## Socket Evidence',
            '```text',
            "stale_listeners:",
            (Format-SynapseTcpBindListenerSnapshot -Snapshot $StaleListeners),
            '',
            "tcp_clients:",
            (Format-SynapseTcpClientSnapshot -Snapshot $TcpClients),
            '',
            "bind_probe_error=$BindProbeError",
            '```',
            '',
            '## Read After Restart'
        )
        foreach ($item in $postRestartRequiredReads) {
            $md += "- $item"
        }
        $md += @(
            '',
            '## GitHub Reads'
        )
        foreach ($item in $record.github_reads) {
            $md += "- $item"
        }
        $md += @(
            '',
            '## Verification'
        )
        foreach ($item in $record.post_restart_verification) {
            $md += "- $item"
        }
        $md += @(
            '',
            "JSON artifact: $jsonPath",
            ''
        )
        Write-SynapseUtf8NoBomFile -Path $mdPath -Text (($md -join "`n") + "`n")

        if (-not [string]::IsNullOrWhiteSpace($recoveryNotesPath)) {
            $notes = @(
                '# Synapse Recovery Notes',
                '',
                '## Latest Codex Socket Restart Handoff',
                '',
                "- Reason: SYNAPSE_CODEX_CURRENT_PROCESS_SOCKET_STALE ($Reason)",
                '- Phase: dead_owner_bind_drain',
                "- Created UTC: $($record.created_at_utc)",
                "- JSON: $jsonPath",
                "- Markdown: $mdPath",
                "- Stale Codex peer PID(s): $($codexPeerPids -join ',')",
                "- Daemon bind: $Bind",
                "- Active issue: $(if ([string]::IsNullOrWhiteSpace($activeIssueRef)) { 'unknown; recover from caller/session context or open issue queue' } else { $activeIssueRef })",
                '',
                "After restart, re-read AGENTS.md, #351, #1405, $(if ([string]::IsNullOrWhiteSpace($activeIssueRef)) { 'the active issue from the caller/session context' } else { $activeIssueRef }), git status, and this file before resuming. Prove the stale Codex peer PID(s) are gone and rerun real mcp__synapse setup repair; direct helper calls are diagnostics only.",
                ''
            )
            Write-SynapseUtf8NoBomFile -Path $recoveryNotesPath -Text (($notes -join "`n") + "`n")
        }
    } catch {
        Die "SYNAPSE_CODEX_SOCKET_RESTART_HANDOFF_WRITE_FAILED reason=$Reason bind=$Bind path=$jsonPath error=$($_.Exception.Message) remediation=repair permissions on %LOCALAPPDATA%\synapse\codex-restart-handoffs and the repo STATE directory, then rerun setup"
    }

    Info "SYNAPSE_CODEX_CURRENT_PROCESS_SOCKET_STALE handoff_written reason=$Reason json=$jsonPath markdown=$mdPath recovery_notes=$recoveryNotesPath codex_peer_pids=$($codexPeerPids -join ',')"
    return [pscustomobject]@{
        JsonPath = $jsonPath
        MarkdownPath = $mdPath
        RecoveryNotesPath = $recoveryNotesPath
        CodexPeerPids = $codexPeerPids
    }
}

function Read-SynapsePostExitContinuationTaskPlan {
    param(
        [Parameter(Mandatory=$true)][string]$RunPath,
        [Parameter(Mandatory=$true)][string]$ExpectedRoot
    )
    $root=Get-SynapseNormalizedDirectoryPath -Path $ExpectedRoot
    $run=Get-SynapseNormalizedDirectoryPath -Path $RunPath
    if((Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $run)) -ine $root -or (Split-Path -Leaf $run) -notmatch '^post-exit-\d+-\d{8}T\d{9}Z(?:-[0-9a-f]{16})?$'){
        Die "SYNAPSE_POST_EXIT_CONTINUATION_ROOT_INVALID root=$root run=$run"
    }
    $runChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $run)
    $planLeaf='continuation-task-plan.json'
    $state=Get-SynapsePhysicalRelativeState -ParentPath $run -ParentChain $runChain -Leaf $planLeaf
    if(-not $state.Exists){return $null}
    if([int64]$state.Length -lt 1 -or [int64]$state.Length -gt 65536){Die "SYNAPSE_POST_EXIT_CONTINUATION_PLAN_BOUND_INVALID run=$run length=$($state.Length)"}
    $lease=Open-SynapsePhysicalFileReadLease -ParentPath $run -ParentChain $runChain -Leaf $planLeaf -ExpectedFileId128 ([string]$state.FileId128) -ExpectedSha256 ([string]$state.Sha256) -ExpectedLength ([int64]$state.Length) -Context 'post_exit_continuation_plan_recovery'
    try{
        $read=$lease.ReadUtf8(65536);$text=[string]$read.Content
        try{$plan=$text|ConvertFrom-Json -ErrorAction Stop}catch{Die "SYNAPSE_POST_EXIT_CONTINUATION_PLAN_JSON_INVALID run=$run error=$($_.Exception.Message)"}
        if([string]$plan.schema-in@('synapse_post_exit_continuation_task_plan/v2','synapse_post_exit_continuation_task_plan/v3')){
            $legacyExpected=@('schema','state','name_capability_sha256','capability_sha256','invocation_id','run_nonce','run_id','run_root','run_root_file_id_128','parent_pid','task_name','kind','execute','arguments','working_directory','user_sid','task_create_flag','task_ignore_registration_triggers_flag_absent','trigger_types','task_instance_semantics','maximum_concurrent_instances','cleanup_requires_zero_running_instances','submitted_task_xml_sha256','explicit_security_descriptor','security_descriptor_readback_flags','manifest_path','observation_leaf','wrapper_path','wrapper_file_id_128','wrapper_sha256','wrapper_length','created_at_utc','plan_sha256')
            if([string]$plan.schema-ceq'synapse_post_exit_continuation_task_plan/v3'){$legacyExpected=@($legacyExpected[0..25]+'terminal_leaf'+$legacyExpected[26..($legacyExpected.Count-1)])}
            $legacyNames=@($plan.PSObject.Properties.Name)
            if($legacyNames.Count-ne$legacyExpected.Count-or@($legacyNames|Where-Object{$legacyExpected-cnotcontains$_}).Count-ne0-or(Get-SynapseCanonicalJson -Value (ConvertTo-SynapseCanonicalValue -Value $plan))-cne$text){Die "SYNAPSE_POST_EXIT_CONTINUATION_LEGACY_PLAN_SHAPE_INVALID run=$run schema=$($plan.schema)"}
            $legacyCore=[ordered]@{};foreach($name in @($legacyExpected|Where-Object{$_-cne'plan_sha256'})){$legacyCore[$name]=$plan.$name};$legacyPlanSha=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $legacyCore)).ToUpperInvariant()
            $nameCore=[ordered]@{schema='synapse_post_exit_continuation_name_capability/v1';run_nonce=[string]$plan.run_nonce;run_id=[string]$plan.run_id;invocation_id=[string]$plan.invocation_id;run_root=$run;run_root_file_id_128=([string]$runChain[-1].file_id_128).ToUpperInvariant();parent_pid=[int]$plan.parent_pid;execute=[System.IO.Path]::GetFullPath([string]$plan.execute);arguments=[string]$plan.arguments;working_directory=[System.IO.Path]::GetFullPath([string]$plan.working_directory);wrapper_path=[System.IO.Path]::GetFullPath([string]$plan.wrapper_path);wrapper_file_id_128=([string]$plan.wrapper_file_id_128).ToUpperInvariant();wrapper_sha256=([string]$plan.wrapper_sha256).ToUpperInvariant();wrapper_length=[int64]$plan.wrapper_length;explicit_security_descriptor=[string]$plan.explicit_security_descriptor};$nameCapability=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $nameCore)).ToUpperInvariant();$expectedTaskName='SynapseMcpContinuation-'+$nameCapability.Substring(0,40)
            $legacyCapabilityCore=[ordered]@{schema='synapse_post_exit_continuation_capability/v2';name_capability_sha256=$nameCapability;task_name=$expectedTaskName;run_nonce=$nameCore.run_nonce;run_id=$nameCore.run_id;invocation_id=$nameCore.invocation_id;run_root=$nameCore.run_root;run_root_file_id_128=$nameCore.run_root_file_id_128;parent_pid=$nameCore.parent_pid;execute=$nameCore.execute;arguments=$nameCore.arguments;working_directory=$nameCore.working_directory;wrapper_path=$nameCore.wrapper_path;wrapper_file_id_128=$nameCore.wrapper_file_id_128;wrapper_sha256=$nameCore.wrapper_sha256;wrapper_length=$nameCore.wrapper_length;submitted_task_xml_sha256=([string]$plan.submitted_task_xml_sha256).ToUpperInvariant();explicit_security_descriptor=$nameCore.explicit_security_descriptor};$legacyCapability=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $legacyCapabilityCore)).ToUpperInvariant();$triggers=@($plan.trigger_types)
            if([string]$plan.state-cne'prepared_before_task_create'-or[string]$plan.plan_sha256-ine$legacyPlanSha-or[string]$plan.name_capability_sha256-ine$nameCapability-or[string]$plan.capability_sha256-ine$legacyCapability-or[string]$plan.task_name-cne$expectedTaskName-or[string]$plan.kind-cne'continuation'-or[string]$plan.run_nonce-notmatch'^[0-9a-f]{32}$'-or[string]$plan.run_id-cne(Split-Path -Leaf $run)-or(Get-SynapseNormalizedDirectoryPath -Path ([string]$plan.run_root))-ine$run-or[string]$plan.run_root_file_id_128-ine[string]$runChain[-1].file_id_128-or[int]$plan.parent_pid-le0-or[string]$plan.user_sid-ine(Get-SynapseCurrentUserSid)-or[int]$plan.task_create_flag-ne2-or[bool]$plan.task_ignore_registration_triggers_flag_absent-ne$true-or$triggers.Count-ne1-or[string]$triggers[0]-cne'registration'-or[string]$plan.task_instance_semantics-cne'registration_trigger_single_oneshot_ignore_new'-or[int]$plan.maximum_concurrent_instances-ne1-or[bool]$plan.cleanup_requires_zero_running_instances-ne$true-or[int]$plan.security_descriptor_readback_flags-ne7-or[string]$plan.submitted_task_xml_sha256-notmatch'^[0-9A-Fa-f]{64}$'-or[System.IO.Path]::GetFullPath([string]$plan.manifest_path)-ine[System.IO.Path]::GetFullPath((Join-Path $run 'continuation.json'))-or[System.IO.Path]::GetFullPath([string]$plan.wrapper_path)-ine[System.IO.Path]::GetFullPath((Join-Path $run 'launch-continuation.ps1'))-or([string]$plan.schema-ceq'synapse_post_exit_continuation_task_plan/v3'-and[string]$plan.terminal_leaf-cne'continuation-terminal.json')-or[string]$plan.observation_leaf-cne'continuation-task-observation.json'){Die "SYNAPSE_POST_EXIT_CONTINUATION_LEGACY_PLAN_IDENTITY_INVALID run=$run task=$($plan.task_name) schema=$($plan.schema)"}
            [void](Assert-SynapseAuthorityTaskSecurityDescriptorSemantic -SecurityDescriptor ([string]$plan.explicit_security_descriptor) -ExpectedOwnerSid (Get-SynapseCurrentUserSid) -Context "post_exit_legacy_plan_$($plan.task_name)");$wrapper=Get-SynapsePhysicalRelativeState -ParentPath $run -ParentChain $runChain -Leaf 'launch-continuation.ps1';if(-not(Test-SynapsePhysicalStateExact -State $wrapper -ExpectedExists $true -ExpectedFileId128 ([string]$plan.wrapper_file_id_128) -ExpectedSha256 ([string]$plan.wrapper_sha256) -ExpectedLength ([int64]$plan.wrapper_length))){Die "SYNAPSE_POST_EXIT_CONTINUATION_LEGACY_WRAPPER_DRIFT run=$run task=$($plan.task_name)"};$definition=New-SynapseTaskCreateDefinitionPlan -Name ([string]$plan.task_name) -Kind continuation -Execute ([string]$plan.execute) -Arguments ([string]$plan.arguments) -WorkingDirectory ([string]$plan.working_directory) -UserSid ([string]$plan.user_sid);if([string]$definition.SubmittedXmlSha256-ine[string]$plan.submitted_task_xml_sha256){Die "SYNAPSE_POST_EXIT_CONTINUATION_LEGACY_SUBMITTED_XML_DRIFT run=$run task=$($plan.task_name)"}
            return [pscustomobject][ordered]@{Run=$run;RunChain=$runChain;Path=(Join-Path $run $planLeaf);State=$state;Payload=$plan;Lease=$lease;TaskName=[string]$plan.task_name;Kind='continuation';Execute=[string]$plan.execute;Arguments=[string]$plan.arguments;WorkingDirectory=[string]$plan.working_directory;PlanSha256=$legacyPlanSha;LegacyPreparedResidue=$true}
        }
        $expected=@('schema','state','name_capability_sha256','capability_sha256','invocation_id','run_nonce','run_id','run_root','run_root_file_id_128','parent_pid','task_name','kind','execute','arguments','working_directory','user_sid','task_create_flag','task_ignore_registration_triggers_flag_absent','trigger_types','task_instance_semantics','maximum_concurrent_instances','cleanup_requires_zero_running_instances','submitted_task_xml_sha256','submitted_task_semantic_sha256','explicit_security_descriptor','security_descriptor_readback_flags','manifest_path','terminal_leaf','observation_leaf','wrapper_path','wrapper_file_id_128','wrapper_sha256','wrapper_length','created_at_utc','plan_sha256')
        $names=@($plan.PSObject.Properties.Name)
        if($names.Count -ne $expected.Count -or @($names|Where-Object{$expected -cnotcontains $_}).Count -gt 0 -or (Get-SynapseCanonicalJson -Value (ConvertTo-SynapseCanonicalValue -Value $plan)) -cne $text){Die "SYNAPSE_POST_EXIT_CONTINUATION_PLAN_SHAPE_INVALID run=$run"}
        $core=[ordered]@{};foreach($name in @($expected|Where-Object{$_ -cne 'plan_sha256'})){$core[$name]=$plan.$name}
        $calculatedPlan=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $core)).ToUpperInvariant()
        $nameCore=[ordered]@{schema='synapse_post_exit_continuation_name_capability/v1';run_nonce=[string]$plan.run_nonce;run_id=[string]$plan.run_id;invocation_id=[string]$plan.invocation_id;run_root=$run;run_root_file_id_128=([string]$runChain[-1].file_id_128).ToUpperInvariant();parent_pid=[int]$plan.parent_pid;execute=[System.IO.Path]::GetFullPath([string]$plan.execute);arguments=[string]$plan.arguments;working_directory=[System.IO.Path]::GetFullPath([string]$plan.working_directory);wrapper_path=[System.IO.Path]::GetFullPath([string]$plan.wrapper_path);wrapper_file_id_128=([string]$plan.wrapper_file_id_128).ToUpperInvariant();wrapper_sha256=([string]$plan.wrapper_sha256).ToUpperInvariant();wrapper_length=[int64]$plan.wrapper_length;explicit_security_descriptor=[string]$plan.explicit_security_descriptor}
        $nameCapability=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $nameCore)).ToUpperInvariant()
        $expectedTaskName='SynapseMcpContinuation-'+$nameCapability.Substring(0,40)
        $capabilityCore=[ordered]@{schema='synapse_post_exit_continuation_capability/v3';name_capability_sha256=$nameCapability;task_name=$expectedTaskName;run_nonce=$nameCore.run_nonce;run_id=$nameCore.run_id;invocation_id=$nameCore.invocation_id;run_root=$nameCore.run_root;run_root_file_id_128=$nameCore.run_root_file_id_128;parent_pid=$nameCore.parent_pid;execute=$nameCore.execute;arguments=$nameCore.arguments;working_directory=$nameCore.working_directory;wrapper_path=$nameCore.wrapper_path;wrapper_file_id_128=$nameCore.wrapper_file_id_128;wrapper_sha256=$nameCore.wrapper_sha256;wrapper_length=$nameCore.wrapper_length;submitted_task_xml_sha256=([string]$plan.submitted_task_xml_sha256).ToUpperInvariant();submitted_task_semantic_sha256=([string]$plan.submitted_task_semantic_sha256).ToUpperInvariant();explicit_security_descriptor=$nameCore.explicit_security_descriptor}
        $capability=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $capabilityCore)).ToUpperInvariant()
        $triggers=@($plan.trigger_types)
        if([string]$plan.schema -cne 'synapse_post_exit_continuation_task_plan/v4' -or [string]$plan.state -cne 'prepared_before_task_create' -or
           [string]$plan.plan_sha256 -ine $calculatedPlan -or [string]$plan.name_capability_sha256 -ine $nameCapability -or [string]$plan.capability_sha256 -ine $capability -or [string]$plan.task_name -cne $expectedTaskName -or
           [string]$plan.kind -cne 'continuation' -or [string]$plan.run_nonce -notmatch '^[0-9a-f]{32}$' -or [string]$plan.run_id -cne (Split-Path -Leaf $run) -or
           (Get-SynapseNormalizedDirectoryPath -Path ([string]$plan.run_root)) -ine $run -or [string]$plan.run_root_file_id_128 -ine [string]$runChain[-1].file_id_128 -or [int]$plan.parent_pid -le 0 -or
           [string]$plan.user_sid -ine (Get-SynapseCurrentUserSid) -or [int]$plan.task_create_flag -ne 2 -or [bool]$plan.task_ignore_registration_triggers_flag_absent -ne $true -or
           $triggers.Count -ne 1 -or [string]$triggers[0] -cne 'registration' -or [string]$plan.task_instance_semantics -cne 'registration_trigger_single_oneshot_ignore_new' -or
           [int]$plan.maximum_concurrent_instances -ne 1 -or [bool]$plan.cleanup_requires_zero_running_instances -ne $true -or [int]$plan.security_descriptor_readback_flags -ne 7 -or
           [string]$plan.submitted_task_xml_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [string]$plan.submitted_task_semantic_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [string]$plan.terminal_leaf -cne 'continuation-terminal.json' -or [string]$plan.observation_leaf -cne 'continuation-task-observation.json' -or
           [System.IO.Path]::GetFullPath([string]$plan.manifest_path) -ine [System.IO.Path]::GetFullPath((Join-Path $run 'continuation.json')) -or
           [System.IO.Path]::GetFullPath([string]$plan.wrapper_path) -ine [System.IO.Path]::GetFullPath((Join-Path $run 'launch-continuation.ps1'))){Die "SYNAPSE_POST_EXIT_CONTINUATION_PLAN_IDENTITY_INVALID run=$run task=$($plan.task_name)"}
        [void](Assert-SynapseAuthorityTaskSecurityDescriptorSemantic -SecurityDescriptor ([string]$plan.explicit_security_descriptor) -ExpectedOwnerSid (Get-SynapseCurrentUserSid) -Context "post_exit_plan_$($plan.task_name)")
        $wrapper=Get-SynapsePhysicalRelativeState -ParentPath $run -ParentChain $runChain -Leaf 'launch-continuation.ps1'
        if(-not(Test-SynapsePhysicalStateExact -State $wrapper -ExpectedExists $true -ExpectedFileId128 ([string]$plan.wrapper_file_id_128) -ExpectedSha256 ([string]$plan.wrapper_sha256) -ExpectedLength ([int64]$plan.wrapper_length))){Die "SYNAPSE_POST_EXIT_CONTINUATION_WRAPPER_DRIFT run=$run task=$($plan.task_name)"}
        $definition=New-SynapseTaskCreateDefinitionPlan -Name ([string]$plan.task_name) -Kind continuation -Execute ([string]$plan.execute) -Arguments ([string]$plan.arguments) -WorkingDirectory ([string]$plan.working_directory) -UserSid ([string]$plan.user_sid)
        if([string]$definition.SubmittedXmlSha256 -ine [string]$plan.submitted_task_xml_sha256 -or [string]$definition.SemanticSha256 -ine [string]$plan.submitted_task_semantic_sha256){Die "SYNAPSE_POST_EXIT_CONTINUATION_SUBMITTED_DEFINITION_DRIFT run=$run task=$($plan.task_name)"}
        return [pscustomobject][ordered]@{Run=$run;RunChain=$runChain;Path=(Join-Path $run $planLeaf);State=$state;Payload=$plan;Lease=$lease;TaskName=[string]$plan.task_name;Kind='continuation';Execute=[string]$plan.execute;Arguments=[string]$plan.arguments;WorkingDirectory=[string]$plan.working_directory;PlanSha256=$calculatedPlan;LegacyPreparedResidue=$false}
    }catch{if($null -ne $lease){$lease.Dispose()};throw}
}

function Wait-SynapsePostExitContinuationTaskTerminalRuntime {
    param(
        [Parameter(Mandatory=$true)]$Plan,
        [Parameter(Mandatory=$true)][string]$ExpectedXmlSha256,
        [Parameter(Mandatory=$true)][string]$ExpectedSecurityDescriptorSha256,
        [ValidateRange(5,60)][int]$QuietSeconds=15,
        [ValidateRange(30,300)][int]$TimeoutSeconds=120,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $overall=[Diagnostics.Stopwatch]::StartNew();$quiet=$null;$stableRun=0L;$stableResult=[int64]::MinValue;$last='unobserved'
    do{
        $Plan.Lease.RequireExact("${Context}_plan")
        $lookup=Get-SynapseScheduledTaskLookupExact -Name ([string]$Plan.TaskName)
        if(-not[bool]$lookup.Exists){Die "SYNAPSE_POST_EXIT_CONTINUATION_TASK_DISAPPEARED context=$Context task=$($Plan.TaskName)"}
        $registered=$lookup.Task
        $readback=Get-SynapseTaskDefinitionReadback -RegisteredTask $registered -Kind continuation -ExpectedName ([string]$Plan.TaskName) -ExpectedExecute ([string]$Plan.Execute) -ExpectedArguments ([string]$Plan.Arguments) -ExpectedWorkingDirectory ([string]$Plan.WorkingDirectory) -ExpectedUserSid (Get-SynapseCurrentUserSid) -ExpectedXmlSha256 $ExpectedXmlSha256 -ExpectedSecurityDescriptorSha256 $ExpectedSecurityDescriptorSha256 -ExpectedSemanticSha256 ([string]$Plan.Payload.submitted_task_semantic_sha256)
        try{$state=[int]$registered.State;$instances=@($registered.GetInstances(0));$lastRun=[datetime]$registered.LastRunTime;$lastResult=[int64]$registered.LastTaskResult;$nextRun=[datetime]$registered.NextRunTime}catch{Die "SYNAPSE_POST_EXIT_CONTINUATION_RUNTIME_READ_FAILED context=$Context task=$($Plan.TaskName) error=$($_.Exception.Message)"}
        if($instances.Count-gt1){Die "SYNAPSE_POST_EXIT_CONTINUATION_INSTANCE_CARDINALITY_INVALID context=$Context task=$($Plan.TaskName) count=$($instances.Count)"}
        $lastFileTime=if($lastRun.Year-ge2000){[int64]$lastRun.ToUniversalTime().ToFileTimeUtc()}else{0L};$nextPresent=$nextRun.Year-ge2000
        $ready=($state-eq3-and$instances.Count-eq0-and-not$nextPresent-and$lastFileTime-gt0)
        if($ready){
            if($null-eq$quiet-or$lastFileTime-ne$stableRun-or$lastResult-ne$stableResult){$quiet=[Diagnostics.Stopwatch]::StartNew();$stableRun=$lastFileTime;$stableResult=$lastResult}
            if($quiet.Elapsed-ge[TimeSpan]::FromSeconds($QuietSeconds)){
                $Plan.Lease.RequireExact("${Context}_final_plan")
                $finalLookup=Get-SynapseScheduledTaskLookupExact -Name ([string]$Plan.TaskName)
                if(-not[bool]$finalLookup.Exists){Die "SYNAPSE_POST_EXIT_CONTINUATION_TASK_DISAPPEARED context=${Context}_final task=$($Plan.TaskName)"}
                $final=$finalLookup.Task
                [void](Get-SynapseTaskDefinitionReadback -RegisteredTask $final -Kind continuation -ExpectedName ([string]$Plan.TaskName) -ExpectedExecute ([string]$Plan.Execute) -ExpectedArguments ([string]$Plan.Arguments) -ExpectedWorkingDirectory ([string]$Plan.WorkingDirectory) -ExpectedUserSid (Get-SynapseCurrentUserSid) -ExpectedXmlSha256 $ExpectedXmlSha256 -ExpectedSecurityDescriptorSha256 $ExpectedSecurityDescriptorSha256 -ExpectedSemanticSha256 ([string]$Plan.Payload.submitted_task_semantic_sha256))
                $fi=@($final.GetInstances(0));$fr=[datetime]$final.LastRunTime;$fn=[datetime]$final.NextRunTime
                $finalRunFileTime=if($fr.Year-ge2000){[int64]$fr.ToUniversalTime().ToFileTimeUtc()}else{0L}
                $finalResult=[int64]$final.LastTaskResult
                if([int]$final.State-ne3-or$fi.Count-ne0-or$fn.Year-ge2000-or$fr.Year-lt2000-or$finalRunFileTime-ne$stableRun-or$finalResult-ne$stableResult){Die "SYNAPSE_POST_EXIT_CONTINUATION_TERMINAL_HORIZON_FINAL_DRIFT context=$Context task=$($Plan.TaskName)"}
                return [pscustomobject][ordered]@{RegisteredTask=$final;Readback=$readback;TaskState=3;InstanceCount=0;NextRunTimePresent=$false;LastRunTimeUtc=$fr.ToUniversalTime().ToString('o');LastRunTimeFileTimeUtc=$stableRun;LastTaskResult=$stableResult;QuietSeconds=$QuietSeconds}
            }
            $last="ready quiet_ms=$([int64]$quiet.Elapsed.TotalMilliseconds) last_run=$stableRun result=$stableResult"
        }else{
            if($null-ne$quiet){$quiet.Stop()}
            $quiet=$null;$stableRun=0L;$stableResult=[int64]::MinValue
            $last="state=$state instances=$($instances.Count) next=$nextPresent last_run=$lastFileTime result=$lastResult"
        }
        if($overall.Elapsed-ge[TimeSpan]::FromSeconds($TimeoutSeconds)){Die "SYNAPSE_POST_EXIT_CONTINUATION_TERMINAL_HORIZON_TIMEOUT context=$Context task=$($Plan.TaskName) elapsed_s=$([int64]$overall.Elapsed.TotalSeconds) last=$last"};Start-Sleep -Milliseconds 250
    }while($true)
}

function Resume-SynapsePostExitContinuationTaskIntents {
    param([Parameter(Mandatory=$true)][string]$Root)
    $root=Get-SynapseNormalizedDirectoryPath -Path $Root
    if(-not(Test-Path -LiteralPath $root -PathType Container)){return}
    $rootChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $root)
    $entries=@(Get-SynapsePhysicalDirectoryEntriesBounded -Path $root -Chain $rootChain -MaximumEntries 128 -Context 'post_exit_continuation_root')
    foreach($entry in @($entries|Sort-Object Name)){
        if(-not [bool]$entry.IsDirectory -or ([uint32]$entry.Attributes -band [uint32][System.IO.FileAttributes]::ReparsePoint) -or [string]$entry.Name -notmatch '^post-exit-\d+-\d{8}T\d{9}Z(?:-[0-9a-f]{16})?$'){Die "SYNAPSE_POST_EXIT_CONTINUATION_NAMESPACE_INVALID root=$root entry=$($entry.Name)"}
        $plan=$null
        try{
            $plan=Read-SynapsePostExitContinuationTaskPlan -RunPath ([string]$entry.Path) -ExpectedRoot $root
            if($null -eq $plan){continue}
            if([bool]$plan.LegacyPreparedResidue){$legacyLookup=Get-SynapseScheduledTaskLookupExact -Name ([string]$plan.TaskName);if([bool]$legacyLookup.Exists){Die "SYNAPSE_POST_EXIT_CONTINUATION_LEGACY_TASK_UNEXPECTED run=$($plan.Run) task=$($plan.TaskName) schema=$($plan.Payload.schema) remediation=the frozen legacy plan could not pass semantic authority registration; preserve this unexpected task for operator inspection"};$legacyObservation=Get-SynapsePhysicalRelativeState -ParentPath $plan.Run -ParentChain $plan.RunChain -Leaf ([string]$plan.Payload.observation_leaf);if([bool]$legacyObservation.Exists){Die "SYNAPSE_POST_EXIT_CONTINUATION_LEGACY_OBSERVATION_UNEXPECTED run=$($plan.Run) task=$($plan.TaskName) schema=$($plan.Payload.schema)"};$plan.Lease.RequireExact('post_exit_continuation_legacy_prepared_residue');Info "SYNAPSE_POST_EXIT_CONTINUATION_LEGACY_PREPARED_RESIDUE_RETAINED run=$($plan.Run) task=$($plan.TaskName) schema=$($plan.Payload.schema) task_absent=true";continue}
            $manifestState=Get-SynapsePhysicalRelativeState -ParentPath $plan.Run -ParentChain $plan.RunChain -Leaf 'continuation.json'
            $manifest=$null;$manifestClassification='absent';$manifestTornCut=$null
            if([bool]$manifestState.Exists){
                $manifestTornCut=[ordered]@{file_id_128=([string]$manifestState.FileId128).ToUpperInvariant();sha256=([string]$manifestState.Sha256).ToUpperInvariant();length=[int64]$manifestState.Length}
                if([int64]$manifestState.Length-ge 1 -and [int64]$manifestState.Length-le 1048576){
                    $manifestLease=$null
                    try{
                        $manifestLease=Open-SynapsePhysicalFileReadLease -ParentPath $plan.Run -ParentChain $plan.RunChain -Leaf 'continuation.json' -ExpectedFileId128 ([string]$manifestState.FileId128) -ExpectedSha256 ([string]$manifestState.Sha256) -ExpectedLength ([int64]$manifestState.Length) -Context 'post_exit_continuation_manifest_recovery'
                        $manifestText=[string]$manifestLease.ReadUtf8(1048576).Content
                        try{
                            $candidateManifest=$manifestText|ConvertFrom-Json -ErrorAction Stop
                            if([string]$candidateManifest.schema -cne 'synapse_setup_post_exit_continuation/v3' -or [string]$candidateManifest.run_id -cne [string]$plan.Payload.run_id -or [string]$candidateManifest.task_name -cne [string]$plan.TaskName -or [string]$candidateManifest.task_capability_sha256 -ine [string]$plan.Payload.capability_sha256 -or [string]$candidateManifest.task_plan_file_id_128 -ine [string]$plan.State.FileId128 -or [string]$candidateManifest.task_plan_sha256 -ine [string]$plan.State.Sha256 -or [int64]$candidateManifest.task_plan_length -ne [int64]$plan.State.Length){throw 'manifest identity does not crossbind the immutable plan'}
                            $manifest=$candidateManifest;$manifestClassification='valid'
                        }catch{$manifestClassification='stable_torn'}
                        $manifestLease.RequireExact('post_exit_continuation_manifest_recovery_after_classification')
                    }finally{if($null-ne$manifestLease){$manifestLease.Dispose()}}
                }else{$manifestClassification='stable_torn'}
            }
            $terminal=$null;$terminalState=Get-SynapsePhysicalRelativeState -ParentPath $plan.Run -ParentChain $plan.RunChain -Leaf ([string]$plan.Payload.terminal_leaf)
            if([bool]$terminalState.Exists){
                if([int64]$terminalState.Length-lt 1 -or [int64]$terminalState.Length-gt 1048576){Die "SYNAPSE_POST_EXIT_CONTINUATION_TERMINAL_BOUND_INVALID run=$($plan.Run) task=$($plan.TaskName) length=$($terminalState.Length)"}
                $terminalLease=Open-SynapsePhysicalFileReadLease -ParentPath $plan.Run -ParentChain $plan.RunChain -Leaf ([string]$plan.Payload.terminal_leaf) -ExpectedFileId128 ([string]$terminalState.FileId128) -ExpectedSha256 ([string]$terminalState.Sha256) -ExpectedLength ([int64]$terminalState.Length) -Context 'post_exit_continuation_terminal_recovery'
                try{$terminalText=[string]$terminalLease.ReadUtf8(1048576).Content;$terminal=$terminalText|ConvertFrom-Json -ErrorAction Stop}finally{$terminalLease.Dispose()}
                $terminalNames=@($terminal.PSObject.Properties.Name);$expectedTerminalNames=@('schema','state','run_id','task_name','task_capability_sha256','task_plan_file_id_128','task_plan_sha256','task_plan_length','exit_code','message','readback','terminal_at_utc')
                if($terminalNames.Count-ne$expectedTerminalNames.Count -or @($terminalNames|Where-Object{$expectedTerminalNames-cnotcontains$_}).Count-ne0 -or ((Get-SynapseCanonicalJson -Value (ConvertTo-SynapseCanonicalValue -Value $terminal))+"`n")-cne$terminalText -or [string]$terminal.schema-cne'synapse_post_exit_continuation_terminal/v1' -or [string]$terminal.state-notin@('completed','failed') -or [string]$terminal.run_id-cne[string]$plan.Payload.run_id -or [string]$terminal.task_name-cne[string]$plan.TaskName -or [string]$terminal.task_capability_sha256-ine[string]$plan.Payload.capability_sha256 -or [string]$terminal.task_plan_file_id_128-ine[string]$plan.State.FileId128 -or [string]$terminal.task_plan_sha256-ine[string]$plan.State.Sha256 -or [int64]$terminal.task_plan_length-ne[int64]$plan.State.Length){Die "SYNAPSE_POST_EXIT_CONTINUATION_TERMINAL_INVALID run=$($plan.Run) task=$($plan.TaskName)"}
                if($manifestClassification-cne'valid' -or [string]$manifest.state-cne[string]$terminal.state){
                    $recoveredProjection=if($manifestClassification-ceq'valid'){$manifest}else{[pscustomobject][ordered]@{schema='synapse_setup_post_exit_continuation/v3';state='projection_recovered_from_terminal';run_id=[string]$plan.Payload.run_id;task_name=[string]$plan.TaskName;task_capability_sha256=[string]$plan.Payload.capability_sha256;task_plan_file_id_128=([string]$plan.State.FileId128).ToUpperInvariant();task_plan_sha256=([string]$plan.State.Sha256).ToUpperInvariant();task_plan_length=[int64]$plan.State.Length;projection_preimage=$manifestTornCut}}
                    $recoveredProjection|Add-Member -NotePropertyName state -NotePropertyValue ([string]$terminal.state) -Force
                    $recoveredProjection|Add-Member -NotePropertyName exit_code -NotePropertyValue ([int]$terminal.exit_code) -Force
                    $recoveredProjection|Add-Member -NotePropertyName updated_at_utc -NotePropertyValue ([string]$terminal.terminal_at_utc) -Force
                    $recoveredProjection|Add-Member -NotePropertyName message -NotePropertyValue ([string]$terminal.message) -Force
                    $recoveredProjection|Add-Member -NotePropertyName readback -NotePropertyValue $terminal.readback -Force
                    if([string]$terminal.state-ceq'completed'){$recoveredProjection|Add-Member -NotePropertyName completed_at_utc -NotePropertyValue ([string]$terminal.terminal_at_utc) -Force;$recoveredProjection|Add-Member -NotePropertyName failure -NotePropertyValue $null -Force}else{$recoveredProjection|Add-Member -NotePropertyName failed_at_utc -NotePropertyValue ([string]$terminal.terminal_at_utc) -Force;$recoveredProjection|Add-Member -NotePropertyName failure -NotePropertyValue ([ordered]@{message=[string]$terminal.message;remediation='inspect the immutable terminal record and task observation before retrying setup'}) -Force}
                    [void](Write-SynapseAtomicManifestProjectionExact -Path (Join-Path $plan.Run 'continuation.json') -Value $recoveredProjection -Purpose 'post_exit_continuation_projection_from_terminal')
                    $manifest=$recoveredProjection;$manifestClassification='recovered_from_terminal'
                }
            }
            $scheduler=Get-SynapseScheduledTaskComRoot
            $taskLookup=Get-SynapseScheduledTaskLookupExact -Name ([string]$plan.TaskName) -Scheduler $scheduler
            if(-not [bool]$taskLookup.Exists){
                if($null-ne$terminal){Info "SYNAPSE_POST_EXIT_CONTINUATION_TASK_ALREADY_ABSENT task=$($plan.TaskName) run=$($plan.Run) terminal=$($terminal.state)"}
                continue
            }
            $registered=$taskLookup.Task
            $expectedXml='';$expectedSd=''
            $observationState=Get-SynapsePhysicalRelativeState -ParentPath $plan.Run -ParentChain $plan.RunChain -Leaf 'continuation-task-observation.json'
            if($observationState.Exists){
                if([int64]$observationState.Length -lt 1 -or [int64]$observationState.Length -gt 65536){Die "SYNAPSE_POST_EXIT_CONTINUATION_OBSERVATION_BOUND_INVALID run=$($plan.Run) task=$($plan.TaskName) length=$($observationState.Length)"}
                $observationLease=Open-SynapsePhysicalFileReadLease -ParentPath $plan.Run -ParentChain $plan.RunChain -Leaf 'continuation-task-observation.json' -ExpectedFileId128 ([string]$observationState.FileId128) -ExpectedSha256 ([string]$observationState.Sha256) -ExpectedLength ([int64]$observationState.Length) -Context 'post_exit_continuation_observation_recovery'
                try{$observationText=[string]$observationLease.ReadUtf8(65536).Content;$observation=$observationText|ConvertFrom-Json -ErrorAction Stop}finally{$observationLease.Dispose()}
                $observationNames=@($observation.PSObject.Properties.Name);$expectedObservationNames=@('schema','capability_sha256','plan_sha256','task_name','submitted_task_xml_sha256','submitted_task_semantic_sha256','xml_sha256','security_descriptor_sha256','security_descriptor_readback_flags','observed_at_utc')
                if($observationNames.Count -ne $expectedObservationNames.Count -or @($observationNames|Where-Object{$expectedObservationNames -cnotcontains $_}).Count -gt 0 -or (Get-SynapseCanonicalJson -Value (ConvertTo-SynapseCanonicalValue -Value $observation)) -cne $observationText -or [string]$observation.schema -cne 'synapse_post_exit_continuation_task_observation/v2' -or [string]$observation.capability_sha256 -ine [string]$plan.Payload.capability_sha256 -or [string]$observation.plan_sha256 -ine [string]$plan.PlanSha256 -or [string]$observation.task_name -cne [string]$plan.TaskName -or [string]$observation.submitted_task_xml_sha256 -ine [string]$plan.Payload.submitted_task_xml_sha256 -or [string]$observation.submitted_task_semantic_sha256 -ine [string]$plan.Payload.submitted_task_semantic_sha256 -or [int]$observation.security_descriptor_readback_flags -ne 7 -or [string]$observation.xml_sha256 -notmatch '^[0-9A-Fa-f]{64}$' -or [string]$observation.security_descriptor_sha256 -notmatch '^[0-9A-Fa-f]{64}$'){Die "SYNAPSE_POST_EXIT_CONTINUATION_OBSERVATION_INVALID run=$($plan.Run) task=$($plan.TaskName)"}
                $expectedXml=[string]$observation.xml_sha256;$expectedSd=[string]$observation.security_descriptor_sha256
            }
            $authority=[pscustomobject][ordered]@{Path=$plan.Path;FileId128=$plan.State.FileId128;Sha256=$plan.State.Sha256;Length=$plan.State.Length;Lease=$plan.Lease;TaskName=$plan.TaskName;Kind='continuation';Execute=$plan.Execute;Arguments=$plan.Arguments;WorkingDirectory=$plan.WorkingDirectory;Payload=$plan.Payload}
            $task=Register-SynapseTaskCreateOnly -Name $plan.TaskName -Kind continuation -Execute $plan.Execute -Arguments $plan.Arguments -WorkingDirectory $plan.WorkingDirectory -ExpectedXmlSha256 $expectedXml -ExpectedSecurityDescriptorSha256 $expectedSd -PlannedSecurityDescriptor ([string]$plan.Payload.explicit_security_descriptor) -SemanticPlanAuthority $authority
            $terminalRuntime=Wait-SynapsePostExitContinuationTaskTerminalRuntime -Plan $plan -ExpectedXmlSha256 $expectedXml -ExpectedSecurityDescriptorSha256 $expectedSd -Context 'post_exit_continuation_recovery'
            if($null-eq$terminal -and ($manifestClassification-cne'valid' -or [string]$manifest.state-notin@('completed','failed'))){
                $lastRun=[datetime]$terminalRuntime.LastRunTimeUtc;$lastResult=[int64]$terminalRuntime.LastTaskResult
                $recoveredState=if($lastResult-eq 0){'completed'}else{'failed'}
                $recoveredMessage="recovered_from_$manifestClassification task_last_result=$lastResult task_last_run_utc=$($lastRun.ToUniversalTime().ToString('o'))"
                if($manifestClassification-ceq'valid'){$recoveredManifest=$manifest}else{$recoveredManifest=[pscustomobject][ordered]@{schema='synapse_setup_post_exit_continuation/v3';state='projection_recovered';run_id=[string]$plan.Payload.run_id;task_name=[string]$plan.TaskName;task_capability_sha256=[string]$plan.Payload.capability_sha256;task_plan_file_id_128=([string]$plan.State.FileId128).ToUpperInvariant();task_plan_sha256=([string]$plan.State.Sha256).ToUpperInvariant();task_plan_length=[int64]$plan.State.Length;projection_preimage=$manifestTornCut}}
                $now=[DateTime]::UtcNow.ToString('o');$recoveredManifest|Add-Member -NotePropertyName state -NotePropertyValue $recoveredState -Force;$recoveredManifest|Add-Member -NotePropertyName exit_code -NotePropertyValue ([int]$lastResult) -Force;$recoveredManifest|Add-Member -NotePropertyName updated_at_utc -NotePropertyValue $now -Force;$recoveredManifest|Add-Member -NotePropertyName message -NotePropertyValue $recoveredMessage -Force
                if($recoveredState-ceq'completed'){$recoveredManifest|Add-Member -NotePropertyName completed_at_utc -NotePropertyValue $now -Force;$recoveredManifest|Add-Member -NotePropertyName failure -NotePropertyValue $null -Force}else{$recoveredManifest|Add-Member -NotePropertyName failed_at_utc -NotePropertyValue $now -Force;$recoveredManifest|Add-Member -NotePropertyName failure -NotePropertyValue ([ordered]@{message=$recoveredMessage;remediation='inspect the immutable task plan/observation plus Scheduler LastTaskResult before retrying setup'}) -Force}
                $terminalValue=[ordered]@{schema='synapse_post_exit_continuation_terminal/v1';state=$recoveredState;run_id=[string]$plan.Payload.run_id;task_name=[string]$plan.TaskName;task_capability_sha256=([string]$plan.Payload.capability_sha256).ToUpperInvariant();task_plan_file_id_128=([string]$plan.State.FileId128).ToUpperInvariant();task_plan_sha256=([string]$plan.State.Sha256).ToUpperInvariant();task_plan_length=[int64]$plan.State.Length;exit_code=[int]$lastResult;message=$recoveredMessage;readback=[ordered]@{source='scheduler_physical_state';task_state=[int]$terminalRuntime.TaskState;last_run_time_utc=$lastRun.ToUniversalTime().ToString('o');last_run_time_filetime_utc=[int64]$terminalRuntime.LastRunTimeFileTimeUtc;last_task_result=[int64]$terminalRuntime.LastTaskResult;next_run_time_present=[bool]$terminalRuntime.NextRunTimePresent;instance_count=[int]$terminalRuntime.InstanceCount;quiet_seconds=[int]$terminalRuntime.QuietSeconds;projection_classification=$manifestClassification};terminal_at_utc=$now}
                [void](Publish-SynapseImmutableManifestTransition -Directory $plan.Run -Leaf ([string]$plan.Payload.terminal_leaf) -Value $terminalValue -Purpose 'post_exit_continuation_terminal_recovery')
                [void](Write-SynapseAtomicManifestProjectionExact -Path (Join-Path $plan.Run 'continuation.json') -Value $recoveredManifest -Purpose 'post_exit_continuation_projection_recovery')
                $terminal=[pscustomobject]$terminalValue
            }
            if($null-eq$terminal-and[string]$manifest.state-in@('completed','failed')){
                $terminalValue=[ordered]@{schema='synapse_post_exit_continuation_terminal/v1';state=[string]$manifest.state;run_id=[string]$plan.Payload.run_id;task_name=[string]$plan.TaskName;task_capability_sha256=([string]$plan.Payload.capability_sha256).ToUpperInvariant();task_plan_file_id_128=([string]$plan.State.FileId128).ToUpperInvariant();task_plan_sha256=([string]$plan.State.Sha256).ToUpperInvariant();task_plan_length=[int64]$plan.State.Length;exit_code=[int]$manifest.exit_code;message=[string]$manifest.message;readback=$manifest.readback;terminal_at_utc=$(if($manifest.PSObject.Properties['completed_at_utc']){[string]$manifest.completed_at_utc}elseif($manifest.PSObject.Properties['failed_at_utc']){[string]$manifest.failed_at_utc}else{[DateTime]::UtcNow.ToString('o')})}
                [void](Publish-SynapseImmutableManifestTransition -Directory $plan.Run -Leaf ([string]$plan.Payload.terminal_leaf) -Value $terminalValue -Purpose 'post_exit_continuation_terminal_migration')
                $terminal=[pscustomobject]$terminalValue
            }
            if($null-eq$terminal){continue}
            [void](Remove-SynapseTransientTaskExact -Expected $task -Kind continuation -RequireNoRunningInstances)
            Info "SYNAPSE_POST_EXIT_CONTINUATION_TASK_CLEANED task=$($plan.TaskName) run=$($plan.Run) terminal=$($terminal.state) manifest_classification=$manifestClassification"
        }finally{if($null -ne $plan -and $null -ne $plan.Lease){$plan.Lease.Dispose()}}
    }
}

function Start-SynapsePostExitSetupContinuation {
    param(
        [Parameter(Mandatory=$true)][string]$Reason,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$SourceDir,
        [Parameter(Mandatory=$true)][string]$ExePath,
        [Parameter(Mandatory=$true)][string]$ChromeNativeHostExePath,
        [Parameter(Mandatory=$true)][AllowEmptyString()][string]$CargoTarget,
        [Parameter(Mandatory=$true)][string]$DbPath,
        [Parameter(Mandatory=$true)][string]$ProfilesDir,
        [Parameter(Mandatory=$true)][string]$LogDir,
        [Parameter(Mandatory=$true)][string]$TokenPath,
        [Parameter(Mandatory=$true)][string]$CodexToolSurfaceSnapshotPath,
        [Parameter(Mandatory=$true)][string]$TaskName,
        [Parameter(Mandatory=$true)][string]$MaintenanceLockPath,
        [AllowNull()][string]$CalyxConfigPath,
        [string]$ActiveIssue,
        [object]$DeadOwnerDetail
    )

    $root = Join-Path $env:LOCALAPPDATA 'synapse\setup-continuations'
    New-Item -ItemType Directory -Force -Path $root | Out-Null
    $root = Get-SynapseNormalizedDirectoryPath -Path $root
    $rootChain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $root)
    $stamp = (Get-Date).ToUniversalTime().ToString('yyyyMMddTHHmmssfffZ')
    $runNonce = [Guid]::NewGuid().ToString('N')
    $runId = "post-exit-$PID-$stamp-$($runNonce.Substring(0,16))"
    $runCreated = [SynapseSetup.AtomicFileV2]::CreatePhysicalDirectoryRelative($root,(Get-SynapsePhysicalChainPaths -Chain $rootChain),(Get-SynapsePhysicalChainFileIds -Chain $rootChain),$runId)
    $runDir = Get-SynapseNormalizedDirectoryPath -Path ([string]$runCreated.Path)
    $runChain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $runDir)
    $manifestPath = Join-Path $runDir 'continuation.json'
    $stdoutPath = Join-Path $runDir 'stdout.log'
    $stderrPath = Join-Path $runDir 'stderr.log'
    $wrapperPath = Join-Path $runDir 'launch-continuation.ps1'
    $launcherPath = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
    if (-not (Test-Path -LiteralPath $launcherPath)) {
        Die "SYNAPSE_POST_EXIT_CONTINUATION_POWERSHELL_MISSING path=$launcherPath remediation=repair Windows PowerShell before retrying setup"
    }

    $args = @(
        '-NoProfile',
        '-ExecutionPolicy',
        'Bypass',
        '-File',
        $PSCommandPath,
        '-SourceDir',
        $SourceDir,
        '-Bind',
        $Bind,
        '-ExePath',
        $ExePath,
        '-ChromeNativeHostExePath',
        $ChromeNativeHostExePath,
        '-DbPath',
        $DbPath,
        '-ProfilesDir',
        $ProfilesDir,
        '-LogDir',
        $LogDir,
        '-TokenPath',
        $TokenPath,
        '-CodexToolSurfaceSnapshotPath',
        $CodexToolSurfaceSnapshotPath,
        '-TaskName',
        $TaskName,
        '-MaintenanceLockPath',
        $MaintenanceLockPath,
        '-BuildTimeoutMinutes',
        ([string]$BuildTimeoutMinutes),
        '-PostExitParentPid',
        ([string]$PID),
        '-PostExitContinuationReason',
        'dead_owner_bind_after_install',
        '-PostExitManifestPath',
        $manifestPath,
        '-ForceRestart'
    )
    if (-not [string]::IsNullOrWhiteSpace($ActiveIssue)) {
        $args += @('-ActiveIssue', $ActiveIssue)
    }
    if (-not [string]::IsNullOrWhiteSpace($CalyxConfigPath)) {
        $args += @('-CalyxConfigPath', $CalyxConfigPath)
    }
    # Relay the resolved build tree only when one was actually resolved. The
    # continuation rebuilds from this exact source checkout after the
    # parent transaction has rolled back and exited. Relaying an empty value
    # would bind a blank -CargoTarget, while a resolved alternate must carry its
    # authorization with it (#1857).
    if (-not [string]::IsNullOrWhiteSpace($CargoTarget)) {
        $args += @('-CargoTarget', $CargoTarget)
        if ($AllowAlternateBuildTarget) {
            $args += '-AllowAlternateBuildTarget'
        }
    }
    if ($SkipClientWiring) {
        $args += '-SkipClientWiring'
    }
    $taskArgument = "-NoProfile -ExecutionPolicy Bypass -File $(Quote-WindowsCommandArgument -Value $wrapperPath)"
    $argLiteralLines = @($args | ForEach-Object { "    $(Quote-PowerShellSingleQuotedString -Value $_)" })
    $wrapperLines = @(
        # Task Scheduler can inherit a pwsh-first PSModulePath even though this
        # wrapper runs Windows PowerShell 5.1. Pin the trusted OS module root as
        # the first executable statement so neither the wrapper nor the full
        # setup child can auto-load Core-only Utility/CimCmdlets/NetTCPIP bytes.
        '$env:PSModulePath = [IO.Path]::Combine($PSHOME, ''Modules'')',
        '$ErrorActionPreference = ''Stop''',
        "`$launcherPath = $(Quote-PowerShellSingleQuotedString -Value $launcherPath)",
        "`$sourceDir = $(Quote-PowerShellSingleQuotedString -Value $SourceDir)",
        "`$stdoutPath = $(Quote-PowerShellSingleQuotedString -Value $stdoutPath)",
        "`$stderrPath = $(Quote-PowerShellSingleQuotedString -Value $stderrPath)",
        '$argList = @('
    )
    $wrapperLines += $argLiteralLines
    $wrapperLines += @(
        ')',
        '$exitCode = 1',
        'try {',
        '    Set-Location -LiteralPath $sourceDir',
        '    & $launcherPath @argList 1> $stdoutPath 2> $stderrPath 3>&1 4>&1 5>&1 6>&1',
        '    if ($null -ne $global:LASTEXITCODE) {',
        '        $exitCode = [int]$global:LASTEXITCODE',
        '    } else {',
        '        $exitCode = 0',
        '    }',
        '} catch {',
        '    try { ($_ | Out-String) | Add-Content -LiteralPath $stderrPath -Encoding UTF8 } catch {}',
        '    $exitCode = 1',
        '}',
        'exit $exitCode'
    )
    Ensure-SynapseAtomicFileType
    $wrapperText=($wrapperLines -join "`n")+"`n"
    $wrapperWrite=[SynapseSetup.AtomicFileV2]::CreatePhysicalUtf8TextFileRelative($runDir,(Get-SynapsePhysicalChainPaths -Chain $runChain),(Get-SynapsePhysicalChainFileIds -Chain $runChain),(Split-Path -Leaf $wrapperPath),$wrapperText)
    # Keep the exact immutable wrapper object non-write/non-delete-shareable
    # across TASK_CREATE and its RegistrationTrigger launch. The task action is
    # therefore never authorized by a path-only check.
    $wrapperLease=Open-SynapsePhysicalFileReadLease -ParentPath $runDir -ParentChain $runChain -Leaf (Split-Path -Leaf $wrapperPath) -ExpectedFileId128 ([string]$wrapperWrite.FileId128) -ExpectedSha256 ([string]$wrapperWrite.Sha256) -ExpectedLength ([int64]$wrapperWrite.Length) -Context 'post_exit_continuation_wrapper_create'
    $userSid=Get-SynapseCurrentUserSid
    $plannedSddl=Get-SynapseAuthorityTaskExplicitSecurityDescriptor -UserSid $userSid
    $nameCore=[ordered]@{
        schema='synapse_post_exit_continuation_name_capability/v1';run_nonce=$runNonce;run_id=$runId;invocation_id=$script:SynapseSetupInvocationId
        run_root=$runDir;run_root_file_id_128=([string]$runChain[-1].file_id_128).ToUpperInvariant();parent_pid=$PID
        execute=[System.IO.Path]::GetFullPath($launcherPath);arguments=$taskArgument;working_directory=[System.IO.Path]::GetFullPath($SourceDir)
        wrapper_path=[System.IO.Path]::GetFullPath($wrapperPath);wrapper_file_id_128=([string]$wrapperWrite.FileId128).ToUpperInvariant();wrapper_sha256=([string]$wrapperWrite.Sha256).ToUpperInvariant();wrapper_length=[int64]$wrapperWrite.Length
        explicit_security_descriptor=$plannedSddl
    }
    $nameCapability=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $nameCore)).ToUpperInvariant()
    $continuationTaskName='SynapseMcpContinuation-'+$nameCapability.Substring(0,40)
    $submittedDefinition=New-SynapseTaskCreateDefinitionPlan -Name $continuationTaskName -Kind continuation -Execute $launcherPath -Arguments $taskArgument -WorkingDirectory $SourceDir -UserSid $userSid
    $capabilityCore=[ordered]@{schema='synapse_post_exit_continuation_capability/v3';name_capability_sha256=$nameCapability;task_name=$continuationTaskName;run_nonce=$nameCore.run_nonce;run_id=$nameCore.run_id;invocation_id=$nameCore.invocation_id;run_root=$nameCore.run_root;run_root_file_id_128=$nameCore.run_root_file_id_128;parent_pid=$nameCore.parent_pid;execute=$nameCore.execute;arguments=$nameCore.arguments;working_directory=$nameCore.working_directory;wrapper_path=$nameCore.wrapper_path;wrapper_file_id_128=$nameCore.wrapper_file_id_128;wrapper_sha256=$nameCore.wrapper_sha256;wrapper_length=$nameCore.wrapper_length;submitted_task_xml_sha256=([string]$submittedDefinition.SubmittedXmlSha256).ToUpperInvariant();submitted_task_semantic_sha256=([string]$submittedDefinition.SemanticSha256).ToUpperInvariant();explicit_security_descriptor=$nameCore.explicit_security_descriptor}
    $continuationCapability=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $capabilityCore)).ToUpperInvariant()
    $planCore=[ordered]@{
        schema='synapse_post_exit_continuation_task_plan/v4';state='prepared_before_task_create';name_capability_sha256=$nameCapability;capability_sha256=$continuationCapability
        invocation_id=$script:SynapseSetupInvocationId;run_nonce=$runNonce;run_id=$runId;run_root=$runDir;run_root_file_id_128=([string]$runChain[-1].file_id_128).ToUpperInvariant();parent_pid=$PID
        task_name=$continuationTaskName;kind='continuation';execute=[System.IO.Path]::GetFullPath($launcherPath);arguments=$taskArgument;working_directory=[System.IO.Path]::GetFullPath($SourceDir)
        user_sid=$userSid;task_create_flag=2;task_ignore_registration_triggers_flag_absent=$true;trigger_types=@('registration');task_instance_semantics='registration_trigger_single_oneshot_ignore_new';maximum_concurrent_instances=1;cleanup_requires_zero_running_instances=$true;submitted_task_xml_sha256=([string]$submittedDefinition.SubmittedXmlSha256).ToUpperInvariant();submitted_task_semantic_sha256=([string]$submittedDefinition.SemanticSha256).ToUpperInvariant()
        explicit_security_descriptor=$plannedSddl;security_descriptor_readback_flags=7;manifest_path=[System.IO.Path]::GetFullPath($manifestPath);terminal_leaf='continuation-terminal.json';observation_leaf='continuation-task-observation.json'
        wrapper_path=[System.IO.Path]::GetFullPath($wrapperPath);wrapper_file_id_128=([string]$wrapperWrite.FileId128).ToUpperInvariant();wrapper_sha256=([string]$wrapperWrite.Sha256).ToUpperInvariant();wrapper_length=[int64]$wrapperWrite.Length
        created_at_utc=(Get-Date).ToUniversalTime().ToString('o')
    }
    $planCore.plan_sha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $planCore)).ToUpperInvariant()
    $planText=Get-SynapseCanonicalJson -Value $planCore
    $planLeaf='continuation-task-plan.json'
    $planPath=Join-Path $runDir $planLeaf
    $planWrite=[SynapseSetup.AtomicFileV2]::CreatePhysicalUtf8TextFileRelative($runDir,(Get-SynapsePhysicalChainPaths -Chain $runChain),(Get-SynapsePhysicalChainFileIds -Chain $runChain),$planLeaf,$planText)
    $planLease=Open-SynapsePhysicalFileReadLease -ParentPath $runDir -ParentChain $runChain -Leaf $planLeaf -ExpectedFileId128 ([string]$planWrite.FileId128) -ExpectedSha256 ([string]$planWrite.Sha256) -ExpectedLength ([int64]$planWrite.Length) -Context 'post_exit_continuation_task_plan'
    $planAuthority=[pscustomobject][ordered]@{Path=$planPath;FileId128=[string]$planWrite.FileId128;Sha256=[string]$planWrite.Sha256;Length=[int64]$planWrite.Length;Lease=$planLease;TaskName=$continuationTaskName;Kind='continuation';Execute=[string]$planCore.execute;Arguments=[string]$planCore.arguments;WorkingDirectory=[string]$planCore.working_directory;Payload=[pscustomobject]$planCore}
    $manifest = [ordered]@{
        schema='synapse_setup_post_exit_continuation/v3';state='planned_before_task_create';run_id=$runId;reason=$Reason;bind=$Bind;parent_pid=$PID
        launch_mode='task_create_registration_trigger_only';task_name=$continuationTaskName;task_argument=$taskArgument;launcher_path=$launcherPath;wrapper_path=$wrapperPath
        task_capability_sha256=$continuationCapability;task_plan_path=$planPath;task_plan_file_id_128=([string]$planWrite.FileId128).ToUpperInvariant();task_plan_sha256=([string]$planWrite.Sha256).ToUpperInvariant();task_plan_length=[int64]$planWrite.Length
        task_observation=$null;setup_script_path=$PSCommandPath;source_dir=$SourceDir;stdout_log=$stdoutPath;stderr_log=$stderrPath;command_args=$args
        active_issue=$ActiveIssue;dead_owner_detail=$DeadOwnerDetail;created_at_utc=(Get-Date).ToUniversalTime().ToString('o')
        remediation='continuation waits for parent rollback and process exit, reacquires setup maintenance lock, then rebuilds and deploys the exact source checkout as a new transaction'
    }
    [void]([SynapseSetup.AtomicFileV2]::CreatePhysicalUtf8TextFileRelative($runDir,(Get-SynapsePhysicalChainPaths -Chain $runChain),(Get-SynapsePhysicalChainFileIds -Chain $runChain),(Split-Path -Leaf $manifestPath),(Get-SynapseCanonicalJson -Value $manifest)))

    $taskReadback=$null
    try {
        $wrapperLease.RequireExact('post_exit_continuation_wrapper_pre_task_create')
        $taskReadback=Register-SynapseTaskCreateOnly -Name $continuationTaskName -Kind continuation -Execute $launcherPath -Arguments $taskArgument -WorkingDirectory $SourceDir -PlannedSecurityDescriptor $plannedSddl -SemanticPlanAuthority $planAuthority
        $wrapperLease.RequireExact('post_exit_continuation_wrapper_post_task_create')
        $observation=[ordered]@{schema='synapse_post_exit_continuation_task_observation/v2';capability_sha256=$continuationCapability;plan_sha256=[string]$planCore.plan_sha256;task_name=$continuationTaskName;submitted_task_xml_sha256=[string]$planCore.submitted_task_xml_sha256;submitted_task_semantic_sha256=[string]$planCore.submitted_task_semantic_sha256;xml_sha256=[string]$taskReadback.XmlSha256;security_descriptor_sha256=[string]$taskReadback.SecurityDescriptorSha256;security_descriptor_readback_flags=7;observed_at_utc=(Get-Date).ToUniversalTime().ToString('o')}
        $observationWrite=[SynapseSetup.AtomicFileV2]::CreatePhysicalUtf8TextFileRelative($runDir,(Get-SynapsePhysicalChainPaths -Chain $runChain),(Get-SynapsePhysicalChainFileIds -Chain $runChain),'continuation-task-observation.json',(Get-SynapseCanonicalJson -Value $observation))
        Start-Sleep -Seconds 1
        $child = Get-CimInstance Win32_Process -Filter "Name = 'powershell.exe'" -ErrorAction SilentlyContinue |
            Where-Object { $_.CommandLine -and ($_.CommandLine -like "*$wrapperPath*" -or $_.CommandLine -like "*$runId*") } |
            Sort-Object CreationDate -Descending |
            Select-Object -First 1
        $manifest.state='started';$manifest.child_pid=if($child){[int]$child.ProcessId}else{0};$manifest.task_state=[string]$taskReadback.State
        $manifest.started_at_utc=(Get-Date).ToUniversalTime().ToString('o')
        $manifest.task_observation=[ordered]@{path=(Join-Path $runDir 'continuation-task-observation.json');file_id_128=([string]$observationWrite.FileId128).ToUpperInvariant();sha256=([string]$observationWrite.Sha256).ToUpperInvariant();length=[int64]$observationWrite.Length;xml_sha256=[string]$taskReadback.XmlSha256;security_descriptor_sha256=[string]$taskReadback.SecurityDescriptorSha256}
        [void](Write-SynapseAtomicUtf8TextFile -Path $manifestPath -Content (Get-SynapseCanonicalJson -Value $manifest) -Purpose 'post_exit_continuation_started_manifest')
    } catch {
        Die "SYNAPSE_POST_EXIT_CONTINUATION_START_FAILED run_id=$runId task=$continuationTaskName manifest=$manifestPath plan=$planPath error=$($_.Exception.Message) remediation=preserve the immutable plan and any exact create-only task; ordinary setup recovery validates its XML/SD/instances before cleanup"
    } finally {
        if($null -ne $planLease){$planLease.Dispose()}
        if($null -ne $wrapperLease){$wrapperLease.Dispose()}
    }

    Info "SYNAPSE_POST_EXIT_CONTINUATION_STARTED run_id=$runId launch_mode=task_create_registration_trigger_only task_name=$continuationTaskName capability_sha256=$continuationCapability submitted_task_xml_sha256=$($planCore.submitted_task_xml_sha256) observed_xml_sha256=$($taskReadback.XmlSha256) observed_sd_sha256=$($taskReadback.SecurityDescriptorSha256) parent_pid=$PID child_pid=$($manifest.child_pid) manifest=$manifestPath plan=$planPath wrapper=$wrapperPath stdout=$stdoutPath stderr=$stderrPath"
    return [pscustomobject]@{
        RunId = $runId
        RunDir = $runDir
        ManifestPath = $manifestPath
        StdoutPath = $stdoutPath
        StderrPath = $stderrPath
        ChildPid = $manifest.child_pid
        LaunchMode = 'task_create_registration_trigger_only'
        TaskName = $continuationTaskName
        WrapperPath = $wrapperPath
    }
}

function Write-SynapseCodexRestartHandoff {
    param(
        [Parameter(Mandatory=$true)][string]$Phase,
        [Parameter(Mandatory=$true)][string]$Reason,
        [AllowNull()]$CodexAncestor,
        [AllowNull()]$Surface,
        [AllowNull()]$Diff,
        [AllowNull()][string]$ProcessHashAtStart,
        [AllowNull()][string]$ProcessSnapshotAtStart,
        [AllowNull()][string]$CurrentSnapshotPath,
        [AllowNull()][string]$SourceDir,
        [AllowNull()][string]$Bind,
        [AllowNull()][string]$TokenPath,
        [AllowNull()][string]$ActiveIssue
    )

    $root = Join-Path $env:LOCALAPPDATA 'synapse\codex-restart-handoffs'
    $stamp = [DateTime]::UtcNow.ToString('yyyyMMddTHHmmssfffZ')
    $codexPid = if ($CodexAncestor) { [int]$CodexAncestor.ProcessId } else { 0 }
    $baseName = "codex-restart-handoff-$codexPid-$stamp"
    $jsonPath = Join-Path $root "$baseName.json"
    $mdPath = Join-Path $root "$baseName.md"
    $recoveryNotesPath = Get-SynapseRecoveryNotesPath -SourceDir $SourceDir
    $startSnapshotStatus = if ([string]::IsNullOrWhiteSpace($ProcessSnapshotAtStart)) {
        'missing_env'
    } elseif (Test-Path -LiteralPath $ProcessSnapshotAtStart) {
        'readable'
    } else {
        'missing_file'
    }

    $daemon = [ordered]@{
        bind = $Bind
        pid = if ($Surface -and $Surface.PSObject.Properties['daemon_pid']) { $Surface.daemon_pid } else { $null }
        pid_role = if ($Phase -eq 'pre_handoff_candidate') { 'preflight_candidate' } else { 'installed_configured_daemon' }
        pid_authoritative_for_configured_bind = ($Phase -ne 'pre_handoff_candidate')
        pid_expectation = if ($Phase -eq 'pre_handoff_candidate') {
            'This PID belongs to the isolated candidate daemon used before live handoff and is expected to be stopped before the configured daemon is installed.'
        } else {
            'This PID is the installed daemon observed after live handoff and should own the configured bind unless a later setup run superseded it.'
        }
        tool_count = if ($Surface -and $Surface.PSObject.Properties['tool_count']) { $Surface.tool_count } else { $null }
        tool_surface_sha256 = if ($Surface -and $Surface.PSObject.Properties['tool_surface_sha256']) { [string]$Surface.tool_surface_sha256 } else { $null }
        snapshot_path = $CurrentSnapshotPath
    }
    $codexProcess = if ($CodexAncestor) {
        [ordered]@{
            pid = [int]$CodexAncestor.ProcessId
            name = [string]$CodexAncestor.Name
            command_line = [string]$CodexAncestor.CommandLine
        }
    } else {
        [ordered]@{
            pid = $null
            name = $null
            command_line = $null
        }
    }
    $diffObject = ConvertTo-SynapseHandoffDiffObject -Diff $Diff
    $gitReadback = Get-SynapseHandoffGitReadback -SourceDir $SourceDir
    $activeIssueRef = Get-SynapseNormalizedIssueRef -Issue $ActiveIssue
    $activeIssueNumber = Get-SynapseIssueNumberFromRef -IssueRef $activeIssueRef
    $activeIssueRead = if ([string]::IsNullOrWhiteSpace($activeIssueNumber)) {
        $null
    } else {
        "gh issue view $activeIssueNumber --repo ChrisRoyse/Synapse --comments"
    }
    $resumeInstruction = if ([string]::IsNullOrWhiteSpace($activeIssueRef)) {
        'Resume the active GitHub issue from the caller/session context; if unknown, read the open issue queue and choose the issue that produced this setup handoff. Perform manual real-MCP FSV; do not use direct helper calls as acceptance.'
    } else {
        "Resume $activeIssueRef and perform manual real-MCP FSV; do not use direct helper calls as acceptance."
    }
    $restartCommandHint = if ([string]::IsNullOrWhiteSpace($activeIssueRef)) {
        "Close this Codex session completely, start a new Codex session through the patched Codex launcher, verify the active codex.exe PID is not $codexPid, then resume the active issue from the caller/session context."
    } else {
        "Close this Codex session completely, start a new Codex session through the patched Codex launcher, verify the active codex.exe PID is not $codexPid, then resume $activeIssueRef."
    }
    $postRestartRequiredReads = @(
        'C:\Users\hotra\Downloads\AICodingAgentSuperPrompt.md',
        'C:\code\Synapse\docs\compressionprompt.md',
        'C:\code\Synapse\AGENTS.md',
        $recoveryNotesPath
    ) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) }
    $githubReads = @(
        'gh issue view 351 --repo ChrisRoyse/Synapse --comments',
        $activeIssueRead,
        'gh issue list --repo ChrisRoyse/Synapse --state open --limit 100'
    ) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) }

    $record = [ordered]@{
        schema_version = 2
        artifact_kind = 'synapse_codex_restart_handoff'
        created_at_utc = [DateTime]::UtcNow.ToString('o')
        reason_code = 'SYNAPSE_CODEX_CURRENT_PROCESS_SCHEMA_STALE'
        reason = $Reason
        phase = $Phase
        required_restart = $true
        no_in_process_hot_refresh = $true
        explanation = 'The already-running Codex process has process-local MCP callable metadata that does not match the current daemon tools/list surface. Restart through the patched Codex launcher is the same-agent recovery boundary.'
        codex_process = $codexProcess
        daemon = $daemon
        current_process_start_surface = [ordered]@{
            env_hash_present = (-not [string]::IsNullOrWhiteSpace($ProcessHashAtStart))
            env_hash = $ProcessHashAtStart
            env_snapshot_path = $ProcessSnapshotAtStart
            snapshot_status = $startSnapshotStatus
        }
        diff = $diffObject
        post_restart_required_reads = $postRestartRequiredReads
        active_issue = [ordered]@{
            issue_ref = $activeIssueRef
            issue_number = $activeIssueNumber
            source = 'ActiveIssue parameter or SYNAPSE_ACTIVE_ISSUE environment variable'
            status = if ([string]::IsNullOrWhiteSpace($activeIssueRef)) { 'unknown' } else { 'provided' }
        }
        stale_schema_context_issue = [ordered]@{
            issue_ref = '#1398'
            role = 'background context for the stale-schema bug class; not the resume target'
        }
        github_reads = $githubReads
        post_restart_verification = @(
            'Run git status --short --branch and confirm the working tree matches the handoff/recovery notes.',
            "Read the active Codex process parent chain and confirm the active codex.exe PID is not stale PID $codexPid from this handoff.",
            'Run deferred tool discovery for Synapse first, then call real mcp__synapse.health and verify daemon pid/tool_surface_sha256 matches or intentionally supersedes this handoff.',
            'If Synapse tool discovery, approval, or metadata is still stale, rerun scripts\synapse-setup.ps1 and keep the issue open.',
            $resumeInstruction
        )
        restart_command_hint = $restartCommandHint
        repo_readback = $gitReadback
        token_path = $TokenPath
        recovery_notes_path = $recoveryNotesPath
    }

    try {
        New-Item -ItemType Directory -Force -Path $root | Out-Null
        Write-SynapseUtf8NoBomFile -Path $jsonPath -Text (($record | ConvertTo-Json -Depth 40) + "`n")
        $md = @(
            '# Synapse Codex Restart Handoff',
            '',
            "- Reason: SYNAPSE_CODEX_CURRENT_PROCESS_SCHEMA_STALE ($Reason)",
            "- Phase: $Phase",
            "- Created UTC: $($record.created_at_utc)",
            "- Codex PID: $codexPid",
            "- Daemon: pid=$($daemon.pid) bind=$($daemon.bind) tool_count=$($daemon.tool_count) tool_surface_sha256=$($daemon.tool_surface_sha256)",
            "- Active issue: $(if ([string]::IsNullOrWhiteSpace($activeIssueRef)) { 'unknown; recover from caller/session context or open issue queue' } else { $activeIssueRef })",
            "- Stale-schema context issue: #1398 (background only; not the resume target)",
            "- Current process start snapshot: status=$startSnapshotStatus hash=$ProcessHashAtStart path=$ProcessSnapshotAtStart",
            "- Current daemon snapshot: $CurrentSnapshotPath",
            "- Diff: $($diffObject.summary)",
            '',
            '## Required Restart',
            "The running Codex process cannot hot-add changed MCP tools or mutate cached tool schemas. Close stale Codex PID $codexPid completely, restart Codex through the patched launcher, and prove the active codex.exe PID changed before continuing. Typing continue into the same PID is not a restart.",
            '',
            '## Read After Restart'
        )
        foreach ($item in $postRestartRequiredReads) {
            $md += "- $item"
        }
        $md += @(
            '',
            '## GitHub Reads'
        )
        foreach ($item in $record.github_reads) {
            $md += "- $item"
        }
        $md += @(
            '',
            '## Verification'
        )
        foreach ($item in $record.post_restart_verification) {
            $md += "- $item"
        }
        $md += @(
            '',
            "JSON artifact: $jsonPath",
            ''
        )
        Write-SynapseUtf8NoBomFile -Path $mdPath -Text (($md -join "`n") + "`n")

        if (-not [string]::IsNullOrWhiteSpace($recoveryNotesPath)) {
            $notes = @(
                '# Synapse Recovery Notes',
                '',
                '## Latest Codex Restart Handoff',
                '',
                "- Reason: SYNAPSE_CODEX_CURRENT_PROCESS_SCHEMA_STALE ($Reason)",
                "- Phase: $Phase",
                "- Created UTC: $($record.created_at_utc)",
                "- JSON: $jsonPath",
                "- Markdown: $mdPath",
                "- Stale Codex PID: $codexPid",
                "- Daemon bind: $Bind",
                "- Daemon tool surface: $($daemon.tool_surface_sha256)",
                "- Active issue: $(if ([string]::IsNullOrWhiteSpace($activeIssueRef)) { 'unknown; recover from caller/session context or open issue queue' } else { $activeIssueRef })",
                "- Stale-schema context issue: #1398 (background only; not the resume target)",
                '',
                "After restart, re-read AGENTS.md, #351, $(if ([string]::IsNullOrWhiteSpace($activeIssueRef)) { 'the active issue from the caller/session context' } else { $activeIssueRef }), git status, and this file before resuming. #1398 is stale-schema background context only. Run deferred Synapse tool discovery before calling real mcp__synapse tools for FSV; direct helper calls are diagnostics only.",
                ''
            )
            Write-SynapseUtf8NoBomFile -Path $recoveryNotesPath -Text (($notes -join "`n") + "`n")
        }
    } catch {
        Die "SYNAPSE_CODEX_RESTART_HANDOFF_WRITE_FAILED phase=$Phase reason=$Reason path=$jsonPath error=$($_.Exception.Message) remediation=repair permissions on %LOCALAPPDATA%\synapse\codex-restart-handoffs and the repo STATE directory, then rerun setup"
    }

    Info "SYNAPSE_CODEX_CURRENT_PROCESS_SCHEMA_STALE handoff_written phase=$Phase reason=$Reason json=$jsonPath markdown=$mdPath recovery_notes=$recoveryNotesPath"
    return [pscustomobject]@{
        JsonPath = $jsonPath
        MarkdownPath = $mdPath
        RecoveryNotesPath = $recoveryNotesPath
    }
}

function Assert-CodexCandidateHandoffPreservesCurrentProcess {
    param(
        [AllowNull()]$CodexAncestor,
        [Parameter(Mandatory=$true)]$CandidateSurface,
        [AllowNull()][string]$ProcessHashAtStart,
        [AllowNull()][string]$ProcessSnapshotAtStart,
        [AllowNull()][string]$SourceDir,
        [AllowNull()][string]$Bind,
        [AllowNull()][string]$TokenPath,
        [AllowNull()][string]$ActiveIssue
    )

    if ($null -eq $CodexAncestor) {
        return
    }

    $candidateHash = [string]$CandidateSurface.tool_surface_sha256
    if ([string]::IsNullOrWhiteSpace($candidateHash)) {
        Die "SYNAPSE_CODEX_CANDIDATE_TOOL_SURFACE_HASH_MISSING codex_pid=$($CodexAncestor.ProcessId) remediation=candidate tools/list preflight did not produce a usable tool_surface_sha256; refusing to touch the live daemon"
    }

    if ($ProcessHashAtStart -eq $candidateHash) {
        Info "Codex current-process tool surface will survive candidate handoff codex_pid=$($CodexAncestor.ProcessId) tool_surface_sha256=$candidateHash tool_count=$($CandidateSurface.tool_count)"
        return
    }

    $startSurface = Read-SynapseCodexToolSurfaceSnapshotOrNull -Path $ProcessSnapshotAtStart
    $diff = Get-SynapseToolSurfaceDiff -StartSurface $startSurface -CurrentSurface $CandidateSurface
    $diffSummary = $diff.Summary

    if ([string]::IsNullOrWhiteSpace($ProcessHashAtStart)) {
        $handoff = Write-SynapseCodexRestartHandoff `
            -Phase 'pre_handoff_candidate' `
            -Reason 'start_snapshot_missing_before_candidate_handoff' `
            -CodexAncestor $CodexAncestor `
            -Surface $CandidateSurface `
            -Diff $diff `
            -ProcessHashAtStart $ProcessHashAtStart `
            -ProcessSnapshotAtStart $ProcessSnapshotAtStart `
            -CurrentSnapshotPath $null `
            -SourceDir $SourceDir `
            -Bind $Bind `
            -TokenPath $TokenPath `
            -ActiveIssue $ActiveIssue
        Info ("WARN: SYNAPSE_CODEX_CURRENT_PROCESS_SCHEMA_STALE_PRE_HANDOFF codex_pid={0} tool_surface_at_process_start=missing candidate_tool_surface_sha256={1} candidate_tool_count={2} candidate_pid={3} start_snapshot={4} handoff={5} {6} remediation=setup will continue only to install the verified daemon; final setup must fail closed if this Codex process remains stale." -f `
            $CodexAncestor.ProcessId,
            $candidateHash,
            $CandidateSurface.tool_count,
            $CandidateSurface.daemon_pid,
            $ProcessSnapshotAtStart,
            $handoff.JsonPath,
            $diffSummary)
        return
    }

    if (-not $diff.HasRestartRequired) {
        Info ("Codex current-process tool surface hash will change after candidate handoff but callable schema is unchanged; continuing codex_pid={0} start_tool_surface_sha256={1} candidate_tool_surface_sha256={2} candidate_tool_count={3} candidate_pid={4} start_snapshot={5} {6}" -f `
            $CodexAncestor.ProcessId,
            $ProcessHashAtStart,
            $candidateHash,
            $CandidateSurface.tool_count,
            $CandidateSurface.daemon_pid,
            $ProcessSnapshotAtStart,
            $diffSummary)
        return
    }

    $handoff = Write-SynapseCodexRestartHandoff `
        -Phase 'pre_handoff_candidate' `
        -Reason 'start_snapshot_hash_mismatch_before_candidate_handoff' `
        -CodexAncestor $CodexAncestor `
        -Surface $CandidateSurface `
        -Diff $diff `
        -ProcessHashAtStart $ProcessHashAtStart `
        -ProcessSnapshotAtStart $ProcessSnapshotAtStart `
        -CurrentSnapshotPath $null `
        -SourceDir $SourceDir `
        -Bind $Bind `
        -TokenPath $TokenPath `
        -ActiveIssue $ActiveIssue
    Info ("WARN: SYNAPSE_CODEX_CURRENT_PROCESS_SCHEMA_STALE_PRE_HANDOFF codex_pid={0} start_tool_surface_sha256={1} candidate_tool_surface_sha256={2} candidate_tool_count={3} candidate_pid={4} start_snapshot={5} handoff={6} {7} remediation=setup will continue only to install the verified daemon; final setup must fail closed if this Codex process remains stale." -f `
        $CodexAncestor.ProcessId,
        $ProcessHashAtStart,
        $candidateHash,
        $CandidateSurface.tool_count,
        $CandidateSurface.daemon_pid,
        $ProcessSnapshotAtStart,
        $handoff.JsonPath,
        $diffSummary)
    return
}

function Assert-CodexCurrentProcessToolSurfaceFresh {
    param(
        [AllowNull()]$CodexAncestor,
        [Parameter(Mandatory=$true)]$CurrentSurface,
        [AllowNull()][string]$ProcessHashAtStart,
        [AllowNull()][string]$ProcessSnapshotAtStart,
        [Parameter(Mandatory=$true)][string]$SnapshotPath,
        [AllowNull()][string]$SourceDir,
        [AllowNull()][string]$Bind,
        [AllowNull()][string]$TokenPath,
        [AllowNull()][string]$ActiveIssue,
        [switch]$NonFatal
    )

    if ($null -eq $CodexAncestor) {
        return
    }

    $currentHash = [string]$CurrentSurface.tool_surface_sha256
    $startSurface = Read-SynapseCodexToolSurfaceSnapshotOrNull -Path $ProcessSnapshotAtStart
    $diff = Get-SynapseToolSurfaceDiff -StartSurface $startSurface -CurrentSurface $CurrentSurface
    $diffSummary = $diff.Summary
    if ([string]::IsNullOrWhiteSpace($ProcessHashAtStart)) {
        $handoff = Write-SynapseCodexRestartHandoff `
            -Phase 'post_handoff_current_daemon' `
            -Reason 'start_snapshot_missing_after_daemon_handoff' `
            -CodexAncestor $CodexAncestor `
            -Surface $CurrentSurface `
            -Diff $diff `
            -ProcessHashAtStart $ProcessHashAtStart `
            -ProcessSnapshotAtStart $ProcessSnapshotAtStart `
            -CurrentSnapshotPath $SnapshotPath `
            -SourceDir $SourceDir `
            -Bind $Bind `
            -TokenPath $TokenPath `
            -ActiveIssue $ActiveIssue
        $message = ("SYNAPSE_CODEX_CURRENT_PROCESS_SCHEMA_STALE codex_pid={0} tool_surface_at_process_start=missing current_tool_surface_sha256={1} tool_count={2} daemon_pid={3} snapshot={4} start_snapshot={5} handoff={6} {7} remediation=restart Codex through the patched launcher, read the handoff plus STATE\\RECOVERY_NOTES.md, then resume the active issue named in the handoff and verify real mcp__synapse metadata." -f `
            $CodexAncestor.ProcessId,
            $currentHash,
            $CurrentSurface.tool_count,
            $CurrentSurface.daemon_pid,
            $SnapshotPath,
            $ProcessSnapshotAtStart,
            $handoff.JsonPath,
            $diffSummary)
        if ($NonFatal) {
            Info "WARN: $message"
            return
        }
        Die $message
    }

    if ($ProcessHashAtStart -ne $currentHash) {
        if (-not $diff.HasRestartRequired) {
            Info ("Codex current-process tool surface hash changed but callable schema is unchanged; continuing without restart handoff codex_pid={0} start_tool_surface_sha256={1} current_tool_surface_sha256={2} tool_count={3} daemon_pid={4} snapshot={5} start_snapshot={6} {7}" -f `
                $CodexAncestor.ProcessId,
                $ProcessHashAtStart,
                $currentHash,
                $CurrentSurface.tool_count,
                $CurrentSurface.daemon_pid,
                $SnapshotPath,
                $ProcessSnapshotAtStart,
                $diffSummary)
            return
        }
        $handoff = Write-SynapseCodexRestartHandoff `
            -Phase 'post_handoff_current_daemon' `
            -Reason 'start_snapshot_hash_mismatch_after_daemon_handoff' `
            -CodexAncestor $CodexAncestor `
            -Surface $CurrentSurface `
            -Diff $diff `
            -ProcessHashAtStart $ProcessHashAtStart `
            -ProcessSnapshotAtStart $ProcessSnapshotAtStart `
            -CurrentSnapshotPath $SnapshotPath `
            -SourceDir $SourceDir `
            -Bind $Bind `
            -TokenPath $TokenPath `
            -ActiveIssue $ActiveIssue
        $message = ("SYNAPSE_CODEX_CURRENT_PROCESS_SCHEMA_STALE codex_pid={0} tool_surface_at_process_start=mismatch start_tool_surface_sha256={1} current_tool_surface_sha256={2} tool_count={3} daemon_pid={4} snapshot={5} start_snapshot={6} handoff={7} {8} remediation=restart Codex through the patched launcher, read the handoff plus STATE\\RECOVERY_NOTES.md, then resume the active issue named in the handoff and verify real mcp__synapse metadata." -f `
            $CodexAncestor.ProcessId,
            $ProcessHashAtStart,
            $currentHash,
            $CurrentSurface.tool_count,
            $CurrentSurface.daemon_pid,
            $SnapshotPath,
            $ProcessSnapshotAtStart,
            $handoff.JsonPath,
            $diffSummary)
        if ($NonFatal) {
            Info "WARN: $message"
            return
        }
        Die $message
    }

    Info "Codex current-process tool surface matches daemon snapshot codex_pid=$($CodexAncestor.ProcessId) tool_surface_sha256=$currentHash tool_count=$($CurrentSurface.tool_count)"
}

function Request-SynapseGracefulShutdown {
    param(
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$Token,
        [Parameter(Mandatory=$true)][int[]]$ExpectedPids,
        [Parameter(Mandatory=$true)][string]$Reason
    )

    try {
        $response = Invoke-RestMethod `
            -Method Post `
            -Uri "http://$Bind/shutdown" `
            -Headers @{ Authorization = "Bearer $Token" } `
            -UserAgent "synapse-setup/$Reason" `
            -TimeoutSec 4
    } catch {
        return [pscustomobject]@{ Ok = $false; Code = 'SYNAPSE_GRACEFUL_SHUTDOWN_REQUEST_FAILED'; Response = $null; Error = $_.Exception.Message }
    }

    $responsePid = 0
    try {
        $responsePid = [int]$response.pid
    } catch {
        return [pscustomobject]@{ Ok = $false; Code = 'SYNAPSE_GRACEFUL_SHUTDOWN_PID_UNREADABLE'; Response = $response; Error = $_.Exception.Message }
    }

    if ($ExpectedPids -notcontains $responsePid) {
        return [pscustomobject]@{
            Ok = $false
            Code = 'SYNAPSE_GRACEFUL_SHUTDOWN_PID_MISMATCH'
            Response = $response
            Error = "response_pid=$responsePid expected_pids=$($ExpectedPids -join ',')"
        }
    }

    if ($response.ok -ne $true -or "$($response.shutdown)" -ne 'requested') {
        return [pscustomobject]@{
            Ok = $false
            Code = 'SYNAPSE_GRACEFUL_SHUTDOWN_RESPONSE_INVALID'
            Response = $response
            Error = "response=$($response | ConvertTo-Json -Compress -Depth 6)"
        }
    }

    [pscustomobject]@{ Ok = $true; Code = 'OK'; Response = $response; Error = $null }
}

function Read-SynapseHttpErrorResponseBody {
    param([Parameter(Mandatory=$true)]$ErrorRecord)

    $errorDetailsBody = [string]$ErrorRecord.ErrorDetails.Message
    if (-not [string]::IsNullOrWhiteSpace($errorDetailsBody)) {
        return $errorDetailsBody
    }

    $response = $ErrorRecord.Exception.Response
    if ($null -eq $response) {
        return $null
    }
    if ($null -ne $response.Content) {
        try {
            return $response.Content.ReadAsStringAsync().GetAwaiter().GetResult()
        } catch {
            return "SYNAPSE_HTTP_ERROR_BODY_READ_FAILED source=http_response_content error=$($_.Exception.Message)"
        }
    }
    try {
        $stream = $response.GetResponseStream()
        if ($null -eq $stream) {
            return $null
        }
        $reader = New-Object System.IO.StreamReader($stream)
        try {
            return $reader.ReadToEnd()
        } finally {
            $reader.Dispose()
        }
    } catch {
        return "SYNAPSE_HTTP_ERROR_BODY_READ_FAILED source=response_stream error=$($_.Exception.Message)"
    }
}

function Read-SynapseHttpErrorStatus {
    param([Parameter(Mandatory=$true)]$ErrorRecord)

    $response = $ErrorRecord.Exception.Response
    if ($null -eq $response) {
        return $null
    }
    try {
        return [int]$response.StatusCode
    } catch {
        return $null
    }
}

function Request-SynapseChromeBridgeMaintenancePause {
    param(
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$Token,
        [Parameter(Mandatory=$true)][string]$Reason,
        [int]$PauseMs = $SynapseChromeBridgeMaintenancePauseMs,
        [int]$ResumeProbeAfterMs = $SynapseChromeBridgeMaintenanceResumeProbeAfterMs
    )

    $health = $null
    $healthAttempts = @()
    $healthTimeouts = @(4, 8, 12)
    for ($healthAttempt = 1; $healthAttempt -le $healthTimeouts.Count; $healthAttempt++) {
        $timeoutSec = [int]$healthTimeouts[$healthAttempt - 1]
        try {
            $health = Invoke-RestMethod `
                -Method Get `
                -Uri "http://$Bind/health" `
                -Headers @{ Authorization = "Bearer $Token" } `
                -UserAgent "synapse-setup/$Reason" `
                -TimeoutSec $timeoutSec
            $healthAttempts += [pscustomobject]@{
                attempt = $healthAttempt
                ok = $true
                timeout_sec = $timeoutSec
                error = $null
            }
            if ($healthAttempt -gt 1) {
                Info ("SYNAPSE_CHROME_BRIDGE_MAINTENANCE_PAUSE_HEALTH_RETRY_OK reason={0} bind={1} attempt={2} timeout_sec={3}" -f `
                    $Reason,
                    $Bind,
                    $healthAttempt,
                    $timeoutSec)
            }
            break
        } catch {
            $healthAttempts += [pscustomobject]@{
                attempt = $healthAttempt
                ok = $false
                timeout_sec = $timeoutSec
                error = $_.Exception.Message
            }
            if ($healthAttempt -lt $healthTimeouts.Count) {
                Start-Sleep -Seconds 1
            }
        }
    }

    if ($null -ne $health) {
        $chromeBridge = $health.subsystems.chrome_bridge
        if ($null -eq $chromeBridge) {
            return [pscustomobject]@{
                Ok = $false
                Skipped = $false
                Code = 'SYNAPSE_CHROME_BRIDGE_MAINTENANCE_PAUSE_HEALTH_MISSING'
                Response = [pscustomobject]@{
                    health = $health
                    health_attempts = $healthAttempts
                }
                Error = 'health.subsystems.chrome_bridge missing'
                Detail = $null
            }
        }

        $status = "$($chromeBridge.status)"
        $detail = "$($chromeBridge.detail)"
        if ($detail -match 'no_active_chrome_bridge_host') {
            return [pscustomobject]@{
                Ok = $true
                Skipped = $true
                Code = 'SYNAPSE_CHROME_BRIDGE_MAINTENANCE_PAUSE_SKIPPED_NO_ACTIVE_HOST'
                Response = [pscustomobject]@{
                    health = $health
                    health_attempts = $healthAttempts
                }
                Error = $null
                Detail = $detail
            }
        }
        if ([string]::IsNullOrWhiteSpace($status)) {
            return [pscustomobject]@{
                Ok = $false
                Skipped = $false
                Code = 'SYNAPSE_CHROME_BRIDGE_MAINTENANCE_PAUSE_STATUS_UNREADABLE'
                Response = [pscustomobject]@{
                    health = $health
                    health_attempts = $healthAttempts
                }
                Error = 'health.subsystems.chrome_bridge.status missing'
                Detail = $detail
            }
        }
        if ($Reason -eq 'install_health_failed_rollback' -and
            $script:SynapseManualInstallHealthRollbackProbe -and
            $script:SynapseManualInstallHealthRollbackPauseMode -eq 'force_unacknowledged') {
            return [pscustomobject]@{
                Ok = $false
                Skipped = $false
                Code = 'SYNAPSE_CHROME_BRIDGE_MAINTENANCE_PAUSE_MANUAL_UNACKNOWLEDGED_PROBE'
                Response = [pscustomobject]@{
                    manual_probe = 'install_health_failed_rollback'
                    pause_mode = $script:SynapseManualInstallHealthRollbackPauseMode
                    health = $health
                    health_attempts = $healthAttempts
                    bridge_status = $status
                    bridge_detail = $detail
                }
                Error = 'manual rollback probe forced the maintenance pause to remain unacknowledged after /health readback'
                Detail = $detail
                Attempts = @()
            }
        }
    } else {
        $listeners = @(Get-SynapseTcpBindListenerSnapshot -Bind $Bind)
        $tcpClients = @(Get-SynapseTcpClientSnapshot -Bind $Bind)
        $liveListeners = @($listeners | Where-Object { $_.OwnerExists })
        $liveTcpClients = @($tcpClients | Where-Object { $_.HasLivePeer -and [int]$_.PeerOwningProcess -gt 0 })
        if ($liveListeners.Count -eq 0 -and $liveTcpClients.Count -eq 0) {
            $detail = "health_preflight_unreadable attempts=$($healthAttempts.Count); socket_sot=reachable_daemon_endpoint_absent live_listener_count=0 live_tcp_clients=0"
            Info ("SYNAPSE_CHROME_BRIDGE_MAINTENANCE_PAUSE_SKIPPED_NO_REACHABLE_DAEMON_ENDPOINT reason={0} bind={1} attempts={2} last_error={3}`nlisteners:`n{4}`ntcp_clients:`n{5}`nremediation=/health is unreadable and the independent process/socket Source of Truth proves there is no live HTTP endpoint or live bridge/client peer to acknowledge. Setup will continue only through exact verified synapse-mcp.exe PID stop and a separate bind-release readback." -f `
                $Reason,
                $Bind,
                $healthAttempts.Count,
                $healthAttempts[-1].error,
                (Format-SynapseTcpBindListenerSnapshot -Snapshot $listeners),
                (Format-SynapseTcpClientSnapshot -Snapshot $tcpClients))
            return [pscustomobject]@{
                Ok = $true
                Skipped = $true
                Code = 'SYNAPSE_CHROME_BRIDGE_MAINTENANCE_PAUSE_SKIPPED_NO_REACHABLE_DAEMON_ENDPOINT'
                Response = [pscustomobject]@{
                    health = $null
                    health_attempts = $healthAttempts
                    listeners = $listeners
                    tcp_clients = $tcpClients
                }
                Error = $null
                Detail = $detail
                Attempts = @()
            }
        }

        $detail = "health_preflight_unreadable attempts=$($healthAttempts.Count); live_listener_count=$($liveListeners.Count); live_tcp_clients=$($liveTcpClients.Count); proceeding_to_maintenance_pause_post because the POST endpoint is the authoritative bridge pause acknowledgement gate when a live daemon endpoint or live client peer exists"
        Info ("SYNAPSE_CHROME_BRIDGE_MAINTENANCE_PAUSE_HEALTH_PREFLIGHT_UNREADABLE_PROCEEDING reason={0} bind={1} attempts={2} last_error={3} live_listener_count={4} live_tcp_clients={5}`nlisteners:`n{6}`ntcp_clients:`n{7}" -f `
            $Reason,
            $Bind,
            $healthAttempts.Count,
            $healthAttempts[-1].error,
            $liveListeners.Count,
            $liveTcpClients.Count,
            (Format-SynapseTcpBindListenerSnapshot -Snapshot $listeners),
            (Format-SynapseTcpClientSnapshot -Snapshot $tcpClients))
        if ($Reason -eq 'install_health_failed_rollback' -and
            $script:SynapseManualInstallHealthRollbackProbe -and
            $script:SynapseManualInstallHealthRollbackPauseMode -eq 'force_unacknowledged') {
            return [pscustomobject]@{
                Ok = $false
                Skipped = $false
                Code = 'SYNAPSE_CHROME_BRIDGE_MAINTENANCE_PAUSE_MANUAL_UNACKNOWLEDGED_PROBE'
                Response = [pscustomobject]@{
                    manual_probe = 'install_health_failed_rollback'
                    pause_mode = $script:SynapseManualInstallHealthRollbackPauseMode
                    health = $null
                    health_attempts = $healthAttempts
                    bridge_status = '<unreadable>'
                    bridge_detail = $detail
                }
                Error = 'manual rollback probe forced the maintenance pause to remain unacknowledged after /health readback failed'
                Detail = $detail
                Attempts = @()
            }
        }
    }

    $body = [ordered]@{
        pause_ms = $PauseMs
        resume_probe_after_ms = $ResumeProbeAfterMs
        reason = $Reason
    } | ConvertTo-Json -Compress -Depth 4

    $attempts = @()
    $maxAttempts = 5
    for ($attempt = 1; $attempt -le $maxAttempts; $attempt++) {
        try {
            $response = Invoke-RestMethod `
                -Method Post `
                -Uri "http://$Bind/chrome-debugger/native/maintenance-pause" `
                -Headers @{ Authorization = "Bearer $Token" } `
                -ContentType 'application/json' `
                -UserAgent "synapse-setup/$Reason" `
                -Body $body `
                -TimeoutSec 8
        } catch {
            $responseBody = Read-SynapseHttpErrorResponseBody -ErrorRecord $_
            $statusCode = Read-SynapseHttpErrorStatus -ErrorRecord $_
            $responseDetail = $responseBody
            $parsedResponseBody = $null
            if (-not [string]::IsNullOrWhiteSpace($responseBody)) {
                try {
                    $parsedResponseBody = $responseBody | ConvertFrom-Json -ErrorAction Stop
                    if ($null -ne $parsedResponseBody.detail) {
                        $responseDetail = "$($parsedResponseBody.detail)"
                    }
                } catch {
                    $parsedResponseBody = $null
                }
            }
            if ($statusCode -eq 503 -and $responseDetail -match 'no_active_chrome_bridge_host') {
                return [pscustomobject]@{
                    Ok = $true
                    Skipped = $true
                    Code = 'SYNAPSE_CHROME_BRIDGE_MAINTENANCE_PAUSE_SKIPPED_NO_ACTIVE_HOST'
                    Response = [pscustomobject]@{
                        health_attempts = $healthAttempts
                        maintenance_pause_attempt = $attempt
                        post_response = $parsedResponseBody
                        post_response_body = $responseBody
                    }
                    Error = $null
                    Detail = $responseDetail
                    Attempts = $attempts
                }
            }
            $attempts += [pscustomobject]@{
                attempt = $attempt
                code = 'SYNAPSE_CHROME_BRIDGE_MAINTENANCE_PAUSE_REQUEST_FAILED'
                ok = $false
                status = $statusCode
                error = $_.Exception.Message
                response = $responseBody
            }
            if ($attempt -lt $maxAttempts) {
                Start-Sleep -Seconds 1
                continue
            }
            return [pscustomobject]@{
                Ok = $false
                Skipped = $false
                Code = 'SYNAPSE_CHROME_BRIDGE_MAINTENANCE_PAUSE_REQUEST_FAILED'
                Response = $attempts
                Error = "attempts=$($attempts.Count) last_status=$statusCode message=$($_.Exception.Message)"
                Detail = $detail
                Attempts = $attempts
            }
        }

        $pause = $response.pause
        $websocketClose = $null
        if ($null -ne $pause) {
            $websocketClose = $pause.websocket_close
        }
        $activeSocketWasOpen = $false
        if ($null -ne $websocketClose -and $null -ne $websocketClose.ready_state_before) {
            $readyStateBefore = [int]$websocketClose.ready_state_before
            $activeSocketWasOpen = ($readyStateBefore -eq 0 -or $readyStateBefore -eq 1)
        }
        $websocketCloseFailed = $false
        if ($null -eq $websocketClose) {
            $websocketCloseFailed = $true
        } elseif ($null -ne $websocketClose.close_error) {
            $websocketCloseFailed = $true
        } elseif ($activeSocketWasOpen -and $websocketClose.close_requested -ne $true) {
            $websocketCloseFailed = $true
        }

        $attemptReadback = [pscustomobject]@{
            attempt = $attempt
            code = 'OK'
            ok = ($response.ok -eq $true)
            status = 200
            pause_ms = if ($null -eq $pause) { $null } else { $pause.pause_ms }
            resume_probe_after_ms = if ($null -eq $pause) { $null } else { $pause.resume_probe_after_ms }
            resume_probe_after_unix_ms = if ($null -eq $pause) { $null } else { $pause.resume_probe_after_unix_ms }
            paused_daemon_pid = if ($null -eq $pause) { $null } else { $pause.paused_daemon_pid }
            paused_daemon_instance_id = if ($null -eq $pause) { $null } else { $pause.paused_daemon_instance_id }
            reconnect_suppressed = if ($null -eq $pause) { $null } else { $pause.reconnect_suppressed }
            persisted = if ($null -eq $pause) { $null } else { $pause.persisted }
            websocket_close = $websocketClose
        }
        $attempts += $attemptReadback

        $resumeProbeReadbackOk = (
            $null -eq $pause.resume_probe_after_ms -or
            [int64]$pause.resume_probe_after_ms -eq [int64]$ResumeProbeAfterMs
        )
        if ($response.ok -eq $true -and $null -ne $pause -and $pause.reconnect_suppressed -eq $true -and $pause.persisted -eq $true -and $resumeProbeReadbackOk -and -not $websocketCloseFailed) {
            return [pscustomobject]@{
                Ok = $true
                Skipped = $false
                Code = 'OK'
                Response = $response
                Error = $null
                Detail = $detail
                Attempts = $attempts
            }
        }

        $attemptReadback.code = 'SYNAPSE_CHROME_BRIDGE_MAINTENANCE_PAUSE_RESPONSE_INVALID'
        if ($attempt -lt $maxAttempts) {
            Start-Sleep -Seconds 1
        }
    }

    [pscustomobject]@{
        Ok = $false
        Skipped = $false
        Code = 'SYNAPSE_CHROME_BRIDGE_MAINTENANCE_PAUSE_RESPONSE_INVALID'
        Response = $attempts
        Error = "attempts=$($attempts.Count) last_response=$($attempts[-1] | ConvertTo-Json -Compress -Depth 8)"
        Detail = $detail
        Attempts = $attempts
    }
}

function Enter-SynapseChromeBridgeMaintenancePause {
    param(
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$Token,
        [Parameter(Mandatory=$true)][string]$Reason,
        [switch]$AllowUnacknowledgedChromeBridgePauseForRollback
    )

    if ($script:SynapseChromeBridgeMaintenancePausePrepared) {
        if ($script:SynapseChromeBridgeMaintenancePausePreparedBind -cne $Bind -or
            $script:SynapseChromeBridgeMaintenancePausePreparedReason -cne $Reason) {
            Die ("SYNAPSE_CHROME_BRIDGE_MAINTENANCE_PAUSE_PREPARED_SCOPE_MISMATCH prepared_bind={0} requested_bind={1} prepared_reason={2} requested_reason={3} remediation=a maintenance pause acknowledgement is scoped to one daemon handoff; start a fresh setup run instead of reusing it for another bind or reason" -f `
                $script:SynapseChromeBridgeMaintenancePausePreparedBind,
                $Bind,
                $script:SynapseChromeBridgeMaintenancePausePreparedReason,
                $Reason)
        }
        if ($null -ne $script:SynapseChromeBridgeMaintenancePauseUntilUnixMs) {
            Assert-SynapseChromeBridgeMaintenancePauseBudget -Reason $Reason -Bind $Bind -Phase 'prepared_pause_reuse'
        }
        Info ("FORCE_RESTART: SYNAPSE_CHROME_BRIDGE_MAINTENANCE_PAUSE_PREPARED_REUSED reason={0} bind={1} pause_until_unix_ms={2} resume_probe_after_unix_ms={3}" -f `
            $Reason,
            $Bind,
            ($(if ($null -eq $script:SynapseChromeBridgeMaintenancePauseUntilUnixMs) { '<skipped-no-active-host>' } else { $script:SynapseChromeBridgeMaintenancePauseUntilUnixMs })),
            ($(if ($null -eq $script:SynapseChromeBridgeMaintenanceResumeProbeAfterUnixMs) { '<none>' } else { $script:SynapseChromeBridgeMaintenanceResumeProbeAfterUnixMs })))
        return $script:SynapseChromeBridgeMaintenancePausePreparedResult
    }

    $script:SynapseChromeBridgeMaintenancePauseUntilUnixMs = $null
    $script:SynapseChromeBridgeMaintenanceResumeProbeAfterUnixMs = $null
    $pause = Request-SynapseChromeBridgeMaintenancePause `
        -Bind $Bind `
        -Token $Token `
        -Reason $Reason `
        -PauseMs $SynapseChromeBridgeMaintenancePauseMs `
        -ResumeProbeAfterMs $SynapseChromeBridgeMaintenanceResumeProbeAfterMs
    if (-not $pause.Ok) {
        if ($AllowUnacknowledgedChromeBridgePauseForRollback -and $Reason -eq 'install_health_failed_rollback') {
            Info ("FORCE_RESTART: SYNAPSE_CHROME_BRIDGE_MAINTENANCE_PAUSE_UNACKNOWLEDGED_ROLLBACK_CONTINUING reason={0} bind={1} code={2} error={3} detail={4} response={5} remediation=install health already failed after replacing the daemon binary, so rollback must restore the previous verified daemon instead of stranding the failed candidate; setup will continue only through authenticated shutdown or exact verified synapse-mcp.exe PID stop, then separately verify the restored daemon and Chrome bridge Source of Truth." -f `
                $Reason,
                $Bind,
                $pause.Code,
                $pause.Error,
                $pause.Detail,
                ($(if ($null -eq $pause.Response) { '<none>' } else { $pause.Response | ConvertTo-Json -Compress -Depth 8 })))
            return $pause
        }
        Die ("{0} reason={1} bind={2} error={3} detail={4} response={5} remediation=forced daemon maintenance requires the already-open Chrome bridge to acknowledge a bounded reconnect pause before shutdown when an active bridge host exists. Inspect the exact extension error code/detail in this response and daemon CHROME_DEBUGGER_RESPONSE_ACCEPTED log; setup keeps restart authority intact until this prepare gate succeeds." -f `
            $pause.Code,
            $Reason,
            $Bind,
            $pause.Error,
            $pause.Detail,
            ($(if ($null -eq $pause.Response) { '<none>' } else { $pause.Response | ConvertTo-Json -Compress -Depth 8 })))
    }

    if ($pause.Skipped) {
        Info ("FORCE_RESTART: {0} reason={1} bind={2} detail={3}" -f `
            $pause.Code,
            $Reason,
            $Bind,
            $pause.Detail)
    } else {
        $pauseUntil = $pause.Response.pause.pause_until_unix_ms
        $resumeProbeAfter = $pause.Response.pause.resume_probe_after_unix_ms
        try {
            $script:SynapseChromeBridgeMaintenancePauseUntilUnixMs = [int64]$pauseUntil
            $script:SynapseChromeBridgeMaintenanceResumeProbeAfterUnixMs = [int64]$resumeProbeAfter
        } catch {
            Die ("SYNAPSE_CHROME_BRIDGE_MAINTENANCE_PAUSE_ACK_TIME_INVALID reason={0} bind={1} pause_until_unix_ms={2} resume_probe_after_unix_ms={3} error={4} remediation=the bridge acknowledgement did not contain exact integer lease timestamps; restart authority remains intact and setup refuses the handoff" -f `
                $Reason,
                $Bind,
                $pauseUntil,
                $resumeProbeAfter,
                $_.Exception.Message)
        }
        if ($script:SynapseChromeBridgeMaintenancePauseUntilUnixMs -le 0 -or
            $script:SynapseChromeBridgeMaintenanceResumeProbeAfterUnixMs -le 0) {
            Die ("SYNAPSE_CHROME_BRIDGE_MAINTENANCE_PAUSE_ACK_TIME_INVALID reason={0} bind={1} pause_until_unix_ms={2} resume_probe_after_unix_ms={3} remediation=the bridge acknowledgement returned non-positive lease timestamps; restart authority remains intact and setup refuses the handoff" -f `
                $Reason,
                $Bind,
                $script:SynapseChromeBridgeMaintenancePauseUntilUnixMs,
                $script:SynapseChromeBridgeMaintenanceResumeProbeAfterUnixMs)
        }
        Assert-SynapseChromeBridgeMaintenancePauseBudget -Reason $Reason -Bind $Bind -Phase 'pause_prepare'
        Info ("FORCE_RESTART: SYNAPSE_CHROME_BRIDGE_MAINTENANCE_PAUSE_ACK reason={0} bind={1} pause={2}" -f `
            $Reason,
            $Bind,
            ($pause.Response.pause | ConvertTo-Json -Compress -Depth 8))
        $webSocketClose = $pause.Response.pause.websocket_close
        if ($webSocketClose -and $webSocketClose.had_socket -eq $true -and $webSocketClose.close_requested -eq $true) {
            Info ("FORCE_RESTART: SYNAPSE_CHROME_BRIDGE_MAINTENANCE_PAUSE_SOCKET_DRAIN_WAIT reason={0} bind={1} wait_ms={2} had_socket={3} close_requested={4} close_deferred={5} remediation=the bridge intentionally sends the pause response before closing its active WebSocket, so setup waits for the bounded response-drain window before daemon shutdown." -f `
                $Reason,
                $Bind,
                $SynapseChromeBridgeMaintenanceCloseDrainMs,
                $webSocketClose.had_socket,
                $webSocketClose.close_requested,
                ($(if ($null -eq $webSocketClose.close_deferred) { '<missing>' } else { $webSocketClose.close_deferred })))
            Start-Sleep -Milliseconds $SynapseChromeBridgeMaintenanceCloseDrainMs
        }
    }

    $script:SynapseChromeBridgeMaintenancePausePrepared = $true
    $script:SynapseChromeBridgeMaintenancePausePreparedBind = $Bind
    $script:SynapseChromeBridgeMaintenancePausePreparedReason = $Reason
    $script:SynapseChromeBridgeMaintenancePausePreparedResult = $pause
    return $pause
}

function Get-SynapseActiveSessionCount {
    param([Parameter(Mandatory=$true)]$Health)

    $value = $Health.subsystems.http.active_sessions
    if ($null -eq $value) {
        return $null
    }

    try {
        return [int]$value
    } catch {
        return $null
    }
}

function Assert-SynapseRestartAllowed {
    param(
        [Parameter(Mandatory=$true)][string]$Reason,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$DbPath,
        [Parameter(Mandatory=$true)][string]$TokenPath,
        [ValidateRange(1, 300)][int]$HealthTimeoutSec = 120,
        [switch]$ForceRestart,
        [switch]$AllowActiveClientDrain
    )

    $allProcesses = @(Get-SynapseMcpProcessSnapshot)
    $processes = @(Select-SynapseMcpDeployTargetProcesses -Snapshot $allProcesses -Bind $Bind -DbPath $DbPath)
    $ignoredProcesses = @(Select-SynapseMcpDeployTargetProcesses -Snapshot $allProcesses -Bind $Bind -DbPath $DbPath -Invert)
    if ($ignoredProcesses.Count -gt 0) {
        Info ("Synapse restart guard reason={0} ignored_non_target_process_count={1}`nignored:`n{2}" -f `
            $Reason,
            $ignoredProcesses.Count,
            (Format-SynapseMcpProcessSnapshot -Snapshot $ignoredProcesses))
    }
    if ($processes.Count -eq 0) {
        Info "Synapse restart guard reason=$Reason target_process_count=0 ignored_non_target_process_count=$($ignoredProcesses.Count) verdict=clear"
        return
    }

    $null = Get-SynapseBindEndpoint -Bind $Bind
    $nonHttpProcesses = @($processes | Where-Object { $_.CommandLine -notmatch '(?i)--mode\s+http' })
    $tokenRead = Read-SynapseSetupTokenForRestartGuard -TokenPath $TokenPath
    if (-not $tokenRead.Ok) {
        $message = "$($tokenRead.Code) reason=$Reason process_count=$($processes.Count) $($tokenRead.Detail) remediation=do not restart blindly while the daemon may have clients; repair token state or rerun with -ForceRestart after coordinating a maintenance window"
        if ($ForceRestart) {
            Info "FORCE_RESTART: $message"
        } else {
            Die $message
        }
    }

    $activeSessions = $null
    $healthRead = $null
    if ($tokenRead.Ok) {
        $healthRead = Read-SynapseHealthForRestartGuard -Bind $Bind -Token $tokenRead.Token -TimeoutSec $HealthTimeoutSec
        if (-not $healthRead.Ok) {
            $message = "SYNAPSE_RESTART_GUARD_HEALTH_UNREADABLE reason=$Reason bind=$Bind timeout_s=$($healthRead.TimeoutSec) error=$($healthRead.Error) remediation=do not restart blindly; repair the daemon/token or rerun with -ForceRestart after coordinating a maintenance window"
            if ($ForceRestart) {
                Info "FORCE_RESTART: $message"
            } else {
                Die $message
            }
        }
    }

    if ($tokenRead.Ok -and $healthRead.Ok) {
        $activeSessions = Get-SynapseActiveSessionCount -Health $healthRead.Health
        if ($null -eq $activeSessions) {
            $message = "SYNAPSE_RESTART_GUARD_ACTIVE_SESSIONS_UNREADABLE reason=$Reason bind=$Bind remediation=health did not expose subsystems.http.active_sessions; do not restart blindly"
            if ($ForceRestart) {
                Info "FORCE_RESTART: $message"
            } else {
                Die $message
            }
        }
    }

    $tcpConnections = @(Get-SynapseTcpClientSnapshot -Bind $Bind)
    $setupLineagePids = @((Get-ProcessLineage -StartPid $PID) | ForEach-Object { [int]$_.ProcessId })
    $selfProbeTcpClients = @($tcpConnections | Where-Object {
        $_.HasLivePeer -and $setupLineagePids -contains [int]$_.PeerOwningProcess
    })
    $tcpClients = @($tcpConnections | Where-Object {
        $_.HasLivePeer -and $setupLineagePids -notcontains [int]$_.PeerOwningProcess
    })
    $staleTcpConnections = @($tcpConnections | Where-Object { -not $_.HasLivePeer })
    $blockers = @()
    $clientDrainBlockers = @()
    if ($nonHttpProcesses.Count -gt 0) { $blockers += "non_http_synapse_processes=$($nonHttpProcesses.Count)" }
    if ($tcpClients.Count -gt 0) {
        $blockers += "live_tcp_clients=$($tcpClients.Count)"
        $clientDrainBlockers += "live_tcp_clients=$($tcpClients.Count)"
    }
    if ($null -ne $activeSessions -and $activeSessions -gt 0 -and $tcpClients.Count -gt 0) {
        $blockers += "active_sessions=$activeSessions"
        $clientDrainBlockers += "active_sessions=$activeSessions"
    }
    if ($null -ne $activeSessions -and $activeSessions -gt 0 -and $tcpClients.Count -eq 0) {
        Info "Synapse restart guard reason=$Reason idle_session_map_entries=$activeSessions live_tcp_clients=0 verdict=not_blocking_idle_sessions"
    }
    if ($staleTcpConnections.Count -gt 0) {
        Info ("Synapse restart guard reason={0} stale_tcp_connections={1}`nstale_tcp:`n{2}" -f `
            $Reason,
            $staleTcpConnections.Count,
            (Format-SynapseTcpClientSnapshot -Snapshot $staleTcpConnections))
    }
    if ($selfProbeTcpClients.Count -gt 0) {
        Info ("Synapse restart guard reason={0} self_probe_tcp_connections={1}`nself_probe_tcp:`n{2}" -f `
            $Reason,
            $selfProbeTcpClients.Count,
            (Format-SynapseTcpClientSnapshot -Snapshot $selfProbeTcpClients))
    }

    if ($blockers.Count -gt 0) {
        $message = ("SYNAPSE_ACTIVE_CLIENTS_PRESENT reason={0} blockers={1} process_count={2} active_sessions={3} live_tcp_clients={4} idle_session_map_entries={5} stale_tcp_connections={6}`nprocesses:`n{7}`ntcp_clients:`n{8}`nstale_tcp:`n{9}`nremediation=wait for MCP clients to disconnect, close only the exact owner-known helper process listed here, or rerun with -ForceRestart only after coordinating a maintenance window. Do not close terminal windows or broad shell processes." -f `
            $Reason,
            ($blockers -join ','),
            $processes.Count,
            ($(if ($null -eq $activeSessions) { 'unknown' } else { $activeSessions })),
            $tcpClients.Count,
            ($(if ($null -eq $activeSessions) { 'unknown' } else { $activeSessions })),
            $staleTcpConnections.Count,
            (Format-SynapseMcpProcessSnapshot -Snapshot $processes),
            (Format-SynapseTcpClientSnapshot -Snapshot $tcpClients),
            (Format-SynapseTcpClientSnapshot -Snapshot $staleTcpConnections))
        if ($nonHttpProcesses.Count -gt 0 -and -not $ForceRestart) {
            Die $message
        } elseif ($AllowActiveClientDrain -and $clientDrainBlockers.Count -gt 0 -and $nonHttpProcesses.Count -eq 0) {
            Info ("Synapse restart guard reason={0} verdict=drain_permitted blockers={1} active_sessions={2} live_tcp_clients={3} stale_tcp_connections={4} process_count={5} drain=authenticated_http_shutdown" -f `
                $Reason,
                ($clientDrainBlockers -join ','),
                ($(if ($null -eq $activeSessions) { 'unknown' } else { $activeSessions })),
                $tcpClients.Count,
                $staleTcpConnections.Count,
                $processes.Count)
        } elseif ($ForceRestart) {
            Info "FORCE_RESTART: $message"
        } else {
            Die $message
        }
    } else {
        Info "Synapse restart guard reason=$Reason verdict=clear health_timeout_s=$($healthRead.TimeoutSec) active_sessions=$activeSessions live_tcp_clients=0 stale_tcp_connections=$($staleTcpConnections.Count) process_count=$($processes.Count)"
    }
}

function Assert-SynapseProcessStopTarget {
    param(
        [Parameter(Mandatory=$true)]$SnapshotProcess,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$DbPath
    )

    $pidValue = [int]$SnapshotProcess.ProcessId
    $current = Get-CimInstance Win32_Process -Filter "ProcessId=$pidValue" -ErrorAction SilentlyContinue
    if (-not $current) {
        Info "Synapse process stop target already exited pid=$pidValue"
        return $null
    }

    $protectedNames = @(
        'cmd.exe',
        'powershell.exe',
        'pwsh.exe',
        'WindowsTerminal.exe',
        'OpenConsole.exe',
        'conhost.exe',
        'wsl.exe',
        'wslhost.exe',
        'Code.exe'
    )
    if ($protectedNames -contains $current.Name) {
        Die ("SYNAPSE_PROTECTED_PROCESS_STOP_REFUSED pid={0} name={1} command_line={2} remediation=terminal/IDE/WSL host processes are operator and agent workspaces; never close them from setup, tests, or FSV. Stop only exact owner-known helper PIDs." -f `
            $pidValue,
            $current.Name,
            $current.CommandLine)
    }

    $exeLeaf = if ($current.ExecutablePath) { Split-Path -Leaf $current.ExecutablePath } else { '' }
    if (-not (Test-SynapseMcpExecutableLeafName -Name $current.Name) -and -not (Test-SynapseMcpExecutableLeafName -Name $exeLeaf)) {
        Die ("SYNAPSE_PROCESS_STOP_TARGET_MISMATCH pid={0} expected=synapse-mcp.exe_or_content_addressed_name actual_name={1} actual_path={2} command_line={3} remediation=PID was reused or snapshot was not a Synapse process; refusing exact-PID stop" -f `
            $pidValue,
            $current.Name,
            $current.ExecutablePath,
            $current.CommandLine)
    }
    if ($current.CommandLine -notmatch '(?i)synapse-mcp(\.exe)?') {
        Die ("SYNAPSE_PROCESS_STOP_TARGET_UNVERIFIED pid={0} name={1} command_line={2} remediation=command line does not prove a Synapse MCP target; refusing exact-PID stop" -f `
            $pidValue,
            $current.Name,
            $current.CommandLine)
    }

    $targetMatch = Get-SynapseMcpDeployTargetMatch -Process $current -Bind $Bind -DbPath $DbPath
    if (-not $targetMatch.IsMatch) {
        Die ("SYNAPSE_PROCESS_STOP_TARGET_SCOPE_MISMATCH pid={0} bind={1} db={2} actual_bind_arg={3} actual_db_arg={4} command_line={5} remediation=setup only stops synapse-mcp.exe processes whose command line targets the deployed --bind or --db; refusing collateral stop" -f `
            $pidValue,
            $Bind,
            $targetMatch.ExpectedDb,
            $targetMatch.BindArg,
            $targetMatch.DbArg,
            $current.CommandLine)
    }
    $rules = $targetMatch.Rules -join ','
    $current | Add-Member -NotePropertyName DeployTargetMatched -NotePropertyValue $true -Force
    $current | Add-Member -NotePropertyName DeployTargetRules -NotePropertyValue $rules -Force
    $current | Add-Member -NotePropertyName DeployTargetBindArg -NotePropertyValue $targetMatch.BindArg -Force
    $current | Add-Member -NotePropertyName DeployTargetDbArg -NotePropertyValue $targetMatch.DbArg -Force
    Info "Synapse process stop target verified pid=$pidValue match_rules=$rules path=$($current.ExecutablePath) cmd=$($current.CommandLine)"

    return $current
}

function Get-SynapseDaemonLivenessSample {
    param(
        [AllowNull()][string]$LogDir,
        [Parameter(Mandatory=$true)][string]$DbPath
    )

    $logPath = '<none>'
    $logLength = -1
    $logWriteTicks = 0
    if (-not [string]::IsNullOrWhiteSpace($LogDir) -and (Test-Path -LiteralPath $LogDir -PathType Container)) {
        $newest = Get-ChildItem -LiteralPath $LogDir -Filter 'daemon-stderr-gen*.log' -File -ErrorAction SilentlyContinue |
            Sort-Object LastWriteTimeUtc -Descending |
            Select-Object -First 1
        if ($null -ne $newest) {
            $logPath = $newest.FullName
            $logLength = [int64]$newest.Length
            $logWriteTicks = [int64]$newest.LastWriteTimeUtc.Ticks
        }
    }

    $endingPhase = '<none>'
    $endingAt = 0
    $endedAt = 0
    $runCurrentPath = Join-Path $DbPath 'daemon-run-current.json'
    if (Test-Path -LiteralPath $runCurrentPath -PathType Leaf) {
        try {
            $run = Get-Content -Raw -LiteralPath $runCurrentPath -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
            if ($null -ne $run.ending_phase) { $endingPhase = [string]$run.ending_phase }
            if ($null -ne $run.ending_at_unix_ms) { $endingAt = [int64]$run.ending_at_unix_ms }
            if ($null -ne $run.ended_at_unix_ms) { $endedAt = [int64]$run.ended_at_unix_ms }
        } catch {
            # A torn read of a file being atomically replaced is expected and is
            # not evidence of anything; the next poll resolves it.
            $endingPhase = '<unreadable>'
        }
    }

    [pscustomobject]@{
        LogPath        = $logPath
        LogLength      = $logLength
        LogWriteTicks  = $logWriteTicks
        EndingPhase    = $endingPhase
        EndingAtUnixMs = $endingAt
        EndedAtUnixMs  = $endedAt
        RunCurrentPath = $runCurrentPath
        # One comparable value: any change in any witness is progress.
        Fingerprint    = "$logPath|$logLength|$logWriteTicks|$endingPhase|$endingAt|$endedAt"
    }
}

function Stop-SynapseMcpProcesses {
    param(
        [Parameter(Mandatory=$true)][string]$Reason,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$DbPath,
        [Parameter(Mandatory=$true)][string]$TokenPath,
        [switch]$ForceRestart,
        [switch]$AllowUnacknowledgedChromeBridgePauseForRollback,
        # Install-handoff escalation (#1800): when graceful shutdown times out,
        # proceed to the identity-verified exact-PID force stop instead of dying.
        # By that point the daemon has already closed its listener and committed
        # to exit (retained-owner fail-closed state); aborting the deploy only
        # leaves a zombie window until the daemon's own 90s shutdown watchdog
        # forces the same termination without installing the new binary.
        [switch]$EscalateAfterGracefulTimeout,
        [int]$TimeoutSeconds = 15,
        # #2100: where the daemon's own liveness evidence lives. Optional so the
        # `-Remove` path and any caller without a log directory keeps the old
        # flat-budget behaviour explicitly rather than by accident -- when this is
        # absent the run-record marker is still read, and when neither witness is
        # available the wait degrades to the wall-clock budget and SAYS SO.
        [AllowNull()][string]$LogDir,
        # Longest the daemon may produce no evidence of progress at all before
        # the exit-wait escalates. This, not $TimeoutSeconds, is the number that
        # decides a kill on a healthy-but-slow close.
        [int]$StallSeconds = 25,
        # Absolute backstop on the extended wait, so a daemon that keeps writing
        # forever still cannot hold a deploy open indefinitely.
        [int]$MaxWaitSeconds = 600
    )

    $allBefore = @(Get-SynapseMcpProcessSnapshot)
    $before = @(Select-SynapseMcpDeployTargetProcesses -Snapshot $allBefore -Bind $Bind -DbPath $DbPath)
    $ignoredBefore = @(Select-SynapseMcpDeployTargetProcesses -Snapshot $allBefore -Bind $Bind -DbPath $DbPath -Invert)
    Info "Synapse process stop requested reason=$Reason before_all_count=$($allBefore.Count) target_count=$($before.Count) ignored_non_target_count=$($ignoredBefore.Count) bind=$Bind db=$DbPath"
    Info ("Synapse process stop target candidates:`n{0}" -f (Format-SynapseMcpProcessSnapshot -Snapshot $before))
    if ($ignoredBefore.Count -gt 0) {
        Info ("Synapse process stop ignored non-target processes:`n{0}" -f (Format-SynapseMcpProcessSnapshot -Snapshot $ignoredBefore))
    }
    if ($before.Count -eq 0) {
        Wait-SynapseBindReleased -Reason $Reason -Bind $Bind -TimeoutSeconds $TimeoutSeconds -ForceRestart:$ForceRestart
        return
    }

    foreach ($proc in $before) {
        $null = Assert-SynapseProcessStopTarget -SnapshotProcess $proc -Bind $Bind -DbPath $DbPath
    }

    $httpProcesses = @($before | Where-Object { $_.CommandLine -match '(?i)--mode\s+http' })
    $nonHttpProcesses = @($before | Where-Object { $_.CommandLine -notmatch '(?i)--mode\s+http' })
    if ($nonHttpProcesses.Count -gt 0 -and -not $ForceRestart) {
        Die ("SYNAPSE_GRACEFUL_SHUTDOWN_NON_HTTP_PROCESS reason={0} count={1}`nprocesses:`n{2}`nremediation=setup will not force-stop stdio/bridge/non-http Synapse processes without -ForceRestart; run synapse-mcp --mode doctor to inspect ownership, or coordinate a maintenance window before forcing exact verified PIDs. Do not close terminal windows." -f `
            $Reason,
            $nonHttpProcesses.Count,
            (Format-SynapseMcpProcessSnapshot -Snapshot $nonHttpProcesses))
    }

    if ($httpProcesses.Count -gt 0) {
        if ($ForceRestart) {
            $liveTcpClients = @(Get-SynapseTcpClientSnapshot -Bind $Bind | Where-Object { $_.HasLivePeer })
            if ($liveTcpClients.Count -gt 0) {
                $targetPids = (($httpProcesses | ForEach-Object { [int]$_.ProcessId }) -join ',')
                Info ("FORCE_RESTART: SYNAPSE_FORCE_RESTART_LIVE_CLIENTS_GRACEFUL_FIRST reason={0} bind={1} target_pids={2} live_tcp_client_count={3}`ntcp_clients:`n{4}`nremediation=-ForceRestart is explicit maintenance. Setup still asks the HTTP daemon to shut down first so it can close accepted sockets cleanly; if Windows keeps dead-owner rows because client peers remain connected, setup closes only exact known non-terminal peers and then requires a normal bind probe before installing or starting anything." -f `
                    $Reason,
                    $Bind,
                    $targetPids,
                    $liveTcpClients.Count,
                    (Format-SynapseTcpClientSnapshot -Snapshot $liveTcpClients))
            }
        }

        $tokenRead = Read-SynapseSetupTokenForRestartGuard -TokenPath $TokenPath
        if (-not $tokenRead.Ok) {
            $message = ("{0} reason={1} process_count={2} {3} remediation=graceful shutdown requires the daemon bearer token; repair token state before setup, or use -ForceRestart only after manually verifying no held inputs and no live clients." -f `
                $tokenRead.Code,
                $Reason,
                $httpProcesses.Count,
                $tokenRead.Detail)
            if ($ForceRestart) {
                Info "FORCE_RESTART: $message"
            } else {
                Die $message
            }
        } else {
            $expectedPids = @($httpProcesses | ForEach-Object { [int]$_.ProcessId })
            if ($ForceRestart) {
                $null = Enter-SynapseChromeBridgeMaintenancePause `
                    -Bind $Bind `
                    -Token $tokenRead.Token `
                    -Reason $Reason `
                    -AllowUnacknowledgedChromeBridgePauseForRollback:$AllowUnacknowledgedChromeBridgePauseForRollback
            }
            $shutdown = Request-SynapseGracefulShutdown -Bind $Bind -Token $tokenRead.Token -ExpectedPids $expectedPids -Reason $Reason
            if (-not $shutdown.Ok) {
                $message = ("{0} reason={1} bind={2} error={3} response={4} remediation=the running daemon did not accept authenticated graceful shutdown; inspect daemon logs and token/bind state. Use -ForceRestart only for a coordinated legacy-runtime transition after manual input-state readback." -f `
                    $shutdown.Code,
                    $Reason,
                    $Bind,
                    $shutdown.Error,
                    ($(if ($null -eq $shutdown.Response) { '<none>' } else { $shutdown.Response | ConvertTo-Json -Compress -Depth 6 })))
                if ($ForceRestart) {
                    Info "FORCE_RESTART: $message"
                } else {
                    Die $message
                }
            } else {
                Info ("Synapse graceful shutdown requested reason={0} pid={1} active_sessions_before_shutdown={2}" -f `
                    $Reason,
                    $shutdown.Response.pid,
                    $shutdown.Response.active_sessions_before_shutdown)
            }
        }

        # --- #2100: stall-based exit wait -------------------------------------
        $waitStarted = Get-Date
        $hardDeadline = $waitStarted.AddSeconds([Math]::Max($TimeoutSeconds, $MaxWaitSeconds))
        $liveness = Get-SynapseDaemonLivenessSample -LogDir $LogDir -DbPath $DbPath
        $livenessAvailable = ($liveness.LogWriteTicks -gt 0) -or ($liveness.EndingAtUnixMs -gt 0)
        $lastProgressAt = $waitStarted
        $lastFingerprint = $liveness.Fingerprint
        $progressObservations = 0
        $extendedSeconds = 0
        $lastProgressLogAt = $waitStarted
        $exitWaitVerdict = 'pending'
        Info ("SYNAPSE_GRACEFUL_SHUTDOWN_EXIT_WAIT_START reason={0} base_timeout_s={1} stall_s={2} max_wait_s={3} liveness_available={4} log_path={5} ending_phase={6} remediation=the exit-wait escalates when the daemon stops producing evidence of progress, not when a constant expires (#2100)." -f `
            $Reason,
            $TimeoutSeconds,
            $StallSeconds,
            $MaxWaitSeconds,
            $livenessAvailable,
            $liveness.LogPath,
            $liveness.EndingPhase)

        do {
            Start-Sleep -Milliseconds 250
            $remainingHttpPids = @($httpProcesses | Where-Object {
                $pidValue = [int]$_.ProcessId
                $current = Get-CimInstance Win32_Process -Filter "ProcessId=$pidValue" -ErrorAction SilentlyContinue
                $exeLeaf = if ($current -and $current.ExecutablePath) { Split-Path -Leaf $current.ExecutablePath } else { '' }
                $null -ne $current -and ((Test-SynapseMcpExecutableLeafName -Name $current.Name) -or (Test-SynapseMcpExecutableLeafName -Name $exeLeaf))
            })
            if ($remainingHttpPids.Count -eq 0) {
                $exitWaitVerdict = 'exited'
                $waitedMs = [int64]((Get-Date) - $waitStarted).TotalMilliseconds
                Info ("Synapse graceful shutdown verified reason={0} http_process_count=0 waited_ms={1} extended_s={2} progress_observations={3}" -f `
                    $Reason, $waitedMs, $extendedSeconds, $progressObservations)
                Wait-SynapseBindReleased -Reason $Reason -Bind $Bind -TimeoutSeconds $TimeoutSeconds -ForceRestart:$ForceRestart
                break
            }

            $now = Get-Date
            $liveness = Get-SynapseDaemonLivenessSample -LogDir $LogDir -DbPath $DbPath
            if ($liveness.Fingerprint -ne $lastFingerprint) {
                $lastFingerprint = $liveness.Fingerprint
                $lastProgressAt = $now
                $progressObservations += 1
            }
            $stalledSeconds = [int]($now - $lastProgressAt).TotalSeconds
            $elapsedSeconds = [int]($now - $waitStarted).TotalSeconds

            # The base budget is spent. From here the wait continues ONLY while
            # the daemon keeps proving it is doing something.
            if ($elapsedSeconds -ge $TimeoutSeconds) {
                if (-not $livenessAvailable) {
                    $exitWaitVerdict = 'no_liveness_witness'
                    break
                }
                if ($stalledSeconds -ge $StallSeconds) {
                    $exitWaitVerdict = 'stalled'
                    break
                }
                if ($now -ge $hardDeadline) {
                    $exitWaitVerdict = 'ceiling'
                    break
                }
                $extendedSeconds = $elapsedSeconds - $TimeoutSeconds
                if (($now - $lastProgressLogAt).TotalSeconds -ge 5) {
                    $lastProgressLogAt = $now
                    Info ("SYNAPSE_GRACEFUL_SHUTDOWN_EXIT_WAIT_EXTENDED reason={0} elapsed_s={1} extended_s={2} stalled_s={3} stall_budget_s={4} ceiling_s={5} progress_observations={6} ending_phase={7} log_path={8} log_bytes={9}" -f `
                        $Reason,
                        $elapsedSeconds,
                        $extendedSeconds,
                        $stalledSeconds,
                        $StallSeconds,
                        $MaxWaitSeconds,
                        $progressObservations,
                        $liveness.EndingPhase,
                        $liveness.LogPath,
                        $liveness.LogLength)
                }
            }
        } while ($true)

        $remainingHttpPids = @($httpProcesses | Where-Object {
            $pidValue = [int]$_.ProcessId
            $current = Get-CimInstance Win32_Process -Filter "ProcessId=$pidValue" -ErrorAction SilentlyContinue
            $exeLeaf = if ($current -and $current.ExecutablePath) { Split-Path -Leaf $current.ExecutablePath } else { '' }
            $null -ne $current -and ((Test-SynapseMcpExecutableLeafName -Name $current.Name) -or (Test-SynapseMcpExecutableLeafName -Name $exeLeaf))
        })
        if ($remainingHttpPids.Count -gt 0) {
            $waitedMs = [int64]((Get-Date) - $waitStarted).TotalMilliseconds
            $liveness = Get-SynapseDaemonLivenessSample -LogDir $LogDir -DbPath $DbPath
            # The verdict names WHY the wait ended, which is the whole point: a
            # kill after `stalled` is a kill of a daemon that had stopped, and a
            # kill after `no_liveness_witness` says the drain could not tell and
            # fell back to the wall clock. #2100's escalation reported neither.
            $message = ("SYNAPSE_GRACEFUL_SHUTDOWN_TIMEOUT reason={0} verdict={1} base_timeout_s={2} waited_ms={3} stall_budget_s={4} ceiling_s={5} progress_observations={6} liveness_available={7} log_path={8} log_bytes={9} ending_phase={10} ending_at_unix_ms={11} remaining_count={12}`nremaining:`n{13}" -f `
                $Reason,
                $exitWaitVerdict,
                $TimeoutSeconds,
                $waitedMs,
                $StallSeconds,
                $MaxWaitSeconds,
                $progressObservations,
                $livenessAvailable,
                $liveness.LogPath,
                $liveness.LogLength,
                $liveness.EndingPhase,
                $liveness.EndingAtUnixMs,
                $remainingHttpPids.Count,
                (Format-SynapseMcpProcessSnapshot -Snapshot $remainingHttpPids))
            if ($ForceRestart) {
                Info "FORCE_RESTART: $message"
            } elseif ($EscalateAfterGracefulTimeout) {
                Info "GRACEFUL_TIMEOUT_ESCALATION: $message"
                Info "GRACEFUL_TIMEOUT_ESCALATION: escalating to identity-verified exact-PID force stop reason=$Reason (the daemon has closed its listener and retained-owner evidence is preserved in the daemon log)"
            } else {
                Die $message
            }
        }
    }

    $remaining = @(Select-SynapseMcpDeployTargetProcesses -Snapshot @(Get-SynapseMcpProcessSnapshot) -Bind $Bind -DbPath $DbPath)
    if ($remaining.Count -eq 0) {
        Wait-SynapseBindReleased -Reason $Reason -Bind $Bind -TimeoutSeconds $TimeoutSeconds -ForceRestart:$ForceRestart
        $ignoredAfter = @(Select-SynapseMcpDeployTargetProcesses -Snapshot @(Get-SynapseMcpProcessSnapshot) -Bind $Bind -DbPath $DbPath -Invert)
        Info "Synapse process stop verified reason=$Reason target_after_count=0 ignored_non_target_after_count=$($ignoredAfter.Count)"
        return
    }

    if (-not $ForceRestart -and -not $EscalateAfterGracefulTimeout) {
        Die ("SYNAPSE_PROCESS_STOP_INCOMPLETE reason={0} remaining_count={1} remaining=`n{2}" -f `
            $Reason,
            $remaining.Count,
            (Format-SynapseMcpProcessSnapshot -Snapshot $remaining))
    }

    Info ("FORCE_RESTART: exact-PID stop for remaining verified Synapse processes reason={0} remaining_count={1}`nremaining:`n{2}" -f `
        $Reason,
        $remaining.Count,
        (Format-SynapseMcpProcessSnapshot -Snapshot $remaining))
    foreach ($proc in $remaining) {
        $verified = Assert-SynapseProcessStopTarget -SnapshotProcess $proc -Bind $Bind -DbPath $DbPath
        if (-not $verified) { continue }
        $pidValue = [int]$verified.ProcessId
        # Capture the exact verified daemon identity BEFORE the stop attempt so a
        # readback can distinguish a natural exit / terminating-image ghost / PID
        # reuse from a still-live verified daemon.  CreationDate (the OS process
        # start time) is the canonical PID-reuse discriminator: a reused PID is
        # always created strictly later than the process we verified.
        $verifiedCreationDate = $verified.CreationDate
        $verifiedExecutablePath = [string]$verified.ExecutablePath
        $verifiedExecutablePathNorm = Normalize-SynapseSetupPathForCompare -Path $verifiedExecutablePath
        $verifiedCreationText = if ($verifiedCreationDate) { $verifiedCreationDate.ToString('o') } else { '<unknown>' }
        try {
            Stop-Process -Id $pidValue -Force -ErrorAction Stop
            Info "Synapse process exact-PID force stop issued pid=$pidValue reason=$Reason match_rules=$($verified.DeployTargetRules) path=$($verified.ExecutablePath) cmd=$($verified.CommandLine)"
        } catch {
            # The verified process can exit between the CIM ownership snapshot and
            # Stop-Process (e.g. Stop-Process returns "Cannot find a process with
            # the process identifier N").  Resolve that race by re-reading the exact
            # PID identity: accept success ONLY when the exact verified identity is
            # confirmed absent (PID fully gone, or the PID is now held by a
            # different process = reuse, which proves the original exited).  A live
            # or terminating-image process that still matches the verified identity
            # remains a hard stop failure and a reused live PID is never stopped
            # from stale data.
            $stopError = ($_.Exception.Message -replace '\s+', ' ').Trim()
            $afterStopError = Get-Process -Id $pidValue -ErrorAction SilentlyContinue
            # Bounded reread window (race resolution, not a stop retry): give a
            # terminating image time to clear from Win32_Process before deciding.
            $cimDeadline = (Get-Date).AddSeconds(2)
            do {
                $afterStopErrorCim = Get-CimInstance Win32_Process -Filter "ProcessId=$pidValue" -ErrorAction SilentlyContinue
                if (-not $afterStopErrorCim) { break }
                Start-Sleep -Milliseconds 100
            } while ((Get-Date) -lt $cimDeadline)
            $getProcessPresence = if ($afterStopError) { 'present' } else { 'absent' }

            if (-not $afterStopErrorCim) {
                if (-not $afterStopError) {
                    # Exact verified PID is fully gone from both process tables.
                    Info ("Synapse process exact-PID stop already satisfied pid={0} reason={1} stop_error={2} readback=Get-Process:absent,Win32_Process:absent verified_creation={3} identity=verified-target-gone" -f `
                        $pidValue, $Reason, $stopError, $verifiedCreationText)
                    continue
                }
                # Get-Process still lists the PID but Win32_Process has no row: the
                # identity cannot be re-proven, so fail closed rather than assume exit.
                Die ("SYNAPSE_PROCESS_STOP_FAILED pid={0} reason={1} error={2} readback=Get-Process:present,Win32_Process:absent verified_creation={3} remediation=the exact verified PID is still listed by Get-Process while Win32_Process reports no row; setup cannot re-prove the verified identity is gone, refuses to assume exit, and only stops verified synapse-mcp.exe PIDs; inspect process ownership and retry after the daemon exits" -f `
                    $pidValue, $Reason, $stopError, $verifiedCreationText)
            }

            # A Win32_Process row exists for the PID.  Compare its identity to the
            # exact daemon we verified before the stop attempt.
            $observedCreationDate = $afterStopErrorCim.CreationDate
            $observedCreationText = if ($observedCreationDate) { $observedCreationDate.ToString('o') } else { '<unknown>' }
            $observedExecutablePath = [string]$afterStopErrorCim.ExecutablePath
            $observedExecutablePathNorm = Normalize-SynapseSetupPathForCompare -Path $observedExecutablePath
            $identityMatches = ($null -ne $verifiedCreationDate) -and ($null -ne $observedCreationDate) -and `
                ($observedCreationDate -eq $verifiedCreationDate) -and `
                ($observedExecutablePathNorm -ieq $verifiedExecutablePathNorm)

            if (-not $identityMatches) {
                # PID reuse: the PID now (or still) belongs to a different process
                # image / start time, which proves the exact verified daemon exited.
                # The reused PID may be a live unrelated process and must NEVER be
                # stopped from stale data, nor counted as our daemon still running.
                Info ("Synapse process exact-PID stop already satisfied pid={0} reason={1} stop_error={2} readback=Get-Process:{3},Win32_Process:present identity=pid-reused verified_creation={4} observed_creation={5} verified_path={6} observed_path={7} observed_name={8} => exact verified daemon absent; leaving reused PID untouched" -f `
                    $pidValue, $Reason, $stopError, $getProcessPresence, $verifiedCreationText, $observedCreationText, $verifiedExecutablePath, $observedExecutablePath, $afterStopErrorCim.Name)
                continue
            }

            # The Win32_Process row matches the exact verified identity.
            if (-not $afterStopError) {
                Die ("SYNAPSE_PROCESS_TERMINATING_IMAGE_STILL_MAPPED pid={0} reason={1} path={2} command={3} stop_error={4} readback=Get-Process:absent,Win32_Process:present identity=verified-target-terminating verified_creation={5} observed_creation={6} remediation=the exact verified daemon is absent from Get-Process but remains in Win32_Process/tasklist with a matching start time and image path and may keep its executable image mapped; inspect the named PID and image lock, do not report it as stopped, and use a content-addressed executable handoff or restart Windows only in a coordinated maintenance window" -f `
                    $pidValue,
                    $Reason,
                    $observedExecutablePath,
                    $afterStopErrorCim.CommandLine,
                    $stopError,
                    $verifiedCreationText,
                    $observedCreationText)
            }
            Die ("SYNAPSE_PROCESS_STOP_FAILED pid={0} reason={1} error={2} readback=Get-Process:present,Win32_Process:present identity=verified-target-live verified_creation={3} observed_creation={4} path={5} remediation=the exact verified daemon is still live with a matching start time and image path; setup only stops verified synapse-mcp.exe PIDs; inspect process ownership and retry after the daemon exits" -f `
                $pidValue,
                $Reason,
                $stopError,
                $verifiedCreationText,
                $observedCreationText,
                $observedExecutablePath)
        }
    }

    $deadline = (Get-Date).AddSeconds($TimeoutSeconds)
    do {
        Start-Sleep -Milliseconds 250
        $after = @(Select-SynapseMcpDeployTargetProcesses -Snapshot @(Get-SynapseMcpProcessSnapshot) -Bind $Bind -DbPath $DbPath)
        if ($after.Count -eq 0) {
            Wait-SynapseBindReleased -Reason $Reason -Bind $Bind -TimeoutSeconds $TimeoutSeconds -ForceRestart:$ForceRestart
            $ignoredAfter = @(Select-SynapseMcpDeployTargetProcesses -Snapshot @(Get-SynapseMcpProcessSnapshot) -Bind $Bind -DbPath $DbPath -Invert)
            Info "Synapse process stop verified reason=$Reason target_after_count=0 ignored_non_target_after_count=$($ignoredAfter.Count)"
            return
        }
    } while ((Get-Date) -lt $deadline)

    $remaining = @(Select-SynapseMcpDeployTargetProcesses -Snapshot @(Get-SynapseMcpProcessSnapshot) -Bind $Bind -DbPath $DbPath)
    Die ("SYNAPSE_PROCESS_STOP_FAILED reason={0} timeout_s={1} remaining_count={2} remaining=`n{3}" -f `
        $Reason, $TimeoutSeconds, $remaining.Count, (Format-SynapseMcpProcessSnapshot -Snapshot $remaining))
}

function Get-SynapseDaemonSupervisorProcessSnapshot {
    param([Parameter(Mandatory=$true)][string]$SupervisorPath)

    $resolvedSupervisorPath = $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($SupervisorPath)
    @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue |
        Where-Object {
            $name = [string]$_.Name
            $commandLine = [string]$_.CommandLine
            ($name -ieq 'powershell.exe' -or $name -ieq 'pwsh.exe') -and
                ($commandLine.IndexOf('-File', [System.StringComparison]::OrdinalIgnoreCase) -ge 0) -and
                ($commandLine.IndexOf($resolvedSupervisorPath, [System.StringComparison]::OrdinalIgnoreCase) -ge 0)
        } |
        Select-Object ProcessId,ParentProcessId,Name,ExecutablePath,CommandLine)
}

function Format-SynapseDaemonSupervisorProcessSnapshot {
    param([AllowNull()][object[]]$Snapshot)

    if (-not $Snapshot -or $Snapshot.Count -eq 0) {
        return '<none>'
    }
    return (($Snapshot | ForEach-Object {
        "pid=$($_.ProcessId) ppid=$($_.ParentProcessId) name=$($_.Name) path=$($_.ExecutablePath) cmd=$($_.CommandLine)"
    }) -join "`n")
}

# #2092: when a drain times out waiting for the supervisor to park, "it did not
# park" is not a diagnosis. The supervisor's own last ledger line says whether it
# never saw the stop-request, saw it and threw, or is sitting in a restart
# backoff -- three different remediations. Read-only and never fatal: a missing
# or unreadable ledger is reported as such, because this runs on a path that is
# already failing.
function Get-SynapseDaemonSupervisorLastEventText {
    param([Parameter(Mandatory=$true)][string]$LogDir)

    $eventsPath = Join-Path $LogDir 'daemon-supervisor-events.jsonl'
    if (-not (Test-Path -LiteralPath $eventsPath -PathType Leaf)) {
        return "<missing:$eventsPath>"
    }
    try {
        $last = Get-Content -LiteralPath $eventsPath -Tail 1 -ErrorAction Stop
        if ([string]::IsNullOrWhiteSpace($last)) { return "<empty:$eventsPath>" }
        return ($last -replace '\s+', ' ').Trim()
    } catch {
        return "<unreadable:$eventsPath error=$($_.Exception.Message)>"
    }
}

function Stop-SynapseDaemonSupervisorProcessesForInstallHandoff {
    param(
        [Parameter(Mandatory=$true)][string]$SupervisorPath,
        [Parameter(Mandatory=$true)]$LegacySnapshot,
        [Parameter(Mandatory=$true)]$LegacyDenialTransition,
        [int]$TimeoutSeconds = 20
    )

    $supervisorFull=[System.IO.Path]::GetFullPath($SupervisorPath)
    $declaredSupervisor=Get-SynapseLegacyDenialProbeLauncherObjectExact -LegacySnapshot $LegacySnapshot -Role 'legacy_supervisor'
    $protectedPowerShell=Get-SynapseLegacyDenialProbeLauncherObjectExact -LegacySnapshot $LegacySnapshot -Role 'legacy_supervisor_interpreter'
    if([System.IO.Path]::GetFullPath([string]$declaredSupervisor.path) -ine $supervisorFull){
        Die "SYNAPSE_SUPERVISOR_STOP_SNAPSHOT_PATH_MISMATCH expected=$($declaredSupervisor.path) actual=$supervisorFull"
    }
    [void](Assert-SynapseLegacyAuthoritySnapshotUnchanged -Snapshot $LegacySnapshot -LegacyDenialTransition $LegacyDenialTransition)
    $denialCut=Get-SynapseAuthorityControlTransitionPhysicalCut -Transition $LegacyDenialTransition -Context 'install_handoff_supervisor_denial'
    if([string]$denialCut.PostLocation-cne'canonical' -or $null-eq$LegacyDenialTransition.CanonicalLease){Die "SYNAPSE_SUPERVISOR_STOP_DENIAL_AUTHORITY_NOT_CANONICAL supervisor_path=$supervisorFull post_location=$($denialCut.PostLocation)"}
    $LegacyDenialTransition.CanonicalLease.RequireExact('install_handoff_supervisor_denial')
    $before = @(Get-SynapseLegacyDenialProbeActionProcessSnapshot -LegacySnapshot $LegacySnapshot -Context 'install_handoff_supervisor_snapshot' | Where-Object {[string]$_.Role -ceq 'legacy_supervisor_interpreter'})
    if ($before.Count -eq 0) {
        Info "Synapse daemon supervisor stop not needed before binary handoff: supervisor_path=$supervisorFull"
        return
    }
    if($before.Count -ne 1){Die "SYNAPSE_SUPERVISOR_STOP_CARDINALITY_INVALID supervisor_path=$supervisorFull count=$($before.Count)"}

    Info ("Synapse daemon supervisor exact-identity stop requested before binary handoff count={0}`nsupervisors:`n{1}" -f `
        $before.Count,
        (Format-SynapseDaemonSupervisorProcessSnapshot -Snapshot $before))

    foreach ($identity in $before) {
        $pidValue = [int]$identity.ProcessId
        if ($pidValue -eq $PID) {
            Die "SYNAPSE_SUPERVISOR_STOP_REFUSED_SELF pid=$pidValue supervisor_path=$supervisorFull remediation=setup refused to stop its own process while preparing daemon handoff"
        }
        if([string]$identity.ParentRelation -cne 'exact_wscript_parent'){
            Die "SYNAPSE_SUPERVISOR_STOP_PARENT_AUTHORITY_UNPROVEN pid=$pidValue parent_pid=$($identity.ParentProcessId) relation=$($identity.ParentRelation)"
        }
        $mappedLease=$null;$primary=''
        try {
            $protected=$protectedPowerShell.protected_os
            $mappedLease=[SynapseAuthorityRuntime.MappedProcessLease]::OpenProtectedOsForTermination([uint32]$pidValue,0L,[string]$protectedPowerShell.path,[string]$protectedPowerShell.file_id_128,[string]$protectedPowerShell.sha256,[int64]$protectedPowerShell.length,[uint32]$protected.link_count,[string]$protected.security_descriptor_sddl,[string[]]@($protected.hardlink_paths),'install_handoff_supervisor_mapped')
            $creation=[int64]$mappedLease.CreationTimeFileTime
            if(-not $mappedLease.RequireExactOrTerminal('install_handoff_supervisor_initial_state')){
                [SynapseAuthorityRuntime.MappedProcessLease]::RequireIdentityGone([uint32]$pidValue,[int64]$creation,'install_handoff_supervisor_already_terminal')
                Info "Synapse daemon supervisor exited before retained-handle stop pid=$pidValue creation_filetime_utc=$creation supervisor_path=$supervisorFull"
                continue
            }
            [void](Assert-SynapseMappedProcessMetadataUnderLease -Lease $mappedLease -ExpectedProcessId $pidValue -ExpectedParentProcessId ([int]$identity.ParentProcessId) -ExpectedSessionId ([int]$identity.SessionId) -ExpectedImagePath ([string]$protectedPowerShell.path) -ExpectedCommandLine ([string]$identity.CommandLine) -ExpectedCreationDate ([string]$identity.CreationDate) -Context 'install_handoff_supervisor_boundary')
            Ensure-SynapseWindowsCommandLineArgvType
            $nativeCommandLine=$mappedLease.ReadCommandLine('install_handoff_supervisor_native_command_line')
            $nativeArgv=@([SynapseSetup.WindowsCommandLineArgv]::Parse($nativeCommandLine))
            $expectedArgv=@([System.IO.Path]::GetFullPath([string]$protectedPowerShell.path),'-NoProfile','-ExecutionPolicy','Bypass','-File',$supervisorFull)
            if($nativeArgv.Count-ne$expectedArgv.Count){Die "SYNAPSE_SUPERVISOR_STOP_NATIVE_ARGV_COUNT_INVALID pid=$pidValue expected=$($expectedArgv.Count) actual=$($nativeArgv.Count)"}
            for($argvIndex=0;$argvIndex-lt$expectedArgv.Count;$argvIndex++){
                $argvMatches=if($argvIndex-in@(0,5)){[System.IO.Path]::GetFullPath([string]$nativeArgv[$argvIndex])-ieq[System.IO.Path]::GetFullPath([string]$expectedArgv[$argvIndex])}else{[string]$nativeArgv[$argvIndex]-ceq[string]$expectedArgv[$argvIndex]}
                if(-not$argvMatches){Die "SYNAPSE_SUPERVISOR_STOP_NATIVE_ARGV_INVALID pid=$pidValue index=$argvIndex expected=$($expectedArgv[$argvIndex]) actual=$($nativeArgv[$argvIndex])"}
            }
            if([string]$nativeCommandLine-cne[string]$identity.CommandLine){Die "SYNAPSE_SUPERVISOR_STOP_NATIVE_COMMAND_LINE_DRIFT pid=$pidValue"}
            [void](Assert-SynapseLegacyAuthoritySnapshotUnchanged -Snapshot $LegacySnapshot -LegacyDenialTransition $LegacyDenialTransition)
            $LegacyDenialTransition.CanonicalLease.RequireExact('install_handoff_supervisor_denial_before_terminate')
            $recheck=@(Get-SynapseLegacyDenialProbeActionProcessSnapshot -LegacySnapshot $LegacySnapshot -Context 'install_handoff_supervisor_destructive_recheck'|Where-Object{[int]$_.ProcessId-eq$pidValue -and [string]$_.Role-ceq'legacy_supervisor_interpreter'})
            if($recheck.Count-ne 1 -or [int64]$recheck[0].CreationMicroseconds-ne[int64]$identity.CreationMicroseconds -or [string]$recheck[0].CommandLine-cne[string]$identity.CommandLine -or
               (Get-SynapseCanonicalJson -Value @($recheck[0].Arguments))-cne(Get-SynapseCanonicalJson -Value @($identity.Arguments)) -or [string]$recheck[0].ParentRelation-cne'exact_wscript_parent'){
                Die "SYNAPSE_SUPERVISOR_STOP_DESTRUCTIVE_IDENTITY_DRIFT pid=$pidValue count=$($recheck.Count)"
            }
            $mappedLease.RequireExact('install_handoff_supervisor_immediately_before_kill')
            $nativeCommandLineAtKill=$mappedLease.ReadCommandLine('install_handoff_supervisor_native_command_line_at_kill')
            if([string]$nativeCommandLineAtKill-cne[string]$nativeCommandLine){Die "SYNAPSE_SUPERVISOR_STOP_NATIVE_COMMAND_LINE_CHANGED_AT_KILL pid=$pidValue"}
            $exitCode=$mappedLease.TerminateAndWait([uint32]($TimeoutSeconds*1000),[uint32]127,'install_handoff_supervisor_terminate')
            [SynapseAuthorityRuntime.MappedProcessLease]::RequireIdentityGone([uint32]$pidValue,[int64]$creation,'install_handoff_supervisor_post_kill')
            Info "Synapse daemon supervisor retained-handle stop verified pid=$pidValue creation_filetime_utc=$creation exit_code=$exitCode supervisor_path=$supervisorFull"
        } catch {
            $primary=$_.Exception.Message
            throw
        } finally {
            if($null-ne$mappedLease){try{$mappedLease.Dispose()}catch{[Environment]::FailFast("SYNAPSE_SUPERVISOR_STOP_MAPPED_LEASE_RELEASE_UNPROVEN pid=$pidValue primary=[$primary]",$_.Exception)}}
        }
    }
    [void](Assert-SynapseLegacyAuthoritySnapshotUnchanged -Snapshot $LegacySnapshot -LegacyDenialTransition $LegacyDenialTransition)
    $LegacyDenialTransition.CanonicalLease.RequireExact('install_handoff_supervisor_denial_after_terminate')
    $after=@(Get-SynapseLegacyDenialProbeActionProcessSnapshot -LegacySnapshot $LegacySnapshot -Context 'install_handoff_supervisor_post_stop'|Where-Object{[string]$_.Role-ceq'legacy_supervisor_interpreter'})
    if($after.Count-ne 0){Die "SYNAPSE_SUPERVISOR_STOP_POSTCONDITION_FAILED supervisor_path=$supervisorFull remaining=$($after.Count)"}
}

function Assert-SynapseDaemonTaskRestartAuthorityIdentity {
    param(
        [Parameter(Mandatory=$true)][string]$TaskName,
        [Parameter(Mandatory=$true)][string]$SupervisorPath,
        [Parameter(Mandatory=$true)][string]$Reason
    )

    $task = Get-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue
    if (-not $task) {
        Info "Synapse daemon scheduled task identity preflight: task=$TaskName reason=$Reason task_present=false"
        return $null
    }

    # The canonical task starts the setup-built native bootstrap. The bootstrap
    # establishes the lifetime parent Job before any managed supervisor code is
    # launched. Pre-migration installs used direct PowerShell or a resident
    # WScript wrapper; accept those exact shapes only to prove ownership during
    # a repair handoff, never for live adoption.
    $launcherDir = Split-Path -Parent $SupervisorPath
    $expectedBootstrapPath = Join-Path $launcherDir 'synapse-supervisor-bootstrap.exe'
    $expectedPowerShellPath = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
    $expectedDirectArguments = '-NoProfile -ExecutionPolicy Bypass -File "{0}"' -f ([System.IO.Path]::GetFullPath($SupervisorPath))
    $expectedBootstrapArguments = Get-SynapseSupervisorBootstrapTaskArgumentText `
        -PowerShellPath $expectedPowerShellPath `
        -SupervisorPath $SupervisorPath `
        -WorkingDirectory $launcherDir `
        -LogPath (Join-Path $LogDir 'daemon-supervisor-bootstrap.log')
    $expectedWscriptPath = Join-Path $env:SystemRoot 'System32\wscript.exe'
    $candidateLauncherDirs = @($launcherDir)
    $legacyLauncherDir = $LogDir
    if (-not [string]::IsNullOrWhiteSpace($legacyLauncherDir) -and
        ([System.IO.Path]::GetFullPath($legacyLauncherDir).TrimEnd('\') -ine [System.IO.Path]::GetFullPath($launcherDir).TrimEnd('\'))) {
        $candidateLauncherDirs += $legacyLauncherDir
    }

    $actions = @($task.Actions)
    if ($actions.Count -ne 1) {
        Die "SYNAPSE_TASK_HANDOFF_IDENTITY_MISMATCH task=$TaskName reason=$Reason expected_action_count=1 actual_action_count=$($actions.Count) remediation=the named task is not the single setup-owned Synapse daemon launcher; inspect the Task Scheduler action SoT and remove only the verified owner"
    }

    $action = $actions[0]
    $actualExecutablePath = try {
        [System.IO.Path]::GetFullPath([Environment]::ExpandEnvironmentVariables([string]$action.Execute))
    } catch {
        [string]$action.Execute
    }
    $actualWorkingDirectory = try {
        [System.IO.Path]::GetFullPath([Environment]::ExpandEnvironmentVariables([string]$action.WorkingDirectory)).TrimEnd('\')
    } catch {
        [string]$action.WorkingDirectory
    }

    $matchedLauncherDir = $null
    $isNativeBootstrap = $actualExecutablePath -ieq [System.IO.Path]::GetFullPath($expectedBootstrapPath) -and
        ([string]$action.Arguments -ceq $expectedBootstrapArguments) -and
        $actualWorkingDirectory -ieq [System.IO.Path]::GetFullPath($launcherDir).TrimEnd('\')
    $isDirectSupervisor = $actualExecutablePath -ieq [System.IO.Path]::GetFullPath($expectedPowerShellPath) -and
        ([string]$action.Arguments -ceq $expectedDirectArguments) -and
        $actualWorkingDirectory -ieq [System.IO.Path]::GetFullPath($launcherDir).TrimEnd('\')
    if ($isNativeBootstrap -or $isDirectSupervisor) {
        $matchedLauncherDir = [System.IO.Path]::GetFullPath($launcherDir).TrimEnd('\')
    }
    foreach ($candidateDir in $candidateLauncherDirs) {
        if ($isNativeBootstrap -or $isDirectSupervisor) { break }
        $candidateLauncher = Join-Path $candidateDir 'synapse-daemon-launch-hidden.vbs'
        $candidateArguments = '//B //Nologo "{0}"' -f $candidateLauncher
        $candidateWorkingDirectory = [System.IO.Path]::GetFullPath($candidateDir).TrimEnd('\')
        if ($actualExecutablePath -ieq [System.IO.Path]::GetFullPath($expectedWscriptPath) -and
            ([string]$action.Arguments -ceq $candidateArguments) -and
            $actualWorkingDirectory -ieq $candidateWorkingDirectory) {
            $matchedLauncherDir = $candidateWorkingDirectory
            break
        }
    }

    if (-not $matchedLauncherDir) {
        $legacyArgumentRendering = (@($candidateLauncherDirs | ForEach-Object { '//B //Nologo "{0}"' -f (Join-Path $_ 'synapse-daemon-launch-hidden.vbs') }) -join ' | ')
        Die ("SYNAPSE_TASK_HANDOFF_IDENTITY_MISMATCH task={0} reason={1} expected_bootstrap_execute={2} expected_bootstrap_arguments={3} legacy_powershell_execute={4} legacy_powershell_arguments={5} legacy_wscript_execute={6} accepted_legacy_wscript_arguments={7} actual_execute={8} actual_arguments={9} accepted_working_directories={10} actual_working_directory={11} remediation=the named task action is neither the exact setup-owned native bootstrap nor an exact pre-migration launcher; inspect Task Scheduler and refuse to stop or unregister an unverified task" -f `
            $TaskName,
            $Reason,
            $expectedBootstrapPath,
            $expectedBootstrapArguments,
            $expectedPowerShellPath,
            $expectedDirectArguments,
            $expectedWscriptPath,
            $legacyArgumentRendering,
            $actualExecutablePath,
            [string]$action.Arguments,
            (@($candidateLauncherDirs) -join ' | '),
            $action.WorkingDirectory)
    }

    $isLegacyLayout = -not $isNativeBootstrap
    if ($isLegacyLayout) {
        Warn "SYNAPSE_TASK_HANDOFF_LEGACY_LAUNCHER_LAYOUT task=$TaskName reason=$Reason matched_launcher_dir=$matchedLauncherDir current_launcher_dir=$([System.IO.Path]::GetFullPath($launcherDir).TrimEnd('\')) effect=ownership accepted solely for broker migration; the exact retained legacy action is permanently denied by the broker-adoption stop epoch and is never re-registered, enabled, or deleted"
    }
    $task | Add-Member -NotePropertyName SynapseNativeBootstrapAction -NotePropertyValue ([bool]$isNativeBootstrap) -Force
    $task | Add-Member -NotePropertyName SynapseLegacyDirectPowerShellAction -NotePropertyValue ([bool]$isDirectSupervisor) -Force
    Info "Synapse daemon scheduled task identity preflight verified: task=$TaskName state=$($task.State) reason=$Reason native_prebound_bootstrap=$isNativeBootstrap legacy_direct_powershell_supervisor=$isDirectSupervisor matched_launcher_dir=$matchedLauncherDir legacy_layout=$isLegacyLayout"
    return $task
}

function New-SynapseLegacyVbsLauncherContent {
    param(
        [Parameter(Mandatory=$true)][string]$LauncherLogPath,
        [Parameter(Mandatory=$true)][string]$SupervisorPath,
        [Parameter(Mandatory=$true)][string]$PowerShellPath
    )
    $launcherLog=[System.IO.Path]::GetFullPath($LauncherLogPath)
    $supervisor=[System.IO.Path]::GetFullPath($SupervisorPath)
    $powershell=[System.IO.Path]::GetFullPath($PowerShellPath)
    foreach($value in @($launcherLog,$supervisor,$powershell)){
        if($value.IndexOf('"',[System.StringComparison]::Ordinal) -ge 0 -or $value.IndexOf("`r",[System.StringComparison]::Ordinal) -ge 0 -or $value.IndexOf("`n",[System.StringComparison]::Ordinal) -ge 0){
            Die "SYNAPSE_BROKER_ADOPTION_LEGACY_VBS_PATH_INVALID path=$value"
        }
    }
    # This is the sole historical wrapper shape admitted for broker adoption.
    # Deliberately preserve its original LF body plus terminal CRLF: the exact
    # bytes, not a substring/AST approximation, establish that the wrapper does
    # nothing except synchronously invoke the canonical supervisor and relay its
    # result.  Other legacy/native shapes are preserved and refused.
    $lines=@(
        'Option Explicit',
        'Dim shell, fso, launcherLog, supervisorCommand, exitCode',
        '',
        'Set shell = CreateObject("WScript.Shell")',
        'Set fso = CreateObject("Scripting.FileSystemObject")',
        ('launcherLog = "{0}"' -f $launcherLog),
        ('supervisorCommand = "{0} -NoProfile -ExecutionPolicy Bypass -File {1}"' -f $powershell,$supervisor),
        '',
        'Sub LogLine(message)',
        '  Dim logFile',
        '  Set logFile = fso.OpenTextFile(launcherLog, 8, True)',
        '  logFile.WriteLine Now & " " & message',
        '  logFile.Close',
        'End Sub',
        '',
        'LogLine "SYNAPSE_DAEMON_WRAPPER_START command=" & supervisorCommand',
        'exitCode = shell.Run(supervisorCommand, 0, True)',
        'LogLine "SYNAPSE_DAEMON_WRAPPER_EXIT exit_code=" & exitCode',
        'WScript.Quit exitCode'
    )
    return (($lines -join "`n") + "`r`n")
}

function Resolve-SynapseTaskAccountSid {
    param(
        [Parameter(Mandatory=$true)][string]$Account,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $value=$Account.Trim()
    if($value -match '^S-1-(?:\d+-)+\d+$'){return $value}
    $candidates=@($value)
    if($value.IndexOf('\',[System.StringComparison]::Ordinal) -lt 0 -and -not [string]::IsNullOrWhiteSpace($env:USERDOMAIN)){
        $candidates+=,"$($env:USERDOMAIN)\$value"
    }
    $resolved=@()
    foreach($candidate in $candidates){
        try{$resolved+=,([System.Security.Principal.NTAccount]::new($candidate).Translate([System.Security.Principal.SecurityIdentifier]).Value)}catch{}
    }
    $unique=@($resolved|Sort-Object -Unique)
    if($unique.Count -ne 1){Die "SYNAPSE_LEGACY_TASK_ACCOUNT_SID_UNRESOLVED context=$Context account=$Account resolved=$($unique-join ',')"}
    return [string]$unique[0]
}

function Get-SynapseTaskSemanticAccountLeaf {
    param(
        [Parameter(Mandatory=$true)][string]$Account,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $resolvedSid=Resolve-SynapseTaskAccountSid -Account $Account -Context $Context
    $identity=[System.Security.Principal.WindowsIdentity]::GetCurrent()
    $currentSid=[string]$identity.User.Value
    $currentName=[string]$identity.Name
    if($resolvedSid -cne $currentSid -or [string]::IsNullOrWhiteSpace($currentName)){
        Die "SYNAPSE_TASK_SEMANTIC_ACCOUNT_NOT_CURRENT context=$Context account=$Account resolved_sid=$resolvedSid current_sid=$currentSid current_name=$currentName"
    }
    $separator=$currentName.LastIndexOf('\')
    $leaf=if($separator -ge 0){$currentName.Substring($separator+1)}else{$currentName}
    if([string]::IsNullOrWhiteSpace($leaf) -or $leaf.IndexOf('\') -ge 0){
        Die "SYNAPSE_TASK_SEMANTIC_ACCOUNT_LEAF_INVALID context=$Context current_name=$currentName leaf=$leaf"
    }
    return $leaf
}

function Get-SynapseLegacyDirectRescueSchedulerContract {
    param(
        [Parameter(Mandatory=$true)]$RegisteredTask,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $definition=$RegisteredTask.Definition
    if($null -eq $definition){Die "SYNAPSE_LEGACY_DIRECT_RESCUE_TASK_DEFINITION_MISSING context=$Context"}
    $triggers=@($definition.Triggers)
    if($triggers.Count -ne 1){Die "SYNAPSE_LEGACY_DIRECT_RESCUE_TRIGGER_COUNT_INVALID context=$Context count=$($triggers.Count) expected=1"}
    $trigger=$triggers[0]
    if([int]$trigger.Type -ne 9){Die "SYNAPSE_LEGACY_DIRECT_RESCUE_TRIGGER_TYPE_INVALID context=$Context type=$([int]$trigger.Type) expected=9"}
    $repetition=$trigger.Repetition
    if($null -eq $repetition){Die "SYNAPSE_LEGACY_DIRECT_RESCUE_TRIGGER_REPETITION_INTERFACE_MISSING context=$Context"}
    $triggerDelay=[string]$trigger.Delay
    $triggerStart=[string]$trigger.StartBoundary
    $triggerEnd=[string]$trigger.EndBoundary
    $repetitionInterval=[string]$repetition.Interval
    $repetitionDuration=[string]$repetition.Duration
    $repetitionStop=[bool]$repetition.StopAtDurationEnd
    if(-not [bool]$trigger.Enabled -or -not [string]::IsNullOrEmpty($triggerDelay) -or
       -not [string]::IsNullOrEmpty($triggerStart) -or -not [string]::IsNullOrEmpty($triggerEnd) -or
       -not [string]::IsNullOrEmpty($repetitionInterval) -or -not [string]::IsNullOrEmpty($repetitionDuration) -or $repetitionStop){
        Die "SYNAPSE_LEGACY_DIRECT_RESCUE_LOGON_TRIGGER_NOT_ONE_SHOT context=$Context enabled=$($trigger.Enabled) delay=$triggerDelay start=$triggerStart end=$triggerEnd repetition_interval=$repetitionInterval repetition_duration=$repetitionDuration repetition_stop=$repetitionStop"
    }
    $principal=$definition.Principal
    $settings=$definition.Settings
    if($null -eq $principal -or $null -eq $settings){Die "SYNAPSE_LEGACY_DIRECT_RESCUE_TASK_INTERFACE_MISSING context=$Context"}
    $currentSid=[System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value
    $triggerSid=Resolve-SynapseTaskAccountSid -Account ([string]$trigger.UserId) -Context "${Context}_trigger"
    $principalSid=Resolve-SynapseTaskAccountSid -Account ([string]$principal.UserId) -Context "${Context}_principal"
    if($triggerSid -cne $currentSid -or $principalSid -cne $currentSid -or [int]$principal.LogonType -ne 3 -or [int]$principal.RunLevel -ne 0){
        Die "SYNAPSE_LEGACY_DIRECT_RESCUE_PRINCIPAL_INVALID context=$Context current_sid=$currentSid trigger_sid=$triggerSid principal_sid=$principalSid logon_type=$([int]$principal.LogonType) run_level=$([int]$principal.RunLevel)"
    }
    $restartCount=[int]$settings.RestartCount
    $restartInterval=[string]$settings.RestartInterval
    $restartIntervalTicks=0L
    if($restartCount -lt 0 -or $restartCount -gt 3){Die "SYNAPSE_LEGACY_DIRECT_RESCUE_RESTART_COUNT_INVALID context=$Context count=$restartCount max=3"}
    if($restartCount -eq 0){
        if(-not [string]::IsNullOrEmpty($restartInterval)){Die "SYNAPSE_LEGACY_DIRECT_RESCUE_RESTART_INTERVAL_WITHOUT_COUNT context=$Context interval=$restartInterval"}
    }else{
        try{$restartSpan=[System.Xml.XmlConvert]::ToTimeSpan($restartInterval)}catch{Die "SYNAPSE_LEGACY_DIRECT_RESCUE_RESTART_INTERVAL_INVALID context=$Context interval=$restartInterval error=$($_.Exception.Message)"}
        if($restartSpan -le [TimeSpan]::Zero -or $restartSpan -gt [TimeSpan]::FromMinutes(5)){Die "SYNAPSE_LEGACY_DIRECT_RESCUE_RESTART_INTERVAL_BOUND_INVALID context=$Context interval=$restartInterval max=PT5M"}
        $restartIntervalTicks=[int64]$restartSpan.Ticks
    }
    if(-not [bool]$settings.Enabled -or [int]$settings.MultipleInstances -ne 2 -or [bool]$settings.RunOnlyIfNetworkAvailable -or
       [bool]$settings.RunOnlyIfIdle -or [bool]$settings.WakeToRun){
        Die "SYNAPSE_LEGACY_DIRECT_RESCUE_SETTINGS_INVALID context=$Context enabled=$($settings.Enabled) multiple=$([int]$settings.MultipleInstances) network=$($settings.RunOnlyIfNetworkAvailable) idle=$($settings.RunOnlyIfIdle) wake=$($settings.WakeToRun)"
    }
    $maintenancePresent=$false
    $maintenanceProperty=$settings.PSObject.Properties['MaintenanceSettings']
    if($null -ne $maintenanceProperty){
        try{$maintenance=$settings.MaintenanceSettings}catch{Die "SYNAPSE_LEGACY_DIRECT_RESCUE_MAINTENANCE_READ_FAILED context=$Context error=$($_.Exception.Message)"}
        $maintenancePresent=$null -ne $maintenance
    }
    if($maintenancePresent){Die "SYNAPSE_LEGACY_DIRECT_RESCUE_MAINTENANCE_PRESENT context=$Context"}
    return [ordered]@{
        schema='synapse_legacy_direct_rescue_scheduler_contract/v1';current_user_sid=$currentSid
        trigger_count=1;trigger_type=9;trigger_id=[string]$trigger.Id;trigger_enabled=$true;trigger_user_id=[string]$trigger.UserId;trigger_user_sid=$triggerSid
        trigger_delay='';trigger_start_boundary='';trigger_end_boundary='';repetition_interval='';repetition_duration='';repetition_stop_at_duration_end=$false
        principal_id=[string]$principal.Id;principal_user_id=[string]$principal.UserId;principal_user_sid=$principalSid;principal_logon_type=3;principal_run_level=0
        settings_enabled=$true;multiple_instances=2;restart_count=$restartCount;restart_interval=$restartInterval;restart_interval_ticks=$restartIntervalTicks
        start_when_available=[bool]$settings.StartWhenAvailable;run_only_if_network_available=$false;run_only_if_idle=$false;wake_to_run=$false;allow_demand_start=[bool]$settings.AllowDemandStart
        external_demand_start_excluded_nonhostile_same_user=$true
        maintenance_present=$false;compatibility=[int]$settings.Compatibility
    }
}

function Assert-SynapseLegacyDirectRescueSchedulerContractDescriptor {
    param(
        [Parameter(Mandatory=$true)]$Contract,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $expected=@('schema','current_user_sid','trigger_count','trigger_type','trigger_id','trigger_enabled','trigger_user_id','trigger_user_sid','trigger_delay','trigger_start_boundary','trigger_end_boundary','repetition_interval','repetition_duration','repetition_stop_at_duration_end','principal_id','principal_user_id','principal_user_sid','principal_logon_type','principal_run_level','settings_enabled','multiple_instances','restart_count','restart_interval','restart_interval_ticks','start_when_available','run_only_if_network_available','run_only_if_idle','wake_to_run','allow_demand_start','external_demand_start_excluded_nonhostile_same_user','maintenance_present','compatibility')
    $names=if($Contract -is [System.Collections.IDictionary]){
        @($Contract.Keys|ForEach-Object{[string]$_})
    }else{
        @($Contract.PSObject.Properties.Name)
    }
    if($names.Count -ne $expected.Count -or @($names|Where-Object{$expected -cnotcontains $_}).Count -gt 0 -or
       [string]$Contract.schema -cne 'synapse_legacy_direct_rescue_scheduler_contract/v1' -or
       [string]$Contract.current_user_sid -notmatch '^S-1-(?:\d+-)+\d+$' -or [int]$Contract.trigger_count -ne 1 -or [int]$Contract.trigger_type -ne 9 -or -not [bool]$Contract.trigger_enabled -or
       [string]$Contract.trigger_user_sid -cne [string]$Contract.current_user_sid -or [string]$Contract.principal_user_sid -cne [string]$Contract.current_user_sid -or
       -not [string]::IsNullOrEmpty([string]$Contract.trigger_delay) -or -not [string]::IsNullOrEmpty([string]$Contract.trigger_start_boundary) -or -not [string]::IsNullOrEmpty([string]$Contract.trigger_end_boundary) -or
       -not [string]::IsNullOrEmpty([string]$Contract.repetition_interval) -or -not [string]::IsNullOrEmpty([string]$Contract.repetition_duration) -or [bool]$Contract.repetition_stop_at_duration_end -or
       [int]$Contract.principal_logon_type -ne 3 -or [int]$Contract.principal_run_level -ne 0 -or -not [bool]$Contract.settings_enabled -or [int]$Contract.multiple_instances -ne 2 -or
       [int]$Contract.restart_count -lt 0 -or [int]$Contract.restart_count -gt 3 -or [int64]$Contract.restart_interval_ticks -lt 0 -or
       [bool]$Contract.run_only_if_network_available -or [bool]$Contract.run_only_if_idle -or [bool]$Contract.wake_to_run -or -not [bool]$Contract.external_demand_start_excluded_nonhostile_same_user -or [bool]$Contract.maintenance_present){
        Die "SYNAPSE_LEGACY_DIRECT_RESCUE_SCHEDULER_CONTRACT_INVALID context=$Context"
    }
    if([int]$Contract.restart_count -eq 0){
        if(-not [string]::IsNullOrEmpty([string]$Contract.restart_interval) -or [int64]$Contract.restart_interval_ticks -ne 0){Die "SYNAPSE_LEGACY_DIRECT_RESCUE_SCHEDULER_RESTART_ZERO_INVALID context=$Context"}
    }else{
        try{$span=[System.Xml.XmlConvert]::ToTimeSpan([string]$Contract.restart_interval)}catch{Die "SYNAPSE_LEGACY_DIRECT_RESCUE_SCHEDULER_RESTART_INTERVAL_INVALID context=$Context error=$($_.Exception.Message)"}
        if($span -le [TimeSpan]::Zero -or $span -gt [TimeSpan]::FromMinutes(5) -or [int64]$Contract.restart_interval_ticks -ne [int64]$span.Ticks){Die "SYNAPSE_LEGACY_DIRECT_RESCUE_SCHEDULER_RESTART_BOUND_INVALID context=$Context interval=$($Contract.restart_interval)"}
    }
    return (ConvertTo-SynapseCanonicalValue -Value $Contract)
}

function Read-SynapseLegacyDirectRescueTaskRuntimeState {
    param(
        [Parameter(Mandatory=$true)]$LegacySnapshot,
        [Parameter(Mandatory=$true)][string]$Context,
        $LegacyDenialTransition
    )
    [void](Assert-SynapseLegacyAuthoritySnapshotUnchanged -Snapshot $LegacySnapshot -LegacyDenialTransition $LegacyDenialTransition)
    $lookup=Get-SynapseScheduledTaskLookupExact -Name ([string]$LegacySnapshot.name)
    if(-not [bool]$lookup.Exists){Die "SYNAPSE_LEGACY_DIRECT_RESCUE_TASK_ABSENT context=$Context task=$($LegacySnapshot.name)"}
    $registered=$lookup.Task
    try{
        $state=[int]$registered.State
        $lastRun=[datetime]$registered.LastRunTime
        $lastResult=[int64]$registered.LastTaskResult
        $nextRun=[datetime]$registered.NextRunTime
        $instances=@($registered.GetInstances(0))
    }catch{Die "SYNAPSE_LEGACY_DIRECT_RESCUE_TASK_RUNTIME_READ_FAILED context=$Context task=$($LegacySnapshot.name) error=$($_.Exception.Message)"}
    if($instances.Count -gt 4){Die "SYNAPSE_LEGACY_DIRECT_RESCUE_TASK_INSTANCE_BOUND_EXCEEDED context=$Context task=$($LegacySnapshot.name) count=$($instances.Count) max=4"}
    $instanceRecords=@()
    foreach($instance in $instances){
        try{$instanceRecords+=,[ordered]@{instance_guid=[string]$instance.InstanceGuid;engine_pid=[int]$instance.EnginePID;current_action=[string]$instance.CurrentAction}}
        catch{Die "SYNAPSE_LEGACY_DIRECT_RESCUE_TASK_INSTANCE_READ_FAILED context=$Context task=$($LegacySnapshot.name) error=$($_.Exception.Message)"}
    }
    $nextPresent=$nextRun.Year -ge 2000
    return [pscustomobject][ordered]@{
        Schema='synapse_legacy_direct_rescue_task_runtime/v1';TaskName=[string]$LegacySnapshot.name;State=$state
        LastRunTimeUtc=$lastRun.ToUniversalTime().ToString('o');LastRunTimeFileTimeUtc=[int64]$lastRun.ToUniversalTime().ToFileTimeUtc();LastTaskResult=$lastResult
        NextRunTimePresent=$nextPresent;NextRunTimeUtc=$(if($nextPresent){$nextRun.ToUniversalTime().ToString('o')}else{''})
        InstanceCount=$instances.Count;Instances=@($instanceRecords)
    }
}

function Assert-SynapseLegacyDirectRescueControlHeld {
    param(
        [Parameter(Mandatory=$true)]$LegacyGateTransition,
        [Parameter(Mandatory=$true)]$LegacyDenialTransition,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $gateCut=Get-SynapseAuthorityControlTransitionPhysicalCut -Transition $LegacyGateTransition -Context "${Context}_gate"
    $denialCut=Get-SynapseAuthorityControlTransitionPhysicalCut -Transition $LegacyDenialTransition -Context "${Context}_denial"
    if([string]$gateCut.PostLocation -cne 'canonical' -or [string]$denialCut.PostLocation -cne 'canonical'){
        Die "SYNAPSE_LEGACY_DIRECT_RESCUE_CONTROL_NOT_HELD context=$Context gate_post=$($gateCut.PostLocation) denial_post=$($denialCut.PostLocation)"
    }
    if($null -eq $LegacyGateTransition.CanonicalLease -or $null -eq $LegacyDenialTransition.CanonicalLease){Die "SYNAPSE_LEGACY_DIRECT_RESCUE_CONTROL_LEASE_MISSING context=$Context"}
    $LegacyGateTransition.CanonicalLease.RequireExact("${Context}_gate")
    $LegacyDenialTransition.CanonicalLease.RequireExact("${Context}_denial")
}

function Wait-SynapseLegacySchedulerRetryHorizonExhausted {
    param(
        [Parameter(Mandatory=$true)]$LegacySnapshot,
        [Parameter(Mandatory=$true)]$LegacyGateTransition,
        [Parameter(Mandatory=$true)]$LegacyDenialTransition,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$DbPath,
        [Parameter(Mandatory=$true)][string]$SupervisorPath,
        [Parameter(Mandatory=$true)][string]$Context,
        [ValidateRange(5,60)][int]$MarginSeconds=15
    )
    $contract=Assert-SynapseLegacyDirectRescueSchedulerContractDescriptor -Contract $LegacySnapshot.scheduler_contract -Context "${Context}_contract"
    $horizonTicks=[int64]$contract.restart_count * [int64]$contract.restart_interval_ticks
    $horizon=[TimeSpan]::FromTicks($horizonTicks).Add([TimeSpan]::FromSeconds($MarginSeconds))
    if($horizon -lt [TimeSpan]::FromSeconds($MarginSeconds) -or $horizon -gt [TimeSpan]::FromMinutes(16)){Die "SYNAPSE_LEGACY_DIRECT_RESCUE_RETRY_HORIZON_INVALID context=$Context ticks=$horizonTicks margin_s=$MarginSeconds"}
    $overall=[System.Diagnostics.Stopwatch]::StartNew()
    $overallLimit=$horizon.Add([TimeSpan]::FromMinutes(2))
    $quietClock=$null;$stableLastRun=0L;$stableLastResult=[int64]::MinValue;$last='<none>'
    do{
        Assert-SynapseLegacyDirectRescueControlHeld -LegacyGateTransition $LegacyGateTransition -LegacyDenialTransition $LegacyDenialTransition -Context $Context
        $runtime=Read-SynapseLegacyDirectRescueTaskRuntimeState -LegacySnapshot $LegacySnapshot -LegacyDenialTransition $LegacyDenialTransition -Context $Context
        $actions=@(Get-SynapseLegacyDenialProbeActionProcessSnapshot -LegacySnapshot $LegacySnapshot -Context $Context)
        $targets=@(Select-SynapseMcpDeployTargetProcesses -Snapshot @(Get-SynapseMcpProcessSnapshot) -Bind $Bind -DbPath $DbPath)
        $listeners=@(Get-SynapseTcpBindListenerSnapshot -Bind $Bind)
        $supervisors=@(Get-SynapseDaemonSupervisorProcessSnapshot -SupervisorPath $SupervisorPath)
        $ready=([int]$runtime.State -eq 3 -and [int64]$runtime.LastTaskResult -eq 0 -and -not [bool]$runtime.NextRunTimePresent -and [int]$runtime.InstanceCount -eq 0 -and
                $actions.Count -eq 0 -and $targets.Count -eq 0 -and $listeners.Count -eq 0 -and $supervisors.Count -eq 0)
        if($ready){
            if($null -eq $quietClock -or $stableLastRun -ne [int64]$runtime.LastRunTimeFileTimeUtc -or $stableLastResult -ne [int64]$runtime.LastTaskResult){
                $quietClock=[System.Diagnostics.Stopwatch]::StartNew();$stableLastRun=[int64]$runtime.LastRunTimeFileTimeUtc;$stableLastResult=[int64]$runtime.LastTaskResult
            }
            if($quietClock.Elapsed -ge $horizon){
                Assert-SynapseLegacyDirectRescueControlHeld -LegacyGateTransition $LegacyGateTransition -LegacyDenialTransition $LegacyDenialTransition -Context "${Context}_complete"
                $final=Read-SynapseLegacyDirectRescueTaskRuntimeState -LegacySnapshot $LegacySnapshot -LegacyDenialTransition $LegacyDenialTransition -Context "${Context}_complete"
                if([int64]$final.LastRunTimeFileTimeUtc -ne $stableLastRun -or [int64]$final.LastTaskResult -ne 0 -or [int]$final.State -ne 3 -or [int]$final.InstanceCount -ne 0){Die "SYNAPSE_LEGACY_DIRECT_RESCUE_RETRY_HORIZON_FINAL_DRIFT context=$Context"}
                return [pscustomobject][ordered]@{schema='synapse_legacy_direct_rescue_retry_horizon/v1';completed_at_utc=[DateTime]::UtcNow.ToString('o');horizon_ticks=[int64]$horizon.Ticks;margin_seconds=$MarginSeconds;last_run_time_filetime_utc=$stableLastRun;last_task_result=0;task_state=3;instance_count=0;action_process_count=0;target_process_count=0;listener_count=0;supervisor_process_count=0}
            }
            $last="ready quiet_ms=$([int64]$quietClock.Elapsed.TotalMilliseconds) required_ms=$([int64]$horizon.TotalMilliseconds)"
        }else{
            if($null -ne $quietClock){$quietClock.Stop()};$quietClock=$null;$stableLastRun=0L;$stableLastResult=[int64]::MinValue
            $last="state=$($runtime.State) result=$($runtime.LastTaskResult) next=$($runtime.NextRunTimePresent) instances=$($runtime.InstanceCount) action=$($actions.Count) targets=$($targets.Count) listeners=$($listeners.Count) supervisors=$($supervisors.Count)"
        }
        if($overall.Elapsed -ge $overallLimit){Die "SYNAPSE_LEGACY_DIRECT_RESCUE_RETRY_HORIZON_TIMEOUT context=$Context horizon_s=$([int64]$horizon.TotalSeconds) elapsed_s=$([int64]$overall.Elapsed.TotalSeconds) last=$last remediation=the exact retained Scheduler retry authority did not become durably quiescent while the positive gate and denial stub remained held"}
        Start-Sleep -Milliseconds 250
    }while($true)
}

function Assert-SynapseLegacyDirectRescuePreResumeBoundary {
    param(
        [Parameter(Mandatory=$true)]$LegacySnapshot,
        [Parameter(Mandatory=$true)]$LegacyDenialTransition,
        [Parameter(Mandatory=$true)]$RetryHorizonReceipt,
        [Parameter(Mandatory=$true)][ValidateRange(1,2147483647)][int]$SuspendedRootPid,
        [Parameter(Mandatory=$true)][ValidateRange(0,65535)][int]$ExpectedSessionId,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$DbPath,
        [Parameter(Mandatory=$true)][string]$SupervisorPath,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $runtime=Read-SynapseLegacyDirectRescueTaskRuntimeState -LegacySnapshot $LegacySnapshot -LegacyDenialTransition $LegacyDenialTransition -Context $Context
    if([int]$runtime.State -ne 3 -or [int64]$runtime.LastTaskResult -ne 0 -or [bool]$runtime.NextRunTimePresent -or [int]$runtime.InstanceCount -ne 0 -or
       [int64]$runtime.LastRunTimeFileTimeUtc -ne [int64]$RetryHorizonReceipt.last_run_time_filetime_utc){
        Die "SYNAPSE_LEGACY_DIRECT_RESCUE_SCHEDULER_BOUNDARY_DRIFT context=$Context state=$($runtime.State) result=$($runtime.LastTaskResult) instances=$($runtime.InstanceCount) last_run=$($runtime.LastRunTimeFileTimeUtc) expected_last_run=$($RetryHorizonReceipt.last_run_time_filetime_utc)"
    }
    $actions=@(Get-SynapseLegacyDenialProbeActionProcessSnapshot -LegacySnapshot $LegacySnapshot -Context $Context)
    $root=@($actions|Where-Object{[int]$_.ProcessId -eq $SuspendedRootPid})
    $extra=@($actions|Where-Object{[int]$_.ProcessId -ne $SuspendedRootPid})
    if($root.Count -ne 1 -or [string]$root[0].Role -cne 'legacy_task_interpreter' -or [int]$root[0].SessionId -ne $ExpectedSessionId -or $extra.Count -ne 0){
        Die "SYNAPSE_LEGACY_DIRECT_RESCUE_PRE_RESUME_ACTION_SET_INVALID context=$Context root_pid=$SuspendedRootPid root_count=$($root.Count) root_role=$($root[0].Role) root_session=$($root[0].SessionId) expected_session=$ExpectedSessionId extra=$(@($extra.ProcessId)-join ',')"
    }
    $targets=@(Select-SynapseMcpDeployTargetProcesses -Snapshot @(Get-SynapseMcpProcessSnapshot) -Bind $Bind -DbPath $DbPath)
    $listeners=@(Get-SynapseTcpBindListenerSnapshot -Bind $Bind)
    $supervisors=@(Get-SynapseDaemonSupervisorProcessSnapshot -SupervisorPath $SupervisorPath)
    if($targets.Count -ne 0 -or $listeners.Count -ne 0 -or $supervisors.Count -ne 0){Die "SYNAPSE_LEGACY_DIRECT_RESCUE_PRE_RESUME_AUTHORITY_PRESENT context=$Context targets=$($targets.Count) listeners=$($listeners.Count) supervisors=$($supervisors.Count)"}
    return [pscustomobject][ordered]@{TaskRuntime=$runtime;RootAction=$root[0];ActionProcessCount=1;TargetProcessCount=0;ListenerCount=0;SupervisorProcessCount=0}
}

function Get-SynapseLegacySupervisorDaemonArgumentText {
    param(
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$DbPath,
        [Parameter(Mandatory=$true)][string]$ProfilesDir,
        [Parameter(Mandatory=$true)][bool]$EnableAudio,
        [AllowNull()][string]$AllowedPermissions
    )
    $arguments=@('--mode','http','--bind',(Quote-WindowsCommandArgument $Bind),'--db',(Quote-WindowsCommandArgument $DbPath),'--profile-dir',(Quote-WindowsCommandArgument $ProfilesDir),'--log-level','info')
    if($EnableAudio){$arguments+='--enable-audio'}
    $normalizedPermissions=Normalize-SynapseAllowedPermissionsArgument -Value $AllowedPermissions
    if(-not [string]::IsNullOrWhiteSpace($normalizedPermissions)){$arguments+=@('--allowed-permissions',(Quote-WindowsCommandArgument $normalizedPermissions))}
    return ($arguments-join ' ')
}

function Assert-SynapseLegacySupervisorCompatibilityContractDescriptor {
    param(
        [Parameter(Mandatory=$true)]$Contract,
        [Parameter(Mandatory=$true)]$SupervisorDescriptor,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $expected=@('schema','template_id','encoding','normalized_sha256','normalized_length','source_file_id_128','source_sha256','source_length','line_feed_count','crlf_count','bare_lf_count','bare_cr_count','ends_with_crlf','root_assignment_count','start_process_command_count','parent_job_abi_absent','recovery_job_inheritance','legacy_calyx_config','assignments')
    $names=if($Contract -is [System.Collections.IDictionary]){@($Contract.Keys|ForEach-Object{[string]$_})}else{@($Contract.PSObject.Properties.Name)}
    $assignmentNames=@('ExePath','Bind','DbPath','ProfilesDir','DaemonLogDir','TokenPath','LauncherLog','SupervisorState','SupervisorEvents','MaintenanceLockPath','SupervisorStopRequestPath','ExpectedCalyxConfigPath','DaemonArgumentText','ExpectedAllowedPermissions','ExpectedEnableAudio')
    $actualAssignmentNames=if($Contract.assignments -is [System.Collections.IDictionary]){@($Contract.assignments.Keys|ForEach-Object{[string]$_})}else{@($Contract.assignments.PSObject.Properties.Name)}
    if($names.Count -ne $expected.Count -or @($names|Where-Object{$expected -cnotcontains $_}).Count -gt 0 -or
       $actualAssignmentNames.Count -ne $assignmentNames.Count -or @($actualAssignmentNames|Where-Object{$assignmentNames -cnotcontains $_}).Count -gt 0 -or
       [string]$Contract.schema -cne 'synapse_legacy_supervisor_63dbe29e/v1' -or [string]$Contract.template_id -cne 'legacy_supervisor_63dbe29e/v1' -or
       [string]$Contract.encoding -cne 'utf8_no_bom_exact_mixed_lf' -or [string]$Contract.normalized_sha256 -cne '38B33235CDCD7D1A06A1358E6905042585A4FEC038702BC60E2B50DFCBA923DF' -or
       [int64]$Contract.normalized_length -ne 39980 -or [string]$Contract.source_file_id_128 -ine [string]$SupervisorDescriptor.file_id_128 -or
       [string]$Contract.source_sha256 -ine [string]$SupervisorDescriptor.sha256 -or [int64]$Contract.source_length -ne [int64]$SupervisorDescriptor.length -or
       [int]$Contract.line_feed_count -ne 703 -or [int]$Contract.crlf_count -ne 1 -or [int]$Contract.bare_lf_count -ne 702 -or [int]$Contract.bare_cr_count -ne 0 -or -not [bool]$Contract.ends_with_crlf -or
       [int]$Contract.root_assignment_count -ne 15 -or [int]$Contract.start_process_command_count -ne 1 -or -not [bool]$Contract.parent_job_abi_absent -or
       [string]$Contract.recovery_job_inheritance -cne 'inherited_no_limit_job_cold_start_process' -or [string]$Contract.legacy_calyx_config -cne 'absent'){
        Die ("SYNAPSE_LEGACY_SUPERVISOR_COMPATIBILITY_DESCRIPTOR_INVALID context={0} names=[{1}] expected_names=[{2}] assignment_names=[{3}] expected_assignment_names=[{4}] schema={5} template_id={6} encoding={7} normalized_sha256={8} normalized_length={9} source_file_id={10} descriptor_file_id={11} source_sha256={12} descriptor_sha256={13} source_length={14} descriptor_length={15} lf={16} crlf={17} bare_lf={18} bare_cr={19} ends_crlf={20} root_assignments={21} start_process={22} parent_job_absent={23} inheritance={24} calyx={25} remediation=inspect the named field drift; never infer compatibility from a partial legacy descriptor" -f `
            $Context,($names-join ','),($expected-join ','),($actualAssignmentNames-join ','),($assignmentNames-join ','),
            [string]$Contract.schema,[string]$Contract.template_id,[string]$Contract.encoding,[string]$Contract.normalized_sha256,[string]$Contract.normalized_length,
            [string]$Contract.source_file_id_128,[string]$SupervisorDescriptor.file_id_128,[string]$Contract.source_sha256,[string]$SupervisorDescriptor.sha256,
            [string]$Contract.source_length,[string]$SupervisorDescriptor.length,[string]$Contract.line_feed_count,[string]$Contract.crlf_count,[string]$Contract.bare_lf_count,
            [string]$Contract.bare_cr_count,[string]$Contract.ends_with_crlf,[string]$Contract.root_assignment_count,[string]$Contract.start_process_command_count,
            [string]$Contract.parent_job_abi_absent,[string]$Contract.recovery_job_inheritance,[string]$Contract.legacy_calyx_config)
    }
    $a=$Contract.assignments
    $audio=$false
    if(-not [bool]::TryParse([string]$a.ExpectedEnableAudio,[ref]$audio)){Die "SYNAPSE_LEGACY_SUPERVISOR_AUDIO_ASSIGNMENT_INVALID context=$Context value=$($a.ExpectedEnableAudio)"}
    $expectedArguments=Get-SynapseLegacySupervisorDaemonArgumentText -Bind ([string]$a.Bind) -DbPath ([string]$a.DbPath) -ProfilesDir ([string]$a.ProfilesDir) -EnableAudio $audio -AllowedPermissions ([string]$a.ExpectedAllowedPermissions)
    $supervisorParent=Split-Path -Parent ([System.IO.Path]::GetFullPath([string]$SupervisorDescriptor.path))
    if(-not [string]::IsNullOrEmpty([string]$a.ExpectedCalyxConfigPath) -or
       [string]$a.LauncherLog -ine [System.IO.Path]::GetFullPath((Join-Path ([string]$a.DaemonLogDir) 'daemon-launcher.log')) -or
       [string]$a.SupervisorState -ine [System.IO.Path]::GetFullPath((Join-Path ([string]$a.DaemonLogDir) 'daemon-supervisor-current.json')) -or
       [string]$a.SupervisorEvents -ine [System.IO.Path]::GetFullPath((Join-Path ([string]$a.DaemonLogDir) 'daemon-supervisor-events.jsonl')) -or
       [string]$a.SupervisorStopRequestPath -ine [System.IO.Path]::GetFullPath((Join-Path $supervisorParent $script:SynapseDaemonSupervisorStopRequestFileName)) -or
       [string]$a.DaemonArgumentText -cne $expectedArguments -or
       [string]$a.ExpectedAllowedPermissions -cne (Normalize-SynapseAllowedPermissionsArgument -Value ([string]$a.ExpectedAllowedPermissions))){
        Die "SYNAPSE_LEGACY_SUPERVISOR_ASSIGNMENT_CROSSBIND_INVALID context=$Context"
    }
    return (ConvertTo-SynapseCanonicalValue -Value $Contract)
}

function Get-SynapseLegacySupervisorCompatibilityContract {
    param(
        [Parameter(Mandatory=$true)][string]$Source,
        [Parameter(Mandatory=$true)]$SupervisorDescriptor,
        [Parameter(Mandatory=$true)][string]$ExePath,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$DbPath,
        [Parameter(Mandatory=$true)][string]$ProfilesDir,
        [Parameter(Mandatory=$true)][string]$LogDir,
        [Parameter(Mandatory=$true)][string]$TokenPath,
        [Parameter(Mandatory=$true)][string]$MaintenanceLockPath,
        [Parameter(Mandatory=$true)][bool]$EnableAudio,
        [AllowNull()][string]$AllowedPermissions,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $utf8=[System.Text.UTF8Encoding]::new($false,$true)
    if($Source.Length -eq 0 -or [int]$Source[0] -eq 0xFEFF -or $utf8.GetByteCount($Source) -ne [int64]$SupervisorDescriptor.length){Die "SYNAPSE_LEGACY_SUPERVISOR_ENCODING_INVALID context=$Context length=$($SupervisorDescriptor.length)"}
    $crlf=[regex]::Matches($Source,"`r`n").Count;$bareLf=[regex]::Matches($Source,"(?<!`r)`n").Count;$bareCr=[regex]::Matches($Source,"`r(?!`n)").Count
    if($crlf -ne 1 -or $bareLf -ne 702 -or $bareCr -ne 0 -or -not $Source.EndsWith("`r`n",[System.StringComparison]::Ordinal)){Die "SYNAPSE_LEGACY_SUPERVISOR_LINE_ENDING_CONTRACT_INVALID context=$Context crlf=$crlf bare_lf=$bareLf bare_cr=$bareCr ends_crlf=$($Source.EndsWith("`r`n"))"}
    $tokens=$null;$errors=$null;$ast=[System.Management.Automation.Language.Parser]::ParseInput($Source,[ref]$tokens,[ref]$errors)
    if($errors.Count -ne 0 -or $null -ne $ast.ParamBlock){Die "SYNAPSE_LEGACY_SUPERVISOR_AST_INVALID context=$Context errors=$(@($errors.Message)-join '|') param_block=$($null-ne$ast.ParamBlock)"}
    $assignmentNames=@('ExePath','Bind','DbPath','ProfilesDir','DaemonLogDir','TokenPath','LauncherLog','SupervisorState','SupervisorEvents','MaintenanceLockPath','SupervisorStopRequestPath','ExpectedCalyxConfigPath','DaemonArgumentText','ExpectedAllowedPermissions','ExpectedEnableAudio')
    $allAssignments=@($ast.FindAll({param($node)$node -is [System.Management.Automation.Language.AssignmentStatementAst]},$true))
    $rootAssignments=@($ast.EndBlock.Statements|Where-Object{$_ -is [System.Management.Automation.Language.AssignmentStatementAst]})
    $values=[ordered]@{};$replacementPlans=@()
    foreach($name in $assignmentNames){
        $matches=@($allAssignments|Where-Object{$_.Left -is [System.Management.Automation.Language.VariableExpressionAst] -and [string]$_.Left.VariablePath.UserPath -ceq $name})
        if($matches.Count -ne 1){Die "SYNAPSE_LEGACY_SUPERVISOR_ASSIGNMENT_CARDINALITY_INVALID context=$Context name=$name count=$($matches.Count)"}
        $assignment=$matches[0]
        $isRoot=@($rootAssignments|Where-Object{$_.Extent.StartOffset -eq $assignment.Extent.StartOffset -and $_.Extent.EndOffset -eq $assignment.Extent.EndOffset}).Count -eq 1
        $literal=if($assignment.Right -is [System.Management.Automation.Language.CommandExpressionAst]){$assignment.Right.Expression}else{$assignment.Right}
        if(-not $isRoot -or $assignment.Operator -ne [System.Management.Automation.Language.TokenKind]::Equals -or
           $literal -isnot [System.Management.Automation.Language.StringConstantExpressionAst] -or
           $literal.StringConstantType -ne [System.Management.Automation.Language.StringConstantType]::SingleQuoted){
            Die "SYNAPSE_LEGACY_SUPERVISOR_ASSIGNMENT_SHAPE_INVALID context=$Context name=$name root=$isRoot right=$($assignment.Right.GetType().Name) literal=$(if($null-ne$literal){$literal.GetType().Name}else{'<null>'})"
        }
        $values[$name]=[string]$literal.Value
        $replacementPlans+=,[pscustomobject]@{Name=$name;Start=[int]$assignment.Right.Extent.StartOffset;End=[int]$assignment.Right.Extent.EndOffset}
    }
    $expectedValues=[ordered]@{
        ExePath=[System.IO.Path]::GetFullPath($ExePath);Bind=$Bind;DbPath=[System.IO.Path]::GetFullPath($DbPath);ProfilesDir=[System.IO.Path]::GetFullPath($ProfilesDir)
        DaemonLogDir=[System.IO.Path]::GetFullPath($LogDir);TokenPath=[System.IO.Path]::GetFullPath($TokenPath)
        LauncherLog=[System.IO.Path]::GetFullPath((Join-Path $LogDir 'daemon-launcher.log'));SupervisorState=[System.IO.Path]::GetFullPath((Join-Path $LogDir 'daemon-supervisor-current.json'));SupervisorEvents=[System.IO.Path]::GetFullPath((Join-Path $LogDir 'daemon-supervisor-events.jsonl'))
        MaintenanceLockPath=[System.IO.Path]::GetFullPath($MaintenanceLockPath);SupervisorStopRequestPath=[System.IO.Path]::GetFullPath((Join-Path (Split-Path -Parent ([string]$SupervisorDescriptor.path)) $script:SynapseDaemonSupervisorStopRequestFileName))
        ExpectedCalyxConfigPath='';DaemonArgumentText=(Get-SynapseLegacySupervisorDaemonArgumentText -Bind $Bind -DbPath ([System.IO.Path]::GetFullPath($DbPath)) -ProfilesDir ([System.IO.Path]::GetFullPath($ProfilesDir)) -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions)
        ExpectedAllowedPermissions=(Normalize-SynapseAllowedPermissionsArgument -Value $AllowedPermissions);ExpectedEnableAudio=([bool]$EnableAudio).ToString()
    }
    foreach($name in $assignmentNames){
        $pathAssignment=$name -in @('ExePath','DbPath','ProfilesDir','DaemonLogDir','TokenPath','LauncherLog','SupervisorState','SupervisorEvents','MaintenanceLockPath','SupervisorStopRequestPath')
        $matches=if($pathAssignment){[string]$values[$name] -ieq [string]$expectedValues[$name]}else{[string]$values[$name] -ceq [string]$expectedValues[$name]}
        if(-not $matches){Die "SYNAPSE_LEGACY_SUPERVISOR_ASSIGNMENT_VALUE_INVALID context=$Context name=$name expected=$($expectedValues[$name]) actual=$($values[$name])"}
    }
    $normalized=$Source
    foreach($replacement in @($replacementPlans|Sort-Object Start -Descending)){
        $placeholder="'__SYNAPSE_LEGACY_$($replacement.Name)__'"
        $normalized=$normalized.Substring(0,$replacement.Start)+$placeholder+$normalized.Substring($replacement.End)
    }
    $normalizedLength=$utf8.GetByteCount($normalized);$normalizedSha=(Get-SynapseSha256Hex -Text $normalized).ToUpperInvariant()
    $startProcessCount=@($ast.FindAll({param($node)$node -is [System.Management.Automation.Language.CommandAst] -and [string]$node.GetCommandName() -ceq 'Start-Process'},$true)).Count
    $forbidden=@('ParentJobName','PROC_THREAD_ATTRIBUTE_JOB_LIST','CREATE_BREAKAWAY_FROM_JOB','AssignProcessToJobObject')|Where-Object{$Source.IndexOf($_,[System.StringComparison]::OrdinalIgnoreCase) -ge 0}
    if($normalizedSha -cne '38B33235CDCD7D1A06A1358E6905042585A4FEC038702BC60E2B50DFCBA923DF' -or $normalizedLength -ne 39980 -or $startProcessCount -ne 1 -or @($forbidden).Count -ne 0){Die "SYNAPSE_LEGACY_SUPERVISOR_TEMPLATE_IDENTITY_INVALID context=$Context normalized_sha256=$normalizedSha normalized_length=$normalizedLength start_process_count=$startProcessCount forbidden=$($forbidden-join ',')"}
    $contract=[ordered]@{
        schema='synapse_legacy_supervisor_63dbe29e/v1';template_id='legacy_supervisor_63dbe29e/v1';encoding='utf8_no_bom_exact_mixed_lf'
        normalized_sha256=$normalizedSha;normalized_length=$normalizedLength;source_file_id_128=([string]$SupervisorDescriptor.file_id_128).ToUpperInvariant();source_sha256=([string]$SupervisorDescriptor.sha256).ToUpperInvariant();source_length=[int64]$SupervisorDescriptor.length
        line_feed_count=($crlf+$bareLf);crlf_count=$crlf;bare_lf_count=$bareLf;bare_cr_count=$bareCr;ends_with_crlf=$true;root_assignment_count=15;start_process_command_count=$startProcessCount
        parent_job_abi_absent=$true;recovery_job_inheritance='inherited_no_limit_job_cold_start_process';legacy_calyx_config='absent';assignments=$values
    }
    return (Assert-SynapseLegacySupervisorCompatibilityContractDescriptor -Contract ([pscustomobject]$contract) -SupervisorDescriptor $SupervisorDescriptor -Context $Context)
}

function Get-SynapseLegacySnapshotSupervisorDescriptor {
    param(
        [Parameter(Mandatory=$true)]$Snapshot,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $supervisorValue = Get-SynapseObjectPropertyValue -Object $Snapshot -Names @('supervisor','Supervisor')
    if ($null -eq $supervisorValue) {
        $launcherObjectsValue = Get-SynapseObjectPropertyValue -Object $Snapshot -Names @('launcher_objects','LauncherObjects')
        $supervisorObjects = @(
            @($launcherObjectsValue) | Where-Object {
                [string](Get-SynapseObjectPropertyValue -Object $_ -Names @('role','Role')) -ceq 'legacy_supervisor'
            }
        )
        if ($supervisorObjects.Count -ne 1) { Die "SYNAPSE_LEGACY_SUPERVISOR_DESCRIPTOR_CARDINALITY_INVALID context=$Context count=$($supervisorObjects.Count)" }
        $supervisorValue = $supervisorObjects[0]
    }
    return ConvertTo-SynapseAuthorityFileDescriptor -Identity $supervisorValue -Role 'legacy_supervisor'
}

function Assert-SynapseLegacySupervisorCompatibilitySourceUnderLease {
    param(
        [Parameter(Mandatory=$true)]$Snapshot,
        [Parameter(Mandatory=$true)]$Lease,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $contractValue = Get-SynapseObjectPropertyValue -Object $Snapshot -Names @('supervisor_compatibility_contract','SupervisorCompatibilityContract')
    $supervisorValue = Get-SynapseLegacySnapshotSupervisorDescriptor -Snapshot $Snapshot -Context $Context
    $declared=Assert-SynapseLegacySupervisorCompatibilityContractDescriptor -Contract $contractValue -SupervisorDescriptor $supervisorValue -Context "${Context}_descriptor"
    $read=$Lease.ReadUtf8(2MB)
    $source=if($read -is [string]){[string]$read}else{[string]$read.Content}
    $audio=$false
    if(-not [bool]::TryParse([string]$declared.assignments.ExpectedEnableAudio,[ref]$audio)){Die "SYNAPSE_LEGACY_SUPERVISOR_AUDIO_ASSIGNMENT_INVALID context=$Context"}
    $actual=Get-SynapseLegacySupervisorCompatibilityContract -Source $source -SupervisorDescriptor $supervisorValue -ExePath ([string]$declared.assignments.ExePath) -Bind ([string]$declared.assignments.Bind) -DbPath ([string]$declared.assignments.DbPath) -ProfilesDir ([string]$declared.assignments.ProfilesDir) -LogDir ([string]$declared.assignments.DaemonLogDir) -TokenPath ([string]$declared.assignments.TokenPath) -MaintenanceLockPath ([string]$declared.assignments.MaintenanceLockPath) -EnableAudio $audio -AllowedPermissions ([string]$declared.assignments.ExpectedAllowedPermissions) -Context $Context
    if((Get-SynapseCanonicalJson -Value $actual) -cne (Get-SynapseCanonicalJson -Value $declared)){Die "SYNAPSE_LEGACY_SUPERVISOR_COMPATIBILITY_SOURCE_DRIFT context=$Context"}
    return $actual
}

function Get-SynapseRetainedDeniedLegacyFloor {
    param([Parameter(Mandatory=$true)][string]$TaskName,[Parameter(Mandatory=$true)][string]$RuntimeBinDir,[Parameter(Mandatory=$true)][string]$SupervisorPath,[Parameter(Mandatory=$true)][string]$LogDir,[Parameter(Mandatory=$true)][string]$Bind,[Parameter(Mandatory=$true)][string]$DbPath,[switch]$TaskOnly)
    $task=Assert-SynapseDaemonTaskRestartAuthorityIdentity -TaskName $TaskName -SupervisorPath $SupervisorPath -Reason 'retained_denied_legacy_floor';if($null-eq$task){return $null}
    $supervisor=[IO.Path]::GetFullPath($SupervisorPath);if(-not[IO.File]::Exists($supervisor)){return $null};$text=[IO.File]::ReadAllText($supervisor,[Text.UTF8Encoding]::new($false,$true));$match=[regex]::Match($text,'\A# SYNAPSE_LEGACY_AUTHORITY_DENIAL_STUB_V1 broker_identity_sha256=(?<identity>[0-9A-F]{64}) authority_epoch=(?<epoch>[1-9][0-9]*) task_capability_sha256=(?<capability>[0-9A-F]{64})\r?\n');if(-not$match.Success){return $null};$identity=$match.Groups['identity'].Value;$epoch=[int64]$match.Groups['epoch'].Value;$capability=$match.Groups['capability'].Value;$expected=New-SynapseLegacyAuthorityDenialStubContent -BrokerIdentitySha256 $identity -AuthorityEpoch $epoch -TaskCapabilitySha256 $capability;if($text-cne$expected){Die "SYNAPSE_RETAINED_DENIED_LEGACY_STUB_INVALID path=$supervisor"}
    $scheduler=Get-SynapseScheduledTaskComRoot;$lookup=Get-SynapseScheduledTaskLookupExact -Name $TaskName -Scheduler $scheduler;if(-not[bool]$lookup.Exists){Die "SYNAPSE_RETAINED_DENIED_LEGACY_TASK_DISAPPEARED task=$TaskName"};$actions=@($lookup.Task.Definition.Actions);if($actions.Count-ne1){Die "SYNAPSE_RETAINED_DENIED_LEGACY_TASK_ACTION_INVALID task=$TaskName"};$expectedWscript=[IO.Path]::GetFullPath((Join-Path $env:SystemRoot 'System32\wscript.exe'));$vbsMatch=[regex]::Match([string]$actions[0].Arguments,'^//B //Nologo "(?<path>[^"]+\.vbs)"$');if([IO.Path]::GetFullPath([string]$actions[0].Path)-ine$expectedWscript-or-not$vbsMatch.Success){Die "SYNAPSE_RETAINED_DENIED_LEGACY_TASK_ACTION_INVALID task=$TaskName"};$vbs=[IO.Path]::GetFullPath($vbsMatch.Groups['path'].Value)
    $launcherLog=[IO.Path]::GetFullPath((Join-Path $LogDir 'daemon-launcher.log'));$legacyPowerShell=[IO.Path]::GetFullPath((Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'));$expectedVbs=New-SynapseLegacyVbsLauncherContent -LauncherLogPath $launcherLog -SupervisorPath $supervisor -PowerShellPath $legacyPowerShell;if([IO.File]::ReadAllText($vbs,[Text.UTF8Encoding]::new($false,$true))-cne$expectedVbs){Die "SYNAPSE_RETAINED_DENIED_LEGACY_VBS_INVALID path=$vbs"}
    $runtime=Get-SynapseNormalizedDirectoryPath -Path $RuntimeBinDir;$chain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path $runtime);$denialState=Get-SynapsePhysicalRelativeState -ParentPath $runtime -ParentChain $chain -Leaf (Split-Path -Leaf $supervisor);$gatePath=[IO.Path]::GetFullPath((Join-Path $runtime $script:SynapseDaemonSupervisorStopRequestFileName));$gateState=Get-SynapsePhysicalRelativeState -ParentPath $runtime -ParentChain $chain -Leaf (Split-Path -Leaf $gatePath);if(-not[bool]$denialState.Exists-or-not[bool]$gateState.Exists){Die 'SYNAPSE_RETAINED_DENIED_LEGACY_CONTROL_MISSING'};$gateText=[IO.File]::ReadAllText($gatePath,[Text.UTF8Encoding]::new($false,$true));$gate=ConvertFrom-SynapseJsonPreservingStrings -Json $gateText -MaximumJsonLength 65536;if((Get-SynapseCanonicalJson -Value (ConvertTo-SynapseCanonicalValue -Value $gate))-cne$gateText-or[string]$gate.schema-cne'synapse_daemon_supervisor_stop_request/v1'-or[string]$gate.state-cne'requested'-or[string]$gate.reason-cne'broker_authority_adoption_epoch'-or[string]$gate.bind-cne$Bind-or[IO.Path]::GetFullPath([string]$gate.db_path)-ine[IO.Path]::GetFullPath($DbPath)-or[IO.Path]::GetFullPath([string]$gate.supervisor_path)-ine$supervisor-or[string]$gate.broker_identity_sha256-ine$identity-or[int64]$gate.authority_epoch-ne$epoch){Die 'SYNAPSE_RETAINED_DENIED_LEGACY_GATE_INVALID'}
    $targets=@(Select-SynapseMcpDeployTargetProcesses -Snapshot @(Get-SynapseMcpProcessSnapshot) -Bind $Bind -DbPath $DbPath);$listeners=@(Get-SynapseTcpBindListenerSnapshot -Bind $Bind);if($targets.Count-ne0-or$listeners.Count-ne0){Die "SYNAPSE_RETAINED_DENIED_LEGACY_NOT_INERT targets=$($targets.Count) listeners=$($listeners.Count)"}
    $floor=[pscustomobject][ordered]@{legacy_gate=[ordered]@{path=$gatePath;file_id_128=([string]$gateState.FileId128).ToUpperInvariant();sha256=([string]$gateState.Sha256).ToUpperInvariant();length=[int64]$gateState.Length};legacy_denial_stub=[ordered]@{path=$supervisor;file_id_128=([string]$denialState.FileId128).ToUpperInvariant();sha256=([string]$denialState.Sha256).ToUpperInvariant();length=[int64]$denialState.Length};legacy_task_name=$TaskName;broker_identity_sha256=$identity;authority_epoch=$epoch;task_capability_sha256=$capability}
    $scheduler.Root.DeleteTask($TaskName,0);if([bool](Get-SynapseScheduledTaskLookupExact -Name $TaskName -Scheduler $scheduler).Exists){Die "SYNAPSE_RETAINED_DENIED_LEGACY_TASK_DELETE_FAILED task=$TaskName"};if($TaskOnly){Info "SYNAPSE_RETAINED_DENIED_LEGACY_TASK_RETIRED task=$TaskName";return $floor}
    Remove-SynapsePhysicalRelativeEntryExact -ParentPath $runtime -ParentChain $chain -Leaf (Split-Path -Leaf $gatePath) -ExpectedFileId128 ([string]$gateState.FileId128) -ExpectedSha256 ([string]$gateState.Sha256) -ExpectedLength ([int64]$gateState.Length) -Context 'retained_denied_legacy_gate_retire'
    Remove-SynapsePhysicalRelativeEntryExact -ParentPath $runtime -ParentChain $chain -Leaf (Split-Path -Leaf $supervisor) -ExpectedFileId128 ([string]$denialState.FileId128) -ExpectedSha256 ([string]$denialState.Sha256) -ExpectedLength ([int64]$denialState.Length) -Context 'retained_denied_legacy_stub_retire'
    $gateAfter=Get-SynapsePhysicalRelativeState -ParentPath $runtime -ParentChain $chain -Leaf (Split-Path -Leaf $gatePath);$denialAfter=Get-SynapsePhysicalRelativeState -ParentPath $runtime -ParentChain $chain -Leaf (Split-Path -Leaf $supervisor);if([bool]$gateAfter.Exists-or[bool]$denialAfter.Exists){Die "SYNAPSE_RETAINED_DENIED_LEGACY_CONTROL_RETIRE_FAILED gate=$($gateAfter.Exists) denial=$($denialAfter.Exists)"};Info "SYNAPSE_RETAINED_DENIED_LEGACY_RETIRED task=$TaskName gate=$gatePath denial=$supervisor"
    return $null
}

function Get-SynapseLegacyAuthoritySnapshot {
    param(
        [Parameter(Mandatory=$true)][string]$TaskName,
        [Parameter(Mandatory=$true)][string]$SupervisorPath,
        [Parameter(Mandatory=$true)][string]$LogDir,
        [Parameter(Mandatory=$true)][string]$ExePath,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$DbPath,
        [Parameter(Mandatory=$true)][string]$ProfilesDir,
        [Parameter(Mandatory=$true)][string]$TokenPath,
        [Parameter(Mandatory=$true)][string]$MaintenanceLockPath,
        [Parameter(Mandatory=$true)][bool]$EnableAudio,
        [AllowNull()][string]$AllowedPermissions,
        [Parameter(Mandatory=$true)][string]$Reason
    )

    $task=Assert-SynapseDaemonTaskRestartAuthorityIdentity -TaskName $TaskName -SupervisorPath $SupervisorPath -Reason $Reason
    if($null -eq $task){Die "SYNAPSE_BROKER_ADOPTION_LEGACY_TASK_MISSING task=$TaskName reason=$Reason"}
    if([string]$task.State -eq 'Disabled'){Die "SYNAPSE_BROKER_ADOPTION_LEGACY_TASK_DISABLED task=$TaskName reason=$Reason remediation=broker migration requires one admitted live prior authority; repair the exact setup-owned task before adoption"}
    $scheduler=Get-SynapseScheduledTaskComRoot
    $taskLookup=Get-SynapseScheduledTaskLookupExact -Name $TaskName -Scheduler $scheduler
    if(-not [bool]$taskLookup.Exists){Die "SYNAPSE_BROKER_ADOPTION_LEGACY_TASK_COM_READ_FAILED task=$TaskName hresult=$($taskLookup.HResult) reason=exact_task_absent"}
    $registered=$taskLookup.Task
    $schedulerContract=Get-SynapseLegacyDirectRescueSchedulerContract -RegisteredTask $registered -Context "legacy_snapshot_$TaskName"
    $xml=[string]$registered.Xml
    $xmlSha=(Get-SynapseSha256Hex -Text $xml).ToUpperInvariant()
    $sd=[string]$registered.GetSecurityDescriptor(7)
    $sdSha=(Get-SynapseSha256Hex -Text $sd).ToUpperInvariant()
    $actions=@($registered.Definition.Actions)
    if($actions.Count -ne 1){Die "SYNAPSE_BROKER_ADOPTION_LEGACY_TASK_ACTION_COUNT_INVALID task=$TaskName count=$($actions.Count)"}
    $action=$actions[0]
    $execute=[System.IO.Path]::GetFullPath([Environment]::ExpandEnvironmentVariables([string]$action.Path))
    $working=[System.IO.Path]::GetFullPath([Environment]::ExpandEnvironmentVariables([string]$action.WorkingDirectory))
    $supervisorFull=[System.IO.Path]::GetFullPath($SupervisorPath)
    $supervisorIdentity=Get-SynapseRuntimeFileIdentityForAuthority -Path $supervisorFull -Role 'legacy_supervisor'
    $launcherLeases=@()
    $supervisorLease=$null
    try {
        $supervisorChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path ([string]$supervisorIdentity.parent_path))
        $supervisorLease=Open-SynapsePhysicalFileTransitionLease -ParentPath ([string]$supervisorIdentity.parent_path) -ParentChain $supervisorChain -Leaf (Split-Path -Leaf ([string]$supervisorIdentity.path)) -ExpectedFileId128 ([string]$supervisorIdentity.file_id_128) -ExpectedSha256 ([string]$supervisorIdentity.sha256) -ExpectedLength ([int64]$supervisorIdentity.length) -Context 'legacy_admission_supervisor_transition'
        if([int64]$supervisorIdentity.length -gt 2MB){Die "SYNAPSE_BROKER_ADOPTION_LEGACY_SUPERVISOR_BOUND_EXCEEDED path=$supervisorFull length=$($supervisorIdentity.length) max=2097152"}
        $supervisorText=[string]$supervisorLease.ReadUtf8(2MB).Content
        $supervisorCompatibility=Get-SynapseLegacySupervisorCompatibilityContract -Source $supervisorText -SupervisorDescriptor $supervisorIdentity -ExePath $ExePath -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -LogDir $LogDir -TokenPath $TokenPath -MaintenanceLockPath $MaintenanceLockPath -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions -Context "legacy_snapshot_$TaskName"
        $launcherObjects=@($supervisorIdentity)
    if($execute.EndsWith('wscript.exe',[System.StringComparison]::OrdinalIgnoreCase)){
        $vbsMatch=[regex]::Match([string]$action.Arguments,'^//B //Nologo "(?<path>[^"]+\.vbs)"$')
        if(-not $vbsMatch.Success){Die "SYNAPSE_BROKER_ADOPTION_LEGACY_VBS_ARGUMENT_INVALID task=$TaskName arguments=$($action.Arguments)"}
        $vbsPath=[System.IO.Path]::GetFullPath($vbsMatch.Groups['path'].Value)
        $vbsIdentity=Get-SynapseRuntimeFileIdentityForAuthority -Path $vbsPath -Role 'legacy_vbs_launcher'
        $vbsChain=@(Get-SynapsePhysicalDirectoryChainDescriptor -Path ([string]$vbsIdentity.parent_path))
        $launcherLeases+=,(Open-SynapsePhysicalFileReadLease -ParentPath ([string]$vbsIdentity.parent_path) -ParentChain $vbsChain -Leaf (Split-Path -Leaf ([string]$vbsIdentity.path)) -ExpectedFileId128 ([string]$vbsIdentity.file_id_128) -ExpectedSha256 ([string]$vbsIdentity.sha256) -ExpectedLength ([int64]$vbsIdentity.length) -Context 'legacy_admission_vbs')
        if([int64]$vbsIdentity.length -gt 65536){Die "SYNAPSE_BROKER_ADOPTION_LEGACY_VBS_BOUND_EXCEEDED path=$vbsPath length=$($vbsIdentity.length)"}
        $vbsText=[string]$launcherLeases[-1].ReadUtf8(65536).Content
        $expectedPowerShell=[System.IO.Path]::GetFullPath((Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'))
        $expectedWscript=[System.IO.Path]::GetFullPath((Join-Path $env:SystemRoot 'System32\wscript.exe'))
        $expectedLauncherLog=[System.IO.Path]::GetFullPath((Join-Path ([System.IO.Path]::GetFullPath($LogDir)) 'daemon-launcher.log'))
        $expectedVbs=New-SynapseLegacyVbsLauncherContent -LauncherLogPath $expectedLauncherLog -SupervisorPath $supervisorFull -PowerShellPath $expectedPowerShell
        if($execute -ine $expectedWscript -or $vbsText -cne $expectedVbs){
            Die "SYNAPSE_BROKER_ADOPTION_LEGACY_VBS_CLOSED_CONTRACT_INVALID task=$TaskName execute=$execute expected_execute=$expectedWscript vbs=$vbsPath expected_sha256=$((Get-SynapseSha256Hex -Text $expectedVbs).ToUpperInvariant()) actual_sha256=$($vbsIdentity.sha256) remediation=preserve the unrecognized launcher; broker adoption admits only the exact historical wrapper whose sole authority path is the canonical supervisor"
        }
        $wscriptIdentity=Get-SynapseRuntimeFileIdentityForAuthority -Path $expectedWscript -Role 'legacy_task_interpreter'
        $launcherLeases+=,(Open-SynapseProtectedOsInterpreterLease -Descriptor $wscriptIdentity -ExpectedRole 'legacy_task_interpreter' -Context 'legacy_admission_wscript')
        $powershellIdentity=Get-SynapseRuntimeFileIdentityForAuthority -Path $expectedPowerShell -Role 'legacy_supervisor_interpreter'
        $launcherLeases+=,(Open-SynapseProtectedOsInterpreterLease -Descriptor $powershellIdentity -ExpectedRole 'legacy_supervisor_interpreter' -Context 'legacy_admission_powershell')
        $launcherObjects+=,$vbsIdentity,$wscriptIdentity,$powershellIdentity
    } else {
        Die "SYNAPSE_BROKER_ADOPTION_LEGACY_LAUNCHER_SHAPE_UNSUPPORTED task=$TaskName execute=$execute native_bootstrap=$($task.SynapseNativeBootstrapAction) direct_powershell=$($task.SynapseLegacyDirectPowerShellAction) remediation=preserve the opaque launcher; broker adoption requires the exact historical VBS wrapper plus retained wscript, PowerShell, wrapper, and supervisor identities"
    }
    foreach($lease in $launcherLeases){$lease.RequireExact('legacy_admission_complete')}
    $supervisorLease.RequireExact('legacy_admission_supervisor_complete')
    return [pscustomobject][ordered]@{
        name=$TaskName; xml=$xml; xml_sha256=$xmlSha; security_descriptor=$sd; security_descriptor_sha256=$sdSha
        execute=$execute; arguments=[string]$action.Arguments; working_directory=$working; state=[string]$task.State
        enabled=[bool]$registered.Definition.Settings.Enabled; scheduler_contract=$schedulerContract; supervisor_compatibility_contract=$supervisorCompatibility
        supervisor=$supervisorIdentity; launcher_objects=@($launcherObjects); native_bootstrap=$false; Leases=@($launcherLeases); SupervisorLease=$supervisorLease
    }
    } catch {
        foreach($lease in $launcherLeases){try{$lease.Dispose()}catch{[Environment]::FailFast('SYNAPSE_LEGACY_ADMISSION_LAUNCHER_LEASE_RELEASE_UNPROVEN',$_.Exception)}}
        if($null -ne $supervisorLease){try{$supervisorLease.Dispose()}catch{[Environment]::FailFast('SYNAPSE_LEGACY_ADMISSION_SUPERVISOR_LEASE_RELEASE_UNPROVEN',$_.Exception)}}
        throw
    }
}

function Assert-SynapseLegacyAuthoritySnapshotUnchanged {
    param([Parameter(Mandatory=$true)]$Snapshot,$LegacyDenialTransition)
    $snapshotName=[string](Get-SynapseObjectPropertyValue -Object $Snapshot -Names @('name'))
    $snapshotXmlSha=[string](Get-SynapseObjectPropertyValue -Object $Snapshot -Names @('xml_sha256'))
    $snapshotSdSha=[string](Get-SynapseObjectPropertyValue -Object $Snapshot -Names @('security_descriptor_sha256'))
    $snapshotEnabled=[bool](Get-SynapseObjectPropertyValue -Object $Snapshot -Names @('enabled'))
    $snapshotExecute=[string](Get-SynapseObjectPropertyValue -Object $Snapshot -Names @('execute'))
    $snapshotArguments=[string](Get-SynapseObjectPropertyValue -Object $Snapshot -Names @('arguments'))
    $snapshotWorkingDirectory=[string](Get-SynapseObjectPropertyValue -Object $Snapshot -Names @('working_directory'))
    $scheduler=Get-SynapseScheduledTaskComRoot
    $taskLookup=Get-SynapseScheduledTaskLookupExact -Name $snapshotName -Scheduler $scheduler
    if(-not [bool]$taskLookup.Exists){Die "SYNAPSE_BROKER_ADOPTION_LEGACY_TASK_DISAPPEARED task=$snapshotName hresult=$($taskLookup.HResult)"}
    $task=$taskLookup.Task
    $xml=[string]$task.Xml
    $sd=[string]$task.GetSecurityDescriptor(7)
    $actions=@($task.Definition.Actions)
    if($actions.Count -ne 1 -or
        (Get-SynapseSha256Hex -Text $xml) -ine $snapshotXmlSha -or
        (Get-SynapseSha256Hex -Text $sd) -ine $snapshotSdSha -or
        [bool]$task.Definition.Settings.Enabled -ne $snapshotEnabled -or
        [System.IO.Path]::GetFullPath([Environment]::ExpandEnvironmentVariables([string]$actions[0].Path)) -ine [System.IO.Path]::GetFullPath($snapshotExecute) -or
        [string]$actions[0].Arguments -cne $snapshotArguments -or
        [System.IO.Path]::GetFullPath([Environment]::ExpandEnvironmentVariables([string]$actions[0].WorkingDirectory)) -ine [System.IO.Path]::GetFullPath($snapshotWorkingDirectory)){
        Die "SYNAPSE_BROKER_ADOPTION_LEGACY_TASK_DRIFT task=$snapshotName remediation=preserve the externally changed task; setup never disables, updates, or unregisters it"
    }
    $snapshotSchedulerContract=Get-SynapseObjectPropertyValue -Object $Snapshot -Names @('scheduler_contract')
    if($null -eq $snapshotSchedulerContract){Die "SYNAPSE_LEGACY_DIRECT_RESCUE_SCHEDULER_CONTRACT_MISSING task=$snapshotName"}
    $expectedScheduler=Assert-SynapseLegacyDirectRescueSchedulerContractDescriptor -Contract $snapshotSchedulerContract -Context "legacy_snapshot_expected_$snapshotName"
    $actualScheduler=Get-SynapseLegacyDirectRescueSchedulerContract -RegisteredTask $task -Context "legacy_snapshot_current_$snapshotName"
    $actualSchedulerCanonical=Get-SynapseCanonicalJson -Value $actualScheduler
    $expectedSchedulerCanonical=Get-SynapseCanonicalJson -Value $expectedScheduler
    if($actualSchedulerCanonical -cne $expectedSchedulerCanonical){
        Die "SYNAPSE_LEGACY_DIRECT_RESCUE_SCHEDULER_CONTRACT_DRIFT task=$snapshotName expected=[$expectedSchedulerCanonical] actual=[$actualSchedulerCanonical]"
    }
    if($null -ne $Snapshot.PSObject.Properties['Leases']){
        foreach($lease in @($Snapshot.Leases)){$lease.RequireExact('legacy_authority_snapshot_unchanged')}
    }
    if($null -ne $LegacyDenialTransition){
        $snapshotSupervisor = Get-SynapseLegacySnapshotSupervisorDescriptor -Snapshot $Snapshot -Context "legacy_snapshot_transition_$($Snapshot.name)"
        $supervisor=[string]$snapshotSupervisor.path
        if(-not [bool]$LegacyDenialTransition.pre_existed -or [string]$LegacyDenialTransition.path -ine $supervisor -or
           [string]$LegacyDenialTransition.pre_file_id_128 -ine [string]$snapshotSupervisor.file_id_128 -or
           [string]$LegacyDenialTransition.pre_sha256 -ine [string]$snapshotSupervisor.sha256 -or [int64]$LegacyDenialTransition.pre_length -ne [int64]$snapshotSupervisor.length){
            Die "SYNAPSE_BROKER_ADOPTION_LEGACY_SNAPSHOT_TRANSITION_INVALID task=$($Snapshot.name) supervisor=$supervisor"
        }
        $preimageLease=if($null -ne $LegacyDenialTransition.PreLease){$LegacyDenialTransition.PreLease}elseif($null -ne $LegacyDenialTransition.RestoredLease){$LegacyDenialTransition.RestoredLease}else{$Snapshot.SupervisorLease}
        if($null -eq $preimageLease){Die "SYNAPSE_BROKER_ADOPTION_LEGACY_SUPERVISOR_LEASE_MISSING task=$($Snapshot.name) supervisor=$supervisor"}
        $preimageLease.RequireExact('legacy_authority_snapshot_supervisor_preimage')
        [void](Assert-SynapseLegacySupervisorCompatibilitySourceUnderLease -Snapshot $Snapshot -Lease $preimageLease -Context 'legacy_authority_snapshot_supervisor_preimage')
        [void](Get-SynapseAuthorityControlTransitionPhysicalCut -Transition $LegacyDenialTransition -Context "legacy_snapshot_$($Snapshot.name)")
    }elseif($null -ne $Snapshot.PSObject.Properties['SupervisorLease'] -and $null -ne $Snapshot.SupervisorLease){
        $Snapshot.SupervisorLease.RequireExact('legacy_authority_snapshot_supervisor_canonical')
        [void](Assert-SynapseLegacySupervisorCompatibilitySourceUnderLease -Snapshot $Snapshot -Lease $Snapshot.SupervisorLease -Context 'legacy_authority_snapshot_supervisor_canonical')
    }
    return $true
}

function Move-SynapseLegacyDenialPreimageLeaseToSnapshot {
    param(
        [Parameter(Mandatory=$true)]$Snapshot,
        [Parameter(Mandatory=$true)]$LegacyDenialTransition,
        [Parameter(Mandatory=$true)][string]$Context
    )
    $cut=Get-SynapseAuthorityControlTransitionPhysicalCut -Transition $LegacyDenialTransition -Context "${Context}_physical_cut"
    if([string]$cut.PreLocation -cne 'canonical'){
        Die "SYNAPSE_LEGACY_DENIAL_PREIMAGE_NOT_CANONICAL context=$Context pre_location=$($cut.PreLocation) post_location=$($cut.PostLocation)"
    }
    $owners=@()
    if($null -ne $LegacyDenialTransition.PreLease){$owners+=,[pscustomobject]@{Name='PreLease';Lease=$LegacyDenialTransition.PreLease}}
    if($null -ne $LegacyDenialTransition.RestoredLease){$owners+=,[pscustomobject]@{Name='RestoredLease';Lease=$LegacyDenialTransition.RestoredLease}}
    if($owners.Count -ne 1){Die "SYNAPSE_LEGACY_DENIAL_PREIMAGE_LEASE_OWNER_INVALID context=$Context owner_count=$($owners.Count) owners=$(@($owners.Name)-join ',')"}
    if($null -ne $Snapshot.PSObject.Properties['SupervisorLease'] -and $null -ne $Snapshot.SupervisorLease){Die "SYNAPSE_LEGACY_DENIAL_SNAPSHOT_SUPERVISOR_LEASE_ALREADY_OWNED context=$Context"}
    $owner=$owners[0];$owner.Lease.RequireExact("${Context}_preimage_handoff")
    if([string]$owner.Name -ceq 'PreLease'){$LegacyDenialTransition.PreLease=$null}else{$LegacyDenialTransition.RestoredLease=$null}
    if($null -eq $Snapshot.PSObject.Properties['SupervisorLease']){$Snapshot|Add-Member -NotePropertyName SupervisorLease -NotePropertyValue $owner.Lease}else{$Snapshot.SupervisorLease=$owner.Lease}
    $Snapshot.SupervisorLease.RequireExact("${Context}_snapshot_owned")
}

function Close-SynapseLegacyAuthoritySnapshotLeases {
    param($Snapshot)
    if($null -eq $Snapshot -or $null -eq $Snapshot.PSObject.Properties['Leases']){return}
    foreach($lease in @($Snapshot.Leases)){if($null -ne $lease){try{$lease.Dispose()}catch{[Environment]::FailFast('SYNAPSE_LEGACY_SNAPSHOT_LEASE_RELEASE_UNPROVEN',$_.Exception)}}}
    $Snapshot.Leases=@()
    if($null -ne $Snapshot.PSObject.Properties['SupervisorLease'] -and $null -ne $Snapshot.SupervisorLease){
        $borrowed=($null-ne$Snapshot.PSObject.Properties['SupervisorLeaseBorrowed'] -and [bool]$Snapshot.SupervisorLeaseBorrowed)
        if(-not$borrowed){
            try{$Snapshot.SupervisorLease.Dispose()}catch{[Environment]::FailFast('SYNAPSE_LEGACY_SNAPSHOT_SUPERVISOR_LEASE_RELEASE_UNPROVEN',$_.Exception)}
            $Snapshot.SupervisorLease=$null
            if($null-ne$Snapshot.PSObject.Properties['SupervisorLeaseBorrowed']){$Snapshot.SupervisorLeaseBorrowed=$false}
        }
    }
}

function Open-SynapseLegacyAuthorityDescriptorLeases {
    param(
        [Parameter(Mandatory=$true)]$Descriptor,
        [Parameter(Mandatory=$true)][string]$Context,
        $LegacyDenialTransition,
        $BorrowedLegacySupervisorLease=$null,
        [switch]$ReadOnlyLegacySupervisor
    )
    $leases=@();$transitionLease=$null;$ownsTransitionLease=$false;$ownsDescriptorSupervisorLease=$false
    try{
        foreach($object in @($Descriptor.launcher_objects)){
            $role=[string]$object.role
            if($role -ceq 'legacy_supervisor' -and $null -eq $LegacyDenialTransition -and $null -ne $BorrowedLegacySupervisorLease){
                $expectedPath=[System.IO.Path]::GetFullPath([string]$object.path)
                $actualPath=[System.IO.Path]::GetFullPath([string]$BorrowedLegacySupervisorLease.CurrentPath)
                if($actualPath -ine $expectedPath -or
                   [string]$BorrowedLegacySupervisorLease.FileId128 -ine [string]$object.file_id_128 -or
                   [string]$BorrowedLegacySupervisorLease.Sha256 -ine [string]$object.sha256 -or
                   [int64]$BorrowedLegacySupervisorLease.Length -ne [int64]$object.length){
                    Die "SYNAPSE_BROKER_ADOPTION_BORROWED_LEGACY_SUPERVISOR_BINDING_INVALID context=$Context expected_path=$expectedPath actual_path=$actualPath"
                }
                $BorrowedLegacySupervisorLease.RequireExact("${Context}_reuse_legacy_supervisor_without_transition")
                $transitionLease=$BorrowedLegacySupervisorLease
                if($null-eq$Descriptor.PSObject.Properties['SupervisorLease']){$Descriptor|Add-Member -NotePropertyName SupervisorLease -NotePropertyValue $transitionLease}else{$Descriptor.SupervisorLease=$transitionLease}
                if($null-eq$Descriptor.PSObject.Properties['SupervisorLeaseBorrowed']){$Descriptor|Add-Member -NotePropertyName SupervisorLeaseBorrowed -NotePropertyValue $true}else{$Descriptor.SupervisorLeaseBorrowed=$true}
                continue
            }
            if($role -ceq 'legacy_supervisor' -and $null -ne $LegacyDenialTransition){
                if(-not [bool]$LegacyDenialTransition.pre_existed -or
                   [System.IO.Path]::GetFullPath([string]$object.path) -ine [System.IO.Path]::GetFullPath([string]$LegacyDenialTransition.path) -or
                   [string]$object.file_id_128 -ine [string]$LegacyDenialTransition.pre_file_id_128 -or
                   [string]$object.sha256 -ine [string]$LegacyDenialTransition.pre_sha256 -or
                   [int64]$object.length -ne [int64]$LegacyDenialTransition.pre_length){
                    Die "SYNAPSE_BROKER_ADOPTION_LEGACY_SUPERVISOR_TRANSITION_BINDING_INVALID context=$Context path=$($object.path)"
                }
                $canonical=Get-SynapsePhysicalRelativeState -ParentPath $LegacyDenialTransition.parent -ParentChain $LegacyDenialTransition.parent_chain -Leaf $LegacyDenialTransition.leaf
                $park=Get-SynapseAuthorityControlRootState -Transition $LegacyDenialTransition -Leaf $LegacyDenialTransition.park_leaf
                $canonicalIsPre=Test-SynapsePhysicalStateExact -State $canonical -ExpectedExists $true -ExpectedFileId128 $LegacyDenialTransition.pre_file_id_128 -ExpectedSha256 $LegacyDenialTransition.pre_sha256 -ExpectedLength $LegacyDenialTransition.pre_length
                $parkIsPre=Test-SynapsePhysicalStateExact -State $park -ExpectedExists $true -ExpectedFileId128 $LegacyDenialTransition.pre_file_id_128 -ExpectedSha256 $LegacyDenialTransition.pre_sha256 -ExpectedLength $LegacyDenialTransition.pre_length
                if(([int]$canonicalIsPre+[int]$parkIsPre) -ne 1){
                    Die "SYNAPSE_BROKER_ADOPTION_LEGACY_SUPERVISOR_PREIMAGE_LOCATION_INVALID context=$Context canonical=$canonicalIsPre park=$parkIsPre path=$($object.path)"
                }
                $transitionLease=if($null-ne$BorrowedLegacySupervisorLease){$BorrowedLegacySupervisorLease}elseif($null-ne$LegacyDenialTransition.PreLease){$LegacyDenialTransition.PreLease}elseif($null-ne$LegacyDenialTransition.RestoredLease){$LegacyDenialTransition.RestoredLease}elseif($null-ne$LegacyDenialTransition.CanonicalLease){$LegacyDenialTransition.CanonicalLease}elseif($null-ne$Descriptor.PSObject.Properties['SupervisorLease'] -and $null-ne$Descriptor.SupervisorLease){$Descriptor.SupervisorLease}else{$null}
                if($null-ne$transitionLease){
                    $transitionLease.RequireExact("${Context}_reuse_legacy_supervisor")
                    if($null-ne$BorrowedLegacySupervisorLease){
                        if($null-eq$Descriptor.PSObject.Properties['SupervisorLease']){$Descriptor|Add-Member -NotePropertyName SupervisorLease -NotePropertyValue $transitionLease}else{$Descriptor.SupervisorLease=$transitionLease}
                        if($null-eq$Descriptor.PSObject.Properties['SupervisorLeaseBorrowed']){$Descriptor|Add-Member -NotePropertyName SupervisorLeaseBorrowed -NotePropertyValue $true}else{$Descriptor.SupervisorLeaseBorrowed=$true}
                    }
                }elseif($ReadOnlyLegacySupervisor){
                    $verified=Assert-SynapseAuthorityFileDescriptorPhysicalIdentity -Descriptor $object -ExpectedRole $role -Context "${Context}_$role"
                    $supervisorReadLease=Open-SynapsePhysicalFileReadLease -ParentPath $verified.ParentPath -ParentChain $verified.Chain -Leaf (Split-Path -Leaf $verified.Path) -ExpectedFileId128 $verified.FileId128 -ExpectedSha256 $verified.Sha256 -ExpectedLength $verified.Length -Context "${Context}_lease_$role"
                    if($null-eq$Descriptor.PSObject.Properties['SupervisorLease']){$Descriptor|Add-Member -NotePropertyName SupervisorLease -NotePropertyValue $supervisorReadLease}else{$Descriptor.SupervisorLease=$supervisorReadLease}
                    $ownsDescriptorSupervisorLease=$true
                }else{
                    $transitionLease=if($canonicalIsPre){
                        Open-SynapsePhysicalFileTransitionLease -ParentPath $LegacyDenialTransition.parent -ParentChain $LegacyDenialTransition.parent_chain -Leaf $LegacyDenialTransition.leaf -ExpectedFileId128 $LegacyDenialTransition.pre_file_id_128 -ExpectedSha256 $LegacyDenialTransition.pre_sha256 -ExpectedLength $LegacyDenialTransition.pre_length -Context "${Context}_lease_legacy_supervisor_canonical"
                    }else{
                        Open-SynapsePhysicalFileTransitionLease -ParentPath $LegacyDenialTransition.transaction_root -ParentChain $LegacyDenialTransition.transaction_root_chain -Leaf $LegacyDenialTransition.park_leaf -ExpectedFileId128 $LegacyDenialTransition.pre_file_id_128 -ExpectedSha256 $LegacyDenialTransition.pre_sha256 -ExpectedLength $LegacyDenialTransition.pre_length -Context "${Context}_lease_legacy_supervisor_park"
                    }
                    $LegacyDenialTransition.PreLease=$transitionLease
                    $ownsTransitionLease=$true
                }
                continue
            }
            $verified=Assert-SynapseAuthorityFileDescriptorPhysicalIdentity -Descriptor $object -ExpectedRole $role -Context "${Context}_$role"
            if(Test-SynapseProtectedOsInterpreterRole -Role $role){$leases+=,(Open-SynapseProtectedOsInterpreterLease -Descriptor $object -ExpectedRole $role -Context "${Context}_lease_$role")}else{$leases+=,(Open-SynapsePhysicalFileReadLease -ParentPath $verified.ParentPath -ParentChain $verified.Chain -Leaf (Split-Path -Leaf $verified.Path) -ExpectedFileId128 $verified.FileId128 -ExpectedSha256 $verified.Sha256 -ExpectedLength $verified.Length -Context "${Context}_lease_$role")}
        }
        foreach($lease in $leases){$lease.RequireExact("${Context}_complete")}
        if($null -ne $transitionLease){$transitionLease.RequireExact("${Context}_complete_legacy_supervisor")}
        return @($leases)
    }catch{
        foreach($lease in $leases){try{$lease.Dispose()}catch{[Environment]::FailFast("SYNAPSE_LEGACY_DESCRIPTOR_LEASE_RELEASE_UNPROVEN context=$Context",$_.Exception)}}
        if($ownsDescriptorSupervisorLease -and $null-ne$Descriptor.SupervisorLease){try{$Descriptor.SupervisorLease.Dispose()}catch{[Environment]::FailFast("SYNAPSE_LEGACY_DESCRIPTOR_SUPERVISOR_LEASE_RELEASE_UNPROVEN context=$Context",$_.Exception)};$Descriptor.SupervisorLease=$null}
        if($null-ne$BorrowedLegacySupervisorLease -and $null-ne$Descriptor.PSObject.Properties['SupervisorLeaseBorrowed'] -and [bool]$Descriptor.SupervisorLeaseBorrowed){$Descriptor.SupervisorLease=$null;$Descriptor.SupervisorLeaseBorrowed=$false}
        if($ownsTransitionLease -and $null -ne $transitionLease){try{$transitionLease.Dispose()}catch{[Environment]::FailFast("SYNAPSE_LEGACY_DESCRIPTOR_TRANSITION_LEASE_RELEASE_UNPROVEN context=$Context",$_.Exception)};$LegacyDenialTransition.PreLease=$null}
        throw
    }
}

function Write-SynapseDaemonLifecycleModeRecord {
    param(
        [Parameter(Mandatory=$true)][string]$LogDir,
        [Parameter(Mandatory=$true)][hashtable]$Record
    )

    New-Item -ItemType Directory -Force -Path $LogDir | Out-Null
    $currentPath = Join-Path $LogDir 'daemon-operator-lifecycle-current.json'
    $eventsPath = Join-Path $LogDir 'daemon-operator-lifecycle-events.jsonl'
    $ordered = [ordered]@{ schema = 'synapse_daemon_operator_lifecycle/v1' }
    foreach ($key in $Record.Keys) { $ordered[$key] = $Record[$key] }
    $json = ($ordered | ConvertTo-Json -Depth 12)
    try {
        Set-Content -LiteralPath $currentPath -Value $json -Encoding ascii
        ($ordered | ConvertTo-Json -Compress -Depth 12) | Add-Content -LiteralPath $eventsPath -Encoding ascii
    } catch {
        Die "SYNAPSE_DAEMON_OPERATOR_LIFECYCLE_RECORD_WRITE_FAILED current_path=$currentPath events_path=$eventsPath error=$($_.Exception.Message) remediation=the operator stop/start transaction must leave a durable record; repair the log directory and rerun"
    }
    Info "Synapse daemon operator lifecycle record written current=$currentPath events=$eventsPath"
    return $currentPath
}

function Assert-SynapseInstallPathUnlocked {
    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$Bind,
        [Parameter(Mandatory=$true)][string]$DbPath,
        [int]$TimeoutSeconds = 30
    )

    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
        Info "Installed daemon path does not exist yet; exclusive lock check skipped path=$Path"
        return
    }

    $deadline = (Get-Date).AddSeconds($TimeoutSeconds)
    $lastError = $null
    do {
        try {
            $stream = [System.IO.File]::Open(
                $Path,
                [System.IO.FileMode]::Open,
                [System.IO.FileAccess]::ReadWrite,
                [System.IO.FileShare]::None)
            $stream.Dispose()
            Info "Installed daemon path exclusive-open verified path=$Path"
            return
        } catch {
            $lastError = $_.Exception.Message
            Start-Sleep -Milliseconds 250
        }
    } while ((Get-Date) -lt $deadline)

    $holders = @(Select-SynapseMcpDeployTargetProcesses -Snapshot @(Get-SynapseMcpProcessSnapshot) -Bind $Bind -DbPath $DbPath)
    Die ("SYNAPSE_INSTALL_BINARY_LOCKED path={0} timeout_s={1} error={2}`nverified_synapse_targets:`n{3}`nremediation=installed synapse-mcp.exe is still open after daemon/task drain; inspect the listed exact targets and supervisor logs before retrying binary replacement" -f `
        $Path,
        $TimeoutSeconds,
        $lastError,
        (Format-SynapseMcpProcessSnapshot -Snapshot $holders))
}

function Get-SynapseChromeNativeHostProcessSnapshot {
    param([Parameter(Mandatory=$true)][string]$NativeHostExePath)

    $expectedPath = $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($NativeHostExePath)
    @(Get-CimInstance Win32_Process -Filter "Name='synapse-chrome-native-host.exe'" -ErrorAction SilentlyContinue |
        Where-Object {
            $_.ExecutablePath -and
            ($ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($_.ExecutablePath) -ieq $expectedPath)
        } |
        Select-Object ProcessId,ParentProcessId,Name,ExecutablePath,CommandLine)
}

function Format-SynapseChromeNativeHostProcessSnapshot {
    param($Snapshot)
    $rows = @($Snapshot | ForEach-Object {
        "pid=$($_.ProcessId) ppid=$($_.ParentProcessId) path=$($_.ExecutablePath) cmd=$($_.CommandLine)"
    })
    if ($rows.Count -eq 0) { return '<none>' }
    return ($rows -join "`n")
}

function Assert-SynapseChromeNativeHostStopTarget {
    param(
        [Parameter(Mandatory=$true)]$SnapshotProcess,
        [Parameter(Mandatory=$true)][string]$NativeHostExePath
    )

    $pidValue = [int]$SnapshotProcess.ProcessId
    $current = Get-CimInstance Win32_Process -Filter "ProcessId=$pidValue" -ErrorAction SilentlyContinue
    if (-not $current) {
        Info "Chrome native host stop target already exited pid=$pidValue"
        return $null
    }

    $expectedPath = $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($NativeHostExePath)
    $actualPath = if ($current.ExecutablePath) { $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($current.ExecutablePath) } else { '' }
    if ($current.Name -ine 'synapse-chrome-native-host.exe' -or $actualPath -ine $expectedPath) {
        Die ("SYNAPSE_CHROME_NATIVE_HOST_STOP_TARGET_MISMATCH pid={0} expected_path={1} actual_name={2} actual_path={3} command_line={4} remediation=PID was reused or snapshot was not the Synapse Chrome native host; refusing exact-PID stop" -f `
            $pidValue,
            $expectedPath,
            $current.Name,
            $current.ExecutablePath,
            $current.CommandLine)
    }
    if ($current.CommandLine -notmatch 'chrome-extension://leoocgnkjnplbfdbklajepahofecgfbk/') {
        Die ("SYNAPSE_CHROME_NATIVE_HOST_STOP_UNVERIFIED pid={0} name={1} command_line={2} remediation=command line does not prove the Synapse Chrome extension bridge target; refusing exact-PID stop" -f `
            $pidValue,
            $current.Name,
            $current.CommandLine)
    }

    return $current
}

function Stop-SynapseChromeNativeHostProcesses {
    param(
        [Parameter(Mandatory=$true)][string]$Reason,
        [Parameter(Mandatory=$true)][string]$NativeHostExePath,
        [int]$TimeoutSeconds = 10
    )

    $before = @(Get-SynapseChromeNativeHostProcessSnapshot -NativeHostExePath $NativeHostExePath)
    Info "Chrome native host process stop requested reason=$Reason before_count=$($before.Count)"
    Info ("Chrome native host process stop before:`n{0}" -f (Format-SynapseChromeNativeHostProcessSnapshot -Snapshot $before))
    foreach ($proc in $before) {
        $verified = Assert-SynapseChromeNativeHostStopTarget -SnapshotProcess $proc -NativeHostExePath $NativeHostExePath
        if (-not $verified) { continue }
        $pidValue = [int]$verified.ProcessId
        try {
            Stop-Process -Id $pidValue -Force -ErrorAction Stop
            Info "Chrome native host exact-PID stop issued pid=$pidValue reason=$Reason"
        } catch {
            Die ("SYNAPSE_CHROME_NATIVE_HOST_STOP_FAILED pid={0} reason={1} error={2} remediation=setup only stops verified synapse-chrome-native-host.exe PIDs; it never stops cmd.exe/native-messaging wrapper or terminal processes" -f `
                $pidValue,
                $Reason,
                $_.Exception.Message)
        }
    }

    $deadline = (Get-Date).AddSeconds($TimeoutSeconds)
    do {
        Start-Sleep -Milliseconds 250
        $after = @(Get-SynapseChromeNativeHostProcessSnapshot -NativeHostExePath $NativeHostExePath)
        if ($after.Count -eq 0) {
            Info "Chrome native host process stop verified reason=$Reason after_count=0"
            return
        }
    } while ((Get-Date) -lt $deadline)

    $remaining = @(Get-SynapseChromeNativeHostProcessSnapshot -NativeHostExePath $NativeHostExePath)
    Die ("SYNAPSE_CHROME_NATIVE_HOST_STOP_FAILED reason={0} timeout_s={1} remaining_count={2} remaining=`n{3}" -f `
        $Reason, $TimeoutSeconds, $remaining.Count, (Format-SynapseChromeNativeHostProcessSnapshot -Snapshot $remaining))
}

# ---------------------------------------------------------------------------
# Uninstall path
# ---------------------------------------------------------------------------
$maintenanceReason = if ($Remove) { 'remove' } elseif ($Stop) { 'stop' } elseif ($Start) { 'start' } elseif ($ResumeChromeBridgePending) { 'resume_chrome_bridge' } else { 'setup' }

# #2083: the operator lifecycle modes are exclusive of every other mode and of
# each other. They share the maintenance lock with setup/remove so two agents
# cannot drive daemon lifecycle concurrently.
$synapseExclusiveModes = @()
if ($Stop) { $synapseExclusiveModes += '-Stop' }
if ($Start) { $synapseExclusiveModes += '-Start' }
if ($Remove) { $synapseExclusiveModes += '-Remove' }
if ($ResumeChromeBridgePending) { $synapseExclusiveModes += '-ResumeChromeBridgePending' }
if ($synapseExclusiveModes.Count -gt 1) {
    Die "SYNAPSE_SETUP_MODE_CONFLICT modes=$($synapseExclusiveModes -join ',') remediation=pass exactly one of -Stop, -Start, -Remove or -ResumeChromeBridgePending"
}
if (($Stop -or $Start) -and $SkipBuild) {
    Die "SYNAPSE_SETUP_MODE_CONFLICT modes=$($synapseExclusiveModes -join ','),-SkipBuild remediation=-Stop/-Start never build or install anything, so -SkipBuild is meaningless with them; drop it"
}
if ($Start -and $ForceRestart) {
    Die "SYNAPSE_SETUP_MODE_CONFLICT modes=-Start,-ForceRestart remediation=-Start refuses to start on top of a live daemon rather than forcing one; run -Stop -ForceStop first if a forced takedown is genuinely intended"
}
if($Purge-and-not$Remove){Die 'SYNAPSE_SETUP_MODE_CONFLICT modes=-Purge_without_-Remove remediation=-Purge is valid only with -Remove'}
if($ConfirmVaultDestruction-and-not($Remove-and$Purge)){Die 'SYNAPSE_SETUP_MODE_CONFLICT modes=-ConfirmVaultDestruction_without_-Remove_-Purge remediation=confirmation is consumed only by an exact purge transaction'}
$purgeContractValue=[ordered]@{schema='synapse_setup_purge_target_contract/v1';db_path=(Get-SynapseNormalizedDirectoryPath -Path $DbPath);profiles_dir=(Get-SynapseNormalizedDirectoryPath -Path $ProfilesDir);token_path=[System.IO.Path]::GetFullPath($TokenPath);record_root=(Get-SynapseNormalizedDirectoryPath -Path (Join-Path $env:LOCALAPPDATA 'synapse\deletion-records'))}
$purgePathContract=[pscustomobject][ordered]@{DbPath=[string]$purgeContractValue.db_path;ProfilesDir=[string]$purgeContractValue.profiles_dir;TokenPath=[string]$purgeContractValue.token_path;RecordRoot=[string]$purgeContractValue.record_root;Contract=$purgeContractValue;ContractSha256=(Get-SynapseSha256Hex -Text (Get-SynapseCanonicalJson -Value $purgeContractValue)).ToUpperInvariant()}
if($Remove){$purgePathContract=Assert-SynapsePurgePathContract -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -RuntimeBinDir $RuntimeBinDir -LogDir $LogDir -MaintenanceLockPath $MaintenanceLockPath -ExePath $ExePath -SourceDir $SourceDir -CodexToolSurfaceSnapshotPath $CodexToolSurfaceSnapshotPath -ChromeNativeHostExePath $ChromeNativeHostExePath -ChromeBridgePendingPath $ChromeBridgePendingPath}

# Validate the parameter combination before taking the maintenance lock or doing
# any preflight work (#1873). -SourceDir is consumed by candidate validation and
# model-pin verification, not only by the build, so -SkipBuild does not make it
# optional. Discovering that inside a Mandatory parameter binding stranded the
# operator with a raw PowerShell exception after several minutes of preflight,
# and without naming the parameter, the reason, or the value to supply.
if (-not $Remove -and -not $Stop -and -not $Start -and [string]::IsNullOrWhiteSpace($SourceDir)) {
    $sourceDirMessage = @(
        ("SYNAPSE_SETUP_SOURCE_DIR_REQUIRED skip_build={0} remove={1} stop={2} start={3}" -f [bool]$SkipBuild, [bool]$Remove, [bool]$Stop, [bool]$Start),
        'source_of_truth=-SourceDir parameter',
        ('remediation=pass -SourceDir <path to the synapse source checkout containing Cargo.toml>. ' +
         'It is required whether or not -SkipBuild is set, because candidate-daemon validation and ' +
         'embedded model-pin verification both read the checkout. With -SkipBuild the already-installed ' +
         'binary is what gets validated and deployed; omit -SkipBuild to build and deploy that checkout.')
    ) -join ' '
    Die $sourceDirMessage
}

# Pure-input fence (#2211). Everything in this block depends only on bound
# parameters, environment-backed parameter defaults, and read-only prerequisite
# inspection. It MUST stay before parent waiting, maintenance-lock acquisition,
# artifact cleanup, build output creation, or candidate launch. In particular,
# parameter validation attributes do not validate default values, so ActiveIssue
# must be normalized explicitly here to cover SYNAPSE_ACTIVE_ISSUE as well as an
# explicitly supplied argument.
if ($maintenanceReason -eq 'setup') {
    $ActiveIssue = Get-SynapseNormalizedIssueRef -Issue $ActiveIssue

    if ($ManualInstallHealthRollbackPauseMode -ne 'normal' -and -not $ManualInstallHealthRollbackProbe) {
        Die "SYNAPSE_MANUAL_INSTALL_HEALTH_ROLLBACK_PAUSE_MODE_WITHOUT_PROBE mode=$ManualInstallHealthRollbackPauseMode remediation=-ManualInstallHealthRollbackPauseMode is only valid with -ManualInstallHealthRollbackProbe because it intentionally changes rollback maintenance-pause behavior"
    }
    if ($ManualInstallHealthRollbackProbe) {
        if (-not $ForceRestart) {
            Die "SYNAPSE_MANUAL_INSTALL_HEALTH_ROLLBACK_PROBE_REQUIRES_FORCE_RESTART remediation=the rollback drill intentionally drains and restarts the live daemon, so rerun with -ForceRestart during a maintenance window"
        }
        if ($SkipBuild) {
            Die "SYNAPSE_MANUAL_INSTALL_HEALTH_ROLLBACK_PROBE_REQUIRES_BUILD remediation=the rollback drill needs a real candidate that differs from the installed daemon; -SkipBuild cannot produce a backup/candidate handoff"
        }
        if ($script:SynapsePostExitStartOnly) {
            Die "SYNAPSE_MANUAL_INSTALL_HEALTH_ROLLBACK_PROBE_POST_EXIT_UNSUPPORTED remediation=post-exit continuation only starts the already-installed daemon; run the rollback drill from the primary setup process"
        }
    }

    if ([string]::IsNullOrWhiteSpace($CalyxConfigPath)) {
        $script:SynapseManagedCalyxConfig = $true
        $managedCalyxIdentity = Get-SynapseManagedCpuOnlyCalyxConfigIdentity
        $CalyxConfigPath = [System.IO.Path]::GetFullPath(
            (Join-Path $RuntimeBinDir ("synapse-calyx-cpu-only-{0}.toml" -f $managedCalyxIdentity.sha256)))
        Info "Managed Calyx tuning identity selected path=$CalyxConfigPath sha256=$($managedCalyxIdentity.sha256) policy=content_addressed_immutable"
    } else {
        try {
            $CalyxConfigPath = [System.IO.Path]::GetFullPath($CalyxConfigPath)
        } catch {
            Die "SYNAPSE_CALYX_CONFIG_PATH_INVALID path=$CalyxConfigPath error=$($_.Exception.Message) remediation=pass an absolute or resolvable local TOML file path to -CalyxConfigPath"
        }
        if (-not (Test-Path -LiteralPath $CalyxConfigPath -PathType Leaf)) {
            Die "SYNAPSE_CALYX_CONFIG_FILE_MISSING path=$CalyxConfigPath remediation=create the exact [calyx] TOML file or omit -CalyxConfigPath to use validated defaults"
        }
        try {
            $configStream = [System.IO.File]::Open($CalyxConfigPath, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
            $configStream.Dispose()
        } catch {
            Die "SYNAPSE_CALYX_CONFIG_FILE_UNREADABLE path=$CalyxConfigPath error=$($_.Exception.Message) remediation=repair the exact file permissions before setup builds or touches the live daemon"
        }
        $script:SynapseCalyxConfigSha256 = Get-SynapseFileSha256 -Path $CalyxConfigPath
        Info "Explicit Calyx tuning source verified path=$CalyxConfigPath; candidate and installed daemon will both receive --calyx-config."
    }

    if (-not (Test-Path -LiteralPath (Join-Path $SourceDir 'Cargo.toml') -PathType Leaf)) {
        Die "-SourceDir '$SourceDir' has no Cargo.toml. Point it at a synapse source checkout on a LOCAL drive."
    }
    if ($SourceDir -match '^\\\\' -or $SourceDir -match '^[Zz]:\\home\\') {
        Die "-SourceDir '$SourceDir' looks like a UNC / WSL-mapped path. Build from a real local copy: building over \\wsl.localhost bakes transient drive paths into the binary."
    }

    # Source profiles are part of the candidate/install contract, not optional
    # state that may be borrowed from a prior deployment (#2212). Validate once
    # and carry this exact directory through candidate preflight and deployment.
    $srcProfiles = Join-Path $SourceDir 'crates\synapse-profiles\profiles'
    if (-not (Test-Path -LiteralPath $srcProfiles -PathType Container)) {
        Die "SYNAPSE_SOURCE_PROFILES_MISSING source=$srcProfiles source_dir=$SourceDir remediation=restore the tracked crates\synapse-profiles\profiles directory in the named checkout; setup refuses to validate a new daemon against stale deployed profiles"
    }
    $candidateProfilesDir = $srcProfiles
    $candidateProfileCount = @(Get-ChildItem -LiteralPath $candidateProfilesDir -Filter '*.toml' -File).Count
    if ($candidateProfileCount -lt 1) {
        Die "SYNAPSE_SOURCE_PROFILES_EMPTY source=$candidateProfilesDir source_dir=$SourceDir remediation=restore at least one tracked bundled .toml profile; setup refuses to validate a candidate against an empty or previously deployed profile set"
    }

    # An existing token is an input prerequisite. A missing token is created in
    # the later token phase, but malformed existing bytes are knowable now and
    # must not be discovered after a release build.
    if (Test-Path -LiteralPath $TokenPath -PathType Leaf) {
        try {
            $preflightToken = (Get-Content -LiteralPath $TokenPath -Raw -ErrorAction Stop).Trim()
        } catch {
            Die "SYNAPSE_TOKEN_PREFLIGHT_READ_FAILED path=$TokenPath error=$($_.Exception.Message) remediation=repair the token file permissions or remove the unreadable file so setup can create a new token before rerunning"
        }
        if ($preflightToken.Length -lt 16) {
            Die "SYNAPSE_TOKEN_PREFLIGHT_TOO_SHORT path=$TokenPath chars=$($preflightToken.Length) remediation=remove the malformed token and rerun setup so a cryptographically random replacement can be created before candidate launch"
        }
        Remove-Variable -Name preflightToken -ErrorAction SilentlyContinue
    }

    $cargo = "$env:USERPROFILE\.cargo\bin\cargo.exe"
    if (-not $SkipBuild) {
        if (-not (Test-Path -LiteralPath $cargo -PathType Leaf)) {
            Die "cargo not found at $cargo. Install the Rust toolchain (https://rustup.rs) on Windows, then re-run. Synapse builds with the current stable toolchain."
        }

        # #1819: Cargo resolves these path dependencies while parsing manifests,
        # before a build script can emit a useful diagnostic.
        $vendoredCalyxCrates = Join-Path $SourceDir 'calyx\crates'
        $requiredCalyxCrates = @(
            'calyx-assay', 'calyx-aster', 'calyx-core', 'calyx-forge', 'calyx-ledger',
            'calyx-lodestar', 'calyx-loom', 'calyx-paths', 'calyx-registry',
            'calyx-search', 'calyx-sextant'
        )
        $missingCalyxCrates = @(
            $requiredCalyxCrates | Where-Object {
                -not (Test-Path -LiteralPath (Join-Path $vendoredCalyxCrates (Join-Path $_ 'Cargo.toml')) -PathType Leaf)
            }
        )
        if ($missingCalyxCrates.Count -gt 0) {
            Die ("SYNAPSE_VENDORED_CALYX_TREE_MISSING source_dir=$SourceDir " +
                 "vendored_path=$vendoredCalyxCrates missing_crate_count=$($missingCalyxCrates.Count) " +
                 "missing_crates=$($missingCalyxCrates -join ',') " +
                 "detail=crates\synapse-calyx depends on these through cargo path dependencies, which are " +
                 "resolved before any build script runs, so the build cannot report this itself. " +
                 "The tree is tracked in git and is NOT gitignored (.gitignore excludes only /calyx/target/). " +
                 "remediation=run 'git checkout -- calyx' in $SourceDir to restore the vendored Calyx " +
                 "workspace, confirm 'git status' reports no deletions under calyx/, then re-run setup")
        }

        # Resolve/authorize the output tree and select the physical math build
        # capability before maintenance state or acquisition artifacts change.
        $cargoTargetResolution = Resolve-SynapseCargoTargetDirectory `
            -SourceDir $SourceDir `
            -Requested $CargoTarget `
            -AllowAlternate ([bool]$AllowAlternateBuildTarget)
        $CargoTarget = $cargoTargetResolution.path
        $cudaBuildCapability = Get-SynapseCudaBuildCapability
    }
}

Wait-SynapsePostExitParent -ParentPid $PostExitParentPid -Reason $PostExitContinuationReason
Acquire-SynapseSetupMaintenanceLock -Path $MaintenanceLockPath -Reason $maintenanceReason
Acquire-SynapseBrokerDecommissionMutex
if($Remove){
    $lockedDecommissionPathContract=Assert-SynapsePurgePathContract -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -RuntimeBinDir $RuntimeBinDir -LogDir $LogDir -MaintenanceLockPath $MaintenanceLockPath -ExePath $ExePath -SourceDir $SourceDir -CodexToolSurfaceSnapshotPath $CodexToolSurfaceSnapshotPath -ChromeNativeHostExePath $ChromeNativeHostExePath -ChromeBridgePendingPath $ChromeBridgePendingPath
    if([string]$lockedDecommissionPathContract.ContractSha256-ine[string]$purgePathContract.ContractSha256-or(Get-SynapseCanonicalJson -Value $lockedDecommissionPathContract.Contract)-cne(Get-SynapseCanonicalJson -Value $purgePathContract.Contract)){Die 'SYNAPSE_BROKER_DECOMMISSION_PATH_CONTRACT_DRIFT boundary=maintenance_lock'}
    $purgePathContract=$lockedDecommissionPathContract
}
$pendingPurge=Get-SynapsePendingPurgeRecord -PathContract $purgePathContract
if($null-ne$pendingPurge){
    $purgeTerminal=($null-ne$pendingPurge.PSObject.Properties['Completed']-and$null-ne$pendingPurge.Completed)
    $legacyPurgeRecord=[string]$pendingPurge.Authorized.Path
    foreach($record in @($pendingPurge.Completed,$pendingPurge.Ready,$pendingPurge.OperatorCleanup,$pendingPurge.Confirmation,$pendingPurge.Authorized)){if($null-ne$record-and$null-ne$record.Lease){$record.Lease.Dispose()}}
    $pendingPurge=$null
    if(-not$purgeTerminal){Die "SYNAPSE_LEGACY_PURGE_NONTERMINAL_SUPERSEDED record=$legacyPurgeRecord remediation=preserve the exact deletion-records bundle; the legacy purge cannot resume because it would delete data while retaining the broker task/process authority. Complete a versioned migration before any setup/remove mutation"}
}
Initialize-SynapseAuthorityRuntimeForSetup
$pendingDecommission=Get-SynapsePendingBrokerDecommissionRecord -RuntimeBinDir $RuntimeBinDir -TaskName $TaskName -ExePath $ExePath -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -Bind $Bind -LogDir $LogDir -MaintenanceLockPath $MaintenanceLockPath -Remove:$Remove -Purge:$Purge
if($null-ne$pendingDecommission-and$Remove-and($null-ne$pendingDecommission.Completed-or$null-ne$pendingDecommission.Parked)){
    try{
        if($null-eq$pendingDecommission.Completed){
            if($Purge-and$ConfirmVaultDestruction-and$null-eq$pendingDecommission.Confirmation-and$null-eq$pendingDecommission.CleanupReady){$pendingDecommission.Confirmation=New-SynapseBrokerDecommissionConfirmationRecord -Authorized $pendingDecommission.Authorized}
            $earlyDeleteBoundaryContract=Assert-SynapsePurgePathContract -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -RuntimeBinDir $RuntimeBinDir -LogDir $LogDir -MaintenanceLockPath $MaintenanceLockPath -ExePath $ExePath -SourceDir $SourceDir -CodexToolSurfaceSnapshotPath $CodexToolSurfaceSnapshotPath -ChromeNativeHostExePath $ChromeNativeHostExePath -ChromeBridgePendingPath $ChromeBridgePendingPath
            if([string]$earlyDeleteBoundaryContract.ContractSha256-ine[string]$purgePathContract.ContractSha256-or(Get-SynapseCanonicalJson -Value $earlyDeleteBoundaryContract.Contract)-cne(Get-SynapseCanonicalJson -Value $purgePathContract.Contract)){Die 'SYNAPSE_BROKER_DECOMMISSION_PATH_CONTRACT_DRIFT boundary=early_delete'}
            $pendingDecommission.Completed=Resume-SynapseBrokerDecommission -Pending $pendingDecommission -Context 'broker_decommission_early_resume'
            if($null-eq$pendingDecommission.Completed){Die 'SYNAPSE_BROKER_DECOMMISSION_EARLY_RESUME_NO_TERMINAL'}
        }
        [void](Write-SynapseBrokerDecommissionCompletionLifecycle -Pending $pendingDecommission -LogDir $LogDir -Context 'broker_decommission_early_terminal')
    }finally{Close-SynapsePendingBrokerDecommissionRecord -Pending $pendingDecommission;$pendingDecommission=$null}
    Release-SynapseBrokerDecommissionMutex
    Release-SynapseSetupMaintenanceLock -State released
    return
}
if($null-ne$pendingDecommission){Close-SynapsePendingBrokerDecommissionRecord -Pending $pendingDecommission;$pendingDecommission=$null}
$removeMissingTokenPreflight=[pscustomobject][ordered]@{Missing=$false;TokenAuthority=$null;InventoryFingerprintSha256=''}
if($Remove){
    $removeMissingTokenPreflight=Assert-SynapseBrokerDecommissionMissingTokenGlobalPreflight -RuntimeBinDir $RuntimeBinDir -TaskName $TaskName -ExePath $ExePath -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -LogDir $LogDir -MaintenanceLockPath $MaintenanceLockPath -HealthTimeoutSeconds ([Math]::Min(900,[Math]::Max(120,$InstallHealthTimeoutSeconds)))
    Set-SynapseBrokerDecommissionGlobalTokenAuthorityBoundary -Descriptor $removeMissingTokenPreflight.TokenAuthority -ExpectedPath $TokenPath -Context 'broker_decommission_global_token_boundary_acquire'
    Assert-SynapseRestartAllowed -Reason 'remove' -Bind $Bind -DbPath $DbPath -TokenPath $TokenPath -HealthTimeoutSec ([Math]::Min(300,[Math]::Max(120,$InstallHealthTimeoutSeconds))) -ForceRestart:$ForceRestart
    Assert-SynapseBrokerDecommissionGlobalTokenAuthorityBoundary -Descriptor $removeMissingTokenPreflight.TokenAuthority -ExpectedPath $TokenPath -Context 'broker_decommission_global_token_boundary_after_restart_guard'
}
if(-not$Remove){Release-SynapseBrokerDecommissionMutex}
[void](Resume-SynapseCodexLauncherInstallTransactions -Root (Get-SynapseCodexLauncherInstallRoot) -Context 'maintenance_lock_recovery')
if($Purge){
    $lockedPurgePathContract=Assert-SynapsePurgePathContract -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -RuntimeBinDir $RuntimeBinDir -LogDir $LogDir -MaintenanceLockPath $MaintenanceLockPath -ExePath $ExePath -SourceDir $SourceDir -CodexToolSurfaceSnapshotPath $CodexToolSurfaceSnapshotPath -ChromeNativeHostExePath $ChromeNativeHostExePath -ChromeBridgePendingPath $ChromeBridgePendingPath
    if([string]$lockedPurgePathContract.ContractSha256-ine[string]$purgePathContract.ContractSha256-or(Get-SynapseCanonicalJson -Value $lockedPurgePathContract.Contract)-cne(Get-SynapseCanonicalJson -Value $purgePathContract.Contract)){Die 'SYNAPSE_PURGE_PATH_CONTRACT_DRIFT boundary=maintenance_lock'}
    $purgePathContract=$lockedPurgePathContract
}
$globalRecoveryMode=if($Stop){'stop'}elseif($Start){'start'}elseif($Remove){'remove'}elseif($ResumeChromeBridgePending){'resume_chrome'}else{'setup'}
$globalRecoveryAuthority=$null
$globalRecoveryTaskInfrastructure=$null
$globalRecoveryInventory=$null
$globalRecoverySelection=$null
$globalRecoveryPreviousFingerprint=''
$purgeOperatorStopRecord=$null
$globalRecoveryMaxPasses64=1L + (2L * [int64]$script:SynapseDeploymentArtifactMaxDirectEntries) + (3L * [int64]$script:SynapseAuthorityMaxEpochs)
if($globalRecoveryMaxPasses64 -lt 1 -or $globalRecoveryMaxPasses64 -gt [int]::MaxValue){Die "SYNAPSE_GLOBAL_RECOVERY_BOUND_OVERFLOW computed=$globalRecoveryMaxPasses64"}
$globalRecoveryMaxPasses=[int]$globalRecoveryMaxPasses64
for($globalRecoveryPass=1;$globalRecoveryPass -le $globalRecoveryMaxPasses;$globalRecoveryPass++){
    if($null -ne $globalRecoveryTaskInfrastructure){Close-SynapseBrokerTaskReceiptInfrastructure -Infrastructure $globalRecoveryTaskInfrastructure;$globalRecoveryTaskInfrastructure=$null}
    if($Remove){Assert-SynapseBrokerDecommissionGlobalTokenAuthorityBoundary -Descriptor $removeMissingTokenPreflight.TokenAuthority -ExpectedPath $TokenPath -Context "broker_decommission_global_pass_${globalRecoveryPass}_before_inventory"}
    $globalRecoveryInventory=Get-SynapseGlobalRecoveryInventory -LogDir $LogDir -ProfilesDir $ProfilesDir -RuntimeBinDir $RuntimeBinDir
    $fingerprint=[string]$globalRecoveryInventory.FingerprintSha256
    if([bool]$removeMissingTokenPreflight.Missing){
        $missingTokenSelection=Select-SynapseGlobalRecoveryAction -Inventory $globalRecoveryInventory -Mode setup
        $missingTokenTerminalV1=@($globalRecoveryInventory.V1|Where-Object{[string]$_.State-in@('committed','rolled_back')})
        $missingTokenTerminalV3=@($globalRecoveryInventory.LegacyV3|Where-Object{[string]$_.EffectiveState-ceq'rolled_back'})
        if(-not[bool]$missingTokenSelection.Allowed-or[string]$missingTokenSelection.Action-cne'none'-or$missingTokenTerminalV1.Count-ne0-or$missingTokenTerminalV3.Count-ne0){Die "SYNAPSE_BROKER_DECOMMISSION_MISSING_TOKEN_GLOBAL_STATE_CHANGED pass=$globalRecoveryPass allowed=$([bool]$missingTokenSelection.Allowed) action=$($missingTokenSelection.Action) terminal_v1=$($missingTokenTerminalV1.Count) terminal_v3=$($missingTokenTerminalV3.Count)"}
    }

    # Committed task/adoption receipts are permanent prerequisites rather than
    # recovery owners.  Prove their live Scheduler, immutable-object, legacy
    # floor, and canonical gate/roster identities before *any* cleanup or owner
    # dispatch in this pass.  The receipt bundle retains exact object leases
    # through the immediately following recovery boundary.
    $passCommittedTasks=@($globalRecoveryInventory.TaskEpochs|Where-Object{[string]$_.RecordKind -ceq 'journal' -and [string]$_.State -ceq 'commit_decided'})
    if($passCommittedTasks.Count -ge 1){
        $taskLayout=Get-SynapseAuthorityLayoutReadOnly -RuntimeBinDir $RuntimeBinDir -RequireAuthorityRoot
        $latestPassCommittedTask=@($passCommittedTasks|Sort-Object{[int64]$_.Initial.task_epoch})[-1]
        $recoveryBootstrapSource=[IO.Path]::GetFullPath((Join-Path $SourceDir 'target\release\synapse-supervisor-bootstrap.exe'))
        $recoveryPowerShell=[IO.Path]::GetFullPath((Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'))
        if(-not(Test-Path -LiteralPath $recoveryBootstrapSource -PathType Leaf)){Die "SYNAPSE_GLOBAL_RECOVERY_CURRENT_BOOTSTRAP_MISSING path=$recoveryBootstrapSource remediation=run the repo release build before authority recovery"}
        $globalRecoveryTaskInfrastructure=Initialize-SynapseAuthorityBrokerInfrastructure -Layout $taskLayout -BootstrapSourcePath $recoveryBootstrapSource -PowerShellPath $recoveryPowerShell -WorkingDirectory $RuntimeBinDir -LogDir $LogDir
        if((Get-SynapseNormalizedDirectoryPath -Path ([string]$globalRecoveryTaskInfrastructure.TaskReceipt.Root))-ine(Get-SynapseNormalizedDirectoryPath -Path ([string]$latestPassCommittedTask.Root))){
            Info "SYNAPSE_GLOBAL_RECOVERY_TASK_SUCCESSOR_COMMITTED pass=$globalRecoveryPass predecessor=$($latestPassCommittedTask.Root) successor=$($globalRecoveryTaskInfrastructure.TaskReceipt.Root) action=reinventory_before_other_domains"
            $globalRecoveryPreviousFingerprint=$fingerprint
            continue
        }
    }
    $globalRecoveryPrerequisite=Assert-SynapseGlobalCommittedAuthorityPreflight -Inventory $globalRecoveryInventory -TaskInfrastructure $globalRecoveryTaskInfrastructure -RuntimeBinDir $RuntimeBinDir -RequestedLegacyTaskName $TaskName -DecommissionStructuralOnly:$Remove
    if([bool]$removeMissingTokenPreflight.Missing){
        if([string]$globalRecoveryPrerequisite.ControlState-cne'parked'){Die "SYNAPSE_BROKER_DECOMMISSION_MISSING_TOKEN_CONTROL_STATE_CHANGED pass=$globalRecoveryPass state=$($globalRecoveryPrerequisite.ControlState)"}
    }
    if($Remove){Assert-SynapseBrokerDecommissionGlobalTokenAuthorityBoundary -Descriptor $removeMissingTokenPreflight.TokenAuthority -ExpectedPath $TokenPath -Context "broker_decommission_global_pass_${globalRecoveryPass}_after_prerequisite"}
    $globalRecoverySelection=Select-SynapseGlobalRecoveryAction -Inventory $globalRecoveryInventory -Mode $globalRecoveryMode
    if(-not [bool]$globalRecoverySelection.Allowed){Die ([string]$globalRecoverySelection.Error)}
    if($globalRecoveryPreviousFingerprint -and $fingerprint -ieq $globalRecoveryPreviousFingerprint){
        Die "SYNAPSE_GLOBAL_RECOVERY_NO_PROGRESS action=$($globalRecoverySelection.Action) fingerprint=$fingerprint pass=$globalRecoveryPass remediation=preserve every domain; a recovery action must produce an exact new inventory before any unrelated mutation"
    }
    $globalRecoveryPreviousFingerprint=$fingerprint
    if($Remove){Assert-SynapseBrokerDecommissionGlobalTokenAuthorityBoundary -Descriptor $removeMissingTokenPreflight.TokenAuthority -ExpectedPath $TokenPath -Context "broker_decommission_global_pass_${globalRecoveryPass}_mutation_boundary"}

    # Terminal legacy receipts are not owners, but their exact bounded storage
    # must be removed before the selector can hand off an empty namespace.  v3
    # is cleanup-only here: armed/candidate/commit states were refused above.
    $terminalV1=@($globalRecoveryInventory.V1|Where-Object{[string]$_.State -in @('committed','rolled_back')}|Sort-Object Root)
    if($terminalV1.Count -gt 0){
        $terminal=$terminalV1[0]
        [void](Remove-SynapseDeploymentTransactionArtifact -Path ([string]$terminal.Root) -ExpectedRoot ([string]$globalRecoveryInventory.Roots.V1.Path) -ExpectedState ([string]$terminal.State) -Reason 'global_legacy_v1_terminal_cleanup')
        continue
    }
    $terminalV3=@($globalRecoveryInventory.LegacyV3|Where-Object{[string]$_.EffectiveState -ceq 'rolled_back'}|Sort-Object Root)
    if($terminalV3.Count -gt 0){
        $terminal=$terminalV3[0]
        [void](Remove-SynapseDeploymentTransactionArtifact -Path ([string]$terminal.Root) -ExpectedRoot ([string]$globalRecoveryInventory.Roots.Application.Path) -ExpectedState rolled_back -Reason 'global_legacy_v3_terminal_cleanup' -Domain application)
        continue
    }

    $action=[string]$globalRecoverySelection.Action
    if($action -ceq 'none'){break}
    $record=$globalRecoverySelection.Record
    Info "SYNAPSE_GLOBAL_RECOVERY_DISPATCH pass=$globalRecoveryPass action=$action root=$($record.Root) state=$($record.State) effective_state=$($record.EffectiveState) fingerprint=$fingerprint"
    switch($action){
        'adoption_predecessor_cleanup' {
            if($null-eq$globalRecoverySelection.Successor){Die "SYNAPSE_GLOBAL_RECOVERY_PREDECESSOR_CLEANUP_SUCCESSOR_MISSING predecessor=$($record.Root)"}
            [void](Remove-SynapseAuthorityCommittedSuccessorPredecessor -PredecessorRecord $record -SuccessorRecord $globalRecoverySelection.Successor -ExpectedParent ([string]$globalRecoveryInventory.Roots.Adoption.Path) -Context 'global_committed_successor_predecessor_cleanup')
        }
        'legacy_v1' {
            if([string]$record.RecordKind -ceq 'unarmed'){
                [void](Remove-SynapseDeploymentTransactionArtifact -Path ([string]$record.Root) -ExpectedRoot ([string]$globalRecoveryInventory.Roots.V1.Path) -ExpectedState unarmed -Reason 'global_legacy_v1_unarmed_cleanup')
            }elseif([string]$record.State -ceq 'armed'){
                [void](Complete-SynapseLegacyV1NoMutationRecovery -ManifestPath (Join-Path ([string]$record.Root) 'transaction.json') -Manifest $record.Initial -ExpectedManifestSha256 ([string]$record.ManifestSha256) -ExpectedTaskName ([string]$record.Initial.task_name))
                [void](Remove-SynapseDeploymentTransactionArtifact -Path ([string]$record.Root) -ExpectedRoot ([string]$globalRecoveryInventory.Roots.V1.Path) -ExpectedState rolled_back -Reason 'global_legacy_v1_recovered_cleanup')
            }else{Die "SYNAPSE_GLOBAL_RECOVERY_V1_DISPATCH_STATE_INVALID root=$($record.Root) kind=$($record.RecordKind) state=$($record.State)"}
        }
        'task' {
            if([string]$record.RecordKind -ceq 'unarmed'){
                [void](Remove-SynapseDeploymentTransactionArtifact -Path ([string]$record.Root) -ExpectedRoot ([string]$globalRecoveryInventory.Roots.Task.Path) -ExpectedState unarmed -Reason 'global_broker_task_unarmed_cleanup' -Domain task)
            }elseif([string]$record.State -in @('armed','candidate_ready')){
                $taskLayout=Get-SynapseAuthorityLayoutReadOnly -RuntimeBinDir $RuntimeBinDir -RequireAuthorityRoot
                Close-SynapseBrokerTaskReceiptInfrastructure -Infrastructure $globalRecoveryTaskInfrastructure
                $globalRecoveryTaskInfrastructure=Complete-SynapseBrokerTaskCreateEpoch -Layout $taskLayout -Journal $record.Journal
            }else{Die "SYNAPSE_GLOBAL_RECOVERY_TASK_DISPATCH_STATE_INVALID root=$($record.Root) kind=$($record.RecordKind) state=$($record.State)"}
        }
        'adoption' {
            if([string]$record.RecordKind -ceq 'unarmed'){
                [void](Remove-SynapseDeploymentTransactionArtifact -Path ([string]$record.Root) -ExpectedRoot ([string]$globalRecoveryInventory.Roots.Adoption.Path) -ExpectedState unarmed -Reason 'global_broker_adoption_unarmed_cleanup' -Domain authority)
                break
            }
            $taskReceiptRecords=@($globalRecoveryInventory.TaskEpochs|Where-Object{[string]$_.RecordKind -ceq 'journal' -and [string]$_.State -ceq 'commit_decided'})
            if($taskReceiptRecords.Count -lt 1){Die "SYNAPSE_GLOBAL_RECOVERY_ADOPTION_TASK_RECEIPT_MISSING root=$($record.Root) count=$($taskReceiptRecords.Count)"}
            $taskReceiptRecord=@($taskReceiptRecords|Sort-Object{[int64]$_.Initial.task_epoch})[-1]
            if($null -eq $globalRecoveryTaskInfrastructure){
                $taskLayout=Get-SynapseAuthorityLayoutReadOnly -RuntimeBinDir $RuntimeBinDir -RequireAuthorityRoot
                $globalRecoveryTaskInfrastructure=Complete-SynapseBrokerTaskCreateEpoch -Layout $taskLayout -Journal $taskReceiptRecord.Journal
            }
            $taskInitial=$taskReceiptRecord.Initial
            $bootstrapObjects=@($taskInitial.immutable_objects|Where-Object{[string]$_.role -ceq 'broker_bootstrap'})
            if($bootstrapObjects.Count -ne 1){Die "SYNAPSE_GLOBAL_RECOVERY_ADOPTION_BOOTSTRAP_AMBIGUOUS root=$($record.Root) count=$($bootstrapObjects.Count)"}
            $initial=$record.Initial
            $priorAuthority=if($null -ne $initial){[string]$initial.prior_authority}else{'absent'}
            if($null -ne $initial -and $priorAuthority -ceq 'absent' -and (Test-SynapseScheduledTaskExistsExact -Name ([string]$initial.task_name))){
                $floor=Get-SynapseRetainedDeniedLegacyFloor -TaskName ([string]$initial.task_name) -RuntimeBinDir $RuntimeBinDir -SupervisorPath ([string]$initial.legacy_denial_stub_transition.path) -LogDir $LogDir -Bind ([string]$initial.bind) -DbPath ([string]$initial.db_path) -TaskOnly
                if($null-eq$floor-or[string]$floor.legacy_gate.file_id_128-ine[string]$initial.legacy_gate_transition.post_file_id_128-or[string]$floor.legacy_gate.sha256-ine[string]$initial.legacy_gate_transition.post_sha256-or[int64]$floor.legacy_gate.length-ne[int64]$initial.legacy_gate_transition.post_length-or[string]$floor.legacy_denial_stub.file_id_128-ine[string]$initial.legacy_denial_stub_transition.post_file_id_128-or[string]$floor.legacy_denial_stub.sha256-ine[string]$initial.legacy_denial_stub_transition.post_sha256-or[int64]$floor.legacy_denial_stub.length-ne[int64]$initial.legacy_denial_stub_transition.post_length){Die "SYNAPSE_GLOBAL_RECOVERY_FRESH_LEGACY_TASK_APPEARED root=$($record.Root) task=$($initial.task_name) reason=not_exact_denied_floor"}
            }
            $tokenRead=Read-SynapseSetupTokenForRestartGuard -TokenPath $(if($null -ne $initial){[string]$initial.token_path}else{$TokenPath})
            if(-not [bool]$tokenRead.Ok -and ($priorAuthority -ceq 'legacy'-or$Remove)){Die "$($tokenRead.Code) reason=global_adoption_recovery $($tokenRead.Detail)"}
            $recoveryToken=if([bool]$tokenRead.Ok){[string]$tokenRead.Token}else{'fresh-adoption-recovery-token-not-consumed'}
            $priorRoster=if($priorAuthority -ceq 'legacy'){$initial.prior_generation.active_roster_payload}else{$null}
            $recoveryExe=if($null -ne $priorRoster){[string]$priorRoster.exe_path}else{$ExePath}
            $recoveryProfiles=if($null -ne $priorRoster){[string]$priorRoster.profiles_dir}else{$ProfilesDir}
            $recoveryLog=if($null -ne $priorRoster){[string]$priorRoster.log_dir}else{$LogDir}
            $recoveryConfig=if($null -ne $priorRoster){[string]$priorRoster.calyx_config_path}else{$CalyxConfigPath}
            $recoveryConfigSha=if($null -ne $priorRoster){[string]$priorRoster.calyx_config_sha256}else{'0'*64}
            $recoveryPermissions=if($null -ne $priorRoster){[string]$priorRoster.allowed_permissions}else{[string]$AllowedPermissions}
            $recoveryAudio=if($null -ne $priorRoster){[bool]$priorRoster.enable_audio}else{[bool]$EnableAudio}
            [void](Ensure-SynapseBrokerAuthorityAdopted -RuntimeBinDir $RuntimeBinDir -BootstrapSourcePath ([string]$bootstrapObjects[0].path) -PowerShellPath ([string]$taskInitial.powershell.path) -WorkingDirectory ([string]$taskInitial.task.working_directory) -LogDir $recoveryLog -TaskName $(if($null -ne $initial){[string]$initial.task_name}else{$TaskName}) -ExePath $recoveryExe -Bind $(if($null -ne $initial){[string]$initial.bind}else{$Bind}) -DbPath $(if($null -ne $initial){[string]$initial.db_path}else{$DbPath}) -ProfilesDir $recoveryProfiles -TokenPath $(if($null -ne $initial){[string]$initial.token_path}else{$TokenPath}) -Token $recoveryToken -MaintenanceLockPath $MaintenanceLockPath -CalyxConfigPath $recoveryConfig -ExpectedCalyxConfigSha256 $recoveryConfigSha -EnableAudio $recoveryAudio -AllowedPermissions $recoveryPermissions -RecoveryOnly -HealthTimeoutSeconds ([Math]::Min(900,[Math]::Max(120,$InstallHealthTimeoutSeconds))) )
        }
        'downstream_unarmed' {
            $parent=Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent ([string]$record.Root))
            $isOperator=($parent -ieq [string]$globalRecoveryInventory.Roots.Operator.Path)
            if([string]$record.RecordKind -ceq 'cleanup_tail'){
                [void](Remove-SynapseDeploymentCleanupTailIfPresent -TransactionRoot ([string]$record.Root) -ExpectedParent $parent)
            }else{
                [void](Remove-SynapseDeploymentTransactionArtifact -Path ([string]$record.Root) -ExpectedRoot $parent -ExpectedState unarmed -Reason 'global_downstream_unarmed_cleanup' -Domain $(if($isOperator){'authority'}else{'application'}))
            }
        }
        {$_ -in @('probe','application_v4','operator')} {
            if($null -eq $globalRecoveryAuthority){
                $globalRecoveryAuthority=Get-SynapseBrokerAuthorityForOperatorLifecycle -RuntimeBinDir $RuntimeBinDir -TaskName $TaskName -ExePath $ExePath -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -LogDir $LogDir -MaintenanceLockPath $MaintenanceLockPath -DecommissionStructuralOnly:$Remove -AllowMissingTokenWhenParked:($Remove-and[bool]$removeMissingTokenPreflight.Missing) -ExpectedTokenAuthority $(if($Remove){$removeMissingTokenPreflight.TokenAuthority}else{$null}) -HealthTimeoutSeconds ([Math]::Min(900,[Math]::Max(120,$InstallHealthTimeoutSeconds)))
            }
            $wrapped=[pscustomobject]@{Directory=$record.Entry;Journal=$record.Journal}
            if($action -ceq 'probe'){
                Recover-SynapseBrokerSourceCandidateProbeTransaction -Record $wrapped -Authority $globalRecoveryAuthority -ExpectedParent ([string]$globalRecoveryInventory.Roots.Application.Path) -HealthTimeoutSeconds ([Math]::Min(900,[Math]::Max(120,$InstallHealthTimeoutSeconds)))
            }elseif($action -ceq 'application_v4'){
                Recover-SynapseBrokerApplicationTransaction -Record $wrapped -Authority $globalRecoveryAuthority -ExpectedParent ([string]$globalRecoveryInventory.Roots.Application.Path) -HealthTimeoutSeconds ([Math]::Min(900,[Math]::Max(120,$InstallHealthTimeoutSeconds)))
            }else{
                $operatorRecoveryMode=if($globalRecoveryMode -ceq 'start'){'start'}elseif($globalRecoveryMode -ceq 'remove'){'remove'}elseif($globalRecoveryMode -ceq 'setup'){'setup'}else{'inspect'}
                [void](Resolve-SynapseBrokerOperatorStopTransaction -Authority $globalRecoveryAuthority -Mode $operatorRecoveryMode -HealthTimeoutSeconds ([Math]::Min(900,[Math]::Max(120,$InstallHealthTimeoutSeconds))) )
            }
        }
        default {Die "SYNAPSE_GLOBAL_RECOVERY_ACTION_UNHANDLED action=$action root=$($record.Root)"}
    }
}
if($null -eq $globalRecoverySelection -or [string]$globalRecoverySelection.Action -cne 'none'){
    Die "SYNAPSE_GLOBAL_RECOVERY_PASS_BOUND_EXCEEDED max=$globalRecoveryMaxPasses remediation=preserve all remaining journals; recovery did not converge to an owner-free inventory"
}
if($Remove){Assert-SynapseBrokerDecommissionGlobalTokenAuthorityBoundary -Descriptor $removeMissingTokenPreflight.TokenAuthority -ExpectedPath $TokenPath -Context 'broker_decommission_global_converged_token_boundary'}
# A committed production task and adoption are prerequisites, not active
# recovery owners. Validate their live Scheduler/SD/action and exact immutable
# objects before any unrelated continuation/config/build mutation. Complete on
# a committed task journal performs readback only; TASK_CREATE is armed-only.
$committedTaskReceipts=@($globalRecoveryInventory.TaskEpochs|Where-Object{[string]$_.RecordKind -ceq 'journal' -and [string]$_.State -ceq 'commit_decided'})
if($committedTaskReceipts.Count -eq 1 -and $null -eq $globalRecoveryTaskInfrastructure){
    $taskLayout=Get-SynapseAuthorityLayoutReadOnly -RuntimeBinDir $RuntimeBinDir -RequireAuthorityRoot
    $globalRecoveryTaskInfrastructure=Complete-SynapseBrokerTaskCreateEpoch -Layout $taskLayout -Journal $committedTaskReceipts[0].Journal
}
$committedAdoptions=@($globalRecoveryInventory.Adoptions|Where-Object{[string]$_.RecordKind -ceq 'journal' -and [string]$_.State -ceq 'commit_decided'})
if($committedAdoptions.Count -eq 1){
    if($null -eq $globalRecoveryTaskInfrastructure){Die 'SYNAPSE_GLOBAL_RECOVERY_COMMITTED_TASK_PREFLIGHT_MISSING'}
    if($null-ne$globalRecoveryAuthority){Close-SynapseBrokerTaskReceiptInfrastructure -Infrastructure $globalRecoveryAuthority.Infrastructure;$globalRecoveryAuthority=$null}
    $globalRecoveryAuthority=Get-SynapseBrokerAuthorityForOperatorLifecycle -RuntimeBinDir $RuntimeBinDir -TaskName $TaskName -ExePath $ExePath -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -LogDir $LogDir -MaintenanceLockPath $MaintenanceLockPath -DecommissionStructuralOnly:$Remove -AllowMissingTokenWhenParked:($Remove-and[bool]$removeMissingTokenPreflight.Missing) -ExpectedTokenAuthority $(if($Remove){$removeMissingTokenPreflight.TokenAuthority}else{$null}) -HealthTimeoutSeconds ([Math]::Min(900,[Math]::Max(120,$InstallHealthTimeoutSeconds)))
    # The returned authority now owns an overlapping exact task/object receipt;
    # close the preliminary bundle only after that handoff is complete.
    Close-SynapseBrokerTaskReceiptInfrastructure -Infrastructure $globalRecoveryTaskInfrastructure
    $globalRecoveryTaskInfrastructure=$null
}
$globalRecoveryFingerprint=[string]$globalRecoveryInventory.FingerprintSha256
if($Remove){
    $decommissionAuthority=$globalRecoveryAuthority;$decommissionPending=$null;$decommissionInfrastructureClosed=$false
    try{
        $decommissionPending=Get-SynapsePendingBrokerDecommissionRecord -RuntimeBinDir $RuntimeBinDir -TaskName $TaskName -ExePath $ExePath -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -Bind $Bind -LogDir $LogDir -MaintenanceLockPath $MaintenanceLockPath -Remove -Purge:$Purge
        if($null-ne$decommissionPending-and$null-ne$decommissionPending.Completed){
            [void](Write-SynapseBrokerDecommissionCompletionLifecycle -Pending $decommissionPending -LogDir $LogDir -Context 'broker_decommission_post_recovery_terminal')
        }else{
            if($null-eq$decommissionAuthority){$decommissionAuthority=Get-SynapseBrokerAuthorityForOperatorLifecycle -RuntimeBinDir $RuntimeBinDir -TaskName $TaskName -ExePath $ExePath -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -LogDir $LogDir -MaintenanceLockPath $MaintenanceLockPath -DecommissionStructuralOnly -AllowMissingTokenWhenParked:([bool]$removeMissingTokenPreflight.Missing) -ExpectedTokenAuthority $removeMissingTokenPreflight.TokenAuthority -HealthTimeoutSeconds ([Math]::Min(900,[Math]::Max(120,$InstallHealthTimeoutSeconds)))}
            if($null-eq$decommissionPending){
                $decommissionExecutablePath=if($null-ne$decommissionAuthority.CurrentGeneration){
                    [System.IO.Path]::GetFullPath([string]$decommissionAuthority.CurrentGeneration.Executable.Path)
                }else{
                    [System.IO.Path]::GetFullPath($ExePath)
                }
                $authorized=New-SynapseBrokerDecommissionAuthorizedRecord -Authority $decommissionAuthority -ExePath $decommissionExecutablePath -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -LogDir $LogDir -MaintenanceLockPath $MaintenanceLockPath -Purge:$Purge -Confirmed:$ConfirmVaultDestruction
                $decommissionPending=[pscustomobject][ordered]@{RootLease=$authorized.RecordRootLease;RetainedLegacyLeases=$authorized.RetainedLegacyLeases;Authorized=$authorized;Confirmation=$null;Parked=$null;TaskAbsent=$null;Drained=$null;CleanupReady=$null;Completed=$null}
            }
            if($null-ne$decommissionPending.Parked){Die 'SYNAPSE_BROKER_DECOMMISSION_POST_RECOVERY_UNEXPECTED_PARKED_PHASE'}
            if($Purge-and$ConfirmVaultDestruction-and$null-eq$decommissionPending.Confirmation-and$null-eq$decommissionPending.CleanupReady){$decommissionPending.Confirmation=New-SynapseBrokerDecommissionConfirmationRecord -Authorized $decommissionPending.Authorized}
            $decommissionResumingParkedSuccessor=([string]$decommissionPending.Authorized.Payload.authority_source-ceq'active_generation'-and$null-eq$decommissionAuthority.CurrentGeneration)
            [void](Assert-SynapseBrokerDecommissionAuthorizationAuthorityBoundary -Authorized $decommissionPending.Authorized -Authority $decommissionAuthority -Context 'broker_decommission_pre_stop' -AllowActiveSourceParkedSuccessor:$decommissionResumingParkedSuccessor)
            Assert-SynapseBrokerDecommissionGlobalTokenAuthorityBoundary -Descriptor $removeMissingTokenPreflight.TokenAuthority -ExpectedPath $TokenPath -Context 'broker_decommission_pre_stop_global_token_boundary'
            if([string]$decommissionPending.Authorized.Payload.authority_source-ceq'active_generation'-and-not$decommissionResumingParkedSuccessor){
                $decommissionStop=Invoke-SynapseBrokerOperatorStop -Authority $decommissionAuthority -Bind $Bind -DbPath $DbPath -Decommission -HealthTimeoutSeconds ([Math]::Min(900,[Math]::Max(120,$InstallHealthTimeoutSeconds)))
                $decommissionPending.Parked=New-SynapseBrokerDecommissionParkedRecord -Authorized $decommissionPending.Authorized -Authority $decommissionAuthority -StopResult $decommissionStop
            }else{
                $decommissionPending.Parked=New-SynapseBrokerDecommissionParkedRecord -Authorized $decommissionPending.Authorized -Authority $decommissionAuthority -AlreadyParked
            }
            Assert-SynapseBrokerDecommissionGlobalTokenAuthorityBoundary -Descriptor $removeMissingTokenPreflight.TokenAuthority -ExpectedPath $TokenPath -Context 'broker_decommission_parked_global_token_boundary'
            Close-SynapseBrokerTaskReceiptInfrastructure -Infrastructure $decommissionAuthority.Infrastructure;$decommissionInfrastructureClosed=$true
            if($null-ne$globalRecoveryTaskInfrastructure){Close-SynapseBrokerTaskReceiptInfrastructure -Infrastructure $globalRecoveryTaskInfrastructure;$globalRecoveryTaskInfrastructure=$null}
            Release-SynapseBrokerDecommissionGlobalTokenBoundaryLease
            $deleteBoundaryContract=Assert-SynapsePurgePathContract -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -RuntimeBinDir $RuntimeBinDir -LogDir $LogDir -MaintenanceLockPath $MaintenanceLockPath -ExePath $ExePath -SourceDir $SourceDir -CodexToolSurfaceSnapshotPath $CodexToolSurfaceSnapshotPath -ChromeNativeHostExePath $ChromeNativeHostExePath -ChromeBridgePendingPath $ChromeBridgePendingPath
            if([string]$deleteBoundaryContract.ContractSha256-ine[string]$purgePathContract.ContractSha256-or(Get-SynapseCanonicalJson -Value $deleteBoundaryContract.Contract)-cne(Get-SynapseCanonicalJson -Value $purgePathContract.Contract)){Die 'SYNAPSE_BROKER_DECOMMISSION_PATH_CONTRACT_DRIFT boundary=delete'}
            $decommissionPending.Completed=Resume-SynapseBrokerDecommission -Pending $decommissionPending -Context 'broker_decommission_fresh_remove'
            if($null-eq$decommissionPending.Completed){Die 'SYNAPSE_BROKER_DECOMMISSION_FRESH_REMOVE_NO_TERMINAL'}
            [void](Write-SynapseBrokerDecommissionCompletionLifecycle -Pending $decommissionPending -LogDir $LogDir -Context 'broker_decommission_fresh_terminal')
        }
    }finally{
        if($null-ne$decommissionPending){Close-SynapsePendingBrokerDecommissionRecord -Pending $decommissionPending;$decommissionPending=$null}
        if($null-ne$decommissionAuthority-and-not$decommissionInfrastructureClosed){Close-SynapseBrokerTaskReceiptInfrastructure -Infrastructure $decommissionAuthority.Infrastructure}
        if($null-ne$globalRecoveryTaskInfrastructure){Close-SynapseBrokerTaskReceiptInfrastructure -Infrastructure $globalRecoveryTaskInfrastructure;$globalRecoveryTaskInfrastructure=$null}
    }
    Release-SynapseBrokerDecommissionMutex
    Release-SynapseSetupMaintenanceLock -State released
    return
}
Resume-SynapsePostExitContinuationTaskIntents -Root (Join-Path $env:LOCALAPPDATA 'synapse\setup-continuations')
# Candidate recovery runs before the later build/install phases that historically
# materialized LogDir. Create the caller-selected directory now so a legitimate
# fresh nested -LogDir remains supported, then let the recovery descriptors prove
# it and setup-candidates are physical non-reparse directories before enumeration.
New-Item -ItemType Directory -Force -Path $LogDir -ErrorAction Stop | Out-Null
if ($maintenanceReason -eq 'setup') {
    if ($script:SynapseManagedCalyxConfig) {
        $managedCalyxConfig = Write-SynapseManagedCpuOnlyCalyxConfig -Path $CalyxConfigPath
        $script:SynapseCalyxConfigSha256 = $managedCalyxConfig.sha256
    } else {
        $lockedConfigSha256 = Get-SynapseFileSha256 -Path $CalyxConfigPath
        if ($lockedConfigSha256 -ine $script:SynapseCalyxConfigSha256) {
            Die "SYNAPSE_CALYX_CONFIG_CHANGED_DURING_PREFLIGHT path=$CalyxConfigPath expected_sha256=$($script:SynapseCalyxConfigSha256) actual_sha256=$lockedConfigSha256 remediation=stop the concurrent config writer and rerun setup from one stable CPU-only config"
        }
    }
}
Remove-SynapseStaleDaemonStagingArtifacts -LogDir $LogDir
Resume-SynapseCandidateProbeTaskIntents -Root (Join-Path $LogDir 'setup-candidates')
Resume-SynapseCandidateCleanupIntents -Root (Join-Path $LogDir 'setup-candidates')
Remove-SynapseStaleSuccessfulCandidateArtifacts -Root (Join-Path $LogDir 'setup-candidates')

$globalRecoveryBeforeLifecycle=Get-SynapseGlobalRecoveryInventory -LogDir $LogDir -ProfilesDir $ProfilesDir -RuntimeBinDir $RuntimeBinDir
$globalRecoveryBeforeLifecycleTaskInfrastructure=if($null-ne$globalRecoveryAuthority){$globalRecoveryAuthority.Infrastructure}else{$globalRecoveryTaskInfrastructure}
$globalRecoveryBeforeLifecyclePrerequisite=Assert-SynapseGlobalCommittedAuthorityPreflight -Inventory $globalRecoveryBeforeLifecycle -TaskInfrastructure $globalRecoveryBeforeLifecycleTaskInfrastructure -RuntimeBinDir $RuntimeBinDir -RequestedLegacyTaskName $TaskName -DecommissionStructuralOnly:$Remove
$globalRecoveryBeforeLifecycleSelection=Select-SynapseGlobalRecoveryAction -Inventory $globalRecoveryBeforeLifecycle -Mode $globalRecoveryMode
if(-not [bool]$globalRecoveryBeforeLifecycleSelection.Allowed){Die ([string]$globalRecoveryBeforeLifecycleSelection.Error)}
if([string]$globalRecoveryBeforeLifecycle.FingerprintSha256 -ine $globalRecoveryFingerprint){
    Die "SYNAPSE_GLOBAL_RECOVERY_INVENTORY_CHANGED initial_sha256=$globalRecoveryFingerprint current_sha256=$($globalRecoveryBeforeLifecycle.FingerprintSha256) boundary=operator_lifecycle remediation=preserve every domain; no lifecycle action begins after the global journal inventory changes"
}

if ($ResumeChromeBridgePending) {
    Invoke-SynapseChromeBridgePendingResume -CheckpointPath $ChromeBridgePendingPath
    Release-SynapseSetupMaintenanceLock -State released
    return
}

if ($Stop) {
    $lifecycleStarted=(Get-Date).ToUniversalTime()
    Assert-SynapseRestartAllowed -Reason 'operator_stop' -Bind $Bind -DbPath $DbPath -TokenPath $TokenPath -HealthTimeoutSec ([Math]::Min(300,[Math]::Max(120,$InstallHealthTimeoutSeconds))) -ForceRestart:$ForceRestart
    $operatorAuthority=Get-SynapseBrokerAuthorityForOperatorLifecycle -RuntimeBinDir $RuntimeBinDir -TaskName $TaskName -ExePath $ExePath -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -LogDir $LogDir -MaintenanceLockPath $MaintenanceLockPath -HealthTimeoutSeconds ([Math]::Min(900,[Math]::Max(120,$InstallHealthTimeoutSeconds)))
    $stopResult=Invoke-SynapseBrokerOperatorStop -Authority $operatorAuthority -Bind $Bind -DbPath $DbPath -HealthTimeoutSeconds ([Math]::Min(900,[Math]::Max(120,$InstallHealthTimeoutSeconds)))
    $recordPath=Write-SynapseDaemonLifecycleModeRecord -LogDir $LogDir -Record @{
        mode='stop';reason='operator_stop';outcome='stopped';authority_model='immutable_broker/v1';broker_task_name=[string]$operatorAuthority.BrokerTask.Name
        broker_identity_sha256=[string]$operatorAuthority.Infrastructure.BrokerIdentitySha256;authority_epoch=[int64]$operatorAuthority.AuthorityEpoch
        generation_id=[string]$stopResult.GenerationId;operator_transaction_root=[string]$stopResult.Root;bind=$Bind;db_path=$DbPath
        started_utc=$lifecycleStarted.ToString('o');ended_utc=(Get-Date).ToUniversalTime().ToString('o');setup_pid=$PID
    }
    Info "SYNAPSE_BROKER_OPERATOR_STOP_VERIFIED generation=$(if([string]::IsNullOrWhiteSpace([string]$stopResult.GenerationId)){'<absent>'}else{$stopResult.GenerationId}) broker_task=$($operatorAuthority.BrokerTask.Name) transaction_root=$(if([string]::IsNullOrWhiteSpace([string]$stopResult.Root)){'<none>'}else{$stopResult.Root}) record=$recordPath"
    Release-SynapseSetupMaintenanceLock -State released
    return
}

if ($Start) {
    $lifecycleStarted=(Get-Date).ToUniversalTime()
    $operatorAuthority=Get-SynapseBrokerAuthorityForOperatorLifecycle -RuntimeBinDir $RuntimeBinDir -TaskName $TaskName -ExePath $ExePath -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -LogDir $LogDir -MaintenanceLockPath $MaintenanceLockPath -HealthTimeoutSeconds ([Math]::Min(900,[Math]::Max(120,$InstallHealthTimeoutSeconds)))
    $startResult=Resolve-SynapseBrokerOperatorStopTransaction -Authority $operatorAuthority -Mode start -HealthTimeoutSeconds ([Math]::Min(900,[Math]::Max(120,$InstallHealthTimeoutSeconds)))
    if(-not [bool]$startResult.Restored){
        if($null -eq $operatorAuthority.CurrentGeneration){Die 'SYNAPSE_BROKER_OPERATOR_START_NO_STOPPED_GENERATION remediation=-Start requires one durable operator-stop transaction or an already-active exact broker generation; run ordinary setup to install a generation'}
        $activeProof=Assert-SynapseCurrentBrokerAuthorityGenerationOperational -Authority $operatorAuthority -ExpectedGenerationId ([string]$operatorAuthority.CurrentGeneration.GenerationId) -HealthTimeoutSeconds ([Math]::Min(900,[Math]::Max(120,$InstallHealthTimeoutSeconds))) -Context 'operator_start_idempotent'
        $startResult=[pscustomobject][ordered]@{Restored=$true;Generation=$activeProof.Generation;Proof=$activeProof.Proof}
    }
    $recordPath=Write-SynapseDaemonLifecycleModeRecord -LogDir $LogDir -Record @{
        mode='start';reason='operator_start';outcome='running';authority_model='immutable_broker/v1';broker_task_name=[string]$operatorAuthority.BrokerTask.Name
        broker_identity_sha256=[string]$operatorAuthority.Infrastructure.BrokerIdentitySha256;authority_epoch=[int64]$operatorAuthority.AuthorityEpoch
        generation_id=[string]$startResult.Generation.GenerationId;daemon_pid=[int]$startResult.Proof.DaemonPid;bind=$Bind;db_path=$DbPath
        started_utc=$lifecycleStarted.ToString('o');ended_utc=(Get-Date).ToUniversalTime().ToString('o');setup_pid=$PID
    }
    Info "SYNAPSE_BROKER_OPERATOR_START_VERIFIED generation=$($startResult.Generation.GenerationId) daemon_pid=$($startResult.Proof.DaemonPid) broker_task=$($operatorAuthority.BrokerTask.Name) record=$recordPath"
    Release-SynapseSetupMaintenanceLock -State released
    return
}

# ---------------------------------------------------------------------------
# 1. Preflight
# ---------------------------------------------------------------------------
Step "Preflight"
if ($ManualInstallHealthRollbackProbe) {
    Info "Manual install-health rollback probe armed pause_mode=$ManualInstallHealthRollbackPauseMode; setup will reject the first installed daemon health readback and exit fail-loud after rollback readback"
}
if (-not $SkipBuild) {
    Info "Vendored Calyx workspace verified: $($requiredCalyxCrates.Count) path-dependency crates present under $vendoredCalyxCrates"
    New-Item -ItemType Directory -Force -Path $LogDir | Out-Null
    $cargoVersionLog = Join-Path $LogDir 'setup-cargo-version.log'
    $cargoVersionDiagnosticsPath = Join-Path $LogDir 'setup-cargo-version-diagnostics.json'
    if (Test-Path -LiteralPath $cargoVersionDiagnosticsPath) { Remove-Item -LiteralPath $cargoVersionDiagnosticsPath -Force }
    $cargoVersionDiagnostics = $null
    $cargoVersionExit = Invoke-SynapseProcessInKillOnCloseJob `
        -FilePath $cargo `
        -ArgumentList @('--version') `
        -WorkingDirectory $SourceDir `
        -TimeoutMinutes 1 `
        -LogPath $cargoVersionLog `
        -Diagnostics ([ref]$cargoVersionDiagnostics)
    $cargoVersionLogSignal = Get-SynapseBuildLogSignal -Path $cargoVersionLog
    if ($cargoVersionExit -ne 0) {
        $failureKind = Get-SynapseCargoVersionFailureKind -Diagnostics $cargoVersionDiagnostics
        $versionFailure = [ordered]@{
            schema = 'synapse_setup_cargo_version_failure/v1'
            code = $failureKind.code
            source_dir = $SourceDir
            cargo = $cargo
            version_log = $cargoVersionLog
            preflight_timeout_minutes = 1
            version_exit = $cargoVersionExit
            remediation = $failureKind.remediation
            invocation = $cargoVersionDiagnostics
            log_signal = $cargoVersionLogSignal
        }
        $versionFailure | ConvertTo-Json -Depth 32 | Set-Content -LiteralPath $cargoVersionDiagnosticsPath -Encoding UTF8
        $job = $cargoVersionDiagnostics.process_job
        $childPid = if ($job -and $job.child_pid) { $job.child_pid } else { '<unknown>' }
        $completionKind = if ($job -and $job.completion_kind) { $job.completion_kind } else { '<unknown>' }
        $waitKind = if ($job -and $job.wait_kind) { $job.wait_kind } else { '<unknown>' }
        $terminateJobOk = if ($job) { [string]$job.terminate_job_ok } else { '<unknown>' }
        $cleanupWaitKind = if ($job -and $job.cleanup_wait_kind) { $job.cleanup_wait_kind } else { '<unknown>' }
        $childAliveAfter = if ($cargoVersionDiagnostics.cleanup_result) { [string]$cargoVersionDiagnostics.cleanup_result.child_process_alive_after } else { '<unknown>' }
        Die ("{0} exit={1} child_pid={2} child_alive_after={3} completion={4} wait={5} timeout_minutes=1 terminate_job_ok={6} cleanup_wait={7} diagnostics={8} log={9} remediation={10}`nTail:`n{11}" -f `
            $failureKind.code,
            $cargoVersionExit,
            $childPid,
            $childAliveAfter,
            $completionKind,
            $waitKind,
            $terminateJobOk,
            $cleanupWaitKind,
            $cargoVersionDiagnosticsPath,
            $cargoVersionLog,
            $failureKind.remediation,
            $cargoVersionLogSignal.tail_80)
    }
    $cargoVersionText = if (Test-Path -LiteralPath $cargoVersionLog) {
        ((Get-Content -LiteralPath $cargoVersionLog -ErrorAction SilentlyContinue) -join "`n").Trim()
    } else {
        ''
    }
    if ([string]::IsNullOrWhiteSpace($cargoVersionText)) {
        $emptyVersionFailure = [ordered]@{
            schema = 'synapse_setup_cargo_version_failure/v1'
            code = 'SYNAPSE_CARGO_VERSION_EMPTY'
            source_dir = $SourceDir
            cargo = $cargo
            version_log = $cargoVersionLog
            preflight_timeout_minutes = 1
            version_exit = $cargoVersionExit
            remediation = 'cargo --version exited 0 but produced no version text; repair Rust toolchain stdout/stderr before setup continues'
            invocation = $cargoVersionDiagnostics
            log_signal = $cargoVersionLogSignal
        }
        $emptyVersionFailure | ConvertTo-Json -Depth 32 | Set-Content -LiteralPath $cargoVersionDiagnosticsPath -Encoding UTF8
        Die "SYNAPSE_CARGO_VERSION_EMPTY log=$cargoVersionLog remediation=cargo --version exited 0 but produced no version text; repair Rust toolchain stdout/stderr before setup continues"
    }
    Info "cargo: $cargoVersionText"
}

# ---------------------------------------------------------------------------
# 2. Build (local source -> persistent target) and verify the binary
# ---------------------------------------------------------------------------
# The shipping feature set is CPU-only. Do not probe or mutate nvcc/MSVC state:
# no CUDA build script is eligible to run under this deployment contract.
$ortRuntimeRoot = Join-Path $env:LOCALAPPDATA 'synapse\runtime\onnxruntime-cpu'
$embeddedModelRoot = Join-Path $env:LOCALAPPDATA 'synapse\build-models'
$acquisitionCleanup = Remove-SynapseStaleAcquisitionArtifacts -Roots @($ortRuntimeRoot, $embeddedModelRoot)
$acquisitionCleanupPath = Join-Path $LogDir 'setup-acquisition-cleanup.json'
$acquisitionCleanup | ConvertTo-Json -Depth 16 | Set-Content -LiteralPath $acquisitionCleanupPath -Encoding UTF8
try {
    $acquisitionCleanupReadback = Get-Content -LiteralPath $acquisitionCleanupPath -Raw -Encoding UTF8 | ConvertFrom-Json
} catch {
    Die "SYNAPSE_ACQUISITION_CLEANUP_READBACK_UNREADABLE path=$acquisitionCleanupPath error=$($_.Exception.Message) remediation=repair the setup log directory; setup cannot prove which stale acquisition bytes it reclaimed"
}
if ([int64]$acquisitionCleanupReadback.reclaimed_bytes -ne [int64]$acquisitionCleanup.reclaimed_bytes -or
    [int]$acquisitionCleanupReadback.reaped_count -ne [int]$acquisitionCleanup.reaped_count) {
    Die "SYNAPSE_ACQUISITION_CLEANUP_READBACK_MISMATCH path=$acquisitionCleanupPath expected_reaped_count=$($acquisitionCleanup.reaped_count) actual_reaped_count=$($acquisitionCleanupReadback.reaped_count) expected_reclaimed_bytes=$($acquisitionCleanup.reclaimed_bytes) actual_reclaimed_bytes=$($acquisitionCleanupReadback.reclaimed_bytes) remediation=inspect the setup log filesystem; the durable cleanup ledger differs from the in-memory result"
}
$acquisitionCleanupSha = Get-SynapseFileSha256 -Path $acquisitionCleanupPath
Info "Acquisition cleanup readback -> $acquisitionCleanupPath sha256=$acquisitionCleanupSha reaped_count=$($acquisitionCleanupReadback.reaped_count) reclaimed_bytes=$($acquisitionCleanupReadback.reclaimed_bytes) retained_live_count=$($acquisitionCleanupReadback.retained_live_count)"
$ortRuntime = Install-SynapsePinnedOrtCpuRuntime -Root $ortRuntimeRoot
$env:ORT_LIB_LOCATION = $ortRuntime.NativeDir
$env:ORT_PREFER_DYNAMIC_LINK = '1'
Info "ONNX Runtime build linkage configured mode=dynamic ORT_LIB_LOCATION=$($env:ORT_LIB_LOCATION) version=$($ortRuntime.Version)"

if (-not $SkipBuild) {
    Step "Building synapse-mcp (release) from $SourceDir"
    $releaseBuildCompilerEnvironment = Set-SynapseReleaseBuildCompilerEnvironment
    Info ("Release build compiler environment: RUST_MIN_STACK={0} source={1}" -f `
        $releaseBuildCompilerEnvironment.rust_min_stack,
        $releaseBuildCompilerEnvironment.rust_min_stack_source)
    # The build target is the source checkout's own `target` tree unless the
    # operator explicitly authorized an alternate. Because that tree belongs to
    # exactly one checkout it is inherently per-checkout, so it cannot reproduce
    # the cross-checkout fingerprint poisoning that the old hashed
    # %LOCALAPPDATA% cache existed to prevent (observed live 2026-06-12: a
    # synapse-core compiled from a sibling clone shadowed new modules and broke
    # the deploy build). Cargo freshness is mtime-based against the dep-info
    # file list, and a checkout-owned tree is only ever written by that one
    # checkout's builds.
    Info ("Cargo target directory: {0} (kind={1} authorized_by={2} source_dir={3})" -f `
        $cargoTargetResolution.path, $cargoTargetResolution.kind,
        $cargoTargetResolution.authorized_by, $cargoTargetResolution.source_dir)

    $alternateBuildTargetInventory = Get-SynapseAlternateBuildTargetInventory
    if ($alternateBuildTargetInventory.exists -and @($alternateBuildTargetInventory.trees).Count -gt 0) {
        Info ("Pre-existing alternate build trees under {0}: count={1} total_gib={2}. Setup never removes these implicitly; remove one only after proving exact ownership and age." -f `
            $alternateBuildTargetInventory.root,
            @($alternateBuildTargetInventory.trees).Count,
            $alternateBuildTargetInventory.total_gib)
        foreach ($tree in $alternateBuildTargetInventory.trees) {
            Info ("  alternate_build_tree path={0} gib={1} files={2} last_write_utc={3} age_days={4}" -f `
                $tree.path, $tree.footprint.gib, $tree.footprint.file_count, $tree.last_write_utc, $tree.age_days)
        }
    }

    # Fail closed BEFORE burning a full release build: if any live process runs
    # its image out of the cargo target tree, Windows will refuse to let cargo
    # replace its own link output and the build dies at the very end (#1865).
    # The collision is knowable here, so the operator never pays ~20 minutes to
    # learn it.
    $buildOutputImageHolders = Get-SynapseBuildOutputImageHolders -TargetDir $CargoTarget
    if (-not $buildOutputImageHolders.process_table_read) {
        Die ("SYNAPSE_RELEASE_BUILD_OUTPUT_HOLDER_PREFLIGHT_UNREADABLE cargo_target_dir={0} error={1} remediation=setup cannot prove no live process runs from the build output tree; repair Win32_Process access for this session before rerunning setup" -f `
            $CargoTarget, $buildOutputImageHolders.process_table_error)
    }
    if (@($buildOutputImageHolders.holders).Count -gt 0) {
        Die ("SYNAPSE_RELEASE_BUILD_OUTPUT_DIR_IMAGE_LIVE cargo_target_dir={0} holder_count={1} holders={2} remediation=Windows locks a running executable image, so cargo cannot replace its own link output; stop each PID listed above (verify it exited) and rerun setup. Running the daemon directly out of target\release is the usual cause; deploy through setup so the live daemon runs from the installed path instead." -f `
            $buildOutputImageHolders.target_dir,
            @($buildOutputImageHolders.holders).Count,
            (Format-SynapseBuildOutputImageHolders -Readback $buildOutputImageHolders))
    }
    Info ("Build output holder preflight: cargo_target_dir={0} live_images_under_target=0 unreadable_path_processes={1}" -f `
        $buildOutputImageHolders.target_dir,
        @($buildOutputImageHolders.unreadable_path_processes).Count)

    New-Item -ItemType Directory -Force -Path $CargoTarget, $LogDir | Out-Null
    $env:CARGO_TARGET_DIR = $CargoTarget
    # Serialize source-install compiler producers so independent rustc/native
    # heaps cannot exceed the lightweight-host envelope in aggregate. The
    # release profile and process-Job contract bound the remaining single-rustc
    # case; job count alone never did.
    $maxLightweightBuildJobs = 1
    if (-not $env:CARGO_BUILD_JOBS) {
        # Bound installation work independently of host size. CARGO_BUILD_JOBS
        # (env) outranks any `[build] jobs = N` in a user or repo config.toml,
        # so this holds regardless of local cargo configuration.
        #
        # A hard `Min(8, ...)` cap lived here from 2026-07-22 to 2026-08-06 as a
        # mitigation for the rustc STATUS_ACCESS_VIOLATION crashes on #1731. It
        # is removed because the evidence says it never mitigated anything:
        #
        #   * The crash it was added for was a rustc 1.96.1 fault. That compiler
        #     was replaced on 2026-07-26 (rust-toolchain.toml -> 1.97.1, c9a6b85a)
        #     precisely because it "repeatedly crashed".
        #   * The crash then recurred anyway AT 8 JOBS. The archived readback
        #     logs/setup-build-failures/release-build-20260804T004949861Z-pid27796
        #     records code=SYNAPSE_RELEASE_BUILD_TOOLCHAIN_CRASHED,
        #     cargo_build_jobs=8, crash_tool=rustc.exe,
        #     crash_status=STATUS_ACCESS_VIOLATION.
        #   * It is not resource exhaustion: that same readback shows 46 GB
        #     physical still available and commit at 52.3%.
        #   * It then recurred AT 32 JOBS too (2026-08-06, archive
        #     release-build-20260806T174951173Z-pid46444, 72.8 GB free). Same
        #     fault at both ends of the range: job count is not a lever on it in
        #     EITHER direction, so the cap could not have been preventing it.
        #
        # An earlier version of this comment claimed "upstream places this fault
        # in the ThinLTO LLVM codegen workers (rust-lang/rust#125765, #109067,
        # #113433)". That citation was checked in #2029 and DOES NOT SUPPORT the
        # claim -- do not propagate it. #125765 is closed as not-a-bug (the
        # reporter's build was OOMing under an 8 GiB Docker limit) and is on
        # windows-gnu; #109067 is a miscompilation needing -Zdylib-lto; #113433
        # is an unmerged PR about building rustc itself with LTO. All three are
        # 2023-2024 and none is a compile-time AV under `-C lto=thin` on
        # windows-msvc. As of 2026-08-07 there is NO open upstream bug matching
        # this signature, and 1.97.1 is already the newest stable, so there is
        # no toolchain to bump to either.
        #
        # The live arm is the release profile's `lto = "thin"` -> false, taken
        # 2026-08-07 in the root Cargo.toml (#2029) -- where the evidence and
        # the falsification criterion live. It is NOT worked around here.
        #
        # The earlier crash investigation established only that job count did
        # not fix the compiler crash. It did not justify consuming every CPU or
        # allowing many simultaneous rustc heaps. Installation is background
        # host work, so the resource contract now serializes compiler jobs while
        # retaining incremental/profile build semantics. An explicit override
        # above that contract is rejected rather than silently clamped.
        $logicalCpus = [Environment]::ProcessorCount
        $ramGb = [math]::Floor((Get-CimInstance Win32_ComputerSystem).TotalPhysicalMemory / 1GB)
        # Heavy rustc/cl.exe jobs peak around 1.5 GB each; on a low-RAM host cap
        # the count so the build does not swap, which costs far more than
        # running fewer jobs. On a well-provisioned host this never binds.
        $memoryJobs = [math]::Max(1, [math]::Floor($ramGb / 1.5))
        $env:CARGO_BUILD_JOBS = [string][int][math]::Min($maxLightweightBuildJobs, [math]::Min($logicalCpus, $memoryJobs))
    } else {
        $configuredBuildJobs = 0
        if (-not [int]::TryParse($env:CARGO_BUILD_JOBS, [ref]$configuredBuildJobs) -or
            $configuredBuildJobs -lt 1 -or $configuredBuildJobs -gt $maxLightweightBuildJobs) {
            Die "SYNAPSE_SETUP_BUILD_JOBS_OUT_OF_CONTRACT value=$($env:CARGO_BUILD_JOBS) required=1..$maxLightweightBuildJobs remediation=unset CARGO_BUILD_JOBS or choose a value within the lightweight installation contract"
        }
    }
    # cargo forwards this to build scripts as NUM_JOBS, but cmake-driven -sys
    # crates read CMAKE_BUILD_PARALLEL_LEVEL instead and otherwise serialize
    # their native compiles. synapse-update.ps1 has always set this; setup lost
    # it, so the same source tree built with different native parallelism
    # depending on which entry point the operator used.
    if (-not $env:CMAKE_BUILD_PARALLEL_LEVEL) {
        $env:CMAKE_BUILD_PARALLEL_LEVEL = $env:CARGO_BUILD_JOBS
    } else {
        $configuredCmakeJobs = 0
        if (-not [int]::TryParse($env:CMAKE_BUILD_PARALLEL_LEVEL, [ref]$configuredCmakeJobs) -or
            $configuredCmakeJobs -lt 1 -or $configuredCmakeJobs -gt $maxLightweightBuildJobs) {
            Die "SYNAPSE_SETUP_CMAKE_JOBS_OUT_OF_CONTRACT value=$($env:CMAKE_BUILD_PARALLEL_LEVEL) required=1..$maxLightweightBuildJobs remediation=unset CMAKE_BUILD_PARALLEL_LEVEL or choose a value within the lightweight installation contract"
        }
    }
    Info "Build parallelism: CARGO_BUILD_JOBS=$($env:CARGO_BUILD_JOBS) CMAKE_BUILD_PARALLEL_LEVEL=$($env:CMAKE_BUILD_PARALLEL_LEVEL) (logical CPUs: $([Environment]::ProcessorCount))"
    $buildLog = Join-Path $LogDir 'setup-build.log'
    $buildDiagnosticsPath = Join-Path $LogDir 'setup-build-diagnostics.json'
    $buildInvocationPath = Join-Path $LogDir 'setup-build-invocation.json'
    # Preserve the last failure diagnostics across later successful retries;
    # each new failure also writes an immutable per-attempt archive below.
    $built = Join-Path $CargoTarget 'release\synapse-mcp.exe'
    $builtNativeHost = Join-Path $CargoTarget 'release\synapse-chrome-native-host.exe'
    $builtSupervisorBootstrap = Join-Path $CargoTarget 'release\synapse-supervisor-bootstrap.exe'
    Info "Build process tree is job-owned; log: $buildLog"
    $buildInvocationDiagnostics = $null
    $cargoBuildArgs = @('build','--release','-p','synapse-mcp')
    if (@($cudaBuildCapability.cargo_features).Count -gt 0) {
        $cargoBuildArgs += @('--features', ($cudaBuildCapability.cargo_features -join ','))
    }
    Info ("Cargo invocation: {0} {1} (CARGO_TARGET_DIR={2})" -f $cargo, ($cargoBuildArgs -join ' '), $env:CARGO_TARGET_DIR)

    # Bounded retry on a PHYSICALLY CRASHED toolchain only (#1975 ask 3). Every
    # other failure classification is still fatal on the first attempt. See
    # Get-SynapseReleaseBuildToolchainCrashRetryBudget for why this is a gate
    # rather than a fallback.
    $crashRetryBudget = Get-SynapseReleaseBuildToolchainCrashRetryBudget
    $maxBuildAttempts = 1 + $crashRetryBudget.budget
    $buildAttempt = 0
    $toolchainCrashHistory = @()
    Info ("Release build toolchain-crash retry budget: {0} extra attempt(s) (max_attempts={1} source={2}); retries fire ONLY on SYNAPSE_RELEASE_BUILD_TOOLCHAIN_CRASHED" -f `
        $crashRetryBudget.budget, $maxBuildAttempts, $crashRetryBudget.source)

    while ($true) {
    $buildAttempt++
    $buildInvocationDiagnostics = $null
    $buildMemoryBefore = Get-SynapseWindowsMemoryReadback
    Info ("Release build attempt {0} of {1} (max). Memory before: read_succeeded={2} commit_charge_bytes={3} commit_limit_bytes={4} commit_percent={5} available_physical_bytes={6}" -f `
        $buildAttempt,
        $maxBuildAttempts,
        $buildMemoryBefore.read_succeeded,
        $buildMemoryBefore.commit_charge_bytes,
        $buildMemoryBefore.commit_limit_bytes,
        $buildMemoryBefore.commit_percent,
        $buildMemoryBefore.available_physical_bytes)
    $buildExit = Invoke-SynapseProcessInKillOnCloseJob `
        -FilePath $cargo `
        -ArgumentList $cargoBuildArgs `
        -WorkingDirectory $SourceDir `
        -TimeoutMinutes $BuildTimeoutMinutes `
        -LogPath $buildLog `
        -Diagnostics ([ref]$buildInvocationDiagnostics)
    $buildMemoryAfter = Get-SynapseWindowsMemoryReadback
    Info ("Release build memory after: read_succeeded={0} commit_charge_bytes={1} commit_limit_bytes={2} commit_percent={3} available_physical_bytes={4}" -f `
        $buildMemoryAfter.read_succeeded,
        $buildMemoryAfter.commit_charge_bytes,
        $buildMemoryAfter.commit_limit_bytes,
        $buildMemoryAfter.commit_percent,
        $buildMemoryAfter.available_physical_bytes)
    $buildInvocationDiagnostics |
        ConvertTo-Json -Depth 32 |
        Set-Content -LiteralPath $buildInvocationPath -Encoding UTF8
    $buildInvocationReadback = Get-Content -LiteralPath $buildInvocationPath -Raw |
        ConvertFrom-Json
    if ($buildInvocationReadback.schema -ne 'synapse_setup_process_job_invocation/v2' -or
        -not $buildInvocationReadback.process_job -or
        -not $buildInvocationReadback.process_job.child_pid) {
        Die "SYNAPSE_RELEASE_BUILD_INVOCATION_DIAGNOSTICS_INVALID path=$buildInvocationPath remediation=inspect filesystem integrity and setup process-job serialization"
    }
    Info "Build invocation diagnostics: $buildInvocationPath"
    if ($buildExit -eq 0) {
        # A build that only succeeded after a crash is NOT reported as a clean
        # build. The crash history is stated on success too, so the #1975 rate
        # keeps accruing instead of disappearing the moment a retry works.
        if (@($toolchainCrashHistory).Count -gt 0) {
            Warn ("Release build SUCCEEDED on attempt {0} of {1} after {2} toolchain crash(es): {3}. This is #1975; the crash is probabilistic on this host and each crashed attempt archived its own diagnostics." -f `
                $buildAttempt,
                $maxBuildAttempts,
                @($toolchainCrashHistory).Count,
                (($toolchainCrashHistory | ForEach-Object { "attempt $($_.attempt): $($_.tool) $($_.status) $($_.exit_code) -> $($_.diagnostics_archive)" }) -join ' | '))
        }
        break
    }

    # ---- failure path: classify, archive, then decide retry vs die ----
        $buildLogSignal = Get-SynapseBuildLogSignal -Path $buildLog
        $artifactReadback = Get-SynapseArtifactReadback -Path $built
        # Re-enumerate at failure time: a process can have started running out of
        # the target tree during the build itself, and the classifier must name
        # the exact PID/image rather than assume the preflight state still holds.
        $buildOutputImageHoldersAfter = Get-SynapseBuildOutputImageHolders -TargetDir $CargoTarget
        $failureKind = Get-SynapseReleaseBuildFailureKind `
            -Diagnostics $buildInvocationDiagnostics `
            -LogSignal $buildLogSignal `
            -ArtifactReadback $artifactReadback `
            -OutputImageHolders $buildOutputImageHoldersAfter
        $buildFailureStamp = (Get-Date).ToUniversalTime().ToString('yyyyMMddTHHmmssfffZ')
        $buildFailureDir = Join-Path $LogDir 'setup-build-failures'
        New-Item -ItemType Directory -Force -Path $buildFailureDir | Out-Null
        $buildFailurePrefix = "release-build-$buildFailureStamp-pid$PID"
        $buildLogArchivePath = Join-Path $buildFailureDir "$buildFailurePrefix.build.log"
        $buildDiagnosticsArchivePath = Join-Path $buildFailureDir "$buildFailurePrefix.diagnostics.json"
        $buildLogArchiveSha256 = $null
        if (Test-Path -LiteralPath $buildLog) {
            Copy-Item -LiteralPath $buildLog -Destination $buildLogArchivePath -Force
            try {
                $buildLogArchiveSha256 = Get-SynapseFileSha256 -Path $buildLogArchivePath
            } catch {
                $buildLogArchiveSha256 = "hash_failed: $($_.Exception.Message)"
            }
        }
        $buildStartedAtUtc = $null
        if ($buildInvocationDiagnostics -and $buildInvocationDiagnostics.started_at_utc) {
            $buildStartedAtUtc = [string]$buildInvocationDiagnostics.started_at_utc
        }
        $werCrashReadback = Get-SynapseWerCrashReadback -SinceUtc $buildStartedAtUtc
        $rustToolchainReadback = Get-SynapseRustToolchainReadback -CargoPath $cargo
        $buildDiagnostics = [ordered]@{
            schema = 'synapse_setup_release_build_failure/v1'
            code = $failureKind.code
            attempt_id = $buildFailurePrefix
            observed_at_utc = (Get-Date).ToUniversalTime().ToString('o')
            source_dir = $SourceDir
            cargo = $cargo
            cargo_target_dir = $CargoTarget
            expected_artifact = $built
            build_log = $buildLog
            archived_build_log = $buildLogArchivePath
            archived_build_log_sha256 = $buildLogArchiveSha256
            build_timeout_minutes = $BuildTimeoutMinutes
            build_exit = $buildExit
            remediation = $failureKind.remediation
            diagnostics_archive = $buildDiagnosticsArchivePath
            compiler_environment = $releaseBuildCompilerEnvironment
            cargo_build_jobs = $env:CARGO_BUILD_JOBS
            memory_before = $buildMemoryBefore
            memory_after = $buildMemoryAfter
            invocation = $buildInvocationDiagnostics
            log_signal = $buildLogSignal
            artifact_readback = $artifactReadback
            build_output_image_holders_preflight = $buildOutputImageHolders
            build_output_image_holders_after = $buildOutputImageHoldersAfter
            rust_toolchain_readback = $rustToolchainReadback
            wer_crash_readback = $werCrashReadback
        }
        $buildDiagnosticsJson = $buildDiagnostics | ConvertTo-Json -Depth 32
        $buildDiagnosticsJson | Set-Content -LiteralPath $buildDiagnosticsPath -Encoding UTF8
        $buildDiagnosticsJson | Set-Content -LiteralPath $buildDiagnosticsArchivePath -Encoding UTF8
        $job = $buildInvocationDiagnostics.process_job
        $childPid = if ($job -and $job.child_pid) { $job.child_pid } else { '<unknown>' }
        $completionKind = if ($job -and $job.completion_kind) { $job.completion_kind } else { '<unknown>' }
        $waitKind = if ($job -and $job.wait_kind) { $job.wait_kind } else { '<unknown>' }
        $terminateJobOk = if ($job) { [string]$job.terminate_job_ok } else { '<unknown>' }
        $cleanupWaitKind = if ($job -and $job.cleanup_wait_kind) { $job.cleanup_wait_kind } else { '<unknown>' }
        $compilerError = if ($buildLogSignal.has_compiler_error) { 'true' } else { 'false' }
        $childAliveAfter = if ($buildInvocationDiagnostics.cleanup_result) { [string]$buildInvocationDiagnostics.cleanup_result.child_process_alive_after } else { '<unknown>' }
        $ownedBuildToolCount = @($buildInvocationDiagnostics.job_owned_build_tool_processes_after).Count
        $unrelatedBuildToolCount = @($buildInvocationDiagnostics.unrelated_build_tool_processes_after).Count
        $recentWerDumpCount = if ($werCrashReadback) { [int]$werCrashReadback.recent_dump_count } else { 0 }
        $outputLocked = if ($buildLogSignal.has_output_locked_error) { 'true' } else { 'false' }
        $outputHolderText = Format-SynapseBuildOutputImageHolders -Readback $buildOutputImageHoldersAfter
        # Printed beside compiler_error so the two can never be read as the same
        # fact again (#1975): a crashed tool sets this and clears that.
        $toolchainCrash = if ($buildLogSignal.has_toolchain_crash) {
            "true(tool={0} status={1} exit={2})" -f `
                ($(if ($buildLogSignal.toolchain_crash_tool) { $buildLogSignal.toolchain_crash_tool } else { '<unnamed>' })),
                ($(if ($buildLogSignal.toolchain_crash_status) { $buildLogSignal.toolchain_crash_status } else { '<unnamed>' })),
                ($(if ($buildLogSignal.toolchain_crash_exit_code) { $buildLogSignal.toolchain_crash_exit_code } else { '<unknown>' }))
        } else { 'false' }

        # The ONLY retryable state, and it takes TWO independent facts, not one.
        #
        # (1) the classification is TOOLCHAIN_CRASHED -- a named build tool was
        #     killed by the OS on an NTSTATUS; and
        # (2) the log carries ZERO source diagnostics.
        #
        # (2) is not redundant. TOOLCHAIN_CRASHED is also reached when cargo
        #     ITSELF dies on an access violation, and that branch fires whether
        #     or not the log already carried real `error[E....]` diagnostics --
        #     the classifier says so explicitly ("The log ALSO carries N
        #     source-diagnostic line(s)"). Retrying that would spend the whole
        #     budget re-proving a deterministic source error. The retry must mean
        #     "there is provably nothing here for a human to repair", so it is
        #     gated on the absence of diagnostics rather than on the crash alone.
        $sourceDiagnosticCount = @($buildLogSignal.compiler_error_matches).Count
        if ($failureKind.code -eq 'SYNAPSE_RELEASE_BUILD_TOOLCHAIN_CRASHED' -and
            $sourceDiagnosticCount -eq 0 -and
            $buildAttempt -lt $maxBuildAttempts) {
            $toolchainCrashHistory += [pscustomobject]@{
                attempt = $buildAttempt
                observed_at_utc = (Get-Date).ToUniversalTime().ToString('o')
                tool = $(if ($buildLogSignal.toolchain_crash_tool) { $buildLogSignal.toolchain_crash_tool } else { '<unnamed>' })
                status = $(if ($buildLogSignal.toolchain_crash_status) { $buildLogSignal.toolchain_crash_status } else { '<unnamed>' })
                exit_code = $(if ($buildLogSignal.toolchain_crash_exit_code) { $buildLogSignal.toolchain_crash_exit_code } else { '<unknown>' })
                build_exit = $buildExit
                source_diagnostic_count = @($buildLogSignal.compiler_error_matches).Count
                diagnostics_archive = $buildDiagnosticsArchivePath
                log_archive = $buildLogArchivePath
                rust_min_stack = $releaseBuildCompilerEnvironment.rust_min_stack
            }
            Warn ("SYNAPSE_RELEASE_BUILD_TOOLCHAIN_CRASHED_RETRYING attempt={0} of {1} tool={2} status={3} exit={4} source_diagnostics={5} rust_min_stack={6} diagnostics_archive={7} log_archive={8} reason=the toolchain crashed with zero source diagnostics, which no source change can repair; retrying the build. Every dependency is cached, so this attempt rebuilds only the final crate." -f `
                $buildAttempt,
                $maxBuildAttempts,
                $toolchainCrashHistory[-1].tool,
                $toolchainCrashHistory[-1].status,
                $toolchainCrashHistory[-1].exit_code,
                $toolchainCrashHistory[-1].source_diagnostic_count,
                $toolchainCrashHistory[-1].rust_min_stack,
                $buildDiagnosticsArchivePath,
                $buildLogArchivePath)
            continue
        }

        # Falling through with a crash classification means the budget is spent.
        # Say so explicitly and attach every attempt, so "it crashed 3 times" is
        # distinguishable from "it crashed once" without reading the log dir.
        $crashHistoryText = if (@($toolchainCrashHistory).Count -gt 0) {
            "attempts_crashed={0} history={1}" -f `
                (@($toolchainCrashHistory).Count + 1),
                (($toolchainCrashHistory | ForEach-Object { "#$($_.attempt) $($_.tool) $($_.status) $($_.exit_code) archive=$($_.diagnostics_archive)" }) -join ' | ')
        } else { 'attempts_crashed=0' }
        if ($failureKind.code -eq 'SYNAPSE_RELEASE_BUILD_TOOLCHAIN_CRASHED' -and $sourceDiagnosticCount -gt 0) {
            Warn ("SYNAPSE_RELEASE_BUILD_TOOLCHAIN_CRASH_NOT_RETRIED source_diagnostics={0} reason=a build tool crashed, but the log also carries real source diagnostics. Those are deterministic and a retry cannot clear them, so the crash-retry budget was deliberately NOT spent. Repair the diagnostics first; if the crash then persists on a clean tree it is the #1975 fault and will be retried." -f `
                $sourceDiagnosticCount)
        }
        elseif ($failureKind.code -eq 'SYNAPSE_RELEASE_BUILD_TOOLCHAIN_CRASHED') {
            Warn ("SYNAPSE_RELEASE_BUILD_TOOLCHAIN_CRASH_RETRY_BUDGET_EXHAUSTED max_attempts={0} budget_source={1} rust_min_stack={2} {3} conclusion=the crash reproduced on every attempt, so it is NOT the probabilistic #1975 fault this budget exists for; treat it as deterministic and investigate the toolchain (release profile lto/codegen-units, rustc version) rather than rerunning." -f `
                $maxBuildAttempts,
                $crashRetryBudget.source,
                $releaseBuildCompilerEnvironment.rust_min_stack,
                $crashHistoryText)
        }
        Die ("{0} attempt={25} of {26} crash_history=[{27}] exit={1} child_pid={2} child_alive_after={3} completion={4} wait={5} timeout_minutes={6} terminate_job_ok={7} cleanup_wait={8} compiler_error={9} toolchain_crash={24} output_locked={22} output_dir_live_images={23} job_owned_build_tools_after={10} unrelated_build_tools_after={11} artifact_exists={12} artifact_sha256={13} artifact_exclusive_open={14} diagnostics={15} diagnostics_archive={16} log={17} log_archive={18} wer_recent_dumps={19} remediation={20}`nTail:`n{21}" -f `
            $failureKind.code,
            $buildExit,
            $childPid,
            $childAliveAfter,
            $completionKind,
            $waitKind,
            $BuildTimeoutMinutes,
            $terminateJobOk,
            $cleanupWaitKind,
            $compilerError,
            $ownedBuildToolCount,
            $unrelatedBuildToolCount,
            $artifactReadback.exists,
            ($(if ($artifactReadback.sha256) { $artifactReadback.sha256 } else { '<none>' })),
            $artifactReadback.exclusive_open,
            $buildDiagnosticsPath,
            $buildDiagnosticsArchivePath,
            $buildLog,
            $buildLogArchivePath,
            $recentWerDumpCount,
            $failureKind.remediation,
            $buildLogSignal.tail_80,
            $outputLocked,
            $outputHolderText,
            $toolchainCrash,
            $buildAttempt,
            $maxBuildAttempts,
            $crashHistoryText)
    }
    if (-not (Test-Path $built)) { Die "Build reported success but $built is missing." }
    if (-not (Test-Path -LiteralPath $builtNativeHost -PathType Leaf)) {
        Die "SYNAPSE_BUILD_NATIVE_HOST_MISSING path=$builtNativeHost remediation=cargo build -p synapse-mcp must emit every declared package binary; inspect the Cargo target inventory and setup-build.log"
    }
    if (-not (Test-Path -LiteralPath $builtSupervisorBootstrap -PathType Leaf)) {
        Die "SYNAPSE_BUILD_SUPERVISOR_BOOTSTRAP_MISSING path=$builtSupervisorBootstrap remediation=cargo build -p synapse-mcp must emit the declared native prebound supervisor bootstrap; inspect the Cargo target inventory and setup-build.log"
    }
    Info "Built: $built ($([math]::Round((Get-Item $built).Length/1MB,1)) MB)"
    Info "Built Chrome native host: $builtNativeHost ($([math]::Round((Get-Item $builtNativeHost).Length/1MB,1)) MB)"
    Info "Built native supervisor bootstrap: $builtSupervisorBootstrap ($([math]::Round((Get-Item $builtSupervisorBootstrap).Length/1MB,1)) MB)"

    # Durable readback naming the EXACT build tree and feature set used, so an
    # operator can prove after the fact where artifacts landed (#1857) and which
    # acceleration was compiled in (#1859) without re-deriving it from logs.
    $buildTargetReadbackPath = Join-Path $LogDir 'setup-build-target.json'
    $builtArtifact = Get-Item -LiteralPath $built
    $builtNativeHostArtifact = Get-Item -LiteralPath $builtNativeHost
    $builtSupervisorBootstrapArtifact = Get-Item -LiteralPath $builtSupervisorBootstrap
    $buildTargetReadback = [ordered]@{
        schema = 'synapse_setup_build_target_readback/v2'
        observed_at_utc = (Get-Date).ToUniversalTime().ToString('o')
        source_dir = $cargoTargetResolution.source_dir
        cargo_target_dir = $cargoTargetResolution.path
        cargo_target_dir_kind = $cargoTargetResolution.kind
        cargo_target_dir_authorized_by = $cargoTargetResolution.authorized_by
        cargo_target_dir_env = $env:CARGO_TARGET_DIR
        canonical_checkout_target = (Join-Path $cargoTargetResolution.source_dir 'target')
        alternate_target_footprint = $cargoTargetResolution.alternate_footprint
        pre_existing_alternate_build_targets = $alternateBuildTargetInventory
        cargo_invocation = ($cargoBuildArgs -join ' ')
        cuda_build_capability = $cudaBuildCapability
        artifact_path = $built
        artifact_byte_len = $builtArtifact.Length
        artifact_sha256 = (Get-SynapseFileSha256 -Path $built)
        artifact_last_write_utc = $builtArtifact.LastWriteTimeUtc.ToString('o')
        chrome_native_host_artifact_path = $builtNativeHost
        chrome_native_host_artifact_byte_len = $builtNativeHostArtifact.Length
        chrome_native_host_artifact_sha256 = (Get-SynapseFileSha256 -Path $builtNativeHost)
        chrome_native_host_artifact_last_write_utc = $builtNativeHostArtifact.LastWriteTimeUtc.ToString('o')
        supervisor_bootstrap_artifact_path = $builtSupervisorBootstrap
        supervisor_bootstrap_artifact_byte_len = $builtSupervisorBootstrapArtifact.Length
        supervisor_bootstrap_artifact_sha256 = (Get-SynapseFileSha256 -Path $builtSupervisorBootstrap)
        supervisor_bootstrap_artifact_last_write_utc = $builtSupervisorBootstrapArtifact.LastWriteTimeUtc.ToString('o')
    }
    $buildTargetReadback | ConvertTo-Json -Depth 32 | Set-Content -LiteralPath $buildTargetReadbackPath -Encoding UTF8
    Info ("Build target readback -> {0} (cargo_target_dir={1} kind={2} cuda_kernels={3} artifact_sha256={4} chrome_native_host_sha256={5})" -f `
        $buildTargetReadbackPath,
        $buildTargetReadback.cargo_target_dir,
        $buildTargetReadback.cargo_target_dir_kind,
        $cudaBuildCapability.enabled,
        $buildTargetReadback.artifact_sha256,
        $buildTargetReadback.chrome_native_host_artifact_sha256)
    $embeddedModels = @(Install-SynapsePinnedDetectionModels -Root $embeddedModelRoot -SourceDir $SourceDir)
    foreach ($slotName in $script:SynapseEmbeddedModelSlotOrder) {
        if (-not @($embeddedModels | Where-Object { $_.Name -eq $slotName })[0]) {
            Die "SYNAPSE_EMBEDDED_MODEL_SELECTION_FAILED root=$embeddedModelRoot slot=$slotName remediation=the pinned model acquisition did not return an entry for every registered model slot"
        }
    }
    # Record the capability gaps this build ships with, next to the build
    # readback, so "why is STT unavailable" is answerable from disk without
    # re-deriving it (#1863).
    $capabilityGaps = @($embeddedModels | Where-Object { -not $_.Present } | ForEach-Object {
        [ordered]@{
            model = $_.Name
            capability = $_.Capability
            required = $_.Required
            expected_sha256 = $_.Sha256
            expected_length = $_.Length
            reason = $_.AbsenceReason
            recipe = $_.Recipe
            override_env = $_.OverrideEnv
            pin_path = $_.PinPath
        }
    })
    $capabilityGapPath = Join-Path $LogDir 'synapse-setup-capability-gaps.json'
    ([ordered]@{
        schema = 'synapse_setup_capability_gaps/v1'
        observed_at_utc = (Get-Date).ToUniversalTime().ToString('o')
        executable = $built
        executable_sha256 = (Get-SynapseFileSha256 -Path $built)
        absent_optional_models = @($capabilityGaps)
    }) | ConvertTo-Json -Depth 32 | Set-Content -LiteralPath $capabilityGapPath -Encoding UTF8
    if (@($capabilityGaps).Count -gt 0) {
        Warn "SYNAPSE_BUILD_CAPABILITY_GAPS count=$(@($capabilityGaps).Count) readback=$capabilityGapPath models=$(@($capabilityGaps | ForEach-Object { $_.model }) -join ',')"
    } else {
        Info "Build capability gaps: none; every registered model was packaged (readback=$capabilityGapPath)"
    }
}

# ---------------------------------------------------------------------------
# 3. Token, data dirs, and profile source resolution
# ---------------------------------------------------------------------------
Step "Bearer token + data dirs"
$tokDir = Split-Path -Parent $TokenPath
New-Item -ItemType Directory -Force -Path $tokDir, $DbPath, $LogDir | Out-Null
if (-not (Test-Path $TokenPath)) {
    $bytes = New-Object byte[] 32
    [System.Security.Cryptography.RandomNumberGenerator]::Create().GetBytes($bytes)
    ($bytes | ForEach-Object { $_.ToString('x2') }) -join '' | Set-Content -Path $TokenPath -NoNewline -Encoding ascii
    Info "Generated token -> $TokenPath"
} else { Info "Reusing token -> $TokenPath" }
$tokenRaw = Get-Content -Raw $TokenPath
$token = if ($null -eq $tokenRaw) { '' } else { $tokenRaw.Trim() }
if ($token.Length -lt 16) { Die "Token at $TokenPath is too short ($($token.Length) chars); delete it and re-run to regenerate." }
[Environment]::SetEnvironmentVariable('SYNAPSE_BEARER_TOKEN', $token, 'User')
$env:SYNAPSE_BEARER_TOKEN = $token
Info "Set Windows User SYNAPSE_BEARER_TOKEN from $TokenPath for native HTTP MCP clients that require env-based bearer auth."
try {
    $signature = '[DllImport("user32.dll", SetLastError=true, CharSet=CharSet.Auto)] public static extern IntPtr SendMessageTimeout(IntPtr hWnd, uint Msg, UIntPtr wParam, string lParam, uint fuFlags, uint uTimeout, out UIntPtr lpdwResult);'
    $type = Add-Type -MemberDefinition $signature -Name Win32SendMessageTimeout -Namespace SynapseEnv -PassThru -ErrorAction Stop
    $broadcastResult = [UIntPtr]::Zero
    $rawReturn = $type::SendMessageTimeout([IntPtr]0xffff, 0x001A, [UIntPtr]::Zero, 'Environment', 0x0002, 5000, [ref]$broadcastResult)
    if ($rawReturn -eq [IntPtr]::Zero) {
        Info "WARN: environment broadcast returned 0; future GUI clients may need restart before seeing SYNAPSE_BEARER_TOKEN."
    }
} catch {
    Info "WARN: environment broadcast failed: $($_.Exception.Message). Future GUI clients may need restart before seeing SYNAPSE_BEARER_TOKEN."
}

Info "Candidate profiles verified path=$candidateProfilesDir count=$candidateProfileCount"

# ---------------------------------------------------------------------------
# 4. Stage and health-check the replacement before touching the live daemon
# ---------------------------------------------------------------------------
Step "Validating candidate daemon before handoff"
$installSourcePath = $ExePath
$installSourceHash = $null
$nativeHostInstallSourcePath = $ChromeNativeHostExePath
$nativeHostInstallSourceHash = $null
$supervisorBootstrapInstallSourcePath = Join-Path $RuntimeBinDir 'synapse-supervisor-bootstrap.exe'
$supervisorBootstrapInstallSourceHash = $null
if ($SkipBuild) {
    if (-not (Test-Path -LiteralPath $ExePath)) {
        Die "SYNAPSE_SKIP_BUILD_BINARY_MISSING path=$ExePath remediation=-SkipBuild requires a real local synapse-mcp.exe at -ExePath before setup can touch the live daemon"
    }
    # Validating a pre-built binary rather than packaging one: the expectations
    # still come from the committed pins, and each slot's presence is read from
    # the binary itself. A required slot that is absent still fails closed.
    $skipBuildBundle = Get-SynapseExecutableModelBundle -ExecutablePath $ExePath
    if (-not $skipBuildBundle) {
        Die "SYNAPSE_EMBEDDED_MODEL_BUNDLE_MISSING path=$ExePath remediation=-SkipBuild requires a binary already packaged by this setup script; build without -SkipBuild to package one"
    }
    $skipBuildModels = @(Get-SynapseEmbeddedModelPins -SourceDir $SourceDir)
    foreach ($skipBuildModel in $skipBuildModels) {
        $slot = @($skipBuildBundle.Slots | Where-Object { $_.Name -eq $skipBuildModel.Name })[0]
        $skipBuildModel | Add-Member -NotePropertyName Present -NotePropertyValue ([bool]($slot -and $slot.Present)) -Force
        $skipBuildModel | Add-Member -NotePropertyName Path -NotePropertyValue $null -Force
    }
    [void](Assert-SynapseExecutableModelBundle -ExecutablePath $ExePath -Models $skipBuildModels)
    $installSourceHash = Get-SynapseFileSha256 -Path $ExePath
    Info "SkipBuild candidate binary path=$ExePath sha256=$installSourceHash"
    if (-not (Test-Path -LiteralPath $ChromeNativeHostExePath -PathType Leaf)) {
        Die "SYNAPSE_SKIP_BUILD_NATIVE_HOST_MISSING path=$ChromeNativeHostExePath remediation=-SkipBuild reuses an already installed release generation and requires its real Chrome native host executable"
    }
    $nativeHostInstallSourceHash = Get-SynapseFileSha256 -Path $ChromeNativeHostExePath
    Info "SkipBuild Chrome native host path=$ChromeNativeHostExePath sha256=$nativeHostInstallSourceHash"
    if (-not (Test-Path -LiteralPath $supervisorBootstrapInstallSourcePath -PathType Leaf)) {
        Die "SYNAPSE_SKIP_BUILD_SUPERVISOR_BOOTSTRAP_MISSING path=$supervisorBootstrapInstallSourcePath remediation=-SkipBuild requires the native prebound supervisor bootstrap at the canonical runtime-bin path; run setup without -SkipBuild to build/install the current generation"
    }
    $supervisorBootstrapInstallSourceHash = Get-SynapseFileSha256 -Path $supervisorBootstrapInstallSourcePath
    Info "SkipBuild native supervisor bootstrap path=$supervisorBootstrapInstallSourcePath sha256=$supervisorBootstrapInstallSourceHash"
    $skipBuildCudaProviderPath = Join-Path (Split-Path -Parent $ExePath) 'onnxruntime_providers_cuda.dll'
    if (Test-Path -LiteralPath $skipBuildCudaProviderPath -PathType Leaf) {
        $legacyCudaProviderSha256 = Get-SynapseFileSha256 -Path $skipBuildCudaProviderPath
        $stagedSkipBuildBinary = New-SynapseStagedDaemonBinary `
            -BuiltPath $ExePath `
            -LogDir $LogDir `
            -RuntimeDir (Split-Path -Parent $ExePath)
        $installSourcePath = $stagedSkipBuildBinary.Path
        $installSourceHash = $stagedSkipBuildBinary.Sha256
        Info "SkipBuild isolated CPU-only candidate bundle staged away from legacy CUDA provider source_provider=$skipBuildCudaProviderPath source_provider_sha256=$legacyCudaProviderSha256 candidate=$installSourcePath candidate_sha256=$installSourceHash effect=the live runtime is not mutated before candidate acceptance; verified handoff later retires the stale provider"
    }
} else {
    $stagedBinary = New-SynapseStagedDaemonBinary -BuiltPath $built -LogDir $LogDir -RuntimeDir $ortRuntime.NativeDir -EmbeddedModels $embeddedModels
    $installSourcePath = $stagedBinary.Path
    $installSourceHash = $stagedBinary.Sha256
    $nativeHostInstallSourcePath = $builtNativeHost
    $nativeHostInstallSourceHash = Get-SynapseFileSha256 -Path $nativeHostInstallSourcePath
    $supervisorBootstrapInstallSourcePath = $builtSupervisorBootstrap
    $supervisorBootstrapInstallSourceHash = Get-SynapseFileSha256 -Path $supervisorBootstrapInstallSourcePath
}
if ([string]::IsNullOrWhiteSpace($nativeHostInstallSourceHash)) {
    Die "SYNAPSE_NATIVE_HOST_CANDIDATE_HASH_MISSING path=$nativeHostInstallSourcePath remediation=setup requires a physical SHA-256 identity for the Chrome native host before handoff"
}
if ([string]::IsNullOrWhiteSpace($supervisorBootstrapInstallSourceHash) -or
    -not (Test-Path -LiteralPath $supervisorBootstrapInstallSourcePath -PathType Leaf)) {
    Die "SYNAPSE_SUPERVISOR_BOOTSTRAP_CANDIDATE_MISSING path=$supervisorBootstrapInstallSourcePath sha256=$(if ($supervisorBootstrapInstallSourceHash) { $supervisorBootstrapInstallSourceHash } else { '<absent>' }) remediation=the exact native prebound bootstrap built alongside the daemon must exist before candidate handoff"
}
$candidateRuntimeFiles = @(Get-SynapseOrtRuntimeCompanions -ExecutablePath $installSourcePath)
foreach ($candidateRuntimeFile in $candidateRuntimeFiles) {
    $candidateRuntimeFile | Add-Member `
        -NotePropertyName DestinationPath `
        -NotePropertyValue ([System.IO.Path]::GetFullPath((Join-Path (Split-Path -Parent $ExePath) $candidateRuntimeFile.Name))) `
        -Force
}
$candidateRuntimeFiles += [pscustomobject]@{
    Name = 'synapse-supervisor-bootstrap.exe'
    Path = [System.IO.Path]::GetFullPath($supervisorBootstrapInstallSourcePath)
    Sha256 = $supervisorBootstrapInstallSourceHash
    DestinationPath = [System.IO.Path]::GetFullPath((Join-Path $RuntimeBinDir 'synapse-supervisor-bootstrap.exe'))
}
$runtimeSupervisorOutputPath = [System.IO.Path]::GetFullPath((Join-Path $RuntimeBinDir 'synapse-daemon-launch-hidden.vbs'))
$runtimeSupervisorCandidate = New-HiddenDaemonLauncher `
    -OutputPath $runtimeSupervisorOutputPath `
    -ExePath $ExePath `
    -Bind $Bind `
    -DbPath $DbPath `
    -ProfilesDir $ProfilesDir `
    -LogDir $LogDir `
    -TokenPath $TokenPath `
    -MaintenanceLockPath $MaintenanceLockPath `
    -EnableAudio $EnableAudio `
    -AllowedPermissions $AllowedPermissions `
    -CalyxConfigPath $CalyxConfigPath `
    -ExpectedCalyxConfigSha256 $script:SynapseCalyxConfigSha256 `
    -ContentOnly
$runtimeCandidateMappings = @()
$installSourceItem = Get-Item -LiteralPath $installSourcePath -Force -ErrorAction Stop
$runtimeCandidateMappings += [pscustomobject][ordered]@{
    DestinationPath = [System.IO.Path]::GetFullPath($ExePath)
    SourcePath = [System.IO.Path]::GetFullPath($installSourcePath)
    Sha256 = ([string]$installSourceHash).ToUpperInvariant()
    Length = [int64]$installSourceItem.Length
}
$nativeHostInstallSourceItem = Get-Item -LiteralPath $nativeHostInstallSourcePath -Force -ErrorAction Stop
$runtimeCandidateMappings += [pscustomobject][ordered]@{
    DestinationPath = [System.IO.Path]::GetFullPath($ChromeNativeHostExePath)
    SourcePath = [System.IO.Path]::GetFullPath($nativeHostInstallSourcePath)
    Sha256 = ([string]$nativeHostInstallSourceHash).ToUpperInvariant()
    Length = [int64]$nativeHostInstallSourceItem.Length
}
foreach ($candidateRuntimeFile in $candidateRuntimeFiles) {
    $candidateRuntimeItem = Get-Item -LiteralPath ([string]$candidateRuntimeFile.Path) -Force -ErrorAction Stop
    $runtimeCandidateMappings += [pscustomobject][ordered]@{
        DestinationPath = [System.IO.Path]::GetFullPath([string]$candidateRuntimeFile.DestinationPath)
        SourcePath = [System.IO.Path]::GetFullPath([string]$candidateRuntimeFile.Path)
        Sha256 = ([string]$candidateRuntimeFile.Sha256).ToUpperInvariant()
        Length = [int64]$candidateRuntimeItem.Length
    }
}
$runtimeCandidateMappings += [pscustomobject][ordered]@{
    DestinationPath = [string]$runtimeSupervisorCandidate.SupervisorPath
    Content = [string]$runtimeSupervisorCandidate.Content
    Sha256 = ([string]$runtimeSupervisorCandidate.Sha256).ToUpperInvariant()
    Length = [int64]$runtimeSupervisorCandidate.Length
}
$runtimeCandidateMappings = @($runtimeCandidateMappings | Sort-Object { [System.IO.Path]::GetFullPath([string]$_.DestinationPath) })
$runtimeExpectedPaths = @($runtimeCandidateMappings | ForEach-Object { [System.IO.Path]::GetFullPath([string]$_.DestinationPath) } | Sort-Object -Unique)
if ($runtimeExpectedPaths.Count -ne $runtimeCandidateMappings.Count) {
    Die "SYNAPSE_RUNTIME_CANDIDATE_MAPPING_DUPLICATE expected_unique=$($runtimeExpectedPaths.Count) actual=$($runtimeCandidateMappings.Count)"
}
foreach ($runtimeCandidateParent in @($runtimeExpectedPaths | ForEach-Object { Split-Path -Parent $_ } | Sort-Object -Unique)) {
    [void](Ensure-SynapsePhysicalDirectoryPath -Path $runtimeCandidateParent -Context 'runtime_candidate_parent_prerequisite')
}
$candidateRuntimeSummary = ($candidateRuntimeFiles | ForEach-Object { "{0}:{1}:destination={2}" -f $_.Name, $_.Sha256, $_.DestinationPath }) -join ','
Info "Candidate runtime bundle verified files=$candidateRuntimeSummary supervisor_path=$($runtimeSupervisorCandidate.SupervisorPath) supervisor_sha256=$($runtimeSupervisorCandidate.Sha256) exact_transaction_path_count=$($runtimeExpectedPaths.Count)"
$replacementReservationId = Get-SynapseCandidateReplacementReservationId -Bind $Bind -Token $token -LogDir $LogDir -CalyxConfigPath $CalyxConfigPath -ExpectedCalyxConfigSha256 $script:SynapseCalyxConfigSha256
$adoptionRehearsalSurface=Get-SynapseOfflineToolSurfaceReceipt -ExecutablePath $installSourcePath -ExpectedSha256 $installSourceHash
Info "SYNAPSE_OFFLINE_TOOL_SURFACE_SEALED candidate=$installSourcePath tool_count=$($adoptionRehearsalSurface.ToolCount) tool_surface_sha256=$($adoptionRehearsalSurface.ToolSurfaceSha256)"

# Recover an interrupted armed transaction before taking a new snapshot. The
# manifest is accepted only when every identity is inside this setup's exact
# managed path set; an ambiguous or foreign path fails closed.
$globalRecoveryBeforeAction=Get-SynapseGlobalRecoveryInventory -LogDir $LogDir -ProfilesDir $ProfilesDir -RuntimeBinDir $RuntimeBinDir
$globalRecoveryBeforeActionTaskInfrastructure=if($null-ne$globalRecoveryAuthority){$globalRecoveryAuthority.Infrastructure}else{$globalRecoveryTaskInfrastructure}
$globalRecoveryBeforeActionPrerequisite=Assert-SynapseGlobalCommittedAuthorityPreflight -Inventory $globalRecoveryBeforeAction -TaskInfrastructure $globalRecoveryBeforeActionTaskInfrastructure -RuntimeBinDir $RuntimeBinDir -RequestedLegacyTaskName $TaskName -DecommissionStructuralOnly:$Remove
$globalRecoveryBeforeActionSelection=Select-SynapseGlobalRecoveryAction -Inventory $globalRecoveryBeforeAction -Mode $globalRecoveryMode
if(-not [bool]$globalRecoveryBeforeActionSelection.Allowed){Die ([string]$globalRecoveryBeforeActionSelection.Error)}
if([string]$globalRecoveryBeforeAction.FingerprintSha256 -ine $globalRecoveryFingerprint){
    Die "SYNAPSE_GLOBAL_RECOVERY_INVENTORY_CHANGED initial_sha256=$globalRecoveryFingerprint current_sha256=$($globalRecoveryBeforeAction.FingerprintSha256) remediation=preserve every domain; no recovery or cleanup action begins after the global journal inventory changes"
}
$deploymentTransactionParent = Join-Path $LogDir 'setup-transactions'
$deploymentRecoveryAllowedPaths = @(
    $ExePath,
    $ChromeNativeHostExePath,
    $CalyxConfigPath,
    (Join-Path $RuntimeBinDir 'synapse-supervisor-bootstrap.exe'),
    (Join-Path $RuntimeBinDir 'synapse-daemon-supervisor.ps1'),
    (Join-Path $RuntimeBinDir 'synapse-daemon-launch-hidden.vbs'),
    (Join-Path $LogDir 'synapse-daemon-supervisor.ps1'),
    (Join-Path $LogDir 'synapse-daemon-launch-hidden.vbs'),
    (Join-Path (Split-Path -Parent $ExePath) 'onnxruntime_providers_cuda.dll'),
    (Join-Path (Split-Path -Parent $ExePath) 'synapse-fsv-toast-history.exe'),
    # Pre-fix armed manifests may name the bootstrap destination that setup
    # mistakenly derived from ExePath. Permit only rollback of that exact path;
    # new transaction snapshots and installs use the RuntimeBinDir destination.
    (Join-Path (Split-Path -Parent $ExePath) 'synapse-supervisor-bootstrap.exe'),
    (Get-SynapseDaemonSupervisorStopRequestPath -RuntimeBinDir $RuntimeBinDir)
)
$deploymentRecoveryAllowedPaths += @($candidateRuntimeFiles | ForEach-Object { $_.DestinationPath })
$deploymentRecoveryAllowedPaths = @($deploymentRecoveryAllowedPaths | ForEach-Object { [System.IO.Path]::GetFullPath([string]$_) } | Sort-Object -Unique)
if (Test-Path -LiteralPath $deploymentTransactionParent -PathType Container) {
    $armedRecoveryTransactions = @()
    $legacyTransactionParentChain = @(Get-SynapsePhysicalDirectoryChainDescriptor -Path $deploymentTransactionParent)
    $legacyTransactionEntries = @(Get-SynapsePhysicalDirectoryEntriesBounded -Path $deploymentTransactionParent -Chain $legacyTransactionParentChain -MaximumEntries 128 -Context 'legacy_v1_transaction_parent')
    $legacyUnexpectedEntries = @($legacyTransactionEntries | Where-Object {
        -not [bool]$_.IsDirectory -or
        ([uint32]$_.Attributes -band [uint32][System.IO.FileAttributes]::ReparsePoint) -or
        [string]$_.Name -notmatch '^deployment-\d{8}T\d{9}Z-\d+$'
    })
    if ($legacyUnexpectedEntries.Count -gt 0) {
        Die "SYNAPSE_DEPLOYMENT_TRANSACTION_V1_PARENT_CONTENT_INVALID root=$deploymentTransactionParent entries=$(@($legacyUnexpectedEntries.Name)-join ',') remediation=preserve unexpected legacy transaction siblings"
    }
    foreach ($recoveryDirectory in @($legacyTransactionEntries | Sort-Object Name)) {
        $recoveryManifestPath = Join-Path $recoveryDirectory.Path 'transaction.json'
        if (-not (Test-Path -LiteralPath $recoveryManifestPath -PathType Leaf)) {
            [void](Remove-SynapseDeploymentTransactionArtifact -Path $recoveryDirectory.Path -ExpectedRoot $deploymentTransactionParent -ExpectedState 'unarmed' -Reason 'orphan_unarmed_deployment_transaction_cleanup')
            continue
        }
        $recoveryManifestItem = Get-Item -LiteralPath $recoveryManifestPath -Force -ErrorAction Stop
        if (($recoveryManifestItem.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -or $recoveryManifestItem.Length -gt 1MB) {
            Die "SYNAPSE_DEPLOYMENT_TRANSACTION_RECOVERY_MANIFEST_INVALID path=$recoveryManifestPath length=$($recoveryManifestItem.Length) attributes=$($recoveryManifestItem.Attributes) remediation=preserve and inspect the bounded regular transaction manifest before setup continues"
        }
        try { $recoveryManifest = Get-Content -Raw -LiteralPath $recoveryManifestPath -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop } catch {
            Die "SYNAPSE_DEPLOYMENT_TRANSACTION_RECOVERY_MANIFEST_UNREADABLE path=$recoveryManifestPath error=$($_.Exception.Message) remediation=preserve the transaction directory and repair its manifest before setup continues"
        }
        if ([string]$recoveryManifest.schema -ne 'synapse_deployment_transaction/v1') {
            Die "SYNAPSE_DEPLOYMENT_TRANSACTION_RECOVERY_SCHEMA_INVALID path=$recoveryManifestPath schema=$($recoveryManifest.schema) remediation=do not guess how to restore an unknown deployment transaction schema"
        }
        if ([string]$recoveryManifest.state -eq 'committed' -or [string]$recoveryManifest.state -eq 'rolled_back') {
            [void](Remove-SynapseDeploymentTransactionArtifact -Path $recoveryDirectory.Path -ExpectedRoot $deploymentTransactionParent -ExpectedState ([string]$recoveryManifest.state) -Reason 'terminal_deployment_transaction_cleanup')
            continue
        }
        if ([string]$recoveryManifest.state -ne 'armed') {
            Die "SYNAPSE_DEPLOYMENT_TRANSACTION_RECOVERY_STATE_INVALID path=$recoveryManifestPath state=$($recoveryManifest.state) remediation=preserve the transaction directory and resolve its exact terminal state"
        }
        $armedRecoveryTransactions += [pscustomobject]@{ Directory = $recoveryDirectory; ManifestPath = $recoveryManifestPath; Manifest = $recoveryManifest }
    }
    if ($armedRecoveryTransactions.Count -gt 1) {
        Die "SYNAPSE_DEPLOYMENT_TRANSACTION_RECOVERY_AMBIGUOUS root=$deploymentTransactionParent armed_count=$($armedRecoveryTransactions.Count) remediation=preserve every manifest and determine which exact task/file generation owns restart authority before setup continues"
    }
    if ($armedRecoveryTransactions.Count -eq 1) {
        $recovery = $armedRecoveryTransactions[0]
        $manifest = $recovery.Manifest
        if ([string]$manifest.task_name -cne $TaskName -or
            [string]$manifest.bind -cne $Bind -or
            [System.IO.Path]::GetFullPath([string]$manifest.db_path) -ine [System.IO.Path]::GetFullPath($DbPath) -or
            [System.IO.Path]::GetFullPath([string]$manifest.token_path) -ine [System.IO.Path]::GetFullPath($TokenPath) -or
            [System.IO.Path]::GetFullPath([string]$manifest.transaction_root) -ine [System.IO.Path]::GetFullPath($recovery.Directory.Path)) {
            Die "SYNAPSE_DEPLOYMENT_TRANSACTION_RECOVERY_IDENTITY_MISMATCH manifest=$($recovery.ManifestPath) remediation=the interrupted transaction does not belong to this exact task/bind/db/token/root identity"
        }
        $recoveryProfileTransaction = $null
        $recoveryProfileProperty = $manifest.PSObject.Properties['profile_transaction']
        if ($null -ne $recoveryProfileProperty) {
            $recoveryProfileTransaction = $recoveryProfileProperty.Value
            $recoveryProfilePlan = Assert-SynapseBundledProfilesTransactionDescriptor `
                -Descriptor $recoveryProfileTransaction `
                -ProfilesDir $ProfilesDir `
                -TransactionRoot $recovery.Directory.Path
            $deploymentRecoveryAllowedPaths += @($recoveryProfilePlan.ManagedPaths)
            $deploymentRecoveryAllowedPaths = @($deploymentRecoveryAllowedPaths |
                ForEach-Object { [System.IO.Path]::GetFullPath([string]$_) } |
                Sort-Object -Unique)
        }
        $recoverySnapshotPaths = New-SynapseCaseInsensitiveMap
        foreach ($recoveryFile in @($manifest.file_snapshots)) {
            $recoveryPath = [System.IO.Path]::GetFullPath([string]$recoveryFile.Path)
            if ($recoverySnapshotPaths.ContainsKey($recoveryPath)) {
                Die "SYNAPSE_DEPLOYMENT_TRANSACTION_RECOVERY_DUPLICATE_PATH manifest=$($recovery.ManifestPath) path=$recoveryPath remediation=rollback refuses ambiguous duplicate snapshots"
            }
            $recoverySnapshotPaths[$recoveryPath] = $recoveryFile
            if ($deploymentRecoveryAllowedPaths -inotcontains $recoveryPath) {
                Die "SYNAPSE_DEPLOYMENT_TRANSACTION_RECOVERY_PATH_OUT_OF_SCOPE manifest=$($recovery.ManifestPath) path=$recoveryPath remediation=rollback refuses any path outside the exact setup-managed runtime generation"
            }
            if ([bool]$recoveryFile.Existed) {
                $recoveryBackupPath = [System.IO.Path]::GetFullPath([string]$recoveryFile.BackupPath)
                if ((Split-Path -Parent $recoveryBackupPath) -ine [System.IO.Path]::GetFullPath($recovery.Directory.Path)) {
                    Die "SYNAPSE_DEPLOYMENT_TRANSACTION_RECOVERY_BACKUP_OUT_OF_SCOPE manifest=$($recovery.ManifestPath) backup=$recoveryBackupPath remediation=rollback backup bytes must reside directly in their transaction directory"
                }
            }
        }
        if ($null -ne $recoveryProfileTransaction) {
            foreach ($profileTransition in @($recoveryProfilePlan.Transitions)) {
                if (-not $recoverySnapshotPaths.ContainsKey($profileTransition.Path)) {
                    Die "SYNAPSE_DEPLOYMENT_TRANSACTION_RECOVERY_PROFILE_SNAPSHOT_MISSING manifest=$($recovery.ManifestPath) path=$($profileTransition.Path) remediation=preserve the interrupted transaction; every declared profile mutation path needs a durable pre-mutation snapshot"
                }
                $profileSnapshot = $recoverySnapshotPaths[$profileTransition.Path]
                if ([bool]$profileSnapshot.Existed -ne [bool]$profileTransition.pre_existed -or
                    ([bool]$profileSnapshot.Existed -and [string]$profileSnapshot.Sha256 -ine [string]$profileTransition.pre_sha256)) {
                    Die "SYNAPSE_DEPLOYMENT_TRANSACTION_RECOVERY_PROFILE_PREIMAGE_MISMATCH manifest=$($recovery.ManifestPath) path=$($profileTransition.Path) planned_exists=$($profileTransition.pre_existed) planned_sha256=$($profileTransition.pre_sha256) snapshot_exists=$($profileSnapshot.Existed) snapshot_sha256=$($profileSnapshot.Sha256) remediation=preserve the transaction; recovery never guesses between divergent ownership and backup preimages"
                }
            }
        }
        $legacyManifestSha256 = Get-SynapseFileSha256 -Path $recovery.ManifestPath
        $legacyNoopWrite = Complete-SynapseLegacyV1NoMutationRecovery `
            -ManifestPath $recovery.ManifestPath `
            -Manifest $manifest `
            -ExpectedManifestSha256 $legacyManifestSha256 `
            -ExpectedTaskName $TaskName
        [void](Remove-SynapseDeploymentTransactionArtifact -Path $recovery.Directory.Path -ExpectedRoot $deploymentTransactionParent -ExpectedState 'rolled_back' -Reason 'recovered_deployment_transaction_cleanup')
        Info "SYNAPSE_DEPLOYMENT_TRANSACTION_V1_NOOP_RECOVERED manifest=$($recovery.ManifestPath) terminal_sha256=$($legacyNoopWrite.sha256) runtime_mutations=0 task_mutations=0"
    }
}

# Arm one durable deployment transaction before the first runtime drain. Its
# file/task snapshots are the rollback Source of Truth for candidate failure,
# first install, same-binary restart, and every later pre-commit exception.

# v3 stores the whole deployment transaction beside ProfilesDir so every
# profile root/stage/park transition is same-volume and handle-relative. The
# persistent parent is setup metadata; each invocation directory is exact-ID
# bounded and independently recoverable.
$profilesTransactionParent = Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent ([System.IO.Path]::GetFullPath($ProfilesDir)))
$profilesTransactionLeaf = Split-Path -Leaf ([System.IO.Path]::GetFullPath($ProfilesDir))
if ($profilesTransactionLeaf -ieq $script:SynapseDeploymentTransactionParentDirName) {
    Die "SYNAPSE_DEPLOYMENT_TRANSACTION_RESERVED_PROFILE_TOPOLOGY profiles_dir=$ProfilesDir reserved_leaf=$($script:SynapseDeploymentTransactionParentDirName) remediation=ProfilesDir must be a distinct direct sibling of setup transaction metadata"
}
$deploymentTransactionParent = Join-Path $profilesTransactionParent $script:SynapseDeploymentTransactionParentDirName
$deploymentTransactionParent = Get-SynapseNormalizedDirectoryPath -Path $deploymentTransactionParent
if ((Get-SynapseNormalizedDirectoryPath -Path (Split-Path -Parent $deploymentTransactionParent)) -ine $profilesTransactionParent -or
    (Get-SynapseNormalizedDirectoryPath -Path ([System.IO.Path]::GetFullPath($ProfilesDir))) -ieq $deploymentTransactionParent) {
    Die "SYNAPSE_DEPLOYMENT_TRANSACTION_PARENT_TOPOLOGY_INVALID profiles_dir=$ProfilesDir profiles_parent=$profilesTransactionParent transaction_parent=$deploymentTransactionParent remediation=the reserved transaction parent must be one distinct direct sibling under the pinned ProfilesDir parent"
}
$deploymentTransactionParentChain = @(Ensure-SynapsePhysicalDirectoryPath -Path $deploymentTransactionParent -Context 'deployment_transaction_parent')
$brokerProbeParkRecovery = @()
$brokerApplicationV4Recovery = @()
$deploymentTransactionParentEntries = @(Get-SynapsePhysicalDirectoryEntriesBounded -Path $deploymentTransactionParent -Chain $deploymentTransactionParentChain -MaximumEntries $script:SynapseDeploymentArtifactMaxDirectEntries -Context 'deployment_transaction_parent_recovery')
$unexpectedTransactionParentEntries=@($deploymentTransactionParentEntries|Where-Object{-not [bool]$_.IsDirectory -or ([uint32]$_.Attributes -band [uint32][System.IO.FileAttributes]::ReparsePoint) -or [string]$_.Name -notmatch '^deployment-\d{8}T\d{9}Z-\d+$'})
if($unexpectedTransactionParentEntries.Count -gt 0){Die "SYNAPSE_DEPLOYMENT_TRANSACTION_PARENT_CONTENT_INVALID root=$deploymentTransactionParent entries=$(@($unexpectedTransactionParentEntries.Name)-join ',') remediation=preserve unexpected sibling metadata; setup will not broaden recovery authority"}
foreach ($recoveryDirectory in @($deploymentTransactionParentEntries | Where-Object { [bool]$_.IsDirectory -and [string]$_.Name -match '^deployment-\d{8}T\d{9}Z-\d+$' } | Sort-Object Name)) {
    $journal = $null
    try { $journal = Read-SynapseDeploymentTransactionJournal -TransactionRoot $recoveryDirectory.Path } catch {
        $journalReadError = $_.Exception.Message
        if (Remove-SynapseDeploymentCleanupTailIfPresent -TransactionRoot $recoveryDirectory.Path -ExpectedParent $deploymentTransactionParent) {
            continue
        }
        try {
            [void](Remove-SynapseDeploymentTransactionArtifact -Path $recoveryDirectory.Path -ExpectedRoot $deploymentTransactionParent -ExpectedState 'unarmed' -Reason 'torn_initial_v3_transaction_cleanup')
            Info "SYNAPSE_DEPLOYMENT_TRANSACTION_TORN_INITIAL_CLEANED root=$($recoveryDirectory.Path) error=$journalReadError"
            continue
        } catch {
            Die "SYNAPSE_DEPLOYMENT_TRANSACTION_V3_JOURNAL_UNREADABLE root=$($recoveryDirectory.Path) error=$journalReadError cleanup_error=$($_.Exception.Message) remediation=preserve the exact transaction directory; recovery refuses ambiguous journal bytes"
        }
    }
    if ($null -eq $journal) {
        [void](Remove-SynapseDeploymentTransactionArtifact -Path $recoveryDirectory.Path -ExpectedRoot $deploymentTransactionParent -ExpectedState 'unarmed' -Reason 'orphan_unarmed_v3_transaction_cleanup')
        continue
    }
    $initial = $journal.Initial
    if([string]$initial.schema -ceq 'synapse_broker_probe_park_transaction/v1' -and [string]$initial.transaction_kind -ceq 'synapse_broker_probe_park/v1'){
        $brokerProbeParkRecovery += [pscustomobject]@{Directory=$recoveryDirectory;Journal=$journal}
        continue
    }
    if([string]$initial.schema -ceq 'synapse_deployment_transaction/v4' -and [string]$initial.transaction_kind -ceq 'synapse_broker_application/v1'){
        $brokerApplicationV4Recovery += [pscustomobject]@{Directory=$recoveryDirectory;Journal=$journal}
        continue
    }
    if([string]$initial.schema -cne 'synapse_deployment_transaction/v3' -or $null -ne $initial.PSObject.Properties['transaction_kind']){
        Die "SYNAPSE_DEPLOYMENT_TRANSACTION_RECOVERY_SCHEMA_KIND_INVALID root=$($recoveryDirectory.Path) schema=$($initial.schema) kind=$($initial.transaction_kind)"
    }
    if ([string]$initial.task_name -cne $TaskName -or [string]$initial.bind -cne $Bind -or
        [System.IO.Path]::GetFullPath([string]$initial.db_path) -ine [System.IO.Path]::GetFullPath($DbPath) -or
        [System.IO.Path]::GetFullPath([string]$initial.token_path) -ine [System.IO.Path]::GetFullPath($TokenPath) -or
        [string]$initial.transaction_root_file_id_128 -ine [string]$journal.RootChain[-1].file_id_128 -or
        [string]$initial.transaction_root_file_id_128 -ine [string]$initial.profile_transaction.transaction_root_chain[-1].file_id_128) {
        Die "SYNAPSE_DEPLOYMENT_TRANSACTION_V3_IDENTITY_MISMATCH root=$($recoveryDirectory.Path) task=$($initial.task_name) bind=$($initial.bind)"
    }
    $recoveryPlan = Assert-SynapseBundledProfilesTransactionDescriptor -Descriptor $initial.profile_transaction -ProfilesDir $ProfilesDir -TransactionRoot $recoveryDirectory.Path
    if ($null -eq $initial.PSObject.Properties['runtime_transaction']) {
        Die "SYNAPSE_DEPLOYMENT_TRANSACTION_V3_RUNTIME_DESCRIPTOR_MISSING root=$($recoveryDirectory.Path) remediation=unknown/unshipped profile-only v3 descriptors are preserved and refused"
    }
    $legacyV3RuntimePaths=@($initial.runtime_transaction.records|ForEach-Object{[System.IO.Path]::GetFullPath([string]$_.path)})
    $recoveryRuntimePlan = ConvertTo-SynapseRuntimeDeploymentPlan `
        -Descriptor $initial.runtime_transaction `
        -TransactionRoot $recoveryDirectory.Path `
        -ExpectedPaths $legacyV3RuntimePaths `
        -Allocation $journal.Allocation
    if ($journal.State -eq 'commit_decided') {
        Complete-SynapseRuntimeCommittedGeneration -RuntimePlan $recoveryRuntimePlan
        Complete-SynapseBundledProfilesCommittedGeneration -ProfilePlan $recoveryPlan
        [void](Remove-SynapseDeploymentTransactionArtifact -Path $recoveryDirectory.Path -ExpectedRoot $deploymentTransactionParent -ExpectedState 'committed' -Reason 'committed_v3_transaction_recovery_cleanup')
        Info "SYNAPSE_DEPLOYMENT_TRANSACTION_COMMIT_RECOVERED root=$($recoveryDirectory.Path) sequence=$($journal.Sequence)"
        continue
    }
    if ($journal.State -eq 'rolled_back') {
        [void](Remove-SynapseDeploymentTransactionArtifact -Path $recoveryDirectory.Path -ExpectedRoot $deploymentTransactionParent -ExpectedState 'rolled_back' -Reason 'rolled_back_v3_transaction_recovery_cleanup')
        continue
    }
    if ($journal.State -eq 'cleanup_ready') {
        $cleanupExpectedState = if ([string]$journal.Latest.detail.terminal_state -eq 'commit_decided') { 'committed' } elseif ([string]$journal.Latest.detail.terminal_state -eq 'rolled_back') { 'rolled_back' } else { Die "SYNAPSE_DEPLOYMENT_TRANSACTION_CLEANUP_READY_STATE_INVALID root=$($recoveryDirectory.Path) terminal=$($journal.Latest.detail.terminal_state)" }
        [void](Remove-SynapseDeploymentTransactionArtifact -Path $recoveryDirectory.Path -ExpectedRoot $deploymentTransactionParent -ExpectedState $cleanupExpectedState -Reason 'v3_cleanup_ready_recovery')
        continue
    }
    if ($journal.State -in @('armed','candidate_ready')) {
        Die "SYNAPSE_DEPLOYMENT_TRANSACTION_V3_FROZEN_ACTIVE_PRESERVED root=$($recoveryDirectory.Path) state=$($journal.State) runtime_mutations=0 task_mutations=0 remediation=preserve this unshipped fixed-task transaction; broker-era setup never rolls it back or mutates its canonical Scheduled Task name"
    }
    Die "SYNAPSE_DEPLOYMENT_TRANSACTION_V3_STATE_INVALID root=$($recoveryDirectory.Path) state=$($journal.State)"
}

if($brokerProbeParkRecovery.Count -gt 1 -or $brokerApplicationV4Recovery.Count -gt 1 -or ($brokerProbeParkRecovery.Count -gt 0 -and $brokerApplicationV4Recovery.Count -gt 0)){
    Die "SYNAPSE_BROKER_APPLICATION_RECOVERY_AMBIGUOUS root=$deploymentTransactionParent probe_count=$($brokerProbeParkRecovery.Count) application_v4_count=$($brokerApplicationV4Recovery.Count)"
}
$authorityPowerShellPath=[System.IO.Path]::GetFullPath((Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'))
$brokerAuthority=Ensure-SynapseBrokerAuthorityAdopted -RuntimeBinDir $RuntimeBinDir -BootstrapSourcePath $supervisorBootstrapInstallSourcePath -PowerShellPath $authorityPowerShellPath -WorkingDirectory $RuntimeBinDir -LogDir $LogDir -TaskName $TaskName -ExePath $ExePath -AdoptionRehearsalExePath $installSourcePath -AdoptionRehearsalExpectedToolCount ([int]$adoptionRehearsalSurface.ToolCount) -AdoptionRehearsalExpectedToolSurfaceSha256 ([string]$adoptionRehearsalSurface.ToolSurfaceSha256) -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -Token $token -MaintenanceLockPath $MaintenanceLockPath -CalyxConfigPath $CalyxConfigPath -ExpectedCalyxConfigSha256 $script:SynapseCalyxConfigSha256 -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions -HealthTimeoutSeconds ([Math]::Min(900,[Math]::Max(120,$InstallHealthTimeoutSeconds)) )
$operatorRecovery=Resolve-SynapseBrokerOperatorStopTransaction -Authority $brokerAuthority -Mode setup -HealthTimeoutSeconds ([Math]::Min(900,[Math]::Max(120,$InstallHealthTimeoutSeconds)))
if([bool]$operatorRecovery.Restored){
    $brokerAuthority=Ensure-SynapseBrokerAuthorityAdopted -RuntimeBinDir $RuntimeBinDir -BootstrapSourcePath $supervisorBootstrapInstallSourcePath -PowerShellPath $authorityPowerShellPath -WorkingDirectory $RuntimeBinDir -LogDir $LogDir -TaskName $TaskName -ExePath $ExePath -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -Token $token -MaintenanceLockPath $MaintenanceLockPath -CalyxConfigPath $CalyxConfigPath -ExpectedCalyxConfigSha256 $script:SynapseCalyxConfigSha256 -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions -HealthTimeoutSeconds ([Math]::Min(900,[Math]::Max(120,$InstallHealthTimeoutSeconds)))
}
if($brokerProbeParkRecovery.Count -eq 1){
    Recover-SynapseBrokerSourceCandidateProbeTransaction -Record $brokerProbeParkRecovery[0] -Authority $brokerAuthority -ExpectedParent $deploymentTransactionParent -HealthTimeoutSeconds ([Math]::Min(900,[Math]::Max(120,$InstallHealthTimeoutSeconds)))
    # Recovery may have advanced the physical control pair from parked back to
    # its journal-bound active generation. Re-read the committed authority
    # receipt and derive current physical state instead of carrying a stale
    # pre-recovery CurrentGeneration value.
    $brokerAuthority=Ensure-SynapseBrokerAuthorityAdopted -RuntimeBinDir $RuntimeBinDir -BootstrapSourcePath $supervisorBootstrapInstallSourcePath -PowerShellPath $authorityPowerShellPath -WorkingDirectory $RuntimeBinDir -LogDir $LogDir -TaskName $TaskName -ExePath $ExePath -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -Token $token -MaintenanceLockPath $MaintenanceLockPath -CalyxConfigPath $CalyxConfigPath -ExpectedCalyxConfigSha256 $script:SynapseCalyxConfigSha256 -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions -HealthTimeoutSeconds ([Math]::Min(900,[Math]::Max(120,$InstallHealthTimeoutSeconds)))
}
if($brokerApplicationV4Recovery.Count -eq 1){
    [void](Recover-SynapseBrokerApplicationTransaction -Record $brokerApplicationV4Recovery[0] -Authority $brokerAuthority -ExpectedParent $deploymentTransactionParent -HealthTimeoutSeconds ([Math]::Min(900,[Math]::Max(120,$InstallHealthTimeoutSeconds))) )
    # Recovery can change the canonical control pair from active prior to
    # parked to active candidate (forward), or back to the exact prior
    # generation (rollback).  Re-derive physical authority from the committed
    # adoption receipt before planning a new deployment; invocation inputs are
    # not a substitute for the current roster Source of Truth.
    $brokerAuthority=Ensure-SynapseBrokerAuthorityAdopted -RuntimeBinDir $RuntimeBinDir -BootstrapSourcePath $supervisorBootstrapInstallSourcePath -PowerShellPath $authorityPowerShellPath -WorkingDirectory $RuntimeBinDir -LogDir $LogDir -TaskName $TaskName -ExePath $ExePath -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -Token $token -MaintenanceLockPath $MaintenanceLockPath -CalyxConfigPath $CalyxConfigPath -ExpectedCalyxConfigSha256 $script:SynapseCalyxConfigSha256 -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions -HealthTimeoutSeconds ([Math]::Min(900,[Math]::Max(120,$InstallHealthTimeoutSeconds)))
}

$brokerExcludedRuntimeDestinations=@(
    [System.IO.Path]::GetFullPath((Join-Path $RuntimeBinDir 'synapse-supervisor-bootstrap.exe')),
    [System.IO.Path]::GetFullPath([string]$runtimeSupervisorCandidate.SupervisorPath)
)
$brokerRuntimeCandidateMappings=@($runtimeCandidateMappings|Where-Object{
    $destination=[System.IO.Path]::GetFullPath([string]$_.DestinationPath)
    $brokerExcludedRuntimeDestinations -inotcontains $destination
}|Sort-Object{[System.IO.Path]::GetFullPath([string]$_.DestinationPath)})
if($brokerRuntimeCandidateMappings.Count -lt 2 -or @($brokerRuntimeCandidateMappings|Where-Object{[System.IO.Path]::GetFullPath([string]$_.DestinationPath) -ieq [System.IO.Path]::GetFullPath($ExePath)}).Count -ne 1 -or
   @($brokerRuntimeCandidateMappings|Where-Object{[System.IO.Path]::GetFullPath([string]$_.DestinationPath) -ieq [System.IO.Path]::GetFullPath($ChromeNativeHostExePath)}).Count -ne 1){
    Die "SYNAPSE_BROKER_RUNTIME_MAPPING_CUTOVER_INVALID count=$($brokerRuntimeCandidateMappings.Count) exe=$ExePath native_host=$ChromeNativeHostExePath"
}
try {
    $sourceProbe=Invoke-SynapseBrokerSourceCandidateProbe -Authority $brokerAuthority -DeploymentTransactionParent $deploymentTransactionParent -DeploymentTransactionParentChain $deploymentTransactionParentChain -CandidateExePath $installSourcePath -CandidateBootstrapPath ([string]$brokerAuthority.Infrastructure.Bootstrap.Path) -ExpectedCandidateBootstrapSha256 ([string]$brokerAuthority.Infrastructure.Bootstrap.Sha256) -ProfilesDir $candidateProfilesDir -TokenPath $TokenPath -Token $token -LogDir $LogDir -Bind $Bind -DbPath $DbPath -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions -CalyxConfigPath $CalyxConfigPath -ExpectedCalyxConfigSha256 $script:SynapseCalyxConfigSha256 -ReplacementReservationId $replacementReservationId -HealthTimeoutSeconds ([Math]::Min(900,[Math]::Max(120,$InstallHealthTimeoutSeconds)))
    if([string]$sourceProbe.Sha256 -ine [string]$installSourceHash -or [string]$sourceProbe.CalyxConfigSha256 -ine [string]$script:SynapseCalyxConfigSha256){
        Die "SYNAPSE_BROKER_SOURCE_PROBE_IDENTITY_MISMATCH expected_exe_sha256=$installSourceHash actual_exe_sha256=$($sourceProbe.Sha256) expected_config_sha256=$($script:SynapseCalyxConfigSha256) actual_config_sha256=$($sourceProbe.CalyxConfigSha256)"
    }
    if($script:SynapseBindPostExitContinuationRequired){
        throw 'SYNAPSE_BIND_POST_EXIT_CONTINUATION_REQUIRED_AFTER_SOURCE_PROBE'
    }
    # The source probe temporarily parks and restores the current generation.
    # Its terminal proof is durable, but a new deployment must still plan from
    # a fresh exact control-pair readback rather than a pre-probe snapshot.
    $brokerAuthority=Ensure-SynapseBrokerAuthorityAdopted -RuntimeBinDir $RuntimeBinDir -BootstrapSourcePath $supervisorBootstrapInstallSourcePath -PowerShellPath $authorityPowerShellPath -WorkingDirectory $RuntimeBinDir -LogDir $LogDir -TaskName $TaskName -ExePath $ExePath -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -TokenPath $TokenPath -Token $token -MaintenanceLockPath $MaintenanceLockPath -CalyxConfigPath $CalyxConfigPath -ExpectedCalyxConfigSha256 $script:SynapseCalyxConfigSha256 -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions -HealthTimeoutSeconds ([Math]::Min(900,[Math]::Max(120,$InstallHealthTimeoutSeconds)))
    $brokerApplicationDeployment=Invoke-SynapseBrokerApplicationDeployment -Authority $brokerAuthority -DeploymentTransactionParent $deploymentTransactionParent -DeploymentTransactionParentChain $deploymentTransactionParentChain -RuntimeMappings $brokerRuntimeCandidateMappings -SourceProfilesDir $srcProfiles -ExePath $ExePath -Bind $Bind -DbPath $DbPath -ProfilesDir $ProfilesDir -LogDir $LogDir -TokenPath $TokenPath -Token $token -MaintenanceLockPath $MaintenanceLockPath -CalyxConfigPath $CalyxConfigPath -ExpectedCalyxConfigSha256 $script:SynapseCalyxConfigSha256 -EnableAudio $EnableAudio -AllowedPermissions $AllowedPermissions -PowerShellPath $authorityPowerShellPath -WorkingDirectory $RuntimeBinDir -SourceProbe $sourceProbe -ReplacementReservationId $replacementReservationId -HealthTimeoutSeconds ([Math]::Min(900,[Math]::Max(120,$InstallHealthTimeoutSeconds)))
} catch {
    $deploymentFailure=[string]$_.Exception.Message
    if($script:SynapseBindPostExitContinuationRequired -and $null -eq $script:SynapseDeploymentTransaction){
        $continuation=Start-SynapsePostExitSetupContinuation -Reason 'broker_application_bind_handoff' -Bind $Bind -SourceDir $SourceDir -ExePath $ExePath -ChromeNativeHostExePath $ChromeNativeHostExePath -CargoTarget $CargoTarget -DbPath $DbPath -ProfilesDir $ProfilesDir -LogDir $LogDir -TokenPath $TokenPath -CodexToolSurfaceSnapshotPath $CodexToolSurfaceSnapshotPath -TaskName $TaskName -MaintenanceLockPath $MaintenanceLockPath -CalyxConfigPath $CalyxConfigPath -ActiveIssue $ActiveIssue -DeadOwnerDetail $script:SynapseBindPostExitContinuationDetail
        Die "SYNAPSE_BIND_POST_EXIT_CONTINUATION_STARTED reason=broker_application_bind_handoff bind=$Bind task=$($continuation.TaskName) child_pid=$($continuation.ChildPid) manifest=$($continuation.ManifestPath) stdout=$($continuation.StdoutPath) stderr=$($continuation.StderrPath) primary_failure=[$deploymentFailure] remediation=the broker transaction restored and proved its exact prior generation before registering this journal-bound one-shot continuation; it waits for parent_pid=$PID, reacquires the maintenance lock, and deploys through a fresh transaction"
    }
    throw
}
$installedHash=([string]$brokerApplicationDeployment.Generation.Executable.Sha256).ToUpperInvariant()
$nativeHostRecord=@($brokerApplicationDeployment.RuntimePlan.Records|Where-Object{[System.IO.Path]::GetFullPath([string]$_.path) -ieq [System.IO.Path]::GetFullPath($ChromeNativeHostExePath)})
if($nativeHostRecord.Count -ne 1){Die "SYNAPSE_BROKER_COMMITTED_NATIVE_HOST_RECORD_INVALID path=$ChromeNativeHostExePath count=$($nativeHostRecord.Count)"}
$installedNativeHostHash=([string]$nativeHostRecord[0].post_sha256).ToUpperInvariant()
$validatedCalyxConfigSha256=([string]$script:SynapseCalyxConfigSha256).ToUpperInvariant()
$profileDeploy=$brokerApplicationDeployment.ProfileDeploy
$runtimeDeploymentPlan=$brokerApplicationDeployment.RuntimePlan
$candidatePreflight=$brokerApplicationDeployment.CandidatePreflight
$toolSurface=$brokerApplicationDeployment.ToolSurface
$h=$brokerApplicationDeployment.Health
$healthPid=[int]$h.pid
$daemonCommitHealth=$h
$daemonCommitIdentityReadback=$brokerApplicationDeployment.Proof
$chromeBridgeInstaller=Join-Path $PSScriptRoot 'install-synapse-chrome-debugger.ps1'
$deploymentCommitReceipt=[ordered]@{schema='synapse_broker_application_commit_receipt/v1';recorded_at_utc=[DateTime]::UtcNow.ToString('o');invocation_id=$script:SynapseSetupInvocationId;broker_identity_sha256=[string]$brokerAuthority.Infrastructure.BrokerIdentitySha256;authority_epoch=[int64]$brokerAuthority.AuthorityEpoch;generation_id=[string]$brokerApplicationDeployment.Generation.GenerationId;daemon_pid=$healthPid;bind=$Bind;installed_binary_path=[System.IO.Path]::GetFullPath($ExePath);installed_binary_sha256=$installedHash;chrome_native_host_path=[System.IO.Path]::GetFullPath($ChromeNativeHostExePath);chrome_native_host_sha256=$installedNativeHostHash;tool_count=[int]$toolSurface.tool_count;tool_surface_sha256=[string]$toolSurface.tool_surface_sha256;runtime_generation_sha256=[string]$brokerApplicationDeployment.Generation.RuntimeGenerationSha256;profile_generation_sha256=[string]$brokerApplicationDeployment.Generation.ProfileGenerationSha256}
$deploymentCommitWrite=Write-SynapseAtomicUtf8TextFile -Path (Join-Path $LogDir 'daemon-deployment-current.json') -Content (Get-SynapseCanonicalJson -Value $deploymentCommitReceipt) -Purpose 'broker_application_commit_receipt'
# Publish the already-validated strict MCP surface only after the generation's
# durable commit. A failure here is loud but must not roll the healthy daemon
# back to bytes whose tools/list differs from the accepted surface.
Write-SynapseCodexToolSurfaceSnapshot -Path $CodexToolSurfaceSnapshotPath -Surface $toolSurface
$h = $daemonCommitHealth

try {
    $h = Assert-SynapseChromeBridgeLiveAfterSetup `
        -Bind $Bind `
        -Token $token `
        -Health $h `
        -ChromeBridgeInstallerPath $chromeBridgeInstaller `
        -ChromeNativeHostExePath $ChromeNativeHostExePath
} catch {
    # A committed daemon handoff and a pending Chrome activation are two
    # different transactions.  In particular, a legacy worker that predates
    # reloadSelf cannot consume freshly deployed bytes without either a natural
    # Chrome lifecycle transition or foreground UI.  Rolling the healthy daemon
    # back does not repair that browser state, while trying UI violates the
    # background-only contract.  Persist the exact committed identities and
    # fail loudly so -ResumeChromeBridgePending can finish only this phase after
    # Chrome has naturally loaded the debugger-free worker.
    $bridgeActivationError = $_.Exception.Message
    $pendingAuthority=Assert-SynapseCurrentBrokerAuthorityGenerationOperational -Authority $brokerAuthority -ExpectedGenerationId ([string]$brokerApplicationDeployment.Generation.GenerationId) -HealthTimeoutSeconds ([Math]::Min(900,[Math]::Max(120,$InstallHealthTimeoutSeconds))) -Context 'chrome_pending_broker_authority'
    $h=$pendingAuthority.Proof.Health
    $pendingDaemonPid = [int]$pendingAuthority.Proof.DaemonPid
    $pendingDaemonProcess = Get-SynapseDaemonProcessIdentity -ProcessId $pendingDaemonPid
    $pendingTask = Assert-SynapseTaskReadbackIdentity -Expected $brokerAuthority.BrokerTask -Kind broker
    $pendingDaemonRunPath = Join-Path $DbPath 'daemon-run-current.json'
    if (-not (Test-Path -LiteralPath $pendingDaemonRunPath -PathType Leaf)) {
        Die "SYNAPSE_SETUP_BRIDGE_PENDING_DAEMON_RUN_MISSING path=$pendingDaemonRunPath daemon_pid=$pendingDaemonPid bridge_error=$bridgeActivationError remediation=repair the daemon lifecycle ledger before setup can persist an identity-bound Chrome activation checkpoint"
    }
    $pendingReadback = [ordered]@{
        state = 'pending'
        checkpoint_generation_id = $script:SynapseSetupInvocationId
        resume_attempt_count = 0
        daemon_handoff = 'committed'
        deployment_commit_manifest_sha256 = $deploymentCommitWrite.sha256
        accepted_tool_count = [int]$toolSurface.tool_count
        accepted_tool_surface_sha256 = [string]$toolSurface.tool_surface_sha256
        daemon_pid = $pendingDaemonPid
        bind = $Bind
        db_path = $DbPath
        installed_binary_path = [System.IO.Path]::GetFullPath($ExePath)
        installed_binary_sha256 = $installedHash
        daemon_process_executable_path = $pendingDaemonProcess.ExecutablePath
        daemon_process_command_line = $pendingDaemonProcess.CommandLine
        daemon_process_creation_date = $pendingDaemonProcess.CreationDate
        daemon_run_current_path = [System.IO.Path]::GetFullPath($pendingDaemonRunPath)
        daemon_run_current_sha256 = Get-SynapseFileSha256 -Path $pendingDaemonRunPath
        token_path = [System.IO.Path]::GetFullPath($TokenPath)
        token_sha256 = Get-SynapseFileSha256 -Path $TokenPath
        setup_script_path = [System.IO.Path]::GetFullPath($PSCommandPath)
        setup_script_sha256 = Get-SynapseFileSha256 -Path $PSCommandPath
        chrome_bridge_installer_path = [System.IO.Path]::GetFullPath($chromeBridgeInstaller)
        chrome_bridge_installer_sha256 = Get-SynapseFileSha256 -Path $chromeBridgeInstaller
        chrome_native_host_exe_path = [System.IO.Path]::GetFullPath($ChromeNativeHostExePath)
        chrome_native_host_exe_sha256 = $installedNativeHostHash
        broker_identity_sha256 = [string]$brokerAuthority.Infrastructure.BrokerIdentitySha256
        authority_epoch = [int64]$brokerAuthority.AuthorityEpoch
        authority_root_path = [string]$brokerAuthority.Layout.Root
        authority_root_file_id_128 = [string]$brokerAuthority.Layout.RootChain[-1].file_id_128
        runtime_bin_dir = [string]$brokerAuthority.Layout.RuntimeBinDir
        runtime_bin_file_id_128 = [string]$brokerAuthority.Layout.RuntimeChain[-1].file_id_128
        authority_generation_id = [string]$brokerApplicationDeployment.Generation.GenerationId
        control_gate_file_id_128 = [string]$pendingAuthority.ControlGate.FileId128
        control_gate_sha256 = [string]$pendingAuthority.ControlGate.Sha256
        control_gate_length = [int64]$pendingAuthority.ControlGate.Length
        roster_file_id_128 = [string]$pendingAuthority.Roster.FileId128
        roster_sha256 = [string]$pendingAuthority.Roster.Sha256
        roster_length = [int64]$pendingAuthority.Roster.Length
        broker_task_capability_sha256 = ([string]$brokerAuthority.Infrastructure.TaskCapabilitySha256).ToUpperInvariant()
        broker_task_name = [string]$pendingTask.Name
        broker_task_xml_sha256 = [string]$pendingTask.XmlSha256
        broker_task_security_descriptor_sha256 = [string]$pendingTask.SecurityDescriptorSha256
        broker_task_action_execute = [string]$pendingTask.Execute
        broker_task_action_arguments = [string]$pendingTask.Arguments
        broker_task_action_working_directory = [string]$pendingTask.WorkingDirectory
        broker_bootstrap_path = [string]$brokerAuthority.Infrastructure.Bootstrap.Path
        broker_bootstrap_parent_path = [string]$brokerAuthority.Infrastructure.Bootstrap.ParentPath
        broker_bootstrap_parent_file_id_128 = [string]$brokerAuthority.Infrastructure.Bootstrap.ParentFileId128
        broker_bootstrap_file_id_128 = [string]$brokerAuthority.Infrastructure.Bootstrap.FileId128
        broker_bootstrap_sha256 = [string]$brokerAuthority.Infrastructure.Bootstrap.Sha256
        broker_bootstrap_length = [int64]$brokerAuthority.Infrastructure.Bootstrap.Length
        broker_script_path = [string]$brokerAuthority.Infrastructure.BrokerScript.Path
        broker_script_parent_path = [string]$brokerAuthority.Infrastructure.BrokerScript.ParentPath
        broker_script_parent_file_id_128 = [string]$brokerAuthority.Infrastructure.BrokerScript.ParentFileId128
        broker_script_file_id_128 = [string]$brokerAuthority.Infrastructure.BrokerScript.FileId128
        broker_script_sha256 = [string]$brokerAuthority.Infrastructure.BrokerScript.Sha256
        broker_script_length = [int64]$brokerAuthority.Infrastructure.BrokerScript.Length
        maintenance_lock_path = [System.IO.Path]::GetFullPath($MaintenanceLockPath)
        chrome_bridge_activation_error = $bridgeActivationError
        chrome_bridge_health = $h.subsystems.chrome_bridge
        remediation = 'leave the healthy daemon running and normal Chrome bridge commands failed closed; after Chrome naturally loads the deployed debugger-free worker, run scripts\synapse-setup.ps1 -ResumeChromeBridgePending to verify the exact checkpointed daemon/task/binary/token/DB identities and complete only Chrome activation'
    }
    Die-SynapseChromeBridgePending `
        -Message "SYNAPSE_CHROME_BRIDGE_ACTIVATION_PENDING daemon_pid=$pendingDaemonPid bind=$Bind checkpoint=$($script:SynapseChromeBridgePendingPath) bridge_error=$bridgeActivationError remediation=do not activate, restore, navigate, click, type into, or restart a human Chrome window; wait for a natural Chrome lifecycle transition, then run -ResumeChromeBridgePending" `
        -Readback $pendingReadback
}
$finalBrokerAuthority=Assert-SynapseCurrentBrokerAuthorityGenerationOperational -Authority $brokerAuthority -ExpectedGenerationId ([string]$brokerApplicationDeployment.Generation.GenerationId) -HealthTimeoutSeconds ([Math]::Min(900,[Math]::Max(120,$InstallHealthTimeoutSeconds))) -Context 'final_after_chrome_broker_authority'
$finalInstalledHealth=$finalBrokerAuthority.Proof.Health
$healthPid=[int]$finalBrokerAuthority.Proof.DaemonPid
$finalToolSurface=$finalBrokerAuthority.Proof.ToolSurface
if([int]$finalToolSurface.tool_count -ne [int]$toolSurface.tool_count -or [string]$finalToolSurface.tool_surface_sha256 -ine [string]$toolSurface.tool_surface_sha256){
    Die "SYNAPSE_FINAL_BROKER_TOOL_SURFACE_DRIFT generation=$($brokerApplicationDeployment.Generation.GenerationId) expected_count=$($toolSurface.tool_count) actual_count=$($finalToolSurface.tool_count) expected_sha256=$($toolSurface.tool_surface_sha256) actual_sha256=$($finalToolSurface.tool_surface_sha256)"
}
$finalNonChromeReady = Test-SynapseHealthAllNonChromeSubsystemsReady -Health $finalInstalledHealth
if (-not $finalNonChromeReady.Ok) {
    Die "SYNAPSE_FINAL_INSTALLED_NON_CHROME_HEALTH_FAILED bind=$Bind expected_pid=$healthPid detail=$($finalNonChromeReady.Detail) subsystem_statuses=$(Format-SynapseHealthSubsystemStatuses -Health $finalInstalledHealth) remediation=repair every non-Chrome subsystem reporting error and rerun setup"
}
if ($finalInstalledHealth.ok -ne $true) {
    Die "SYNAPSE_FINAL_INSTALLED_HEALTH_NOT_OK bind=$Bind expected_pid=$healthPid actual_pid=$($finalInstalledHealth.pid) subsystem_statuses=$(Format-SynapseHealthSubsystemStatuses -Health $finalInstalledHealth) remediation=the explicit Chrome transition has ended, so final global health must be true; repair the named error subsystem and rerun setup"
}
$finalAcceleratorPolicy = Assert-SynapseNoExplicitGpuRuntimeHealth `
    -Health $finalInstalledHealth `
    -ProcessId $healthPid `
    -Bind $Bind `
    -Phase 'installed_after_tools_list_and_chrome_repair'
$daemonIdentityReadback=$finalBrokerAuthority.Proof.Identity
$h = $finalInstalledHealth
$healthPid = [int]$h.pid
Info "SYNAPSE_FINAL_BROKER_POLICY_AND_RESOURCE_CONTRACT_VERIFIED generation=$($finalBrokerAuthority.Generation.GenerationId) pid=$healthPid bind=$Bind health_ok=true non_chrome_contract=[$($finalNonChromeReady.Detail)] no_explicit_gpu_policy_closure=[$($finalAcceleratorPolicy.Detail)] broker_task=$($brokerAuthority.BrokerTask.Name) outer_bootstrap_pid=$($finalBrokerAuthority.Proof.OuterBootstrapPid) broker_pid=$($finalBrokerAuthority.Proof.BrokerPid) inner_bootstrap_pid=$($finalBrokerAuthority.Proof.InnerBootstrapPid) supervisor_pid=$($finalBrokerAuthority.Proof.SupervisorPid) daemon_job_name=$($daemonIdentityReadback.JobName) outer_job_current_memory_used_bytes=$($finalBrokerAuthority.Proof.OuterJob.CurrentJobMemoryUsedBytes) outer_job_peak_memory_used_bytes=$($finalBrokerAuthority.Proof.OuterJob.PeakJobMemoryUsedBytes) outer_job_cpu_rate=$($finalBrokerAuthority.Proof.OuterJob.CpuRate) inner_job_current_memory_used_bytes=$($finalBrokerAuthority.Proof.InnerJob.CurrentJobMemoryUsedBytes) inner_job_peak_memory_used_bytes=$($finalBrokerAuthority.Proof.InnerJob.PeakJobMemoryUsedBytes) inner_job_cpu_rate=$($finalBrokerAuthority.Proof.InnerJob.CpuRate) daemon_job_current_memory_used_bytes=$($finalBrokerAuthority.Proof.DaemonJob.CurrentJobMemoryUsedBytes) daemon_job_peak_memory_used_bytes=$($finalBrokerAuthority.Proof.DaemonJob.PeakJobMemoryUsedBytes) daemon_job_cpu_rate=$($finalBrokerAuthority.Proof.DaemonJob.CpuRate) note=exact immutable broker task/control-pair/generation/five-process lineage and nested Windows Job contracts were re-read after Chrome activation"
$daemonLineage = Get-ProcessLineage -StartPid $healthPid
$cmdAncestor = $daemonLineage | Where-Object { $_.Name -ieq 'cmd.exe' } | Select-Object -First 1
if ($cmdAncestor) {
    $lineageText = ($daemonLineage | ForEach-Object { "{0}:{1}" -f $_.ProcessId, $_.Name }) -join ' <- '
    Die "SYNAPSE_DAEMON_CMD_ANCESTOR_FORBIDDEN pid=$healthPid cmd_pid=$($cmdAncestor.ProcessId) lineage=$lineageText remediation=rerun setup after removing legacy daemon launchers; daemon must not be launched through cmd.exe."
}

# ---------------------------------------------------------------------------
# 9. Wire the Windows-side MCP clients
# ---------------------------------------------------------------------------
if (-not $SkipClientWiring) {
    Step "Wiring Windows-side MCP clients"

    # Claude Code (Windows) speaks Streamable HTTP natively -> point at the daemon.
    $claude = Get-Command claude -ErrorAction SilentlyContinue
    if ($claude) {
        try {
            & $claude.Source mcp remove synapse -s user 2>$null | Out-Null
            & $claude.Source mcp add --scope user --transport http synapse "http://$Bind/mcp" --header "Authorization: Bearer $token"
            Info "Claude Code (Windows) wired via HTTP transport."
        } catch { Info "WARN: 'claude mcp add' failed: $($_.Exception.Message). Wire it manually (transport http -> http://$Bind/mcp)." }
    } else { Info "claude CLI not found on Windows PATH; skipping Claude Code wiring." }

    # Codex speaks Streamable HTTP; Claude Desktop remains stdio-only -> connect bridge.
    $bridgeArgs = @('--mode','connect','--bind',$Bind)

    $codex = Get-Command codex -ErrorAction SilentlyContinue
    $codexCfg = "$env:USERPROFILE\.codex\config.toml"
    if ($codex) {
        if (Test-CodexSynapseHttpTransportConfig -ConfigPath $codexCfg -Bind $Bind) {
            Info "Codex MCP entry already uses the required Streamable HTTP transport."
        } else {
            & $codex.Source mcp remove synapse 2>$null | Out-Null
            & $codex.Source mcp add synapse --url "http://$Bind/mcp" --bearer-token-env-var SYNAPSE_BEARER_TOKEN
            $codexAddExit = $LASTEXITCODE
            if ($codexAddExit -ne 0 -and -not (Test-CodexSynapseHttpTransportConfig -ConfigPath $codexCfg -Bind $Bind)) {
                Die "codex mcp add failed (exit $codexAddExit). Codex must be wired to HTTP, not the connect bridge."
            }
            if (-not (Test-CodexSynapseHttpTransportConfig -ConfigPath $codexCfg -Bind $Bind)) {
                Die "codex mcp add completed but Codex config is not the required HTTP transport."
            }
            if ($codexAddExit -ne 0) {
                Info "WARN: codex mcp add exited $codexAddExit but Codex config now contains the required HTTP entry; continuing."
            }
        }
        Set-CodexSynapseClientPolicy -ConfigPath $codexCfg -Bind $Bind -StartupTimeoutSec $CodexMcpStartupTimeoutSeconds
        if (-not (Test-CodexSynapseHttpConfig -ConfigPath $codexCfg -Bind $Bind -StartupTimeoutSec $CodexMcpStartupTimeoutSeconds)) {
            Die "SYNAPSE_CODEX_MCP_CONFIG_INCOMPLETE path=$codexCfg remediation=repair [mcp_servers.synapse] so it contains url=http://$Bind/mcp, bearer_token_env_var=SYNAPSE_BEARER_TOKEN, required=true, default_tools_approval_mode=approve, and exactly one startup_timeout_sec=$CodexMcpStartupTimeoutSeconds."
        }
        Install-CodexSynapseTokenLoader -CodexCommandPath $codex.Source -TokenPath $TokenPath -CodexToolSurfaceSnapshotPath $CodexToolSurfaceSnapshotPath
        Info "Codex (Windows) wired via Streamable HTTP transport with required=true, default_tools_approval_mode=approve, and startup_timeout_sec=$CodexMcpStartupTimeoutSeconds."
    } elseif (Test-Path $codexCfg) {
        $c = Get-Content -Raw $codexCfg
        if ($c -match '(?m)^\[mcp_servers\.synapse\]' -and
            -not (Test-CodexSynapseHttpConfig -ConfigPath $codexCfg -Bind $Bind -StartupTimeoutSec $CodexMcpStartupTimeoutSeconds)) {
            Die "Codex config exists at $codexCfg but codex CLI is not on PATH and the synapse entry is not the required HTTP transport/client policy. Install/repair Codex CLI, then re-run."
        }
        Info "Codex CLI not found; existing Codex config is already HTTP or has no synapse entry."
    } else { Info "codex CLI/config not found; skipping Codex wiring." }

    $desktopCfg = "$env:APPDATA\Claude\claude_desktop_config.json"
    if (Test-Path $desktopCfg) {
        try {
            $j = Get-Content -Raw $desktopCfg | ConvertFrom-Json
            if (-not $j.mcpServers) { $j | Add-Member -NotePropertyName mcpServers -NotePropertyValue (@{}) -Force }
            $desktopEntry = @{ command = $ExePath; args = $bridgeArgs; env = @{ SYNAPSE_MCP_DISABLE_OPERATOR_HOTKEY = '1' } }
            # $j.mcpServers is a hashtable when freshly created above, but a PSCustomObject when
            # parsed from an existing config. Dot-assigning a NEW property to a PSCustomObject throws
            # "The property 'synapse' cannot be found on this object" under Windows PowerShell 5.1,
            # so branch on type: index-assign dictionaries, Add-Member -Force PSCustomObjects (the
            # latter both adds-or-overwrites and works on PS 5.1 and 7+).
            if ($j.mcpServers -is [System.Collections.IDictionary]) {
                $j.mcpServers['synapse'] = $desktopEntry
            } else {
                $j.mcpServers | Add-Member -NotePropertyName synapse -NotePropertyValue $desktopEntry -Force
            }
            ($j | ConvertTo-Json -Depth 12) | Set-Content $desktopCfg -Encoding utf8
            Info "Claude Desktop wired -> connect bridge."
        } catch { Info "WARN: could not update $desktopCfg : $($_.Exception.Message)" }
    } else { Info "No Claude Desktop config at $desktopCfg; skipping." }
}

if (-not $SkipClientWiring) {
    $codexAncestor = Get-SynapseCurrentCodexAncestor
    if ($codexAncestor -and $processTokenAtStart -ne $token) {
        Info ("WARN: SYNAPSE_CODEX_CURRENT_PROCESS_ENV_STALE_NONFATAL codex_pid={0} token_at_process_start={1} token_file={2} remediation=do not assume the current Codex process is disconnected; first call real mcp__synapse.health from this same session and verify daemon PID/tool_surface readback. The patched launcher has been updated for future clients; if this already-running process has no authenticated MCP connection, use the existing live daemon and token file as diagnostics until the client can refresh its environment." -f $codexAncestor.ProcessId, ($(if ([string]::IsNullOrWhiteSpace($processTokenAtStart)) { 'missing' } else { 'mismatch' })), $TokenPath)
    }
    Assert-CodexCurrentProcessToolSurfaceFresh `
        -CodexAncestor $codexAncestor `
        -CurrentSurface $toolSurface `
        -ProcessHashAtStart $processToolSurfaceHashAtStart `
        -ProcessSnapshotAtStart $processToolSurfaceSnapshotAtStart `
        -SnapshotPath $CodexToolSurfaceSnapshotPath `
        -SourceDir $SourceDir `
        -Bind $Bind `
        -TokenPath $TokenPath `
        -ActiveIssue $ActiveIssue
} else {
    $codexAncestor = Get-SynapseCurrentCodexAncestor
    if ($codexAncestor) {
        Assert-CodexCurrentProcessToolSurfaceFresh `
            -CodexAncestor $codexAncestor `
            -CurrentSurface $toolSurface `
            -ProcessHashAtStart $processToolSurfaceHashAtStart `
            -ProcessSnapshotAtStart $processToolSurfaceSnapshotAtStart `
            -SnapshotPath $CodexToolSurfaceSnapshotPath `
            -SourceDir $SourceDir `
            -Bind $Bind `
            -TokenPath $TokenPath `
            -ActiveIssue $ActiveIssue `
            -NonFatal
        Info "Skipped client wiring because -SkipClientWiring was set; current-process freshness check still wrote any required current-daemon handoff in nonfatal mode."
    } else {
        Info "Skipped client wiring because -SkipClientWiring was set; no current Codex ancestor was found for a freshness handoff."
    }
}

$checkpointTerminalization = Complete-SynapseObsoleteChromeBridgeCheckpoint `
    -Path $script:SynapseChromeBridgePendingPath `
    -DaemonPid $healthPid `
    -Bind $Bind `
    -DbPath $DbPath `
    -InstalledBinaryPath $ExePath `
    -InstalledBinarySha256 $installedHash `
    -ChromeNativeHostExePath $ChromeNativeHostExePath `
    -ChromeNativeHostExeSha256 $installedNativeHostHash `
    -ToolSurface $toolSurface `
    -ChromeBridge $h.subsystems.chrome_bridge

if ($script:SynapsePostExitStartOnly) {
    $completionReadback = [ordered]@{
        daemon_pid = $healthPid
        bind = $Bind
        db_path = $DbPath
        daemon_run_current_path = (Join-Path $DbPath 'daemon-run-current.json')
        installed_binary_path = $ExePath
        installed_binary_sha256 = $installedHash
        chrome_native_host_exe_path = [System.IO.Path]::GetFullPath($ChromeNativeHostExePath)
        chrome_native_host_exe_sha256 = $installedNativeHostHash
        codex_tool_surface_snapshot_path = $CodexToolSurfaceSnapshotPath
        tool_count = $toolSurface.tool_count
        tool_surface_sha256 = $toolSurface.tool_surface_sha256
        chrome_bridge_status = $h.subsystems.chrome_bridge.status
        chrome_bridge_detail = $h.subsystems.chrome_bridge.detail
        chrome_bridge_checkpoint = $checkpointTerminalization
    }
    Write-SynapsePostExitManifestState `
        -State 'completed' `
        -Message 'post-exit setup continuation completed after daemon, Chrome bridge, tool-surface, and client-config readbacks passed' `
        -ExitCode 0 `
        -Readback $completionReadback
    Info "SYNAPSE_POST_EXIT_CONTINUATION_COMPLETED manifest=$PostExitManifestPath daemon_pid=$healthPid tool_count=$($toolSurface.tool_count) tool_surface_sha256=$($toolSurface.tool_surface_sha256)"
}

$setupRepairCompletionReadback = [ordered]@{
    daemon_pid = $healthPid
    bind = $Bind
    db_path = $DbPath
    daemon_run_current_path = (Join-Path $DbPath 'daemon-run-current.json')
    installed_binary_path = $ExePath
    installed_binary_sha256 = $installedHash
    chrome_native_host_exe_path = [System.IO.Path]::GetFullPath($ChromeNativeHostExePath)
    chrome_native_host_exe_sha256 = $installedNativeHostHash
    codex_tool_surface_snapshot_path = $CodexToolSurfaceSnapshotPath
    tool_count = $toolSurface.tool_count
    tool_surface_sha256 = $toolSurface.tool_surface_sha256
    chrome_bridge_status = $h.subsystems.chrome_bridge.status
    chrome_bridge_detail = $h.subsystems.chrome_bridge.detail
    chrome_bridge_checkpoint = $checkpointTerminalization
}
Write-SynapseSetupRepairManifestState `
    -State 'completed' `
    -Message 'setup repair completed after daemon, Chrome bridge, tool-surface, and client-config readbacks passed' `
    -ExitCode 0 `
    -Readback $setupRepairCompletionReadback

# The maintenance record and completion ledger are the durable success
# authorities. Publish them before any informational output: a setup child may
# legitimately outlive a bounded caller, whose stdout pipe is no longer a
# dependency the transaction can trust (#2207).
Release-SynapseSetupMaintenanceLock -State released
$phaseLedgerPath = Write-SynapseSetupPhaseLedger -Outcome 'completed' -Message 'setup completed'
Step "Done"
Info "Synapse daemon is live on http://$Bind (MCP: http://$Bind/mcp)."
Info "Token: $TokenPath   DB: $DbPath   Profiles: $ProfilesDir"
Info "WSL clients: run scripts/synapse-install.sh from WSL to wire Claude Code + Codex there."
if ($phaseLedgerPath) {
    $ledgerReadback = Get-Content -LiteralPath $phaseLedgerPath -Raw | ConvertFrom-Json
    Info ("Setup wall clock: total={0}s phases={1} cargo_build_jobs={2} ledger={3}" -f `
        $ledgerReadback.total_elapsed_seconds,
        $ledgerReadback.phase_count,
        ($(if ($ledgerReadback.cargo_build_jobs) { $ledgerReadback.cargo_build_jobs } else { '<unset:SkipBuild>' })),
        $phaseLedgerPath)
    foreach ($slow in @($ledgerReadback.slowest_phases)) {
        Info ("  slowest_phase elapsed_s={0} phase={1}" -f $slow.elapsed_seconds, $slow.phase)
    }
} else {
    if (-not [string]::IsNullOrWhiteSpace($script:SynapseSetupPhaseLedgerWriteError)) {
        Warn $script:SynapseSetupPhaseLedgerWriteError
    } else {
        Warn "SYNAPSE_SETUP_PHASE_LEDGER_UNWRITTEN log_dir=$LogDir remediation=setup completed but its phase timing ledger could not be written; inspect LogDir permissions"
    }
}
